si[i++] = gsitm("N501010160000J00ENG.html", "Tightening torque", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "The tightening torque specifications of bolts and nuts may be presented as either a range or a standard tightening torque.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Select with proper thickness.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Should be lubricated with oil.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Adjustment is required.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Sealing point", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Direction", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Should be lubricated with grease. Unless otherwise indicated, use recommended multi-purpose grease.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Metal clip", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Apply petroleum jelly.", "ptxt");
si[i++] = gsitm("N501010160000J00ENG.html", "Clip", "ptxt");
