si[i++] = gsitm("N5010108A0000Z00ENG.html", "Special Service Tool Number Substitution List", "title");
si[i++] = gsitm("N5010108A0000Z00ENG.html", "When you order special service tool, use part number on \"tool order number\" instead of part number on \"tool number for service manual\".", "ptxt");
