si[i++] = gsitm("N501010510000E00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N501010510000E00ENG.html", "WORK FLOW", "title");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "DESCRIPTION", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 1", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Get detailed information about the conditions and the environment when the incident occurred.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "The following are key pieces of information required to make a good analysis:", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "WHAT", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Vehicle Model, Engine, Transmission/Transaxle and the System (i.e. Radio).", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "WHEN", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Date, Time of Day, Weather Conditions, Frequency.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "WHERE", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Road Conditions, Altitude and Traffic Situation.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "HOW", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "System Symptoms, Operating Conditions (Other Components Interaction).", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Service History and if any After Market Accessories have been installed.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 2", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Operate the system, road test if necessary.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Verify the parameter of the incident.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "If the problem cannot be duplicated, refer to “Incident Simulation Tests”.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 3", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Get the proper diagnosis materials together including:", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Power Supply Routing", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "System Operation Descriptions", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Applicable Service Manual Sections", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Check for any Service Bulletins", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Identify where to begin diagnosis based upon your knowledge of the system operation and the customer comments.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 4", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Inspect the system for mechanical binding, loose connectors or wiring damage.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Determine which circuits and components are involved and diagnose using the Power Supply Routing and Harness Layouts.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 5", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Repair or replace the incident circuit or component.", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "STEP 6", "ptxt");
si[i++] = gsitm("N501010510000E00ENG.html", "Operate the system in all modes. Verify the system works properly under all conditions. Check you have not inadvertently created a new incident during your diagnosis or repair steps.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Control Units and Electrical Parts", "title");
si[i++] = gsitm("N5010101H0000E00ENG.html", "PRECAUTIONS", "title");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Never reverse polarity of battery terminals.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Install only parts specified for a vehicle.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Before replacing the control unit, check the input and output and functions of the component parts.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Do not apply excessive force when disconnecting a connector.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Do not apply excessive shock to the control unit by dropping or hitting it.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Be careful to prevent condensation in the control unit due to rapid temperature changes and do not let water or rain get on it. If water is found in the control unit, dry it fully and then install it in the vehicle.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Be careful not to let oil to get on the control unit connector.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Avoid cleaning the control unit with volatile oil.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "Do not disassemble the control unit, and do not remove the upper and lower covers.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "When using a DMM, be careful not to let test probes get close to each other to prevent the power transistor in the control unit from damaging battery voltage because of short circuiting.", "ptxt");
si[i++] = gsitm("N5010101H0000E00ENG.html", "When checking input and output signals of the control unit, use the specified check adapter.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "How to Check Terminal", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "CONNECTOR AND TERMINAL PIN KIT", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Use the connector and terminal pin kits listed below when replacing connectors or terminals.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "The connector and terminal pin kits contain some of the most commonly used Mitsubishi Motors connectors and terminals. For detailed connector and terminal pin replacement procedures, refer to the latest Mitsubishi Motors CONNECTOR AND TERMINAL PIN SERVICE MANUAL.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Tool number", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "(TechMate No.)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "-", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "(J38751-95NI)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Connector and terminal pin kit (Mitsubishi Motors)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "(J38751-95INF)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "(J42992-98KIT)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "OBD and terminal repair kit", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "(J42992-2000UPD)", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "OBD-II Connector Kit Update", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "HOW TO PROBE CONNECTORS", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Connector damage and an intermittent connection can result from improperly probing of the connector during circuit checks.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "The probe of a digital multimeter (DMM) may not correctly fit the connector cavity. To correctly probe the connector, follow the procedures below using a “T” pin. For the best contact grasp the “T” pin using an alligator clip.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Probing from Harness Side", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Standard type (not waterproof type) connector should be probed from harness side with “T” pin.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "If the connector has a rear cover such as a ECM connector, remove the rear cover before probing the terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Do not probe waterproof connector from harness side. Damage to the seal between wire and connector may result.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Probing from Terminal Side", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "FEMALE TERMINAL", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "There is a small notch above each female terminal. Probe each terminal with the “T” pin through the notch.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Do not insert any object other than the same type male terminal into female terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Some connectors do not have a notch above each terminal. To probe each terminal, remove the connector retainer to make contact space for probing.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "MALE TERMINAL", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Carefully probe the contact surface of each terminal using a “T” pin.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Never bend terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "How to Check Enlarged Contact Spring of Terminal", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "An enlarged contact spring of a terminal may create intermittent signals in the circuit.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "If the intermittent open circuit occurs, follow the procedure below to inspect for open wires and enlarged contact spring of female terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Assemble a male terminal and approx. 10 cm (3.9 in) of wire.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Use a male terminal which matches the female terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Disconnect the suspected faulty connector and hold it terminal side up.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "While holding the wire of the male terminal, try to insert the male terminal into the female terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Never force the male terminal into the female terminal with your hands.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "While moving the connector, check whether the male terminal can be easily inserted or not.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "If the male terminal can be easily inserted into the female terminal, replace the female terminal.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Waterproof Connector Inspection", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "If water enters the connector, it can short interior circuits. This may lead to intermittent problems.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Check the following items to maintain the original waterproof characteristics.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "RUBBER SEAL INSPECTION", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Most waterproof connectors are provided with a rubber seal between the male and female connectors. If the seal is missing, the waterproof performance may not meet specifications.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "The rubber seal may come off when connectors are disconnected. Whenever connectors are reconnected, check the rubber seal is properly installed on either side of male or female connector.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "WIRE SEAL INSPECTION", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "The wire seal must be installed on the wire insertion area of a waterproof connector. Be sure that the seal is installed properly.", "ptxt");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Terminal Lock Inspection", "title");
si[i++] = gsitm("N5010102T0000E00ENG.html", "Check for unlocked terminals by pulling wire at the end of connector. An unlocked terminal may create intermittent signals in the circuit.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Intermittent Incident", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Sometimes the symptom is not present when the vehicle is brought in for service. If possible, re-create the conditions present at the time of the incident. Doing so may help avoid a No Trouble Found Diagnosis. The following section illustrates ways to simulate the conditions/environment under which the owner experiences an electrical incident.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The section is broken into the six following topics:", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Vehicle vibration", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Heat sensitive", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Freezing", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Water intrusion", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Electrical load", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Cold or hot start up", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Get a thorough description of the incident from the customer. It is important for simulating the conditions of the problem.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "VEHICLE VIBRATION", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The problem may occur or become worse while driving on a rough road or when engine is vibrating (idle with A/C on). In such a case, you will want to check for a vibration related condition. Refer to the following illustration.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Connector & Harness", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Determine which connectors and wiring harness would affect the electrical system you are inspecting. Gently shake each connector and harness while monitoring the system for the incident you are trying to duplicate. This test may indicate a loose or poor electrical connection.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Hint", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Connectors can be exposed to moisture. It is possible to get a thin film of corrosion on the connector terminals. A visual inspection may not reveal this without disconnecting the connector. If the problem occurs intermittently, perhaps the problem is caused by corrosion. It is a good idea to disconnect, inspect and clean the terminals on related connectors in the system.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Sensor & Relay", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Gently apply a slight vibration to sensors and relays in the system you are inspecting.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "This test may indicate a loose or poorly mounted sensor or relay.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Engine Compartment", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "There are several reasons a vehicle or engine vibration could cause an electrical complaint. Some of the things to check for are:", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Connectors not fully seated.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Wiring harness not long enough and is being stressed due to engine vibrations or rocking.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Wires laying across brackets or moving components.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Loose, dirty or corroded ground wires.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Wires routed too close to hot components.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "To inspect components under the hood, start by verifying the integrity of ground connections. (Refer to Ground Inspection described later.) First check that the system is properly grounded. Then check for loose connection by gently shaking the wiring or components as previously explained. Using the wiring diagrams inspect the wiring for continuity.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Behind the Instrument Panel", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "An improperly routed or improperly clamped harness can become pinched during accessory installation. Vehicle vibration can aggravate a harness which is routed along a bracket or near a screw.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Under Seating Areas", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "An unclamped or loose harness can cause wiring to be pinched by seat components (such as slide guides) during vehicle vibration. If the wiring runs under seating areas, inspect wire routing for possible damage or pinching.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "HEAT SENSITIVE", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The customer\'s concern may occur during hot weather or after car has sat for a short time. In such cases you will want to check for a heat sensitive condition.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "To determine if an electrical component is heat sensitive, heat the component with a heat gun or equivalent.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Never heat components above 60°C (140°F).", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "If incident occurs while heating the unit, either replace or properly insulate the component.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "FREEZING", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The customer may indicate the incident goes away after the car warms up (winter time). The cause could be related to water freezing somewhere in the wiring/electrical system.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "There are two methods to check for this. The first is to arrange for the owner to leave his car overnight. Check it will get cold enough to demonstrate his complaint. Leave the car parked outside overnight. In the morning, do a quick and thorough diagnosis of those electrical components which could be affected.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The second method is to put the suspect component into a freezer long enough for any water to freeze. Reinstall the part into the car and check for the reoccurrence of the incident. If it occurs, repair or replace the component.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "WATER INTRUSION", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The incident may occur only during high humidity or in rainy/snowy weather. In such cases the incident could be caused by water intrusion on an electrical part. This can be simulated by soaking the car or running it through a car wash.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "Never spray water directly on any electrical components.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "ELECTRICAL LOAD", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "The incident may be electrical load sensitive. Perform diagnosis with all accessories (including A/C, rear window defogger, radio, fog lights) turned on.", "ptxt");
si[i++] = gsitm("N5010107B0000J00ENG.html", "COLD OR HOT START UP", "title");
si[i++] = gsitm("N5010107B0000J00ENG.html", "On some occasions an electrical incident may occur only when the car is started cold, or it may occur when the car is restarted hot shortly after being turned off. In these cases you may have to keep the car overnight to make a proper diagnosis.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Circuit Inspection", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "In general, testing electrical circuits is an easy task if it is approached in a logical and organized method. Before beginning it is important to have all available information on the system to be tested. Also, get a thorough understanding of system operation. Then you will be able to use the appropriate equipment and follow the correct test procedure.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "You may have to simulate vehicle vibrations while testing electrical components. Gently shake the wiring harness or electrical component to do this.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "OPEN", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "A circuit is open when there is no continuity through a section of the circuit.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "SHORT", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "There are two types of shorts.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "SHORT CIRCUIT", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "When a circuit contacts another circuit and causes the normal resistance to change.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "SHORT TO GROUND", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "When a circuit contacts a ground source and grounds the circuit.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Refer to How to Check Terminal to probe or check terminal.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "TESTING FOR “OPENS” IN THE CIRCUIT", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Before you begin to diagnose and test the system, you should rough sketch a schematic of the system. This will help you to logically walk through the diagnosis process. Drawing the sketch will also reinforce your working knowledge of the system.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Continuity Check Method", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "The continuity check is used to find an open in the circuit. The digital multimeter (DMM) set on the resistance function will indicate an open circuit as over limit (no beep tone or no ohms symbol). Check to always start with the DMM at the highest resistance level.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "To help in understanding the diagnosis of open circuits, please refer to the previous schematic.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Disconnect the battery negative cable.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Start at one end of the circuit and work your way to the other end. (At the fuse block in this example)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect one probe of the DMM to the fuse block terminal on the load side.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect the other probe to the fuse block (power) side of SW1. Little or no resistance will indicate that portion of the circuit has good continuity. If there were an open in the circuit, the DMM would indicate an over limit or infinite resistance condition. (point A)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect the probes between SW1 and the relay. Little or no resistance will indicate that portion of the circuit has good continuity. If there were an open in the circuit, the DMM would indicate an over limit or infinite resistance condition. (point B)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect the probes between the relay and the solenoid. Little or no resistance will indicate that portion of the circuit has good continuity. If there were an open in the circuit, the DMM would indicate an over limit or infinite resistance condition. (point C)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Any circuit can be diagnosed using the approach in the previous example.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Voltage Check Method", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "To help in understanding the diagnosis of open circuits please refer to the previous schematic.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "In any powered circuit, an open can be found by methodically checking the system for the presence of voltage. This is done by switching the DMM to the voltage function.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect one probe of the DMM to a known good ground.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Begin probing at one end of the circuit and work your way to the other end.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "With SW1 open, probe at SW1 to check for voltage.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: open is further down the circuit than SW1.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: open is between fuse block and SW1 (point A).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Close SW1 and probe at relay.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: open is further down the circuit than the relay.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: open is between SW1 and relay (point B).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Close the relay and probe at the solenoid.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: open is further down the circuit than the solenoid.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: open is between relay and solenoid (point C).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Any powered circuit can be diagnosed using the approach in the previous example.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "TESTING FOR “SHORTS” IN THE CIRCUIT", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "To simplify the discussion of shorts in the system, please refer to the following schematic.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Resistance Check Method", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Disconnect the battery negative cable and remove the blown fuse.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Disconnect all loads (SW1 open, relay disconnected and solenoid disconnected) powered through the fuse.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect one probe of the DMM to the load side of the fuse terminal. Connect the other probe to a known good ground.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "With SW1 open, check for continuity.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "continuity: short is between fuse terminal and SW1 (point A).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no continuity: short is further down the circuit than SW1.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Close SW1 and disconnect the relay. Put probes at the load side of fuse terminal and a known good ground. Then, check for continuity.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "continuity: short is between SW1 and the relay (point B).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no continuity: short is further down the circuit than the relay.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Close SW1 and jump the relay contacts with jumper wire. Put probes at the load side of fuse terminal and a known good ground. Then, check for continuity.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "continuity: short is between relay and solenoid (point C).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no continuity: check solenoid, retrace steps.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Remove the blown fuse and disconnect all loads (i.e. SW1 open, relay disconnected and solenoid disconnected) powered through the fuse.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Turn the ignition switch to the ON or START position. Verify battery voltage at the battery + side of the fuse terminal (one lead on the battery + terminal side of the fuse block and one lead on a known good ground).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "With SW1 open and the DMM leads across both fuse terminals, check for voltage.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: short is between fuse block and SW1 (point A).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: short is further down the circuit than SW1.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "With SW1 closed, relay and solenoid disconnected and the DMM leads across both fuse terminals, check for voltage.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: short is between SW1 and the relay (point B).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: short is further down the circuit than the relay.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "With SW1 closed, relay contacts jumped with fused jumper wire check for voltage.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "voltage: short is down the circuit of the relay or between the relay and the disconnected solenoid (point C).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "no voltage: retrace steps and check power to fuse block.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "GROUND INSPECTION", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Ground connections are very important to the proper operation of electrical and electronic circuits. Ground connections are often exposed to moisture, dirt and other corrosive elements. The corrosion (rust) can become an unwanted resistance. This unwanted resistance can change the way a circuit works.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Electronically controlled circuits are very sensitive to proper grounding. A loose or corroded ground can drastically affect an electronically controlled circuit. A poor or corroded ground can easily affect the circuit. Even when the ground connection looks clean, there can be a thin film of rust on the surface.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "When inspecting a ground connection follow these rules:", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Remove the ground bolt or screw.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Inspect all mating surfaces for tarnish, dirt, rust, etc.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Clean as required to assure good contact.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Reinstall bolt or screw securely.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Inspect for “add-on” accessories which may be interfering with the ground circuit.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "If several wires are crimped into one ground eyelet terminal, check for proper crimps. Check all of the wires are clean, securely fastened and providing a good ground path. If multiple wires are cased in one eyelet check no ground wires have excess wire insulation.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "For detailed ground distribution information, refer to “Ground Distribution” in PG section.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "VOLTAGE DROP TESTS", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Voltage drop tests are often used to find components or circuits which have excessive resistance. A voltage drop in a circuit is caused by a resistance when the circuit is in operation.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Check the wire in the illustration. When measuring resistance with DMM, contact by a single strand of wire will give reading of 0 ohms. This would indicate a good circuit. When the circuit operates, this single strand of wire is not able to carry the current. The single strand will have a high resistance to the current. This will be picked up as a slight voltage drop.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Unwanted resistance can be caused by many situations as follows:", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Undersized wiring (single strand example)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Corrosion on switch contacts", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Loose wire connections or splices.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "If repairs are needed always use wire that is of the same or larger gauge.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Measuring Voltage Drop — Accumulated Method", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Connect the DMM across the connector or part of the circuit you want to check. The positive lead of the DMM should be closer to power and the negative lead closer to ground.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Operate the circuit.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "The DMM will indicate how many volts are being used to “push” current through that part of the circuit.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Note in the illustration that there is an excessive 4.1 volt drop between the battery and the bulb.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Measuring Voltage Drop — Step-by-Step", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "The step-by-step method is most useful for isolating excessive drops in low voltage systems (such as those in “Computer Controlled Systems”).", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Circuits in the “Computer Controlled System” operate on very low amperage.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "The (Computer Controlled) system operations can be adversely affected by any variation in resistance in the system. Such resistance variation may be caused by poor connection, improper installation, improper wire gauge or corrosion.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "The step by step voltage drop test can identify a component or wire with too much resistance.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "CONTROL UNIT CIRCUIT TEST", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "System Description", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "When the switch is ON, the control unit lights up the light.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "CASE 1", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "INPUT-OUTPUT VOLTAGE CHART", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Terminal No.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Condition", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Value (Approx.)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "In case of high resistance such as single strand (V) *", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "+", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "−", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Signal name", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Input/Output", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "1", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Body ground", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Switch", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Input", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Switch ON", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Battery voltage", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Lower than battery voltage Approx. 8 (Example)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Switch OFF", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "0 V", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Approx. 0", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "2", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Light", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Output", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Approx. 0 (Inoperative light)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "The voltage value is based on the body ground.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "*: If high resistance exists in the switch side circuit (caused by a single strand), terminal 1 does not detect battery voltage. Control unit does not detect the switch is ON even if the switch does not turn ON. Therefore, the control unit does not supply power to light up the light.", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "CASE 2", "title");
si[i++] = gsitm("N501010780000E00ENG.html", "Battery voltage (Inoperative light)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Higher than 0 Approx. 4 (Example)", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "5 V", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "Approx. 5", "ptxt");
si[i++] = gsitm("N501010780000E00ENG.html", "*: If high resistance exists in the switch side circuit (caused by a single strand), terminal 2 does not detect approx. 0 V. Control unit does not detect the switch is ON even if the switch does not turn ON. Therefore, the control unit does not control ground to light up the light.", "ptxt");
si[i++] = gsitm("N5010101J0002300ENG.html", "Description", "title");
si[i++] = gsitm("N5010101J0002300ENG.html", "When M.U.T.-III SE/GST is connected with a data link connector  equipped on the vehicle side, it will communicate with the control unit equipped in the vehicle and then enable various kinds of diagnostic tests.", "ptxt");
si[i++] = gsitm("N5010101J0002300ENG.html", ": Instrument lower panel", "ptxt");
si[i++] = gsitm("N5010101J0002300ENG.html", "Refer to M.U.T.-III SE Software Operation Manual for more information.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "M.U.T.-III SE Function and System Application*1", "title");
si[i++] = gsitm("N501010790001300ENG.html", "FUNCTION", "title");
si[i++] = gsitm("N501010790001300ENG.html", "Mode", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Function", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Read All DTCs", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Display all DTCs or diagnostic items that all ECUs are recording and judging.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Special Function", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "This mode enables a technician to adjust some devices faster and more accurately.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Self-diagnosis", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Retrieve DTC from ECU and display diagnostic items.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Data List", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Monitor the input/output signal of the control unit in real time.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Actuator Test", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Send the drive signal from M.U.T.-III SE to the actuator. The operation check can be performed.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "ECU Information", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Display the ECU identification number (part number etc.) of the selected system.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Configuration", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Function to WRITE vehicle configuration.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "SRT Status/Permanent DTC Status", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "The state of System Readiness Test (SRT) items, the presence or absence of permanent DTC*, and driving conditions can be checked.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Others", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "Other results or histories, etc. that are recorded in ECU are displayed.", "ptxt");
si[i++] = gsitm("N501010790001300ENG.html", "*: Permanent DTC is not applied for regions where it is not mandated.", "ptxt");
