si[i++] = gsitm("N5010107A0000T00ENG.html", "M.U.T.-III SE Data Link Connector (DLC) Circuit", "title");
si[i++] = gsitm("N5010107A0000T00ENG.html", "INSPECTION PROCEDURE", "title");
si[i++] = gsitm("N5010107A0000T00ENG.html", "If the M.U.T.-III SE/GST cannot diagnose the system properly, check the following items.", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Symptom", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Check item", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "M.U.T.-III SE cannot access any system.", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "M.U.T.-III SE DLC power supply circuit (Terminal 8 and 16) and ground circuit (Terminal 4 and 5)", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Check the power supply and ground circuit of 8CH CAN gateway. Refer to", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", ".", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Check the data link connector branch line circuit. Refer to .", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Check the diagnostic CAN communication circuit. Refer to .", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "If above inspection results are normal, replace 8CH CAN gateway. Refer to .", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "M.U.T.-III SE cannot access individual system. (Other systems can be accessed.)", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Power supply and ground circuit for the control unit of the system (For detailed circuit, refer to wiring diagram for each system.)", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Open or short circuit between the system and M.U.T.-III SE DLC (For detailed circuit, refer to wiring diagram for each system.)", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "Open or short circuit CAN communication line. Refer to .", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "The DDL1 and DDL2 circuits from DLC pins 12, 13, 14 and 15 may be connected to more than one system. A short in a DDL circuit connected to a control unit in one system may affect M.U.T.-III SE access to other systems.", "ptxt");
si[i++] = gsitm("N5010107A0000T00ENG.html", "If the GST cannot operate properly, check the circuit based on the information of SAE J1962 and ISO 15031-3.", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "Required Procedure After Battery Disconnection", "title");
si[i++] = gsitm("N501010450000X00ENG.html", "SYSTEM", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "ITEM", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "REFERENCE", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "Power window", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "Power window control", "ptxt");
si[i++] = gsitm("N501010450000X00ENG.html", "Refer to Description", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "HOW TO COPE WITH INTERMITTENT MALFUNCTIONS", "title");
si[i++] = gsitm("N501150090000700ENG.html", "Most intermittent malfunctions occur under certain conditions. If those conditions can be identified, the cause will be easier to find.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "TO COPE WITH INTERMITTENT MALFUNCTION;", "title");
si[i++] = gsitm("N501150090000700ENG.html", "1. ASK THE CUSTOMER ABOUT THE MALFUNCTION", "title");
si[i++] = gsitm("N501150090000700ENG.html", "Ask what it feels like, what it sounds like, etc. Then ask about driving conditions, weather, frequency of occurrence, and so on.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "2. DETERMINE THE CONDITIONS FROM THE CUSTOMER\'S RESPONSES", "title");
si[i++] = gsitm("N501150090000700ENG.html", "Typically, almost all intermittent malfunctions occur from conditions like vibration, temperature and/or moisture change, poor connections. From the customer\'s responses, it should be reasoned which condition is most likely.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "3. USE SIMULATION TEST", "title");
si[i++] = gsitm("N501150090000700ENG.html", "Use the simulation tests below to attempt to duplicate the customer\'s complaint. Determine the most likely circuit(s) and perform the simulation tests on the connectors and parts of that circuit(s). Be sure to use the inspection procedures provided for diagnostic trouble codes and trouble symptoms.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "For temperature and/or moisture condition related intermittent malfunctions, try to change the conditions of the suspected circuit components, then use the simulation tests below.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "4. VERIFY THE INTERMITTENT MALFUNCTION IS ELIMINATED", "title");
si[i++] = gsitm("N501150090000700ENG.html", "Repair the malfunctioning part and try to duplicate the condition(s) again to verify the intermittent malfunction has been eliminated.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "SIMULATION TESTS", "title");
si[i++] = gsitm("N501150090000700ENG.html", "In case of difficulty in finding the cause of the intermittent malfunction, the data recorder function in the scan tool is effective.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "For these simulation tests, shake, then gently bend, pull, and twist the wiring of each of these examples to duplicate the intermittent malfunction.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "Shake the connector up-and-down, and right-and-left.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "Shake the wiring harness up-and-down, and right-and-left. Especially, check the splice points of wiring harnesses carefully.", "ptxt");
si[i++] = gsitm("N501150090000700ENG.html", "Shake the part or sensor.", "ptxt");
si[i++] = gsitm("N501150100000O00ENG.html", "HOW TO TREAT PAST TROUBLE", "title");
si[i++] = gsitm("N501150100000O00ENG.html", "Since the trouble may still be present even the status is \"Stored\", set the vehicle to the diagnostic trouble code detection condition and check that the status changes to \"Active\". If the status does not change from \"Stored\", carry out the following procedure.", "ptxt");
si[i++] = gsitm("N501150100000O00ENG.html", "Establish from the customer whether a fuse or connector has been replaced or disconnected.", "ptxt");
si[i++] = gsitm("N501150100000O00ENG.html", "If yes, erase the diagnostic trouble code, and then check that no diagnostic code is stored again. If no diagnostic trouble code is stored again, the diagnosis is complete.", "ptxt");
si[i++] = gsitm("N501150100000O00ENG.html", "If no, follow the applicable Diagnostic Trouble Code Chart. Then check the wiring harness and connector, and refer to \"How to Cope with Intermittent Malfunctions  .\"", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "INSPECTION SERVICE POINTS FOR A BLOWN FUSE", "title");
si[i++] = gsitm("N501150080000G00ENG.html", "Remove the blown fuse and measure the resistance between the load side of the blown fuse and the ground. Close the switches of all circuits which are connected to this fuse. If the resistance is almost 0 Ω at this time, there is a short somewhere between these switches and the load. If the resistance is not 0 Ω, there is no short at the present time, but a momentary short has probably caused the fuse to blow.", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "The main causes of a short circuit are the following.", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "Harness being clamped by the vehicle body", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "Damage to the outer casing of the harness due to wear or heat", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "Water getting into the connector or circuitry", "ptxt");
si[i++] = gsitm("N501150080000G00ENG.html", "Human error (mistakenly shorting a circuit, etc.)", "ptxt");
si[i++] = gsitm("N501160100000200ENG.html", "TARGETS OF DEVELOPMENT", "title");
