si[i++] = gsitm("N501160080000700ENG.html", "Strong horizontal structured body.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "Powerful and tough look of muscular fender flares and class top level 20-inch large diameter tires. &lt;some models>", "ptxt");
