si[i++] = gsitm("N501160080000700ENG.html", "Floating console with horizontal instrument panel provides roomy and rich space.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "JAPANESE CRAFTSMANSHIP", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "Meticulous craftsman\'s high quality in wide area of soft material and stitch gives highly comfortable space for all passengers.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "SOLID TOUCH FEELING", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "Reliable grip and accurate response for the confidence of operation.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "VISIBLE FUNCTIONALITY", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "Advanced impression with improved intuitive operation and easy interface.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "HOSPITALITY", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "All passengers are welcomed by Japanese hospitality (OMOTENASHI) with thoughtful details and attentiveness.", "ptxt");
si[i++] = gsitm("N501160080000700ENG.html", "&lt;Interior color>", "title");
