si[i++] = gsitm("N501160050000200ENG.html", "ACTIVE SAFETY", "title");
si[i++] = gsitm("N501160050000200ENG.html", "Top-class safety by aiming for a 5 stars rating in the New Car Assessment Program (NCAP).", "ptxt");
si[i++] = gsitm("N501160050000200ENG.html", "Rear Automatic Emergency Braking (Rear AEB) has been adopted that detects vehicles diagonally behind.", "ptxt");
si[i++] = gsitm("N501160050000200ENG.html", "Active Blind Spot Assist [ABSA] has been adopted.", "ptxt");
si[i++] = gsitm("N501160050000200ENG.html", "Trailer Stability Assist (TSA) has been adopted.", "ptxt");
si[i++] = gsitm("N501160050000200ENG.html", "Forward Collision Mitigation (FCM) and Predictive Forward Collision Warning (PFCW) have been adopted.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "PASSIVE SAFETY", "title");
si[i++] = gsitm("N501160060000200ENG.html", "The following safety equipment/systems are adopted:", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Reinforced Impact Safety Evolution Body (RISE Body) has been adopted.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "A maximum of 8 airbag modules can be installed in the vehicle.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Driver\'s air bag module", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Driver\'s side knee air bag module", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Passenger\'s air bag module", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Front side-airbag module (driver\'s side)", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Front side-airbag module (passenger\'s side)", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Front side-airbag module (center)", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Curtain air bag module (driver\'s side)", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Curtain air bag module (passenger\'s side)", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Driver\'s side seat belt is 3-point seat belt with ELR and double pre-tensioner has been adopted.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "Passenger\'s side seat belt is 3-point seat belt with ELR and double pre-tensioner has been adopted.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "The second seat belt is 3-point seat belt with ELR (both sides and center) and single pre-tensioner (both sides) has been adopted.", "ptxt");
si[i++] = gsitm("N501160060000200ENG.html", "The third seat belt is 3-point seat belt with ELR (both sides) has been adopted.", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "EQUIPMENT", "title");
si[i++] = gsitm("N501160070000200ENG.html", "UTILITY", "title");
si[i++] = gsitm("N501160070000200ENG.html", "The 10.8-inch wide full-color head up display (HUD) has been adopted.", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "The reverse auto tilt door mirrors with parking assist have been adopted.", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "The multi-around monitor with Moving Object Detection (MOD) has been adopted.", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "The power remote liftgate with hands-free access has been adopted.", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "Convenient items:", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "Wireless charger \"Qi\" is equipped with USB sockets and illumination", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "Pockets for the second row seats", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "INNOVATIVE TECHNOLOGY", "title");
si[i++] = gsitm("N501160070000200ENG.html", "Meter and IVI", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "12.3-inch full digital driver\'s display", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "9-inch smartphone link display audio (SDA) navigation system &lt;Vehicle with navigation>", "ptxt");
si[i++] = gsitm("N501160070000200ENG.html", "8-inch smartphone link display audio (SDA) &lt;Vehicle without navigation>", "ptxt");
si[i++] = gsitm("N5020106M0000K00ENG.html", "Precaution for Procedure without Cowl Top Cover", "title");
si[i++] = gsitm("N5020106M0000K00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5020106Q0000L00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5020204R0001200ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5020204R0001200ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5020204R0001200ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Precautions For Engine Service", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "DISCONNECTING FUEL PIPING", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Before starting work, check no fire or spark producing items are in the work area.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Release fuel pressure before disconnecting and disassembly.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "After disconnecting pipes, plug openings to stop fuel leakage.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "DRAINING ENGINE COOLANT", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Drain engine coolant and engine oil when the engine is cooled.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "INSPECTION, REPAIR AND REPLACEMENT", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Before repairing or replacing, thoroughly inspect parts. Inspect new replacement parts in the same way, and replace if necessary.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "When replacing or inspecting air cleaner element, remove foreign matter inside air duct, on air cleaner element surface, and inside cleaner case.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "REMOVAL AND DISASSEMBLY", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "When instructed to use SST, use specified tools. Always be careful to work safely, avoid forceful or uninstructed operations.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Exercise maximum care to avoid damage to mating or sliding surfaces.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Dowel pins are used for several parts alignment. When replacing and reassembling parts with dowel pins, check that dowel pins are installed in the original position.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Must cover openings of engine system with a tape or equivalent, to seal out foreign materials.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Mark and arrange disassembly parts in an organized way for easy troubleshooting and reassembly.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "When loosening nuts and bolts, as a basic rule, start with the one furthest outside, then the one diagonally opposite, and so on. If the order of loosening is specified, do exactly as specified. Power tools may be used in the step.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "ASSEMBLY AND INSTALLATION", "title");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Use torque wrench to tighten bolts or nuts to specification.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "When tightening nuts and bolts, as a basic rule, equally tighten in several different steps starting with the ones in center, then ones on inside and outside diagonally in this order. If the order of tightening is specified, do exactly as specified.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Before removing or installing any intake-system-related parts, thoroughly clean them to prevent foreign matter from entering inside engine.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Replace with new gasket, packing, oil seal or O-ring.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Thoroughly wash, clean, and air-blow each part. Carefully check engine oil or engine coolant passages for any restriction and blockage.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Avoid damaging sliding or mating surfaces. Completely remove foreign materials such as cloth lint or dust. Before assembly, oil sliding surfaces well.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "After disassembling, or exposing any internal engine parts, change engine oil and replace oil filter with a new one.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "Release air within route when refilling after draining engine coolant.", "ptxt");
si[i++] = gsitm("N5020106P0000K00ENG.html", "After repairing, start the engine and increase engine speed to check engine coolant, fuel, engine oil, and exhaust gases for leakage.", "ptxt");
si[i++] = gsitm("N5020109F0000E00ENG.html", "Precaution for Handling High Pressure Fuel System", "title");
si[i++] = gsitm("N5020109F0000E00ENG.html", "High pressure fuel system components are between high pressure fuel pump and fuel injector.", "ptxt");
si[i++] = gsitm("N5020109F0000E00ENG.html", "Always release fuel pressure and never start the engine when performing removal and installation.", "ptxt");
si[i++] = gsitm("N5020109F0000E00ENG.html", "When removing or installing parts without releasing fuel pressure, fuel may be splashed and, if fuel contacts skin or eyes, it may cause inflammation.", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Parts Requiring Angle Tightening", "title");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Use the angle wrench [SST: KV10112100] for the final tightening of the following engine parts:", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Camshaft sprocket (INT) bolt", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Cylinder head bolts", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Main bearing cap bolts", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Connecting rod cap bolts", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Crankshaft pulley bolt (No the angle wrench is required as bolt flange is provided with notches for angle tightening)", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Do not use a torque value for final tightening.", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "The torque value for these parts are for a preliminary step.", "ptxt");
si[i++] = gsitm("N5020204Q0000H00ENG.html", "Ensure thread and seat surfaces are clean and coated with engine oil.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Liquid Gasket", "title");
si[i++] = gsitm("N5020109G0000E00ENG.html", "REMOVAL OF LIQUID GASKET SEALING", "title");
si[i++] = gsitm("N5020109G0000E00ENG.html", "After removing mounting nuts and bolts, separate the mating surface using the seal cutter [SST: KV10111100] (A) and remove old liquid gasket sealing.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Never damage the mating surfaces.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Tap the seal cutter [SST: KV10111100] to insert it , and then slide it  by tapping on the side as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "In areas where the seal cutter [SST: KV10111100] is difficult to use, lightly tap the parts using a plastic hammer to remove it.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "If for some unavoidable reason tool such as a screwdriver is used, be careful not to damage the mating surfaces.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "LIQUID GASKET APPLICATION PROCEDURE", "title");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Using a scraper (A), remove old liquid gasket adhering to the liquid gasket application surface and the mating surface.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Remove liquid gasket completely from the groove of the liquid gasket application surface, mounting bolts, and bolt holes.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Wipe the liquid gasket application surface and the mating surface with white gasoline (lighting and heating use) to remove adhering moisture, grease and foreign materials.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Attach liquid gasket tube to the tube presser (commercial service tool).", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Use Genuine Liquid Gasket or equivalent.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Apply liquid gasket without gaps to the specified location according to the specified dimensions.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "If there is a groove for liquid gasket application, apply liquid gasket to the groove.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "As for bolt holes , normally apply liquid gasket inside the holes. Occasionally, it should be applied outside the holes. Check to read the text of this manual.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", ": Groove", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", ": Inside", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Within five minutes of liquid gasket application, install the mating component.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "If liquid gasket protrudes, wipe it off immediately.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "Do not retighten mounting bolts or nuts after the installation.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "After 30 minutes or more have passed from the installation, fill engine oil and engine coolant.", "ptxt");
si[i++] = gsitm("N5020109G0000E00ENG.html", "If there are specific instructions in this manual, observe them.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Special Cautions to Ensure the Safe Disposal of Sodium-filled Exhaust Valves", "title");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Handling and disposal of sodium-filled exhaust valves requires special care and consideration. Under conditions such as breakage with subsequent contact with water, metal sodium which lines the inner portion of exhaust valve will react violently, forming sodium hydroxide and hydrogen which may result in an explosion. Sodium-filled exhaust valve is identified on the top of its stem as shown in illustration.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Identification mark of sodium-filled exhaust valve", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": 6RA", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "DEALER DISPOSAL INSTRUCTIONS", "title");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Use approved shatter-resistant eye protection when performing this procedure.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Perform this and all subsequent disposal work procedures in an open room, away from flammable liquids. Keep a fire extinguisher, rated at least 10 ABC, in close proximity to the work area.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Be sure to wear rubber gloves when performing the following operations.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Make sure the resultant (high alkalinity) waste water does not contact your skin. If the waste water does contact you, wash the contacted area immediately with large quantities of water.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Dealers should check their respective state and local regulations concerning any chemical treatment or waste water discharge permits which may be required to dispose of the resultant (high alkalinity) waste water.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Clamp valve stem in a vice.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "The valve has a specially-hardened surface. To cut through it, first remove a half-round section, approximately 30 mm (1.18 in) long using air-powered grinder until black color is removed and silver color appears.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": Black color", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": Silver color", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": 47 mm (1.85 in)", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": 17 mm (0.67 in)", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Use hacksaw to cut through approximately half the diameter of valve stem. Make the serration at a point 40 mm (1.57 in) from the end of valve stem.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", ": 32 mm (1.26 in)", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Cover the serrated end of the valve with a large shop towel . Strike the valve face end with a hammer, separating it into two pieces.", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "Fill a bucket  (such as a 20  oil can) with at least 10  (2-1/4 lmp gal) of water. Carefully place the already cut (serrated) valves into the water one-at-a-time using a set of large tweezers and quickly move away at least 2.7 m (9 ft).", "ptxt");
si[i++] = gsitm("N5020109H0000E00ENG.html", "The valves should be placed in a standing position as shown in the illustration to allow complete reaction. After the bubbling action has subsided, additional valves can be placed into the bucket allowing each subsequent chemical reaction to subside. However, no more than 8 valves should be placed in the same 10  (2-1/4 lmp gal) amount of water. The complete chemical reaction may take as long as 4 to 5 hours. Remove the valves using a set of large tweezers after the chemical reaction has stopped. Afterwards, valves can be disposed as ordinary scrap.", "ptxt");
si[i++] = gsitm("N5020109I0000F00ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N5020109I0000F00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
