si[i++] = gsitm("N5020109L0000E00ENG.html", "Inspection (Dry Paper Type)", "title");
si[i++] = gsitm("N5020109L0000E00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5020109L0000E00ENG.html", "Examine with eyes that there is no stain, clogging, or damage on air cleaner element.", "ptxt");
si[i++] = gsitm("N5020109L0000E00ENG.html", "Remove dusts (such as dead leafs) on air cleaner element surface and inside cleaner case.", "ptxt");
si[i++] = gsitm("N5020109L0000E00ENG.html", "To clean air cleaner element, blow it from intake manifold side towards air intake side to remove trash or dust.", "ptxt");
si[i++] = gsitm("N5020109L0000E00ENG.html", "If clogging or damage is observed, replace the air cleaner element.", "ptxt");
si[i++] = gsitm("N5020103O000AM00ENG.html", "Exploded View", "title");
