si[i++] = gsitm("N50201070000AR00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000AR00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000AR00ENG.html", "Turn the steering wheel to the right.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Remove the splash guard (RH). Refer to .", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Securely hold the hexagonal part  of drive belt auto-tensioner  using suitable tool, and move in the direction of arrow () (loosening direction of tensioner).", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Avoid placing hand in a location where pinching may occur if the holding tool accidentally comes off.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Insert a rod approximately 6.0 mm (0.24 in) in diameter through the rear of the drive belt auto-tensioner into retaining boss  to lock drive belt auto-tensioner pulley.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Leave drive belt auto-tensioner pulley arm locked until drive belt is installed again.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Loosen drive belt from drive belt auto-tensioner and then remove it from the other pulleys.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000AR00ENG.html", "Install the drive belt onto all of the pulleys except for the drive belt auto-tensioner. Then install the drive belt onto drive belt auto-tensioner last.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Confirm belts are completely set on the pulleys.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Release drive belt auto-tensioner, and apply tension to drive belt.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Turn crankshaft pulley clockwise several times to equalize tension between each pulley.", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Confirm the indicator is within the possible use range. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000AR00ENG.html", "Install the splash guard (RH). Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AE00ENG.html", "Alternator", "ptxt");
