si[i++] = gsitm("N50201048000AE00ENG.html", "Range when new drive belt is installed", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "C", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Possible use range", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Indicator (notch on the fixed side)", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Perform this step when engine is stopped.", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Check that the indicator  (notch on fixed side) of drive belt auto-tensioner is within the possible use range (C) in the figure.", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Check the drive belt auto-tensioner indication when the engine is cold.", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "When new drive belt is installed, the indicator (notch on fixed side) should be within the range (B) in the figure.", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "Visually check entire drive belt for wear, damage or cracks.", "ptxt");
si[i++] = gsitm("N50201048000AE00ENG.html", "If the indicator (notch on fixed side) is out of the possible use range or belt is damaged, replace drive belt.", "ptxt");
