si[i++] = gsitm("N50201070000AS00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000AS00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000AS00ENG.html", "Remove engine cover (with engine cover models). Refer to Removal and Installation.", "par1");
si[i++] = gsitm("N50201070000AS00ENG.html", "Remove ignition coil.", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", "Remove spark plug with spark plug wrench (commercial service tool).", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", ":", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", "14 mm (0.55 in)", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", "Never drop or shock spark plug.", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", "Never disassemble ignition coil.", "ptxt");
si[i++] = gsitm("N50201070000AS00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000AS00ENG.html", "Install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AF00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N50201048000AF00ENG.html", "Use standard type spark plug for normal condition.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Spark plug (standard)", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", ": Refer to Spark Plug.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Visually check the electrode for dirt and wear and the insulator for burning.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Never drop or shock spark plug.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Never use wire brush for cleaning.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "If plug tip is covered with carbon, spark plug cleaner may be used.", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Cleaner air pressure:", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Less than 588 kPa (5.9 bar , 6 kg/cm2, 85 psi)", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Cleaning time:", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Less than 20 seconds", "ptxt");
si[i++] = gsitm("N50201048000AF00ENG.html", "Checking and adjusting plug gap is not required between change intervals.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Inspection and Adjustment", "title");
si[i++] = gsitm("N5020104J0000H00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Perform inspection as follows after removal, installation or replacement of camshaft or valve-related parts, or if there is unusual engine conditions regarding valve clearance.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Remove rocker cover. Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Measure the valve clearance with the following procedure:", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Set No. 1 cylinder at TDC of its compression stroke.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Rotate crankshaft pulley  clockwise and align TDC mark (no paint)  to timing indicator  on front cover.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Paint marks (Not used for service)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "At the same time, check that both intake and exhaust cam noses of No. 1 cylinder face inside () as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Camshaft (EXH)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Camshaft (INT)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "If they do not face inside, rotate crankshaft pulley once more (360 degrees) and align as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Use a feeler gauge, measure the clearance between valve lifter and camshaft.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Valve clearance", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "By referring to the figure, measure the valve clearances at locations marked “×” as shown in the table below [locations indicated with black arrow () in the figure] with a feeler gauge.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Exhaust side", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": No. 1 cylinder", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": No. 2 cylinder", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": No. 3 cylinder", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": No. 4 cylinder", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Intake side", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Measuring position", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 1 CYL.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 2 CYL.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 3 CYL.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 4 CYL.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 1 cylinder at compression TDC", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "INT", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "EXH", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Set No. 4 cylinder at TDC of its compression stroke, rotate crankshaft pulley  one revolution (360 degrees) and align TDC mark (no paint)  to timing indicator  on front cover.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": Paint marks", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "By referring to the figure, measure the valve clearance at locations marked “×” as shown in the table below [locations indicated with black arrow () in the figure] with a feeler gauge.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "No. 4 cylinder at compression TDC", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "If out of standard, perform adjustment. Refer to \"ADJUSTMENT\".", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "ADJUSTMENT", "title");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Perform adjustment depending on selected head thickness of valve lifter.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Remove camshaft. Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Remove valve lifters at the locations that are out of the standard.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Measure the center thickness of the removed valve lifters with a micrometer (A).", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Use the equation below to calculate valve lifter thickness for replacement.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Valve lifter thickness calculation:", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "t = t1 + (C1 – C2)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "t", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "= Valve lifter thickness to be replaced", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "t1", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "= Removed valve lifter thickness", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "C1", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "= Measured valve clearance", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "C2", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "= Standard valve clearance:", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Intake", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": 0.31 mm (0.011 in)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Exhaust", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", ": 0.32 mm (0.012 in)", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Thickness of new valve lifter  can be identified by stamp mark  on the reverse side (inside the cylinder).", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Stamp mark “302” indicates 3.02 mm (0.1189 in) in thickness.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Available thickness of valve lifter: 26 sizes range 3.00 to 3.50 mm (0.1181 to 0.1378 in) in steps of 0.02 mm (0.0008 in) (when manufactured at factory). Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Install the selected valve lifter.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Install camshaft. Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Install timing chain and related parts. Refer to .", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Manually rotate crankshaft pulley a few rotations.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Check that the valve clearances is within the standard. Refer to “INSPECTION”.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Install remaining parts in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5020104J0000H00ENG.html", "Warm up the engine, and check for unusual noise and vibration.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AG00ENG.html", "Warm up engine thoroughly. Then, stop it.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Release fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Disconnect fuel pump fuse to avoid fuel injection during measurement. Refer to How To Check.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Remove ignition coil and spark plug from each cylinder. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Connect engine tachometer (not required in use of M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Install compression tester (A) with adapter onto spark plug hole.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Use compression tester whose end  (rubber portion) is smaller than 20 mm (0.79 in) in diameter. Otherwise, it may be caught by cylinder head during removal.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "With accelerator pedal fully depressed, turn ignition switch to “START” for cranking. When the gauge pointer stabilizes, read the compression pressure and engine rpm. Perform these steps to check each cylinder.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Compression pressure", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", ": Refer to General Specification.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Always use a fully charged battery to obtain specified engine speed.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If the engine speed is out of specified range, check battery liquid for proper gravity. Check engine speed again with normal battery gravity.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If compression pressure is below minimum value, check valve clearances and parts associated with combustion chamber (Valve, valve seat, piston, piston ring, cylinder bore, cylinder head, cylinder head gasket). After the checking, measure the compression pressure again.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If some cylinder has low compression pressure, pour small amount of engine oil into the spark plug hole of the cylinder to re-check it for compression.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If the added engine oil improves the compression, piston rings may be worn out or damaged. Check piston rings and replace if necessary.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If the compression pressure remains at low level despite the addition of engine oil, valves may be malfunctioning. Check valves for damage. Replace valve or valve seat accordingly.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "If two adjacent cylinders have respectively low compression pressure and their compression remains low even after the addition of engine oil, gaskets are leaking. In such a case, replace cylinder head gaskets.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "After inspection is completed, install removed parts.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Start engine, and confirm that engine runs smoothly.", "ptxt");
si[i++] = gsitm("N50201048000AG00ENG.html", "Perform trouble diagnosis. If DTC appears, erase it. Refer to M.U.T.-III SE Function.", "ptxt");
