si[i++] = gsitm("N50201070000AV00ENG.html", "To avoid the danger of being scalded, do not drain the coolant when the engine is hot.", "ptxt");
si[i++] = gsitm("N50201070000AV00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N50201070000AV00ENG.html", "Disconnect battery negative terminal.", "ptxt");
si[i++] = gsitm("N50201070000AV00ENG.html", "Remove the air cleaner case assembly and air duct. Refer to .", "ptxt");
