si[i++] = gsitm("N50201070000AV00ENG.html", "Disconnect harness connector  from the electric throttle control actuator.", "par1");
si[i++] = gsitm("N50201070000AV00ENG.html", "Disconnect water hoses  from the electric throttle control actuator.", "par3");
si[i++] = gsitm("N50201070000AV00ENG.html", "When removing only intake manifold, position electric throttle control actuator aside without disconnecting the water hose.", "ptxt");
si[i++] = gsitm("N50201070000AV00ENG.html", "Loosen bolts in reverse order as shown, then remove electric throttle control actuator and electric throttle actuator gasket.", "ptxt");
