si[i++] = gsitm("N50201070000AV00ENG.html", "Disconnect the EVAP canister purge volume control solenoid valve hose 1 from the intake manifold assembly.", "ptxt");
si[i++] = gsitm("N50201070000AV00ENG.html", "Disconnect harness connectors from the intake manifold runner control valve motor, intake manifold runner control valve position sensor, intake manifold tuning valve motor and manifold absolute pressure (MAP) sensor.", "par7");
si[i++] = gsitm("N50201070000AV00ENG.html", "Release harness retainers  from intake manifold.", "par8");
si[i++] = gsitm("N50201070000AV00ENG.html", "Loosen nuts and bolts in reverse of the sequence shown and remove the intake manifold.", "ptxt");
