si[i++] = gsitm("N50201070000CV00ENG.html", "Exhaust Manifold and Three Way Catalyst", "title");
si[i++] = gsitm("N50201070000CV00ENG.html", "Install studs in cylinder head and exhaust manifold and three way catalyst if removed. Then tighten to specification.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Do not reuse stud bolts.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Install the exhaust manifold and three way catalyst and gasket. Then tighten the nuts to specification in the numerical order shown.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", ": 41.65 N·m (4.2 kg-m, 31 ft-lb)", "ptxt");
