si[i++] = gsitm("N50201070000CV00ENG.html", "Then tighten the nuts to specification in the numerical order shown again.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Install exhaust manifold and three way catalyst cover and bolts.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Do not reuse bolts.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Install the air fuel ratio sensor 1 using heated oxygen sensor wrench [SST: KV10117100] if removed and tighten to specification.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Be careful not to damage air fuel ratio sensor 1.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Discard any air fuel ratio sensor which has been dropped from a height of more than 0.5 m (19.7 in) onto a hard surface such as a concrete floor; replace with a new one.", "ptxt");
si[i++] = gsitm("N50201070000CV00ENG.html", "Do not over-tighten the air fuel ratio sensor 1. Doing so may cause damage to the air fuel ratio sensor 1, resulting in a malfunction and the MIL coming on.", "ptxt");
si[i++] = gsitm("N50201048000AX00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AX00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N50201048000AX00ENG.html", "Check the joint of parts with the engine in running state.", "par1");
si[i++] = gsitm("N50201048000AX00ENG.html", "Check that there are no leaks of exhaust gas and abnormal sound.", "par2");
si[i++] = gsitm("N50201048000AX00ENG.html", "Surface Distortion", "title");
si[i++] = gsitm("N50201048000AX00ENG.html", "Using a feeler gauge (A) and straight edge (B), check the surface distortion of the exhaust manifold and three way catalyst mating surface as shown in the shaded area .", "par25");
