si[i++] = gsitm("N5020103O000AT00ENG.html", "Bracket", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000AY00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000AY00ENG.html", "Be sure to read Precaution for Handling High Pressure Fuel System when working on the high pressure fuel system.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Put a “CAUTION: FLAMMABLE” sign in the workshop.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Be sure to work in a well ventilated area and furnish workshop with a CO2 fire extinguisher.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never smoke while servicing fuel system. Keep open flames and sparks away from the work area.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "To avoid the danger of being scalded, never drain engine coolant when engine is hot.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Release fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove engine cover. Refer to . (With engine cover models)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove high pressure fuel pump insulator bracket. Refer to . (Without engine cover models)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove air duct. Refer to Removal and Installation.", "par6");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove battery tray. Refer to Removal and Installation.", "par7");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove high pressure fuel pump insulator.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Disconnect quick connector  with the following procedure.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Disconnect fuel feed hose  from bracket hose clamp .", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Disengage  and pull up  the pawl of the fuel feed hose connector retainer  to disconnect the fuel feed hose from high pressure fuel pump.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "If the fuel feed hose is stuck, hold the fuel pipe by hand and disconnect it by pushing and pulling.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Keep parts away from heat source. Especially, be careful when welding is performed around them.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never expose parts to battery electrolyte or other acids.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never bend or twist connection between quick connector and fuel feed hose during installation/removal.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Pull quick connector holding .", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never remove the retainer.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Prepare a tray and waste beforehand as fuel leaks out.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never pull with lateral force applied. O-ring inside quick connector may be damaged.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "To prevent damage to each joint and protect it from the entry of foreign matter, cover the joint with plastic bag  or an equivalent.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove intake manifold. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove high pressure fuel tube.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Do not reuse high pressure fuel tube.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Disconnect high pressure fuel pump harness connector from the high pressure fuel pump.", "par3");
si[i++] = gsitm("N50201070000AY00ENG.html", "Remove high pressure fuel pump  and lifter.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "To prevent damage to high pressure fuel pump and camshaft bracket, loosen bolt  alternately by one turn at a time until the reaction force applied on the high pressure fuel pump disappears.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Do not reuse O-rings.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000AY00ENG.html", "To prevent damage to parts due to generated abnormal stress and eccentric load, always observe the installation procedure.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Install high pressure fuel pump according to the following procedure.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Check the orientation of pump cam from the mounting area (view arrow) of high pressure fuel pump.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Aim pump cam at the BDC area (arrow position).", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": Camshaft (EXH)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "For BDC area, anywhere within the area indicated by arrow can be accepted.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Install O-ring to high pressure fuel pump. When handing new O-ring, paying attention to the following caution items:", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Do not reuse O-ring.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Handle O-ring with bare hands. Never wear gloves.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Lubricate O-ring with new engine oil.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never clean O-ring with solvent.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Check that O-ring and its mating part are free of foreign material.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never damage O-ring with tools and fingernails during the installation. In addition, twisting or stretching O-ring is not allowed. If O-ring is stretched during the installation to high pressure fuel pump, never install high pressure fuel pump immediately.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Lubricate high pressure fuel pump lifter and high pressure fuel pump lifter bore with clean engine oil.", "par1");
si[i++] = gsitm("N50201070000AY00ENG.html", "Reinstall the high pressure fuel pump lifter.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "When installing high pressure fuel pump lifter, note the orientation of protrusion  and cutout  in camshaft bracket, they should be aligned.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Apply oil to the fitting area of high pressure fuel pump O-ring and camshaft bracket side to install high pressure fuel pump.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Install high pressure fuel pump. To prevent damage to high pressure fuel pump and camshaft bracket, the following instructions must be observed.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten the high pressure fuel pump bolt  until it hits the high pressure fuel pump, and then tighten both bolts by 180 degrees.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": High pressure fuel pump", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Temporarily alternately tighten bolt  by three turn at time by hand.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "While pushing the center of the high pressure fuel pump by hand until it hits the camshaft bracket, tighten the high pressure fuel pump bolt by the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten the bolt (1) as shown in the figure (temporarily).", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": 2.0 N·m (0.2 kg-m, 18 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten the bolt (2) as shown in the figure (specified torque).", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": 10.0 N·m (1.0 kg-m, 89 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten the bolt (3) as shown in the figure (specified torque).", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Connect fuel feed hose with the following procedure, and them install the fuel feed hose.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Check no foreign substances are deposited in and around matching pipe and quick connector, and no damage on them.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Quick connector shall be inserted gradually, aligning with the axis of the matching pipe.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Insert the retainer until it clicks and check the retainer is locked. After insertion, pull the connector and check that the connector is locked.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": Lock position", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": Unlock position", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "If retainer cannot be installed smoothly, quick connector may be have not been installed correctly. Check connection again.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Install the fuel tube with the following procedure.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "When removing fuel tube, always replace fuel rail connector together with fuel tube.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never reuse fuel tube.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Never use fuel tube if its terminal tip is damaged.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Observe the tightening order and the tightening torque.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Temporarily tighten until the high pressure fuel tube  flare nuts  and  contact the seat.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "When temporarily tightening flare nut, place pipe in the center of the nut inner diameter.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Temporarily tighten the high-pressure fuel tube bracket mounting bolt .", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten flare nut  to the specified torque.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": 23.0 N·m (2.3 kg-m, 17 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Before tightening, check that the tool is attached at a 90° angle to the flare nut when working.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Again tighten flare nut  to the specified torque.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Tighten tighten the high-pressure fuel tube bracket mounting bolt  specified torque.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", ": 25.0 N·m (2.6 kg-m, 18 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "Install in the reverse order of removal after this step.", "ptxt");
si[i++] = gsitm("N50201070000AY00ENG.html", "After checking fuel leakage, maintain ten minutes of idling to bleed the fuel line.", "ptxt");
si[i++] = gsitm("N50201048000AK00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AK00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AK00ENG.html", "Check for Fuel Leakage", "title");
si[i++] = gsitm("N50201048000AK00ENG.html", "Turn ignition switch “ON” (with the engine stopped). With fuel pressure applied to fuel piping, check that there is no fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AK00ENG.html", "Use mirrors for checking at points out of clear sight.", "ptxt");
si[i++] = gsitm("N50201048000AK00ENG.html", "Start the engine. With engine speed increased, check again that there is no fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AK00ENG.html", "Never touch the engine immediately after it is stopped because the engine is extremely hot.", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Seal ring", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Fuel injector", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Injector holder", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Backup ring", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "O-ring (black)", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Fuel rail pressure sensor", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Gasket", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "High pressure fuel rail", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Stud bolt", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "High pressure fuel rail insulator", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "High pressure fuel rail protector", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Comply with the installation procedure when tightening. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "To High pressure fuel tube. Refer to", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", ": N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", ": Should be lubricated with oil.", "ptxt");
si[i++] = gsitm("N5020103O000AU00ENG.html", "Never remove or disassemble parts unless instructed in the figure.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Put a “CAUTION: FLAMMABLE” sign in the workshop.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Be sure to work in a well ventilated area and furnish workshop with a CO2 fire extinguisher.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Never smoke while servicing fuel system. Keep open flames and sparks away from the work area.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Release the fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Disconnect the battery negative terminal. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove intake manifold. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove high pressure fuel rail protector.", "par1");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove high pressure fuel rail insulator.", "par2");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove high pressure fuel tube. Refer to Removal and Installation.", "par3");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Disconnect harness connector from fuel rail pressure sensor.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Disconnect harness connector from fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove fuel rail pressure sensor if necessary.", "par4");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove high pressure fuel rail and fuel injector assembly.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Loosen mounting bolts and nuts in the reverse order of as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "When removing, be careful to avoid any interference with fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Use a shop cloth to absorb any fuel leakage from high pressure fuel rail.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove fuel injector from high pressure fuel rail with the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove fuel injector  from high pressure fuel rail  by pulling straight.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Be careful with remaining fuel that may go out from fuel tube.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Be careful not to damage fuel injector nozzle during removal.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Never bump or drop fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Never disassemble fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Open and remove clip  if necessary.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove O-ring, backup ring and injector holder from direct fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not reuse O-ring, backup ring or injector holder.", "par6");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Cut seal ring  while pinching it.", "par7");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not scratch direct fuel injector when removing seal ring.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not reuse seal ring.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Remove the high pressure fuel rail studs from the cylinder head if necessary.", "par9");
si[i++] = gsitm("N50201070000AZ00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000AZ00ENG.html", "If removed, install the high pressure fuel rail studs.", "par18");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install seal ring to fuel injector using the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Handle seal ring with bare hands. Do not wear gloves.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not apply engine oil to seal ring.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not clean seal ring with solvent.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install seal guide [SST:KV10119720 (J-50364)] (A) to fuel injector .", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Set seal ring  into seal installer [SST:KV10119730 (J-50364)] (A).", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Straightly insert seal ring , which is set in step b, to fuel injector as shown and install onto fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Be careful that seal ring does not exceed the groove portion of fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Insert drift [SST:KV10119710 (J-50364)] (A) to fuel injector and rotate clockwise and counterclockwise by 90° while pressing seal ring to fit it.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "This is done to correct any elongation of the seal ring caused by installation and for preventing sticking when inserting fuel injector into cylinder head.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install O-ring and backup ring to fuel injector.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not reuse O-ring.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Handle O-ring with bare hands. Do not wear gloves.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Lubricate O-ring with new engine oil.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not allow engine oil into fuel passage of fuel injector.", "par19");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not clean O-ring with solvent.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Check that O-ring and its mating part are free of foreign material.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "When installing O-ring , be careful not to scratch it with tool or fingernails. Also be careful not to twist or stretch O-ring. If O-ring was stretched while it was being attached, do not insert it quickly into high pressure fuel rail.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Insert new O-ring straight into fuel rail. Do not decenter or twist it.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Always install the backup ring  in the right direction as instructed.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the fuel injectors and high pressure fuel rail using the following procedure:", "par20");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the injector holder  onto the fuel injector .", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not reuse injector holder.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Be careful to keep injector holder from interfering with O-ring. If interference occurs, replace O-ring.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Insert fuel injector into high pressure fuel rail with injector holder attached.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Insert it while matching it to the axial center.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Insert so that tab  of injector holder is aligned to cutout  of high pressure fuel rail.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Check that installation is complete by checking that fuel injector does not rotate or come off.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Check that tabs of injector holders and high pressure fuel rail are aligned after installation.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the fuel injector and high pressure fuel rail assembly into the cylinder head and tighten the nuts and bolts using the following procedure:", "par22");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Temporarily tighten mounting fuel rail bolt 2 and fuel rail nut 3.", "par24");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tighten mounting fuel rail nuts and bolts to the specified torque in the sequence shown.", "par25");
si[i++] = gsitm("N50201070000AZ00ENG.html", "High pressure fuel rail nuts and bolts", "par27");
si[i++] = gsitm("N50201070000AZ00ENG.html", ": 10.0 N·m (1.0 kg-m, 89 in-lb)", "par28");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tighten nuts and bolts to the specified torque in the sequence shown.", "par29");
si[i++] = gsitm("N50201070000AZ00ENG.html", ": 20.5 N·m (2.1 kg-m, 15 ft-lb)", "par32");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the fuel rail pressure sensor if necessary using the following procedure:", "par33");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not reuse fuel rail pressure sensor.", "par34");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not use fuel rail pressure sensor that has been dropped.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Check that high pressure fuel rail and fuel rail pressure sensor screw have no damage, foreign matter, or stains.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not use a tool on the fuel rail while tightening the fuel pressure sensor or fuel rail damage could result.", "par35");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Do not scratch or crack high pressure fuel rail when installing fuel rail pressure sensor.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Apply engine oil to the threaded portion and front edge of the fuel rail pressure sensor.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Before tightening fuel rail pressure sensor, securely install a hexagon tool.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Lubricate fuel rail pressure sensor threads with clean engine oil.", "par36");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Check that high pressure fuel rail and fuel rail pressure sensor threads have no damage or foreign matter.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tighten fuel rail pressure sensor to the specified torque.", "par37");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Fuel rail pressure sensor", "par39");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tighten fuel rail pressure sensor to the specified angle using angle wrench [SST:KV10112100 (BT-8653-A)].", "par41");
si[i++] = gsitm("N50201070000AZ00ENG.html", "To check tightening angle, use Tool. Do not judge the angle by visual inspection.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "The torque value for the angle tightening must be 90 N·m (9.2 kg-m, 66 ft-lb) or less.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "If torque value reaches 90 N·m (9.2 kg-m, 66 ft-lb), then replace the fuel rail pressure sensor and high pressure fuel rail with a new one.", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tightening angle", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", ": 45°", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Connect the fuel rail pressure sensor harness connector.", "par42");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Connect the fuel injector harness connector.", "par43");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the high pressure fuel tube. Refer to Removal and Installation .", "ptxt");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Install the high pressure fuel rail protector using the following procedure:", "par10");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Hand tighten the bolts in order number of to shown in the figure.", "par11");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Tighten the bolts in order number of to shown in the figure (specified torque).", "par13");
si[i++] = gsitm("N50201070000AZ00ENG.html", "High pressure fuel rail protector bolts", "par16");
si[i++] = gsitm("N50201070000AZ00ENG.html", ": 25.0 N·m (2.6 kg-m, 18 ft-lb)", "par17");
si[i++] = gsitm("N50201070000AZ00ENG.html", "Installation of the remaining components is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201048000AL00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AL00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AL00ENG.html", "Check on Fuel Leakage", "title");
si[i++] = gsitm("N50201048000AL00ENG.html", "Turn ignition switch “ON” (with the engine stopped). With fuel pressure applied to fuel piping, check there are no fuel leaks at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AL00ENG.html", "Use mirrors for checking at points out of clear sight.", "ptxt");
si[i++] = gsitm("N50201048000AL00ENG.html", "Start the engine. With engine speed increased, check again that there are no fuel leaks at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AL00ENG.html", "Never touch the engine immediately after stopped, as the engine becomes extremely hot.", "ptxt");
