si[i++] = gsitm("N50201070000B000ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000B000ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the engine cover (with engine cover models). Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000B000ENG.html", "Disconnect the brake booster vacuum hose  and brake booster vacuum tube  from the intake manifold.", "par1");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the EGR outlet tube .", "par3");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the engine oil gauge.", "par5");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the high pressure fuel pump insulator. Refer to Removal and Installation.", "par6");
si[i++] = gsitm("N50201070000B000ENG.html", "Disconnect the harness connectors from the ignition coils.", "par7");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the ignition coils.", "par8");
si[i++] = gsitm("N50201070000B000ENG.html", "Disconnect the harness clip from the rocker cover and reposition harness.", "par9");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove bolt and reposition the engine cover bracket. Refer to Removal and Installation..", "par10");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the PCV hose and blow-by hose from the rocker cover.", "par11");
