si[i++] = gsitm("N50201070000B000ENG.html", "Remove the rocker cover and rocker cover gasket.", "par14");
si[i++] = gsitm("N50201070000B000ENG.html", "Do not reuse rocker cover gasket.", "ptxt");
si[i++] = gsitm("N50201070000B000ENG.html", "Do not drop or shock rocker cover.", "par34");
si[i++] = gsitm("N50201070000B000ENG.html", "Discard any rocker cover which has been dropped or shocked.", "par35");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the oil filler cap if necessary.", "par15");
si[i++] = gsitm("N50201070000B000ENG.html", "Remove the PCV valve if necessary.", "par16");
si[i++] = gsitm("N50201070000B000ENG.html", "Do not reuse O-ring.", "ptxt");
si[i++] = gsitm("N50201070000B000ENG.html", "INSTALLATION", "title");
