si[i++] = gsitm("N50201070000CZ00ENG.html", "Make sure the mating marks on the timing chain and each sprocket are still aligned. Then install the front cover.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Do not damage the front oil seal or camshaft sprocket (INT) oil seal during installation.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Tighten the front cover bolts to the specified torque in the sequence shown.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Front cover bolts", "par108");
si[i++] = gsitm("N50201070000CZ00ENG.html", "No. 6, 7, 8, 9, 10, 11, 13", "par109");
si[i++] = gsitm("N50201070000CZ00ENG.html", ": 49 N·m (5.0 kg-m, 36 ft-lb)", "par110");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Except No. 6, 7, 8, 9, 10, 11, 13", "par112");
si[i++] = gsitm("N50201070000CZ00ENG.html", ": 12.8 N·m (1.3 kg-m, 9 ft-lb)", "par111");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Install crankshaft pulley using the following procedure:", "par124");
si[i++] = gsitm("N50201070000CZ00ENG.html", "When inserting crankshaft pulley with a suitable tool, tap on its center portion (not circumference).", "par125");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Do not damage front oil seal lip portion.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Secure crankshaft pulley  with a suitable tool (A).", "par126");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Apply new engine oil to thread and seat surfaces of crankshaft pulley bolt.", "par128");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Tighten crankshaft pulley bolt to the specified torque.", "par129");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Crankshaft bolt", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", ": 42.1 N·m (4.3 kg-m, 31 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Tighten crankshaft pulley bolt to the specified angle using angle wrench [SST: KV10112100 (BT-8653-A)].", "par130");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Check and confirm the tightening angle using angle wrench [SST: KV10112100 (BT-8653-A)]. Avoid judgment by visual inspection without Tool.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Tightening angle", "par132");
si[i++] = gsitm("N50201070000CZ00ENG.html", ": 90° - 96°", "par133");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Check that crankshaft rotates clockwise smoothly.", "par137");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Install the electric intake valve timing control actuator and tighten the bolts to the specified torque in the sequence shown.", "par138");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Installation of the remaining components is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Perform \"Electric intake valve timing control actuator position learning\". Refer to Work Procedure.", "par158");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Perform the “Throttle Valve Closed Position Learning” when harness connector of electric throttle control actuator is disconnected.", "ptxt");
si[i++] = gsitm("N50201070000CZ00ENG.html", "Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "Timing Chain", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "Check timing chain for cracks  and any excessive wear  at the roller links of timing chain. Replace timing chain if necessary.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Balancer Unit Bolt Outer Diameter", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "Measure outer diameters (D, C) at the two positions as shown.", "ptxt");
