si[i++] = gsitm("N50201048000AM00ENG.html", ": 40 mm (1.57 in)", "par197");
si[i++] = gsitm("N50201048000AM00ENG.html", "E", "par198");
si[i++] = gsitm("N50201048000AM00ENG.html", ": 10 mm (0.39 in)", "par199");
si[i++] = gsitm("N50201048000AM00ENG.html", "Measure (C) within the range (B).", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "If the value difference [(D) - (C)] exceeds the limit, replace the balancer unit bolt with a new one.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", ": 0.15 mm (0. 0059 in) or more", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "Inspection for Leaks", "title");
si[i++] = gsitm("N50201048000AM00ENG.html", "The following are procedures for checking fluids leak, lubricates leak.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Before starting engine, check oil/fluid levels including engine coolant and engine oil. If less than required quantity, fill to the specified level.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Use procedure below to check for fuel leakage.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Turn ignition switch “ON” (with engine stopped). With fuel pressure applied to fuel piping, check for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Start engine. With engine speed increased, check again for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Run engine to check for unusual noise and vibration.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Warm up engine thoroughly to check there is no leakage of fuel, or any oil/fluids including engine oil and engine coolant.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "Bleed air from lines and hoses of applicable lines, such as in cooling system.", "ptxt");
si[i++] = gsitm("N50201048000AM00ENG.html", "After cooling down engine, again check oil/fluid levels including engine oil and engine coolant. Refill to the specified level, if necessary.", "ptxt");
