si[i++] = gsitm("N50201070000B200ENG.html", "To avoid the danger of being scalded, never drain the engine oil when the engine is hot.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "When removing oil pan (lower) only, take step 2 and 3.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Remove engine under cover front. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Drain engine oil. Refer to Draining.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Remove oil pan (lower) with the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Loosen mounting bolts in reverse order as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Insert seal cutter [SST:KV10111100 (J-37228)] (A) between oil pan (upper) and oil pan (lower).", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Be careful not to damage the mating surface.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000B200ENG.html", "Do not reuse drain plug washer.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Install oil pan (lower) with the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Use a scraper (A) to remove old liquid gasket from mating surfaces.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Also remove old liquid gasket from mating surface of oil pan (upper).", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Remove old liquid gasket from the bolt holes and threads.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Never scratch or damage the mating surface when cleaning off liquid gasket.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Apply a continuous bead of liquid gasket  with a tube presser (commercial service tool) as shown in the figure.", "ptxt");
