si[i++] = gsitm("N50201070000B200ENG.html", "Attaching should be done within 5 minutes after liquid gasket application.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Then allow 30 minutes for the liquid gasket to set before adding oil to the engine.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Tighten bolts in numerical order as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Oil pan (lower) bolts", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", ": 7.4 N·m (0.75 kg-m, 65 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Install drain plug.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Refer to the figure of components of former page for installation direction of washer. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Install in the reverse order of removal after this step.", "ptxt");
si[i++] = gsitm("N50201070000B200ENG.html", "Pour engine oil at least 30 minutes after oil pan is installed.", "ptxt");
