si[i++] = gsitm("N50201070000CW00ENG.html", "Install the rear plate cover.", "par8");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install support bearing bracket to oil pan (upper).", "par13");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install rear torque rod to rear torque rod bracket.", "par12");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install water hose A and water hose B from oil cooler.", "par11");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install the engine oil pressure control solenoid valve and tighten bolts to the specified torque in the sequence shown.", "par14");
si[i++] = gsitm("N50201070000CW00ENG.html", "Bolts", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", ": 9.0 N·m (0.92 kg-m, 80 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Ensure engine oil pressure control solenoid valve O-ring sealing surface is free from dents or flaws.", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Apply clean engine oil to O-rings.", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Ensure engine oil pressure control solenoid valve harness is pushed to baffle side to avoid interference with upper oil pan and oil strainer.", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install the oil strainer and tighten bolts to the specified torque in the sequence shown.", "par16");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install oil pan (lower). Refer to .", "ptxt");
