si[i++] = gsitm("N50201070000CW00ENG.html", "Refer to the figure of components of former page for installation direction of washer. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Install in the reverse order of removal after this step.", "ptxt");
si[i++] = gsitm("N50201070000CW00ENG.html", "Pour engine oil at least 30 minutes after oil pan is installed.", "ptxt");
si[i++] = gsitm("N50201048000AO00ENG.html", "Inspection", "title");
