si[i++] = gsitm("N50201048000AO00ENG.html", "Check engine oil level and adjust engine oil. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AO00ENG.html", "Start engine, and check there is no leaks of engine oil.", "ptxt");
si[i++] = gsitm("N50201048000AO00ENG.html", "Stop engine and wait for 10 minutes.", "ptxt");
si[i++] = gsitm("N50201048000AO00ENG.html", "Check engine oil level again. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000B400ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000B400ENG.html", "Remove camshafts. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Remove valve lifters. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Rotate crankshaft, and set piston whose valve oil seal is to be removed to TDC. This will prevent valve from dropping into cylinder.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "When rotating crankshaft, be careful to avoid scarring front cover with timing chain.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Remove valve collet.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Compress valve spring with valve spring compressor [SST: KV10116200] (A), attachment [SST: KV10115900] (C) and adapter [SST: KV10109220] (B). Remove valve collet with a magnet hand.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Be careful not to damage valve lifter holes.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Install Tool (A) in the center of valve spring retainer to press it.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", ": Valve spring retainer", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Remove valve spring retainer and valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Never remove valve spring seat from valve spring.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Remove valve oil seal with a valve oil seal puller [SST: KV10107902] (A).", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000B400ENG.html", "Apply new engine oil to valve oil seal joint surface and seal lip.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Press in valve oil seal to the height “H” shown in the figure with a valve oil seal drift [SST: KV10115600] (A).", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Height “H”", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", ": CylinderHead.", "ptxt");
si[i++] = gsitm("N50201070000B400ENG.html", "Install in the reverse order of removal after this step.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Removal and Installation", "title");
