si[i++] = gsitm("N50201070000B500ENG.html", "Be careful not to damage front cover and crankshaft.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Do not reuse front oil seal.", "par2");
si[i++] = gsitm("N50201070000B500ENG.html", "INSTALLATION", "title");
