si[i++] = gsitm("N50201070000B500ENG.html", "Install front oil seal so that each seal lip is oriented as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", ": Dust seal lip", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", ": Oil seal lip", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", ": Engine outside", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", ": Engine inside", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Press-fit front oil seal until it is flush with front end surface of front cover using a suitable drift (A).", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Press-fit oil seal straight to avoid causing burrs or tilting.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Never touch the grease applied to the oil seal lip.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Do not reuse oil seal.", "ptxt");
si[i++] = gsitm("N50201070000B500ENG.html", "Install in the reverse order of removal after this step.", "ptxt");
