si[i++] = gsitm("N50201070000B600ENG.html", "Be careful not to damage crankshaft and cylinder block.", "ptxt");
si[i++] = gsitm("N50201070000B600ENG.html", "Do not reuse rear oil seal.", "par1");
si[i++] = gsitm("N50201070000B600ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000B600ENG.html", "Apply new engine oil to seal lip.", "ptxt");
