si[i++] = gsitm("N50201070000CY00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Situate the vehicle on a flat and solid surface.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Place chocks at front and back of rear wheels.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Attach proper slingers and bolts described in PARTS CATALOG if engine slingers are not equipped.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Always be careful to work safely, avoid forceful or uninstructed operations.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Never start working until exhaust system and coolant are cool enough.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "If items or work required are not covered by the engine section, refer to the applicable sections.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Always use the support point specified for lifting.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Use either 2-pole lift type or separate type lift as best you can. If board-on type is used for unavoidable reasons, support at the rear axle jacking point with a transmission jack or similar tool before starting work, in preparation for the backward shift of center of gravity.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "For supporting points for lifting and jacking point at rear axle, refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Outline", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the engine and the transaxle assembly from the vehicle downward. Separate the engine and the transaxle.", "par1");
si[i++] = gsitm("N50201070000CY00ENG.html", "Preparation", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Release fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Drain engine coolant from radiator. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Perform this step when the engine is cold.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Never spill engine coolant on drive belt.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the following parts.", "ptxt");
