si[i++] = gsitm("N50201070000CY00ENG.html", "Engine Room LH", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect all connections of engine harness around the engine mounting insulator (LH), and then temporarily secure the engine harness into the engine side.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Protect connectors using a resin bag against foreign materials during the operation.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove battery bracket. Refer to .", "par5");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the battery positive terminal harness nut . Refer to .", "par4");
si[i++] = gsitm("N50201070000CY00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the cooling fan harness connector and clamp.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the brake booster vacuum hose on the engine side. Refer to  &lt;LHD>.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the brake booster vacuum hose on the engine side. Refer to  &lt;RHD>.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the heater hose on the engine side.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect fuel feed hose at engine side. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the EVAP canister hose  from vacuum delay valve assembly .", "par6");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the radiator hose (upper) on the engine side.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect CVT fluid cooler hose A and CVT fluid cooler hose B from the CVT oil warmer. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Engine Room Underbody LH", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the engine harness  from the relay box .", "par10");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove the engine harness connectors  from the units.", "par12");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove ground cable .", "par11");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove ground cable bracket  at transaxle side.", "par7");
si[i++] = gsitm("N50201070000CY00ENG.html", "Engine Room RH", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect A/C low pressure piping from A/C compressor, and temporarily fasten it on vehicle with a rope. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove ground cable at engine side.", "par8");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the reservoir tank hose on the reservoir tank side.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Vehicle inside", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect steering column assembly at steering gear assembly side. Refer to .", "ptxt");
