si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect the radiator hose (lower) on the radiator side. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Disconnect A/C high pressure piping from A/C compressor, and temporarily fasten it on vehicle with a rope. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove propeller shaft (4WD models). Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Fasten the radiator at the upper radiator core support with a rope or similar.", "par9");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove torque rod numerical order shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove front suspension member. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove front drive shafts (RH and LH). Refer to  (2WD models), Removal and Installation (4WD models).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Removal", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Use a manual lift table caddy (commercial service tool) or equivalently rigid tool such as a transmission jack. Securely support bottom of the engine and the transaxle assembly.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Put a piece of wood or an equivalent as the supporting surface, secure a completely stable condition.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove engine mounting insulator bolts (RH).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Loosen the mounting bolts in the reverse order as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove engine mounting insulator bolts (LH).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Loosen the mounting bolts (A) as shown in the figure.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove engine and transaxle assembly from the vehicle by lowering (or raising the lift) a bottom supporting tool, such as manual lift table caddy (commercial service tool) or mission jack.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Check that no part interferes with the vehicle side.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Before and during this lifting, always check if any harnesses are left connected.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "During the removal, always be careful to prevent the vehicle from falling off the lift due to changes in the center of gravity.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "If necessary, support the vehicle by setting jack or suitable tool at the rear.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Separation", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Install engine slingers into front left of engine mount bracket (RH) and rear right of cylinder head.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Slinger bolts", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Engine slinger  cylinder head side:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", ": 22.0 N·m (2.2 kg-m, 16 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Engine slinger  engine mount bracket side:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove starter motor. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Lift with a hoist and separate the engine from the transaxle assembly. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Never allow engine oil to get on engine mounting insulator. Be careful not to damage engine mounting insulator.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Check that each mounting insulator is seated properly, and tighten mounting nuts and bolts.", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Install the engine mounting insulator bolts (LH) as follows:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Tighten the bolt in order of numbers shown in the figure (specified torque).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", ": 62.0 N·m (6.3 kg-m, 46 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Install the engine mounting insulator bolts (RH) as follows:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Tighten the bolt (A) as shown in the figure (temporarily).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Install the rear torque rod bracket bolts as follows:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", ": 105.0 N·m (11.0 kg-m, 77 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Installation", "title");
si[i++] = gsitm("N50201070000CY00ENG.html", "Lift up the engine assembly to the vehicle.", "par13");
si[i++] = gsitm("N50201070000CY00ENG.html", "Tighten the bolt (A) as shown in the figure (specified torque).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Remove bottom supporting tool, such as manual lift table caddy (commercial service tool) or mission jack.", "par14");
si[i++] = gsitm("N50201070000CY00ENG.html", "Check the engine mounting insulator is not twisted.", "par48");
si[i++] = gsitm("N50201070000CY00ENG.html", "Install the rear torque bolts as follows:", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Tighten the bolts (A) as shown in the figure (temporarily).", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", ": 180.0 N·m (18.0 kg-m, 133 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000CY00ENG.html", "Check the engine rear torque is not twisted.", "par15");
si[i++] = gsitm("N50201048000AP00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AP00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AP00ENG.html", "Inspection for Leaks", "title");
si[i++] = gsitm("N50201048000AP00ENG.html", "The following are procedures for checking fluids leak, lubricates leak and exhaust gases leak.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Before starting engine, check oil/fluid levels including engine coolant and engine oil. If less than required quantity, fill to the specified level.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Use procedure below to check for fuel leakage.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Turn ignition switch “ON” (with engine stopped). With fuel pressure applied to fuel piping, check for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Start engine. With engine speed increased, check again for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Run engine to check for unusual noise and vibration.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Warm up engine thoroughly to check there is no leakage of fuel, exhaust gases, or any oil/fluids including engine oil and engine coolant.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "Bleed air from lines and hoses of applicable lines, such as in cooling system.", "ptxt");
si[i++] = gsitm("N50201048000AP00ENG.html", "After cooling down engine, again check oil/fluid levels including engine oil and engine coolant. Refill to the specified level, if necessary.", "ptxt");
