si[i++] = gsitm("N502010750000H00ENG.html", "Setting", "title");
si[i++] = gsitm("N502010750000H00ENG.html", "Explained here is how to disassemble with engine stand supporting transaxle surface. When using different type of engine stand, note with difference in steps and etc.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Remove the engine and the transaxle assembly from the vehicle, and separate the transaxle from the engine. Refer to .", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Remove drive plate. Remove to .", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Lift the engine with a hoist to install it onto widely use engine stand.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Use the engine stand that has a load capacity [approximately 135 kg (298 lb) or more] large enough for supporting the engine weight.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "If the load capacity of stand is not adequate, remove the following parts beforehand to reduce the potential risk of overturning stand.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Intake manifold: Refer to .", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Exhaust manifold: Refer to .", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "The figure shows an example of widely used engine stand (A) that can support mating surface of transaxle.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Before removing the hanging chains, check the engine stand is stable and there is no risk of overturning.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Drain engine oil. Refer to Draining.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Be sure to clean drain plug and install with new washer.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Drain engine coolant by removing water drain plug  from inside of the engine.", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", "Tightening torque", "ptxt");
si[i++] = gsitm("N502010750000H00ENG.html", ": 9.8 N·m (1.0 kg-m, 87 in-lb)", "ptxt");
