si[i++] = gsitm("N50201070000B800ENG.html", "Remove drive belt. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B800ENG.html", "Keep each auto-tensioner pulley arm locked after drive belts are removed.", "ptxt");
si[i++] = gsitm("N50201070000B800ENG.html", "Remove drive belt auto-tensioner.", "ptxt");
si[i++] = gsitm("N50201070000B800ENG.html", "Installation", "title");
si[i++] = gsitm("N50201070000B800ENG.html", "Installation is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201070000B800ENG.html", "When installing drive belt auto-tensioner, be careful not to interfere with water pump pulley.", "ptxt");
si[i++] = gsitm("N50201070000B800ENG.html", "Never swap the pulley between new and old drive belt auto-tensioner.", "ptxt");
si[i++] = gsitm("N5020103O000B100ENG.html", "Exploded View", "title");
