si[i++] = gsitm("N50201070000B900ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000B900ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000B900ENG.html", "Remove the engine and the transaxle assembly from the vehicle, and separate the transaxle from the engine. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Remove the drive plate using the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Secure crankshaft pulley  with a pulley holder [commercial service tool] (A), and remove flywheel damper mounting bolts.", "par2");
si[i++] = gsitm("N50201070000B900ENG.html", "Loosen drive plate bolts and remove drive plate and drive plate reinforcement.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Do not disassemble drive plate.", "par15");
si[i++] = gsitm("N50201070000B900ENG.html", "Do not place drive plate with signal plate facing down.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "When handling signal plate, take care not to damage or scratch drive plate.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Handle signal plate in a manner that prevents them from becoming magnetized.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Remove pilot converter , from the rear end of the crankshaft. Use a pilot bushing puller (commercial service tool) (A), if necessary.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000B900ENG.html", "Install pilot converter.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Install drive plate in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Install drive plate , reinforcement plate  and pilot converter  as shown in figure.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", ": Crankshaft rear end", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", ": Rounded", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", ": Chamfered", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", ": Engine front", "par4");
si[i++] = gsitm("N50201070000B900ENG.html", "Using a drift of 33 mm (1.30 in) in diameter, press-fit pilot converter into the end of crankshaft until it stops.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Be careful not to damage or scratch the signal plate.", "ptxt");
si[i++] = gsitm("N50201070000B900ENG.html", "Temporarily tighten drive plate bolts in a diagonal order over several steps.", "par7");
si[i++] = gsitm("N50201070000B900ENG.html", "Tighten drive plate bolts using a suitable tool in a diagonal order over several steps.", "par1");
si[i++] = gsitm("N50201070000B900ENG.html", "Installation of the remaining components is in the reverse order of removal.", "par10");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Appearance of Drive Plate", "title");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Replace drive plate if dents, scratches or damage exist.", "par4");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Drive Plate Lateral Run-Out", "title");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Install drive plate to crankshaft and measure deflection with suitable tool (A).", "ptxt");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Measure deflection on the drive plate to torque converter contact surface . Measurements should be taken 11.0 - 20.6 mm (0.43 - 0.811 in) from the center of the torque converter bolt hole.", "ptxt");
si[i++] = gsitm("N50201048000AQ00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N50201048000AQ00ENG.html", ": 0.35 mm (0.014 in) or less.", "ptxt");
si[i++] = gsitm("N50201048000AQ00ENG.html", "If the measurement value is outside the reference value, replace drive plate.", "ptxt");
