si[i++] = gsitm("N50201070000BA00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000BA00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the timing chain. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Disconnect the harness connectors from the intake camshaft position sensor, exhaust camshaft position sensor, engine coolant temperature sensor, EVAP canister purge volume control solenoid valve, high pressure fuel pump and air fuel ratio (A/F) sensor 1.", "par1");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove camshaft position sensors.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Do not reuse O-rings.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Release harness retainers and reposition harness.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the high pressure fuel pump insulator. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the high pressure fuel tube, high pressure fuel pump and high pressure fuel pump lifter. Refer to .", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove electric intake valve timing control actuator target from camshaft sprocket (INT).", "par2");
si[i++] = gsitm("N50201070000BA00ENG.html", "Do not reuse electric intake valve timing control actuator target.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the camshaft sprocket [INT]  and camshaft sprocket [EXH]  using the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Do not rotate the crankshaft or camshafts while the timing chain is removed. It can cause damage to the valves and pistons.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Secure hexagonal part  of the camshaft with a suitable tool and loosen the camshaft sprocket bolt.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the camshaft sprocket bolt and camshaft sprockets for both camshafts.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Loosen camshaft bracket bolts in reverse of the sequence shown.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Camshaft bracket (No.1) and camshaft position sensor bracket use liquid gasket and can be difficult to remove.  Do not damage mating surface when removing.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": Exhaust side", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": Intake side", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove camshaft signal plate (INT) and camshaft signal plate (EXH) (if necessary).", "par5");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove the valve lifters.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Check installation positions, and set them aside in the order removed.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000BA00ENG.html", "If replacing intake camshaft position sensor or exhaust camshaft position sensor, perform \"Electric intake valve timing control actuator position learning\". Refer to .", "par3");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the valve lifter.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install them in the same position from which they were removed.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "If removed, install the camshaft signal plate (INT) and camshaft signal plate (EXH).", "par8");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the camshaft [INT]  and camshaft [EXH] .", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "The distinction between the intake and exhaust camshaft can be made by the shape of the rear  of the exhaust camshaft.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install camshafts so that the dowel pins  on the front side are positioned as shown.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": Exhaust camshaft", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": Intake camshaft", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install camshaft brackets.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install by referring to identification mark on upper surface mark.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install so that identification mark can be correctly read when viewed from the exhaust side.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install camshaft bracket (No. 1) and camshaft position sensor bracket.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Apply a bead of liquid gasket [3.4 - 4.4 mm (0.134-0.173 in)] to camshaft bracket [No. 1]  and camshaft position sensor bracket as shown.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "The components must be installed within 5 minutes of the liquid gasket application.", "par10");
si[i++] = gsitm("N50201070000BA00ENG.html", "Do not re-tighten bolts after the 5 minutes have elapsed.", "par12");
si[i++] = gsitm("N50201070000BA00ENG.html", "Allow 30 minutes for the liquid gasket to set before adding oil to the engine.", "par13");
si[i++] = gsitm("N50201070000BA00ENG.html", "Remove liquid gasket that protrudes at locations () shown.", "par11");
si[i++] = gsitm("N50201070000BA00ENG.html", "Use Liquid Gasket or equivalent.", "par40");
si[i++] = gsitm("N50201070000BA00ENG.html", "Permatex Ultra Grey 82194", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "ThreeBond 1207, 1215, 1216, 1217F, 1217G and 1217H", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Nissan RTV Part No. 999MP-A7007", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Tighten camshaft bracket bolts in five steps in the order as shown.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 1 (bolts 1 - 26)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 1.96 N·m (0.20 kg-m, 17 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 2 (bolts 11 - 26)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 5.88 N·m (0.60 kg-m, 52 in-lb)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 3 (bolts 1 - 10)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 4 (bolts 11 - 26)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 10.41 N·m (1.1 kg-m, 8 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 5 (bolts 1 - 10)", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "After tightening camshaft bracket bolts, be sure to wipe off excessive liquid gasket from the parts listed below.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Mating surface of rocker cover.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Mating surface of front cover.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the camshaft sprocket [INT]  and camshaft sprocket [EXH] .", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Secure hexagonal part  of the camshaft with a suitable tool and tighten the camshaft sprocket bolts to the specified torque.", "par14");
si[i++] = gsitm("N50201070000BA00ENG.html", "Camshaft sprocket (INT) bolt", "par30");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 1", "par32");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 35.0 N·m (3.6 kg-m, 26 ft-lb)", "par33");
si[i++] = gsitm("N50201070000BA00ENG.html", "Step 2", "par34");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 28° - 33°", "par35");
si[i++] = gsitm("N50201070000BA00ENG.html", "Camshaft sprocket (EXH) bolt", "par36");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 50.0 N·m (5.1 kg-m, 37 ft-lb)", "par39");
si[i++] = gsitm("N50201070000BA00ENG.html", ": 45° - 50°", "par40");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the electric valve timing control actuator target  into the camshaft sprocket (INT)  until the metal ring  clips into the groove  in the sprocket.", "par25");
si[i++] = gsitm("N50201070000BA00ENG.html", "Do not reuse electric valve timing control actuator target.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Apply new engine oil to the electric valve timing control actuator target O-ring if necessary. Make sure that no engine oil adheres to front face of camshaft sprocket (INT).", "par27");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the timing chain. Refer to Removal and Installation.", "par31");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the high pressure fuel pump. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Install the high pressure fuel tube. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Check and adjust valve clearances. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N50201070000BA00ENG.html", "Installation of the remaining components is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft Runout", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Put V-block on a precise flat table, and support No. 2 and 5 journal of camshaft.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Never support No. 1 journal (on the side of camshaft sprocket) because it has a different diameter from the other four locations.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Set dial indicator (A) vertically to No. 3 journal.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Turn camshaft to one direction with hands, and measure the camshaft runout on dial indicator. (Total indicator reading)", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Standard: Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If out of the standard, replace camshaft.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft Cam Height", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the camshaft cam height with a micrometer (A).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Standard and Limit: Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If it exceeds the limit, replace camshaft.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft Journal Oil Clearance", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "CAMSHAFT JOURNAL DIAMETER", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the outer diameter of camshaft journal with a micrometer (A).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "CAMSHAFT BRACKET INNER DIAMETER", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Tighten camshaft bracket bolts with specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the inner diameter (A) of camshaft bracket with a cylinder gauge (B).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "CAMSHAFT JOURNAL OIL CLEARANCE", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "(Oil clearance) = (Camshaft bracket inner diameter) – (Camshaft journal diameter)", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If out of the standard, replace either or both camshaft and cylinder head.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft bracket cannot be replaced as a single part, because it is machined together with cylinder head. Replace whole cylinder head assembly.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft End Play", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Install camshaft in cylinder head. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Install dial indicator (A) in thrust direction on front end of camshaft. Read the end play of dial indicator when camshaft is moved forward/backward (in direction to axis).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Standard : Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the following parts if out of the standard.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Dimension “A” for camshaft No. 1 journal", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", ":", "par3");
si[i++] = gsitm("N50201048000AW00ENG.html", "Dimension “B” for cylinder head No. 1 journal", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Refer to the standards above, and then replace camshaft and/or cylinder head.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Camshaft Sprocket Runout", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Install the camshaft in the cylinder head.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Install the camshaft sprocket on the camshaft.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the camshaft sprocket runout with a dial indicator (A). (Total indicator reading)", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Limit: Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If it exceeds the limit, replace camshaft sprocket.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Valve Lifter", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Check if surface of valve lifter has any wear or cracks.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If anything of the above is found, replace valve lifter. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Valve Lifter Clearance", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "VALVE LIFTER OUTER DIAMETER", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the outer diameter of valve lifter with a micrometer (A).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "VALVE LIFTER HOLE DIAMETER", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Measure the diameter of valve lifter hole of cylinder head with an inside micrometer (A).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "VALVE LIFTER CLEARANCE", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "(Valve lifter clearance) = (Valve lifter hole diameter) – (Valve lifter outer diameter)", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If out of the standard, referring to the each standard of valve lifter outer diameter and valve lifter hole diameter, replace either or both valve lifter and cylinder head.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Inspection of Camshaft Sprocket (EXH) Oil Groove.", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "Check when engine is cold so as to prevent burns from any splashing engine oil.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Perform this inspection only when DTC P0014, P0015, P0017 is detected in self-diagnostic results of M.U.T.-III SE and it is directed according to inspection procedure of EC section.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Check when the engine is cold so as to prevent burns from any splashing engine oil.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Check the engine oil level. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Remove the exhaust valve timing intermediate lock control solenoid valve, exhaust valve timing control solenoid valve. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Perform the following procedure so as to prevent the engine from being unintentionally started while checking.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Release fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Disconnect ignition coil and injector harness connectors.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Remove intake valve timing control solenoid valve. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Crank the engine, and then check that engine oil comes out from intake valve timing control cover oil hole . End crank after checking.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Be careful not to touch rotating parts (drive belt, idler pulley, and crankshaft pulley, etc.).", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Engine oil may squirt from intake valve timing control solenoid valve installation hole during cranking. Use a shop cloth to prevent the engine components and the vehicle. Do not allow engine oil to get on rubber components such as drive belt or engine mount insulators. Immediately wipe off any splashed engine oil.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If engine oil does not come out from valve timing control holes, diagnose problem in lubrication circuit such as dirty oil groove between oil strainer and exhaust valve timing intermediate lock control solenoid valve or exhaust valve timing control solenoid valve.Refer to .", "par5");
si[i++] = gsitm("N50201048000AW00ENG.html", "Remove components between exhaust valve timing intermediate lock control solenoid valve or exhaust valve timing control solenoid valve and camshaft sprocket (EXH) (if necessary) and then check each oil groove for clogging.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Clean oil groove if necessary. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "After inspection, install removed parts.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Inspection for Leakage", "title");
si[i++] = gsitm("N50201048000AW00ENG.html", "The following are procedures for checking fluid leakage, lubricant leakage, and exhaust gas leakage.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Before starting engine, check oil/fluid levels including engine coolant and engine oil. If less than required quantity, fill to the specified level. Refer to", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Inspection.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Use procedure below to check for fuel leakage:", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Place ignition switch in the “ON” position (with engine stopped). With fuel pressure applied to fuel piping, check for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Start engine. With engine speed increased, check again for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Run engine to check for unusual noise and vibration.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "If hydraulic pressure inside timing chain tensioner drops after removal/installation, slack in guide may generate a pounding noise during and just after the engine start. However, this does not indicate an unusualness. Noise will stop after hydraulic pressure rises.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Warm up engine thoroughly to check that there is no leakage of fuel, or any oil/fluids including engine oil and engine coolant.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "Bleed air from lines and hoses of applicable lines, such as in cooling system.", "ptxt");
si[i++] = gsitm("N50201048000AW00ENG.html", "After cooling down engine, again check oil/fluid levels including engine oil and engine coolant. Refill to the specified level, if necessary.", "ptxt");
