si[i++] = gsitm("N50201070000BB00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N50201070000BB00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove the camshafts. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove spark plugs. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove the three way catalyst. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove the EGR cooler bracket bolts and remove the EGR cooler and EGR cooler bracket as an assembly. Refer to Removal and Installation.", "par16");
si[i++] = gsitm("N50201070000BB00ENG.html", "Loosen the cylinder head bolts in reverse of the order shown.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove cylinder head.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Remove cylinder head gasket.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Do not reuse cylinder head gasket.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N50201070000BB00ENG.html", "Clean surfaces of cylinder head and cylinder block.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Install a new cylinder head gasket.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Install the cylinder head.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Tighten cylinder head bolts using the following procedure:", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "If cylinder head bolts are reused, check their outer diameters before installation. Refer to", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Clean threads and seating surfaces of bolts.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Apply new engine oil to the threads and the seating surfaces of bolts.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Tighten all cylinder head bolts to the specified torque in the sequence shown.", "par22");
si[i++] = gsitm("N50201070000BB00ENG.html", "Cylinder head bolts", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", ": 39.2 Nm (4.0 kg-m, 29 ft-lb)", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Tighten cylinder head bolts to the specified angle in the sequence shown.", "par23");
si[i++] = gsitm("N50201070000BB00ENG.html", "Check and confirm the tightening angle by using angle wrench [KV10112100 (BT-8653-A)] (A). Do not judge angle by visual inspection.", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Step 1", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", ": Tighten 75° - 80°", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Step 2", "ptxt");
si[i++] = gsitm("N50201070000BB00ENG.html", "Installation of the remaining components is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5020102X0001R00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove spark plug with spark plug wrench (commercial service tool).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve lifter.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Identify installation positions, and store them without mixing them up.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve collet.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Compress valve spring with valve spring compressor [SST: KV10116200] (A), adapter [SST: KV10109220] (B) and attachment [SST: KV10115900] (C).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Never damage valve lifter holes.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Fit the attachment [SST: KV10115900] (A) in the center of valve spring retainer to press it.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Valve spring retainer", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve spring retainer and valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Never remove valve spring seat from valve spring.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Push valve stem to combustion chamber side, and remove valve.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Inspect valve guide clearance. Refer to", "par1");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve oil seal with a valve oil seal puller [SST: KV10107902] (A).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve seat, if valve seat must be replaced.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Bore out old seat until it collapses. Boring should not continue beyond the bottom face of the seat recess in cylinder head. Set the machine depth stop to ensure this. Refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Prevent to scratch cylinder head by excessive boring.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove valve guide, if valve guide must be replaced.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "To remove valve guide, heat cylinder head to 110 to 130°C (230 to 266°F) by soaking in heated oil .", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Drive out valve guide with a press hammer and suitable tool (A).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Cylinder head contains heat, when working, wear protective equipment to avoid getting burned.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove spark plug tubes (if necessary) using suitable tool.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Do not damage cylinder head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Do not remove spark plug tube if not necessary. Once removed, the spark plug tube cannot be reused because of deformation during removal.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve guide if removed.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Replace with oversize [0.2 mm (0.008 in)] valve guide.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Ream cylinder head valve guide hole with a valve guide reamer (commercial service tool) (A).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "For service parts", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Oversize [0.2 mm (0.008 in)]", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Heat cylinder head to 110 to 130°C (230 to 266°F) by soaking in heated oil .", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Cylinder head contains heat. When working, wear protective equipment to avoid getting burned.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Press valve guide  from camshaft side to dimensions as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ":Cylinder head", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Projection \"H\"", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Apply reamer finish to valve guide with a valve guide reamer (commercial service tool) (A).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve seat if removed.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Ream cylinder head  recess diameter for service valve seat.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Valve seat", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Oversize [0.5 mm (0.020 in)]", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Be sure to ream in circles concentric to the valve guide center.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "This will enable valve seat to fit correctly.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Provide valve seats cooled well with dry ice. Press-fit valve seat into cylinder head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Avoid directly to touching cold valve seats.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Using valve seat cutter set (commercial service tool) (A) or valve seat grinder, finish valve seat to the specified dimensions. For dimensions, refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "When using valve seat cutter, firmly grip the cutter handle with both hands. Then, press on the contacting surface all around the circumference to cut in a single drive. Improper pressure on with the cutter or cutting many different times may result in stage valve seat.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Using compound, grind to adjust valve fitting.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Check again for normal contact. Refer to .", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Apply new engine oil to new valve oil seal joint surface and seal lip.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve oil seal.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install with a valve oil seal drift [SST: KV10115600] (A) to match dimension in the figure.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Dimension \"H\" is height that measured before installing valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Height \"H\"", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ":", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install larger diameter to intake side.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install smaller pitch (valve spring seat side) to cylinder head side .", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Valve spring seat", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Confirm identification color  of valve spring.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Intake", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", ": Purple", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Exhaust", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve spring retainer.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve collet.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "When working, be careful not to damage valve lifter holes.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Tap valve stem edge lightly with a plastic hammer after installation to check its installed condition.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "The center of the suitable tool (A) and valve spring retainer  must be aligned.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install valve lifter.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install it in the original position.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install spark plug tube if removed.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Press-fit it into cylinder head with the following procedure:", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Remove old thread locking sealant from cylinder head side installation hole.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Apply thread locking sealant all round on spark plug tube within approximately 12 mm (0.47 in) (A) width from edge of spark plug tube on the press-fit side.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Use Genuine Thread Locking Sealant or equivalent.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Using a drift, press-fit spark plug tube so that height is as same as \"H\" shown in figure.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Standard press-fit height \"H\":", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "41.2 - 42.2 mm (1.622 - 1.661 in)", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "When press-fitting, be careful not to deform spark plug tube.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "After press-fitting, wipe off any protruding thread locking sealant on top surface of cylinder head.", "ptxt");
si[i++] = gsitm("N5020102X0001R00ENG.html", "Install spark plug with spark plug wrench (commercial service tool).", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Inspection", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Cylinder Head Bolts Outer Diameter", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Replace the cylinder heads bolts with new ones if the size difference between (A) and (B) exceeds the limit.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Limit [(A) – (B)]", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": 0.23 mm (0.0091 in)", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "(C)", "par21");
si[i++] = gsitm("N50201048000AS00ENG.html", ": 55 mm (2.17 in)", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "(D)", "par19");
si[i++] = gsitm("N50201048000AS00ENG.html", ": 12 mm (0.47 in)", "par20");
si[i++] = gsitm("N50201048000AS00ENG.html", "If reduction of outer diameter appears in a position other than (B), use it as (B) point.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Cylinder Head Distortion", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "When performing this inspection, cylinder block distortion should also be checked. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Wipe off engine oil and remove water scale deposits, old gasket, old sealer, and carbon using a suitable tool.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Use care not to allow gasket debris to enter passages for engine oil or engine coolant.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "At each of several locations on bottom surface of cylinder head, measure the distortion in six directions.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "A", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": Straightedge", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "B", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": Feeler gauge", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": Refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If it exceeds the limit, replace cylinder head.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "VALVE DIMENSIONS", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Check dimensions of each valve. For dimensions, refer to Cylinder Head.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If dimensions are out of the standard, replace valve.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "VALVE GUIDE CLEARANCE", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Valve Stem Diameter", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Measure the diameter of valve stem with a micrometer (A).", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Valve Guide Inner Diameter", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Measure the inner diameter of valve guide with a bore gauge.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Valve Guide Clearance", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "(Valve guide clearance) = (Valve guide inner diameter) – (Valve stem diameter).", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Standard and Limit", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If it exceeds the limit, replace valve guide and/or valve. When valve guide must be replaced. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "VALVE SEAT CONTACT", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "After confirming that the dimensions of valve guides and valves are within specifications, perform this procedure.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Apply prussian blue (or white lead) onto contacting surface of valve seat to check the condition of the valve contact on the surface.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Check if the contact area band is continuous all around the circumference.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": OK", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": NG", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If not, grind to adjust valve fitting and check again. If the contacting surface still has NG conditions even after the re-check, replace valve seat. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "VALVE SPRING SQUARENESS", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Set try square (A) along the side of valve spring and rotate the spring. Measure the maximum clearance  between the top of valve spring and try square.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": Contact", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "C", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": V-block", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Never remove valve spring seat from valve spring.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If it exceeds the limit, replace valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "VALVE SPRING DIMENSIONS AND VALVE SPRING PRESSURE LOAD", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Do not remove the valve spring seat.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Check valve spring pressure with valve spring seat installed at the specified spring height.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": Valve spring tester", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Before measuring valve spring pressure, compress each spring to specified solid height for intake and exhaust valve springs.", "par10");
si[i++] = gsitm("N50201048000AS00ENG.html", "Valve spring", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", ": 24.76 mm (0.9748 in)", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If the installation load or load with valve open is out of the standard, replace valve spring (with valve spring seat).", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "Inspection for Leaks", "title");
si[i++] = gsitm("N50201048000AS00ENG.html", "The following are procedures for checking fluids leak, lubricates leak and exhaust gases leak.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Before starting engine, check oil/fluid levels including engine coolant and engine oil. If less than required quantity, fill to the specified level.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Use procedure below to check for fuel leakage.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Turn ignition switch “ON” (with engine stopped). With fuel pressure applied to fuel piping, check for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Start engine. With engine speed increased, check again for fuel leakage at connection points.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Run engine to check for unusual noise and vibration.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "If hydraulic pressure inside timing chain tensioner drops after removal/installation, slack in guide may generate a pounding noise during and just after the engine start. However, this does not indicate an unusualness. Noise will stop after hydraulic pressure rises.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Warm up engine thoroughly to check there is no leakage of fuel, exhaust gases, or any oil/fluids including engine oil and engine coolant.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "Bleed air from lines and hoses of applicable lines, such as in cooling system.", "ptxt");
si[i++] = gsitm("N50201048000AS00ENG.html", "After cooling down engine, again check oil/fluid levels including engine oil and engine coolant. Refill to the specified level, if necessary.", "ptxt");
