si[i++] = gsitm("N5020102X0001U00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5020102X0001U00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Mount the engine on a suitable engine stand. Refer to Setting.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Drain any remaining engine oil and engine coolant if necessary.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove drain plugs from cylinder block.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove cylinder head. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove oil pan (upper). Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove the thermostat housing. Refer to Removal and Installation.", "par2");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove knock sensors.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Carefully handle knock sensor avoiding shocks.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove crankshaft position sensor.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Avoid impacts such as dropping.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not disassemble.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Keep crankshaft position sensor away from metal particles.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not place crankshaft position sensor in a location where it is exposed to magnetism.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove piston and connecting rod assembly with the following procedure:", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Before removing piston and connecting rod assembly, check the connecting rod side clearance. Refer to .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Position crankshaft pin corresponding to connecting rod to be removed onto the bottom dead center.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove connecting rod cap. Number connecting rod caps so they can be assembled in the same position and direction.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Using a suitable tool, push piston and connecting rod assembly out to cylinder head side.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not damage matching surface with connecting rod cap.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not damage cylinder wall and crankshaft pin when removing piston and connecting rod assembly.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Number the pistons and rods so they can be installed in the same position.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove connecting rod bearings.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing them note the installation position. Keep them in the correct order.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove piston rings from piston.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Before removing piston rings check the piston ring side clearance. Refer to .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove piston rings using suitable tool (A).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing piston rings, do not damage the piston.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not damage piston rings by expanding them excessively.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove piston from connecting rod using the following procedure:", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove snap rings using snap ring pliers (A).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Heat piston to 60°C to 70°C (140°F to 158°F) with a suitable tool (A).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Push out piston pin using a suitable tool.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove ladder assembly using the following procedure:", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Measure crankshaft end play before loosening ladder assembly bolts. Refer to .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Loosen and remove ladder assembly bolts in reverse of the sequence shown.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove the ladder assembly using seal cutter [KV10111100 (J-37228)] (A).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not damage the mating surfaces.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "In areas where the cutter is difficult to use, use a plastic hammer to lightly tap  the cutter where the liquid gasket is applied. Use a plastic hammer to slide  the cutter by tapping on the side.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove the ladder assembly while tapping lightly with a plastic hammer.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove crankshaft .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not damage or deform signal plate  mounted on crankshaft.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When setting crankshaft on a flat floor surface, use a block of wood to avoid contact between signal plate and floor surface.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not remove signal plate unless it is necessary.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing or installing signal plate, use socket (size T30).", "par4");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove main bearing (upper and lower) and thrust bearings from cylinder block and ladder assembly.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing bearings note the installation position. Keep them in the correct order.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing the rear oil seal without removing the cylinder block, use a suitable tool to pull it out between the crankshaft and block.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove oil jets  from cylinder block (if necessary).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "When removing oil jet assemblies note the installation position. Keep them in the correct order.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Inspect dowel pins, welch plugs and threaded plugs and remove if necessary.", "par3");
si[i++] = gsitm("N5020102X0001U00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Thoroughly clean engine coolant and oil passages in cylinder block, as well as inside of crankcase and cylinder bores, with compressed air.", "par5");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Be sure to wear protective goggles for protection from flying substances.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install drain plug to cylinder block as shown.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Apply liquid gasket to the threads of drain plug .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Water drain plug", "par7");
si[i++] = gsitm("N5020102X0001U00ENG.html", ": 9.8 N·m (1.0 kg-m, 87 in-lb)", "par6");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Use Liquid Gasket or equivalent.", "par40");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Permatex Ultra Grey 82194", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "ThreeBond 1207, 1215, 1216, 1217F, 1217G and 1217H", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Nissan RTV Part No. 999MP-A7007", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install oil jets .", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install main bearings and thrust bearings using following procedure:", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Remove dust, dirt, and engine oil on the bearing mating surfaces of cylinder block and ladder assembly.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install thrust bearings  to both sides of the No. 3 journal  housing on cylinder block.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install thrust bearings with the oil groove  facing crankshaft arm (outside).", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Install the main bearings paying attention to the direction.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Before installing bearing, lubricate bearing surface (inside) with clean engine oil.", "par8");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Do not apply engine oil to back surface of main bearings.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Check that the oil hole in cylinder block and the oil hole  in main bearing  are aligned. The main bearing without an oil hole goes in ladder assembly.", "ptxt");
