si[i++] = gsitm("N5020102X0001U00ENG.html", "Using a heat gun (A), heat piston until piston pin can be pushed in by hand without excess force [approximately 60°C to 70°C (140°F to 158°F)]. From the front to the rear, insert piston pin into piston and connecting rod.", "ptxt");
si[i++] = gsitm("N5020102X0001U00ENG.html", "Set so that the front mark  on the piston head, the oil splash  and the cylinder number  on connecting rod are positioned as shown.", "ptxt");
