si[i++] = gsitm("N50201048000AT00ENG.html", "CYLINDER BLOCK TOP SURFACE DISTORTION", "title");
si[i++] = gsitm("N50201048000AT00ENG.html", "Remove gasket on the cylinder block surface and also remove engine oil, scale, carbon and other contamination using suitable tool.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Do not allow gasket flakes to enter engine oil or engine coolant passages.", "ptxt");
