si[i++] = gsitm("N50201048000AT00ENG.html", "(Bearing oil clearance) = (Connecting rod bearing inner diameter) - (Crankshaft pin journal diameter)", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "If measured value exceeds limit select proper connecting rod bearing. Use connecting rod big end diameter and crankshaft pin journal diameter to obtain specified bearing oil clearance.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Method by Using Plastigage", "title");
si[i++] = gsitm("N50201048000AT00ENG.html", "Remove engine oil and dust on crankshaft pin and the surfaces of each bearing completely.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Cut plastigage slightly shorter than bearing width and place it in crankshaft axial direction avoiding oil holes.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Install connecting rod bearings to connecting rod and cap and tighten connecting rod bolts. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Do not rotate crankshaft.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Remove connecting rod cap and bearing and using the scale (A) on the plastigage bag measure the plastigage width.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "The procedure when the measured value exceeds the limit is same as that described in the “Method by Calculation”.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "MAIN BEARING OIL CLEARANCE", "title");
si[i++] = gsitm("N50201048000AT00ENG.html", "Install main bearings  to cylinder block  and ladder assembly  and tighten ladder assembly bolts. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Measure the inner diameter (A) of main bearing with bore gauge.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "(Bearing oil clearance) = (Main bearing inner diameter) - (Crankshaft main journal diameter)", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "If measured value exceeds limit select proper main bearing. Use main bearing inner diameter and crankshaft main journal diameter to obtain specified bearing oil clearance. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Remove engine oil and dust on crankshaft main journal and surfaces of each bearing completely.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Install main bearings on cylinder block and ladder assembly and tighten ladder assembly bolts. Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "Remove ladder assembly and bearings and using the scale (A) on the plastigage bag measure the plastigage width.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "The procedure when measured value exceeds the limit is same as that described in “Method by Calculation”.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "MAIN BEARING CRUSH HEIGHT", "title");
si[i++] = gsitm("N50201048000AT00ENG.html", "When ladder assembly is removed after being tightened to specified torque with main bearings  installed, tip end of bearing must protrude (A). Refer to .", "ptxt");
