si[i++] = gsitm("N50201048000AT00ENG.html", "Standard: There must be crush height.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "If standard is not met, replace main bearings.", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "CONNECTING ROD BEARING CRUSH HEIGHT", "title");
si[i++] = gsitm("N50201048000AT00ENG.html", "When connecting rod bearing cap is removed after being tightened to specified torque with connecting rod bearings  installed, tip end of bearing must protrude (A). Refer to .", "ptxt");
si[i++] = gsitm("N50201048000AT00ENG.html", "If standard is not met, replace connecting rod bearings.", "ptxt");
