si[i++] = gsitm("N5020102M000A100ENG.html", "*Between piston to connecting rod", "ptxt");
si[i++] = gsitm("N5020102M000A100ENG.html", "—", "ptxt");
si[i++] = gsitm("N5020102M000A100ENG.html", "*For the service parts, the grade for fitting cannot be selected between a piston pin and a connecting rod. (Only 0 grade is available.) The information at the shipment from the plant is described as a reference.", "ptxt");
si[i++] = gsitm("N5020102M000A100ENG.html", "The identification grade stamped on each part is the grade for the dimension measured in new condition. This grade cannot apply to reused parts.", "ptxt");
si[i++] = gsitm("N5020102M000A100ENG.html", "For reused or repaired parts, measure the dimension accurately. Determine the grade by comparing the measurement with the values of each selection table.", "ptxt");
si[i++] = gsitm("N5020102M000A100ENG.html", "For details of the measurement method of each part, the reuse standards, and the selection method of the selective fitting parts, follow the applicable procedures.", "ptxt");
