si[i++] = gsitm("N5020201K0000J00ENG.html", "Be careful not to get burned, as engine oil may be hot.", "ptxt");
si[i++] = gsitm("N5020201K0000J00ENG.html", "Prolonged and repeated contact with used engine oil may cause skin cancer. Try to avoid direct skin contact with used engine oil. If skin contact is made, wash thoroughly with soap or hand cleaner as soon as possible.", "ptxt");
