si[i++] = gsitm("N5020203S0000R00ENG.html", "Genuine \"MITSUBISHI MOTORS GENUINE MOTOR OIL SN or SP\" is recommended &lt;Vehicles for Australia and New Zealand>.", "ptxt");
si[i++] = gsitm("N5020203S0000R00ENG.html", "If the above motor oil (or engine oil) is not available, use the equivalent of \"MITSUBISHI MOTORS GENUINE MOTOR OIL\" that matches the following grade and viscosity.", "ptxt");
