si[i++] = gsitm("N5020203Y0001B00ENG.html", "Perform this step when removing water hoses.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Remove the bracket .", "par2");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Remove drive belt. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Remove the air condition compressor mounting bolts. Refer to .", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Place the air condition compressor somewhere where it will not become a disturbance to the process.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Disconnect all water hoses from oil cooler.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "When removing oil cooler only, pinching water hoses near oil cooler to prevent engine coolant from spilling out.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Remaining engine coolant in piping will come out. Use a tray to collect it.", "ptxt");
si[i++] = gsitm("N5020203Y0001B00ENG.html", "Perform this step when the engine is cold.", "ptxt");
