si[i++] = gsitm("N5020202I0002C00ENG.html", "Check the engine oil level and the engine coolant level and add engine oil and engine coolant. Refer to  and .", "ptxt");
si[i++] = gsitm("N5020202I0002C00ENG.html", "Start the engine, and check that there is no leakage of engine oil or engine coolant.", "ptxt");
si[i++] = gsitm("N5020202I0002C00ENG.html", "Stop the engine and wait for 10 minutes.", "ptxt");
si[i++] = gsitm("N5020202I0002C00ENG.html", "Check the engine oil level and the engine coolant level again. Refer to  and .", "ptxt");
si[i++] = gsitm("N502020250001800ENG.html", "Exploded View", "title");
si[i++] = gsitm("N502020250001800ENG.html", "Oil pump is integrated in the balancer unit. Refer to .", "ptxt");
si[i++] = gsitm("N5020204V0000D00ENG.html", "OIL PUMP: Removal & Installation", "title");
si[i++] = gsitm("N5020204V0000D00ENG.html", "The oil pump is an integral part of the balancer unit.", "par1");
si[i++] = gsitm("N5020204V0000D00ENG.html", "If replacement of the oil pump is necessary, replace the balancer unit. Refer to Removal and Installation .", "par2");
