si[i++] = gsitm("N5020302A0005100ENG.html", "Inspection", "title");
si[i++] = gsitm("N5020302A0005100ENG.html", "LEVEL", "title");
si[i++] = gsitm("N5020302A0005100ENG.html", "Check that the reservoir tank engine coolant level is within the “MIN” to “MAX” when the engine is cool.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", ": MAX", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", ": MIN", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Adjust the engine coolant level if necessary.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Refill MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "To avoid the blow out when the coolant is hot, never fill the coolant more than MAX level.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "LEAKAGE", "title");
si[i++] = gsitm("N5020302A0005100ENG.html", "To check for leakage, apply pressure to the cooling system with the radiator cap tester (commercial service tool) (A) and the radiator cap tester adapter [SST: EG17651130] (B).", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Testing pressure: Refer to .", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Never remove reservoir tank cap when engine is hot. Serious burns may occur from high-pressure engine coolant escaping from engine cooling system.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Higher test pressure than specified may cause radiator damage.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "Use radiator cap tester adapter [SST: EG17651130] (B) for connecting radiator cap tester (commercial service tool) (A) and filler neck to prevent deformation of reservoir tank filler neck.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "In a case that engine coolant decreases, replenish radiator with engine coolant.", "ptxt");
si[i++] = gsitm("N5020302A0005100ENG.html", "If anything is found, repair or replace damaged parts.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Draining", "title");
si[i++] = gsitm("N5020301G0000L00ENG.html", "WHEN DRAIN ENGINE COOLANT USING DRAIN HOSE", "title");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Never remove reservoir tank cap when engine is hot. Serious burns may occur from high-pressure engine coolant escaping from radiator.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Wrap a thick cloth around the reservoir tank cap. Slowly turn it a quarter of a turn to release built-up pressure. Then turn it all the way.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Remove engine under cover and engine under cover front. Refer to .", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Connect drain hose.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Use a genera-purpose hose with the dimensions show in the figure.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", ": φ 8.5  mm (0.335 in)", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", ": 150 mm (5.91 in)", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Open radiator drain cock  at the bottom of radiator, and then remove reservoir tank cap.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Perform this step when engine is cold.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Draining coolant from the radiator, should make sure that the drain plug is pointed downwards.", "par1");
si[i++] = gsitm("N5020301G0000L00ENG.html", "When draining all of engine coolant in the system, open water drain plugs on cylinder block. Refer to .", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Remove reservoir tank if necessary, and drain engine coolant and clean reservoir tank before installing.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Disconnect drain hose.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "WHEN DRAIN ENGINE COOLANT USING TEMPORARY PIPE", "title");
si[i++] = gsitm("N5020301G0000L00ENG.html", "When draining coolant, follow the instructions below and create a temporary pipe to prevent from splashing.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Prepare soft plastic board (e.g. plastic file folder) and roll up the plastic board.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Approx. 295 mm (11.61 in)", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Approx. 210 mm (8.27 in)", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "C", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Approx. 145 mm (5.71 in)", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Check that the length of temporary pipe (A) approx. 145 mm (5.71 in).", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Remove engine under cover front. Refer to .", "par3");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Align the plastic board with the outside diameter of drain guide and fix with tape.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Install temporary pipe (A) to drain guide.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Open radiator drain cock  and reservoir tank cap, and then drain engine coolant.", "ptxt");
si[i++] = gsitm("N5020301G0000L00ENG.html", "Remove temporary pipe.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Refilling", "title");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Do not put additive such as water leak preventive, since it may cause cooling waterway clogging.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Refill MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Install reservoir tank if removed and radiator drain cock.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Be sure to clean drain cock and install with new O-ring.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Radiator drain cock", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "If water drain plugs on cylinder block are removed, close and tighten them. Refer to .", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Check that each hose clamp has been firmly tightened.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Fill radiator to specified level.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Never adhere the engine coolant to electronic equipment (alternator etc.).", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Pour coolant slowly of less than 3 (1-3/4 Imp qt) a minute to allow air in system to escape.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Engine coolant capacity (With reservoir tank at \"MAX\" level)", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "9.4 (8-3/10)", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Refill reservoir tank to “MAX” level line with engine coolant.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", ": MAX", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", ": MIN", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Reservoir tank engine coolant capacity (At \"MAX\" level)", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "0.8 (3/4)", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Install reservoir tank cap.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Warm up engine until opening thermostat. Standard for warming-up time is approximately 10 minutes at 3,000 rpm.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Check thermostat opening condition by touching radiator hose (lower) to see a flow of warm water.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Watch water temperature gauge so as not to overheat engine.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Stop the engine and cool down to less than approximately 50°C (122°F).", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Cool down using fan to reduce the time.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "If necessary, refill radiator up to filler neck with engine coolant.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Repeat steps 3 through 8 two or more times with radiator cap installed until engine coolant level no longer drops.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Check cooling system for leakage with engine running.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Warm up the engine, and check for sound of engine coolant flow while running engine from idle up to 3,000 rpm with heater temperature controller set at several position between “COOL” and “WARM”.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Sound may be noticeable at heater unit.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "Repeat step 11 three times.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "If sound is heard, bleed air from cooling system by repeating step 3 through 8 until reservoir tank level no longer drops.", "ptxt");
si[i++] = gsitm("N5020303E0000L00ENG.html", "To avoid the blow out when the coolant is hot, never fill the coolant more than MAX level.", "ptxt");
si[i++] = gsitm("N5020302A0005200ENG.html", "Inspection", "title");
si[i++] = gsitm("N5020302A0005200ENG.html", "Connect radiator cap tester (commercial service tool) (A) with radiator cap tester adapter [SST: EG17651130] (B) and check injection-valve opening pressure of pressure adjusting valve by applying pressure.", "ptxt");
si[i++] = gsitm("N5020302A0005200ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5020302A0005200ENG.html", ":", "ptxt");
si[i++] = gsitm("N5020302A0005200ENG.html", "When installing reservoir tank cap to radiator cap tester (commercial service tool), apply water or coolant to the seal of cap.", "ptxt");
si[i++] = gsitm("N5020302A0005200ENG.html", "If negative pressure valve has a malfunction or injection-valve opening pressure is outside the reference value, replace reservoir tank cap.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Inspection", "title");
si[i++] = gsitm("N5020302A0005300ENG.html", "Check radiator for mud or clogging. If necessary, clean radiator as follows.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Be careful not to bend or damage radiator fins.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "When radiator is cleaned without removal, remove all surrounding parts such as radiator cooling fan assembly and horns. Then tape harness and harness connectors to prevent water from entering.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Apply water by hose to the back side of the radiator core vertically downward.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Apply water again to all radiator core surfaces once per minute.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Stop washing if any stains no longer flow out from radiator.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Blow air into the back side of radiator core vertically downward.", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Use compressed air lower than 490 kPa (4.9 bar, 5 kg/cm2, 71 psi) and keep distance more than 30 cm (11.81 in).", "ptxt");
si[i++] = gsitm("N5020302A0005300ENG.html", "Blow air again into all the radiator core surfaces once per minute until no water sprays out.", "ptxt");
si[i++] = gsitm("N5020301W0002Q00ENG.html", "Exploded View", "title");
