si[i++] = gsitm("N5020302A0005700ENG.html", "Place a thread  so that it is caught in the valves of thermostat . Immerse fully in a container  filled with water. Heat while stirring.", "ptxt");
si[i++] = gsitm("N5020302A0005700ENG.html", "The valve opening temperature is the temperature at which the valve opens and falls from the thread.", "ptxt");
si[i++] = gsitm("N5020302A0005700ENG.html", "Continue heating. Check the full open valve lift amount.", "ptxt");
si[i++] = gsitm("N5020302A0005700ENG.html", "After checking the maximum valve lift amount, lower the water temperature and check the valve closing temperature.", "ptxt");
si[i++] = gsitm("N5020302A0005700ENG.html", "Standard: Refer to Thermostat.", "ptxt");
si[i++] = gsitm("N5020302A0005700ENG.html", "If out of the standard, replace thermostat.", "ptxt");
