si[i++] = gsitm("N5020303G0002U00ENG.html", "Disconnect EVAP canister purge volume control solenoid valve harness connectors  and remove EVAP canister purge volume control solenoid valve harness clamp .", "par4");
si[i++] = gsitm("N5020303G0002U00ENG.html", "Remove fuel tube  from EVAP canister purge volume control solenoid valve bracket clamp .", "par6");
si[i++] = gsitm("N5020303G0002U00ENG.html", "Remove EVAP canister purge volume control solenoid valve bracket.", "par8");
si[i++] = gsitm("N5020303G0002U00ENG.html", "Remove EVAP hose  from vacuum delay valve assembly .", "par9");
si[i++] = gsitm("N5020303G0002U00ENG.html", "Disconnect engine coolant temperature harness connectors and remove engine coolant temperature harness clamp.", "par11");
