si[i++] = gsitm("N5020303G0002U00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5020303G0002U00ENG.html", "WATER OUTLET", "title");
si[i++] = gsitm("N5020303G0002U00ENG.html", "Install the water outlet and tighten bolts to the specified torque in the sequence shown.", "par20");
