si[i++] = gsitm("N5020303B0000L00ENG.html", "Radiator", "title");
si[i++] = gsitm("N5020303B0000L00ENG.html", "Cap relief pressure", "ptxt");
si[i++] = gsitm("N5020303B0000L00ENG.html", "Standard", "ptxt");
