si[i++] = gsitm("N5020303Y0000L00ENG.html", "Thermostat", "title");
si[i++] = gsitm("N5020303Y0000L00ENG.html", "Standard", "title");
si[i++] = gsitm("N5020303Y0000L00ENG.html", "Valve opening temperature", "ptxt");
si[i++] = gsitm("N5020303Y0000L00ENG.html", "80.5 - 83.5°C (177 - 182°F)", "ptxt");
si[i++] = gsitm("N5020303Y0000L00ENG.html", "Maximum valve lift", "ptxt");
