si[i++] = gsitm("N502040170000M00ENG.html", "Stop light switch", "ptxt");
si[i++] = gsitm("N502040170000M00ENG.html", "Accelerator pedal position sensor", "ptxt");
si[i++] = gsitm("N5022404K0000K00ENG.html", "Accelerator Pedal Position Sensor", "title");
si[i++] = gsitm("N5022404K0000K00ENG.html", "The accelerator pedal position sensor is installed on the upper end of the accelerator pedal assembly. The sensor detects the accelerator position and sends a signal to the ECM.", "ptxt");
si[i++] = gsitm("N5022404K0000K00ENG.html", "Accelerator pedal position sensor has two sensors. These sensors are a kind of potentiometers which transform the accelerator pedal position into output voltage, and emit the voltage signal to the ECM. In addition, these sensors detect the opening and closing speed of the accelerator pedal and feed the voltage signals to the ECM. The ECM judges the current opening angle of the accelerator pedal from these signals and controls the throttle control motor based on these signals.", "ptxt");
si[i++] = gsitm("N5022404K0000K00ENG.html", "Idle position of the accelerator pedal is determined by the ECM receiving the signal from the accelerator pedal position sensor. The ECM uses this signal for the engine operation such as fuel cut.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "Air Fuel Ratio (A/F) Sensor 1", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "ECM judges the state of air fuel ratio with this signal, and precisely controls air fuel ratio to match the stoichiometric ratio. Also, the sensor is equipped with heater for maintaining the activated state.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "A/F Sensor 1", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "The A/F sensor 1 transmits the signal of detected oxygen concentration in the exhaust gas to ECM.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "A/F Sensor 1 Heater", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "The A/F sensor 1 heater activates A/F sensor 1.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "While O2 sensor changes output voltage by ON/OFF (rich/lean) mode within a narrow range of the stoichiometric ratio, the A/F sensor changes output voltage between 0 - 4 V for a wide range of air fuel ratio.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "The ECM performs ON/OFF duty control of the A/F sensor 1 heater corresponding to condition to keep the temperature of A/F sensor 1 element within the specified range.", "ptxt");
si[i++] = gsitm("N5022404L0000J00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5022404L0000J00ENG.html", "The A/F sensor 1 is installed on the exhaust manifold.", "ptxt");
si[i++] = gsitm("N502030120000S00ENG.html", "Cooling Fan", "title");
si[i++] = gsitm("N502030120000S00ENG.html", "COOLING FAN CONTROL MODULE", "title");
si[i++] = gsitm("N502030120000S00ENG.html", "Cooling fan control module receives ON/OFF pulse duty signal from IPDM E/R. Corresponding to this ON/OFF pulse duty signal, cooling fan control module sends cooling fan motor operating voltage to cooling fan motor. The revolution speed of cooling fan motor is controlled by duty cycle of the voltage.", "ptxt");
si[i++] = gsitm("N502030120000S00ENG.html", "COOLING FAN MOTOR", "title");
si[i++] = gsitm("N502030120000S00ENG.html", "Cooling fan motor receives cooling fan motor operating voltage from cooling fan control module. The revolution speed of cooling fan motor is controlled by duty cycle of the voltage.", "ptxt");
si[i++] = gsitm("N502030120000S00ENG.html", "COOLING FAN RELAY", "title");
si[i++] = gsitm("N502030120000S00ENG.html", "Cooling fan relay provides power supply to the cooling fan control module.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "Crankshaft Position Sensor", "title");
si[i++] = gsitm("N5022405R0000J00ENG.html", "The crankshaft position sensor is located on the oil pan facing the gear teeth (cogs) of the signal plate. It detects the fluctuation of the engine revolution.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "The sensor consists of a permanent magnet and MRE IC.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "When the engine is running, the high and low parts of the teeth cause the gap with the sensor to change.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "The changing gap causes the magnetic field near the sensor to change.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "Due to the changing magnetic field, the voltage from the sensor changes.", "ptxt");
si[i++] = gsitm("N5022405R0000J00ENG.html", "The ECM receives the voltage signal and detects the fluctuation of the engine revolution.", "ptxt");
si[i++] = gsitm("N502040210000K00ENG.html", "ECM", "title");
si[i++] = gsitm("N502040210000K00ENG.html", "The ECM consists of a microcomputer and connectors for signal input and output and for power supply. The ECM controls the engine.", "ptxt");
si[i++] = gsitm("N502040AZ0000G00ENG.html", "EGR Volume Control Valve", "title");
si[i++] = gsitm("N502040AZ0000G00ENG.html", "EGR VOLUME CONTROL VALVE", "title");
si[i++] = gsitm("N502040AZ0000G00ENG.html", "The EGR volume control valve used a DC motor and controls the flow rate of EGR from downstream of exhaust manifold catalyst. ECM controls the DC motor to make the valve opening angle in response to driving conditions.", "ptxt");
si[i++] = gsitm("N502040AZ0000G00ENG.html", "EGR CONTROL POSITION SENSOR", "title");
si[i++] = gsitm("N502040AZ0000G00ENG.html", "The EGR control valve control position sensor is built in the EGR control valve and uses a permanent magnet and a semiconductor device. This sensor measures valve shaft movements and transmits a voltage signal to ECM. Based on this signal, ECM judges the valve opening angle as of then and controls the motor to achieve opening angle appropriate to the driving conditions.", "ptxt");
si[i++] = gsitm("N502040B00000G00ENG.html", "Electric Intake Valve Timing Control Actuator", "title");
si[i++] = gsitm("N502040B00000G00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B00000G00ENG.html", "The electric intake valve timing control actuator operates the electric intake valve timing control motor based on the signal from the electric intake valve timing control module, and it advances or retards the intake valve timing according to the conditions. It also transmits the motor position and motor speed to the electric intake valve timing control module based on the electric intake valve timing control position sensor.", "ptxt");
si[i++] = gsitm("N502040B00000G00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B00000G00ENG.html", "It is composed of the electric intake valve timing control motor and electric intake valve timing control actuator (located inside the electric intake valve timing control position sensor).", "ptxt");
si[i++] = gsitm("N502040B00000G00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N502040B00000G00ENG.html", "The electric intake valve timing control motor rotates in the same direction as the intake camshaft, and the difference in rotation controls timing advancement, holding, and retardation.", "ptxt");
si[i++] = gsitm("N502040B00000G00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N502040B00000G00ENG.html", "The electric intake valve timing control actuator (located inside the electric intake valve timing control position sensor) is installed on the engine front side of the intake camshaft.", "ptxt");
si[i++] = gsitm("N502040B00000G00ENG.html", "The electric intake valve timing control motor is installed inside the cam sprocket (INT).", "ptxt");
si[i++] = gsitm("N502040B10000G00ENG.html", "Electric Intake Valve Timing Control Module", "title");
si[i++] = gsitm("N502040B10000G00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B10000G00ENG.html", "The electric intake valve timing control module controls the electric intake valve timing control actuator based on the signals from the ECM and the electric intake valve timing control position sensor. The target intake valve timing angle is also corrected by the signal transmitted from the ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040B10000G00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B10000G00ENG.html", "The electric intake valve timing control module controls the electric intake valve timing control actuator according to the signal from the ECM, and changes the intake valve open/close timing. It also has a diagnosis function and transmits a malfunction detection signal to the ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040B10000G00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N502040B10000G00ENG.html", "The electric intake valve timing control module controls the electric intake valve timing control actuator, and if it detects a malfunction, it transmits a malfunction detection signal to the ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040B10000G00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N502040B10000G00ENG.html", "The electric intake valve timing control module is installed to the engine room left side.", "ptxt");
si[i++] = gsitm("N5022405W0000L00ENG.html", "Electric Throttle Control Actuator", "title");
si[i++] = gsitm("N5022405W0000L00ENG.html", "Electric throttle control actuator consists of throttle body, throttle valve, throttle control motor and throttle position sensor.", "ptxt");
si[i++] = gsitm("N5022405W0000L00ENG.html", "THROTTLE CONTROL MOTOR", "title");
si[i++] = gsitm("N5022405W0000L00ENG.html", "The throttle control motor is operated by the ECM and it opens and closes the throttle valve.", "ptxt");
si[i++] = gsitm("N5022405W0000L00ENG.html", "The current opening angle of the throttle valve is detected by the throttle position sensor and it provides feedback to the ECM to control the throttle control motor to make the throttle valve opening angle properly in response to driving condition.", "ptxt");
si[i++] = gsitm("N5022405W0000L00ENG.html", "THROTTLE POSITION SENSOR", "title");
si[i++] = gsitm("N5022405W0000L00ENG.html", "The throttle position sensor responds to the throttle valve movement.", "ptxt");
si[i++] = gsitm("N5022405W0000L00ENG.html", "The throttle position sensor has two sensors. These sensors are a kind of potentiometers which transform the throttle valve position into output voltage, and emit the voltage signal to the ECM. In addition, these sensors detect the opening and closing speed of the throttle valve and feed the voltage signals to the ECM. The ECM judges the current opening angle of the throttle valve from these signals and the ECM controls the throttle control motor to make the throttle valve opening angle properly in response to driving condition.", "ptxt");
si[i++] = gsitm("N5022405X0000J00ENG.html", "Engine Coolant Temperature Sensor", "title");
si[i++] = gsitm("N5022405X0000J00ENG.html", "The engine coolant temperature sensor is used to detect the engine coolant temperature. The sensor modifies a voltage signal from the ECM. The modified signal returns to the ECM as the engine coolant temperature input. The sensor uses a thermistor which is sensitive to the change in temperature. The electrical resistance of the thermistor decreases as temperature increases.", "ptxt");
si[i++] = gsitm("N5022405X0000J00ENG.html", "&lt;Reference data>", "ptxt");
