si[i++] = gsitm("N502040B20000G00ENG.html", "Engine Oil Pressure Control Solenoid Valve", "title");
si[i++] = gsitm("N502040B20000G00ENG.html", "The engine oil pressure control solenoid valve performs the variable hydraulic control (low oil pressure control and high oil pressure control) according to oil temperature and engine load.", "ptxt");
si[i++] = gsitm("N5022405Y0000J00ENG.html", "Engine Oil Pressure Sensor", "title");
si[i++] = gsitm("N5022405Y0000J00ENG.html", "The engine oil pressure (EOP) sensor is detects engine oil pressure and transmits a voltage signal to the ECM.", "ptxt");
si[i++] = gsitm("N5022405Z0000J00ENG.html", "Engine Oil Temperature Sensor", "title");
si[i++] = gsitm("N5022405Z0000J00ENG.html", "The engine oil temperature sensor is used to detect the engine oil temperature. The sensor modifies a voltage signal from the ECM. The modified signal returns to the ECM as the engine oil temperature input. The sensor uses a thermistor which is sensitive to the change in temperature. The electrical resistance of the thermistor decreases as temperature increases.", "ptxt");
si[i++] = gsitm("N5022405Z0000J00ENG.html", "&lt;Reference data>", "ptxt");
si[i++] = gsitm("N5022405Z0000J00ENG.html", "Engine oil temperature", "ptxt");
