si[i++] = gsitm("N502040B30000K00ENG.html", "EVAP Canister", "title");
si[i++] = gsitm("N502040B30000K00ENG.html", "EVAP canister stores the generated fuel vapors in the sealed fuel tank to activated charcoals of EVAP canister when the engine is not operating or when refueling to the fuel tank.", "ptxt");
si[i++] = gsitm("N502240600000J00ENG.html", "EVAP Canister Purge Volume Control Solenoid Valve", "title");
si[i++] = gsitm("N502240600000J00ENG.html", "The EVAP canister purge volume control solenoid valve uses a ON/OFF duty to control the flow rate of fuel vapor from the EVAP canister. The EVAP canister purge volume control solenoid valve is moved by ON/OFF pulses from the ECM. The longer the ON pulse, the greater the amount of fuel vapor that will flow through the valve.", "ptxt");
si[i++] = gsitm("N502240620000J00ENG.html", "Exhaust Valve Timing Control Solenoid Valve", "title");
si[i++] = gsitm("N502240620000J00ENG.html", "Exhaust valve timing control solenoid valve is activated by ON/OFF pulse duty (ratio) signals from the ECM.", "ptxt");
si[i++] = gsitm("N502240620000J00ENG.html", "The exhaust valve timing control solenoid valve changes the oil amount and direction of flow through exhaust valve timing control unit or stops oil flow.", "ptxt");
si[i++] = gsitm("N502240620000J00ENG.html", "The longer pulse width retards valve angle.", "ptxt");
si[i++] = gsitm("N502240620000J00ENG.html", "The shorter pulse width advances valve angle.", "ptxt");
si[i++] = gsitm("N502240620000J00ENG.html", "When ON and OFF pulse widths become equal, the solenoid valve stops oil pressure flow to fix the exhaust valve angle at the control position.", "ptxt");
si[i++] = gsitm("N502040B40000G00ENG.html", "Exhaust Camshaft Position Sensor", "title");
si[i++] = gsitm("N502040B40000G00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B40000G00ENG.html", "The ECM identifies the cylinders from the combination of the exhaust camshaft position sensor signal and the crankshaft position sensor signal input into it.", "ptxt");
si[i++] = gsitm("N502040B40000G00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502040B40000G00ENG.html", "The ECM inputs the voltage change caused by the change in magnetic field generated close to the exhaust camshaft position sensor, and the timing of the change, as signal voltage.", "ptxt");
si[i++] = gsitm("N502040B40000G00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N502040B40000G00ENG.html", "The exhaust camshaft position sensor consists of a permanent magnet and MRE IC. When engine is running, the high and low parts of the teeth cause the gap with the sensor to change. The changing gap causes the magnetic field near the sensor to change. Due to the changing magnetic field, the voltage from the sensor changes.", "ptxt");
si[i++] = gsitm("N502040B40000G00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N502040B40000G00ENG.html", "The exhaust camshaft position sensor is installed on the exhaust camshaft right side (engine rear side) of the camshaft bracket.", "ptxt");
si[i++] = gsitm("N502040B50000G00ENG.html", "Exhaust Valve Timing Intermediate Lock Control Solenoid Valve", "title");
si[i++] = gsitm("N502040B50000G00ENG.html", "Exhaust valve timing intermediate lock control solenoid valve is activated by ON/OFF signals from the ECM.", "ptxt");
si[i++] = gsitm("N502040B50000G00ENG.html", "The exhaust valve timing intermediate lock control solenoid valve opens/closes the path of oil pressure acting on the lock key in the camshaft sprocket (EXH).", "ptxt");
si[i++] = gsitm("N502040B50000G00ENG.html", "When the solenoid valve becomes ON, oil pressure to the lock key is drained to perform intermediate lock.", "ptxt");
si[i++] = gsitm("N502040B50000G00ENG.html", "When the solenoid valve becomes OFF, oil pressure is acted on the lock key to release the intermediate lock.", "ptxt");
si[i++] = gsitm("N502240630000J00ENG.html", "Fuel Injector", "title");
si[i++] = gsitm("N502240630000J00ENG.html", "For the fuel injector, a high pressure fuel injector is used and this enables a high pressure fuel injection at a high voltage within a short time. The ECM is equipped with an injector driver unit and actuates the fuel injector at a high voltage (approximately 65 V at the maximum).", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Fuel Level Sensor Unit and Fuel Pump", "title");
si[i++] = gsitm("N502040B60000G00ENG.html", "FUEL PUMP", "title");
si[i++] = gsitm("N502040B60000G00ENG.html", "The low pressure fuel pump build into the fuel tank.", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "The ECM turns the fuel pump relay ON/OFF and controls the low-pressure fuel pump.", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "The low pressure fuel pump is integrated with a fuel pressure regulator and a fuel filter.", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "When the ignition switch is turned ON, the fuel pump operates for 1 second to start the engine. During cranking and while the engine is running, the fuel pump relay turns ON to operate the low pressure fuel pump, and gasoline inside the fuel tank is sent to the fuel line after passing through the fuel filter. When the fuel pressure in the fuel line reaches or exceeds the specified pressure, the low pressure fuel regulator opens, and the gasoline in the fuel line returns to the fuel tank, lowering the fuel pressure.", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Vehicle condition", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Fuel pump operation", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Ignition switch is turned to ON", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Operates for 1 seconds", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Engine cranking and running", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Operates", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "When engine is stopped", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Stops in 1.5 seconds", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Except as shown above", "ptxt");
si[i++] = gsitm("N502040B60000G00ENG.html", "Stops", "ptxt");
si[i++] = gsitm("N502240650000J00ENG.html", "Fuel Rail Pressure Sensor", "title");
si[i++] = gsitm("N502240650000J00ENG.html", "The fuel rail pressure (FRP) sensor is placed to the fuel rail and", "ptxt");
si[i++] = gsitm("N502240650000J00ENG.html", "measures fuel pressure in the fuel rail. The sensor transmits voltage signal to the ECM. As the pressure increases, the voltage rises. The ECM controls the fuel pressure in the fuel rail by operating high pressure fuel pump. The ECM uses the signal from fuel rail pressure sensor as a feedback signal.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Heated Oxygen Sensor 2", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "Heated oxygen sensor 2 detects the oxygen concentration in the exhaust gases, converts it to a voltage signal, and transmits the signal to the ECM. Heated oxygen sensor 2 contains a heater for maintaining its activation.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "Under normal conditions, heated oxygen sensor 2 is not used for engine control. When A/F sensor 1 is malfunctioning, the signal from heated oxygen sensor 2 is used to control the A/F ratio to the stoichiometric ratio.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Heated Oxygen Sensor 2 Heater", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "The heated oxygen sensor 2 heater activates heated oxygen sensor 2.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "Heated oxygen sensor 2 is composed of a zirconia element in a test tube shape, and is exposed to the atmosphere on the inside and the exhaust gases on the outside. When there is a difference in the oxygen concentration between the inside and outside, electromotive force is generated. When the A/F ratio is leaner than the stoichiometric ratio, the voltage is approximately 0 V. When it is richer, the voltage is approximately 1 V.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "The ECM performs ON/OFF control of the heated oxygen sensor 2 heater corresponding to the engine speed, amount of intake air and engine coolant temperature.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Engine speed", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Heated oxygen sensor 2 heater", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Above 3,600 rpm", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "OFF", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Below 3,600 rpm after the following conditions are met.", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Engine: After warming up", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "Keeping the engine speed between 3,500 and 4,000 rpm for 1 minute and at idle for 1 minute under no load", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N502240670000J00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N502240670000J00ENG.html", "The heated oxygen sensor 2 is installed on the downstream side of three way catalyst (manifold).", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "High Pressure Fuel Pump", "title");
si[i++] = gsitm("N502240680000J00ENG.html", "Balanced flow volume control type single cylinder high pressure fuel pump, which approximately equalize the amount of injection and pump output, is adopted.", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "The high pressure fuel pump is activated by the exhaust camshaft. ECM controls the high pressure fuel pump control solenoid valve built into the high pressure fuel pump and adjusts the amount of discharge by changing the suction timing of the low pressure fuel.", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "Inflow process: Cam driven lowering plunger let the fuel from low pressure fuel pump induced into high pressure fuel pump.", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "Spill process: Although the cam driven plunger start moving upward, inflow check valve still at open position due to the control solenoid valve, so the fuel is not pressurized and spilled out to low pressure fuel pump side. By changing the amount of this spill out volume changes the amount of injection.", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "Outflow process: When the control solenoid valve turns ON, the inflow check valve is closed, fuel is pressurized and when the pressure exceeds certain point discharge check valve is pushed open to discharge fuel into fuel rail.", "ptxt");
si[i++] = gsitm("N502240680000J00ENG.html", "Operating Description", "title");
si[i++] = gsitm("N502240680000J00ENG.html", "Operating Chart", "title");
si[i++] = gsitm("N5022406B0000J00ENG.html", "Ignition Coil With Power Transistor", "title");
si[i++] = gsitm("N5022406B0000J00ENG.html", "The ignition signal from the ECM is sent to and amplified by the power transistor. The power transistor turns ON and OFF the ignition coil primary circuit. This ON/OFF operation induces the proper high voltage in the coil secondary circuit.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "Intake Camshaft Position Sensor", "title");
si[i++] = gsitm("N502040B70000G00ENG.html", "Intake camshaft position sensor detects the protrusion of the signal plate installed to the intake camshaft rear end.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "This sensor signal is used for sensing a position of the intake camshaft.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "The sensor consists of a permanent magnet and MRE IC.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "When engine is running, the high and low parts of the teeth cause the gap with the sensor to change.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "The changing gap causes the magnetic field near the sensor to change.", "ptxt");
si[i++] = gsitm("N502040B70000G00ENG.html", "Due to the changing magnetic field, the voltage from the sensor changes.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "Intake Manifold Runner Control Valve", "title");
si[i++] = gsitm("N502040B80000G00ENG.html", "Intake manifold runner control valve  is integrated to intake manifold.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "Intake manifold runner control valve is mounted each port of the intake manifold and opened/closed by the intake manifold runner control valve motor.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "ECM controls the intake manifold runner control valve motor, according to signals of engine speed, water temperature, etc. and stabilizes combustion by generating a strong tumble flow.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "INTAKE MANIFOLD RUNNER CONTROL VALVE MOTOR", "title");
si[i++] = gsitm("N502040B80000G00ENG.html", "Intake manifold runner control valve motor  is connected to the rear end of the valve shaft.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "The motor opens or closes the valve by the output signal of the ECM.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "INTAKE MANIFOLD RUNNER CONTROL VALVE POSITION SENSOR", "title");
si[i++] = gsitm("N502040B80000G00ENG.html", "Intake manifold runner control valve position sensor  is connected to the front end of the valve shaft.", "ptxt");
si[i++] = gsitm("N502040B80000G00ENG.html", "The sensor consists of variable resister. It senses the valve shaft movement and feeds the voltage signals to the ECM.", "ptxt");
si[i++] = gsitm("N502040B90000G00ENG.html", "Intake Manifold Tuning Valve", "title");
si[i++] = gsitm("N502040B90000G00ENG.html", "Intake manifold tuning valve  is integrated to intake manifold.", "ptxt");
si[i++] = gsitm("N502040B90000G00ENG.html", "Intake manifold tuning valve consists of valve and motor.", "ptxt");
si[i++] = gsitm("N502040B90000G00ENG.html", "Intake manifold tuning valve is used to control the suction passage of the intake manifold tuning system.", "ptxt");
si[i++] = gsitm("N502040B90000G00ENG.html", "INTAKE MANIFOLD TUNING VALVE MOTOR", "title");
si[i++] = gsitm("N502040B90000G00ENG.html", "Intake manifold tuning valve motor is connected to the rear end of the valve shaft.", "ptxt");
si[i++] = gsitm("N502040B90000G00ENG.html", "The motor is operated by the ECM and it opens and closes the intake manifold tuning valve.", "ptxt");
si[i++] = gsitm("N5022406E0000J00ENG.html", "Knock Sensor", "title");
si[i++] = gsitm("N5022406E0000J00ENG.html", "The knock sensor is attached to the cylinder block. It senses engine knocking using a piezoelectric element. A knocking vibration from the cylinder block is sensed as vibrational pressure. This pressure is converted into a voltage signal and sent to the ECM.", "ptxt");
si[i++] = gsitm("N5022406H0000J00ENG.html", "Manifold Absolute Pressure Sensor", "title");
si[i++] = gsitm("N5022406H0000J00ENG.html", "The manifold absolute pressure (MAP) sensor is placed at intake manifold collector. It detects intake manifold pressure and sends the voltage signal to the ECM.", "ptxt");
si[i++] = gsitm("N5022406H0000J00ENG.html", "The sensor uses a silicon diaphragm which is sensitive to the change in pressure. As the pressure increases, the voltage rises.", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "Mass Air Flow Sensor (With Intake Air Temperature Sensor)", "title");
si[i++] = gsitm("N5022406I0000J00ENG.html", "MASS AIR FLOW SENSOR", "title");
si[i++] = gsitm("N5022406I0000J00ENG.html", "The mass air flow sensor is placed in the stream of intake air. It measures the intake flow rate by measuring a part of the entire intake flow. The MAF sensor controls the temperature of the heater in sensing element to a certain amount. The temperature distribution around the heater changes according to the increase in intake air volume. The change is detected by a thermistor and the air volume data is sent to ECM by the MAF sensor.", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "INTAKE AIR TEMPERATURE SENSOR", "title");
si[i++] = gsitm("N5022406I0000J00ENG.html", "The intake air temperature sensor is built-into mass air flow sensor. The sensor detects intake air temperature and transmits a signal to the ECM.", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "The temperature sensing unit uses a thermistor which is sensitive to the change in temperature.", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "&lt;Reference data>", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "Intake air temperature", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "[°C (°F)]", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "Voltage* (V)", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "25 (77)", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "1.9 – 2.1", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "80 (176)", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "3.0 – 3.2", "ptxt");
si[i++] = gsitm("N5022406I0000J00ENG.html", "*: These data are reference values on the diagnosis tool.", "ptxt");
si[i++] = gsitm("N5022406P0000J00ENG.html", "Refrigerant Pressure Sensor", "title");
si[i++] = gsitm("N5022406P0000J00ENG.html", "The refrigerant pressure sensor is installed at the condenser of the air conditioner system. The sensor uses an electrostatic volume pressure transducer to convert refrigerant pressure to voltage. The voltage signal is sent to ECM, and ECM controls cooling fan system.", "ptxt");
si[i++] = gsitm("N502040BA0000H00ENG.html", "Steering Switch", "title");
si[i++] = gsitm("N502040BA0000H00ENG.html", "ASCD/ACC/MI-PILOT steering switch has variant values of electrical resistance for each button. ECM reads voltage variation of switch, and determines which button is operated.", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Stop Light Switch", "title");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Stop light switch is installed to brake pedal bracket.", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "ECM detects the state of the brake pedal by those two types of input (ON/OFF signal).", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Brake pedal", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Connector", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Status", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Released", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "1 – 2", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "OFF", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "3 – 4", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N5022406R0000J00ENG.html", "Depressed", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "Positive Crankcase Ventilation", "title");
si[i++] = gsitm("N5022406L0000J00ENG.html", "This system returns blow-by gas to the intake manifold.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "The positive crankcase ventilation (PCV) valve is provided to conduct crankcase blow-by gas to the intake manifold.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "During partial throttle operation of the engine, the intake manifold sucks the blow-by gas through the PCV valve.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "Normally, the capacity of the valve is sufficient to handle any blow-by and a small amount of ventilating air.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "The ventilating air is then drawn from the air inlet tubes into the crankcase. In this process the air passes through the hose connecting air inlet tubes to rocker cover.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "Under full-throttle condition, the manifold vacuum is insufficient to draw the blow-by flow through the valve. The flow goes through the hose connection in the reverse direction.", "ptxt");
si[i++] = gsitm("N5022406L0000J00ENG.html", "On vehicles with an excessively high blow-by, the valve does not meet the requirement. This is because some of the flow will go through the hose connection to the air inlet tubes under all conditions.", "ptxt");
