si[i++] = gsitm("N502040A10008K00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008K00ENG.html", "ECM controls the engine by various functions.", "ptxt");
si[i++] = gsitm("N502040A10008K00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N502040A10008K00ENG.html", "Dig (direct injection gasoline) system", "ptxt");
si[i++] = gsitm("N502040A10008K00ENG.html", "Electric ignition system", "ptxt");
