si[i++] = gsitm("N502040BB0000V00ENG.html", "Fail Safe", "title");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Description", "title");
si[i++] = gsitm("N502040BB0000V00ENG.html", "When a DTC is detected, ECM executes a mode (in the Fail-safe mode) applicable to the DTC. The fail-safe mode has the preset traveling control mode (accelerator angle variation and engine output limit), device fix mode and combustion control mode.", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Fail safe mode", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Vehicle behavior", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Fail safe pattern", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Traveling control mode", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Accelerator angle variation control", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "ECM controls the accelerator pedal depression speed to make it slower than actual speed. This causes a drop in accelerating performance and encourages the driver to repair malfunction.", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "ECM does not control the accelerator pedal releasing speed.", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "A", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Engine output control", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "ECM reduces the engine output, according to the rise in engine speed. This reduces the vehicle speed to encourage the driver to repair malfunction.", "ptxt");
si[i++] = gsitm("N502040BB0000V00ENG.html", "Driving at 70 km/h (44 MPH) or more is possible.", "ptxt");
