si[i++] = gsitm("N502040A10008000ENG.html", "Crankshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", ".", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Exhaust camshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Mass air flow sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "(With intake air temperature sensor)", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Throttle position sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Accelerator pedal position sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Battery", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "ECM receives the battery voltage signal.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Knock sensor", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "ECM receives the vehicle speed signal via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "ECM receives the park/neutral position signal via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "Ignition coil", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "(With power transistor)", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008000ENG.html", "Firing order: 1 - 3 - 4 - 2", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "The ignition timing is controlled by the ECM to maintain the best air-fuel ratio for every running condition of the engine. The ignition timing data is stored in the ECM.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "The ECM receives information such as the injection pulse width and camshaft position sensor signal. Computing this information, ignition signals are transmitted to the power transistor.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "During the following conditions, the ignition timing is revised by the ECM according to the other data stored in the ECM.", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "At starting", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "During warm-up", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "At idle", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "At low battery voltage", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "During acceleration", "ptxt");
si[i++] = gsitm("N502040A10008000ENG.html", "The knock sensor retard system is designed only for emergencies. The basic ignition timing is programmed within the anti-knocking zone, if recommended fuel is used under dry conditions. The retard system does not operate under normal driving conditions. If engine knocking occurs, the knock sensor monitors the condition. The signal is transmitted to the ECM. The ECM retards the ignition timing to eliminate the knocking condition.", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008100ENG.html", "System Diagram", "title");
