si[i++] = gsitm("N502040A10008100ENG.html", "Exhaust camshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Fuel rail pressure sensor", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Throttle position sensor", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Accelerator pedal position sensor", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Battery", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "ECM detects the battery voltage.", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "High pressure fuel pump", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008100ENG.html", "Low fuel pressure control", "title");
si[i++] = gsitm("N502040A10008100ENG.html", "The low fuel pressure pump is controlled by ECM and pumps fuel according to a driving condition. The pumped fuel passes through the fuel filter and is sent to the high pressure fuel pump.", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "Low fuel pressure is adjusted by the fuel pressure regulator.", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "High fuel pressure control", "title");
si[i++] = gsitm("N502040A10008100ENG.html", "The high pressure fuel pump is actuated by the cam of camshaft (EXH).", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "The high pressure fuel pump activates the high pressure fuel pump solenoid based on a signal received from ECM, and adjusts the amount of discharge by changing the timing of closing the inlet check valve to control fuel rail pressure.", "ptxt");
si[i++] = gsitm("N502040A10008100ENG.html", "For details about operation, Refer to .", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008200ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N502040A10008200ENG.html", "Component parts", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Function", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Crankshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Intake camshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Engine oil temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Electric intake valve timing control module", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Electric intake valve timing control actuator", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Electric intake valve timing control motor*", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "*: Electric intake valve timing control motor is built in to the cam sprocket (INT).", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008200ENG.html", "Electric VTC responds faster than hydraulic VTC and can extend the operation angle of the camshaft. This improves the fuel economy, engine output, and exhaust performance.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "This mechanism continuously controls the phase of camshaft by the electric intake valve timing (IVT) control motor with the amount of intake valve operation held constant.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "ECM transmits a target position of the electric IVT control motor to electric IVT control module via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "The electric IVT control module controls the electric IVT control motor according to a signal from ECM and changes the opening and closing timing of intake valve.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Furthermore, the electric IVT control module has a diagnostic function and transmits a DTC detection signal to ECM via engine communication when detecting a system error.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Intake camshaft condition", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Electric intake valve timing control actuator operation", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Advanced angle", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "The electric intake valve timing control motor rotates the intake camshaft to advanced angle.", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Maintained", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Stop rotating the electric intake valve timing control motor to keep the intake camshaft position (cam phase).", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "Retard angle", "ptxt");
si[i++] = gsitm("N502040A10008200ENG.html", "The electric intake valve timing control motor rotates the intake camshaft to retard angle.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "Component parts", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Function", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Crankshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Exhaust camshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Engine oil temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "ECM receives vehicle speed signal via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Exhaust valve timing control solenoid valve", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "With the exhaust valve timing controller which controls the phase of exhaust camshaft to optional position continuously, ECM improves both low-middle speed torque and high speed performance, emission and fuel efficiency by optimizing the exhaust valve open/close timing according to driving conditions.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "The exhaust valve timing controller is hydraulically controlled by the exhaust valve timing control solenoid valve.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "This mechanism hydraulically controls cam phases continuously with the fixed operating angle of the exhaust valve.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "The ECM receives signals such as crankshaft position, camshaft position, engine speed, and engine oil temperature. Then, the ECM sends ON/OFF pulse duty signals to the exhaust valve timing control solenoid valve depending on driving status. This makes it possible to control the shut/open timing of the exhaust valve to increase engine torque and output in a range of high engine speed.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "EXHAUST VALVE TIMING CONTROL SOLENOID VALVE CONTROL", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "The exhaust valve timing control solenoid valve is driven ON-OFF (duty control) by ECM output signal, and controls the open/close timing of the exhaust valve to the optimum by changing its duty ratio according to the vehicle\'s driving condition.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Exhaust valve timing control solenoid valve condition", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Exhaust valve timing controller operation", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Engine OFF", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "When starting the engine, the controller vane and sprocket are fixed in full advanced position by the reaction force of return spring, improving the starting performance of the engine.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Active (Retard angle)", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "When the energization rate to the control solenoid valve is increased, the oil pressure from the oil pump is conveyed to the retard angle chamber of the controller. And advanced angle chamber oil is drained. Accordingly, the controller vane rotates leftward and the phase of camshaft becomes retard angle.This condition brings about the greater overlap with the intake valve, enabling the exhaust gas cleaning by the internal EGR effect and the fuel consumption improvement by the reduction in pumping loss.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Neutral (Maintained)", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "When it is the target valve timing, the energization rate to the control solenoid valve is adjusted to the intermediate state. The solenoid valve is positioned at the neutral position and the oil path is interrupted to maintain the cam shaft phase.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Return (Advanced angle)", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "When the energization rate to the control solenoid valve is decreased, the oil pressure from the oil pump is conveyed to the advanced chamber of the controller. And retard angle chamber oil is drained.Accordingly, the controller vane rotates rightward and the phase of camshaft becomes advanced angle.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "EXHAUST VALVE TIMING CONTROL FEEDBACK CONTROL", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "Cam Position Detection", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "The exhaust camshaft position sensor mounted at the rear of the cylinder head detects a cam position, by using the groove on the plate located at the rear of the exhaust camshaft.", "ptxt");
si[i++] = gsitm("N502040A10008300ENG.html", "Feedback Control", "title");
si[i++] = gsitm("N502040A10008300ENG.html", "The exhaust camshaft position sensor feeds back an actual cam position signal to ECM. Based on the signal, ECM controls the exhaust valve timing control solenoid valve to satisfy the optimum target valve opening/closing timing according to a driving condition.", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008400ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N502040A10008400ENG.html", "Component parts", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Function", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Crankshaft position sensor", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Engine oil temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Battery", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "ECM receives the battery voltage signal.", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Engine oil pressure control solenoid valve", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008400ENG.html", "ECM performs the variable hydraulic control (low oil pressure control and high oil pressure control) based on signals from each sensor according to oil temperature and engine load. ECM activates the engine oil pressure control solenoid valve and switches to the low oil pressure control and high oil pressure control. ECM uses the low oil pressure control for 80-90 % of the operating area to maintain low oil pressure and stops piston cooling jet (i.e. achievement of less than or equal to jet injection valve opening pressure).", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "High oil pressure control start condition", "title");
si[i++] = gsitm("N502040A10008400ENG.html", "High engine speed", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Coolant temperature is 60°C (140°F)or more under high engine load condition", "ptxt");
si[i++] = gsitm("N502040A10008400ENG.html", "Low oil pressure control start condition", "title");
si[i++] = gsitm("N502040A10008400ENG.html", "Coolant temperature is less than 60°C (140°F) under low engine speed condition", "ptxt");
