si[i++] = gsitm("N502040A10008500ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "Intake manifold runner control valve motor", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008500ENG.html", "Intake manifold runner control valve has a valve portion in the intake passage of each cylinder.", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "While idling and during low engine coolant temperature, the intake manifold runner control valve closes. Thus the velocity of the air in the intake passage increases, promoting the vaporization of the fuel and producing a intake manifold runner in the combustion chamber.", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "Because of this operation, this system tends to increase the burning speed of the gas mixture, improve exhaust emission, and increase the stability in running conditions.", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "Also, except when idling and during low engine coolant temperature, this system opens the intake manifold runner control valve.", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "In this condition, this system tends to increase power by improving intake efficiency via reduction of intake flow resistance.", "ptxt");
si[i++] = gsitm("N502040A10008500ENG.html", "The intake manifold runner control valve is operated by the ECM.", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008600ENG.html", "SYSTEM DIAGRAM", "title");
