si[i++] = gsitm("N502040A10008600ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Battery", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "ECM detects the battery voltage.", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Intake manifold tuning valve motor", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008600ENG.html", "This system switches the length of intake air path according to the low-to-medium speed range or high speed range. Torque is increased in the low-to-medium speed range and the engine output is improved in the high speed range.", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Engine speed: Low and medium speed range", "title");
si[i++] = gsitm("N502040A10008600ENG.html", "Since the intake manifold tuning (IMT) valve is closed when the engine speed is less than 5,000 rpm, the length of the effective intake air path is from the mouth of intake manifold collector to the intake valve. This long path brings the inertia effect of intake air, contributing to the improvement in intake air efficiency and the generation of high torque.", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Engine speed: High speed range", "title");
si[i++] = gsitm("N502040A10008600ENG.html", "When engine speed is 5,000 rpm or more, ECM turns ON the intake manifold tuning valve motor to open the intake manifold tuning valve. The length of the effective intake air path at this time is from the intake manifold tuning valve to the intake valve. This short path brings the inertia effect of intake air in the high speed range, contributing to the torque improvement while the engine is running at high speeds. (The highest engine output is improved.)", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Intake Manifold Tuning Valve Operating Condition", "title");
si[i++] = gsitm("N502040A10008600ENG.html", "ECM opens the intake manifold tuning valve when all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Engine speed: 5,000 rpm or more", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Engine coolant temperature: -30°C (-22°F) or more", "ptxt");
si[i++] = gsitm("N502040A10008600ENG.html", "Battery voltage: 16 V or less", "ptxt");
