si[i++] = gsitm("N502040A10008700ENG.html", "Cooling fan relay", "ptxt");
si[i++] = gsitm("N502040A10008700ENG.html", "Cooling fan motor", "ptxt");
si[i++] = gsitm("N502040A10008700ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008700ENG.html", "Cooling fan control signal is sent to IPDM E/R from ECM by CAN communication line. Then, IPDM E/R sends ON/OFF pulse duty signal to cooling fan control module. Corresponding to this ON/OFF pulse duty signal, cooling fan control module gives cooling fan motor operating voltage to cooling fan motors. Cooling fan speed is controlled by duty cycle of cooling fan motor operating voltage sent from cooling fan control module.", "ptxt");
si[i++] = gsitm("N502040A10008700ENG.html", "Cooling Fan Speed Request for Cooling the Engine", "title");
si[i++] = gsitm("N502040A10008700ENG.html", "Cooling fan speed for cooling the engine is judged based on vehicle speed, engine coolant temperature, air conditioner ON signal, refrigerant pressure, target A/C evaporator temperature, and A/C evaporator temperature.", "ptxt");
