si[i++] = gsitm("N502040A10008800ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008800ENG.html", "EGR system decreases oxygen density in intake air by recirculating a part of exhaust gas to intake system, and decreases recirculating exhaust gas temperature by water cooling type cooler. This is to reduce combustion temperature inside of cylinder so that control generating NOx and knocking. Also this function is for coexistence of driveability and the exhaust performance, and fuel economy.", "ptxt");
si[i++] = gsitm("N502040A10008800ENG.html", "EGR is deactivated under the following conditions to enhance driveability:", "ptxt");
