si[i++] = gsitm("N502040A10008Y00ENG.html", "Engine Malfunction Power reduced Service now", "ptxt");
si[i++] = gsitm("N502040A10008Y00ENG.html", "Engine Malfunction Service now", "ptxt");
si[i++] = gsitm("N502040A10008Y00ENG.html", "Check it according to DTC Diagnosis Procedure.", "ptxt");
si[i++] = gsitm("N502040A10008Y00ENG.html", "Even in the case of DTCs to be confirmed in the 2nd trip, this warning may be displayed by the 1st trip DTCs and the DTCs may be stored in the ECM memory. Then, if the system is determined to be normal in the 2nd trip, this warning will disappear and the 1st trip DTCs will be cleared.", "ptxt");
