si[i++] = gsitm("N502040A10008A00ENG.html", "(Mixture ratio feedback signal)", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "Vehicle speed*2", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "*1: ECM determines the start signal status by the signals of engine speed and battery voltage.", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "*2: This signal is sent to the ECM through CAN communication line.", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008A00ENG.html", "The evaporative emission system is used to reduce hydrocarbons emitted into the atmosphere from the fuel system. This reduction of hydrocarbons is accomplished by activated charcoals in the EVAP canister.", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "The fuel vapor in the sealed fuel tank is led into the EVAP canister which contains activated carbon and the vapor is stored there when the engine is not operating or when refueling to the fuel tank.", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "The vapor in the EVAP canister is purged by the air through the purge line to the intake manifold when the engine is operating. EVAP canister purge volume control solenoid valve is controlled by ECM. When the engine operates, the flow rate of vapor controlled by EVAP canister purge volume control solenoid valve is proportionally regulated as the air flow increases.", "ptxt");
si[i++] = gsitm("N502040A10008A00ENG.html", "EVAP canister purge volume control solenoid valve also shuts off the vapor purge line during decelerating.", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "System Description", "title");
