si[i++] = gsitm("N502040A1000AP00ENG.html", "Engine oil temperature", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A1000AP00ENG.html", "The engine protection control at low engine oil pressure warns the driver of a decrease in engine oil pressure by the oil pressure warning light a before the engine becomes damaged.", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "When detecting a decrease in engine oil pressure at an engine speed less than 1,000 rpm, ECM transmits an oil pressure warning light signal to the combination meter. The combination meter turns ON the oil pressure warning light, according to the signal.", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "Decrease in engine oil pressure", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "Fuel cut", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "Detection", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "Less than 1,000 rpm", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "ON*", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "NO", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "1,000 rpm or more", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "YES", "ptxt");
si[i++] = gsitm("N502040A1000AP00ENG.html", "*: When detecting a normal engine oil pressure, ECM turns OFF the oil pressure warning light.", "ptxt");
si[i++] = gsitm("N502040A10008C00ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008C00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008C00ENG.html", "ECM transmits a target power generation voltage signal received from IPDM E/R to the generator via LIN communication.", "ptxt");
si[i++] = gsitm("N502040A10008C00ENG.html", "The generator includes a self-diagnosis function and transmits a diagnosis signal to ECM via LIN communication when detecting a malfunction. When ECM receives a diagnosis signal, ECM detects DTC and transmits a charge warning light request signal to the combination meter to turn ON the charge warning light.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "System Description", "title");
