si[i++] = gsitm("N502040A10008D00ENG.html", "ASCD steering switch", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", ".", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "It transmits the output shaft speed signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "It transmits the park/neutral position signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "It transmits the vehicle speed signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "It receives the ASCD status signal from ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Electric throttle control actuator", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "BASIC ASCD SYSTEM", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "Refer to Owner\'s Manual for ASCD operating instructions.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Automatic Speed Control Device (ASCD) allows a driver to keep vehicle at predetermined constant speed without depressing accelerator pedal. Driver can set vehicle speed in advance between approximately 40 km/h (25 MPH) and 144 km/h (89 MPH).", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "ECM controls throttle angle of electric throttle control actuator to regulate engine speed.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "The ASCD operation status is indicated by two indicators (CRUISE and SET on the information display) on the combination meter. If any malfunction occurs in ASCD system, SET indicator blinks and ASCD control is deactivated.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Always drive vehicle in safe manner according to traffic conditions and obey all traffic laws.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "SET OPERATION", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "Press MAIN switch. (CRUISE is indicated on the information display.)", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "When vehicle speed reaches a desired speed between approximately 40 km/h (25 MPH) and 144 km/h (89 MPH), press SET- switch or RES+ switch. (Then SET is indicated on the information display.)", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "If press RES+ switch when there is no set speed, the set speed is set to the current speed.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "ACCELERATE OPERATION", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "If the RES+ switch is pressed during cruise control driving, increase the vehicle speed until the switch is released or vehicle speed reaches maximum speed controlled by the system.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "And then ASCD will keep the new set speed.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "CANCEL OPERATION", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "When any of following conditions exist, cruise operation will be canceled.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "CANCEL switch is pressed", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "More than 2 switches at ASCD steering switch are pressed at the same time (Set speed will be cleared)", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Brake pedal is depressed", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Selector lever is changed to N, P, R position", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Vehicle speed decreased to 13 km/h (8 MPH) lower than the set speed", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "TCS system is operated", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "When the ECM detects any of the following conditions, the ECM will cancel the cruise operation and inform the driver by blinking indicators.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Engine coolant temperature is slightly higher than the normal operating temperature, CRUISE indicator may blink slowly.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "When the engine coolant temperature decreases to the normal operating temperature, CRUISE indicator will stop blinking and the cruise operation will be able to work by pressing SET- switch or RES+ switch.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Malfunction for some self-diagnoses regarding ASCD control: SET indicator will blink quickly.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "If MAIN switch is turned to OFF during ASCD is activated, all of ASCD operations will be canceled and vehicle speed memory will be erased.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "COAST OPERATION", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "When the SET- switch is pressed during cruise control driving, decrease vehicle set speed until the switch is released. And then ASCD will keep the new set speed.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "RESUME OPERATION", "title");
si[i++] = gsitm("N502040A10008D00ENG.html", "When the RES+ switch is pressed after cancel operation other than pressing MAIN switch is performed, vehicle speed will return to last set speed. To resume vehicle set speed, vehicle condition must meet following conditions.", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Brake pedal is released", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Selector lever is in other than P and N positions", "ptxt");
si[i++] = gsitm("N502040A10008D00ENG.html", "Vehicle speed is greater than 40 km/h (25 MPH) and less than 144 km/h (89 MPH)", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008L00ENG.html", "BASIC SPEED LIMITER SYSTEM", "title");
si[i++] = gsitm("N502040A10008L00ENG.html", "The speed limiter is a system that enables to restrict the vehicle speed within the set speed that is selected by the driver. Driver can set vehicle speed between 30 km/h (20 MPH) and 190 km/h (120 MPH) (in the metric system mode) or 20 MPH and 120 MPH (in the yard/pound system mode). ECM controls fuel injector to regulate vehicle speed. Operation status of speed limiter is indicated on the information display in the combination meter. If any malfunction occurs in speed limiter system, it automatically deactivates control.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "Always drive vehicle in safe manner according to traffic conditions and obey all traffic laws.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "SET OPERATION", "title");
si[i++] = gsitm("N502040A10008L00ENG.html", "Press speed limiter MAIN switch. (LIMIT indicated on the information display)", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "By pressing the SET– switch, the vehicle speed can be set within the range between 30 km/h (20 MPH) and 190 km/h (120 MPH). (SET and set speed is indicated on the information display)", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "When pressing the RES+ switch, the set speed can be increased.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "When pressing the SET– switch, the set speed can be decreased.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "CANCEL OPERATION", "title");
si[i++] = gsitm("N502040A10008L00ENG.html", "When any of following conditions exist, speed limiter operation will be canceled.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "Speed limiter MAIN switch pressed (Set speed will be cleared)", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "CANCEL switch is pressed", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "Accelerator pedal is fully depressed (kickdown)", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "When the accelerator pedal is depressed within the range shown in the figure (A) below, the accelerator pedal reaction force strengthens. Further depressing the accelerator pedal within the (C) range cancels the speed limiter. This allows acceleration in emergencies.", "ptxt");
si[i++] = gsitm("N502040A10008L00ENG.html", "RESUME OPERATION", "title");
si[i++] = gsitm("N502040A10008L00ENG.html", "After the speed limiter is released by other method than the MAIN switch, the RES+ switch allows to set the vehicle speed again to the one that is previously set before releasing the speed limiter.", "ptxt");
