si[i++] = gsitm("N502040A10008E00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008E00ENG.html", "This system improves engine operation when the air conditioner is used.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "Under the following conditions, the air conditioner is turned off.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "When cranking the engine.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "At high engine speeds.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "When the engine coolant temperature becomes excessively high.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "When operating power steering during low engine speed or low vehicle speed.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "When engine speed is excessively low.", "ptxt");
si[i++] = gsitm("N502040A10008E00ENG.html", "When refrigerant pressure is excessively low or high.", "ptxt");
si[i++] = gsitm("N502040A10008F00ENG.html", "System Description", "title");
si[i++] = gsitm("N502040A10008F00ENG.html", "CAN (Controller Area Network) is a serial communication line for real time application. It is an on-vehicle multiplex communication line with high data communication speed and excellent error detection ability. Many electronic control units are equipped onto a vehicle, and each control unit shares information and links with other control units during operation (not independent). In CAN communication, control units are connected with 2 communication lines (CAN H line, CAN L line) allowing a high rate of information transmission with less wiring. Each control unit transmits/receives data but selectively reads required data only.", "ptxt");
si[i++] = gsitm("N502040A10008F00ENG.html", "Refer to . about CAN communication for detail.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "System Description", "title");
