si[i++] = gsitm("N502040A10008G00ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Mass Air Flow Sensor (With Intake Air Temperature Sensor)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "ECM receives the vehicle speed signal via CAN communication.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502040A10008G00ENG.html", "ECM calculates engine load, engine coolant temperature, and engine speed based on signals from the mass air flow sensor, engine coolant temperature sensor, and crankshaft position sensor and monitors the deterioration state of engine oil.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "When the mileage before engine oil change comes to approximately 1,500 km or less, pre-alert message is displayed to inform the driver that the maintenance timing is close as shown in the following table.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Remaining mileage to the engine oil change timing", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Alert timing", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "1,000 km &lt; the mileage ≤ 1,500 km (630 mile &lt;the mileage ≤ 940 mile)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "The first IGN ON after reaching 1,500 km (940 mile)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "500 km &lt; the mileage ≤ 1,000 km (310 mile &lt; the mileage ≤ 630 mile)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "The first IGN ON after reaching 1,000 km (630 mile)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "500 km or less (310 mile or less)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "The first IGN ON every 100 km (60 mile)", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Furthermore, when the timing is passed, alert message is displayed every time when ignition switch is turned ON to inform the driver that engine oil change is necessary.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "At oil change, the mileage must be reset using vehicle information display function.", "ptxt");
si[i++] = gsitm("N502040A10008G00ENG.html", "Alerted mileage might be different from actual mileage.", "ptxt");
si[i++] = gsitm("N502040BM0000G00ENG.html", "Warning/Indicator (On Information Display)", "title");
