si[i++] = gsitm("N5020403S0000I00ENG.html", "Speed limiter MAIN switch", "ptxt");
si[i++] = gsitm("N5020403S0000I00ENG.html", "Master switch to activate the speed limiter system.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "System Readiness Test (SRT) Code", "title");
si[i++] = gsitm("N5022406T0000N00ENG.html", "System Readiness Test (SRT) code is specified in Service $01 of SAE J1979/ISO 15031-5.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "As part of an enhanced emissions test for Inspection & Maintenance (I/M), certain states require the status of SRT be used to indicate whether the ECM has completed self-diagnosis of major emission systems and components. Completion must be verified in order for the emissions inspection to proceed.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "If a vehicle is rejected for a State emissions inspection due to one or more SRT items indicating \"Incomplete\", use the information in this Service Manual to set the SRT to \"Complete\".", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "In most cases the ECM will automatically complete its self-diagnosis cycle during normal usage, and the SRT status will indicate \"Complete\" for each application system. Once set as \"Complete\", the SRT status remains \"Complete\" until the self-diagnosis memory is erased.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Occasionally, certain portions of the self-diagnostic test may not be completed as a result of the customer\'s normal driving pattern; the SRT will indicate \"Incomplete\" for these items.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "The SRT will also indicate \"Incomplete\" if the self-diagnosis memory is erased for any reason or if the ECM memory power supply is interrupted for several hours.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "If, during the state emissions inspection, the SRT indicates \"Complete\" for all test items, the inspector will continue with the emissions test. However, if the SRT indicates \"Incomplete\" for one or more of the SRT items the vehicle is returned to the customer untested.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "SRT SET TIMING", "title");
si[i++] = gsitm("N5022406T0000N00ENG.html", "SRT is set as \"Complete\" after self-diagnosis has been performed one or more times. Completion of SRT is done regardless of whether the result is OK or NG. The set timing is different between OK and NG results and is shown in the table below.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Self-diagnosis result", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Example", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Diagnosis", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Ignition cycle", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "← ON → OFF ← ON → OFF ← ON → OFF ← ON →", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "All OK", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Case 1", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "P0400", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "OK (1)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "– (1)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "OK (2)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "– (2)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "P1402", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "SRT of EGR", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "\"Complete\"", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Case 2", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "\"Incomplete\"", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "NG exists", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "Case 3", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "OK", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "–", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "NG", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "(Consecutive NG)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "(1st trip)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "1st trip DTC", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "(= MIL ON)", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "OK: Self-diagnosis is carried out and the result is OK.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "NG: Self-diagnosis is carried out and the result is NG.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "–: Self-diagnosis is not carried out.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "When all SRT related self-diagnoses show OK results in a single cycle (Ignition OFF-ON-OFF), the SRT will indicate \"Complete\". → Case 1 above", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "When all SRT related self-diagnoses show OK results through several different cycles, the SRT will indicate \"Complete\" at the time the respective self-diagnoses have at least one OK result. → Case 2 above", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "If one or more SRT related self-diagnoses show NG results in 2 consecutive cycles, the SRT will also indicate \"Complete\". → Case 3 above", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "The table above shows that the minimum number of cycles for setting SRT as \"Incomplete\" is the number one (1) for each self-diagnosis (Case 1 & 2) or the number two (2) for one of self-diagnoses (Case 3). However, in preparation for the state emissions inspection, it is unnecessary for each self-diagnosis to be executed twice (Case 3) for the following reasons:", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "The SRT will indicate \"Complete\" at the time the respective self-diagnoses have one (1) OK result.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "The emissions inspection requires \"Complete\" of the SRT only with OK self-diagnosis results.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "During SRT driving pattern, the 1st trip DTC (NG) is detected prior to \"Complete\" of SRT and the self-diagnosis memory must be erased from the ECM after repair.", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "If the 1st trip DTC is erased, all the SRT will indicate \"Incomplete\".", "ptxt");
si[i++] = gsitm("N5022406T0000N00ENG.html", "SRT can be set as \"Complete\" together with the DTC(s). Therefore, DTC check must always be carried out prior to the state emission inspection even though the SRT indicates \"Complete\".", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "DTC and Freeze Frame Data", "title");
si[i++] = gsitm("N5022405T0000U00ENG.html", "DTC AND 1ST TRIP DTC (PROVISIONAL DTC)", "title");
si[i++] = gsitm("N5022405T0000U00ENG.html", "The 1st trip DTC (whose number is the same as the DTC number) is displayed for the latest self-diagnostic result obtained. If the ECM memory was cleared previously, and the 1st trip DTC did not recur, the 1st trip DTC will not be displayed.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "If a malfunction is detected during the 1st trip, the 1st trip DTC is saved in the ECM memory. The MIL will not light up (two trip detection logic). If the same malfunction is not detected in the 2nd trip (meeting the required driving pattern), the 1st trip DTC is cleared from the ECM memory. If the same malfunction is detected in the 2nd trip, both the 1st trip DTC and DTC are saved in the ECM memory and the MIL lights up. In other words, the DTC is stored in the ECM memory and the MIL lights up when the same malfunction occurs in two consecutive trips. If a 1st trip DTC is stored and a non-diagnostic operation is performed between the 1st and 2nd trips, only the 1st trip DTC will continue to be stored. For malfunctions that blink or light up the MIL during the 1st trip, the DTC and 1st trip DTC are stored in the ECM memory.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "For malfunctions in which 1st trip DTCs are displayed, Refer to . These items are required by legal regulations to continuously monitor the system/component. In addition, the items monitored non-continuously are also displayed on M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "1st trip DTC is specified in Service $07 of SAE J1979/ISO 15031-5. 1st trip DTC detection occurs without illuminating the MIL and therefore does not warn the driver of a malfunction.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "When a 1st trip DTC is detected, check, print out or write down and erase (1st trip) DTC and Freeze Frame data as specified in Work Flow procedure Step 2, Refer to . Then perform DTC Confirmation Procedure or Component Function Check to try to duplicate the malfunction. If the malfunction is duplicated, the item requires repair.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "FREEZE FRAME DATA AND 1ST TRIP FREEZE FRAME DATA", "title");
si[i++] = gsitm("N5022405T0000U00ENG.html", "The ECM records the driving conditions such as fuel system status, calculated load value, engine coolant temperature, short term fuel trim, long term fuel trim, engine speed, vehicle speed, absolute throttle position, base fuel schedule and intake air temperature at the moment a malfunction is detected.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Data which are stored in the ECM memory, along with the 1st trip DTC, are called 1st trip freeze frame data. The data, stored together with the DTC data, are called freeze frame data and displayed on M.U.T.-III SE or GST.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Only one set of freeze frame data (either 1st trip freeze frame data or freeze frame data) can be stored in the ECM. 1st trip freeze frame data is stored in the ECM memory along with the 1st trip DTC. However, once freeze frame data (2nd trip detection/MIL on) is stored in the ECM memory, 1st trip freeze frame data is no longer stored. Remember, only one set of freeze frame data can be stored in the ECM. The ECM has the following priorities to update the data.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Priority", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Items", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "1", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Freeze frame data", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Misfire – DTC: P0300 – P0304", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Fuel Injection System Function – DTC: P0171, P0172", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Except the above items", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "1st trip freeze frame data", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "For example, the EGR malfunction (Priority: 2) was detected and the freeze frame data was saved in the 2nd trip. After that when the misfire (Priority: 1) is detected in another trip, the freeze frame data will be updated from the EGR malfunction to the misfire. Once freeze frame data is stored in the ECM memory, 1st trip freeze data is no longer stored (because only one freeze frame data or 1st trip freeze frame data can be stored in the ECM). If freeze frame data is stored in the ECM memory and freeze frame data with the same priority occurs later, the first (original) freeze frame data remains unchanged in the ECM memory.", "ptxt");
si[i++] = gsitm("N5022405T0000U00ENG.html", "Both 1st trip freeze frame data and freeze frame data (along with the DTCs) are cleared when the ECM memory is erased.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Driving Pattern", "title");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Always drive at a safe speed.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "DRIVING PATTERN A", "title");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Driving pattern A means a trip satisfying the following conditions.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Engine speed reaches 400 rpm or more.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Engine coolant temperature rises by 20°C (36°F) or more after starting the engine.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Engine coolant temperature reaches 70°C (158°F) or more.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "The ignition switch is turned from ON to OFF.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the same malfunction is detected regardless of driving conditions, reset the counter of driving pattern A.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the above conditions are satisfied without detecting the same malfunction, reset the counter of driving pattern A.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "DRIVING PATTERN B", "title");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Driving pattern B means a trip satisfying the following conditions.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Vehicle speed of 70 – 120 km/h (44 – 75 MPH) is maintained for 60 seconds or more under the control of closed loop.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Vehicle speed of 30 – 60 km/h (19 – 37 MPH) is maintained for 10 seconds or more under the control of closed loop.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Under the closed loop control condition, the following state reaches 12 seconds or more in total: Vehicle speed of 4 km/h (2 MPH) or less with idling condition.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "The state of driving at 10 km/h (7 MPH) or more reaches 10 minutes or more in total.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "A lapse of 22 minutes or more after engine start.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Drive the vehicle at a constant velocity.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the same malfunction is detected regardless of driving conditions, reset the counter of driving pattern B.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the above conditions are satisfied without detecting the same malfunction, reset the counter of driving pattern B.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "DRIVING PATTERN C", "title");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Driving pattern C means operating vehicle as per the following:", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "The following conditions should be satisfied at the same time:", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Engine speed: (Engine speed in the freeze frame data) ±375 rpm", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Calculated load value: (Calculated load value in the freeze frame data) x (1±0.1) [%]", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Engine coolant temperature condition:", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the freeze frame data shows lower than 70°C (158°F), engine coolant temperature should be lower than 70°C (158°F).", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the freeze frame data shows higher than or equal to 70°C (158°F), engine coolant temperature should be higher than or equal to 70°C (158°F).", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the same malfunction is detected regardless of the above vehicle conditions, reset the counter of driving pattern C.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the above conditions are satisfied without detecting the same malfunction, reset the counter of driving pattern C.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "The 1st trip DTC will be cleared when C counter is counted once without the same malfunction after DTC is stored in ECM.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "DRIVING PATTERN D", "title");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Driving pattern D means a trip satisfying the following conditions.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "The state of driving at 40 km/h (25 MPH) reaches 300 seconds or more in total.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "Idle speed lasts 30 seconds or more.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "A lapse of 600 seconds or more after engine start.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the same malfunction is detected regardless of driving conditions, reset the counter of driving pattern D.", "ptxt");
si[i++] = gsitm("N5022405S0000J00ENG.html", "When the above conditions are satisfied without detecting the same malfunction, reset the counter of driving pattern D.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Counter System", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "RELATIONSHIP BETWEEN MIL, 1ST TRIP DTC, DTC, AND DETECTABLE ITEMS", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When a malfunction is detected for the first time, the 1st trip DTC and the 1st trip freeze frame data are stored in the ECM memory.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When the same malfunction is detected in two consecutive trips, the DTC and the freeze frame data are stored in the ECM memory, and the MIL will come on.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "The MIL will turn OFF after the vehicle is driven 3 times (driving pattern B) with no malfunction. The drive is counted only when the recorded driving pattern is met (as stored in the ECM). If another malfunction occurs while counting, the counter will reset.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "The DTC and the freeze frame data will be stored until the vehicle is driven 40 times (driving pattern A) without the same malfunction recurring (except for Misfire and Fuel Injection System). For Misfire and Fuel Injection System, the DTC and freeze driven.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "The 1st trip DTC is not displayed when the self-diagnosis results in OK for the 2nd trip.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "COUNTER SYSTEM CHART", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Items", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Fuel Injection System", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Misfire", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Other", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "MIL (turns OFF)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "3 (pattern B)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "DTC, Freeze Frame Data (no display)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "80 (pattern C)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "40 (pattern A)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "1st Trip DTC (clear)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "1 (pattern B)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "1st Trip Freeze Frame Data (clear)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "1 (pattern C)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "For details about patterns B and C under “Fuel Injection System” and “Misfire”, see “EXPLANATION FOR DRIVING PATTERNS FOR “MISFIRE &lt;EXHAUST QUALITY DETERIORATION>”, “FUEL INJECTION SYSTEM”.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Relationship Between MIL, DTC, 1st Trip DTC and Driving Patterns System", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*1:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When the same malfunction is detected in two consecutive trips, MIL will light up.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*2:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "MIL will turn OFF after vehicle is driven 3 times (pattern B) without any malfunctions.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*3:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When the same malfunction is detected in two consecutive trips, the DTC and the freeze frame data will be stored in ECM.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*4:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "The DTC and the freeze frame data will not be displayed any longer after vehicle is driven 40 times (pattern A) without the same malfunction.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "(The DTC and the freeze frame data still remain in ECM.)", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*5:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When a malfunction is detected for the first time, the 1st trip DTC and the 1st trip freeze frame data will be stored in ECM.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*6:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "1st trip DTC will be cleared after vehicle is driven once (pattern B) without the same malfunction.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "*7:", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "When the same malfunction is detected in the 2nd trip, the 1st trip freeze frame data will be cleared.", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Explanation for Driving Patterns Except for “Misfire &lt;Exhaust Quality Deterioration>”, “Fuel Injection System”", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Driving Pattern A", "title");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5022405Q0000J00ENG.html", "Driving Pattern B", "title");
si[i++] = gsitm("N5022404J0000J00ENG.html", "1st Trip Detection Logic and Two Trip Detection Logic", "title");
si[i++] = gsitm("N5022404J0000J00ENG.html", "When a malfunction is detected for the first time, 1st trip DTC and 1st trip Freeze Frame data are stored in the ECM memory. The MIL will not illuminate at this stage. &lt;1st trip>", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "If the same malfunction is detected again during the next drive, the DTC and Freeze Frame data are stored in the ECM memory, and the MIL illuminates. The MIL illuminates at the same time when the DTC is stored. &lt;2nd trip> The “trip” in the “Two Trip Detection Logic” means a driving mode in which self-diagnosis is performed during vehicle operation. Specific on board diagnostic items will cause the ECM to illuminate or blink the MIL, and store DTC and Freeze Frame data, even in the 1st trip, as shown below.", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "Items", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "MIL", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "1st trip DTC", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "1st trip", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "2nd trip", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "1st trip displaying", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "2nd trip displaying", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "Blinking", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "Illuminated", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "Misfire (Possible three way catalyst damage) — DTC: P0300 – P0304 is being detected", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "—", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "One trip detection diagnoses Refer to .", "ptxt");
si[i++] = gsitm("N5022404J0000J00ENG.html", "Except above", "ptxt");
si[i++] = gsitm("N5022406G0000M00ENG.html", "Malfunction Indicator Light (MIL)", "title");
si[i++] = gsitm("N5022406G0000M00ENG.html", "When emission-related ECU detects a malfunction in the emission control systems components and/or the powertrain control components (which affect vehicle emissions), it turns on/blinks MIL to inform the driver that a malfunction has been detected.", "ptxt");
si[i++] = gsitm("N5022406G0000M00ENG.html", "The MIL illuminates when ignition switch is turned ON (engine is not running).", "ptxt");
si[i++] = gsitm("N5022406G0000M00ENG.html", "Check the MIL circuit if MIL does not illuminate. Refer to .", "ptxt");
si[i++] = gsitm("N5022406G0000M00ENG.html", "When the engine is started, the MIL should go off.", "ptxt");
si[i++] = gsitm("N5022406G0000M00ENG.html", "If MIL continues to illuminate/blink, perform self-diagnoses and inspect/repair accordingly because an emission-related ECU has detected a malfunction in the emission control systems components and/or the powertrain control components (which affect vehicle emissions).", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "On Board Diagnosis Function", "title");
