si[i++] = gsitm("N5022406J0000J00ENG.html", "If ECM detects a malfunction, it illuminates or blinks MIL to inform the driver that a malfunction has been detected.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Accelerator pedal released position learning", "ptxt");
