si[i++] = gsitm("N5022406J0000J00ENG.html", "This function allows damage inspection in the MIL bulb (blown, open circuit, etc.).", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Operation Procedure", "title");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "The MIL on the instrument panel should stay ON.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "If it remains OFF, check MIL circuit. Refer to .", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "SRT STATUS MODE", "title");
si[i++] = gsitm("N5022406J0000J00ENG.html", "This function allows to read if ECM has completed the self-diagnoses of major emission control systems and components. For SRT, Refer to .", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Turn ignition switch ON and wait 20 seconds.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "SRT status is indicated as shown blow.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "ECM continues to illuminate MIL if all SRT codes are set.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "ECM blinks MIL for about 10 seconds if all SRT codes are not set.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "MALFUNCTION WARNING MODE", "title");
si[i++] = gsitm("N5022406J0000J00ENG.html", "In this function ECM turns on or blinks MIL when it detects a malfunction in the emission control system components and/or the powertrain control components (which affect vehicle emissions) to inform the driver that a malfunction has been detected.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Check that MIL illuminates.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "Start engine and let it idle.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "For two trip detection logic diagnoses, ECM turns on MIL when it detects the same malfunction twice in the two consecutive driving cycles.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "For 1st trip detection logic diagnoses, ECM turns on MIL when it detects a malfunction in one driving cycle.", "ptxt");
si[i++] = gsitm("N5022406J0000J00ENG.html", "ECM blinks MIL when it detects a malfunction that may damage the three way catalyst (misfire).", "ptxt");
