si[i++] = gsitm("N5022405P0000L00ENG.html", "Diagnostic Test Mode in which M.U.T.-III SE drives some actuators apart from the ECMs and also shifts some parameters in a specified range.", "ptxt");
si[i++] = gsitm("N5022405P0000L00ENG.html", "ECM part number can be read.", "ptxt");
si[i++] = gsitm("N5022405P0000L00ENG.html", "This mode enables a technician to adjust some devices faster and more accurately by following the indications on the M.U.T.-III SE unit.", "ptxt");
