si[i++] = gsitm("N5022406V0000J00ENG.html", "Test Value and Test Limit", "title");
si[i++] = gsitm("N5022406V0000J00ENG.html", "The following is the information specified in Service $06 of SAE J1979/ISO 15031-5.", "ptxt");
si[i++] = gsitm("N5022406V0000J00ENG.html", "The test value is a parameter used to determine whether a system/circuit diagnostic test is OK or NG while being monitored by the ECM during self-diagnosis. The test limit is a reference value which is specified as the maximum or minimum value and is compared with the test value being monitored.", "ptxt");
si[i++] = gsitm("N5022406V0000J00ENG.html", "These data (test value and test limit) are specified by Test ID (TID), Unit and Scaling ID and can be displayed on the GST screen.", "ptxt");
si[i++] = gsitm("N5022406V0000J00ENG.html", "The items of the test value and test limit will be displayed with GST screen which items are provided by the ECM. (e.g., if bank 2 is not applied on this vehicle, only the items of bank 1 are displayed)", "ptxt");
