si[i++] = gsitm("N502040AM0001600ENG.html", "Work Flow", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "Get the detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurred) using the \"Diagnostic Work Sheet\". (Refer to .)", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Ask if the customer requests I/M examination.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Malfunction information, obtained", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "No malfunction information, but a request for I/M examination", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 13.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Perform the following procedure if DTC is displayed.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Record DTC and freeze frame data. (Print them out with M.U.T.-III SE or GST.)", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Erase only DTC of “ENGINE\".", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "\"How to Erase DTC and 1st Trip DTC\" in Refer to M.U.T.-III SE Function .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer. (Symptom Matrix Chart is useful. Refer to .)", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Are any symptoms described and any DTCs detected?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "Try to confirm the symptom described by the customer (except MIL ON).", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Also study the normal operation and fail-safe related to the symptom. Refer to Symptom . and Refer to Fail-safe", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Diagnosis Work Sheet is useful to verify the incident.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Also study the normal operation and fail-safe related to the symptom. Refer to Symptom . and Refer to Fail-safe.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "id2004");
si[i++] = gsitm("N502040AM0001600ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the displayed DTC, and then check that DTC is detected again.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "If two or more DTCs are detected, Refer to . and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "YES", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "NO", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "Check according to Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "PERFORM BASIC INSPECTION", "id2005");
si[i++] = gsitm("N502040AM0001600ENG.html", "Perform Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Do you have M.U.T.-III SE?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "PERFORM SPEC IN DATA MONITOR MODE", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "Check that \"Mass air flow sensor B1\", \"Base fuel schedule\", \"Air fuel ratio compensation B1\" are within the SP value using \"SPEC\" in \"DATA MONITOR\" mode with M.U.T.-III SE. Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Is the measurement value within the SP value?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "DETECT MALFUNCTIONING PART BY TROUBLE DIAGNOSIS - SPECIFICATION VALUE", "id2007");
si[i++] = gsitm("N502040AM0001600ENG.html", "Detect malfunctioning part according to diagnosis procedure. Refer to Diagnosis Procedure.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Is a malfunctioning part detected?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM TABLE", "id2008");
si[i++] = gsitm("N502040AM0001600ENG.html", "Detect malfunctioning system according to Refer to . based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptoms.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "id2009");
si[i++] = gsitm("N502040AM0001600ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "The Diagnosis Procedure in EC section described based on open circuit inspection. A short circuit inspection is also required for the circuit check in the Diagnosis Procedure. For details, Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Monitor input data from related sensors or check voltage of related ECM terminals using M.U.T.-III SE. Refer to Values On The Diagnosis Tool.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "id2010");
si[i++] = gsitm("N502040AM0001600ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Check DTC. If DTC is displayed, erase it. Refer to the following.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "GO TO 12.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N502040AM0001600ENG.html", "When DTC was detected in step 2, perform DTC CONFIRMATION PROCEDURE or Component Function Check again, and then check that the malfunction have been completely repaired.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "When symptom was described from the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N502040AM0001600ENG.html", "YES-1", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "DTC is detected: GO TO 10.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "YES-2", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "Symptom remains: GO TO 6.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "NO-1", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "No request for I/M examination from the customer: Before returning the vehicle to the customer, always erase unnecessary DTC in ECM and TCM (: Refer to \"How to Erase DTC and 1st Trip DTC\" in Refer to M.U.T.-III SE Function.), If the completion of SRT is needed, drive vehicle under the specific driving pattern. Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "NO-2", "result");
si[i++] = gsitm("N502040AM0001600ENG.html", "I/M examination, requested from the customer: GO TO 13.", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "PREPARE FOR I/M EXAMINATION", "id2012");
si[i++] = gsitm("N502040AM0001600ENG.html", "Set SRT codes. Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001600ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "There are many operating conditions that lead to the malfunction of engine components. A good grasp of such conditions can make troubleshooting faster and more accurate.", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "In general, each customer feels differently about symptoms. It is important to fully understand the symptoms or conditions for a customer complaint.", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "Utilize a diagnostic worksheet like the WORKSHEET SAMPLE below in order to organize all the information for troubleshooting.", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "Some conditions may cause the MIL to illuminate or blink, and DTC to be detected. Examples:", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "Vehicle ran out of fuel, which caused the engine to misfire.", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "Fuel filler cap was left off or incorrectly screwed on, allowing fuel to evaporate into the atmosphere.", "ptxt");
si[i++] = gsitm("N5020401Q0000G00ENG.html", "WORKSHEET SAMPLE", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "INSPECTION START", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Check service records for any recent repairs that may indicate a related malfunction, or a current need for scheduled maintenance.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Open engine hood and check the following:", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Harness connectors for improper connections", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Wiring harness for improper connections, pinches and cut", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Vacuum hoses for splits, kinks and improper connections", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Hoses and ducts for leaks", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Air cleaner clogging", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Gasket", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Confirm that electrical or mechanical loads are not applied.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Headlight switch is OFF.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Air conditioner switch is OFF.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Rear window defogger switch is OFF.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Steering wheel is in the straight-ahead position, etc.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Start engine and warm it up until engine coolant temperature indicator points the middle of gauge.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Ensure engine stays below 1,000 rpm.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Run engine at about 2,000 rpm for about 2 minutes under no load.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Make sure that no DTC is displayed with M.U.T.-III SE or GST.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N502040AO0005H00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "NO", "result");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "REPAIR OR REPLACE", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Repair or replace components as necessary according to corresponding Diagnostic Procedure.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "CHECK TARGET IDLE SPEED", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Rev engine (2,000 to 3,000 rpm) two or three times under no load, then run engine at idle speed for about 1 minute.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Check idle speed.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "For procedure, Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "For specification, Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "PERFORM ACCELERATOR PEDAL RELEASED POSITION LEARNING", "id2003");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Stop engine.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Refer to Description.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "PERFORM THROTTLE VALVE CLOSED POSITION LEARNING", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "PERFORM IDLE AIR VOLUME LEARNING", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Is Idle Air Volume Learning carried out successfully?", "question");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Follow the instruction of Idle Air Volume Learning. Then GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "CHECK TARGET IDLE SPEED AGAIN", "title");
si[i++] = gsitm("N502040AO0005H00ENG.html", "Start engine and warm it up to normal operating temperature.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N502040AO0005H00ENG.html", "DETECT MALFUNCTIONING PART", "title");
