si[i++] = gsitm("N5020401G0005V00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0005V00ENG.html", "When replacing ECM, the following procedure must be performed. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0005V00ENG.html", "When replacing the ECM, always replace it with a new one. The functions controlled by the ECM does not operate properly in case of reuse of the ECM from another vehicle.", "ptxt");
si[i++] = gsitm("N5020401G0005V00ENG.html", "PROGRAMMING OPERATION", "title");
si[i++] = gsitm("N5020401G0005V00ENG.html", "When replacing the ECM, a new ECM must be used. The functions controlled by the ECM do not operate properly if a ECM from another vehicle is used.", "ptxt");
si[i++] = gsitm("N5020401G0005V00ENG.html", "After replacing with a blank ECM, programming is required to write ECM information. Be sure to follow the procedure to perform the programming.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Before Replacing ECM", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "SAVE ECM DATA", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Reconnect all harness connectors disconnected.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Select \"SAVING DATA FOR REPLC CPU\" in \"WORK SUPPORT\" mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Follow the instruction of M.U.T.-III SE display.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Necessary data in ECM is copied and saved to M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Go to Step 2 regardless of with or without success in saving data.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "With remote engine start function", "result");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Without remote engine start function", "result");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Replace ECM.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "After replacing ECM, perform necessary work.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "REPLACE ECM", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Replace ECM. Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "After Replacing ECM", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM ECM PROGRAMMING", "PERFORMECMPROGRAMMINGFASTLINKED-F6E566BA");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Perform ECM programming according to the procedure of \"Programming\" in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Battery voltage: 12 – 13.5 V (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM IGNITION SWITCH OPERATION", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM INITIALIZATION OF NATS SYSTEM AND REGISTRATION OF ALL NATS IGNITION KEY IDS", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "CHECK ECM DATA STATUS", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Check if the data is successfully copied from the ECM at Step 1 (before replacement) and saved in M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Is the data saved successfully?", "question");
si[i++] = gsitm("N502040AO0006R00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "NO", "result");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "WRITE ECM DATA", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Select \"WRITING DATA FOR REPLC CPU\" in \"WORK SUPPORT\" mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "The data saved by \"SAVING DATA FOR REPLC CPU\" is written to ECM.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM VIN REGISTRATION", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Refer to Description .", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "WRITING MAC KEY FOR ECM", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM ACCELERATOR PEDAL RELEASED POSITION LEARNING", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM THROTTLE VALVE CLOSED POSITION LEARNING", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM IDLE AIR VOLUME LEARNING", "title");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM EGR VOLUME CONTROL VALVE CLOSED POSITION LEARNING", "PERFORMEGRVOLUMECONTROLVALVECLOSEDP-F6E566B1");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 12.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "CHECK DTC", "CHECKDTC-F6E5669F");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Turn ignition switch OFF and wait for 10 seconds or more.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "If DTC is displayed, perform diagnosis of detected DTC. Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "GO TO 13.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "PERFORM THE FACTORY MODE OFF", "PERFORM THE FACTORY MODE OFF -F6E5669F");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"ENGINE\".", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "Check the item No.1: Factory Mode and perform the following procedure by the set value.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N502040AO0006R00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5020401G0005W00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0005W00ENG.html", "Accelerator Pedal Released Position Learning is a function of ECM to learn the fully released position of the accelerator pedal by monitoring the accelerator pedal position sensor output signal. It must be performed each time harness connector of accelerator pedal position sensor or ECM is disconnected. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N502040AO0005300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005300ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0005300ENG.html", "Make sure that accelerator pedal is fully released.", "ptxt");
si[i++] = gsitm("N502040AO0005300ENG.html", "Turn ignition switch ON and wait at least 2 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005300ENG.html", "Turn ignition switch OFF and wait at least 10 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005300ENG.html", "END", "ptxt");
si[i++] = gsitm("N5020401G0005X00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0005X00ENG.html", "EGR Volume Control Valve Closed Position Learning is a function of ECM to learn the fully closed position of the EGR volume control valve by monitoring the EGR volume control valve output signal. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0005X00ENG.html", "It must be performed under any of the following conditions:", "ptxt");
si[i++] = gsitm("N5020401G0005X00ENG.html", "Replacement EGR volume control valve", "ptxt");
si[i++] = gsitm("N5020401G0005X00ENG.html", "Replacement of ECM", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005400ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0005400ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "Select “EGR control valve closed position learning” in \"Learning\" (in \"Special Function\") of \"ENGINE\".", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "After \"Completed\" is displayed, turn ignition switch OFF and wait at least 3 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "Learning is completed during a self-shutoff of the EGR volume control valve.", "ptxt");
si[i++] = gsitm("N502040AO0005400ENG.html", "END", "ptxt");
si[i++] = gsitm("N5020401G0005Y00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0005Y00ENG.html", "Idle Air Volume Learning is a function of ECM to learn the idle air volume that keeps each engine idle speed within the specific range. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0005Y00ENG.html", "It must be performed under any of the following conditions:", "ptxt");
si[i++] = gsitm("N5020401G0005Y00ENG.html", "Each time electric throttle control actuator or ECM is replaced.", "ptxt");
si[i++] = gsitm("N5020401G0005Y00ENG.html", "Idle speed or ignition timing is out of specification.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0006N00ENG.html", "PRECONDITIONING", "title");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Make sure that all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Learning will be cancelled if any of the following conditions are missed for even a moment.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Battery voltage: More than 12.9 V (At idle)", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Engine coolant temperature: 70 - 105°C (158 - 221°F)", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Selector lever : P or N", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Electric load switch: OFF", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "(Air conditioner, headlight, rear window defogger)", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "On vehicles equipped with daytime running light systems, set lighting switch to the 1st position to light only small lamps.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Steering wheel: Neutral (Straight-ahead position)", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Vehicle speed: Stopped", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Transmission: Warmed-up", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Drive vehicle until \"ATF TENP SEN\" in \"DATA MONITOR\" mode of \"CVT\" system indicates less than 0.9 V.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Without M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Drive vehicle for 10 minutes.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "IDLE AIR VOLUME LEARNING", "idE2");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Perform Accelerator Pedal Released Position Learning. Refer to Description.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Perform Throttle Valve Closed Position Learning. Refer to Description.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Start engine and warm it up to normal operating temperature.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Select \"Idle Air Volume Learning\" in \"WORK SUPPORT\" mode of \"ENGINE\".", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Touch \"OK\" and wait 20 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Is \"Completed\" displayed on M.U.T.-III SE screen?", "question");
si[i++] = gsitm("N502040AO0006N00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0006N00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "NO", "result");
si[i++] = gsitm("N502040AO0006N00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "CHECK IDLE SPEED AND IGNITION TIMING", "idE3");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Rev up the engine two or three times and make sure that idle speed and ignition timing are within the specifications. For specification, Refer to  and .", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N502040AO0006N00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "DETECT MALFUNCTIONING PART", "idE4");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Check the following", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Check that throttle valve is fully closed.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Check PCV valve operation.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Check that downstream of throttle valve is free from air leakage.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Repair or replace malfunctioning part.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Engine component parts and their installation condition are questionable. Check and eliminate the cause of the incident.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "It is useful to perform \"TROUBLE DIAGNOSIS - SPECIFICATION VALUE\". Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "If any of the following conditions occur after the engine has started, eliminate the cause of the incident and perform Idle Air Volume Learning all over again:", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Engine stalls.", "ptxt");
si[i++] = gsitm("N502040AO0006N00ENG.html", "Erroneous idle.", "ptxt");
si[i++] = gsitm("N5020401G0005Z00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0005Z00ENG.html", "Throttle Valve Closed Position Learning is a function of ECM to learn the fully closed position of the throttle valve by monitoring the throttle position sensor output signal. It must be performed each time the harness connector of the electric throttle control actuator or ECM is disconnected or electric throttle control actuator inside is cleaned. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0006O00ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0006O00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Select \"Closed throttle position learning\" in \"Learning\" (in \"Special Function\") mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Follow the instructions on the M.U.T.-III SE display.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Turn ignition switch OFF and wait at least 10 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Check that throttle valve moves during the above 10 seconds by confirming the operating sound.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Without M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Engine coolant temperature is 25°C (77°F) or less before engine starts.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Warm up the engine.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "Raise engine coolant temperature until it reaches 65°C (149°F) or more.", "ptxt");
si[i++] = gsitm("N502040AO0006O00ENG.html", "END", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006000ENG.html", "Electric intake valve timing control (IVT) module requires the learning of camshaft reference position. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "This learning must be performed where the following operations are performed:", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of electric IVT control module", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of intake/exhaust camshaft position sensor", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of crankshaft position sensor", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Removal and installation of timing chain", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of the mechanical parts listed below:", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of timing chain", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of intake/exhaust camshaft", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of intake/exhaust camshaft sprocket", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of piston", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of connecting rod", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "Replacement of crankshaft", "ptxt");
si[i++] = gsitm("N5020401G0006000ENG.html", "If learning is not performed after the replacement of the above listed parts, the engine may not be able to be started.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005J00ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Do you have M.U.T.-III SE?", "question");
si[i++] = gsitm("N502040AO0005J00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0005J00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "NO", "result");
si[i++] = gsitm("N502040AO0005J00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "ELECTRIC INTAKE VALVE TIMING (IVT) CONTROL ACTUATOR REFERENCE POSITION LEARNING", "idE2");
si[i++] = gsitm("N502040AO0005J00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "On M.U.T.-III SE screen, select Read All DTCs and check that any DTC is not detected.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Select “Electric intake valve timing control learning” in “WORK SUPPORT” of “ENGINE”.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Touch \"OK\" and start the engine within 10 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Let the engine be idle.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Check that “COMPLETED” is displayed.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Is the learning completed normally?", "question");
si[i++] = gsitm("N502040AO0005J00ENG.html", "END", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Check that DTC is not detected and restart the learning.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "PERFORM ELECTRIC IVT CONTROL ACTUATOR REFERENCE POSITION LEARNING", "idE3");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Without M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Disconnect electric IVT control actuator harness connector (actuator side).", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Turn ignition switch ON and wait at least 30 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Reconnect the disconnected harness connector.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Start engine and let it idle at least 15 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005J00ENG.html", "Check and erase DTC.", "ptxt");
si[i++] = gsitm("N5020401G0006100ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006100ENG.html", "This describes how to erase the mixture ratio self-learning value. For the actual procedure, follow the instructions in “Diagnosis Procedure”. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005800ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0005800ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Start engine and warm it up to normal operating temperature.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Select \"SELF-LEARNING CONT\" in \"Learning\" (in \"Special Function\") mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Clear mixture ratio self-learning value by touching \"OK\".", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "With GST", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Disconnect mass air flow sensor harness connector.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Restart engine and let it idle for at least 5 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Stop engine and reconnect mass air flow sensor harness connector.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Select Service $03 with GST. Make sure DTC P0102 is detected.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "Select Service $04 with GST to erase the DTC P0102.", "ptxt");
si[i++] = gsitm("N502040AO0005800ENG.html", "END", "ptxt");
si[i++] = gsitm("N5020401G0006200ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006200ENG.html", "VIN Registration is an operation to registering VIN in ECM. It must be performed each time ECM is replaced. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0006200ENG.html", "Accurate VIN which is registered in ECM may be required for Inspection & Maintenance (I/M).", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0006P00ENG.html", "CHECK VIN", "title");
si[i++] = gsitm("N502040AO0006P00ENG.html", "Check the VIN of the vehicle and note it. Refer to GROUP 00 - Vehicle Identification - Vehicle Identification Number Plate.", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "PERFORM VIN REGISTRATION", "title");
si[i++] = gsitm("N502040AO0006P00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "Turn ignition switch ON and engine stopped.", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "Select \"Chassis No./VIN Registration\" in \"WORK SUPPORT\" mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "Follow the instruction of M.U.T.-III SE display.", "ptxt");
si[i++] = gsitm("N502040AO0006P00ENG.html", "END", "ptxt");
si[i++] = gsitm("N5020401G0006300ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006300ENG.html", "When replacing ECM, it is necessary to write MAC key to ECM. Write MAC key to ECM according to \"MAC Key writing\" procedure of \"M.U.T.-III SE Operation Manual\". Refer to .", "ptxt");
si[i++] = gsitm("N5020401G0006300ENG.html", "During MAC key writing, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5020401G0006300ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N5020401G0006300ENG.html", "M.U.T.-III SE is connected to internet", "ptxt");
si[i++] = gsitm("N502040AO0005A00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005A00ENG.html", "PERFORM MAC KEY WRITING", "title");
si[i++] = gsitm("N502040AO0005A00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0005A00ENG.html", "Select \"MAC Key writing\" on \"Special Function\" of \"ECM\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AO0005A00ENG.html", "Touch \"Write\".", "ptxt");
si[i++] = gsitm("N502040AO0005A00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5020401G0006400ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006400ENG.html", "The oil control system allows calculating the remaining distance to drive before oil change request. The engine oil data reset must be performed after engine oil is changed. (For details, refer to .)", "ptxt");
si[i++] = gsitm("N5020401G0006400ENG.html", "Never reset data except when changing engine oil.", "ptxt");
si[i++] = gsitm("N5020401G0006400ENG.html", "Data cannot be reset until the vehicle travels 10 km (6.2 mile) from the previous data reset.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005B00ENG.html", "START", "title");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Check information display of the combination meter.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Is Distance to Engine Oil Change displayed?", "question");
si[i++] = gsitm("N502040AO0005B00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0005B00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "NO", "result");
si[i++] = gsitm("N502040AO0005B00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "SELECT OIL CONTROL SYSTEM MODE", "title");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Push the Display next switch and select oil control system mode.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "RESET ENGINE OIL DATA", "title");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Press and hold the Display Next switch at least 1 second while Distance to Engine Oil Change is displayed.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "Stop pressing the Display Next switch, and a few seconds later, check that the value of Distance to Engine Oil Change is reset.", "ptxt");
si[i++] = gsitm("N502040AO0005B00ENG.html", "END", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Work Flow", "title");
si[i++] = gsitm("N502040AM0001700ENG.html", "FUEL PRESSURE RELEASE", "title");
si[i++] = gsitm("N502040AM0001700ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Perform \"Chassis No./VIN Registration\" in \"WORK SUPPORT\" mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "After engine stalls, crank it two or three times to release all fuel pressure.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Without M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Remove fuel pump fuse located in IPDM E/R.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Reinstall fuel pump fuse after servicing fuel system.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "END", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "FUEL PRESSURE CHECK", "title");
si[i++] = gsitm("N502040AM0001700ENG.html", "Before disconnecting fuel line, release fuel pressure from fuel line to eliminate danger.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Prepare pans or saucers under the disconnected fuel line because the fuel may spill out. The fuel pressure cannot be completely released because this models do not have fuel return system.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Use Fuel Pressure Gauge Kit [SST: (J-44321)] to check fuel pressure.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Release fuel pressure to zero.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Connect fuel tube adapter [SST:KV10120000] to quick connector.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Turn ignition switch ON and check for fuel leakage.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Start engine and check for fuel leakage.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Read the indication of fuel pressure gauge.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "At idling", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", ": Approximately 500 kPa (0.5 bar, 5.1 kg/cm2, 72.5 psi)", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N502040AM0001700ENG.html", "YES", "result");
si[i++] = gsitm("N502040AM0001700ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "NO", "result");
si[i++] = gsitm("N502040AM0001700ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "CHECK FUEL HOSES AND FUEL TUBES", "title");
si[i++] = gsitm("N502040AM0001700ENG.html", "Check fuel hoses and fuel tubes for clogging.", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Replace \"fuel filter and fuel pump assembly\". Refer to .", "ptxt");
si[i++] = gsitm("N502040AM0001700ENG.html", "Repair or replace error-detected parts.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "SRT Set Driving Pattern", "title");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "Always drive the vehicle in safe manner according to traffic conditions and obey all traffic laws.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "*1: Depress the accelerator pedal until vehicle speed is 90 km/h (56 MPH), then release the accelerator pedal and keep it released for more than 10 seconds. Depress the accelerator pedal until vehicle speed is 90 km/h (56 MPH) again.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "*2: Checking the vehicle speed with GST is advised.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "The time required for each diagnosis varies with road surface conditions, weather, altitude, individual driving habits, etc.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "“Zone A” is the fastest time where required for the diagnosis under normal conditions*. If the diagnosis is not completed within “Zone A”, the diagnosis can still be performed within “Zone B”.", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "*: Normal conditions", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "Sea level", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "Flat road", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "Ambient air temperature: 20 – 30°C (68 – 86°F)", "ptxt");
si[i++] = gsitm("N5022406Q0000J00ENG.html", "Diagnosis is performed as quickly as possible under normal conditions. However, under other conditions, diagnosis may also be performed. [For example: ambient air temperature other than 20 – 30°C (68 – 86°F)]", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0007H00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N5020401G0007H00ENG.html", "In order to set all SRTs, the self-diagnoses as in the \"SRT ITEM\" table must have been performed at least once. Each diagnosis may require actual driving for a long period of time under various conditions.", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "SRT ITEM", "title");
si[i++] = gsitm("N5020401G0007H00ENG.html", "The table below shows required self-diagnostic items to set the SRT to \"Complete\".", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "SRT item", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "(M.U.T.-III SE indication)", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Performance Priority*", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Required self-diagnostic items to set the SRT to \"Complete\"", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Corresponding DTC No.", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "CATALYST", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "1", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Three way catalyst function", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "P0420", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "HO2S", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Air fuel ratio (A/F) sensor 1", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "P014C, P014D", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Heated oxygen sensor 2", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "P0130, P0131, P0132, P0139, P2270, P2271, P2A01", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "EGR/VVT SYSTEM", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "Intake/Exhaust valve timing control function", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "P0011, P0012, P0014, P0015, P0401, P052A, P052B, P054A, P054B", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "*: If completion of several SRTs is required, perform driving patterns (DTC confirmation procedure), one by one based on the priority for models with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5020401G0007H00ENG.html", "SRT SERVICE PROCEDURE", "title");
si[i++] = gsitm("N5020401G0007H00ENG.html", "If a vehicle has failed the state emissions inspection due to one or more SRT items indicating \"Incomplete\", review the flowchart diagnostic sequence, referring to the following flowchart.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N502040AO0005K00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N502040AO0005K00ENG.html", "YES", "result");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Repair malfunction(s) and erase DTC. Refer to .", "ptxt");
