si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "CHECK SRT STATUS", "idE2");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Without M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Perform “SRT status” mode with Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "With GST", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Select Service $01 with GST.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Is SRT code(s) set?", "question");
si[i++] = gsitm("N502040AO0005K00ENG.html", "END", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Without M.U.T.-III SE: GO TO 3.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PERFORM ROAD TEST", "idE3");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Check the “Performance Priority” in the “SRT ITEM” table. Refer to Description.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Perform the most efficient SRT set driving pattern to set the SRT properly. Refer to .", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "In order to set all SRTs, the SRT set driving pattern must be performed at least once.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PATTERN 1", "idE4");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Check the vehicle condition;", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Engine coolant temperature is −10 to 35°C (14 to 95°F).", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Fuel tank temperature is more than 0°C (32°F).", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Keep engine idling until the engine coolant temperature is greater than 70°C (158°F)", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "ECM terminal voltage is follows;", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Engine coolant temperature", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "−10 to 35°C (14 to 95°F): 3.0 – 4.3 V", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "70°(158°F): Less than 4.1 V", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Fuel tank temperature: Less than 1.4 V", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Refer to Values On The Diagnosis Tool.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PATTERN 2", "idE5");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Drive the vehicle. And depress the accelerator pedal until vehicle speed is 90 km/h (56 MPH), then release the accelerator pedal and keep it released for more than 10 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Depress the accelerator pedal until vehicle speed is 90 km/h (56 MPH) again", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Checking the vehicle speed with GST is advised.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "When steady-state driving is performed again even after it is interrupted, each diagnosis can be conducted. In this case, the time required for diagnosis may be extended.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PATTERN 3", "idE6");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Operate vehicle following the driving pattern shown in the figure.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Release the accelerator pedal during deceleration of vehicle speed from 90 km/h (56 MPH) to 0 km/h (0 MPH).", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PATTERN 4", "idE7");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Drive the vehicle in a proper gear at 60 km/h (38 MPH) and maintain the speed.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Release the accelerator pedal fully at least 5 seconds.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Repeat the above two steps at least 5 times.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "PATTERN 5", "idE8");
si[i++] = gsitm("N502040AO0005K00ENG.html", "The accelerator pedal must be held very steady during steady-state driving.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "If the accelerator pedal is moved, the test must be conducted again.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N502040AO0005K00ENG.html", "Is SRT(s) set?", "question");
