si[i++] = gsitm("N502040130008600ENG.html", "Atmospheric temperature: 20 - 30°C (68 - 86°F)", "ptxt");
si[i++] = gsitm("N502040130008600ENG.html", "Engine coolant temperature: 75 - 95°C (167 - 203°F)", "ptxt");
si[i++] = gsitm("N502040130008600ENG.html", "Transmission: Warmed-up", "ptxt");
