si[i++] = gsitm("N5020401U004DM00ENG.html", "DTC DETECTION LOGIC", "title");
si[i++] = gsitm("N5020401U004DM00ENG.html", "With the Air/Fuel Mixture Ratio Self-Learning Control, the actual mixture ratio can be brought closely to the theoretical mixture ratio based on the mixture ratio feedback signal from the A/F sensors 1. The ECM calculates the necessary compensation to correct the offset between the actual and the theoretical ratios.", "ptxt");
si[i++] = gsitm("N5020401U004DM00ENG.html", "In case the amount of the compensation value is extremely large (The actual mixture ratio is too rich.), the ECM judges the condition as the fuel injection system malfunction and lights up the MIL (2 trip detection logic).", "ptxt");
