si[i++] = gsitm("N5020401U004E800ENG.html", "FAIL-SAFE", "title");
si[i++] = gsitm("N5020401U004E800ENG.html", "Engine operating condition in fail-safe mode", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Fail safe mode", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Vehicle behavior", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Traveling control mode", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Accelerator angle variation control", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "ECM controls the accelerator pedal depression speed to make it slower than actual speed. This causes a drop in accelerating performance and encourages the driver to repair malfunction.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "ECM does not control the accelerator pedal releasing speed.", "ptxt");
