si[i++] = gsitm("N5020401U004E800ENG.html", "Stops feedback control of idle speed and controls with specified speed.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Recovery speed control at decelerating", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Stops recovery speed control by the fuel cut at decelerating and controls with specified speed.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Idle neutral control", "ptxt");
