si[i++] = gsitm("N5020401U004E800ENG.html", "DTC Confirmation Procedure", "title");
si[i++] = gsitm("N5020401U004E800ENG.html", "PRECONDITIONING", "title");
si[i++] = gsitm("N5020401U004E800ENG.html", "If DTC Confirmation Procedure has been previously conducted, always perform the following procedure before conducting the next test.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Turn ignition switch OFF and wait at least 10 seconds.", "ptxt");
