si[i++] = gsitm("N5020401U004E800ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE-1", "title");
si[i++] = gsitm("N5020401U004E800ENG.html", "Start engine and warm it up to normal operating temperature.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Restart engine and let it idle for about 15 minutes.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Check 1st trip DTC.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Is 1st trip DTC detected?", "question");
