si[i++] = gsitm("N5020401U004E800ENG.html", "NO", "result");
si[i++] = gsitm("N5020401U004E800ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE-2", "title");
si[i++] = gsitm("N5020401U004E800ENG.html", "Start engine and drive the vehicle as per the similar conditions to (1st trip) Freeze Frame Data for a certain time. Refer to the table below.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Hold the accelerator pedal as steady as possible.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "The similar conditions to (1st trip) Freeze Frame Data means the vehicle operation that the following conditions should be satisfied at the same time.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Always drive vehicle in safe manner according to traffic conditions and obey all traffic laws when driving.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Engine speed in the freeze frame data ± 400 rpm", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Vehicle speed", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Vehicle speed in the freeze frame data ± 10 km/h (6 MPH)", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Engine coolant temperature (T) condition", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "When the freeze frame data shows lower than 70°C (158°F),", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "T should be lower than 70°C (158°F).", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "When the freeze frame data shows higher than or equal to 70°C (158°F),", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "T should be higher than or equal to 70°C (158°F).", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "The time to driving varies according to the engine speed in the freeze frame data.", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Time", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Around 1,000 rpm", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Approximately 10 minutes", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Around 2,000 rpm", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Approximately 5 minutes", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "More than 3,000 rpm", "ptxt");
si[i++] = gsitm("N5020401U004E800ENG.html", "Approximately 3.5 minutes", "ptxt");
