si[i++] = gsitm("N5020401U004E900ENG.html", "DTC Description", "title");
si[i++] = gsitm("N5020401U004E900ENG.html", "DTC DETECTION LOGIC", "title");
si[i++] = gsitm("N5020401U004E900ENG.html", "When a misfire occurs, engine speed will fluctuate. If the engine speed fluctuates enough to cause the crankshaft position (CKP) sensor signal to vary, ECM can determine that a misfire is occurring.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "Sensor", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "Input signal to ECM", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "ECM function", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "Crankshaft position sensor", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "Engine speed", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "On board diagnosis of misfire", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "The misfire detection logic consists of the following two conditions.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "One Trip Detection Logic (Three Way Catalyst Damage)", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "On the 1st trip, when a misfire condition occurs that can damage the three way catalyst (TWC) due to overheating, the MIL will blink.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "When a misfire condition occurs, the ECM monitors the CKP sensor signal every 200 engine revolutions for a change.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "When the misfire condition decreases to a level that will not damage the TWC, the MIL will turn off.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "If another misfire condition occurs that can damage the TWC on a second trip, the MIL will blink.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "When the misfire condition decreases to a level that will not damage the TWC, the MIL will remain on.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "If another misfire condition occurs that can damage the TWC, the MIL will begin to blink again.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "Two Trip Detection Logic (Exhaust quality deterioration)", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "For misfire conditions that will not damage the TWC (but will affect vehicle emissions), the MIL will only light when the misfire is detected on a second trip. During this condition, the ECM monitors the CKP sensor signal every 1,000 engine revolutions.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "A misfire malfunction can be detected on any one cylinder or on multiple cylinders.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "M.U.T.-III SE screen terms", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "(Trouble diagnosis content)", "ptxt");
