si[i++] = gsitm("N5020401U004E900ENG.html", "To check malfunction symptom before repair: Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N5020401U004E900ENG.html", "NO-2", "result");
si[i++] = gsitm("N5020401U004E900ENG.html", "Confirmation after repair: INSPECTION END", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "DTC Diagnosis Procedure", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK GROUND CONNECTION", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check the following.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Connection condition of the ground F1 and F2.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Connection condition of the ground harness between engine assembly and vehicle body (If equipped).", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Is the inspection result normal?", "question");
