si[i++] = gsitm("N5020401W0026P00ENG.html", "PERFORM POWER BALANCE TEST", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Perform “Power balance” in “ACTIVE TEST” mode of “ENGINE” using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Make sure that each circuit produces a momentary engine speed drop.", "ptxt");
