si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK FUNCTION OF FUEL INJECTOR", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Start engine and let engine idle.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Listen to each fuel injector operating sound.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Clicking noise should be heard.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Perform trouble diagnosis for FUEL INJECTOR. Refer to .", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK FUNCTION OF IGNITION COIL-1", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Do the following procedure in the place where ventilation is good without the combustible.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Remove fuel pump fuse in IPDM E/R to release fuel pressure.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Do not use M.U.T.-III SE to release fuel pressure, or fuel pressure applies again during the following procedure.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "After engine stalls, crank it two or three times to release all fuel pressure.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Remove all ignition coil harness connectors to avoid the electrical discharge from the ignition coils.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Remove ignition coil and spark plug of the cylinder to be checked.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Crank engine for 5 seconds or more to remove combustion gas in the cylinder.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Connect spark plug and harness connector to ignition coil.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Fix ignition coil using a rope etc. with gap of 13 - 17 mm (0.52 - 0.66 in) between the edge of the spark plug and grounded metal portion as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Crank engine for about 3 seconds, and check whether spark is generated between the spark plug and the grounded metal portion.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Spark should be generated.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Do not approach to the spark plug and the ignition coil within 50 cm (19.7 in). Be careful not to get an electrical shock while checking, because the electrical discharge voltage becomes 20 kV or more.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "It might cause to damage the ignition coil if the gap of more than 17 mm (0.66 in) is taken.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "When the gap is less than 13 mm (0.52 in), the spark might be generated even if the coil is malfunctioning.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK FUNCTION OF IGNITION COIL-2", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Disconnect spark plug and connect a known-good spark plug.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Crank engine for about 3 seconds, and recheck whether spark is generated between the spark plug and the grounded metal portion.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check ignition coil, power transistor and their circuits. Refer to Component Inspection.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK SPARK PLUG", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check the initial spark plug for fouling, etc.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Replace spark plug(s) with standard type one(s). For spark plug type, refer to Inspection.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Repair or clean spark plug. Then GO TO 9.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK FUNCTION OF IGNITION COIL-3", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Reconnect the initial spark plugs.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Crank engine for about 3 seconds, and recheck whether spark is generated between the spark plug and the grounded portion.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Replace spark plug(s) with standard type one(s). For spark plug type. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK COMPRESSION PRESSURE", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check compression pressure. Refer to .", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check pistons, piston rings, valves, valve seats and cylinder head gaskets.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "CHECK FUEL PRESSURE", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Install all removed parts.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Release fuel pressure to zero.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Install fuel pressure gauge and check fuel pressure. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "At idling: Approximately 500 kPa (0.5 bar, 5.1 kg/cm2, 72.5 psi)", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 13.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "GO TO 12.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "DETECT MALFUNCTIONING PART", "title");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Check fuel hoses and fuel tubes for clogging.", "ptxt");
si[i++] = gsitm("N5020401W0026P00ENG.html", "Replace “fuel filter and fuel pump assembly”. Refer to .", "ptxt");
