si[i++] = gsitm("N5020401U004EA00ENG.html", "To check malfunction symptom before repair: Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N5020401U004EA00ENG.html", "NO-2", "result");
si[i++] = gsitm("N5020401U004EA00ENG.html", "Confirmation after repair: INSPECTION END", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "DTC Diagnosis Procedure", "title");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "CHECK GROUND CONNECTION", "title");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Check the following.", "ptxt");
