si[i++] = gsitm("N5020401W0026Q00ENG.html", "Connection condition of the ground harness between engine assembly and vehicle body (If equipped).", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Is the inspection result normal?", "question");
