si[i++] = gsitm("N5020401W0026Q00ENG.html", "Repair or replace error-detected parts.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "CHECK FOR INTAKE AIR LEAK AND PCV HOSE", "title");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Start engine and run it at idle speed.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Listen for the sound of the intake air leak.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Check PCV hose connection.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Is intake air leak detected?", "question");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "Discover air leak location and repair.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5020401W0026Q00ENG.html", "CHECK FOR EXHAUST SYSTEM CLOGGING", "title");
