si[i++] = gsitm("N5020401W0026R00ENG.html", "CHECK FUNCTION OF IGNITION COIL-1", "title");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Do the following procedure in the place where ventilation is good without the combustible.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Remove fuel pump fuse in IPDM E/R to release fuel pressure.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Do not use M.U.T.-III SE to release fuel pressure, or fuel pressure applies again during the following procedure.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "After engine stalls, crank it two or three times to release all fuel pressure.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Remove all ignition coil harness connectors to avoid the electrical discharge from the ignition coils.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Remove ignition coil and spark plug of the cylinder to be checked.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Crank engine for 5 seconds or more to remove combustion gas in the cylinder.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Connect spark plug and harness connector to ignition coil.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Fix ignition coil using a rope etc. with gap of 13 - 17 mm (0.52 - 0.66 in) between the edge of the spark plug and grounded metal portion as shown in the figure.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Crank engine for about 3 seconds, and check whether spark is generated between the spark plug and the grounded metal portion.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Spark should be generated.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "Do not approach to the spark plug and the ignition coil within 50 cm (19.7 in). Be careful not to get an electrical shock while checking, because the electrical discharge voltage becomes 20 kV or more.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "It might cause to damage the ignition coil if the gap of more than 17 mm (0.66 in) is taken.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "When the gap is less than 13 mm (0.52 in), the spark might be generated even if the coil is malfunctioning.", "ptxt");
si[i++] = gsitm("N5020401W0026R00ENG.html", "GO TO 7.", "ptxt");
