si[i++] = gsitm("N5020401U004EC00ENG.html", "Vehicle behavior", "ptxt");
si[i++] = gsitm("N5020401U004EC00ENG.html", "Traveling control mode", "ptxt");
si[i++] = gsitm("N5020401U004EC00ENG.html", "accelerator angle variation control", "ptxt");
si[i++] = gsitm("N5020401U004EC00ENG.html", "ECM controls the accelerator pedal depression speed to make it slower than actual speed. This causes a drop in accelerating performance and encourages the driver to repair malfunction.", "ptxt");
si[i++] = gsitm("N5020401U004EC00ENG.html", "ECM does not control the accelerator releasing speed.", "ptxt");
