si[i++] = gsitm("N5020401W0026S00ENG.html", "Reconnect the initial spark plugs.", "ptxt");
si[i++] = gsitm("N5020401W0026S00ENG.html", "Crank engine for about 3 seconds, and recheck whether spark is generated between the spark plug and the grounded portion.", "ptxt");
