si[i++] = gsitm("N5020401U004EM00ENG.html", "DTC Description", "title");
si[i++] = gsitm("N5020401U004EM00ENG.html", "DTC DETECTION LOGIC", "title");
si[i++] = gsitm("N5020401U004EM00ENG.html", "The ECM monitors the switching frequency ratio of air fuel ratio (A/F) sensor 1 and heated oxygen sensor 2.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "A three way catalyst (manifold) with high oxygen storage capacity will indicate a low switching frequency of heated oxygen sensor 2. As oxygen storage capacity decreases, the heated oxygen sensor 2 switching frequency will increase.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "When the frequency ratio of air fuel ratio (A/F) sensor 1 and heated oxygen sensor 2 approaches a specified limit value, the three way catalyst (manifold) malfunction is diagnosed.", "ptxt");
