si[i++] = gsitm("N5020401U004EM00ENG.html", "If not, warm up engine and go to next step when “Coolant temperature sensor” indication reaches to 70°C (158°F).", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "Open engine hood.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "Select \"SRT STATUS\" mode of \"ENGINE\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "Rev engine up to 2,500 to 3,000 rpm and hold it for 3 consecutive minutes then release the accelerator pedal completely.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "Check the indication of “Catalyst”.", "ptxt");
si[i++] = gsitm("N5020401U004EM00ENG.html", "Which is displayed on M.U.T.-III SE screen?", "question");
