si[i++] = gsitm("N5022405C0000J00ENG.html", "Do not use M.U.T.-III SE to release fuel pressure, or fuel pressure applies again during the following procedure.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "After engine stalls, crank it 2 or 3 times to release all fuel pressure.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Remove all ignition coil harness connectors to avoid the electrical discharge from the ignition coils.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Remove ignition coil and spark plug of the cylinder to be checked.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Crank engine for 5 seconds or more to remove combustion gas in the cylinder.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Connect spark plug and harness connector to ignition coil.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Fix ignition coil using a rope etc. with gap of 13 - 17 mm (0.52 - 0.66 in) between the edge of the spark plug and grounded metal portion as shown in the figure.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Crank engine for approximately 3 seconds, and check whether spark is generated between the spark plug and the grounded metal portion.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "Spark should be generated.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "During the operation, always stay 0.5 m (19.7 in) or more away from the spark plug and the ignition coil. Be careful not to get an electrical shock while checking, because the electrical discharge voltage becomes 20 kV or more.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "It might cause to damage the ignition coil if the gap of more than 17 mm (0.66 in) is taken.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "When the gap is less than 13 mm (0.52 in), the spark might be generated even if the coil is malfunctioning.", "ptxt");
si[i++] = gsitm("N5022405C0000J00ENG.html", "INSPECTION END", "ptxt");
