si[i++] = gsitm("N5020401G0006800ENG.html", "Description", "title");
si[i++] = gsitm("N5020401G0006800ENG.html", "FUEL CUT CONTROL (AT NO LOAD AND HIGH ENGINE SPEED)", "title");
si[i++] = gsitm("N5020401G0006800ENG.html", "If the status of that the engine speed is above 2,500 rpm under no load (at 0 km/h and the selector lever position is P or N) takes more than the specified time, fuel will be cut off after some time. The exact time when the fuel is cut off varies based on engine speed.Fuel cut will be operated until the engine speed falls below 2,000 rpm.", "ptxt");
si[i++] = gsitm("N5020401G0006800ENG.html", "This function is different from deceleration control listed under direct injection gasoline system, refer to .", "ptxt");
si[i++] = gsitm("N5020401G0006800ENG.html", "Fuel cut when the accelerator pedal is fully depressed.", "title");
si[i++] = gsitm("N5020401G0006800ENG.html", "When starts the engine with fully depressing the accelerator pedal, in order to eliminate the spark plug fouling, performs fuel cut while cranking and prevent the engine from starting. The fuel cut continues until the accelerator pedal is released.", "ptxt");
