si[i++] = gsitm("N5020502Z0000G00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
