si[i++] = gsitm("N502050210000F00ENG.html", "General Precautions", "title");
si[i++] = gsitm("N502050210000F00ENG.html", "When replacing fuel line parts, be sure to observe the following.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Put a \"CAUTION: FLAMMABLE\" sign in the workshop.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Be sure to work in a well ventilated area and furnish workshop with a CO2 fire extinguisher.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Never smoke while servicing fuel system. Keep open flames and sparks away from the work area.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Use gasoline required by the regulations for octane number. Refer to .", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Before removing fuel line parts, perform out the following procedures:", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Put drained fuel in an explosion-proof container and put the lid on securely. Keep the container in safe area.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Release fuel pressure from the fuel lines. Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Disconnect the battery cable from the negative terminal.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Always replace O-ring and clamps with new ones.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Never bend or twist tubes when they are being installed.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Never tighten hose clamps excessively to avoid damaging hoses.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "After installing tubes, check that there is no fuel leakage at connections in the following steps.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Apply fuel pressure to fuel lines with turning ignition switch \"ON\" (with engine stopped). Then check for fuel leakage at connections.", "ptxt");
si[i++] = gsitm("N502050210000F00ENG.html", "Start engine and rev it up and check for fuel leakage at connections.", "ptxt");
si[i++] = gsitm("N5020409R0001300ENG.html", "Special Service Tools", "title");
