si[i++] = gsitm("N502050340002000ENG.html", "Read \"General Precautions\" when working on the fuel system. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N502050340002000ENG.html", "2WD", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Perform the operation with vehicle on level ground.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Release fuel pressure. Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Open fuel filler lid.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Insert a general purpose pipe with the dimensions shown in fuel filler cap less unit and release the pressure inside the fuel tank.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "A", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Over Φ 16 mm (0.63 in)", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "B", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Φ 21.0 mm (0.83 in)", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "C", "par8");
si[i++] = gsitm("N502050340002000ENG.html", ": 150 mm (5.91 in)", "par9");
si[i++] = gsitm("N502050340002000ENG.html", "Insert and hold 80 mm (3.15 in) from the end of the general purpose pipe into the fuel filler port.", "par24");
si[i++] = gsitm("N502050340002000ENG.html", "Check fuel level on a level ground. If the fuel level is 7/8 of the fuel tank (full or nearly full), draw appropriate amount of fuel from the fuel tank.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Guideline", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Draw approximately 15 liters (3-2/8 Imp gal) from a full-tank condition.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "In the event of malfunction in fuel pump, insert a hose measuring 16 mm (0.63 in) in diameter into the filler opening to draw approximately 15 liters (3-2/8 Imp gal) fuel.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove second seat.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove inspection hole cover.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Using a screwdriver, remove it by turning clips clockwise by 90 degrees.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Disconnect harness connector  and quick connector .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Fuel feed tube", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Fuel level sensor unit, fuel filter and fuel pump assembly", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Disconnect quick connector as follows:", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Hold the sides of connector, push in tabs  and pull out fuel feed tube.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Pull", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "If quick connector sticks to tube of fuel level sensor unit, fuel filter and fuel pump assembly, push and pull quick connector several times until they start to move. Then disconnect them by pulling.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Quick connector  can be disconnected when the tabs  are completely depressed. Never twist it more than necessary.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Connection (cross-section)", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": To under floor fuel line", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": To fuel tank", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Disconnection", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never use any tools to disconnected quick connector.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Keep resin tube  away from heat. Be especially careful when welding near the resin tube.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Prevent acid liquid such as battery electrolyte, etc. from getting on resin tube.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never bend or twist resin tube during installation and disconnection.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never remove the remaining retainer  on hard tube (or the equivalent)  except when resin tube or retainer is replaced.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "When resin tube or hard tube (or the equivalent) is replaced, also replace retainer with new one.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "To keep the connecting portion clean and to avoid damage and foreign materials, cover them completely with plastic bags  or something similar.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove crossmember assembly &lt;Vehicles for 5 persons>.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove lock ring according to the following instructions:", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install pawl (B) of unified fuel lock ring wrench [SST: KV101207S0 ( - )] (A) to the position shown in the figure.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Temporarily tighten mounting bolt (B) of the pawl according to the measurement (R) from the center of unified fuel lock ring wrench [SST: KV101207S0 ( - )] (A) to the end of pawl (C).", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "R", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": 82 mm (3.23 in)", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Set unified fuel lock ring wrench [SST: KV101207S0 ( - )] to lock ring and tighten the mounting bolt of the pawl.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove lock ring.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "To prevent lock ring wrench from being detached, securely hold down spinner handle by hand.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "To reduce impact caused by removal operation, use long spinner handle [handle length: 60 cm (23.62 in) or more] and slowly turn it counterclockwise.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Remove fuel level sensor unit, fuel filter and fuel pump assembly.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "4WD", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Raise fuel level sensor unit, fuel filter and fuel pump assembly.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never bend float arm during removal.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never pollute the inside by residue fuel. Draw out avoiding inclination by supporting with a cloth.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never cause impacts such by dropping when handling components.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Separate fuel tube as per the following steps to remove fuel level sensor unit, fuel filter and fuel pump assembly.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Disconnect harness connector .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Pinch quick connector  square-part with your fingers, and pull out the quick connector by hand.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "If quick connector and tube on sender unit are stuck, push several times until they move, and pull out.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "When separating the fuel tube, tie a gasoline-resistance rope to the tip of the fuel tube and leave the rope on the fuel tank side to easily pull the fuel tube for installation.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Sub Fuel Level Sensor Assembly", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Remove sub fuel level sensor assembly .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never disassemble a fuel tube  from sub fuel sensor assembly.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Tie a gasoline-resistance rope to a tip of the tube. Draw and leave the rope to the fuel tank side so that the rope can be the guide for installation.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Note to the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Fuel Level Sensor Unit, Fuel Filter and Fuel Pump Assembly", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Install new O-ring to fuel tank without any twist.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Do not reuse O-rings.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install the fuel level sensor unit, fuel filter and fuel pump assembly on the fuel tank with the fuel level sensor unit, fuel filter and fuel pump assembly face  faced the shown in the figure against the arrow vehicle front.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never allow seal packing to drop.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never bend float arm during installing.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install lock ring for fuel level sensor unit, fuel filter and fuel pump assembly with unified fuel lock ring wrench [SST: KV101207S0] ( - ) by turning clockwise.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install lock ring horizontally.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Turn the lock ring  until it is engaged in the fuel tank side  as shown in the figure.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Connect quick connector of fuel feed tube as per following procedures.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Check the connection for damage or any foreign materials.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Align the connector with the tube, then insert the connector straight into the tube until a \"click\" sound is heard.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "After connecting, check that the connection is secured with following procedures.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Visually confirm that the two tabs are connected to the connector.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Pull  the tube and the connector to check that they are securely connected.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Connect harness connector.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Inspection Hole Cover", "title");
si[i++] = gsitm("N502050340002000ENG.html", "Before installing inspection hole cover, check that the connecting part has no fuel leakage. Refer to Inspection .", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install inspection hole covers with the front mark (arrow) facing front of vehicle.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Lock clips by turning counterclockwise.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Using the rope left on the fuel tank side at removal, run the fuel tube inside the fuel tank to install the sub fuel level sensor assembly to the fuel tank.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Never bend float arm during installation.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "To install, fuel tube  must run to the front () of the vehicle to avoid the interference with the float arm , as shown in the figure.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install the sub fuel level sensor assembly on the fuel tank with the fuel level sensor unit, fuel filter and fuel pump assembly face  faced the shown in the figure against the arrow vehicle front.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Install lock ring for sub fuel level sensor assembly with unified fuel lock ring wrench [SST: KV101207S0 ( - )] by turning clockwise.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Connect the fuel tube as per the following steps.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Insert the quick connector  straight to the fuel level sensor unit, fuel filter and fuel pump assembly.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Judge a good fit from connecting sound and tactile feedback.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Pull the fuel tube by hand to check a secure fit.", "ptxt");
si[i++] = gsitm("N502050340002000ENG.html", "Connect harness connector .", "ptxt");
