si[i++] = gsitm("N5020602P0000G00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5020602P0000G00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5020602P0000G00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Be sure to use genuine exhaust system parts or equivalents which are specially designed for heat resistance, corrosion resistance, and shape.", "ptxt");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Perform the operation with the exhaust system fully cooled down because the system will be hot just after engine stops.", "ptxt");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Be careful not to cut your hand on the heat insulator edge.", "ptxt");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Never use silicon-containing products (e.g. oil) to prevent malfunctions such as the interference with the conduction of electricity and the occurrence of noise in the radio.", "ptxt");
si[i++] = gsitm("N5020602T0000W00ENG.html", "Prevent rust preventives from adhering to the sensor body.", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N5020409R0001400ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Tool number", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "KV10114400", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Heated oxygen sensor wrench", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "Loosening or tightening heated oxygen sensor 2", "ptxt");
si[i++] = gsitm("N5020409R0001400ENG.html", "a: For 22 mm (0.87 in) width hexagon nut", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Commercial Service Tools", "title");
si[i++] = gsitm("N502040110000P00ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Power tool", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Loosening nuts and bolts", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Heated oxygen sensor thread cleaner", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Reconditioning the exhaust system threads before installing a new heated oxygen sensor (Use with anti-seize lubricant shown below.)", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "A: J-43897-18 [18 mm (0.71 in) dia.] for zirconia heated oxygen sensor", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "B: J-43897-12 [12 mm (0.47 in) dia.] for titania heated oxygen sensor", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "C: Mating surface shave cylinder", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "D: Flutes", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Anti-seize lubricant (Permatex 133AR or equivalent meeting MIL specification MIL-A-907)", "ptxt");
si[i++] = gsitm("N502040110000P00ENG.html", "Lubricating heated oxygen sensor thread cleaner when reconditioning exhaust system threads", "ptxt");
si[i++] = gsitm("N502060200000X00ENG.html", "Inspection", "title");
si[i++] = gsitm("N502060200000X00ENG.html", "Check exhaust pipes, muffler, and mounting for improper attachment, leakage, cracks, damage or deterioration.", "ptxt");
si[i++] = gsitm("N502060200000X00ENG.html", "If anything is found, repair or replace damaged parts.", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5020601N0000L00ENG.html", "2WD", "title");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Gasket", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Stud bolt", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Exhaust front tube", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Heat insulator (upper)", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Mounting rubber", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Heated oxygen sensor 2", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Heat insulator (lower)", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "Main muffler", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "To exhaust manifold. Refer to .", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", ": N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", ": Indicates that the part is connected at points with same symbol in actual vehicle.", "ptxt");
si[i++] = gsitm("N5020601N0000L00ENG.html", "4WD", "title");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5020602T0000X00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Disconnect each joint and mounting.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Remove heated oxygen sensor 2 with following procedure.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Using heated oxygen sensor wrench [SST: KV10114400] (A), removal heated oxygen sensor 2 .", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", ": Exhaust front tube", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Discard any sensor which has been dropped from a height of more than 0.5 m (19.7 in) onto a hard surface such as a concrete floor; use a new one.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Always replace gaskets with new ones when reassembling.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Discard any heated oxygen sensor 2 which has been dropped onto a hard surface such as a concrete floor. Use a new one.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Before installing a new heated oxygen sensor 2, clean exhaust system threads using the heated oxygen sensor thread cleaner [commercial service tool (J-43897-18 or J-43897-12)] and apply anti-seize lubricant (commercial service tool).", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Never over torque heated oxygen sensor 2. Doing so may cause damage to the heated oxygen sensor 2, resulting in the “MIL” coming on.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "If heat insulator is badly deformed, repair or replace it. If deposits such as mud pile up on the heat insulator, remove them.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "When installing heat insulator avoid large gaps or interference between heat insulator and each exhaust pipe.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Remove deposits from the sealing surface of each connection. Connect them securely to avoid gas leakage.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Temporarily tighten mounting nuts and bolts. Check each part for unusual interference and mounting rubber interference, and then tighten them to the specified torque.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "When installing each mounting rubber, avoid twisting or unusual extension in up/down, front/rear and right/left directions.", "ptxt");
si[i++] = gsitm("N5020602T0000X00ENG.html", "Install the mounting rubber with the FR arrow mark facing the front of the vehicle.", "ptxt");
si[i++] = gsitm("N502060200000Y00ENG.html", "Inspection", "title");
si[i++] = gsitm("N502060200000Y00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N502060200000Y00ENG.html", "Check clearance between tail tube and rear bumper is even.", "ptxt");
si[i++] = gsitm("N502060200000Y00ENG.html", "With engine running, check exhaust tube joints for gas leakage and unusual noises.", "ptxt");
si[i++] = gsitm("N502060200000Y00ENG.html", "Check to ensure that mounting brackets and mounting rubbers are installed properly and free from undue stress. Improper installation could result in excessive noise and vibration.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5020204R0001100ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5020204R0001100ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5020204R0001100ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5020702W0000H00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5020702W0000H00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020700Q0000G00ENG.html", "Commercial Service Tools", "title");
si[i++] = gsitm("N5020700Q0000G00ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N5020700Q0000G00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5020700Q0000G00ENG.html", "Power tool", "ptxt");
si[i++] = gsitm("N5020700Q0000G00ENG.html", "Loosening bolts, nuts and screws", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N5020700W0000P00ENG.html", "Starter motor", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "Refer to Starter motor.", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "Refer to", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5020700W0000P00ENG.html", "Starter cut relay", "ptxt");
si[i++] = gsitm("N502070490000D00ENG.html", "Starter motor", "title");
si[i++] = gsitm("N502070490000D00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N502070490000D00ENG.html", "Starter motor is controlled by IPDM E/R and BCM.", "ptxt");
si[i++] = gsitm("N502070490000D00ENG.html", "Starter motor cranks engine.", "ptxt");
si[i++] = gsitm("N502070490000D00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N502070490000D00ENG.html", "Starter motor is run by 12V battery power and cranks engine.", "ptxt");
si[i++] = gsitm("N502070490000D00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N502070490000D00ENG.html", "When “S” terminal of starter motor  is supplied with electric power, starter motor plunger  closes and starter motor is supplied with 12V battery power via \"B\" terminal.", "ptxt");
si[i++] = gsitm("N502070490000D00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N502070490000D00ENG.html", "Starter motor is installed to front side of engine. Refer to .", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "System Description", "title");
si[i++] = gsitm("N5020703L0000H00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Starter motor", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Refer to Starter motor.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "CPU inside IPDM E/R controls starter relay.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Refer to", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "BCM controls starter cut relay.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Starter cut relay", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Power is supplied to the starter cut relay with BCM control.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5020703L0000H00ENG.html", "“B” terminal is constantly supplied with 12V battery power.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "When starter operating condition is satisfied, IPDM E/R turns starter relay ON by starter relay control signal.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "When engine cranking condition is satisfied, BCM turns starter cut relay ON by starter cut relay control signal.", "ptxt");
si[i++] = gsitm("N5020703L0000H00ENG.html", "Then 12V battery power is supplied to starter motor (“S” terminal) through starter cut relay and starter relay.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "WORK FLOW (WITH Multitasking battery and electrical diagnostic station (commercially-available tool))", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Starting System Diagnosis with Multitasking battery and electrical diagnostic station (commercially-available tool)", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "To test the starting system, use the Multitasking battery and electrical diagnostic station (commercially-available tool):", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Refer to the diagnostic station Instruction Manual for proper starting system diagnosis procedures.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Overall Sequence", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Detailed Flow", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "To ensure a complete and thorough diagnosis, the battery, starter motor and alternator test segments must be done as a set from start to finish.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "If any malfunction is found, immediately disconnect the battery cable from the negative terminal.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "DIAGNOSIS WITH Multitasking battery and electrical diagnostic station (commercially-available tool)", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Perform starting system test with Multitasking battery and electrical diagnostic station (commercially-available tool). For details and operating instructions, refer to diagnostic station Instruction Manual.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "How is the test result?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CRANKING NORMAL", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "LOW VOLTAGE", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHARGE BATTERY", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Perform the slow battery charging procedure. (Initial rate of charge is 10A for 12 hours.) Perform battery test again. Refer to diagnostic station instruction manual.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "REPLACE BATTERY", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Before replacing battery, clean the battery cable clamps and battery posts. Perform battery test again. Refer to diagnostic station instruction manual. If second test result is “REPLACE BATTERY”, then do so. Perform battery test again to confirm repair.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "COMPARISON BETWEEN ENGINE COOLANT AND CRANKING VOLTAGE", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Compare engine coolant temperature and the cranking voltage with the specifications.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Minimum Specification of Cranking Voltage Referencing Coolant Temperature", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Engine coolant temperature [°C (°F)]", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Voltage [V]", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "−30 to −20 (−22 to −4)", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "8.6", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "−19 to −10 (−2 to 14)", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "9.1", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "−9 to 0 (16 to 32)", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "9.5", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "More than 1 (More than 34)", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "9.9", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Is the voltage less than the specified value?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "YES", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "NO", "result");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHECK ENGINE START", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Crank engine and check that engine starts.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Does engine start?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHECK RETURN OF PINION GEAR", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check that pinion gear returns to original position after engine starts.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Does pinion gear return?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Starter motor is OK. INSPECTION END", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHECK ENGINE SPEED WITH CRANKING", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check that engine turns while cranking.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Does engine turn by cranking?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHECK STARTER MOTOR TURNING WITH CRANKING", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check that starter motor runs smoothly without abnormal noise at cranking.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Does starter motor turn normally?", "question");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check ignition/fuel system.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check engine mechanical and power train system.", "ptxt");
si[i++] = gsitm("N5020703U0000D00ENG.html", "CHECK STARTER MOTOR SPEED WITH CRANKING", "title");
si[i++] = gsitm("N5020703U0000D00ENG.html", "Check that starter motor turns while cranking.", "ptxt");
