si[i++] = gsitm("N502070220000J00ENG.html", "Remove starter motor from vehicle. Refer to .", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Connect 12V battery to starter motor as shown in the figure. Check that pinion gear  is driven out by magnetic switch.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Replace magnetic switch if pinion gear does not driven out.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Disconnect “M” terminal as shown in the figure. Check that pinion gear  does not return to original position.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Replace magnetic switch if pinion gear returns.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Disconnect (-) wire from starter motor body as shown in the figure. Check that pinion gear  returns to original position.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Replace magnetic switch if pinion gear does not return.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "PINION PROTRUSION LENGTH", "title");
si[i++] = gsitm("N502070220000J00ENG.html", "Compare movement “L” in height of pinion gear  when it is pushed out with magnetic switch energized and when it is pulled out by hand until it touches stopper.", "ptxt");
