si[i++] = gsitm("N502070220000J00ENG.html", "Replace starter motor if the measurement value is not within specifications.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "PINION CLUTCH", "title");
si[i++] = gsitm("N502070220000J00ENG.html", "Check pinion gear teeth.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Replace pinion assembly if teeth are worn or damaged. (Also check condition of ring gear teeth.)", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Check to see if pinion locks in one direction and rotates smoothly in the opposite direction.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "Replace pinion assembly if it is locked, rotates in both directions or unusual resistance is evident.", "ptxt");
si[i++] = gsitm("N502070220000J00ENG.html", "NO-LOAD TEST", "title");
