si[i++] = gsitm("N502391040001800ENG.html", "For the engine hanger balancer (MB991454), use the chain only.", "ptxt");
si[i++] = gsitm("N502391040001800ENG.html", "Engine hanger balancer (MB991454) is a part of the engine hanger attachment set (MB991453).", "ptxt");
