si[i++] = gsitm("N502391060000P00ENG.html", "INSPECT ENGINE LOW RPM AND ACCELERATION CONDITIONS", "title");
si[i++] = gsitm("N502391060000P00ENG.html", "When the engine is warmed up, check to see if the RPM continues smoothly while idling. When a tachometer is used, check it whether idle speed is in the range of the standard value.", "ptxt");
si[i++] = gsitm("N502391060000P00ENG.html", "Gradually increase the engine RPM and make sure it runs smoothly without any engine stalls or knocking etc.", "ptxt");
si[i++] = gsitm("N502391070000T00ENG.html", "EXHAUST GAS CONDITION INSPECTION", "title");
si[i++] = gsitm("N502391070000T00ENG.html", "When the engine is warmed up, visually inspect whether the color of the exhaust gas is white smoke or black smoke.", "ptxt");
si[i++] = gsitm("N502391550000I00ENG.html", "DRIVE BELT DAMAGE CHECK", "title");
si[i++] = gsitm("N502391550000I00ENG.html", "Remove the engine room side cover RH (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502391550000I00ENG.html", "Inspect visually and by touch completely for significant wear, damage, or cracks on the side surfaces.", "ptxt");
si[i++] = gsitm("N502391090000H00ENG.html", "DRIVE BELT TENSION CHECK AND ADJUSTMENT", "title");
si[i++] = gsitm("N502391090000H00ENG.html", "Make sure that the indicator mark on the drive belt auto-tensioner is within the area marked with A in the illustration.", "ptxt");
si[i++] = gsitm("N502391090000H00ENG.html", "Check the drive belt tension after turning the crankshaft clockwise one turn or more.", "ptxt");
si[i++] = gsitm("N502391090000H00ENG.html", "If the mark is out of the area A, replace the drive belt (Refer to ).", "ptxt");
si[i++] = gsitm("N502391090000H00ENG.html", "The drive belt tension adjustment is not necessary as the drive belt auto-tensioner is adopted.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "DRIVE BELT AUTO-TENSIONER CHECK", "title");
si[i++] = gsitm("N502391120000B00ENG.html", "OPERATION CHECK", "title");
si[i++] = gsitm("N502391120000B00ENG.html", "Stop the engine from the idle state.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Check that the drive belt are not protruding from the pulley width of drive belt auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Securely set the tool to the hexagonal part of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Recommended tool:", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "KTC Ratchet box end wrench (Extra long flex) (No. MR15L-14F)", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Check that no binding is present by turning the auto-tensioner in the left directions.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Be sure to set the tool to the hexagonal part securely to prevent the tool from falling off because the tension of the auto-tensioner is high.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Be sure to rotate the auto-tensioner counterclockwise because the hexagonal part may be broken if the auto-tensioner is rotated clockwise.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "In order to prevent damage to the pulley of the auto-tensioner, do not rotate the pulley until it interferes with the installation area of the auto-tensioner of the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "In order to prevent breakage of the spring of the auto-tensioner, do not touch the spring when checking the movement of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "If there are any problems in the procedure 2 or 4, replace the drive belt auto-tensioner (Refer to ).", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "FUNCTION CHECK", "title");
si[i++] = gsitm("N502391120000B00ENG.html", "The drive belt auto-tensioner can be checked whether it is in good condition by checking its tension.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "&lt;When the vibration frequency is measured: Recommendation>", "title");
si[i++] = gsitm("N502391120000B00ENG.html", "Check the tension of the drive belt (Refer to ).", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Gently tap the middle of the drive belt between the pulleys (the place indicated by the arrow) with your finger as shown in the illustration.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "When measuring, make sure that the engine is cold.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Measure after turning the crankshaft clockwise one turn or more.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Do not let any contaminants such as water or oil get onto the microphone.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "If strong gusts of wind blow against the microphone or if there is loud sources of noise nearby, the values measured by the microphone may not correspond to actual values.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "If the microphone is touching the belt while the measurement is being made, the values measured by the microphone may not correspond to actual values.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Do not take the measurement while the vehicle\'s engine is running.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Check that the vibration frequency of the drive belt is within the standard value.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Standard value (Reference): 117 - 153 Hz", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "To take the measurement repeatedly, fillip the drive belt again.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "If not within the standard value, replace the drive belt auto-tensioner (Refer to ).", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "&lt;When tension is measured>", "title");
si[i++] = gsitm("N502391120000B00ENG.html", "Use a belt tension gauge in the middle of the drive belt between the pulleys shown in the figure (at the place indicated by the arrow) to check that the drive belt tension is within the standard value.", "ptxt");
si[i++] = gsitm("N502391120000B00ENG.html", "Standard value (Reference): 235 - 406 N", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "IGNITION TIMING CHECK", "title");
si[i++] = gsitm("N502391130000W00ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Start the engine and let it run at idle.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Select the item No. 3 on M.U.T.-III SE and measure engine idle speed and check that it is approximately 850 r/min.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Select No. 4 (actuator test function) of the M.U.T.-III SE, and set the ignition timing to the basic ignition timing.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Check that basic ignition timing is within the standard value.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Standard value: 6° BTDC ± 3°", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "If the basic ignition timing is outside the standard value, inspect the MFI system (Refer to Engine - DI and MPI - Troubleshooting - Inspection Chart for Trouble symptoms ).", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Cancel the actuator test function item No. 4, Basic ignition timing set mode, on M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "If the test is not cancelled, a forced driving will continue for 27 minutes. Driving under this condition may damage the engine.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Check that ignition timing is at the standard value.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Standard value: approximately 10° BTDC", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "The ignition timing may fluctuate within ± 7°. This is normal.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "In higher altitude, the ignition timing is more advanced than the standard value by approximately 5°.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Wait till approximately 1 minute passes after the engine started, and check the ignition timing when the engine stabilized.", "ptxt");
si[i++] = gsitm("N502391130000W00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then disconnect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "CURB IDLE SPEED CHECK", "title");
si[i++] = gsitm("N502391140000H00ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Start the engine and let it run at idle.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Check that ignition timing is at the standard value.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Standard value: approximately 10° BTDC", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "The ignition timing may fluctuate within ±7°. This is normal.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "In higher altitude, the ignition timing is more advanced than the standard value by approximately 5°.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Wait till approximately 1 minute passes after the engine started, and check the ignition timing when the engine stabilized.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Check the idle speed.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Standard value: 850 ± 100 r/min", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "The idle speed is controlled automatically by the idle speed control system.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "When using the M.U.T.-III SE, select item No. 3 and take a reading of the idle speed.", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "If the idle speed is outside the standard value, inspect the MFI system (Refer to Engine - DI and MPI - Troubleshooting - Inspection Chart for Trouble Symptoms ).", "ptxt");
si[i++] = gsitm("N502391140000H00ENG.html", "Turn the ignition switch to \"LOCK\" (OFF) position and then disconnect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "IDLE MIXTURE CHECK", "title");
si[i++] = gsitm("N502391150000V00ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Start the engine and let it run at idle.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Check that ignition timing is at the standard value.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Standard value: approximately 10° BTDC", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "The ignition timing may fluctuate within ±7°. This is normal.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "In higher altitude, the ignition timing is more advanced than the standard value by approximately 5°.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Wait till approximately 1 minute passes after the engine started, and check the ignition timing when the engine stabilized.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Run the engine at 2,000 - 3,000 r/min for 2 minutes.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Set the CO, HC tester.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Check the CO contents and the HC contents at idle.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Standard value", "title");
si[i++] = gsitm("N502391150000V00ENG.html", "CO contents: 0.5 % or less", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "HC contents: 100 ppm or less", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "If there is a deviation from the standard value, inspect the MFI system (Refer to Engine - DI and MPI - Troubleshooting - Inspection Chart for Trouble Symptoms )", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Remove the CO, HC tester.", "ptxt");
si[i++] = gsitm("N502391150000V00ENG.html", "Turn the ignition switch to \"LOCK\" (OFF) position and then disconnect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "VALVE CLEARANCE CHECK AND ADJUSTMENT", "title");
si[i++] = gsitm("N502391160000S00ENG.html", "Perform the valve clearance check and adjustment at the engine cold state.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Remove the cylinder head cover assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Turn the crankshaft clockwise, and set the protrusion of the camshaft as shown in the figure. Therefore, No.1 cylinder goes to the compression top dead center.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Turn the crankshaft always clockwise.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Using a thickness gauge, measure the valve clearance with the arrow shown in Figure. If deviated from the standard value, make note for the valve clearance.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Standard value (cold engine)", "title");
si[i++] = gsitm("N502391160000S00ENG.html", "Intake side: 0.22 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Exhaust side: 0.30 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Turn the crankshaft clockwise 360 degrees. Therefore, No.4 cylinder goes to the compression top dead center.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Check the valve clearance with the arrow shown in Figure. In the same procedure as 3.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "If the valve clearance is deviated from the standard value, remove the camshaft and the valve tappet. (Refer to ).", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Using a micrometer, measure the thickness of the removed valve tappet.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Calculate the thickness of the newly installed valve tappet through the following equation.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "A: thickness of newly installed valve tappet", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "B: thickness of removed valve tappet", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "C: measured valve clearance", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Equation", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Intake valve: A = B + (C - 0.22 mm)", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Exhaust valve: A = B + (C - 0.30 mm)", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Every valve tappet has an identification mark stamped at the illustrated location.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Valve tappets are available in 31 sizes, at 0.020 mm intervals in the 2.700 - 3.300 mm range, as shown in the following table.", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Thickness mm", "ptxt");
