si[i++] = gsitm("N502391160000S00ENG.html", "Install the valve tappet selected through the procedure 8 to 10, and put the camshaft in position. (Refer to ).", "ptxt");
si[i++] = gsitm("N502391160000S00ENG.html", "Install the cylinder head cover assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "COMPRESSION PRESSURE CHECK", "title");
si[i++] = gsitm("N502391170000X00ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Remove all of the ignition coils and spark plugs (Refer to Engine - Engine Electrical - Ignition System - Ignition Coil ).", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Disconnect the all of the injector connectors.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Cover the spark plug hole with a shop towel etc., and after the engine has been cranked, check that no foreign material is adhering to the shop towel.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Keep away from the spark plug hole when cranking.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If compression is measured with water, oil, fuel, etc., that has come from cracks inside the cylinder, these materials will become heated and will gush out from the spark plug hole, which is dangerous.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Set compression gauge to one of the spark plug holes.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Cranking the engine with the accelerator pedal fully depressed, measure the compression pressure.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Standard value (at engine speed of 250 r/min): 1,560 kPa", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Limit (at engine speed of 250 r/min): Minimum 1,110 kPa", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Measure the compression pressure for all the cylinders, and check that the pressure differences of the cylinders are below the limit.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Limit: Maximum 100 kPa", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If there is a cylinder with compression or a compression difference that is outside the limit, pour a small amount of engine oil through the spark plug hole, and repeat the operations in steps from 5 to 7.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If the compression increases after oil is added, the cause of the malfunction is a worn or damaged piston ring and/or cylinder inner surface.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If the compression does not rise after oil is added, the cause is a burnt or defective valve seat, or pressure is leaking from the gasket.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "Install the spark plugs and ignition coils (Refer to Engine - Engine Electrical - Ignition System - Ignition Coil ).", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If a diagnostic trouble code or a provisional diagnostic trouble code is set by the check, erase the diagnostic trouble code or the provisional diagnostic trouble code using the M.U.T.-III SE (Refer to Engine - DI and MPI – Troubleshooting – Diagnostic Function ).", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "This will erase the diagnostic trouble code or the provisional diagnostic trouble code resulted from the injector connector being disconnected.", "ptxt");
si[i++] = gsitm("N502391170000X00ENG.html", "If a diagnostic trouble code or a provisional diagnostic trouble code is set, engine start is prohibited by the fail-safe control.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "MANIFOLD VACUUM CHECK", "title");
si[i++] = gsitm("N502391180000N00ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Turn the ignition switch to \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Disconnect the PCV hose from the PCV valve, and then connect a vacuum gauge to the PCV hose. Plug the PCV valve.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Start the engine and check that idle speed is approximately 850 r/min.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Check the intake manifold vacuum.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Limit: Minimum 75 kPa", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Turn off the ignition switch.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Remove the vacuum gauge and then connect the PCV hose to the PCV valve.", "ptxt");
si[i++] = gsitm("N502391180000N00ENG.html", "Remove the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Pre-removal and Post-installation operation", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Engine Room Under Cover Front B and Engine Room Side Cover RH Removal and Installation (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Drive belt Tension Check and Adjustment (Refer to ) &lt;Only at Post-installation Operation>.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Front Fender Protector RH Removal and Installation (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Front Fender Protector/Rear Wheel House Protector ).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "A/C Heat Exchanger Pipe Bracket Removal and Installation (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - Refrigerant Line ).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Front Washer Tank Inlet Removal and Installation (Refer to Driver Controls - Wiper and Washer - Removal and Installation - Washer Tank ).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Auto-tensioner", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Drive belt", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;C>>", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Crankshaft pulley center bolt", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Crankshaft pulley washer", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Torsional vibration damper", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;D>>", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Crankshaft isolation pulley", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;A>> AUTO-TENSIONER REMOVAL", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Disconnect the belt drive starter generator ground cable (Refer to Engine - Engine Electrical - Charging System - Belt Drive Starter Generator ).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Follow the steps below to release the tension of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Securely set the tool to the hexagonal part of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Recommended tool:", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "KTC Ratchet box end wrench (Extra long flex) (No. MR15L-14F)", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Rotate the auto-tensioner counterclockwise.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Be sure to set the tool to the hexagonal part securely to prevent the tool from falling off because the tension of the auto-tensioner is high.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Be sure to rotate the auto-tensioner counterclockwise because the hexagonal part may be broken if the auto-tensioner is rotated clockwise.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "In order to prevent damage to the pulley of the auto-tensioner, do not rotate the pulley until it interferes with the installation area of the auto-tensioner of the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "In order to prevent breakage of the spring of the auto-tensioner, do not touch the spring when checking the movement of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Secure the auto-tensioner by inserting a hexagonal wrench (4 mm) or the like in the right hole of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Remove the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;Auto-tensioner removal procedure for when the drive belt is broken>", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Rotate the auto-tensioner, and insert a hexagonal wrench (4 mm) or the like into the left hole to secure the auto-tensioner in the groove of the auto-tensioner bracket.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Do not insert a hexagonal wrench or the like too deeply as it may interfere with rotation of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Slightly rotate the auto-tensioner counterclockwise, and remove the hexagonal wrench or the like which is inserted into the left hole.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;B>> DRIVE BELT REMOVAL", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "To reuse the drive belt, draw an arrow indicating the rotating direction on the back of the belt using chalk to install the same direction.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;C>> CRANKSHAFT PULLEY CENTER BOLT / CRANKSHAFT PULLEY WASHER / TORSIONAL VIBRATION DAMPER REMOVAL", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Assemble the following special tools and the nuts (M12 × 1.25).", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Pulley holder (MB991800)", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Pin (MB992100)", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Set each nut to the position where it is flush with the tip of the pin.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Use the special tools to support the torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Apply the special tool to the torsional vibration damper securely to prevent the tool from coming off.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Loosen the crankshaft pulley center bolt, remove the crankshaft pulley washer and torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "If the torsional vibration damper and the crankshaft isolation pulley came off together, separate them by hands. If they cannot be separated by hands, clean the connection part.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "&lt;&lt;D>> CRANKSHAFT ISOLATION PULLEY REMOVAL", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "If the crankshaft isolation pulley cannot be removed from the crankshaft by hands, remove it by following the steps below.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Use an inner-claw type bearing puller. If the crankshaft isolation pulley is removed with other tools, replace the pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Insert the bearing puller into the crankshaft isolation pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Bearing puller dimension", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "Diameter of claw at the tip (A)", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When the bearing puller is inserted: 16.8 mm or less", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When engaged: 17.4 mm or more", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Amount of insertion (B): 20 to 24 mm", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Engage the claw at the tip of the bearing puller with the crankshaft isolation pulley to secure the pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Install the slide hammer to the bearing puller, and remove the crankshaft isolation pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "If the claw of the bearing puller has stopped in the hole of the crankshaft isolation pulley, replace the pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "After wiping off the dirt on the installation surfaces of the crankshaft isolation pulley and the crankshaft, degrease the installation surfaces.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", ">>A&lt;&lt; CRANKSHAFT ISOLATION PULLEY / TORSIONAL VIBRATION DAMPER / CRANKSHAFT PULLEY WASHER / CRANKSHAFT PULLEY CENTER BOLT INSTALLATION", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "If the part to be installed cannot be inserted smoothly, replace the part.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Wipe off the dirt on the crankshaft as shown in the figure using a rag.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Wipe off the dirt on the oil pump drive shaft, crankshaft isolation pulley and torsional vibration damper as shown in the figure using a rag, and then degrease the areas.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Degrease them to prevent drop in the friction coefficient of the pressed area which is caused by oil adhesion.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Insert the pin of the crankshaft isolation pulley into the pin hole of the torsional vibration damper, and install them to the crankshaft.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When installing the crankshaft isolation pulley and the torsional vibration damper, do not insert them forcibly with the axial force of the bolt. If the bolt cannot be seated by hand, replace the parts.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Wipe off the dirt on the crankshaft pulley washer and the crankshaft pulley center bolt as shown in the figure using a rag.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Apply an adequate and minimum amount of engine oil to the thread of the crankshaft pulley center bolt and the lower area of the flange.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Use the following special tools and nut (M12 × 1.25) as during removal to support the torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tighten the crankshaft pulley center bolt as follows:", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tighten the crankshaft pulley center bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tightening torque: 90 N·m", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tighten the crankshaft pulley center bolt in a 90°.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When the tightening angle is smaller than the specified tightening angle, the appropriate tightening capacity cannot be secured.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When the tightening angle is larger than the specified tightening angle, remove the bolt to start from the beginning again according to the procedure.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Loosen the crankshaft pulley center bolt completely.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", ">>B&lt;&lt; DRIVE BELT / AUTO-TENSIONER INSTALLATION", "title");
si[i++] = gsitm("N502391200000Z00ENG.html", "To reuse the drive belt, install it by aligning the arrow mark on the backside of belt marked at the removal with the rotating direction.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Check that the notches of the notched pulley and the notches of the drive belt are fit correctly.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Check that the drive belt is installed in the center of the flat surface of the flat pulley.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Install the drive belt to each pulley as shown in the figure.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "When installing the drive belt, be sure to set the belt drive starter generator bracket side of the idler pulley at the end.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tighten the auto-tensioner mounting bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Tightening torque: 25 ± 3 N·m", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Apply tension to the drive belt as follows:", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Slightly rotate the auto-tensioner counterclockwise.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Remove the hexagonal wrench (4 mm) or the like which is inserted into the right hole of the auto-tensioner.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Apply tension to the drive belt while slowly turning the auto-tensioner clockwise.", "ptxt");
si[i++] = gsitm("N502391200000Z00ENG.html", "Connect the belt drive starter generator ground cable (Refer to Engine - Engine Electrical - Charging System - Belt Drive Starter Generator ).", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502391280000L00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Inlet oil feeder control valve", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "O-ring", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Exhaust oil feeder control valve", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502391280000L00ENG.html", ">>A&lt;&lt; O-RING / ENGINE OIL CONTROL VALVE INSTALLATION", "title");
si[i++] = gsitm("N502391280000L00ENG.html", "Apply a little amount of engine oil to the O-ring of engine oil control valve.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Do not reuse the O-ring.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Install the O-ring after wrap a tape not having adhesion (such as a seal tape) round the notch on the oil passage of engine oil control valve to prevent it from damage. The damaged O-ring may cause oil leakage.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Remove the tape before installing engine oil control valve.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Install the engine oil control valve to the engine support bracket.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "To install the engine oil control valve, be careful to keep foreign material from entering oil channels.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "When installing the engine oil control valve to the cylinder head, check the engine oil control valve filter for foreign matters attached, defects and deformation.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Tighten the mounting bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502391280000L00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502391370000K00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N502391370000K00ENG.html", "Ignition Coil Removal and Installation (Refer to Engine - Engine Electrical - Ignition System - Ignition Coil ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Throttle Body Assembly Removal and Installation (Refer to Engine - DFI and MPI - Throttle Body Assembly ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Removal steps", "ptxt");
