si[i++] = gsitm("N502391370000K00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Intercooler radiator reservoir tank assembly", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Breather hose", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "•", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "PCV hose connection (Refer to Engine - Intake and Exhaust - Intake Manifold ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Intercooler coolant temperature sensor housing bracket (Refer to Engine - Intake and Exhaust - Intercooler Water Hose and Water Pipe ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Brake booster vacuum hose (Refer to ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Fuel injection tube connection (Refer to Engine - DI and MPI - Injector ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "PCV hose connection", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Cylinder head cover assembly", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Cylinder head cover gasket", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502391370000K00ENG.html", "&lt;&lt;A>> INTERCOOLER RADIATOR RESERVOIR TANK REMOVAL", "title");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the A/C heat exchanger pipe bracket (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - Refrigerant Line ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the front washer tank inlet (Refer to Driver Controls - Wiper and Washer - Removal and Installation - Washer Tank ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the intercooler radiator reservoir tank assembly mounting bolts (Refer to Engine - Intake and Exhaust - Intercooler Radiator Reservoir Tank ).", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the intercooler radiator reservoir tank assembly together with the intercooler water hose.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the intercooler and intercooler radiator reservoir tank assembly at a position where they will not interfere with the removal and installation of cylinder head cover assembly.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502391370000K00ENG.html", ">>A&lt;&lt; CYLINDER HEAD COVER ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the sealant from the cylinder head cover assembly and the matching area of the cylinder head assembly and the engine support bracket, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Remove the sealant from the cylinder head cover assembly and the matching area of the cylinder head assembly and the rear camshaft bearing cap, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Apply specified sealant to the matching area of the cylinder head assembly and the engine support bracket as shown.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Apply specified sealant to the matching area of the cylinder head assembly and the rear camshaft bearing cap as shown, and install the cylinder head cover assembly to the cylinder head assembly.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Install the cylinder head cover assembly immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Tighten the cylinder head cover assembly mounting bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Tightening torque: 3.0 ± 1.0 N·m", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Tighten again the cylinder head cover assembly mounting bolts to the specified torque in the order of number shown in the figure.", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "Tightening torque: 5.5 ± 0.5 N·m", "ptxt");
si[i++] = gsitm("N502391370000K00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "REMOVAL AND INSTALLATION", "title");
