si[i++] = gsitm("N502391260000W00ENG.html", "12.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Exhaust camshaft", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "&lt;&lt;D>>", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "13.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Valve tappet", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Valve clearance adjustment (Refer to ) &lt;Installation only>.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "&lt;&lt;A>> FUEL PUMP SUPPORT REMOVAL", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "After removing the fuel pump support mounting bolts, slightly pry the groove of the fuel pump support shown in the figure using a tire lever, and remove the fuel pump support from the cylinder head and rear camshaft bearing cap.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "&lt;&lt;B>> ENGINE MOUNTING BRACKET REMOVAL", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Temporary install the engine hanger to the cylinder head (Refer to ).", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the engine mounting bracket from the engine support bracket (Refer to Engine - Power Plant Mount - Removal and Installation - Power Plant Mount ).", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "&lt;&lt;C>> CAMSHAFT BEARING CAP / CAMSHAFT / V.V.T. SPROCKET ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Turn the crankshaft clockwise so that the V.V.T. sprocket assembly timing marks become horizontal to the cylinder head upper surface, and set the No.1 cylinder to the top dead center of compression.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Never turn the crankshaft counterclockwise.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "With the plunger of the tensioner shortened, insert a pin or a similar tool (2.5 mm or less in diameter) to the hole shown in the illustration of the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Loosen the timing chain tensioner mounting bolts, and remove the timing chain tensioner from the timing chain case hole.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Do not turn the crankshaft after removing the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the tensioner lever assembly installation bolt to drop the tensioner lever assembly.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "While holding the intake camshaft hexagonal area using a wrench or a similar tool, use special tool torque wrench adapter (MB991992) to loosen the V.V.T. sprocket assembly mounting bolt.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "In accordance with the numerical order shown in the illustration remove the installation bolt of each camshaft bearing cap.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Slide the intake V.V.T. sprocket assembly to the front side of engine as much as possible.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Lift the intake V.V.T. sprocket assembly and camshaft and then push them toward the exhaust side.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the intake V.V.T. sprocket bolt.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the camshaft from the intake V.V.T. sprocket assembly.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the camshaft from the exhaust V.V.T. sprocket and camshaft assembly.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "&lt;&lt;D>> VALVE TAPPET REMOVAL", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "To facilitate reassembly, attach a tag to each valve tappet removed that shows where it has been assembled.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502391260000W00ENG.html", ">>A&lt;&lt; VALVE TAPPET INSTALLATION", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Reassemble each valve tappet to the correct location shown on the tag.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", ">>B&lt;&lt; V.V.T. SPROCKET ASSEMBLY / CAMSHAFT / CAMSHAFT BEARING CAP INSTALLATION", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Apply a proper minimum quantity of engine oil to the following points.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Camshaft end", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Insertion hole in V.V.T. sprocket assembly (all over inside and outside surfaces)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Threads and head of V.V.T. sprocket bolt", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Bearing surface of V.V.T. sprocket bolt", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "While holding the hexagonal part of the exhaust camshaft with a wrench, tighten the exhaust V.V.T. sprocket bolt.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: 82 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the exhaust V.V.T. sprocket and camshaft assembly to the cylinder head.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "The No. 2 to No. 5 camshaft bearing caps are equally shaped for both the intake and exhaust camshafts. Be sure to correctly install them by referring to the identification marks.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Identification mark (stamped on the No. 2 to No. 5 camshaft bearing caps)", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "I: Intake", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "E: Exhaust", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "In accordance with the numerical order shown in the illustration, tighten each camshaft bearing cap.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: 11 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Set the installation bolt to the intake V.V.T. sprocket assembly.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the intake V.V.T. sprocket assembly to the timing chain. Move it to the front side of engine.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Align the dowel pin with the intake V.V.T. sprocket assembly to install the camshaft.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the intake V.V.T. sprocket assembly installation bolt by hand.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the sealant from the rear camshaft bearing cap and cylinder head, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Apply specified sealant to the matching area of the rear camshaft bearing cap as shown, and install the rear camshaft bearing cap to the cylinder head.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the rear camshaft bearing cap immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "In accordance with the numerical order shown in the illustration, tighten each camshaft bearing cap first and then tighten the front camshaft bearing cap in several steps.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque:", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "M6 bolt: 11 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "M8 bolt: 20 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "While holding the intake camshaft hexagonal area using a wrench or a similar tool, use special tool torque wrench adapter (MB991992) to tighten the intake V.V.T. sprocket assembly mounting bolt to the specified torque. Since the intake V.V.T. sprocket assembly mounting bolt is tightened by special tool (MB991992), calculate the tightening torque by the following formula.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: (70 ± 5) × {L ÷ (L + 150)} N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "70 ± 5: Tightening torque of the intake V.V.T. sprocket assembly mounting bolt (unit: N·m)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "L: Distance between the center of a torque wrench drive and of its handle (unit: mm)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "150: Length of special tool (unit: mm)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: (52 ± 3) × {L ÷ (L + 5.9)} N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "52 ± 3: Tightening torque of the intake V.V.T. sprocket assembly mounting bolt (unit: N·m)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "5.9: Length of special tool (unit: mm)", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Push tensioner lever assembly up with fingers, letting the tensioner lever assembly go along the timing chain.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Confirm the installation hole of the tensioner lever assembly from the service hall on the upper side. If the iron plate of the tensioner lever assembly slips off, adjust it by hands.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the tensioner lever assembly mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: 23 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the timing chain tensioner mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the pin or a similar tool from the tensioner.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", ">>C&lt;&lt; TIMING CHAIN CASE COVER B INSTALLATION", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the sealant from the timing chain case cover B and timing chain case, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Apply specified sealant to the matching area of the timing chain case cover B as shown, and install the timing chain case cover B to the timing chain case.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the timing chain case cover B immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the timing chain case cover B mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", ">>D&lt;&lt; TIMING CHAIN CASE COVER A INSTALLATION", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the sealant from the timing chain case cover A and timing chain case, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Apply specified sealant to the matching area of the timing chain case cover A as shown, and install the timing chain case cover A to the timing chain case.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the timing chain case cover A immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the timing chain case cover A mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", ">>E&lt;&lt; FUEL PUMP SUPPORT INSTALLATION", "title");
si[i++] = gsitm("N502391260000W00ENG.html", "Remove the sealant from the fuel pump support and the matching area of the rear camshaft bearing cap and the cylinder head, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "When installing the fuel pump support 10 minutes after the rear camshaft bearing cap is assembled, clean the part shown in the figure.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "When installing the fuel pump support 10 minutes after the rear camshaft bearing cap is assembled, perform the operations below. Apply sealant to the positions shown of the cylinder head and bearing cap.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Apply sealant to the position shown of the fuel pump support.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Specified sealant: Three Bond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Install the fuel pump support immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391260000W00ENG.html", "Tighten the fuel pump support mounting bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
