si[i++] = gsitm("N502391320000K00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "&lt;&lt;A>> OIL PAN LOWER REMOVAL", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the engine oil pan mounting bolts.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Use special tool oil pan FIPG cutter (MD998727) to remove the oil pan.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "&lt;&lt;B>> A/C COMPRESSOR AND CLUTCH ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the A/C compressor and clutch assembly mounting bolts (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System -Removal and Installation - A/C Compressor ).", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the A/C compressor and clutch assembly together with the hose from the oil pan upper.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Tie the removed A/C compressor and clutch assembly with a string at a position where they will not interfere with the removal and installation of oil pan upper.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "&lt;&lt;C>> SUPPORT BEARING BRACKET REMOVAL", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the support bearing bracket mounting bolts (Refer to Transmission and Driveline - Front Axle - 2WD - Removal and Installation - Front Drive Shaft ) &lt;2WD>.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the support bearing bracket mounting bolts (Refer to Transmission and Driveline - Front Axle - 4WD - Removal and Installation - Front Drive Shaft ) &lt;AWD>.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Place a wooden block between the support bearing bracket and the cylinder block to secure a space for removal and installation of the oil pan upper.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "&lt;&lt;D>> OIL PAN UPPER REMOVAL", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove the oil pan mounting bolts.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "If the mounting bolts cannot be pulled out, remove them together with the oil pan.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Screw in the bolt into bolt hole in the location shown. Then lift the oil pan and remove it.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Do not use special tool oil pan FIPG cutter (MD998727). The oil pan upper is made of aluminum and this tool will damage it.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502391320000K00ENG.html", ">>A&lt;&lt; OIL STRAINER GASKET INSTALLATION", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Securely insert the gasket in the groove of the oil strainer without causing any torsion or damage to the gasket.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", ">>B&lt;&lt; OIL PAN UPPER INSTALLATION", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove all the traces of sealant adhering to the oil pan and cylinder block using a remover or others. Then, degrease them.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Apply the sealant without any gap to the mating surface of oil pan as shown in the figure, and install the oil pan to the cylinder block.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Install the oil pan immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Tighten the oil pan mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Tighten the oil pan and CVT connecting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Tightening torque: 30 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", ">>C&lt;&lt; OIL PAN LOWER INSTALLATION", "title");
si[i++] = gsitm("N502391320000K00ENG.html", "Remove all the traces of sealant adhering to the oil pan using a remover or others. Then, degrease them.", "ptxt");
si[i++] = gsitm("N502391320000K00ENG.html", "Apply the sealant without any gap to the mating surface of oil pan as shown in the figure, and install the oil pan.", "ptxt");
si[i++] = gsitm("N502010490000A00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502010490000A00ENG.html", "Check the engine oil pan for cracks.", "ptxt");
si[i++] = gsitm("N502010490000A00ENG.html", "Check the engine oil pan sealant-coated surface for damage and deformation.", "ptxt");
