si[i++] = gsitm("N502391510000S00ENG.html", ">>A&lt;&lt; CRANKSHAFT FRONT OIL SEAL INSTALLATION", "title");
si[i++] = gsitm("N502391510000S00ENG.html", "Remove the engine mounting bracket (Refer to Engine - Power Plant Mount - Removal And Installation - Power Plant Mount ).", "ptxt");
si[i++] = gsitm("N502391510000S00ENG.html", "Lower the engine to the position where the front side member does not interfere with the special tool.", "ptxt");
si[i++] = gsitm("N502391510000S00ENG.html", "Apply a small amount of engine oil to the entire inner diameter of the oil seal lip.", "ptxt");
si[i++] = gsitm("N502391510000S00ENG.html", "Using special tool crankshaft front oil seal installer (MD998382), press in the crankshaft front oil seal up to the chamfered surface of timing chain case.", "ptxt");
si[i++] = gsitm("N502391510000S00ENG.html", "When installing the crankshaft front oil seal, be careful to avoid damage to the crankshaft front oil seal.", "ptxt");
