si[i++] = gsitm("N502391410000L00ENG.html", "&lt;&lt;A>> ENGINE SUPPORT BRACKET REMOVAL", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Insert the following special tools to the rib as shown. Then lift the engine support bracket and remove it.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Slide hammer (MB990211)", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Adapter (MB990212)", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "&lt;&lt;B>> TIMING CHAIN CASE ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Insert a screwdriver to the rib as shown. Then lift the timing chain case assembly and remove it.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502391410000L00ENG.html", ">>A&lt;&lt; CRANKSHAFT FRONT OIL SEAL INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Apply a small amount of engine oil to the entire inner diameter of the front oil seal lip.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Using special tool crankshaft front oil seal installer (MD998382), press in the crankshaft front oil seal up to the chamfered surface of timing chain case.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "When installing the crankshaft oil seal, be careful to avoid damage to the crankshaft front oil seal.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", ">>B&lt;&lt; O-RING/TIMING CHAIN CASE ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Completely remove liquid gasket adhering to the timing chain case, cylinder block and cylinder head.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Completely remove all the old liquid gasket, which might be remaining in the installation hole, the O-ring groove or among the components such as the cylinder head gasket.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Degrease the surface where the liquid gasket is applied and the contact surface between the cylinder block and the cylinder head.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Sufficiently check that there is no residual oil on the place where degreasing is performed. If fingerprints are left, do not touch it with bare hands after the degreasing, since the oils from your fingers will harm the seal ability.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Apply a 2 ± 0.5 mm bead of liquid gasket to location A, and a 1.75 ± 0.5 mm bead of liquid gasket to location B on the timing chain case respectively as illustrated.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Specified sealant:", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "A: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "B: ThreeBond 1227D or equivalent", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Install the timing chain case assembly immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Taking care not to scrub the specified sealant applied on the timing chain case assembly with the cylinder block etc., install the timing chain case assembly to the cylinder block.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "If the sealant contacts any other part during installation of the timing chain case assembly, apply sealant again before installing the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Install the timing chain case assembly mounting bolts to the position shown, and tighten the bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "M6: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "M10: 36 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", ">>C&lt;&lt; ENGINE OIL CONTROL VALVE GASKET INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Fit the engine oil control valve gasket in the engine support bracket groove securely with neither twisting nor damage given.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", ">>D&lt;&lt; ENGINE SUPPORT BRACKET INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Remove the sealant from the engine support bracket and the matching area of the cylinder head assembly and the timing chain case assembly, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Apply specified sealant to the matching area of the engine support bracket as shown, and install the engine support bracket to the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Install the engine support bracket immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "Tighten the engine support bracket mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", "M8: 21 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", ">>E&lt;&lt; O-RING / OIL DIPSTICK GUIDE INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Install the oil dipstick guide to the timing chain case assembly paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502391410000L00ENG.html", ">>F&lt;&lt; O-RING / OIL DIPSTICK INSTALLATION", "title");
si[i++] = gsitm("N502391410000L00ENG.html", "Install the oil dipstick to the oil dipstick guide paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "TIMING CHAIN REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502391430000P00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N502391430000P00ENG.html", "Timing Chain Case Assembly Removal and Installation (Refer to N502391410000100ENG ).", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Timing chain tensioner", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Tensioner lever assembly", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Timing chain guide", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Timing chain", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Crankshaft sprocket", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Key", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502391430000P00ENG.html", "&lt;&lt;A>> TIMING CHAIN TENSIONER REMOVAL", "title");
si[i++] = gsitm("N502391430000P00ENG.html", "Set special tool oil pressure switch socket wrench (MD998012) to the crankshaft with the smaller outer diameter side facing toward the engine side as shown in the figure, and install the crankshaft pulley center bolt and washer.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Turn the crankshaft clockwise, and align the timing mark of the V.V.T. sprocket assembly (the groove of V.V.T. sprocket assembly side face). Then set No.1 cylinder to the top dead center of compression.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Never turn the crankshaft counterclockwise.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "While holding the inlet camshaft hexagonal area with a wrench or a similar tool, slightly turn the exhaust camshaft clockwise to tighten the timing chain at the timing chain tensioner side and shorten the plunger of the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "With the plunger of the tensioner shortened, insert a pin (2.5 mm or less in diameter) or a similar tool.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Remove the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Do not turn the crankshaft after removing the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502391430000P00ENG.html", ">>A&lt;&lt; TIMING CHAIN / TIMING CHAIN GUIDE / TENSIONER LEVER ASSEMBLY / TIMING CHAIN TENSIONER INSTALLATION", "title");
si[i++] = gsitm("N502391430000P00ENG.html", "Turn the camshaft and crankshaft clockwise, and align the timing marks of the V.V.T. sprocket assembly (the groove of V.V.T. sprocket assembly side face) and the crankshaft sprocket. Then set No.1 cylinder to the top dead center of compression.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Locate the marked link plate of the timing chain as shown in the illustration of each sprocket, and install the timing chain.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Install the timing chain guide, the tensioner lever assembly, and the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "When the plunger of the timing chain tensioner is stretched, remove the pin or the similar tool. While pressing the cam in the lower area of the timing chain tensioner, press and shorten the plunger to keep the status with the pin or the similar tool.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "After installing the timing chain tensioner, confirm that the timing marks of each sprocket are aligned with the cylinder No. 1 to the top dead center of compression, and the marked link plate of the timing chain is aligned with the specified position of each sprocket. Then pull out the pin or a similar tool of the timing chain tensioner, and apply tension to the timing chain.", "ptxt");
si[i++] = gsitm("N502391430000P00ENG.html", "Remove special tool MD998012.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502391490001200ENG.html", "When the engine assembly is replaced, initialize the learned value using M.U.T.-III SE (Refer to Engine - DI and MPI - On-vehicle Service - Initialisation Procedure for Learning Value in DI and MPI Engine ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Fuel Line Pressure Reduction (Refer to Engine - DI and MPI - On-vehicle Service - Reduce Fuel Pressure in Pressurised Fuel Lines ) &lt;Only at Pre-removal Operation>.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Fuel Leak Check &lt;Only at Post-installation Operation>.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Engine Room Under Cover Front A, B and Engine Room Side Cover Removal and Installation (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Front Fender Protector Removal and Installation (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Front Fender Protector/Rear Wheel House Protector ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Engine Oil Draining and Refilling (Refer to Engine - Engine Lubrication - On-vehicle Service - Engine Oil Change ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Engine Coolant Draining and Refilling (Refer to Engine - Engine Cooling - On-vehicle Service - Engine Coolant Change ).", "ptxt");
