si[i++] = gsitm("N502391490001200ENG.html", "Transfer Oil Level Check (Refer to Transmission and Driveline - Driveline - Transfer - Periodic Maintenance - Transfer Oil ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Battery and Battery Tray Removal (Refer to Electrical and Power Control - Power Supply, Ground and Circuit Elements - Removal and Installation - Battery Tray ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "ECM Bracket Removal and Installation (Refer to Engine - DI and MPI - ECM ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Air Cleaner Assembly, Air Pipe and Air Duct Hose Removal and Installation (Refer to Engine - Intake and Exhaust - Air Cleaner ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Front Bumper Removal and Installation (Refer to Body - Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Front Bumper ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Low Horn Removal and Installation (Refer to Body - Driver Controls - Horn - Removal and Installation - Horn ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Electric Water Pump Assembly Removal and Installation (Refer to Engine - Intake and Exhaust - Intercooler - Intercooler Water Pump ).", "ptxt");
