si[i++] = gsitm("N502391490001200ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;A>> DRIVE PLATE AND TORQUE CONVERTER MOUNTING BOLT REMOVAL", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the drive plate and torque converter mounting bolts (4 pieces) (Refer to Transmission and Driveline - Transaxle and Transmission - CVT - Unit Removal and Installation - Transaxle Assembly ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;B>> ENGINE ASSEMBLY AND TRANSAXLE ASSEMBLY MOUNTING BOLT REMOVAL", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the engine assembly and transaxle assembly mounting bolts (4 pieces) (Refer to Transmission and Driveline - Transaxle and Transmission - CVT - Unit Removal and Installation - Transaxle Assembly ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;C>> CONTROL WIRING HARNESS (FUSIBLE LINK) DISCONNECTION", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the IPDM E/R (Refer to Electrical and Power Control - Power Control System - IPDM E/R - Removal and Installation - IPDM E/R ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the fusible link mounting nut.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Disconnect the control wiring harness connectors.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Disconnect the control wiring harness from the vehicle.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;D>> CONTROL WIRING HARNESS (GROUNDING BOLT) / CONTROL WIRING HARNESS (RELAY BOX CONNECTOR) DISCONNECTION", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the grounding bolts.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the relay box mounting nuts.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the relay box cover.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Open the relay box side cover.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Disconnect the relay box connectors from the relay box.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;E>> A/C COMPRESSOR AND CLUTCH ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the A/C compressor and clutch assembly mounting bolts (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - A/C Compressor ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the A/C compressor and clutch assembly together with the hose from the engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Tie the removed A/C compressor and clutch assembly with a string at a position where they will not interfere with the removal and installation of engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;F>> ENGINE AND TRANSAXLE ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Place commercial cart below the engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Cart: Commercially available product [Load capacity 500 kg or more, recommended top plate dimensions 775 × 1,225 mm]", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Place wooden blocks or pieces so that the weight of the engine and transaxle assembly is taken at the position shown in the figure.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Always use wooden blocks or pieces to take the weight of the engine and transaxle assembly at the specified position. If the weight is taken by the bottom of the oil pan, it will be deformed.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Lower the vehicle to take the weight of the assembly off the transaxle mounting bracket and the engine mounting bracket.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the bolts securing the transaxle mounting bracket (Refer to Engine - Power Plant Mount ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the bolts securing the engine mounting bracket (Refer to Engine - Power Plant Mount ).", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the transaxle mounting bracket and the engine mounting bracket.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Make sure that all the hoses and wiring harness connectors are disconnected.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Raise the body slowly with a lift, and remove the engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Be careful not to bend the fuel-high pressure hose.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "&lt;&lt;G>> TRANSAXLE ASSEMBLY / ENGINE ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502391490001200ENG.html", "Install the special tool engine hanger plate (MB991956) to the protector bracket as shown.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Install the special tool hanger (MB991527) and engine hanger balancer (MB991454) to the engine hanger as shown to support the engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502391490001200ENG.html", "Remove the transaxle assembly from the engine assembly (Refer to Transmission and Driveline - Transaxle and Transmission - CVT - Unit Removal and Installation - Transaxle Assembly ).", "ptxt");
