si[i++] = gsitm("N502400450000D00ENG.html", ">>A&lt;&lt; O-RING / CRANK ANGLE SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502400450000D00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Install the crank angle sensor to the cylinder block attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", ">>B&lt;&lt; O-RING / CAMSHAFT POSITION SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502400450000D00ENG.html", "Install the camshaft position sensor to the rear camshaft bearing cap paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", ">>C&lt;&lt; O-RING / ENGINE OIL CONTROL VALVE INSTALLATION", "title");
si[i++] = gsitm("N502400450000D00ENG.html", "Apply a little amount of engine oil to the O-ring of engine oil control valve.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Do not reuse the O-ring.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Install the O-ring after wrap a tape not having adhesion (such as a seal tape) round the notch on the oil passage of engine oil control valve to prevent it from damage. The damaged O-ring may cause oil leakage.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Remove the tape before installing engine oil control valve.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Install the engine oil control valve to the engine support bracket.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "To install the engine oil control valve, be careful to keep foreign material from entering oil channels.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "When installing the engine oil control valve to the cylinder head, check the engine oil control valve filter for foreign matters attached, defects and deformation.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Tighten the mounting bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502400450000D00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400140000M00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "Ignition coil", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "Spark plug", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400140000M00ENG.html", "&lt;&lt;A>> SPARK PLUG REMOVAL", "title");
si[i++] = gsitm("N502400140000M00ENG.html", "Using special tool spark plug wrench (MB991398), remove the spark plug.", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502400140000M00ENG.html", ">>A&lt;&lt; SPARK PLUG INSTALLATION", "title");
si[i++] = gsitm("N502400140000M00ENG.html", "In the same manner as removal, use special tool spark plug wrench (MB991398) to tighten the spark plug to the specified torque.", "ptxt");
si[i++] = gsitm("N502400140000M00ENG.html", "Tightening torque: 18 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Crankshaft pulley center bolt", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Crankshaft pulley washer", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Torsional vibration damper", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Crankshaft isolation pulley", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Water pump pulley", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Idler pulley", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "7.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "&lt;&lt;A>> CRANKSHAFT PULLEY CENTER BOLT / CRANKSHAFT PULLEY WASHER / TORSIONAL VIBRATION DAMPER REMOVAL", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "Assemble the following special tools and the nuts (M12 × 1.25).", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Pulley holder (MB991800)", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Pin (MB992100)", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Set each nut to the position where it is flush with the tip of the pin.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Use the special tools to support the torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Apply the special tool to the torsional vibration damper securely to prevent the tool from coming off.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Loosen the crankshaft pulley center bolt, remove the crankshaft pulley washer and torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "If the torsional vibration damper and the crankshaft isolation pulley came off together, separate them by hands. If they cannot be separated by hands, clean the connection part.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "&lt;&lt;B>> CRANKSHAFT ISOLATION PULLEY REMOVAL", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "If the crankshaft isolation pulley cannot be removed from the crankshaft by hands, remove it by following the steps below.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Use an inner-claw type bearing puller. If the crankshaft isolation pulley is removed with other tools, replace the pulley.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Insert the bearing puller into the crankshaft isolation pulley.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Bearing puller dimension", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "Diameter of claw at the tip (A)", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "When the bearing puller is inserted: 16.8 mm or less", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "When engaged: 17.4 mm or more", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Amount of insertion (B): 20 to 24 mm", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Engage the claw at the tip of the bearing puller with the crankshaft isolation pulley to secure the pulley.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Install the slide hammer to the bearing puller, and remove the crankshaft isolation pulley.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "If the claw of the bearing puller has stopped in the hole of the crankshaft isolation pulley, replace the pulley.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "After wiping off the dirt on the installation surfaces of the crankshaft isolation pulley and the crankshaft, degrease the installation surfaces.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502400180000U00ENG.html", ">>A&lt;&lt; CRANKSHAFT ISOLATION PULLEY / TORSIONAL VIBRATION DAMPER / CRANKSHAFT PULLEY WASHER / CRANKSHAFT PULLEY CENTER BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400180000U00ENG.html", "If the part to be installed cannot be inserted smoothly, replace the part.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Wipe off the dirt on the crankshaft as shown in the figure using a rag.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Wipe off the dirt on the oil pump drive shaft, crankshaft isolation pulley and torsional vibration damper as shown in the figure using a rag, and then degrease the areas.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Degrease them to prevent drop in the friction coefficient of the pressed area which is caused by oil adhesion.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Insert the pin of the crankshaft isolation pulley into the pin hole of the torsional vibration damper, and install them to the crankshaft.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "When installing the crankshaft isolation pulley and the torsional vibration damper, do not insert them forcibly with the axial force of the bolt. If the bolt cannot be seated by hand, replace the parts.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Wipe off the dirt on the crankshaft pulley washer and the crankshaft pulley center bolt as shown in the figure using a rag.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Apply an adequate and minimum amount of engine oil to the thread of the crankshaft pulley center bolt and the lower area of the flange.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Use the following special tools and nut (M12 × 1.25) as during removal to support the torsional vibration damper.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Tighten the crankshaft pulley center bolt as follows:", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Tighten the crankshaft pulley center bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Tightening torque: 90 N·m", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Tighten the crankshaft pulley center bolt in a 90°.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "When the tightening angle is smaller than the specified tightening angle, the appropriate tightening capacity cannot be secured.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "When the tightening angle is larger than the specified tightening angle, remove the bolt to start from the beginning again according to the procedure.", "ptxt");
si[i++] = gsitm("N502400180000U00ENG.html", "Loosen the crankshaft pulley center bolt completely.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400760000S00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Drive plate bolt", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Adapter plate", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Drive plate", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Crankshaft rear oil seal case assembly", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400760000S00ENG.html", "&lt;&lt;A>> DRIVE PLATE BOLT REMOVAL", "title");
si[i++] = gsitm("N502400760000S00ENG.html", "Fix the drive plate using special tool flywheel stopper (MB991883).", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Remove the drive plate bolts.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400760000S00ENG.html", ">>A&lt;&lt; CRANKSHAFT REAR OIL SEAL CASE ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400760000S00ENG.html", "Remove sealant from the crankshaft rear oil seal case assembly mounting surface of the cylinder block, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Apply a bead of specified sealant to the crankshaft rear oil seal case assembly mating surface of the cylinder block as shown.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Install the crankshaft rear oil seal case assembly immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Install the crankshaft rear oil seal case assembly to the cylinder block.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Install the crankshaft rear oil seal case assembly not to damage the crankshaft rear oil seal.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Tighten the crankshaft rear oil seal case assembly mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Tightening torque: 11 ± 3 N·m", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", ">>B&lt;&lt; ADAPTER PLATE / DRIVE PLATE BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400760000S00ENG.html", "Remove the sealant, engine oil, and other adhering materials from the drive plate installation face, adapter plate, crankshaft screw hole, and drive plate bolts.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Install the adapter plate in the direction shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Install the drive plate to the crankshaft.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "In the same manner as removal, fix the drive plate using special tool flywheel stopper (MB991883) in the same manner as removal.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Apply a small amount of engine oil to the installation face of the drive plate bolts.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Apply specified sealant to the drive plate bolts threads.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Specified sealant: ThreeBond 1324 or equivalent", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Tighten the drive plate bolts to the specified torque in two or three steps in the order shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400760000S00ENG.html", "Tightening torque: 100 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400780000H00ENG.html", "Do not disassemble any belt drive starter generator other than those described in this manual.", "ptxt");
