si[i++] = gsitm("N502400780000H00ENG.html", "Belt drive starter generator bracket", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400780000H00ENG.html", ">>A&lt;&lt; BELT DRIVE STARTER GENERATOR BRACKET INSTALLATION", "title");
si[i++] = gsitm("N502400780000H00ENG.html", "Temporally tighten belt drive starter generator bracket mounting bolts (1, 2) in the order of number shown in the illustration with seating bolts.", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "Tighten belt drive starter generator bracket mounting bolts (3 to 7) to the specified torque in the order of number shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "3: 43 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "Except 3: 36 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", ">>B&lt;&lt; BELT DRIVE STARTER GENERATOR INSTALLATION", "title");
si[i++] = gsitm("N502400780000H00ENG.html", "Tighten belt drive starter generator mounting bolts to the specified torque in the order of number shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400780000H00ENG.html", "Tightening torque: 42 ± 4 N·m", "ptxt");
