si[i++] = gsitm("N502400410000W00ENG.html", "&lt;Exhaust side>", "title");
si[i++] = gsitm("N502400410000W00ENG.html", "When removing or installing the engine coolant temperature sensor, be careful not to apply impact to the sensor.", "ptxt");
si[i++] = gsitm("N502400410000W00ENG.html", "Do not reuse the engine coolant temperature sensor that has been dropped.", "ptxt");
si[i++] = gsitm("N502400410000W00ENG.html", "When the engine coolant temperature sensor is tightened to more than 16.8 N·m, do not reuse the engine coolant temperature sensor.", "ptxt");
si[i++] = gsitm("N502400410000W00ENG.html", "Engine coolant temperature sensor", "ptxt");
