si[i++] = gsitm("N502400320000U00ENG.html", "Fit the intake manifold gasket in the intake manifold groove securely with neither twisting nor damage given.", "ptxt");
si[i++] = gsitm("N502400320000U00ENG.html", ">>B&lt;&lt; INTAKE MANIFOLD INSTALLATION", "title");
si[i++] = gsitm("N502400320000U00ENG.html", "In accordance with the installation order, tighten them to the specified torque.", "ptxt");
si[i++] = gsitm("N502400320000U00ENG.html", "Tightening torque: 22 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502400320000U00ENG.html", ">>C&lt;&lt; O-RING / MANIFOLD ABSOLUTE PRESSURE SENSOR INSTALLATION", "title");
