si[i++] = gsitm("N502400260000J00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400260000J00ENG.html", "&lt;&lt;A>> FUEL TUBE DISCONNECTION", "title");
si[i++] = gsitm("N502400260000J00ENG.html", "Follow the steps below to unlock the fuel tube connector.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Insert a flat-tipped screwdriver (6 mm wide and1 mm 0.04 inch thick) into the retainer of the fuel tube connector.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Turn the flat-tipped screwdriver inserted into the retainer by 90° to push up the retainer and unlock the fuel tube connector.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "When pushing up the retainer of the fuel tube connector, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Remove the fuel tube.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400260000J00ENG.html", ">>A&lt;&lt; FUEL PUMP (HIGH PRESSURE) TAPPET / O-RING / FUEL PUMP (HIGH PRESSURE) ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400260000J00ENG.html", "Install the torsional vibration damper (Refer to ).", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Turn the torsional vibration damper and put in parallel the flat surface of exhaust camshaft pump cam and installation surface of the fuel pump support as shown in the figure, install the fuel pump (high pressure) tappet.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "By hand, install the fuel pump (high pressure) assembly to the fuel pump support paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "By one rotation per time, tighten the installation bolts of the fuel pump (high pressure) assembly until reaching the specified torque.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tightening torque: 34 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", ">>B&lt;&lt; FUEL DELIVERY INTERMEDIATE PIPE INSTALLATION", "title");
si[i++] = gsitm("N502400260000J00ENG.html", "Do not tighten it until a flare nut performs a seating.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "By hand, temporally tighten the flare nuts of the fuel delivery intermediate pipe.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Temporally tighten the bolt of the fuel delivery intermediate pipe to the engine hanger.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Temporally tighten the bolt of the fuel delivery intermediate pipe to the cylinder head.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "By hand, temporally tighten it to the place where flare nuts stops by hand.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tighten the fuel pump (high pressure) side flare nut to the specified torque.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tightening torque: 35 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tighten the delivery pipe  (high pressure) side flare nut to the specified torque.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tighten the engine hanger side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tighten the cylinder head side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Tightening torque: 22 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", ">>C&lt;&lt; FUEL TUBE CONNECTION", "title");
si[i++] = gsitm("N502400260000J00ENG.html", "Pull up the retainer of fuel tube to unlock before installing.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Install the fuel tube to the fuel pump (high pressure) and delivery pipe .", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "Push in the retainer of the fuel tube connector to lock the fuel pump (high pressure) and delivery pipe .", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "When pushing in the retainer of the fuel tube connector, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N502400260000J00ENG.html", "After the installation of the fuel tube, slightly pull the fuel tube to check that it is connected securely. At this time, also check that there is approximately 1 mm play.", "ptxt");
