si[i++] = gsitm("N502400280000S00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "&lt;&lt;A>> DELIVERY PIPE  AND FUEL INJECTOR ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "Remove the delivery pipe  with the fuel injectors attached to it.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "Do not drop the fuel injector.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400280000S00ENG.html", ">>A&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "While turning the fuel injector to right and left, install the O-ring to the fuel injector with care to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", ">>B&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "Using special tool O-ring installer (MB992106), install the fuel injector paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", ">>C&lt;&lt; FUEL INJECTOR ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "When applying the engine oil, make sure not to allow the engine oil to enter the delivery pipe  inside.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "Turning the fuel injector assembly to right and left, install it to the delivery pipe  with care not to damage the O-ring. After the installation, check for its smooth rotation. At this time, check that the projection part of the fuel injector assembly is in the center.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "If the rotation is not smooth, the O-ring may be caught. Remove the fuel injector assembly and check the O-ring for damage. After this, re-insert it to the delivery pipe  and check for its smooth rotation.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", ">>D&lt;&lt; FUEL INJECTOR SUPPORT INSTALLATION", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "Install the fuel injector support to the fuel injector groove and delivery pipe  brim, and fix the fuel injector assembly and delivery pipe .", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", ">>E&lt;&lt; DELIVERY PIPE  AND FUEL INJECTOR ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400280000S00ENG.html", "Apply a small amount of new engine oil to the O-ring at the end of fuel injector assembly.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "When installing the delivery pipe  and fuel injector assembly to the cylinder head, pay attention to avoid damage to the O-ring at the end of the fuel injector assembly.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "Install the delivery pipe  and fuel injector assembly to the cylinder head. Be careful not to damage the O-ring.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "Tighten the delivery pipe  mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400280000S00ENG.html", "Tightening torque: 14 ± 3 N·m", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Do not install or remove the delivery pipe  and fuel injector assembly (high pressure) while holding the fuel pressure sensor.", "ptxt");
