si[i++] = gsitm("N502400340000C00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "&lt;&lt;A>> SEAL RING REMOVAL", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Cut and remove the seal ring while picking it up so that the fuel injector (high pressure) will not be scratched.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Be careful not to scratch the nozzle part of the fuel injector (high pressure).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400340000C00ENG.html", ">>A&lt;&lt; SEAL RING INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Attach the special tool injector seal drift (MQ713981) with the side that has the \"UP\" punch mark facing the injector to the fuel injector (high pressure).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Do not apply engine oil to the seal ring.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Do not clean the seal ring with solvents.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Set the special tool injector seal guide (MQ713982) to the fuel injector (high pressure).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Set the seal ring to the special tool injector seal insulator (MQ713983).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Insert the seal ring set as shown in the figure straight into the fuel injector (high pressure).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Be careful not to slide over the groove of the fuel injector (high pressure) when inserting the seal ring.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Move the special tool injector seal drift (MQ713981) in the direction of the drawing so that the seal ring will fit into the groove.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Hold it for over 30 seconds to fit the seal ring.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", ">>B&lt;&lt; BACKUP RING INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Install the backup ring with the wider side facing upward to the fuel injector (high pressure).", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", ">>C&lt;&lt; RING STOPPER INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "As shown in the Fig., put a link stopper on a flat surface.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Pushing the fuel injector (high pressure), install the ring stopper.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", ">>D&lt;&lt; INJECTION SUPPORT INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Install the Injector support to the fuel injector (high pressure) as shown in the figure.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", ">>E&lt;&lt; DELIVERY PIPE  AND FUEL INJECTOR (HIGH PRESSURE) ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400340000C00ENG.html", "Confirming that the injector support and Delivery pipe  (high pressure) are in the positions shown in the figure.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Never hold the fuel pressure sensor during the installation. If adding loads to the fuel pressure sensor, it may cause the trouble.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Replace the seal ring when the seal ring is damaged during installation.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "When an O-ring is damaged during installation, replace the O-ring and ring stopper.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "When installing the Fuel injector (High pressure) assembly, apply engine oil to the seal ring.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Tighten bolts 1 and 2 shown in the figure alternately by one rotation at a time to the specified torque.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Specified torque: 23 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "Tighten the bolts to the specified torque in the order of 3 and 4.", "ptxt");
si[i++] = gsitm("N502400340000C00ENG.html", "When tightening bolts 3 and 4, it is not necessary to tighten them alternately by one rotation at a time.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400740000C00ENG.html", "The connector and harness of the EGR gas temperature sensor shall be fixed to the bracket securely.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "The harness is to be free from defects such as excess torsion after the installation of EGR gas temperature sensor.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Attention to EGR gas temperature sensor without any damages from falling or the impact of the tool.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Do not give any impact on EGR gas temperature sensor installed EGR passage lower, using a hammer, etc.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Do not use the impact wrench to tighten the EGR gas temperature sensor.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Not entry of water into the connector when installing connector.", "ptxt");
