si[i++] = gsitm("N502400740000C00ENG.html", "15.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400740000C00ENG.html", ">>A&lt;&lt; STUD INSTALLATION", "title");
si[i++] = gsitm("N502400740000C00ENG.html", "The stud should protrude 18 to 20 mm from the end of the cylinder block.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", ">>B&lt;&lt; STUD INSTALLATION", "title");
si[i++] = gsitm("N502400740000C00ENG.html", "The stud should protrude 23 mm or less from the end of the EGR cooler.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", ">>C&lt;&lt; EGR COOLER / EGR PASSAGE / EGR VALVE GASKET / EGR VALVE / EGR HOSE / EGR FILTER GASKET / EGR VALVE BRACKET / EGR VALVE STAY INSTALLATION", "title");
si[i++] = gsitm("N502400740000C00ENG.html", "Install the each gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Assemble the following parts (EGR unit), tighten the mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tightening torque: 27 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Temporally tighten the EGR valve bracket mounting bolts (A) to the cylinder block.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Install the EGR hose to the EGR unit and air inlet fitting.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Temporally tighten the EGR unit mounting nut (B) to the cylinder block.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Temporally tighten the EGR valve bracket mounting bolt (C) to the EGR unit.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Temporally tighten the EGR valve stay mounting bolts (D) to the EGR unit and turbocharger bracket.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tighten the EGR valve bracket mounting bolts (A) to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tighten the EGR unit mounting nut (B) to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tightening torque: 24 ± 3 N·m", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tighten the EGR valve bracket mounting bolt (C) to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tighten the EGR valve stay mounting bolts (D) to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tighten the EGR hose clamps (E) to the specified torque.", "ptxt");
si[i++] = gsitm("N502400740000C00ENG.html", "Tightening torque: 4.0 ± 1.0 N·m", "ptxt");
