si[i++] = gsitm("N502400390000C00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400390000C00ENG.html", ">>A&lt;&lt; STUD INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "The stud should protrude 24.5 to 26.5 mm from the end of the turbocharger assembly.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", ">>B&lt;&lt; TURBOCHARGER GASKET / TURBOCHARGER ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "Install the turbocharger gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "When retighten the turbocharger assembly, remove the rust or foreign material attached on the flange surface.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "If the turbocharger assembly mounting surface is uneven, polish the surface with sandpaper and then tighten the nuts to install the turbocharger assembly to the cylinder head.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the nuts to specified torque in the sequence shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tightening torque: 24 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the nuts again to specified torque in the sequence shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tightening torque: 42 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", ">>C&lt;&lt; OIL PIPE ASSEMBLY / EYE BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "Temporally tighten the oil pipe assembly mounting eye bolts", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Temporally tighten the clamp mounting bolts.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the oil pipe assembly mounting eye bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tightening torque: 17 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the clamp mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", ">>D&lt;&lt; OIL RETURN PIPE GASKET INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "Install the oil return pipe gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", ">>E&lt;&lt; TURBOCHARGER BRACKET INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the bolts to temporally at the cylinder head side.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the bolt to temporally at the turbocharger side.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the bolts to the specified torque at the cylinder head side.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tightening torque: 27 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", "Tighten the bolt to the specified torque at the turbocharger side.", "ptxt");
si[i++] = gsitm("N502400390000C00ENG.html", ">>F&lt;&lt; AIR INLET FITTING GASKET INSTALLATION", "title");
si[i++] = gsitm("N502400390000C00ENG.html", "Install the gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Engine oil pressure switch", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Engine oil pressure sensor", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Detonation sensor", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "&lt;&lt;A>> ENGINE OIL PRESSURE SWITCH REMOVAL", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "Use special tool oil pressure switch wrench (MB992118) to remove the engine oil pressure switch.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "The sealant is applied to the bolt. Remove the bolt with care not to break it.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "&lt;&lt;B>> ENGINE OIL PRESSURE SENSOR REMOVAL", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400840000C00ENG.html", ">>A&lt;&lt; DETONATION SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "Align the detonation sensor connector with the position shown in the illustration, and then tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Tightening torque: 20 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", ">>B&lt;&lt; ENGINE OIL PRESSURE SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "Apply sealant to the engine oil pressure sensor thread.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Specified sealant: ThreeBond 1215 or equivalent", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Install the engine oil pressure sensor immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Tighten the engine oil pressure sensor to the specified torque.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Tightening torque: 13 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", ">>C&lt;&lt; ENGINE OIL PRESSURE SWITCH INSTALLATION", "title");
si[i++] = gsitm("N502400840000C00ENG.html", "Apply sealant to the engine oil pressure switch thread.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Install the engine oil pressure switch immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "In the same manner as removal, use special tool oil pressure switch wrench (MB992118) to tighten the engine oil pressure switch to the specified torque.", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400840000C00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
