si[i++] = gsitm("N502400470000J00ENG.html", "Cylinder head cover", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Cylinder head cover gasket", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "&lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N502400470000J00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400470000J00ENG.html", ">>A&lt;&lt; CYLINDER HEAD COVER ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400470000J00ENG.html", "Remove the sealant from the cylinder head cover assembly and the matching area of the cylinder head assembly and the engine support bracket, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Remove the sealant from the cylinder head cover assembly and the matching area of the cylinder head assembly and the rear camshaft bearing cap, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Apply specified sealant to the matching area of the cylinder head assembly and the engine support bracket as shown.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Apply specified sealant to the matching area of the cylinder head assembly and the rear camshaft bearing cap as shown, and install the cylinder head cover assembly to the cylinder head assembly.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Install the cylinder head cover assembly immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Tighten the cylinder head cover assembly mounting bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Tightening torque: 3.0 ± 1.0 N·m", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Tighten again the cylinder head cover assembly mounting bolts to the specified torque in the order of number shown in the figure.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Tightening torque: 5.5 ± 0.5 N·m", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", ">>B&lt;&lt; O-RING / PCV VALVE INSTALLATION", "title");
si[i++] = gsitm("N502400470000J00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502400470000J00ENG.html", "Install the PCV valve to the cylinder head cover paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", "REMOVAL AND INSTALLATION", "title");
