si[i++] = gsitm("N502400510000K00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", "Engine oil pan drain plug gasket", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", ">>C&lt;&lt;", "ptxt");
