si[i++] = gsitm("N502400510000K00ENG.html", "Oil pan lower", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400510000K00ENG.html", ">>B&lt;&lt;", "ptxt");
