si[i++] = gsitm("N502400530000C00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "Engine oil filter bracket", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "Engine oil filter bracket gasket", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400530000C00ENG.html", "&lt;&lt;A>> ENGINE OIL FILTER REMOVAL", "title");
si[i++] = gsitm("N502400530000C00ENG.html", "Use special tool oil filter wrench (MB991396) or commercially-available tool to remove the engine oil filter.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400530000C00ENG.html", ">>A&lt;&lt; ENGINE OIL FILTER BRACKET GASKET INSTALLATION", "title");
si[i++] = gsitm("N502400530000C00ENG.html", "Clean the engine oil filter bracket gasket mounting surface of the cylinder block.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", ">>B&lt;&lt; ENGINE OIL FILTER INSTALLATION", "title");
si[i++] = gsitm("N502400530000C00ENG.html", "Clean the engine oil filter installing surface on the engine oil filter bracket side.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "Apply a small amount of engine oil to the new engine oil filter O-ring.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "Tighten the engine oil filter until the O-ring contacts with the installation surface.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "In the same manner as removal, use special tool oil filter wrench (MB991396) or commercially-available tool to tighten the engine oil filter to the specified torque.", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", "Tightening torque: Approximately 1 turn (14 ± 2 N·m)", "ptxt");
si[i++] = gsitm("N502400530000C00ENG.html", ">>C&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N502400530000C00ENG.html", "Clean the O-ring mounting surface of the engine oil filter bracket.", "ptxt");
