si[i++] = gsitm("N502400550000J00ENG.html", "Oil pump drive shaft", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "16.", "ptxt");
