si[i++] = gsitm("N502400550000J00ENG.html", "17.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Key", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "&lt;&lt;A>> ENGINE SUPPORT BRACKET REMOVAL", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Insert the following special tools to the rib as shown. Then lift the engine support bracket and remove it.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Slide hammer (MB990211)", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Adapter (MB990212)", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "&lt;&lt;B>> TIMING CHAIN CASE ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Insert a screwdriver to the rib as shown. Then lift the timing chain case assembly and remove it.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400550000J00ENG.html", ">>A&lt;&lt; CRANKSHAFT FRONT OIL SEAL INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Apply a small amount of engine oil to the entire inner diameter of the front oil seal lip.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Using special tool crankshaft front oil seal installer (MD998382), press in the crankshaft front oil seal up to the chamfered surface of timing chain case.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "When installing the crankshaft oil seal, be careful to avoid damage to the crankshaft front oil seal.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>B&lt;&lt; O-RING / TIMING CHAIN CASE ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Completely remove liquid gasket adhering to the timing chain case, cylinder block and cylinder head.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Completely remove all the old liquid gasket, which might be remaining in the installation hole, the O-ring groove or among the components such as the cylinder head gasket.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Degrease the surface where the liquid gasket is applied and the contact surface between the cylinder block and the cylinder head.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Sufficiently check that there is no residual oil on the place where degreasing is performed. If fingerprints are left, do not touch it with bare hands after the degreasing, since the oils from your fingers will harm the seal ability.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Apply a 2 ± 0.5 mm bead of liquid gasket to location A, and a 1.75 ± 0.5 mm bead of liquid gasket to location B on the timing chain case respectively as illustrated.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Specified sealant:", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "A: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "B: ThreeBond 1227D or equivalent", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the timing chain case assembly immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Taking care not to scrub the specified sealant applied on the timing chain case assembly with the cylinder block etc., install the timing chain case assembly to the cylinder block.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "If the sealant contacts any other part during installation of the timing chain case assembly, apply sealant again before installing the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the timing chain case assembly mounting bolts to the position shown, and tighten the bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "M6: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "M10: 36 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>C&lt;&lt; ENGINE OIL CONTROL VALVE GASKET INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Fit the engine oil control valve gasket in the engine support bracket groove securely with neither twisting nor damage given.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>D&lt;&lt; ENGINE SUPPORT BRACKET INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Remove the sealant from the engine support bracket and the matching area of the cylinder head assembly and the timing chain case assembly, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Apply specified sealant to the matching area of the engine support bracket as shown, and install the engine support bracket to the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the engine support bracket immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Tighten the engine support bracket mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "M8: 21 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>E&lt;&lt; TIMING CHAIN CASE COVER B INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Remove the sealant from the timing chain case cover B and timing chain case, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Apply specified sealant to the matching area of the timing chain case cover B as shown, and install the timing chain case cover B to the timing chain case.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the timing chain case cover B immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Tighten the timing chain case cover B mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>F&lt;&lt; TIMING CHAIN CASE COVER A INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Remove the sealant from the timing chain case cover A and timing chain case, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Apply specified sealant to the matching area of the timing chain case cover A as shown, and install the timing chain case cover A to the timing chain case.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the timing chain case cover A immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Tighten the timing chain case cover A mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>G&lt;&lt; O-RING / WATER PUMP INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Carefully remove the drying material and other foreign materials on the installation groove for the water pump O-ring.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Carefully remove the drying material and other foreign materials on the water pump installation area of the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Sufficiently apply water or coolant to the O-ring to prevent it from dropping using brushes.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Securely fit the O-ring flange area into the installation groove of the water pump O-ring.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Reverse the water pump carefully and check that the O-ring does not fall down.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the water pump to the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", "When installing the water pump, pay attention not to let the O-ring fall down or be bitten. Otherwise, a coolant leak may be caused.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>H&lt;&lt; O-RING / OIL DIPSTICK GUIDE INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the oil dipstick guide to the timing chain case assembly paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400550000J00ENG.html", ">>I&lt;&lt; O-RING / OIL DIPSTICK INSTALLATION", "title");
si[i++] = gsitm("N502400550000J00ENG.html", "Install the oil dipstick to the oil dipstick guide paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Timing chain tensioner", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Tensioner lever assembly", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Timing chain guide assembly", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Timing chain", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Intake V.V.T. sprocket assembly", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Exhaust V.V.T. sprocket assembly", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "7.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Crankshaft sprocket", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "8.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Key", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "&lt;&lt;A>> TIMING CHAIN TENSIONER REMOVAL", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "While holding the inlet camshaft hexagonal part with a wrench or a similar tool, slightly turn the exhaust camshaft clockwise to tighten the timing chain at the timing chain tensioner side and shorten the plunger of the timing chain tensioner.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "With the plunger of the tensioner shortened, insert a pin (2.5 mm or less in diameter) or a similar tool.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Remove the timing chain tensioner assembly.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "&lt;&lt;B>> V.V.T. SPROCKET ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "Hold the hexagonal part of the camshaft with a wrench and loosen the V.V.T. sprocket bolt.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400570000V00ENG.html", ">>A&lt;&lt; V.V.T. SPROCKET ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "Apply a proper minimum quantity of engine oil to the following points.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Camshaft end", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Insertion hole in V.V.T. sprocket assembly (all over inside and outside surfaces)", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Threads and head of V.V.T. sprocket bolt", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Bearing surface of V.V.T. sprocket bolt", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the V.V.T. sprocket assembly onto the camshaft.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Make sure that the V.V.T. sprocket is installed all the way onto the camshaft. Holding the hexagonal portion of the camshaft with a wrench, check that the V.V.T. sprocket assembly does not turn.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "While holding the hexagonal part of the camshaft with a wrench, tighten the V.V.T. sprocket bolt.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Intake: 70 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Exhaust: 82 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", ">>B&lt;&lt; TIMING CHAIN INSTALLATION", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "Place the timing chain such that the link plate that is away from the other two link plates of the chain is on the crankshaft side.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the timing chain onto the crankshaft sprocket, aligning the link plate with the mark on the sprocket.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the chain onto the V.V.T. sprocket, aligning the link plate with the mark on the sprocket.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the chain onto the camshaft sprocket, aligning the link plate with the mark on the sprocket. When doing this, rotate the V.V.T. sprocket assembly or the camshaft sprocket by a tooth or two and then align the link plate and the mark.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Ensure that all of the 3 pairs of the timing marks are aligned.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the chain guide and the tensioner lever.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", ">>C&lt;&lt; TIMING CHAIN TENSIONER INSTALLATION", "title");
si[i++] = gsitm("N502400570000V00ENG.html", "While pressing in the plunger of the timing chain tensioner insert a pin or a similar tool (2.5 mm or less in diameter) as illustrated to lock the plunger.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Install the timing chain tensioner onto the cylinder block, tighten the mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502400570000V00ENG.html", "Remove the pin from the tensioner. Timing chain should be tensioned via the tensioner lever assembly.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502400580000O00ENG.html", "VALVE CLEARANCE ADJUSTMENT", "title");
si[i++] = gsitm("N502400580000O00ENG.html", "Measure valve clearance in the following procedure.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Check and adjust the valve clearance with the timing chain installed.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Rotate the crankshaft clockwise to align the timing mark of the V.V.T. sprocket with the top surface of the cylinder head as illustrated. (Set the No. 1 piston at top dead center on the compression stroke.)", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Always rotate the crankshaft clockwise.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Valve clearance can be measured at the illustrated location in this condition.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Use a thickness gauge to measure clearance between the camshaft and valve tappet.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Standard value (cold engine)", "title");
si[i++] = gsitm("N502400580000O00ENG.html", "Intake side: 0.22 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Exhaust side: 0.30 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "If measured values are out of the standard value, record measured values.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Rotate the crankshaft by one turn clockwise to set the No. 4 piston at top dead center on the compression stroke.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "The timing mark of the exhaust V.V.T. sprocket must be at the illustrated position.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "If the measured value is out of the standard value, replace the valve tappet.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "There are 31 kinds of valve tappets at intervals of 0.020 mm in the range between 2.700 and 3.300 mm.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Select a valve tappet in the following procedure.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Measure thickness of a removed valve tappet.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Calculate thickness of a valve tappet so that valve clearance meets the standard value.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "A: Thickness of valve tappet to be selected", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "B: Thickness of removed valve tappet", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "C: Measured valve clearance", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Formula", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Intake side: A = B + (C - 0.22 mm)", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Exhaust side: A = B + (C - 0.30 mm)", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Refer to  for removal and installation procedure of valve tappets.", "ptxt");
si[i++] = gsitm("N502400580000O00ENG.html", "Refer to  for inspection procedure of valve tappets.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Fuel pump support", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Rear camshaft bearing cap", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Front camshaft bearing cap", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Camshaft bearing cap", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Intake camshaft", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Exhaust camshaft", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;C>>", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "7.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Valve tappet", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;A>> FUEL PUMP SUPPORT REMOVAL", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "After removing the fuel pump support mounting bolts, slightly pry the groove of the fuel pump support shown in the figure using a tire lever, and remove the fuel pump support from the cylinder head and rear camshaft bearing cap.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;B>> CAMSHAFT BEARING CAP REMOVAL", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "In accordance with the numerical order shown in the illustration remove the installation bolt of each camshaft bearing cap.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "&lt;&lt;C>> VALVE TAPPET REMOVAL", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "To facilitate reassembly, attach a tag to each valve tappet removed that shows where it has been assembled.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400600000U00ENG.html", ">>A&lt;&lt; VALVE TAPPET INSTALLATION", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "Reassemble each valve tappet to the correct location shown on the tag.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", ">>B&lt;&lt; CAMSHAFT/CAMSHAFT BEARING CAP INSTALLATION", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "Install each camshaft, ensuring that the dowel pin faces the illustrated direction.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Remove the sealant from the rear camshaft bearing cap and cylinder head, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Follow the steps below to degrease the sealant application surface.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Before degreasing, make sure that the sealant application surface is free of dust, oil, or foreign materials.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Wipe the sealant application surface with a dry paper towel.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "By using detergent for aluminum, degrease the sealant application surface by spray cleaning.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Wipe detergent thoroughly with a dry paper towel. Do not touch the sealant application surface with your fingers, as the fingerprints adhering to the sealant surface affect the sealing.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Apply specified sealant to the matching area of the rear camshaft bearing cap as shown, and install the rear camshaft bearing cap to the cylinder head assembly.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Specified sealant: Three Bond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Install the rear camshaft bearing cap immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "The No. 2 to No. 5 camshaft bearing caps are equally shaped for both the intake and exhaust camshafts. Be sure to correctly install them by referring to the identification marks.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Identification mark (stamped on the No. 2 to No. 5 camshaft bearing caps)", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "I: Intake", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "E: Exhaust", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "In accordance with the numerical order shown in the illustration, tighten each camshaft bearing cap in several steps.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Tightening torque &lt;Cold engine>:", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "M6 bolt: 11 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "M8 bolt: 20 ± 1 N·m", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", ">>C&lt;&lt; FUEL PUMP SUPPORT INSTALLATION", "title");
si[i++] = gsitm("N502400600000U00ENG.html", "Remove the sealant from the fuel pump support and the matching area of the rear camshaft bearing cap and the cylinder head, and degrease the surface where the sealant is applied.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "When installing the fuel pump support 10 minutes after the rear camshaft bearing cap is assembled, clean the part shown in the figure.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "When installing the fuel pump support 10 minutes after the rear camshaft bearing cap is assembled, perform the operations below. Apply sealant to the positions shown of the cylinder head and bearing cap.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Apply sealant to the position shown of the fuel pump support.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Install the fuel pump support immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Tighten the fuel pump support mounting bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400600000U00ENG.html", "Tightening torque: 23 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502400610000T00ENG.html", "CAMSHAFT", "title");
si[i++] = gsitm("N502400610000T00ENG.html", "Measure the cam height. If the measured value exceeds the limit, replace the camshaft.", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Standard value:", "title");
si[i++] = gsitm("N502400610000T00ENG.html", "Intake: 44.71 mm", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Exhaust: 44.18 mm", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Limit:", "title");
si[i++] = gsitm("N502400610000T00ENG.html", "Intake: 44.21 mm", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Exhaust: 43.68 mm", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "VALVE TAPPET", "title");
si[i++] = gsitm("N502400610000T00ENG.html", "Measure the valve tappet at the illustrated location. If the measured valve is discord to instruction valve by identification mark and following table, replace the tappet.", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Every valve tappet has an identification mark stamped at the illustrated location.", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Valve tappets are available in 31 sizes, at 0.020 mm intervals in the 2.700 - 3.300 mm range, as shown in the following table.", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "Thickness mm", "ptxt");
si[i++] = gsitm("N502400610000T00ENG.html", "ID mark", "ptxt");
