si[i++] = gsitm("N502400630001500ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Store the removed parts separately by cylinder number, intake side, and exhaust side so that they can be reinstalled in the same place when reassembling.", "ptxt");
