si[i++] = gsitm("N502400630001500ENG.html", "Cylinder head", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400630001500ENG.html", "&lt;&lt;A>> CYLINDER HEAD BOLT REMOVAL", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Loosen the cylinder head bolts in 2 or 3 steps, and remove the cylinder head bolt.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "&lt;&lt;B>> RETAINER LOCK REMOVAL", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Use a special tool to compress the valve spring and to remove the retainer lock.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Valve spring compressor (MD998735)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Retainer holder C (MB992089)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Be careful not to allow retainer holder C to interfere with the wall of the tappet hole and to damage it.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Store the removed valve spring retainer locks separately so that they can be reinstalled in the same place when reassembling.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Store removed parts such as valves and springs with tags describing cylinder No. and installed position attached for reassembly.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "&lt;&lt;C>> EXHAUST VALVE REMOVAL (VALVE HANDLING PRECAUTIONS)", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Sodium reacts violently with water or moisture generation heat and liberating hydrogen. It must be handled with utmost care because otherwise the following dangerous conditions may result:", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Loss of eyesight if sodium gets in eyes.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Burns if sodium contacts skin.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Fire hazard.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Handling of Sodium-filled Exhaust Valves", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Sodium-filled exhaust valves are not dangerous and may be handled in the same way as ordinary valves unless they are broken.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Never try to break the valves and expose sodium to the air.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "When worn exhaust valves are to be discarded, have them disposed of by a salvage company equipped with special disposal system, notifying them that the valves contain sodium.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Should the exhaust valves be broken, neutralize sodium using the method described below, and discard the valves in the same way as ordinary valves.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "How to Neutralize Sodium", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Place a container filled with more than 10 liters of water in a well ventilated large space.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Wear rubber gloves and goggles, and carefully take out broken valves from the cylinder head.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Put a broken valves in the water-filled container and quickly get away from the container at least 2 or 3 m.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Valves must be neutralized one at a time.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Put a valve in the container only after sodium in the preceding one has completely reacted with water.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Do not let the solution contact the eyes or the skin.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Should it get in the eyes, immediately flush them with clean water thoroughly, and receive medical attention. When it contacts the skin, wash with ample amounts of clean water.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Keep fire away from the container during the neutralization. The resulting hydrogen gas is highly explosive.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "After the reaction has completed (hydrogen gas is not generated any longer), take out the valve with large tweezers.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "The reaction occurs when water enters the cavity in the valve. Hydrogen gas may be trapped inside the valve, temporarily blocking the water passage. In such a case, wait until hydrogen gas in released and remaining sodium reacts with water.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "After the neutralization of sodium, water in the container contains sodium hydroxide and is highly alkaline. The water solution should be disposed of according to local regulations.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "&lt;&lt;D>> VALVE STEM SEAL REMOVAL", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Use special tool valve stem seal pliers (MB992085) to firmly pinch the base of the stem seal and twist it right and left for pulling out.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400630001500ENG.html", ">>A&lt;&lt; EXHAUST VALVE STEM SEAL INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "The valve stem seal must not be reused.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Do not damage the tappet wall during assembly.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Be sure to use a special tool to install the valve stem seal. Poor installation causes oil loss via valve guides.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "If oil is not applied, the valve stem seal may rise to the surface after it is press fitted.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Apply a small amount of engine oil to the press-fit part and the lip part of the new valve stem seal.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use special tool valve stem seal installer (MD998775) to press-fit the valve stem seal into the valve guide.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Press-fit the valve stem seal until it contacts with the upper surface of the cylinder head.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", ">>B&lt;&lt; INTAKE VALVE SPRING SEAT / INTAKE VALVE STEM SEAL INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Use a special tool to install the valve stem seal, obeying the following procedures:", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "The special tool valve stem seal installer adjustable (MB992922) is composed of the components shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "1: Chuck", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "2: Sleeve", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "3: Lock nut (small)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "4: Outer pipe", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "5: Lock nut (large)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "6: Guide pin (5.9)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "7: Guide pin (4.9)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "8: Cap", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "9: Guide pin (5.4)", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Adjust the inside chuck diameter, obeying the following procedures.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the sleeve to the chuck as shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the shoulder of the valve stem seal to the chuck, aligning with the outer circumference line of the chuck as shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Turn the sleeve to wring the chuck.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Stop the sleeve at the position where you can easily remove the valve stem seal by hand.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use the (small) lock nut to fix the sleeve.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Adjust the stem seal insertion length (L), obeying the following procedures.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "The position, in which the end face of the outer pipe is aligned with the outer circumference line of the chuck, is 0 mm of the insertion length. Insert the chuck and the sleeve into the outer pipe to fit the nut as shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Turn the chuck to adjust the valve stem seal insertion length.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "The insertion length can change by 1 mm per the chuck turn.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "To easily know how many times the chuck is turned, put the mark at the position shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use a vernier caliper to measure the checkpoint (L1) of the insertion length shown in the illustration. Check the insertion length.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Insertion length: 14.4 mm", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use the (large) lock nut to fix the sleeve.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the cap to the guide pin (4.9).", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the guide pin (4.9) as shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Apply the engine oil to the valve stem seal to set the chuck.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the intake valve spring seat.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use the plastic hammer to insert the valve stem seal.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", ">>C&lt;&lt; VALVE SPRING INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Install the valve springs in the corresponding cylinder No., intake side and exhaust side where they were removed.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the valve spring so that the painted side (small diameter side) faces toward the camshaft.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Identification color:", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Intake side: White", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Exhaust side: Green", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Pitch interval:", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Camshaft side", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Wide", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Valve side", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Narrow", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", ">>D&lt;&lt; RETAINER LOCK INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Use a special tool to compress the valve spring and to install the retainer lock.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Reinstall the removed valve spring retainer locks in the same place where they were removed.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", ">>E&lt;&lt; CYLINDER HEAD GASKET INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Completely remove the liquid gasket on the upper plane of the cylinder block and the lower plane of the cylinder head.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Degrease the place specified in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Sufficiently check that there is no residual oil on the place where degreasing is performed. If fingerprints are left, do not touch it with bare hands after the degreasing, since the oils from your fingers will harm the seal ability.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "As shown in the illustration, apply sealant to the top face of cylinder block.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Specified sealant: ThreeBond 1217G or equivalent", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the cylinder head gasket immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the cylinder head gasket.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Check that the center of the liquid gasket is located toward the cylinder head gasket in the position specified in the illustration.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "As shown in the illustration, apply sealant to the top face of cylinder head gasket.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the cylinder head assembly immediately after the application of sealant.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Install the cylinder head assembly.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", ">>F&lt;&lt; CYLINDER HEAD BOLT WASHER / CYLINDER HEAD BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400630001500ENG.html", "Replace cylinder head bolts and washers with a new one.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Apply a small amount of engine oil to the thread of the bolts and to the washers.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "In accordance with the installation order, tighten them to the specified torque in several steps.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Tightening torque: 24.5 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Make sure all bolts reach the specified torque.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use special tool angle gauge (MB991614), tighten the bolts in the correct sequence by 180 to 184 degree angle.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "When the tightening angle is smaller than the specified tightening angle, the appropriate tightening capacity cannot be secured.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "When the tightening angle is larger than the specified tightening angle, remove the bolt to start from the beginning again according to the procedure.", "ptxt");
si[i++] = gsitm("N502400630001500ENG.html", "Use special tool angle gauge (MB991614), tighten the bolts in the correct sequence by 90 to 94 degree angle.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "CYLINDER HEAD", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Before cleaning, check the cylinder head for leakage of coolant or exhaust gas as well as cracks or other damage.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Remove oil, scale, sealant, carbon and other residues completely. Clean the oil passages and blow compressed air through them to verify that they are free of restriction.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Using a straight edge and a thickness gauge, measure the flatness of the cylinder head bottom surface.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Bottom face distortion", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Standard value: 0.03 mm or less", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Cylinder head height (standard value for new part): 112.9 - 113.1 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "The grinding limit for the cylinder head and block combined is 0.2 mm.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "VALVE", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "If the valve face-to-seat contact is uneven or interrupted, correct the valve seat.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Measure the valve head margin. If the measured value exceeds the limit, replace with a new valve.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Standard value:", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 0.85 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 1.50 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Limit:", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 0.70 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 1.35 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Measure the valve overall length. If the measured value exceeds the limit, replace with a new valve.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 89.61 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 90.94 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 89.11 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 90.44 mm mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "VALVE SPRING", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Measure the valve spring free height. If the measured value exceeds the limit, replace with a new spring.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 53.57 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 52.12 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 52.57 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 51.12 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Measure the valve spring out-of-squareness. If the measured value exceeds the limit, replace with a new spring.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Standard value: 2° or less", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Limit: 4°", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "VALVE GUIDE", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Measure the clearance between the valve guide and the valve stem. If the measured value exceeds the limit, replace the valve guide or the valve, or both.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 0.020 - 0.047 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 0.041 - 0.068 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake 0.10 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust 0.15 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "VALVE SEAT", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Assemble the valve, then measure the contact width. If the measurement exceeds the specified limit, replace or correct the valve seat.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Standard value: 1.1 - 1.5 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "If the variation in the width exceeds 0.2 mm even if the contact width is within the standard value, correct the valve sheet.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "REPAIR PROCEDURE OF VALVE SEAT", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Check clearance between valve guide and valve.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Repair the valve seat so that seat width and seat angle can become the specified shape.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Smear a lapping compound on the valve and valve seat after the repair. Fit the valve into the valve seat.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "REPLACEMENT PROCEDURE OF VALVE SEAT", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Scrape the valve seat to be replaced from inside to make its wall thickness thin before pulling out.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Repair the valve seat hole of the cylinder head to match it with the diameter of the oversize valve seat.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Intake valve seat oversize hole diameter:", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "0.30 O.S.: 31.83 - 31.85 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Exhaust valve seat oversize hole diameter:", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "0.30 O.S.: 28.32 - 28.34 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Press fit the valve seat, paying attention not to score the cylinder head inner diameter at room temperature.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Ream the valve seat.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Refer to \"Repair procedure of valve seat.\"", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "REPLACEMENT PROCEDURE OF VALVE GUIDE", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "Pull out the valve guide with a press toward the cylinder block side.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Ream the valve guide hole of the cylinder head to match it with the diameter of the oversize valve guide.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Do not use a valve guide with the same size as that of the pulled out valve guide because it cannot be press fitted.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Valve guide oversize hole diameter", "title");
si[i++] = gsitm("N502400640000S00ENG.html", "0.05 O.S.: 10.55 - 10.57 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Press fit the valve guide to the illustrated dimension.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Standard value: 12.7 - 13.3 mm", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "Press fit the valve guide from the cylinder head top surface.", "ptxt");
si[i++] = gsitm("N502400640000S00ENG.html", "After pressing fit the valve guide, insert a new valve to check for sliding.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>G&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod cap bolt", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>F&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod cap", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>D&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod bearing", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>E&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Piston, connecting rod assembly", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Piston ring No. 1", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "7.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Piston ring No. 2", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "8.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Oil ring", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "9.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Circlip", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "10.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "11.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Piston pin", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "12.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Piston", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "13.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "&lt;&lt;A>> CONNECTING ROD CAP REMOVAL", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "To facilitate reassembly, mark the side face of the connecting rod big end with the corresponding cylinder number.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "&lt;&lt;B>> PISTON PIN REMOVAL", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Remove the circlips.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Put the piston into the container which can hold sufficient engine oil to fully immerse the piston.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Heat the engine oil to warm the piston to approximately 70°C. And then pull out the piston pin.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "The clearance between the piston and the piston pin is an almost tight fit at room temperature. Therefore, be sure the heat the piston before pulling out the piston pin. In addition, note that the piston is hot after heating.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400680000U00ENG.html", ">>A&lt;&lt; PISTON PIN INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Set the circlip into one side of the piston pin hole.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Heat the engine oil to warm the piston to approximately 70°C.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Apply ample coat of engine oil to the periphery of the piston pin and the hole of the connecting rod small end. The clearance between the piston and the piston pin is an almost tight fit at room temperature. Therefore, be sure to heat the piston before inserting the piston pin. In addition, note that the piston is hot after heating.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "With the front mark of the connecting rod and that of the piston located on the same side, insert the piston pin.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Set the circlip into the other side of the piston pin hole.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Check that the piston moves smoothly", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>B&lt;&lt; OIL RING INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Install the oil ring spacer first into the piston ring groove, followed by the upper side rail and then the lower side rail.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Side rails can be installed easily by first inserting one end of the rail into the piston groove, then pressing the rail into place with finger.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Do not use a ring expander on side rails as they may break when the gap is opened.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "With the side rails installed onto the piston, check that they can be rotated smoothly in both directions.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>C&lt;&lt; PISTON RING NO. 2 / PISTON RING NO. 1 INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Use a piston ring expander to install the No. 1 and No. 2 piston rings. The ring identification mark should face upwards.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Identification mark", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "No. 1 ring: 1T", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "No. 2 ring: 2T", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>D&lt;&lt; CONNECTING ROD BEARING INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod bearings are number coded with paint at the illustrated locations. Bearings should be selected based on the following table.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Crankshaft Identification mark", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting rod Identification mark", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Connecting bearing Identification mark", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "0", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "1", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Black or 1", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "2", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "None or 2", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Green or 3", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Blue or 4", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Measure the illustrated location. The error should be within 0.5 mm.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>E&lt;&lt; PISTON, CONNECTING ROD ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Apply engine oil sufficiently onto the piston periphery, the piston rings and the oil ring.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Align the gaps of the piston rings and the oil ring (side rails, spacer) as illustrated.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Insert the piston and connecting rod assembly from above the cylinder block and through the cylinder bore, ensuring that the front mark on the piston top faces the camshaft sprocket.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "While firmly holding the piston rings with a ring band, insert the piston and connecting rod assembly into place.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Do not try to strike hard on the assembly to fit it in place as this will break the piston rings.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>F&lt;&lt; CONNECTING ROD CAP INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "The connecting rod resulting from the breaking process has the high insertion force. The new connecting rod assembly may possibly be difficult to remove the connecting rod.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "If difficult to remove it, alternately strike the two bolt heads with a plastic hammer while the connecting rod bolt is slightly loosened, or strike the center of the cap shaft\'s inside diameter slightly and outward.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "If the outside of the cap is directly struck, the lateral force is added to the broken-out section. Thus, pay attention to the broken-out section that might be difficult to be separated or might fall.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Clean the broken-out section before the installation to the engine, using compression air.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Install the correct bearing cap onto the corresponding connecting rod, based on the marking placed during disassembly.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Ensure that the thrust clearance of the connecting rod big end is to specification.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Standard value: 0.10 - 0.35 mm", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Limit: 0.4 mm", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", ">>G&lt;&lt; CONNECTING ROD CAP BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400680000U00ENG.html", "Check in the following procedure before reusing the connecting rod bolt.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Measure the outside diameter \"A.\"", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Measure the smallest outside diameter \"B\" within the range \"X\" shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "If the difference of outside diameter of thread exceeds the limit, replace the connecting rod bolt.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Limit: 0.1 mm", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Apply engine oil to the threaded portion and seating face of the bolt.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "To correctly install the cap, loosely install the bolts with fingers.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Alternately, tighten the bolts in several steps to the specified torque.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Tightening torque: 14.7 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "Use special tool angle gauge (MB991614), tighten the bolt 120 ± 2 degree angle.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "When the tightening angle is smaller than the specified tightening angle, the appropriate tightening capacity cannot be secured.", "ptxt");
si[i++] = gsitm("N502400680000U00ENG.html", "When the tightening angle is larger than the specified tightening angle, remove the bolt to start from the beginning again according to the procedure.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502400690000R00ENG.html", "PISTON RING", "title");
si[i++] = gsitm("N502400690000R00ENG.html", "Measure the clearance between the piston ring and the ring groove. If the measured value exceeds the limit, replace the piston ring, or both the piston and the piston ring.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Standard value:", "title");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 1 ring: 0.040 - 0.085 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 2 ring: 0.040 - 0.080 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Limit: 0.1 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Insert the piston ring into the cylinder bore. Insert the piston with the top face end first into the cylinder bore, pushing the piston ring and positioning it squarely with the cylinder bore. Then, measure the piston ring end gap using a feeler gauge. If the measured value exceeds the limit, replace the piston ring.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 1 ring: 0.21 - 0.24 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 2 ring: 0.40 - 0.55 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Oil ring: 0.10 - 0.35 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Limit:", "title");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 1 ring: 0.8 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "No. 2 ring: 0.8 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Oil ring: 1.0 mm", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "CRANKSHAFT PIN OIL CLEARANCE (PLASTIGAGE METHOD)", "title");
si[i++] = gsitm("N502400690000R00ENG.html", "Wipe off oil from the crankshaft pin and the connecting rod bearings.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Place a plastigage, with a length equal to the bearing width, onto the crank pin in the axial direction.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Carefully install the connecting rod cap over the plastigage, and tighten the bolts to 14.7 ± 2 N·m then +120 ± 2 degree angle.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Remove the bolts. Slowly remove the connecting rod cap.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Using the measure printed on the plastigage package, measure the width (widest portion) of the crushed plastigage.", "ptxt");
si[i++] = gsitm("N502400690000R00ENG.html", "Standard value: 0.020 - 0.038 mm", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>G&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Water jacket spacer", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>F&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Stiffener plate", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>E&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing cap bolt", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing cap", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>D&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing lower No.1", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "6.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing lower No.2 to No.5", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "7.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "8.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing upper No.1", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "9.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing upper No.2 to No.5", "ptxt");
