si[i++] = gsitm("N502400710000U00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "11.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft sensing ring", "ptxt");
