si[i++] = gsitm("N502400710000U00ENG.html", "Cylinder block", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "&lt;&lt;A>> CRANKSHAFT BEARING CAP BOLT REMOVAL", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Loosen and remove the bolts in the order of number shown in the figure.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502400710000U00ENG.html", ">>A&lt;&lt; CRANKSHAFT SENSING RING INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Install the crankshaft sensing ring to the crankshaft after aligning a stamp to the position as shown in the illustration when the crankshaft set the No.1 cylinder to the top dead center of compression.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tighten the crankshaft sensing ring screws to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>B&lt;&lt; THRUST BEARING INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Install the thrust bearing onto the cylinder block side of the No. 4 bearing. Apply engine oil to the thrust bearing to facilitate installation.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "The thrust bearing should be installed such that its groove faces the crankshaft weight.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>C&lt;&lt; CRANKSHAFT BEARING UPPER INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "The crankshaft bearing upper should be selected based on the identification mark on the right side face of the cylinder block (illustrated) and the table shown below.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing number", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Identification mark", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Journal diameter mm", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "1", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "50.000 - 50.005", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "2", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "50.005 - 50.010", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "3", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "50.010 - 50.015", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Every crankshaft bearing upper is identified by the number mark at the illustrated location.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Select and install the crankshaft bearing upper.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Measure the illustrated location. The error should be within 0.5 mm.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>D&lt;&lt; CRANKSHAFT BEARING LOWER INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "The crankshaft bearing lower should be selected based on the identification mark on the crankshaft rear flange (illustrated) and the table shown below.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Crankshaft bearing number mark", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "46.019 - 46.024", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "46.014 - 46.019", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "4", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "46.009 - 46.014", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "5", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "46.004 - 46.009", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Every crankshaft bearing lower is identified by the number mark at the illustrated location.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Select and install the crankshaft bearing lower.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>E&lt;&lt; CRANKSHAFT BEARING CAP / CRANKSHAFT BEARING CAP BOLT INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Install the bearing cap.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Before the bearing cap bolt is installed, check the nominal length of the bolt. If above the standard value, replace the bolt with the new one.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Standard value: 88.5 - 89.5 mm", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Apply engine oil to the threaded portion and seating face of the bolt.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tighten the nuts to specified torque in the sequence shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tighten the bearing cap bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tightening torque: 5.0 ± 2.0 N·m", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tightening torque: 35 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Using the special tool angle gauge (MB991614), tighten the bearing cap bolts in the illustrated sequence by a further 120 to 124 degree angle.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "When the tightening angle is smaller than the specified tightening angle, the appropriate tightening capacity cannot be secured.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "When the tightening angle is larger than the specified tightening angle, remove the bolt to start from the beginning again according to the procedure.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "With the bearing caps installed, check the crankshaft end play. If the measured value exceeds the limit, replace the crankshaft bearings.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Standard value: 0.09 - 0.27 mm", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Limit: 0.30 mm", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>F&lt;&lt; STIFFENER INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Tighten the stiffener plate bolts to the specified torque in the order of the numbers shown in the illustration.", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", "Tightening torque: 26 ± 6 N·m", "ptxt");
si[i++] = gsitm("N502400710000U00ENG.html", ">>G&lt;&lt; WATER JACKET SPACER INSTALLATION", "title");
si[i++] = gsitm("N502400710000U00ENG.html", "Install the water jacket spacer on the cylinder block with the protruding part of the spacer in the direction shown in the figure, making sure that no oil, grease or foreign matter adheres to the spacer.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502400720000V00ENG.html", "CRANKSHAFT OIL CLEARANCE (USING PLASTIGAGE)", "title");
si[i++] = gsitm("N502400720000V00ENG.html", "Oil clearance can be measured easily by using \"plastigage.\"", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Use the \"plastigage\" in the following manner.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Wipe off oil from the surfaces of the crankshaft journals as well as the inner surfaces of the bearings.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Assemble the crankshaft.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Place a plastigage, with a length equal to the width of the bearing, onto the journals in the axial direction.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Carefully place the main bearing caps, and tighten the bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Remove the bolts. Carefully remove the main bearing caps.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Using the measure printed on the plastigage package, measure the width (widest portion) of the crushed plastigage.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Standard value: 0.014 - 0.034 mm", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Limit: 0.1 mm", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "CYLINDER BLOCK", "title");
si[i++] = gsitm("N502400720000V00ENG.html", "Check visually for scoring, rust, or corrosion. Perform liquid penetrant test etc. to check for cracks. If faulty, replace.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Using a straight edge or a thickness gauge, measure the flatness of the cylinder block top surface. If distortion exceeds the limit, grind and repair it. Ensure that no gasket or other foreign matter is attached to the top face.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Standard value: 0.05 mm", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Check the cylinder bore for scoring or seizure. If faulty, replace.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Using a cylinder gauge, measure the cylinder bore and centricity. If excessively worn, replace the cylinder block.", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Standard value:", "title");
si[i++] = gsitm("N502400720000V00ENG.html", "Inner diameter 75 mm", "ptxt");
si[i++] = gsitm("N502400720000V00ENG.html", "Cylindrically 0.01 mm or less", "ptxt");
si[i++] = gsitm("N502410010000G00ENG.html", "GENERAL DESCRIPTION", "title");
si[i++] = gsitm("N502410010000G00ENG.html", "The lubrication system is the full-flow, filter pumping system.", "ptxt");
si[i++] = gsitm("N502410010000G00ENG.html", "The engine oil that accumulates in the oil pan is drawn and discharged by the oil pump. After its pressure is regulated by the oil pump, the oil passes through the oil filter and oil cooler. Then, it flows from the oil passage in the cylinder block to the individual crankshaft journals and the cylinder head.", "ptxt");
si[i++] = gsitm("N502410010000G00ENG.html", "After the oil is pumped to the individual crankshaft journals, it passes through a passage in the crankshaft and is fed to the pins. After the oil is pumped to the cylinder head, it flows to the camshaft journals and the oil feeder control valves.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "LUBRICATION RELATION", "title");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL FILLER CAP", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL DIPSTICK", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "DRAIN PLUG", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL PAN LOWER", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "The oil pan lower, located below the engine, is made of sheet metal.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL PAN UPPER", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "An aluminum oil pan upper is adopted to reduce the vibration and noise of the engine unit.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "A connection part is added between the oil pan upper and transaxle to reduce the vibration and noise of the entire power plant and to improve quietness.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL FILTER", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "The oil filter is installed to the oil filter bracket.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL COOLER", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "A water-cooled oil cooler has been adopted.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "ENGINE OIL PRESSURE SWITCH, ENGINE OIL PRESSURE SENSOR", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "The engine oil pressure switch and the engine oil pressure sensor are installed to the cylinder block.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "OIL PUMP", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "The oil pump is incorporated into the timing chain case and is driven directly by the crankshaft.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "A vane-type variable displacement oil pump has been adopted. The engine oil pressure is controlled optimally by varying the oil pump capacity by the oil relief control valve to reduce engine friction.", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "Type", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "Vane pump", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "Number of vanes", "ptxt");
si[i++] = gsitm("N502410020000F00ENG.html", "9", "ptxt");
si[i++] = gsitm("N502410030000F00ENG.html", "OIL PASSAGE", "title");
si[i++] = gsitm("N502411000000900ENG.html", "GENERAL INFORMATION", "title");
si[i++] = gsitm("N502411000000900ENG.html", "The lubrication method is a fully force-fed, full-flow filtration type.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "The oil pump is a vane type which is driven by the crankshaft.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "ENGINE OILS HEALTH WARNING", "title");
si[i++] = gsitm("N502411000000900ENG.html", "Prolonged and repeated contact with mineral oil will result in the removal of natural fats from the skin, leading to dryness, irritation and dermatitis. In addition, used engine oil contains potentially harmful contaminants which may cause skin cancer. Adequate means of skin protection and washing facilities must be provided.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "RECOMMENDED PRECAUTIONS", "title");
si[i++] = gsitm("N502411000000900ENG.html", "The most effective precaution is to adapt working practices which prevent, as far as practicable, the risk of skin contact with mineral oils, for example by using enclosed systems for handling used engine oil and by degreasing components, where practicable, before handling them. Other precautions:", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Avoid prolonged and repeated contact with oils, particularly used engine oils.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Wear protective clothing, including impervious gloves where practicable.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Avoid contaminating clothes, particularly underpants, with oil.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Do not put oily rags in pockets, the use of overalls without pockets will avoid this.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Do not wear heavily soiled clothing and oil-impregnated foot-wear. Overalls must be cleaned regularly and kept separate from personal clothing.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Where there is a risk of eye contact, eye protection should be worn, for example, chemical goggles or face shields; in addition an eye wash facility should be provided.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Obtain first aid treatment immediately for open cuts and wounds.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Wash regularly with soap and water to ensure all oil is removed, especially before meals (skin cleansers and nail brushes will help). After cleaning, the application of preparations containing lanolin to replace the natural skin oils is advised.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Do not use gasoline, kerosine, diesel fuel, gas oil, thinners or solvents for cleaning skin.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "Use barrier creams, applying them before each work period, to help the removal of oil from the skin after work.", "ptxt");
si[i++] = gsitm("N502411000000900ENG.html", "If skin disorders develop, obtain medical advice without delay.", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "SERVICE SPECIFICATION", "title");
si[i++] = gsitm("N502411010000J00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "Standard value", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "Oil pressure kPa", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "at idle", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "29 or more", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "at 3,500 r/min", "ptxt");
si[i++] = gsitm("N502411010000J00ENG.html", "294 – 686", "ptxt");
si[i++] = gsitm("N502411030000K00ENG.html", "SEALANT", "title");
