si[i++] = gsitm("N502411030000K00ENG.html", "Semi-drying sealant", "ptxt");
si[i++] = gsitm("N502411030000K00ENG.html", "Engine oil pressure sensor", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "LUBRICANTS", "title");
si[i++] = gsitm("N502411020000X00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Engine oil classification", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Select engine oil of the proper SAE viscosity number according to the atmospheric temperature.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "It is recommended to use engine oil that complies with API classification.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "API classification: “For service SN” or higher.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "If using oils other than those mentioned above, use one of the following types.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "ILSAC certificated oil", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "ACEA classification:", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "“For service A3/B3, A3/B4, or A5/B5”*", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "*: Only oils that simultaneously meet API classification“SN or higher” are permitted.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "SAE 0W-20, 0W-30, 5W-20, 5W-30 and 5W-40 engine oils can only be used if they meet ACEA A3/B3, A3/B4 or A5/B5 and API “SN or higher” specifications.", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Engine oil quantity L", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "With oil filter change", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Approximately 4.3", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Without oil filter change", "ptxt");
si[i++] = gsitm("N502411020000X00ENG.html", "Approximately 4.1", "ptxt");
si[i++] = gsitm("N502411040000J00ENG.html", "SPECIAL TOOL", "title");
