si[i++] = gsitm("N502411060000H00ENG.html", "Rear oil seal", "ptxt");
si[i++] = gsitm("N502411060000H00ENG.html", "Oil pan", "ptxt");
si[i++] = gsitm("N502411060000H00ENG.html", "Oil filter", "ptxt");
si[i++] = gsitm("N502411060000H00ENG.html", "Drain plug", "ptxt");
si[i++] = gsitm("N502411060000H00ENG.html", "Oil hose", "ptxt");
si[i++] = gsitm("N502411060000H00ENG.html", "Oil cooler", "ptxt");
si[i++] = gsitm("N502411070000J00ENG.html", "ENGINE OIL CHECK", "title");
si[i++] = gsitm("N502411070000J00ENG.html", "Pull out the engine oil dipstick slowly and check that the oil level is in the illustrated range.", "ptxt");
si[i++] = gsitm("N502411070000J00ENG.html", "Check that the oil is not excessively dirty, that there is no coolant or gasoline mixed in, and that it has sufficient viscosity.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "ENGINE OIL CHANGE", "title");
si[i++] = gsitm("N502411080001000ENG.html", "Start the engine and allow it to warm up until the temperature of the coolant reaches 80°C to 90°C.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Remove the engine oil filler cap.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Use care as engine oil could be hot.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Remove the engine room under cover front B (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Remove the engine oil pan drain plug to drain engine oil.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Install a new engine oil pan drain plug gasket and then tighten the engine oil pan drain plug to the specified torque.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Tightening torque: 39 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Refill with specified quantity of engine oil.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Specified engine oil:", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Select engine oil of the proper SAE viscosity number according to the atmospheric temperature.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "It is recommended to use engine oil that complies with API classification.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "API classification: “For service SN” or higher.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "If using oils other than those mentioned above, use one of the following types.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "ILSAC certificated oil", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "ACEA classification:", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "“For service A3/B3, A3/B4, or A5/B5”*", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "*: Only oils that simultaneously meet API classification“SN or higher” are permitted.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "SAE 0W-20, 0W-30, 5W-20, 5W-30 and 5W-40 engine oils can only be used if they meet ACEA A3/B3, A3/B4 or A5/B5 and API “SN or higher” specifications.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Engine oil quantity:", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "With oil filter change: Approximately 4.3 L", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Without oil filter change: Approximately 4.1 L", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil is recommended for optimum fuel economy and cold weather starting.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "If Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil is not available, 5W-20 grade oils displaying the ILSAC certification can be used. However, Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil should be used at the next oil change to maintain optimum fuel economy and cold weather starting.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Install the engine oil filler cap.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Let the engine run for a few minutes.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Stop the engine, and then check the engine oil level using the engine oil dipstick after a few minutes.", "ptxt");
si[i++] = gsitm("N502411080001000ENG.html", "Install the engine room under cover front B (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "ENGINE OIL FILTER REPLACEMENT", "title");
si[i++] = gsitm("N502411090000L00ENG.html", "Remove the engine oil pan drain plug to drain engine oil (Refer to ).", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Use special tool oil filter wrench (MB991396) or commercially-available tool to remove the engine oil filter.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Clean the engine oil filter installing surface on the engine oil filter bracket side.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Apply a small amount of engine oil to the new engine oil filter O-ring.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Tighten the engine oil filter until the O-ring contacts with the installation surface.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "In the same manner as removal, use special tool oil filter wrench (MB991396) or commercially-available tool to tighten the engine oil filter to the specified torque.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Tightening torque: Approximately 1 turn (14 ± 2 N·m)", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Install the engine oil pan drain plug and refill the engine oil (Refer to ).", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Rev the engine a few times, and check to be sure that no engine oil leaks from the installation section of the engine oil filter.", "ptxt");
si[i++] = gsitm("N502411090000L00ENG.html", "Install the engine room under cover front B (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "ENGINE OIL PRESSURE CHECK", "title");
si[i++] = gsitm("N502411110000K00ENG.html", "Check engine oil level (Refer to ).", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Remove the engine oil pressure switch (Refer to ).", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Install the oil pressure gauge.", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Use an adapter of PT 1/8 thread.", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Run the engine to warm it.", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "After the engine has been warmed up, check that oil pressure is within the standard value.", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "At idle: 29 kPa or more", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "At 3,500 r/min: 294 - 686 kPa", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Remove the oil pressure gauge.", "ptxt");
si[i++] = gsitm("N502411110000K00ENG.html", "Install the engine oil pressure switch (Refer to ).", "ptxt");
