si[i++] = gsitm("N502411130000J00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502411130000J00ENG.html", "&lt;&lt;A>> ENGINE OIL PRESSURE SWITCH REMOVAL", "title");
si[i++] = gsitm("N502411130000J00ENG.html", "The sealant is applied to the bolt. Remove the bolt with care not to break it.", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502411130000J00ENG.html", ">>A&lt;&lt; ENGINE OIL PRESSURE SWITCH INSTALLATION", "title");
si[i++] = gsitm("N502411130000J00ENG.html", "Apply sealant to the engine oil pressure switch thread.", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "Specified sealant: ThreeBond 1215 or equivalent", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "Install the engine oil pressure switch immediately after applying sealant.", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "After the installation, until a sufficient period of time (one hour or more) elapses, do not apply the engine oil or water to the sealant application area or start the engine.", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "Tighten the engine oil pressure switch to the specified torque.", "ptxt");
si[i++] = gsitm("N502411130000J00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
