si[i++] = gsitm("N502500410000A00ENG.html", "OBD-II DRIVE CYCLE", "title");
si[i++] = gsitm("N502500410000A00ENG.html", "All kinds of diagnostic codes (Diagnosis Codes) can be monitored by carrying out a short drive according to the following 30 drive cycle patterns. In other words, doing such a drive regenerates any kind of trouble which involves illuminating the Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) and verifies the diagnosis code malfunction is fixed [the Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) is no longer illuminated].", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "Two technicians should always be in the vehicle when carrying out a test.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "Perform the pattern of the trouble check at least two times.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "Do not lack the safety in patterns with high vehicle speed and high load operation.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "Check that the diagnosis trouble code (Diagnosis Code) is not set before driving the OBD-II drive cycle.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "Erase the diagnosis code with M.U.T.-III SE if it has been set. Excluding diagnosis code driving the OBD-II drive cycles of pattern 1 to 15.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "For P0461 please reference the M.U.T.-III SE data list to judge whether these monitor items are normal.", "ptxt");
si[i++] = gsitm("N502500410000A00ENG.html", "DRIVE CYCLE PATTERN LIST", "title");
