si[i++] = gsitm("N502500490000900ENG.html", "Code No. P0010-00: Inlet oil feeder control valve circuit", "title");
si[i++] = gsitm("N502500490000900ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502500490000900ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502500490000900ENG.html", "Power is supplied to the inlet engine oil control valve from the engine control relay.", "ptxt");
si[i++] = gsitm("N502500490000900ENG.html", "The ECM connector terminal OCVI makes the power transistor in the unit be in ON position, and that makes currents go on the inlet engine oil control valve.", "ptxt");
si[i++] = gsitm("N502500490000900ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502500490000900ENG.html", "The ECM controls the spool valve position of the inlet engine oil control valve corresponding to the driving condition of the engine and continuously changes the angle of the inlet camshaft.", "ptxt");
si[i++] = gsitm("N502500490000900ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N502500490000900ENG.html", "Inlet oil feeder control valve circuit current is out of the specified range.", "ptxt");
