si[i++] = gsitm("N5025004C0000700ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025004C0000700ENG.html", "Power is supplied to the exhaust oil feeder control valve from the engine control relay.", "ptxt");
si[i++] = gsitm("N5025004C0000700ENG.html", "The ECM connector terminal OCVE makes the power transistor in the unit be in ON position, and that makes currents go on the exhaust oil feeder control valve.", "ptxt");
