si[i++] = gsitm("N5025004P0000500ENG.html", "Code No. P0069-00: Abnormal correlation between manifold absolute pressure sensor and barometric pressure sensor &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025004P0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025004P0000500ENG.html", "The ECM detects abnormality in the sensor by comparing the manifold absolute pressure sensor output with the barometric pressure sensor output.", "ptxt");
si[i++] = gsitm("N5025004P0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025004P0000500ENG.html", "The ECM compares the manifold absolute pressure sensor output with the barometric pressure sensor output after the ignition switch is in \"LOCK\" (OFF) position. When the difference exceeds the specified value between them, the ECM determines whether the manifold absolute pressure sensor/the barometric pressure sensor has malfunction or not.", "ptxt");
