si[i++] = gsitm("N5025004U0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025004U0000600ENG.html", "The No. 2 intake air temperature sensor converts the intake air temperature into a voltage and inputs the voltage signal to the ECM.", "ptxt");
si[i++] = gsitm("N5025004U0000600ENG.html", "In response to the signal, the ECM corrects the fuel injection amount, etc.", "ptxt");
si[i++] = gsitm("N5025004U0000600ENG.html", "The No. 2 intake air temperature sensor is a kind of resistor, which has characteristics to reduce its resistance as the intake air temperature rises. Therefore, the sensor output voltage varies with the intake air temperature, and becomes lower as the intake air temperature rises.", "ptxt");
