si[i++] = gsitm("N5025004X0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025004X0000600ENG.html", "The intercooler coolant temperature sensor converts the intercooler coolant temperature into a voltage signal, and inputs the voltage to the ECM.", "ptxt");
si[i++] = gsitm("N5025004X0000600ENG.html", "The intercooler coolant temperature sensor is a kind of resistor, which has characteristics to reduce its resistance as the intercooler coolant temperature rises. Therefore, the sensor output voltage varies with the intercooler coolant temperature, and becomes lower as the intercooler coolant temperature rises.", "ptxt");
