si[i++] = gsitm("N502500500000500ENG.html", "The air temperature sensor is a kind of resistor, which has characteristics to reduce its resistance as the intake air temperature rises. Therefore, the sensor output voltage varies with the intake air temperature, and becomes lower as the intake air temperature rises.", "ptxt");
