si[i++] = gsitm("N502500530000600ENG.html", "Code No. P00EB-00: Air Temperature Sensor circuit high (bottom throttle)", "title");
si[i++] = gsitm("N502500530000600ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502500530000600ENG.html", "A power voltage of 5 V is applied to the air temperature sensor power terminal of air flow sensor connector from the ECM connector terminal MATS.", "ptxt");
si[i++] = gsitm("N502500530000600ENG.html", "The power voltage is grounded to the ECM connector terminal MAPE from the air temperature sensor.", "ptxt");
si[i++] = gsitm("N502500530000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502500530000600ENG.html", "The air temperature sensor converts the intake air temperature into a voltage and inputs the voltage signal to the ECM.", "ptxt");
si[i++] = gsitm("N502500530000600ENG.html", "In response to the signal, the ECM corrects the fuel injection amount, etc.", "ptxt");
si[i++] = gsitm("N502500530000600ENG.html", "The air temperature sensor is a kind of resistor, which has characteristics to reduce its resistance as the intake air temperature rises. Therefore, the sensor output voltage varies with the intake air temperature, and becomes lower as the intake air temperature rises.", "ptxt");
si[i++] = gsitm("N502500530000600ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N502500530000600ENG.html", "No. 3 intake air temperature sensor output voltage is out of specified range.", "ptxt");
