si[i++] = gsitm("N502500540000900ENG.html", "Power is supplied by the engine control relay to the air flow sensor.", "ptxt");
si[i++] = gsitm("N502500540000900ENG.html", "Power is supplied by the ECM connector terminal AFS5 to the air flow sensor, and the air flow sensor is grounded through the ECM connector terminal AFSE.", "ptxt");
si[i++] = gsitm("N502500540000900ENG.html", "The air flow sensor outputs a sensor signal, which is input into the ECM connector terminal AFS.", "ptxt");
si[i++] = gsitm("N502500540000900ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502500540000900ENG.html", "The air flow sensor outputs current that varies in accordance with the intake air volume.", "ptxt");
si[i++] = gsitm("N502500540000900ENG.html", "The ECM uses the amperage output by the air flow sensor and the engine speed signal in order to determine the basic injection duration of the fuel injector.", "ptxt");
