si[i++] = gsitm("N502500590000800ENG.html", "The No. 1 intake air temperature sensor converts the change in thermistor resistance to the voltage corresponding to the intake air temperature by the signal processing circuit and outputs the voltage to the ECM.", "ptxt");
si[i++] = gsitm("N502500590000800ENG.html", "The ECM checks whether this voltage is within a specified range.", "ptxt");
