si[i++] = gsitm("N502500590000800ENG.html", "The temperature change of No. 1 intake air temperature sensor is too small or too large relative to the temperature change of the other temperature sensors (engine coolant temperature sensor, No. 2 intake air temperature sensor, No. 3 intake air temperature sensor, EGR gas temperature sensor).", "ptxt");
