si[i++] = gsitm("N5025005A0000500ENG.html", "Code No. P0111-00: Intake air temperature circuit range/performance problem (sensor 1) &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "Approximately 5 V are applied to the No. 1 intake air temperature sensor output terminal from the ECM terminal ATS via the resistor in the ECM. The ground terminal is grounded with ECM terminal AFSE.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "The No. 1 intake air temperature sensor is a negative temperature coefficient type of resistor. When the intake air temperature rises, the resistance decreases.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "The No. 1 intake air temperature sensor output voltage increases when the resistance increases and decreases when the resistance decreases.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "The No. 1 intake air temperature sensor converts the intake air temperature to a voltage.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "The ECM checks whether this voltage is within a specified range.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "No. 1 intake air temperature sensor output voltage does not change when specified go/stop operations are repeated.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "MONITOR EXECUTION", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "Continuous.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "MONITOR EXECUTION CONDITIONS (Other monitor and Sensor)", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "Other Monitor (There is no temporary diagnosis code set in memory for the item monitored below)", "title");
si[i++] = gsitm("N5025005A0000500ENG.html", "Not applicable", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Sensor (The sensor below is determined to be normal)", "title");
