si[i++] = gsitm("N5025005A0000500ENG.html", "Remove the air flow sensor from the air intake hose.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Set M.U.T.-III SE to the data reading mode for item 5, Air Temperature Sensor.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Heating the sensor using a hair drier.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "The indicated temperature increases.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Do not allow it to increase over 80°C.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Attach the air flow sensor.", "ptxt");
si[i++] = gsitm("N5025005A0000500ENG.html", "Is the sensor operating properly?", "question");
si[i++] = gsitm("N5025005A0000500ENG.html", "YES", "result");
