si[i++] = gsitm("N5025005D0000500ENG.html", "Code No. P0116-00: Engine coolant temperature circuit range/performance problem &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025005D0000500ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025005D0000500ENG.html", "A power voltage of 5 V is applied to the engine coolant temperature sensor output terminal from the ECM terminal WTS via the resistor in the ECM. The ground terminal is grounded with ECM terminal WTSE.", "ptxt");
si[i++] = gsitm("N5025005D0000500ENG.html", "The engine coolant temperature sensor is a negative temperature coefficient type of resistor. It has the characteristic that when the engine coolant temperature rises the resistance decreases.", "ptxt");
si[i++] = gsitm("N5025005D0000500ENG.html", "The engine coolant temperature sensor output voltage increases when the resistance increases and decreases when the resistance decreases.", "ptxt");
si[i++] = gsitm("N5025005D0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025005D0000500ENG.html", "The engine coolant temperature sensor converts the engine coolant temperature to a voltage and outputs it.", "ptxt");
si[i++] = gsitm("N5025005D0000500ENG.html", "The ECM checks whether this voltage is within a specified range.", "ptxt");
si[i++] = gsitm("N5025005D0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025005D0000500ENG.html", "Engine coolant temperature sensor output voltage does not change for specified period.", "ptxt");
