si[i++] = gsitm("N5025005R0000600ENG.html", "Code No. P0138-00: Oxygen sensor (rear) circuit high voltage", "title");
si[i++] = gsitm("N5025005R0000600ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025005R0000600ENG.html", "The sensor signal is inputted to the ECM connector terminal O2RL from the oxygen sensor (rear) output terminal.", "ptxt");
si[i++] = gsitm("N5025005R0000600ENG.html", "The oxygen sensor (rear) ground terminal is grounded at ECM connector terminal ORLE.", "ptxt");
si[i++] = gsitm("N5025005R0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025005R0000600ENG.html", "The oxygen sensor (rear) converts the concentration of oxygen in the exhaust emission into a voltage and inputs the signal to the ECM.", "ptxt");
si[i++] = gsitm("N5025005R0000600ENG.html", "When the air-fuel ratio is richer than the theoretical air-fuel ratio, the oxygen sensor (rear) outputs a voltage of about 1 V. When it is leaner than the theoretical air-fuel ratio, it outputs a voltage of about 0 V.", "ptxt");
si[i++] = gsitm("N5025005R0000600ENG.html", "In response to the signal, the ECM controls the fuel injection amount so that the air-fuel ratio can be equivalent to the theoretical air-fuel ratio.", "ptxt");
si[i++] = gsitm("N5025005R0000600ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025005R0000600ENG.html", "Oxygen sensor (rear) output voltage is over specified range.", "ptxt");
