si[i++] = gsitm("N5025005U0000500ENG.html", "Code No. P0140-00: Oxygen sensor (rear) circuit no activity detected", "title");
si[i++] = gsitm("N5025005U0000500ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025005U0000500ENG.html", "Check code No. P0137-00: Oxygen sensor (rear) circuit low voltage (Refer to ).", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025005U0000500ENG.html", "The oxygen sensor (rear) converts the concentration of oxygen in the exhaust emission into a voltage and inputs the signal to the ECM.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "When the air-fuel ratio is richer than the theoretical air-fuel ratio, the oxygen sensor (rear) outputs a voltage of about 1 V. When it is leaner than the theoretical air-fuel ratio, it outputs a voltage of about 0 V.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "In response to the signal, the ECM controls the fuel injection amount so that the air-fuel ratio can be equivalent to the theoretical air-fuel ratio.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025005U0000500ENG.html", "Oxygen sensor (rear) output voltage does not change during specified go/stop operations including fuel cut are repeated.", "ptxt");
