si[i++] = gsitm("N5025005U0000500ENG.html", "Volumetric efficiency is higher than 40%.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "Vehicle speed is more than 30 km/h.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "A total of more than 60 seconds have passed with the above mentioned conditions, and more than 3 seconds have passed with the fuel shut off.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "Stop*2:", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "Vehicle speed is less than 1.5 km/h.", "ptxt");
