si[i++] = gsitm("N5025005U0000500ENG.html", "Change in the output voltage of oxygen sensor (rear) is less than 0.313 volts.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "or", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "The maximum output voltage of oxygen sensor (rear) is less than 0.508 volts.", "ptxt");
si[i++] = gsitm("N5025005U0000500ENG.html", "Monitoring stops after fuel has been shut off for more than 64 seconds.", "ptxt");
