si[i++] = gsitm("N5025044A0000300ENG.html", "Code No. P014C-00: Linear A/F sensor slow response - Rich to Lean &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025044A0000300ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025044A0000300ENG.html", "The ECM effects air/fuel ratio feedback control in accordance with the signals from the linear A/F sensor.", "ptxt");
si[i++] = gsitm("N5025044A0000300ENG.html", "If the linear A/F sensor has deteriorated, corrections will be made by the oxygen sensor (rear).", "ptxt");
si[i++] = gsitm("N5025044A0000300ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025044A0000300ENG.html", "When the average of the difference between the response times of the rich side and the lean side of the linear A/F sensor during the monitoring time becomes equal to or higher than the predetermined value, the diagnosis code is set as the linear A/F sensor deterioration.", "ptxt");
