si[i++] = gsitm("N5025005X0000500ENG.html", "Code No. P0181-00: Fuel Tank Temperature Sensor circuit offset &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025005X0000500ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025005X0000500ENG.html", "A power voltage of 5 V is applied to the fuel tank temperature sensor output terminal from the ECM terminal F/TM via the resistor in the ECM.", "ptxt");
si[i++] = gsitm("N5025005X0000500ENG.html", "The fuel tank temperature sensor output voltage increases when the resistance increases and decreases when the resistance decreases. The ground terminal is grounded to the vehicle body.", "ptxt");
si[i++] = gsitm("N5025005X0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025005X0000500ENG.html", "The fuel tank temperature sensor converts the fuel tank temperature to a voltage.", "ptxt");
si[i++] = gsitm("N5025005X0000500ENG.html", "The ECM detects the fuel tank temperature with this output voltage.", "ptxt");
si[i++] = gsitm("N5025005X0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025005X0000500ENG.html", "Fuel tank temperature at engine start is higher than engine coolant temperature at engine start by specified value when engine is cold start condition.", "ptxt");
