si[i++] = gsitm("N502500670000500ENG.html", "The power is supplied from the electric water pump relay to the power supply terminal (12V) of the electric water pump connector.", "ptxt");
si[i++] = gsitm("N502500670000500ENG.html", "The ground terminal (GND) of the electric water pump connector is grounded to the body.", "ptxt");
si[i++] = gsitm("N502500670000500ENG.html", "ECM connector terminal EWP outputs a control signal (PWM) to the electric water pump connector control terminal (EWP).", "ptxt");
si[i++] = gsitm("N502500670000500ENG.html", "The signal output terminal (EWPM) of the electric water pump connector outputs a rotation signal (PWM) to the ECM connector terminal EWPM.", "ptxt");
