si[i++] = gsitm("N502500690000400ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502500690000400ENG.html", "The ECM detects abnormality in the sensor by comparing the manifold absolute pressure sensor output with the boost pressure sensor output.", "ptxt");
