si[i++] = gsitm("N502500690000400ENG.html", "The ECM compares the manifold absolute pressure sensor output with the boost pressure sensor output after the ignition switch is in \"LOCK\" (OFF) position. When the difference exceeds the specified value between them, the ECM determines whether the manifold absolute pressure sensor/the boost pressure sensor has malfunction or not.", "ptxt");
