si[i++] = gsitm("N5025006U0000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025006U0000800ENG.html", "A power voltage of 5 V is applied to the crank angle sensor power terminal from the ECM connector terminal SGT5 and grounded to ECM connector terminal SGTE from the crank angle sensor connector terminal.", "ptxt");
si[i++] = gsitm("N5025006U0000800ENG.html", "The sensor signal is inputted to the ECM connector terminal SGT from the crank angle sensor output terminal.", "ptxt");
si[i++] = gsitm("N5025006U0000800ENG.html", "TECHNICAL DESCRIPTION", "title");
