si[i++] = gsitm("N502500780000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502500780000600ENG.html", "The EGR gas temperature sensor converts the EGR gas temperature into a voltage and inputs the voltage signal to the ECM.", "ptxt");
si[i++] = gsitm("N502500780000600ENG.html", "The EGR gas temperature sensor is a kind of resistor, which has characteristics to reduce its resistance as the EGR gas temperature rises. Therefore, the sensor output voltage varies with the EGR gas temperature, and becomes lower as the EGR gas temperature rises.", "ptxt");
