si[i++] = gsitm("N5025007C0000800ENG.html", "Code No. P0421-00: Warm up catalyst efficiency below threshold", "title");
si[i++] = gsitm("N5025007C0000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007C0000800ENG.html", "The signal from the oxygen sensor (rear) differs from the oxygen sensor (front). That is because the catalytic converter purifies exhaust gas. When the catalytic converter has deteriorated, the signal from the oxygen sensor (front) becomes similar to the oxygen sensor (rear).", "ptxt");
si[i++] = gsitm("N5025007C0000800ENG.html", "The ECM compares the output of the front and rear oxygen sensor signals.", "ptxt");
si[i++] = gsitm("N5025007C0000800ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007C0000800ENG.html", "Linear A/F sensor and oxygen sensor (rear) rich/lean waveforms are nearly equal.", "ptxt");
