si[i++] = gsitm("N5025007D0000500ENG.html", "Code No. P0441-00: Evaporative emission control system incorrect purge flow &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025007D0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007D0000500ENG.html", "ECM detects a stuck open condition of purge control solenoid valve and a stuck closed condition of ventilation solenoid valve by pressure change in fuel tank.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Stuck open purge control solenoid valve is judged through monitoring leak of evaporative emission system.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Stuck closed ventilation solenoid valve is judged after 20 seconds from end of monitoring leak of evaporative emission system, or of usual operation of purge control solenoid valve from ON to OFF.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007D0000500ENG.html", "Fuel tank pressure decreases largely during purge-cut.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "MONITOR EXECUTION", "title");
si[i++] = gsitm("N5025007D0000500ENG.html", "Continuous.", "ptxt");
