si[i++] = gsitm("N5025007D0000500ENG.html", "Engine is running.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "ON duty cycle of the purge control solenoid valve is 0%.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "20 seconds have elapsed since the duty cycle of the purge control solenoid valve has turned to 0%.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Judgement Criterion", "title");
si[i++] = gsitm("N5025007D0000500ENG.html", "The pressure in the fuel tank is specified value or less for 0.1 second.", "ptxt");
