si[i++] = gsitm("N5025007D0000500ENG.html", "Replace the purge control solenoid valve (Refer to Engine &lt;4B4> – Engine Overhaul – Solenoid Valve and Vacuum Hose – ). Then GO TO 6.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Item 6: VENT Solenoid", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Repair or replace the vent hose and air filter (Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – Canister - ). Then GO TO 5.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Replace the ventilation solenoid valve (Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – Canister - ). Then GO TO 6.", "ptxt");
si[i++] = gsitm("N5025007D0000500ENG.html", "Reconfirmation of the diagnosis code.", "ptxt");
