si[i++] = gsitm("N5025007G0000400ENG.html", "Code No. P0451-00: Canister Pressure Sensor slosh &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "The ECM terminal FPR5 supplies 5 volts reference signal to the fuel tank pressure sensor. The fuel tank pressure sensor is grounded through the ECM terminal FPRE.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "The fuel tank pressure sensor returns a voltage signal to the ECM terminal F/PR that is proportional to the pressure in the fuel tank.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Diagnosis item name \"Canister Pressure Sensor\" and \"Evaporative Emission Control System Pressure Sensor\" of diagnosis code, which are shown on the M.U.T.-III SE display and described in the Workshop Manual, indicate fuel tank pressure sensor.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "The ECM monitors the fuel tank pressure sensor signal voltage.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "The ECM determines whether the fuel tank pressure sensor signal voltage is within normal operating parameters.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Detect malfunction if change of fuel tank pressure sensor output voltage during idling stays large during specified go/stop operations.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "MONITOR EXECUTION", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Continuous.", "ptxt");
