si[i++] = gsitm("N5025007G0000400ENG.html", "DIAGNOSIS CODE SET CONDITIONS", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check Conditions", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Accelerator pedal is not depressed.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Vehicle speed is 1.5 km/h or less.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "The conditions for deviating from idling operation are as follows.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Vehicle speed is 50 km/h or more.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Judgement Criteria", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "The drastic pressure fluctuation is detected 20 times or more per engine idling, which is that the fuel tank pressure sensor output voltage is 0.2 volts or more.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "The condition described above is consecutively detected 4 times under the normal driving conditions.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "If the number of sudden pressure fluctuations does not reach twenty during any one period of engine idling, or if the ignition switch is turned OFF, the counter will reset to zero.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "FAIL-SAFE AND BACKUP FUNCTION", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "None.", "ptxt");
