si[i++] = gsitm("N5025007G0000400ENG.html", "Fuel tank pressure sensor circuit, harness damage or connector damage.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "ECM failed.", "ptxt");
