si[i++] = gsitm("N5025007G0000400ENG.html", "Using M.U.T.-III SE, check data list.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Disconnect hose D and hose H from the canister. After disconnecting the hose, cap the nipple on the canister.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Disconnect hose E from the canister.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Set M.U.T.-III SE to the data reading mode for item 35, Fuel Tank Pressure Sensor.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Output voltage should be between 3.5 to 4.5 volts.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Connect the hand pump to the nipple on the canister where hose E was previously connected, and pressurize the canister.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "The canister pressure reading should increase.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Remove the hand pump.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Connect hose D, hose E and hose H to the canister.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Q: Is the sensor operating properly?", "question");
si[i++] = gsitm("N5025007G0000400ENG.html", "YES", "result");
si[i++] = gsitm("N5025007G0000400ENG.html", "Intermittent malfunction (Refer to General Information – General Information – Basic Inspection – Service Information for Electrical Incident – ).", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "NO", "result");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Measure the sensor supply voltage at fuel tank pressure sensor harness side connector.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Disconnect the fuel tank pressure sensor connector and measure at the harness side.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Measure the voltage between terminal FPR5 line and ground.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Voltage should be between 4.9 and 5.1 volts.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Q: Is the measured voltage between 4.9 and 5.1 volts?", "question");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check of harness damage in FPR5 line between fuel tank pressure sensor connector and ECM connector.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Q: Is the harness wire in good condition?", "question");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Repair it. Then GO TO 8.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check the continuity at fuel tank pressure sensor harness side connector.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check for the continuity between terminal FPRE line and ground.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Continuity (2 Ω or less).", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Q: Does continuity exist?", "question");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check of harness damage in FPRE line between fuel tank pressure sensor connector and ECM connector.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check of harness damage in F/PR line between fuel tank pressure sensor connector and ECM connector.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Replace the fuel tank pressure sensor.", "title");
si[i++] = gsitm("N5025007G0000400ENG.html", "Carry out a test drive with the drive cycle pattern. Refer to Diagnostic Function – OBD-II Drive Cycle – Pattern 21 .", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Check the diagnosis code.", "ptxt");
si[i++] = gsitm("N5025007G0000400ENG.html", "Q: Is diagnosis code P0451-00 set?", "question");
