si[i++] = gsitm("N5025007J0000400ENG.html", "Code No. P0455-00: Evaporative emission control system leak detected (gross leak) &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "The fuel tank may be under a slight pressure or vacuum depending on the state of the evaporative emission control system. The ECM monitors and responds to these pressure/vacuum changes. If the pressure/vacuum varies from the specified range, the ECM will set diagnosis code P0455-00.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The ECM energizes the ventilation solenoid valve to shut off the canister outlet port.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The purge control solenoid valve is activated to apply engine manifold vacuum to the evaporative emission control system.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "When the fuel system develops a vacuum of 2 kPa, the purge control solenoid valve is turned \"off\" and the fuel system vacuum is maintained at 2 kPa.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The ECM determines whether there is a leak or clog in the fuel system by measuring the change in vacuum inside the fuel tank.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The test is stopped when fuel vapor pressure is determined to be too high.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Depressurizing EVAP system by intake manifold negative pressure is impossible within specified period.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "MONITOR EXECUTION", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Continuous.", "ptxt");
