si[i++] = gsitm("N5025007J0000400ENG.html", "Fuel tank pressure is in the range of -4.9 kPa to +4.9 kPa.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Amount of remaining fuel is 15 - 85 % of capacity when the engine is started.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Enough purge flow to depressurize the fuel tank.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "There is not much evaporation in the fuel tank.", "ptxt");
