si[i++] = gsitm("N5025007J0000400ENG.html", "Purge line or vapor line is clogged.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Fuel tank, purge line or vapor line seal failed.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Purge control solenoid valve failed.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Ventilation solenoid valve failed.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Fuel tank pressure sensor failed.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Canister seal is faulty.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Canister is clogged.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Required Special Tools:", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "MB993028: VCI-3 kit with wireless adapters", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "-: VCI-3 device", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "MB993029: DLC cable", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "MB993030: USB cable", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "MB993031: Wireless USB adapter (Qty:2)", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "MB993040: VCI-3 kit without wireless adapters", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Using M.U.T.-III SE, test the Evap Leak Monitor.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "To prevent damage to M.U.T.-III SE, always turn the ignition switch to the \"LOCK\" (OFF) position before connecting or disconnecting M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "During this test, the ECM will automatically increase the engine speed to 1,600 r/min or greater. Check that the transmission is set to P range.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Erase the diagnosis codes using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Securely close the fuel filler door.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Select \"Special Function\".", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Select \"Evap Leak Monitor.\"", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "During this test, keep the accelerator pedal at the idle position.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Keep the engine speed and engine load within the specified range. When the monitor test starts, the \"In Progress\" item on M.U.T.-III SE will change from \"NO\" to \"YES\".", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Q: Is \"Evap Leak was detected.\" displayed on M.U.T.-III SE?", "question");
si[i++] = gsitm("N5025007J0000400ENG.html", "YES", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "A malfunction has been detected during the monitor test. Refer to the Diagnostic Code Chart and diagnose any other diagnosis codes that are set . If no other diagnosis codes have been set, GO TO 2.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO &lt;\"Evap Leak Monitor test passed.\" is displayed on M.U.T.-III SE.>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "Intermittent malfunction (Refer to General Information – General Information – Basic Inspection – Service Information for Electrical Incident – ).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO &lt;\"Evap Leak Monitor discontinued. Once turn the IG off then retest again from the beginning.\" is displayed on M.U.T.-III SE.>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "The evap leak monitor has been interrupted during the test. Turn the ignition switch to the \"LOCK\" (OFF) position once, and repeat the monitoring from (1).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check for fuel filler door and fuel filler neck", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check the installation condition and damage of capless fuel filler components (fuel filler door and fuel filler neck).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check the fuel filler door inside of foreign materials.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check flap of capless unit for easy opening and closing operation, when bar or nozzle with Φ20 - 21 mm is inserted or nozzle.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "While applying air or 1 kPa to fuel filler neck, check air for leakage.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Q: Is the check result normal?", "question");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "Repair or replace the fuel filler door or fuel filler neck (Refer to Engine &lt;4B4> - Fuel Supply &lt;2WD>, &lt;4WD>). Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Using M.U.T.-III SE, check data list.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Data list reference table (Refer to ).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Item 35: Fuel Tank Pressure Sensor", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Replace the fuel tank pressure sensor (Refer to Engine &lt;4B4> - Engine and Emission Control - Emission Control - Evaporative Emission Control System - Canister- ). Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check the purge control solenoid valve for leaks and clogging.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – .", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Replace the purge control solenoid valve (Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – ). Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Using M.U.T.-III SE, check actuator test.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Disconnect the hose I from the ventilation solenoid valve.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Connect a hand vacuum pump to the nipple where the hose is disconnected at the previous step.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The vacuum should leak when vacuum is applied, and the vacuum should be maintained when the ventilation solenoid valve is activated by the actuator test Item 6: VENT Sol of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Replace the canister and ventilation solenoid valve assembly (Refer to Engine &lt;4B4> - Engine and Emission Control - Emission Control - Evaporative Emission Control System - Canister- ). Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check for leaks and clogging in hose A.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Use a hand vacuum pump to check hose A.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Repair or replace the hose A. Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Performance test.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Fuel temperature should be lower than 40°C during the performance test.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "In this step, verify if the evaporative emission control system works properly, or determine which area of the evaporative emission control system has a failure.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "As a 0 - 6.2 kPa range vacuum gauge is used, the gauge may be broken if excessive vacuum pressure is applied. Do not apply a vacuum of more than 2.9 kPa.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "To achieve the performance test efficiently, a mechanical vacuum gauge 0 - 6.2 kPa range and M.U.T.-III SE should be used, and the engine to generate vacuum.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Install a mechanical vacuum gauge (0 - 6.2 kPa range) between the purge control solenoid valve and the hose B.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Select the data list Item A3201 fuel tank pressure sensor on M.U.T.-III SE to see the fuel tank pressure sensor output.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Run the engine at idle.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Using locking pliers, pinch the hose A to close the purge flow, as a preparation of the performance test.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Disconnect hose I from the ventilation solenoid valve, and plug the nipple of ventilation solenoid valve.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Momentary, remove the locking pliers at the hose A, this will cause the vacuum build up in the evaporative emission control system.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The engine vacuum comes from the purge port through the purge control solenoid valve.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "During this operation, the purge control solenoid valve may turn off but will resume operation in about 20 seconds. Operation of the purge control solenoid valve can be checked by needle fluctuation of the mechanical vacuum gauge.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Warm up the engine until the engine coolant temperature is 80°C or higher.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Turn the ignition switch to the \"OFF\" position.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Watch the vacuum reading on the mechanical vacuum gauge and M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "When the vacuum reading reaches 2.9 kPa on the mechanical vacuum gauge and -2.9 kPa on the M.U.T.-III SE, pinch the hose A using locking pliers; this stops the application of vacuum and seals the evaporative emission control system for the leak test.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "If there is a system failure, either of both vacuum readings may not reach to the above specifications. In this case, it is not necessary to pinch off the hose A", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "After an elapsed time of 20 second, check the fuel tank pressure reading on M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "OK: Change in pressure reading is 0.4 kPa or less (holding -2.5 kPa or more vacuum).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO &lt;Mechanical vacuum gauge reading reaches 2.9 kPa, but M.U.T.-III SE data list Item 35 reading does not reach -2.5 kPa>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO &lt;Mechanical vacuum gauge reading does not reach 2.9 kPa, also M.U.T.-III SE data list Item 35 reading does not reach -2.5 kPa>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check for clogging in evaporative emission control system.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Disconnect one portion of the evaporative emission control system at a time working towards the front of the vehicles until blockage is found (hose H and hose E to B shown in the system diagram).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Repair the location of the blockage. Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check for leaks in fuel tank area.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "To find the vacuum leakage in the system, clamp the hose E. Repeat the performance test. This will determine if the vacuum leak is either in the fuel tank area or in the rest of the system.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "YES &lt;The system hold the vacuum>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "Repair or replace the leaked parts (fuel tank, fuel filler tube assembly, hose F, hose G and hose E) and check again that there are no leaks. Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "NO &lt;The vacuum leak>", "result");
si[i++] = gsitm("N5025007J0000400ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check for leaks at other than fuel tank area.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Clamp off the vacuum hose one component at a time working towards the front of the vehicles until leakage is found (hose H and hose E to B shown in the system diagram).", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Repair the leakage at the location. Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "During this test, the ECM automatically increases the engine speed to 1,600 r/min or greater. Check that the transmission is set to P range.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Select \"Special Function.\"", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "During the test, keep the accelerator pedal at the idle position.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Replace the ECM (Refer to ). Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The evaporative emission control system is working properly at this time. Then GO TO 12.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Test the OBD-II drive cycle.", "title");
si[i++] = gsitm("N5025007J0000400ENG.html", "Carry out a test drive with the drive cycle pattern. Refer to Diagnostic Function – OBD-II Drive Cycle – Pattern 19 .", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Check the diagnosis code.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "Q: Is diagnosis code P0455-00 set?", "question");
si[i++] = gsitm("N5025007J0000400ENG.html", "Retry the troubleshooting.", "ptxt");
si[i++] = gsitm("N5025007J0000400ENG.html", "The inspection is complete.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Code No. P0456-00: Evaporative emission control system 0.5mm leak &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "The ECM monitors the Evaporative Emission (EVAP) System pressure.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The ECM controls the ventilation solenoid valve. It closes the ventilation solenoid valve to seal the canister side of the system.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The purge control solenoid valve is opened to allow manifold vacuum to create low pressure (vacuum) in the EVAP system.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "When the EVAP system develops a vacuum of 2 kPa, the purge control solenoid valve is closed and the fuel system vacuum is maintained at 2 kPa.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The ECM determines whether there is a leak in the EVAP system by monitoring the vacuum inside the fuel tank.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The test is stopped when fuel vapor pressure exceeds predetermined limits.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Measure reverting pressure after depressurizing by intake manifold negative pressure and detect malfunction if reverting pressure rises largely.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MONITOR EXECUTION", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Once per driving cycle.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MONITOR EXECUTION CONDITIONS (Other monitor and Sensor)", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Other Monitor (There is no temporary diagnosis code set in memory for the item monitored below)", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Evaporative emission purge system monitor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Sensor (The sensor below is determined to be normal)", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Purge control solenoid valve", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Ventilation solenoid valve", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel tank temperature sensor monitor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel tank pressure sensor monitor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel level sensor monitor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Air flow sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "No. 1 intake air temperature sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Barometric pressure sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Manifold absolute pressure sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Boost pressure sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "DIAGNOSIS CODE SET CONDITIONS", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check Conditions", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Engine coolant temperature is less than 35°C when the engine is started.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Intake air temperature is less than 36°C when the engine is started.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Engine coolant temperature is more than 20°C.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Amount of remaining fuel is 15 - 85% of capacity when the engine is started.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Barometric pressure is more than 76 kPa.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Intake air temperature is more than -10°C.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel temperature is less than 33°C.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel tank pressure is in the range of -4.9 kPa to 4.9 kPa.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Enough purge flow to depressurize the fuel tank.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "There is not much evaporation in the fuel tank.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Judgment Criterion", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "In case the amount of change in the pressure that is monitored for a given length of time inside the tank is beyond the specified value after sealing off the fuel tank and the vapor line.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The specified value varies depending on the fuel temperature and fuel level.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "FAIL-SAFE AND BACKUP FUNCTION", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "None.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "OBD-II DRIVE CYCLE PATTERN", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Refer to Diagnostic Function – OBD-II Drive Cycle – Pattern 19 .", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Malfunction fuel door or fuel filler neck (Insufficient sealing of the fuel cap less structure).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Canister seal is leaking.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel tank, purge line or vapor line seal is leaking.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Ventilation solenoid valve does not seal.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Required Special Tools:", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "MB993028: VCI-3 kit with wireless adapters", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "-: VCI-3 device", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MB993029: DLC cable", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MB993030: USB cable", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MB993031: Wireless USB adapter (Qty:2)", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "MB993040: VCI-3 kit without wireless adapters", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Using M.U.T.-III SE, test the Evap Leak Monitor.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "To prevent damage to M.U.T.-III SE, always turn the ignition switch to the \"LOCK\" (OFF) position before connecting or disconnecting M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "During this test, the ECM will automatically increase the engine speed to 1,600 r/min or greater. Check that the transmission is set to P range.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Erase the diagnosis codes using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Securely close the fuel filler door.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Select \"Special Function\".", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Select \"Evap Leak Monitor.\"", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "During this test, keep the accelerator pedal at the idle position.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Keep the engine speed and engine load within the specified range. When the monitor test starts, the \"In Progress\" item on M.U.T.-III SE will change from \"NO\" to \"YES\".", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Q: Is \"Evap Leak was detected.\" displayed on M.U.T.-III SE?", "question");
si[i++] = gsitm("N5025048S0000400ENG.html", "YES", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "A malfunction has been detected during the monitor test. Refer to the Diagnostic Code Chart and diagnose any other diagnosis codes that are set . If no other diagnosis codes have been set, GO TO 2.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "NO &lt;\"Evap Leak Monitor test passed.\" is displayed on M.U.T.-III SE.>", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "Intermittent malfunction (Refer to General Information – General Information – Basic Inspection – Service Information for Electrical Incident – ).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "NO &lt;\"Evap Leak Monitor discontinued. Once turn the IG off then retest again from the beginning.\" is displayed on M.U.T.-III SE.>", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "The evap leak monitor has been interrupted during the test. Turn the ignition switch to the \"LOCK\" (OFF) position once, and repeat the monitoring from (1).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check for fuel filler door and fuel filler neck", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check the installation condition and damage of capless fuel filler components (fuel filler door and fuel filler neck).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check the fuel filler door inside of foreign materials.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check flap of capless unit for easy opening and closing operation, when bar or nozzle with Φ20 - 21 mm is inserted or nozzle.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "While applying air or 1 kPa to fuel filler neck, check air for leakage.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Q: Is the check result normal?", "question");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "NO", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "Repair or replace the fuel filler door or fuel filler neck. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Repair or replace the fuel filler door or fuel filler neck (Refer to Engine &lt;4B4> - Fuel Supply &lt;2WD>, &lt;4WD>). Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Using M.U.T.-III SE, check data list.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Data list reference table (Refer to ).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Item 35: Fuel Tank Pressure Sensor", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the fuel tank pressure sensor (Refer to Engine &lt;4B4> - Engine and Emission Control - Emission Control - Evaporative Emission Control System - Canister- ). Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Using M.U.T.-III SE, check actuator test.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Disconnect the hose B from the purge control solenoid valve.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Connect a hand vacuum pump to the nipple where the hose is disconnected at the previous step.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The vacuum should be maintained when vacuum is applied and vacuum should leak when the purge control solenoid valve is activated by the actuator test item 3: Purge Control Solenoid Valve of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the purge control solenoid valve (Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – ). Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Disconnect the hose I from the ventilation solenoid valve.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The vacuum should leak when vacuum is applied, and the vacuum should be maintained when the ventilation solenoid valve is activated by the actuator test Item 6: VENT Sol of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the canister and ventilation solenoid valve assembly. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the canister and ventilation solenoid valve assembly (Refer to Engine &lt;4B4> - Engine and Emission Control - Emission Control - Evaporative Emission Control System - Canister- ). Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check for leaks in hose A.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Use a hand vacuum pump to check hose A.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the hose A. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Performance test.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Fuel temperature should be lower than 40°C during the performance test.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "In this step, verify if the evaporative emission control system works properly, or determine which area of the evaporative emission control system has a failure.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "As a 0 - 6.2 kPa range vacuum gauge is used, the gauge may be broken if excessive vacuum pressure is applied. Do not apply a vacuum of more than 2.9 kPa.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "To achieve the performance test efficiently, a mechanical vacuum gauge 0 - 6.2 kPa range and M.U.T.-III SE should be used, and the engine to generate vacuum.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Install a mechanical vacuum gauge (0 - 6.2 kPa range) between the purge control solenoid valve and the hose B.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Disconnect hose I from the ventilation solenoid valve, and plug the nipple of ventilation solenoid valve.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Select the data list Item A3201 fuel tank pressure sensor on M.U.T.-III SE to see the fuel tank pressure sensor output.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Run the engine at idle.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Using locking pliers, pinch the hose A to close the purge flow, as a preparation of the performance test.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Momentary, remove the locking pliers at the hose A, this will cause the vacuum build up in the evaporative emission control system.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The engine vacuum comes from the purge port through the purge control solenoid valve.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "During this operation, the purge control solenoid valve may turn off but will resume operation in about 20 seconds. Operation of the purge control solenoid valve can be checked by needle fluctuation of the mechanical vacuum gauge.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Watch the vacuum reading on the mechanical vacuum gauge and M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "When the vacuum reading reaches 2.9 kPa on the mechanical vacuum gauge and -2.9 kPa on the on M.U.T.-III SE, pinch the hose A using locking pliers; this stops the application of vacuum and seals the evaporative emission control system for the leak test.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "If there is a system failure, either of both vacuum readings may not reach to the above specifications. In this case, it is not necessary to pinch off the hose A", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "After an elapsed time of 20 second, check the fuel tank pressure reading on M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "OK: Change in pressure reading is 0.4 kPa or less (holding -2.5 kPa or more vacuum).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check for leaks in fuel tank area.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "To find the vacuum leakage in the system, clamp the hose E. Repeat the performance test. This will determine if the vacuum leak is either in the fuel tank area or in the rest of the system.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "In this case, as we clamped off the vacuum hose connecting to the fuel tank, M.U.T.-III SE reading will not change. Please the use the mechanical gauge reading.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "YES &lt;The system hold the vacuum>", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "Repair or replace the leaked parts (fuel tank, fuel filler neck assembly, hose F, hose G and hose E) and check again that there are no leaks. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "NO &lt;The vacuum leak>", "result");
si[i++] = gsitm("N5025048S0000400ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check for leaks at other than fuel tank area.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Clamp off the vacuum hose one component at a time working towards the front of the vehicles until leakage is found (hose H and hose E to B shown in the system diagram).", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Repair the leakage at the location. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "During this test, the ECM automatically increases the engine speed to 1,600 r/min or greater. Check that the transmission is set to P range.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Select \"Special Function.\"", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "During the test, keep the accelerator pedal at the idle position.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Replace the ECM (Refer to ). Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The evaporative emission control system is working properly at this time. Then GO TO 11.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Test the OBD-II drive cycle.", "title");
si[i++] = gsitm("N5025048S0000400ENG.html", "Carry out a test drive with the drive cycle pattern. Refer to Diagnostic Function – OBD-II Drive Cycle – Pattern 19 .", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Check the diagnosis code.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "Q: Is diagnosis code P0456-00 set?", "question");
si[i++] = gsitm("N5025048S0000400ENG.html", "Retry the troubleshooting.", "ptxt");
si[i++] = gsitm("N5025048S0000400ENG.html", "The inspection is complete.", "ptxt");
si[i++] = gsitm("N5025007K0000500ENG.html", "Code No. P0458-00: Evaporative emission control system purge control valve circuit low input", "title");
si[i++] = gsitm("N5025007K0000500ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025007K0000500ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025007K0000500ENG.html", "Power is supplied to the purge control solenoid valve from the engine control relay.", "ptxt");
si[i++] = gsitm("N5025007K0000500ENG.html", "The ECM connector terminal PURG makes the power transistor in the unit be in ON position, and that makes currents go on the purge control solenoid valve.", "ptxt");
si[i++] = gsitm("N5025007K0000500ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007K0000500ENG.html", "In response to a signal from the ECM, the purge control solenoid valve controls the flow rate of the purge air to be introduced into the inlet manifold.", "ptxt");
si[i++] = gsitm("N5025007K0000500ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007K0000500ENG.html", "The ECM detects open circuit and short malfunction.", "ptxt");
