si[i++] = gsitm("N5025007L0000500ENG.html", "Replace the purge control solenoid valve (Refer to Engine &lt;4B4> – Engine and Emission Control – Emission Control – Evaporative Emission Control System – ). Then GO TO 5.", "ptxt");
