si[i++] = gsitm("N5025007M0000400ENG.html", "The output signal of the fuel level sensor does not change within the 4 ohms even though the vehicle has been driven a long distance (e.g. 50 - 100 km (31.1 - 62.1 mile)).", "ptxt");
si[i++] = gsitm("N5025007M0000400ENG.html", "When the fuel consumption calculated from the operation time of the injector amounts to 10 liters (2.6 gallons)*, the diversity of the amount of fuel in tank calculated from the fuel level sensor is less than 2 liters (0.5 gallons).", "ptxt");
si[i++] = gsitm("N5025007M0000400ENG.html", "* Fuel consumption is equivalent to 20 liters (5.2 gallons) under the following conditions.", "ptxt");
si[i++] = gsitm("N5025007M0000400ENG.html", "Fuel tank level is 95% or more.", "ptxt");
si[i++] = gsitm("N5025007M0000400ENG.html", "Fuel level sensor resistance is more than 192 ohms and less than 204 ohms. &lt;4WD>", "ptxt");
si[i++] = gsitm("N5025007M0000400ENG.html", "Not reset after each drive cycle.", "ptxt");
