si[i++] = gsitm("N5025007P0000800ENG.html", "The ECM monitors the change in the differential pressure sent from the EGR differential pressure sensor when the EGR valve is activated.", "ptxt");
si[i++] = gsitm("N5025007P0000800ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007P0000800ENG.html", "The ECM checks for changes in the differential pressure of the EGR differential pressure sensor.", "ptxt");
