si[i++] = gsitm("N5025007R0000700ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "The ventilation solenoid valve power is supplied from the engine control relay.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "The ECM controls ground ventilation solenoid valve by turning the power transistor in the ECM \"ON\" and \"OFF\".", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007R0000700ENG.html", "In response to a signal from the ECM, the ventilation solenoid valve controls the flow rate of the ventilation air to be introduced into the inlet manifold.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007R0000700ENG.html", "The ECM detects open circuit and short malfunction.", "ptxt");
