si[i++] = gsitm("N5025007R0000700ENG.html", "Replace the ventilation solenoid valve (Refer to Engine &lt;4B4> - Engine and Emission Control - Emission Control - Evaporative Emission Control System - Canister - ). Then GO TO 8.", "ptxt");
