si[i++] = gsitm("N5025007R0000700ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "Measure the voltage between terminal power supply line and ground.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "Voltage should be battery positive voltage.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "Q: Is battery positive voltage (approximately 12 V) present?", "question");
si[i++] = gsitm("N5025007R0000700ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5025007R0000700ENG.html", "Repair or replace the connector(s), or check and repair the harness of short to ground and open circuit in power supply line between engine control relay connector and ventilation solenoid valve connector. Then GO TO 8.", "ptxt");
