si[i++] = gsitm("N5025007V0000800ENG.html", "Code No. P04FA-00: EGR system - high temperature gas", "title");
si[i++] = gsitm("N5025007V0000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025007V0000800ENG.html", "A power voltage of 5 V is applied to the EGR gas temperature sensor output terminal from the ECM connector terminal EGRT.", "ptxt");
si[i++] = gsitm("N5025007V0000800ENG.html", "The power voltage is grounded to the ECM connector terminal ETSE from the EGR gas temperature sensor connector ground terminal.", "ptxt");
si[i++] = gsitm("N5025007V0000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025007V0000800ENG.html", "The ECM checks whether EGR gas temperature below the specified value.", "ptxt");
si[i++] = gsitm("N5025007V0000800ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025007V0000800ENG.html", "The EGR gas temperature sensor is a kind of resistor that features a reduction in resistance when the exhaust gas temperature rises. Therefore, the sensor output voltage changes according to the exhaust gas temperature. When exhaust gas temperature rises, it lowers.", "ptxt");
