si[i++] = gsitm("N502500810000800ENG.html", "A power voltage of 5 V is applied to the engine oil pressure sensor power terminal from the ECM connector terminal OPS5 and grounded to the ECM connector terminal OPSG from the engine oil pressure sensor connector ground terminal.", "ptxt");
si[i++] = gsitm("N502500810000800ENG.html", "The sensor signal is inputted to the ECM connector terminal OPS from the engine oil pressure sensor output terminal.", "ptxt");
