si[i++] = gsitm("N502500810000800ENG.html", "The engine oil pressure sensor converts the oil pressure into a voltage signal and inputs the signal to the ECM.", "ptxt");
si[i++] = gsitm("N502500810000800ENG.html", "The ECM uses this signal for relief control of engine oil pressure.", "ptxt");
si[i++] = gsitm("N502500810000800ENG.html", "The ECM monitors the change in the output signal of the engine oil pressure sensor according to the engine operation state.", "ptxt");
