si[i++] = gsitm("N5025043G0000600ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025043G0000600ENG.html", "ECM relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025043G0000600ENG.html", "Power is supplied to the inlet oil feeder control valve from the ECM relay.", "ptxt");
si[i++] = gsitm("N5025043G0000600ENG.html", "The ECM connector terminal OCVI makes the power transistor in the unit be in ON position, and that makes currents go on the inlet oil feeder control valve.", "ptxt");
si[i++] = gsitm("N5025043G0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025043G0000600ENG.html", "The ECM controls the spool valve position of the inlet oil feeder control valve corresponding to the driving condition of the engine and continuously changes the phase of the intake camshaft.", "ptxt");
si[i++] = gsitm("N5025043G0000600ENG.html", "The phase angle of the intake camshaft is computed from the signal patterns of the crank angle sensor and intake camshaft position sensor.", "ptxt");
si[i++] = gsitm("N5025043G0000600ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025043G0000600ENG.html", "The difference between the actual intake valve opening timing and the intake valve target opening timing is over the specified value.", "ptxt");
