si[i++] = gsitm("N502500860000500ENG.html", "The A/C pressure sensor converts the refrigerant pressure (A/C load) into a voltage signal and inputs the signal to the ECM.", "ptxt");
si[i++] = gsitm("N502500860000500ENG.html", "The ECM uses this output voltage to calculate correction torque of the A/C compressor.", "ptxt");
