si[i++] = gsitm("N5025043I0000600ENG.html", "ECM relay is integrated into the IPDM E/R", "ptxt");
si[i++] = gsitm("N5025043I0000600ENG.html", "Power is supplied to the exhaust oil feeder control valve from the ECM relay.", "ptxt");
si[i++] = gsitm("N5025043I0000600ENG.html", "The ECM connector terminal OCVE makes the power transistor in the unit be in ON position, and that makes currents go on the exhaust oil feeder control valve.", "ptxt");
si[i++] = gsitm("N5025043I0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025043I0000600ENG.html", "The ECM controls the spool valve position of the exhaust oil feeder control valve corresponding to the driving condition of the engine and continuously changes the phase of the exhaust camshaft.", "ptxt");
si[i++] = gsitm("N5025043I0000600ENG.html", "The phase angle of the exhaust camshaft is computed from the signal patterns of the crank angle sensor and exhaust camshaft position sensor.", "ptxt");
