si[i++] = gsitm("N5025008C0000400ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "Power is supplied to the active grill shutter connector power terminal (P+) from the IPDM E/R connector terminal ACT4.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "The ground terminal (E) of the active grill shutter connector is grounded to the body.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "The signals are sent and received between ECM connector terminal LNGS and communication terminal (S) of the active grill shutter connector via LIN communication.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025008C0000400ENG.html", "The ECM directs the active grill shutter to open or close via LIN communication depending on the driving conditions.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "The engine warning light does not illuminate and only the GPF warning mark (red) may be displayed. This is to encourage driving so that the GPF can be regenerated.", "ptxt");
si[i++] = gsitm("N5025008C0000400ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025008C0000400ENG.html", "The difference between the actual grille shutter position and the target grille shutter position is over the specified value.", "ptxt");
