si[i++] = gsitm("N5025008P0000800ENG.html", "Code No. P0685-00: Main relay stuck open", "title");
si[i++] = gsitm("N5025008P0000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N5025008P0000800ENG.html", "Engine control relay is integrated into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N5025008P0000800ENG.html", "The power supply voltage is applied to the engine control relay from the 12V battery through IPDM E/R connector terminal STO.", "ptxt");
si[i++] = gsitm("N5025008P0000800ENG.html", "ECM connector terminal C/R turns on the power transistor in the unit to energize the engine control relay coil through IPDM E/R connector terminal C/R and turns on the relay.", "ptxt");
si[i++] = gsitm("N5025008P0000800ENG.html", "When the engine control relay turns on, the 12V battery voltage is supplied to the ECM, the sensor and the actuator.", "ptxt");
si[i++] = gsitm("N5025008P0000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025008P0000800ENG.html", "When the ignition switch ON signal is input into the ECM, the ECM turns ON the engine control relay. This causes 12V battery voltage to be supplied to the ECM, sensor and actuator.", "ptxt");
