si[i++] = gsitm("N5025009Y0000900ENG.html", "The engine ECU detects abnormal combustion (LSPI) at low engine rotation.", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Using engine oil other than genuine goods, oil dilution, or fuel deterioration may cause LSPI. In rare cases, it may occur when intake air temperature is high and high load operation is performed with low rotation.", "ptxt");
