si[i++] = gsitm("N5025009Y0000900ENG.html", "Check with the user whether specified engine oil is used, about the supply source of fuel, fueling timing, fueling amount, and car usage status (how long has the car not been used, the driving situation at the time of diagnosis code occurrence, or whether short distance driving in a cold condition occurred).", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Check compression pressure.", "title");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Check the compression pressure (Refer to Engine &lt;4B4> - Engine Mechanical - On-vehicle Service - ).", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Check whether there is an abnormality such as abnormal noise or any sticking in the crank shaft rotation during cranking.", "ptxt");
