si[i++] = gsitm("N5025009Y0000900ENG.html", "Refill or replace fuel", "title");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Check when fuel was refilled and the amount of the fuel, and refill or replace fuel as shown in the table.", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Conditions", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Remedy", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Refilled by a quarter or more of the fuel tank capacity within three months.", "ptxt");
