si[i++] = gsitm("N5025009Y0000900ENG.html", "Not refilled within three months but refilled within six months by one-half or more of the fuel tank capacity.", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Refill it by one-half or more of the fuel tank capacity with fuel.*", "ptxt");
si[i++] = gsitm("N5025009Y0000900ENG.html", "Other than the above. Or, fuel properties, refilling timing, or the fuel supply amount is unknown.", "ptxt");
