si[i++] = gsitm("N502501060000800ENG.html", "Code No. P1564-1C: Cruise Control Switch Circuit Short or Open", "title");
si[i++] = gsitm("N502501060000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501060000800ENG.html", "The voltage for detecting the switch position is applied to the steering switch (RH) connector from ECM connector terminal CNTS.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "The steering switch (RH) connector is grounded to ECM connector terminal FPR5.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "As for the cruise control-related switches (cruise ON/OFF, CANCEL, DISTANCE &lt;vehicles with ACC>, SET-, RES+) in the steering switch (RH), the resistance value changes depending on the pressed switch.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501060000800ENG.html", "When each cruise control-related switch of the steering switch (RH) is pressed, the CNTS terminal voltage of the ECM changes depending on which switch is pressed.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "The ECM determines which switch is pressed according to the voltage of the CNTS terminal.", "ptxt");
