si[i++] = gsitm("N502501060000800ENG.html", "1.5 seconds later after battery voltage is 9 volts or more.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "Cruise Control or Adaptive Cruise Control is equipped.", "ptxt");
si[i++] = gsitm("N502501060000800ENG.html", "Judgement Criterion", "title");
