si[i++] = gsitm("N5025048C0000600ENG.html", "The 12V battery voltage is between 10.0 and 16.5 volts.", "ptxt");
si[i++] = gsitm("N5025048C0000600ENG.html", "The starter motor is OFF.", "ptxt");
si[i++] = gsitm("N5025048C0000600ENG.html", "2 seconds or more have passed after the above mentioned conditions have been met.", "ptxt");
si[i++] = gsitm("N5025048C0000600ENG.html", "The DCDC power supply voltage is 8.0 volts or more.", "ptxt");
si[i++] = gsitm("N5025048C0000600ENG.html", "Judgment Criterion", "title");
si[i++] = gsitm("N5025048C0000600ENG.html", "The control voltage is 6.5 volts or less for 2.1 seconds.", "ptxt");
