si[i++] = gsitm("N5025048D0000300ENG.html", "Code No. P1DE0-00: IPDM E/R battery voltage circuit failure", "title");
si[i++] = gsitm("N5025048D0000300ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025048D0000300ENG.html", "The IPDM E/R monitors the battery voltage sensor and sends CAN signal of the diagnosis result (OK/NOK) to the ECM.", "ptxt");
