si[i++] = gsitm("N5025048I0000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N5025048I0000600ENG.html", "The ECM effects air/fuel ratio feedback control in accordance with the signals from the linear A/F sensor.", "ptxt");
si[i++] = gsitm("N5025048I0000600ENG.html", "If the linear A/F sensor has deteriorated, corrections will be made by the oxygen sensor (rear).", "ptxt");
si[i++] = gsitm("N5025048I0000600ENG.html", "DESCRIPTIONS OF MONITOR METHODS", "title");
si[i++] = gsitm("N5025048I0000600ENG.html", "When an abnormality exists in the linear A/F sensor, the amount of compensated fuel injection is abnormal. When this situation continues, it is judged to be faulty.", "ptxt");
si[i++] = gsitm("N5025048I0000600ENG.html", "If an abnormality exists in the oxygen sensor (rear), also it is judged to be faulty even though the linear A/F sensor is normal.", "ptxt");
