si[i++] = gsitm("N502501120000800ENG.html", "A power voltage of 5 V is applied to the accelerator pedal position sensor from the ECM connector terminal APS5.", "ptxt");
si[i++] = gsitm("N502501120000800ENG.html", "The power voltage is grounded to the ECM connector terminal APSE from the accelerator pedal position sensor.", "ptxt");
