si[i++] = gsitm("N5025011S0000A00ENG.html", "Check the termination resistance measurement at the ECM.", "title");
si[i++] = gsitm("N5025011S0000A00ENG.html", "A digital multimeter should be used.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "A test wiring harness should be used.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "When measuring the resistance, disconnect the negative battery terminal.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Disconnect connector, and measure at the ECM side.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Measure resistance between the ECM connector terminal No.134 (LCAH) and terminal No.145 (LCAL).", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "OK: 120 ± 20 Ω", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Q: Is the check result normal?", "question");
si[i++] = gsitm("N5025011S0000A00ENG.html", "YES", "result");
si[i++] = gsitm("N5025011S0000A00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "NO", "result");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Replace the ECM (Refer to ). Then GO TO 7.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Disconnect connector, and measure at the harness side.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Check the termination resistance measurement at the 48V battery", "title");
si[i++] = gsitm("N5025011S0000A00ENG.html", "A strand end of the twist wire should be within 10 cm from the connector.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "When checking the joint connector, ensure that its wiring harness side and its short pins are not damaged.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Disconnect connector, and measure at the 48V battery side.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Measure resistance between the 48V battery connector terminal No.5 (CANL) and terminal No.11 (CANH).", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Repair or replace the connector, or repair the harness wire. Then GO TO 7.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Replace the 48V battery (Refer to Electrical & Power Control – Power Supply, Ground & Circuit Elements – Removal and Installation – 48V Battery – ). Then GO TO 7.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Check the termination resistance measurement at the belt drive starter generator.", "title");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Disconnect connector, and measure at the belt drive starter generator side.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Measure resistance between the belt drive starter generator connector terminal No.2 (CANL) and terminal No.3 (CANH).", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "OK: 1 kΩ or more", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Replace the belt drive starter generator (Refer to Engine &lt;4B4> - Engine Electrical - Charging System - Belt Drive Starter Generator - ). Then GO TO 7.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Check voltage measurement at the belt drive starter generator.", "title");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Ignition switch: ON position", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Voltage between belt drive starter generator connector terminal No.2 (CANL) and body ground.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "OK: 5V or less", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Voltage between belt drive starter generator connector terminal No.3 (CANH) and body ground.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Measure resistance belt drive starter generator connector terminal No.2 (CANL) and ground.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "OK: No continuity", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Measure resistance belt drive starter generator connector terminal No.3 (CANH) and ground.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Check belt drive starter generator power supply (Refer to Electric Power Train – 48V Mild Hybrid – Diagnosis Code/Circuit Diagnosis – Power Supply And Ground Circuit – Belt Drive Starter Generator – Diagnosis Procedure – ).", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Repair the connector(s) or wiring harness. Then GO TO 7.", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Test the OBD-II drive cycle.", "title");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Carry out a test drive with the drive cycle pattern. (Refer to Diagnostic Function – OBD-II Drive Cycle – Pattern 5 ).", "ptxt");
si[i++] = gsitm("N5025011S0000A00ENG.html", "Check the diagnosis code.", "ptxt");
