si[i++] = gsitm("N502501200000A00ENG.html", "Check the termination resistance measurement at the ECM.", "title");
si[i++] = gsitm("N502501200000A00ENG.html", "A digital multimeter should be used.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "A test wiring harness should be used.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "When measuring the resistance, disconnect the negative battery terminal.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Disconnect connector, and measure at the ECM side.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Measure resistance between the ECM connector terminal No.134 (LCAH) and terminal No.145 (LCAL).", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "OK: 120 ± 20 Ω", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Q: Is the check result normal?", "question");
