si[i++] = gsitm("N502501200000A00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Check the termination resistance measurement at the 48V battery", "title");
si[i++] = gsitm("N502501200000A00ENG.html", "A strand end of the twist wire should be within 10 cm from the connector.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "When checking the joint connector, ensure that its wiring harness side and its short pins are not damaged.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Disconnect 48V battery connector, and measure at the 48V battery side.", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Measure resistance between the 48V battery connector terminal No.5 (CANL) and terminal No.11 (CANH).", "ptxt");
si[i++] = gsitm("N502501200000A00ENG.html", "Repair or replace the connector, or repair the harness wire. Then GO TO 6.", "ptxt");
