si[i++] = gsitm("N502501550000700ENG.html", "Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) does not illuminate right after the ignition switch is turned to the ON position.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "1", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) remains illuminating and never goes out.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "2", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Starting", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Starting impossible", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "(starter operative but no initial combustion)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The starter is operative and cranks the engine, but no initial combustion occurs in the cylinders to start the engine.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "3", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Starting impossible (initial combustion but no complete combustion)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Initial combustion occurs, but the engine stalls soon due to the incomplete combustion.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "4", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Improper starting (long time to start)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine starts, but it takes too long for cranking.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Improper idling", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Unstable idling", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "(rough idling, hunting)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine speed is not constant and fluctuates during the idling. Usually, this malfunction can be judged from the shaking tachometer pointer or vibrations transmitted to the steering wheel, shift lever, vehicle body and so on.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "5", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "&lt;Vehicles for Taiwan>", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "&lt;Vehicles for Vietnam>", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Improper idling speed (too high or too low)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The idling speed is not within the normal range.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Engine stalls during idling", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "(die out)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine stalls during the idling in no relation to the vehicle movement.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Engine stalls", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine stalls when starting the car (pass out)", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine stalls when the accelerator pedal is depressed in the idling speed, or during the operation.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "6", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine stalls when decelerating", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine stalls at the deceleration.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Driving", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Engine does not revolve up", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine speed does not increase even when the accelerator pedal is depressed.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "7", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Hesitation, sag", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The response of vehicle speed (engine speed) is delayed when the accelerator pedal is depressed to accelerate vehicle speed, or the vehicle speed (engine speed) is temporarily dropped during the acceleration.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "This phenomenon is called \"hesitation\" and a serious hesitation is called \"sag\".", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "8", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Poor acceleration", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine operates smoothly at a constant-speed run, but the vehicle does not accelerate properly as the throttle valve opening changes. In addition, vehicle will not run in the specified maximum speed.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Stumble", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The engine speed increase is delayed when the accelerator pedal is initially depressed at the starting.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Surge", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "At a constant-speed or acceleration the vehicle is subject to repeated jerking (in terms of the drive speed) in the driving direction.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The feeling of impact or vibration when accelerating", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The driver feels a sudden impact when the vehicle is accelerated.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "9", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The feeling of impact or vibration when decelerating", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The driver feels a sudden impact when the vehicle is decelerated.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "10", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Knocking", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Sharp sound like a hammer striking on the cylinder walls during the driving can be heard and wrongly affects the driving.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "11", "ptxt");
