si[i++] = gsitm("N502501550000700ENG.html", "12", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Exhaust gas", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "Odour, white smoke, black smoke and high-concentration of CO/HC during idling", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "The exhaust has an abnormal odor. Either white or black exhaust gas comes out. The concentration of CO/HC is high during the idling.", "ptxt");
si[i++] = gsitm("N502501550000700ENG.html", "13", "ptxt");
