si[i++] = gsitm("N502501320000600ENG.html", "Inspection Procedure 1: The Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) does not illuminate light after the ignition switch is turned to the ON position", "title");
si[i++] = gsitm("N502501320000600ENG.html", "COMMENTS ON TROUBLE SYMPTOM", "title");
si[i++] = gsitm("N502501320000600ENG.html", "The combination meter illuminates the Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) just after the ignition switch is in the ON position.", "ptxt");
si[i++] = gsitm("N502501320000600ENG.html", "If the Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) is not illuminated just after the ignition switch is in the ON position, the failure could possibly be caused by the defective Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light), open/short circuit of the combination meter and so on.", "ptxt");
si[i++] = gsitm("N502501320000600ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N502501320000600ENG.html", "Failed combination meter", "ptxt");
si[i++] = gsitm("N502501320000600ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N502501320000600ENG.html", "Check the trouble symptom.", "title");
si[i++] = gsitm("N502501320000600ENG.html", "Does the trouble symptom persist?", "question");
si[i++] = gsitm("N502501320000600ENG.html", "YES", "result");
si[i++] = gsitm("N502501320000600ENG.html", "Check combination meter system (Refer to Driver Information & Multimedia – Meter, Warning Light Indicator – Full TFT Meter – Basic Inspection – Meter, Warning Light & Indicator – Diagnosis and Repair Workflow –  &lt;FULL TFT METER>, refer to Driver Information & Multimedia – Meter, Warning Light Indicator – 7 Inch Information Display – Basic Inspection – Diagnosis and Repair Workflow –  &lt;7 INCH INFORMATION DISPLAY>).", "ptxt");
si[i++] = gsitm("N502501320000600ENG.html", "NO", "result");
si[i++] = gsitm("N502501320000600ENG.html", "Intermittent malfunction (Refer to General Information - General Information - Basic Inspection - Service Information for Electrical Incident - ).", "ptxt");
si[i++] = gsitm("N502501330000600ENG.html", "Inspection Procedure 2: The Malfunction Indicator Light (SERVICE ENGINE SOON or Check Engine Light) remains illuminated and never goes out", "title");
si[i++] = gsitm("N502501330000600ENG.html", "COMMENTS ON TROUBLE SYMPTOM", "title");
si[i++] = gsitm("N502501330000600ENG.html", "The ECM has detected a failed sensor or a failed actuator. Or the TCM has detected a failed sensor or a failed actuator. Or failure is possibly caused by malfunction of the combination meter.", "ptxt");
si[i++] = gsitm("N502501330000600ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
