si[i++] = gsitm("N502501570000600ENG.html", "Inspection Procedure 19: Cannot Set Cruise Control", "title");
si[i++] = gsitm("N502501570000600ENG.html", "COMMENTS ON TROUBLE SYMPTOM", "title");
si[i++] = gsitm("N502501570000600ENG.html", "A malfunction related to the brake monitoring switch or a malfunction in the DI and MPI system is suspected. Check if a diagnosis code is set.", "ptxt");
si[i++] = gsitm("N502501570000600ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
