si[i++] = gsitm("N502501490000A00ENG.html", "Inspection Procedure 20: ECM Power Supply, ECM Relay, Ignition Switch - IG1 System", "title");
si[i++] = gsitm("N502501490000A00ENG.html", "OPERATION", "title");
si[i++] = gsitm("N502501490000A00ENG.html", "The ECM relay is built into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "12V battery positive voltage is applied to the ECM relay.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "ECM connector terminal C/R applies current to the ECM relay coil by turning ON the power transistor in the unit in order to turn the relay ON.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "When the ECM relay is turned ON, the 12V battery positive voltage power will be supplied from the ECM relay to the ECM, sensor and actuator.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "FUNCTION", "title");
si[i++] = gsitm("N502501490000A00ENG.html", "When the ignition switch is turned ON, the ignition relay in the IPDM E/R turns ON and 12V battery positive voltage will be applied to the IGN terminal of the ECM. Consequently, the ECM turns the  ECM relay ON. Due to this, 12V battery positive voltage will be supplied to the ECM, sensor and actuator.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "PROBABLE CAUSES", "title");
