si[i++] = gsitm("N502501490000A00ENG.html", "Failed IPDM E/R.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Failed ignition relay (built into the IPDM E/R).", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Failed ECM relay (built into the IPDM E/R).", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Open/short circuit or harness damage in ECM relay circuit, or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Open/short circuit or harness damage in ignition relay circuit, or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Open circuit or harness damage in ECM ground circuit, or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Failed ECM.", "ptxt");
