si[i++] = gsitm("N502501490000A00ENG.html", "NO", "result");
si[i++] = gsitm("N502501490000A00ENG.html", "Replace the 12V battery (Refer to Electrical & Power Control – Power Supply, Ground & Circuit Elements – Removal and Installation – Battery – ).", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Using scan tool (M.U.T.-III SE), read the other system DTC.", "title");
si[i++] = gsitm("N502501490000A00ENG.html", "Use scan tool (M.U.T.-III SE) to check and see if a DTC is set in the IPDM E/R [Refer to Electrical & Power Control – Power Control System – IPDM E/R – System Description – Diagnosis System (IPDM E/R) – ].", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Is any DTC set in the IPDM E/R?", "question");
