si[i++] = gsitm("N502501490000A00ENG.html", "Repair the connector(s), or check and repair of open circuit in C/R line between IPDM E/R connector and ECM connector.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Short-circuit ECM harness side connector terminal C/R line to ground.", "ptxt");
