si[i++] = gsitm("N502501490000A00ENG.html", "Repair the connector(s), or check and repair of damage in C/R line between IPDM E/R connector and ECM connector.", "ptxt");
si[i++] = gsitm("N502501490000A00ENG.html", "Check of damage in BAT1 line between IPDM E/R connector and ECM connector.", "title");
