si[i++] = gsitm("N502501500000800ENG.html", "Inspection Procedure 21: Fuel Pump System", "title");
si[i++] = gsitm("N502501500000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501500000800ENG.html", "The fuel pump relay is built into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "ECM connector terminal FP/R applies current to the fuel pump relay coil by turning ON the power transistor in the unit in order to turn the relay ON.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "When the fuel pump relay is turned ON, the 12V battery voltage will be supplied from the fuel pump relay (IPDM E/R connector terminal F/P) to the fuel pump.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501500000800ENG.html", "When the ignition switch ON signal is inputted into the ECM, the ECM turns ON the fuel pump relay. This causes the 12V battery voltage to be supplied to the fuel pump.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Failed fuel pump relay in the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Failed fuel pump.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Open/short circuit or harness damage in fuel pump drive circuit, or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Failed ECM.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Using M.U.T.-III SE, read the other system diagnosis code.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Use M.U.T.-III SE to check and see if a diagnosis code is set in the IPDM E/R [Refer to Electrical & Power Control – Power Control System – IPDM E/R – System Description – Diagnosis System (IPDM E/R) –  ).", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Is any diagnosis code set in the IPDM E/R?", "question");
si[i++] = gsitm("N502501500000800ENG.html", "YES", "result");
si[i++] = gsitm("N502501500000800ENG.html", "Perform the troubleshooting of the IPDM E/R (Refer to Electrical & Power Control – Power Control System – IPDM E/R – ECU Diagnosis Information – IPDM E/R – ).", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "NO", "result");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Perform voltage measurement at ECM connector.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Disconnect connector, and measure at harness side.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Voltage between terminal FP/R and ground.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "OK: 12V battery positive voltage", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Is the check result normal?", "question");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Repair the connector(s), or check and repair of short to ground, and open circuit in FP/R line between IPDM E/R connector and ECM connector.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Check fuel pump operations.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Fuel tank pump operation check (Refer to ).", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Replace the fuel tank pump and gauge assembly (FWD: Refer to Engine &lt;4B4> – Fuel Supply – Fuel Tank &lt;FWD> – , AWD: Refer to Engine &lt;4B4> – Fuel Supply – Fuel Tank &lt;AWD> – ).", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Perform resistance measurement at fuel pump connector.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Resistance between terminal ground line and ground.", "ptxt");
