si[i++] = gsitm("N502501500000800ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Repair the connector(s), or check and repair of open circuit, and damage in ground line between fuel pump connector and ground.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Perform voltage measurement at fuel pump connector.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Voltage between terminal IPDM E/R F/P line and ground.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Check of open circuit, short circuit, and damage in F/P line between IPDM E/R connector and fuel pump connector.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Repair the connector(s), or check and repair of damage in FP/R line between IPDM E/R connector and ECM connector.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Repair the connector(s) or wiring harness.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Check of damage in F/P line between IPDM E/R connector and fuel pump connector.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Using M.U.T.-III SE, check actuator test.", "title");
si[i++] = gsitm("N502501500000800ENG.html", "Item 2: Fuel Pump", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "OK: Operating sound of fuel pump can be heard.", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Intermittent malfunction (Refer to General Information – General Information – Basic Inspection – Service Information for Electrical Incident – ).", "ptxt");
si[i++] = gsitm("N502501500000800ENG.html", "Replace the ECM (Refer to ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Inspection Procedure 22: Ignition Circuit System", "title");
si[i++] = gsitm("N502501510000800ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501510000800ENG.html", "The ECM relay is built into the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "The 12V battery positive voltage is applied from the ECM relay to the ignition coil and is grounded to the vehicle body via the ignition coil.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "A power voltage of 12 V is applied to the ignition coil from the ECM connector terminals CIL1, CIL2, CIL3 and CIL4.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501510000800ENG.html", "When the ECM turn the power transistor in the unit to OFF, the 12V battery positive voltage is applied to the power transistor in the ignition coil, resulting that the power transistor is ON. And, when the ECM turns the power transistor in the unit to ON, the power transistor in the ignition coil will be turned OFF.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "When the power transistor in the ignition coil is turned to ON with any signal from the ECM, the primary voltage will be applied through the ignition coil. When the power transistor in the ignition coil is turned OFF, the primary current is blocked and high voltage is generated in the secondary coil.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Failed spark plug.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Failed ignition coil.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Open/short circuit or harness damage in ignition system circuit or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Failed ECM.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Visual check of ignition spark.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Remove the spark plug and install it to the ignition coil.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Connect the ignition coil connector.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Disconnect all fuel injector connectors.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "At the engine start, check each spark plug produces a spark.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Is the check result normal?", "question");
si[i++] = gsitm("N502501510000800ENG.html", "YES", "result");
si[i++] = gsitm("N502501510000800ENG.html", "Intermittent malfunction (Refer to General Information – General Information – Basic Inspection – Service Information for Electrical Incident – ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "NO", "result");
si[i++] = gsitm("N502501510000800ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check spark plug itself.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Replace the spark plug which did not generate a spark with the one which generated a spark, and check whether the spark plug generates a spark (Refer to Engine &lt;4B4> – Engine Electrical – Ignition System – On-vehicle Service – ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Replace the spark plug (Refer to Engine &lt;4B4> – Engine Electrical – Ignition System – Ignition Coil – ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check ignition coil itself.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Ignition coil check (Refer to Engine &lt;4B4> – Engine Electrical – Ignition System – On-vehicle Service – ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Replace the ignition coil (Refer to Engine &lt;4B4> – Engine Electrical – Ignition System – Ignition Coil – ).", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Perform voltage measurement at ignition coil connectors.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Disconnect connector, and measure at harness side.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Voltage between terminal power supply line and ground.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "OK: 12V battery positive voltage", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Are the check results normal?", "question");
si[i++] = gsitm("N502501510000800ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Repair the connector(s), or check and repair of open circuit, and short circuit in power supply line between IPDM E/R connector and ignition coil connector.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Perform resistance measurement at ignition coil connectors.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Resistance between terminal ground line and ground.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "OK: Continuity (2 Ω or less)", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Repair the connector(s), or check and repair of open circuit, and damage in ground line between ignition coil connectors and ground.", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check of open circuit, short circuit, and damage between ignition coil connector and ECM connector.", "title");
si[i++] = gsitm("N502501510000800ENG.html", "Check and repair in CIL1 line between No. 1 ignition coil connector and ECM connector", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check and repair in CIL2 line between No. 2 ignition coil connector and ECM connector", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check and repair in CIL3 line between No. 3 ignition coil connector and ECM connector", "ptxt");
si[i++] = gsitm("N502501510000800ENG.html", "Check and repair in CIL4 line between No. 4 ignition coil connector and ECM connector", "ptxt");
