si[i++] = gsitm("N502501520000600ENG.html", "Inspection Procedure 23: Brake Monitoring Switch System", "title");
si[i++] = gsitm("N502501520000600ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501520000600ENG.html", "When the brake pedal is depressed and the stop light switch turns ON, 12V battery positive voltage will be applied to the BRK terminal of the ECM and the BRK1 terminal of the BCM.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501520000600ENG.html", "The brake monitoring switch detects whether the brake pedal is depressed or not, and sends a signal to the ECM. The ECM compares the stop light signal sent from the BCM via the CAN with the brake monitoring switch input signal, and determines whether the input information is reliable. In addition, it sends the brake monitoring switch signal information to other ECUs (such as TCM) via the CAN.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N502501520000600ENG.html", "Failed stop light switch.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "Open/short circuit or harness damage in brake monitoring switch circuit or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "Failed ECM.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N502501520000600ENG.html", "Check the illumination of the stop light.", "title");
si[i++] = gsitm("N502501520000600ENG.html", "Check whether the stop light illuminates when the brake pedal is depressed.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "Is the check result normal?", "question");
si[i++] = gsitm("N502501520000600ENG.html", "YES", "result");
si[i++] = gsitm("N502501520000600ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N502501520000600ENG.html", "NO", "result");
si[i++] = gsitm("N502501520000600ENG.html", "Check the stop light switch-related circuit of the BCM. (Refer to Driver Controls – Exterior lighting System – LED Head Light – Diagnosis Code/Circuit Diagnosis – Stop Light Circuit – ).", "ptxt");
