si[i++] = gsitm("N502501530000600ENG.html", "Inspection Procedure 24: Engine Oil Pressure Switch System", "title");
si[i++] = gsitm("N502501530000600ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501530000600ENG.html", "12V battery positive voltage is applied to the engine oil pressure switch from the ECM connector terminal OPSW.", "ptxt");
si[i++] = gsitm("N502501530000600ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501530000600ENG.html", "Detect the oil pressure conditions and enter the result into the ECM. After starting the engine if the oil pressure rises to higher than the given pressure, the engine oil pressure switch turns OFF. Under this condition the ECM sends the command of turning off the oil warning light to the combination meter via CAN.", "ptxt");
si[i++] = gsitm("N502501530000600ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
si[i++] = gsitm("N502501530000600ENG.html", "Failed engine oil pressure switch.", "ptxt");
si[i++] = gsitm("N502501530000600ENG.html", "Open/short circuit or harness damage in engine oil pressure switch circuit or loose connector contact.", "ptxt");
si[i++] = gsitm("N502501530000600ENG.html", "Failed ECM.", "ptxt");
si[i++] = gsitm("N502501530000600ENG.html", "DIAGNOSIS", "title");
