si[i++] = gsitm("N502501580000700ENG.html", "Inspection Procedure 25: 48V Battery Power Supply System", "title");
si[i++] = gsitm("N502501580000700ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501580000700ENG.html", "12V battery positive voltage is applied to the ignition relay 1.", "ptxt");
si[i++] = gsitm("N502501580000700ENG.html", "BCM connector terminal IGNR applies current to the ignition relay 1 coil by turning ON the power transistor in the unit in order to turn the relay ON.", "ptxt");
si[i++] = gsitm("N502501580000700ENG.html", "When the ignition relay 1 is turned ON, the 12V battery positive voltage power will be supplied from the ignition relay 1 to the 48V battery.", "ptxt");
si[i++] = gsitm("N502501580000700ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501580000700ENG.html", "When the ignition switch is turned ON, the ignition relay 1 turns ON and 12V battery positive voltage will be applied to the IG terminal of the 48V battery.", "ptxt");
si[i++] = gsitm("N502501580000700ENG.html", "Consequently, the BCM turns the ignition relay 1 ON. Due to this, 12V battery positive voltage will be supplied to the 48V battery.", "ptxt");
si[i++] = gsitm("N502501580000700ENG.html", "TROUBLESHOOTING HINTS (The most likely causes for this code to be set are:)", "title");
