si[i++] = gsitm("N502501580000700ENG.html", "Repair the part that caused a blown fuse and then replace the fuse with a new one (Refer to General Information – General Information – Basic Inspection – How to Use Troubleshooting/Inspection Service Points – ).", "ptxt");
