si[i++] = gsitm("N502501590000700ENG.html", "Inspection Procedure 26: DC-DC converter power supply system", "title");
si[i++] = gsitm("N502501590000700ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501590000700ENG.html", "12V battery positive voltage is applied to the ignition relay 1.", "ptxt");
si[i++] = gsitm("N502501590000700ENG.html", "BCM connector terminal IGNR applies current to the ignition relay 1 coil by turning ON the power transistor in the unit in order to turn the relay ON.", "ptxt");
si[i++] = gsitm("N502501590000700ENG.html", "When the ignition relay 1 is turned ON, the 12V battery positive voltage power will be supplied from the ignition relay 1 to the DC-DC converter.", "ptxt");
si[i++] = gsitm("N502501590000700ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501590000700ENG.html", "When the ignition switch is turned ON, the ignition relay 1 turns ON and 12V battery positive voltage will be applied to the IG terminal of the DC-DC converter.", "ptxt");
si[i++] = gsitm("N502501590000700ENG.html", "Consequently, the BCM turns the ignition relay 1 ON. Due to this, 12V battery positive voltage will be supplied to the DC-DC converter.", "ptxt");
