si[i++] = gsitm("N502501600000700ENG.html", "Inspection Procedure 27: Belt Drive Starter Generator Power Supply System", "title");
si[i++] = gsitm("N502501600000700ENG.html", "CIRCUIT OPERATION", "title");
si[i++] = gsitm("N502501600000700ENG.html", "12V battery positive voltage is applied to the 48V battery fan & motor relay.", "ptxt");
si[i++] = gsitm("N502501600000700ENG.html", "ECM connector terminal C/R applies current to the 48V battery fan & motor relay coil by turning ON the power transistor in the unit in order to turn the relay ON.", "ptxt");
si[i++] = gsitm("N502501600000700ENG.html", "When the 48V battery fan & motor relay is turned ON, the 12V battery positive voltage power will be supplied from the 48V battery fan & motor relay to the belt drive starter generator (BSG).", "ptxt");
si[i++] = gsitm("N502501600000700ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502501600000700ENG.html", "When the ignition switch is turned ON, the 48V battery fan & motor relay turns ON and 12V battery positive voltage will be applied to the VC terminal of the belt drive starter generator (BSG).", "ptxt");
si[i++] = gsitm("N502501600000700ENG.html", "Consequently, the ECM turns the 48V battery fan & motor relay ON. Due to this, 12V battery positive voltage will be supplied to the belt drive starter generator (BSG).", "ptxt");
