si[i++] = gsitm("N5025048Y0000200ENG.html", "GENERAL SCAN TOOL (GST) MODE 01 REFERENCE TABLE", "title");
si[i++] = gsitm("N5025048Y0000200ENG.html", "The purpose of this service of to allow access to current emission-related data values, including analog inputs and outputs, digital inputs and outputs, and system status information.", "ptxt");
si[i++] = gsitm("N5025048Y0000200ENG.html", "The request for information includes a parameter identification (PID) value that indicates to the on-board system the specific information requested.", "ptxt");
si[i++] = gsitm("N5025048Y0000200ENG.html", "The ECM will respond to this message by transmitting the requested data value last determined by the system. All data values returned for sensor readings will be actual readings, not default or substitute values used by the system because of a fault with that sensor.", "ptxt");
si[i++] = gsitm("N5025048Y0000200ENG.html", "GST MODE 01 can be accessed through the use of a general scan tool.", "ptxt");
