si[i++] = gsitm("N502500470000D00ENG.html", "CHECK CHART FOR RESISTANCE AND CONTINUITY BETWEEN TERMINALS", "title");
si[i++] = gsitm("N502500470000D00ENG.html", "Turn the ignition switch to \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "Disconnect the ECM connector.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "Measure the resistance and check for continuity between the terminals of the ECM harness-side connector while referring to the check chart.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "When measuring resistance and checking continuity, a harness for checking contact pin pressure should be used instead of inserting a test probe.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "Checking need not be carried out in the order given in the chart.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "If the terminals that should be checked are mistaken, or if connector terminals are not correctly shorted to ground, damage may be caused to the vehicle wiring, sensors, ECM and/or ohmmeter.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "Be careful to prevent this!", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "If the ohmmeter shows any deviation from the standard value, check the corresponding sensor, actuator and related electrical wiring, and the repair or replace.", "ptxt");
si[i++] = gsitm("N502500470000D00ENG.html", "After repair or replacement, recheck with the ohmmeter to confirm that the repair or replacement has corrected the problem.", "ptxt");
