si[i++] = gsitm("N5025012Y0000300ENG.html", "CAUTIONS FOR WORKING IN ENGINE COMPARTMENT", "title");
si[i++] = gsitm("N5025012Y0000300ENG.html", "Just after the ignition switch is turned to OFF position, the adjustments must always be made with the cooling fan stopped. After the ignition switch is turned to OFF position, the cooling fan might be driven for a few minutes by the after run fan control. If the adjustments are made with the cooling fan driven, injury or damage may occur.", "ptxt");
si[i++] = gsitm("N5025012Y0000300ENG.html", "Never take power from the connector terminal of the belt drive starter generator because unlike the components related to the 12V system, the belt drive starter generator operates at high voltage of 48 V.", "ptxt");
si[i++] = gsitm("N5025012Y0000300ENG.html", "In addition, ensure that the voltage is not applied to the 48V line when checking the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "CHASSIS NUMBER (Chassis No.) WRITING", "title");
si[i++] = gsitm("N5025002A0000300ENG.html", "When the ECM has been replaced, perform the work in following order.", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Update ECM (Refer to )", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Chassis number (Chassis no.) writing", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "MAC key writing (Refer to )", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Learning procedure for idling in DI and MPI engine (Refer to )", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Factory mode OFF", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Using the M.U.T.-III SE, write the chassis number in the ECM by the following procedures.", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Select “ENGINE” in the system selection screen.", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Select “Special Function” and then select “Chassis No./VIN Registration”", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "Write the chassis number by following the instructions on the screen.", "ptxt");
si[i++] = gsitm("N5025002A0000300ENG.html", "For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "UPDATE ENGINE CONTROL MODULE (ECM)", "title");
si[i++] = gsitm("N5025002B0000700ENG.html", "When the ECM is updated (reprogrammed), check that no diagnostic code is set after the update because CAN communication abnormality may occur in the components related to the 48V MILD HYBRID", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "When the ECM has been replaced, perform the work in following order.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Update ECM", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Chassis number (Chassis no.) writing (Refer to )", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "MAC key writing (Refer to )", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Learning procedure for idling in DI and MPI engine (Refer to )", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Factory mode OFF", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Maintain following conditions when executing the ECU update procedure.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Turn OFF all electric loads", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Do not depress the brake pedal", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Battery voltage is 12 to 13.5 V.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Execute the update of the ECM with following procedure using the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "After entering the vehicle information, press the “ECU reprogramming” button.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "Update the ECM following the instruction on the screen.", "ptxt");
si[i++] = gsitm("N5025002B0000700ENG.html", "For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "MAC KEY WRITING", "title");
si[i++] = gsitm("N502501620000200ENG.html", "When the ECM has been replaced, perform the work in following order.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Update ECM (Refer to )", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Chassis number (Chassis no.) writing (Refer to )", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "MAC key writing", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Learning procedure for idling in DI and MPI engine (Refer to )", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Factory mode OFF", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When writing the MAC KEY, it is necessary to connect the M.U.T.-III SE to network.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When the chassis number writing, MAC KEY writing or vehicle specification writing is carried out, Diagnosis code No. U2252-08 may be set in the ECM. Therefore, carry out the following procedures after the writing.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Check that the diagnosis code No. U2252-08 is set in the ECM.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When the diagnosis code is not set: Go to Step 2.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When the diagnosis code is set as a past trouble: Erase the diagnosis code, then go to Step 2.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When the diagnosis code is set as a current trouble: Carry out the following procedures.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Start the engine (set the drive mode to battery charge mode, or start the continuous idling mode) or drive the vehicle at 5 km/h or more.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Change the power supply mode of the electric motor switch to OFF.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Change the power supply mode of the electric motor switch to ON.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Check whether the diagnosis code No. U2252-08 is set in the ECM.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "When the diagnosis code is set as a current trouble: Carry out the diagnosis procedures for the diagnosis code No. U2252-08, then go to Step 2.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Using the M.U.T.-III SE, write the MAC KEY in the ECM by the following procedures.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "On the \"System selection\" screen, select \"ENGINE\".", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Select \"Special Function\", then select \"MAC KEY Writing\".", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "Write the MAC KEY by following the instructions on the screen.", "ptxt");
si[i++] = gsitm("N502501620000200ENG.html", "For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "INITIALISATION PROCEDURE FOR LEARNING VALUE IN DI AND MPI ENGINE", "title");
si[i++] = gsitm("N5025002C0000600ENG.html", "Initialize learning values in the DI and MPI engine when one of the following service operations is performed.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "At replacing engine assembly", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "At replacing Fuel injector and at cleaning", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "At replacing Fuel injector (high pressure) and at cleaning", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "At replacing throttle body and at cleaning", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "At replacing detonation sensor", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "INITIALISATION PROCEDURE", "title");
si[i++] = gsitm("N5025002C0000600ENG.html", "To prevent damage to M.U.T.-III SE, always turn the ignition switch to the OFF position before connecting or disconnecting M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "After the ignition switch is in OFF position, connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Turn the ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Select \"ENGINE\" from System select Screen of the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Select \"Special Function\" from ENGINE Screen.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Select \"Reset\" from Special Function Screen.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Select \"Learned value reset\" from Learned value reset Screen.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "Initialize the learning value by pressing the \"OK\" button.", "ptxt");
si[i++] = gsitm("N5025002C0000600ENG.html", "After initializing the learning value, the learning value of DI and MPI engine idling is necessary. Learning procedure for idling in DI and MPI engine (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "LEARNING PROCEDURE FOR IDLING IN DI AND MPI ENGINE", "title");
si[i++] = gsitm("N5025002D0000601ENG.html", "PURPOSE", "title");
si[i++] = gsitm("N5025002D0000601ENG.html", "When the ECM is replaced, or when the learning value is initialized, the idling is not stabilized because the learning value in DI and MPI engine is not completed. In this case, carry out the learning method for the idling through the following procedures.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "LEARNING PROCEDURE", "title");
si[i++] = gsitm("N5025002D0000601ENG.html", "Start the engine and carry out the warm-up for the engine coolant temperature to reach 80°C or more.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "When the engine coolant temperature is 80°C or more, the warm-up is not needed if the ignition switch is in ON position once.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Place the ignition switch in OFF position and stop the engine.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "After 10 seconds or more, start the engine again.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "For 10 minutes, carry out the idling under the condition shown below and then confirm the engine has the normal idling.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Transmission: \"P\" range", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Operation in lights, fan and attachments: Not to be operated", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Engine coolant temperature: 80°C or more", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "CVT fluid temperature: 60°C or more", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "When the engine stalls during the idling, check the dirtiness (on the throttle valve) of the throttle body and then perform the service from Procedure 1 again.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Carry out idling under the condition shown below for 10 seconds.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Transmission: \"D\" range", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "A/C switch: OFF", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "A/C switch: ON", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "INITIALIZATION PROCEDURE FOR THROTTLE VALVE CONTROL SERVO", "title");
si[i++] = gsitm("N5025002D0000601ENG.html", "Disconnecting and reconnecting the battery cables causes the throttle valve closed-position value learned to be erased from the memory. This may prevent the idle speed control from being executed properly. When the battery cables have been disconnected and reconnected, initialize the throttle valve control servo in the following manner.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Turn the ignition switch to ON and then to OFF.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Keep the ignition switch in OFF for at least 10 seconds.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Turn the ignition switch to ON position.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"ENGINE\".", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "heck the item No. 1: Factory Mode OFF and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\"", "ptxt");
si[i++] = gsitm("N5025002D0000601ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "THROTTLE BODY (THROTTLE VALVE AREA) CLEANING", "title");
si[i++] = gsitm("N5025002E0000500ENG.html", "When touching the throttle valve, surely shut off the driving circuits of the throttle valve. In the event that the throttle valve is operated, a finger might be injured as the result of being caught by the throttle valve.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "When throttle body is cleaned, use the M.U.T.-III SE to initialize the learning value (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Disconnect the electronic-controlled throttle valve connector.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Remove the throttle body assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Do not spray the cleaning fluid directly to the throttle valve.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Spray the cleaning fluid on a clean cloth.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Make sure it does not enter the sensor through the shaft.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Do not scrape off molybdenum layer around the inlet manifold end of the throttle valve shaft.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Wipe off the dirt around the throttle valve with the cloth sprayed with cleaning fluid.", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Install the throttle body assembly and intercooler (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002E0000500ENG.html", "Connect the electronic-controlled throttle valve connector.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "FUEL PRESSURE TEST", "title");
si[i++] = gsitm("N5025002F0000701ENG.html", "&lt;Measurement of fuel pressure between the fuel pump and fuel injector>", "title");
si[i++] = gsitm("N5025002F0000701ENG.html", "Release residual pressure from the fuel pipe line to prevent fuel gush out (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Cover the hose connection with rags to prevent splash of fuel that could be caused by some residual pressure in the fuel pipe line.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Remove the fuel injection tube at the fuel pump (high pressure).", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Assemble the special tool Injector test set (MB992076) of special tool as shown in figure.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Remove the fuel injector installation adapter from the hose. Remove another hose together with the adapter and remove the adopter from the remaining hose.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Install the special tool quick connector (MB992049) and the special tool hose adapter (MB992001) to the hose without the adapter.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Install a hose (inner diameter: 8.5 mm) to the nipple on the side from which the hose was removed in the procedure \"a\".", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Install the special tool assembled in Step 3 between the Fuel pump (high pressure) and fuel high pressure hose.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Install the fuel pressure gauge on the special tool for measuring the fuel pressure via an appropriate O-ring or gasket.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "To prevent damage to the M.U.T.-III SE, always turn the ignition switch to the \"LOCK\" (OFF) position before connecting or disconnecting the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Turn the ignition switch to \"ON\" position (But do not start the engine).", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Select \"Item No. 2\" from the M.U.T.-III SE Actuator test to drive the fuel pump. Check that there are no fuel leaks from any parts.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Finish the actuator test or turn the ignition switch to \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Start the engine and run at idle.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Measure fuel pressure while the engine is running at idle.", "ptxt");
