si[i++] = gsitm("N5025002F0000701ENG.html", "Perform the fuel pressure measurement between the fuel pump (high pressure) and fuel injector (high pressure) after confirming that the fuel pressure between the fuel pump and fuel injector is normal.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Warm up the engine until the engine coolant temperature is 80°C or higher.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Check \"Item No. A2301: Fuel pressure from the M.U.T.-III SE data list while the engine is running at idle.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Standard value: 4,000 - 37,400 kPa at curb idle", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position, and stop the engine.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "If any of fuel pressure measured in steps 3 to 4 is out of specification, perform the following inspection.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Start the engine, and maintain a stable idle speed for one minute.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "If the engine warning light is illuminated during Steps (1) - (3), stop the engine and erase the diagnosis code. And then go to Step (5).", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Suddenly race the engine from 4,500/min to 5,000 r/min.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Maintain a stable idle speed for five minutes.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Confirm the diagnosis code. Finish the inspection if there is not diagnosis code (intermittent malfunction). If the diagnosis code is set, delete the diagnosis code and go to Step (5).", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "If the engine warning light is illuminated during Steps (5) - (7), check the diagnosis code and perform the appropriate troubleshooting based on the diagnosis code.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "Confirm the diagnosis code. Finish the inspection if there is not diagnosis code (intermittent malfunction). If a diagnosis code is set, perform the appropriate troubleshooting based on the diagnosis code.", "ptxt");
si[i++] = gsitm("N5025002F0000701ENG.html", "If the fuel pressure deviates from the standard value, there will be a malfunction shown in the table below.", "ptxt");
