si[i++] = gsitm("N5025002M0000700ENG.html", "Disconnect the boost pressure sensor connector.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Measure the resistance between terminal No. 1 and No. 3 of the boost pressure sensor connector.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Standard value:", "title");
si[i++] = gsitm("N5025002M0000700ENG.html", "13 - 18 kΩ (at -20°C)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "5.3 - 6.7 kΩ [at 0°C (32°F )]", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "2.3 - 3.0 kΩ [at 20°C (68°F)]", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "0.30 - 0.45 kΩ [at 80°C (176°F)]", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Remove the boost pressure sensor.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Measure resistance while heating the sensor using a hair drier.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Normal condition:", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Temperature", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Resistance (kΩ)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Higher", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Smaller", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "If the value deviates from the standard value or the resistance remains unchanged, replace the boost pressure sensor (Refer to Engine &lt;4B4> – Intake and Exhaust – Intercooler – Intercooler – ).", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Install the boost pressure sensor and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Tightening torque: 5.5 ± 1.5 N·m ( 49 ± 13 in–lb )", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "NO. 3 INTAKE AIR TEMPERATURE SENSOR", "title");
si[i++] = gsitm("N5025002M0000700ENG.html", "Disconnect the manifold absolute pressure sensor connector.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Measure the resistance between terminal No. 1 and No. 3 of the manifold absolute pressure sensor connector.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "13 - 18 kΩ (at -20°C)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "5.3 - 6.7 kΩ (at 0°C)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "2.3 - 3.0 kΩ (at 20°C)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "0.30 - 0.45 kΩ (at 80°C)", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Remove the manifold absolute pressure sensor.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "If the value deviates from the standard value or the resistance remains unchanged, replace the manifold absolute pressure sensor (Refer to Engine &lt;4B4> – Intake and Exhaust – Intake Manifold – ).", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Install the manifold absolute pressure sensor and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N5025002M0000700ENG.html", "Tightening torque: 5.5 ± 1.5 N·m", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "ENGINE COOLANT TEMPERATURE SENSOR CHECK", "title");
si[i++] = gsitm("N5025002Q0000700ENG.html", "Remove the engine coolant temperature sensor (Refer to Engine &lt;4B4> – Engine Cooling – Water Hose And Water Pipe – ).", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "With temperature sensing portion of engine coolant temperature sensor immersed in hot water, measure the resistance between connector terminals.", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "Standard value:", "title");
si[i++] = gsitm("N5025002Q0000700ENG.html", "15.2 - 20.6 kΩ (at -20°C)", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "1.04 - 1.28 kΩ (at 40°C)", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "0.148 - 0.164 kΩ (at 100°C)", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "If the resistance deviates from the standard value greatly, replace the sensor (Refer to Engine &lt;4B4> – Engine Cooling – Water Hose And Water Pipe – ).", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "Install a new O-ring to the engine coolant temperature sensor.", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "Tighten the engine coolant temperature sensor to the specified torque.", "ptxt");
si[i++] = gsitm("N5025002Q0000700ENG.html", "Tightening torque: 12 ± 2 N·m", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "INTERCOOLER COOLANT TEMPERATURE SENSOR CHECK", "title");
si[i++] = gsitm("N5025002R0000900ENG.html", "Remove the intercooler coolant temperature sensor (Refer to Engine &lt;4B4> – Intake and Exhaust – Intercooler – Intercooler Water Hose and Water Pipe – ).", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "With temperature sensing portion of engine coolant temperature sensor immersed in hot water, measure the resistance between connector terminals.", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "Standard value:", "title");
si[i++] = gsitm("N5025002R0000900ENG.html", "15.2 - 20.6 kΩ (at -20°C)", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "1.04 - 1.28 kΩ (at 40°C)", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "0.148 - 0.164 kΩ (at 100°C)", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "If the resistance deviates from the standard value greatly, replace the sensor (Refer to Engine &lt;4B4> – Intake and Exhaust – Intercooler – Intercooler Water Hose and Water Pipe – ).", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "Install a new O-ring to the intercooler coolant temperature sensor.", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "Tighten the intercooler coolant temperature sensor to the specified torque.", "ptxt");
si[i++] = gsitm("N5025002R0000900ENG.html", "Tightening torque: 12 ± 2 N·m", "ptxt");
si[i++] = gsitm("N5025002S0000800ENG.html", "LINEAR AIR–FUEL RATIO SENSOR", "title");
si[i++] = gsitm("N5025002S0000800ENG.html", "Disconnect the linear A/F sensor connector.", "ptxt");
si[i++] = gsitm("N5025002S0000800ENG.html", "Measure the resistance between terminal No. 1 and No. 2 of the linear A/F sensor connector.", "ptxt");
si[i++] = gsitm("N5025002S0000800ENG.html", "Standard value: 1.7 - 2.6 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N5025002S0000800ENG.html", "If the resistance deviates from the standard value, replace the linear A/F sensor (Refer to Engine &lt;4B4> – Intake and Exhaust – Catalytic Converter –  &lt;2WD>,  &lt;4WD>).", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "HEATED OXYGEN SENSOR  CHECK", "title");
si[i++] = gsitm("N5025002T0000800ENG.html", "OXYGEN SENSOR (REAR)", "title");
si[i++] = gsitm("N5025002T0000800ENG.html", "Drive test must be performed, while two persons are on board, in a place where a full-throttle accelerating drive can be attempted safely.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Disconnect the oxygen sensor (rear) connector.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Measure the resistance between terminal No. 1 and No. 2 of the oxygen sensor (rear) connector.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Standard value: 4.9 - 7.6 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "If the resistance deviates from the standard value, replace the oxygen sensor (rear) (Refer to Engine &lt;4B4> – Intake and Exhaust – Catalytic Converter – ).", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Warm up the engine until the engine coolant temperature is 80°C or higher.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Perform a racing for 5 minutes or more with the engine speed of 2,000 r/min.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Connect the digital voltmeter between terminal No. 3 and No. 4.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "While repeatedly racing the engine, measure the oxygen sensor (rear) output voltage.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Engine", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Heated oxygen sensor output voltage", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "Remarks", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "When racing the engine", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "0.6 - 1.0 V", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "High load operation makes air/fuel ratio richer and normal oxygen sensor (rear) also can output voltage of 0.6 - 1.0 V", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "If the temperature of sensing area does not reach the high temperature (of approximately 400°C or more) even though the oxygen sensor (rear) is normal, the output voltage would be possibly low in spite of the rich air-fuel ratio.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "When the vehicle is driven with high loads, the temperature of the sensing area of the oxygen sensor (rear) is sufficiently high. Thus, it is not necessary to apply the voltage to the heater.", "ptxt");
si[i++] = gsitm("N5025002T0000800ENG.html", "If the voltage deviates from the standard value, replace the oxygen sensor (rear) (Refer to Engine &lt;4B4> – Intake and Exhaust – Catalytic Converter – ).", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "FUEL PUMP (HIGH PRESSURE) CHECK", "title");
si[i++] = gsitm("N5025002V0000700ENG.html", "MEASUREMENT OF RESISTANCE", "title");
si[i++] = gsitm("N5025002V0000700ENG.html", "Disconnect the fuel pump (high pressure) connector.", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "Measure the resistance between terminals.", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "Standard value: 0.48 - 0.55 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "Measure the resistance between fuel pump (high pressure) body and either terminal No. 1 or terminal No. 2 of the connector at the fuel pump (high pressure).", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "Standard value: No continuity", "ptxt");
si[i++] = gsitm("N5025002V0000700ENG.html", "If the resistance is deviates from the standard value, replace the fuel pump (high pressure) (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "FUEL INJECTOR CHECK", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "FUEL INJECTOR", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "CHECK THE OPERATION SOUND", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "Beware that the operation sounds of other fuel injectors can be heard even if the fuel injector that is being inspected might not be operating.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Use a stethoscope to listen to the operation sound (clicking) of the fuel injectors while the engine is idling or cranking.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Verify that the operation sound increases with the engine speed.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "If the operating sound cannot be heard, inspect the fuel injector actuation circuit.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "MEASUREMENT OF RESISTANCE BETWEEN TERMINALS", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "Disconnect the charge air cooler assembly from the throttle body with the water hoses connected (Refer to Engine &lt;4B4> – Intake and Exhaust – charge air cooler – charge air cooler – ).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Disconnect the fuel injector connector.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Measure the resistance between terminals.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Standard value: 10.5 - 13.5 Ω [at 20°C (68°F)]", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "If the resistance is deviates from the standard value, replace the fuel injector (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "CHECK THE INJECTION CONDITION", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "Release the residual pressure in the fuel pipe line to prevent the fuel from running out (Refer to ).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Do not make fuel splash by covering fuel with waste and so on because the residual pressure is in the fuel pipeline.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Remove the fuel high-pressure hose at the delivery pipe side.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Remove the fuel fuel injector.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Prepare the special tool called injector test set (MB992076) as shown in the figure.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Disconnect the fuel injector mounting hose.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Remove the adapter for mounting fuel injector and attach the special tool Injector test nipple (MB992088) instead.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "After attaching the fuel injector on the special tool Injector test nipple (MB992088), secure it with the special tool injector holder (MB992184).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Mount the injector test set (MB992076) prepared with the special tool hose adapter (MB992001) onto the fuel high-pressure hose.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Connect the M.U.T.-IIISE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Turn the ignition switch to \"ON\" position (but do not start the engine).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Select \"Item No. 2\" from M.U.T.-IIISE actuator test and drive the fuel pump.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Connect the special tool fuel injector test harness (MB991607) between the fuel injector and battery to drive the fuel injector.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Check each fuel injector for spray conditions. The condition can be considered satisfactory unless it is extremely poor.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Stop the actuation of the fuel injector, and check for leakage from the injector nozzle.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Standard value: 1 drop or less per minute", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "After turning the ignition switch to the \"LOCK\" (OFF) position, remove the M.U.T.-IIISE.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Actuate the injector until it does not spray fuel any longer, then drain the fuel inside the special tool.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Remove the special tool.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "When the spray condition is extremely poor or any fuel leaks from the injector nozzle, replace the fuel injector.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Replace the fuel injector and fuel high-pressure hose in the original places.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "FUEL INJECTOR (HIGH PRESSURE)", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "MEASUREMENT OF RESISTANCE", "title");
si[i++] = gsitm("N5025002X0000900ENG.html", "Disconnect the intermediate connector (12 pin) shown in the figure.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Measure the resistance between the terminals for each fuel injector (high pressure) in the intermediate connector (12 pin).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Fuel injector (high pressure)", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Measurement terminal", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Standard value (at 20°C)", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "No. 1", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "2 - 5", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "1.34 - 1.64 Ω", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "No. 2", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "1 -4", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "No. 3", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "3 -12", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "No. 4", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "10 -11", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "If the resistance is not within the standard value, disconnect the fuel injector (high pressure) connector of the defective cylinder and check whether the resistance between the terminals is within the standard value.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Since it is difficult to disconnect the No.1 fuel injector (high pressure) connector, it is necessary to remove the belt drive starter generator (Refer to Engine &lt;4B4> – Engine Electrical – Charging System – Belt Drive Starter Generator – ).", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "If the resistance between the terminals of the fuel injector (high pressure) is normal, check the wiring harness between the fuel injector (high pressure) connector and the intermediate connector (12 pin) and repair if necessary.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Measure the resistance between each terminal for each fuel injector (high pressure) in the intermediate connector (12 pin) and the corresponding fuel injector (high pressure) body.", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "Normal condition", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "2, 5", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "No continuity", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "1, 4", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "3, 12", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "10, 11", "ptxt");
si[i++] = gsitm("N5025002X0000900ENG.html", "If the measurement result is abnormal, replace the fuel injector (high pressure) of the relevant cylinder (Refer to ).", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "THROTTLE VALVE CONTROL SERVO CHECK", "title");
si[i++] = gsitm("N502500340000800ENG.html", "OPERATION CHECK", "title");
si[i++] = gsitm("N502500340000800ENG.html", "When checking the throttle valve operation, never insert fingers into the throttle valve. The extremely strong power of the throttle valve motor might trap and injure fingers.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Remove the air intake hose from the throttle body.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Turn the ignition switch to ON position.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Verify that the throttle opens or closes according to the accelerate pedal operated.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "CHECK THE COIL RESISTANCE", "title");
si[i++] = gsitm("N502500340000800ENG.html", "When touching the throttle valve, surely shut off the driving circuits of the throttle valve. In the event that throttle valve is operated, a finger might be injured as the result of being caught by the throttle valve.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Disconnect the electronic-controlled throttle valve connector.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Measure the resistance between terminals No. 1 and No. 2 at the electronic-controlled throttle valve connector.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "Standard value: 0.3 - 100 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "If the measured resistance deviates from the standard value, fully open the throttle valve with your finger more than five times, then check the result again. If the throttle valve control serve is not used for an extended period of time, the resistance may be increased as a result of internal forming of oxide film. Therefore, it means that the oxide film can be removed through a self cleaning capability of the throttle valve control servo, if forcibly moved.", "ptxt");
si[i++] = gsitm("N502500340000800ENG.html", "If resistance is outside the standard value, replace the throttle body assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "ENGINE OIL CONTROL VALVE CHECK", "title");
si[i++] = gsitm("N502500370000800ENG.html", "INLET OIL FEEDER CONTROL VALVE", "title");
si[i++] = gsitm("N502500370000800ENG.html", "OPERATION CHECK", "title");
si[i++] = gsitm("N502500370000800ENG.html", "Disconnect the inlet oil feeder control valve connector.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "To prevent the coil from burning, keep the duration of the voltage application as short as possible.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "Make sure that the inlet oil feeder control valve generates a tick sound when the battery voltage is applied between the connector terminals at the inlet oil feeder control valve side.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "MEASUREMENT OF RESISTANCE BETWEEN TERMINALS", "title");
si[i++] = gsitm("N502500370000800ENG.html", "Measure the resistance between the terminals of the connector at the inlet oil feeder control valve.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "Standard value: 7.3 - 8.3 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "If the resistance deviates from the standard value, replace the inlet oil feeder control valve (Refer to Engine &lt;4B4> – Engine Mechanical – Engine OIL Control Valve – ).", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "EXHAUST OIL FEEDER CONTROL VALVE", "title");
si[i++] = gsitm("N502500370000800ENG.html", "Disconnect the exhaust oil feeder control valve connector.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "Make sure that the exhaust oil control valve generates a tick sound when the battery voltage is applied between the connector terminals at the exhaust oil feeder control valve side.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "Measure the resistance between the terminals of the connector at the exhaust oil feeder control valve.", "ptxt");
si[i++] = gsitm("N502500370000800ENG.html", "If the resistance deviates from the standard value, replace the exhaust oil feeder control valve (Refer to Engine &lt;4B4> – Engine Mechanical – Engine OIL Control Valve – ).", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "CRUISE CONTROL SWITCH CHECK", "title");
si[i++] = gsitm("N502501300000400ENG.html", "Disconnect the spiral cable harness connector (Refer to Steering - Steering System - Removal And Installation - Steering Wheel - ).", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Measure the resistance between terminal No.8 and terminal No.9 when each of the MAIN (ON/OFF), CANCEL, DISTANCE , SET- and RES+ switches is pressed. If the values measured at the time each switch is pressed correspond to those in the table below, the resistance values are correct.", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "&lt;Vehicles without ACC>", "title");
si[i++] = gsitm("N502501300000400ENG.html", "Measurement terminal", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Switch condition", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Resistance (Ω)", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "No. 8 - No. 9", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "MAIN (ON/OFF) switch: Pressed", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 0", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "CANCEL switch: Pressed", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 249", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "SET - switch: Pressed", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 661", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "RES + switch: Pressed", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 1,486", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Not operate", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 3,976", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "&lt;Vehicles with ACC>", "title");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 309", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "DISTANCE: Pressed", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 741", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 1,406", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 2,586", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "Approx. 5,456", "ptxt");
si[i++] = gsitm("N502501300000400ENG.html", "If the resistance is not normal, replace the steering wheel assembly.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "If the fuel pump (high pressure) is replaced or removed and installed, activate the fuel pump in the fuel tank before starting the engine to fill the fuel pump (high pressure) with fuel to prevent damage to the fuel pump (high pressure) (Refer to Engine &lt;4B4> – Fuel Supply – On-vehicle Service – ).", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Pre-removal operation", "title");
