si[i++] = gsitm("N5025003J0000500ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "&lt;&lt;A>> FUEL TUBE / FUEL HIGH-PRESSURE HOSE DISCONNECTION", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "Follow the steps below to unlock the fuel high-pressure hose connector or the fuel injection tube connector.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Insert a flat-tipped screwdriver [6 mm (0.24 inches) wide and 1 mm (0.04 inches) thick] into the retainer of the fuel high-pressure hose connector or the fuel tube connector.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "When pushing up the retainer of the fuel high-pressure hose connector or the fuel tube connector, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Turn the flat-tipped screwdriver inserted into the retainer by 90° to push up the retainer and unlock the fuel high-pressure hose connector or the fuel tube connector.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Remove the fuel high-pressure hose or the fuel tube.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", ">>A&lt;&lt; FUEL PUMP (HIGH PRESSURE) ASSEMBLY INSTALLATION CONNECTION", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "Install the torsional vibration damper (Refer to Engine &lt;4B4> – Engine Overhaul – Crankshaft Pulley – ).", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Turn the torsional vibration damper and put in parallel the flat surface of exhaust camshaft pump cam and installation surface of the fuel pump support as shown in the figure, install the fuel pump (high pressure) tappet.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "By hand, install the fuel pump (high pressure) assembly to the fuel pump support paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "By one rotation per time, tighten the installation bolts of the fuel pump (high pressure) assembly until reaching the specified torque.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tightening torque: 34 ± 4 N·m", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", ">>B&lt;&lt; FUEL DELIVERY INTERMEDIATE PIPE INSTALLATION", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "Do not tighten it until a flare nut performs a seating.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "By hand, temporally tighten the flare nuts of the fuel delivery intermediate pipe.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Temporally tighten the bolt of the fuel delivery intermediate pipe to the engine hanger.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Temporally tighten the bolt of the fuel delivery intermediate pipe to the cylinder head.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "By hand, temporally tighten it to the place where flare nuts stops by hand.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tighten the fuel pump (high pressure) side flare nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tightening torque: 35 ± 5 N·m", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tighten the delivery pipe  (high pressure) side flare nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tighten the engine hanger side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tighten the cylinder head side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Tightening torque: 22 ± 1 N·m", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", ">>C&lt;&lt; FUEL TUBE CONNECTION", "title");
si[i++] = gsitm("N5025003J0000500ENG.html", "Pull up the retainer of fuel tube or fuel high-pressure hose to unlock before installing.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Install the fuel tube or fuel high-pressure hose to the fuel pump (high pressure) suction tube and delivery pipe.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "When pushing in the fuel tube connector or fuel high-pressure hose, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "After the installation of the fuel tube or fuel high-pressure hose, slightly pull the fuel tube or fuel high-pressure hose to check that it is connected securely. At this time, also check that there is approximately 1 mm (0.04 inches ) play.", "ptxt");
si[i++] = gsitm("N5025003J0000500ENG.html", "Push in the retainer of the fuel tube connector or fuel high-pressure hose to lock the fuel pump (high pressure) and delivery pipe.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "When the fuel injector is replaced, initialize the learned value using scan tool (M.U.T.-III SE) (Refer to ).", "ptxt");
