si[i++] = gsitm("N5025003K0000E00ENG.html", "Charge air cooler coolant temperature sensor Housing Bracket Installation (Refer to Engine &lt;4B4> – Intake and Exhaust – Charge Air Cooler – Charge Air Cooler Water Hose and Water Pipe – )", "ptxt");
