si[i++] = gsitm("N5025003K0000E00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "&lt;&lt;A>> FUEL INJECTION TUBE DISCONNECTION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Follow the steps below to unlock the fuel injection tube connector.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Insert a flat-tipped screwdriver [6 mm (0.24 inches) wide and 1 mm (0.04 inches) thick] into the retainer of the fuel injection tube connector.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "When pushing up the retainer of the fuel injection tube connector, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Turn the flat-tipped screwdriver inserted into the retainer by 90° to push up the retainer and unlock the fuel injection tube connector.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Remove the fuel injection tube.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "&lt;&lt;B>> FUEL RAIL AND FUEL INJECTOR ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Do not drop the fuel injector.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Remove the fuel rail with the fuel injectors attached to it.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>A&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "While turning the fuel injector to right and left, install the O-ring to the fuel injector with care to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>B&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Using special tool O-ring installer (MB992106), install the fuel injector paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>C&lt;&lt; FUEL INJECTOR ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "When applying the engine oil, make sure not to allow the engine oil to enter the fuel rail inside.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Turning the fuel injector assembly to right and left, install it to the fuel rail with care not to damage the O-ring. After the installation, check for its smooth rotation. At this time, check that the projection part of the fuel injector assembly is in the center.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "If the rotation is not smooth, the O-ring may be caught. Remove the fuel injector assembly and check the O-ring for damage. After this, re-insert it to the fuel rail and check for its smooth rotation.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>D&lt;&lt; FUEL INJECTOR SUPPORT INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Install the fuel injector support to the fuel injector groove and fuel rail brim, and fix the fuel injector assembly and fuel rail.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>E&lt;&lt; FUEL RALL AND FUEL INJECTOR ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Apply a small amount of new engine oil to the O-ring at the end of fuel injector assembly.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "When installing the fuel rail and fuel injector assembly to the cylinder head, pay attention to avoid damage to the O-ring at the end of the fuel injector assembly.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Install the fuel rail and fuel injector assembly to the cylinder head. Be careful not to damage the O-ring.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Tighten the fuel rail mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Tightening torque: 14 ± 3 N·m", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", ">>F&lt;&lt; FUEL INJECTION TUBE CONNECTION", "title");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Pull up the retainer of fuel injection tube to unlock before installing.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Install the fuel injection tube to the fuel rail.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "When pushing in the retainer of the fuel injection tube connector, pay attention to avoid damage to the retainer.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "After the installation of the fuel injection tube, slightly pull the fuel injection tube to check that it is connected securely. At this time, also check that there is approximately 1 mm play.", "ptxt");
si[i++] = gsitm("N5025003K0000E00ENG.html", "Push in the retainer of the fuel injection tube connector to lock the fuel injection tube and fuel rail.", "ptxt");
si[i++] = gsitm("N5025003L0000800ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5025003L0000800ENG.html", "Do not install nor remove the fuel rail and fuel injector assembly (high pressure) while holding the fuel rail pressure sensor.", "ptxt");
si[i++] = gsitm("N5025003L0000800ENG.html", "When the fuel injector (high pressure) is replaced, initialize the learned value using scan tool (M.U.T.-III SE) (Refer to ).", "ptxt");
