si[i++] = gsitm("N5025003L0000800ENG.html", "Starter Assembly Removal (Refer to Engine &lt;4B4> – Engine Electrical – Starting System – Starter Motor – ).", "ptxt");
si[i++] = gsitm("N5025003L0000800ENG.html", "Knock sensor Connection Connection .", "ptxt");
si[i++] = gsitm("N5025003L0000800ENG.html", "Multi-flow control valve Connector Connection (Refer to Engine &lt;4B4> – Engine Cooling – Water Hose and Water Pipe – ) .", "ptxt");
