si[i++] = gsitm("N5025003M0000600ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5025003M0000600ENG.html", ">>A&lt;&lt; THROTTLE BODY GASKET INSTALLATION", "title");
si[i++] = gsitm("N5025003M0000600ENG.html", "Fit the throttle body gasket in the inlet manifold groove securely with neither twisting nor damage given.", "ptxt");
si[i++] = gsitm("N5025003M0000600ENG.html", ">>B&lt;&lt; INITIALISATION OPERATION", "title");
si[i++] = gsitm("N5025003M0000600ENG.html", "Turn the ignition switch to the \"ON\" position and then to \"LOCK\" (OFF) position and hold it for at least 10 seconds.", "ptxt");
si[i++] = gsitm("N5025003N0000800ENG.html", "ECM REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5025003N0000800ENG.html", "If the ECM is replaced, another ECU related to immobilizer system should not be replaced together. If at least two ECUs needs to be replaced, replace one ECU and then register its ID with scan tool (M.U.T.-III SE). Then proceed to the replacement of the other ECU.", "ptxt");
si[i++] = gsitm("N5025003N0000800ENG.html", "If the ECM is replaced, execute the ECM update (Refer to ).", "ptxt");
si[i++] = gsitm("N5025003N0000800ENG.html", "If the ECM is replaced, use scan tool (M.U.T.-III SE) to write the Chassis No. (Refer to ).", "ptxt");
si[i++] = gsitm("N5025003N0000800ENG.html", "If the ECM is replaced, use scan tool (M.U.T.-III SE) to write the MAC KEY (Refer to ).", "ptxt");
si[i++] = gsitm("N5025003N0000800ENG.html", "After the ECM replacement, idling speed may be unstable because the DFI and MFI engine learning is not completed. To make it stable, let the system learn the idling (Refer to ).", "ptxt");
