si[i++] = gsitm("N5020502Z0000G00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5020502Z0000G00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "General Precautions", "title");
si[i++] = gsitm("N502050210000I00ENG.html", "When replacing fuel line parts, be sure to observe the following.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Put a \"CAUTION: FLAMMABLE\" sign in the workshop.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Be sure to work in a well ventilated area and furnish workshop with a CO2 fire extinguisher.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Never smoke while servicing fuel system. Keep open flames and sparks away from the work area.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Use gasoline required by the regulations for octane number. Refer to .", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Before removing fuel line parts, perform out the following procedures:", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Put drained fuel in an explosion-proof container and put the lid on securely. Keep the container in safe area.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Release fuel pressure from the fuel lines. Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Disconnect the battery cable from the negative terminal.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Always replace O-ring and clamps with new ones.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Never bend or twist tubes when they are being installed.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Never tighten hose clamps excessively to avoid damaging hoses.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "After installing tubes, check that there is no fuel leakage at connections in the following steps.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Apply fuel pressure to fuel lines with turning ignition switch \"ON\" (with engine stopped). Then check for fuel leakage at connections.", "ptxt");
si[i++] = gsitm("N502050210000I00ENG.html", "Start engine and rev it up and check for fuel leakage at connections.", "ptxt");
si[i++] = gsitm("N5020409R0001B00ENG.html", "Special Service Tools", "title");
