si[i++] = gsitm("N5020503Z0000H00ENG.html", "Low Fuel Level Warning", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "DESIGN/PURPOSE", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "This warns the driver that the fuel level is low.", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "OPERATION AT COMBINATION METER CAN COMMUNICATION CUT-OFF OR UNUSUAL SIGNAL", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "For the operation for CAN communications blackout or abnormal signal reception, refer to .", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "The combination meter receives fuel level sensor signal (resistance value) from the fuel level sensor unit and indicates low fuel level warning on the vehicle information display when fuel level sensor signal (resistance value) is less than the specified value.", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "LIGHTING CONDITION", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "When all of the following conditions are satisfied:", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "After a lapse of 15 seconds after the ignition switch is turned ON.", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Fuel level is lower than the specified level.", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Fuel level warning indication timing (Vehicle: Parked on the level)", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Fuel level", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Approx. 9.7 or less", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "(fuel tank dead amount included)", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Fuel tank dead amount", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Approx. 2.7", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "SHUTOFF CONDITION", "title");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "When any of the following conditions was satisfied:", "ptxt");
si[i++] = gsitm("N5020503Z0000H00ENG.html", "Ignition switch is OFF.", "ptxt");
