si[i++] = gsitm("N502050340002800ENG.html", "Be sure to read \"General Precautions\" when working on the fuel system. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Perform the steps 1 to 7 of \"REMOVAL\" in \" FUEL LEVEL SENSOR UNIT, FUEL FILTER AND FUEL PUMP ASSEMBLY\". Refer to", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Drain fuel from fuel tank if necessary. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Because fuel tank forwardly inclines and becomes unstable when installing/removing, fuel should be drained if found the remaining quantity.", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Situate vehicle on a flat and solid surface.", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Remove main muffler. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Remove rear propeller shaft. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Remove under cover LH and under cover RH.", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Disconnect vapor tube from EVAP canister.", "par7");
si[i++] = gsitm("N502050340002800ENG.html", "Remove fuel filler hose at fuel filler tube side.", "par6");
si[i++] = gsitm("N502050340002800ENG.html", "Support center of fuel tank  with suitable jack .", "par3");
si[i++] = gsitm("N502050340002800ENG.html", "Remove fuel tank bands.", "par2");
si[i++] = gsitm("N502050340002800ENG.html", "Tilt the fuel tank forward and lower the fuel tank front 10 cm.", "par8");
si[i++] = gsitm("N502050340002800ENG.html", "Disconnect vent hose at rear side of fuel tank.", "par4");
si[i++] = gsitm("N502050340002800ENG.html", "Lower suitable jack carefully to remove fuel tank while holding it by hand.", "par1");
si[i++] = gsitm("N502050340002800ENG.html", "Fuel tank may be in an unstable condition, due to the shape of the fuel tank bottom. Be sure to secure tank at all times.", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "If replacing the fuel tank, remove the fuel level sensor unit, fuel filter and fuel pump assembly to transfer to the new fuel tank. Remove and discard the O-ring. Refer to .", "par15");
si[i++] = gsitm("N502050340002800ENG.html", "Fuel Filler Tube", "title");
si[i++] = gsitm("N502050340002800ENG.html", "Remove rear wheel house protector. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Remove rear suspension member. Refer to .", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "Remove fuel filler tube.", "ptxt");
si[i++] = gsitm("N502050340002800ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N502050340002800ENG.html", "Installation is in the reverse order of removal.", "par16");
si[i++] = gsitm("N502050340002800ENG.html", "Fuel Filler Hose", "title");
si[i++] = gsitm("N502050340002800ENG.html", "Insert fuel filler hose to the length below.", "par18");
si[i++] = gsitm("N502050340002800ENG.html", "35 mm (1.38 in)", "par20");
si[i++] = gsitm("N502050340002800ENG.html", "Be sure hose clamp is not placed on swelled area of fuel filler tube.", "par21");
si[i++] = gsitm("N502050340002800ENG.html", "When installing the fuel filler tube, make sure that the lip  of the fuel filler base is firmly attached to the rib  of the cap less unit part.", "par27");
si[i++] = gsitm("N502050340002800ENG.html", "Vapor Tube", "title");
si[i++] = gsitm("N502050340002800ENG.html", "Insert the vapor tube connector  into the EVAP canister until it clicks into place.", "par27");
