si[i++] = gsitm("N5020502B0001P00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Use the following procedure to check for fuel leakage.", "ptxt");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Use the following procedure to check for fuel leakage.", "ptxt");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Turn ignition switch \"ON\" (with engine stopped), and check connections for leakage by applying fuel pressure to fuel piping.", "ptxt");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Turn ignition switch \"ON\" (with engine stopped), and check connections for leakage by applying fuel pressure to fuel piping.", "ptxt");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Start engine and rev it up and check that there is no fuel leakage at the fuel system tube and hose connections.", "ptxt");
si[i++] = gsitm("N5020502B0001P00ENG.html", "Start engine and rev it up and check that there is no fuel leakage at the fuel system tube and hose connections.", "ptxt");
