si[i++] = gsitm("N502431160001100ENG.html", "&lt;&lt;A>> FUEL MAIN PIPE DISCONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Disconnect fuel main pipe quick connector according to the following instructions:", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Push in the retainer (orange, white) of the fuel main pipe connector and unlock the connector.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Disconnect the fuel main pipe from the fuel tank pump and gauge assembly.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "&lt;&lt;B>> FUEL VAPOR TUBE DISCONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Disconnect fuel vapor tube quick connector according to the following instructions:", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Push in the retainer of the fuel vapor tube connector and unlock the connector.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Disconnect the fuel vapor tube from the canister.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "&lt;&lt;C>> FUEL VAPOR TUBE DISCONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Disconnect the fuel vapor tube from the fuel tank filler tube assembly.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "&lt;&lt;D>> FUEL TANK BAND/FUEL TANK ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Support center of fuel tank  with suitable jack .", "par3");
si[i++] = gsitm("N502431160001100ENG.html", "Remove fuel tank bands.", "par2");
si[i++] = gsitm("N502431160001100ENG.html", "Tilt the fuel tank forward and lower the fuel tank front 10 cm.", "par8");
si[i++] = gsitm("N502431160001100ENG.html", "Lower suitable jack carefully to remove fuel tank while holding it by hand.", "par1");
si[i++] = gsitm("N502431160001100ENG.html", "Fuel tank may be in an unstable condition, due to the shape of the fuel tank bottom. Be sure to secure tank at all times.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502431160001100ENG.html", ">>A&lt;&lt; FUEL FILLER NECK INSTALLATION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "When installing the fuel filler neck, make sure that the lip  of the fuel filler base is firmly attached to the rib  of the cap less unit part.", "par27");
si[i++] = gsitm("N502431160001100ENG.html", ">>B&lt;&lt; FUEL FILLER HOSE CONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Tighten the clamp hand with the top mark  until the mark is on the bolt head flange.", "par22");
si[i++] = gsitm("N502431160001100ENG.html", ">>C&lt;&lt; FUEL VAPOR TUBE CONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Insert the connector of the fuel vapor tube into the fuel tank filler tube assembly it clicks into place.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "After the installation of the fuel vapor tube, slightly pull the fuel vapor tube to check that it is connected securely.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", ">>D&lt;&lt; FUEL VAPOR TUBE CONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Insert the connector of the fuel vapor tube into the canister until it clicks into place.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", ">>E&lt;&lt; FUEL MAIN PIPE CONNECTION", "title");
si[i++] = gsitm("N502431160001100ENG.html", "Connect fuel main pipe quick connector according to the following instructions:", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Pull up the retainer (orange) of fuel main pipe connector to unlock before installing.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "Install the connector of the fuel main pipe to the fuel tank pump and gauge assembly securely and push in the retainer (orange) and lock the connector.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "When pushing in the retainer of the fuel main pipe connector, pay attention to avoid damage to the retainer. If the fuel main pipe is not inserted completely, the retainer cannot be inserted.", "ptxt");
si[i++] = gsitm("N502431160001100ENG.html", "After the installation of the fuel main pipe, slightly pull the fuel main pipe to check that it is connected securely.", "ptxt");
