si[i++] = gsitm("N502431190000Y00ENG.html", "DISASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "&lt;&lt;A>> LOCK LING", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Remove lock ring according to the following instructions:", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install pawl (B) of special tool unified fuel lock ring wrench (KV101207S0) (A) to the position shown in the figure.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Temporarily tighten mounting bolt (B) of the pawl according to the measurement (R) from the center special tool (KV101207S0) (A) to the end of pawl (C).", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Set special tool (KV101207S0) to lock ring and tighten the mounting bolt of the pawl.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Remove lock ring.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "To prevent lock ring wrench from being detached, securely hold down spinner handle by hand.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "To reduce impact caused by removal operation, use long spinner handle [handle length: 60 cm or more] and slowly turn it counterclockwise.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "&lt;&lt;B>> FUEL TANK PUMP AND GAUGE ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Remove the fuel tank pump and gauge assembly.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never bend float arm during removal.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never pollute the inside by residue fuel. Draw out avoiding inclination by supporting with a cloth.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never cause impacts such by dropping when handling components.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Separate fuel tube as per the following steps to remove fuel tank pump and gauge assembly.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Disconnect harness connector .", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Pinch quick connector  square-part with your fingers, and pull out the quick connector by hand.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "If quick connector and tube on sender unit are stuck, push several times until they move, and pull out.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "When separating the fuel tube, tie a gasoline-resistance rope to the tip of the fuel tube and leave the rope on the fuel tank side to easily pull the fuel tube for installation.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "&lt;&lt;C>> FUEL LEVEL SENSOR REMOVAL", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Remove fuel level sensor .", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never disassemble a fuel tube  from fuel level sensor.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Tie a gasoline-resistance rope to a tip of the tube. Draw and leave the rope to the fuel tank side so that the rope can be the guide for installation.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "ASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", ">>A&lt;&lt; O-RING INSTALLATION", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install new O-ring to fuel tank without any twist.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Do not reuse O-rings.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", ">>B&lt;&lt; FUEL LEVEL SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Using the rope left on the fuel tank side at removal, run the fuel tube inside the fuel tank to install the fuel level sensor to the fuel tank.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never bend float arm during installation.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "To install, fuel tube  must run to the front () of the vehicle to avoid the interference with the float arm , as shown in the figure.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install the fuel level sensor on the fuel tank with the fuel tank pump and gauge assembly face  faced the shown in the figure against the arrow vehicle front.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never allow seal packing to drop.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Never bend float arm during installing.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", ">>C&lt;&lt; LOCK LING INSTALLATION", "");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install lock ring for fuel tank pump and gauge assembly with special tool unified fuel lock ring wrench (KV101207S0) by turning clockwise.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install lock ring horizontally.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Turn the lock ring  until it is engaged in the fuel tank side  as shown in the figure.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", ">>D&lt;&lt; FUEL TANK PUMP AND GAUGE ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Connect the fuel tube as per the following steps.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Insert the quick connector  straight to the fuel tank pump and gauge assembly.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Judge a good fit from connecting sound and tactile feedback.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Pull the fuel tube by hand to check a secure fit.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Connect harness connector .", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", "Install the fuel tank pump and gauge assembly on the fuel tank with the fuel tank pump and gauge assembly face  faced the shown in the figure against the arrow vehicle front.", "ptxt");
si[i++] = gsitm("N502431190000Y00ENG.html", ">>E&lt;&lt; FUEL FILLER HOSE INSTALLATION", "title");
si[i++] = gsitm("N502431190000Y00ENG.html", "Tighten the clamp hand with the top mark  until the mark is on the bolt head flange.", "par22");
