si[i++] = gsitm("N502440010000L00ENG.html", "GENERAL DESCRIPTION", "title");
si[i++] = gsitm("N502440010000L00ENG.html", "The cooling system is a water-cooled pressurized, forced circulation type which offers the following features:", "ptxt");
si[i++] = gsitm("N502440010000L00ENG.html", "A multi-flow control valve has been adopted to improve fuel efficiency.", "ptxt");
si[i++] = gsitm("N502440010000L00ENG.html", "Simplicity sealed type engine cooling system has been adopted to improve the air bleeding performance of the coolant.", "ptxt");
si[i++] = gsitm("N502440010000L00ENG.html", "Multi-stage control type fan motor has been adopted to reduce the fan driving noise.", "ptxt");
