si[i++] = gsitm("N502440020000M00ENG.html", "*2: includes approximately 0.8 L in the reservoir tank", "ptxt");
si[i++] = gsitm("N502440030000K00ENG.html", "CONSTRUCTION DIAGRAM", "title");
si[i++] = gsitm("N502440040000K00ENG.html", "WATER PASSAGE", "title");
si[i++] = gsitm("N502440050000L00ENG.html", "WATER PUMP", "title");
si[i++] = gsitm("N502440050000L00ENG.html", "The water pump is the centrifugal, impeller type that is installed in front of the cylinder block. It is driven by the drive belt.", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "Discharge volume L / min [7,600 r/min]", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "106", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "Impeller diameter mm", "ptxt");
si[i++] = gsitm("N502440050000L00ENG.html", "56", "ptxt");
si[i++] = gsitm("N502441360000700ENG.html", "RADIATOR RESERVOIR TANK", "title");
si[i++] = gsitm("N502441360000700ENG.html", "A completely-sealed type reservoir tank has been adopted. The completely-sealed type has the following features:", "ptxt");
si[i++] = gsitm("N502441360000700ENG.html", "In the water complete sealing system, the air is separated from the engine coolant as the engine coolant constantly flows into the reservoir tank.", "ptxt");
si[i++] = gsitm("N502441360000700ENG.html", "The structure in which the engine coolant constantly flows into the reservoir tank makes it easier to bleed the air from the piping, thus improving serviceability.", "ptxt");
si[i++] = gsitm("N502441360000700ENG.html", "The radiator cap is installed to the reservoir tank.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "MULTI-FLOW CONTROL VALVE", "title");
si[i++] = gsitm("N502441330000700ENG.html", "GENERAL INFORMATION", "title");
si[i++] = gsitm("N502441330000700ENG.html", "A multi-flow control valve is adopted and installed on the left side of the cylinder block.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "The multiple coolant passages and the flow rates are appropriately controlled to promote warm-up and to reduce friction and cooling loss for better fuel efficiency.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "When the coolant temperature rises due to the malfunction of the multi-flow control valve, the thermostat inside opens and the coolant flows through the passage of the radiator. The coolant cooled in the radiator circulates in the engine, and this prevents overheating.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "MULTI-FLOW CONTROL VALVE SPECIFICATIONS", "title");
si[i++] = gsitm("N502441330000700ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Operation system", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Rotary linear control", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Mounting position", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Engine inlet", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "The number of the controlled passages", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "3 (Except the passage for the thermostat to sense the coolant temperature)", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Drive actuator", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "DC motor, valve-integrated type", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Position sensor", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Non-contact type", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "CONSTRUCTION AND OPERATION", "title");
si[i++] = gsitm("N502441330000700ENG.html", "The multi-flow control valve is mounted at the engine inlet and it controls three coolant passages: the radiator (1), the heater (2) and the engine oil cooler (3).", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "As for the inlet of the coolant, there is an inlet for the thermostat to sense the coolant temperature in addition to the three passages above.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Coolant passage", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Opening pattern", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P1", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P2", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P3", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P4", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P5", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "P6", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "1", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Close", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "Open", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "2", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "3", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "When the engine starts, the rotor position changes from P1 to P6 depending on the coolant temperature and other combined conditions.", "ptxt");
si[i++] = gsitm("N502441330000700ENG.html", "All the passages will open at P5 (conventional thermostat open state).", "ptxt");
si[i++] = gsitm("N502441010001600ENG.html", "SERVICE SPECIFICATIONS", "title");
si[i++] = gsitm("N502441010001600ENG.html", "Item", "ptxt");
