si[i++] = gsitm("N502441010001600ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N502441010001600ENG.html", "Valve opening pressure of radiator reservoir tank cap kPa", "ptxt");
si[i++] = gsitm("N502441010001600ENG.html", "130 - 150", "ptxt");
