si[i++] = gsitm("N502441040001000ENG.html", "Harness set", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "a: Check harness", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "b: LED harness", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "c: LED harness adapter", "ptxt");
