si[i++] = gsitm("N502441040001000ENG.html", "Checking the continuity and measuring the voltage at the harness connector.", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "MB992006", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Extra fine probe", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Continuity check and voltage measurement at harness wire or connector for loose, corroded or damaged terminals, or terminals pushed back in the connector.", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "EG17651130", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Radiator cap tester adapter", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Engine coolant leak check.", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Radiator reservoir tank cap valve opening pressure check.", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "MB991871", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "LLC changer", "ptxt");
si[i++] = gsitm("N502441040001000ENG.html", "Engine coolant refilling.", "ptxt");
si[i++] = gsitm("N502441080000M00ENG.html", "INSPECTION CHART FOR TROUBLE SYMPTOMS", "title");
si[i++] = gsitm("N502441080000M00ENG.html", "Trouble symptom", "ptxt");
si[i++] = gsitm("N502441080000M00ENG.html", "Inspection procedure", "ptxt");
si[i++] = gsitm("N502441080000M00ENG.html", "Reference page", "ptxt");
si[i++] = gsitm("N502441080000M00ENG.html", "Radiator fan (LH) and Radiator fan (RH) do not operate normally (The fans do not operate or operate unintentionally).", "ptxt");
si[i++] = gsitm("N502441080000M00ENG.html", "1", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Inspection Procedure 1: Radiator fan (LH) and Radiator fan (RH) do not operate normally (The fans do not operate or operate unintentionally)", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "If there is any problem in the CAN bus lines, an incorrect diagnosis code may be set. Prior to this diagnosis, diagnose the CAN bus lines (Refer to Electrical and Power Control - LAN System - CAN Fundamental - Basic Inspection - Diagnosis and Repair Workflow - Explanation About the M.U.T.-III SE CAN Bus Diagnostics ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Whenever ECU is replaced, ensure that the CAN bus lines are normal.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "OPERATION", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Based on the engine coolant temperature from the engine coolant temperature sensor, the vehicle speed from the TCM and the A/C switch signal from the A/C Amp., the ECM sends the radiator fans (LH) and (RH) rotation speed signal to the IPDM E/R using a CAN signal.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Based on the radiator fans (LH) and (RH) rotation speed signal from the ECM, the IPDM E/R sends the rotation speed signal (PWM) to the radiator fans (LH) and (RH).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Based on the rotation speed signal received from the IPDM E/R, the radiator fans (LH) and (RH) drive the fan motors.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "TECHNICAL DESCRIPTION", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "If the radiator fan (LH) or (RH) does not operate normally, a fault may occur in wiring harness wires/connectors, the fusible links, the fan motor or the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Alternatively, if a fault occurs in the CAN bus line, the ECM, the TCM or the A/C system, the radiator fan may not operate normally.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "PROBABLE CAUSES", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of CAN bus system", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of IPDM E/R", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of ECM", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of TCM", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of A/C Amp.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Damaged harness or connector", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of fusible link No. V", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of fusible link No. Y", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of engine coolant temperature sensor", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Malfunction of blower assembly [radiator fan motor (LH) and (RH)]", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "DIAGNOSIS", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Check the diagnosis code.", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Use M.U.T.-III SE to check if the diagnosis code is set in the ECM (Refer to Engine – DI AND MPI, Troubleshooting, Diagnostic Function, Method of Reading and Erasing Diagnostic Trouble Codes ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Is the diagnosis code set?", "question");
si[i++] = gsitm("N502441100000V00ENG.html", "YES", "result");
si[i++] = gsitm("N502441100000V00ENG.html", "Troubleshoot the diagnosis code set in the ECM (Refer to Engine – DI AND MPI, Troubleshooting, Diagnostic Trouble Code Chart ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "NO", "result");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 2.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "M.U.T.-III SE other system diagnosis code", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Use M.U.T.-III SE to check if the diagnosis code is set in the IPDM E/R.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Troubleshoot the diagnosis code set in the IPDM E/R (Refer to Electrical & Power Control – Power Control System, IPDM E/R, ECU Diagnosis Information, IPDM E/R, Diagnosis code Index ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 3.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Using M.U.T.-III SE to check if the diagnosis code is set in the TCM.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Troubleshoot the diagnosis code set in the TCM (Refer to Transmission & Driveline – Transaxle & Transmission, CVT, ECU Diagnosis Information, TCM, Diagnosis code Index ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 4.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Use M.U.T.-III SE to check if the diagnosis code is set in the A/C Amp.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Troubleshoot the diagnosis code set in the A/C Amp. (Refer to Ventilation, Heater & Air Conditioner – Heater & Air Conditioning Control System, Automatic Air Conditioning, ECU Diagnosis Information, A/C Amp., Diagnosis code Index ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 5.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "M.U.T.-III SE actuator test", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Perform actuator testing of ECM using M.U.T.-III SE (Refer to Engine – DI and MPI, Troubleshooting, Actuator Test Table ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Item No. 5: PWM Radiator Fan out", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "OK: The radiator fan motor (LH) and (RH) rotate at high speed.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Is the check result normal?", "question");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 11.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 6.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Check the fusible link Nos. V and Y.", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 7.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Replace the damaged fusible link.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Check of short to ground circuit and open circuit in wiring harness between fusible link No. V and radiator fan motor (LH) connector (terminal No. 2) and wiring harness between fusible link No. Y and radiator fan motor (RH) connector (terminal No. 2)", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 8.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Repair the connector(s) or wiring harness.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Check of open circuit and damage in wiring harness between radiator fan motor (LH) connector (terminal No. 1) and body ground and wiring harness between radiator fan motor (RH) connector (terminal No. 1) and body ground", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 9.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Check of short to power supply circuit, short to ground circuit and open circuit in wiring harness between IPDM E/R connector (terminal No. 137) and radiator fan motor (LH) connector (terminal No. 4) and wiring harness between IPDM E/R connector (terminal No. 137) and radiator fan motor (RH) connector (terminal No. 4)", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Go to Step 10.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Perform actuator testing of ECM using M.U.T.-III SE (Refer to Engine – DI and MPI, troubleshooting, Actuator Test Table ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Replace the blower assembly [built-in radiator fan motor (LH) and (RH) ]. Then, go to Step 12.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Check the symptoms", "title");
si[i++] = gsitm("N502441100000V00ENG.html", "Make sure the radiator fan (LH) and (RH) is operating normally.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Transient malfunction.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Replace the IPDM E/R (Refer to Electrical & Power Control – Power Control System, IPDM E/R, Removal and Installation, IPDM E/R ).", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "The radiator fan motor (LH) and (RH) rotate at high speed.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Inspection completed.", "ptxt");
si[i++] = gsitm("N502441100000V00ENG.html", "Replace the ECM (Refer to Engine – DI and MPI, ECM ).", "ptxt");
si[i++] = gsitm("N502441150001400ENG.html", "ENGINE COOLANT CHECK", "title");
si[i++] = gsitm("N502441150001400ENG.html", "Inspect to see whether the amount of coolant in the reservoir tank is between the MAX and MIN amounts.", "ptxt");
si[i++] = gsitm("N502441150001400ENG.html", "Inspect to see that no oil, etc. is mixed in with the coolant.", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "ENGINE COOLANT LEAK CHECK", "title");
si[i++] = gsitm("N502441160000X00ENG.html", "Remove the engine room under cover front A, B and engine room under cover rear (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "Inspect to see that there is no leakage from the points below while idling or while pressurizing with the radiator cap tester (commercial service tool) (A) and special tool radiator cap tester adapter (EG17651130) (B).", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "Radiator", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "Water pump", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "EGR cooler", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "At hose joints", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "When carrying out the inspection while the engine is idling, make sure that the engine is sufficiently warmed up.", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "Inspect to see that there is no hose damage or deterioration, and that the hose clamps are not loose.", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "In the event that there are traces of coolant drainage around the drain hole, vapor hole, or the mounting surface even when the water pump is normal, inspect for leaks from the water pump.", "ptxt");
si[i++] = gsitm("N502441160000X00ENG.html", "(Refer to )", "ptxt");
si[i++] = gsitm("N502441390000700ENG.html", "RADIATOR RESERVOIR TANK CAP VALVE OPENING PRESSURE CHECK", "title");
si[i++] = gsitm("N502441390000700ENG.html", "Be sure that the cap is clean before testing. Rust or other foreign material on the cap seal will cause an improper reading.", "ptxt");
si[i++] = gsitm("N502441390000700ENG.html", "Connect radiator reservoir tank cap tester (commercial service tool) (A) with special tool radiator reservoir tank cap tester adapter (EG17651130) (B) and check radiator reservoir tank cap valve opening pressure.", "ptxt");
si[i++] = gsitm("N502441390000700ENG.html", "Increase the pressure until the indicator of the gauge stops moving.", "ptxt");
si[i++] = gsitm("N502441390000700ENG.html", "Standard value: 130 - 150 kPa", "ptxt");
si[i++] = gsitm("N502441390000700ENG.html", "If not within the standard value, replace the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "ENGINE COOLANT CHANGE", "title");
si[i++] = gsitm("N502441180000U00ENG.html", "When removing the radiator reservoir tank cap, use care to avoid contact with hot engine coolant or steam. Place a shop towel over the radiator reservoir tank cap and turn the radiator reservoir tank cap counterclockwise a little to let the pressure escape through the vinyl tube. After relieving the steam pressure, remove the radiator reservoir tank cap by slowly turning it counterclockwise.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "When draining engine coolant, use a general-purpose hose (drain hose) with the dimensions show in the figure.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Remove the engine room under cover front B (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Connect drain hose.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Drain the water from the radiator, heater core and engine after unplugging the radiator drain plug and removing the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Remove the radiator reservoir tank and drain the coolant.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Disconnect drain hose.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Securely tighten the radiator drain plug.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Reinstall the radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Use special tool LLC changer (MB991871) to refill the engine coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Recommended antifreeze: MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent*", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "*similar high quality ethylene glycol based non-silicate, non-amine, non-nitrate and non-borate coolant with long life hybrid organic acid technology.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Quantity: Approximately 8.0 L", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Do not use alcohol or methanol anti-freeze or any engine coolants mixed with alcohol or methanol anti-freeze. The use of an improper anti-freeze can cause corrosion of the aluminum components.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Do not fill with engine coolant above the \"MAX\" line in the radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "For how to use special tool (MB991871), refer to its manufacturer\'s instructions.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Tighten the radiator reservoir tank cap securely.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Turn the A/C switch to OFF position to start the engine and warm up until the cooling fan operates.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Rev the engine several times and then stop it. Check that there are no coolant leaks.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Remove the radiator reservoir tank cap, and add the engine coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N502441180000U00ENG.html", "Install the engine room under cover front B (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502441170000Q00ENG.html", "ENGINE COOLANT CONCENTRATION CHECK", "title");
si[i++] = gsitm("N502441170000Q00ENG.html", "Using a hydrometer, check if the engine coolant concentration is within the standard value range.", "ptxt");
si[i++] = gsitm("N502441170000Q00ENG.html", "Standard value: 30 to 60% (service concentration range)", "ptxt");
si[i++] = gsitm("N502441170000Q00ENG.html", "Engine coolant of less than 30% concentration has a less rust-proof effect. In a concentration of over 60%, the antifreeze effect and engine cooling performance of the engine coolant are deteriorated, causing a detrimental effect on the engine. Therefore, observe the service concentration range without fail.", "ptxt");
si[i++] = gsitm("N502441170000Q00ENG.html", "Use the MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM without adding water because the concentration is preadjusted to 50%.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "WATER PUMP ENGINE COOLANT LEAK CHECK", "title");
si[i++] = gsitm("N502441190001200ENG.html", "Even when the water pump is normal, a residue of the coolant draining may be found on the drain hole, the vapor hole and the installation surface of the water pump. If a residue of the coolant draining is found, check the water pump leakage by following method.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Wipe off the residue of the coolant draining on the water pump.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Remove the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Make sure that the coolant is cold when removing the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Install the radiator reservoir cap tester (commercial service tool) (A) and special tool radiator reservoir cap tester adapter (EG17651130) (B), and pressurize with 100 kPa.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Do not apply a pressure of more than 100 kPa.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Hold the pressurized state for 20 minutes, and check that the water leakage from the drain hole, the vapor hole or the installation surface of the water pump.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Remove the radiator reservoir tank cap tester and special tool, and install the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "Warm up the engine, let it idle for 20 minutes and stop it.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "After the engine is stopped, check the water leakage from the drain hole, the vapor hole or the installation surface of the water pump.", "ptxt");
si[i++] = gsitm("N502441190001200ENG.html", "If the water leakage is confirmed in the items 4 and 7, replace the water pump. (Refer to ).", "ptxt");
si[i++] = gsitm("N502441400000E00ENG.html", "RADIATOR HOSE CHECK", "title");
si[i++] = gsitm("N502441400000E00ENG.html", "Check entire circumference and length of hoses, using a mirror as required (Refer to ).", "ptxt");
si[i++] = gsitm("N502441400000E00ENG.html", "Check all clamps for tightness and connections for leakage.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "REMOVAL AND INSTALLATION", "title");
