si[i++] = gsitm("N502441260000S00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Water pump", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "O-ring", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502441260000S00ENG.html", ">>A&lt;&lt; O-RING / WATER PUMP INSTALLATION", "title");
si[i++] = gsitm("N502441260000S00ENG.html", "Carefully remove the drying material and other foreign materials on the installation groove for the water pump O-ring.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Carefully remove the drying material and other foreign materials on the water pump installation area of the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Sufficiently apply water or coolant to the O-ring to prevent it from dropping using brushes.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Securely fit the O-ring flange area into the installation groove of the water pump O-ring.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Reverse the water pump carefully and check that the O-ring does not fall down.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "Install the water pump to the timing chain case assembly.", "ptxt");
si[i++] = gsitm("N502441260000S00ENG.html", "When installing the water pump, pay attention not to let the O-ring fall down or be bitten. Otherwise, a coolant leak may be caused.", "ptxt");
