si[i++] = gsitm("N502450040000R00ENG.html", "AIR DUCT AND AIR CLEANER", "title");
si[i++] = gsitm("N502450040000R00ENG.html", "CONSTRUCTION DIAGRAM", "title");
si[i++] = gsitm("N502450040000R00ENG.html", "The front cold air suction method is adopted. For quietness, the resonator is placed at the optimum position.", "ptxt");
si[i++] = gsitm("N502451000000F00ENG.html", "GENERAL DESCRIPTION", "title");
si[i++] = gsitm("N502451000000F00ENG.html", "A water-cooled intercooler, which does not need travelling air to cool the supercharged air, has been adopted.", "ptxt");
si[i++] = gsitm("N502451000000F00ENG.html", "The intercooler is located right above the engine to shorten the length of the intake pipe to improve engine response.", "ptxt");
si[i++] = gsitm("N502451000000F00ENG.html", "The EGR introduction region is expanded by controlling the intake air temperature to improve fuel efficiency and reduce exhaust gas.", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "SPECIFICATIONS", "title");
si[i++] = gsitm("N502451480000E00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Cooling method", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Water-cooled pressurized, forced circulation", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Water pump", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Drive method", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Electric motor", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Intercooler radiator", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Type", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Pressurized corrugate type", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Intercooler coolant", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Specified coolant", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent*1", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Quantity L", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "Approximately 3.2*2", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "*1: similar high quality ethylene glycol based non-silicate, non-amine, non-nitrate and non-borate coolant with long life hybrid organic acid technology", "ptxt");
si[i++] = gsitm("N502451480000E00ENG.html", "*2: includes approximately 0.6 L in the reservoir tank", "ptxt");
si[i++] = gsitm("N502450050000F00ENG.html", "CONSTRUCTION DIAGRAM", "title");
si[i++] = gsitm("N502451470000E00ENG.html", "WATER PASSAGE", "title");
si[i++] = gsitm("N502450070000L00ENG.html", "INTERCOOLER", "title");
si[i++] = gsitm("N502450070000L00ENG.html", "The water-cooled intercooler is located between the turbocharger and the throttle body.", "ptxt");
si[i++] = gsitm("N502450070000L00ENG.html", "The supercharged air is cooled by exchanging heat between the supercharged air and the coolant.", "ptxt");
si[i++] = gsitm("N502450070000L00ENG.html", "The core part is made of aluminum and the tank part is made of resin.", "ptxt");
si[i++] = gsitm("N502451380000I00ENG.html", "INTERCOOLER WATER PUMP", "title");
si[i++] = gsitm("N502451380000I00ENG.html", "The electric water pump is located at the lower side of the left-side headlight.", "ptxt");
si[i++] = gsitm("N502451380000I00ENG.html", "The electric water pump, which can finely control the temperature and manage the flow rate, has been adopted and the coolant inside the cooling circuit is forcibly circulated.", "ptxt");
si[i++] = gsitm("N502451410000K00ENG.html", "INTERCOOLER RADIATOR RESERVOIR TANK", "title");
si[i++] = gsitm("N502451410000K00ENG.html", "A completely-sealed type intercooler reservoir tank has been adopted. The completely-sealed type has the following features:", "ptxt");
si[i++] = gsitm("N502451410000K00ENG.html", "In the water complete sealing system, the air is separated from the intercooler coolant as the intercooler coolant constantly flows into the reservoir tank.", "ptxt");
si[i++] = gsitm("N502451410000K00ENG.html", "The structure in which the intercooler coolant constantly flows into the reservoir tank makes it easier to bleed the air from the piping, thus improving serviceability.", "ptxt");
si[i++] = gsitm("N502451410000K00ENG.html", "The intercooler radiator cap is installed to the reservoir tank.", "ptxt");
si[i++] = gsitm("N502451350000I00ENG.html", "INTERCOOLER RADIATOR", "title");
si[i++] = gsitm("N502451350000I00ENG.html", "The intercooler radiator is located between the A/C condenser and the engine cooling radiator.", "ptxt");
si[i++] = gsitm("N502451350000I00ENG.html", "The hot coolant inside the cooling circuit is cooled by the ambient air.", "ptxt");
si[i++] = gsitm("N502450060000R00ENG.html", "INTAKE MANIFOLD", "title");
si[i++] = gsitm("N502450060000R00ENG.html", "The intake manifold is made of plastic for weight reduction, and the surface roughness of the inner walls of the ports has been improved to reduce intake resistance.", "ptxt");
si[i++] = gsitm("N502450080000R00ENG.html", "EXHAUST MANIFOLD", "title");
si[i++] = gsitm("N502450080000R00ENG.html", "The exhaust manifold has a built-in cylinder head to improve the cooling of the exhaust system and improve the engine performance.", "ptxt");
si[i++] = gsitm("N502450090000F00ENG.html", "TURBOCHARGER", "title");
si[i++] = gsitm("N502450090000F00ENG.html", "The electronic-controlled waste gate actuator is electrically controlled to reduce exhaust energy loss and improve performance by improving the closing property of the turbocharger wastegate valve.", "ptxt");
si[i++] = gsitm("N502450090000F00ENG.html", "The air by-pass valve is integrated with the compressor housing to make it lighter and more compact.", "ptxt");
si[i++] = gsitm("N502450090000F00ENG.html", "The waste gate position sensor is built in to the electronic-controlled waste gate actuator. Waste gate position sensor outputs voltage to ECM based on the turbocharger wastegate valve opening angle. ECM uses this signal to detect the turbocharger wastegate valve opening angle to perform electronic-controlled waste gate actuator feedback control.", "ptxt");
si[i++] = gsitm("N502450090000F00ENG.html", "The electronic-controlled waste gate actuator control motor is built in to the electronic-controlled waste gate actuator. ECM changes current direction according to the Open/Close direction and also changes current to the motor coil to control the electronic-controlled waste gate actuator control motor.", "ptxt");
si[i++] = gsitm("N502450090000F00ENG.html", "The mixed flow turbine is adopted for the turbine to improve supercharging response.", "ptxt");
si[i++] = gsitm("N502450100000T00ENG.html", "EXHAUST PIPE AND MUFFLER", "title");
si[i++] = gsitm("N502450100000T00ENG.html", "CONSTRUCTION DIAGRAM", "title");
si[i++] = gsitm("N502450100000T00ENG.html", "&lt;FWD>", "title");
si[i++] = gsitm("N502450100000T00ENG.html", "&lt;AWD>", "title");
si[i++] = gsitm("N502450100000T00ENG.html", "A 3-piece type of exhaust pipe and muffler which consists of the front catalytic converter, under floor catalytic converter and main muffler has been adopted, and has the following features:", "ptxt");
si[i++] = gsitm("N502450100000T00ENG.html", "The transmission of engine vibration to the car body is reduced by using a flexible tube.", "ptxt");
si[i++] = gsitm("N502450100000T00ENG.html", "A 5-point exhaust muffler hanger has been adopted for optimization of position, which reduces vibration to the vehicle.", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "SERVICE SPECIFICATIONS", "title");
si[i++] = gsitm("N502451010000M00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Standard value", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Valve opening pressure of intercooler radiator reservoir tank cap kPa", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "130 - 150", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "-", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Range of intercooler coolant antifreeze concentration of intercooler radiator %", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "30 - 60", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Turbocharger intake charge pressure kPa", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "180 - 250", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Turbocharger distortion of the installation surface mm", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Cylinder head side", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "0.70 or less", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "Turbocharger side", "ptxt");
si[i++] = gsitm("N502451010000M00ENG.html", "0.40 or less", "ptxt");
si[i++] = gsitm("N502451620000E00ENG.html", "LUBRICANT", "title");
