si[i++] = gsitm("N502451620000E00ENG.html", "*1: similar high quality ethylene glycol based non-silicate, non-amine, non-nitrate and non-borate coolant with long life hybrid organic acid technology.", "ptxt");
si[i++] = gsitm("N502451620000E00ENG.html", "*2: includes approximately 0.6 L in the reservoir tank", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "SPECIAL TOOLS", "title");
si[i++] = gsitm("N502451030000O00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Tool", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Number", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Name", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Use", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "EG17651130", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Radiator cap tester adapter", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Intercooler coolant leak check", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Intercooler radiator reservoir tank cap valve opening pressure check", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB991871", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "LLC changer", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Intercooler coolant refilling.", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "-", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB992744", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB992745", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB992747", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB992748", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "M.U.T.-IIISE", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Checking the supercharging pressure", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MB991953", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Oxygen sensor wrench", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Oxygen sensor (rear) or linear A/F sensor removal and installation", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "MD998770", "ptxt");
si[i++] = gsitm("N502451030000O00ENG.html", "Oxygen sensor (rear) &lt;FWD> or linear A/F sensor removal and installation", "ptxt");
si[i++] = gsitm("N502451520000J00ENG.html", "INTERCOOLER COOLANT CHECK", "title");
si[i++] = gsitm("N502451520000J00ENG.html", "Inspect to see whether the amount of intercooler coolant in the intercooler radiator reservoir tank is between the MAX and MIN amounts.", "ptxt");
si[i++] = gsitm("N502451520000J00ENG.html", "Inspect to see that no oil, etc. is mixed in with the intercooler coolant.", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "INTERCOOLER COOLANT LEAK CHECK", "title");
si[i++] = gsitm("N502451530000J00ENG.html", "Inspect to see that there is no leakage from the points below while idling or while pressurizing with the radiator cap tester (commercial service tool) (A) and special tool radiator cap tester adapter (EG17651130) (B).", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "Intercooler radiator", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "Intercooler water pump", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "Intercooler", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "At hose joints", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "When carrying out the inspection while the engine is idling, make sure that the engine is sufficiently warmed up.", "ptxt");
si[i++] = gsitm("N502451530000J00ENG.html", "Inspect to see that there is no hose damage or deterioration, and that the hose clamps are not loose.", "ptxt");
si[i++] = gsitm("N502451550000K00ENG.html", "INTERCOOLER RADIATOR RESERVOIR TANK CAP VALVE OPENING PRESSURE CHECK", "title");
si[i++] = gsitm("N502451550000K00ENG.html", "Be sure that the cap is clean before testing. Rust or other foreign material on the cap seal will cause an improper reading.", "ptxt");
si[i++] = gsitm("N502451550000K00ENG.html", "Connect radiator cap tester (commercial service tool) (A) with special tool radiator cap tester adapter (EG17651130) (B) and check intercooler radiator reservoir tank cap valve opening pressure.", "ptxt");
si[i++] = gsitm("N502451550000K00ENG.html", "Increase the pressure until the indicator of the gauge stops moving.", "ptxt");
si[i++] = gsitm("N502451550000K00ENG.html", "Standard value: 130 - 150 kPa", "ptxt");
si[i++] = gsitm("N502451550000K00ENG.html", "If not within the standard value, replace the intercooler radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "INTERCOOLER COOLANT CHANGE", "title");
si[i++] = gsitm("N502451560000K00ENG.html", "When removing the intercooler radiator reservoir tank cap, use care to avoid contact with hot intercooler coolant or steam. Place a shop towel over the intercooler radiator reservoir tank cap and turn the intercooler radiator reservoir tank cap counterclockwise a little to let the pressure escape through the vinyl tube. After relieving the steam pressure, remove the intercooler radiator reservoir tank cap by slowly turning it counterclockwise.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "When draining intercooler coolant, follow the instructions below and create a temporary pipe to prevent from splashing.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Prepare soft plastic board (e.g. plastic file folder) and roll up the plastic board.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Check that the length of temporary pipe.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Remove the engine room under cover front A (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Remove the air guide lower mounting clips (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - Condenser Assembly ).", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Install temporary pipe to the intercooler radiator and fix with tape.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Drain the intercooler coolant from the intercooler radiator, intercooler water pump and intercooler after unplugging the intercooler radiator drain plug and removing the intercooler radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Remove the intercooler radiator reservoir tank and drain the intercooler coolant.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Remove temporary pipe.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Securely tighten the intercooler radiator drain plug.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Reinstall the intercooler radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Use special tool LLC changer (MB991871) to refill the intercooler coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Recommended antifreeze: MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent*", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "*similar high quality ethylene glycol based non-silicate, non-amine, non-nitrate and non-borate coolant with long life hybrid organic acid technology.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Quantity: Approximately  3.2 L", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Do not use alcohol or methanol anti-freeze or any engine coolants mixed with alcohol or methanol anti-freeze. The use of an improper anti-freeze can cause corrosion of the aluminum components.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Do not fill with intercooler coolant above the \"MAX\" line in the intercooler radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "For how to use special tool (MB991871), refer to its manufacturer\'s instructions.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Tighten the intercooler radiator reservoir tank cap securely.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Turn the A/C switch to OFF position to start the engine and warm up until the cooling fan operates.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Rev the engine several times and then stop it. Check that there are no intercooler coolant leaks.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Remove the intercooler radiator reservoir tank cap, and add the intercooler coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Install the air guide lower mounting clips (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - Condenser Assembly ).", "ptxt");
si[i++] = gsitm("N502451560000K00ENG.html", "Install the engine room under cover front A (Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502451540000I00ENG.html", "INTERCOOLER COOLANT CONCENTRATION CHECK", "title");
si[i++] = gsitm("N502451540000I00ENG.html", "Using a hydrometer, check if the intercooler coolant concentration is within the standard value range.", "ptxt");
si[i++] = gsitm("N502451540000I00ENG.html", "Standard value: 30 to 60% (service concentration range)", "ptxt");
si[i++] = gsitm("N502451540000I00ENG.html", "Intercooler coolant of less than 30% concentration has a less rust-proof effect. In a concentration of over 60%, the antifreeze effect and intercooler cooling performance of the intercooler coolant are deteriorated, causing a detrimental effect on the intercooler. Therefore, observe the service concentration range without fail.", "ptxt");
si[i++] = gsitm("N502451540000I00ENG.html", "Use the MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM without adding water because the concentration is preadjusted to 50%.", "ptxt");
si[i++] = gsitm("N502451650000I00ENG.html", "INTERCOOLER WATER HOSE CHECK", "title");
si[i++] = gsitm("N502451650000I00ENG.html", "Check entire circumference and length of hoses, using a mirror as required (Refer to ).", "ptxt");
si[i++] = gsitm("N502451650000I00ENG.html", "Check all clamps for tightness and connections for leakage.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "INTAKE CHARGE PRESSURE CHECK", "title");
si[i++] = gsitm("N502451120000G00ENG.html", "Conduct the driving test in a location where driving at full acceleration can be done with safety. Two person should be in the vehicle when the test is conducted; the person in the passenger seat should read the indications shown by the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Turn the ignition switch to \"LOOK\" (OFF) position, and connect the diagnosis connector to the M.U.T.-III SE (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Use the data list function named \"Item No. A7025: Boost pressure sensor 1\" of the M.U.T.-III SE to check the intake charge pressure when the engine speed increases to approximately 3,000 r/min or more by driving at full acceleration in 2nd.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Standard value: 180 - 250 kPa", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "If the intake charge pressure deviates from the standard value, check the following items for possible cause.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Malfunction of the electronic-controlled waste gate actuator", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Leakage of intake charge pressure", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Malfunction of the turbocharger", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Malfunction of the turbocharger wastegate valve", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Malfunction of the air by-pass valve", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "Open circuit or harness damage in turbocharger waste gate actuator circuit or loose connector contact.", "ptxt");
si[i++] = gsitm("N502451120000G00ENG.html", "When the indicated intake charge is more than standard value, supercharging control may be faulty, therefore check the followings.", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "ELECTRONIC-CONTROLLED WASTE GATE ACTUATOR CHECK", "title");
si[i++] = gsitm("N502451130000I00ENG.html", "RESISTANCE BETWEEN TERMINALS CHECK", "title");
si[i++] = gsitm("N502451130000I00ENG.html", "Disconnect the electronic-controlled waste gate actuator connector.", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "Check the continuity of the locations in the table below and check the normal condition. If it is bad, replace the turbocharger assembly.", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "Terminal connector of tester", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "Electrical continuity", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "5-3", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "No continuity", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "5-2", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "5-4", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "5-1", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "Continuity", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "OPERATION CHECK", "title");
si[i++] = gsitm("N502451130000I00ENG.html", "Confirm open circuit and looseness for the harness and connector before operation check.", "ptxt");
si[i++] = gsitm("N502451130000I00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position, check that the electronic-controlled waste gate actuator rod moves. If the electronic-controlled waste gate actuator rod is not moving, replace the turbocharger assembly.", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "AIR BY-PASS VALVE CHECK", "title");
si[i++] = gsitm("N502451140000F00ENG.html", "Remove the intercooler assembly together with the intercooler water hose (Refer to Engine - Engine Electrical - Ignition System - Ignition Coil ).", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Remove the intercooler air hose from the turbocharger (Refer to ).", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Remove the intercooler assembly at a position where they will not interfere with the air by-pass valve check.", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Connect the hand vacuum pump to the nipple of the air by-pass valve.", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Insert the fiber scope into the turbocharger from the position shown in the figure.", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Check operation of the air by-pass valve (diaphragm).", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Negative pressure", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Valve operation", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "Approximately 40.5 kPa", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "It starts opening", "ptxt");
si[i++] = gsitm("N502451140000F00ENG.html", "If the air by-pass valve is defective, replace the turbocharger assembly.", "ptxt");
si[i++] = gsitm("N502451630000M00ENG.html", "AIR CLEANER ELEMENT REPLACEMENT", "title");
si[i++] = gsitm("N502451630000M00ENG.html", "The air cleaner element will become dirty and loaded with dust during use, and the filtering effect will be substantially reduced. Replace it with a new one.", "ptxt");
si[i++] = gsitm("N502451630000M00ENG.html", "Unclasp the air cleaner cover clamp.", "ptxt");
si[i++] = gsitm("N502451630000M00ENG.html", "Remove the air cleaner element and install a new one.", "ptxt");
si[i++] = gsitm("N502451630000M00ENG.html", "Be sure to close the air cleaner cover completely when clamping it.", "ptxt");
si[i++] = gsitm("N502451320000Q00ENG.html", "AIR CLEANER ELEMENT FILTH, PLUGGED, AND DAMAGE INSPECTION", "title");
si[i++] = gsitm("N502451320000Q00ENG.html", "Inspect the air cleaner element for filth, plugged, or damage through visual inspection.", "ptxt");
si[i++] = gsitm("N502451320000Q00ENG.html", "Remove any foreign material from within the air cleaner box.", "ptxt");
si[i++] = gsitm("N502451640000J00ENG.html", "INTAKE AIR HOSE DAMAGE CHECK", "title");
si[i++] = gsitm("N502451640000J00ENG.html", "Check the air duct hose for cracks or damage (Refer to ).", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "EXHAUST PIPE, MUFFLER MOUNT LOOSENESS DAMAGE INSPECTION", "title");
si[i++] = gsitm("N502451330000R00ENG.html", "Inspect the mounted and connected parts of exhaust pipe and muffler for looseness by manually shaking them.", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "Inspect the mounting bolts and nuts of exhaust pipe, muffler and heat shield for looseness.", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "Inspect deterioration, damage and mounted condition of rubber hangers.", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "Inspect the exhaust pipe, muffler and heat shield for corrosion and damage.", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "Inspect that the exhaust pipe and muffler are not in contact with other parts.", "ptxt");
si[i++] = gsitm("N502451330000R00ENG.html", "Start the engine and inspect for exhaust gas leakage from connected parts, etc.", "ptxt");
si[i++] = gsitm("N502451340000Q00ENG.html", "CHECK MUFFLER FUNCTION", "title");
si[i++] = gsitm("N502451340000Q00ENG.html", "Start the engine, vary the engine speed, and listen for any abnormalities in the exhaust noise.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502451160000X00ENG.html", "When removing or installing the air flow sensor, be careful not to apply impact to the sensor.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Do not reuse the air flow sensor that has been dropped.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Degrease the air duct hose and air pipe by isopropyl alcohol, parts cleaner (MZ100387) or equivalent.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "As for the parts cleaner, use the petroleum cleaner whose major component is aliphatic hydrocarbon.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Working area should be airy and kept from flame.", "ptxt");
