si[i++] = gsitm("N502451160000X00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502451160000X00ENG.html", ">>A&lt;&lt; AIR PIPE INSTALLATION", "title");
si[i++] = gsitm("N502451160000X00ENG.html", "When installing the air pipe to each component, make sure that the seal rubber does not come off from the air pipe.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", ">>B&lt;&lt; AIR FLOW SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502451160000X00ENG.html", "Install the air flow sensor to the air cleaner cover with care not to damage the gasket.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Tighten the mounting screws to the specified torque.", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Tightening torque: 1.5 ± 0.2 N·m", "ptxt");
si[i++] = gsitm("N502451160000X00ENG.html", "Do not over-tighten. If the mounting screw is over-tightened, the air cleaner cover can be damaged.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502451180000I00ENG.html", "When removing or installing the boost pressure sensor, be careful not to apply impact to the sensor.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Do not reuse the boost pressure sensor that has been dropped.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Degrease the air hose by isopropyl alcohol, parts cleaner (MZ100387) or equivalent.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "As for the parts cleaner, use the petroleum cleaner whose major component is aliphatic hydrocarbon.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Working area should be airy and kept from flame.", "ptxt");
