si[i++] = gsitm("N502451180000I00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502451180000I00ENG.html", ">>A&lt;&lt; INTERCOOLER BRACKET / INTERCOOLER ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502451180000I00ENG.html", "Install the intercooler assembly to the throttle body, and tighten the intercooler mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Tightening torque: 10 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "After temporarily tightening the intercooler bracket with the mounting bolts, check the intercooler bracket fastens securely to the engine.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Tighten the intercooler bracket mounting bolt to the specified tightening torque.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Tightening torque: 23 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", ">>B&lt;&lt; INTERCOOLER AIR HOSE INSTALLATION", "title");
si[i++] = gsitm("N502451180000I00ENG.html", "Insert hose to stopper end and not overlap with stopper.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Place the hose clamp as shown in the figure so that it does not overlap with the bulge and the stopper end. Then, set the hose clamp between marking.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Tighten the hose clamp to the specified torque.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Tightening torque: 6.0 ± 1.0 N·m", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Do not use an electric screwdriver or air tool. Manually tighten the hose clamp.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", ">>C&lt;&lt; INTERCOOLER GASKET INSTALLATION", "title");
si[i++] = gsitm("N502451180000I00ENG.html", "Fit the intercooler gasket in the intercooler groove securely with neither twisting nor damage given.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", ">>D&lt;&lt; O-RING / BOOST PRESSURE SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502451180000I00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502451180000I00ENG.html", "Install the boost pressure sensor to the intercooler paying attention to avoid damage to the O-ring", "ptxt");
si[i++] = gsitm("N502451390000L00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502451390000L00ENG.html", "If the electric water pump is dropped, do not reuse that electric water pump.", "ptxt");
si[i++] = gsitm("N502451390000L00ENG.html", "Do not operate the electric water pump when the intercooler coolant is empty. If the electric water pump is operated, the electric water pump service life may be reduced. Therefore, do not reuse that electric water pump.", "ptxt");
