si[i++] = gsitm("N502451260000G00ENG.html", "&lt;&lt;A>> AIR INLET FITTING / AIR INLET FITTING GASKET REMOVAL", "title");
si[i++] = gsitm("N502451260000G00ENG.html", "Remove the air inlet fitting mounting bolts.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Be careful not to drop the air inlet fitting gasket.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Loose the EGR hose clamp.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502451260000G00ENG.html", ">>A&lt;&lt; TURBOCHARGER GASKET / TURBOCHARGER ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N502451260000G00ENG.html", "Install the turbocharger gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "When retighten the turbocharger assembly, remove the rust or foreign material attached on the flange surface.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "If the turbocharger assembly mounting surface is uneven, polish the surface with sandpaper and then tighten the nuts to install the turbocharger assembly to the cylinder head.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the nuts to specified torque in the sequence shown in the illustration.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 24 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the nuts again to specified torque in the sequence shown in the illustration.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 42 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", ">>B&lt;&lt; OIL PIPE ASSEMBLY / EYE BOLT INSTALLATION", "title");
si[i++] = gsitm("N502451260000G00ENG.html", "Temporally tighten the oil pipe assembly mounting eye bolts", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Temporally tighten the clamp mounting bolts.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the oil pipe assembly mounting eye bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 17 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the clamp mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 9.5 ± 2.5 N·m", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", ">>C&lt;&lt; OIL RETURN PIPE GASKET INSTALLATION", "title");
si[i++] = gsitm("N502451260000G00ENG.html", "Install the oil return pipe gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", ">>D&lt;&lt; AIR INLET FITTING GASKET / AIR INLET FITTING INSTALLATION", "title");
si[i++] = gsitm("N502451260000G00ENG.html", "Install the gasket as its projection is in the direction shown.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the EGR hose clamp to the specified torque.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 4.0 ± 1.0 N·m", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tighten the air inlet fitting mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N502451260000G00ENG.html", "Tightening torque: 27 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502451270000F00ENG.html", "TURBOCHARGER ASSEMBLY CHECK", "title");
si[i++] = gsitm("N502451270000F00ENG.html", "Visually check the turbine wheel and the compressor wheel for cracking or other damage.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Check whether the turbine wheel and the compressor wheel can be easily turned by hand.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Check for oil leakage from the turbocharger assembly.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "When the waist gate valve is usual, it controls it as follows.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Ignition switch \"LOCK\" (OFF) position: Open", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Ignition switch \"ON\" position: Close", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "DISTORTION CHECK", "title");
si[i++] = gsitm("N502451270000F00ENG.html", "Check the turbocharger for damage and cracks, and replace it if necessary.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Using a straight edge and a thickness gauge, check for distortion of the cylinder head and turbocharger installation surface.", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "Limit:", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "0.70 mm or less &lt;Cylinder head side>", "ptxt");
si[i++] = gsitm("N502451270000F00ENG.html", "0.40 mm or less &lt;Turbocharger side>", "ptxt");
