si[i++] = gsitm("N502451500001100ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502451500001100ENG.html", "The connector and harness of the oxygen sensor (rear) shall be fixed to the bracket securely.", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "The harness is to be free from defects such as excess torsion after the installation of oxygen sensor (rear).", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "Attention to oxygen sensor (rear) without any damages from falling or the impact of the tool.", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "Do not give any impact on oxygen sensor (rear) installed under floor catalytic converter, using a hammer, etc.", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "Do not use the impact wrench to tighten the oxygen sensor (rear).", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "When assembling the oxygen sensor (rear) by special tool oxygen sensor wrench (MD998770), do not damage the lead wires by a slit.", "ptxt");
si[i++] = gsitm("N502451500001100ENG.html", "Not entry of water into the connector when installing connector.", "ptxt");
