si[i++] = gsitm("N502461380000400ENG.html", "BELT DRIVE STARTER GENERATOR", "title");
si[i++] = gsitm("N502461380000400ENG.html", "A belt drive starter generator (generator with motor function) has been adopted instead of alternator.", "ptxt");
si[i++] = gsitm("N502461380000400ENG.html", "The voltage for activating and driving the belt drive starter generator is 48 V. The DC-DC converter regulates the voltage down to 12 V and the electricity is supplied to the vehicle electrical components.", "ptxt");
si[i++] = gsitm("N502461380000400ENG.html", "A water-cooled belt drive starter generator has been adopted. The inverter part is cooled by engine coolant.", "ptxt");
si[i++] = gsitm("N502461380000400ENG.html", "BELT DRIVE STARTER GENERATOR SPECIFICATIONS", "title");
si[i++] = gsitm("N502461380000400ENG.html", "Refer to Electric Power Train - 48V Mild Hybrid - Description - Component Parts - Belt Drive Starter Generator .", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "STARTER MOTOR", "title");
si[i++] = gsitm("N502460020000400ENG.html", "The starter motor is a reduction drive type with planetary gear.", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "STARTER MOTOR SPECIFICATIONS", "title");
si[i++] = gsitm("N502460020000400ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Type", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Reduction drive with planetary gear", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Rated output kW/V", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "1.2/12", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Number of pinion teeth", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "10", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N502460020000400ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502460020000400ENG.html", "\"B\" terminal is constantly supplied with 12V battery power.", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "When starter operating condition is satisfied, IPDM E/R turns starter relay ON by starter relay control signal.", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "When engine cranking condition is satisfied, BCM turns starter cut relay ON by starter cut relay control signal.", "ptxt");
si[i++] = gsitm("N502460020000400ENG.html", "Then 12V battery power is supplied to starter motor (\"S\" terminal) through starter cut relay and starter relay.", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "IGNITION COIL", "title");
si[i++] = gsitm("N502460040000800ENG.html", "The ignition coil is the plug-top type.", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "This plug-top type ignition coil has the following features:", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "A durable low-tension distribution system is adopted.", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "A separate igniting system is adopted. Due to this, high voltage generated in the ignition coils can be delivered into the spark plugs effectively.", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Low fuel consumption due to combustion stabilization", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Compact and light weight", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "IGNITION COIL SPECIFICATION", "title");
si[i++] = gsitm("N502460040000800ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Specification", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Type", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Molded 4-coil", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N502460040000800ENG.html", "This system is equipped with four ignition coils with built-in power transistors for each of the cylinders.", "ptxt");
si[i++] = gsitm("N502460040000800ENG.html", "Interruption of the primary current flowing in the primary side of an ignition coil generates a high voltage in the secondary side of ignition coil. The high voltage thus generated is applied to the spark plugs to generate sparks. The engine control module (ECM) turns the power transistors inside the ignition coils alternately on and off. This causes the primary currents in the ignition coils to be alternately interrupted and allowed to flow to fire the cylinders in the order 1-3-4-2 (Refer to Engine - DI and MPI - Description - Ignition Timing and Control For Current Carrying Time ).", "ptxt");
si[i++] = gsitm("N502460050000700ENG.html", "SPARK PLUG", "title");
si[i++] = gsitm("N502460050000700ENG.html", "Iridium-tipped spark plugs are used.", "ptxt");
si[i++] = gsitm("N502460050000700ENG.html", "SPARK PLUG SPECIFICATION", "title");
si[i++] = gsitm("N502460050000700ENG.html", "Item", "ptxt");
si[i++] = gsitm("N502460050000700ENG.html", "Specification", "ptxt");
