si[i++] = gsitm("N502461390000400ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502461390000400ENG.html", "Do not disassemble any belt drive starter generator other than those described in this manual.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "As a result of troubleshooting, if the belt drive starter generator itself is found to be faulty and you need to disconnect the harnesses connected to the belt drive starter generator (area A in the figure) for replacement, use appropriate insulating protective equipment.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "If the belt drive starter generator is not faulty and the unit is being removed and installed as part of related work, insulating protective equipment is not required.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Insulating protective equipment is not required when replacing the drive belt.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Pre-removal and Post-installation Operation", "title");
