si[i++] = gsitm("N502461390000400ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502461390000400ENG.html", "&lt;&lt;A>> INTERCOOLER RADIATOR RESERVOIR TANK ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502461390000400ENG.html", "Remove the intercooler radiator reservoir tank assembly mounting bolts (Refer to Engine - Intake and Exhaust - Intercooler Radiator Reservoir Tank ).", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Remove the intercooler radiator reservoir tank assembly together with the intercooler hose.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Remove the intercooler radiator reservoir tank assembly at a position where they will not interfere with the removal and installation of belt drive starter generator.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N502461390000400ENG.html", ">>A&lt;&lt; BELT DRIVE STARTER GENERATOR BRACKET INSTALLATION", "title");
si[i++] = gsitm("N502461390000400ENG.html", "Temporally tighten belt drive starter generator bracket mounting bolts (1, 2) in the order of number shown in the illustration with seating bolts.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Tighten belt drive starter generator bracket mounting bolts (3 to 7) to the specified torque in the order of number shown in the illustration.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "3: 43 ± 5 N·m", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Except 3: 36 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", ">>B&lt;&lt; BELT DRIVE STARTER GENERATOR INSTALLATION", "title");
si[i++] = gsitm("N502461390000400ENG.html", "Tighten belt drive starter generator mounting bolts to the specified torque in the order of number shown in the illustration.", "ptxt");
si[i++] = gsitm("N502461390000400ENG.html", "Tightening torque: 42 ± 4 N·m", "ptxt");
si[i++] = gsitm("N502461400000400ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502461400000400ENG.html", "Rotate the pulley of the belt drive starter generator to check that the pulley rotates smoothly without abnormal noise or looseness. If there is any problem, replace the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N502461020000X00ENG.html", "SERVICE SPECIFICATIONS", "title");
