si[i++] = gsitm("N502461270000A00ENG.html", "Engine Room Under Cover front B Removal and Installation (Refer to Body Exterior, Doors, Roof and Vehicle Security - Exterior - Removal and Installation - Under Cover ).", "ptxt");
si[i++] = gsitm("N502461270000A00ENG.html", "Removal", "ptxt");
si[i++] = gsitm("N502461270000A00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N502461270000A00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502461270000A00ENG.html", "Starter motor assembly", "ptxt");
si[i++] = gsitm("N502461270000A00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502461270000A00ENG.html", "&lt;&lt;A>> STARTER MOTOR ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502461270000A00ENG.html", "Remove the starter motor assembly from below the vehicle.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "STARTER MOTOR ASSEMBLY INSPECTION", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "PINION GAP ADJUSTMENT", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "Disconnect the field coil wire from the M-terminal of the magnetic switch.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect a 12-volt battery between the S-terminal and M-terminal.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Set the switch to \"ON\", and the pinion will move out.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "This test must be performed quickly (in less than 10 seconds) to prevent the coil from burning.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Check the pinion-to-stopper clearance (pinion gap) with a feeler gauge.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Standard value: 0.5 - 2.0 mm", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "If the pinion gap is out of specification, adjust by adding or removing gasket(s) between the magnetic switch and front bracket.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "MAGNETIC SWITCH PULL-IN TEST", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "If the pinion moves out, the pull-in coil is good. If it doesn\'t, replace the magnetic switch.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "MAGNETIC SWITCH HOLD-IN TEST", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect a 12-volt battery between the S-terminal and body.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Manually pull out the pinion as far as the pinion stopper position.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "If the pinion remains out, everything is in order. If the pinion moves in, the hold-in circuit is open. Replace the magnetic switch.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "FREE RUNNING TEST", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "Place the starter motor in a vise equipped with soft jaws and connect a fully-charged 12-volt battery to the starter motor as follows:", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect a test ammeter (100-ampere scale) and carbon pile rheostat in series between the battery (+) terminal and starter motor terminal.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect a voltmeter (15-volt scale) across the starter motor.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Rotate the rheostat to full-resistance position.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect the battery cable from the battery (-) terminal to the starter motor body.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Adjust the rheostat until the battery voltage shown on the voltmeter is 11 V.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Confirm that the maximum amperage is within the specifications and that the starter motor turns smoothly and freely.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Current: maximum 95 A", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "MAGNETIC SWITCH RETURN TEST", "title");
si[i++] = gsitm("N502461290000D00ENG.html", "Connect a 12-volt battery between the M-terminal and body.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Pull the pinion out and release. If the pinion quickly returns to its original position, everything is operating properly. If it doesn\'t, replace the magnetic switch.", "ptxt");
si[i++] = gsitm("N502461290000D00ENG.html", "Be careful not to get your fingers caught when pulling out the pinion.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "DISASSEMBLY AND REASSEMBLY", "title");
