si[i++] = gsitm("N502461280000400ENG.html", "DISASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N502461280000400ENG.html", "&lt;&lt;A>> MAGNETIC SWITCH REMOVAL", "title");
si[i++] = gsitm("N502461280000400ENG.html", "Disconnect the lead from the M terminal of the magnetic switch.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "Do not clamp the yoke assembly with a vise.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "&lt;&lt;B>> SNAP RING / STOPPER RING REMOVAL", "title");
si[i++] = gsitm("N502461280000400ENG.html", "Apply a long socket wrench of an appropriate size to the stopper ring and strike the wrench to drive out the stopper ring toward the pinion gear side.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "Remove the snap ring with snap ring pliers, then remove the stop ring and overrunning clutch.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "STARTER MOTOR PARTS CLEANING", "title");
si[i++] = gsitm("N502461280000400ENG.html", "Never clean in a solvent such starter motor parts as the magnetic switch, brush holder, and armature. If they are soaked in a solvent, their insulation could be impaired. When these parts require cleaning, wipe off contamination with cloth.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "Never soak the drive unit in a solvent. If it is washed in a solvent, the grease having been packed in the overrunning clutch at the factory will be washed out. Wipe the drive unit with cloth if it requires cleaning.", "ptxt");
si[i++] = gsitm("N502461280000400ENG.html", "REASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N502461280000400ENG.html", ">>A&lt;&lt; STOPPER RING / SNAP RING INSTALLATION", "title");
si[i++] = gsitm("N502461280000400ENG.html", "Use a suitable puller to pull the stopper ring until it gets over the snap ring.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N502461410000400ENG.html", "COMMUTATOR", "title");
si[i++] = gsitm("N502461410000400ENG.html", "Support the armature with a pair of V block and turn it to measure the runout of the surface not rubbed by the brushes using a dial gauge.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Standard value: 0.05 mm or less", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Limit: 0.1 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Measure the diameter of the commutator.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Standard value: 29.4 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Limit: 28.8 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Measure the depth of the undercut between segments.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Standard value: 0.5 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Limit: 0.2 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "BRUSH HOLDER", "title");
si[i++] = gsitm("N502461410000400ENG.html", "Push the brush into the brush holder to make sure that the spring is working on the brush.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "If the spring is not working, replace the brush holder.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "OVERRUNNING CLUTCH", "title");
si[i++] = gsitm("N502461410000400ENG.html", "Make sure that the pinion cannot be turned counterclockwise and can be turned clockwise freely.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Check the pinion for abnormal ware and damage.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "BRUSHES", "title");
si[i++] = gsitm("N502461410000400ENG.html", "Check the commutator contacting surface of each brush for abnormal roughness. Also check the height of the brush. Replace the brush holder if the height is lower than the limit.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Limit: 7 mm", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "When the contact surface of the brush is rectified or the brush holder is replaced, recondition the contact surface with sandpaper wrapped around the commutator.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "ARMATURE COIL", "title");
si[i++] = gsitm("N502461410000400ENG.html", "Check the armature coil for short circuit as follows.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Set the armature in a growler.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "While holding a thin strip of iron against the armature in parallel with its axis, turn the armature slowly. The armature is normal if the iron strip is not attracted to the armature or it does not vibrate.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Clean the surface of the armature thoroughly before performing the test.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Check the insulation between commutator segments and armature coils. The armature coils are properly insulated if no continuity is present.", "ptxt");
si[i++] = gsitm("N502461410000400ENG.html", "Check continuity between a segment and another. There is no open circuit in the tested coil if there is continuity.", "ptxt");
si[i++] = gsitm("N502461040000T00ENG.html", "SPECIAL TOOLS", "title");
si[i++] = gsitm("N502461040000T00ENG.html", "Tool", "ptxt");
