si[i++] = gsitm("N502461040000T00ENG.html", "M.U.T.-IIISE", "ptxt");
si[i++] = gsitm("N502461040000T00ENG.html", "Reading diagnosis code", "ptxt");
si[i++] = gsitm("N502461040000T00ENG.html", "MB991398", "ptxt");
si[i++] = gsitm("N502461040000T00ENG.html", "Spark plug wrench", "ptxt");
si[i++] = gsitm("N502461040000T00ENG.html", "Removal and installation of spark plug", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "IGNITION COIL CHECK", "title");
si[i++] = gsitm("N502461170000J00ENG.html", "It is impossible to carry out an easy check using a circuit tester because a diode and so on are integrated into the inside circuit of this ignition coil. Accordingly, check the ignition coil in the following procedure.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector (Refer to General Information - General Information - Basic Inspection - M.U.T.-III SE Checking System - Description ).", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Make sure the diagnostic trouble codes are not set using M.U.T.-III SE. If set, record the code No. Carry out the troubleshooting for the set codes and solve the problems even if not related to the ignition.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Disconnect the injector connectors on all of the cylinders.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Disconnect the ignition coil connector.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Remove the ignition coil and install a good spark plug to the ignition coil.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Connect the ignition coil connector.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Ground the side electrode of the spark plug and crank the engine.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Check that spark is produced between the electrodes of the spark plug.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "If the spark plug has weak sparks or no sparks, carry out the same check using a good ignition coil. If there are strong sparks on this check with a good ignition coil, it becomes clear there is a problem with the ignition coil. Replace the ignition coil with a new one. If there are no sparks on this check with a good ignition coil, there is probably a problem with the ignition circuit. Check the ignition circuit.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Using M.U.T.-III SE, make sure whether the diagnostic trouble codes are set due to the check, or not. Except the codes set in Step 1, clear the codes all together if they are present. And then, carry out the troubleshooting about the codes recorded.", "ptxt");
si[i++] = gsitm("N502461170000J00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position, and then disconnect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N502461450000D00ENG.html", "SPARK PLUG REPLACEMENT", "title");
si[i++] = gsitm("N502461450000D00ENG.html", "For the removal and installation of spark plug, refer to .", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502461310000I00ENG.html", "Removal steps", "ptxt");
