si[i++] = gsitm("N502461310000I00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Intercooler assembly", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "•", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Air by-pass valve vacuum pipe and hose assembly connection (Refer to - Engine - Engine Overhaul - Solenoid Valve and Vacuum Hose ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Ignition coil", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "&lt;&lt;B>>", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Spark plug", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502461310000I00ENG.html", "&lt;&lt;A>> INTERCOOLER ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502461310000I00ENG.html", "Disconnect the brake booster vacuum hose and vacuum piping (Refer to Brakes - Brake System - Removal and Installation - Vacuum Lines ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Disconnect the purge control solenoid valve vacuum hose (Refer to Engine - Intake and Exhaust - Intake Manifold ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Remove the water pipe bracket mounting bolt (Refer to Engine - Intake and Exhaust - Intercooler Water Hose and Water Pipe ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Remove the intercooler mounting bolts (Refer to Engine - Intake and Exhaust - Intercooler ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Disconnect the intercooler air hose from the intercooler (Refer to Engine - Intake and Exhaust - Intercooler ).", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Remove the intercooler assembly together with the intercooler water hose.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Remove the intercooler assembly at a position where they will not interfere with the removal and installation of ignition coil.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "&lt;&lt;B>> SPARK PLUG REMOVAL", "title");
si[i++] = gsitm("N502461310000I00ENG.html", "Using special tool spark plug wrench (MB991398), remove the spark plug.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502461310000I00ENG.html", ">>A&lt;&lt; SPARK PLUG INSTALLATION", "title");
si[i++] = gsitm("N502461310000I00ENG.html", "In the same manner as removal, use special tool spark plug wrench (MB991398) to tighten the spark plug to the specified torque.", "ptxt");
si[i++] = gsitm("N502461310000I00ENG.html", "Tightening torque: 18 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502461330000K00ENG.html", "When removing or installing the camshaft position sensor, be careful not to apply impact to the sensor.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "Do not reuse the camshaft position sensor that has been dropped.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "Removal steps", "ptxt");
