si[i++] = gsitm("N502461330000K00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "O-ring", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "•", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "Air by-pass valve vacuum pipe and hose assembly connection (Refer to - Engine - Engine Overhaul - Solenoid Valve and Vacuum Hose ).", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "Exhaust camshaft position sensor", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502461330000K00ENG.html", ">>A&lt;&lt; O-RING / CAMSHAFT POSITION SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502461330000K00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502461330000K00ENG.html", "Install the camshaft position sensor to the rear camshaft bearing cap paying attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502461350000K00ENG.html", "When removing or installing the crank angle sensor, be careful not to apply impact to the sensor.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "Do not reuse the crank angle sensor that has been dropped.", "ptxt");
