si[i++] = gsitm("N502461350000K00ENG.html", "A/C compressor and clutch assembly", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "Crank angle sensor", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "O-ring", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N502461350000K00ENG.html", "&lt;&lt;A>> A/C COMPRESSOR AND CLUTCH ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N502461350000K00ENG.html", "Remove the A/C compressor and clutch assembly mounting bolts (Refer to Ventilation, Heater and Air Conditioner - Heater and Air Conditioning System - Removal and Installation - A/C Compressor ).", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "Remove the A/C compressor and clutch assembly together with the hose from the engine assembly.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "Tie the removed A/C compressor and clutch assembly with a string at a position where they will not interfere with the removal and installation of crank angle sensor.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502461350000K00ENG.html", ">>A&lt;&lt; O-RING / CRANK ANGLE SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502461350000K00ENG.html", "Apply a small amount of new engine oil to the O-ring.", "ptxt");
si[i++] = gsitm("N502461350000K00ENG.html", "Install the crank angle sensor to the cylinder block attention to avoid damage to the O-ring.", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502461370000H00ENG.html", "When the detonation sensor is replaced, initialize the learned value using M.U.T.-III SE (Refer to Engine - DI and MPI - On-vehicle Service - Initialisation Procedure for Learning Value in DI and MPI Engine ).", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N502461370000H00ENG.html", "Starter Motor Assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "Removal", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "Detonation sensor", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502461370000H00ENG.html", ">>A&lt;&lt; DETONATION SENSOR INSTALLATION", "title");
si[i++] = gsitm("N502461370000H00ENG.html", "Align the detonation sensor connector with the position shown in the illustration, and then tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N502461370000H00ENG.html", "Tightening torque: 20 ± 2 N·m", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N502480020000B00ENG.html", "Pre-removal and post-installation operation", "title");
si[i++] = gsitm("N502480020000B00ENG.html", "Instrument Lower Panel Assembly (Instrument Panel Driver\'s Side) Removal and Installation (Refer to Body Interior - Instrument Panel - Removal and Installation - Instrument Panel Driver\'s Side )", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "Accelerator pedal connector", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "Accelerator pedal", "ptxt");
si[i++] = gsitm("N502480020000B00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502480020000B00ENG.html", ">>A&lt;&lt; ACCELERATOR PEDAL INSTALLATION", "title");
si[i++] = gsitm("N502480020000B00ENG.html", "Attach the protrusions of the bracket of the accelerator pedal to the positioning hole A of the brake pedal, check that the positioning pin of the accelerator pedal protrudes from the positioning hole B of the brake pedal, and then tighten the mounting bolt.", "ptxt");
si[i++] = gsitm("N502480050000D00ENG.html", "GENERAL DESCRIPTION", "title");
si[i++] = gsitm("N502480050000D00ENG.html", "The emission control system consists of the following subsystems:", "ptxt");
si[i++] = gsitm("N502480050000D00ENG.html", "Crankcase emission control system", "ptxt");
si[i++] = gsitm("N502480050000D00ENG.html", "Evaporative emission control system", "ptxt");
si[i++] = gsitm("N502480050000D00ENG.html", "Exhaust gas recirculation system", "ptxt");
si[i++] = gsitm("N502480050000D00ENG.html", "Emission reduction control system", "ptxt");
si[i++] = gsitm("N502480060000400ENG.html", "SYSTEM CONFIGURATION DIAGRAM", "title");
si[i++] = gsitm("N502480070000400ENG.html", "EXHAUST GAS CLEANING DEVICES LIST", "title");
si[i++] = gsitm("N502480070000400ENG.html", "System", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Objective / Function", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Composition parts", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Crankcase ventilation system", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "HC decrease", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Re-combustion of blow-by gas.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Positive crankcase ventilation (PCV) valve", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Evaporative emission control system", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Re-combustion of fuel vapor gas.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Canister", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Purge control solenoid valve", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Ventilation solenoid valve &lt;Vehicles for Taiwan>", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Fuel tank pressure sensor &lt;Vehicles for Taiwan>", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Exhaust gas recirculation system", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "NOx decrease", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Reduce NOx generation by controlling EGR volume according to engine warm-up condition and driving conditions.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "EGR valve (DC motor, EGR position sensor)", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "EGR cooler", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "EGR filter", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "EGR gas temperature sensor", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "EGR differential pressure sensor", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Emission reduction systems", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Air-fuel ratio feedback control", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Decrease of CO, HC and NOx", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Controls air-fuel ratio of air-fuel mixture to become theoretical air-fuel ratio (about 14.7), which is when the 3-way catalytic converter\'s cleaning performance is best. It also controls optimum fuel supply based on coolant temperature, driving conditions etc.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Air flow sensor", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Fuel injector", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Fuel injector (high pressure)", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Linear A/F sensor", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Oxygen sensor (rear)", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Crank angle sensor etc.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Catalytic converter", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "It facilitates oxidation of CO and HC and reduction of NOx so that all 3 component gases are cleaned simultaneously.", "ptxt");
si[i++] = gsitm("N502480070000400ENG.html", "Monolith catalyst", "ptxt");
si[i++] = gsitm("N502480080000400ENG.html", "CRANKCASE VENTILATION SYSTEM", "title");
si[i++] = gsitm("N502480080000400ENG.html", "A blow-by gas reduction device prevents blow-by gas from being expelled into the atmosphere and is of closed type. A positive crankcase ventilation (PCV) valve is provided in the ventilation hose from the cylinder head cover to the intake manifold. During low load driving, clean air is supplied to the crankcase by the air intake hose via the breather hose and cylinder head cover, and it mixes with the blow-by gas in the crankcase. The blow-by gas in the crankcase is induced to the intake manifold through the cylinder head cover and PCV valve. During high load driving, blow-by gas in the crankcase is induced to the intake manifold through the air intake hose and throttle body via the breather hose due to negative pressure in the air cleaner.", "ptxt");
si[i++] = gsitm("N502480080000400ENG.html", "POSITIVE CRANKCASE VENTILATION (PCV) VALVE", "title");
si[i++] = gsitm("N502480080000400ENG.html", "PCV valve lifts the plunger according to negative pressure at the intake manifold to create appropriate ventilation for the crankcase.", "ptxt");
si[i++] = gsitm("N502480090000500ENG.html", "EVAPORATIVE EMISSION CONTROL SYSTEM", "title");
si[i++] = gsitm("N502480090000500ENG.html", "HC (hydrocarbon) generated in the fuel tank are adsorbed by the active carbon in the canister and stored. HC stored in the canister is introduced to the intake manifold when engine is in operation where it is mixed with intake air and combusted. ECM introduces optimum HC amount according to driving conditions and so performs duty control on the purge control solenoid valve. Also, the purge control solenoid valve is closed during deceleration or immediately after engine start to restrict change in air-fuel ratio and prevent engine from stalling.", "ptxt");
si[i++] = gsitm("N502480090000500ENG.html", "PURGE CONTROL SOLENOID VALVE", "title");
si[i++] = gsitm("N502480090000500ENG.html", "A purge control solenoid valve is installed on the engine hanger, that is the rear side of the engine. The purge control solenoid valve controls the intake volume of fuel vapor gas from the canister. The purge control solenoid valve is a duty control type solenoid valve. When current is not passing through the coil, nipple A is kept airtight and fuel vapor gas cannot be sucked in. When current passes through the coil, air can pass between nipple A and B and fuel vapor gas is sucked in. ECM changes the ON duty ratio according to engine\'s operating condition to control the intake volume of fuel vapor gas.", "ptxt");
si[i++] = gsitm("N502480090000500ENG.html", "CANISTER", "title");
si[i++] = gsitm("N502480090000500ENG.html", "The canister is installed on the rear right side of the fuel tank. For vehicles for Taiwan, a fuel tank pressure sensor and a ventilation solenoid valve are installed to the canister to check the evaporative emission control system for a fuel evaporative emission leak. For how to monitor a fuel evaporative emission leak, refer to Engine &lt;4B4> - Direct Injection and Multipoint Fuel Injection (DI and MPI), Description, Evaporative Emission Control System Leak Check Monitor and Purge Flow Monitor .", "ptxt");
si[i++] = gsitm("N502480090000500ENG.html", "Fuel Tank Pressure Sensor &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N502480090000500ENG.html", "Refer to Engine &lt;4B4> - Direct Injection and Multipoint Fuel Injection (DI and MPI), Description, Sensor, Fuel Tank Pressure Sensor .", "ptxt");
si[i++] = gsitm("N502480090000500ENG.html", "Ventilation Solenoid Valve &lt;Vehicles for Taiwan>", "title");
si[i++] = gsitm("N502480090000500ENG.html", "Refer to Engine &lt;4B4> - Direct Injection and Multipoint Fuel Injection (DI and MPI), Description, Actuator, Ventilation Solenoid Valve .", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EXHAUST GAS RECIRCULATION SYSTEM", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "When the combustion gas temperature becomes high, generation of the environment polluting NOx (nitrogen oxides) increases rapidly. Exhaust gas recirculation system is used to decrease the volume of NOx generated.The exhaust gas recirculation system re-circulates the exhaust gas to the intake side. It increases specific heat of the combustion gases and reduces combustion speed to lower the combustion temperature and reduce the volume of NOx generated.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR cooler lowers the exhaust gas temperature to suppress temperature rise after the intake air is mixed.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "ECM calculates the exhaust gas recirculation introduction volume according to engine operating conditions and controls the exhaust gas recirculation valve opening angle at optimum.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "Initialise control", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "After the ignition switch turns off, the ECM actuates the EGR valve from the fully closed position to the fully open position. Then, it records the fully closed value and fully open value learned from the EGR valve position sensor output signals. The learned values that are recorded will be used for compensation purposes when the EGR valve is to be actuated subsequently.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR VALVE (DC MOTOR)", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "An EGR valve is installed under the compressor of the turbocharger, and it adjusts the EGR flow rate by opening and closing the valve.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR valve is composed of a good response, low energy, and small DC motor with brush and can generate rotation force corresponding to the current applied on the coil.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "ECM changes current direction according to the Open/Close direction and also changes current to the motor coil in order to the control EGR valve.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR VALVE POSITION SENSOR", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR valve position sensor is integrated with the EGR valve.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "This EGR valve position sensor uses Hall IC and is a non-contact type.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR valve position sensor outputs voltage to ECM based on the EGR valve opening angle.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "ECM uses this signal to detect opening angle of the EGR valve.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR DIFFERENTIAL PRESSURE SENSOR", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR differential pressure sensor is installed near the compressor of the turbocharger.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR differential pressure sensor detects the differential pressure between the upstream area and the downstream area of the EGR valve and sends a digital signal according to the differential pressure to the ECM via SENT communication by using the digital processing circuit incorporated into the sensor.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "Based on this signal, the ECM calculates the flow rate of the exhaust gas that passes through the EGR valve and controls the EGR valve to provide an appropriate EGR amount to prevent the occurrence of misfire, knocking, etc.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR GAS TEMPERATURE SENSOR", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR gas temperature sensor is installed in the EGR passage.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR gas temperature sensor detects the temperature of the gas, which flows from the EGR cooler into the EGR valve as resistance through the thermistor varies, and then sends a voltage signal to the ECM in relation to the EGR gas temperature.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "Based on this output voltage, the ECM corrects the EGR amount to an appropriate amount to prevent the occurrence of misfire, knocking, etc.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR COOLER", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR cooler, which is installed on the exhaust side of the cylinder block, is a laminated type.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR cooler lowers the exhaust gas temperature by circulating the engine coolant through the internal water passage.", "ptxt");
si[i++] = gsitm("N5024800A0000500ENG.html", "EGR FILTER", "title");
si[i++] = gsitm("N5024800A0000500ENG.html", "The EGR filter is provided between the EGR valve and the EGR cooler and it prevents entry of foreign materials to the compressor of the turbocharger.", "ptxt");
si[i++] = gsitm("N5024800C0000400ENG.html", "EMISSION REDUCTION SYSTEMS", "title");
si[i++] = gsitm("N5024800C0000400ENG.html", "These decrease CO, HC and NOx in the exhaust gases and consist of air-fuel ratio feedback control and catalytic converter.", "ptxt");
si[i++] = gsitm("N5024800C0000400ENG.html", "1. AIR-FUEL RATIO FEEDBACK CONTROL", "title");
si[i++] = gsitm("N5024800C0000400ENG.html", "Refer to Engine &lt;4B4> - Direct Injection and Multipoint Fuel Injection (DI and MPI), Description, Fuel Injection Control .", "ptxt");
si[i++] = gsitm("N5024800C0000400ENG.html", "2. CATALYTIC CONVERTER", "title");
si[i++] = gsitm("N5024800C0000400ENG.html", "The catalytic converters are installed under the turbocharger and under the floor.", "ptxt");
si[i++] = gsitm("N5024800C0000400ENG.html", "Based on appropriate air-fuel ratio feedback from linear A/F sensor and oxygen sensor (rear), CO and HC are oxidized and NOx is reduced. Catalytic converter is a monolith with beehive design with catalysts on the unit surface. It is protected by a thermally insulating mat and enclosed in a shell.", "ptxt");
si[i++] = gsitm("N5024800D0000H00ENG.html", "EMISSION CONTROL DEVICE REFERENCE TABLE", "title");
