si[i++] = gsitm("N502480210000R00ENG.html", "M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N502480210000R00ENG.html", "Actuator test check.", "ptxt");
si[i++] = gsitm("N5024800G0000E00ENG.html", "VACUUM CIRCUIT DIAGRAM", "title");
si[i++] = gsitm("N5024800H0000D00ENG.html", "VACUUM HOSE CHECK", "title");
si[i++] = gsitm("N5024800H0000D00ENG.html", "Using the vacuum circuit diagram as a guide, check to be sure that the vacuum hoses are correctly connected.", "ptxt");
si[i++] = gsitm("N5024800H0000D00ENG.html", "Check the connection condition of the vacuum hoses which can be removed, loosened, clogged possibly. And then check whether there are no folded and damaged vacuum hoses.", "ptxt");
si[i++] = gsitm("N5024800I0000D00ENG.html", "VACUUM HOSE INSTALLATION", "title");
si[i++] = gsitm("N5024800I0000D00ENG.html", "When connecting the vacuum hoses, they should be securely inserted onto the nipples.", "ptxt");
si[i++] = gsitm("N5024800I0000D00ENG.html", "Connect the hoses correctly, using the vacuum circuit diagram as a guide.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "GENERAL DESCRIPTION (CRANKCASE EMISSION CONTROL SYSTEM)", "title");
si[i++] = gsitm("N5024800K0000C00ENG.html", "The crankcase emission control system prevents blow-by gases from escaping inside the crankcase into the atmosphere.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "Fresh air is sent from the air cleaner into the crankcase through the breather hose.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "The air becomes mixed with the blow-by gases inside the crankcase.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "The blow-by gas inside the crankcase is drawn into the intake manifold through the positive crankcase ventilation valve.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "The positive crankcase ventilation valve lifts the plunger according to the intake manifold vacuum so as to regulate the flow of blow-by gas properly.", "ptxt");
si[i++] = gsitm("N5024800K0000C00ENG.html", "In other words, the blow-by gas flow is regulated during low load engine operation to maintain engine stability, while the flow is increased during high load operation to improve the ventilation performance.", "ptxt");
si[i++] = gsitm("N5024800L0000D00ENG.html", "COMPONENT LOCATION (CRANKCASE EMISSION CONTROL SYSTEM)", "title");
si[i++] = gsitm("N5024800M0000F00ENG.html", "POSITIVE CRANKCASE VENTILATION SYSTEM CHECK &lt;VEHICLES FOR TAIWAN>", "title");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Remove the PCV hose from the nipple of the positive crankcase ventilation (PCV) valve.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Attach the hand vacuum pump to the PCV hose removed in step 1.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Check that the needle of the vacuum gauge does not rise when negative pressure is applied with the hand vacuum pump.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Attach the PCV hose that was removed to the nipple on the PCV valve and return it to the original state.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Remove the PCV hose from the nipple on the intake manifold side.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Attach the hand vacuum pump to the PCV hose removed in step 5.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Check how the needle of the vacuum gauge moves when negative pressure is applied with the hand vacuum pump.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "If the needle of the vacuum gauge rises slightly while negative pressure is being applied, the PCV valve is normal if the needle returns to 0 when the negative pressure is stopped.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "If the needle of the vacuum gauge keeps rising while negative pressure is being applied and does not return to 0 when the negative pressure is stopped, the plunger of the PCV valve may be seized. Replace the cylinder head cover assembly.", "ptxt");
si[i++] = gsitm("N5024800M0000F00ENG.html", "Attach the PCV hose that was removed to the nipple on the intake manifold and return it to the original state.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "POSITIVE CRANKCASE VENTILATION SYSTEM CHECK &lt;VEHICLES FOR VIETNAM>", "title");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Remove the ventilation hose from the positive crankcase ventilation valve.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Remove the positive crankcase ventilation valve from the cylinder head cover.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Install the positive crankcase ventilation valve at the ventilation hose.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Start the engine and run at idle.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Place a finger at the opening of the positive crankcase ventilation valve and check that vacuum of the inlet manifold is felt.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "At this moment, the plunger in the positive crankcase ventilation valve moves back and forth.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "If vacuum is not felt, clean the positive crankcase ventilation valve or replace it.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Apply a small amount of new engine oil to the new O-ring on the positive crankcase ventilation valve, and tighten to the specified torque.", "ptxt");
si[i++] = gsitm("N5024800M0000G00ENG.html", "Standard value: 2.5 ± 0.4 N·m", "ptxt");
si[i++] = gsitm("N5024800N0000D00ENG.html", "POSITIVE CRANKCASE VENTILATION VALVE CHECK &lt;VEHICLES FOR VIETNAM>", "title");
si[i++] = gsitm("N5024800N0000D00ENG.html", "Insert a thin rod into the positive crankcase ventilation valve from the side shown in the illustration (cylinder head cover installation side), and move the rod back and forth to check that the plunger moves.", "ptxt");
si[i++] = gsitm("N5024800N0000D00ENG.html", "If the plunger does not move, there is a clogging in the positive crankcase ventilation valve. In this case, clean or replace the positive crankcase ventilation valve.", "ptxt");
si[i++] = gsitm("N5024800Q0000G00ENG.html", "COMPONENT LOCATION (EVAPORATIVE EMISSION CONTROL SYSTEM)", "title");
si[i++] = gsitm("N5024800R0000G00ENG.html", "PURGE CONTROL SYSTEM CHECK", "title");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Disconnect the vacuum hose (between evaporative emission purge solenoid and intake manifold) from evaporative emission purge solenoid and connect a hand vacuum pump to the nipple.", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Plug the vacuum hose.", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "When the engine is cold or hot, apply a vacuum of 53 kPa (15.7 in.Hg), and check the condition of the vacuum.", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "When engine is cold (Engine coolant temperature: 40°C or less)", "title");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Engine condition", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Normal condition", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "At idle", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Vacuum is maintained.", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "When engine is hot (Engine coolant temperature: 80°C or higher)", "title");
si[i++] = gsitm("N5024800R0000G00ENG.html", "At idle (after 3 minutes have passed since the engine was started)", "ptxt");
si[i++] = gsitm("N5024800R0000G00ENG.html", "Vacuum will leak.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "PURGE CONTROL SOLENOID VALVE CHECK", "title");
si[i++] = gsitm("N5024800T0000H00ENG.html", "When removing the vacuum hose, always make a mark so that it can be reconnected at original position.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Remove the vacuum hoses from the purge control solenoid valve.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Disconnect the purge control solenoid valve connector.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Connect a hand vacuum pump to nipple (A) of the solenoid valve (refer to the illustration at left).", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Check airtightness by applying vacuum with voltage applied directly from the battery to the solenoid valve and without applying voltage.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Battery voltage", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "State of nipple B", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Normal condition", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Applied", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Opened", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Vacuum leaks", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "plugged", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Vacuum maintained", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Not applied", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Measure the resistance between the terminals of the solenoid valve.", "ptxt");
si[i++] = gsitm("N5024800T0000H00ENG.html", "Standard value: 22 - 26 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "VENTILATION SOLENOID VALVE CHECK", "title");
si[i++] = gsitm("N5024800U0000800ENG.html", "Follow the steps below to check the ventilation solenoid valve.", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "Disconnect the hose from the nipples (A and B) shown in the figure with the harness connector connected.", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "Blow air into the nipple at (B), and check that the air comes out from the nipple at (A).", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "If the air is flowing, go to Step 4. If the air is not flowing, replace the canister and ventilation solenoid valve assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "Use M.U.T.-III SE to perform the actuator test (Refer to Engine &lt;4B4> - Direct Injection and Multipoint Fuel Injection (DI and MPI), Troubleshooting, Actuator Test Table  ).", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "Item No. 6: VENT Sol", "ptxt");
si[i++] = gsitm("N5024800U0000800ENG.html", "Connect a hand vacuum pump to nipple (A) and apply negative pressure. If negative pressure is maintained, the canister and ventilation solenoid valve assembly is normal. If negative pressure is not maintained, replace the canister and ventilation solenoid valve assembly (Refer to ).", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "REMOVAL AND INSTALLATION", "title");
