si[i++] = gsitm("N5024800X0000S00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "&lt;&lt;A>> FUEL VAPOR TUBE DISCONNECTION", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Disconnect fuel vapor tube quick connector according to the following instructions:", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Push in the retainer of the fuel vapor tube connector and unlock the connector.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Disconnect the fuel vapor tube from the canister.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "&lt;&lt;B>> FUEL VAPOR CONTROL LINE TUBE DISCONNECTION", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Follow the steps below to remove the quick connectors of the fuel vapor control line tube:", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "While pressing the retainer of the fuel vapor control line tube, slide the retainer downward to unlock the connector.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Remove the fuel vapor control line tube from the canister or the canister and ventilation solenoid valve assembly.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", ">>A&lt;&lt; FUEL VAPOR CONTROL LINE TUBE CONNECTION", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Check that the O-ring of the quick connector is not scratched and is properly installed.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Insert the nipple of the canister into the fuel vapor control line tube, push the retainer in the direction of the arrow, and assemble the fuel vapor control line tube to the canister or the canister and ventilation solenoid valve assembly.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "After installing the fuel vapor control line tube, gently pull the pipe to check that it is securely connected. Also check that the fuel vapor control line tube moves by 1 to 3 mm in the axial direction between the fuel vapor control line tube and the canister or the canister and ventilation solenoid valve assembly.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", ">>B&lt;&lt; FUEL VAPOR TUBE CONNECTION", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Insert the connector of the fuel vapor tube into the canister until it clicks into place.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "After the installation of the fuel vapor tube, slightly pull the fuel vapor tube to check that it is connected securely.", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", "&lt;VEHICLES FOR VIETNAM>", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Purge pipe assembly connection", "ptxt");
