si[i++] = gsitm("N5024800X0000S00ENG.html", "Fuel vapor control line clip", "ptxt");
si[i++] = gsitm("N5024800X0000S00ENG.html", ">>A&lt;&lt; FUEL VAPOUR TUBE CONNECTION/PURGE PIPE ASSEMBLY CONNECTION", "title");
si[i++] = gsitm("N5024800X0000S00ENG.html", "Insert the connector into the fuel vapour canister until it clicks into place.", "ptxt");
