si[i++] = gsitm("N502480980000700ENG.html", "Apply pressure to port (C) and check that there is no leakage.", "ptxt");
si[i++] = gsitm("N502480980000700ENG.html", "VENTILATION SOLENOID VALVE CHECK", "title");
si[i++] = gsitm("N502480980000700ENG.html", "Connect a hand vacuum pump to nipple of the canister and ventilation solenoid valve assembly.", "ptxt");
si[i++] = gsitm("N502480980000700ENG.html", "Check air tightness by applying a vacuum with voltage applied directly from the battery to the ventilation solenoid valve and without applying voltage.", "ptxt");
si[i++] = gsitm("N502480980000700ENG.html", "Battery voltage", "ptxt");
