si[i++] = gsitm("N502480980000700ENG.html", "Measure the resistance between the terminals of the solenoid.", "ptxt");
si[i++] = gsitm("N502480980000700ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N502480980000700ENG.html", "55 - 63 Ω (at 20°C)", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "INSPECTION &lt;VEHICLES FOR VIETNAM>", "title");
si[i++] = gsitm("N502480980000800ENG.html", "CANISTER CHECK", "title");
si[i++] = gsitm("N502480980000800ENG.html", "Block port (B).", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "Blow air into port (A) and check that it flows freely out of port (C).", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "Release blocked port (B).", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "Apply vacuum pressure to port (B) and check that vacuum pressure exists at the ports (A) and (C).", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "Block port (A) and (B).", "ptxt");
si[i++] = gsitm("N502480980000800ENG.html", "Apply pressure to port (C) and check that there is no leakage.", "ptxt");
si[i++] = gsitm("N502480120000B00ENG.html", "COMPONENT LOCATION", "title");
si[i++] = gsitm("N502480130000700ENG.html", "EGR VALVE (DC MOTOR) CHECK", "title");
si[i++] = gsitm("N502480130000700ENG.html", "EGR VALVE OPERATING NOISE CHECK", "title");
si[i++] = gsitm("N502480130000700ENG.html", "Carry out this check after confirming that the diagnosis code is not set. If the diagnosis code is set, the check on the EGR valve (DC motor) would not possibly be carried out correctly.", "ptxt");
si[i++] = gsitm("N502480130000700ENG.html", "Start the engine and warm up. Allow the engine coolant temperature to reach above 70°C.", "ptxt");
si[i++] = gsitm("N502480130000700ENG.html", "Turn the ignition switch to \"LOCK\" (OFF) position. Confirm that the operating noise of the EGR valve, such as the clicking noise, can be heard five times when the engine is stopped.", "ptxt");
si[i++] = gsitm("N502480130000700ENG.html", "If the operating noise cannot be heard, check the driving circuit of the DC motor.", "ptxt");
si[i++] = gsitm("N502480130000700ENG.html", "If the operating noise cannot be heard although the circuit is normal, There can possibly be something wrong with the EGR valve.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "EGR GAS TEMPERATURE SERSOR CHECK", "title");
si[i++] = gsitm("N502480160000700ENG.html", "Disconnect the EGR gas temperature sensor connector.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Measure resistance between terminals No. 1 and No. 2.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Standard value: 16 – 24 kΩ (at 20°C)", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Remove the EGR gas temperature sensor", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Measure resistance while heating the sensor using a hair drier.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Normal condition:", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Temperature (°C)", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Resistance (kΩ)", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Higher", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Smaller", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "If the value deviates from the standard value or the resistance remains unchanged, replace the EGR gas temperature sensor.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Install a gasket and the EGR gas temperature sensor, and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N502480160000700ENG.html", "Tightening torque: 18 ± 2 N·m", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "EGR DIFFERENTIAL PRESSURE SENSOR REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5024801M0000600ENG.html", "Install EGR differential pressure sensor without shock.", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "Dropped EGR differential pressure sensor must not be used.", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "Tighten with roll stopper fitted securely when installing EGR differential pressure sensor.", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "Not wrong is inserting hose into EGR differential pressure sensor pressure port.", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "Not entry of water into the connector when installing connector.", "ptxt");
