si[i++] = gsitm("N5024801M0000600ENG.html", "Remove the vacuum hose from the differential pressure sensor.", "ptxt");
si[i++] = gsitm("N5024801M0000600ENG.html", "Since the hose does not come off easily if it is stuck to the pipe, make a space and then remove the hose.", "ptxt");
