si[i++] = gsitm("N502480170000G00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N502480170000G00ENG.html", "&lt;&lt;A>> BAND CLAMP / EGR HOSE REMOVAL", "");
si[i++] = gsitm("N502480170000G00ENG.html", "Loosen the hose clamp and remove the EGR hose.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Make sure that the hose band does not fall off.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "&lt;&lt;B>> TURBOCHARGER BRACKET / EGR VALVE STAY REMOVAL", "");
si[i++] = gsitm("N502480170000G00ENG.html", "Remove the four mounting bolts of the turbocharger bracket and the EGR valve stay. Then remove the turbocharger bracket and the EGR valve stay with the turbocharger bracket and the EGR valve stay assembled with each other.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "&lt;&lt;C>> EGR PASSAGE UPPER / EGR VALVE REMOVAL", "title");
si[i++] = gsitm("N502480170000G00ENG.html", "Remove the EGR passage upper mounting bolts.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "When pulling out the mounting bolts, make sure that the EGR valve gasket does not fall off.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N502480170000G00ENG.html", ">>A&lt;&lt; TURBOCHARGER BRACKET / EGR VALVE STAY / EGR VALVE GASKET / EGR VALVE AND EGR PASSAGE ASSEMBLY INSTALLATION", "");
si[i++] = gsitm("N502480170000G00ENG.html", "Fix the EGR valve gasket and the EGR valve by tightening the mounting bolts by hand until they are seated.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Be careful not to let the EGR valve gasket deviate from its position.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Install the EGR valve connector and check that the connector is locked.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Tighten the four mounting bolts of the turbocharger bracket and the EGR valve stay by hand until they are seated.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "A: M8 x 20 Flange bolt", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "B: M8 x 20 Flange bolt + Washer", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "C: 8 x 16 Flange bolt", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Check that there is no space between the EGR passage upper and the EGR valve stay.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Tighten the four mounting bolts of the turbocharger bracket and the EGR valve stay lightly with a tool.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Tighten the EGR passage upper mounting bolts on the rear side of the vehicle to 27 ± 2 N·m (20 ± 1 ft-lb).", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Make sure that the EGR valve is aligned with the passage.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Remove the four mounting bolts of the turbocharger bracket and the EGR valve stay and then remove the turbocharger bracket and the EGR valve stay.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Tighten the EGR passage upper mounting bolts on the front side of the vehicle to 27 ± 2 N·m (20 ± 1 ft-lb)..Check again whether the EGR passage upper mounting bolts (two locations) are tightened to 27 ± 2 N·m (20 ± 1 ft-lb).", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Check that the EGR valve stay is in contact with the EGR passage upper tightly.", "ptxt");
si[i++] = gsitm("N502480170000G00ENG.html", "Tighten the four mounting bolts of the turbocharger bracket and the EGR valve stay to 27 ± 2 N·m (20 ± 1 ft-lb).", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "EGR VALVE INSPECTION", "title");
si[i++] = gsitm("N5024801R0000500ENG.html", "EGR VALVE OPERATIONAL CHECK", "title");
si[i++] = gsitm("N5024801R0000500ENG.html", "Prepare the power supply (5 – 9 V) for the check.", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "Disconnect the EGR valve connector.", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "At this time, the power supply voltage is to be 5 V. For each voltage, current is to be applied within 5 seconds. Once the valve is opened, the voltage is not to be increased any more. The supply voltage to the motor must be a maximum of 9 V.", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "Connect the terminal No. 5 of the EGR valve connector with the positive terminal of the power supply of the check (5 V). Connect the terminal No. 4 of the EGR valve connector with the negative terminal of the power supply of the check.", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "Apply the power supply of 5 V to the EGR valve. Confirm that the EGR valve is opened. If the valve is not opened, increase the voltage of the power supply for the check by 1 V each time.", "ptxt");
si[i++] = gsitm("N5024801R0000500ENG.html", "If the EGR valve is not opened although the voltage applied to the motor is increased to 9 V, clean the EGR valve and carry out the operation check again. Despite this, replace the EGR valve if it does not operate.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "EXHAUST TEMPERATURE SENSOR REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5024801N0000500ENG.html", "&lt;FWD>", "title");
si[i++] = gsitm("N5024801N0000500ENG.html", "The connector and harness of the EGR gas temperature sensor shall be fixed to the bracket securely.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "The harness is to be free from defects such as excess torsion after the installation of EGR gas temperature sensor.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "Attention to EGR gas temperature sensor without any damages from falling or the impact of the tool.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "Do not give any impact on EGR gas temperature sensor installed EGR passage lower, using a hammer, etc.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "Do not use the impact wrench to tighten the EGR gas temperature sensor.", "ptxt");
si[i++] = gsitm("N5024801N0000500ENG.html", "Not entry of water into the connector when installing connector.", "ptxt");
