si[i++] = gsitm("N5024801O0000700ENG.html", "&lt;&lt;A>> TURBOCHARGER BRACKET / EGR VALVE STAY REMOVAL", "");
si[i++] = gsitm("N5024801O0000700ENG.html", "Remove the four mounting bolts of the turbocharger bracket and the EGR valve stay. Then remove the turbocharger bracket and the EGR valve stay with the turbocharger bracket and the EGR valve stay assembled with each other.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "&lt;&lt;B>> EGR VALVE AND EGR PASSAGE UPPER, LOWER ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5024801O0000700ENG.html", "Remove the EGR valve and EGR passage upper, lower mounting bolts.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "When pulling out the mounting bolts of the EGR valve and EGR passage upper, lower assembly, make sure that the EGR filter gasket does not fall off.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N5024801O0000700ENG.html", ">>A&lt;&lt; EGR COOLER / EGR VALVE BRACKET / EGR FILTER GASKET / EGR VALVE AND EGR PASSAGE UPPER, LOWER ASSEMBLY / EGR VALVE STAY / TURBOCHARGER BRACKET INSTALLATION", "");
si[i++] = gsitm("N5024801O0000700ENG.html", "Temporally tighten the EGR cooler mounting nut to the cylinder block.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Temporally tighten the EGR valve bracket mounting bolts to the cylinder block.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Temporally tighten the EGR valve and EGR passage upper, lower assembly mounting bolt to the EGR cooler", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Be careful not to let the EGR filter gasket deviate from its position.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Temporally tighten the EGR valve bracket mounting bolt to the EGR valve and EGR passage upper, lower assembly", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Install the EGR stay on the Turbocharger bracket.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Temporarily tighten the four mounting bolts of the assembled EGR stay and turbocharger bracket.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "A: M8 x 20 Flange bolt (cylinder block)", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "B: M8 x 20 Flange bolt + Washer (Turbocharger bracket)", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "C: 8 x 16 Flange bolt (EGR valve and EGR passage upper, lower assembly)", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Check that the EGR valve stay is in contact with the EGR passage upper tightly.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tighten the EGR valve bracket mounting bolts (cylinder block side) to the specified torque.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tightening torque: 27 ± 2 N·m", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tighten the EGR valve and EGR passage upper, lower assembly mounting nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tighten the EGR cooler mounting nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tightening torque: 24 ± 3 N·m", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tighten the EGR valve bracket mounting bolt (EGR valve and EGR passage upper, lower assembly side) to the specified torque.", "ptxt");
si[i++] = gsitm("N5024801O0000700ENG.html", "Tighten the EGR stay and Turbocharger bracket mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N5024801I0000F00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5024801I0000F00ENG.html", "&lt;UNDER FLOOR>", "title");
si[i++] = gsitm("N5024801I0000F00ENG.html", "Refer to Engine &lt;4B4> - Intake and Exhaust - Catalytic Converter .", "ptxt");
si[i++] = gsitm("N5024801I0000F00ENG.html", "&lt;2WD>", "title");
si[i++] = gsitm("N5024801I0000F00ENG.html", "The catalytic converter is integrated with the exhaust front pipe. The removal and installation is the same as exhaust front pipe (Refer to Engine &lt;4B4> - Intake and Exhaust - Catalytic Converter ).", "ptxt");
si[i++] = gsitm("N5024801I0000F00ENG.html", "&lt;4WD>", "title");
si[i++] = gsitm("N502490150000C00ENG.html", "Description", "title");
si[i++] = gsitm("N502490150000C00ENG.html", "Pendulum type engine mount, which is composed of the engine mounting bracket, transmission mounting bracket and torque rod, has been adopted.", "ptxt");
si[i++] = gsitm("N502490150000C00ENG.html", "This mounting system has the following features:", "ptxt");
si[i++] = gsitm("N502490150000C00ENG.html", "The power train mass is supported in line with the axis of inertia and torque reaction is controlled by torque rod with longitudinal force in stead of vertical force, sensitive to noise and vibration.", "ptxt");
si[i++] = gsitm("N502490150000C00ENG.html", "Engine roll stopper rod has two rubber-to-metal bushings, and reduces vibration and noise doubly.", "ptxt");
si[i++] = gsitm("N502490150000C00ENG.html", "By adopting liquid seal mounts (engine mounting bracket) on the engine side, reduces transmission of noise and vibration in common use and enhances ride quality.", "ptxt");
si[i++] = gsitm("N502490150000C00ENG.html", "Construction Diagram", "title");
si[i++] = gsitm("N502490110000C00ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N502490110000C00ENG.html", "Tool number", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "MB991956", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Engine hanger plate", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Supporting the engine assembly", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "For the engine hanger balancer (MB991454), use the chain only.", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Engine hanger balancer (MB991454) is a part of the engine hanger attachment set (MB991453).", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "MB991454", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Engine hanger balancer", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "MB991527", "ptxt");
si[i++] = gsitm("N502490110000C00ENG.html", "Hanger", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", "Exploded view", "title");
si[i++] = gsitm("N502490180000N00ENG.html", "Engine mounting bracket", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", "Front suspension member", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", "Engine roll stopper rod", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", "Transmission mounting bracket", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", "Comply with the installation procedure when tightening. Refer to Removal and Installation .", "ptxt");
si[i++] = gsitm("N502490180000N00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N502490070001100ENG.html", "When the vehicle is in the READY state, with the service plug detached, faults can occur in the vehicle. Therefore, do not put the vehicle in READY state other than when instructed by the workshop manual to do so.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Work with safety in mind, and do not attempt anything risky.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Do not start work before the exhaust system and engine coolant have cooled down.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Use the specified support points when lifting.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "If the front transaxle assembly is removed or installed, perform the following tasks in numerical order.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Stored Range Value Clear.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Leaning of Movable Range.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Check Initial Learning Quantity.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N502490070001100ENG.html", "Preparation", "title");
si[i++] = gsitm("N502490070001100ENG.html", "Pre-removal Operation (Refer to Engine Mechanical - Engine Assembly )", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Removal", "title");
si[i++] = gsitm("N502490070001100ENG.html", "Install the special tool engine hanger plate (MB991956) to the protector bracket as shown.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the special tool hanger (MB991527) and engine hanger balancer (MB991454) to the engine hanger as shown to support the engine and transaxle assembly.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove the transaxle assembly from the engine assembly (Refer to Transmission & Driveline - Transaxle & Transmission - CVT - CVT - Transaxle Assembly - ).", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove the drive shafts (LH and RH). Refer to  &lt;2WD>,  &lt;AWD>.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove engine roll stopper rod mounting bolts , ,  and  then remove the engine roll stopper rod.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove the front suspension member. Refer to Suspension - Front Suspension - Removal and Installation - Front Suspension Member - .", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove the transmission mounting bracket mounting bolts ,  and .", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Remove the engine mounting bracket mounting bolts  and .", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Make sure that all the hoses and wiring harness connectors are disconnected.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Raise the body slightly with a lift and remove the engine mounting bracket and transmission mounting bracket from the gap between the engine and transaxle assembly and the body.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Be careful not to bend the fuel-high pressure hose.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N502490070001100ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Never allow engine oil to get on engine mounting bracket and transmission mounting bracket. Be careful not to damage engine mounting bracket and transaxle mounting bracket.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Check that engine mounting bracket, transaxle mounting bracket and torque rod are seated properly, and tighten mounting nuts and bolts.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "For parts that are instructed in the mounting direction, check the front mark before mounting.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the transmission mounting bracket to the vehicle, and temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Final tightening (Specified torque)", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 1 → 2 → 3 → 4", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the engine mounting bracket to the vehicle, and temporarily tighten the bolts, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Temporary tightening", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 1 → 2 → 3", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Installation", "title");
si[i++] = gsitm("N502490070001100ENG.html", "Lower the vehicle until the engine mounting bracket and the transmission mounting bracket can be installed. To do so, be careful not to pinch the hoses or the connectors.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the engine mounting bracket to the engine assembly, and temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 1", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 2 → 3 → 4 → 5", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the transmission mounting bracket to the front motor assembly, and temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Tighten the engine mounting bracket mounting bolts on the vehicle side to the specified torque.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Check the engine mounting bracket and transmission mounting bracket are not twisted.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Install the torque rod to the front suspension member and the front transaxle torque rod adapter, and temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 1 → 2", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", ": 3 → 4 → 5 → 6", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Check the engine roll stopper rod is not twisted.", "ptxt");
si[i++] = gsitm("N502490070001100ENG.html", "Post-installation Operation (Refer to Engine Mechanical - Engine Assembly )", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "PRECAUTIONS FOR SUPPLEMENTAL RESTRAINT SYSTEM (SRS) AIR BAG AND SEAT BELT PRE-TENSIONER : Precautions", "title");
si[i++] = gsitm("N503290280000800ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N503290280000800ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N503290280000800ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "PRECAUTIONS FOR REMOVING BATTERY TERMINAL : Precautions", "title");
si[i++] = gsitm("N503290290000800ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N503290290000800ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N503290290000800ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "PRECAUTIONS FOR 48V BATTERY AND DC-DC CONVERTER : Precautions", "title");
si[i++] = gsitm("N503290300000800ENG.html", "When servicing the 48V battery and the DC-DC converter, note the following points.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "The ignition switch should be OFF during maintenance.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Do not disassemble or modify them.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Do not subject them to strong impact such as dropping them.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Do not connect the connectors or terminals other than specified.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Do not use them as a power supply for accessories.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "When the 48V battery is no longer need after replacement, etc., be sure to dispose it through a specified collection route.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "When storing the 48V battery and the DC-DC converter which have been removed, note the following points.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Protect the \"48V+\" terminal and the \"48V-\" terminal of the 48V battery by wrapping them with insulation tape.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "When removing the 48V battery, be careful not to let the \"48V+\" terminal touch the \"48V-\" terminal because high voltage may still be applied due to component failure.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Protect the \"12V+\" terminal, the \"48V+\" terminal and the \"GND\" terminal of the DC-DC converter with insulation tape.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "When removing the DC-DC converter, be careful not to let the \"48V+\" terminal and the \"12V+\" terminal touch the \"GND\" terminal because high voltage may still be applied due to component failure.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Do not place any objects on the 48V battery and the DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Store them in a well-ventilated place and avoid exposure to direct sunlight, high temperature and high humidity.", "ptxt");
si[i++] = gsitm("N503290300000800ENG.html", "Store them in a place where water, rain, or seawater will not be splashed over them.", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "General Information", "title");
si[i++] = gsitm("N503290020000800ENG.html", "Belt drive starter generator, DC-DC converter and 48V battery have been adopted for the 48V MILD HYBRID.", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "By making the voltage higher (48V), the amount of regenerative power generation by deceleration energy increases and the belt drive starter generator is driven by motor by using the charged electrical energy, thus improving fuel efficiency and acceleration.", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "By driving the belt drive starter generator as a motor to restart the engine (automatic start) after the engine is automatically stopped by the Auto Stop & Go (AS&G) system, the quietness when the engine is started has been improved. In addition, the fuel injection can now be performed after increasing the engine speed almost to the idling speed, and it has the following effects.", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "Reduction of the increase of the engine speed during starting", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "Improvement of the convergence of the engine speed during starting", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "Reduction of the fuel consumption during starting", "ptxt");
si[i++] = gsitm("N503290020000800ENG.html", "The DC-DC converter regulates the voltage down to 12 V and the power is supplied to the vehicle electrical components.", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N503290040000800ENG.html", "Cargo area", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "12V battery current sensor", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "Belt drive starter generator", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "12V battery", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "Accelerator pedal position sensor", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "Combination meter (charge warning lamp, ASG OFF warning lamp)", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "48V battery", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "DC-DC converter", "ptxt");
si[i++] = gsitm("N503290040000800ENG.html", "48V battery fan & motor", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "48V battery", "title");
si[i++] = gsitm("N503290050000800ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N503290050000800ENG.html", "The 48V battery is located under the rear seat and mainly consists of a lithium-ion battery, a lithium-ion battery manager and a relay for opening and closing the circuit.", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "A lithium-ion battery is smaller and lighter compared to a lead battery with the same electric energy and it can be charged and discharged with high power.", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "The lithium-ion battery manager monitors the lithium-ion battery state and sends the lithium-ion battery information to the ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "The 48V battery is charged by the belt drive starter generator and drives the belt drive starter generator as a motor. The 48V battery supplies power to the electrical components and the lead battery via the DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "The 48V battery has a self-diagnosis function and a fail-safe function.", "ptxt");
si[i++] = gsitm("N503290050000800ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N503290050000800ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Belt Drive Starter Generator", "title");
si[i++] = gsitm("N503290060000800ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator has functions of an alternator and a motor for auxiliary power for the engine and performs regenerative power generation, engine restart and assist operation in addition to normal power generation.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator has an inverter instead of the regulator of the conventional alternator.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator is located at the same position as the conventional alternator and mainly consists of the stator coil, the rotor (field coil), the resolver (rotation speed of the rotor/position detection sensor) and the inverter (control circuit/field circuit/power circuit/CAN driver/temperature sensor/current sensor).", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "By raising the working voltage from conventional 12 V to 48 V, driving and power regeneration of 10kW can be performed.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator incorporates a CAN driver and communicates with ECM.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator has a self-diagnosis function and a fail-safe function.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Model", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Alternating current type", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Rated voltage", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "48 V", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Maximum rotation speed", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "18,000 r/min", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "No-load rotation speed", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "1,850 r/min", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Operable temperature", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "-30 to 110 °C", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Rotation direction", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Rotates clockwise when seen from the pulley side.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Power generation mode", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Maximum output", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "10kW or more", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Drive mode", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Maximum input", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N503290060000800ENG.html", "In addition to the function that generates electricity equally to the conventional alternator (power generation mode), the belt drive starter generator has the function that regenerates electricity when the brake is applied (regeneration mode), the mode that functions as an auxiliary power for the engine (motor) corresponding to the amount of the accelerator pedal depression and assists acceleration and improves fuel efficiency (drive mode: motor assist) and the function that automatically restarts the engine by the Auto Stop & Go (AS&G) system (drive mode: engine automatic restart).", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator incorporates a CAN driver and transmits information to the ECM via CAN communication. In addition, the belt drive starter generator monitors the incorporated sensors and if an abnormality is detected, it transmits the belt drive starter generator trouble information to the ECM via CAN communication and performs the fail-safe* control according to the trouble contents.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "*: Stops power generation and motor drive by the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The stator of the belt drive starter generator employs a six-phase circuit that has two sets of three-phase windings.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "The belt drive starter generator (A) is connected by the crankshaft pulley (B) and the drive belt (C) as well as the conventional alternator. As the belt drive starter generator drives and restarts the engine instead of the starting motor, the quietness when the engine is automatically restarted has been improved.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "During the drive mode, a large force is applied to the drive belt. In order to maintain appropriate tension on the drive belt at the time and to prevent the drive belt from slipping, an auto-tensioner (D) has been adopted.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N503290060000800ENG.html", "Power Generation Mode", "title");
si[i++] = gsitm("N503290060000800ENG.html", "By energizing the field coil of the rotor, the rotor becomes an electromagnet as well as the conventional generator, and the electromagnetic induction action changes the magnetic field of the stator to generate electricity. As the electricity generated by the stator is a three-phase (six-phase) alternating current, it flows through the inverter circuit and will be rectified to a direct current and then the electricity will be stored in the 48V battery (lithium-ion battery).", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Depending on the conditions, the power circuit during the power generation mode is switched between the inverter power generation by which the electricity generated by the stator is boosted inside the belt drive starter generator by the PWM and the synchronous rectification by which the electricity generated by the stator is rectified through the transistor side like the conventional alternator.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "Drive Mode", "title");
si[i++] = gsitm("N503290060000800ENG.html", "During the drive mode, the transistor of the power circuit turns ON and the direct current from the 48V battery (lithium-ion battery) flows through the transistor side of the power circuit and will be converted to a three-phase (six-phase) alternating current. By passing a three-phase (six-phase) alternating current through the three-phase (six-phase) winding of the stator, a torque is generated in the rotor and the rotor rotates to function as a motor.", "ptxt");
si[i++] = gsitm("N503290060000800ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N503290060000800ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N503290070000800ENG.html", "DC-DC Converter", "title");
si[i++] = gsitm("N503290070000800ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N503290070000800ENG.html", "The DC-DC converter converts the 48 V power generated by the belt drive starter generator instead of 12 V alternator to 12 V power.", "ptxt");
si[i++] = gsitm("N503290070000800ENG.html", "The DC-DC converter is mounted next to the 48-volt battery and is cooled by using the cooling air.", "ptxt");
si[i++] = gsitm("N503290070000800ENG.html", "The bidirectional converter (48 V ↔ 12 V) has been adopted.", "ptxt");
si[i++] = gsitm("N503290070000800ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N503290070000800ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "System Description", "title");
si[i++] = gsitm("N503290100000900ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N503290100000900ENG.html", "Component", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Function", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "48V battery", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Belt drive starter generator", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "DC-DC converter", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "According to the status of the components (belt drive starter generator, 48V battery, DC-DC converter) related to the 48V SYSTEM, the vehicle status and the driver operation status, the ECM instructs the belt drive starter generator to perform power generation/motor assist to improve fuel efficiency and drivability.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The ECM receives the fault information of the components related to the 48V SYSTEM via CAN and sets a DTC.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When there is a problem in the system, the ECM requests the belt drive starter generator and the DC-DC converter to stop and requests the lithium-ion battery manager to open the relay and stops the 48V SYSTEM. The ECM also requests the combination meter to illuminate the charge warning lamp and informs the driver that the 48V SYSTEM is stopped.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "12V battery", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The 12V battery supplies power to the starter motor when the engine is started by the key and supplies power to the vehicle electrical components when the engine is stopped (except during the automatic stop by the AS&G).", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When a DTC related to the 48V SYSTEM is detected, the ASG OFF warning lamp flashes and the charge lamp turns ON as a warning function.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "12V battery current sensor", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The IPDM E/R receives the value of the sensor and sends it to the ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "48V battery fan & motor", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "48V SYSTEM CONTROL", "title");
si[i++] = gsitm("N503290100000900ENG.html", "Controls the 48V SYSTEM as follows, depending on the vehicle state.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the ignition switch is ON (the engine is stopped)", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The 48V SYSTEM is stopped and the power is supplied from the 12V battery to the electrical components.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The ECM sends the charge warning lamp illumination request to the combination meter via CAN.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When starting the engine", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When start operation by the ignition key is performed by the driver, the starter motor is driven and the engine starts.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The 12V battery supplies power to the starter motor.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the engine is running (The 48V SYSTEM is started)", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the engine is started, the ECM instructs the DC-DC converter to boost the voltage. When the boosting is complete, the ECM requests the lithium-ion battery manager to close the relay. The lithium-ion battery manager receives the request from the ECM to close the relay, and it closes the relay.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the relay is closed, the ECM determines that the startup is completed and requests the DC-DC converter to regulate the voltage down and starts supplying power to the electrical components. The ECM also sends the charge warning lamp OFF request to the combination meter via CAN.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "During driving without power generation/when the engine is automatically stopped", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the charging statuses of the 48V battery (lithium-ion battery) and the 12V battery are good, the ECM stops the power generation by the belt drive starter generator and reduces the engine load which is needed for power generation.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the conditions for the execution of engine automatic stop by the AS&G are met, the ECM stops the engine automatically to reduce fuel consumption amount. In addition, the AS&G indicator lamp in the combination meter illuminates during the engine automatic stop. The power is supplied from the 48V battery to the electrical components also during the automatic stop.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When restarting the engine", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the conditions for the execution of engine automatic restart by the AS&G are met, the ECM sends the drive request signal (control mode*1, request torque*2) to the belt drive starter generator via CAN. According to the information received from the ECM via CAN, the belt drive starter generator is driven as a starting motor to restart the engine automatically.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "*1: There are two control modes: stop mode and torque control mode.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "*2: As for the request torque, a positive value indicates motor drive and a negative value indicates power generation.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The power for driving the belt drive starter generator is supplied from the 48V battery.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Also during the automatic restart, the power is supplied from the 48V battery to the electrical components via the DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "During regenerative charging", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The ECM sends the drive request signal (control mode*1, request torque*2) and the power generation upper limit voltage to the belt drive starter generator via CAN. The belt drive starter generator generates power according to the information received from the ECM via CAN. The power generated by the belt drive starter generator is used to charge the 48V battery and is supplied to the electrical components via the DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The fuel efficiency has been improved by generating power intensively during deceleration.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "During motor assist", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "When the conditions for execution of the motor assist, such as charging status of the 48V battery, the driver operation and the vehicle driving condition, are met, the ECM sends the assist request to the belt drive starter generator to assist the engine drive power. During motor assist, the power for driving the belt drive starter generator is supplied from the 48V battery.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Also during the motor assist, the power is supplied from the 48V battery to the electrical components via the DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "The ECM executes the motor assist when all the following motor assist execution conditions are satisfied. Also, if any of the motor assist prohibition conditions are satisfied, the ECM prohibits the motor assist.", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Motor assist execution/prohibition condition", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Vehicle condition", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Executed", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Prohibited", "ptxt");
si[i++] = gsitm("N503290100000900ENG.html", "Shift position", "ptxt");
