si[i++] = gsitm("N503290330000800ENG.html", "Symptom Table", "title");
si[i++] = gsitm("N503290330000800ENG.html", "Before performing trouble symptom diagnosis, perform self-diagnosis of the ECM with the M.U.T.-III SE. Perform the trouble diagnosis if any DTC is detected.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Symptom", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Possible cause", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Inspection item", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The charge warning lamp does not illuminate when the ignition switch is turned on.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Blown fuse.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Combination meter power supply circuit. Refer to  (Full TFT meter) or  (7 inch information display).", "ptxt");
