si[i++] = gsitm("N503290330000800ENG.html", "Perform CAN bus line diagnosis. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of combination meter.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Perform On Board Diagnosis Function. Refer to  (Full TFT meter) or  (7 inch information display).", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of ECM.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the ECM. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The charge warning lamp illuminates after the engine is started.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The drive belt is loose or worn.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the drive belt. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of DC-DC converter.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the DC-DC converter. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Repair or replace the connector(s) or wiring harness.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of belt drive starter generator.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the belt drive starter generator. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of 48V battery.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the 48V battery. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The 48V battery temperature is low because the vehicle is under cryogenic temperature environment (less than -35°C).", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Leave the vehicle under environment of -35°C or more for a certain period of time.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Since the vehicle had been left for a long period of time, the charging rate of the 48V battery is low (less than 10%).", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Since the 48V battery is charged after the engine is started, check the status of the following items of the ECM data list and check if the power is being generated and charged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Item No. 104: Generator torque", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Item No. 134: 48V battery pack SOC", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Item No. 138: 48V battery pack Current", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The 48V battery is insufficiently charged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The terminal of 48V battery is loose or damaged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Tighten the loose part or replace the 48V battery. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The 48V battery is overcharged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The 12V battery is flat.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The drive belt is damaged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Abnormal noise occurs from the belt drive starter generator.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of belt drive starter generator installation.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Install the belt drive starter generator properly. Refer to .", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "The bearing is dirty, worn or damaged.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of rotor, inverter or stator.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "An abnormal sound is heard from the 48V battery fan & motor.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Malfunction of 48V battery fan & motor.", "ptxt");
si[i++] = gsitm("N503290330000800ENG.html", "Replace the 48V battery fan & motor. Refer to .", "ptxt");
si[i++] = gsitm("N503290230000M00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N503290230000M00ENG.html", "For the removal and installation of 48V battery, refer to ELECTRICAL & POWER CONTROL - POWER SUPPLY, GROUND & CIRCUIT ELEMENTS - REMOVAL AND INSTALLATION - 48V BATTERY - SERVICE PROCEDURE .", "ptxt");
si[i++] = gsitm("N503290230000N00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N503290230000N00ENG.html", "For the removal and installation of belt drive starter generator, refer to ENGINE - ENGINE ELECTRICAL - CHARGING SYSTEM - BELT DRIVE STARTER GENERATOR - REMOVAL AND INSTALLATION .", "ptxt");
si[i++] = gsitm("N503290230000O00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N503290230000O00ENG.html", "For the removal and installation of 48V battery, refer to ELECTRICAL & POWER CONTROL - POWER SUPPLY, GROUND & CIRCUIT ELEMENTS - REMOVAL AND INSTALLATION - 48V BATTERY - SERVICE PROCEDURE .", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "PRECAUTIONS FOR SUPPLEMENTAL RESTRAINT SYSTEM (SRS) AIR BAG AND SEAT BELT PRE-TENSIONER : Precautions", "title");
si[i++] = gsitm("N5040206R0000D00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5040206R0000D00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5040206R0000D00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5040206S0000C00ENG.html", "PRECAUTIONS FOR PROCEDURE WITHOUT COWL TOP COVER : Precautions", "title");
si[i++] = gsitm("N5040206S0000C00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5040206T0000E00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5040206T0000E00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5040206U0000C00ENG.html", "Precaution for TCM and Transaxle Assembly Replacement", "title");
si[i++] = gsitm("N5040206U0000C00ENG.html", "To replace TCM, refer to .", "ptxt");
si[i++] = gsitm("N5040206U0000C00ENG.html", "To replace transaxle assembly, refer to .", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "General Precautions", "title");
si[i++] = gsitm("N5040206V0000D00ENG.html", "The ignition switch is OFF and disconnect the battery cable from the negative terminal before connecting or disconnecting the CVT assembly harness connector. Because battery voltage is applied to TCM even if ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "When connecting or disconnecting pin connectors into or from TCM, never damage pin terminals (bend or break).", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Check that there are not any bends or breaks on TCM pin terminal, when connecting pin connectors.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Perform TCM input/output signal inspection and check whether TCM functions normally or not before replacing TCM. Refer to .", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Perform “DTC (Diagnostic Trouble Code) CONFIRMATION PROCEDURE”.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "If the repair is completed DTC should not be displayed in the “DTC CONFIRMATION PROCEDURE”.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Always use the specified brand of CVT fluid.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Recommended Fluids/Lubricants", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "MITSUBISHI MOTORS GENUINE CVTF-J4 or MITSUBISHI MOTORS GENUINE CVTF-J4+", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Use only “Mitsubishi Motors Genuine CVTF-J4” or “Mitsubishi Motors Genuine CVTF-J4+” transmission fluid to ensure optimum transmission performance.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Use lint-free paper not cloth rags during work.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Dispose of the waste oil using the methods prescribed by law, ordinance, etc. after replacing the CVT fluid.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Before proceeding with disassembly, thoroughly clean the outside of the transaxle. It is important to prevent the internal parts from becoming contaminated by dirt or other foreign matter.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "Disassembly should be done in a clean work area.", "ptxt");
si[i++] = gsitm("N5040206V0000D00ENG.html", "To avoid the risk of minor injury or property damage: If the 12-volt battery has low or no voltage, the transmission cannot be shifted. Replace the battery or repair the damaged power supply system. If towing the vehicle, follow the tow procedure, refer to .", "par1");
si[i++] = gsitm("N5040206W0000E00ENG.html", "On Board Diagnosis (OBD) System of CVT and Engine", "title");
si[i++] = gsitm("N5040206W0000E00ENG.html", "The TCM and ECM have an on board diagnostic system. It will light up the malfunction indicator light (MIL) to warn the driver of a malfunction causing emission deterioration.", "ptxt");
si[i++] = gsitm("N5040206W0000E00ENG.html", "Be sure to turn the ignition switch OFF and disconnect the battery cable from the negative terminal before any repair or inspection work. The open/short circuit of related switches, sensors, solenoid valves, etc. will cause the MIL to light up.", "ptxt");
si[i++] = gsitm("N5040206W0000E00ENG.html", "Be sure to connect and lock the connectors securely after work. A loose (unlocked) connector will cause the MIL to light up due to an open circuit. (Be sure the connector is free from water, grease, dirt, bent terminals, etc.)", "ptxt");
si[i++] = gsitm("N5040206W0000E00ENG.html", "Be sure to route and secure the harnesses properly after work. Interference of the harness with a bracket, etc. may cause the MIL to light up due to a short circuit.", "ptxt");
si[i++] = gsitm("N5040206W0000E00ENG.html", "Be sure to connect rubber tubes properly after work. A misconnected or disconnected rubber tube may cause the MIL to light up due to a malfunction of the EGR system or fuel injection system, etc.", "ptxt");
si[i++] = gsitm("N5040206W0000E00ENG.html", "Be sure to erase the unnecessary malfunction information (repairs completed) from the TCM and ECM before returning the vehicle to the customer.", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Removal and Installation Procedure for CVT Unit Connector", "title");
si[i++] = gsitm("N5040206X0000C00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Rotate bayonet ring  counterclockwise. Pull out CVT unit harness connector  upward and remove it.", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Align marking  on CVT unit harness connector terminal with marking  on bayonet ring. Insert CVT unit harness connector.", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Rotate bayonet ring clockwise.", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Rotate bayonet ring clockwise until marking  on CVT unit harness connector terminal body is aligned with the slit  on bayonet ring as shown in the figure (correctly fitting condition).", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Securely align marking  on CVT unit harness connector terminal body with bayonet ring slit . Then, be careful not to make a half fit condition as shown in the figure.", "ptxt");
si[i++] = gsitm("N5040206X0000C00ENG.html", "Never mistake the slit of bayonet ring for other dent portion.", "ptxt");
si[i++] = gsitm("N5040206Z0000E00ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N5040206Z0000E00ENG.html", "When you order special service tool, use part number on \"tool order number\" of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N5040206Z0000E00ENG.html", "The actual shape of the tools may differ from those illustrated here.", "title");
