si[i++] = gsitm("N5040207H0000C00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5040207H0000C00ENG.html", "When operating the paddle shifter to + side or - side, the shift position is changed over, and shift change like M/T becomes possible.", "ptxt");
