si[i++] = gsitm("N5040207J0000C00ENG.html", "The electric shift control module consists of the microcomputer and input/output connectors for signal and power supply.", "ptxt");
si[i++] = gsitm("N5040207J0000C00ENG.html", "The electric shift control module includes a self-diagnosis function for simplifying trouble diagnosis.", "ptxt");
