si[i++] = gsitm("N5040207K0000C00ENG.html", "Completely stop the vehicle and press the P position switch while depressing the brake pedal. The shift position changes to P.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "R", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "While depressing the brake pedal, press the selector knob button and shift the selector lever to R position. The shift position changes to R.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "Nr", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "When shift position is D or M, while depressing the brake pedal, shift the selector lever to the Nr position and hold it for approx. 0.5 second. The shift position changes to N.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "Even if selector lever is shifted to the Nr position when shift position is R, the shift position does not change to N and the shift position warning buzzer sounds.", "ptxt");
