si[i++] = gsitm("N5040207K0000C00ENG.html", "When shift position is R, while depressing the brake pedal, shift the selector lever to the Nd position and hold it for approx. 0.5 second. The shift position changes to N.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "Even if selector lever is shifted to the Nd position when shift position is D or M, the shift position does not change to N and the shift position warning buzzer sounds.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "D/M", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "While depressing the brake pedal, shift the selector lever to D/M position. The shift position changes to D.", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "While driving in the D position, shift the selector lever to D/M position again. The shift position changes to M (manual mode)", "ptxt");
si[i++] = gsitm("N5040207K0000C00ENG.html", "To switch from M (manual mode) to the D driving, shift the selector lever to D/M position again.", "ptxt");
