si[i++] = gsitm("N5040207O0000C00ENG.html", "The shift actuator operates according to the output signal from the electric shift control module and changes the shift position of the transaxle.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5040207O0000C00ENG.html", "Motor", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "A 3-phase SR motor is used.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "Coil is placed on the stator core around the motor and the current that passes through the coil in sequence generates the rotating force for the inner rotor core.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "Encoder", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "The Hall IC type rotation angle sensor is used for higher accuracy in the detection of the rotor rotation angle.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "It detects the rotor rotation angle and outputs pulse signals to the electric shift control module.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "The electric shift control module controls the timing of the current feed to the coils optimally based on the signal from the encoder.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "Actuator Reduction Gear", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "The actuator reduction gear consists of a cycloidal gear and includes a motor with its torque amplified for secure operation under high torque-requiring conditions.", "ptxt");
si[i++] = gsitm("N5040207O0000C00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5040207O0000C00ENG.html", "The shift actuator moves the manual shaft of transaxle and changes shift position.", "ptxt");
