si[i++] = gsitm("N5040207P0000C00ENG.html", "The shift actuator relay A and B supply power to the motor coil A and B of shift actuator. Electric shift control module activates the shift actuator relay A and B to supply power to the motor coil A and B of shift actuator when the ignition switch is turned ON.", "ptxt");
si[i++] = gsitm("N5040207P0000C00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5040207P0000C00ENG.html", "The shift actuator relay A and B connect and disconnects of the power supply circuit by ON / OFF of the relay switch.", "ptxt");
si[i++] = gsitm("N5040207P0000C00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5040207P0000C00ENG.html", "The relays used in the shift actuator relay are normal open relays.", "ptxt");
si[i++] = gsitm("N5040207P0000C00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5040207P0000C00ENG.html", "The shift actuator relay A and B is installed in the left side of engine room.", "ptxt");
si[i++] = gsitm("N5040207S0000C00ENG.html", "Cross-Sectional View", "title");
