si[i++] = gsitm("N5040207U0000C00ENG.html", "Secondary pulley", "ptxt");
si[i++] = gsitm("N5040207U0000C00ENG.html", "Steel belt", "ptxt");
si[i++] = gsitm("N5040207U0000C00ENG.html", "Final drive", "ptxt");
