si[i++] = gsitm("N5040207X0001900ENG.html", "Protection Control", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "The TCM becomes the protection control status temporarily to protect the safety when the safety of TCM and transmission is lost. It automatically returns to the normal status if the safety is secured.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "The TCM has the following protection control.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "CONTROL FOR WHEEL SPIN", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "Control", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "When a wheel spin is detected, the engine output and gear ratio are limited and the line pressure is increased.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Limits engine output when a wheel spin occurs in any of right and left drive wheels.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Vehicle behavior in control", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "If the accelerator is kept depressing during wheel spin, the engine revolution and vehicle speed are limited to a certain degree.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Normal return condition", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Wheel spin convergence returns the control to the normal control.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "TORQUE IS REDUCED WHEN DRIVING WITH THE REVERSE GEAR", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "Engine output is controlled according to a vehicle speed while reversing the vehicle.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Power performance may be lowered while reversing the vehicle.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Torque returns to normal by positioning the selector lever in a range other than “R” position.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "CONTROL WHEN FLUID TEMPERATURE IS HIGH", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "When the CVT fluid temperature is high, the gear shift permission maximum revolution and the maximum torque are reduced than usual to prevent increase of the oil temperature.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "Power performance may be lowered, compared to normal control.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "The control returns to the normal control when CVT fluid temperature is lowered.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "REVERSE PROHIBIT CONTROL", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "The reverse brake is controlled to avoid becoming engaged when the selector lever is set in “R” position while driving in forward direction at more than the specified speed.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "If the selector lever is put at “R” position when driving with the forward gear, the gear becomes neutral, not reverse.", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "The control returns to normal control when the vehicle is driven at low speeds. (The reverse brake becomes engaged.)", "ptxt");
si[i++] = gsitm("N5040207X0001900ENG.html", "MAC (MESSAGE AUTHENTICATION CODE)", "title");
si[i++] = gsitm("N5040207X0001900ENG.html", "MAC (Message Authentication Code) is a function that prevents unauthorized communication from other than the ECU with MAC function by secure authentication communication. TCM can write a MAC key required for communication between the ECUs and perform MAC diagnosis.", "ptxt");
si[i++] = gsitm("N5040203G0002L00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0002L00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5040203G0002L00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0002L00ENG.html", "Highly accurate line pressure control and secondary pressure control reduces friction for improvement of fuel economy.", "ptxt");
si[i++] = gsitm("N5040203G0002L00ENG.html", "Normal Oil Pressure Control", "title");
si[i++] = gsitm("N5040203G0002L00ENG.html", "Appropriate line pressure and secondary pressure suitable for driving condition are determined based on the accelerator pedal position, engine speed, primary pulley (input) speed, secondary pulley (output) speed, vehicle speed, input torque, stop light switch signal, transmission range switch signal, lock-up signal, power voltage, target shift ratio, oil temperature, oil pressure, and electric shift selector signal.", "ptxt");
si[i++] = gsitm("N5040203G0002L00ENG.html", "Secondary Pressure Feedback Control", "title");
si[i++] = gsitm("N5040203G0002L00ENG.html", "In normal oil pressure control and oil pressure control in shifting, highly accurate secondary pressure is determined by detecting the secondary pressure using an oil pressure sensor and by feedback control.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "To select the gear ratio that can give the driving force to meet driver\'s intent or vehicle situation, the vehicle driving condition such as vehicle speed or accelerator pedal position is detected and the most appropriate gear ratio is selected and the shifting method before reaching the speed is determined. The information is output to the primary pressure solenoid valve and secondary pressure solenoid valve to control the line pressure input/output to the pulley, to determine the pulley (movable pulley) position and to control the gear position.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Shift Position Function", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "D Position", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Gear shifting is performed in all shifting ranges from the lowest to the highest gear ratio.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "M Position (Manual Mode)", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "By pulling the paddle shifter + side or - side in D position or M position the manual mode switch is changed over, and shift change like M/T becomes possible following the changing gear set line step by step.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "The TCM transmits the manual mode shift refusal signal to the combination meter if the TCM refuses the transmission from the driving status of vehicle when the paddle shifter shifts to UP side (+ side) or DOWN side (– side). The combination meter blinks shift indicator on the combination meter and sounds the tone alarm to indicate the driver that the shifting is not performed when receiving this signal. However, the TCM does not transmit the manual mode shift refusal signal in the conditions as per the following.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "When the paddle shifter shifts to DOWN side (– side) while driving in M1.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "When the paddle shifter shifts to UP (+ side) side while driving in M8.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Blipping Control", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "Using engine torque, the blipping control enables a faster and more responsive gear shifting by compensating inertia torque generated from the rotational change during gear shifting in real time.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "The blipping control is activated when shifting up/down in manual mode.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "The blipping control is not activated when the vehicle is in the following conditions:", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "When CAN communication is abnormal.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "During the retard inhibit signal transmission from ECM within the engine-CVT integrated control.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Engine coolant temperature is less than 20°C (68°F).", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "CVT fluid temperature is more than 120°C (248°F).", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Vehicle speed is less than 20 km/h (13 MPH).", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "When ABS, TCS or ASC is active.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "During wheel spin.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "ECM selects blipping control or normal shift control according to the gear position, the shift position, etc.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "The blipping control is activated when ECM judges it controllable after receiving a control permit signal from TCM.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "ECM controls engine torque, based on generated inertia torque.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Hill Climbing And Descending Control", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "If a downhill is detected with the accelerator pedal is released, the system performs downshift to increase the engine brake force so that vehicle may not be accelerated more than necessary. If a climbing hill is detected, the system improves the acceleration performance in re-acceleration by limiting the gear shift range on the high side.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "For engine brake control on a downhill, the control can be stopped with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203G0003300ENG.html", "Control In Acceleration", "title");
si[i++] = gsitm("N5040203G0003300ENG.html", "From change of the vehicle speed or accelerator pedal position, the acceleration request level of the driver or driving scene is evaluated. In start or acceleration during driving, the gear shift characteristics with linearity of revolution increase and vehicle speed increase are gained to improve the acceleration feel.", "ptxt");
si[i++] = gsitm("N5040203G0002N00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0002N00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5040203G0002N00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0002N00ENG.html", "Based on accelerator pedal angle, engine speed, primary pulley speed, and the input speed, the optimum operating pressure is set to reduce impact of a shift operation while shifting from “N” (“P”) to “D” (“R”) position.", "ptxt");
si[i++] = gsitm("N5040203G0002O00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0002O00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5040203G0002O00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0002O00ENG.html", "Controls for improvement of the transmission efficiency by engaging the torque converter clutch in the torque converter and eliminating slip of the converter. Achieves comfortable driving with slip control of the torque converter clutch.", "ptxt");
si[i++] = gsitm("N5040203G0002O00ENG.html", "The oil pressure feed circuit for the torque converter clutch piston chamber is connected to the torque converter clutch control valve. The torque converter clutch control valve is switched by the torque converter clutch solenoid valve with the signal from TCM. This controls the oil pressure circuit, which is supplied to the torque converter clutch piston chamber, to the release side or engagement side.", "ptxt");
si[i++] = gsitm("N5040203G0002O00ENG.html", "If the CVT fluid temperature is low or the vehicle is in fail-safe mode due to malfunction, lock-up control is prohibited.", "ptxt");
si[i++] = gsitm("N5040203G0002O00ENG.html", "Lock-up engagement", "title");
si[i++] = gsitm("N5040203G0002O00ENG.html", "In lock-up engagement, the torque converter clutch solenoid valve makes the torque converter clutch control valve locked up to generate the lock-up apply pressure. This pushes the torque converter clutch piston for engagement.", "ptxt");
si[i++] = gsitm("N5040203G0002O00ENG.html", "Lock-up release condition", "title");
si[i++] = gsitm("N5040203G0002O00ENG.html", "In lock-up release, the torque converter clutch solenoid valve makes the torque converter clutch control valve non-locked up to drain the lock-up apply pressure. This does not engage the torque converter clutch piston.", "ptxt");
si[i++] = gsitm("N5040203G0002P00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0002P00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0002P00ENG.html", "TCM controls shift characteristics of transaxle suitable for SPORT mode.", "ptxt");
si[i++] = gsitm("N5040203G0002P00ENG.html", "Control Details of Each Mode", "title");
si[i++] = gsitm("N5040203G0002P00ENG.html", "Control item", "ptxt");
si[i++] = gsitm("N5040203G0002P00ENG.html", "Control", "ptxt");
