si[i++] = gsitm("N504020110009400ENG.html", "Description", "title");
si[i++] = gsitm("N504020110009400ENG.html", "This is an on board diagnosis system which records diagnosis information related to the exhaust gases. It detects malfunctions related to sensors and actuators. The malfunctions are indicated by means of the malfunction indicator light (MIL) and are stored as DTC in the ECU memory. The diagnosis information can be checked using a diagnosis tool (M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N5040208E0000Q00ENG.html", "Function of OBD", "title");
si[i++] = gsitm("N5040208E0000Q00ENG.html", "The GST is connected to the data link connector on the vehicle and communicates with the on-board control units to perform diagnosis. The data link connector is the same as for M.U.T.-III SE. Refer to Description .", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "1 Trip Detection Diagnosis and 2 Trip Detection Diagnosis", "title");
si[i++] = gsitm("N5040208G0000F00ENG.html", "\"Start the engine and turn OFF the ignition switch after warm-up.\" This is defined as 1 trip.", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "1 TRIP DETECTION DIAGNOSIS", "title");
si[i++] = gsitm("N5040208G0000F00ENG.html", "When initial malfunction is detected, TCM memorizes DTC. In these diagnoses, some illuminate MIL and some do not. Refer to .", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "2 TRIP DETECTION DIAGNOSIS", "title");
si[i++] = gsitm("N5040208G0000F00ENG.html", "When initial malfunction is detected, TCM memorizes DTC of the 1st trip. MIL does not light at this stage. &lt;1 trip>", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "If the same malfunction is detected again in next driving, TCM memorizes DTC. When DTC is memorized, MIL lights. &lt;2 trip>", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "\"Trip\" of the \"2 trip detection diagnosis\" indicates the driving mode that executes self-diagnosis during driving.", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "DTC at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "MIL", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "Display at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "Display at the 2nd trip", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "Illumination at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "Illumination at the 2nd trip", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "1 trip detection diagnosis", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "(Refer to )", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "–", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5040208G0000F00ENG.html", "2 trip detection diagnosis", "ptxt");
si[i++] = gsitm("N5040208H0000D00ENG.html", "DTC and DTC of 1st Trip", "title");
si[i++] = gsitm("N5040208H0000D00ENG.html", "2 TRIP DETECTION DIAGNOSIS THAT ILLUMINATES MIL", "title");
si[i++] = gsitm("N5040208H0000D00ENG.html", "The DTC number of the 1st trip is the same as the DTC number.", "ptxt");
si[i++] = gsitm("N5040208H0000D00ENG.html", "When a malfunction is detected at the 1st trip, TCM memorizes DTC of the 1st trip. MIL does not light at this stage. If the same malfunction is not detected at the 2nd trip (conforming to necessary driving conditions), DTC at the 1st trip is erased from TCM. If the same malfunction is detected at the 2nd trip, TCM memorizes DTC and MIL lights at the same time.", "ptxt");
si[i++] = gsitm("N5040208H0000D00ENG.html", "The DTC of the 1st trip is specified in Service $07 of SAE J1979/ISO 15031-5. Since detection of DTC at the 1st trip does not illuminate MIL, warning for a problem is not given to a driver.", "ptxt");
si[i++] = gsitm("N5040208H0000D00ENG.html", "For procedure to delete DTC and 1st trip DTC from TCM, refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5040208H0000D00ENG.html", "If DTC of the 1st trip is detected, it is necessary to check the cause according to the “Diagnosis flow”. Refer to .", "ptxt");
si[i++] = gsitm("N5040208I0000D00ENG.html", "Malfunction Indicator Light (MIL)", "title");
si[i++] = gsitm("N5040208I0000D00ENG.html", "TCM not only detects DTC, but also sends the MIL signal to ECM through CAN communication. ECM sends the MIL signal to the combination meter through CAN communication according to the signal, and illuminates MIL.", "ptxt");
si[i++] = gsitm("N5040208I0000D00ENG.html", "For malfunction indicator light (MIL) description, refer to Malfunction Indicator Light (MIL) (FULL TFT METER) or Malfunction Indicator Light (MIL) (7 INCH INFORMATION DISPLAY).", "ptxt");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "Permanent Diagnostic Trouble Code", "title");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "Permanent DTC is defined in SAE J1979/ISO 15031-5 Service $0A.", "ptxt");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "TCM stores a DTC issuing a command of turning on MIL as a permanent DTC and keeps storing the DTC as a permanent DTC until TCM judges that there is no presence of malfunction.", "ptxt");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "Permanent DTCs cannot be erased by using the erase function of M.U.T.-III SE and by disconnecting the battery to shut off power to TCM. This prevents a vehicle from passing the in-use inspection without repairing a malfunctioning part.", "ptxt");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "When not passing the in-use inspection due to more than one permanent DTC, permanent DTCs should be erased, referring to this manual.", "ptxt");
si[i++] = gsitm("N5040208J0000Q00ENG.html", "Permanent DTCs never apply for regions that permanent DTCs are not regulated by law.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Counter System", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "RELATION BETWEEN DTC AT 1ST TRIP/DTC/MIL AND DRIVING CONDITIONS (FOR 2 TRIP DETECTION DIAGNOSIS THAT ILLUMINATES MIL)", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When initial malfunction is detected, TCM memorizes DTC of the 1st trip. MIL does not light at this stage.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "If the same malfunction is detected at the 2nd trip, TCM memorizes DTC and MIL lights at the same time.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Then, MIL goes off after driving the vehicle for 3 trips under “Driving condition B” without malfunction.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "DTC is displayed until 40 trips of “Driving condition A” are satisfied with no malfunction on \"Driving condition A\" after MIL lighting off. DTC is erased when 40 trips are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When the self-diagnosis result is acceptable at the 2nd trip (conforming to driving condition B), DTC of the 1st trip is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "COUNTER SYSTEM LIST", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition", "ptxt");
