si[i++] = gsitm("N5040208K0000D00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "DTC (clear)", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "40", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "DTC at 1st trip (clear)", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "1", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "DRIVING CONDITION", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition A", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition A is the driving condition that provides warm-up.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "In specific, count-up is performed when all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Engine speed is 400 rpm or more.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "After start of the engine, the water temperature increased by 20°C (36°F) or more.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Water temperature was 70°C (158°F) or more.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "The ignition switch was changed from ON to OFF.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "If the same malfunction is detected regardless of the driving condition, reset the A counter.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When the above is satisfied without detecting the same malfunction after turning off MIL, count up the A counter.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When MIL goes off due to the malfunction and the A counter reaches 40, the DTC is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition B", "title");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition B is different by each DTC.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Driving condition of count up for each DTC is as follows;", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "Diagnosis condition* and diagnosis delay time* for each DTC are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "While the above \"1\" condition is satisfied, threshold* for each DTC is not satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "*: For details of these, refer to DTC/CIRCUIT DIAGNOSIS >> DTC (Pxxxx or Uxxxx) >> DTC Description >> DTC DETECTION LOGIC.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "If the same malfunction is detected regardless of the driving condition, reset the B counter.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When the above is satisfied without detecting the same malfunction, count up the B counter.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When the B counter reaches 3 without malfunction, MIL goes off.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "When the B counter is counted once without detecting the same malfunction after TCM memorizes DTC of the 1st trip, DTC of the 1st trip is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000D00ENG.html", "TIME CHART", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "M.U.T.-III SE Function", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "After disconnecting the M.U.T.-III SE vehicle interface (VI) from the data link connector, the ignition must be cycled OFF → ON (for at least 5 seconds) → OFF. If this step is not performed, the BCM may not go to “sleep mode”, potentially causing a discharged battery and a no-start condition.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "APPLICABLE ITEM", "title");
