si[i++] = gsitm("N5040208L0001600ENG.html", "Special Function", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "Displays TCM part number", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "This mode enables a technician to adjust some devices faster and more accurately", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "CALIB DATA", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "The calibration data status of TCM can be checked", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "SELF DIAGNOSTIC RESULTS", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "DTC at 1st trip and method to read DTC", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "DTC (P0705, P0711, P0720, etc.) is specified by SAE J2012/ISO 15031-6.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "DTC and DTC at 1st trip are displayed on “Self Diagnostic results” of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "When DTC is currently detected, “Active DTC” is displayed. If “Stored DTC” is displayed, it shows a malfunction occurred in the past.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "When the DTC at the 1st trip is detected, “1t” is displayed.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "DTC deletion method", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "If the ignition switch is left ON after repair, turn OFF the ignition switch and wait for 10 seconds or more. Then, turn the ignition ON again. (Engine stop)", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "Touch “TRANSMISSION” of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "Touch “Self Diagnostic Result”.", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "Touch “Erase DTCs”. (DTC memorized in TCM is erased.)", "ptxt");
si[i++] = gsitm("N5040208L0001600ENG.html", "Freeze Frame Data (FFD)", "title");
si[i++] = gsitm("N5040208L0001600ENG.html", "The following vehicle status is recorded when DTC is detected and is displayed on M.U.T.-III SE.", "ptxt");
