si[i++] = gsitm("N504020110003T00ENG.html", "Description", "title");
si[i++] = gsitm("N504020110003T00ENG.html", "When replacing the TCM, always replace it with a new one. The functions controlled by the TCM does not operate properly in case of reuse of the TCM from another vehicle.", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "Always perform the following work when TCM is replaced. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "WORK BEFORE TCM REPLACEMENT", "title");
si[i++] = gsitm("N504020110003T00ENG.html", "Calibration data (IP characteristics value) saving", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. For this reason, it is necessary to save data of current TCM in M.U.T.-III SE before replacing the TCM. After this, the saved data must be written in new TCM.", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "WORK AFTER TCM REPLACEMENT", "title");
si[i++] = gsitm("N504020110003T00ENG.html", "TCM programming", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "Since vehicle specifications are not yet written in a new TCM, it is necessary to write them with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "MAC key writing", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "Calibration data (IP characteristics value) writing", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. The data stored in M.U.T.-III SE must be written in new TCM.", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "Clutch point learning", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "Select learning (Drive/Reverse learning)", "ptxt");
si[i++] = gsitm("N504020110003T00ENG.html", "G sensor calibration", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "When replacing TCM together with transaxle assembly, perform “ADDITIONAL SERVICE WHEN REPLACING TCM AND TRANSAXLE ASSEMBLY”. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Before starting, make sure:", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "ASIST on the M.U.T.-III SE has been synchronized to the current date.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "All M.U.T.-III SE software updates (if any) have been installed.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "SAVE CALIBRATION DATA (IP CHARACTERISTICS VALUE)", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Save necessary data stored in TCM in M.U.T.-III SE according to the following instructions:", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "The ignition switch is OFF and wait for 10 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "The ignition switch is ON.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Connect M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Select “Special Function” in “TRANSMISSION”.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Select “READ IP CHARA - REPLACEMENT TCM” of “IP characteristics data writing”.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Touch “OK”.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "When the calibration data has been saved to the M.U.T.-III SE, the message “Completed” will be displayed.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "REPLACE TCM", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "The ignition switch is OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Replace the TCM. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "PERFORM TCM PROGRAMMING", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Perform TCM programming according to the procedure of “Programming” in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Battery voltage: 12 – 13.5 V (Be sure to check the value of battery voltage by selecting “BATTERY VOLT” in “Data monitor” of M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "WRITE MAC KEY", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Perform MAC key writing, Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "In the case where the calibration data is successfully saved from the original TCM: GO TO 5.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "In the case where the calibration data cannot be saved from the original TCM and Is obtained from the DXA: GO TO 6.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "WRITE CALIBRATION DATA (IP CHARACTERISTICS VALUE) &lt;In the case where the calibration data is successfully saved from the original TCM>", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Write data saved in M.U.T.-III SE into a new TCM according to the following instructions:", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Verify vehicle is in “Park” (P), then the ignition switch is OFF and wait for 10 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Select “WRITE IP CHARA - REPLACEMENT TCM” of “IP characteristics data writing”.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "When the calibration data has been written to the TCM, the message “Completed” will be displayed.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "WRITE CALIBRATION DATA (IP CHARACTERISTICS VALUE) &lt;In the case where the calibration data cannot be saved from the original TCM and Is obtained from the DXA>", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Write data of new solenoid in TCM according to the following instructions:", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "The ignition switch is ON, engine OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Press the brake pedal.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Depress the throttle pedal half way and hold, then press “OK” on the M.U.T.-III SE screen.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Write data to the TCM according to the instructions on the M.U.T.-III SE screen.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "When the calibration data has been written to the TCM, the current status will indicate “Complete”.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "PERFORM G-SENSOR CALIBRATION", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Perform G-sensor Calibration. Refer to Description.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "PERFORM CLUTCH POINT LEARNING", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Perform Clutch Point Learning. Refer to Description.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "PERFORM SELECT LEARNING (DRIVE/REVERSE LEARNING)", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Always perform Clutch Point Learning before Select Learning.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Perform Select Learning. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Clear any DTCs that may have set and then test drive the vehicle.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Turn the ignition switch ON.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" of \"TRANSMISSION\".", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "Check item No. 1 \"Factory Mode OFF\", perform the following work by setting value. ON: Select \"OK\", change the setting value to \"OFF\".OFF: Work completed as no work is required.", "ptxt");
si[i++] = gsitm("N5040203R0007W00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "Description", "title");
si[i++] = gsitm("N504020110003U00ENG.html", "Perform the following work after the transaxle assembly is replaced. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "The CD provided with the new transaxle assembly contains important calibration data that must be installed with M.U.T.-III SE after installation of the new transaxle assembly. Never discard the CD.", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "WORK BEFORE TRANSAXLE ASSEMBLY REPLACEMENT", "title");
