si[i++] = gsitm("N504020110003U00ENG.html", "Calibration data (IP characteristics value) writing", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. For this reason, after replacing transaxle assembly, it is necessary to write new data in TCM.", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "Select learning (Drive/Reverse learning)", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "CVT fluid degradation level data erasing", "ptxt");
si[i++] = gsitm("N504020110003U00ENG.html", "TCM records the degradation level of the CVT fluid calculated from the vehicle driving status. Therefore, if the transaxle assembly is replaced, it is necessary to erase the CVT fluid degradation level data recorded by TCM.", "ptxt");
