si[i++] = gsitm("N5040201V0003Y00ENG.html", "CHECK SHIFT POSITION", "CHECKSHIFTPOSITION-3EA1BE9A");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "Check the following during engine running.", "ptxt");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the selector lever shifts to each position during depressing the brake pedal, the shift position normally changes.", "par2");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the brake pedal is not depressed at the P position, the shift position does not change even if the selector lever is operated.", "par3");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the P position switch is pressed and released at any shift position except the P position, the shift position changes into the P position.", "par4");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the selector lever shifts to the D position again at the D position, the shift position changes into the M mode.", "par5");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the selector lever shifts to the D position again at the M mode, the shift position changes into the D position.", "par6");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "When the ignition switch turns off, the shift position automatically changes into the P position. (The selector indicator light of the P position turns ON.)", "par7");
si[i++] = gsitm("N5040201V0003Y00ENG.html", "INSPECTION END", "ptxt");
