si[i++] = gsitm("N504020110004400ENG.html", "When a DTC is stored in TCM and MIL is ON, a permanent DTC is erased with MIL shutoff if the same malfunction is not detected after performing the driving pattern for MIL shutoff three times in a raw.", "ptxt");
