si[i++] = gsitm("N5040201C001XM00ENG.html", "DTC other than the applicable DTC is not detected.", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Engine speed: More than 625 rpm", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Shift position: Other than P/N position", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "CVT fluid temperature: More than -20°C (-4°F)", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "TCM power supply: More than 11 V", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "The difference between instruction pressure of secondary pressure and 10-msec-ago instruction secondary pressure is 0 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Instruction pressure of secondary pressure: 0 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Signal", "ptxt");
