si[i++] = gsitm("N5040201C001XM00ENG.html", "Threshold", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "When the following condition is satisfied and this state is maintained for 5.5 seconds:", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Actual secondary pressure - Instruction pressure of secondary pressure: 1.2 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "After the above condition \"1\" is satisfied:", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Diagnosis delay time", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "10 seconds", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "When the following condition \"a\" is satisfied twice in the same DC:", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "a. When all of the following condition a-1 to a-4 are satisfied and this state is maintained for 1.52 seconds:", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "a-1. Instruction pressure of secondary pressure - Actual secondary pressure: 0.25 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "a-2.Actual secondary pressure - low limit of oil level: Less than 0 MPa", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "a-3. Current accelerator pedal position - Accelerator pedal position when all conditions of the diagnosis condition and above condition a-1 to a-2 are met: Less than 5 deg", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "a-4: Current vehicle speed - Vehicle speed when all conditions of the diagnosis condition and above condition a-1 to a-2 are met: Less than 15 km/h (9 MPH)", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Instruction pressure of secondary pressure - Actual secondary pressure: 1.2 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "When all of the following condition b-1 to b-3 are satisfied and this state is maintained for 1 second:", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "b-1. Instruction pressure of secondary pressure - Actual secondary pressure: 0.25 MPa or more", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "b-2. Actual secondary pressure - low limit of oil level: Less than 0 MPa", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "b-3. MIN (Minimum necessary oil pressure - Actual secondary pressure, Target secondary pressure - Actual secondary pressure): 2 MPa or more", "ptxt");
