si[i++] = gsitm("N5040201C001XM00ENG.html", "Always drive vehicle at a safe speed.", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "The MIL is ON and ONLY DTC P0776–00 (PC SOLENOID B - Pressure Control Solenoid \"B\" Performance/Stuck OFF) is stored in the TCM.", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "If this issue should occur, the vehicle may hesitate and/or have a lack of power.", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "CHECK DTC PRIORITY", "title");
si[i++] = gsitm("N5040201C001XM00ENG.html", "When DTC P0776–00 is displayed together with P17F0–07, diagnose first the P17F0–07.", "ptxt");
si[i++] = gsitm("N5040201C001XM00ENG.html", "Is \"P17F0–07\" detected?", "question");
