si[i++] = gsitm("N5040201E0017600ENG.html", "REPLACE TRANSAXLE ASSEMBLY", "title");
si[i++] = gsitm("N5040201E0017600ENG.html", "Replace transaxle assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Component Inspection", "title");
si[i++] = gsitm("N5040200R0003S00ENG.html", "CVT BELT INSPECTION", "title");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Never allow any chemicals or fluids other than NS-3 CVT fluid or equivalent to enter the CVT assembly. Never allow any foreign debris, dust, dirt, etc. to enter the CVT assembly.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Before lifting the vehicle:", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Place the transmission gear selector in Neutral.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Leave the driver door unlatched.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Remove the control valve. Refer to .", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Secure the right front tire with a suitable strap . This will assist in making the belt turn.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Mark the left front tire with a suitable marking. This will ensure all 360° of the belt is inspected.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Using borescope (commercially-available tool) with mirror attachment, visually inspect the entirety of the two sides of the belt  that come in contact with the pulleys . Slowly and carefully turn the left front tire one full turn in the forward rotation to view all of the belt.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "CVT case", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Inspect these sides", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Never inspect these sides", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "If the tire is rotated in the rearward rotation, the camera lens may get caught between the belt and the pulley.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Be sure to remove the protective film from the mirror before the first use.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Clean the camera lens and mirror before each inspection. Use 90% isopropyl alcohol, and a lens swab from Lens Swab packet J-51963.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Before inspecting, make sure the camera handle’s AA batteries are fresh and the LCD monitor’s battery is charged.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Point the scope up and towards the rear of the vehicle.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "First inspect the entire 360° of the passenger side of the belt that comes in contact with the pulley. Refer to figures below for examples of normal and excessive wear patterns.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Belt", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Pulley", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Transaxle case", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Camera flexible tube", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", ": Front", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Insert the camera lens between the CVT case and the pulley.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Insert the lens approximately 7 inches, and then view the side of the belt that contacts the pulley.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Holding the borescope with one hand allows for turning the tire with the other hand.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "If the inspection result is OK on all 360° of the passenger side, inspect all 360° of the driver side of the belt. Refer to figures below for examples of normal and excessive wear patterns.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "BELT WEAR PATTERNS", "title");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Example of OK (normal) wear pattern.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Consistent parallel lines are present across the contact surfaces of each element.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Examples of NG (abnormal) wear patterns.", "ptxt");
si[i++] = gsitm("N5040200R0003S00ENG.html", "Contact surfaces of elements show visible scuffing, smeared or non-existent parallel lines, or damage.", "ptxt");
