si[i++] = gsitm("N5040201C001YM00ENG.html", "The counting of time continues while diagnosis conditions are satisfied and stops when the conditions become unsatisfied (the count is maintained). When accumulated time reaches 30 seconds (Clutch is judged as engaged and the count is reset.)", "ptxt");
