si[i++] = gsitm("N504020CN0000Y00ENG.html", "The CVT fluid is largely affected by temperature. Therefore be sure to use M.U.T.-III SE and check the “FLUID TEMP” under “TRANSMISSION” in “Data List” while adjusting.", "ptxt");
