si[i++] = gsitm("N504020CS0005V00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N504020CS0005V00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Never remove the radiator cap when the engine is hot. Serious burns could occur from high pressure engine coolant escaping from the radiator. Wrap a thick cloth around the cap. Slowly turn it a quarter turn to allow built-up pressure to escape. Carefully remove the cap by turning it all the way.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Perform this step when the engine is cold.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Drain engine coolant. Refer to .", "par11");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Remove engine under cover. Refer to .", "par16");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Remove clip of CVT water hose from bracket.", "par3");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Release hose clamps.", "par7");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Remove CVT water hose from CVT oil warmer and water pump housing.", "par4");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Remove battery tray. Refer to .", "par2");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Remove water control valve from CVT oil warmer and water outlet.", "par6");
si[i++] = gsitm("N504020CS0005V00ENG.html", "When disassembling water control valve, put matching marks on water control valve hoses, water control valve pipe, hose clamp and water control valve.", "par5");
si[i++] = gsitm("N504020CS0005V00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Note the following, and installation is in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Never reuse hose clamps. (When hose clamp is combined with CVT water hose, replace CVT water hose.)", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Hose clamp should not interfere with the spool or bulge.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "*Refer to the following when installing CVT water hose.", "ptxt");
si[i++] = gsitm("N504020CS0005V00ENG.html", "Water hose (1)", "ptxt");
