si[i++] = gsitm("N5040201V0004400ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040201V0004400ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040201V0004400ENG.html", "Water control valve", "title");
si[i++] = gsitm("N5040201V0004400ENG.html", "When coolant is cold, place dial gauge (A) on the pellet  of water control valve. And then measure elongation (M1) between the inlet of tube and the top of pellet.", "par9");
si[i++] = gsitm("N5040201V0004400ENG.html", "When elongation (M1) is 39 mm (1.54 in) or less, change the water control valve because malfunction of valve contract is expected.", "par10");
si[i++] = gsitm("N5040201V0004400ENG.html", "Fully immerse the water control valve  in a container (A). Continue heating the water while stirring.", "par11");
si[i++] = gsitm("N5040201V0004400ENG.html", "Continue heating water 5 minutes or more after bringing the water to a boil.", "par12");
si[i++] = gsitm("N5040201V0004400ENG.html", "Quickly take the water control valve out of the hot water, and measure within 10 seconds the elongation (M2) between the inlet of tube and the top of pellet after placing dial gauge (A) on the pellet .", "par13");
si[i++] = gsitm("N5040201V0004400ENG.html", "Carefully handle the hot water control valve to prevent from scalding.", "ptxt");
si[i++] = gsitm("N5040201V0004400ENG.html", "Lift amount of the pellet is calculated as the following formula; M1–M2=Lift amount", "par14");
si[i++] = gsitm("N5040201V0004400ENG.html", "Specified lift amount: Refer to  .", "par16");
si[i++] = gsitm("N5040201V0004400ENG.html", "When the lift amount is out of standard, replace the water control valve.", "par15");
si[i++] = gsitm("N5040201V0004400ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040201V0004400ENG.html", "Start the engine, and check the joints for coolant leakage. Refer to .", "ptxt");
