si[i++] = gsitm("N504020CS0005X00ENG.html", "Never remove the radiator cap when the engine is hot. Serious burns could occur from high pressure engine coolant escaping from the radiator. Wrap a thick cloth around the cap. Slowly turn it a quarter turn to allow built-up pressure to escape. Carefully remove the cap by turning it all the way.", "ptxt");
si[i++] = gsitm("N504020CS0005X00ENG.html", "Perform this step when the engine is cold.", "ptxt");
si[i++] = gsitm("N504020CS0005X00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N504020CS0005X00ENG.html", "Remove engine under cover. Refer to .", "par1");
si[i++] = gsitm("N504020CS0005X00ENG.html", "Drain engine coolant. Refer to .", "par5");
si[i++] = gsitm("N504020CS0005X00ENG.html", "Remove drain plug from oil pan and then drain the CVT fluid.", "par4");
si[i++] = gsitm("N504020CS0005X00ENG.html", "Remove CVT water hose, water control valve, CVT fluid cooler hose A and CVT fluid cooler hose B from CVT oil warmer. Refer to .", "par3");
