si[i++] = gsitm("N504020CS0006000ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N504020CS0006000ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N504020CS0006000ENG.html", "Never remove the radiator cap when the engine is hot. Serious burns could occur from high pressure engine coolant escaping from the radiator. Wrap a thick cloth around the cap. Slowly turn it a quarter turn to allow built-up pressure to escape. Carefully remove the cap by turning it all the way.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "Perform these steps after the coolant temperature has cooled sufficiently.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When replacing the transaxle, perform \"ADDITIONAL SERVICE WHEN REPLACING TRANSAXLE ASSEMBLY\". Refer to .", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When replacing TCM and transaxle assembly simultaneously, perform \"ADDITIONAL SERVICE WHEN REPLACING TCM AND TRANSAXLE ASSEMBLY\" before work. Refer to .", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "Remove the engine and transaxle assembly. Refer to .", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "Using paint, put matching marks on the drive plate and torque converter when removing the torque converter and drive plate fixing nuts.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N504020CS0006000ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "Write down the serial number of the new transaxle assembly.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When replacing an engine or transaxle you must make sure any dowels are installed correctly.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "During re-assembly improper alignment caused by missing dowels may cause vibration, oil leaks or breaking of drive train components.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "Never reuse O-ring or CVT fluid charging pipe cap.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When turning crankshaft, turn it clockwise as viewed from the front of the engine.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When tightening the nuts for the torque converter while securing the crankshaft pulley bolt, be sure to confirm the tightening torque of the crankshaft pulley bolt. Refer to .", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "After torque converter is installed to drive plate, rotate crankshaft several turns to check that CVT rotates freely without binding.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When installing the CVT to the engine, align the matching mark on the drive plate with the matching mark on the torque converter.", "ptxt");
si[i++] = gsitm("N504020CS0006000ENG.html", "When installing CVT assembly to the engine assembly, tighten the nut and bolts in the sequence shown.", "ptxt");
