si[i++] = gsitm("N504020740000S00ENG.html", "TCM", "title");
si[i++] = gsitm("N504020740000S00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020740000S00ENG.html", "TCM judges the vehicle driving status based on the signals from the sensors, switches, and other control units, and the optimal transaxle control is performed.", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020740000S00ENG.html", "The TCM consists of a microcomputer and connectors for signal input and output and for power supply.", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020740000S00ENG.html", "CVT control system. Refer to .", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "Line pressure control system. Refer to .", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "Shift control system. Refer to .", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "Select control system. Refer to .", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "Lock-up control system. Refer to .", "ptxt");
si[i++] = gsitm("N504020740000S00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020740000S00ENG.html", "The TCM is installed to the front side of transaxle case.", "ptxt");
si[i++] = gsitm("N504020750000O00ENG.html", "Transmission Range Switch", "title");
si[i++] = gsitm("N504020750000O00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020750000O00ENG.html", "The transmission range switch transfers CVT range position to TCM as voltage signal.", "ptxt");
si[i++] = gsitm("N504020750000O00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020750000O00ENG.html", "The transmission range switch judges the CVT range position.", "ptxt");
si[i++] = gsitm("N504020750000O00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020750000O00ENG.html", "Transmission range switch judges the CVT range position by contact point which is switched according to turn of manual shaft.", "ptxt");
si[i++] = gsitm("N504020750000O00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020750000O00ENG.html", "The transmission range switch  is installed to control valve.", "ptxt");
si[i++] = gsitm("N504020760000P00ENG.html", "Input Speed Sensor", "title");
si[i++] = gsitm("N504020760000P00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020760000P00ENG.html", "The input speed sensor transfers detected input shaft speed to TCM as pulse signal.", "ptxt");
si[i++] = gsitm("N504020760000P00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020760000P00ENG.html", "The input speed sensor detects input shaft speed.", "ptxt");
si[i++] = gsitm("N504020760000P00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020760000P00ENG.html", "The input speed sensor generates an ON-OFF pulse signal according to the rotating body speed.", "ptxt");
si[i++] = gsitm("N504020760000P00ENG.html", "TCM judges the rotating body speed based on the pulse signal.", "ptxt");
si[i++] = gsitm("N504020760000P00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020760000P00ENG.html", "The input speed sensor is installed to the front side of transaxle case.", "ptxt");
si[i++] = gsitm("N504020770000Q00ENG.html", "Primary Speed Sensor", "title");
si[i++] = gsitm("N504020770000Q00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020770000Q00ENG.html", "The primary speed sensor transfers detected primary pulley speed to TCM as pulse signal.", "ptxt");
si[i++] = gsitm("N504020770000Q00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020770000Q00ENG.html", "The primary speed sensor detects primary pulley speed.", "ptxt");
si[i++] = gsitm("N504020770000Q00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020770000Q00ENG.html", "The primary speed sensor generates an ON-OFF pulse signal according to the rotating body speed.", "ptxt");
si[i++] = gsitm("N504020770000Q00ENG.html", "TCM judges the rotating body speed based on the pulse signal.", "ptxt");
si[i++] = gsitm("N504020770000Q00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020770000Q00ENG.html", "The primary speed sensor is installed to transaxle side cover.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "Secondary Speed Sensor", "title");
si[i++] = gsitm("N504020DM0000A00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020DM0000A00ENG.html", "The secondary speed sensor transfers detected secondary pulley speed to TCM as pulse signal.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020DM0000A00ENG.html", "The secondary speed sensor detects idler gear speed and transfers speed signal to TCM.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "TCM calculates secondary pulley speed based on signal from secondary speed sensor.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020DM0000A00ENG.html", "The secondary speed sensor generates an ON-OFF pulse signal according to the rotating body speed.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "TCM judges the rotating body speed based on the pulse signal.", "ptxt");
si[i++] = gsitm("N504020DM0000A00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020DM0000A00ENG.html", "The secondary speed sensor is installed to rear side to transaxle case.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "CVT Fluid Temperature Sensor", "title");
si[i++] = gsitm("N504020790000O00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020790000O00ENG.html", "The CVT fluid temperature sensor transfers detected fluid temperature to TCM as signal voltage.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020790000O00ENG.html", "The CVT fluid temperature sensor detects CVT fluid temperature in oil pan.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020790000O00ENG.html", "The fluid temperature sensor uses a thermistor, and changes the voltage signal by converting changes in the CVT fluid temperature to a resistance value.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "The voltage signal value change must be in proportion to the resistance value change.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "TCM evaluates the CVT fluid temperature from the voltage signal value.", "ptxt");
si[i++] = gsitm("N504020790000O00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020790000O00ENG.html", "The CVT fluid temperature sensor  is installed to control valve.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "Line Pressure Sensor", "title");
si[i++] = gsitm("N504020DN0000700ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020DN0000700ENG.html", "The line pressure sensor transfers detected line pressure to TCM as voltage signal.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N504020DN0000700ENG.html", "The line pressure sensor detects line pressure.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020DN0000700ENG.html", "When pressure is applied to the ceramic device in the line pressure sensor, the ceramic device is deformed that produce voltage change.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "TCM evaluates the line pressure based on the voltage change.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "Voltage is increased along with pressure increase.", "ptxt");
si[i++] = gsitm("N504020DN0000700ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020DN0000700ENG.html", "The line pressure sensor  is installed to control valve.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "Primary Pressure Sensor", "title");
si[i++] = gsitm("N5040207A0000P00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5040207A0000P00ENG.html", "The primary pressure sensor transfers detected primary pressure to TCM as voltage signal.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "INDIVIDUAL FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5040207A0000P00ENG.html", "The primary pressure sensor detects pressure applied to the primary pulley.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5040207A0000P00ENG.html", "When pressure is applied to the ceramic device in the primary pressure sensor, the ceramic device is deformed that produce voltage change.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "TCM evaluates the primary pressure based on the voltage change.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "Voltage is increased along with pressure increase.", "ptxt");
si[i++] = gsitm("N5040207A0000P00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5040207A0000P00ENG.html", "The primary pressure sensor  is installed to control valve.", "ptxt");
