si[i++] = gsitm("N5040207K0000O00ENG.html", "Nr", "ptxt");
si[i++] = gsitm("N5040207K0000O00ENG.html", "When shift position is D or M, while depressing the brake pedal, shift the selector lever to the Nr position and hold it for approx. 0.5 second. The shift position changes to N.", "ptxt");
