si[i++] = gsitm("N5040207O0000Q00ENG.html", "The electric shift control module controls the timing of the current feed to the coils optimally based on the signal from the encoder.", "ptxt");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "Actuator Reduction Gear", "ptxt");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "The actuator reduction gear consists of a cycloidal gear and includes a motor with its torque amplified for secure operation under high torque-requiring conditions.", "ptxt");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "The shift actuator moves the manual shaft of transaxle and changes shift position.", "ptxt");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5040207O0000Q00ENG.html", "The shift actuator  is installed above the transaxle.", "ptxt");
si[i++] = gsitm("N504020KW0000500ENG.html", "Shift Actuator Relay", "title");
si[i++] = gsitm("N504020KW0000500ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020KW0000500ENG.html", "The shift actuator relay A supply power to the motor coil A of shift actuator. Electric shift control module activates the shift actuator relay A to supply power to the motor coil A of shift actuator when the ignition switch is turned ON.", "ptxt");
si[i++] = gsitm("N504020KW0000500ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N504020KW0000500ENG.html", "The shift actuator relay A connect and disconnects of the power supply circuit by ON / OFF of the relay switch.", "ptxt");
si[i++] = gsitm("N504020KW0000500ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N504020KW0000500ENG.html", "The relays used in the shift actuator relay are normal open relays.", "ptxt");
si[i++] = gsitm("N504020KW0000500ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N504020KW0000500ENG.html", "The shift actuator relay A is installed in the left side of engine room.", "ptxt");
