si[i++] = gsitm("N5040207S0000O00ENG.html", "Final gear", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Reduction gear", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Idler gear", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Output gear", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Drive sprocket", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Torque converter", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Driven sprocket", "ptxt");
si[i++] = gsitm("N5040207S0000O00ENG.html", "Oil pump chain", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Transaxle Mechanism", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "TORQUE CONVERTER (WITH LOCK-UP FUNCTION)", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "The torque converter increases the engine torque and transmits it to the power train. \"Symmetrical 3-elements 1-stage 2-phases type torque converter\" has been adopted.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "MECHANICAL OIL PUMP", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "The CVT adopts vane type oil pump which is driven by the engine via oil pump drive chain and sprockets, and this enables high efficiency at a low speed, and optimizes the pump output at a high speed. The oil pump discharged oil flows to the control valve and is used for the working fluid for the primary and secondary pulley, the clutch/brake and for lubrication.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "ELECTRIC OIL PUMP", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "The CVT adopts vane type oil pump which is driven by electric motor. This oil pump has two functions below.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Assist oil pressure from mechanical oil pump.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Generate oil pressure when mechanical oil pump is not operating.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "PLANETARY GEAR", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "A planetary gear set is located between the torque converter and the primary pulley.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "The torque converter transmits power to the input shaft and two multi-plate clutches enable to switch between forward and reverse.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Operation of Planetary gear", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "BELT & PULLEY", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "It is composed of a pair of pulleys (the groove width is changed freely in the axial direction) and the chain belt .The groove width changes according to wrapping radius of chain belt and pulley from low status to overdrive status continuously with non-step. It is controlled with the oil pressures of primary pulley and secondary pulley.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Chain belt", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "It consists of a large number of locker pins  and plate . The feature of this chain belt is to transmit power by means of pulling belt. The locker pins require a friction force with the pulley sheave to transmit driving force.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Pulley", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "Both the primary and secondary pulleys consist of the fixed and the movable sheaves. Each pulley has a hydraulic chamber (the primary or secondary chamber) behind the movable sheave. The movable pulley can slide along the axis to change the groove of the pulley. The groove width of the pulley is controlled by changing the operating pressure at the primary and secondary pulleys in response to the engine load (acceleration angle), primary and secondary pulley speed.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "FINAL DRIVE AND DIFFERENTIAL", "title");
si[i++] = gsitm("N5040207T0000P00ENG.html", "It has two reduction gear sets. The primary reduction is composed of the output gear and the idler gear. The secondary reduction is composed of the reduction gear and the final gear.", "ptxt");
si[i++] = gsitm("N5040207T0000P00ENG.html", "All gears are lubricated with CVT fluid (MITSUBISHI MOTORS GENUINE CVTF-J4 or MITSUBISHI MOTORS GENUINE CVTF-J4+) that is used for the working fluid.", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Operation Status", "title");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Shift position", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Parking mechanism", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Forward clutch", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Reverse brake", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Primary pulley", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Secondary pulley", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Chain belt", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "Final drive", "ptxt");
