si[i++] = gsitm("N5040207U0000O00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "R", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "N", "ptxt");
si[i++] = gsitm("N5040207U0000O00ENG.html", "D/M", "ptxt");
si[i++] = gsitm("N5040207V0000O00ENG.html", "Oil Pressure System", "title");
si[i++] = gsitm("N5040207V0000O00ENG.html", "Oil pressure required for operation of the transaxle transmission mechanism is generated by mechanical oil pump, electric oil  pump, oil pressure control valve, solenoid valve, etc.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Component Description", "title");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Part name", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Torque converter", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Increases engine torque and transmits it to the transaxle.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Mechanical oil pump", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Utilizes a vane-type oil pump that is driven by the engine through the oil pump drive chain in order to increase efficiency of pump discharge volume in low-speed zone and optimize pump discharge volume in high-speed zone. Discharged oil from oil pump is transmitted to control valve. It is used as the oil of primary and secondary pulley operation, the oil of clutch operation, and the lubricant for each part.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Electric oil pump", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Utilizes a vane-type oil pump that is driven by electric energy in order to increase efficiency of pump discharge volume. This part has two functions as below.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Assist mechanical oil pump.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Generate oil pressure with control valve and solenoid valve  ,in situation which mechanical oil pump does not operate.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Forward clutch", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "The forward clutch is wet and multiple plate type clutch that consists of clutch drum, piston, drive plate, and driven plate. It is a clutch to move the vehicle forward by activating piston hydraulically, engaging plates, and directly connecting sun gear and input shaft.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reverse brake", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "The reverse brake is a wet multiple-plate type brake that consists of transaxle case, piston, drive plate, and driven plate. It is a brake to move the vehicle in reverse by activating piston hydraulically, engaging plates, and fixing planetary gear.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Internal gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "The internal gear is directly connected to forward clutch drum. It is a gear that moves the outer edge of pinion planet of planet carrier. It transmits power to move the vehicle in reverse when the planet carrier is fixed.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Planet carrier", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Composed of a carrier, pinion planet, and pinion shaft. This gear fixes and releases the planet carrier in order to switch between forward and reverse driving.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Sun gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Sun gear is a set part with planet carrier and internal gear. It transmits transmitted force to primary fixed sheave. It rotates in forward or reverse direction according to activation of either forward clutch or reverse brake.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Input shaft", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "The input shaft is directly connected to forward clutch drum and transmits traction force from torque converter. In shaft center, there are holes for hydraulic distribution to primary pulley and hydraulic distribution for lockup ON/OFF.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Primary pulley", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "It is composed of a pair of pulleys (the groove width is changed freely in the axial direction) and the chain belt. The groove width changes according to wrapping radius of chain belt and pulley from low status to overdrive status continuously with non-step. It is controlled with the oil pressures of primary pulley and secondary pulley.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Secondary pulley", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Chain belt", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Manual shaft", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "When the manual shaft is in the P position, the parking rod that is linked to the manual shaft rotates the parking pole. When the parking pole rotates, it engages with the parking gear, fixing the parking gear. As a result, the secondary pulley that is integrated with the parking gear is fixed.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Parking rod", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Parking pawl", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Parking gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Output gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "The deceleration gears are composed of 2 stages: primary deceleration (output gear, idler gear pair) and secondary deceleration (reduction gear, final gear pair). All of these gears are helical gears.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Idler gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduction gear", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Differential", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Torque converter clutch regulator valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Adjusts the feed pressure to the torque converter to the optimum pressure corresponding to the driving condition.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Pressure regulator valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Adjusts the discharge pressure from the oil pump to the optimum pressure (line pressure) corresponding to the driving condition.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Torque converter clutch control valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Adjusts the torque converter engage and disengage pressures.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Manual valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Distributes the clutch operation pressure to each circuit according to the shift position.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Secondary reducing valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces line pressure and adjusts secondary pressure.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Primary reducing valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces line pressure and adjusts primary pressure.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Pilot valve A", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces line pressure and adjusts pilot pressure to the solenoid valves listed below.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Primary pressure solenoid valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Secondary pressure solenoid valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Select solenoid valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Line pressure solenoid valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Pilot valve B", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces pilot pressure and adjusts pilot pressure to the torque converter clutch solenoid valve.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces pilot A pressure and adjusts solenoid pressure.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Torque converter clutch solenoid valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Reduces pilot B pressure and adjusts solenoid pressure.", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Torque converter lubrication valve", "ptxt");
si[i++] = gsitm("N5040200P0000O00ENG.html", "Switch lubrication circuit and supply lubrication flow to lubrication & cooling system.", "ptxt");
si[i++] = gsitm("N5040203G0005E00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0005E00ENG.html", "CVT FLUID COOLER SCHEMATIC", "title");
si[i++] = gsitm("N5040203G0005E00ENG.html", "COMPONENT DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0005E00ENG.html", "CVT Oil Warmer", "title");
si[i++] = gsitm("N5040203G0005E00ENG.html", "The CVT oil warmer  is installed on the front part of transaxle assembly.", "ptxt");
si[i++] = gsitm("N5040203G0005E00ENG.html", "When engine is started while engine and CVT are cold, engine coolant temperature rises more quickly than CVT fluid temperature. CVT oil warmer is provided with two circuits for CVT and engine coolant respectively so that warmed engine coolant warms CVT quickly. This helps shorten CVT warming up time, improving fuel economy.", "ptxt");
si[i++] = gsitm("N5040203G0005E00ENG.html", "A cooling effect is obtained when CVT fluid temperature is high.", "ptxt");
