si[i++] = gsitm("N5040203G0005L00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0005L00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5040203G0005L00ENG.html", "TCM controls shift characteristics of transaxle suitable for SPORT mode.", "ptxt");
si[i++] = gsitm("N5040203G0005L00ENG.html", "Control Details of Each Mode", "title");
si[i++] = gsitm("N5040203G0005L00ENG.html", "Control item", "ptxt");
si[i++] = gsitm("N5040203G0005L00ENG.html", "Control", "ptxt");
si[i++] = gsitm("N5040203G0005L00ENG.html", "SPORT mode", "ptxt");
si[i++] = gsitm("N5040203G0005L00ENG.html", "This mode uses a shift schedule that mainly utilizes the high engine speed zone and improves the driving control characteristic and response. This assists driving that is similar to driving a sports car.", "ptxt");
si[i++] = gsitm("N5040203G0005M00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040203G0005M00ENG.html", "The electric shift system detects each shift position electrically. In addition, in P position, the electric shift system activates the shift actuator, according to electrical signals received from the P position switch and brings the vehicle into the parking state.", "ptxt");
si[i++] = gsitm("N5040203G0005M00ENG.html", "In the event of a malfunction in the electric shift system, the selector indicator of electric shift selector turns OFF and only the shift indicator (on the combination meter) indicates the shift position.", "ptxt");
si[i++] = gsitm("N5040203G0005M00ENG.html", "In the event of a malfunction in the electric shift system, the system enters fail-safe mode. Refer to .", "ptxt");
