si[i++] = gsitm("N5040207X0002K00ENG.html", "Protection Control", "title");
si[i++] = gsitm("N5040207X0002K00ENG.html", "If shifting to P/R/N/D position is repeated within a short period of time, it may become impossible to shift for system protection. In this case, the system automatically returns to the normal state allowing shifting after approximately 20 seconds.", "ptxt");
si[i++] = gsitm("N504020850000O00ENG.html", "CVT System Warning", "title");
