si[i++] = gsitm("N504020850000O00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N504020850000O00ENG.html", "The TCM judges and decides condition of CVT system/function, according to signals received from each sensor/switch, each actuator, and Electric shift control module.", "ptxt");
si[i++] = gsitm("N504020850000O00ENG.html", "When the displaying conditions of the CVT system warning are satisfied, TCM transmits a CVT warning message signal to the combination meter via CAN  communication.", "ptxt");
si[i++] = gsitm("N504020850000O00ENG.html", "The combination meter displays CVT system warning, according to the CVT warning message signal.", "ptxt");
