si[i++] = gsitm("N504020860000N00ENG.html", "The shift position indicator displays the shift position of transaxle.", "ptxt");
si[i++] = gsitm("N504020860000N00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N504020860000N00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N504020860000N00ENG.html", "The TCM judges the shift position by the transmission range switch, electric shift selector signal, and paddle shifter upshift/downshift signal.", "ptxt");
si[i++] = gsitm("N504020860000N00ENG.html", "The TCM transmits the shift position signal to the combination meter via CAN communication. The combination meter shows the shift position indicator on the information display, according to the signal.", "ptxt");
si[i++] = gsitm("N504020870000M00ENG.html", "Neutral Hold Mode Indicator", "title");
