si[i++] = gsitm("N504020870000M00ENG.html", "Neutral Hold Mode Guidance Indicator", "title");
si[i++] = gsitm("N504020870000M00ENG.html", "This indicator displays when the ignition switch is OFF while the shift position is in the \"N\" (Neutral) position (Neutral hold mode is available).", "ptxt");
si[i++] = gsitm("N504020870000M00ENG.html", "Neutral Hold Mode Activated Indicator", "title");
si[i++] = gsitm("N504020870000M00ENG.html", "This indicator displays when the neutral hold mode is activated. To exit the neutral hold mode, place the vehicle in other than \"N\" (Neutral) position.", "ptxt");
si[i++] = gsitm("N504020870000M00ENG.html", "Neutral Hold Mode Was Not Activated Indicator", "title");
si[i++] = gsitm("N504020870000M00ENG.html", "This indicator displays when the neutral hold mode is unavailable. To activate the neutral hold mode, wait for a while without shifting and then perform the operations again.", "ptxt");
si[i++] = gsitm("N504020880000O00ENG.html", "Electric Shift Warning", "title");
