si[i++] = gsitm("N504020880000O00ENG.html", "The electric shift control module transmits an electric shift malfunction signal to the TCM when detecting a malfunction in the electric shift system.", "ptxt");
si[i++] = gsitm("N504020880000O00ENG.html", "TCM detects DTC when TCM receives an electric shift malfunction signal.", "ptxt");
si[i++] = gsitm("N504020880000O00ENG.html", "TCM transmits an electric shift warning message signal to the combination meter when detecting DTC in TCM.", "ptxt");
si[i++] = gsitm("N504020880000O00ENG.html", "The combination meter displays the each message according to the electric shift warning message signal.", "ptxt");
