si[i++] = gsitm("N504020890000O00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N504020890000O00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N504020890000O00ENG.html", "TCM judges the shift position by the transmission range switch.", "ptxt");
si[i++] = gsitm("N504020890000O00ENG.html", "BCM transmits a door switch signal to the TCM.", "ptxt");
si[i++] = gsitm("N504020890000O00ENG.html", "The TCM judges the vehicle condition according to the shift position signal and the door switch signal. The TCM transmits a shift P range request display signal to the combination meter if the driver\'s door is opened with the shift position not in P position.", "ptxt");
si[i++] = gsitm("N504020890000O00ENG.html", "WARNING/INDICATOR OPERATING CONDITION", "title");
