si[i++] = gsitm("N50402011000D400ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D400ENG.html", "This is an on board diagnosis system which records diagnosis information related to the exhaust gases. It detects malfunctions related to sensors and actuators. The malfunctions are indicated by means of the malfunction indicator light (MIL) and are stored as DTC in the ECU memory. The diagnosis information can be checked using a diagnosis tool (GST: Generic M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N5040208E0000P00ENG.html", "Function of OBD", "title");
si[i++] = gsitm("N5040208E0000P00ENG.html", "The GST is connected to the diagnosis connector on the vehicle and communicates with the on-board control units to perform diagnosis. The diagnosis connector is the same as for M.U.T.-III SE. Refer to Description .", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "1 Trip Detection Diagnosis and 2 Trip Detection Diagnosis", "title");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "“Start the engine and turn OFF the ignition switch after warm-up.” This is defined as 1 trip.", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "1 TRIP DETECTION DIAGNOSIS", "title");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "When initial malfunction is detected, TCM memorizes DTC. In these diagnoses, some illuminate MIL and some do not. Refer to .", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "2 TRIP DETECTION DIAGNOSIS", "title");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "When initial malfunction is detected, TCM memorizes DTC of the 1st trip. MIL does not light at this stage. &lt;1 trip>", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "If the same malfunction is detected again in next driving, TCM memorizes DTC. When DTC is memorized, MIL lights. &lt;2 trip>", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "“Trip” of the “2 trip detection diagnosis” indicates the driving mode that executes self-diagnosis during driving.", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "DTC at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "MIL", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "Display at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "Display at the 2nd trip", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "Illumination at the 1st trip", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "Illumination at the 2nd trip", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "1 trip detection diagnosis", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "(Refer to )", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "—", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5040208G0000Q00ENG.html", "2 trip detection diagnosis", "ptxt");
si[i++] = gsitm("N5040208H0000P00ENG.html", "DTC and DTC of 1st Trip", "title");
si[i++] = gsitm("N5040208H0000P00ENG.html", "2 TRIP DETECTION DIAGNOSIS THAT ILLUMINATES MIL", "title");
si[i++] = gsitm("N5040208H0000P00ENG.html", "The DTC number of the 1st trip is the same as the DTC number.", "ptxt");
si[i++] = gsitm("N5040208H0000P00ENG.html", "When a malfunction is detected at the 1st trip, TCM memorizes DTC of the 1st trip. MIL does not light at this stage. If the same malfunction is not detected at the 2nd trip (conforming to necessary driving conditions), DTC at the 1st trip is erased from TCM. If the same malfunction is detected at the 2nd trip, TCM memorizes DTC and MIL lights at the same time.", "ptxt");
si[i++] = gsitm("N5040208H0000P00ENG.html", "The DTC of the 1st trip is specified in Service $07 of SAE J1979/ISO 15031-5. Since detection of DTC at the 1st trip does not illuminate MIL, warning for a problem is not given to a driver.", "ptxt");
si[i++] = gsitm("N5040208H0000P00ENG.html", "For procedure to delete DTC and 1st trip DTC from TCM, refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5040208H0000P00ENG.html", "If DTC of the 1st trip is detected, it is necessary to check the cause according to the “Diagnosis flow”. Refer to .", "ptxt");
si[i++] = gsitm("N5040208I0000P00ENG.html", "Malfunction Indicator Light (MIL)", "title");
si[i++] = gsitm("N5040208I0000P00ENG.html", "TCM not only detects DTC, but also sends the MIL signal to ECM through CAN communication. ECM sends the MIL signal to the combination meter through CAN communication according to the signal, and illuminates MIL.", "ptxt");
si[i++] = gsitm("N5040208I0000P00ENG.html", "For malfunction indicator light (MIL) description, refer to Malfunction Indicator Light (MIL) (FULL TFT METER) or Malfunction Indicator Light (MIL) (7 INCH INFORMATION DISPLAY).", "ptxt");
si[i++] = gsitm("N5040208J0000O00ENG.html", "Permanent Diagnostic Trouble Code", "title");
si[i++] = gsitm("N5040208J0000O00ENG.html", "Permanent DTC is defined in SAE J1979/ISO 15031-5 Service $0A.", "ptxt");
si[i++] = gsitm("N5040208J0000O00ENG.html", "TCM stores a DTC issuing a command of turning on MIL as a permanent DTC and keeps storing the DTC as a permanent DTC until TCM judges that there is no presence of malfunction.", "ptxt");
si[i++] = gsitm("N5040208J0000O00ENG.html", "Permanent DTCs cannot be erased by using the erase function of M.U.T.-III SE and by disconnecting the battery to shut off power to TCM. This prevents a vehicle from passing the in-use inspection without repairing a malfunctioning part.", "ptxt");
si[i++] = gsitm("N5040208J0000O00ENG.html", "When not passing the in-use inspection due to more than one permanent DTC, permanent DTCs should be erased, referring to this manual.", "ptxt");
si[i++] = gsitm("N5040208J0000O00ENG.html", "Permanent DTCs never apply for regions that permanent DTCs are not regulated by law.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Counter System", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "RELATION BETWEEN DTC AT 1ST TRIP/DTC/MIL AND DRIVING CONDITIONS (FOR 2 TRIP DETECTION DIAGNOSIS THAT ILLUMINATES MIL)", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When initial malfunction is detected, TCM memorizes DTC of the 1st trip. MIL does not light at this stage.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "If the same malfunction is detected at the 2nd trip, TCM memorizes DTC and MIL lights at the same time.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Then, MIL goes off after driving the vehicle for 3 trips under “Driving condition B” without malfunction.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "DTC is displayed until 40 trips of “Driving condition A” are satisfied with no malfunction on \"Driving condition A\" after MIL lighting off. DTC is erased when 40 trips are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When the self-diagnosis result is acceptable at the 2nd trip (conforming to driving condition B), DTC of the 1st trip is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "COUNTER SYSTEM LIST", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Trip", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "MIL (OFF)", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "DTC (clear)", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "40", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "DTC at 1st trip (clear)", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "1", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "DRIVING CONDITION", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition A", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition A is the driving condition that provides warm-up.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "In specific, count-up is performed when all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Engine speed is 400 rpm or more.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "After start of the engine, the water temperature increased by 20°C (36°F) or more.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Water temperature was 70°C (158°F) or more.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "The ignition switch was changed from ON to OFF.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "If the same malfunction is detected regardless of the driving condition, reset the A counter.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When the above is satisfied without detecting the same malfunction after turning off MIL, count up the A counter.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When MIL goes off due to the malfunction and the A counter reaches 40, the DTC is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition B", "title");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition B is different by each DTC.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Driving condition of count up for each DTC is as follows;", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "Diagnosis condition* and diagnosis delay time* for each DTC are satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "While the above \"1\" condition is satisfied, threshold* for each DTC is not satisfied.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "*: For details of these, refer to DTC/CIRCUIT DIAGNOSIS >> DTC (Pxxxx or Uxxxx) >> DTC Description >> DTC DETECTION LOGIC.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "If the same malfunction is detected regardless of the driving condition, reset the B counter.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When the above is satisfied without detecting the same malfunction, count up the B counter.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When the B counter reaches 3 without malfunction, MIL goes off.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "When the B counter is counted once without detecting the same malfunction after TCM memorizes DTC of the 1st trip, DTC of the 1st trip is erased.", "ptxt");
si[i++] = gsitm("N5040208K0000O00ENG.html", "TIME CHART", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "M.U.T.-III SE Function", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "After disconnecting the M.U.T.-III SE vehicle interface (VI) from the diagnosis connector, the ignition must be cycled OFF → ON (for at least 5 seconds) → OFF. If this step is not performed, the BCM may not go to \"sleep mode\", potentially causing a discharged battery and a no-start condition.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "APPLICABLE ITEM", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Diagnosis mode", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Self Diagnostic Result", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Display DTC which TCM memorizes", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Data List", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Displays TCM input/output data in real time", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Special Function", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Displays TCM part number", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "This mode enables a technician to adjust some devices faster and more accurately", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "CALIB DATA", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "The calibration data status of TCM can be checked", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "SELF DIAGNOSIS", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "DTC at 1st trip and method to read DTC", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "DTC (P0705, P0711, P0715, etc.) is specified by SAE J2012/ISO 15031-6.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "DTC and DTC at 1st trip are displayed on \"Self Diagnostic results\" of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "When DTC is currently detected, \"Active DTC\" is displayed. If \"Stored DTC\" is displayed, it shows a malfunction occurred in the past. The trip number of drive without malfunction of concerned DTC can be confirmed with \"IGN counter\" inside \"FFD\".", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "When the DTC at the 1st trip is detected, \"1t\" is displayed.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "DTC deletion method", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "If the ignition switch is left ON after repair, turn OFF the ignition switch and wait for 10 seconds or more. Then, turn the ignition ON again. (Engine stop)", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Touch \"TRANSMISSION\" of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Touch \"Self Diagnostic Result\".", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Touch \"Erase\". (DTC memorized in TCM is erased.)", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "IGN counter", "title");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "The ignition counter is displayed in \"FFD\" and the number of times of satisfied \"Driving condition A\" is displayed after normal recovery of DTC. Refer to .", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "If malfunction (DTC) is currently detected, \"0\" is displayed.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "After normal recovery, every time \"Driving condition A” is satisfied, the display value increases from 1 → 2 → 3...38 → 39.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "When MIL turns OFF due to the malfunction and the counter reaches 40, the DTC is erased.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "The counter display of \"40” cannot be checked.", "ptxt");
si[i++] = gsitm("N504020FZ0000E00ENG.html", "Freeze Frame Data (FFD)", "title");
