si[i++] = gsitm("N504020FZ0000F00ENG.html", "When DTC is currently detected, \"Active DTC\" is displayed. If \"Stored DTC\" is displayed, it shows a malfunction occurred in the past. The trip number of drive without malfunction of concerned DTC can be confirmed with \"IGN counter\" inside \"FFD\".", "ptxt");
