si[i++] = gsitm("N5040203P0000U00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "\"DTC\" includes DTC at the 1st trip.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "OBTAIN INFORMATION ABOUT SYMPTOM", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Refer to  and interview the customer to obtain the malfunction information (conditions and environment when the malfunction occurred) as much as possible when the customer brings in the vehicle.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Before checking the malfunction, check whether any DTC exists.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "If DTC exists, perform the following operations.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Records the DTCs. (Print out using M.U.T.-III SE and affix to the Work Order Sheet.)", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Erase DTCs.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Check the relation between the cause found by DTC and the malfunction information from customer.  can be used effectively.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Check the relevant information including STI, etc.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Do malfunction information and DTC exist?", "question");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Malfunction information and DTC exist.", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Malfunction information exists but no DTC.", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "No malfunction information, but DTC exists.", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "REPRODUCE MALFUNCTION SYSTEM", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Check the malfunction described by the customer on the vehicle.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Check if the behavior is fail safe or normal operation. Refer to  (TCM) or Fail-safe (ELECTRIC SHIFT CONTROL MODULE).", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Interview sheet can be used effectively when reproduce malfunction conditions. Refer to .", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Verify the relationship between the symptom and the conditions in which the malfunction described by the customer occurs.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "REPRODUCE MALFUNCTION SYMPTOM", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "PERFORM \"DTC CONFIRMATION PROCEDURE\"", "PERFORMDTCCONFIRMATIONPROCEDURE-F9066D8D");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Perform \"DTC CONFIRMATION PROCEDURE\" of the appropriate DTC to check if DTC is detected again.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Refer to  (TCM) or  (ELECTRIC SHIFT CONTROL MODULE) when multiple DTCs are detected, and then determine the order for performing the diagnosis.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N5040203P0000U00ENG.html", "YES", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "NO", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Follow Intermittent Incident to check.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "IDENTIFY MALFUNCTIONING SYSTEM WITH \"DIAGNOSIS CHART BY SYMPTOM\"", "IDENTIFYMALFUNCTIONINGSYSTEMWITHDIA-F9060378");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Use  from the symptom inspection result in step 4. Then identify where to start performing the diagnosis based on possible causes and symptoms.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PARTS", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Repair or replace the detected malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Reconnect parts or connector after repairing or replacing, and then erase DTC if necessary.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Perform \"DTC CONFIRMATION PROCEDURE\" again to make sure that the repair is correctly performed.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Check that malfunctions are not reproduced when obtaining the malfunction information from the customer, referring to the symptom inspection result in step 3 or 4.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Is DTC or malfunction symptom reproduced?", "question");
si[i++] = gsitm("N5040203P0000U00ENG.html", "YES-1", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "DTC is reproduced : GO TO 5.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "YES-2", "result");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Malfunction is reproduced : GO TO 6.", "ptxt");
si[i++] = gsitm("N5040203P0000U00ENG.html", "Before delivering the vehicle to the customer, make sure that DTC is erased.", "ptxt");
si[i++] = gsitm("N504020190000R00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N504020190000R00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N504020190000R00ENG.html", "There are many operating conditions that may cause a malfunction of the transmission parts. By understanding those conditions properly, a quick and exact diagnosis can be achieved.", "ptxt");
si[i++] = gsitm("N504020190000R00ENG.html", "In general, perception of a problem varies depending on individuals. Ask the customer about his/her concerns carefully. It is important to understand the phenomenon or status. To systemize all the information for the diagnosis, prepare the question sheet referring to the question points.", "ptxt");
si[i++] = gsitm("N504020190000R00ENG.html", "In some cases, multiple conditions that appear simultaneously may cause a DTC to be detected.", "ptxt");
si[i++] = gsitm("N504020190000R00ENG.html", "Worksheet Sample", "title");
