si[i++] = gsitm("N50402011000D500ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D500ENG.html", "When replacing the TCM, always replace it with a new one. The functions controlled by the TCM does not operate properly in case of reuse of the TCM from another vehicle.", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "Always perform the following work when TCM is replaced. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "WORK BEFORE TCM REPLACEMENT", "title");
si[i++] = gsitm("N50402011000D500ENG.html", "Calibration data (IP characteristics value) saving", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. For this reason, it is necessary to save data of current TCM in M.U.T.-III SE before replacing the TCM. After this, the saved data must be written in new TCM.", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "WORK AFTER TCM REPLACEMENT", "title");
si[i++] = gsitm("N50402011000D500ENG.html", "TCM programming", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "Since vehicle specifications are not yet written in a new TCM, it is necessary to write them with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "MAC key writing", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "Calibration data (IP characteristics value) writing", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. The data stored in M.U.T.-III SE must be written in new TCM.", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "Torque converter clutch point learning", "ptxt");
si[i++] = gsitm("N50402011000D500ENG.html", "Select learning (Drive/Reverse learning)", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Before starting, make sure:", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "All M.U.T.-III SE software updates (if any) have been installed.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "SAVE CALIBRATION DATA (IP CHARACTERISTICS VALUE)", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Save necessary data stored in TCM in M.U.T.-III SE according to the following instructions:", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Ignition switch OFF and wait for 10 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Connect M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Select \"Special Function\" in \"TRANSMISSION\".", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Select \"READ IP CHARA - REPLACEMENT TCM\" of \"IP characteristics data writing\".", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "When the calibration data has been saved to the M.U.T.-III SE, the message \"Completed\" will be displayed.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Touch \"OK\" to finish.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "REPLACE TCM", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Replace the TCM. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "PERFORM TCM PROGRAMMING", "PERFORMTCMPROGRAMMING-D57E8749");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Perform TCM programming, according to \"Programming\" of M.U.T.-III SE User\'s Manual. Refer to M.U.T.-III SE User\'s Manual.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Battery voltage: 12 – 13.5 V (Be sure to check the value of battery voltage.)", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "WRITE MAC KEY", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Perform MAC key writing, Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "WRITE CALIBRATION DATA (IP CHARACTERISTICS VALUE)", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Write data saved in M.U.T.-III SE into a new TCM according to the following instructions:", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Verify vehicle is in \"Park\" (P), then the ignition switch is OFF and wait for 10 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Select \"WRITE IP CHARA - REPLACEMENT TCM\" of \"IP characteristics data writing\".", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "When the calibration data has been written to the TCM, the message \"Completed\" will be displayed.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "PERFORM TORQUE CONVERTER CLUTCH POINT LEARNING", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Perform Torque Converter Clutch Point Learning. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "PERFORM SELECT LEARNING (DRIVE/REVERSE LEARNING)", "title");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Always perform Clutch Point Learning before Select Learning.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Perform Select Learning. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "Clear any DTCs that may have set and then test drive the vehicle.", "ptxt");
si[i++] = gsitm("N5040203R0007N00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D600ENG.html", "Perform the following work after the transaxle assembly is replaced. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "The CD provided with the new transaxle assembly contains important calibration data that must be installed with M.U.T.-III SE after installation of the new transaxle assembly. Never discard the CD.", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "WORK AFTER TRANSAXLE ASSEMBLY REPLACEMENT", "title");
si[i++] = gsitm("N50402011000D600ENG.html", "TCM programming", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "Since vehicle specifications are not yet written in a new TCM, it is necessary to write them with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "MAC key writing", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "Shift actuator learning", "ptxt");
si[i++] = gsitm("N50402011000D600ENG.html", "Select learning (Drive/Reverse learning)", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Before starting, make sure:", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "All M.U.T.-III SE software updates (if any) have been installed.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "REPLACE TRANSAXLE ASSEMBLY", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Replace transaxle assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "PERFORM TCM PROGRAMMING", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Perform TCM programming, according to \"Programming\" of M.U.T.-III SE User\'s Manual. Refer to M.U.T.-III SE User\'s Manual.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Battery voltage: 12 – 13.5 V (Be sure to check the value of battery voltage.)", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "WRITE MAC KEY", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Perform MAC key writing, Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "PERFORM SHIFT ACTUATOR LEARNING", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Perform Shift Actuator Learning. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "PERFORM SELECT LEARNING (DRIVE/REVERSE LEARNING)", "title");
si[i++] = gsitm("N5040203R0007O00ENG.html", "Perform Select Learning. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007O00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D700ENG.html", "Perform the following work after the control valve is replaced. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "The CD provided with the new control valve contains important calibration data that must be installed with M.U.T.-III SE after installation of the new control valve. Never discard the CD.", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "WORK BEFORE CONTROL VALVE REPLACEMENT", "title");
si[i++] = gsitm("N50402011000D700ENG.html", "New control valve serial number checking", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "WORK AFTER CONTROL VALVE REPLACEMENT", "title");
si[i++] = gsitm("N50402011000D700ENG.html", "Current/New calibration data checking", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "Checking that the serial number recorded on the attached CD matches the serial number on new control valve.", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "Calibration data (IP characteristics value) writing", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "TCM performs accurate control by retrieving data (inherent characteristic value) of each solenoid. For this reason, after replacing transaxle assembly, it is necessary to write new data in TCM.", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "Torque converter clutch point learning", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "Select learning (Drive/reverse learning)", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "CVT fluid degradation level data erasing", "ptxt");
si[i++] = gsitm("N50402011000D700ENG.html", "TCM records the degradation level of the CVT fluid calculated from the vehicle driving status. Therefore, if the transaxle assembly is replaced, it is necessary to erase the CVT fluid degradation level data recorded by TCM.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Before starting, make sure:", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "All M.U.T.-III SE software updates (if any) have been installed.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "PRINT CURRENT CALIBRATION DATA", "title");
si[i++] = gsitm("N5040203R0007P00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Connect M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Select \"Calibration data\" in \"TRANSMISSION\".", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Print page.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "This screen print is used for warranty documentation.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "CHECK THE SERIAL NUMBER (PART 1)", "title");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Write down the serial number (calibration file number) of the new control valve.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Compare the serial number (calibration file number) on the CD, QR code label and new control valve. All numbers must match.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "REPLACE CONTROL VALVE", "title");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Replace control valve. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "CHECK THE SERIAL NUMBER (PART 2) AND WRITE CALIBRATION DATA (IP CHARACTERISTICS VALUE)", "title");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Insert the supplied CD into M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Select \"Special Function\" in \"TRANSMISSION\".", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Select \"WRITE IP CHARA - Using import data\" in \"IP characteristics data writing\".", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Touch \"File import\" on the select IP characteristics data file window, and then import data file from CD to M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Select data on the select IP characteristics data file window.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Confirm that the serial number (calibration file number) displayed on M.U.T.-III SE screen matches the serial number (calibration file number) on the new control valve.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Set the vehicle to the following conditions:", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Ignition switch ON, engine OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Set the shift position to the P position.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Press the brake pedal.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Depress the throttle pedal half way and hold.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "IG-OFF/ON operation, and then Touch \"OK\".", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "When the calibration data has been written to the TCM, the message “Completed” will be displayed.", "ptxt");
si[i++] = gsitm("N5040203R0007P00ENG.html", "Touch \"OK\" to finish.", "ptxt");
