si[i++] = gsitm("N50402011000D800ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D800ENG.html", "TCM memorizes a torque converter clutch point (engagement timing), and this enables accurate control. For work procedure, refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "TORQUE CONVERTER CLUTCH POINT LEARNING", "title");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Select “Special Function” in “TRANSMISSION”.", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Select “Item No. 2: LU CLUTCH POINT LEARNING” in \"Learning\".", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Touch \"OK\" to perform learning.", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "During learning, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Brake pedal: Depressed", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Accelerator pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Selector lever: D position", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "A/C switch: OFF", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "CVT fluid temperature: 60°C (140 °F) – 100°C (212 °F)", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Engine coolant temperature: 70°C (158 °F) – 110°C (230 °F)", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Vehicle speed: 3 km/h (2 MPH) or less", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "Input speed: 50 rpm or less", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "DTCs has not been detected.", "ptxt");
si[i++] = gsitm("N5040203R0007Q00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007R00ENG.html", "If Clutch Point Learning is also required, always perform Clutch Point Learning before Select Learning.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Perform Select Learning with CVT fluid temperature below 50°C (122°F) and again with fluid temperature above 50°C (122°F).", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "PERFORM SELECT LEARNING (DRIVE/REVERSE LEARNING)", "title");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Set the parking brake.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Start the engine and wait 5 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Depress the brake pedal", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Shift the selector lever to the N position and hold more than 2 seconds, then to D position and wait for transmission engagement.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Repeat step 3 ten (10) times.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Shift the selector lever to the N position and hold more than 2 seconds, then to R position and wait for transmission engagement.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Repeat step 5 ten (10) times.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "Shift the selector lever to the P position and turn the ignition OFF.", "ptxt");
si[i++] = gsitm("N5040203R0007R00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N50402011000D900ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000D900ENG.html", "When replacing TCM, it is necessary to write MAC key to TCM. Write MAC key to TCM according to \"MAC Key writing\" procedure of \"M.U.T.-III SE User\'s Manual\". Refer to .", "ptxt");
si[i++] = gsitm("N50402011000D900ENG.html", "During MAC key writing, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N50402011000D900ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N50402011000D900ENG.html", "M.U.T.-III SE is connected to internet", "ptxt");
si[i++] = gsitm("N5040203R0007S00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007S00ENG.html", "PERFORM MAC KEY WRITING", "title");
si[i++] = gsitm("N5040203R0007S00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5040203R0007S00ENG.html", "Select \"MAC KEY Writing\" on \"Special Function\" of \"TRANSMISSION\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5040203R0007S00ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N5040203R0007S00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000DA00ENG.html", "Electric shift control module memorizes a shift actuator position, and this enables accurate control.", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Therefore, it is required to perform learning value erase and relearning after the following work is performed.", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Removing/installing shift actuator", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Replacing shift actuator", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Replacing transaxle assembly", "ptxt");
si[i++] = gsitm("N50402011000DA00ENG.html", "Replacing electric shift control module (Learning only)", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007T00ENG.html", "If the electric shift control module has been replaced, start with step 2.", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "ERASE SHIFT ACTUATOR LEARNING VALUE", "title");
si[i++] = gsitm("N5040203R0007T00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Turn ignition switch ON.", "ptxt");
