si[i++] = gsitm("N5040203R0007T00ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "SHIFT ACTUATOR LEARNING", "PREPARATIONBEFORECALIBRATIONPROCEDU-7F04B9B3");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Depress the brake pedal in \"P\" position and wait for 3 seconds.", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5040203R0007T00ENG.html", "Shift to \"D\" position and wait for 3 seconds.", "ptxt");
