si[i++] = gsitm("N5040203R0007U00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5040203R0007U00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Check the engine oil level. Replenish if necessary. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Check for leak of the CVT fluid. Refer to .", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Drive for about 10 minutes to warm up the vehicle so that the CVT fluid temperature is 50 to 80°C (122 to 176°F).", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Be sure to apply the parking brake and block the tires.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Start the engine, depress the brake pedal and shift to the D position.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "While depressing the brake pedal, depress the accelerator pedal gradually.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Read the stall speed quickly. Then, release your foot from the accelerator pedal quickly.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Never depress the accelerator pedal for 5 seconds or more during the test.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Stall speed", "ptxt");
