si[i++] = gsitm("N5040203R0007U00ENG.html", "Shift the N position.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Cool the CVT fluid.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Run the engine with the idle speed for at least 1 minute.", "ptxt");
si[i++] = gsitm("N5040203R0007U00ENG.html", "Put the selector lever to the R position and perform Step 6 to Step 9 again.", "ptxt");
