si[i++] = gsitm("N5040201V0008A00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040201V0008A00ENG.html", "CHECK SELECTOR LEVER OPERATION", "title");
si[i++] = gsitm("N5040201V0008A00ENG.html", "Shift the selector lever and check for excessive effort, sticking, noise or rattle.", "ptxt");
si[i++] = gsitm("N5040201V0008A00ENG.html", "The selector lever automatically moves back to the H (home) position after it is operated.", "ptxt");
