si[i++] = gsitm("N50402011000DB00ENG.html", "Description", "title");
si[i++] = gsitm("N50402011000DB00ENG.html", "WHEN A DTC IS STORED IN TCM", "title");
si[i++] = gsitm("N50402011000DB00ENG.html", "When a DTC is stored in TCM and MIL is ON, a permanent DTC is erased with MIL shutoff if the same malfunction is not detected after performing the driving pattern for MIL shutoff three times in a raw.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "The following timing chart is for DTC of two trip detection diagnosis.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "In case of DTC of one trip detection diagnosis, when NG is detected at one trip, MIL turns ON and permanent DTC is displayed.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "*1:", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "When the same malfunction is detected in two consecutive trips, MIL will illuminate.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "*2:", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "MIL will turn off after vehicle is driven 3 times (driving pattern B) without any malfunctions.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "*3:", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "Diagnosis condition *A and diagnosis delay time *A for each DTC are satisfied.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "(*A: For details of these, refer to DTC/CIRCUIT DIAGNOSIS >> DTC (Pxxxx or Uxxx) >> DTC Description >> DTC DETECTION LOGIC.)", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "WHEN A DTC IS NOT STORED IN TCM", "title");
si[i++] = gsitm("N50402011000DB00ENG.html", "The erasing method depends on a permanent DTC stored in TCM.", "ptxt");
si[i++] = gsitm("N50402011000DB00ENG.html", "For erase procedure of permanent DTC, refer to .", "ptxt");
