si[i++] = gsitm("N5040206Y0000B00ENG.html", "PREPARATION", "title");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Place the vehicle on a lift.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Turn off the ignition switch.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Disconnect negative battery terminal.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Remove the parts around the shift actuator.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Disconnect harness connectors of shift actuator.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Remove shift actuator  from transaxle.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Set the CVT range position to \'N\' with CVT range switch adjuster [SST: KV31501600 (J-53061)].", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Tie the right front tire and any vehicle member with a rope not to rotate the wheel.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Make a suitable mark on a side wall of the left front tire to recognize one round of rotation at the visual inspection steps.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Remove the parts around the CVT chain belt inspection hole.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Clean around the CVT chain belt inspection hole. This will prevent foreign materials from entering into the transaxle case when handling plug of CVT chain belt inspection hole.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Remove the plug of chain belt inspection hole .", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Do not reuse O-ring.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Lift up the vehicle slightly to enable rotating the wheel manually.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "VISUAL INSPECTION", "title");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "To judge if the chain belt is damaged or not, visually inspect all around of the both pulley contact surfaces of chain belt using a borescope [SST: ST04302000 or ST04303000ST04302000 or ST04303000 (J-51951)] with a 90 degree viewing mirror.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Near CVT side cover side Inspection – vehicle left side of flanks surfaces of the chain belt", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Insert the borescope [SST: ST04302000 or ST04303000ST04302000 or ST04303000 (J-51951)]  into chain belt inspection hole on the CVT case with the angle and length (A) shown in the figure. Marking with a piece of tape  shown in the figure will helps this operation as a guide.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Length (A): 11.5 cm (4.53 in)", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Inspect all around of the pulley contact surfaces of chain belt  (flanks surfaces of locker pins).", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Slowly rotate the front left tire entire one round to view all of the chain belt flanks surfaces. Use a mark on the tire to recognize one round of rotation.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Refer to the damage samples below for the judgement.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Near engine side Inspection - vehicle right side of flanks surfaces of the chain belt", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Length (A): 10 cm (3.94 in)", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "OK / DAMAGE SAMPLES", "title");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "&lt;OK SAMPLE>", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "No damage is observed on the flanks of chain belt locker pins.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "&lt;DAMAGE SAMPLES>", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Damages like scuffing are observed on the flanks of chain belt locker pins.", "ptxt");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "AFTER INSPECTION", "title");
si[i++] = gsitm("N5040206Y0000B00ENG.html", "Install removed parts in the reverse order of \'PREPARATION\'.", "ptxt");
