si[i++] = gsitm("N504020CM0000Q00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Use only Genuine CVT fluid. Using transmission fluid other than Genuine CVT fluid will damage the CVT, which is not covered by the warranty.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "During adjustment of the CVT fluid level, check M.U.T.-III SE so that the oil temperature may be maintained from 35 to 45°C (95 to 113°F).", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Always use shop paper. Never use shop cloth.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Replace a drain plug gasket with new ones at the final stage of the operation when installing.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Use caution when looking into the drain hole as there is a risk of dripping fluid entering the eye.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "After replacement, always perform CVT fluid leakage check.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Select \"Data List\" in \"TRANSMISSION\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Select \"Item No. 60: FLUID TEMP\" and confirm that the CVT fluid temperature is 40°C (104°F) or less.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Check that the shift position is in the \"P\" position, then completely engage the parking brake.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Lift up the vehicle.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Remove the drain plug and drain the CVT fluid from the oil pan. Refer to .", "ptxt");
