si[i++] = gsitm("N504020CM0000Q00ENG.html", "Install the CVT fluid charging pipe to the transaxle case. Refer to .", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "Work so that contamination does not get inside the transaxle case.", "ptxt");
si[i++] = gsitm("N504020CM0000Q00ENG.html", "O-ring use the old one.", "ptxt");
