si[i++] = gsitm("N504020CS000CT00ENG.html", "As part  in the figure contains a strong magnet, persons with an electro-medical apparatus should keep it away from his/her body. Otherwise it may cause the electro-medical apparatus to malfunction.", "ptxt");
