si[i++] = gsitm("N504020CS000DD00ENG.html", "When replacing the control valve, attach the serial number sticker packed with it to the actuator.", "par46");
si[i++] = gsitm("N504020CS000DD00ENG.html", "The CD provided with the new control valve contains important calibration data that must be installed with M.U.T.-III SE after installation of the new control valve. Never discard the CD.", "ptxt");
