si[i++] = gsitm("N504020CS000DD00ENG.html", "Set manual shaft and manual plate to N position with CVT range switch adjuster [SST: KV31501600 (J-53061)].", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Rotate manual shaft counterclockwise until it hits to the end, and then return one position to set it to \"N\" position.", "par34");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Set manual valve position to \"N\" by inserting punch or pin of Φ2 mm (Φ0.1 inch) through both holes of control valve and manual valve. Remove the punch or pin after adjusting the position of manual valve.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Install control valve  to transaxle case.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Manual plate  needs to be set into the groove of manual valve  .", "par26");
si[i++] = gsitm("N504020CS000DD00ENG.html", "When installing control valve, prevent it from tilting with respect to transaxle case. Ensure positioning by engaging dowel pins  on the case and dowel pin holes  on control valve.", "par26");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Install the control valve  with mounting bolts ( 10 pieces) which exists on the outline of control valve according to the sequence of ,  and .", "par38");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Install mounting bolts by hand tightening.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "There are 3 types of bolts for control valve installation. Install the bolts to appropriate position.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "When installing the control valve, prevent it from tilting with respect to the case, and ensure positioning with the dowel pin.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Tighten ten control valve mounting bolts to the specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Rotate manual shaft with CVT range switch adjuster [SST: KV31501600 (J-53061)] manually to confirm that the shaft rotates without problem. Set manual shaft to N position after the confirmation.", "ptxt");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Install harness connector  and harness clip .", "par6");
si[i++] = gsitm("N504020CS000DD00ENG.html", "Install two O-rings   to one-way valve .", "ptxt");
