si[i++] = gsitm("N504020CS000DA00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Never remove the radiator cap when the engine is hot. Serious burns could occur from high pressure engine coolant escaping from the radiator. Wrap a thick cloth around the cap. Slowly turn it a quarter turn to allow built-up pressure to escape. Carefully remove the cap by turning it all the way.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Perform these steps after the coolant temperature has cooled sufficiently.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When replacing the transaxle, perform \"ADDITIONAL SERVICE WHEN REPLACING TRANSAXLE ASSEMBLY\". Refer to .", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Remove the engine and transaxle assembly. Refer to &lt;4B4>.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Remove tightening bolts ( 4 pieces) for drive plate and torque converter.", "par19");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Using paint, put matching marks on the drive plate and torque converter when removing the torque converter and drive plate fixing bolts.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Remove mounting bolts for transaxle assembly and engine assembly.", "par1");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Bolt No.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Insertion direction", "par10");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Transaxle to engine", "par11");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Engine to transaxle", "par12");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Number of bolts", "par13");
si[i++] = gsitm("N504020CS000DA00ENG.html", "2", "par14");
si[i++] = gsitm("N504020CS000DA00ENG.html", "7", "par18");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Separate transaxle assembly from engine assembly.", "par17");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Remove the following parts from transaxle assembly.", "par16");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Air breather hose. Refer to .", "par37");
si[i++] = gsitm("N504020CS000DA00ENG.html", "CVT fluid charging pipe", "par38");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Dynamic damper assembly", "par38");
