si[i++] = gsitm("N504020CS000DA00ENG.html", "Corrugate clamp bracket", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Write down the serial number of the new transaxle assembly.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When replacing an engine or transaxle you must make sure any dowels are installed correctly.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "During re-assembly improper alignment caused by missing dowels may cause vibration, oil leaks or breaking of drive train components.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Never reuse O-ring or CVT fluid charging pipe cap.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When turning crankshaft, turn it clockwise as viewed from the front of the engine.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When tightening the bolts for the torque converter while securing the crankshaft pulley centre bolt, be sure to confirm the tightening torque of the crankshaft pulley centre bolt. Refer to .", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "After torque converter is installed to drive plate, rotate crankshaft several turns to check that CVT rotates freely without binding.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When installing the CVT to the engine, align the matching mark on the drive plate with the matching mark on the torque converter.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When installing transaxle assembly to the engine assembly, tighten the bolts in the sequence shown.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "When installing the drive plate to torque converter bolts, tighten them temporarily, then tighten the bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N504020CS000DA00ENG.html", "Perform \"ADDITIONAL SERVICE WHEN REPLACING TRANSAXLE ASSEMBLY\". Refer to .", "ptxt");
