si[i++] = gsitm("N504020CX0005W00ENG.html", "Check the following items:", "ptxt");
si[i++] = gsitm("N504020CX0005W00ENG.html", "CVT fluid leakage, refer to .", "ptxt");
si[i++] = gsitm("N504020CX0005W00ENG.html", "For CVT position, refer to .", "ptxt");
si[i++] = gsitm("N504020CX0005W00ENG.html", "Start the engine and check for coolant leakage from the parts which are removed and reinstalled.", "ptxt");
si[i++] = gsitm("N504020CX0005W00ENG.html", "ADJUSTMENT AFTER INSTALLATION", "title");
si[i++] = gsitm("N504020CX0005W00ENG.html", "Adjust the CVT fluid level. Refer to .", "ptxt");
