si[i++] = gsitm("N504020DC0000N00ENG.html", "Disassembly", "title");
si[i++] = gsitm("N504020DC0000N00ENG.html", "Remove transaxle assembly. Refer to .", "ptxt");
si[i++] = gsitm("N504020DC0000N00ENG.html", "Remove torque converter from transaxle assembly.", "ptxt");
si[i++] = gsitm("N504020DC0000N00ENG.html", "Never damage the bushing on the inside of torque converter sleeve when removing torque converter.", "ptxt");
si[i++] = gsitm("N504020DC0000N00ENG.html", "Remove converter housing oil seal  using suitable tool.", "ptxt");
si[i++] = gsitm("N504020DC0000N00ENG.html", "Be careful not to scratch converter housing and input shaft.", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Assembly", "title");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Note the following and assembly in the reverse order of disassembly.", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Install the new converter housing oil seal to the converter housing evenly until the oil seal becomes horizontal to the surface of the converter housing using the oil seal installer (SST: MB992312) (A)", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Install the new converter housing oil seal  evenly using the ball joint remover and installer A (SST: MB990799) (A)", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "B", "par12");
si[i++] = gsitm("N504020DD0000N00ENG.html", ": 1.0 ± 0.5 mm (0.04 ± 0.020 in)", "par13");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Never reuse converter housing oil seal.", "par9");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Apply CVT fluid to the oil seal lip and around the oil seal.", "par5");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Converter housing oil seal pulling direction is used as the reference.", "par10");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Attach the pawl  of the torque converter to the drive sprocket hole  on the transaxle assembly side.", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Rotate the torque converter for installing torque converter.", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "Never damage the bushing inside the torque converter sleeve when installing the converter housing oil seal.", "ptxt");
si[i++] = gsitm("N504020DD0000N00ENG.html", "After completing installation, check for CVT fluid leaks and CVT fluid level. Refer to .", "ptxt");
si[i++] = gsitm("N5040201V0008I00ENG.html", "Inspection", "title");
