si[i++] = gsitm("N5040304L0000B00ENG.html", "AWD Control Unit", "title");
si[i++] = gsitm("N5040304L0000B00ENG.html", "Controls driving force distribution by signals from each sensor from front wheel driving mode (100:0) to 4-wheel driving mode (50:50).", "ptxt");
si[i++] = gsitm("N5040304L0000B00ENG.html", "Fail-safe mode is available if malfunction is detected in AWD system. For fail-safe, refer to .", "ptxt");
si[i++] = gsitm("N5040304L0000B00ENG.html", "AWD control unit is integrated with actuator assembly of electro-hydraulic coupling assembly. For installation location of actuator assembly, refer to .", "ptxt");
si[i++] = gsitm("N5040304M0000B00ENG.html", "Electro-hydraulic Coupling", "title");
si[i++] = gsitm("N5040304M0000B00ENG.html", "Electro-hydraulic coupling is installed on front of rear final drive and transmits driving force to rear final drive.", "ptxt");
si[i++] = gsitm("N5040304M0000B00ENG.html", "Electro-hydraulic coupling assembly include actuator assembly.", "ptxt");
si[i++] = gsitm("N5040304M0000B00ENG.html", "For operation, refer to .", "ptxt");
si[i++] = gsitm("N5040304M0000B00ENG.html", "For detailed installation location, refer to .", "ptxt");
si[i++] = gsitm("N5040304N0000B00ENG.html", "Transfer Oil Temperature Sensor", "title");
si[i++] = gsitm("N5040304N0000B00ENG.html", "Transfer oil temperature sensor detects the transfer oil temperature and transmits a signal to AWD control unit.", "ptxt");
si[i++] = gsitm("N5040304N0000B00ENG.html", "The electrical resistance of the sensor decreases as temperature increases.", "ptxt");
si[i++] = gsitm("N5040304N0000B00ENG.html", "Transfer oil temperature sensor is installed on transfer. For detailed installation location, refer to .", "ptxt");
