si[i++] = gsitm("N5040304P0000B00ENG.html", "Power from engine", "ptxt");
si[i++] = gsitm("N5040304P0000B00ENG.html", "ELECTRO-HYDRAULIC COUPLING", "title");
si[i++] = gsitm("N5040304P0000B00ENG.html", "AWD control unit (Integrated with actuator assembly) receives the CAN communication signal from the vehicle and judges the vehicle condition.", "ptxt");
si[i++] = gsitm("N5040304P0000B00ENG.html", "The actuator operates according to the command from the AWD control unit, and the hydraulic piston generates hydraulic pressure according to the vehicle condition.", "ptxt");
si[i++] = gsitm("N5040304P0000B00ENG.html", "The main clutch is pressed by the hydraulic pressure generated by the hydraulic piston, and clutch plates (inner side and outer side) are engaged", "ptxt");
si[i++] = gsitm("N5040304P0000B00ENG.html", "The main clutch transmits torque to rear wheels according to the hydraulic pressure from actuator.", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "System Description", "title");
si[i++] = gsitm("N5040302T0000N00ENG.html", "According to signal information from each sensor and switch, the driving torque distribution of front and rear wheels is judged, and pressing force of multiple disc clutch is controlled by electric control.", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "Driving torque distribution of front and rear wheels changes automatically between approximately 100 : 0 (2WD) and 50 : 50 (AWD) to have an optimized torque distribution adapted to road condition change.", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "The optimal driving torque is distributed according to the driving mode selected by the drive mode selector. Refer to .", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "Fail-safe function is activated if malfunction is detected in AWD system. Refer to .", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "When a high load status continues for electro-hydraulic coupling, AWD control temporarily becomes front wheel drive, according to protection function. Refer to .", "ptxt");
si[i++] = gsitm("N5040302T0000N00ENG.html", "SYSTEM DIAGRAM", "title");
