si[i++] = gsitm("N5040304R0000B00ENG.html", "Control in Each Mode", "title");
si[i++] = gsitm("N5040304R0000B00ENG.html", "For driving modes other than AUTO mode by drive mode selector, refer to .", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "AUTO MODE", "title");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Electronic control allows optimal distribution of torque to front/rear wheels to match road conditions.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Pressing force of multiple disc clutch is controlled by electric control. Driving torque distribution of front and rear wheels changes automatically between approximately 100 : 0 (2WD) and 50 : 50 (AWD) to have an optimized torque distribution adapted to road condition change.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Sensor inputs determine the vehicle\'s turning condition, and tight cornering/braking are controlled by distributing optimum torque to rear wheels.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Vehicle Starts Control", "title");
si[i++] = gsitm("N5040304R0000B00ENG.html", "At the start, torque distribution for front and rear wheels is fixed by electric control and stable start is achieved.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Makes possible stable driving, with no wheel spin, on snowy roads or other slippery surfaces.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "Normal Control", "title");
si[i++] = gsitm("N5040304R0000B00ENG.html", "On roads which do not require AWD, it contributes to improved fuel economy by driving in conditions close to front-wheel drive and it results in better fuel efficiency.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "When spin occurs on front wheel, distribute optimum torque to rear wheel and keep stable driving.", "ptxt");
si[i++] = gsitm("N5040304R0000B00ENG.html", "The vehicle cornering status is judged according to information from each sensor, and the optimum torque is distributed to rear wheels for preventing tight cornering/braking symptom.", "ptxt");
si[i++] = gsitm("N5040304S0000T00ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N5040304S0000T00ENG.html", "If any malfunction occurs in AWD electrical system, and control unit detects the malfunction, AWD warning on information display (combination meter) is displayed to indicate system malfunction. And then AWD control unit controls becomes the fail-safe mode depending on DTC.", "ptxt");
si[i++] = gsitm("N5040304S0000T00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5040304S0000T00ENG.html", "Vehicle condition", "ptxt");
