si[i++] = gsitm("N5040302I0000P00ENG.html", "Protection Function", "title");
si[i++] = gsitm("N5040302I0000P00ENG.html", "AWD system activates its protection function (shuts down AWD system temporarily) if AWD system detects high load continuously or the front wheel tire size differs from the rear tire size. (AWD system is automatically restored if AWD system no longer detects any overload or the tire size difference is eliminated.)", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "DTC", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "AWD warning (on information display)", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Error area and root cause", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Contents of protection function", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "—", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Rear final drive assembly in protection mode. It is not malfunction.", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "(Internal temperature rise of electro-hydraulic coupling)", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Shuts down AWD system temporarily", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "(Front wheel drive)", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "Malfunction in each tire or different tire diameter", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "If the AWD warning displays during driving but remains not displayed after the engine is restarted, the system is normal. If it again displays after driving for some time, vehicle must be inspected.", "ptxt");
si[i++] = gsitm("N5040302I0000P00ENG.html", "When there is a difference of revolution speed between the front and rear wheel the shift occasionally changes to direct 4-wheel driving conditions automatically. This is not a malfunction.", "ptxt");
si[i++] = gsitm("N5040304U0000D00ENG.html", "AWD Warning", "title");
