si[i++] = gsitm("N504030110001T00ENG.html", "Description", "title");
si[i++] = gsitm("N504030110001T00ENG.html", "When replacing AWD control unit (integrated with actuator assembly of electro-hydraulic coupling assembly) and electro-hydraulic coupling assembly, the following work is required.", "ptxt");
si[i++] = gsitm("N504030110001T00ENG.html", "For the work procedure, refer to .", "ptxt");
si[i++] = gsitm("N504030110001T00ENG.html", "WORK AFTER REPLACEMENT", "title");
si[i++] = gsitm("N504030110001T00ENG.html", "AWD control unit programming", "ptxt");
si[i++] = gsitm("N504030110001T00ENG.html", "Since vehicle specifications are not yet written in a new AWD control unit, it is necessary to write them with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504030110001T00ENG.html", "Air bleeding and initialize oil deterioration level of electro-hydraulic coupling oil", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N504030320000R00ENG.html", "Before starting, make sure:", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "ASIST on the M.U.T.-III SE has been synchronized to the current date.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "All M.U.T.-III SE software updates (if any) have been installed.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "REPLACING", "title");
si[i++] = gsitm("N504030320000R00ENG.html", "The ignition switch is OFF.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Replace AWD control unit (integrated with actuator assembly) or electro-hydraulic coupling assembly. Refer to .", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "PERFORM AWD CONTROL UNIT PROGRAMMING", "title");
si[i++] = gsitm("N504030320000R00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Perform AWD control unit programming according to the procedure of “Programming” in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Engine: Stopped", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Battery voltage: More than 11 V (Be sure to check the value of battery voltage by selecting “Battery voltage” in “Data List” of M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "PERFORM AIR BLEEDING AND INITIALIZE OIL DETERIORATION LEVEL", "PERFORMAIRBLEEDINGANDINITIALIZEOILD-0B13D72F");
si[i++] = gsitm("N504030320000R00ENG.html", "Perform air bleeding and initialize oil deterioration level of electro-hydraulic coupling oil. Refer to .", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "PERFORM THE FACTORY MODE OFF", "idE6");
si[i++] = gsitm("N504030320000R00ENG.html", "Turn the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"ALL MODE AWD / 4WD\".", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N504030320000R00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N504030110001U00ENG.html", "Description", "title");
si[i++] = gsitm("N504030110001U00ENG.html", "When the electro-hydraulic coupling oil is drained, such as when replacing or removing/installing electro-hydraulic coupling component parts, the air bleeding and initialize oil deterioration level of electro-hydraulic coupling oil is required after fill with new electro-hydraulic coupling oil.", "ptxt");
si[i++] = gsitm("N504030110001U00ENG.html", "For the work procedure, refer to .", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N504030320000M00ENG.html", "PREPARATIONS BEFORE WORK", "title");
si[i++] = gsitm("N504030320000M00ENG.html", "Set the vehicle in the following condition.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Temperature condition is -10°C (14°F) or higher.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Vehicle is stopped on a flat place.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Battery voltage condition is 14.2 V or more.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "If the battery voltage is low, it is necessary to add a booster.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "AIR BLEEDING AND INITIALIZE OIL DETERIORATION LEVEL", "title");
si[i++] = gsitm("N504030320000M00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Turn the ignition switch OFF to ON.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Select “BLEED AIR & INITIALIZE OIL DETERIORATION LEVEL” in “WORK SUPPORT” for “ALL MODE AWD/4WD”.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Select \"OK\".", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Follow the instructions in M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "When air bleeding is activated, operation noise is heard from the lower part of the vehicle, but this is not a malfunction.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "Is “Completed” displayed?", "question");
si[i++] = gsitm("N504030320000M00ENG.html", "YES", "result");
si[i++] = gsitm("N504030320000M00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N504030320000M00ENG.html", "NO", "result");
