si[i++] = gsitm("N5040306I0001Z00ENG.html", "Never twists and damage the harness of transfer oil temperature sensor.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Remove transfer cover mounting bolts.", "ptxt");
