si[i++] = gsitm("N5040306I0001Z00ENG.html", "Never use a tool.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Never damage transfer cover.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Lightly tap the metal part of oil seals  with pin punch etc. from back side of transfer cover to remove transfer cover oil seal (outer/inner).", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "When removing, never damage the transfer cover by scooping it out with a tool.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Remove ring gear bearing adjusting shim (transfer cover side)  and ring gear bearing outer race (transfer cover side) .", "ptxt");
