si[i++] = gsitm("N5040306I0001Z00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Select the ring gear bearing adjusting shim (transfer cover side). Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Install the selected ring gear bearing adjusting shim (transfer cover side)  and ring gear bearing outer race (transfer cover side)  using a drift (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Never reuse ring gear bearing (transfer cover side).", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Apply transfer oil to the ring gear bearing (transfer cover side).", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Install the transfer cover to the transfer case, and apply anti-corrosive oil onto thread and seats on the mounting bolts. Then tighten mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "For tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "At this timing, O-ring installing to transfer cover is not necessary. Install O-ring after tooth contact is checked.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Check backlash, tooth contact, total preload and companion flange runout. Refer to .", "ptxt");
