si[i++] = gsitm("N5040306I0001Z00ENG.html", "Never reuse gasket.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "If transfer oil temperature sensor is subjected to impact by dropping or hitting it, replace with new one.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Be sure to dry the sensor thread before installation.", "ptxt");
si[i++] = gsitm("N5040306I0001Z00ENG.html", "Install gasket onto drain plug and install them to transfer cover.", "ptxt");
