si[i++] = gsitm("N5040306I0002000ENG.html", "Remove ring gear bearing outer race (transfer case side) and ring gear bearing adjusting shim (transfer case side) from the transfer case. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Remove ring gear bearing inner race (transfer cover side) from ring gear shaft using drift (A) (commercial service tool) and separator (B) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Remove ring gear bearing inner race (transfer case side) from ring gear shaft with drift (A) [SST: ST33061000 (J-8107-2)] and puller (B) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Remove the ring gear mounting bolts.", "ptxt");
