si[i++] = gsitm("N5040306I0002000ENG.html", "Remove ring gear shaft oil seal from the ring gear shaft with the puller (A) [SST: KV381054S0 (J-34286)].", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
