si[i++] = gsitm("N5040306I0002000ENG.html", "When installing, never incline oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Apply multi-purpose grease onto oil seal lips, and transfer oil onto the circumference of the oil seal.", "ptxt");
