si[i++] = gsitm("N5040306I0002000ENG.html", "For tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Install ring gear bearing inner race (transfer cover side) with drift (A) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Install the ring gear bearing inner race (transfer case side) to ring gear shaft with drift (A) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Install the ring gear shaft assembly to the transfer case.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Protect transfer case oil seals beforehand from being damaged by the spline of ring gear shaft below method following.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Apply multi-purpose grease to spline part indicated in the figure.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Wrap piece of a suitable vinyl to spline part only indicated in the figure.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", ": Limit line of wrapping", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Never wrap sliding surfaces on oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "A plastic bag can be used by cutting it to fit.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Install transfer cover to check and adjust each part. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "At this timing, O-ring installing to transfer cover is not necessary. Install O-ring after backlash and tooth contact are checked.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Check backlash, tooth contact, total preload and companion flange runout. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Measure the total preload without oil seals of transfer cover and transfer case.", "ptxt");
si[i++] = gsitm("N5040306I0002000ENG.html", "Reinstall transfer cover to install O-ring. Refer to .", "ptxt");
