si[i++] = gsitm("N5040306I0002100ENG.html", "Remove pinion bearing assembly mounting bolts.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Lightly tap companion flange with a plastic hammer to remove pinion bearing assembly .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove the O-ring from pinion bearing assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove drive pinion lock nut.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove drive pinion from pinion bearing assembly using drift (A) (commercial service tool) and separator (B) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove drive pinion adjusting shim.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove companion flange.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove dust shield.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Remove drive pinion oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040306I0002100ENG.html", "Select drive pinion adjusting shim. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Assemble the selected drive pinion adjusting shim to drive pinion.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install the drive pinion to pinion bearing assembly using drift (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Never reuse pinion bearing assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Apply transfer oil to pinion bearing part.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install drive pinion oil seal to pinion bearing assembly using drift (A) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Never reuse the oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "When installing, never incline oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Apply multi-purpose grease onto oil seal lips, and transfer oil onto the circumference of the oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install dust shield.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Tighten dust shield together with pinion bearing assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install companion flange  to pinion bearing using drift (A) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Tighten drive pinion lock nut within the limits of specified torque so as to keep the pinion bearing preload within the standard values.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Apply anti-corrosive oil to the thread and seat of drive pinion lock nut and install it to drive pinion, and then tighten to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Drive pinion lock nut tightening torque", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", ": 90±9 N·m (9.2±0.92kg-m, 66±7 ft-lb)", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Never reuse drive pinion lock nut.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Check that drive pinion lock nut is seated on the companion flange.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "After tightening drive pinion lock nut to the specified torque, tighten the drive pinion lock nut additionally to the specified angle.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Drive pinion lock nut tightening angle", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", ": 25 degrees", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Measure the pinion bearing preload, using preload gauge [SST: ST3127S000 (J-25765-A)].", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Pinion bearing preload", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install O-ring to pinion bearing assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Never reuse O-ring.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Apply multi-purpose grease lightly and evenly onto O-ring.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "When installing O-ring, never use a tool.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Never damage O-ring.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Install pinion bearing assembly, and apply anti-corrosive oil onto thread and seats on the mounting bolts. Tighten to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "For tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Check backlash, tooth contact, total preload and companion flange runout. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002100ENG.html", "Measure the total preload without oil seals of transfer cover and transfer case.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Adjustment", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "ADJUSTING SHIM SELECTION", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Measurement point", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Select adjusting shim of T1, T2, and T3, respectively, by using the following equation.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T1 [Ring gear bearing adjusting shim (transfer case side)]", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T1 = A −(B +X/2) +C +W −V −F −(M/100) +0.071 mm (0.0028 in)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T2 [Ring gear bearing adjusting shim (transfer cover side)]", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T2 = −Y +Z +(B +X/2) −C −D −H +(M/100) +0.071 mm (0.0028 in)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T3 (Drive pinion adjusting shim)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "T3 = −Q +(R +S/2) −K +(O/100)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Check dimension (M) on the ring gear side face.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Dimension “M” indicates the difference between the optimum engagement and standard dimensions in increments of 0.01 mm (0.0004 in) written on the ring gear side face.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Check dimension (O) on the gear end of drive pinion.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Dimension “O” indicates the difference between the optimum engagement and the standard dimensions in increments of 0.01 mm (0.0004 in) written on the gear end of drive pinion.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "PINION BEARING PRELOAD", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Remove ring gear shaft assembly from the transfer case. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Rotate the companion flange back and forth from 2 to 3 times to check for unusual noise, binding, sticking, and so on.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Rotate the companion flange at least 20 times to check for smooth operation of the bearing.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "While rotate drive pinion at 30 rpm, measure the pinion bearing preload with the preload gauge [SST: ST3127S000 (J-25765-A)].", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Pinion bearing preload", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Each rotational part should rotate smoothly with the specified transfer oil.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Preload torque differs before disassembly and after reassembly. (It differ after driving and new parts.)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "If outside the standard, disassemble pinion bearing assembly to check and adjust each part.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "TOTAL PRELOAD", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Measure pinion bearing preload.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Check that the pinion bearing preload is within the standard.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Assemble the ring gear shaft assembly to the transfer case. Refer to", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Install transfer cover to check and adjust each part. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "While rotate drive pinion at 30 rpm, measure the total preload with the preload gauge (A) [SST: ST3127S000 (J-25765-A)].", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Total preload", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "If outside the standard, disassemble the transfer assembly to check and adjust each part. Measure it with the transfer case oil seals and transfer cover oil seals (outer/inner) removed when measuring total preload after disassembly. Then install transfer case oil seals and transfer cover oil seals.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "BACKLASH", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Install the suitable bolt to the companion flange.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Fit a dial indicator onto the suitable bolt .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Measure the circumference backlash of the companion flange.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Backlash", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Backlash differs before disassembly and after reassembly. (It differ after driving and new parts.)", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "If outside the standard, disassemble the transfer assembly to check and adjust each part.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "TOOTH CONTACT", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Remove transfer cover. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Remove ring gear shaft assembly from transfer case. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Apply red lead or equivalent onto the ring gear.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Apply red lead or equivalent to both faces of 3 to 4 gears at 4 locations evenly spaced on the ring gear.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Assemble ring gear shaft assembly to the transfer case. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "At this timing, O-ring installing to transfer cover is not necessary. Install O-ring after backlash and tooth contact are checked.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Remove plug from the transfer case.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Rotate the companion flange back and forth several times, and check the drive pinion gear to ring gear tooth contact by viewing from the plug hole.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Tooth Contact Judgment Guide", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Follow the procedure below to adjust pinion height (dimension X) if tooth contact is improper.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "If no adjusting shim with the calculated value is available, select the thicker and closest one.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Thicken the drive pinion adjusting shim to move the drive pinion closer to the ring gear in case of face contact or heel contact.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Only one adjusting shim can be selected.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Thin the drive pinion adjusting shim to move the drive pinion farther from the ring gear in case of flank contact or toe contact.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "COMPANION FLANGE RUNOUT", "title");
si[i++] = gsitm("N5040306L0001500ENG.html", "Fit a dial indicator onto the companion flange face (inner side of the propeller shaft mounting bolt holes).", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Rotate companion flange to check for runout.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Companion flange face runout", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Fit a test indicator to the inner side of companion flange (socket diameter).", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Inner side of the companion flange runout", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "If the runout value is outside the runout limit, follow the procedure below to adjust.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Check for runout while changing the phase between companion flange and drive pinion in 90° steps. Then search for the minimum point.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Replace companion flange if runout value is still outside the limit after the phase has been changed.", "ptxt");
si[i++] = gsitm("N5040306L0001500ENG.html", "Adjust assembly status of the pinion bearing assembly and drive pinion, or replace pinion bearing assembly if runout is outside the standard after the companion flange is replaced.", "ptxt");
si[i++] = gsitm("N5040301W0003H00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0003H00ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
