si[i++] = gsitm("N5040301W0003H00ENG.html", "Gear and Shaft", "title");
si[i++] = gsitm("N5040301W0003H00ENG.html", "Check gear face and shaft for wear, cracks, damage, and seizure.", "ptxt");
si[i++] = gsitm("N5040301W0003H00ENG.html", "Replace ring gear and drive pinion as a set (hypoid gear set) if any malfunction is detected on the ring gear or drive pinion.", "ptxt");
si[i++] = gsitm("N5040301W0003H00ENG.html", "Bearing", "title");
