si[i++] = gsitm("N5040301W0003J00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "LOOSENESS OF CONNECTED PART", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Check each fixing bolt and nut for looseness using torque wrench. For each tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "BACKLASH OF JOINT PART", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Move the joint of propeller shaft up and down and from side to side (axial direction of shaft and right angle to shaft) to check that the joint has no backlash. If the joint has a malfunction, remove propeller shaft and perform inspection.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "BACKLASH OF CENTER BEARING", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Move the shaft near center bearing up and down and from side to side (axial direction of shaft and right angle to shaft) to check that the bearing has no backlash. If the bearing has a malfunction, remove propeller shaft and perform inspection.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "APPEARANCE AND NOISE", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Check the propeller shaft tube surface for dents or cracks. If malfunction is detected, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "If center bearing is noisy or damaged, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "VIBRATION", "title");
si[i++] = gsitm("N5040301W0003J00ENG.html", "If vibration is present at high speed, adjust the propeller shaft phase first.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Check the propeller shaft for bend and damage. If damaged, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "Perform a cruise test drive to check the propeller shaft for runout. If vibration occurs, separate propeller shaft at final drive companion flange; then change the phase between companion flange and propeller shaft by the one bolt hole at a time and install propeller shaft.", "ptxt");
si[i++] = gsitm("N5040301W0003J00ENG.html", "If vibration is still detected, measure propeller shaft runout after removing it. Refer to .", "ptxt");
si[i++] = gsitm("N5040306B0004400ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5040306B0004400ENG.html", "Propeller shaft assembly", "ptxt");
si[i++] = gsitm("N5040306B0004400ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5040306B0004400ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5040306B0004400ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5040306C0002200ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove engine under cover. Refer to .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Disconnect fixed parts between main muffler and exhaust front tube. Refer to .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove heat insulator  after removing clips of floor insulator.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Never bend heat insulator.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Put matching marks  on propeller shaft flange yoke and transfer companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "For matching mark, use paint. Never damage propeller shaft flange yoke and transfer companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Put matching marks  on propeller shaft flange yoke and rear final drive companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "For matching mark, use paint. Never damage propeller shaft flange yoke and rear final drive companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Loosen mounting nuts of center bearing mounting bracket.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Tighten mounting nuts temporarily to prevent drop of propeller shaft.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove propeller shaft assembly fixing bolts, and separate propeller shaft assembly from transfer companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove propeller shaft assembly fixing bolts and nuts, and separate propeller shaft assembly from rear final drive companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove center bearing mounting bracket mounting nuts.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Constant velocity joint must be handled with care.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "If constant velocity joint was bent during propeller shaft assembly removal, installation, or transportation, its boot  may be damaged. Wrap boot interference area to metal part  with shop cloth or rubber to protect boot from breakage.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Since no retaining pin is included in sliding direction, the boot may be damaged or dropped if the constant velocity joint is slid out 25 mm (0.98 in) or more from the original length. Therefore, handle constant velocity joint by sliding it inward.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040306C0002200ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "For non-reusable parts, refer to .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "For each tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Remove any moisture, oil, or foreign material from matching surface on transfer companion flange, rear final drive companion flange and propeller shaft flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Align matching marks  to install propeller shaft flange yoke and rear final drive companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Align matching marks  to install propeller shaft flange yoke and transfer companion flange.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "If propeller shaft assembly or final drive assembly has been replaced, connect them as follows:", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Install propeller shaft  while aligning its matching mark  of propeller shaft with matching mark  of final drive  on the joint as close as possible.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "The bolt head should not become out of alignment due to interference between the bolt hexagonal head and the stopper .", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Protector  on boot interference area must be removed after installing propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040306C0002200ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "Appearance", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "Check propeller shaft tube surface for dents or cracks. If malfunction is detected, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Propeller Shaft Runout", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "Check propeller shaft runout at measuring points with a dial indicator. If runout exceeds specifications, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Propeller shaft runout", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Propeller shaft runout measuring point (Point “”).", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", ": Front side", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Dimension", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", ": 555 mm (21.85 in)", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", ": 546 mm (21.5 in)", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Journal End Play", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "As shown in the figure, while fixing yoke on one side, check end play of joint. If it is outside the standard, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Journal end play", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Never disassemble joints.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Center Bearing", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "Check center bearing for noise and damage. If malfunction is detected, replace propeller shaft assembly.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "Never disassemble center bearing.", "ptxt");
si[i++] = gsitm("N5040301W0004000ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040301W0004000ENG.html", "After assembly, perform a driving test to check propeller shaft vibration. If vibration occurred, separate propeller shaft from final drive. Reinstall propeller shaft by changing the phase between companion flange and propeller shaft by the one bolt hole at a time. Then perform driving test and check propeller shaft vibration again at each point.", "ptxt");
