si[i++] = gsitm("N5040306I0003900ENG.html", "Be careful to place each part so that the contamination never stick to the drum surface during work.", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Measure and search for the maximum point of drive pinion runout. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Match electro-hydraulic coupling assembly  to spline of drive pinion, then install it to final drive assembly .", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Aligning marking  on drum of electro-hydraulic coupling assembly  and marking  on tip of drive pinion .", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Tighten electro-hydraulic coupling assembly mounting bolts to the specified torque diagonally.", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "For tightening torque, refer to .", "ptxt");
