si[i++] = gsitm("N5040306I0003900ENG.html", "For applying liquid gasket, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Remove old gasket adhering to the mounting surfaces. Also remove any moisture, oil, or foreign material adhering to the mounting surfaces.", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "The width of sealant bead is approximately 2.6 mm (0.102 in). Apply sealant evenly.", "ptxt");
si[i++] = gsitm("N5040306I0003900ENG.html", "Install coupling oil tank cover  to gear carrier and tighten the mounting bolts to the specified torque in the order shown in the figure.", "ptxt");
