si[i++] = gsitm("N5040306L0001Y00ENG.html", "If the runout is outside of the repair limit, check drive pinion assembly condition; drive pinion may be deformed etc.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "Replace drive gear and drive pinion as a set.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "Search for the maximum point of drive pinion runout and put marking  on tip of drive pinion.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "For marking, use paint. Never damage drive pinion.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "COMPANION FLANGE RUNOUT", "title");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "Fit a dial indicator onto the companion flange face (inner side of the propeller shaft mounting bolt holes).", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "Rotate companion flange to check for runout.", "ptxt");
