si[i++] = gsitm("N5040306L0001Y00ENG.html", "Inner side of the companion flange runout", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "If the runout value is outside the runout limit, follow the procedure below to adjust.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "Check for runout while changing the phase between companion flange and shaft of electro-hydraulic coupling by 90° step, and search for the position where the runout is the minimum.", "ptxt");
si[i++] = gsitm("N5040306L0001Y00ENG.html", "If the runout value is still outside of the limit after the phase has been changed, replace electro-hydraulic coupling assembly.", "ptxt");
si[i++] = gsitm("N5040301W0003M00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0003M00ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040301W0003M00ENG.html", "Bearing", "title");
si[i++] = gsitm("N5040301W0003M00ENG.html", "If unusual noise from the bearing is observed, replace electro-hydraulic coupling assembly.", "par1");
si[i++] = gsitm("N5040301W0003M00ENG.html", "Oil Seal", "title");
si[i++] = gsitm("N5040301W0003M00ENG.html", "Whenever disassembled, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003M00ENG.html", "If wear, deterioration of adherence (sealing force lips), or damage is detected on the lips, replace them.", "ptxt");
si[i++] = gsitm("N5040301W0003M00ENG.html", "Companion Flange", "title");
si[i++] = gsitm("N5040301W0003M00ENG.html", "If any chipped mark [about 0.1 mm, (0.004 in)] or other damage on the contact sides of the lips of the companion flange is found, replace.", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Electro-hydraulic coupling assembly", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Drive pinion lock nut", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Pinion front bearing", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Gasket", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Drain plug", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Filler plug", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Coupling oil tank cover", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Gear carrier", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Collapsible spacer", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Drive pinion adjusting shim", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Pinion rear bearing", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Drive pinion", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Drive gear", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Differential case", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Side bearing", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Side bearing adjusting shim", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Side oil seal", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Rear cover", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Stud bolt", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Pinion mate thrust washer", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Pinion mate gear", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Side gear thrust washer", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Side gear", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Pinion mate shaft", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Lock pin", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Outer circumference", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "Screw hole", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": Select with proper thickness.", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "1: Apply gear oil.", "par1");
si[i++] = gsitm("N5040306B0006N00ENG.html", "2: Apply electro-hydraulic coupling oil (Genuine part).", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", "*: Apply anti-corrosion oil.", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": Apply Genuine Silicone RTV or equivalent. Recommended Chemical Products and Sealants: Permatex Ultra Grey 82194, ThreeBond 1207, 1215, 1216, 1217F, 1217G and 1217H or Nissan RTV Part No. 999MP-A7007.", "ptxt");
si[i++] = gsitm("N5040306B0006N00ENG.html", ": Apply Genuine High Strength Thread Locking Sealant or equivalent. Recommended Chemical Products and Sealants: Permatex 27200, ThreeBond 1360, 1360N, 1305 N&P, 1307N, 1335, 1335B, 1363B, 1377C, 1386B, D&E and 1388 or Loctite 648.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5040306I0002400ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove drain plug  and gasket  from gear carrier and drain gear oil.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove filler plug  and gasket  from gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove the side oil seal, using oil seal remover (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never damage gear carrier and rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove rear cover mounting bolts.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Set drifts (A and B) to the right and left side bearing adjusting shims individually. Press differential assembly with side bearing to remove gear carrier assembly and rear cover assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Drift [SST: KV40100610 (J-26089)]", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "The pressure shall be as low as possible to remove gear carrier assembly and rear cover assembly. The maximum pressure shall be 10 kN (1 ton, 1.1 US ton, 1.0 Imp ton).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Differential assembly, side bearings, and adjusting washers are compressed and integrated in gear carrier and rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove stud bolt from rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "It is not necessary to remove stud bolt except when it is replaced.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove side bearing adjusting shims and side bearing outer races.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Mark the side bearing adjusting shims so that the original mounting positions (right/left) can be identified later.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove side bearing inner races, using adapter (A), separator (B) and puller (C).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Adapter [SST: ST33052000 ( — )]", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Separator (commercial service tool)", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "C", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Puller (commercial service tool)", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "To prevent damage to the side bearing and drive gear, place copper plates between these parts and vise.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "It is not necessary to remove side bearing inner race except when it is replaced.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "For proper reinstallation, paint matching marks  on one differential assembly and drive gear.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "For matching marks, use paint. Never damage differential assembly and drive gear.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove drive gear mounting bolts and then remove drive gear from differential assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove lock pin of pinion mate shaft, using the pin punch (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove pinion mate shaft.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove pinion mate gears, pinion mate thrust washers, side gears, side gear thrust washers from differential case.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install side gear thrust washers with the same thickness as the ones installed prior to disassembly or reinstall the old ones on the side gears.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install side gears and side gear thrust washers into differential case.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Align 2 pinion mate gears in diagonally opposite positions, then rotate and install them into differential case after installing thrust washer to pinion mate gear.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Align the lock pin holes on differential case with pinion mate shaft, and install pinion mate shaft.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Measure side gear end play. If necessary, select the appropriate side gear thrust washers.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Place differential assembly straight up so that side gear to be measured comes upward.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Using feeler gauge, measure the clearance between side gear back and differential case at 3 different points, while rotating side gear. Average the 3 readings, and then measure the clearance of the other side as well.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Side gear back clearance", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "To prevent side gear from tilting, insert feeler gauges with the same thickness from both sides.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "If the back clearance is outside the specification, use a thicker/thinner side gear thrust washer to adjust. For selecting thrust washer, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "When the back clearance is large", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Use a thicker thrust washer.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "When the back clearance is small", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Use a thinner thrust washer.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Select a side gear thrust washer for right and left individually.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Drive a lock pin into pinion mate shaft, using the pin punch (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never reuse lock pin.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Press side bearing inner races to differential assembly, using the drifts (A and B).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Drift [SST: KV40105020 ( — )]", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never reuse side bearing inner race.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Apply gear oil to side bearing.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Apply thread locking sealant into the thread hole of drive gear.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "For applying thread locking sealant, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Clean and degrees drive gear back and threaded holes sufficiently.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install the drive gear to differential assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Align the matching mark of differential assembly and drive gear.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Tighten the bolts in a crisscross fashion to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "For tightening torque, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Apply anti-corrosion oil to the thread and seat of mounting bolts.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Assemble side bearing outer races to inner races.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never reuse side bearing outer race.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install new side bearing adjusting shims (left side: two pieces, right side: one piece) with the same thickness as the ones installed prior to disassembly or re-install the old ones, on side bearing outer race of differential assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "If side bearing adjusting shims have been already selected, use them.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Set the drifts (A and B) to the right and left side bearing adjusting shims individually. Compress differential assembly and side bearing to gear carrier assembly to install differential assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", ": Drift [KV40100610 (J-26089)]", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "The drift shall be placed on the center of the adjusting shims.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "The pressure shall be as low as possible to install differential assembly into gear carrier assembly. The maximum pressure shall be 10 kN (1 ton, 1.1 US ton, 1.0 Imp ton).", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "If the adjusting shims are installed by tapping, the gear carrier may be damaged. Avoid tapping.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install dummy cover set, check and adjust drive gear runout, tooth contact, backlash, and total preload torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove dummy cover set.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install stud bolt to rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Screw the stud bolt until the flange surface becomes seating.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Apply liquid gasket to mating surface of rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "For applying liquid gasket, refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Remove old gasket adhering to the mounting surfaces. Also remove any moisture, oil, or foreign material adhering to the mounting surfaces.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "The width of sealant bead is approximately 3 mm (0.12 in). Apply sealant evenly.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Set the drifts (A and B) to the right and left side bearing adjusting shims individually. Compress differential assembly and side bearing to install rear cover.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Tighten rear cover mounting bolts to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Using the drift (A) (commercial service tool), drive side oil seals until it becomes flush with the gear carrier end.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never reuse oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "When installing, never incline oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Check that the oil seal lip is filled up with grease.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Apply gear oil lightly and evenly onto the outer circumference of oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Check total preload torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install drain plug, as per the following procedure.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install drain plug  with gasket  to gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Never reuse gasket.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Tighten drain plug to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install filler plug, as per the following procedure.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Install filler plug  with gasket  to gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002400ENG.html", "Fill with gear oil before tightening filler plug to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Adjustment", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "TOTAL PRELOAD TORQUE", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "Remove electro-hydraulic coupling assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Rotate drive pinion back and forth 2 to 3 times to check for unusual noise and rotation malfunction.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Rotate drive pinion at least 20 times to check for smooth operation of the bearing.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Fit drive pinion socket (A) onto drive pinion spline. Measure the total preload, using the preload gauge (B) and drive pinion socket.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", ": Drive pinion socket [SST: KV38109300 ( — )]", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", ": Preload gauge [SST: ST3127S000 (J-25765-A)]", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Total preload torque", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Total preload torque = Pinion bearing torque + Side bearing torque", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "If measured value is out of the specification, disassemble it to check and adjust each part. Adjust the pinion bearing preload and side bearing preload.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Adjust the pinion bearing preload first, then adjust the side bearing preload.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "When the preload torque is large", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "On pinion bearings:", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Replace the collapsible spacer.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "On side bearings:", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Use thinner side bearing adjusting shims. For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "When the preload is small", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Tighten the drive pinion nut.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Use thicker side bearing adjusting shims. For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "DRIVE GEAR RUNOUT", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "Remove rear cover. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Following the procedure below, install the dummy cover set [SST: KV389L0010 ( — )] to gear carrier.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Set dummy cover shims to the right and left side bearing adjusting shims.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Temporarily tighten dummy cover to gear carrier.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Position dummy cover spacers to dummy cover.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Tighten rear cover mounting bolts to the specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Tighten dummy cover spacer mounting bolts evenly to the specified torque.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", ": 5.9 N·m (0.6 kg-m, 52 in-lb)", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Fit a dial indicator (A) to the drive gear back face.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", ": Dummy cover set [SST: KV389L0010 ( — )]", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Rotate the drive gear to measure runout.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Drive gear back face runout", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "If the runout is outside of the repair limit, check drive gear assembly condition; foreign material may be caught between drive gear and differential case, or differential case or drive gear may be deformed, etc.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Replace drive gear and drive pinion as a set.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "TOOTH CONTACT", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "Apply red lead or equivalent to drive gear.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Apply red lead or equivalent to both the faces of 3 to 4 gears at 4 locations evenly spaced on drive gear.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Rotate drive gear back and forth several times, check drive pinion gear to drive gear tooth contact.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Check tooth contact on drive side and reverse side.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Tooth Contact Judgment Guide", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "If tooth contact is improperly adjusted, follow the procedure below to adjust the pinion height (dimension X).", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "If the tooth contact is near the face (face contact), or near the heel (heel contact), thicken drive pinion gear adjusting shim to move drive pinion closer to drive gear.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "If the tooth contact is near the flank (flank contact), or near the toe (toe contact), thin drive pinion gear adjusting shim to move drive pinion farther from drive gear.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "BACKLASH", "title");
si[i++] = gsitm("N5040306L0001800ENG.html", "Fit a dial indicator (A) to the drive gear face to measure the backlash.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Backlash", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "If the backlash is outside of the specified value, change the thickness of side bearing adjusting shims.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "When the backlash is large:", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Make drive gear back adjusting shims thicker, and drive gear front adjusting shims thinner. For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "When the backlash is small:", "ptxt");
si[i++] = gsitm("N5040306L0001800ENG.html", "Make drive gear back adjusting shims thinner, and drive gear front adjusting shims thicker. For selecting adjusting shim, refer to the latest parts information.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Drive Gear and Drive Pinion", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Clean up the disassembled parts.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If the gear teeth never mesh or line-up correctly, determine the cause and adjust or replace as necessary.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If the gears are worn, cracked, damaged, pitted or chipped (by friction) noticeably, replace with new drive gear and drive pinion as a set.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Bearing", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If any chipped (by friction), pitted, worn, rusted or scratched marks, or unusual noise from the bearing is observed, replace as a bearing assembly (as a new set).", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Oil Seal", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Whenever disassembled, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If wear, deterioration of adherence (sealing force lips), or damage is detected on the lips, replace them.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "Differential Assembly", "title");
si[i++] = gsitm("N5040301W0003N00ENG.html", "DIFFERENTIAL CASE", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If any wear or crack on the contact sides of the differential case is found, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "SIDE GEAR AND PINION MATE GEAR", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If any cracks or damage on the surface of the tooth is found, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If any worn or chipped mark on the contact sides of the thrust washer is found, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "SIDE GEAR THRUST WASHER AND PINION MATE THRUST WASHER", "ptxt");
si[i++] = gsitm("N5040301W0003N00ENG.html", "If it is chipped (by friction), damaged, or unusually worn, replace.", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Exploded View", "title");
