si[i++] = gsitm("N5040306B0006O00ENG.html", "Collapsible spacer", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Drive pinion adjusting shim", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Pinion rear bearing", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Drive pinion", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Drive gear", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Differential case", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Side bearing", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Side bearing adjusting shim", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Side oil seal", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Rear cover", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Stud bolt", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Pinion mate thrust washer", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Pinion mate gear", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Side gear thrust washer", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Side gear", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Pinion mate shaft", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Lock pin", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Outer circumference", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "Screw hole", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": Select with proper thickness.", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "1: Apply gear oil.", "par1");
si[i++] = gsitm("N5040306B0006O00ENG.html", "2: Apply electro-hydraulic coupling oil (Genuine part).", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", "*: Apply anti-corrosion oil.", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": Apply Genuine Silicone RTV or equivalent. Recommended Chemical Products and Sealants: Permatex Ultra Grey 82194, ThreeBond 1207, 1215, 1216, 1217F, 1217G and 1217H or Nissan RTV Part No. 999MP-A7007.", "ptxt");
si[i++] = gsitm("N5040306B0006O00ENG.html", ": Apply Genuine High Strength Thread Locking Sealant or equivalent. Recommended Chemical Products and Sealants: Permatex 27200, ThreeBond 1360, 1360N, 1305 N&P, 1307N, 1335, 1335B, 1363B, 1377C, 1386B, D&E and 1388 or Loctite 648.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5040306I0002500ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove electro-hydraulic coupling assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove differential assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove drive pinion oil seal, using oil seal remover (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Fit drive pinion socket (A) onto drive pinion spline. Remove drive pinion lock nut, using the pinion nut wrench (B).", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Drive pinion socket [SST: KV38109300 ( — )]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Pinion nut wrench [SST: KV38109900 (J-53029)]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Press drive pinion assembly out of gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never drop drive pinion assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove pinion front bearing inner race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove collapsible spacer.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove pinion rear bearing inner race from drive pinion, using the separator (A) and the puller (B).", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Separator (commercial service tool)", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Puller (commercial service tool)", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Using a brass rod or equivalent (A), tap pinion front bearing outer race evenly from the 2 cutouts on gear carrier and remove pinion front bearing outer race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Be careful not to damage gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Using a brass rod or equivalent (A), tap drive pinion adjusting shim evenly from the 2 cutouts on gear carrier and remove drive pinion adjusting shim and pinion rear bearing outer race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040306I0002500ENG.html", "Install a drive pinion adjusting shim of the same thickness as was installed prior to disassembly. Press pinion rear bearing outer race into gear carrier, using the drift (A) [SST: ST33200000 (J-26082)].", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "At first, using a hammer, tap bearing outer race until it becomes flush to gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse pinion rear bearing outer race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Press pinion front bearing outer race into gear carrier, using the drift (A) [SST: ST33230000 (J-25805-01)].", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse pinion front bearing outer race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Press pinion rear bearing inner race to drive pinion, using the drift (A) [SST: ST23860000 ( — )].", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse pinion rear bearing inner race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Check and adjust the tooth contact and back lash of drive gear and drive pinion following the procedure below.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Assemble drive pinion into gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never assemble collapsible spacer.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Apply gear oil to pinion rear bearing.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Assemble pinion front bearing inner race to drive pinion assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse pinion front bearing inner race.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Apply gear oil to pinion front bearing.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Using the drifts (A and C) and press stand (B), press pinion front bearing inner race to drive pinion as far as drive pinion lock nut can be tightened.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Drift [SST: KV40100610 (J-26089)]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Press stand [SST: ST38220000 ( — )]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "C", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Drift [SST: ST23860000 ( — )]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Temporarily tighten removed drive pinion lock nut to drive pinion.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Use removed drive pinion lock nut only for the preload measurement.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Rotate drive pinion more than 20 times to adjust bearing.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Fit the drive pinion socket (A) onto the drive pinion. Using the pinion nut wrench (B), tighten drive pinion lock nut holding drive pinion, while adjusting pinion bearing preload torque using preload gauge (C).", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Preload gauge [SST: ST3127S000 (J-25765-A)]", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Pinion bearing preload", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Drive pinion lock nut is tightened with no collapsible spacer. Be careful not to overtighten it. While measuring the preload, tighten it by 5° to 10°.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Install new side bearing adjusting shims (left side: two pieces, right side: one piece) with the same thickness or re-install the old ones to the same mounting position they were in prior to disassembly. Install differential assembly to gear carrier. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Apply differential gear oil to the side bearings.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Check and adjust tooth contact, drive gear to drive pinion backlash. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove differential assembly.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove drive pinion assembly from gear carrier", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove drive pinion nut and press drive pinion assembly out of gear carrier.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Assemble collapsible spacer  to drive pinion .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Be careful of the mounting direction of collapsible spacer.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse collapsible spacer.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Apply anti-corrosion oil to the thread and seat of drive pinion lock nut, and temporarily tighten drive pinion lock nut to drive pinion.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse drive pinion lock nut.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Fit the drive pinion socket (A) onto the drive pinion. While holding drive pinion, tighten drive pinion lock nut within the limits of specified torque so as to keep the pinion bearing preload within a standard values, using the pinion nut wrench (B) and the preload gauge (C).", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Drive pinion lock nut tightening torque", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Adjust the lower limit of the drive pinion lock nut tightening torque first.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "If the preload torque exceeds the specified value, replace collapsible spacer and tighten it again to adjust. Never loose n drive pinion lock nut to adjust the preload torque.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "After adjustment, rotate drive pinion back and forth 2 to 3 times to check for unusual noise, rotation malfunction, and other malfunctions.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Install differential assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never install rear cover at this timing.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Check and adjust drive gear runout, tooth contact, and drive gear to drive pinion backlash. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Remove dummy cover set, then install rear cover, and side oil seal. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Check total preload torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Using the drift (A) (commercial service tool), install drive pinion oil seal  within the dimension (D) shown as follows.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "D", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", ": 0 ±0.2 mm (0 ±0.008 in)", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Never reuse oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "When installing, never incline oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Check that the oil seal lip is filled up with grease.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Apply gear oil lightly and evenly onto the outer circumference of oil seal.", "ptxt");
si[i++] = gsitm("N5040306I0002500ENG.html", "Install electro-hydraulic coupling assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040301W0003O00ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Drive Gear and Drive Pinion", "title");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Clean up the disassembled parts.", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "If the gear teeth never mesh or line-up correctly, determine the cause and adjust or replace as necessary.", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "If the gears are worn, cracked, damaged, pitted or chipped (by friction) noticeably, replace with new drive gear and drive pinion as a set.", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Bearing", "title");
si[i++] = gsitm("N5040301W0003O00ENG.html", "If any chipped (by friction), pitted, worn, rusted or scratched marks, or unusual noise from the bearing is observed, replace as a bearing assembly (as a new set).", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Oil Seal", "title");
si[i++] = gsitm("N5040301W0003O00ENG.html", "Whenever disassembled, replace.", "ptxt");
si[i++] = gsitm("N5040301W0003O00ENG.html", "If wear, deterioration of adherence (sealing force lips), or damage is detected on the lips, replace them.", "ptxt");
