si[i++] = gsitm("N5040401X0002Z00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "COMPONENT PART", "title");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "Make sure that the mounting conditions (looseness, backlash) of each component and component conditions (wear, damage) are normal.", "ptxt");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "WHEEL HUB ASSEMBLY (BEARING-INTEGRATED TYPE)", "title");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "Check the following items, and replace the part if necessary.", "ptxt");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "Move wheel hub and bearing assembly in the axial direction by hand. Check there is no looseness of wheel bearing.", "ptxt");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "Axial end play", "ptxt");
si[i++] = gsitm("N5040401X0002Z00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0002Z00ENG.html", "Rotate wheel hub and make sure there is no unusual noise or other irregular conditions. If there is any of irregular conditions, replace wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040401X0003000ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040401X0003000ENG.html", "FRONT DRIVE SHAFT INSPECTION", "title");
si[i++] = gsitm("N5040401X0003000ENG.html", "Check the following items, and replace the part if necessary.", "ptxt");
si[i++] = gsitm("N5040401X0003000ENG.html", "Check drive shaft mounting point and joint for looseness and other damage.", "ptxt");
si[i++] = gsitm("N5040401X0003000ENG.html", "Replace entire drive shaft assembly when noise or vibration occur from drive shaft.", "ptxt");
si[i++] = gsitm("N5040401X0003000ENG.html", "Check boot for cracks and other damage.", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Steering knuckle", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Splash guard", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Hub bolt", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Wheel hub and bearing assembly", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Disc rotor", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", "Wheel hub lock nut", "ptxt");
si[i++] = gsitm("N5040404D0001D00ENG.html", ": Comply with the installation procedure when tightening. Refer to .", "par4");
si[i++] = gsitm("N5040404D0001D00ENG.html", ": N·m (kg-m, ft-lb)", "par1");
si[i++] = gsitm("N5040404D0001D00ENG.html", ": Always replace after every disassembly.", "par2");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove tires. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove front wheel sensor from steering knuckle. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove lock plate from strut assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove brake caliper assembly. Hang brake caliper assembly in a place where it will not interfere with work. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never depress brake pedal while brake caliper is removed.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove disc rotor.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Put matching marks  on the wheel hub assembly and the disc rotor before removing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never drop disc rotor.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Using lock nut chisel (SST: KV40108800) (A), release stacked area of wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Stacked area is about 22.5 mm (0.886 in) (A) of wheel hub lock nut .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Loosen wheel hub lock nut, using a hub lock nut wrench (SST: KV40104000) (A).", "par1");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never use a power tool.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "When rotation of locknut does not turn smoothly, release stacked area is performed again.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Patch wheel hub lock nut with a piece of wood. Hammer the wood to disengage wheel hub from drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never place drive shaft joint at an extreme angle.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Also be careful not to overextend slide joint.", "par8");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never allow drive shaft to hang down without support for joint sub-assembly, shaft and the other parts.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Use suitable puller, if wheel hub and drive shaft cannot be separated even after performing the above procedure.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove wheel hub and bearing assembly and splash guard.", "par9");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove steering outer socket from steering knuckle so as not to damage ball joint boot using a ball joint remover (commercial service tool) (A).", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Temporarily tighten the nut to prevent damage to threads and to prevent the ball joint remover from sudden drop turning.", "par22");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never damage the boot of ball joint.", "par23");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove front stabilizer connecting rod.", "par6");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove transverse link mounting bolts and nuts (lower side).from. Refer to .", "par7");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Separate the connection of transverse link and steering knuckle (lower side).", "par10");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove cowl top cover. Refer to .", "par21");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove front strut assembly and steering knuckle.", "par11");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Separate the connection of front strut assembly and steering knuckle as follows.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Be sure to keep the following procedure because steering knuckle may be damaged when you enlarge the gap of steering knuckle too much.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove strut mounting bolt and nut from steering knuckle.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Measure the gap (A) of the steering knuckle. And then mark the enlarged limit (B) to the chisel.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Marking", "par15");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Enlarged limit (B) = gap (A) + 2.5 mm (0.098 in)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Standard of gap: 6.9 ± 0.5 mm (0.272 ± 0.020 in)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Enlarge the gap of the steering knuckle with the chisel (A) (commercial service tool) not to surpass a limit as shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never enlarge the gap more than 2.5 mm (0.098 in).", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Be careful not to damage the projection  and strut assembly  with the chisel.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Separate the connection of strut assembly and steering knuckle.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Be sure to remove lubricants if lubricant has been used to separate the connection of strut assembly and steering knuckle.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove hub bolts  from wheel hub , using the ball joint remover (commercial service tool) (A).", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Remove hub bolt only when necessary.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never hammer the hub bolt to avoid impact to the wheel bearing.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Pull out the hub bolt in a direction perpendicular to the wheel hub.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Note the following, and install in the reverse order of the removal.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Hub Bolts", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Place a washer  as shown in the figure to install the hub bolts  by using the tightening force of the nut .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Check that there is no clearance between wheel hub, and hub bolt.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never reuse hub bolt.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Drive shaft", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Clean the matching surface of wheel hub lock nut and wheel hub.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never apply lubricating oil to these matching surface.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Clean the matching surface of drive shaft, wheel hub, and wheel bearing. And then apply grease [service parts MS991241] to surface  of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Apply paste to cover entire flat surface of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Amount paste", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "1.0 – 3.0 g (0.04 – 0.10 oz)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "When installing drive shaft to wheel hub.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never overlap drive shaft stacked area  and hub bolts .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Use the following torque range for tightening the wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", ": 240.0– 270.0 N·m (24.5 – 27.6 kg-m, 177.1– 199.1 ft-lb)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Since the drive shaft is assembled by press-fitting, use the tightening torque range for the wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Be sure to use torque wrench to tighten the wheel hub lock nut. Never use a power tool.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Never reuse wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Wheel hub lock nut tightening torque does not over torque for avoiding axle noise, and does not less than torque for avoiding looseness.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Using lock nut crimp punch (SST: KV40108700) (A), stake wheel hub lock nut and drive shaft staked area.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Use the following range for stacking the wheel hub lock nut .", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", ": 6.2 mm (0.244 in)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", ": 26.4 – 27.8 mm (1.039 – 1.094 in)", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Disc rotor", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Align the matching marks  made during removal when reusing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Strut Assembly and Steering Knuckle Connection", "title");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Install the steering knuckle to strut assembly as follows.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Set suitable jack under steering knuckle.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Align the gap  of steering knuckle to the projection part  of strut.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Tighten the mounting bolt and nut with pushing up the steering knuckle  until contacts stopper bracket  end face, using a suitable jack.", "ptxt");
si[i++] = gsitm("N5040404E0001P00ENG.html", "Check the stable condition when using a jack.", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Inspection", "title");
