si[i++] = gsitm("N5040401X0003100ENG.html", "Check components for deformation, cracks, and other damage.", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Check boots of transverse link and steering outer socket ball joint for breakage, axial end play, and swing torque.", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Transverse link: Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Steering outer socket: Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040401X0003100ENG.html", "Check runout of disc rotor, when replaced the disc rotor. Refer to .", "par1");
si[i++] = gsitm("N5040401X0003100ENG.html", "Check wheel sensor harness for proper connection. Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Check the wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003100ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
