si[i++] = gsitm("N5040404E0001Q00ENG.html", "Transaxle Side", "title");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Remove boot after removing drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Clean the old grease on joint sub-assembly with paper waste.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Fill serration slot joint sub-assembly  with Mitsubishi Motors genuine grease or equivalent until the serration slot and ball groove become full to the brim.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "After applying grease, use a shop cloth to wipe off old grease that has oozed out.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Install boot and boot bands to shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Never reuse boot and boot band.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Wrap serration on shaft with tape  to protect the boot from damage.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Fill into the boot inside with the specified amount of grease from large diameter side of boot.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Grease amount", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", ": Refer to Drive Shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Install the boot securely into grooves (indicated by “*” marks) shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "If grease adheres to the boot mounting surface (indicated by “*” mark) on the shaft or joint subassembly. boot may be removed. Remove all grease from the boot mounting surface.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "To prevent the deformation of the boot, adjust the boot installation length (L) to the specified value shown below by inserting the suitable tool into the inside of the boot from the large diameter side of the boot and discharging the inside air.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "L", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "If the boot mounting length exceeds the standard, it may cause breakage in the boot.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Be careful not to touch the inside of the boot with a tip of tool.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Secure the large and small ends of the boot with boot bands using the boot band crimping tool (A) (SST: KV40107300).", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Never reuse boot band.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Secure boot band so that dimension (M) meets the specification as shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "M", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", ": 1.0 – 4.0 mm (0.039 – 0.157 in)", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Check that displacement does not occur when boot is rotated with the joint sub-assembly and shaft fixed.", "ptxt");
si[i++] = gsitm("N5040404E0001Q00ENG.html", "Reinstall them using boot bands when boot installation positions become incorrect.", "ptxt");
