si[i++] = gsitm("N5040404D0001E00ENG.html", "1: Fill Mitsubishi Genuine grease or equivalent.", "ptxt");
si[i++] = gsitm("N5040404D0001E00ENG.html", "2: Apply paste [service parts (440037S000)]", "ptxt");
si[i++] = gsitm("N5040404D0001E00ENG.html", ": Always replace after every disassembly", "par1");
si[i++] = gsitm("N5040404D0001E00ENG.html", "RIGHT SIDE", "title");
si[i++] = gsitm("N5040404D0001E00ENG.html", "Support bearing bracket", "ptxt");
si[i++] = gsitm("N5040404D0001E00ENG.html", "Support bearing", "ptxt");
si[i++] = gsitm("N5040404D0001E00ENG.html", ": N·m (kg-m, ft-lb)", "par2");
si[i++] = gsitm("N5040404D0001E00ENG.html", "2: Apply paste [service parts (440037S000)].", "ptxt");
