si[i++] = gsitm("N5040404E0001R00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5040404E0001R00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Left Side", "title");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove tires. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove engine under cover. Refer to .", "par22");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove lock plate from strut assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Release stacked area of wheel hub lock nut. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Loosen wheel hub lock nut using a hub lock nut wrench (A) (SST: KV40104000). Refer to", "par6");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Patch hub lock nut with a piece of wood. Hammer the wood to disengage wheel hub from drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never place drive shaft joint at an extreme angle.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Also be careful not to overextend slide joint.", "par1");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never allow drive shaft to hang down without support for joint sub assembly, shaft and the other parts.", "par5");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Use suitable puller, if wheel hub and bearing assembly and drive shaft cannot be separated even after performing the above procedure.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Separate transverse link from steering knuckle (lower side). Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove drive shaft from wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Remove drive shaft from transaxle assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Use the drive shaft attachment (A) (SST: KV40107500) and a sliding hammer (B) (commercial service tool) while inserting tip of the drive shaft attachment between housing and transaxle assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never place drive shaft joint at an extreme angle when removing drive shaft. Also be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Confirm that the circular clip is attached to the drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Right Side", "title");
si[i++] = gsitm("N5040404E0001R00ENG.html", "If necessary, remove the catalyst bracket, support bearing bracket mounting bolts and the support bearing bracket.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Always replace differential side oil seal with new one when installing drive shaft. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Place the protector (A) (SST: KV38107900) onto transaxle assembly to prevent damage to the differential side oil seal while inserting drive shaft. Slide drive shaft sliding joint and tap with a hammer to install securely.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Ensure that circular clip is properly engaged, otherwise the joint sub-assembly could pull away from transaxle during vehicle operation resulting in loss of drive force and possible drive shaft damage, which may cause a crash and serious injury or damage the drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "To ensure the circular clip is properly engaged, grasp the housing  and pull back and forth in axial direction while listening for clicking sounds.", "par2");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": Wheel side", "par31");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Pull the joint sub-assembly in the axial direction away from transaxle assembly (arrow). Confirm that the joint sub assembly cannot be pulled out.", "par3");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Clean the matching surface of wheel hub lock nut and wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never apply lubricating oil to these matching surface.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Clean the matching surface of drive shaft and wheel hub and bearing assembly. And then apply paste [service parts (440037S000)] to surface  of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Apply paste to cover entire flat surface of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Amount paste", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 1.0 – 3.0 g (0.04 – 0.10 oz)", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Tighten the wheel hub lock nut to the specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Since the drive shaft is assembled by press-fitting, use the tightening torque range for the wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Be sure to use torque wrench to tighten the wheel hub lock nut. Never use a power tool.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never reuse wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Insert drive shaft to wheel hub, and then temporarily tighten hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never overlap drive shaft stacked area  and wheel hub bolts .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Tighten the wheel hub lock nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 240.0 – 270.0 N·m (24.5 – 27.6 kg-m, 177.1 – 199.1 ft-lb)", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Wheel hub lock nut tightening torque does not over torque for avoiding axle noise, and does not less than torque for avoiding looseness.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Using lock nut crimp punch (SST: KV40108700) (A), stake wheel hub lock nut and drive shaft staked area.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Use the following range for stacking the wheel hub lock nut .", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 6.2 mm (0.244 in)", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 26.4 – 27.8 mm (1.039 – 1.094 in)", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Never reuse differential side oil seal.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "When installing support bearing bracket tighten the mounting bolt with the following procedure.", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "To install support bearing bracket  and mounting bolts, temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Temporary tightening", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 1 → 2 → 3", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "Final tightening (Specified torque)", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", ": 4 → 5 → 6", "ptxt");
si[i++] = gsitm("N5040404E0001R00ENG.html", "After inserting the drive shaft  into correct position in the bearing bracket , completely tighten bolt .", "par28");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Transaxle Assembly Side", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Fix shaft with a vise.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Protect shaft using aluminum or copper plates when fixing with a vise.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove boot bands, and then remove boot from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove stopper ring.", "ptxt");
