si[i++] = gsitm("N5040404G0000L00ENG.html", "Use paint or an equivalent for matching marks. Never scratch the surfaces.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Put matching marks  on the spider assembly and shaft.", "ptxt");
