si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove boot from shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove circular clip from housing (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove dust shield from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Clean old grease on housing with paper waste.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Support Bearing", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove snap ring .", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Press out support bearing from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove dust shield.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Wrap serration on shaft with tape  to protect boot from damage. Install new boot and boot bands to shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse boot and boot band.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Remove the tape wrapped around the serration on shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "To install the spider assembly , align it with the matching marks  on the shaft  put during the removal, and direct the serration mounting surface  to the shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Secure spider assembly onto shaft with snap ring .", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse snap ring.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Apply the appropriate amount of grease to spider assembly and sliding surface.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Assemble the housing onto spider assembly, and apply the balance of the specified amount grease.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Grease amount", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", ": Refer to Drive Shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Align matching marks put during the removal of housing.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install stopper ring.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse stopper ring.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install boot securely into grooves (indicated by “*” marks) shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "If grease adheres to the boot mounting surface (indicated by “*” mark) on shaft or housing, boot may be removed. Remove all grease from the surface.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "To prevent from deformation of the boot, adjust the boot installation length to the value shown below (L) by inserting the suitable tool into the inside of boot from the large diameter side of boot and discharging inside air.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "L", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "If the boot installation length exceeds the standard, it may cause breakage in boot.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Be careful not to touch the inside of the boot with the tip of tool.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Secure the large and small ends of the boot with boot bands using the boot band crimping tool (A) (SST: KV40107300).", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse boot band.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Secure boot band so that dimension (M) meets the specification as shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "M", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", ": 1.0 – 4.0 mm (0.039 – 0.157 in)", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Secure housing and shaft, and then make sure that they are in the correct position when rotating boot. Install them with new boot band when the mounting positions become incorrect.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install dust shield (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse dust shield.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install circular clip to housing (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse circular clip.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install dust shield on housing.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Press support bearing  onto housing to using the suitable tool (A).", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install snap ring.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Install dust shields.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Never reuse dust shields.", "ptxt");
si[i++] = gsitm("N5040404G0000L00ENG.html", "Wheel Side", "title");
si[i++] = gsitm("N5040404G0000L00ENG.html", "For further details, refer to the installation procedure of “” for the drive shaft boot.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Move joint up/down, left/right, and in the axial directions. Check for motion that is not smooth and for significant looseness.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check boot for cracks, damage, and leakage of grease.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Disassemble drive shaft and exchange malfunctioning part if there is a non-standard condition.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Shaft", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check shaft for runout, cracks, or other damage. Replace if there are.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Joint Sub-Assembly (Wheel Side)", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Joint sub-assembly for rough rotation and excessive axial looseness", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "The inside of the joint sub-assembly for entry of foreign material", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Joint sub-assembly for compression scars, cracks, and fractures inside of joint sub-assembly", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Replace joint sub-assembly if there are any non-standard conditions of components.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Housing and Spider assembly (Transaxle Side)", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Replace housing and spider assembly if there is scratching or wear of housing roller contact surface or spider roller contact surface.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Housing and spider assembly are used in a set.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Support Bearing (Right Side)", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Make sure wheel bearing rolls freely and is free from noise, cracks, pitting or wear. Replace support bearing if there are any non-standard conditions.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Support Bearing Bracket (Right Side)", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check for bending, cracks, or damage. Replace support bearing bracket if there are any non-standard conditions.", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check wheel sensor harness for proper connection.  Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Check the wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003300ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5040404I0000L00ENG.html", "Drive Shaft", "title");
si[i++] = gsitm("N5040404I0000L00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040404I0000L00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5040404I0000L00ENG.html", "Grease quantity", "ptxt");
