si[i++] = gsitm("N5040404I0000L00ENG.html", "Boots installed length*", "ptxt");
si[i++] = gsitm("N5040404I0000L00ENG.html", "141.5 mm (5.57 in)", "ptxt");
si[i++] = gsitm("N5040404I0000L00ENG.html", "175.4 mm (6.91 in)", "ptxt");
si[i++] = gsitm("N5040404J0000L00ENG.html", "Wheel Bearing", "title");
si[i++] = gsitm("N5040404J0000L00ENG.html", "Axial end play", "ptxt");
si[i++] = gsitm("N5040404J0000L00ENG.html", "0.0 mm (0.0 in) or less", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N504040410000W00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N504040410000W00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N504040410000W00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N504040420000T00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N504040420000T00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N504040420000T00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Precautions for Drive Shaft", "title");
si[i++] = gsitm("N504040430000M00ENG.html", "Note the following precautions when disassembling and assembling drive shaft.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Joint sub-assembly does not disassemble because it is non-overhaul parts.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Perform work in a dust-free location.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Before disassembling and assembling, clean the parts.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Prevent the entry of foreign objects during disassembly of the service location.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Disassembled parts must be carefully reassembled in the correct order. If work is interrupted, a clean cover must be placed over parts.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Paper waste must be used. Fabric shop cloths must not be used because of the danger of lint adhering to parts.", "ptxt");
si[i++] = gsitm("N504040430000M00ENG.html", "Disassembled parts (except for rubber parts) should be cleaned with kerosene which shall be removed by blowing with air or wiping with paper waste.", "ptxt");
si[i++] = gsitm("N504040450000M00ENG.html", "Special Service Tool", "title");
si[i++] = gsitm("N504040450000M00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
