si[i++] = gsitm("N5040401X0003700ENG.html", "Check boots of transverse link and steering outer socket ball joint for breakage, axial end play, and swing torque.", "ptxt");
si[i++] = gsitm("N5040401X0003700ENG.html", "Transverse link: Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5040401X0003700ENG.html", "Steering outer socket: Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003700ENG.html", "INSPECTION AFTER INSTALLATION", "title");
