si[i++] = gsitm("N5040401X0003700ENG.html", "Check the wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003700ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
