si[i++] = gsitm("N5040404D0001G00ENG.html", "Dust shield", "ptxt");
si[i++] = gsitm("N5040404D0001G00ENG.html", "Housing", "ptxt");
si[i++] = gsitm("N5040404D0001G00ENG.html", "Snap ring", "ptxt");
