si[i++] = gsitm("N5040404E0001U00ENG.html", "Remove disc rotor. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Release stacked area of wheel hub lock nut. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Loosen wheel hub lock nut using a hub lock nut wrench (A) (SST: KV40104000). Refer to .", "par6");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Patch hub lock nut with a piece of wood. Hammer the wood to disengage wheel hub from drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never place drive shaft joint at an extreme angle.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Also be careful not to overextend slide joint.", "par1");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never allow drive shaft to hang down without support for joint sub assembly, shaft and the other parts.", "par5");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Use suitable puller, if wheel hub and bearing assembly and drive shaft cannot be separated even after performing the above procedure.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Remove wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Separate transverse link from steering knuckle (lower side). Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Separate steering outer socket from steering knuckle. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Remove drive shaft from wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Remove drive shaft from transaxle assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Use the drive shaft attachment (A) (SST: KV40107500) and a sliding hammer (B) (commercial service tool) while inserting tip of the drive shaft attachment between housing and transaxle assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never place drive shaft joint at an extreme angle when removing drive shaft. Also be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Confirm that the circular clip is attached to the drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Right Side", "title");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Loosen wheel hub lock nut using a hub lock nut wrench (A) (SST: KV40104000).fer  Reto .", "par10");
si[i++] = gsitm("N5040404E0001U00ENG.html", "If necessary, remove the catalyst bracket, support bearing bracket mounting bolts and the support bearing bracket.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Always replace differential side oil seal with new one when installing drive shaft. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Place the protector (A) (SST: KV38107900) onto transaxle assembly to prevent damage to the differential side oil seal while inserting drive shaft. Slide drive shaft sliding joint and tap with a hammer to install securely.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Ensure that circular clip is properly engaged, otherwise the joint sub-assembly could pull away from transaxle during vehicle operation resulting in loss of drive force and possible drive shaft damage, which may cause a crash and serious injury or damage the drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "To ensure the circular clip is properly engaged, grasp the housing  and pull back and forth in axial direction while listening for clicking sounds.", "par2");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": Wheel side", "par30");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Pull the joint sub-assembly in the axial direction away from transaxle assembly (arrow). Confirm that the joint sub assembly cannot be pulled out.", "par3");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Clean the matching surface of wheel hub lock nut and wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never apply lubricating oil to these matching surface.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Clean the matching surface of drive shaft and wheel hub and bearing assembly. And then apply paste [service parts (440037S000)] to surface  of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Apply paste to cover entire flat surface of joint sub-assembly of drive shaft.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Amount paste", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 1.0 – 3.0 g (0.04 – 0.10 oz)", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Insert drive shaft to wheel hub, and then temporarily tighten hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never overlap drive shaft stacked area  and wheel hub bolts .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Tighten the wheel hub lock nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 240.0 – 270.0 N·m (24.5 – 27.6 kg-m, 177.1 – 199.1 ft-lb)", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Since the drive shaft is assembled by press-fitting, use the tightening torque range for the wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Be sure to use torque wrench to tighten the wheel hub lock nut. Never use a power tool.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never reuse wheel hub lock nut.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Wheel hub lock nut tightening torque does not over torque for avoiding axle noise, and does not less than torque for avoiding looseness.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Using lock nut crimp punch (SST: KV40108700) (A), stake wheel hub lock nut and drive shaft staked area.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Use the following range for stacking the wheel hub lock nut .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 6.2 mm (0.244 in)", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 26.4 – 27.8 mm (1.039 – 1.094 in)", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Always replace transfer cover oil seal (outer and inner) with new one when installing drive shaft. Refer to .", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Place the protector (A) (SST: KV38107900) onto transfer assembly to prevent damage to the transfer cover oil seal (inner) and transfer cover oil seal (outer) while inserting drive shaft. Slide drive shaft sliding joint and tap with a hammer to install securely.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Never reuse transfer cover oil seal (inner) and transfer cover oil seal (outer).", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "When installing support bearing bracket tighten the mounting bolt with the following procedure.", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "To install support bearing bracket  and mounting bolts, temporarily tighten the bolts before tightening to the specified torque, referring to the tightening method and the numerical order shown below:", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Temporary tightening", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 1 → 2", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "Final tightening (Specified torque)", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", ": 3 → 4 → 5 → 6 → 7", "ptxt");
si[i++] = gsitm("N5040404E0001U00ENG.html", "After inserting the drive shaft  into correct position in the bearing bracket , completely tighten bolt .", "par28");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5040404G0000M00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Transaxle Assembly Side", "title");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Fix shaft with a vise.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Protect shaft using aluminum or copper plates when fixing with a vise.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove boot bands, and then remove boot from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove stopper ring.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Put matching marks on housing and shaft, and then pull out housing from shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Use paint or an equivalent for matching marks. Never scratch the surfaces.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Put matching marks  on the spider assembly and shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove snap ring , and then remove spider assembly from shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove boot from shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove circular clip from housing (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove dust shield from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Clean old grease on housing with paper waste.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Support Bearing", "title");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove snap ring .", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Press out support bearing from housing.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove dust shield.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Wrap serration on shaft with tape  to protect boot from damage. Install new boot and boot bands to shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse boot and boot band.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Remove the tape wrapped around the serration on shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "To install the spider assembly , align it with the matching marks  on the shaft  put during the removal, and direct the serration mounting surface  to the shaft.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Secure spider assembly onto shaft with snap ring .", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse snap ring.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Apply the appropriate amount of grease to spider assembly and sliding surface.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Assemble the housing onto spider assembly, and apply the balance of the specified amount grease.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Grease amount", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", ": Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Align matching marks put during the removal of housing.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install stopper ring.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse stopper ring.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install boot securely into grooves (indicated by “*” marks) shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "If grease adheres to the boot mounting surface (indicated by “*” mark) on shaft or housing, boot may be removed. Remove all grease from the surface.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "To prevent from deformation of the boot, adjust the boot installation length to the value shown below (L) by inserting the suitable tool into the inside of boot from the large diameter side of boot and discharging inside air.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "L", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "If the boot installation length exceeds the standard, it may cause breakage in boot.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Be careful not to touch the inside of the boot with the tip of tool.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Secure the large and small ends of the boot with boot bands using the boot band crimping tool (A) (SST: KV40107300).", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse boot band.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Secure boot band so that dimension (M) meets the specification as shown in the figure.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "M", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", ": 1.0 – 4.0 mm (0.039 – 0.157 in)", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Secure housing and shaft, and then make sure that they are in the correct position when rotating boot. Install them with new boot band when the mounting positions become incorrect.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install dust shield (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse dust shield.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install circular clip to housing (left side).", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse circular clip.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install dust shield on housing.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Press support bearing  onto housing to using the suitable tool (A).", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install snap ring.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Install dust shields.", "ptxt");
si[i++] = gsitm("N5040404G0000M00ENG.html", "Never reuse dust shields.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Move joint up/down, left/right, and in the axial directions. Check for motion that is not smooth and for significant looseness.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check boot for cracks, damage, and leakage of grease.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Disassemble drive shaft and exchange malfunctioning part if there is a non-standard condition.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Shaft", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check shaft for runout, cracks, or other damage. Replace if there are.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Joint Sub-Assembly (Wheel Side)", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Joint sub-assembly for rough rotation and excessive axial looseness", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "The inside of the joint sub-assembly for entry of foreign material", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Joint sub-assembly for compression scars, cracks, and fractures inside of joint sub-assembly", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Replace joint sub-assembly if there are any non-standard conditions of components.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Housing and Spider assembly (Transaxle Side)", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Replace housing and spider assembly if there is scratching or wear of housing roller contact surface or spider roller contact surface.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Housing and spider assembly are used in a set.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Support Bearing (Right Side)", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Make sure wheel bearing rolls freely and is free from noise, cracks, pitting or wear. Replace support bearing if there are any non-standard conditions.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Support Bearing Bracket (Right Side)", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check for bending, cracks, or damage. Replace support bearing bracket if there are any non-standard conditions.", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check wheel sensor harness for proper connection.  Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Check the wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040401X0003800ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Drive Shaft", "title");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Grease quantity", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Wheel side", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "115 – 135 g (4.06 – 4.76 oz)", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Transaxle side", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "210 – 230 g (7.40 – 8.11 oz)", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "Boots installed length*", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "141.5 mm (5.57 in)", "ptxt");
si[i++] = gsitm("N5040404I0000M00ENG.html", "175.4 mm (6.91 in)", "ptxt");
si[i++] = gsitm("N5040404J0000M00ENG.html", "Wheel Bearing", "title");
si[i++] = gsitm("N5040404J0000M00ENG.html", "Axial end play", "ptxt");
si[i++] = gsitm("N5040404J0000M00ENG.html", "0.0 mm (0.0 in) or less", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5040503N0000U00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5040503N0000U00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
