si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove parking brake actuator harness and rear wheel sensor. Hang parking brake actuator harness and rear wheel sensor not to interfere with work. Refer to .", "par9");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove caliper assembly. Hang caliper assembly in a place where it will not interfere with work. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Never depress brake pedal while brake caliper is removed.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Put matching marks  on the wheel hub and bearing assembly and the disc rotor before removing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Never drop disc rotor.", "ptxt");
