si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove rear suspension arm mounting bolts and nuts  from axle housing .", "par4");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Separate rear suspension arm, and then remove axle housing.", "par2");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove hub bolts  from wheel hub and bearing assembly, using the ball joint remover (A) (commercial service tool).", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Remove hub bolt only when necessary.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Never hammer the hub bolt to avoid impact to the wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Pull out the hub bolt in a direction perpendicular to the wheel hub and bearing assembly.", "ptxt");
