si[i++] = gsitm("N5040503V0000V00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Place a washer  as shown in the figure to install the hub bolts  by using the tightening force of the nut .", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Check that there is no clearance between wheel hub and bearing assembly and hub bolt.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Never reuse hub bolt.", "ptxt");
si[i++] = gsitm("N5040503V0000V00ENG.html", "Align the matching marks  made during removal when reusing the disc rotor.", "ptxt");
