si[i++] = gsitm("N5040501V0001X00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040501V0001X00ENG.html", "Check wheel sensor harness for proper connection. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0001X00ENG.html", "If pressing the piston of rear brake caliper assembly, perform \"REMOVAL/REPLACEMENT OF REAR BRAKE PAD OR REAR BRAKE CALIPER\". Refer to .", "ptxt");
