si[i++] = gsitm("N5040503V0000W00ENG.html", "Align the matching marks  made during removal when reusing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000W00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002000ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040501V0002000ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040501V0002000ENG.html", "Check wheel hub and bearing assembly for wear, cracks, and damage. Replace if there are.", "ptxt");
si[i++] = gsitm("N5040501V0002000ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040501V0002000ENG.html", "Check wheel sensor harness for proper connection. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002000ENG.html", "If pressing the piston of rear brake caliper assembly, perform \"REMOVAL/REPLACEMENT OF REAR BRAKE PAD OR REAR BRAKE CALIPER\". Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002000ENG.html", "Check wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002000ENG.html", "Adjust neutral position of steering angle sensor. Refer to Description.", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Circular clip", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Dust shield", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Housing", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Snap ring", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Spider assembly", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Boot band", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Boot", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", "Drive shaft", "ptxt");
si[i++] = gsitm("N5040503U0000X00ENG.html", ": Wheel side", "par3");
si[i++] = gsitm("N5040503U0000X00ENG.html", ": Fill Mitsubishi Motors genuine grease or an equivalent.", "par2");
si[i++] = gsitm("N5040503U0000X00ENG.html", ": Always replace after every disassembly.", "par1");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5040503V0000X00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove tires. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove wheel sensor from wheel hub and bearing assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove caliper assembly. Hang caliper assembly in a place where it will not interfere with work. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Never depress brake pedal while brake caliper is removed.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove disc rotor. If disc rotor cannot be removed, remove as follows.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Parking brake completely in the released position.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Put matching marks  on the wheel hub and bearing assembly and the disc rotor before removing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Never drop disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove cotter pin, and then loosen wheel hub lock nut, using a wheel hub lock nut wrench (A) (SST: KV40104000).", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Patch hub lock nut with a piece of wood. Hammer the wood to disengage wheel hub and bearing assembly from drive shaft.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Use suitable puller, if wheel hub and bearing assembly and drive shaft cannot be separated even after performing the above procedure.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove wheel hub and bearing assembly.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove parking brake assembly only when necessary.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove back plate.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove hub cap.", "par1");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Remove the rear drive shaft from the rear final drive.", "par2");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Use the drive shaft attachment (A) (SST: KV40107500) and a sliding hammer (B) while inserting tip of the drive shaft attachment between housing and final drive assembly.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Never place drive shaft joint at an extreme angle when removing drive shaft. Also be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Confirm that the circular clip is attached to the drive shaft.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Always replace side oil seal with new one when installing drive shaft. Refer to Exploded View.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Place the protector (A) (SST: KV38107900) onto final drive  assembly to prevent damage to the side oil seal while inserting drive shaft. Slide drive shaft sliding joint and tap with a hammer to install securely.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Check that circular clip is completely engaged.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Never reuse side oil seal.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Align the matching marks  made during removal when reusing the disc rotor.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Perform final tightening of bolts and nuts at suspension arm (rubber bushing), under unladen conditions with tires on level ground.", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Tighten the wheel hub lock nut to the specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N5040503V0000X00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N504050440000B00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N504050440000B00ENG.html", "Final Drive Side", "title");
si[i++] = gsitm("N504050440000B00ENG.html", "Fix shaft with a vise.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Protect shaft using aluminum or copper plates when fixing with a vise.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove boot bands, and then remove boot from housing.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Put matching marks on housing and shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Use paint or an equivalent for matching marks. Never scratch the surface.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Put matching marks  on the spider assembly and shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove snap ring , and then remove spider assembly from shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove boot from shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove circular clip housing.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove dust shield to housing.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove old grease on housing with paper towels.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N504050440000B00ENG.html", "Final drive Side", "title");
si[i++] = gsitm("N504050440000B00ENG.html", "Wrap serration on shaft with tape  to protect boot from damage. Install new boot and boot band to shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Never reuse boot and boot band.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Remove the tape wrapped around the serrated on shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "To install the spider assembly , align it with the matching marks  on the shaft  during the removal, and direct the serration mounting surface  to the shaft.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Secure spider assembly onto shaft with snap ring .", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Never reuse snap ring.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Assemble the housing onto spider assembly, and apply the balance of the specified amount grease.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Grease amount", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Align matching marks painted when housing were removed.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Install boot securely into grooves (indicated by “*” marks) shown in the figure.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "If there is grease on boot mounting surfaces (indicated by “*” marks) of shaft or housing, boot may be removed. Remove all grease from the surfaces.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "To prevent from deformation of the boot, adjust the boot installation length to the value shown below (L) by inserting the suitable tool into the inside of boot from the large diameter side of boot and discharging inside air.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "L", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "If the boot installation length exceeds the standard, it may cause breakage in boot.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Be careful not to touch the inside of the boot with the tip of tool.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Install new boot bands securely.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Never reuse boot band.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "For low profile type band", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Put boot band in the groove on drive shaft boot. Then fit pawls () into holes to temporary installation.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "For the large diameter side, fit projection  and guide slit  at first.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Pinch projection on the band with suitable pliers to tighten band.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Insert tip of band below end of the pawl.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "For omege type band", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Secure the boot bands using the boot band crimping tool (A) (SST: KV40107300).", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Secure boot band so that dimension (M) meets the specification as shown in the figure.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "M", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", ": 2.3 mm (0.091 in) max", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Secure housing and shaft, and then make sure that they are in the correct position when rotating boot. Install them with new boot band when the mounting positions become incorrect.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Install dust shield to housing.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Never reuse dust shield.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Install circular clip to housing.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Never reuse circular clip.", "ptxt");
si[i++] = gsitm("N504050440000B00ENG.html", "Perform inspection after assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Inspection", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Move joint up/down, left/right, and in the axial direction. Check for motion that is not smooth and for significant looseness.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Check boot for cracks or other damage, and also for grease leakage.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "If a malfunction is found, disassemble drive shaft, and then replace with new one.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Shaft", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Check shaft for runout, cracks, or other damage. Replace if there are any abnormal condition.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Joint Sub-Assembly (Wheel Side)", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Joint sub-assembly for rough rotation and excessive axial looseness.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "The inside of the joint sub-assembly for entry of foreign material.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Joint sub-assembly for compression scars, cracks, and fractures inside of joint sub-assembly.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Replace joint sub-assembly if there are any non-standard conditions of components.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Housing and Spider assembly (Final Drive Side)", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Replace housing and spider assembly if there is scratching or wear of housing roller contact surface or spider roller contact surface.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Housing and spider assembly are used in a set.", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5040501V0002100ENG.html", "Check wheel sensor harness for proper connection. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "If pressing the piston of rear brake caliper assembly, perform \"REMOVAL/REPLACEMENT OF REAR BRAKE PAD OR REAR BRAKE CALIPER\". Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Check wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5040501V0002100ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5040503X0000M00ENG.html", "Wheel Bearing", "title");
si[i++] = gsitm("N5040503X0000M00ENG.html", "Axial end play", "ptxt");
si[i++] = gsitm("N5040503X0000M00ENG.html", "0.05 mm (0.002 in) or less", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Drive Shaft", "title");
si[i++] = gsitm("N504050450000B00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Grease quantity", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Wheel side", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "52 – 72 g (1.84 – 2.53 oz)", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Final drive side", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "78 – 98 g (2.76 – 3.45 oz)", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "Boots installed length*", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "106.2 – 112.4 mm (4.18 – 4.43 in)", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "136.35 – 140.55 mm (5.37 – 5.53 in)", "ptxt");
si[i++] = gsitm("N504050450000B00ENG.html", "*: For measuring position. Refer to .", "ptxt");
si[i++] = gsitm("N5050103D0000F00ENG.html", "Precaution for Procedure without Cowl Top Cover", "title");
si[i++] = gsitm("N5050103D0000F00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5050103G0001500ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5050103G0001500ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5050103G0001500ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N505010530001600ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N505010530001600ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N505010530001600ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5050103H0000F00ENG.html", "Precautions for Suspension", "title");
si[i++] = gsitm("N5050103H0000F00ENG.html", "When installing rubber bushings, the final tightening must be carried out under unladen conditions with tires on ground. Spilled oil might shorten the life of rubber bushings. Be sure to wipe off any spilled oil.", "ptxt");
si[i++] = gsitm("N5050103H0000F00ENG.html", "Unladen conditions mean that fuel, engine coolant and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N5050103H0000F00ENG.html", "After servicing suspension parts, be sure to check wheel alignment.", "ptxt");
si[i++] = gsitm("N5050103H0000F00ENG.html", "Self-lock nuts are not reusable. Always use new ones when installing. Since new self-lock nuts are pre-oiled, tighten as they are.", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N5050103U0000F00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "Tool number", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "Tool name", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV991040S1", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "CCK gauge attachment", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV99104020 Adapter A", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV99104030 Adapter B", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV99104040 Adapter C", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV99104050 Adapter D", "ptxt");
si[i++] = gsitm("N5050103U0000F00ENG.html", "KV99104060 Plate", "ptxt");
