si[i++] = gsitm("N5050102H0002P00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5050102H0002P00ENG.html", "COMPONENT PART", "title");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Check the front suspension for the following:", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Check each component for looseness or play.", "par1");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Inspect each component for abnormal wear or damage.", "par2");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Ball Joint Axial End Play", "title");
si[i++] = gsitm("N5050102H0002P00ENG.html", "When moving the front tires up and down by hand, place a jack (A) at the rear floor jack lift point to stabilize the vehicle or the vehicle could rock and fall off the lift resulting in serious personal injury or death.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Set front wheels in a straight-ahead position.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Check ball joint boot for cracks or other damage. If there are cracks or other damage, replace transverse link.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Move axle side of transverse link up and down by hand. Check there is no end play.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Never depress brake pedal when measuring.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Never perform with tires on level ground.", "ptxt");
si[i++] = gsitm("N5050102H0002P00ENG.html", "Be careful not to damage ball joint boot. Do not apply excessive force.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5050102H0004P00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5050102H0004P00ENG.html", "The adjustment mechanisms of camber, caster, and kingpin inclination angles are not included.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "If camber, caster, or kingpin inclination angle exceeds the standard value, check front suspension parts for wear and damage. Replace suspect parts if a malfunction is detected.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Kingpin inclination angle is reference value, no inspection is required.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Measure wheel alignment under unladen conditions.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "“Unladen conditions” means that fuel, engine coolant, and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "PRELIMINARY CHECK", "title");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Tires for improper air pressure. Refer to .", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Tires for improper wear.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Road wheels for runout. Refer to .", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Wheel bearing axial end play.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "For 2WD: .", "par1");
si[i++] = gsitm("N5050102H0004P00ENG.html", "For 4WD: Inspection.", "par2");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Transverse link ball joint axial end play. Refer to Inspection .", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Strut operation.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Each mounting part of axle and suspension for looseness and deformation.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Each of suspension member, strut assembly and transverse link for cracks, deformation and other damage.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "GENERAL INFORMATION AND RECOMMENDATIONS", "title");
si[i++] = gsitm("N5050102H0004P00ENG.html", "A four-wheel thrust alignment should be performed.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "This type of alignment is recommended.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "The four-wheel “thrust” process helps ensure that the vehicle is properly aligned and the steering wheel is centered.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "The alignment rack itself should be capable.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "The rack should be checked to ensure that it is level.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Check the machine is properly calibrated.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Your alignment equipment should be regularly calibrated in order to give correct information.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Check with the manufacturer of your specific equipment for their recommended Service/Calibration Schedule.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "ALIGNMENT PROCESS", "title");
si[i++] = gsitm("N5050102H0004P00ENG.html", "IMPORTANT:", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Use only the alignment specifications listed in this Service Manual.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "When displaying the alignment settings, many alignment machines use \"indicators\": (Green/red, plus or minus, Go/No Go). Never use these indicators.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "The alignment specifications programmed into your machine that operate these indicators may not be correct.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "This may result in an ERROR.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Most camera-type alignment machines are equipped with both “Rolling Compensation” method and optional “Jacking Compensation” method to “compensate” the alignment targets or head units. “Rolling Compensation” is the preferred method.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "If using the “Rolling Compensation” method, after installing the alignment targets or head units, push or pull on the rear wheel to move the vehicle. Do not push or pull on the vehicle body.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "If using the “Jacking Compensation” method, after installing the alignment targets or head units, raise the vehicle and rotate the wheels 1/2 turn both ways.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Do not use the “Rolling Compensation” method if you are using sensor-type alignment equipment.", "ptxt");
si[i++] = gsitm("N5050102H0004P00ENG.html", "Follow all instructions for the alignment machine you\'re using for more information.", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Adjustment", "title");
si[i++] = gsitm("N5050100J0000F00ENG.html", "TOE-IN", "title");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Loosen the steering outer socket, and then adjust the length using steering inner socket.", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Toe-in", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Always evenly adjust both toe-in alternately and adjust the difference between the left and right to the standard.", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Always fix the steering inner socket when tightening the steering outer socket.", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "After toe-in adjustment, adjust neutral position of steering angle sensor. Refer to Description.", "ptxt");
si[i++] = gsitm("N5050100J0000F00ENG.html", "Perform steering torque calibration after toe-in adjustment. Refer to .", "par1");
si[i++] = gsitm("N5050100J0000F00ENG.html", "After adjustment, check that the steering angle is within the standard range. Refer to .", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Piston rod lock nut", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Mounting insulator", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Mounting bearing", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Bound bumper", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Upper rubber seat", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Coil spring", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Lower rubber seat", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Strut", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", "Steering knuckle", "ptxt");
si[i++] = gsitm("N5050101X0002B00ENG.html", ": N·m (kg-m, ft-lb)", "par4");
si[i++] = gsitm("N5050101X0002B00ENG.html", ": Always replace after every disassembly.", "par5");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5050103M0003H00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove cowl top cover. Refer to .", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove tires. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove wheel hub lock nut.", "par11");
si[i++] = gsitm("N5050103M0003H00ENG.html", "For 2WD: Refer to .", "par12");
si[i++] = gsitm("N5050103M0003H00ENG.html", "For 4WD: Refer to .", "par13");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove brake hose lock prate. Refer to .", "par10");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove front wheel sensor. Refer to .", "par9");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove brake hose bracket. Refer to .", "par8");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove brake caliper assembly. Hang brake caliper assembly in a place where it will not interfere with work. Refer to", "par7");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Never depress brake pedal while brake caliper is removed.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove disc rotor.", "par6");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove steering outer socket.", "par5");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove trans verse link mounting bolt and nut. Refer to .", "par4");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Separate stabilizer connecting rod from strut assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove the steering knuckle and strut assembly.", "par1");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Separate the connection of strut assembly and steering knuckle as follows.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Be sure to keep the following procedure because steering knuckle may be damaged when you enlarge the gap of steering knuckle too much.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove strut mounting bolts from steering knuckle.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Measure the gap (A) of the steering knuckle. And then mark the enlarged limit (B) to the chisel.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Marking", "par2");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Enlarged limit (B) = gap (A) + 2.5 mm (0.098 in)", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Standard of gap: 6.9 ± 0.5 mm (2.56 ± 0.02 in)", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Enlarge the gap of the steering knuckle with the chisel (A) (commercial service tool) not to surpass a limit as shown in the figure.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Never enlarge the gap more than 2.5mm (0.098in).", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Be careful not to damage the projection  and strut assembly  with the chisel.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Separate the connection of strut assembly and steering knuckle.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Never place drive shaft joint at an extreme angle.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Be careful not to overextend slide joint.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Never allow drive shaft to hang down without support for joint sub-assembly, shaft and the other parts.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Be sure to remove lubricants if lubricant has been used to separate the connection of strut assembly and steering knuckle.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Remove mounting bolt of mounting insulator, and then remove strut assembly.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Strut Assembly", "title");
si[i++] = gsitm("N5050103M0003H00ENG.html", "When installing strut assembly to the vehicle, set the mounting insulator to the direction shown in the figure.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Never reuse strut mounting nut.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Perform final tightening of fixing parts at the vehicle installation position (rubber bushing), under unladen conditions with tires on level ground.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Perform inspection after installation. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "After replacing the strut, always follow the disposal procedure to discard the strut. Refer to .", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Strut Assembly and Steering Knuckle Connection", "title");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Install the steering knuckle to strut assembly as follows.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Set suitable jack under steering knuckle.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Align the gap  of steering knuckle to the projection part  of strut.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Tighten the mounting bolt with pushing up the steering knuckle  until contacts stopper bracket  end face, using a suitable jack.", "ptxt");
si[i++] = gsitm("N5050103M0003H00ENG.html", "Check the stable condition when using a jack.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5050101L0000X00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Never damage strut assembly piston rod when removing components from strut assembly.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install strut attachment (A) (SST: ST35652000) to strut assembly and secure it in a vise.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "When installing the strut attachment to strut assembly, wrap a shop cloth around strut to protect from damage.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Using a spring compressor (A) (commercial service tool), compress coil spring between spring upper seat and lower seat (strut assembly) until coil spring with a spring compressor is free.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Be sure a spring compressor is securely attached to coil spring. Compress coil spring.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Check coil spring with a spring compressor between spring upper seat and lower seat (strut assembly) is free. And then remove piston rod lock nut while securing the piston rod tip so that piston rod does not turn.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Remove mounting insulator, mounting bearing, upper rubber seat and bound bumper from strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "After removing coil spring with a spring compressor (commercial service tool), then gradually release a spring compressor.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Loosen while making sure coil spring attachment position does not move.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Remove lower rubber seat.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Remove strut attachment (A) (SST: ST35652000) from strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Perform inspection after disassembly. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Never damage strut assembly piston rod when installing components from strut assembly.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install strut attachment (SST: ST35652000) to strut and secure it in a vise.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install lower rubber seat with its protrusion  on the lower area aligned with the hole  on the strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Prepare two sets of spring compressors.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Set coil spring so that its paint marks are aligned with the position from the bottom end of the coil spring as shown in the figure.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Identification paint marks", "par14");
si[i++] = gsitm("N5050101L0000X00ENG.html", ": 1.25 turns", "par12");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Be sure to put a mark at the position where the coil spring overlaps with the central axis of the strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Make a mark on the coil spring at positions a, b, and c shown in the figure.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "a: The position where the coil spring overlaps with the central axis of the strut", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "b: The position where the coil spring overlaps with the 180° opposite side of the central axis of the strut", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "c: The position where the coil spring overlaps with the central axis of the strut when seen from direction E", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "2Perform the work with two or more people.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "By using three spring compressors, the coil spring can be assembled while aligning the coil spring with the central axis of the strut, preventing the central axis of the upper end coil of the coil spring from leaning towards the strut rod section. This eliminates uneven contact on the upper rubber seat and also suppresses unbalanced load on the mounting bearing.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Pay attention to the installation position of the spring compressor, as the section from the upper end of the coil spring to 0.75 turns from the upper end makes contact with the upper rubber seat.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install the spring compressor so that it passes over the marked position a and the hook of the spring compressor is at right angles to the coil spring.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "As for the marked position b, install the spring compressor in the same way as for the marked position a.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Then, compress the coil spring gradually and evenly on the right and left sides using the spring compressor until the upper part of the strut rod protrudes by approximately 15 mm.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install the spring compressor so that it passes over the marked position c.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Before the coil spring is compressed, the central axis of the upper end coil of the coil spring and the central axis of the middle part of the coil spring are tilted.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Therefore, the central axis of the upper end coil of the coil spring gets closer to the central axis of the strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Compress the coil spring by using the spring compressor installed in step 7 until the central axis of the upper end coil of the coil spring and the central axis of the strut are aligned.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Be sure to release the three spring compressors evenly and gradually so that the central axis of the upper end coil of the coil spring and the central axis of the strut are not deviated.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Release the spring compressors until the upper pad is in contact with the upper end coil of the spring when the upper part of the strut insulator is lightly pressed by hand.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Install the strut insulator, strut bearing, and upper pad.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "If the upper pad and the upper end coil of the spring do not make contact, remove the upper pad and others and carry out steps 8 and 9 again.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Temporarily tighten the piston rod lock nut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "As shown in the figure, install the coil spring while moving it so that the lower end coil of the coil spring does not interfere strongly with the lower rubber seat in the bold line area. Then, tighten the piston rod lock nut to the specified torque so that the central axis of the mounting bearing and upper rubber seat does not deviate from the central axis of the strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Tightening the piston rod lock nut determines the position of the lower rubber seat and coil spring at the lower end of the strut.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Make sure that the coil spring does not interfere strongly at right angles to the axis of the upper rubber seat.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Make sure that there is no gap between the coil spring and the upper rubber seat in the axial direction.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Check that a 0.10 mm thickness gauge cannot be inserted into the gap between the mounting bearing and the upper rubber seat at the 0.5 turn from the upper end of the coil spring as shown in the figure.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "If the thickness gauge can be inserted into the gap, start over from step 4.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Make sure that the coil spring indicated by a bold line in the figure does not interfere strongly at right angles to the axis of the upper rubber seat.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "If there is strong interference between the coil spring and the lower part of the upper rubber seat, start over from step 4.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Gradually release a spring compressor (commercial service tool), and remove coil spring.", "ptxt");
si[i++] = gsitm("N5050101L0000X00ENG.html", "Remove the strut attachment (A) (SST: ST35652000) from strut assembly.", "ptxt");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Inspection", "title");
