si[i++] = gsitm("N5050102H0002R00ENG.html", "Check strut mounting insulator and bound bumper for cracks, wear or damage.", "ptxt");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Coil Spring", "title");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Check coil spring for cracks, wear or damage.", "ptxt");
si[i++] = gsitm("N5050102H0002R00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Check wheel sensor harness for proper connector. Refer to .", "ptxt");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Check wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5050102H0002R00ENG.html", "Adjust neutral position of steering angle sensor. Refer to Description.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Disposal", "title");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Set strut assembly horizontally to the ground with the piston rod fully extracted.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Drill 2 – 3 mm (0.08 – 0.12 in) hole at the position () from top as shown in the figure to release gas gradually.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Wear eye protection (safety glasses).", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Wear gloves.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Be careful with metal chips or oil blown out by the compressed gas.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Drill vertically in this direction show by arrow.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Directly to the outer tube avoiding brackets.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "The gas is clear, colorless, odorless, and harmless.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", ": 20 – 30 mm (0.79 – 1.18 in)", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Position the drilled hole downward and drain oil by moving the piston rod several times.", "ptxt");
si[i++] = gsitm("N5050101M0000F00ENG.html", "Dispose of drained oil according to the law and local regulations.", "ptxt");
