si[i++] = gsitm("N5050103M0001S00ENG.html", "Remove front suspension member. Refer to .", "ptxt");
si[i++] = gsitm("N5050103M0001S00ENG.html", "Remove transverse link mounting bolts  and nuts , and then remove transverse link  from suspension member.", "ptxt");
si[i++] = gsitm("N5050103M0001S00ENG.html", "Perform inspection after removal. Refer to Inspection.", "ptxt");
