si[i++] = gsitm("N5050103M0001S00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5050103M0001S00ENG.html", "Never reuse transverse link mounting nut.", "ptxt");
si[i++] = gsitm("N5050103M0001S00ENG.html", "Perform final tightening of bolts and nuts at the vehicle installation position (rubber bushing), under unladen conditions with tires on level ground.", "ptxt");
si[i++] = gsitm("N5050103M0001S00ENG.html", "Perform inspection after installation. Refer to Inspection.", "ptxt");
