si[i++] = gsitm("N5050102H0002S00ENG.html", "Transverse Link", "title");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Transverse link for deformation, cracks or damage.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Check the bushing for complete separation. (If completely separated, inner metal can be pulled out from transverse link.)", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Ball joint boot for cracks or other damage, and also for grease leakage.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Swing Torque", "title");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Manually move ball stud to confirm it moves smoothly with no binding.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Move ball stud at least ten times by hand to check for smooth movement.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Hook a spring balance (A) at cutout on ball stud . Confirm spring balance measurement value is within specifications when ball stud begins moving.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Swing torque", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", ": Refer to Ball Joint.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Measurement on spring balance", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "If swing torque exceeds standard range, replace transverse link assembly.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Axial End Play", "title");
si[i++] = gsitm("N5050102H0002S00ENG.html", "Move tip of ball stud in axial direction to check for looseness.", "ptxt");
si[i++] = gsitm("N5050102H0002S00ENG.html", "If there is axial end play, replace transverse link assembly.", "ptxt");
