si[i++] = gsitm("N5050104E0000Z00ENG.html", "(Decimal degree)", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "Out 0° 04′ (Out 0.07°)", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "In 0° 08′ (In 0.13°)", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "In 0° 20′ (In 0.33°)", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "Measure value under unladen*2 conditions.", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "*1: A difference when assuming the left side a standard.", "ptxt");
si[i++] = gsitm("N5050104E0000Z00ENG.html", "*2: Fuel, engine coolant and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "Ball Joint", "title");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "Swing torque", "ptxt");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "0.5 – 3.4 N·m (0.06 – 0.34 kg-m, 5 – 30 in-lb)", "ptxt");
si[i++] = gsitm("N5050100Q0000F00ENG.html", "Measurement on spring balance", "ptxt");
