si[i++] = gsitm("N5050202H0003E00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5050202H0003E00ENG.html", "COMPONENT PART", "title");
si[i++] = gsitm("N5050202H0003E00ENG.html", "Check the mounting conditions (looseness, backlash) of each component and component conditions (wear, damage) are normal.", "ptxt");
si[i++] = gsitm("N5050202H0003E00ENG.html", "SHOCK ABSORBER", "title");
si[i++] = gsitm("N5050202H0003E00ENG.html", "Check for oil leakage and damage. Replace it if necessary.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5050202H0006O00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Measure wheel alignment under unladen conditions.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "“Unladen conditions” means that fuel, engine coolant, and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "PRELIMINARY CHECK", "title");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Tires for improper air pressure and wear. Refer to .", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Road wheels for runout.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Wheel bearing axial end play.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Refer to following:", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "2WD: Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "4WD: Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Shock absorber operation.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Each mounting point of axle and suspension for looseness and deformation.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Each of lower link, upper link, rear suspension member, suspension arm and shock absorber for cracks, deformation, and other damage.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "GENERAL INFORMATION AND RECOMMENDATIONS", "title");
si[i++] = gsitm("N5050202H0006O00ENG.html", "A four-wheel thrust alignment should be performed.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "This type of alignment is recommended.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "The four-wheel “thrust” process helps ensure that the vehicle is properly aligned and the steering wheel is centered.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "The alignment rack itself should be capable.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "The rack should be checked to ensure that it is level.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Make sure the machine is properly calibrated.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Your alignment equipment should be regularly calibrated in order to give correct information.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Check with the manufacturer of your specific equipment for their recommended Service/Calibration Schedule.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "ALIGNMENT PROCESS", "title");
si[i++] = gsitm("N5050202H0006O00ENG.html", "IMPORTANT:", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Use only the alignment specifications listed in this Service Manual.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "When displaying the alignment settings, many alignment machines use “indicators”: (Green/red, plus or minus, Go/No Go). Never use these indicators.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "The alignment specifications programmed into your machine that operate these indicators may not be correct.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "This may result in an ERROR.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Most camera-type alignment machines are equipped with both “Rolling Compensation” method and optional “Jacking Compensation” method to “compensate” the alignment targets or head units. “Rolling Compensation” is the preferred method.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "If using the “Rolling Compensation” method, after installing the alignment targets or head units, push or pull on the rear wheel to move the vehicle. Do not push or pull on the vehicle body.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "If using the “Jacking Compensation” method, after installing the alignment targets or head units, raise the vehicle and rotate the wheels 1/2 turn both ways.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Do not use the “Rolling Compensation” method if you are using sensor-type alignment equipment.", "ptxt");
si[i++] = gsitm("N5050202H0006O00ENG.html", "Follow all instructions for the alignment machine you\'re using for more information.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "Adjustment", "title");
si[i++] = gsitm("N5050200L0000D00ENG.html", "CAMBER", "title");
si[i++] = gsitm("N5050200L0000D00ENG.html", "If camber is exceeds the standard value, adjust with adjusting bolt  in front lower link .", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "Camber: Refer to .", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "When tightening the nut firmly and checking the torque, use a wrench to prevent the turning of the bolt.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "After adjusting camber, be sure to check toe-in.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "If camber is not still within the specification, inspect and replace any damaged or worn suspension parts.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "TOE-IN", "title");
si[i++] = gsitm("N5050200L0000D00ENG.html", "If toe-in is exceeds the standard value, adjust with adjusting bolt  in rear lower link .", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "Toe-In: Refer to .", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "Be sure to adjust equally on right and left side with adjusting bolt.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "If toe-in is not still within the specification, inspect and replace any damaged or worn suspension parts.", "ptxt");
si[i++] = gsitm("N5050200L0000D00ENG.html", "After toe-in adjustment, adjust neutral position of steering angle sensor. Refer to Description.", "ptxt");
si[i++] = gsitm("N505020210002M00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N505020210002M00ENG.html", "Upper rubber seat", "ptxt");
si[i++] = gsitm("N505020210002M00ENG.html", "Coil spring", "ptxt");
si[i++] = gsitm("N505020210002M00ENG.html", "Lower rubber seat", "ptxt");
