si[i++] = gsitm("N505020210002M00ENG.html", ": Vehicle front", "par2");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5050203N0002M00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Remove tires. Refer to .", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Using jack (A) to rear lower link .", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Never damage the rear lower link with a jack.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Check the stable condition when using a jack.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Loosen the rear lower link mounting bolts and nuts  (rear suspension member side).", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Remove the rear lower link mounting bolts and nuts  (axle housing side).", "par2");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Slowly lower jack, remove upper rubber seat and coil spring .", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Operate while checking that jack supporting status is stable.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Remove lower rubber seat from rear lower link.", "par6");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Install lower rubber seat  with its protrusion  on the lower area aligned with the hole  of rear lower link.", "par7");
si[i++] = gsitm("N5050203N0002M00ENG.html", "The lower rubber seat protrusion  must be securely inserted into the hole  of rear lower link.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Install coil spring  by aligning lower end of coil spring with lower rubber seat  as shown in the figure.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Dimension (A)", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", ": 5 mm (0.20 in) or less", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Set coil spring so that its paint marks  and  are aligned with the position from the bottom end of the coil spring shown in the figure.", "par11");
si[i++] = gsitm("N5050203N0002M00ENG.html", ": Upper side", "par24");
si[i++] = gsitm("N5050203N0002M00ENG.html", ": 3.75 turns", "par25");
si[i++] = gsitm("N5050203N0002M00ENG.html", ": –", "par26");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Perform final tightening of fixing parts at the vehicle installation position (rubber bushing), under unladen conditions with tires on level ground.", "ptxt");
si[i++] = gsitm("N5050203N0002M00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N5050202H0003G00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5050202H0003G00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5050202H0003G00ENG.html", "Check rear lower link, rubber seat, upper seat, and coil spring for deformation, crack, and damage. Replace it if necessary.", "ptxt");
si[i++] = gsitm("N5050202H0003G00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5050202H0003G00ENG.html", "Check wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N505020210005500ENG.html", "Exploded View", "title");
