si[i++] = gsitm("N505020210005500ENG.html", ": N·m (kg-m, ft-lb)", "par1");
si[i++] = gsitm("N505020210005500ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5050203N0002N00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Remove tires. Refer to .", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Set jack under front lower link.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Check the stable condition when using a jack.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Never damage front lower link with a jack (A).", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Remove shock absorber mounting bolt  (lower side).", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Remove shock absorber  mounting bolts  (Upper side).", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Remove shock absorber.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Perform final tightening of fixing parts at the vehicle installation position (rubber bushing), under unladen conditions with tires on level ground.", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N5050203N0002N00ENG.html", "After replacing the shock absorber, always follow the disposal procedure to discard the shock absorber. Refer to Disposal.", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5050201P0000T00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Never damage shock absorber piston rod when removing components from shock absorber.", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "When fixing shock absorber with a vise, wrap a shop cloth around lower side of shock absorber to protect from damage. Never set the cylindrical part of shock absorber with a vise.", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "When removing piston rod lock nut, use special tool rear shock absorber service kit (KV401110S0).", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Fix the tip of the piston rod using special tool rod lock handle (KV40111100) (a) so that the piston rod does not rotate, and remove the piston rod lock nut using special tool socket 18 (KV40111000) (b).", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Perform inspection after removal. Refer to .", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Note the following, and assembly in the reverse order of disassembly.", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "When installing piston rod lock nut, use special tool rear shock absorber service kit (KV401110S0).", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Fix the tip of the piston rod using special tool rod lock handle (KV40111100) (a) so that the piston rod does not rotate, and install the piston rod lock nut using special tool socket 18 (KV40111000) (b).", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Never reuse piston rod lock nut.", "ptxt");
si[i++] = gsitm("N5050201P0000T00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
