si[i++] = gsitm("N5050403V0000D00ENG.html", "BCM", "title");
si[i++] = gsitm("N5050403V0000D00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5050403V0000D00ENG.html", "Tire pressure receiver is integrated in BCM.", "ptxt");
si[i++] = gsitm("N5050403V0000D00ENG.html", "BCM receives the signals of tire air pressure and tire temperature as an input from the tire pressure sensor in each wheel through a radio signal and controls tire pressure monitoring system.", "ptxt");
si[i++] = gsitm("N5050403V0000D00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5050403V0000D00ENG.html", "BCM uses CAN communication to Illuminate the low tire pressure warning light in the combination meter when tire pressure is lowered to less than the specified value or a system malfunction exists.", "ptxt");
si[i++] = gsitm("N5050403V0000D00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5050403V0000D00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5050403V0000D00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "Tire Pressure Sensor", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "A tire pressure sensor detects tire air pressure and tire temperature.", "ptxt");
si[i++] = gsitm("N5051901X0000E00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "A tire pressure sensor transmits the detected air pressure and tire temperature in the form of a radio signal to the low tire pressure warning control unit.", "ptxt");
si[i++] = gsitm("N5051901X0000E00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5051901X0000E00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5051901X0000E00ENG.html", "A tire pressure sensor integrated with a valve is install in each wheel. Refer to .", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "System Description", "title");
si[i++] = gsitm("N5050402U0000B00ENG.html", "During driving, the TPMS (tire pressure monitoring system) receives the signal transmitted from tire pressure sensor installed in each wheel. The BCM of this system has pressure judgment and trouble diagnosis functions. When the TPMS (tire pressure monitoring system) detects low inflation pressure or another unusual symptom, the low tire pressure warning lamps in the combination meter comes on.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "If the tire pressure is less than the warning tire pressure value, the low tire pressure warning light illuminates.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "Location of wheel is specified due to the synchronism of wheel sensor position and tire pressure sensor position.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "Activates the TPMS (tire pressure monitoring system) when the vehicle speed is 40 km/h (25 MPH) or more.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "The TPMS (tire pressure monitoring system) has easy fill tire alert function to aid in the inflation.", "ptxt");
