si[i++] = gsitm("N5050402U0000B00ENG.html", "HAZARD WARNING LIGHT INDICATION CONDITION", "title");
si[i++] = gsitm("N5050402U0000B00ENG.html", "The hazard warning light blinks under the following conditions.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "When ID registration is completed. Refer to .", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "During the use of the inflation indicator function.", "ptxt");
si[i++] = gsitm("N5050402U0000B00ENG.html", "HORN CONTROL CONDITION", "title");
si[i++] = gsitm("N5050402U0000B00ENG.html", "During the use of the easy fill tire alert function.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "Easy Fill Tire Alert Function", "title");
si[i++] = gsitm("N5050403W0000B00ENG.html", "The tire easy fill tire alert function is recommended to use the ignition switch ON.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "When beginning tire inflation, it takes a few seconds for the easy fill tire alert function.  If there is no response for approximately 15 seconds or more, cancel the easy fill tire alert function and move the vehicle approximately 1 m (3.2 ft) backward or forward to try again.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "The easy fill tire alert function operates only when the select lever position is in P-range with the ignition switch ON.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "This function informs the driver with a visual and audible indication that the recommended COLD tire pressure has been reached.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "The hazard warning lamps blink when the recommended COLD tire pressure has been reached. After the recommended COLD tire pressure has been reached, the horn sounds once and the hazard warning lamps stop blinking.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "If the tire pressure value is equal to or greater than 30 kPa (0.31 kg/cm2, 4 psi) more than the recommended COLD tire pressure, the hazard warning lamps flash and horn sounds three times.", "ptxt");
si[i++] = gsitm("N5050403W0000B00ENG.html", "To return the tire to the recommended COLD tire pressure, deflate the tire until the horn sounds once and the hazard warning lamps stop blinking.", "ptxt");
