si[i++] = gsitm("N5050403Z0000G00ENG.html", "DESIGN/PURPOSE", "title");
si[i++] = gsitm("N5050403Z0000G00ENG.html", "The low tire pressure location indicator is displayed in the information display of combination meter with the low tire pressure warning light and warning message when following conditions;", "ptxt");
