si[i++] = gsitm("N505040310000B00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "INTERVIEW FROM THE CUSTOMER", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Clarify customer complaints before inspection. To do so, reproduce the symptom beforehand and fully understand it. Then interview the customer thoroughly. Check the symptoms by driving vehicle with the customer, if necessary.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Customers are not professional. Never guess easily like \"maybe the customer means that...,\" or \" maybe the customer mentions this symptom\".", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "CHECK TIRE PRESSURE WARNING LIGHT FUNCTION", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Check that tire pressure warning light in combination meter.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Tire pressure warning light turn ON?", "question");
si[i++] = gsitm("N505040310000B00ENG.html", "YES", "result");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "NO", "result");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "CHECK TIRE PRESSURE", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Check the tire pressure of all wheels. Refer to .", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Check the tire pressure of cold condition.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Is the inspection standard value?", "question");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "ADJUST TIRE PRESSURE", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Check and adjust the tire pressure for all wheels specified to the value. Refer to .", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Drive the vehicle at 40 km/h (25MPH) or more reaches 10 minutes in total.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Tire pressure warning light turn OFF?", "question");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "CHECK AIR LEAK", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Using soapsuds etc., check air leak.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Check air valve.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Is air leak detected?", "question");
si[i++] = gsitm("N505040310000B00ENG.html", "Repair or replace error-detected parts. Replace the valve. Perform tire pressure sensor ID registration. Refer to .", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Perform \"Self-diagnosis\" of \"BCM\".", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N505040310000B00ENG.html", "Record or print self-diagnosis results and freeze frame data (FFD). GO TO 8.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Perform symptom diagnosis. Refer to Symptom Table.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Repair or replace error-detected parts. GO TO 10.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "PERFORM CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Perform Confirmation Procedure for the detected DTC, and then check that DTC is detected again.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "Check harness and connectors based on the information obtained by interview. Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N505040310000B00ENG.html", "DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N505040310000B00ENG.html", "Perform DTC Diagnosis Procedure.", "ptxt");
