si[i++] = gsitm("N505040120002B00ENG.html", "Description", "title");
si[i++] = gsitm("N505040120002B00ENG.html", "This procedure must be performed.", "ptxt");
si[i++] = gsitm("N505040120002B00ENG.html", "After replacement of a tire pressure sensor or BCM.", "ptxt");
si[i++] = gsitm("N505040120002B00ENG.html", "After replacement of tire or road wheel.", "ptxt");
si[i++] = gsitm("N505040120002B00ENG.html", "ID registration is unnecessary if there are no change in the positions of each wheels (tire pressure sensors) before wheel removal and after wheel installation.", "ptxt");
si[i++] = gsitm("N505040120002B00ENG.html", "After performing tire rotation.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N505040330000M00ENG.html", "TPMS REGISTRATION WITH SIGNAL TECH II TOOL (MB993012)", "title");
si[i++] = gsitm("N505040330000M00ENG.html", "The Signal Tech II must be updated with software version 1.1.48 or newer in order to perform the below procedures. The Signal Tech II software updates can only be downloaded from a M.U.T.-III SE unit with ASIST. Other versions of ASIST will not show the updates.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Adjust the tire pressure for all tires to the recommended value. Refer to .", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Turn the ignition switch ON.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Using M.U.T.-III SE, select \"Special Function\" in \"BCM\". Then, select \"TPMS ID Registration\".", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Select \"OK\" on \"TPMS ID Registration\" screen.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Turn on the Signal Tech II tool (MB993012).", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Hold the Signal Tech II against the side of the left front tire, near the valve.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "With the tool held at a 0 to 15 degree angle to the tire, select “Activate Sensor” from the main menu, then press and release the “OK” button to activate the sensor. Once the sensor is activated, the vehicle parking lamps will flash and the sensor ID will appear on the M.U.T.-III SE screen.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Repeat steps 6 and 7 for the remaining tires in this order: right front, right rear and left rear.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "When ID registration is complete, check the following pattern at each wheel.", "ptxt");
si[i++] = gsitm("N505040330000M00ENG.html", "Sequence", "ptxt");
