si[i++] = gsitm("N505040180007X00ENG.html", "Perform tire pressure sensor ID registration. Refer to .", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "To perform ID registration, observe the following points:", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "Never register ID in a place where radio waves are interfered (e.g. radio tower).", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "Never register ID in a place close to vehicles including TPMS.", "ptxt");
