si[i++] = gsitm("N505040180007X00ENG.html", "Change the work location and perform ID registration again.", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "Depending on the tire pressure sensor position*, a blind spot exists, and the tire pressure receiver gets a poor reception. If an ID registration is performed under this condition, the registration may not be completed. In such case, follow the instructions below to improve the radio wave receiving environment.", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "Rotate tire by 90°, 180°, or 270°. (This step is to change tire pressure sensor position.)", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "Open the door close to the tire of which ID registration is ongoing.", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "*: Radio wave reception condition depends on vehicle architecture (e.g. body harness layout, tire wheel design) or environment.", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "When ID registration is performed, which wheels do not react?", "question");
si[i++] = gsitm("N505040180007X00ENG.html", "All wheels react and ID registration is possible.", "result");
si[i++] = gsitm("N505040180007X00ENG.html", "Only certain wheel(s) do not react.", "result");
si[i++] = gsitm("N505040180007X00ENG.html", "Replace applicable tire pressure sensor. Refer to .", "ptxt");
si[i++] = gsitm("N505040180007X00ENG.html", "All wheels do not react.", "result");
si[i++] = gsitm("N505040180007X00ENG.html", "Replace the BCM. Refer to .", "ptxt");
si[i++] = gsitm("N505040120002I00ENG.html", "Description", "title");
si[i++] = gsitm("N505040120002I00ENG.html", "The easy fill tire alert does not function while inflating a tire when the A/T shift selector position is in P-range with the ignition switch ON or with the engine started.", "ptxt");
si[i++] = gsitm("N505040120002I00ENG.html", "After starting to inflate the tire, it takes a few seconds for the easy fill tire alert to function.", "ptxt");
si[i++] = gsitm("N505040120002I00ENG.html", "If there is no response for approximately 15 seconds or more after inflating the tires, cancel the use of the easy fill tire alert function or move the vehicle approximately 1 m (3.2 ft) backward or forward to try again. The air filler pressure may be weak or out of service area.", "ptxt");
si[i++] = gsitm("N505040120002I00ENG.html", "For easy fill tire alert, Refer to Easy Fill Tire Alert Function.", "ptxt");
