si[i++] = gsitm("N5050401W0000H00ENG.html", "Road Wheel", "title");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Check road wheel for deformation, cracks, corrosion and other damage.", "ptxt");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Check wheel nuts for looseness by using torque wrench.", "ptxt");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Wheel nut tightening torque", "ptxt");
