si[i++] = gsitm("N5050401W0000H00ENG.html", "Tire", "title");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Check entire circumference and both sides of each tire for deformation, cracks, scratch and other damage.", "ptxt");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Check tire tread for wear and foreign matter such as nails and small rock.", "ptxt");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Check that tire pressure is the specified value.", "ptxt");
si[i++] = gsitm("N5050401W0000H00ENG.html", "Tire pressure", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Tire Rotation", "title");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Follow the maintenance schedule for tire rotation service intervals.", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Tire rotation", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Tires should be rotated every 5,000 miles (8,000 km).", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "When installing the wheel, tighten wheel nuts to the specified torque. Refer to .", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Never include the T-type spare tire when rotating the tires.", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "When installing wheels, tighten them diagonally by dividing the work two to three times in order to prevent the wheels from developing any distortion.", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Never tighten wheel nut at torque exceeding the criteria.", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Use Mitsubishi Motors genuine wheel nut.", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "After tire rotation, perform following:", "ptxt");
si[i++] = gsitm("N5050404W0000C00ENG.html", "Perform the ID registration. Refer to .", "ptxt");
