si[i++] = gsitm("N5050404X0000L00ENG.html", "Removal & Installation", "title");
si[i++] = gsitm("N5050404X0000L00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5050404X0000L00ENG.html", "Remove wheel nuts.", "ptxt");
si[i++] = gsitm("N5050404X0000L00ENG.html", "Remove tire assembly.", "ptxt");
si[i++] = gsitm("N5050404X0000L00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5050404X0000L00ENG.html", "Note the following, install in the reverse order of removal.", "ptxt");
