si[i++] = gsitm("N5050101X0002G00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5050101X0002G00ENG.html", "Screw", "ptxt");
si[i++] = gsitm("N5050101X0002G00ENG.html", "Tire pressure sensor", "ptxt");
si[i++] = gsitm("N5050101X0002G00ENG.html", "Valve", "ptxt");
si[i++] = gsitm("N5050101X0002G00ENG.html", "Valve core", "ptxt");
si[i++] = gsitm("N5050101X0002G00ENG.html", "Valve cap", "par5");
si[i++] = gsitm("N5050101X0002G00ENG.html", ": Comply with the assembly procedure when tightening. Refer to Removal and Installation.", "par7");
si[i++] = gsitm("N5050101X0002G00ENG.html", ": N·m (kg-m, in-lb)", "par2");
si[i++] = gsitm("N5050101X0002G00ENG.html", ": Always replace after every disassembly.", "par1");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Removal & Installation", "title");
si[i++] = gsitm("N5050404X0000M00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Remove tire assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Remove valve cap, valve core and then deflate tire.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "If the tire is reused, apply a matching mark to the position of the tire road wheel valve hole for the purpose of wheel balance adjustment after installation.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Use the tire changer and disengage the tire beads.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Be sure not to damage the road wheel or tire pressure sensor.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Apply bead cream or an equivalent to the tire beads.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Turn tire so that valve hole is at bottom and bounce so that tire pressure sensor  is near valve hole. Carefully lift tire onto turntable and position valve hole (and tire pressure sensor) 270 degree from mounting/dismounting head .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Be sure not to damage the road wheel and tire pressure sensor.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Remove mounting screw , and then remove tire pressure sensor  from valve .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Cut the part  of valve, using a pliers cutters (B).", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Be sure not to damage the road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Remove the valve  from road wheel , using a valve inserter (A).", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Pull the valve straight through the rim hole perpendicularly to the rim hole.", "par6");
si[i++] = gsitm("N5050404X0000M00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Never loosen the mounting screw if the tire pressure sensor and valve are assembled.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "When reusing the tire pressure sensor, install the valve to the tire pressure sensor, follow the procedure below.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Insert the tire pressure sensor  to the roll pin  of valve .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Never reuse valve.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install mounting screw .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", ": 1.4 ± 0.1 N·m (0.14 ± 0.01 kg-m, 12.4 ± 0.8 in-lb)", "par13");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Never reuse mounting screw.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Spray water or immerse the valve into water, before mounting in the area  indicated shown in the figure.", "par5");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install the tire pressure sensor assembly, follow the procedure below.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Set the tire pressure sensor assembly to road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Check the tire pressure sensor assembly  direction, tire pressure sensor assembly must be inserted to the rim of road wheel  as shown figure.", "par4");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install the tire pressure sensor assembly  to road wheel , using a valve inserter (A).", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Avoid any contact of the tire pressure sensor with the rim well and valve with the rim hole counter bore during insertion.", "par10");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Insert tire pressure sensor assembly all the way to the road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Check that tire pressure sensor assembly contacts horizontally with road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "If the position is not correct, rotate the tire pressure sensor assembly to the correct position, using a valve inserter.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install the tire inside beads  onto the road wheel  in the position shown in the figure.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Set the tire onto the turntable so that the tire changer arm  is at a position approximately 270° from the tire pressure sensor .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Be sure that the arm does not contact the tire pressure sensor.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install the tire outer side beads onto the road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "When installing, check that the tire does not turn together with the road wheel.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Check the tire pressure for all wheels and adjust to the specified value. Refer to .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Before adding air, align the tire with the position of the matching mark applied at the time of removal.", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Install tire to the vehicle. Refer to .", "ptxt");
si[i++] = gsitm("N5050404X0000M00ENG.html", "Perform tire pressure sensor ID registration. Refer to .", "ptxt");
si[i++] = gsitm("N505040680000300ENG.html", "RADIO WAVE CERTIFICATION", "title");
si[i++] = gsitm("N505040680000300ENG.html", "The TPMS transmitter has obtained a type approval number of radio wave certification for telecommunication equipment.", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "Tire Air Pressure", "title");
si[i++] = gsitm("N5051901G0000E00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "Front", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "Rear", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "235/60R18 103H", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "255/45R20 101W", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "240 (2.4, 2.4, 35)", "par1");
si[i++] = gsitm("N5051901G0000E00ENG.html", "T155/90D18 103M", "ptxt");
si[i++] = gsitm("N5051901G0000E00ENG.html", "420 (4.2, 4.2, 60)", "ptxt");
si[i++] = gsitm("N506010470000G00ENG.html", "Precaution for Procedure without Cowl Top Cover", "title");
si[i++] = gsitm("N506010470000G00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5060104A0001400ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5060104A0001400ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5060104A0001400ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5060106I0001N00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5060106I0001N00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5060106I0001N00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Precaution for Brake System", "title");
si[i++] = gsitm("N506010460000G00ENG.html", "Since dust covering the front and rear brakes has an affect on human body, the dust must be removed with a dust collector. Never splatter the dust with an air blow gun.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Brake fluid use refer to .", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Always confirm the specified tightening torque when installing the brake pipes.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "After pressing the brake pedal more deeply or harder than normal driving, such as air bleeding, check each item of brake pedal.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Always clean with new brake fluid when cleaning the master cylinder, brake caliper and other components.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Never use mineral oils such as gasoline or light oil to clean. They may damage rubber parts and cause improper operation.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Always loosen the brake tube flare nut with a flare nut wrench.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Tighten the brake tube flare nut to the specified torque with a crowfoot (A) and torque wrench (B).", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Turn the ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the battery negative terminal before performing the work.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Check that no brake fluid leakage is present after replacing the parts.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Burnish the brake contact surfaces after refinishing or replacing rotors, after replacing pads, or if a soft pedal occurs at very low mileage.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Front brake pad: Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N506010460000G00ENG.html", "Front disc rotor: Refer to .", "ptxt");
