si[i++] = gsitm("N5060103C0006600ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006600ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103C0006600ENG.html", "Uneven wear", "title");
si[i++] = gsitm("N5060103C0006600ENG.html", "Check the uneven wear of the disc rotor using a micrometer. Replace the disc rotor if the thickness is below the wear limit.", "ptxt");
si[i++] = gsitm("N5060103C0006600ENG.html", "For 2WD: Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006600ENG.html", "For 4WD: Refer to .", "ptxt");
