si[i++] = gsitm("N5060103C000CK00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C000CK00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103C000CK00ENG.html", "BRAKE DRAG FORCE CHECK", "title");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Remove the brake pad, shim cover and pad retainer (Refer to ).", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Using a spring scale, measure the hub sliding torque in the forward direction with the brake pad, shim cover and pad retainer removed.", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Install the brake pad, shim cover and pad retainer (Refer to ).", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Start the engine, and depress the brake pedal lightly two or three times. Then stop the engine. [Depressing force: approximately 50 - 100 N (11.2 - 22.5 pound)]", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Turn the brake disc 10 times in the forward direction.", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Using a spring scale, measure the hub sliding torque in the forward direction with the brake pad, shim cover and pad retainer installed.", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Obtain the disc brake drag force (difference between measured values of item 2 and item 6).", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "68 N (15.3 pound) or less", "ptxt");
si[i++] = gsitm("N5060103C000CK00ENG.html", "If the brake drag force exceeds the standard value, disassemble the brake caliper assembly to check for fouling/rust on the piston sliding section and piston seal deterioration, and confirm whether the sliding pins slide properly (Refer to ).", "ptxt");
si[i++] = gsitm("N5060103C0006800ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006800ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103C0006800ENG.html", "Uneven wear", "title");
si[i++] = gsitm("N5060103C0006800ENG.html", "Check the uneven wear of the disc rotor using a micrometer. Replace the disc rotor if the thickness is below the wear limit.", "ptxt");
si[i++] = gsitm("N5060103C0006800ENG.html", "For 2WD: Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006800ENG.html", "For 4WD: Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006800ENG.html", "Thickness variation [measure the brake disc thickness at minimum eight points which are 10 mm (0.39 inch) inward from its circumference.]", "ptxt");
si[i++] = gsitm("N5060103C0006800ENG.html", ": Refer to .", "ptxt");
