si[i++] = gsitm("N5060103H0003M00ENG.html", "Inspection and Adjustment", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Brake Pedal Height", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Check the height (H1) between the floor panel  and the brake pedal upper surface.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "H1", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Remove the front floor carpet.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Stop Light Switch", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Check the clearance (C) among the lever  and the stop light switch mounting bracket .", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "C", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "The stop light must turn off when the brake pedal is released.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Hold the brake pedal pad to make the clearance between the stop light switch mounting bracket and brake pedal.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Brake Pedal Play", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Press the brake pedal. Check the brake pedal play (A) (stroke until fluid pressure occurs).", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Depressed Brake Pedal Height", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Check the height between the floor panel  and the brake pedal upper surface (H2) when depressing the brake pedal at 490 N (50 kg, 110 lb) while turning engine ON.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "H2", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "ADJUSTMENT", "title");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Perform the following procedure when brake pedal height is not within the specified value because brake pedal height is not adjustable.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Check input rod length. Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Replace brake pedal assembly when input rod length is within specified value.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Remove instrument lower panel LH. Refer to GROUP 52A - INTERIOR, INSTRUMENT PANEL DRIVER\'S SIDE, Removal and Installation.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Disconnect the harness connector from stop light switch.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Loosen the stop light switch 90° counterclockwise.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "The stop light switch  penetrate the clip hole of stop light switch mounting bracket  and firmly push the stop light switch against the lever . (Do not touch the pedal during installing stop light switch.) And, turn the stop light switch clockwise (about 90°) until the stop light switch.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "The clearance (C) between the brake pedal bracket and stop light switch mounting bracket must be the specified value.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "The stop light must be turned off when the brake pedal is released.", "ptxt");
si[i++] = gsitm("N5060103H0003M00ENG.html", "Perform the air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006A00ENG.html", "BRAKE FLUID LEVEL", "title");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Check that the brake fluid level in the reservoir tank is within the standard (between MAX − MIN lines).", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Visually check for any brake fluid leakage around the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Check the brake system for any leakage if the fluid level is extremely low (lower than MIN).", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Check the brake system for fluid leakage if the warning light remains illuminated even after the parking brake is released.", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Check the reservoir tank for the mixing of foreign matter (e.g. dust) and oils other than brake fluid.", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "BRAKE LINE", "title");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Check brake line (tubes and hoses) for cracks, deterioration or other damage. Replace any damaged parts.", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Depress the brake pedal with a force of 785 N (80 kg, 176 lb) and hold down the pedal for approximately 5 seconds with the engine running. Check for any fluid leakage.", "ptxt");
si[i++] = gsitm("N5060103C0006A00ENG.html", "Retighten the applicable connection to the specified torque and repair any abnormal (damaged, worn or deformed) part if any brake fluid leakage is present.", "ptxt");
si[i++] = gsitm("N5060102D0000G00ENG.html", "Draining", "title");
si[i++] = gsitm("N5060102D0000G00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N5060102D0000G00ENG.html", "Turn the ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the battery negative terminal before performing work.", "ptxt");
si[i++] = gsitm("N5060102D0000G00ENG.html", "Connect a vinyl tube to the bleed valve.", "ptxt");
si[i++] = gsitm("N5060102D0000G00ENG.html", "Depress the brake pedal and loosen the bleeder valve to gradually discharge brake fluid.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Refilling", "title");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Turn the ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the battery negative terminal before performing work.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "If fluid completely runs out of the reservoir tank during operation, air will find way into the brake line. Pay attention, therefore, to the fluid level and replenish as necessary.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Check that there is no foreign material in the reservoir tank, and refill with new brake fluid.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Never allow foreign matter (e.g. dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060104G0000Y00ENG.html", "Loosen the bleeder valve, slowly depress the brake pedal to the full stroke, and then release the pedal. Repeat this operation at intervals of 2 or 3 seconds until new brake fluid is discharged. Then close the bleeder valve with the brake pedal depressed. Repeat the same work on each wheel.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Bleeding Brake System", "title");
si[i++] = gsitm("N506010100000G00ENG.html", "Turn the ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the battery negative terminal before performing the work.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Monitor the fluid level in the reservoir tank while performing the air bleeding", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Never allow foreign matter (e.r.dust) and oil other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Connect a vinyl tube to the bleeder valve of the rear right brake.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Fully depress the brake pedal 4 to 5 times.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Loosen the bleeder valve and bleed air with the brake pedal depressed, and then quickly tighten the bleeder valve.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Repeat steps 2 and 3 until all of the air is out of the brake line.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "In case of rear brake caliper with electric parking brake system, operate parking brake 5 times to bleed the air.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Tighten the bleeder valve to the specified torque.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Front disc brake : Refer to .", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Rear disc brake : Refer to .", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Perform steps 2 to 6. Occasionally fill with the brake fluid in order to keep it in the reservoir tank at least half of MAX line. Bleed air in the following order: rear right brake → front left brake → rear left brake → and front right brake in order.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Check that the fluid level in the reservoir tank is within the specified range after air bleeding. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N506010100000G00ENG.html", "Check each item of brake pedal. Adjust it if the measurement value is not the standard. Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006B00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006B00ENG.html", "FLUID LEAK", "title");
si[i++] = gsitm("N5060103C0006B00ENG.html", "Check for brake fluid leakage from the master cylinder mounting face, reservoir tank mounting face and brake tube connections.", "ptxt");
si[i++] = gsitm("N5060103C0006C00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006C00ENG.html", "OPERATION", "title");
si[i++] = gsitm("N5060103C0006C00ENG.html", "Depress the brake pedal several times at 5-second intervals with the engine stopped. Start the engine with the brake pedal fully depressed. Check that the clearance between brake pedal and dash lower panel decreases.", "ptxt");
si[i++] = gsitm("N5060103C0006C00ENG.html", "AIR TIGHT", "title");
si[i++] = gsitm("N5060103C0006C00ENG.html", "Run the engine at idle for 1 minute to apply vacuum to the brake booster, and stop the engine.", "ptxt");
si[i++] = gsitm("N5060103C0006C00ENG.html", "Depress the brake pedal several times at 5-second intervals until the accumulated vacuum is released to atmospheric pressure. Check that the clearance between brake pedal and dash lower panel gradually increases each time the brake pedal is depressed when performing this operation.", "ptxt");
si[i++] = gsitm("N5060103C0006C00ENG.html", "Depress the brake pedal with the engine running. Then stop the engine while holding down the brake pedal. Check that the brake pedal stroke does not change after holding down the brake pedal for 30 seconds or more.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Inspection and Adjustment", "title");
si[i++] = gsitm("N5060103H0003N00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Check brake pad wear thickness from an inspection hole on cylinder body. Check using a scale if necessary.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Wear thickness", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "ADJUSTMENT", "title");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Burnish contact surfaces between disc rotor and brake pads according to the following procedure after refinishing or replacing brake pads, or if a soft pedal occurs at very low mileage.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Be careful of vehicle speed because the brake does not operate firmly/securely until pads and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Only perform this procedure under safe road and traffic conditions. Use extreme caution.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Drive vehicle on straight, flat road.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Depress brake pedal with the power to stop vehicle within 3 to 5 seconds until the vehicle stops.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Drive without depressing brake for a few minutes to cool the brake.", "ptxt");
si[i++] = gsitm("N5060103H0003N00ENG.html", "Repeat steps 1 to 3 until pad and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Inspection and Adjustment", "title");
si[i++] = gsitm("N5060103H0003O00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Appearance", "title");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Check surface of disc rotor for uneven wear, cracks, and serious damage. Replace it if necessary.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "For 2WD, refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "For 4WD, refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Runout", "title");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Fix the disc rotor to the wheel hub and bearing assembly with wheel nuts (2 points at least).", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Check the wheel bearing axial end play.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "For 2WD, refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "For 4WD, refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Inspect the runout with a dial indicator to measure at 10 mm (0.39 in) inside the disc edge.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Runout (with it attached to the vehicle)", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Find the installation position that has a minimum runout by shifting the disc rotor-to-wheel hub and bearing assembly installation position by one hole at a time if the runout exceeds the limit value.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Refinish the disc rotor if the runout is outside the limit even after performing the above operation.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Check in advance that the thickness of the disc rotor is wear thickness + 0.3 mm (0.012 in) or more.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "If the thickness is less than wear thickness + 0.3 mm (0.012 in), replace the disc rotor.", "ptxt");
