si[i++] = gsitm("N5060103H0003O00ENG.html", "Burnish contact surfaces between disc rotors and brake pads according to the following procedure after refinishing or replacing disc rotor, or if a soft pedal occurs at very low mileage.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Be careful of vehicle speed because the brake does not operate firmly/securely until pad and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Only perform this procedure under safe road and traffic conditions. Use extreme caution.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Drive vehicle on straight, flat road.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Depress brake pedal with the power to stop vehicle within 3 to 5 seconds until the vehicle stops.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Drive without depressing brake for a few minutes to cool the brake.", "ptxt");
si[i++] = gsitm("N5060103H0003O00ENG.html", "Repeat steps 1 to 3 until pad and disc rotor are securely fitted.", "ptxt");
