si[i++] = gsitm("N5060104I000BD00ENG.html", "Remove nuts , and then remove bracket .", "par1");
si[i++] = gsitm("N5060104I000BD00ENG.html", "Remove snap pin  and clevis pin  from clevis of brake booster .", "ptxt");
