si[i++] = gsitm("N5060104I000BD00ENG.html", "The clevis pin may be inserted in either direction.", "ptxt");
si[i++] = gsitm("N5060104I000BD00ENG.html", "Never impact brake pedal such as drop and interference with tools and parts.", "ptxt");
