si[i++] = gsitm("N5060104I0004S00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0004S00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never depress the brake pedal while removing the brake hose or brake tube. If this is not complied with, brake fluid may splash.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Remove tires.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Drain brake fluid. Refer to Draining.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Loosen the flare nut  with a flare nut wrench (A) and separate the brake tube  from the brake hose .", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never scratch the flare nut and the brake tube.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never bend sharply, twist or strongly pull out the brake hoses and tubes.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Cover open end of brake tubes and hoses when disconnecting to prevent entrance of dirt.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Remove the union bolt  and copper washers , and remove the brake hose  from the brake caliper assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Remove the lock plate  and remove the brake hose.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never allow foreign matter (e.g. dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Assemble the union bolt  and the copper washer  to the brake hose.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never reuse the copper washer.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Align the brake hose pin  with the brake caliper assembly projection , and tighten the union bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Install the brake tube  to the brake hose , temporarily tighten the flare nut  by hand until it does not rotate further, and fix the brake hose to the bracket  with the lock plate .", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Check that all brake hoses and brake tubes are not twisted and bent.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Tighten the flare nut to the specified torque with a crowfoot (A) and torque wrench (B).", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Refill with new brake fluid and perform the air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Install tires. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004S00ENG.html", "Perform inspection after installation. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060103C0006D00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006D00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103C0006D00ENG.html", "Check the brake hoses and tubes for the following: no scratches; no twist and deformation; no interference with other components when steering the steering wheel; no looseness at connections.", "ptxt");
si[i++] = gsitm("N5060103C0006D00ENG.html", "Clearance with brake hose and each parts being secured more than 10 mm (0.39 in) in unladen condition*.", "ptxt");
si[i++] = gsitm("N5060103C0006D00ENG.html", "*: Fuel, engine coolant and lubricant are quantity to specified. Spare tire, jack, hand tools and mats are brought out of vehicle.", "ptxt");
si[i++] = gsitm("N5060103C0006D00ENG.html", "Depress the brake pedal with a force of 785 N (80 kg, 176 lb) and hold down the pedal for approximately 5 seconds with the engine running. Check for any fluid leakage.", "ptxt");
si[i++] = gsitm("N5060103C0006D00ENG.html", "Retighten the applicable connection to the specified torque and repair any abnormal (damaged, worn or deformed) part if any brake fluid leakage is present.", "ptxt");
