si[i++] = gsitm("N5060104I0004T00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never depress the brake pedal while removing the brake hose or brake tube. If this is not complied with, brake fluid may splash.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Wipe off immediately when attaching brake fluid with disc rotor and caliper assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Remove tires. Refer to", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Drain brake fluid. Refer to Draining.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Loosen the flare nut  with a flare nut wrench (A) and separate the brake tube A  from the brake hose A . And then remove the lock plate .", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never scratch the flare nut and the brake tube.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never bend sharply, twist or strongly pull out the brake hoses and tubes.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Cover open end of brake tubes and brake hoses when disconnecting to prevent entrance of dirt.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Loosen the flare nut  with a flare nut wrench (A) and separate the brake hose A  from the brake tube B . And then remove the lock plate .", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Remove the lock plate , then remove the brake hose from the brake tube bracket.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Loosen the flare nut  with a flare nut wrench (A) and separate the brake tube B  from the brake hose B .", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Remove the lock plate , then remove the brake tube B  from the brake tube bracket.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Remove the union bolt  and copper washers , and remove the brake hose B  from the brake caliper assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never allow foreign matter (e.g. dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Be sure to check the identification color when installing the brake hose (body floor side) because the shapes of the brake hoses are different on the right and left side (Right side: orange, left side: blue).", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Assemble the union bolt  and the copper washers  to the brake hose B.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never reuse the copper washer.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Align the brake hose L-pin  with the brake caliper assembly hole , and tighten the union bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Install the brake hose B to the brake tube B, temporarily tighten the flare nut by hand until it does not rotate further, and fix the brake hose to the brake hose bracket with the lock plate.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Check that all brake hoses and brake tubes are not twisted and bent.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Tighten the flare nut to the specified torque with a crowfoot (A) and torque wrench (B).", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Install the brake tube B to the brake hose A, temporarily tighten the flare nut by hand until it does not rotate further, and fix the brake hose to brake hose brackets with the lock plate.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Install the brake hose A to the brake tube A, temporarily tighten the flare nut by hand until it does not rotate further, and fix the brake hose with the lock plate.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Refill with new brake fluid and perform the air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Install tires. Refer to", "ptxt");
si[i++] = gsitm("N5060104I0004T00ENG.html", "Perform inspection after installation. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060103C0006E00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006E00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103C0006E00ENG.html", "Check the brake hoses and tubes for the following: no scratches; no twist and deformation; no looseness at connections.", "ptxt");
si[i++] = gsitm("N5060103C0006E00ENG.html", "Clearance with brake hose and each parts being secured more than 10 mm (0.39 in) in unladen condition*.", "ptxt");
si[i++] = gsitm("N5060103C0006E00ENG.html", "*: Fuel, engine coolant and lubricant are quantity to specified. Spare tire, jack, hand tools and mats are brought out of vehicle.", "ptxt");
si[i++] = gsitm("N5060103C0006E00ENG.html", "Depress the brake pedal with a force of 785 N (80 kg, 176 lb) and hold down the pedal for approximately 5 seconds with the engine running. Check for any fluid leakage.", "ptxt");
si[i++] = gsitm("N5060103C0006E00ENG.html", "Retighten the applicable connection to the specified torque and repair any abnormal (damaged, worn or deformed) part if any brake fluid leakage is present.", "ptxt");
