si[i++] = gsitm("N5060104I0004U00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0004U00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Depress the brake pedal several times to release the vacuum pressure from the brake booster. Then remove the master cylinder assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never depress the brake pedal while removing the brake tube. If this is not complied with, brake fluid may splash.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Perform inspection before removal. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Drain brake fluid. Refer to Draining.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Remove the battery. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Remove the engine cover. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Disconnect the brake fluid level switch harness connector. Refer to following.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Slide the connector lock  forward of the vehicle (1).", "par2");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Disconnect the brake fluid level switch harness connector  forward of the vehicle (2).", "par3");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Secure the work space by fixing the fuel hose and canister hose with ropes.", "par1");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Separate the brake tube  from the master cylinder assembly  with a flare nut wrench (A).", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never scratch the flare nut and the brake tube.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Remove the master cylinder assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never deform or bend the brake tubes.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never depress the brake pedal after the master cylinder assembly is removed.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "The piston  of the master cylinder assembly is exposed. Never damage it when removing the master cylinder.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "The piston may drop off when pulled out strongly. Never hold the piston. Hold the cylinder body when handling the master cylinder assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Remove the O-ring.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Never reuse the O-ring.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Apply polyglycol ether based lubricant to the brake booster [see  in the figure] when installing the master cylinder assembly to the brake booster.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "The piston  of the master cylinder assembly is exposed. Never damage it when handling the master cylinder.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Check that no dirt and dust are present on the piston before installation. Clean it with new brake fluid if necessary.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "The piston may drop off when pulled strongly. Never hold the piston. Hold the cylinder body when handling the master cylinder assembly.", "ptxt");
si[i++] = gsitm("N5060104I0004U00ENG.html", "Temporarily tighten the brake tube  flare nut to the master cylinder assembly  by hand. Then tighten it to the specified torque with a flare nut torque wrench (A). Refer to .", "ptxt");
