si[i++] = gsitm("N5060102B0001G00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5060102B0001G00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never disassemble the cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Remove the reservoir tank only when necessary.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never drop parts to remove. Replace new parts when dropping.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Fix the master cylinder assembly to a vise.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Always set copper plates or cloth between vise grips when fixing the cylinder body to a vise.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never overtighten the vise.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Remove the reservoir tank pin.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Remove the reservoir tank and grommet from the cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never use mineral oils such as kerosene or gasoline and rubber grease during the cleaning and assembly process.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never allow foreign matter (e.g. dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never drop when installing. The parts must not be reused if they are dropped.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Apply new brake fluid to the grommet and install it to the cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001G00ENG.html", "Never reuse grommets.", "ptxt");
