si[i++] = gsitm("N5060103C0006F00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103C0006F00ENG.html", "Check the following items and replace if necessary.", "ptxt");
si[i++] = gsitm("N5060103C0006F00ENG.html", "Check the master cylinder for deformation, twist, contact with other parts or looseness of connection.", "ptxt");
si[i++] = gsitm("N5060103C0006F00ENG.html", "Check for fluid leakage from connection. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060103C0006F00ENG.html", "If the fluid leakage is present, retighten to the specified torque. Replace parts if necessary.", "ptxt");
