si[i++] = gsitm("N5060107I0001D00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
