si[i++] = gsitm("N5060107I0001D00ENG.html", "Be careful not to damage brake booster stud bolt threads. If brake booster is tilted during installation, the dash panel may damage threads.", "ptxt");
si[i++] = gsitm("N5060107I0001D00ENG.html", "Never deform or bend the brake tubes when installing the brake booster.", "ptxt");
