si[i++] = gsitm("N5060103H0003S00ENG.html", "Inspection and Adjustment", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "INSPECTION BEFORE REMOVAL", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Air Tight", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the air tight condition when the master cylinder and the brake booster is installed.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the air tight use a handy vacuum pump.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "At vacuum of −66.7 kPa (−500 mmHg, −19.69 inHg, −0.067 bar)", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", ": Vacuum should decrease within 3.3 kPa (24.8 mmHg, 0.98 inHg, 0.033 bar) for 15 seconds.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "If the air tight condition cannot be maintained, perform the following operation.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the no dirt and dust are present on the brake booster and brake master cylinder mating faces. Clean it if necessary.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the O-ring on the master cylinder. If anything is found, replace the O-ring. Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the air tight condition again. If the condition still cannot be maintained, replace the brake booster.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Input Rod Length rod Inspection", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Check the input length (A).", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", ": Input rod", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Replace the brake booster if the input rod length is not the standard.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Operation", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Depress the brake pedal several times at 5-second intervals with the engine stopped. Start the engine with the brake pedal fully depressed. Check that the clearance between brake pedal and dash lower panel decreases.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "A slight impact with a small click may be felt on the pedal when the brake pedal is fully depressed. this is normal phenomenon due to the brake system operation.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Run the engine at idle for 1 minute to apply vacuum to the brake booster, and stop the engine.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Depress the brake pedal several times at 5-second intervals until the accumulated vacuum is released to atmospheric pressure. Check that the clearance between brake pedal and dash lower panel gradually increases each time.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Depress the brake pedal with the engine running. Then stop the engine while holding down the brake pedal. Check that the brake pedal stroke does not change after holding down the brake pedal for 30 seconds or more.", "ptxt");
si[i++] = gsitm("N5060103H0003S00ENG.html", "ADJUSTMENT AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103H0003S00ENG.html", "Perform the brake pedal adjustment after installing the brake pedal assembly. Refer to .", "ptxt");
