si[i++] = gsitm("N5060104I0009I00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0009I00ENG.html", "Note the following, install the vacuum hose.", "ptxt");
si[i++] = gsitm("N5060104I0009I00ENG.html", "When the insertion of vacuum hose is difficult, applying volatile alcohol shall be acceptable. However the volatile alcohol shall be composed from ethanol, N-propyl alcohol and isopropyl alcohol.", "par6");
si[i++] = gsitm("N5060104I0009I00ENG.html", "When installing vacuum hose, insert it until its tip reaches the back-end of length (A) or further as shown in the figure.", "ptxt");
