si[i++] = gsitm("N5060102N0005900ENG.html", ": Apply MOLYKOTE® AS-880N or silicone-based grease.", "par3");
si[i++] = gsitm("N5060102N0005900ENG.html", "Molykote is a registered trademark of Dow Corning Corporation.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I000BN00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Clean dust on brake caliper and brake pad with a vacuum dust collector to minimize the hazards of airborne particles or other material.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not depress the brake pedal while removing the brake pads because the pistons may pop out.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "It is not necessary to remove bolts on torque member and brake hose except for disassembly or replacement of brake caliper. For brake pad removal, hang brake caliper with a wire so as not to stretch brake hose.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "If the brake fluid or grease adheres to the brake caliper assembly and disc rotor, quickly wipe it off.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Observe brake fluid level in the reservoir tank. Partially drain brake fluid if necessary. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Remove the front wheels and tires using power tool.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Remove slide pin bolts.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Remove the brake caliper from the torque member. Leaving brake hose attached, reposition the brake caliper aside with wire.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Remove the brake pads , shim covers  and pad retainer  from the torque member .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not reuse the pad retainers.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not damage the piston boot.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not drop the brake pads or the shim covers.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Note the position of components during removal to aid with installation.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Compress the front caliper pistons.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Install the new pad retainers to the torque member.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Do not deform the pad retainers.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Verify that the pad retainers are secured properly to the torque member.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Apply MOLYKOTE® AS-880N or silicone-based grease to the  part of the shim cover , and install the shim covers to the brake pad .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "When installing new brake pads, replace the shim covers.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "The pad retainer is to be installed by identifying the color identification.", "ptxt");
