si[i++] = gsitm("N5060104I000BN00ENG.html", "Green", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "When installing the brake pad , make sure that the tip of return spring part  of the brake pad  is in contact with protrusion  of the pad retainer .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Install the brake pads to the torque member.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Using a suitable tool, press the pistons into the brake caliper.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Install the brake caliper to the torque member.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Install the slide pin bolts and tighten to specification. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Depress the brake pedal several times and verify that drag does not exist.", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Install the front wheels and tires. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I000BN00ENG.html", "Check brake fluid level and refill as necessary. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0009F00ENG.html", "When replacing, replace both brake pads (right and left) as a set.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove the housing clip.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove the protector, and remove the guide pin.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove the caliper body.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove the inner pad with wear indicator assembly from the caliper piston.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Peel off the outer pad assembly from the caliper body.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove any remnants of the old tape. Then degrease the adhesion surface by using a cloth moistened with Mitsubishi Genuine Parts Cleaner (MZ100387).", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Clean the piston, and press the piston into the cylinder completely using the special tool piston expander (MB990520).", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Install the inner pad with wear indicator assembly to the caliper piston.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Install the outer pad assembly to the caliper support.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "In order to adhere a double-sided tape after assembling, make a space between the outer pad assembly and the caliper body at this time to prevent contact with each other.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Remove the release paper of the double-sided tape of the outer pad assembly, and install the caliper body.", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Specified torque: 28 ± 2 N·m", "ptxt");
si[i++] = gsitm("N5060104I0009F00ENG.html", "Depress the brake pedal several times to check that there is no abnormality, and then install the housing clip.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5060103C0006H00ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Replace the shims and shim covers if rust is excessively attached.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Eliminate rust on the pad return spring, pad retainers and the torque member. Replace them if rust is excessively attached.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Check a drag of front disc brake. If any drag is found, follow the procedure described below.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Remove brake pads. Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Press the pistons. Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Install brake pads. Refer to .", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Depress the brake pedal several times.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Check a drag of front disc brake again. If any drag is found, disassemble the cylinder body and replace if necessary. Refer to Disassembly and Assembly.", "ptxt");
si[i++] = gsitm("N5060103C0006H00ENG.html", "Burnish contact surfaces brake pads and disc rotor after refinishing or replacing brake pads, or if a soft pedal occurs at very low mileage. Refer to Inspection and Adjustment.", "ptxt");
