si[i++] = gsitm("N5060102N0009C00ENG.html", "As for the pad set, the brake pads for both the right wheels and the left wheels have the wear indicator.", "ptxt");
si[i++] = gsitm("N5060102N0009C00ENG.html", "Install the pad & wear indicator assembly to the inner side of the brake disc, making sure that the wear indicator is located on the top.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0009J00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Clean dust on brake caliper and brake pad with a vacuum dust collector to minimize the hazard of airborne particles or other materials.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not spill or splash brake fluid on painted areas; it may cause paint damage. If brake fluid is splashed on painted areas, wash it away with water immediately.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not bend, twist or pull the brake hoses and piping.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "When removing components such as hoses, tubes/lines, etc., cap or plug openings to prevent fluid from spilling.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove reservoir cap from the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove front wheels and tires using power tool.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Secure the disc brake rotor using wheel nuts.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove union bolt, copper sealing washers, and disconnect brake hose from brake caliper. Discard the copper sealing washers.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not reuse copper sealing washers.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove slide pin bolts and the brake caliper.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not drop brake pads or caliper.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove the brake pads from the torque member.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not damage the piston boot.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not drop the brake pads, shims, or the shim covers.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Note the position of components during removal to aid with installation.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Install the brake pads in the torque member.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Position the brake caliper to torque member and install the slide pin bolts. Tighten to specification.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Assemble the union bolt  and the copper sealing washers  to the brake hose and install it as an assembly to the brake caliper. Align the brake hose L-pin by aligning it with the brake caliper hole, and tighten the union bolt  to the specified torque.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Refill with new brake fluid and perform the air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not spill or splash brake fluid on the disc brake rotor.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Install the front wheels and tires. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Check the drag of front disc brake. If any drag is found, follow the procedure described below.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Remove brake pads.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Using a suitable tool, press the pistons into the brake caliper body.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Do not damage the piston boots.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Install brake pads.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Depress the brake pedal several times.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Check the drag of front disc brake again. If any drag is found, disassemble the brake caliper body.", "ptxt");
si[i++] = gsitm("N5060104I0009J00ENG.html", "Burnish contact surfaces after refinishing or replacing disc brake rotors or if a soft pedal occurs at very low mileage. Refer to .", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5060102B0001H00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never drop parts to remove.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never remove the torque member, brake pad and pad retainers when disassembling and assembling the cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Remove the sliding pin bolt, and remove the cylinder body from the torque member. Refer to .", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Fix the brake pad at suitable tape so that the brake pad will not drop.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Remove sliding pins and sliding pin boots from torque member.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Remove bushing  from sliding pin .", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Place a wooden block as shown in the figure, and blow air from union bolt mounting hole to remove pistons and piston boots.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never get fingers caught in the pistons.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Remove piston seals from cylinder body using seal pick tool.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Be careful not to damage a cylinder inner wall.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Remove bleeder valve and cap.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Perform inspection after disassembly. Refer to Inspection.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never drop when installing.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Install bleeder valve and cap.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Apply new brake fluid to piston seals , and install them to cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never reuse piston seals.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Apply rubber grease to piston boots . Cover the piston  end with piston boot, and then install cylinder side lip on piston boot securely into a groove on cylinder body.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Never reuse piston boots.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Apply new brake fluid to pistons . Push piston into cylinder body by hand and push piston boot  piston-side lip into the piston groove.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Press the pistons evenly and vary the pressing point to prevent cylinder inner wall from being rubbed.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Apply rubber grease to mating faces  between sliding pin  and bushing , and install bushing to sliding pin.", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Apply rubber grease to mating faces  between sliding pins  and sliding pin boots , and install sliding pins and sliding pin boots to torque member .", "ptxt");
si[i++] = gsitm("N5060102B0001H00ENG.html", "Install the cylinder body to tighten sliding pin bolts to the specified torque.", "ptxt");
