si[i++] = gsitm("N5060103C0006I00ENG.html", "Check the cylinder inner wall for rust, wear, cracks or damage.", "ptxt");
si[i++] = gsitm("N5060103C0006I00ENG.html", "Always clean with new brake fluid. Never clean with mineral oil such as gasoline and light oil.", "ptxt");
