si[i++] = gsitm("N5060104I0004Z00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Since dust covering the front and rear brakes has an affect on human body, the dust must be removed with a dust collector. Never splatter the dust with an air blow gun.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Never depress the brake pedal while removing the brake pads because the piston may pop out.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "If the brake fluid or grease adheres to the brake caliper assembly and disc rotor, quickly wipe it off.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Release the parking brake.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Must be performed additional service when replacing brake pad. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Remove tires.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Disconnect the parking brake actuator harness connector .", "par1");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Remove lower sliding pin bolt .", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Remove the cylinder body , and suspend the cylinder body with suitable wire (A) so that the brake hose  and the electric parking brake harness will not stretch.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Remove the brake pads, shims and shim covers.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Never damage the piston boots.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Never drop the brake pads, shims and shim covers.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Remember each position of the removed brake pads.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Never damage the electric parking brake harness and bracket.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Perform inspection after removal. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Install the brake pads to the torque member.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Apply rubber grease to the cylinder body mounting bolts, and then install the cylinder body to torque member.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Never damage the piston boot.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "When replacing brake pad with new one, check a brake fluid level in the reservoir tank because brake fluid returns to reservoir tank when pressing piston in.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Install the lower sliding pin bolt  and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Connect the parking brake actuator harness connector .", "par3");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Must be performed additional service when removing and installing/replacing brake pad. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Depress the brake pedal several times to check that no drag feel is present for the rear disc brake. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060104I0004Z00ENG.html", "Install tires. Refer to .", "ptxt");
