si[i++] = gsitm("N5060104I0005000ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5060104I0005000ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5060104I0005000ENG.html", "Since dust covering the front and rear brakes has an affect on human body, the dust must be removed with a dust collector. Never splatter the dust with an air blow gun.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. However avoid washing brake components with water.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never depress the brake pedal while removing the brake pads because the piston may pop out.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "If the brake fluid or grease adheres to the brake caliper assembly and disc rotor, quickly wipe it off.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Release the parking brake.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Must be performed additional service when replacing brake caliper. Refer to .", "ptxt");
