si[i++] = gsitm("N5060104I0005000ENG.html", "Remove torque member mounting bolts , and remove brake caliper assembly.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never drop brake pad and brake caliper assembly.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never damage the electric parking brake harness and bracket.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Remove disc rotor.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "For 2WD: .", "par3");
si[i++] = gsitm("N5060104I0005000ENG.html", "For AWD: .", "par2");
si[i++] = gsitm("N5060104I0005000ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never allow foreign matter (e.g.dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Apply the rubber grease to the new O-ring.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Install disc rotor. Refer to.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Install the brake caliper assembly to the steering knuckle and tighten the torque member mounting bolts  to the specified torque.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never spill or splash any grease and moisture on the brake caliper assembly mounting face, threads, mounting bolts and washers. Wipe out any grease and moisture.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Install brake hose and copper washers to brake caliper assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never reuse copper washer.", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Must be performed additional service when removing and installing/replacing brake pad. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Refill with new brake fluid and perform the air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060104I0005000ENG.html", "Never reuse brake fluid.", "ptxt");
