si[i++] = gsitm("N5060305C0000P00ENG.html", "ABS Actuator and Electric Unit (Control Unit)", "title");
si[i++] = gsitm("N5060305C0000P00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305C0000P00ENG.html", "The parking brake actuator is controlled by the signals from the parking brake switch, sensors, and units.", "ptxt");
si[i++] = gsitm("N5060305C0000P00ENG.html", "The parking brake is released and applied by controlling the parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060305C0000P00ENG.html", "When a malfunction is detected, the system enters fail-safe mode.", "ptxt");
si[i++] = gsitm("N5060305C0000P00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305C0000P00ENG.html", "Controls the parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060305C0000P00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060305C0000P00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Parking Brake Switch", "title");
si[i++] = gsitm("N5060305S0000E00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Parking brake is applied/released by the parking brake switch operation.", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305S0000E00ENG.html", "When the parking brake switch is pushed / pulled, the circuit between the ABS actuator and electric unit (control unit) is established to input the switch signal.", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "When parking brake is applied, parking brake switch indicator light is turned ON by the ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Parking brake switch is constructed by a combination of normal open type switch and normal close type switch. And the switch circuit is connected in parallel.", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Parking brake switch is pull: Parking brake is apply and parking brake switch indicator light is turn ON.", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Parking brake switch is push: Parking brake is release and parking brake switch indicator light is turn OFF.", "ptxt");
si[i++] = gsitm("N5060305S0000E00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060305S0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "Parking Brake Actuator", "title");
si[i++] = gsitm("N5060204A0000B00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060204A0000B00ENG.html", "The parking brake actuator  activates / releases the parking brake by moving the piston of the rear brake caliper  according to the signal from the ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060204A0000B00ENG.html", "Parking brake actuator is composed of a motor, gear, etc.", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060204A0000B00ENG.html", "It operates/releases the parking brake by transmitting the motor rotation output to the piston of the rear brake caliper.", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "Braking condition is mechanically maintained. It is not always controlled.", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060204A0000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060204A0000B00ENG.html", "Never reuse the parking brake actuator if the parking brake actuator is removed from the rear brake caliper.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "System Description", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The electric parking brake system uses the signal from the parking brake switch to have the ABS actuator and electric unit (control unit) operate the parking brake actuator to apply and release the parking brake.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake switch is placed in the console finisher so that it can be operated close at hand (applied/released).", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake is operated, the electric parking brake indicator light in the combination meter and the parking brake switch indicator turn ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake is released, the electric parking brake indicator light in the combination meter and the parking brake switch indicator turn OFF.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When a malfunction occurs in the electric parking brake system, electric parking brake warning light turn ON, electric parking brake indicator light turn ON/OFF (depends on the electric parking brake system) or blink, and parking brake switch indicator turn ON/OFF (depends on the electric parking brake system) or blink, and the function for entering the fail-safe status is held.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When a malfunction occurs in the electric parking brake system, the parking brake can be mechanically released. Refer to .", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "OPERATION", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake switch is pulled, a parking brake operation switch signal is transmitted from the ABS actuator and electric unit (control unit) to the parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake actuator receives a parking brake switch signal, it activates the motor in the parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the motor is operated, rotating torque is generated, and transmitted to the piston in the parking brake actuator of the rear brake caliper via gears in parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The piston is pushed out by the rotating torque, and the parking brake operates by pressing the brake pad against the disc rotor.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "RELEASE", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake switch is pushed, a parking brake release switch signal is transmitted from the ABS actuator and electric unit (control unit) to the parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When a parking brake switch signal is input, the motor in the parking brake actuator rotates in reverse and pulls back the piston of the rear brake caliper.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "By pulling back the piston of the rear brake caliper, the brake pad and disc rotor are released as with the normal brakes, and the parking brake is released.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "INPUT SIGNAL AND OUTPUT SIGNAL", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Major signal transmission between each unit via communication lines is shown in the following table.", "ptxt");
