si[i++] = gsitm("N5060203G0000C00ENG.html", "Parking brake switch", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Mainly transmits the following signals to ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Accelerator pedal position signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Engine status signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Engine torque signal", "ptxt");
