si[i++] = gsitm("N5060203G0000C00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Mainly receives the following signals from ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
