si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake warning light signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Meter display signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Chassis control module", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake operation request signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake status signal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake operation signal (switch)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "ELECTRIC PARKING BRAKE OPERATION", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Normal Operation", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake switch is pulled while the vehicle is stopped, the parking brake operates. (The motor in the parking brake actuator starts generating rotating torque.)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake braking force reaches the prescribed value (rotating torque generated by the motor in the parking brake actuator), the electric parking brake indicator light turns ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the auto ACC is OFF, the electric parking brake indicator light is turn OFF.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The braking force of parking brake remains to be held.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Changing from Automatic Brake Hold to Parking Brake", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "For automatic brake hold. Refer to .", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "If any of the following conditions are met, parking brake operates automatically. (The braking method for stopping the vehicle is changed from automatic brake hold to parking brake.)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Automatic brake hold operates for approximately 3 minutes", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Driver seat belt is unfastened while automatic brake hold is being applied", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Ignition switch is OFF", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "A malfunction is detected in automatic brake hold", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Driver side door is open", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake effectiveness reaches the specified value, electric parking brake indicator light turns ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Normal Release (Ignition switch ON)", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake is released when the parking brake switch is pushed while the brake pedal is depressed, the ignition switch is ON, and the parking brake is operating.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Parking brake is not released if only parking brake switch is pushed.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake can be released by turning ON the ignition switch and pushing the parking brake switch while depressing the brake pedal.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When release of the parking brake is completed (it means no rotating torque generated by the motor in the parking brake actuator), the electric parking brake indicator light turns OFF.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Normal Release (Other ignition switch ON)", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake cannot be released if only parking brake switch is pushed while the ignition switch is OFF, the parking brake is applied, and the brake pedal is depressed.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The electric parking brake indicator light turns OFF.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Automatic Release", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake automatically releases under the following conditions.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Engine running", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The electric shift selector is in the D or R position", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Driver side door is close", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The accelerator pedal is depressed", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When traction motor torque necessary for travelling is generated", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Driving", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When parking brake switch is pulled while the vehicle is stopping [Vehicle speed is 4 km/h (2.5 MPH) or less.], the electric parking brake starts the operation (the motor in the parking brake actuator starts the rotation). And then the electric parking brake indicator light is turned ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake switch is pulled while travelling, a command is transmitted to the ABS actuator and electric unit (control unit), and it applies brake on four wheels to reduce vehicle speed.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "If ABS actuator and electric unit (control unit) cannot operate, the electric parking brake system brakes rear wheels by the parking brake actuator. And then vehicle speed is decelerated.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "When the parking brake switch is released, the ABS actuator and electric unit (control unit) releases the brakes.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "During the brake operation (deceleration) by the ABS actuator and electric unit (control unit), the status becomes as follows:", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake indicator light and master warning light are turned ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Buzzer beeps.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "“Release parking brake” is shown on the information display of the combination meter.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Stop light is turn ON.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "If the electric parking brake switch is still pulled after the vehicle speed decelerates 4 km/h (2.5 MPH), the braking operation is switched from control by the ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "CONDITION FOR TURN ON THE WARNING LIGHT, THE INDICATOR LIGHT AND INFORMATION DISPLAY", "title");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Turns ON when ignition switch ON and turns OFF when the system is normal, for bulb check purposes.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Condition (status)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake indicator light (in combination meter)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Master warning light (red) (in combination meter)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake warning light(in combination meter)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Parking brake switch indicator light (in parking brake switch)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Information display (in combination meter)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake system is operating", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "OFF", "ptxt");
