si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake system is released", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake system is malfunctioning", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "ON/OFF (Depends on the status of the electric parking brake system.)", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake switch is pushed without depressing the brake pedal.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Press brake pedal", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The automatic release is applied during driving by depressing the accelerator pedal with the door open, and the engine running.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Release parking brake", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake is operated with the parking brake switch kept pulled during driving.", "ptxt");
