si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake braking force is insufficient (vehicle is moving backward).", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Blinking", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The combination meter cannot receive signals from the ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "A malfunction of the parking brake switch is detected.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "The parking brake switch is operated while a malfunction of the parking brake switch is detected.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Release of the parking brake is inhibited detecting malfunctions of other control units.", "ptxt");
si[i++] = gsitm("N5060203G0000C00ENG.html", "Electric parking brake system does not operate (malfunction check not possible).", "ptxt");
si[i++] = gsitm("N5060305L0001300ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N5060305L0001300ENG.html", "The electric parking brake warning light and/or electric parking indicator light turns ON when a malfunction with the system occurs. Refer to .", "ptxt");
si[i++] = gsitm("N5060305L0001300ENG.html", "When parking brake switch is pulled/pushed during system malfunction, electric parking brake indicator light blinks and electric parking brake warning light turns ON when electric parking brake cannot be operated. It restricts braking and release operations of electric parking brake.", "ptxt");
si[i++] = gsitm("N5060305L0001300ENG.html", "The parking brake can be mechanically released.", "ptxt");
