si[i++] = gsitm("N5060204E0000B00ENG.html", "Parking Brake Warning", "title");
si[i++] = gsitm("N5060204E0000B00ENG.html", "DESIGN/PURPOSE", "title");
si[i++] = gsitm("N5060204E0000B00ENG.html", "Warns the driver of the necessity of depressing the brake pedal.", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "Warns the driver of the necessity of releasing the parking brake.", "ptxt");
