si[i++] = gsitm("N5060204E0000B00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5060204E0000B00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N5060204E0000B00ENG.html", "The ABS actuator and electric unit (control unit) transmits a signal to the combination meter via CAN communication under the conditions bellow:", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "When necessary to depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "When necessary to release the parking brake.", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "WARNING/INDICATOR OPERATING CONDITION", "title");
si[i++] = gsitm("N5060204E0000B00ENG.html", "When the following conditions are satisfied (ignition switch ON)", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "The parking brake switch is pushed without depressing the brake pedal.", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "The parking brake is operated with the parking brake switch kept pulled during driving.", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "The parking brake braking force is insufficient (vehicle is moving backward).", "ptxt");
si[i++] = gsitm("N5060204E0000B00ENG.html", "When the vehicle is moving.", "ptxt");
si[i++] = gsitm("N5060305I0001000ENG.html", "M.U.T.-III SE Function", "title");
si[i++] = gsitm("N5060305I0001000ENG.html", "Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5060305Q0001X00ENG.html", "List of ECU Reference", "title");
si[i++] = gsitm("N5060305Q0001X00ENG.html", "ECU", "ptxt");
si[i++] = gsitm("N5060305Q0001X00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N5060305Q0001X00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5060305Q0001X00ENG.html", "Fail-safe", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "DETAILS OF TROUBLE DIAGNOSIS FLOWCHART", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "COLLECT THE INFORMATION FROM THE CUSTOMER", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "It is also important to clarify customer concerns before starting the inspection. First of all, perform an interview utilizing  and reproduce the symptom as well as fully understand it. Depending on the situations, drive the vehicle with the customer and check the symptom.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Customers are not professionals. Never guess easily like “maybe the customer means that...,” or “maybe the customer mentions this symptom”.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "CHECK SYMPTOM", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Reproduce the symptom that is indicated by the customer, based on the information from the customer obtained by interview. Also check that the symptom is not caused by fail-safe mode. Refer to .", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "When the symptom is caused by normal operation, fully inspect each portion and obtain the understanding of customer that the symptom is not caused by a malfunction.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Auto ACC is OFF and check parking brake switch indicator turn OFF.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Push the parking brake switch.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Set the electric shift selector in the P position.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Pull the parking brake switch.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Perform self-diagnosis for “ABS”.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N5060203N0000B00ENG.html", "YES", "result");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Record or print self-diagnosis results and freeze frame data (FFD). GO TO 4.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "NO", "result");
si[i++] = gsitm("N5060203N0000B00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "REPAIR OR REPLACE ERROR-DETECTED PART", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Repair or replace error-detected parts.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Reconnect part or connector after repairing or replacing.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "When DTC is detected, erase self-diagnostic result for “ABS”.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Be sure wait of 10 seconds after ignition switch OFF or ON.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "IDENTIFY ERROR-DETECTED SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Estimate error-detected system based on symptom diagnosis and perform inspection.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Can the error-detected system be identified?", "question");
si[i++] = gsitm("N5060203N0000B00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Check harness and connectors based on the information obtained by interview. Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5060203N0000B00ENG.html", "Check the reference value for “ABS”.", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "YES-1", "result");
si[i++] = gsitm("N5060203N0000B00ENG.html", "\"CRNT\" is displayed: Check the DTC. Refer to .", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "YES-2", "result");
si[i++] = gsitm("N5060203N0000B00ENG.html", "“Stored DTC” is displayed: INSPECTION END (Erase the memory of self-diagnosis results.)", "ptxt");
si[i++] = gsitm("N5060203N0000B00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060201D0000B00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N5060201D0000B00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5060201D0000B00ENG.html", "In general, customers have their own criteria for a problem. Therefore, it is important to understand the symptom and status well enough by asking the customer about his/her concerns carefully. To systemize all the information for the diagnosis, prepare the interview sheet referring to the interview points.", "ptxt");
si[i++] = gsitm("N5060201D0000B00ENG.html", "In some cases, multiple conditions that appear simultaneously may cause a DTC to be detected.", "ptxt");
