si[i++] = gsitm("N5060201B0001S00ENG.html", "Pull or push parking brake switch, check operation sound of parking brake actuator.", "ptxt");
si[i++] = gsitm("N5060201B0001S00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N5060201B0001S00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060201B0001S00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5060201B0001S00ENG.html", "CHECK REAR DISC BRAKE SYSTEM", "title");
si[i++] = gsitm("N5060201B0001S00ENG.html", "Check the rear disc brake system. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001S00ENG.html", "Replace the ABS actuator and electric unit (control unit). Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001S00ENG.html", "Repair or replace the rear disc brake system. Refer to .", "ptxt");
si[i++] = gsitm("N506020150002H00ENG.html", "Description", "title");
si[i++] = gsitm("N506020150002H00ENG.html", "The parking brake braking force is low and the vehicle moves backward when parked on an incline.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Diagnosis Procedure", "title");
