si[i++] = gsitm("N5060201B0001T00ENG.html", "Pull the parking brake switch, and apply the parking brake.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Pull the parking brake switch 2 seconds ore mode.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Is the vehicle moving backward?", "question");
si[i++] = gsitm("N5060201B0001T00ENG.html", "YES", "result");
si[i++] = gsitm("N5060201B0001T00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "NO", "result");
si[i++] = gsitm("N5060201B0001T00ENG.html", "NORMAL", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "PERFORM THE SELF-DIAGNOSIS", "title");
