si[i++] = gsitm("N5060201B0001T00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "CHECK REAR DISC BRAKE SYSTEM", "title");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Check the rear disc brake system.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear brake pad: Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear disc rotor: Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear brake caliper (and parking brake actuator): Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N5060201B0001T00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Repair or replace error-detected pars.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear brake pad: Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear disc rotor: Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Rear brake caliper (and parking brake actuator): Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "REAPPLY THE PARKING BRAKE (2)", "title");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Pull the parking brake switch again.", "ptxt");
si[i++] = gsitm("N5060201B0001T00ENG.html", "Replace the ABS actuator and electric unit (control unit). Refer to .", "ptxt");
si[i++] = gsitm("N506020150002I00ENG.html", "Description", "title");
si[i++] = gsitm("N506020150002I00ENG.html", "The parking brake breaking force is too high.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Diagnosis Procedure", "title");
si[i++] = gsitm("N5060201B0001U00ENG.html", "PERFORM THE SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N5060201B0001U00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Perform self-diagnosis for “ABS”.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N5060201B0001U00ENG.html", "YES", "result");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Check the DTC. Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "NO", "result");
si[i++] = gsitm("N5060201B0001U00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "CHECK REAR DISC BRAKE SYSTEM (1)", "title");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Check if the rear disc brake is dragging. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Is the rear disc brake dragging?", "question");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Check the rear disc brake system. Refer to Inspection and Adjustment.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "CHECK REAR DISC BRAKE SYSTEM (2)", "title");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Depress the brake pedal 3 times or more.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Drive the vehicle at 30 km/h (19 MPH) or more.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Stop the vehicle.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Depress the brake pedal 3 times or more again.", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Is the braking force of parking brake is high?", "question");
si[i++] = gsitm("N5060201B0001U00ENG.html", "Replace the rear brake caliper assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5060201B0001U00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060201O0000H00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5060201O0000H00ENG.html", "Parking brake actuator harness and rear wheel sensor", "ptxt");
si[i++] = gsitm("N5060201O0000H00ENG.html", "Axle housing", "ptxt");
si[i++] = gsitm("N5060201O0000H00ENG.html", ": Vehicle front", "par2");
si[i++] = gsitm("N5060201O0000H00ENG.html", ": N·m (kg-m, ft-lb)", "par5");
si[i++] = gsitm("N5060201O0000H00ENG.html", ": N·m (kg-m, in-lb)", "par3");
si[i++] = gsitm("N506020340001100ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506020340001100ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506020340001100ENG.html", "Turn the ignition switch ON.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Never start the engine.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Release the parking brake.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "If the brake cannot be released, release it manually. Refer to .", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Turn the ignition switch OFF.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Disconnect 12V battery negative terminal. Refer to .", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Remove rear tires. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Disconnect parking brake actuator harness and rear wheel sensor harness connectors.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Remove parking brake actuator harness and rear wheel sensor harness mounting bolts.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "Remove parking brake actuator harness and rear wheel sensor harness from the vehicle.", "ptxt");
si[i++] = gsitm("N506020340001100ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506020340001100ENG.html", "Install the reverse order of the removal.", "ptxt");
si[i++] = gsitm("N506020340001200ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506020340001200ENG.html", "Never remove parking brake actuator from rear brake caliper assembly. When replacing parking brake actuator, replace rear brake caliper assembly. Refer to .", "ptxt");
si[i++] = gsitm("N506020340001300ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506020340001300ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506020340001300ENG.html", "Remove the console finisher assembly. Refer to .", "ptxt");
si[i++] = gsitm("N506020340001300ENG.html", "Remove parking brake mounting screws , and then remove parking brake switch .", "ptxt");
si[i++] = gsitm("N506020340001300ENG.html", ": Console finisher assembly", "par4");
si[i++] = gsitm("N506020340001300ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506020340001300ENG.html", "Install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5060303Z0000E00ENG.html", "Precaution for Procedure without Cowl Top Cover", "title");
si[i++] = gsitm("N5060303Z0000E00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N506030430003F00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N506030430003F00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N506030430003F00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5060305T0001O00ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5060305T0001O00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5060305T0001O00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Precaution for Brake System", "title");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Since dust covering the front and rear brakes has an affect on human body, the dust must be removed with a dust collector. Never splatter the dust with an air blow gun.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Brake fluid use refer to .", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Always confirm the specified tightening torque when installing the brake pipes.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "After pressing the brake pedal more deeply or harder than normal driving, such as air bleeding, check each item of brake pedal. Adjust brake pedal if it is outside the standard value.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Never use mineral oils such as gasoline or light oil to clean. They may damage rubber parts and cause improper operation.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Always loosen the brake tube flare nut with a flare nut wrench.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Tighten flare nut of brake tube to the specified torque using a flare nut torque wrench (A).", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the 12V battery negative terminal before performing the work. Refer to Precautions for Removing Battery Terminal.", "ptxt");
si[i++] = gsitm("N5060303X0000E00ENG.html", "Check that no brake fluid leakage is present after replacing the parts.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Precaution for Brake Control System", "title");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Always perform a pre-driving check to drive the vehicle.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Always check speed and safety while driving the vehicle.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "To operate M.U.T.-III SE while driving, more than one person is required to be in the vehicle to avoid interference to driving and ensure safety.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Slight vibrations are felt on the brake pedal and the operation noises occur, when ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, or electric parking brake function operates. This is not a malfunction because it is caused by ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, or electric parking brake function that is normally operated.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When starting engine or when starting vehicle just after starting engine, brake pedal may vibrate or motor operating noise may be heard from engine compartment. This is normal condition.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Brake stopping distance may become longer than models without ABS function depending on the road conditions, when ABS function is operated on slippery road like rough road, gravel road or snowy road.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When a malfunction is indicated, always collect information from the customer about conditions of occurrence, estimate cause, and perform operation. Check brake booster operation, brake fluid level, and brake fluid leakage, as well as electrical system.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "The optimum performance is achieved by control for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function when all of brakes, suspensions and tires installed on the vehicle are the specified size and parts. Brake performance and controllability may be negatively affected when other parts than the specified are installed.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Brake stopping distance may become longer and steering stability may be negatively affected, when tires in different size and combination or other parts than the specified are used.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When a radio (including wiring), antenna and antenna lead line are located near ABS actuator and electric unit (control unit), a malfunction or improper operation may occur for the control of ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When the following items are replaced by other parts than genuine parts or modified, ABS warning light, brake warning light and ASC warning light may turn ON, and the control may not operate normally for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Suspension component parts (shock absorber, spring, bushing and others)", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Tire and wheel (other than the specified size)", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Brake component parts (brake pad, disc rotor, brake caliper and others)", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Engine component parts (ECM, muffler and others)", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Body reinforcement component parts (rollover bar, tower bar and others)", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When suspension, tire and brake related parts are excessively worn or deteriorated and the vehicle is driven, ABS warning light, brake warning light and ASC warning light may turn ON, and the control may not operate normally for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "ABS warning light, brake warning light and ASC warning light may turn ON, when only front wheel or rear wheel is rotated using a free roller. This is not a malfunction, because it is caused by wheel speed difference between wheel that is rotated and wheel that is not rotated. In this case, perform self-diagnosis, check self-diagnosis results, and erase memory.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "When power supply voltage is not normal, ABS warning light, brake warning light and ASC warning light turn ON. ABS actuator and electric unit (control unit) stops control for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function. Ordinary brake operates. After power supply returns to normal, ABS warning light, brake warning light and ASC warning light turn OFF. The control becomes operative for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "Brake pedal vibrates and operation sound occurs during sudden acceleration and cornering, when ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function. This is not a malfunction because it is caused by ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function that is operated normally.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "ASC warning light may turn ON and ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function may not normally operate, when driving on a special road the is extremely slanted (bank in a circuit course). This is not a malfunction if the status returns to normal for ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and electric parking brake function after the engine is started again. In this case, perform self-diagnosis, check self-diagnosis results, and erase memory.", "ptxt");
si[i++] = gsitm("N5060303W0000E00ENG.html", "A malfunction in yaw rate/side/decel G sensor system may be detected when the vehicle sharply turns during a spin turn, acceleration turn or drift driving while ASC function and TCS function are OFF (ASC OFF indicator light is in ON status). This is not a malfunction if the status returns to normal for ASC function and TCS function after the engine is started again. In this case, perform self-diagnosis, check self-diagnosis results, and erase memory.", "ptxt");
si[i++] = gsitm("N5060307H0000L00ENG.html", "Precautions for Harness Repair", "title");
si[i++] = gsitm("N5060307H0000L00ENG.html", "Solder the repaired area and wrap tape around the soldered area.", "ptxt");
si[i++] = gsitm("N5060307H0000L00ENG.html", "A fray of twisted lines must be within 110 mm (4.33 in).", "ptxt");
si[i++] = gsitm("N5060307H0000L00ENG.html", "Bypass connection is never allowed at the repaired area.", "ptxt");
si[i++] = gsitm("N5060307H0000L00ENG.html", "Bypass connection may cause CAN communication error. The spliced wire becomes separated and the characteristics of twisted line are lost.", "ptxt");
si[i++] = gsitm("N5060307H0000L00ENG.html", "Replace the applicable harness as an assembly if error is detected on the shield lines of CAN communication line.", "ptxt");
si[i++] = gsitm("N5060304E0000S00ENG.html", "Special Service Tool", "title");
si[i++] = gsitm("N5060304E0000S00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N5060304E0000S00ENG.html", "The actual shapes of the tools may differ from those illustrated here.", "ptxt");
