si[i++] = gsitm("N5060305C0000O00ENG.html", "ABS Actuator and Electric Unit (Control Unit)", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Electric unit (control unit) is integrated with actuator and comprehensively controls ASC function, TCS function, ABS function, EBD function, Brake limited slip differential (BLSD) function, Brake assist function, bake force distribution function, hill start assist function, electric parking brake function, and TSA function.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "ELECTRIC UNIT (CONTROL UNIT)", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Brake fluid pressure, engine and transaxle are controlled according to signals from each sensor.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "If malfunction is detected, the system enters fail-safe mode.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "ACTUATOR", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "The following components are integrated with ABS actuator.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Pump", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Pressure the brake fluid and send.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Returns the brake fluid reserved in reservoir to master cylinder by reducing pressure.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Motor", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Activates the pump according to signals from ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Motor Relay", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Operates the motor ON/OFF according to signals from ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Actuator Relay", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Operates each valve ON/OFF according to signals from ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "ABS In Valve", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Switches the fluid pressure line to increase or hold according to signals from control unit.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Valve is a solenoid valve.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "ABS Out Valve", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Switches the fluid pressure line to increase, hold or decrease according to signals from control unit.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Cut Valve 1, Cut Valve 2", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Shuts off the ordinary brake line from master cylinder, when ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function are activated.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Suction Valve 1, Suction Valve 2", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Supplies the brake fluid from master cylinder to the pump, when ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function are activated.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Inlet Valve", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Brake fluid sucked from the reservoir by the pump does not backflow.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Outlet Valve", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Brake fluid discharged from the pump does not backflow.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Return Check Valve", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Returns the brake fluid from brake caliper to master cylinder by bypassing orifice of each valve when brake is released.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Reservoir", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Temporarily reserves the brake fluid drained from brake caliper and wheel cylinder, so that pressure efficiently decreases when decreasing pressure of brake caliper.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Yaw Rate/Side/Decel G Sensor", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Calculates the following information that affects the vehicle, and transmits a signal to ABS actuator and electric unit (control unit) via communication lines. [Yaw rate/side/decel G sensor is integrated in ABS actuator and electric unit (control unit).]", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Vehicle rotation angular velocity (yaw rate signal)", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Vehicle lateral acceleration (side G signal) and longitudinal acceleration (decel G signal)", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Pressure Sensor", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Detects the brake fluid pressure and transmits signal to ABS actuator and electric unit (control unit). [Pressure sensor is integrated in ABS actuator and electric unit (control unit).]", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Brake fluid pressure, and traction motor are controlled according to signals from each sensor.", "ptxt");
si[i++] = gsitm("N5060305C0000O00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060305C0000O00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "Wheel Sensor and Sensor Rotor", "title");
si[i++] = gsitm("N506030610000E00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030610000E00ENG.html", "Wheel sensor and sensor rotor detect each wheel speed. And wheel sensor inputs wheel speed signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030610000E00ENG.html", "The wheel sensor reads a magnetic field change.", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N506030610000E00ENG.html", "Downsize and weight reduction is aimed. IC for detection portion and magnet for sensor rotor are adopted.", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "Power supply is supplied to detection portion so that magnetic field line is read. Magnetic field that is detected is converted to current signal.", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "When sensor rotor rotates, magnetic field changes. Magnetic field change is converted to current signals (rectangular wave) and is transmitted to ABS actuator and electric unit (control unit). Change of magnetic field is proportional to wheel speed.", "ptxt");
si[i++] = gsitm("N506030610000E00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N506030610000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering Angle Sensor", "title");
si[i++] = gsitm("N5060305W0000E00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering angle sensor transmits steering angle sensor signal to ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering angle sensor detects the following status.", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering wheel rotation amount", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering wheel rotation angular velocity", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering wheel rotation direction", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Steering angle sensor converts the rotation amount, rotation angular velocity and rotation direction of the steering wheel as the steering angle sensor signal.", "ptxt");
si[i++] = gsitm("N5060305W0000E00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060305W0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060305G0000E00ENG.html", "Brake Fluid Level Switch", "title");
si[i++] = gsitm("N5060305G0000E00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305G0000E00ENG.html", "Detects the brake fluid level in reservoir tank and transmits converted electric signal from combination meter to ABS actuator and electric unit (control unit) via CAN communication, when brake fluid level is the specified level or less.", "ptxt");
si[i++] = gsitm("N5060305G0000E00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060305G0000E00ENG.html", "Brake fluid level switch detects the brake fluid level in reservoir tank.", "ptxt");
si[i++] = gsitm("N5060305G0000E00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060305G0000E00ENG.html", "The switch is turned ON when brake fluid level is the specified level or less.", "ptxt");
si[i++] = gsitm("N5060305G0000E00ENG.html", "Ground is supplied as the switch signal to the control unit when the switch is ON.", "ptxt");
si[i++] = gsitm("N5060305G0000E00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5060305G0000E00ENG.html", "Refer to .", "ptxt");
