si[i++] = gsitm("N5060307I0000B00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060307I0000B00ENG.html", "Detects the vacuum in brake booster and transmits converted electric signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060307I0000B00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5060307I0000B00ENG.html", "Detects the vacuum in brake booster.", "ptxt");
si[i++] = gsitm("N5060307I0000B00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5060307I0000B00ENG.html", "Brake vacuum sensor converts the brake vacuum sensor signal.", "ptxt");
