si[i++] = gsitm("N5060304O0004C00ENG.html", "System Description", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "The system switches fluid pressure of each brake to increase, to hold or to decrease according to signals from control unit in ABS actuator and electric unit (control unit). This control system is applied to ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Fail-safe function is available for each function and is activated by each function when system malfunction occurs.", "ptxt");
