si[i++] = gsitm("N5060304O0004C00ENG.html", "Pressure increases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front RH brake increases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is conveyed to the pump from the master cylinder through suction valve 1 and is pressurized by the pump operation. The pressurized brake fluid is supplied to the front RH brake through the ABS IN valve. For the left brake, brake fluid pressure is maintained because the pressurization is unnecessary. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front LH brake increases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is conveyed to the pump from the master cylinder through suction valve 2 and is pressurized by the pump operation. The pressurized brake fluid is supplied to the front LH brake through the ABS IN valve. For the right brake, brake fluid pressure is maintained because the pressurization is unnecessary. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear RH brake increases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is conveyed to the pump from the master cylinder through suction valve 2 and is pressurized by the pump operation. The pressurized brake fluid is supplied to the rear RH brake through the ABS IN valve. For the left brake, brake fluid pressure is maintained because the pressurization is unnecessary. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear LH brake increases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is conveyed to the pump from the master cylinder through suction valve 1 and is pressurized by the pump operation. The pressurized brake fluid is supplied to the rear LH brake through the ABS IN valve. For the right brake, brake fluid pressure is maintained because the pressurization is unnecessary. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "ASC Function, TCS Function, Brake Limited Slip Differential (BLSD) Function, Brake Assist Function, Brake force distribution Function, hill start assist Function, and TSA function are in Operation (During Pressure Holds)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When pressure holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Pressure holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front RH brake holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the cut valve 1 and the suction valve 1 are closed, the front RH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the front RH brake. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front LH brake holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the cut valve 2 and the suction valve 2 are closed, the front LH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the front LH brake. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear RH brake holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the cut valve 2 and the suction valve 2 are closed, the rear RH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the rear RH brake. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear LH brake holds", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the cut valve 1 and the suction valve 1 are closed, the rear LH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the rear LH brake. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "ASC Function, TCS Function, Brake Limited Slip Differential (BLSD) Function, Brake Assist Function, Brake force distribution Function, hill start assist Function, and TSA function are in Operation (During Pressure Decrease)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When pressure decrease", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Pressure decreases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front RH brake decreased", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the suction valve 1 and the ABS OUT valve close and the cut valve 1 and the ABS IN valve open, the fluid pressure applied on the front RH brake is reduced by supplying the fluid pressure to the master cylinder via the ABS IN valve and the cut valve 1. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front LH brake decreased", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the suction valve 2 and the ABS OUT valve close and the cut valve 2 and the ABS IN valve open, the fluid pressure applied on the front LH brake is reduced by supplying the fluid pressure to the master cylinder via the ABS IN valve and the cut valve 2. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear RH brake decreased", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the suction valve 2 and the ABS OUT valve close and the cut valve 2 and the ABS IN valve open, the fluid pressure applied on the rear RH brake is reduced by supplying the fluid pressure to the master cylinder via the ABS IN valve and the cut valve 2. The pressurization for the right brake is controlled separately from the left brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear LH brake decreased", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the suction valve 1 and the ABS OUT valve close and the cut valve 1 and the ABS IN valve open, the fluid pressure applied on the rear LH brake is reduced by supplying the fluid pressure to the master cylinder via the ABS IN valve and the cut valve 1. The pressurization for the left brake is controlled separately from the right brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Component Parts and Function", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Pump", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Pressure the brake fluid and send.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Returns the brake fluid reserved in reservoir to master cylinder by reducing pressure.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Motor", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Activates the pump according to signals from ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Shuts off the ordinary brake line from master cylinder.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Supplies the brake fluid from master cylinder to the pump.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Switches the fluid pressure line to increase or hold according.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Switches the fluid pressure line to increase, hold or decrease according.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "return check valve", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Returns the brake fluid from each brake to master cylinder by bypassing orifice of each valve when brake is released.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Reservoir", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Temporarily reserves the brake fluid drained from each brake, so that pressure efficiently decreases when decreasing pressure of each brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Pressure sensor", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Detects the brake fluid pressure and transmits signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "VALVE OPERATION (ABS FUNCTION)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When Brake Pedal is Applied", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When the cut valve 1 and the ABS IN valve opens, brake fluid is supplied to the front RH brake from the master cylinder through the ABS IN valve. Brake fluid does not flow into the reservoir because the ABS OUT valve is closed.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When the cut valve 2 and the ABS IN valve opens, brake fluid is supplied to the front LH brake from the master cylinder through the ABS IN valve. Brake fluid does not flow into the reservoir because the ABS OUT valve is closed.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When the cut valve 2 and the ABS IN valve opens, brake fluid is supplied to the rear RH brake from the master cylinder through the ABS IN valve. Brake fluid does not flow into the reservoir because the ABS OUT valve is closed.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When the cut valve 1 and the ABS IN valve opens, brake fluid is supplied to the rear LH brake from the master cylinder through the ABS IN valve. Brake fluid does not flow into the reservoir because the ABS OUT valve is closed.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When ABS Function is in Operation (During Pressure Increases)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the front RH brake from the master cylinder through the cut valve 1 and the ABS IN valve. Since the suction valve 1 and the ABS OUT valve is closed, the fluid does not flow into the reservoir. The amount of brake fluid supplied to the front RH brake from the master cylinder is controlled according to time that the ABS IN valve is not energized (time that the ABS IN valve is open).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the front LH brake from the master cylinder through the cut valve 2 and the ABS IN valve. Since the suction valve 2 and the ABS OUT valve is closed, the fluid does not flow into the reservoir. The amount of brake fluid supplied to the front LH brake from the master cylinder is controlled according to time that the ABS IN valve is not energized (time that the ABS IN valve is open).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the rear RH brake from the master cylinder through the cut valve 2 and the ABS IN valve. Since the suction valve 2 and the ABS OUT valve is closed, the fluid does not flow into the reservoir. The amount of brake fluid supplied to the rear RH brake from the master cylinder is controlled according to time that the ABS IN valve is not energized (time that the ABS IN valve is open).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the rear LH brake from the master cylinder through the cut valve 1 and the ABS IN valve. Since the suction valve 1 and the ABS OUT valve is closed, the fluid does not flow into the reservoir. The amount of brake fluid supplied to the rear LH brake from the master cylinder is controlled according to time that the ABS IN valve is not energized (time that the ABS IN valve is open).", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When ABS Function is Operating (During Pressure Holds)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve and the ABS OUT valve are closed, the front RH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the front RH brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve and the ABS OUT valve are closed, the front LH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the front LH brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve and the ABS OUT valve are closed, the rear RH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the rear RH brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve and the ABS OUT valve are closed, the rear LH brake, master cylinder, and reservoir are blocked. This maintains fluid pressure applied on the rear LH brake.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When ABS Function is in Operation (During Pressure Decreases)", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When pressure decreases", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve is closed and the ABS OUT valve is opened, fluid pressure applied on the front RH brake is supplied to the reservoir through the ABS OUT valve. This fluid pressure decreases when sent to the master cylinder by the pump.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve is closed and the ABS OUT valve is opened, fluid pressure applied on the front LH brake is supplied to the reservoir through the ABS OUT valve. This fluid pressure decreases when sent to the master cylinder by the pump.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve is closed and the ABS OUT valve is opened, fluid pressure applied on the rear RH brake is supplied to the reservoir through the ABS OUT valve. This fluid pressure decreases when sent to the master cylinder by the pump.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Since the ABS IN valve is closed and the ABS OUT valve is opened, fluid pressure applied on the rear LH brake is supplied to the reservoir through the ABS OUT valve. This fluid pressure decreases when sent to the master cylinder by the pump.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "When Brake Release", "title");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Component pars", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front RH brake release", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the front RH brake through the return check valve of the ABS IN valve and the cut valve 1, and returns to the master cylinder.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure front LH brake release", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the front LH brake through the return check valve of the ABS IN valve and the cut valve 2, and returns to the master cylinder.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear RH brake release", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the rear RH brake through the return check valve of the ABS IN valve and the cut valve 2, and returns to the master cylinder.", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "During pressure rear LH brake release", "ptxt");
si[i++] = gsitm("N5060304O0004C00ENG.html", "Brake fluid is supplied to the rear LH brake through the return check valve of the ABS IN valve and the cut valve 1, and returns to the master cylinder.", "ptxt");
