si[i++] = gsitm("N5060305L0003I00ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ASC FUNCTION, TCS FUNCTION, BRAKE LIMITED SLIP DIFFERENTIAL (BLSD) FUNCTION, BRAKE ASSIST FUNCTION, BRAKE FORCE DISTRIBUTION FUNCTION, hill start assist FUNCTION, TSA FUNCTION", "title");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ASC warning light in combination meter turn ON when a malfunction occurs in system [ABS actuator and electric unit (control unit)]. The control is suspended for ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and TSA function. The vehicle status becomes the same as models without ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and TSA function. However, ABS function and EBD function are operated normally.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ABS FUNCTION", "title");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ABS warning light and ASC warning light in combination meter turn ON when a malfunction occurs in system [ABS actuator and electric unit (control unit)]. The control is suspended for ASC function, TCS function, ABS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function. The vehicle status becomes the same as models without ASC function, TCS function, ABS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function. However, EBD function is operated normally.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ABS self-diagnosis sound may be heard the same as in the normal condition, because self-diagnosis is performed when ignition switch ON and when vehicle initially starts.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "EBD FUNCTION", "title");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ABS warning light, brake warning light and ASC warning light in combination meter turn ON when a malfunction occurs in system [ABS actuator and electric unit (control unit)]. The control is suspended for ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function. The vehicle status becomes the same as models without ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "ELECTRIC PARKING BRAKE FUNCTION", "title");
si[i++] = gsitm("N5060305L0003I00ENG.html", "The electric parking brake warning light and/or electric parking indicator light turns ON when a malfunction with the system occurs.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "When parking brake switch is pulled/pushed during system malfunction, electric parking brake indicator light blinks and electric parking brake warning light turns ON when electric parking brake cannot be operated. It restricts braking and release operations of electric parking brake.", "ptxt");
si[i++] = gsitm("N5060305L0003I00ENG.html", "The parking brake can be mechanically released.", "ptxt");
