si[i++] = gsitm("N5060304O0004E00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5060304O0004E00ENG.html", "Brake fluid level switch signal", "ptxt");
si[i++] = gsitm("N5060304O0004E00ENG.html", "ABS warning light signal", "ptxt");
si[i++] = gsitm("N5060304O0004E00ENG.html", "Brake warning light signal", "ptxt");
si[i++] = gsitm("N5060304O0004E00ENG.html", "ASC OFF indicator light signal", "ptxt");
si[i++] = gsitm("N5060304O0004E00ENG.html", "ASC warning light signal", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "System Description", "title");
si[i++] = gsitm("N5060304O0004F00ENG.html", "By preventing wheel lock through brake force (brake fluid pressure) control that is electronically controlled by detecting wheel speed during braking, stability during emergency braking is improved so that obstacles can be easily bypassed by steering operation.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "During braking, control units calculates wheel speed and pseudo-vehicle speed, and transmits pressure increase, hold or decrease signals to actuator portion according to wheel slip status.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "The following effects are obtained by preventing wheel lock during braking.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "Vehicle tail slip is prevented during braking when driving straight.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "Understeer and oversteer tendencies are moderated during braking driving on a corner.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "Obstacles may be easily bypassed by steering operation during braking.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "M.U.T.-III SE can be used to diagnose the system diagnosis.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "Fail-safe function is adopted. When a malfunction occurs in ABS function, the control is suspended for ASC function, TCS function, ABS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, and hill start assist function. The vehicle status becomes the same as models without ASC function, TCS function, ABS function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and hill decent control. However, EBD function is operated normally. Refer to .", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "ABS function has the characteristic as described here, This is not the device that helps reckless driving.", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "To stop vehicle efficiently, ABS does not operate and ordinary brake operates at low speed [Approximately 10 km/h (6 MPH) or less, but differs subject to road conditions).", "ptxt");
si[i++] = gsitm("N5060304O0004F00ENG.html", "Self-diagnosis is performed immediately after when engine starts and when vehicle initially is driven [by vehicle speed approximately 15 km/h (9 MPH)]. Motor sounds are generated during self-diagnosis. In addition, brake pedal may be felt heavy when depressing brake pedal lightly. These symptoms are not malfunctions.", "ptxt");
