si[i++] = gsitm("N5060305I0000Y00ENG.html", "ACTIVE TEST", "title");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "The active test is used to determine and identify details of a malfunction, based on self-diagnosis test results and data obtained in the data monitor. In response to instructions from M.U.T.-III SE, instead of those from ABS actuator and electric unit (control unit) on the vehicle, a drive signal is sent to the actuator to check its operation.", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "Never perform active test while driving the vehicle.", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "Always bleed air from brake system before active test.", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "Never perform active test when system is malfunctioning.", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "\"TEST IS STOPPED\" is displayed approximately 10 seconds after operation start.", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "When performing active test again after \"TEST IS STOPPED\" is displayed, select \"BACK\".", "ptxt");
si[i++] = gsitm("N5060305I0000Y00ENG.html", "ABS warning light, brake warning light and ASC warning light may turn ON during active test. This is not a malfunction.", "ptxt");
