si[i++] = gsitm("N506030580001800ENG.html", "Work Flow", "title");
si[i++] = gsitm("N506030580001800ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N506030580001800ENG.html", "INTERVIEW FROM THE CUSTOMER", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Clarify customer complaints before inspection. First of all, perform an interview utilizing  and reproduce the symptom as well as fully understand it. Ask customer about his/her complaints carefully. Check symptoms by driving vehicle with customer, if necessary.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Customers are not professional. Never guess easily like \"maybe the customer means that...,\" or \" maybe the customer mentions this symptom\".", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "CHECK SYMPTOM", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Reproduce the symptom that is indicated by the customer, based on the information from the customer obtained by interview. Also check that the symptom is not caused by fail-safe mode. Refer to .", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "When the symptom is caused by normal operation, fully inspect each portion and obtain the understanding of customer that the symptom is not caused by a malfunction.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "PERFORM THE SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N506030580001800ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Ignition switch OFF (Auto ACC function OFF) to ON.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Perform self-diagnosis for \"ABS\".", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N506030580001800ENG.html", "YES", "result");
si[i++] = gsitm("N506030580001800ENG.html", "Record or print self-diagnosis results and freeze frame data (FFD). GO TO 4.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "NO", "result");
si[i++] = gsitm("N506030580001800ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "RECHECK THE SYMPTOM", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Erase self-diagnostic results for \"ABS\".", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Ignition switch OFF (Auto ACC function OFF) → ON → OFF (Auto ACC function OFF).", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Perform DTC confirmation procedures for the error-detected system.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "If some DTCs are detected at the same time, determine the order for performing the diagnosis based on .", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Check harness and connectors based on the information obtained by interview. Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "REPAIR OR REPLACE ERROR-DETECTED PART", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Disconnect 12V battery negative terminal.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Repair or replace error-detected parts.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Reconnect part or connector after repairing or replacing.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Connect 12V battery negative terminal.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "When DTC is detected, erase self-diagnostic result for \"ABS\".", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Ignition switch OFF (Auto ACC function OFF) → ON → OFF (Auto ACC function OFF) after erase self-diagnosis result.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "IDENTIFY ERROR-DETECTED SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Estimate error-detected system based on symptom diagnosis and perform inspection.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Can the error-detected system be identified?", "question");
si[i++] = gsitm("N506030580001800ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N506030580001800ENG.html", "Check the reference value for \"ABS\".", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Recheck the symptom and check that the symptom is not reproduced on the same conditions.", "ptxt");
si[i++] = gsitm("N506030580001800ENG.html", "Is the symptom reproduced?", "question");
si[i++] = gsitm("N506030580001800ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N506030290000Q00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N506030290000Q00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N506030290000Q00ENG.html", "In general, customers have their own criteria for a problem. Therefore, it is important to understand the symptom and status well enough by asking the customer about his/her concerns carefully. To systemize all the information for the diagnosis, prepare the interview sheet referring to the interview points.", "ptxt");
si[i++] = gsitm("N506030290000Q00ENG.html", "In some cases, multiple conditions that appear simultaneously may cause a DTC to be detected.", "ptxt");
