si[i++] = gsitm("N5060305A000A200ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "Description", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "When replacing the ABS actuator and electric unit (control unit), the procedures of AFTER REPLACEMENT must be performed.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "After replacing the ABS actuator and electric unit (control unit), the following items must be performed:", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "ABS actuator and electric unit (control unit) programming", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "ABS actuator and electric unit (control unit) configuration", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Air bleeding of brake fluid", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Adjust the neutral position of steering angle sensor", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Calibration of the decel G sensor", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Calibration of side G sensor", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Adjustment of rear brake caliper initialization position", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Change of system mode", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Driving 3 km or more", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Save the odometer information of combination meter in ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Work Procedure [After Replace ABS actuator and electric unit (control unit)]", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "PERFORM PROGRAMMING", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform ABS actuator and electric unit (control unit) programming according to the procedure of \"Programming\" in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Electric parking brake: Apply", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "12V battery voltage: 12 – 13.5 V (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "PERFORM NECESSARY WORK", "title");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform air bleeding. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform adjustment of steering angle sensor neutral position. Refer to Description.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform calibration of decel G sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Calibration of side G sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Adjustment of rear brake caliper initialization position. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform the change of system mode. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform the driving 3 km or more.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Raise the vehicle.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Connect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Drive the vehicle at 30 km/h or more until the driving distance displayed on the combination meter is reflected in the Service data No. 30: Odometer.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Perform self-diagnosis for \"Read All DTCs\".", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "Erase the memory of self-diagnosis results.", "ptxt");
si[i++] = gsitm("N5060305A000A200ENG.html", "End of work.", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "Description", "title");
si[i++] = gsitm("N506030200006500ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "For details the network connection and operation, refer to \"M.U.T.-III SE Operation Manual\".", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "The configuration no need to \"save\" configuration data from the ABS actuator and electric unit (control unit). The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "Complete the procedure of \"Configuration\" in order.", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "If incorrect \"Configuration\", incidents might occur.", "ptxt");
si[i++] = gsitm("N506030200006500ENG.html", "Never perform \"Configuration\" except for new ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5060305A0003400ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5060305A0003400ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5060305A0003400ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5060305A0003400ENG.html", "Perform writing vehicle specification to ABS actuator and electric unit (control unit) following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5060305A0003400ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5060305A0003400ENG.html", "For details the network connection and operation, refer to \"M.U.T.-III SE Operation Manual\".", "ptxt");
si[i++] = gsitm("N5060305A0003400ENG.html", "WORK END", "ptxt");
