si[i++] = gsitm("N5060305A0003500ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "Always use M.U.T.-III SE when adjusting the neutral position of steering angle sensor. (It cannot be adjusted other than with M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "CHECK THE VEHICLE STATUS (1)", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "Stop vehicle with front wheels in the straight-ahead position.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Does the vehicle stay in the straight-ahead position?", "question");
si[i++] = gsitm("N5060305A0003500ENG.html", "YES", "result");
si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "NO", "result");
si[i++] = gsitm("N5060305A0003500ENG.html", "Steer the steering wheel to the straight-ahead position. Stop the vehicle.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "ADJUST NEUTRAL POSITION OF STEERING ANGLE SENSOR", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Never start engine.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Select \"ABS\", \"Sensor calibration\" (in \"Special function\") and \"ST ANGLE SENSOR ADJUSTMENT\" in this order.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Select \"OK\".", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Never touch steering wheel while adjusting steering angle sensor.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "After \"Completed\" is displayed, wait bout 10 seconds and press \"OK\".", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Ignition switch OFF (Auto ACC function OFF), and then it ON again.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Be sure to perform the operation above.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "CHECK DATA MONITOR (1)", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "The vehicle is either pointing straight ahead, or the vehicle needs to be moved. Stop when it is pointing straight ahead.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Select \"ABS\", \"Data List\", and \"Steering angle\" in the order. Check that the signal is within the specified value. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Is the inspection result normal?", "question");
