si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Repair or replace error-detected parts. GO TO 5.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "CHECK FRONT SUSPENSION COMPONENT PARTS", "title");
