si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Repair or replace error-detected parts. GO TO 6.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "CHECK FRONT WHEEL ALIGNMENT", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "Check the front wheel alignment. Refer to .", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Adjust the front wheel alignment. Refer to . GO TO 7.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "CHECK THE VEHICLE STATUS (2)", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "GO TO 8.", "ptxt");
