si[i++] = gsitm("N5060305A0003500ENG.html", "EPS LEARNING", "title");
si[i++] = gsitm("N5060305A0003500ENG.html", "Pull the parking brake switch.", "ptxt");
si[i++] = gsitm("N5060305A0003500ENG.html", "Check the parking brake switch indicator is turn On.", "ptxt");
