si[i++] = gsitm("N506010270000400ENG.html", "Perform self-diagnosis for \"ABS\".", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N506010270000400ENG.html", "YES", "result");
si[i++] = gsitm("N506010270000400ENG.html", "Check the DTC. Refer to", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "NO", "result");
si[i++] = gsitm("N506010270000400ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "CHECK DRIVE MODE SELECT SWITCH CIRCUIT", "title");
si[i++] = gsitm("N506010270000400ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Disconnect drive mode select switch harness connector and chassis control module harness connector.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Check the continuity between drive mode select switch harness connector and chassis control module harness connector.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Drive mode select switch", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Continuity", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Connector", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Terminal", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "M186", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "3", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "M18", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "25", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Existed", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Also check harness for short to ground and to power.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N506010270000400ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Repair / replace harness or connector.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "CHECK DRIVE MODE SELECT SWITCH GROUND CIRCUIT", "title");
si[i++] = gsitm("N506010270000400ENG.html", "Check the continuity between drive mode select switch harness connector and ground.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "–", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "4", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Ground", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "CHECK HILL DESCENT CONTROL SWITCH", "title");
si[i++] = gsitm("N506010270000400ENG.html", "Check hill descent control switch.", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N506010270000400ENG.html", "Replace drive mode select switch. Refer to HDC Switch Removal and Installation .", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Description", "title");
si[i++] = gsitm("N506030200006I00ENG.html", "Symptom", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Result", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Brake pedal slightly vibrates and operation sound (motor sound and sound from suspension) occurs when ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, or TSA function operates.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "This is not a malfunction, because it is caused by ASC function, TCS function, ABS function, EBD function, brake limited slip differential (BLSD) function, brake assist function, brake force distribution function, hill start assist function, and TSA function that are normally operated.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Brake stopping distance may become longer than models without ABS function depending on the road conditions, when ABS function is operated on slippery road like rough road, gravel road or snowy road.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Brake pedal vibrates and operation sound occurs during sudden acceleration and cornering, when ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function or brake force distribution function is operated.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Brake pedal vibrates and motor sound from the engine room occurs, when the engine starts or the vehicle starts just after starting the engine.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "This is not a malfunction, because it is caused by operation check of ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Acceleration may be felt insufficient depending on the road conditions.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "This is not a malfunction, because it is caused by TCS function that puts the highest priority to obtain the optimum traction (stability).", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "TCS function may operate momentarily, while driving on a road where friction coefficient varies, or when downshifting, or fully depressing accelerator pedal.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "ABS warning light and ASC warning light may turn ON, when the vehicle is on a rotating turntable or is given a strong shaking or large vibrations on a ship while the engine is running.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "In this case, restart the engine on a normal road. If the normal condition is restored, there is no malfunction. In that case, erase \"ABS\" self-diagnosis result memory with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "ASC warning light may turn ON and ASC function, TCS function, brake limited slip differential (BLSD) function, brake assist function and brake force distribution function may not normally operate, when driving on a special road the is extremely slanted (bank in a circuit course).", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "A malfunction in yaw rate/side/decel G sensor system may be detected when the vehicle sharply turns during a spin turn, acceleration turn or drift driving while ASC function, TCS function, brake assist function and brake force distribution function are OFF (ASC OFF indicator light is in ON status).", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "The vehicle speed does not increase, when the accelerator pedal is depressed while the vehicle is on a 2-wheel chassis dynamometer for speedometer check.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "This is normal. (When checking the vehicle on a chassis dynamometer, operate ASC OFF so that TCS function is OFF.)", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "Flow sound of brake fluid from engine room occurs when hill start assist function operates.", "ptxt");
si[i++] = gsitm("N506030200006I00ENG.html", "This is not a malfunction, because it is caused by hill start assist function that is normally operated.", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5060302N0001700ENG.html", "&lt;LHD>", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "&lt;RHD>", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "ABS actuator and electric unit (control unit) harness connector", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "Bracket", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To master cylinder secondary side", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To master cylinder primary side", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To rear RH caliper", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To front LH caliper", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To front RH caliper", "ptxt");
si[i++] = gsitm("N5060302N0001700ENG.html", "To rear LH caliper", "ptxt");
