si[i++] = gsitm("N506030490005D00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506030490005D00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506030490005D00ENG.html", "Disconnect the battery cable from negative terminal. Refer to", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Drain brake fluid. Refer to Draining.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove the engine cover. Refer to .", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove the cowl top extension. Refer to .", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove heat insulator .", "par1");
si[i++] = gsitm("N506030490005D00ENG.html", ": Vehicle front", "par5");
si[i++] = gsitm("N506030490005D00ENG.html", "Disconnect ABS actuator and electric unit (control unit) harness connector , follow the procedure below.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Down the pawl .", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Push the connector .", "par6");
si[i++] = gsitm("N506030490005D00ENG.html", "Move the lever  in the direction  until locked.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Disconnect ABS actuator and electric unit (control unit) harness connector.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Loosen flare nut of brake tube using a flare nut wrench.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove front brake piping from the clip.", "par7");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove the bolt at the ABS actuator and electric unit (control unit) bracket upper side, then remove the ABS actuator and electric unit as a set with bracket.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Never remove and never install ABS actuator and electric unit (control unit) by holding harness connector.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Be careful not to drop ABS actuator and electric unit (control unit) and apply excessive impact to it.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Remove bracket from ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506030490005D00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "When replacing ABS actuator and electric unit (control unit), remove the inlet hole protector for brake tube just before performing.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "When installing brake tube, tighten to the specified torque using a flare nut torque wrench so that flare nut and brake tube are not damaged. Refer to", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Never remove and install actuator by holding actuator harness.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Bleed air from brake piping after installation. Refer to .", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "Never apply excessive impact to actuator, such as by dropping it.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "After installing the ABS actuator and electric unit (control unit) harness connector , move the lever  in the direction  and up the pawl  to secure the locking.", "ptxt");
si[i++] = gsitm("N506030490005D00ENG.html", "When replacing the ABS actuator and electric unit (control unit), be sure to perform the configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5060302N0001800ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5060302N0001800ENG.html", "Front LH wheel sensor", "ptxt");
si[i++] = gsitm("N5060302N0001800ENG.html", "Identification line", "par4");
si[i++] = gsitm("N5060302N0001800ENG.html", ": Vehicle front", "par6");
si[i++] = gsitm("N5060302N0001800ENG.html", ": N·m (kg-m, in-lb)", "ptxt");
si[i++] = gsitm("N5060302N0001800ENG.html", "Front RH wheel sensor is symmetrically opposite of LH.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506030490002E00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506030490002E00ENG.html", "Remove tires. Refer to Removal and Installation.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Remove front wheel sensor from steering knuckle.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Never rotate and never pull front wheel sensor as much as possible, when pulling out.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Remove front wheel sensor harness from the vehicle.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Never twist or pull front wheel sensor harness, when removing.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506030490002E00ENG.html", "Note the following, and install in the reverse order of the removal.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Check that there is no foreign material like iron powder or damage on inner surface of front wheel sensor mounting hole of steering knuckle and sensor rotor. Install after cleaning when there are foreign material like iron powder, or replace when there is a malfunction.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Never twist front wheel sensor harness when installing front wheel sensor. Check that grommet  is fully inserted to bracket . Check that front wheel sensor harness is not twisted after installation.", "ptxt");
si[i++] = gsitm("N506030490002E00ENG.html", "Check that front wheel sensor identification line faces toward the vehicle front.", "ptxt");
si[i++] = gsitm("N5060302N0001900ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5060302N0001900ENG.html", "Parking brake actuator harness and rear wheel sensor", "ptxt");
si[i++] = gsitm("N5060302N0001900ENG.html", "Axle housing", "par6");
si[i++] = gsitm("N5060302N0001900ENG.html", ": Vehicle front", "par1");
si[i++] = gsitm("N5060302N0001900ENG.html", ": N·m (kg-m, ft-lb)", "par9");
si[i++] = gsitm("N5060302N0001900ENG.html", ": N·m (kg-m, in-lb)", "par2");
si[i++] = gsitm("N5060302N0001900ENG.html", "Rear RH wheel sensor is symmetrically opposite of LH.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506030490002F00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506030490002F00ENG.html", "Remove tire. Refer to .", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Disconnect parking brake actuator harness and rear wheel sensor harness connectors.", "par1");
si[i++] = gsitm("N506030490002F00ENG.html", "Never twist and never pull rear wheel sensor harness, when removing.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Remove parking brake actuator harness and rear wheel sensor mounting bolts.", "par2");
si[i++] = gsitm("N506030490002F00ENG.html", "Remove parking brake actuator harness and rear wheel sensor.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Never rotate or pull rear wheel sensor as much as possible, when pulling out.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506030490002F00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Check that there is no foreign material like iron powder or damage on inner surface of rear wheel sensor mounting hole. Install after cleaning when there are foreign material like iron powder, or replace when there is a malfunction.", "ptxt");
si[i++] = gsitm("N506030490002F00ENG.html", "Never twist rear wheel sensor harness when installing rear wheel sensor. Check that grommet  is fully inserted to bracket . Check that rear wheel sensor harness is not twisted after installation.", "ptxt");
si[i++] = gsitm("N506030490002G00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506030490002G00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N506030490002G00ENG.html", "Remove spiral cable assembly. Refer to .", "ptxt");
si[i++] = gsitm("N506030490002G00ENG.html", "Remove steering angle sensor from spiral cable.", "ptxt");
si[i++] = gsitm("N506030490002G00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N506030490002G00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N506030490002G00ENG.html", "Perform steering angle sensor neutral position adjustment when steering angle sensor is removed and installed, or replaced. Refer to .", "ptxt");
si[i++] = gsitm("N506030490002G00ENG.html", "Perform steering torque calibration after replacing or removal and installation the steering angle sensor. Refer to .", "par1");
si[i++] = gsitm("N506030490005B00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N506030490005B00ENG.html", "An HDC switch is incorporated in the drive mode selector. Refer to Shift Lever Panel, Shift Lever Panel Removal and Installation.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5060305T0001P00ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5060305T0001P00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5060305T0001P00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N506030430003G00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N506030430003G00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N506030430003G00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5060307H0000M00ENG.html", "Precautions for Harness Repair", "title");
si[i++] = gsitm("N5060307H0000M00ENG.html", "Solder the repaired area and wrap tape around the soldered area.", "ptxt");
si[i++] = gsitm("N5060307H0000M00ENG.html", "A fray of twisted lines must be within 110 mm (4.33 in).", "ptxt");
si[i++] = gsitm("N5060307H0000M00ENG.html", "Bypass connection is never allowed at the repaired area.", "ptxt");
si[i++] = gsitm("N5060307H0000M00ENG.html", "Bypass connection may cause CAN communication error. The spliced wire becomes separated and the characteristics of twisted line are lost.", "ptxt");
si[i++] = gsitm("N5060307H0000M00ENG.html", "Replace the applicable harness as an assembly if error is detected on the shield lines of CAN communication line.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "Precaution for Automatic Brake Hold", "title");
si[i++] = gsitm("N506030C80000O00ENG.html", "Do not disassemble chassis control module.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "Do not use any parts that have been dropped.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "Do not perform active test during driving.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "Do not operate automatic brake hold on a steep slope or a slippery road. (The vehicle may move even when automatic brake hold is applied.)", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When the stopped condition of the vehicle cannot be maintained by automatic brake hold, depress brake pedal to maintain the stopped condition.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "Master warning light (yellow) illuminates if a malfunction occurs in automatic brake hold system. A pop-up screen also appears on information display of combination meter. Refer to .", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When the vehicle is moved or may start moving while automatic brake hold is being applied, master warning light (red) illuminates, and a warning chime sounds at the same time. A pop-up screen also appears on information display of combination meter. Refer to .", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When the vehicle is to be moved by towing, car washing machine, or other means, turn OFF automatic brake hold.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When parking the vehicle, shifting the electric shift selector to P range and apply parking brake.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When getting on the vehicle or when loading/unloading a cargo, shifting the electric shift selector to P range and apply parking brake.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "When ASC warning light or electric parking brake warning light is illuminated, automatic brake hold does not operate.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "The automatic brake hold function resets to OFF every time the ignition switch is switched from ON to OFF. &lt;Up To 22 Model Year>", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "The automatic brake hold function memorizes the status of when the ignition switch is turned to OFF position, and it takes over the status the next time the ignition switch is turned to ON position. &lt;From 23 Model Year>", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "While automatic brake hold is being applied, the system may apply the brakes to maintain the stopped condition of the vehicle. At this time, a operating noise may be generated. These are not symptoms of malfunctions and indicate normal operating conditions.", "ptxt");
si[i++] = gsitm("N506030C80000O00ENG.html", "If the switch indicator does not illuminate after operating automatic brake hold switch, inspect brake control system and parking brake system in addition to automatic brake hold system.", "ptxt");
