si[i++] = gsitm("N5060301T0001G00ENG.html", "Refer to  (full TFT meter),  (7 inch information display) for detailed installation location.", "ptxt");
si[i++] = gsitm("N5060301T0001G00ENG.html", "Automatic brake hold switch indicator", "ptxt");
si[i++] = gsitm("N5060301T0001G00ENG.html", "Parking brake switch (automatic brake hold switch)", "ptxt");
si[i++] = gsitm("N5060301T0001G00ENG.html", "Chassis control module", "ptxt");
si[i++] = gsitm("N506030C90000B00ENG.html", "Chassis Control Module", "title");
si[i++] = gsitm("N506030C90000B00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030C90000B00ENG.html", "Chassis control module part controls automatic brake hold according to the signals from each sensor, each switch and each control unit.", "ptxt");
si[i++] = gsitm("N506030C90000B00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030C90000B00ENG.html", "Transmits automatic brake hold activation request signal and automatic brake hold deactivation request signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030C90000B00ENG.html", "Transmits electric parking brake signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N506030C90000B00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N506030C90000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "Parking Brake Switch (Automatic Brake Hold Switch)", "title");
si[i++] = gsitm("N506030CA0000N00ENG.html", "Parking brake switch , automatic brake hold switch , and indicator  are single unit.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030CA0000N00ENG.html", "By operating automatic brake hold switch, turn ON/OFF automatic brake hold function.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N506030CA0000N00ENG.html", "Turns ON/OFF automatic brake hold switch, and turns ON/OFF automatic brake hold function by chassis control module.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "According to the control of chassis control module, automatic brake hold switch indicator turns ON/OFF.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "A normal open type is used for automatic brake hold switch.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "If automatic brake hold switch is pressed when automatic brake hold function is OFF, automatic brake hold function turns ON. In addition, automatic brake hold switch indicator illuminates.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "The automatic brake hold function resets to OFF every time the ignition switch is switched from ON to OFF. &lt;Up To 22 Model Year>", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "The automatic brake hold function memorizes the status of when the ignition switch is turned to OFF position, and it takes over the status the next time the ignition switch is turned to ON position. &lt;From 23 Model Year>", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "If automatic brake hold switch is pressed when automatic brake hold function is ON, automatic brake hold function turns OFF. In addition, automatic brake hold switch indicator turns OFF.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "To turn OFF automatic brake hold function while the brakes are held by automatic brake hold, press automatic brake hold switch while depressing brake pedal.", "ptxt");
si[i++] = gsitm("N506030CA0000N00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N506030CA0000N00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "System Description", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold is used for holding the brakes automatically when the vehicle is stopped by a brake operation.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold is used to reduce continuous brake pedal operations by the driver.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold is controlled by chassis control module.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Chassis control module receives information required for controlling via CAN communication and from each switch to control automatic brake hold.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Signal description", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Mainly transmits the following signals to chassis control module via CAN communication.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Accelerator pedal position signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Engine torque signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Current gear position signal", "ptxt");
