si[i++] = gsitm("N5060304O0009300ENG.html", "Front RH wheel speed signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Rear LH wheel speed signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Rear RH wheel speed signal", "ptxt");
