si[i++] = gsitm("N5060304O0009300ENG.html", "Decel G signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Electric parking brake malfunction signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Mainly receives the following signals from chassis control module via CAN communication.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold indicator light signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Meter display signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Brake pedal status signal", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Seat belt buckle switch (driver side) signal", "ptxt");
