si[i++] = gsitm("N5060304O0009300ENG.html", "Parking brake switch", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "(automatic brake hold switch)", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "OPERATION", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic Brake Hold Function ON (Operation Permitted)", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If automatic brake hold switch is pressed when ignition switch is ON, automatic brake hold function turns ON. In addition, automatic brake hold switch indicator illuminates.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "The automatic brake hold function resets to OFF every time the ignition switch is switched from ON to OFF. &lt;Up To 22 Model Year>", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "The automatic brake hold function memorizes the status of when the ignition switch is turned to OFF position, and it takes over the status the next time the ignition switch is turned to ON position. &lt;From 23 Model Year>", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic Brake Hold Function OFF (Operation Not Permitted)", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If automatic brake hold switch is pressed when automatic brake hold function is ON, automatic brake hold function turns OFF. In addition, automatic brake hold switch indicator turns OFF. [If automatic brake hold indicator light (white or green) is ON, it turns OFF.]", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "To turn OFF automatic brake hold function while the brakes are held by automatic brake hold, press automatic brake hold switch while depressing brake pedal.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Standby", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "When all of the following conditions are satisfied, automatic brake hold enters in the standby state, and automatic brake hold indicator light (white) illuminates.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Seat belt (driver side) is fastened", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Parking brake release", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Electric shift selector is other than P range.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Operation", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If all of the following conditions are satisfied in the standby state, automatic brake hold operates, and the color of automatic brake hold indicator light changes from white to green. In addition, automatic brake display appears on information display of combination meter.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Although the conditions are satisfied in the standby state, automatic brake hold may not operate depending on how far brake pedal is depressed. When automatic brake hold does not operate, depress brake pedal far enough until automatic brake hold indicator light (green) turns on.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Vehicle speed: 0 km/h (0 MPH)", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Brake pedal is depressed", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold is in the standby state [automatic brake hold switch indicator and automatic brake hold indicator light (white) are illuminated]", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Not on a steep slope", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Release (Starting Vehicle)", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If the following condition is satisfied while automatic brake hold is being applied, automatic brake hold is released. (The color of automatic brake hold indicator light changes from green to white.)", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "When depressing accelerator pedal at except P range and N range just before moving the vehicle.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Release (Changing to Parking Brake)", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If any of the following conditions are met while automatic brake hold is being applied, parking brake is operated automatically, and automatic brake hold is released. (Automatic brake hold indicator light turns OFF.)", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Operation of automatic brake hold is continued for approximately 3 minutes", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Seat belt (driver side) is unfastened", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Ignition switch OFF", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "A malfunction is detected in automatic brake hold", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Electric shift selector is P range", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Parking", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "If shifting the electric shift selector to P range while automatic brake hold is being applied, automatic brake hold is released. (Automatic brake hold indicator light turns OFF.)", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Timing Chart", "title");
si[i++] = gsitm("N5060304O0009300ENG.html", "The vehicle is started while automatic brake hold is being applied", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "When the vehicle is stopped by a brake operation by the driver, maintaining of brake fluid pressure is started.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Automatic brake hold is applied (this function holds brake fluid pressure even after the driver has released brake pedal).", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "When the driver performs starting operation, automatic brake hold is released (brake fluid pressure is decreased).", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "Changing the vehicle holding method to parking brake while automatic brake hold is being applied", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "When the vehicle is stopped by a brake operation by the driver, maintaining of the brake fluid pressure is started.", "ptxt");
si[i++] = gsitm("N5060304O0009300ENG.html", "If the conditions for changing to parking brake are satisfied while automatic brake hold is being applied, the method of holding the vehicle stopped is automatically changed to parking brake.", "ptxt");
si[i++] = gsitm("N5060302O0000Z00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5060302O0000Z00ENG.html", "Refer to .", "ptxt");
