si[i++] = gsitm("N506030CD0000B00ENG.html", "Automatic Brake Hold Warning", "title");
si[i++] = gsitm("N506030CD0000B00ENG.html", "DESIGN/PURPOSE", "title");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Notifies the driver when the vehicle is moved or may start moving while automatic brake hold is being applied.", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Waning Message", "title");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Design", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Warning message", "ptxt");
