si[i++] = gsitm("N506030CD0000B00ENG.html", "Press brake pedal", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "When the vehicle moves or possibly moves while automatic brake hold activates.", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Caution Steep slope", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "When the automatic brake hold activates on the steep slope.", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Steep Slope Apply foot brake", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "When the brake pedal is not depressed while the automatic brake hold activates on the steep slope for 3 minutes approximately.", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "Press brake to operate switch", "ptxt");
si[i++] = gsitm("N506030CD0000B00ENG.html", "When the automatic brake hold switch is pushed without depressing brake pedal while the automatic brake hold activates.", "ptxt");
