si[i++] = gsitm("N5060304O0004N00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The AEB system measures the distance from a vehicle ahead using the distance sensor installed in the front grill and front camera unit installed in the windshield glass.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The AEB system detects a pedestrian using the front camera unit installed in the windshield glass.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the system judges that a vehicle or pedestrian is being approached, warning indicators are displayed on the information display and at the same time a warning chime sounds, and the brake is operated.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When it is further judged that the vehicle or pedestrian may collide with the vehicle ahead, the system operates the brake strongly to avoid collision while warning indicators are displayed on the information display and at the same time a warning chime sounds.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Start of warning and partial brake", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Start of harder brake", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Applies partial braking", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Harder brake", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Situation", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Brake", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Warning", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "No obstacle approached", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "No operation", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "—", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Partial brake", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Sounds the buzzer", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Indicates warning indicators on the information display", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "(Higher pitched buzzer)", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "It is the driver′s responsibility to stay alert, drive safely and be in control of the vehicle at all times. As there is a performance limit, it may not provide a warning or brake in certain conditions.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The distance sensor measures the distance from the vehicle ahead and transmits the distance sensor signal to the ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The front camera unit measures the distance from a pedestrian and transmits the pedestrian ahead signal to ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The ADAS control unit 2 judges the possibility of a collision from the distance sensor signal, the pedestrian ahead signal and the vehicle speed.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The ADAS control unit 2 performs the following operations according to the degree of possibility of a collision.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Transmits the buzzer output signal to the combination meter and sounds the buzzer.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Transmits the meter display signal to the combination meter and displays a state of the system on the information display.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Transmits the brake fluid pressure control signal to the ABS actuator and electric unit (control unit) and performs the brake control.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Transmits the stop light request signal to the BCM and turns ON the stop light.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "ON/OFF of AEB system is performed with the information display.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the ignition switch is turned from OFF to ON, the system is automatically activated even if it is OFF.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The AEB system operates under the following conditions.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The AEB system will function when the vehicle is driven at speeds of approximately 10 km/h (6 MPH) and above, and when the vehicle′s speed is approximately 10 km/h (6 MPH) faster than that of the vehicle ahead. (For vehicle)", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5060304O0004N00ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "AEB system: ON", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Vehicle speed (For vehicle): Approximately 10 km/h (6 MPH) or more", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "Vehicle speed (For pedestrian): Approximately 10 – 80 km/h (6 – 50 MPH)", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When there is a possibility of a collision with the vehicle or pedestrian ahead.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5060304O0004N00ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the system judges that the vehicle comes to a standstill by the system control.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the distance sensor area of the front grill is dirty and the measurement of the distance between the vehicles becomes difficult. (For vehicle)", "ptxt");
si[i++] = gsitm("N5060304O0004N00ENG.html", "When the view of ahead is hard is recognized due to dirt around front camera unit of windshield. (For pedestrian)", "ptxt");
