si[i++] = gsitm("N5060303G0000V00ENG.html", "Indicates that AEB system is ON", "ptxt");
si[i++] = gsitm("N5060303G0000V00ENG.html", "Blinks when approaching vehicle ahead", "ptxt");
si[i++] = gsitm("N5060303G0000V00ENG.html", "AEB warning", "ptxt");
si[i++] = gsitm("N5060303G0000V00ENG.html", "Displays immediately before the brake operates", "ptxt");
