si[i++] = gsitm("N5060302X0000M00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5060302X0000M00ENG.html", "DISTANCE SENSOR HANDLING", "title");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Refer to Precautions for Predictive Forward Collision Warning(PFCW).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "FRONT CAMERA UNIT HANDLING", "title");
