si[i++] = gsitm("N5060302X0000M00ENG.html", "PRECAUTIONS FOR AEB", "title");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Failure to follow the warnings and instructions for proper use of the AEB with pedestrian detection system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system is a supplemental aid to the driver. It is not a replacement for the driver\'s attention to traffic conditions or responsibility to drive safely. It cannot prevent accidents due to carelessness or dangerous driving techniques.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system does not function in all driving, traffic, weather and road conditions.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Listed below are the system limitations for the AEB with pedestrian detection system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system cannot detect all vehicles, pedestrians or cyclists under all conditions.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system does not detect the following:", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Pedestrians that are small (for example, children), in a sitting position, operating toys/skateboards, on scooters or in wheelchairs, or not in an upright standing or walking position.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Animals of any size.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Obstacles (for example, cargo or debris) on the roadway or roadside.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Oncoming or crossing vehicles.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Vehicles where the tires are difficult to see or the shape of the rear of the vehicle is unclear or obstructed.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Parked vehicles.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system has some performance limitations.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If a stationary vehicle is in the vehicle\'s path, the system does not function when the vehicle approaches the stationary vehicle at speeds over approximately 80 km/h (50 MPH).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Pedestrian and cyclist detection does not function when the vehicle is driven at speeds over approximately 60 km/h (37 MPH) or below approximately 10 km/h (6 MPH).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "For pedestrians, the AEB with pedestrian detection system does not issue the first warning.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system may not function properly or detect a vehicle, pedestrian or cyclist ahead in the following conditions:", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "In poor visibility conditions (such as rain, snow, fog, dust storms, sand storms, smoke, and road spray from other vehicles).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If dirt, ice, snow, fog or other material is covering the radar sensor area or camera area of the windshield.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If strong light (for example, sunlight or high beams) enters the front camera or a sudden change in brightness occurs (for example, entering a tunnel or driving in lightning).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "In dark or dimly lit conditions, such as at night or in tunnels, including cases where own vehicle\'s headlights are off or dim, or the tail lights of the vehicle ahead are off.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When the direction of the camera is misaligned.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When driving on a steep downhill slope, on roads with sharp curves, and/or bumpy or dirt roads.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If there is interference by other radar sources.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When own vehicle\'s position or movement is changed quickly or significantly (for example, lane change, turning vehicle, abrupt steering, sudden acceleration or deceleration).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When own vehicle or the vehicle, pedestrian or cyclist ahead moves quickly or significantly such that the system cannot detect and react in time (for example, pedestrian moving quickly toward the vehicle at close range, vehicle cutting in, changing lanes, making a turn, steering abruptly, sudden acceleration or deceleration).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When the vehicle, pedestrian or cyclist is offset from the vehicle\'s forward path.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If the speed difference between the two vehicles is small.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The pedestrian\'s profile is partially obscured or unidentifiable; for example, due to transporting luggage, pushing a stroller, wearing bulky or very loose-fitting clothing or accessories, or being in a unique posture (such as raising hands).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "There is poor contrast of a person to the background, such as having clothing color or pattern which is similar to the background.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "For approximately 15 seconds after starting the engine.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "If the vehicle ahead has a unique or unusual shape, extremely low or high clearance heights, or unusual cargo loading or is narrow (for example, a motorcycle).", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When the vehicle, pedestrian or cyclist is located near a traffic sign, a reflective area (for example, water on road), or is in a shadow.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When multiple pedestrians or cyclists are grouped together.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "When the view of the pedestrian or cyclist is obscured by a vehicle or other object.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "While towing a trailer or other vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The system performance may be degraded in the following conditions:", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The vehicle is driven on a slippery road.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The vehicle is driven on a slope.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Excessively heavy baggage is loaded in the rear seat or the cargo area of own vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The system is designed to automatically check the sensor (radar and camera)\'s functionality, within certain limitations. The system may not detect some forms of obstruction of the sensor area such as ice, snow or stickers, for example. In these cases, the system may not be able to warn the driver properly. Be sure that the driver checks, clean and clear sensor areas regularly.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "In some road and traffic conditions, the AEB with pedestrian detection system may unexpectedly apply partial braking. When acceleration is necessary, depress the accelerator pedal to override the system.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system may operate when a pattern, object, shadow or lights are detected that are similar to the outline of vehicles, pedestrians or cyclists, or if they are the same size and position as a vehicle or motorcycle\'s tail lights.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The system may keep operating when the vehicle ahead is turning right or left.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The system may operate when own vehicle is approaching and passing a vehicle ahead.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Depending on the road shape (curved road, entrance and exit of the curve, winding road, lane regulation, under construction, etc.), the system may operate temporarily for the oncoming vehicle in front of own vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "The AEB with pedestrian detection system may react to:", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "objects on the roadside (traffic sign, guardrail, pedestrian, cyclist, motorcycle, vehicle, etc.)", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "objects above road (low bridge, traffic sign, etc.)", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "objects on the road surface (railroad track, grate, steel plate, etc.)", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "objects in the parking garage (beam, pillar, etc.)", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "pedestrians, cyclists or motorcycles approaching the traveling lane", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "vehicles, pedestrians, cyclists, motorcycles or objects in adjacent lanes or close to the vehicle", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "oncoming pedestrians, cyclists", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "objects on the road (such as trees)", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Braking distances increase on slippery surfaces.", "ptxt");
si[i++] = gsitm("N5060302X0000M00ENG.html", "Excessive noise interferes with the warning chime sound, and the chime may not be heard.", "ptxt");
si[i++] = gsitm("N506030CO0001F00ENG.html", "M.U.T.-III SE Function (ACC/ADAS 2)", "title");
si[i++] = gsitm("N506030CO0001F00ENG.html", "Refer to M.U.T.-III SE Function (ACC/ADAS 2).", "ptxt");
