si[i++] = gsitm("N506030580001A00ENG.html", "SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N506030580001A00ENG.html", "Perform the applicable diagnosis according to the diagnosis chart by symptom. Refer to .", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "TROUBLE DIAGNOSIS BY DTC", "title");
