si[i++] = gsitm("N506030580001A00ENG.html", "Perform trouble diagnosis for the detected DTC following.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "\"ACC/ADAS 2\": Refer to DTC Index", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "\"LASER/RADAR\": Refer to DTC Index", "ptxt");
