si[i++] = gsitm("N506030580001A00ENG.html", "If Network-DTC is detected, first diagnose the CAN communication system.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "MALFUNCTIONING PART REPAIR", "title");
si[i++] = gsitm("N506030580001A00ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
