si[i++] = gsitm("N506030580001A00ENG.html", "REPAIR CHECK (SELF-DIAGNOSIS WITH M.U.T.-III SE)", "title");
si[i++] = gsitm("N506030580001A00ENG.html", "Erases self-diagnosis results.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "Perform \"Read All DTCs\" again after repairing or replacing the specific items.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "Check if any DTC is detected in self-diagnosis results of following.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "REPAIR CHECK (ACTION TEST)", "title");
si[i++] = gsitm("N506030580001A00ENG.html", "Perform the action test. Check that the malfunction symptom is solved or no other symptoms occur. Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N506030580001A00ENG.html", "Is there a malfunction symptom?", "question");
si[i++] = gsitm("N506030580001A00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060305A0003B00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5060305A0003B00ENG.html", "Always perform the AEB system action test to check that the system operates normally after replacing the ADAS control unit 2, replacing the front camera unit, or repairing any AEB system malfunction.", "ptxt");
si[i++] = gsitm("N5060305A0003B00ENG.html", "CHECK AEB SYSTEM SETTING", "title");
si[i++] = gsitm("N5060305A0003B00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5060305A0003B00ENG.html", "Check that the AEB system setting can be enabled/disabled on the information display.", "ptxt");
si[i++] = gsitm("N5060305A0003B00ENG.html", "INSPECTION END", "ptxt");
