si[i++] = gsitm("N5060304O000C800ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5060304O000C800ENG.html", "The Rear Automatic Braking system can assist the driver when the vehicle is backing up and approaching objects directly behind the vehicle.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When the shift lever is in the R (Reverse) position and the vehicle speed is less than approximately 15 km/h (7 MPH), the RAB system operates.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "The Rear AEB system detects obstacles behind the vehicle using the sonar sensors.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "If a risk of a collision with an obstacle is detected when own vehicle is backing up, the Rear AEB system warning indicator blinks in the vehicle information display, a red frame appears in the center display (with Multi Around Monitor system), and the system chimes three times.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "The system automatically applies the brakes.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "After the automatic brake application, the driver must depress the brake pedal to maintain brake pressure.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Driver can temporarily cancel the sonar function in the vehicle, but the Rear AEB system continues to operate.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5060304O000C800ENG.html", "Sonar detects a object approaching, and transmits the object detection signal to ADAS control unit 2 via CAN communication.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "The ADAS control unit 2 performs the following operations according to the degree of possibility of a collision.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Transmits the buzzer output signal to the combination meter and sounds the buzzer.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Transmits the meter display signal to the combination meter and displays the Rear AEB system warning indicator.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Transmits the brake fluid pressure control signal to the ABS actuator and electric unit (control unit) and performs the brake control.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Transmits the stop light request signal to BCM and turn ON the stop light.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "ON/OFF of Rear AEB system is performed with the combination meter.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "The Rear AEB system is automatically turned ON when the engine is restarted.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5060304O000C800ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Rear AEB system: ON", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "Vehicle speed: Less than approximately 15 km/h (9 MPH)", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When there is a possibility of a collision with the object backward.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When towing a trailer with trailer hitch harness of Genuine Mitsubishi Accessory attached, the ADAS control unit 2 disables the Rear AEB system. (ON/OFF Settings menu in the multi-information display does not switched automatically.) &lt;From 23 Model yea>", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5060304O000C800ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When the system judges that the vehicle comes to a standstill by the system control.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5060304O000C800ENG.html", "When the sonar area of the rear bumper is dirty and the measurement of the distance between the object becomes difficult.", "ptxt");
si[i++] = gsitm("N5060302O0001100ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5060302O0001100ENG.html", "Refer to .", "ptxt");
