si[i++] = gsitm("N5060303G0000X00ENG.html", "RAB warning light", "ptxt");
si[i++] = gsitm("N5060303G0000X00ENG.html", "RAB warning light indicates that an malfunction condition is present in RAB system", "ptxt");
