si[i++] = gsitm("N5060302X0000N00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5060302X0000N00ENG.html", "PRECAUTIONS FOR REAR SONAR SENSORS", "title");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Always keep the rear sonar sensors clean.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "If the rear sonar sensors are dirty, wipe them off with a soft cloth while being careful to not damage them.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Do not subject the area around the rear sonar sensors to strong impact.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Do not install any stickers (including transparent stickers) or accessories on the rear sonar sensors and their surrounding areas. This may cause a malfunction or improper operation.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "PRECAUTIONS FOR RAB", "title");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Failure to follow the warnings and instructions for proper use of the RAB system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The RAB system is a supplemental aid to the driver. It is not a replacement for proper driving procedures. Always use the side and rear mirrors and turn and look in the direction to move before and while backing up. Never rely solely on the RAB system. It is the driver\'s responsibility to stay alert, drive safely, and be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There is a limitation to the RAB system capability. The RAB system is not effective in all situations.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Listed below are the system limitations for the RAB system. Failure to follow the warnings and instructions for proper use of the RAB system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "When the vehicle approaches an obstacle while the accelerator or brake pedal is depressed, the function may not operate or the start of the operation may be delayed. The RAB system may not operate or may not perform sufficiently due to vehicle conditions, driving conditions, the traffic environment, the weather, road surface conditions, etc. Do not wait for the system to operate. Operate the brake pedal as soon as necessary.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "If it is necessary to override RAB operation, strongly press the accelerator pedal.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Always checks surroundings and turn to check what is behind the vehicle before and while backing up. The RAB system detects stationary objects behind the vehicle. The RAB system does not detect the following objects:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Moving objects", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Low objects", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Narrow objects", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Wedge-shaped objects", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Complex-shaped objects", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Multiple object in close", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Objects close to the bumper (less than approximately 1 ft [30 cm])", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Objects that suddenly appear", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Thin objects such as rope, wire, chain, etc.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The RAB system may not operate for pedestrians or animals.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The RAB system may not operate for the following obstacles:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Obstacles located high off the ground", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Obstacles in a position offset from the vehicle", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Obstacles, such as spongy materials or snow, that have soft outer surfaces and can easily absorb a sound wave", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The RAB system may not operate in the following conditions:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There is rain, snow, ice, dirt, etc., attached to the sonar sensors.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "A loud sound is heard in the area around the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The surface of the obstacle is diagonal to the rear of the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The sonar sensors or the area around them are extremely hot or cold.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The RAB system may unintentionally operate in the following conditions:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There is overgrown grass in the area around the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There is a structure (e.g., a wall, toll gate equipment, a narrow tunnel, a parking lot gate) near the side of the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There are bumps, protrusions, or manhole covers on the road surface.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is driving through a draped flag or a curtain.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is driving on a steep hill.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "There is an accumulation of snow or ice behind the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "An ultrasonic wave source, such as another vehicle\'s sonar, is near the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Once the automatic brake control operates, it does not operate again if the vehicle approaches the same obstacle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The automatic brake control can only operate for a short period of time. Therefore, the driver must depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "In the following situations, the RAB system may not operate properly or may not function sufficiently:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is driven in bad weather (rain, fog, snow, etc.).", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is driven on a steep hill.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle\'s posture is changed (e.g., when driving over a bump).", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is driven on a slippery road.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is turned sharply by turning the steering wheel fully.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Snow chains are used.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Wheels or tires other than Mitsubishi Motors recommended are used.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The brakes are cold at low ambient temperatures or immediately after driving has started.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The braking force becomes poor due to wet brakes after driving through a puddle or washing the vehicle.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Turn the RAB system off in the following conditions to prevent the occurrence of an unexpected accident resulting from sudden system operation:", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is towed.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is carried on a flatbed truck.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle is on the chassis dynamometer.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "The vehicle drives on an uneven road surface.", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Suspension parts other than those designated as genuine parts are used. (If the vehicle height or the vehicle body inclination is changed, the system may not detect an obstacle correctly.)", "ptxt");
si[i++] = gsitm("N5060302X0000N00ENG.html", "Excessive noise (e.g., audio system volume, an open vehicle window) interferes with the chime sound, and it may not be heard.", "ptxt");
si[i++] = gsitm("N506030CO0001E00ENG.html", "M.U.T.-III SE Function (ACC/ADAS 2)", "title");
si[i++] = gsitm("N506030CO0001E00ENG.html", "Refer to M.U.T.-III SE Function (ACC/ADAS 2).", "ptxt");
si[i++] = gsitm("N5060305Q0001W00ENG.html", "List of ECU Reference", "title");
si[i++] = gsitm("N5060305Q0001W00ENG.html", "ECU", "ptxt");
si[i++] = gsitm("N5060305Q0001W00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N5060305Q0001W00ENG.html", "ADAS control unit 2", "ptxt");
si[i++] = gsitm("N5060305Q0001W00ENG.html", "DTC Index", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "INTERVIEW FOR MALFUNCTION", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "It is also important to clarify the customer concerns before starting the inspection. Interview the customer about the concerns carefully and understand the symptoms fully.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "The customers are not professionals. Never assume that \"maybe the customer means···\" or \"maybe the customer mentioned this symptom\".", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "SELF-DIAGNOSIS WITH M.U.T.-III SE", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform \"Read All DTCs\" with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Check if the DTC is detected on the self-diagnosis results of following.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "\"ACC/ADAS 2\"", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N506030580001B00ENG.html", "YES", "result");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "NO", "result");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "ACTION TEST", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform RAB system action test to check the operation status. Refer to .", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Check if any other malfunctions occur.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform the applicable diagnosis according to the diagnosis chart by symptom. Refer to .", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "TROUBLE DIAGNOSIS BY DTC", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Check the DTC in the self-diagnosis results.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform trouble diagnosis for the detected DTC following.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "\"ACC/ADAS 2\": Refer to DTC Index .", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "If \"DTC: U1000–01\" is detected, first diagnose the CAN communication system.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "MALFUNCTIONING PART REPAIR", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "REPAIR CHECK (SELF-DIAGNOSIS WITH M.U.T.-III SE)", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Erases self-diagnosis results.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform \"Read All DTCs\" again after repairing or replacing the specific items.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Check if any DTC is detected in self-diagnosis results of following.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "REPAIR CHECK (ACTION TEST)", "title");
si[i++] = gsitm("N506030580001B00ENG.html", "Perform the RAB system action test. Check that the malfunction symptom is solved or no other symptoms occur.", "ptxt");
si[i++] = gsitm("N506030580001B00ENG.html", "Is there a malfunction symptom?", "question");
si[i++] = gsitm("N506030580001B00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060305A0003C00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5060305A0003C00ENG.html", "Always perform the rear automatic braking system action test to check that the system operates normally after replacing the ADAS control unit 2 or repairing any rear automatic braking system malfunction.", "ptxt");
si[i++] = gsitm("N5060305A0003C00ENG.html", "CHECK REAR AUTOMATIC BRAKING SYSTEM SETTING", "title");
si[i++] = gsitm("N5060305A0003C00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5060305A0003C00ENG.html", "Check that the rear automatic braking system setting can be enabled/disabled on the combination meter.", "ptxt");
si[i++] = gsitm("N5060305A0003C00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Symptom Table", "title");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Perform the self-diagnosis with M.U.T.-III SE before the symptom diagnosis. Perform the trouble diagnosis if any DTC is detected.", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Symptom", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Confirmation item", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Reference page", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "RAB system display does not display", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "(FULL TFT METER)", "ptxt");
si[i++] = gsitm("N5060304M0000N00ENG.html", "(7 INCH INFORMATION DISPLAY)", "ptxt");
si[i++] = gsitm("N506030200006K00ENG.html", "Description", "title");
si[i++] = gsitm("N506030200006K00ENG.html", "PRECAUTIONS FOR RAB", "title");
si[i++] = gsitm("N506030200006K00ENG.html", "Refer to Precautions for Rear Automatic Braking.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5070103O0000K00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5070103O0000K00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5070105M0000J00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5070105M0000J00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5070105M0000J00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Service Notice or Precautions for Steering System", "title");
si[i++] = gsitm("N507010410000L00ENG.html", "In case of removing steering gear assembly, make the final tightening with grounded and unloaded vehicle condition, and then check wheel alignment.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Observe the following precautions when disassembling.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Before disassembly, thoroughly clean the outside of the unit.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Disassembly should be done in a clean work area. It is important to prevent the internal parts from becoming contaminated by dirt or other foreign matter.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "For easier and proper assembly, place disassembled parts in order on a parts rack.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Use nylon cloth or paper towels to clean the parts; common shop rags can leave lint that might interfere with their operation.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Never reuse non-reusable parts.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Before assembling, apply the specified grease to the directed parts.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "During quick steering, rasping noise may be heard from around the steering wheel. This is not a malfunction. The noise is an operating noise of the EPS system under normal conditions. If the rasping noise occurs during slow steering, this may not be an operating noise of the system. In this case, it is necessary to find out the location of the noise and repair, if necessary.", "ptxt");
si[i++] = gsitm("N507010410000L00ENG.html", "Never repeat static steering. (Motor and EPS control unit could be heated.)", "ptxt");
si[i++] = gsitm("N507010460000C00ENG.html", "Special Service Tools", "title");
si[i++] = gsitm("N507010460000C00ENG.html", "When you order special service tool, use part number on “tool order number” of special service tool number substitution list. Refer to", "ptxt");
si[i++] = gsitm("N507010460000C00ENG.html", "The actual shape of the tools may differ from those illustrated here.", "title");
