si[i++] = gsitm("N5070105J0000C00ENG.html", "Heated Steering Wheel", "title");
si[i++] = gsitm("N5070105J0000C00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105J0000C00ENG.html", "Maintains the surface temperature of the steering wheel between 20°C (68°F) and 30°C (86°F).", "ptxt");
si[i++] = gsitm("N5070105J0000C00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105J0000C00ENG.html", "Heat is generated by the heating element built in the steering wheel, and the temperature is controlled with the thermostat.", "ptxt");
si[i++] = gsitm("N5070105J0000C00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5070105J0000C00ENG.html", "Heating element  and thermostat  built into the steering wheel.", "ptxt");
si[i++] = gsitm("N5070105J0000C00ENG.html", "Heating element: Generates heat by energization.", "ptxt");
si[i++] = gsitm("N5070105J0000C00ENG.html", "Thermostat: Turns ON/OFF power supply according to the specified temperature.", "ptxt");
si[i++] = gsitm("N5070105J0000C00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5070105J0000C00ENG.html", "The heated steering wheel is installed steering column.", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", "Heated Steering Wheel Switch", "title");
si[i++] = gsitm("N5070105L0000J00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105L0000J00ENG.html", "When the heated steering wheel switch  is pressed, the heated steering wheel system is alternatively active or inactive.", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", ": A/C switch assembly", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", "Indicator light ON when the system is activated.", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105L0000J00ENG.html", "An ON / OFF signal of heated steering wheel switch is transmitted to A/C amp.", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5070105L0000J00ENG.html", "When the driver presses the button, the internal circuit conducts, and when the  driver presses the button, the internal circuit is cut off.", "ptxt");
si[i++] = gsitm("N5070105L0000J00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5070105L0000J00ENG.html", "The heated steering wheel switch is included in A/C switch assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5070105K0000C00ENG.html", "Heated Steering Wheel Relay", "title");
si[i++] = gsitm("N5070105K0000C00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105K0000C00ENG.html", "Through the control of the A/C amp., the heated steering wheel relay turns ON/OFF electricity to the heating element built-in the steering wheel and turns ON/OFF the indicator light mounted on the heated steering wheel switch.", "ptxt");
si[i++] = gsitm("N5070105K0000C00ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070105K0000C00ENG.html", "Turn ON / OFF the electricity to the heating element and the heated steering wheel switch.", "ptxt");
si[i++] = gsitm("N5070105K0000C00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5070105K0000C00ENG.html", "The relays used in the heated steering wheel relay are normal open relays.", "ptxt");
si[i++] = gsitm("N5070105K0000C00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5070105K0000C00ENG.html", "The heated steering wheel relay is installed near the back side of A/C switch assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5070106B0000900ENG.html", "A/C Amp.", "title");
si[i++] = gsitm("N5070106B0000900ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070106B0000900ENG.html", "The heated steering wheel relay is turned ON/OFF by the signal from the heated steering wheel switch.", "ptxt");
si[i++] = gsitm("N5070106B0000900ENG.html", "INDIVIDUAL FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070106B0000900ENG.html", "Timer: Turn ON/OFF the heated steering wheel relay for a specified time.", "ptxt");
si[i++] = gsitm("N5070106B0000900ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5070106B0000900ENG.html", "The A/C amp.  has a built-in timer that turns OFF the heated steering wheel relay when the operating time reaches 30 minutes.", "ptxt");
si[i++] = gsitm("N5070106B0000900ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5070106B0000900ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5070105N0000I00ENG.html", "System Description (Heated Steering Wheel)", "title");
si[i++] = gsitm("N5070105N0000I00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5070105N0000I00ENG.html", "The heated steering wheel switch controls the heated steering wheel relay. When the heated steering wheel switch is turned on, the heated steering wheel relay is energized and the heated steering wheel system will operate. The heated steering wheel system will turn off when the heated steering wheel temperature reaches approximately 37°C (99°F). Heated steering wheel system operation can also be canceled by pressing the heated steering wheel switch again. The A/C amp. Incorporates a timer and turns OFF the heated steering wheel relay when operating time reaches a certain time.", "ptxt");
si[i++] = gsitm("N5070105N0000I00ENG.html", "If the surface temperature of the steering wheel is below 33°C (91°F), the system will heat the steering wheel and cycle off and on to maintain a temperature above 33°C (91°F). The indicator light will remain on as long as the system is on. Push the switch again to turn the heated steering wheel system off manually. The indicator light will go off.", "ptxt");
si[i++] = gsitm("N5070105N0000I00ENG.html", "CIRCUIT DIAGRAM", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Work Flow (Heated Steering Wheel)", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "OBTAIN INFORMATION ABOUT SYMPTOM", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Interview the customer to obtain the malfunction information (conditions and environment when the malfunction occurred) as much as possible when the customer brings the vehicle in.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "REPRODUCE THE MALFUNCTION INFORMATION", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Check the malfunction on the vehicle that the customer describes.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Inspect the relation of the symptoms and the condition when the symptoms occur.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "IDENTIFY THE MALFUNCTIONING SYSTEM WITH “SYMPTOM DIAGNOSIS”", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Use “Symptom diagnosis” from the symptom inspection result in step 2 and then identify where to start performing the diagnosis based on possible causes and symptoms.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "IDENTIFY THE MALFUNCTIONING PARTS WITH “COMPONENT DIAGNOSIS”", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Perform the diagnosis with “Component diagnosis” of the applicable system.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PARTS", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Repair or replace the specified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Check that malfunctions are not reproduced when obtaining the malfunction information from the customer, referring to the symptom inspection result in step 2.", "ptxt");
si[i++] = gsitm("N5070105O0000C00ENG.html", "Are the malfunctions corrected?", "question");
si[i++] = gsitm("N5070105O0000C00ENG.html", "YES", "result");
