si[i++] = gsitm("N5070102O0002900ENG.html", "NEUTRAL POSITION STEERING WHEEL", "title");
si[i++] = gsitm("N5070102O0002900ENG.html", "Check neutral position on steering wheel after confirming that wheel alignment is correct. Refer to Inspection.", "par2");
si[i++] = gsitm("N5070102O0002900ENG.html", "Turn tires to the straight ahead position on a flat surface equalizing left and right individual toe, check if steering wheel is in the neutral position.", "ptxt");
si[i++] = gsitm("N5070102O0002900ENG.html", "If it is not in the neutral position, place steering wheel in the neutral position and perform wheel alignment again. Refer to .", "ptxt");
