si[i++] = gsitm("N5070102O0002900ENG.html", "Tires need to be inflated to normal pressure. Refer to .", "par3");
si[i++] = gsitm("N5070102O0002900ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N5070102O0002900ENG.html", "Check steering wheel turning force using pull gauge (commercially-available tool) when steering wheel has been turned 90° from neutral position.", "ptxt");
si[i++] = gsitm("N5070102O0002900ENG.html", "Steering wheel turning force", "ptxt");
