si[i++] = gsitm("N5070103X0002B00ENG.html", "Do not cause impact to steering column or shaft during removal or installation.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Be careful when removing steering column assembly from the vehicle because it is heavy.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Never unlock the tilt and telescopic adjustment lever when the column is not securely mounted to the vehicle.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Place the steering column tilt and telescopic lever in the locked position and zip tie the lever to the column assembly to avoid it being unlocked during removal and installation.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Never disassemble steering column components or lower shaft from upper steering column. They should not be separated.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Do not move the steering gear during removal or installation of steering column assembly.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Shall handle the shaft steering lower without interference between upper and lower yoke, when carry the steering column assembly.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Shall not handle only the shaft steering lower, when carry the steering column assembly.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Set vehicle to the straight ahead position.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Unlock the tilt/telescopic adjustment lever then place the tilt to the highest level and telescopic in to the shortest position. Then, lock the adjustment lever.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove the steering wheel. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove steering column covers. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove harness and set it aside.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove spiral cable. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove the combination switch. Refer to .", "par3");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove the instrument lower panel. Refer to GROUP 52A - INTERIOR, INSTRUMENT PANEL DRIVER\'S SIDE, Removal and Installation.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove driver knee air bag module. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove clips  and then remove steering shaft lower cover .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Add zip tie  around lever  and column  to prevent lever from being unlocked, tightened just enough to snug it. Don\'t overtighten or bend the lever.", "par4");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove lower shaft mounting bolt.", "par5");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove the steering column assembly upper mounting bolts.", "par6");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove harness clip and move harness.", "par13");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove the steering column assembly middle cross bolt.", "par7");
si[i++] = gsitm("N5070103X0002B00ENG.html", "When removing the mounting bolts, be careful not to drop the steering column assembly.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Remove steering column assembly.", "par8");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Perform inspection after removal. Refer to .", "par9");
si[i++] = gsitm("N5070103X0002B00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Reject and replace steering column if tilt and telescopic adjustment lever is unlocked prior to install and torque to steering cross member.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Do not unlock lever until mounting bolt and steering column assembly middle cross bolt are tightened to specified torque.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Fit bolts by hand to ensure bolts turn smoothly without catching before tightening to specified torque.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Must perform front wheel alignment resetting the steering wheel and toe.", "par11");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Unlock the tilt and telescopic adjustment lever, move steering column up and down smoothly without any catching or noise.", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Perform steering torque calibration after removal and installation the steering column assembly. Refer to .", "par1");
si[i++] = gsitm("N5070103X0002B00ENG.html", "If equipped with ACC, perform steering torque calibration after replacing or removing and installing the steering column assembly. Refer to .", "par1");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Perform alignment resetting the front wheel toe with steering wheel on center. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002B00ENG.html", "Reset steering angle sensor. Refer to Description.", "par2");
si[i++] = gsitm("N5070102O0002700ENG.html", "Inspection", "title");
si[i++] = gsitm("N5070102O0002700ENG.html", "INSPECTION AFTER REMOVAL", "title");
si[i++] = gsitm("N5070102O0002700ENG.html", "Check the following items and replace, if necessary.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Check each part of steering column assembly for damage or other malfunctions. Replace if there are any abnormal conditions.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Measure steering column rotating torque using a preload gauge (commercial service tool) (A). Replace steering column assembly if the rotating torque is outside the standard.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Rotating torque", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", ": Refer to .", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Measure the length “L” shown in the figure, if vehicle has been involved in a minor collision. Replace steering column assembly if “L” is outside the standard.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Steering column length (L)", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Before completing this measurement, the steering column must be at the telescopic minimum length.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Do not unlock the tilt and telescopic adjustment lever if the steering column assembly is removed from the vehicle.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "First reinstall the column, move to telescopic min, then complete the measurement.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5070102O0002700ENG.html", "Check tilt and telescopic mechanism operating range “T”, “L” as shown in the figure.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Tilt operating range (T)", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Telescopic operating range (L)", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Unlock the tilt and telescopic adjustment lever, move steering column up and down smoothly without any catching or noise.", "par7");
si[i++] = gsitm("N5070102O0002700ENG.html", "After installation, turn steering wheel to make sure it moves smoothly while turning to the left and right stops.", "par8");
si[i++] = gsitm("N5070102O0002700ENG.html", "Make sure the number of turns is the same from the straight-forward position to left and right stops.", "par9");
si[i++] = gsitm("N5070102O0002700ENG.html", "Make sure that the steering wheel is in a neutral position when driving straight ahead.", "par10");
si[i++] = gsitm("N5070102O0002700ENG.html", "Rotate steering wheel to check for decentered condition, binding, noise, or excessive steering effort.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Check the steering wheel play, neutral position steering wheel, steering wheel turning torque, and front wheel turning angle.", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Steering wheel play: Refer to .", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Neutral position steering wheel, steering wheel turning torque, and front wheel turning angle: Refer to .", "ptxt");
si[i++] = gsitm("N5070102O0002700ENG.html", "Adjust neutral position of steering angle sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5070101W0002B00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Heat insulator", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Steering gear assembly", "ptxt");
