si[i++] = gsitm("N5070101W0002B00ENG.html", ": N·m (kg-m, in-lb)", "par2");
si[i++] = gsitm("N5070101W0002B00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Outer socket", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Outer socket lock nut", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Boot clamp (small diameter)", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Boot", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Boot clamp (large diameter)", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Inner socket", "ptxt");
