si[i++] = gsitm("N5070101W0002B00ENG.html", "Gear housing assembly", "ptxt");
si[i++] = gsitm("N5070101W0002B00ENG.html", ": Apply Dow corning 111 or equivalent.", "par7");
si[i++] = gsitm("N5070101W0002B00ENG.html", ": Always replace after every disassembly.", "par9");
si[i++] = gsitm("N5070101W0002B00ENG.html", "Never apply the grease to the surface between steering rack and inner socket screw part.", "par6");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5070103X0003P00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Set vehicle to the straight-ahead position.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Remove front suspension member. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Remove front stabilizer bar. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Remove steering gear assembly.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Note the following, and install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Spiral cable may be cut if steering wheel turns while separating steering column assembly and steering gear assembly. Always fix the steering wheel using string to avoid turning.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Before installation, check that the tilt position is at the middle level.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Clean mounting surface on the body side of fire wall seal when installing steering gear assembly.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Perform final tightening of nuts and bolts on each part under unladen conditions with tires on level ground when removing steering gear assembly. Check wheel alignment.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Rotate steering wheel to check for decentered condition, binding, noise or excessive steering effort.", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Perform inspection after installation. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "Perform either of the following depending on the servicing work.", "par1");
si[i++] = gsitm("N5070103X0003P00ENG.html", "When removing and installing the steering gear assembly or gear housing assembly: Perform the steering torque sensor calibration. Refer to . If equipped with MI-PILOT, it is necessary to perform the steering torque calibration for the driver assistance system. Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0003P00ENG.html", "When replacing the steering gear assembly or gear housing assembly:Perform the additional service. Refer to . If equipped with MI-PILOT, it is necessary to perform the steering torque calibration for the driver assistance system. Refer to .", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5070101M0001300ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5070101M0001300ENG.html", "Disassemble and assemble steering gear assembly by fixing the mounting area with a vise using copper plates.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Loosen inner socket lock nut .", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "To prevent damage, hold outer socket  across flats using suitable tool while loosening inner socket lock nut .", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Remove outer socket.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Remove boot clamps, and then remove boot from inner socket.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Never damage inner socket part of gear housing assembly when removing boot. Steering gear assembly must be replaced if gear housing assembly are damaged because it may cause foreign material interfusion.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Remove inner socket  using variable spanner (SST: MB992249) (A).", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Remove fire wall seal.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Remove O-ring.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Perform inspection after disassembly. Refer to .", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install O-ring.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install fire wall seal to gear housing assembly.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install inner socket , tighten specified torque with variable spanner (SST: MB992249) (A) and torque wrench (B).", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Apply recommended grease to inner socket part  of gear housing assembly, and install boot to gear housing assembly.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Use Dow corning 111 (manufactured by TOURE·DAUKONINGU) or equivalent.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Never reuse boot.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Grease application position (Reference)", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "B", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", ": 10 mm (0.39 in)", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install boot clamp (large diameter)  to boot using boot band crimping tool (SST: KV40107300) (A).", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Never reuse boot clamp (large diameter).", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install boot clamp (large diameter) securely to boot groove, and crimp it so as to have clearance (B) of 3 mm (0.12 in) or less as shown.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Install boot clamp (small diameter) to boot.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Adjust inner socket to standard length (L), and then tighten lock nut  to the specified torque. Check length again after tightening lock nut.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Inner socket length (L)", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", ":", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "When tightening the lock nut , be sure to fix outer socket  with a wrench or an equivalent to prevent the ball joint from getting contact with the knuckle.", "ptxt");
si[i++] = gsitm("N5070101M0001300ENG.html", "Adjust toe-in after this procedure. The length achieved after toe-in adjustment is not necessary the above value.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "INSPECTION AFTER DISASSEMBLY", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Boot", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Check boot for cracks, and replace it if a malfunction is detected.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Gear Housing Assembly", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Check gear housing assembly for damage and scratches (inner wall). Replace if there are any abnormal conditions.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Outer Socket and Inner Socket", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Check the following items and replace the component if it does not meet the standard.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "BALL JOINT ROTATING TORQUE", "par1");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Make sure that the reading is within the following specified range using suitable tool (A). Replace outer socket if the reading is outside the specification.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Rotating torque", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", ": Refer to", "par3");
si[i++] = gsitm("N5070102O0001P00ENG.html", "INSPECTION AFTER INSTALLATION", "title");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Check if steering wheel turns smoothly when it is turned several times fully to the end of the left and right.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Check the steering wheel play, neutral position steering wheel, steering wheel turning force, and front wheel turning angle.", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Steering wheel play: Refer to .", "ptxt");
si[i++] = gsitm("N5070102O0001P00ENG.html", "Neutral position steering wheel, steering wheel turning force, and front wheel turning angle: Refer to .", "ptxt");
si[i++] = gsitm("N5070103X0002I00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5070103X0002I00ENG.html", "When replacing heated steering wheel switch, replace A/C switch assembly. Refer to Removal and Installation.", "par2");
si[i++] = gsitm("N5070106C0000900ENG.html", "Steering Wheel", "title");
