si[i++] = gsitm("N5070200U0000W00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Refer to  (full TFT meter),  (7 inch information display) for detailed installation location.", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Steering angle sensor", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Power steering torque sensor", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "Power steering control unit", "ptxt");
si[i++] = gsitm("N5070200U0000W00ENG.html", "EPS motor", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "Steering Gear Assembly", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "The steering gear assembly is primarily composed of EPS motor , power steering torque sensor  and power steering control module .", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "POWER STEERING CONTROL MODULE", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "By receiving steering angle sensor signal, vehicle speed signal and power steering torque sensor signal, the power steering control module calculates the current of motor drive according to the driving conditions. The power steering control module controls the EPS motor.", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "Diagnoses can be performed via M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "POWER STEERING TORQUE SENSOR", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "Power steering torque sensor detects the steering torque, and transmit the signal to power steering control module.", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "EPS MOTOR", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "The EPS motor provides the assist torque according to the signal from power steering control module.", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5070204I0000R00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5070204I0000R00ENG.html", "PARTS LOCATION", "title");
