si[i++] = gsitm("N507020380000Q00ENG.html", "Power steering torque sensor", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Transmits mainly the following signals to power steering control module via CAN communication.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Engine status signal", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Receives mainly the following signals from power steering control module via CAN communication.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Battery supply current signal", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "EPS torque on signal", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Vehicle speed signal (ABS)", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Steering angle sensor", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Steering angle sensor signal", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Turns ON the power steering warning light according to the signal from the power steering control module via CAN communication.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N507020380000Q00ENG.html", "EPS system consists mainly of power steering control module, EPS motor, power steering torque sensor.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "EPS system calculates a control signal to transmit to the EPS motor based on information received from ECM, ABS actuator and electric unit (control unit) and steering angle sensor via CAN communication and information received from power steering torque sensor.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Power steering control module performs an arithmetical operation on data, such as steering wheel turning force (sensor signal) from the power steering torque sensor, vehicle speed signal, etc. Then it generates an optimum assist torque signal to the EPS motor according to the driving condition.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "After engine start, the EPS system performs control.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "When a malfunction occurs in the system, the fail-safe function stops the EPS system (manual steering state) or restricts its operation (Constant steering assist level state). Refer to .", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Power steering control module decreases the output signal to EPS motor while extremely using the power steering function (e.g., full steering) consecutively for protecting EPS motor and power steering control module (Overload protection control). Refer to .", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "CONDITIONS FOR POWER STEERING WARNING LIGHT ON", "title");
si[i++] = gsitm("N507020380000Q00ENG.html", "Turn ON when there is a malfunction in EPS system. If indicates that fail-safe mode is engaged and enters a manual steering state (Control turning force steering wheel becomes heavy).", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Also turns ON when ignition switch is ON, for purpose of light check. Turns OFF after the engine starts, if system is normal.", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Condition", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Power steering warning light", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "Ignition switch ON. (Light check)", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "After engine start (steering assist force is generated)", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "OFF", "ptxt");
si[i++] = gsitm("N507020380000Q00ENG.html", "When steering assist is stopped", "ptxt");
si[i++] = gsitm("N5070204J0001F00ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N5070204J0001F00ENG.html", "If any malfunction occurs in the system and control module detects the malfunction, power steering warning light on combination meter turns ON to indicate system malfunction.", "ptxt");
si[i++] = gsitm("N5070204J0001F00ENG.html", "When the system enters the fail-safe state, the power steering warning light turns ON and the system will be in the condition described in the table below. When the system is in the manual steering state, the steering becomes heavy.", "ptxt");
