si[i++] = gsitm("N5070204N0000S00ENG.html", "The following vehicle status is recorded when DTC is detected and is displayed on M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "MONITOR ITEM", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "Unit", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "Ignition switch counter", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "(0 – 255)", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "The number of times that ignition switch ON after the DTC is detected is displayed.", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "When “0” is displayed: It indicates that the system is presently malfunctioning.", "ptxt");
si[i++] = gsitm("N5070204N0000S00ENG.html", "When except “0” is displayed: It indicates that system malfunction in the past is detected, but the system is presently normal.", "ptxt");
