si[i++] = gsitm("N5070203H0000S00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "INTERVIEW FROM THE CUSTOMER", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Clarify customer complaints before inspection. First of all, perform an interview utilizing reproduce symptoms as well as fully understand it. Ask customer about his/her complaints carefully. Check symptoms by driving vehicle with customer, if necessary.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Customers are not professional. Never guess easily like “maybe the customer means that...,” or “maybe the customer mentions this symptom”.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "CHECK SYMPTOM", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Reproduce the symptom that is indicated by the customer, based on the information from the customer obtained by interview. Also check that the symptom is not caused by protection function. Refer to .", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "When the symptom is caused by normal operation, fully inspect each portion and obtain the understanding of customer that the symptom is not caused by a malfunction.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 3..", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Perform self-diagnosis.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N5070203H0000S00ENG.html", "YES", "result");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Record or print DTC. GO TO 4.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "NO", "result");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "RECHECK SYMPTOM", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Erase self-diagnostic results for “EPS/DAST 3”.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Pull the parking brake switch.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Check the parking brake switch indicator is turn On.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Get out of the vehicle and close all doors.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Wait 65 seconds.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Check the parking brake switch indicator turn OFF.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "If the rear brake caliper is heated, wait an hour so that parking brake switch indicator does not turn OFF.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Never drive the vehicle.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Perform DTC confirmation procedures for the error detected system.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "If some DTCs are detected at the same time, determine the order for performing the diagnosis based on. Refer to .", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Check harness and connectors based on the information obtained by interview. Refer to .", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "REPAIR OR REPLACE ERROR-DETECTED PARTS", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Repair or replace error-detected parts.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Reconnect part or connector after repairing or replacing.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "When DTC is detected, erase self-diagnostic results for “EPS/DAST 3”.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "IDENTIFY ERROR-DETECTED SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Estimate error-detected system based on symptom diagnosis and perform inspection.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Can the error-detected system be identified?", "question");
si[i++] = gsitm("N5070203H0000S00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Check the reference value for power steering control module.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Recheck the symptom and check that symptom is not reproduced on the same conditions.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "Is the symptom reproduced?", "question");
si[i++] = gsitm("N5070203H0000S00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5070203H0000S00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N507020190000M00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N507020190000M00ENG.html", "Description", "title");
si[i++] = gsitm("N507020190000M00ENG.html", "In general, customers have their own criteria for a problem. Therefore, it is important to understand the symptom and status well enough by asking the customer about his/her concerns carefully. To systemize all the information for the diagnosis, prepare the interview sheet referring to the interview points.", "ptxt");
si[i++] = gsitm("N507020190000M00ENG.html", "In some cases, multiple conditions that appear simultaneously may cause a DTC to be detected.", "ptxt");
