si[i++] = gsitm("N5070203J0001U00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5070203J0001U00ENG.html", "When replacing the power steering control module, the procedures of AFTER REPLACEMENT must be performed. For work procedure, refer to the following:", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "After power steering control module replacement.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N5070203J0001U00ENG.html", "After replacing the power steering control module, the following items must be performed:", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Power steering control module programming.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Power steering control module configuration.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Steering torque sensor calibration.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "WORK PROCEDURE (AFTER REPLACING POWER STEERING CONTROL MODULE)", "title");
si[i++] = gsitm("N5070203J0001U00ENG.html", "PERFORM PROGRAMMING", "title");
si[i++] = gsitm("N5070203J0001U00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Perform power steering control module programming according to the procedure of “Programming” in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Steering wheel: Not steering", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "12V battery voltage: 8 V or more (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Vehicle speed: 0 km/h (0 MPH)", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Perform steering torque sensor calibration. Refer to .", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Turn the steering wheel from full left stop to full right stop three or more times.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Perform self-diagnosis for “EPS/DAST 3”.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "Erase the memory of self-diagnosis results.", "ptxt");
si[i++] = gsitm("N5070203J0001U00ENG.html", "End of work.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "Description", "title");
si[i++] = gsitm("N507020110003S00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the power steering control module.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the power steering control module.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "The configuration no need to “save” configuration data from the power steering control module. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N507020110003S00ENG.html", "Never perform “Configuration” except for new power steering control module.", "ptxt");
si[i++] = gsitm("N5070203J0001V00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5070203J0001V00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5070203J0001V00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5070203J0001V00ENG.html", "Perform writing vehicle specification to power steering control module following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5070203J0001V00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5070203J0001V00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N5070203J0001V00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N507020170014V00ENG.html", "Diagnosis Procedure", "title");
si[i++] = gsitm("N507020170014V00ENG.html", "Always perform the steering torque sensor calibration before driving when the following operation is performed. Refer to .", "ptxt");
si[i++] = gsitm("N507020170014V00ENG.html", "Replacing power steering control module", "ptxt");
si[i++] = gsitm("N507020170014V00ENG.html", "Wheel alignment (Front)", "ptxt");
si[i++] = gsitm("N507020170014V00ENG.html", "Removing/installing/replacing steering wheel and steering angle sensor", "ptxt");
