si[i++] = gsitm("N5070203J0001W00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5070203J0001W00ENG.html", "STEERING TORQUE SENSOR CALIBRATION", "title");
si[i++] = gsitm("N5070203J0001W00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Select \"EPS/DAST 3\".", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Select \"Special function\".", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Select \"Learning\".", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Select and run \"Torque sensor neutral position learning\".", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Make sure that the tires and the steering wheel are in the straight-ahead position.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Do not apply torque to the steering wheel while the learning process is executed.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Ignition switch OFF to ON.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Wait 5 seconds.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Erase self-diagnostic results for “EPS/DAST 3”.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Pull the parking brake switch.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Check the parking brake switch indicator is turn On.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Get out of the vehicle and close all doors.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Wait 65 seconds.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Check the parking brake switch indicator turn OFF.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "If the rear brake caliper is heated, wait an hour so that parking brake switch indicator does not turn OFF.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Perform self-diagnosis for “EPS/DAST 3”.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Is DTC C1608-46 or C160B-54 detected?", "question");
si[i++] = gsitm("N5070203J0001W00ENG.html", "YES", "result");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Ignition switch OFF once, and then repeat the procedure from the start.", "ptxt");
si[i++] = gsitm("N5070203J0001W00ENG.html", "NO", "result");
si[i++] = gsitm("N5070203J0001W00ENG.html", "Work End", "ptxt");
