si[i++] = gsitm("N5080203V0000N00ENG.html", "Third seat belt buckle switch", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Occupant detection system control unit", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Occupant detection system control unit transmits the occupant detection signal to air bag diagnosis sensor unit.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Occupant detection system sensor", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Detecting whether a person sits in the seat or not.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Air bag diagnosis sensor unit", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Turns ON seat belt warning light based on the information from occupant detection system control unit.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Air bag diagnosis sensor unit transmits the seat belt warning signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Turns the seat belt warning light ON when the seat belt buckle switch is unfastened.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Turns the seat belt warning light ON when the seat belt warning signal received.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Engine control module (ECM)", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Engine control module (ECM) transmits the vehicle speed signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "BCM transmits the seat belt buckle switch signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Meter speaker", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Operates when signal is received from combination meter.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "SEAT BELT WARNING LIGHT OPERATION", "title");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Seat belt warning light on combination meter turns ON during a period when ignition switch is turns ON until seat belts are fastened. Seat belt warning light turns OFF when seat belt is fastened. Seat belt warning light turns ON again when seat belt is unfastened.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "SEAT BELT WARNING CHIME OPERATION", "title");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Front", "title");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Seat belt warning chime sounds for approximately 95 seconds when the vehicle speed is 15 km/h (9.3 MPH) or more when any occupied seat and seat belt is unfastened.", "ptxt");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Rear &lt;Vehicles for Australia and New Zealand>", "title");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Rear &lt;Except vehicles for Australia and New Zealand>", "title");
si[i++] = gsitm("N5080203V0000N00ENG.html", "Rear seat belt warning chime sounds for approximately 95 seconds when rear seat belt warning display is turned ON due to the change of any rear seat belt buckle switch status from fastened to unfastened and vehicle speed is 15 km/h (9.3 MPH) or more.", "ptxt");
si[i++] = gsitm("N5080204J0000A00ENG.html", "Rear Seat Belt Warning", "title");
