si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the damaged trim parts.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Curtain air bag module LH", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If the curtain air bag LH has not deployed:", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check for visible signs of damage (dents, tears, deformation, etc.) of the door finisher on the collision side.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the door finisher LH with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check for visible signs of damage (tears etc.) of the curtain air bag module LH.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If no damage is found, reinstall door finisher.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "When removing curtain air bag module from door finisher, do not reuse door finisher.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the door finisher LH and curtain air bag module LH with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Curtain air bag module RH", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If the curtain air bag RH has not deployed:", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the door finisher RH with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check for visible signs of damage (tears etc.) of the curtain air bag module RH.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the door finisher RH and curtain air bag module RH with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Occupant detection system (Passenger seat)", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Remove passenger seat assembly.", "par1");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check control unit case for dents, cracks of deformities.", "par2");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check connectors for damage and terminals for deformities.", "par3");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check seat frame and cushion pan for dents or deformities.", "par4");
si[i++] = gsitm("N5080303C0001000ENG.html", "If no damage is found, reinstall seat with new fasteners.", "par5");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the seat cushion assembly with new fasteners.", "par6");
si[i++] = gsitm("N5080303C0001000ENG.html", "Pop-up roll bar", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If the pop-up roll bar not deployed:", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check for visible signs of damage (dents, tears, deformation, etc.) of the pop-up roll bar.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPLACE the pop-up roll bar with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If no damage is found, reinstall the pop-up roll bar with new fasteners.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "Check for visible signs of damage (dents, cracks, deformation, etc.) of the seatback support brace assembly.", "ptxt");
si[i++] = gsitm("N5080303C0001000ENG.html", "If damaged - REPAIR the seatback support brace assembly.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "For rear collision", "title");
si[i++] = gsitm("N5080305H0000A00ENG.html", "FOR REAR COLLISION: When SRS is not activated in a collision", "title");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Due to varying models and option levels, not all parts listed in the chart below apply to all vehicles.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "WORK PROCEDURE", "title");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Before performing any of the following steps, ensure that all vehicle body and structural repairs have been completed.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check the SRS components using the table below.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Replace any SRS components showing visible signs of damage. (dents, cracks and deformation, etc).", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Perform self-diagnosis using M.U.T.-III SE or air bag warning light. Refer to DTCIndex. for details.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Ensure entire SRS operates properly.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "After the work is completed, check that no malfunction is detected by air bag warning light.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "SRS INSPECTION (FOR REAR COLLISION)", "title");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Part", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Inspection", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Driver air bag module", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the driver air bag has not been activated:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Remove driver air bag module. Check harness cover and connectors for damage, terminals for deformities, and harness for binding.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Install driver air bag module into the steering wheel to check fit and alignment with the wheel.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If no damage is found, reinstall with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE. Install driver air bag modules with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Driver knee air bag module", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the driver knee air bag has not been activated:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Remove driver knee air bag module. Check harness cover and connectors for damage, terminals for deformities, and harness for binding.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Install driver knee air bag module into the instrument panel to check fit with the instrument panel.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE. Install driver knee air bag modules with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Front passenger air bag module", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the front passenger air bag has not been activated:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Remove front passenger air bag module. Check harness cover and connectors for damage, terminals for deformities, and harness for binding.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Install front passenger air bag module into the instrument panel to check fit with the instrument panel.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE. Install front passenger air bag modules with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Crash zone sensor", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the front air bags or seat belt pre-tensioners have not been activated:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Remove the crash zone sensor. Check harness connectors for damage, terminals for deformities, and harness for binding.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check for visible signs of damage (dents, cracks, deformation) of the crash zone sensor and bracket.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Install the crash zone sensor to check fit.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE the crash zone sensor and bracket with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Seat belt pre-tensioner assemblies", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "(All applicable locations: buckle, retractor, lap outer)", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "REPLACE the seat belt pre-tensioner assembly.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Install with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Diagnosis sensor unit", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If none of the SRS components have been activated:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check case for dents, cracks or deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check connectors for damage, and terminals for deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE. Install diagnosis sensor unit with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Steering wheel", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Visually check steering wheel for deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check harness (built into steering wheel) and connectors for damage, and terminals for deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check steering wheel for excessive free play.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If no damage is found, reinstall.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Spiral cable", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the driver front air bag has not deployed:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Visually check spiral cable and combination switch for damage.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check connectors and protective tape for damage.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check steering wheel for noise, binding or heavy operation.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Occupant detection system (Passenger seat)", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Remove passenger seat assembly.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check control unit case for dents, cracks of deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check connectors for damage and terminals for deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check seat frame and cushion pan for dents or deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If no damage is found, reinstall seat with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE seat cushion assembly with new fasteners.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Harness and connectors", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check connectors for poor connection, damage, and terminals for deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Check harness for binding, chafing, cuts, or deformities.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If no damage is found, reinstall the harness and connectors.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE the damaged harness. Do not attempt to repair, splice or modify any SRS harness.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Instrument panel assembly", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If the passenger front air bag has not deployed:", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "Visually check instrument panel for damage.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If no damage is found, reinstall the instrument panel assembly.", "ptxt");
si[i++] = gsitm("N5080305H0000A00ENG.html", "If damaged - REPLACE the instrument panel assembly.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Be sure to check precautions and notes by referring to PRECAUTIONS before work.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Before servicing, ignition switch OFF, disconnect battery negative terminal and wait for 3 minutes or more (discharges electricity held in the additional power supply circuit of the air bag diagnosis sensor unit).", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Always work from the side of air bag module. Never work in front of it.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Pre-removal Operation", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Check that the front wheels are at the straight-ahead position.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "•", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Disconnect the negative (–) battery terminal.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Driver air bag module", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Driver air bag module harness connector", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Horn wiring harness", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Installation steps", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Connect the negative (–) battery terminal.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ">>C&lt;&lt;", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Post-installation inspection", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "REMOVAL SERVICE POINTS", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "&lt;&lt;A>> DRIVER AIR BAG MODULE/DRIVER AIR BAG MODULE HARNESS CONNECTOR REMOVAL", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Never use an electric tester to diagnose the air bag module circuit. Never attempt to disassemble the air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Be sure to store the removed air bag module in a clean and dry place with a pad surface facing upward.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Follow the procedure below according to the item numbers in the illustration.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Insert a TORX (screw) driver (T-30) into the service hole on the steering wheel.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Use the TORX (screw) driver (T-30) to press the rod in driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "When the driver air bag module is disengaged, the driver air bag module will be released.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Repeat for the other service hole end then remove the driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Use the flat-tipped screwdriver to pull out the locking button of wiring harness side connector, and release the lock.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent accidental explosion, always place the driver air bag module with pad side facing upward.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ": Upward", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent damage to the parts, never impact the driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Replace driver air bag module if it has been dropped or sustained an impact.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent accidental explosion, never insert any foreign objects (screwdriver, etc.) into the driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent accidental explosion, never disassemble the driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent accidental explosion, never expose the driver air bag module to temperatures exceeding 90 °C (194 °F).", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "To prevent damage to the parts, never allow oil, grease, detergent, or water to come in contact with the driver air bag module.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N508030310007B00ENG.html", ">>A&lt;&lt; HORN WIRING HARNESS/DRIVER AIR BAG MODULE HARNESS CONNECTOR INSTALLATION", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Fit the horn wiring harness and the driver air bag module harness connector into the clip.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ">>B&lt;&lt; DRIVER AIR BAG MODULE INSTALLATION", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Press driver air bag module  until it snaps into place with a clicking sound.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", ">>C&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310007B00ENG.html", "Check that horn does not sound when driver air bag module is not pressed.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "Never damage the harness while installing.", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "After installation is completed, perform self-diagnosis using M.U.T.-III SE or air bag warning light, if the system is normal and \"Stored DTC\" of \"Self-diagnosis\" is indicated, always perform \"Erase DTCs\" of \"Self-diagnosis\" using M.U.T.-III SE. Refer to Work Flow .", "ptxt");
si[i++] = gsitm("N508030310007B00ENG.html", "After the work is completed, check that no system malfunction is detected by air bag warning light in the user mode.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "Inspection", "title");
si[i++] = gsitm("N508030260000900ENG.html", "Never attempt to measure the circuit resistance of the air bag modules (squib), even if you are using the specified tester. If the circuit resistance is measured with a tester, accidental air bag deployment will result, and possible serious personal injury.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "If any component damage is found during the following inspection, replace the air bag module with a new one.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "If any malfunction is found in the following inspections, replace the air bag module with a new one.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "Pad cover dent, crack or deformation", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "Check the harness and connector for damage and the terminal for deformation.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "Check the air bag inflator cases for dents, cracks or deformation.", "ptxt");
si[i++] = gsitm("N508030260000900ENG.html", "Check the air bag module for proper installation.", "ptxt");
si[i++] = gsitm("N5080301P0004N00ENG.html", "Exploded View", "title");
si[i++] = gsitm("N5080301P0004N00ENG.html", "Combination switch", "ptxt");
si[i++] = gsitm("N5080301P0004N00ENG.html", "Spiral cable", "ptxt");
si[i++] = gsitm("N5080301P0004N00ENG.html", "Steering angle sensor", "ptxt");
si[i++] = gsitm("N5080301P0004N00ENG.html", ": Pawl", "ptxt");
si[i++] = gsitm("N5080301P0004N00ENG.html", ": Always replace after every disassembly.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310007A00ENG.html", "Be sure to check precautions and notes by referring to PRECAUTIONS before work.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Never use air tools or electric tools for servicing.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N508030310007A00ENG.html", "Remove steering wheel. Refer to .", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Remove steering column cover. Refer to .", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Disconnect spiral cable body side harness connectors .", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Left side", "par1");
si[i++] = gsitm("N508030310007A00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Right side (with steering heater models)", "par3");
si[i++] = gsitm("N508030310007A00ENG.html", "Disconnect steering angle sensor body side harness connector .", "par5");
si[i++] = gsitm("N508030310007A00ENG.html", "Disengage spiral cable fixing pawls, and then remove spiral cable with steering angle sensor.", "par7");
si[i++] = gsitm("N508030310007A00ENG.html", ": Pawl", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Disengage steering angle sensor fixing pawls, and then remove steering angle sensor from spiral cable.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "To prevent damage to the parts, never impact the spiral cable.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Replace spiral cable if it is dropped or sustains an impact.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "To prevent damage to the parts, never disassemble the spiral cable.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "To prevent damage to the parts, never apply lubricant to the spiral cable.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "To prevent damage to the parts, never allow oil, grease, detergent, or water to come in contact with the spiral cable.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N508030310007A00ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "Always replace combination switch with a new one when spiral cable is removed. Refer to .", "par9");
si[i++] = gsitm("N508030310007A00ENG.html", "After installation is completed, perform steering torque calibration. Refer to .", "par28");
si[i++] = gsitm("N508030310007A00ENG.html", "The spiral cable may snap during steering operation if the cable is installed in an improper position.", "ptxt");
si[i++] = gsitm("N508030310007A00ENG.html", "When install spiral cable, set the neutral position following procedure below.", "par15");
si[i++] = gsitm("N508030310007A00ENG.html", "If you buy the new parts, no need to set the neutral position because its has been set the neutral position.", "par17");
si[i++] = gsitm("N508030310007A00ENG.html", "Install steering angle sensor to spiral cable.", "par24");
si[i++] = gsitm("N508030310007A00ENG.html", "When installing, align  of spiral cable and  of steering angle sensor.", "par25");
si[i++] = gsitm("N508030310007A00ENG.html", "Set the neutral position.", "par18");
si[i++] = gsitm("N508030310007A00ENG.html", "Carefully turn spiral cable clockwise to the end position.", "par19");
si[i++] = gsitm("N508030310007A00ENG.html", "Never turn spiral cable powerfully where the end position.", "par20");
si[i++] = gsitm("N508030310007A00ENG.html", "Turn counterclockwise (about 2 and a half turns) and stop turning where the part of  matching mark is fit and which the clear window  appear yellow mark.", "par21");
si[i++] = gsitm("N508030310007A00ENG.html", "Install spiral cable into combination switch by fixing pawls.", "par22");
si[i++] = gsitm("N508030310007A00ENG.html", "Connect body harness to spiral cable and steering angle sensor.", "par10");
si[i++] = gsitm("N508030310007A00ENG.html", "Remove lock pin  of combination switch according to numerical order 1→2 indicated by arrows as shown in figure.", "par23");
si[i++] = gsitm("N508030310007A00ENG.html", "Install steering column cover. Refer to .", "par11");
si[i++] = gsitm("N508030310007A00ENG.html", "Install steering wheel. Refer to .", "par12");
si[i++] = gsitm("N508030310007A00ENG.html", "When install steering wheel, set locate pin  of spiral cable and locate hole  of steering wheel.", "par13");
