si[i++] = gsitm("N508030310008A00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "Before servicing, ignition switch OFF, disconnect battery negative terminal and wait for 3 minutes or more (discharges electricity held in the additional power supply circuit of the air bag diagnosis sensor unit).", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "Always work from the side of air bag module. Never work in front of it.", "ptxt");
