si[i++] = gsitm("N508030310008A00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N508030310008A00ENG.html", "&lt;&lt;A>> PASSENGER AIR BAG MODULE REMOVAL", "title");
si[i++] = gsitm("N508030310008A00ENG.html", "Disengage fixing hooks of passenger air bag while pulling installment panel assembly, and then remove passenger air bag module according to numerical order 1→2 indicated by arrows as shown in figure.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent accidental explosion, always place the passenger air bag module with deploying direction facing upward.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", ": Upward", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent damage to the parts, never impact the passenger air bag module.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "Replace passenger air bag module if it is dropped or sustains an impact.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent accidental explosion, never insert any foreign objects (screwdriver, etc.) into the passenger air bag module.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent accidental explosion, never disassemble the passenger air bag module.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent accidental explosion, never expose the passenger air bag module to temperature of more than 90 °C (194 °F).", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "To prevent damage to the parts, never allow oil, grease, detergent, or water to come in contact with the passenger air bag module.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N508030310008A00ENG.html", ">>A&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008A00ENG.html", "Never damage the harness while installing.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "After installation is completed, perform self-diagnosis using M.U.T.-III SE or air bag warning light, if the system is normal and \"PAST\" of \"Self Diagnostic Result\" is indicated, always perform \"ERASE\" of \"Self Diagnostic Result\" using M.U.T.-III SE. Refer to Work Flow.", "ptxt");
si[i++] = gsitm("N508030310008A00ENG.html", "After the work is completed, check that no system malfunction is detected by air bag warning light.", "ptxt");
