si[i++] = gsitm("N508030310008900ENG.html", "&lt;&lt;A>> DRIVER KNEE AIR BAG MODULE REMOVAL", "title");
si[i++] = gsitm("N508030310008900ENG.html", "For installing/removing the driver knee air bag harness connector, insert a thin screwdriver wrapped in tape into notch, lift lock and remove the connector.", "ptxt");
si[i++] = gsitm("N508030310008900ENG.html", "Install connector with lock raised, and push lock into the connector.", "ptxt");
si[i++] = gsitm("N508030310008900ENG.html", "After installing the connector, check that the lock is pushed securely into it.", "ptxt");
si[i++] = gsitm("N508030310008900ENG.html", "To prevent accidental explosion, always place the driver knee air bag module with deploying direction facing upward.", "ptxt");
si[i++] = gsitm("N508030310008900ENG.html", ": Upward", "ptxt");
