si[i++] = gsitm("N508030310007500ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N508030310007500ENG.html", "&lt;&lt;A>> CURTAIN AIR BAG MODULE REMOVAL", "title");
si[i++] = gsitm("N508030310007500ENG.html", "Never use an electric tester to diagnose the air bag module circuit. Never attempt to disassemble the air bag module.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "The removed air bag module should be stored in a clean, dry place.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Use the flat-tipped screwdriver to pull out the locking button of wiring harness side connector, and release the lock.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "To prevent damage to the parts, never impact the curtain air bag module.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Replace curtain air bag module if it is dropped or sustains an impact.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "To prevent accidental explosion, never insert any foreign objects (screwdriver, etc.) into the curtain air bag module.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "To prevent accidental explosion, never disassemble the curtain air bag module.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "To prevent accidental explosion, never expose the curtain air bag module to temperatures of more than 90°C (194°F).", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "To prevent damage to the parts, never allow oil, grease, detergent, or water to come in contact with the curtain air bag module.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N508030310007500ENG.html", ">>A&lt;&lt; CURTAIN AIR BAG MODULE INSTALLATION", "title");
si[i++] = gsitm("N508030310007500ENG.html", "Take care not to contort the curtain air bag when installing it.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Do not trap the air bag with the peripheral parts.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Do not trap the strap with the front pillar garnish clip or others.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Connect the connector to the inflator thoroughly.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Install the strap part of the curtain air bag module by adhering it to the area shown in the figure with double-sided tape.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", ">>B&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310007500ENG.html", "Check perforation of curtain air bag module to check that curtain air bag module is not twisted.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "Never damage the harness while installing.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "After installation is completed, perform self-diagnosis using M.U.T.-III SE or air bag warning light, if the system is normal and ″PAST″ of ″Self Diagnostic Result″ is indicated, always perform ″ERASE″ of ″Self Diagnostic Result″ using M.U.T.-III SE. Refer to Work Flow.", "ptxt");
si[i++] = gsitm("N508030310007500ENG.html", "After the work is completed, check that no system malfunction is detected by air bag warning light.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "Inspection", "title");
si[i++] = gsitm("N508030260000A00ENG.html", "Never attempt to measure the circuit resistance of the air bag modules (squib), even if you are using the specified tester. If the circuit resistance is measured with a tester, accidental air bag deployment will result, and possible serious personal injury.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "If any component damage is found during the following inspection, replace the air bag module with a new one.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "There must be no abnormality to the air bag deployment section of headlining.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "If any malfunction is found in the following inspections, replace with a new curtain air bag module.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "Check the inflator surface for cracks, dents or deformations.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "Check the air bag for breakage.", "ptxt");
si[i++] = gsitm("N508030260000A00ENG.html", "Check the connector for damage, the terminal for deformation and the harness for binding.", "ptxt");
