si[i++] = gsitm("N508030310007200ENG.html", "Before servicing, ignition switch OFF, disconnect battery negative terminal and wait for 3 minutes or more (discharges electricity held in the additional power supply circuit of the air bag diagnosis sensor unit).", "ptxt");
si[i++] = gsitm("N508030310007200ENG.html", "Never place seat belt pre-tensioner retractor and lap pre-tensioner in an area where the temperature reaches 80°C (176°F) or more.", "ptxt");
