si[i++] = gsitm("N508030260000B00ENG.html", "Inspection", "title");
si[i++] = gsitm("N508030260000B00ENG.html", "Never attempt to measure the circuit resistance of the seat belt pre-tensioner and lap pre-tensioner (squib), even if you are using the specified tester. If the circuit resistance is measured with a tester, accidental air bag deployment will result, and possible serious personal injury.", "ptxt");
si[i++] = gsitm("N508030260000B00ENG.html", "If any component damage is found during the following inspection, replace the seat belt pre-tensioner with a new one.", "ptxt");
si[i++] = gsitm("N508030260000B00ENG.html", "If any malfunction is found in the following inspections, replace the seat belt pre-tensioner with a new one.", "ptxt");
si[i++] = gsitm("N508030260000B00ENG.html", "Check the seat belt pre-tensioner and lap pre-tensioner for dents, cracks or deformation.", "ptxt");
si[i++] = gsitm("N508030260000B00ENG.html", "Check the harness and connector for damage and the terminal for deformation.", "ptxt");
