si[i++] = gsitm("N508030310008M00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310008M00ENG.html", "Be sure to check precautions and notes by referring to PRECAUTIONS for SEAT before work.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Never attempt to disassemble or repair the occupant detection system control unit. If faulty, replace it.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Do not drop or subject the occupant detection system control unit to impact or vibration. Replace the occupant detection system control unit, if dents, cracking, deformation, or rust are present.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "When replacing the occupant detection system control unit, be careful not to apply static electricity to it.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "The occupant detection system control unit must not be damped with any liquid or steam.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Pre-removal Operation", "title");
