si[i++] = gsitm("N508030310008M00ENG.html", "The occupant detection system control unit is supplied with the front seat cushion assembly as a set. In order to replace the occupant detection system control unit, replace the front seat cushion assembly.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "REMOVAL SERVICE POINT", "title");
