si[i++] = gsitm("N508030310008M00ENG.html", "Wait at least 3 minutes after disconnecting the battery cable before doing any further work.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Battery posts, terminals and related accessories contain lead and lead compounds. WASH HANDS AFTER HANDLING.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Disconnect the negative (-) battery cable from the battery and tape the terminal to prevent accidental connection and air bag(s) deployment.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N508030310008M00ENG.html", ">>A&lt;&lt; PRE-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008M00ENG.html", "Check the occupant detection system control unit for dents, breakage and bending and measure the resistance between the terminals, even when installing a new occupant detection system control unit.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", ">>B&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008M00ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "Check that the air bag warning light is illuminated, and extinguished afterward.", "ptxt");
si[i++] = gsitm("N508030310008M00ENG.html", "If the light does not extinguish, perform the troubleshooting.", "ptxt");
si[i++] = gsitm("N508030260000C00ENG.html", "Inspection", "title");
si[i++] = gsitm("N508030260000C00ENG.html", "If any component damage is found during the following inspection, replace the occupant detection system control unit with a new one. Dispose of the old one according to the specified procedure.", "ptxt");
si[i++] = gsitm("N508030260000C00ENG.html", "Always replace the front seat cushion assembly together with the occupant detection system control unit.", "ptxt");
si[i++] = gsitm("N508030260000C00ENG.html", "If any malfunction is found in the following inspections, replace the front seat cushion assembly with a new one.", "ptxt");
si[i++] = gsitm("N508030260000C00ENG.html", "Check the occupant detection system control unit for dent, cracks or deformation.", "ptxt");
si[i++] = gsitm("N508030260000C00ENG.html", "Check the connector for damage, and terminals for deformation.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310008N00ENG.html", "Be sure to check precautions and notes by referring to PRECAUTIONS for SEAT before work.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Never attempt to disassemble or repair the occupant detection system sensor. If faulty, replace it.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Do not drop or subject the occupant detection system sensor to impact or vibration. Replace the occupant detection system sensor, if dents, cracking, deformation, or rust are present.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "When replacing the front seat cushion assembly, be careful not to apply static electricity to it.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "The front seat cushion assembly must not be damped with any liquid or steam.", "ptxt");
