si[i++] = gsitm("N508030310008N00ENG.html", "Occupant detection system sensor (Refer to Front Seat Assembly ).", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Installation steps", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", ">>A&lt;&lt;", "ptxt");
