si[i++] = gsitm("N508030310008N00ENG.html", "Post-installation inspection", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "The occupant detection system sensor is supplied with the front seat cushion frame. In order to replace the occupant detection system sensor, replace the front seat cushion assembly.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "REMOVAL SERVICE POINT", "title");
