si[i++] = gsitm("N508030310008N00ENG.html", "Wait at least 3 minutes after disconnecting the battery cable before doing any further work.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Battery posts, terminals and related accessories contain lead and lead compounds. WASH HANDS AFTER HANDLING.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Disconnect the negative (-) battery cable from the battery and tape the terminal to prevent accidental connection and air bag(s) deployment.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N508030310008N00ENG.html", ">>A&lt;&lt; PRE-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008N00ENG.html", "Check the occupant detection system sensor for dents, breakage and bending and measure the resistance between the terminals, even when installing a new occupant detection system sensor.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", ">>B&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008N00ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "Check that the air bag warning light is illuminated, and extinguished afterward.", "ptxt");
si[i++] = gsitm("N508030310008N00ENG.html", "If the light does not extinguish, perform the troubleshooting.", "ptxt");
si[i++] = gsitm("N508030260000D00ENG.html", "Inspection", "title");
si[i++] = gsitm("N508030260000D00ENG.html", "If a dent, crack, deformation or rust is detected, replace with a new front seat cushion assembly.", "ptxt");
si[i++] = gsitm("N508030260000D00ENG.html", "For checking of the occupant detection system sensor other than described below, refer to the section concerning SRS diagnosis.", "ptxt");
si[i++] = gsitm("N508030260000D00ENG.html", "Check the front seat cushion assembly for damage (gouges and tears, etc.).", "ptxt");
si[i++] = gsitm("N508030260000D00ENG.html", "Check the connector and harness for damage, and terminals for deformation.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310008500ENG.html", "Be sure to check precautions and notes by referring to PRECAUTIONS before work.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Before servicing, ignition switch OFF, disconnect battery negative terminal and wait for 3 minutes or more (discharges electricity held in the additional power supply circuit of the air bag diagnosis sensor unit).", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Before disconnecting the air bag sensor unit harness connector, be sure to disconnect each harness connector of the air bag modules, seat belt pre-tensioners and lap pre-tensioner to prevent air bag deployment by static electricity and seat belt pre-tensioner operation.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Never use air tools or electric tools for servicing (prevents the air bag diagnosis sensor unit from activating unexpectedly due to vibration).", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "When the air bag diagnosis sensor unit is replaced, perform the additional service procedures. Refer to Restraints – SRS Airbag Control System – Basic Inspection – Additional Service When Replacing Air Bag Diagnosis Sensor Unit – .", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Pre-removal Operation", "title");
si[i++] = gsitm("N508030310008500ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "•", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Disconnect the negative (-) battery terminal.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Center console assembly (Refer to Floor Console Assembly )", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "1.", "ptxt");
