si[i++] = gsitm("N508030310008500ENG.html", "Air bag diagnosis sensor unit", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Installation steps", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Connect the negative (-) battery terminal.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Post-installation inspection", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N508030310008500ENG.html", "&lt;&lt;A>> AIR BAG DIAGNOSIS SENSOR UNIT REMOVAL", "title");
si[i++] = gsitm("N508030310008500ENG.html", "Turn the lock lever (A in the figure) of the air bag diagnosis sensor unit harness side connector toward the direction of the arrow to release the lock lever, and remove the connector.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "To prevent damage to the air bag diagnosis sensor unit, never impact it", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Replace air bag diagnosis sensor unit if it is dropped or sustains an impact.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Replace air bag diagnosis sensor unit of deployed driver air bag module, deployed passenger air bag module, deployed driver knee air bag module, deployed passenger knee air bag module, deployed front side air bag module, deployed front center air bag module, deployed rear side air bag module, deployed curtain air bag module, deployed seat belt pre-tensioner or deployed lap pre-tensioner.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N508030310008500ENG.html", ">>A&lt;&lt; GROUND BOLT INSTALLATION", "title");
si[i++] = gsitm("N508030310008500ENG.html", "Check the head mark \"E\" and install the ground bolt.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", ">>B&lt;&lt; POST-INSTALLATION INSPECTION", "title");
si[i++] = gsitm("N508030310008500ENG.html", "Never damage the harness while installing.", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "Be sure to perform ADDITIONAL SERVICE WHEN REPLACING AIR BAG DIAGNOSIS UNIT when replacing air bag diagnosis sensor unit. Or not doing so, air bag diagnosis sensor unit control function does not operate normally. Refer to .", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "After installation is completed, perform self-diagnosis using M.U.T.-III SE or air bag warning light, if the system is normal and \"Stored DTC\" of \"Self-diagnosis\" is indicated, always perform \"Erase DTCs\" of \"Self-diagnosis\" using M.U.T.-III SE. Refer to Work Flow .", "ptxt");
si[i++] = gsitm("N508030310008500ENG.html", "After the work is completed, check that no system malfunction is detected by air bag warning light.", "ptxt");
si[i++] = gsitm("N508030310008B00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N508030310008B00ENG.html", "For removal and installation, refer to Front Camera Unit .", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5080405I0000X00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5080405I0000X00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5080406G0000U00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5080406G0000U00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5080406G0000U00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Service", "title");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Never use electrical test equipment to check SRS circuits unless instructed to in this Service Manual.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Before servicing the SRS, ignition switch OFF, disconnect battery negative terminal and wait 3 minutes or more.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "For approximately 3 minutes after the cables are removed, it is still possible for the air bag and seat belt pre-tensioner to deploy. Therefore, never work on any SRS connectors or wires until at least 3 minutes have passed.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Diagnosis sensor unit must always be installed with their arrow marks “⇐” pointing towards the front of the vehicle for proper operation. Also check diagnosis sensor unit for cracks, deformities or rust before installation and replace as required.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "The spiral cable must be aligned with the neutral position since its rotations are limited. Never turn steering wheel and column after removal of steering gear.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Handle air bag module carefully. Always place driver and front passenger air bag modules with the pad side facing upward and seat mounted front side air bag module standing with the stud bolt side facing down.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Conduct self-diagnosis to check entire SRS for proper function after replacing any components.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "After air bag inflates, the front instrument panel assembly should be replaced if damaged.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Always replace instrument panel pad following front passenger air bag deployment.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Never solder the harness when making repairs. Check that harness is not pinched and that there is no contact with other components.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Never allow harness to come in contact with oil, grease, waste oil, or water.", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Never insert foreign materials, such as a screwdriver, into the harness connector. (This is to prevent accidental activation caused by static electricity.)", "ptxt");
si[i++] = gsitm("N5080405L0000S00ENG.html", "Always use M.U.T.-III SE or SRS air bag warning light to perform the circuit diagnosis. (Never use an electric tester such as a circuit tester.)", "ptxt");
