si[i++] = gsitm("N508040610001E00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N508040610001E00ENG.html", "Supplemental Restraint System (SRS) activates air bag module and seat belt pre-tensioner when it detects a collision that is more than the specified limit. Together with other safety devices, it reduces the impact that occupant receives when vehicle collision occurs. Air bag diagnosis sensor unit supplies power supply to air bag module and pre-tensioner seat belt when deceleration that is more than the specified limit is detected by G sensor in air bag diagnosis sensor unit, crash zone sensor and each satellite sensor. Air bag module is composed of electric igniter (squib), filter, pyrotechnic material, and gas generating material. When air bag module receives a signal from air bag diagnosis sensor unit, air bag module ignites pyrotechnic material using electric igniter (squib) so that gas generating material generates high temperature nitrogen gas. The gas through filter activates air bag. At the same time, pre-tensioner seat belt receives power supply from air bag diagnosis sensor unit, gas generator is activated, and then gas is generated. The pressure of the generated gas causes the balls inside of pipe to move and the shaft to rotate and retract the shoulder belt. Similarly, the piston inside of pipe moves, and retracts the lap belt connected to the wire.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "AIR BAG DIAGNOSIS SENSOR UNIT FUNCTIONS", "title");
si[i++] = gsitm("N508040610001E00ENG.html", "Air bag diagnosis sensor unit has the following functions.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Detects a collision and supplies the energy for deploying air bag and seat belt pre-tensioner.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Detects and records electrical malfunction in air bag system and seat belt pre-tensioner system, and turns SRS air bag warning light ON.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Detects and records the deployment of air bag and seat belt pre-tensioner, and turns ON SRS air bag warning light.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Indicates the malfunction record via M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "SRS AIR BAG WARNING LIGHT", "title");
si[i++] = gsitm("N508040610001E00ENG.html", "Detects electrical malfunction in air bag system and seat belt pre-tensioner system, and turns SRS air bag warning light ON.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Detects deployment malfunction in air bag system and seat belt pre-tensioner system, and turns SRS air bag warning light ON.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Air bag diagnosis sensor unit warns the driver by turning SRS air bag warning light ON when air bag diagnosis sensor unit detects battery low voltage. SRS air bag warning light turns ON when a voltage value at which air bag diagnosis sensor unit cannot operate normally (9 V or less) is detected. After starting to turn ON, SRS air bag warning light turns OFF when air bag diagnosis sensor unit detects the normal value of battery voltage.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "Air bag diagnosis sensor unit warns the driver by turning SRS air bag warning light ON when air bag diagnosis sensor unit detects battery high voltage. SRS air bag warning light turns ON when a voltage value at which air bag diagnosis sensor unit cannot operate normally (16 V or more) is detected. After starting to turn ON, SRS air bag warning light turns OFF when air bag diagnosis sensor unit detects the normal value of battery voltage.", "ptxt");
si[i++] = gsitm("N508040610001E00ENG.html", "SRS air bag warning light operation", "ptxt");
