si[i++] = gsitm("N5080406A0000P00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Record DTC (Print them out using M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Are any symptoms described and any DTC detected?", "question");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N5080406A0000P00ENG.html", "YES", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "NO", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Check DTC. If DTC is detected, erase it.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5080406A0000P00ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is repaired securely.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N5080406A0000P00ENG.html", "YES-1", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "YES-2", "result");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N5080406A0000P00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N5080403X0002400ENG.html", "Description", "title");
si[i++] = gsitm("N5080403X0002400ENG.html", "After replaced air bag diagnosis sensor unit, it is necessary to perform control unit configuration with M.U.T.-III SE. For details, refer to .", "ptxt");
si[i++] = gsitm("N5080406C0002I00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5080406C0002I00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5080406C0002I00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5080406C0002I00ENG.html", "Perform writing vehicle specification to air bag diagnosis sensor unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5080406C0002I00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5080406C0002I00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N5080406C0002I00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5080403X0002500ENG.html", "Description", "title");
si[i++] = gsitm("N5080403X0002500ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the air bag diagnosis sensor unit.", "ptxt");
si[i++] = gsitm("N5080403X0002500ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the air bag diagnosis sensor unit.", "ptxt");
si[i++] = gsitm("N5080403X0002500ENG.html", "Refer to .", "ptxt");
