si[i++] = gsitm("N509010450003W00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N509010450003W00ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N509010450003W00ENG.html", "If the filter is deformed/damaged when removing, replace it with a new one. Deformed/damaged filter may deteriorate the dust collecting performance.", "ptxt");
si[i++] = gsitm("N509010450003W00ENG.html", "When installing, handle the filter with extreme care to avoid deforming/damaging.", "ptxt");
