si[i++] = gsitm("N5090203Z0000A00ENG.html", "A/C Compressor", "title");
si[i++] = gsitm("N5090203Z0000A00ENG.html", "Intakes, compresses, and discharges refrigerant, to circulate refrigerant inside the refrigerant cycle.", "ptxt");
si[i++] = gsitm("N5090203Z0000W00ENG.html", "A/C Compressor", "title");
si[i++] = gsitm("N5090203Z0000W00ENG.html", "Intakes, compresses, and discharges refrigerant, to circulate refrigerant inside the refrigerant cycle.", "ptxt");
si[i++] = gsitm("N509020400000A00ENG.html", "Condenser", "title");
si[i++] = gsitm("N509020400000A00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N509020400000A00ENG.html", "A sub-cool condenser that combines a parallel-flow condenser and liquid tank in the sub-cool cycle is used.", "ptxt");
si[i++] = gsitm("N509020400000A00ENG.html", "Cools refrigerant discharged from compressor, and transforms it to liquid refrigerant.", "ptxt");
si[i++] = gsitm("N509020400000A00ENG.html", "STRUCTURE AND OPERATION", "title");
si[i++] = gsitm("N509020400000A00ENG.html", "The sub-cool section is installed on the condenser, and the liquid refrigerant that exits the liquid tank is further cooled by the condenser sub-cool section, increasing the amount of heat that the liquid refrigerant can absorb and improving cooling performance.", "ptxt");
si[i++] = gsitm("N509020410000O00ENG.html", "Liquid Tank", "title");
si[i++] = gsitm("N509020410000O00ENG.html", "A liquid tank compatible with HFC134a &lt;22 Model Year, From 23 Model Year (Except Vehicles for Australia and New Zealand)> or HFO-1234yf &lt;From 23 Model Year (Vehicles for Australia and New Zealand)> refrigerant is used.", "ptxt");
si[i++] = gsitm("N509020410000O00ENG.html", "Eliminates foreign matter in refrigerant, and stores temporarily liquid refrigerant.", "ptxt");
si[i++] = gsitm("N509020420000A00ENG.html", "Heater & Cooling Unit Assembly", "title");
si[i++] = gsitm("N509020420000A00ENG.html", "This system utilizes a heater & cooling unit that combines heater unit, and cooling unit.", "ptxt");
si[i++] = gsitm("N509020430000A00ENG.html", "Expansion Valve", "title");
si[i++] = gsitm("N509020430000A00ENG.html", "The refrigerant temperature is detected by the temperature sensing part located in low-pressure refrigerant path inside expansion valve. The lift amount of high-pressure side ball valve is changed to regulate the refrigerant flow.", "ptxt");
si[i++] = gsitm("N509020440000A00ENG.html", "Evaporator", "title");
si[i++] = gsitm("N509020440000A00ENG.html", "A thin laminate pipeless evaporator is used.", "ptxt");
si[i++] = gsitm("N509020440000A00ENG.html", "The mist from liquid refrigerant transforms to gas by evaporation by the air conveyed from blower motor. The air is cooled by the heat by evaporation.", "ptxt");
si[i++] = gsitm("N509020450000G00ENG.html", "Internal Heat Exchanger Pipe", "title");
si[i++] = gsitm("N509020450000G00ENG.html", "Transfers heat out of the liquid refrigerant, sub cooling it below condensation temperature.", "ptxt");
si[i++] = gsitm("N509020450000H00ENG.html", "Internal Heat Exchanger Pipe", "title");
si[i++] = gsitm("N509020450000H00ENG.html", "Transfers heat out of the liquid refrigerant, sub cooling it below condensation temperature.", "ptxt");
si[i++] = gsitm("N509020460000I00ENG.html", "System Diagram", "title");
si[i++] = gsitm("N509020460000I00ENG.html", "Except vehicles for GCC, Australia and New Zealand", "title");
si[i++] = gsitm("N509020460000I00ENG.html", "Vehicles for GCC, Australia and New Zealand", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "System Description", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "REFRIGERANT CYCLE", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "Refrigerant Flow", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "The refrigerant from the A/C compressor, flows the condenser with liquid tank, the evaporator, and returns to the A/C compressor. The refrigerant evaporation in the evaporator is controlled by an expansion valve.", "ptxt");
si[i++] = gsitm("N5090202T0000C00ENG.html", "Freeze Protection", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090202T0000C00ENG.html", "REFRIGERANT SYSTEM PROTECTION", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "Refrigerant Pressure Sensor", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "The refrigerant system is protected against excessively high- or low-pressures by the refrigerant pressure sensor, located on the condenser. The refrigerant pressure sensor detects the pressure inside the refrigerant line and sends the voltage signal to the ECM if the system pressure rises above, or falls below the specifications.", "ptxt");
si[i++] = gsitm("N5090202T0000C00ENG.html", "ECM turns the A/C relay to OFF and stops the A/C compressor when the high-pressure side detected by refrigerant pressure sensor.", "ptxt");
si[i++] = gsitm("N5090202T0000C00ENG.html", "Pressure Relief Valve", "title");
si[i++] = gsitm("N5090202T0000C00ENG.html", "The refrigerant system is also protected by a pressure relief valve, located in the rear head of the A/C compressor. The release port on the pressure relief valve automatically opens and releases refrigerant into the atmosphere when the pressure of refrigerant in the system increases to an unusual level [more than 3,800 kPa (38.0 bar, 38.8 kg/cm2, 551 psi)].", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "INTERVIEW FOR MALFUNCTION", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Interview the symptom to the customer.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "SYMPTOM CHECK", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Check the symptom from the customer\'s information. Check that any symptom occurs other than the interviewed symptom.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Insufficient cooling/heating", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Refrigerant leakage", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Noise", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "CONTROL SYSTEM DIAGNOSIS", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Perform the system diagnosis for the A/C control system. Refer to .", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Is A/C control system normal?", "question");
si[i++] = gsitm("N509020300000A00ENG.html", "YES", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "NO", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "PERFORMANCE TEST", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Perform the performance test. Check the operation of each part. Refer to .", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "TROUBLE DIAGNOSIS FOR UNUSUAL PRESSURE", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Diagnose using a manifold gauge whenever system\'s high and/or low side pressure(s) is/are unusual. Specify the malfunctioning part. Refer to .", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Low refrigerant charge", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "Except above", "result");
si[i++] = gsitm("N509020300000A00ENG.html", "CHECK REFRIGERANT FOR LEAKAGES", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Check refrigerant for leakages. Specify the malfunctioning part.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "TROUBLE DIAGNOSIS FOR NOISE", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Perform trouble diagnosis for noise. Specify the malfunctioning part. Refer to .", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "MALFUNCTION PART REPAIR", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "REPAIR CHECK (OPERATION CHECK)", "title");
si[i++] = gsitm("N509020300000A00ENG.html", "Check the operation of each part.", "ptxt");
si[i++] = gsitm("N509020300000A00ENG.html", "Does it operate normally?", "question");
si[i++] = gsitm("N509020300000A00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N509020560000100ENG.html", "Recycle Refrigerant/Charge Refrigerant", "title");
si[i++] = gsitm("N509020560000100ENG.html", "Never charge the refrigerant excessively, or the A/C system may be damaged.", "ptxt");
si[i++] = gsitm("N509020560000100ENG.html", "Always keep away thermal ignition sources, electrical sparks or flame impact from the refrigerant. In the presence of flame, refrigerant forms a poisonous gas. Keep the area well ventilated.", "ptxt");
si[i++] = gsitm("N509020560000100ENG.html", "Recover the refrigerant according to the specified procedure. Never release it into the atmosphere.", "ptxt");
si[i++] = gsitm("N509020560000100ENG.html", "Remove the refrigerant by the flon reclaim machine and replenish the specified quantity of refrigerant.", "ptxt");
si[i++] = gsitm("N509020560000100ENG.html", "Refer to the Refrigerant Recovery and Recycling Unit instruction Manual for operation of the unit.", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Description", "title");
si[i++] = gsitm("N509020110001I00ENG.html", "CONNECTION OF SERVICE TOOLS AND EQUIPMENT", "title");
si[i++] = gsitm("N509020110001I00ENG.html", "Shut-off valve", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "A/C service valve", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Recovery/recycling/recharging equipment", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Refrigerant container (HFO-1234yf)", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Weight scale", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Vacuum pump", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Manifold gauge set", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Preferred (best) method", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "Alternative method", "ptxt");
si[i++] = gsitm("N509020110001I00ENG.html", "For charging", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Leak Test", "title");
si[i++] = gsitm("N509020490000J00ENG.html", "CHECK REFRIGERANT LEAKAGE USING ELECTRICAL LEAK DETECTOR", "title");
si[i++] = gsitm("N509020490000J00ENG.html", "Never check refrigerant leakage while the engine is running.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Be careful of the following items so that inaccurate checks or misidentifications are avoided.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Never allow refrigerant vapor, shop chemical vapors, cigarette smoke, or others around the vehicle.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Always check refrigerant leakage in a low air flow environment so that refrigerant may not disperse when leakage occurs.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Stop the engine.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Connect recovery/recycling/recharging equipment or manifold gauge set to A/C service valve.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Check that A/C refrigerant pressure is 345 kPa (3.45 bar, 3.52 kg/cm2, 50 psi) or more when temperature is 16°C (61°F) or more. When pressure is lower than the specified value, recycle refrigerant completely and fill refrigerant to the specified level.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Leakages may not be detected if A/C refrigerant pressure is 345 kPa (3.45 bar, 3.52 kg/cm2, 50 psi) or less when temperature is less than 16°C (61°F).", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Clean area where refrigerant leakage check is performed, and check refrigerant leakage along all surfaces of pipe connections and A/C system components using electrical leak detector probe.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Continue checking when a leakage is found. Always continue and complete checking along all pipe connections and A/C system components for additional leakage.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "When a leakage is detected, clean leakage area using compressed air and check again.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "When checking leakage of cooling unit inside, always clean inside of drain hose so that the probe surface may not be exposed to water or dirt.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Always check leakage starting from high-pressure side and continue to low-pressure side.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "When checking leakage of cooling unit inside, operate blower fan motor for 15 minutes or more at the maximum fan speed while the engine is stopped, and then insert electrical leak detector probe into drain hose and hold for 10 minutes or more.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "When disconnecting shut-off valve that is connected to A/C service valve, always evacuate remaining refrigerant so that misidentification can be avoided.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Repair or replace parts where refrigerant leakage is detected. (Leakage is detected but leakage area is unknown. GO TO 6.)", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Start the engine and set A/C control in the following conditions.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "A/C switch ON", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Air flow: VENT (ventilation)", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Intake door position: Recirculation", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Temperature setting: Full cold", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Fan (blower) speed: Maximum speed set", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Run the engine at approximately 1,500 rpm for 2 minutes or more.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Stop the engine. Check again for refrigerant leakage. GO TO 4.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Be careful not to get burned when the engine is hot.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "Start refrigerant leakage check immediately after the engine is stopped.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "When refrigerant circulation is stopped, pressure on the low-pressure side rises gradually, and after this, pressure on the high-pressure side falls gradually.", "ptxt");
si[i++] = gsitm("N509020490000J00ENG.html", "The higher the pressure is, the easier it is to find the refrigerant leakage.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Recycle Refrigerant", "title");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Always use HFO-1234yf for A/C refrigerant. If CFC-12 or HFC-134a is accidentally charged, A/C compressor is damaged due to insufficient lubrication.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Always observe and follow precautions described on refrigerant container. Incorrect handling may result in an explosion of refrigerant container, frostbite, or the loss of eyesight.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Never breathe A/C refrigerant and lubricant vapor or mist. Exposure may irritate eyes, nose, or throat.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Never allow HFO-1234yf to be exposed to an open flame or others because it generates poisonous gas when in contact with high temperature objects. Keep workshop well ventilated.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Perform lubricant return operation. Refer to Perform Lubricant Return Operation. (If refrigerant or lubricant leakage is detected in a large amount, omit this step, and then GO TO 2.)", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Never perform lubricant return operation if a large amount of refrigerant or lubricant leakage is detected.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Check gauge pressure readings of recovery/recycling/recharging equipment. When remaining pressure exists, recycle refrigerant from high-pressure hose and low-pressure hose.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Follow manufacturer instructions for the handling or maintenance of the equipment. Never fill the equipment with non-specified refrigerant.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Remove A/C service valve cap from the vehicle.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Connect recovery/recycling/recharging equipment to A/C service valve.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Operate recovery/recycling/recharging equipment, and recycle refrigerant from the vehicle.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Evacuate air for 10 minutes or more to remove any remaining refrigerant integrated to compressor lubricant, etc.", "ptxt");
si[i++] = gsitm("N5090204A0000L00ENG.html", "Refrigerant recycle operation is complete.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Charge Refrigerant", "title");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Always use HFO-1234yf for A/C refrigerant. If CFC-12 or HFC-134a is accidentally charged, compressor is damaged due to insufficient lubrication.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Always observe and follow precautions described on refrigerant container. Incorrect handling may result in an explosion of refrigerant container, frostbite, or the loss of eyesight.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Never breathe A/C refrigerant and lubricant vapor or mist. Exposure my irritate eyes, nose, or throat.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Never allow HFO-1234yf to be exposed to an open flame or others because it generates poisonous gas when in contact with high temperature objects. Keep workshop well ventilated.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Connect recovery/recycling/recharging equipment to the A/C service valve.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Operate recovery/recycling/recharging equipment, and evacuate air from A/C system for 25 minutes or more.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Evacuate air for 15 minutes or more if the parts are replaced.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Check the airtightness of A/C system for 25 minutes or more. If pressure raises more than the specified level, charge A/C system with approximately 200 g refrigerant and check that there is no refrigerant leakage. Refer to .", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Check the airtightness for 15 minutes or more if the parts are replaced.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "If parts other than compressor are replaced, fill compressor lubricant according to parts that are replaced.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Charge the specified amount of refrigerant to A/C system.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Check that A/C system operates normally.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Disconnect recovery/recycling/recharging equipment. (Collect the refrigerant from the high-pressure hose and low-pressure hose of recovery/recycling/recharging equipment.)", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Install A/C service valve cap.", "ptxt");
si[i++] = gsitm("N5090204B0000L00ENG.html", "Refrigerant charge is complete.", "ptxt");
si[i++] = gsitm("N509020560000200ENG.html", "Recycle Refrigerant/Charge Refrigerant", "title");
si[i++] = gsitm("N509020560000200ENG.html", "Never charge the refrigerant excessively, or the A/C system may be damaged.", "ptxt");
si[i++] = gsitm("N509020560000200ENG.html", "Always keep away thermal ignition sources, electrical sparks or flame impact from the refrigerant. In the presence of flame, refrigerant forms a poisonous gas. Keep the area well ventilated.", "ptxt");
si[i++] = gsitm("N509020560000200ENG.html", "Recover the refrigerant according to the specified procedure. Never release it into the atmosphere.", "ptxt");
si[i++] = gsitm("N509020560000200ENG.html", "Remove the refrigerant by the flon reclaim machine and replenish the specified quantity of refrigerant.", "ptxt");
si[i++] = gsitm("N509020560000200ENG.html", "Refer to the Refrigerant Recovery and Recycling Unit instruction Manual for operation of the unit.", "ptxt");
si[i++] = gsitm("N509020110000U00ENG.html", "Description", "title");
si[i++] = gsitm("N509020110000U00ENG.html", "MAINTENANCE OF LUBRICANT LEVEL", "title");
si[i++] = gsitm("N509020110000U00ENG.html", "The A/C compressor lubricant is circulating in the system together with the refrigerant. It is necessary to fill A/C compressor with lubricant when replacing A/C system parts or when a large amount of refrigerant leakage is detected. It is important to always maintain lubricant level within the specified level. Or otherwise, the following conditions may occur.", "ptxt");
si[i++] = gsitm("N509020110000U00ENG.html", "Insufficient lubricant amount: Stuck A/C compressor", "ptxt");
si[i++] = gsitm("N509020110000U00ENG.html", "Excessive lubricant amount: Insufficient cooling (caused by insufficient heat exchange)", "ptxt");
si[i++] = gsitm("N509020110000U00ENG.html", "Name", "ptxt");
si[i++] = gsitm("N509020110000U00ENG.html", ": ND-OIL12 (PAG)", "ptxt");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5090201W0000N00ENG.html", "If a A/C compressor is malfunctioning (internal noise, insufficient cooling), check the A/C compressor oil.", "par1");
si[i++] = gsitm("N5090201W0000N00ENG.html", "COMPRESSOR OIL JUDGMENT", "title");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Remove the A/C compressor. Refer to .", "ptxt");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Sample a A/C compressor oil and judge on the figure.", "ptxt");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Judgment result 1", "par3");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Replace A/C compressor only.", "par4");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Judgment result 2", "par5");
si[i++] = gsitm("N5090201W0000N00ENG.html", "Replace compressor and condenser & liquid tank.", "par6");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Perform Lubricant Return Operation", "title");
si[i++] = gsitm("N5090204D0000A00ENG.html", "If a large amount of refrigerant or lubricant leakage is detected, never perform lubricant return operation.", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Start the engine and set to the following conditions.", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Engine speed: Idling to 1,200 rpm", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "A/C switch: ON", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Fan (blower) speed: Maximum speed set", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Intake door position: Recirculation", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Temperature setting: Full cold", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Perform lubricant return operation for approximately 10 minutes.", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Stop the engine.", "ptxt");
si[i++] = gsitm("N5090204D0000A00ENG.html", "Lubricant return operation is complete.", "ptxt");
si[i++] = gsitm("N5090204E0000A00ENG.html", "Lubricant Adjusting Procedure for Components Replacement Except A/C compressor", "title");
si[i++] = gsitm("N5090204E0000A00ENG.html", "Fill with lubricant for the amount that is calculated according to the following conditions.", "ptxt");
si[i++] = gsitm("N5090204E0000A00ENG.html", "Example: Lubricant amount to be added when replacing evaporator and condenser & liquid tank [m (Imp fl oz)] = 45 (1.6) + 15 (0.5) + α", "ptxt");
