si[i++] = gsitm("N5090204F0000A00ENG.html", "Lubricant Adjusting Procedure for A/C compressor Replacement", "title");
si[i++] = gsitm("N5090204F0000A00ENG.html", "Drain lubricant from removed A/C compressor and measure lubricant amount.", "ptxt");
si[i++] = gsitm("N5090204F0000A00ENG.html", "Remove drain bolt , and then drain lubricant from drain port.", "ptxt");
si[i++] = gsitm("N5090204F0000A00ENG.html", "Measure total amount of lubricant that is drained from removed A/C compressor.", "ptxt");
si[i++] = gsitm("N5090204F0000A00ENG.html", "Drain lubricant from a new A/C compressor that is calculated according to the following conditions.", "ptxt");
si[i++] = gsitm("N5090204F0000A00ENG.html", "Amount to be drained (A) [m (Imp fl oz)] = F − (D + S + R + α)", "ptxt");
