si[i++] = gsitm("N5090204F0000A00ENG.html", ": Lubricant amount that is recycled together with refrigerant during recycle operation", "ptxt");
si[i++] = gsitm("N5090204F0000A00ENG.html", "If lubricant amount that is drained from removed A/C compressor is less than 60 m (2.1 Imp fl oz), perform calculation by setting \"D\" as 40 m (1.4 Imp fl oz).", "ptxt");
