si[i++] = gsitm("N5090201W0003U00ENG.html", "TEST CONDITION SETTING", "title");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Check that the temperature/humidity of measurement location satisfies the test conditions, and then set the vehicle body conditions to the designated status according to the test conditions. If the temperature/humidity is not within the test conditions, an accurate judgment cannot be made. Therefore, postpone the performance test.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "COOLING PERFORMANCE CHECK", "title");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Insert a thermometer into the air outlet located at the center of instrument panel.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Set a thermometer so that cool air from the air outlet blows directly against the sensing part.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Set a wet and dry bulb thermometer in the air intake of the front passenger\'s foot area (below the glove box).", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Set a wet and dry bulb thermometer so that cool air does not blow against it.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Start the engine to warm up. Confirm that the engine speed of the test condition is satisfied.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Set the A/C control panel to the mode instructed in the test conditions.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Wait until the air outlet temperature is stable (approximately 10 minutes after the A/C starts), and measure dry-bulb/wet-bulb temperatures at the air outlet and the air intake.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "If the air outlet temperature is in the range specified by the table below, it is judged normal. If the temperature is outside the permissible range in the table below, refer to the refrigerant gas pressure inspection result, and check each section according to the diagnosis chart of refrigerant system.", "ptxt");
