si[i++] = gsitm("N5090201W0003U00ENG.html", "REFRIGERANT GAS PRESSURE CHECK", "title");
si[i++] = gsitm("N5090201W0003U00ENG.html", "The temperature of equipment in the engine room is high and the refrigerant gas pressure is also high immediately after the engine and A/C operation are stopped, thus leave the vehicle for a while, and then perform the refrigerant gas pressure check.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "On completion, stop the engine and wait until the high-pressure side of the gauge manifold is depressurized. Then remove the quick joints and the others.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Place the quick joint onto the service valve, and press to fit the part A securely until the sleeve clicks into place.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "When connecting, run your hand along the hose while pressing to ensure that there are no bends in the hose.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Check that the engine and A/C are stopped.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Close the high-pressure valve of the gauge manifold.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Connect the charging hose to the hi-pressure side of the gauge manifold.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Connect the coupler high side to the charging hose.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Install the coupler high side to the high-pressure side service valve of the vehicle.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Close the low-pressure valve of the gauge manifold.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Connect the charging hose to the low-pressure side of the gauge manifold.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Connect the coupler low side to the charging hose.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Install the coupler low side to the low-pressure side service valve of the vehicle.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Start and fully warm up the engine, and then check that the engine speed of the test condition is satisfied.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Measure the high pressure/low pressure, and check that the measurement is within the permissible range of the table below. If the value is outside the permissible range, refer to the cooling performance check result, and perform a check according to the diagnosis chart of refrigerant system.", "ptxt");
si[i++] = gsitm("N5090201W0003U00ENG.html", "Prior to the measurement, wait until the refrigerant pressure is stable. (Approximately 10 minutes after A/C operation start)", "ptxt");
