si[i++] = gsitm("N5090204N0009900ENG.html", "&lt;&lt;A>> A/C COMPRESSOR AND CLUTCH ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5090204N0009900ENG.html", "Use the plug which is not breathable because A/C compressor oil or receiver have high hygroscopicity.", "ptxt");
