si[i++] = gsitm("N5090204N0009900ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N5090204N0009900ENG.html", ">>A&lt;&lt; A/C COMPRESSOR AND CLUTCH ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N5090204N0009900ENG.html", "If a new compressor is installed, first adjust the amount of oil according to the procedures described below, and then install the compressor.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Measure the amount X mL of oil within the removed compressor.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Drain (from the new compressor) the amount of oil calculated according to the following formula, and then install the new compressor.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "New compressor oil amount = 110mL", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "110 mL - X mL = Y mL", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Y mL indicates the amount of oil in the refrigerant line, the condenser, the evaporator, etc.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Perform compressor lubricant adjusting procedure before installing new compressor. Refer to .", "par3");
si[i++] = gsitm("N5090204N0009900ENG.html", "Check for leakages when recharging refrigerant.", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Check tension of the drive belt after installing A/C compressor and clutch assembly. Refer to Adjustment .", "ptxt");
si[i++] = gsitm("N5090204N0009900ENG.html", "Tighten A/C compressor and clutch assembly mounting bolts according to the following order.", "par4");
si[i++] = gsitm("N5090204N0009900ENG.html", "Temporarily tighten .", "par7");
si[i++] = gsitm("N5090204N0009900ENG.html", "Tighten  to the specified torque.", "par8");
si[i++] = gsitm("N5090201W0003R00ENG.html", "Inspection", "title");
si[i++] = gsitm("N5090201W0003R00ENG.html", "A/C COMPRESSOR (MAGNETIC CLUTCH) OPERATION CHECK", "title");
si[i++] = gsitm("N5090201W0003R00ENG.html", "Connect the connector battery to positive battery terminal in the A/C compressor, and then earth the battery (-) terminal to the A/C compressor itself. At this time, check that the A/C compressor (magnetic clutch) operating sound can be heard.", "ptxt");
