si[i++] = gsitm("N5090204N0009C00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5090204N0009C00ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5090204N0009C00ENG.html", "The air conditioning evaporator should never be repaired or replaced with a part from another vehicle. To replace a damaged or leaking evaporator, use only a new genuine Mitsubishi Motors replacement part or equivalent.", "ptxt");
si[i++] = gsitm("N5090204N0009C00ENG.html", "Install so that there are no gaps in heater & cooling unit, front case upper and front case lower.", "par21");
si[i++] = gsitm("N5090204N0009C00ENG.html", "After installing a new evaporator, adjust the compressor lubricant level. Refer to .", "par20");
si[i++] = gsitm("N5090204N0009C00ENG.html", "Replace O-rings with new ones. Then apply A/C compressor oil to them when installing.", "ptxt");
si[i++] = gsitm("N5090204N0009C00ENG.html", "Check for leakages when recharging refrigerant.", "ptxt");
si[i++] = gsitm("N5090204N0009B00ENG.html", "Removal and Installation", "title");
