si[i++] = gsitm("N5090204N0009B00ENG.html", "Remove cooler packing.", "ptxt");
si[i++] = gsitm("N5090204N0009B00ENG.html", "Remove mounting bolts and then remove expansion valve.", "ptxt");
si[i++] = gsitm("N5090204N0009B00ENG.html", "Cap or wrap the joint of the evaporator and expansion valve with suitable material such as vinyl tape to avoid the entry of air.", "ptxt");
si[i++] = gsitm("N5090204N0009B00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5090204N0009B00ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
