si[i++] = gsitm("N5090304Y0000E00ENG.html", "A/C Amp.", "title");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "A/C amp. controls the automatic air conditioning system by inputting and calculating signals from each sensor and each switch.", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "The A/C amp. consists of a microcomputer and input/output connectors for signals and power supply.", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "It has a CAN communications function, and it transmits and receives the necessary signals from each control module via CAN communication.", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "It has a LIN communications function, and transmits and receives signals to/from the A/C switch assembly, each door motor, rear air control and each seat heater.", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "A/C amp. has self-diagnosis function. Diagnosis of automatic air conditioning system can be performed quickly.", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5090304Y0000E00ENG.html", "The A/C amp. is installed to the blower unit assembly.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "A/C Switch Assembly", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "A/C switch assembly transmits setting status to A/C amp. via LIN communication line. A/C amp. controls automatic air conditioning system.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "A/C switch assembly has switches and display that can set and indicate the operation of automatic air conditioning system.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "With rear air control", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Without rear air control", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "The conditions that are set for the automatic air conditioning system that is operated by each control switch are transmitted to the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "The operating status of the automatic air conditioning is transmitted from the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "The operation status of each switch is detected by the control and is transmitted as an operation signal to the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "The following switch specification control was adopted.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Temperature control: Dial type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Air outlet control: Push-return type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Air inlet control: Push-return type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Air flow control: Push-return type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "A/C compressor ON/OFF: Push-return type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Regarding the push switches: Refer to the following for the differences between push-lock types and push-return types.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Push-lock type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Push-return type", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch ON operation", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch OFF operation", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch ON operation: At the time of switch ON operation, the switch is pushed from the reference point  to the pushed position , and the switch turns ON. When the switch is released from this position, the switch returns from the pushed position  to the hold position , and the switch position is held there.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch OFF operation: At the time of the switch OFF operation, the switch is pushed from the hold position  to the pushed position . When the switch is released from this position, the switch returns from the pushed position  to the reference point , and the switch turns OFF.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch ON operation: At the time of the switch ON operation, the switch is pushed from the reference point  to the pushed position , and the switch turns ON. When the switch is released from this position, the switch returns from the pushed position  to the reference point .", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Switch OFF operation: At the time of the switch OFF operation, the switch is pushed from the reference point  to the pushed position , and the switch turns OFF. When the switch is released from this position, the switch returns from the pushed position  to the reference point .", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "For details the function of each switch. Refer to .", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "The A/C switch assembly is installed to the center ventilator finisher.", "ptxt");
si[i++] = gsitm("N5090304Z0000X00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Rear Air Control", "title");
si[i++] = gsitm("N509030500000B00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030500000B00ENG.html", "The rear air control is activated by LIN communication with the A/C amp., and can set the rear temperature.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "The rear air conditioning operating status is indicated on the display located on the control.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030500000B00ENG.html", "The conditions that are set for the rear air control that is operated by temperature switch are transmitted to the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "The operating status of the  air conditioner is transmitted from the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030500000B00ENG.html", "The operation status of each switch is detected by the control and is transmitted as an operation signal to the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "The following switch specification control was adopted.", "ptxt");
