si[i++] = gsitm("N509030500000B00ENG.html", "Push-return type", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch ON operation", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch OFF operation", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch ON operation: At the time of switch ON operation, the switch is pushed from the reference point  to the pushed position , and the switch turns ON. When the switch is released from this position, the switch returns from the pushed position  to the hold position , and the switch position is held there.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch OFF operation: At the time of the switch OFF operation, the switch is pushed from the hold position  to the pushed position . When the switch is released from this position, the switch returns from the pushed position  to the reference point , and the switch turns OFF.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch ON operation: At the time of the switch ON operation, the switch is pushed from the reference point  to the pushed position , and the switch turns ON. When the switch is released from this position, the switch returns from the pushed position  to the reference point .", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Switch OFF operation: At the time of the switch OFF operation, the switch is pushed from the reference point  to the pushed position , and the switch turns OFF. When the switch is released from this position, the switch returns from the pushed position  to the reference point .", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "For the name and function of each switch. Refer to .", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030500000B00ENG.html", "The rear air control is installed to the console rear finisher.", "ptxt");
si[i++] = gsitm("N509030500000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "Ambient Sensor", "title");
si[i++] = gsitm("N509030510000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030510000E00ENG.html", "The ambient sensor detects the temperature of the ambient air, and transmits the ambient sensor signal to the combination meter.", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "This signal is transmitted from the combination meter to the A/C amp. via CAN communication and is used in air conditioning system.", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030510000E00ENG.html", "The ambient sensor measures the ambient air temperature.", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030510000E00ENG.html", "The ambient sensor measures the ambient air temperature, and transmits the ambient sensor signal to the combination meter. This sensor uses a thermistor with electrical resistance that decreases as the temperature increases.", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030510000E00ENG.html", "The ambient sensor is installed to the active grille shutter.", "ptxt");
si[i++] = gsitm("N509030510000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030520001300ENG.html", "Intake Sensor", "title");
si[i++] = gsitm("N509030520001300ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030520001300ENG.html", "The intake sensor converts the evaporator surface temperature detected with thermistor into the voltage, and the A/C amp. inputs this voltage.", "ptxt");
si[i++] = gsitm("N509030520001300ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030520001300ENG.html", "Intake sensor measures evaporator temperature (through air temperature).", "ptxt");
si[i++] = gsitm("N509030520001300ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030520001300ENG.html", "The sensor uses a thermistor which is sensitive to the change in temperature. The electrical resistance of the thermistor decreases as temperature increases.", "ptxt");
si[i++] = gsitm("N509030520001300ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030520001300ENG.html", "Intake sensor is located on the evaporator.", "ptxt");
si[i++] = gsitm("N509030520001300ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "In-vehicle Sensor", "title");
si[i++] = gsitm("N509030530000B00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030530000B00ENG.html", "The in-vehicle sensor detects the temperature of the in-vehicle air that is taken in by the aspirator, and transmits the in-vehicle sensor signal to the A/C amp.", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030530000B00ENG.html", "The in-vehicle sensor measures the temperature of the in-vehicle air taken in by the front blower motor.", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030530000B00ENG.html", "The in-vehicle sensor measures the temperature of the in-vehicle air that is taken in by the aspirator, and transmits the in-vehicle sensor signal to the A/C amp. This sensor uses a thermistor with electrical resistance that decreases as the temperature increases.", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "The aspirator generates the vacuum by the air blown from the heater & cooling unit case and draws the air of the passenger room to the in-vehicle sensor area via the aspirator duct.", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030530000B00ENG.html", "The in-vehicle sensor is installed to the instrument lower panel center.", "ptxt");
si[i++] = gsitm("N509030530000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "Refrigerant Pressure Sensor", "title");
si[i++] = gsitm("N509030540000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030540000E00ENG.html", "The refrigerant pressure sensor converts high-pressure side refrigerant pressure into voltage and outputs it to ECM.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "This value is transmitted from the ECM to the A/C amp. via CAN communication and is used in A/C compressor control and cooling fan operation request control.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030540000E00ENG.html", "The refrigerant pressure sensor converts refrigerant pressure into voltage.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030540000E00ENG.html", "The refrigerant pressure sensor is a capacitance type sensor. It consists of a pressure detection area and a signal processing area.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "The pressure detection area, which is a variable capacity condenser, changes internal static capacitance according to pressure force.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "The signal processing area detects the static capacitance of the pressure detection area, converts the static capacitance into a voltage value, and transmits the voltage value to ECM.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "The output voltage increases as the refrigerant pressure rises.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030540000E00ENG.html", "The refrigerant pressure sensor is installed to the high pressure pipe.", "ptxt");
si[i++] = gsitm("N509030540000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030550000B00ENG.html", "Sunload Sensor", "title");
si[i++] = gsitm("N509030550000B00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030550000B00ENG.html", "Sunload sensor converts sunload amount to voltage signal by photodiode and transmits to A/C amp.", "ptxt");
si[i++] = gsitm("N509030550000B00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030550000B00ENG.html", "Sunload sensor measures sunload amount.", "ptxt");
si[i++] = gsitm("N509030550000B00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030550000B00ENG.html", "The sunload sensor measures the sunload and outputs the sunload sensor signal to the A/C amp. This sensor uses a photodiode with an electrical current that increases as the sunload increases.", "ptxt");
si[i++] = gsitm("N509030550000B00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030550000B00ENG.html", "The sunload sensor is installed to the instrument garnish.", "ptxt");
si[i++] = gsitm("N509030550000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "Air Mix Door Motor LH", "title");
si[i++] = gsitm("N509030560000W00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030560000W00ENG.html", "Air mix door motor LH consists of motor that drives door, PBR (Potentio Balance Register) that detects door position and LCU (Local Control Unit) that perform multiplex communication control (LIN) with A/C amp.", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030560000W00ENG.html", "Rotation of motor is transmitted to front air mix door (left side). Air flow temperature is switched.", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030560000W00ENG.html", "LCU (Local Control Unit) is built into air mix door motor LH. And detects door position by PBR (Potentio Balance Resistor).", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "A/C amp. communicates with each LCU via communication line. And receives air mix door LH position feedback signal from LCU.", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "LCU transmits the signal of door movement completion to A/C amp., when the door movement is completed.", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030560000W00ENG.html", "The air mix door motor LH is installed to the heater & cooling unit assembly.", "ptxt");
si[i++] = gsitm("N509030560000W00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "Air Mix Door Motor RH", "title");
si[i++] = gsitm("N509030570000V00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030570000V00ENG.html", "Air mix door motor RH consists of motor that drives door, PBR (Potentio Balance Register) that detects door position and LCU (Local Control Unit) that perform multiplex communication control (LIN) with A/C amp.", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030570000V00ENG.html", "Rotation of motor is transmitted to front air mix door (right side). Air flow temperature is switched.", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030570000V00ENG.html", "LCU (Local Control Unit) is built into air mix door motor RH. And detects door position by PBR (Potentio Balance Resistor).", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "A/C amp. communicates with each LCU via communication line. And receives air mix door RH position feedback signal from LCU.", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "LCU transmits the signal of door movement completion to A/C amp., when the door movement is completed.", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030570000V00ENG.html", "The air mix door motor RH is installed to the heater & cooling unit assembly.", "ptxt");
si[i++] = gsitm("N509030570000V00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "Air Mix Door Motor (Rear)", "title");
si[i++] = gsitm("N509030580000B00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030580000B00ENG.html", "Air mix door motor (rear) consists of motor that drives door, PBR (Potentio Balance Register) that detects door position and LCU (Local Control Unit) that perform multiplex communication control (LIN) with A/C amp.", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030580000B00ENG.html", "Rotation of motor is transmitted to rear air mix door. Air flow temperature is switched.", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030580000B00ENG.html", "LCU (Local Control Unit) is built into air mix door motor (rear). And detects door position by PBR (Potentio Balance Resistor).", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "A/C amp. communicates with each LCU via communication line. And receives air mix door (rear) position feedback signal from LCU.", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "LCU transmits the signal of door movement completion to A/C amp., when the door movement is completed.", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030580000B00ENG.html", "The air mix door motor (rear) is installed to the heater & cooling unit assembly.", "ptxt");
si[i++] = gsitm("N509030580000B00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "Front Blower Motor", "title");
si[i++] = gsitm("N509030590000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N509030590000E00ENG.html", "The rotation speed is changed according to the voltage controlled by the A/C amp. and the air flow rate is controlled.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N509030590000E00ENG.html", "The motor with the sirocco fan rotates, taking in-vehicle or ambient air and sending it into the passenger room.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N509030590000E00ENG.html", "The front blower motor adopts the brush-less.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "Brush motor rotates the coil while the brush functions as contact point.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "Brush-less motor, the magnet part rotates.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N509030590000E00ENG.html", "The front blower motor is installed to the blower unit assembly.", "ptxt");
si[i++] = gsitm("N509030590000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "Intake Door Motor", "title");
si[i++] = gsitm("N5090305A0000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5090305A0000E00ENG.html", "Intake door motor consists of motor that drives door, PBR (Potentio Balance Register) that detects door position and LCU (Local Control Unit) that perform multiplex communication control (LIN) with A/C amp.", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5090305A0000E00ENG.html", "Rotation of motor is transmitted to intake door. Air inlet is switched.", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5090305A0000E00ENG.html", "LCU (Local Control Unit) is built into intake door motor. And detects door position by PBR (Potentio Balance Resistor).", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "A/C amp. communicates with each LCU via communication line. And receives intake door position feedback signal from LCU.", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "LCU transmits the signal of door movement completion to A/C amp., when the door movement is completed.", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5090305A0000E00ENG.html", "The intake door motor is installed to the blower unit assembly.", "ptxt");
si[i++] = gsitm("N5090305A0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "Mode Door Motor", "title");
si[i++] = gsitm("N5090305B0000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5090305B0000E00ENG.html", "Mode door motor consists of motor that drives door, PBR (Potentio Balance Register) that detects door position and LCU (Local Control Unit) that perform multiplex communication control (LIN) with A/C amp.", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5090305B0000E00ENG.html", "Rotation of motor is transmitted to each mode door. Air outlet is switched.", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5090305B0000E00ENG.html", "LCU (Local Control Unit) is built into mode door motor. And detects door position by PBR (Potentio Balance Resistor).", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "A/C amp. communicates with each LCU via communication line. And receives each mode door position feedback signal from LCU.", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "LCU transmits the signal of door movement completion to A/C amp., when the door movement is completed.", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5090305B0000E00ENG.html", "The mode door motor is installed to the heater & cooling unit assembly.", "ptxt");
si[i++] = gsitm("N5090305B0000E00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "A/C Compressor", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "IPDM E/R controls the magnetic clutch and ECV (electrical control valve) according to the requests from the A/C amp. and ECM, and changes the A/C compressor drive and refrigerant discharge amount.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "For controlling the A/C compressor, a magnetic clutch  that drives the A/C compressor is used, together with an ECV  that changes the refrigerant discharge amount.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Magnetic Clutch", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "The magnetic clutch turns ON/OFF, transmitting the rotational motion of the engine to the A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "ECV (Electrical Control Valve)", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Changing the cam plate angle, it changes the piston stroke and controls the refrigerant discharge amount.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Magnetic clutch consists of pulley, clutch disc, and field coil.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Pulley is connected with crankshaft pulley of engine via drive belt and is always rotated while engine is running.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Clutch disc is connected with drive shaft of A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Field coil, which becomes a strong electric magnet when electricity is supplied, strongly pulls clutch disc and presses it to pulley.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "When smart FET integrated in IPDM E/R turns ON, electricity is supplied to field coil, clutch disc is presses to pulley, and engine rotational movement is transmitted from crankshaft pulley → drive belt → pulley → clutch disc → drive shaft. A/C compressor is operated. When smart FET turns OFF, electricity is not supplied to field coil, and clutch disc is released from pulley. A/C compressor is not operated.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "ECV (Electrical Control Valve) is integrated in the A/C compressor. IPDM E/R receives the ECV control signal from A/C amp. via CAN communication, and ECV is controlled according to the control signal transmitted from IPDM E/R.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "ECV is controlled according to the control signal transmitted from IPDM E/R.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "The control signal transmitted by IPDM E/R is controlled according to the ECV control signal transmitted from A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "ECV varies the air pressure balance in the left and right air spaces that are divided by the cam plate in order to change the angle of the cam plate inside the A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "By changing the cam plate angle, it changes the piston stroke and controls the refrigerant discharge amount.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5090305C0000J00ENG.html", "The A/C compressor is installed to the engine.", "ptxt");
si[i++] = gsitm("N5090305C0000J00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "System Description", "title");
