si[i++] = gsitm("N5090302V0000U00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "ABS actuator and electric unit (control unit) transmits vehicle speed signal to A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "AV control unit", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "AV control unit transmits blower reduction request signal to A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "BCM transmits remote engine start status signal to A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Combination meter transmits ambient temperature signal to A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "ECM, when receiving A/C ON signal and blower fan ON signal from A/C amp., transmits A/C compressor request signal to IPDM E/R via CAN communication line according to status of the engine and refrigerant pressure.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "ECM transmits engine coolant temperature signal and refrigerant pressure sensor signal to A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "ECM controls the cooling fan based on the cooling fan request signal received from the A/C amp.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Smart FET is integrated in IPDM E/R.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "IPDM E/R operates smart FET when receiving A/C compressor request signal from ECM via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "IPDM E/R controls ECV when receiving ECV control signal from A/C amp. via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C switch assembly", "ptxt");
