si[i++] = gsitm("N5090302V0000U00ENG.html", "Control unit", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Signal status", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the vehicle speed signal to A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the blower reduction request signal to A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the remote engine start status signal to A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the ambient temperature signal to A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the following signal to A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Engine coolant temperature signal", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Refrigerant pressure sensor signal", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the A/C compressor request signal to IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Receives mainly the following signal from A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C ON signal", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Blower fan ON signal", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Cooling fan request signal", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Receives mainly the ECV control signal from A/C amp. via CAN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the A/C control signal to A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Receives mainly the A/C display signal from A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the rear A/C control signal to A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Receives mainly the rear A/C display signal from A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Transmits the door position feedback signal to A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Receives mainly the door motor request signal to A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Automatic air conditioning system is controlled by each function of A/C amp., ECM and IPDM E/R.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Each operation of air conditioning system can be controlled by the A/C switch assembly.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "CONTROL BY A/C amp.", "title");
si[i++] = gsitm("N5090302V0000U00ENG.html", "CORRECTION FOR INPUT VALUE", "title");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Ambient temperature correction", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. inputs the temperature detected by ambient temperature signal received from combination meter via CAN communication as the ambient temperature.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction of the temperature detected by ambient sensor for air conditioning control.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. selects and uses the initial value of ambient temperature data depending on the engine coolant temperature when turning the ignition switch from OFF to ON. The detection temperature of the ambient sensor is used when engine coolant temperature is low [less than approximately 56°C (133°F)]. The memory data (before the ignition switch is OFF) when the engine is warmed up [approximately 56°C (133°F) or more].", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "The correction of the ambient temperature is not performed when the detection temperature of the ambient temperature is less than approximately −20°C (–4°F).", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "In-vehicle temperature correction", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. inputs the temperature detected by in-vehicle sensor as the in-vehicle temperature.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction of the temperature detected by in-vehicle sensor for air conditioning control.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction so that the recognition passenger room temperature changes depending on the difference between the detected passenger room temperature and the recognition passenger room temperature. If the difference is large, the changing is early. The changing becomes slow as the difference becomes small.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Intake temperature correction", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. inputs the temperature detected by intake sensor as the intake temperature (evaporator temperature).", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction of the temperature detected by intake sensor for air conditioning control.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction so that the recognition intake temperature changes depending on the difference between the detected intake temperature and the recognition intake temperature. If the difference is large, the changing is early. The changing becomes slow as the difference becomes small.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Sunload amount correction", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. inputs the sunload amount detected by sunload sensor.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction of the sunload amount detected by sunload sensor for air conditioning control.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "When the sunload amount suddenly changes, for example when entering a tunnel, perform the correction so that the recognition sunload amount of the A/C amp. changes slowly.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "Set temperature correction", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "A/C amp. performs the correction to the target temperature set by the A/C switch assembly so as to match the temperature felt by the passengers depending on the ambient temperature detected by ambient sensor and controls it so that the in-vehicle temperature is always the most suitable.", "ptxt");
si[i++] = gsitm("N5090302V0000U00ENG.html", "CONTROL BY ECM", "title");
si[i++] = gsitm("N5090302V0000U00ENG.html", "CONTROL BY IPDM E/R", "title");
si[i++] = gsitm("N5090305G0000B00ENG.html", "Temperature Control", "title");
si[i++] = gsitm("N5090305G0000B00ENG.html", "When ignition switch is in the ON position, A/C amp. always automatically controls temperature regardless of air conditioner operational state.", "ptxt");
si[i++] = gsitm("N5090305G0000B00ENG.html", "A/C amp. calculates the target air mix door opening angle depending on set temperature, in-vehicle temperature, ambient temperature, and sunload.", "ptxt");
si[i++] = gsitm("N5090305G0000B00ENG.html", "Air mix door is controlled depending on the comparison of current air mix door opening angle and target air mix door opening angle.", "ptxt");
si[i++] = gsitm("N5090305G0000B00ENG.html", "Regardless of in-vehicle temperature, ambient temperature, and sunload, air mix door is fixed at the fully cold position when set temperature is \"Lo\", and at the fully hot position when set temperature is \"Hi\".", "ptxt");
si[i++] = gsitm("N5090305H0000B00ENG.html", "Air Outlet Control", "title");
si[i++] = gsitm("N5090305H0000B00ENG.html", "While air outlet is in automatic control, A/C amp. selects the mode door position depending on a target air mix door angle and outlet air temperature calculated from sunload.", "ptxt");
si[i++] = gsitm("N5090305H0000B00ENG.html", "If ambient temperature is excessively low, D/F is selected to prevent windshield fogging when air outlet is set to FOOT.", "ptxt");
si[i++] = gsitm("N5090305I0000E00ENG.html", "Air Inlet Control", "title");
si[i++] = gsitm("N5090305I0000E00ENG.html", "A/C amp. controls intake door motor, and change air inlet.", "ptxt");
si[i++] = gsitm("N5090305I0000E00ENG.html", "While air inlet is in automatic control, A/C amp. selects air inlet (fresh air intake, 20% fresh air intake, or recirculation) depending on set temperature, in-vehicle temperature, and ambient temperature.", "ptxt");
si[i++] = gsitm("N5090305I0000E00ENG.html", "When air inlet is set to recirculation by manual control, the air inlet may be automatically changed to fresh air intake depending on vehicle condition (example: when ambient temperature and engine coolant temperature are low).", "ptxt");
si[i++] = gsitm("N5090305I0000E00ENG.html", "Air inlet may not be changed to recirculation by intake switch (indicator: ON) (with rear air control) or REC switch (without rear air control) depending on vehicle condition.", "ptxt");
si[i++] = gsitm("N5090305J0000E00ENG.html", "Door Control", "title");
si[i++] = gsitm("N5090305J0000E00ENG.html", "SWITCH AND THEIR CONTROL FUNCTION", "title");
