si[i++] = gsitm("N5090305K0000B00ENG.html", "Air Flow Control", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "A/C amp. changes duty ratio of front blower motor control signal and controls air flow continuously. When air flow is increased, duty ratio of front blower motor control signal gradually increases to prevent a sudden increase in air flow.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "In addition to manual control and automatic control, air flow control is compose of starting fan speed control, low coolant temperature starting control, high in-vehicle temperature starting control, and blower speed control at door motor operation and fan speed control at voice recognition.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "AUTOMATIC AIR FLOW CONTROL", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "A/C amp. decides target air flow depending on target air mix door opening angle.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "A/C amp. changes duty ratio of front blower motor control signal and controls air flow continuously so that air flow matches to target air flow.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "When air outlet is VENT or B/L, the minimum air flow is changed depending on sunload.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "STARTING FAN SPEED CONTROL", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "When front blower motor is activated, A/C amp. gradually increases voltage of front blower motor to prevent a sudden increase in discharge air flow. (T1 – T2 = approximately 8 seconds)", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "Do not perform the starting air flow control when the air outlet is set to DEF.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "LOW COOLANT TEMPERATURE STARTING CONTROL", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "If the engine coolant temperature is 56°C (133°F) or less, to prevent a cold discharged air flow, A/C amp. suspends front blower motor activation for the maximum 150 seconds depending on target air mix door opening angle. After this, voltage of front blower motor is increased gradually, and front blower motor is activated.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "HIGH IN-VEHICLE TEMPERATURE STARTING CONTROL", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "When evaporator temperature is high [intake sensor value is 35°C (95°F) or more], to prevent a hot discharged air flow, A/C amp. suspends front blower motor activation for approximately 3 seconds so that evaporator is cooled by refrigerant.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "FAN SPEED CONTROL AT DOOR MOTOR OPERATION", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "When mode door motor is activated while air flow is more than the specified value, A/C amp. reduces temporarily fan speed so that mode door moves smoothly.", "ptxt");
si[i++] = gsitm("N5090305K0000B00ENG.html", "FAN SPEED CONTROL AT VOICE RECOGNITION", "title");
si[i++] = gsitm("N5090305K0000B00ENG.html", "When the voice control (voice command) switch is operated during air flow automatic control, A/C amp. decreases the air flow of the front blower motor once and controls the air flow so as not to disturb the voice recognition function. This control continues while voice recognition function is operating.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "A/C Compressor Control", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "When the A/C compressor activation condition is satisfied while front blower motor is activated, A/C amp. transmits A/C ON signal and blower fan ON signal to ECM.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "ECM judges the conditions of each sensor (Refrigerant pressure sensor signal, accelerator position signal, etc.), and transmits the A/C compressor request signal to IPDM E/R via CAN communication line.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "By receiving the A/C compressor request signal from ECM, IPDM E/R turns the smart FET to ON, and activates the A/C compressor. Refer to .", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "CONTROL BY A/C amp.", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "Low Temperature Protection Control", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "When intake sensor detects that evaporator fin temperature is  [−5.0°C (23.0°F)] or less, A/C amp. requests ECM to turn the A/C compressor OFF, and stops the A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "When the air temperature returns to  [−2.0°C (28.4°F)] or more, the A/C compressor is activated.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "Refrigerant Discharge Amount Control", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "A/C amp. transmits the ECV control signal via CAN communication. IPDM E/R transmits the control signal to ECV according to the received ECV control signal.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "ECV is controlled according to change in the duty ratio of the transmitted control signal.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "Except when temperature setting is full cold or outlet is DEF, A/C amp. controls the refrigerant discharge amount according to the required cooling capacity.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "A/C amp. increases the refrigerant discharge amount when evaporator temperature is higher than the target temperature upper limit, and reduces the refrigerant discharge amount when evaporator temperature is at or below the target temperature upper limit.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "Target temperature upper limit value of evaporator can be changed using “TARGET EVAPORATOR TEMP UPPER LIMIT SETTING” in “Work support” mode of M.U.T.-III SE. Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "A/C Compressor Oil Circulation Control", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "When the engine starts, A/C amp. activates the A/C compressor for a few seconds and circulates the A/C compressor oil once.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "CONTROL BY ECM", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "A/C Compressor Protection Control at Pressure Malfunction", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "The high-pressure side value that is detected by refrigerant pressure sensor is excessively low or high, ECM requests IPDM E/R to turn smart FET OFF and stop the A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305L0000E00ENG.html", "Air Conditioning Cut Control", "title");
si[i++] = gsitm("N5090305L0000E00ENG.html", "When the engine condition is high load, ECM transmit smart FET OFF request to IPDM E/R, and stops the A/C compressor.", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "Cooling Fan Operation Request Control", "title");
si[i++] = gsitm("N5090305M0000H00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5090305M0000H00ENG.html", "A/C amp. controls the cooling fan operation request according to the refrigerant pressure status and vehicle speed status.", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "For an overview of the cooling fan and information about control. Refer to .", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "CONTROL OUTLINE", "title");
si[i++] = gsitm("N5090305M0000H00ENG.html", "A/C amp. receives the refrigerant pressure sensor signal from ECM via CAN communication and vehicle speed signal from the ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "A/C amp. sets one of the optionally determined stages according to the received refrigerant pressure sensor signal and vehicle speed signal.", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "For the rules that prescribe the predetermined stages, refer to the following figures.", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "Vehicle speed stages", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "Vehicle speed [km/h (MPH)]", "ptxt");
