si[i++] = gsitm("N5090305M0000H00ENG.html", "Refrigerant pressure stages", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "Refrigerant pressure [MPa (bar, kg/cm2, psi)]", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", ": 0.7 (7.0, 7.1, 102)", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", ": 1.0 (10.0, 10.2, 145)", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", ": 1.3 (13.0, 13.3, 189)", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", ": 1.6 (16.0, 16.3, 232)", "ptxt");
si[i++] = gsitm("N5090305M0000H00ENG.html", "The requested cooling fan operation strength (0%, 35%, 40%, 55%, 85%, 100%) is determined according to the combination of these two stages, and the request signal is transmitted to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N5090305N0000G00ENG.html", "Remote Engine Start Control", "title");
si[i++] = gsitm("N5090305N0000G00ENG.html", "A/C amp. operates air conditioning system in following mode according to the vehicle situation when remote engine start function is operated. For an overall description of the remote engine start function. Refer to .", "ptxt");
