si[i++] = gsitm("N5090305N0000G00ENG.html", "When switch is operated while remote engine start function is operated, air conditioning system hold the setting.", "ptxt");
si[i++] = gsitm("N5090305N0000G00ENG.html", "When switch is not operated while remote engine start function is operated, air conditioning system returns to the previous setting.", "ptxt");
si[i++] = gsitm("N5090301L0000T00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5090301L0000T00ENG.html", "FAIL-SAFE FUNCTION", "title");
si[i++] = gsitm("N5090301L0000T00ENG.html", "A/C amp. performs fail-safe control when any DTC are detected.", "ptxt");
