si[i++] = gsitm("N5090301L0000T00ENG.html", "B24A6-15", "ptxt");
si[i++] = gsitm("N5090301L0000T00ENG.html", "If a CAN communication error exists between the A/C amp., ECM, IPDM E/R, BCM and combination meter for 2 seconds or longer, air conditioning is controlled under the following conditions:", "ptxt");
si[i++] = gsitm("N5090301L0000T00ENG.html", "A/C compressor", "ptxt");
