si[i++] = gsitm("N509030320000E00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Record DTC and freeze frame data (Print them out using M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Are any symptoms described and any DTC detected?", "question");
si[i++] = gsitm("N509030320000E00ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Also study the normal operation and fail-safe related to the symptom.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again. At this time, always connect M.U.T.-III SE to the vehicle, and check self diagnostic results in real time.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "If two or more DTCs are detected, refer to DTC INSPECTION PRIORITY CHART, and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N509030320000E00ENG.html", "YES", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "NO", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Is the symptom described?", "question");
si[i++] = gsitm("N509030320000E00ENG.html", "Monitor input data from related sensors or check voltage of related module terminals using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Check DTC. If DTC is detected, erase it.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N509030320000E00ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is repaired securely.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N509030320000E00ENG.html", "YES-1", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "YES-2", "result");
si[i++] = gsitm("N509030320000E00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N509030320000E00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "The purpose of the operation inspection is to check that the individual system operates normally.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check condition", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", ": Engine running at normal operating temperature.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "OPERATION INSPECTION", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK MEMORY FUNCTION", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Press AUTO switch to activate air conditioning.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Set temperature to 32.0°C (89°F) by operating temperature control dial (driver side).", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Press ON·OFF switch.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Ignition switch OFF.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Press AUTO switch.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that the set temperature 32.0°C (89°F) is maintained.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N509030340003N00ENG.html", "YES", "result");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "NO", "result");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK FAN SPEED", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate fan switch and check that fan speed changes.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check operation for all fan speeds.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK AIR OUTLET", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate fan switch to set the fan speed to maximum speed.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate MODE switch and DEF switch.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that air outlets change according to each indicated air outlet by placing a hand in front of the outlets.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK AIR INLET", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Press intake switch to set the air inlet to recirculation. The intake switch indicator turns ON.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Listen to intake sound and confirm air inlets change.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Press intake switch again to set the air inlet to fresh air intake. The intake switch indicator turns OFF.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK A/C COMPRESSOR", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Press A/C switch. The A/C switch indicator turns ON.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check visually and by sound that the A/C compressor operates.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Press A/C switch again. The A/C switch indicator turns OFF.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that A/C compressor stops.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK DISCHARGE AIR TEMPERATURE", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control dial (driver side).", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that discharge air temperature (driver side) changes.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control dial (passenger side).", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that discharge air temperature (passenger side) changes.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control switch (rear air control).", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that discharge rear air temperature changes.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Press SYNC switch. SYNC switch indicator turns ON.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that air temperature setting [front (driver side/passenger side) / rear] is unified to the driver side temperature setting.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK WITH TEMPERATURE SETTING LOWERED", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate A/C compressor.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control dial (driver side) to lower the set temperature to \"Lo\".", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that cool air blows from the air outlets.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK TEMPERATURE INCREASE", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Warm up engine to the normal operating temperature.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control dial (driver side) to raise the set temperature to \"Hi\".", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that warm air blows from the air outlets.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK AUTO MODE", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Press AUTO switch and check that AUTO indicator turns ON.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Operate temperature control switch (driver side) to check that fan speed or air outlet changes (the air outlet or fan speed varies depending on the ambient temperature, in-vehicle temperature, set temperature, and etc.).", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK SELF-DIAGNOSIS WITH M.U.T.-III SE", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Perform self-diagnosis with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that any DTC is detected.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N509030340003N00ENG.html", "Refer to , and perform the appropriate diagnosis.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N509030340003N00ENG.html", "CHECK FAIL-SAFE ACTIVATION", "title");
si[i++] = gsitm("N509030340003N00ENG.html", "Check that symptom is applied to the fail-safe activation. Refer to .", "ptxt");
si[i++] = gsitm("N509030130001W00ENG.html", "Description", "title");
si[i++] = gsitm("N509030130001W00ENG.html", "After replaced A/C amp. it is necessary to perform control unit configuration with M.U.T.-III SE. For details, refer to .", "ptxt");
si[i++] = gsitm("N509030130001W00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N509030130001W00ENG.html", "When replacing A/C amp. write vehicle specification with M.U.T.-III SE vehicle configuration.", "ptxt");
si[i++] = gsitm("N509030130001W00ENG.html", "Never perform vehicle configuration other than performing with new A/C amp. or the control function may not operate normally.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N509030340004500ENG.html", "REPLACE A/C AMP.", "title");
si[i++] = gsitm("N509030340004500ENG.html", "Replace A/C amp. Refer to .", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N509030340004500ENG.html", "Perform configuration (HVAC). Refer to .", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N509030340004500ENG.html", "Turn the ignition switch ON.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "Select “Factory Mode OFF” in “Special Function” of “HVAC”.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "Check item No. 1 “Factory Mode OFF”, perform the following work by setteing value.ON: Select “OK”, change the setting value to “OFF”.OFF: Work completed as no work is required.", "ptxt");
si[i++] = gsitm("N509030340004500ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "Description", "title");
si[i++] = gsitm("N509030130001X00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the A/C amp.", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the A/C amp.", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "The configuration no need to “save” configuration data from the A/C amp. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N509030130001X00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N509030340001900ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N509030340001900ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N509030340001900ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N509030340001900ENG.html", "Perform writing vehicle specification to A/C amp. following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N509030340001900ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N509030340001900ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N509030340001900ENG.html", "WORK END", "ptxt");
