si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;A>> SUN VISOR HOLDER REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Insert special tools MB990784 into the sun visor holder from its left and right sides to disengage the claws on the sun visor holder sides.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;B>> SUN VISOR REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Lift the lock cover bracket.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "Remove the sun visor shown in the figure using a flat-tipped screwdriver.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "Be careful not to damage to the wiring harness of the spot lamp.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "Remove the claws shown in the figure using special tool MB990784.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;C>> MAP LAMP ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "The map lamp assembly has clips on the front side and insertion type tabs on the rear side. Therefore, insert special tool MB990784 from the front side to remove the map lamp assembly.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;D>> VANITY MIRROR LAMP REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Remove the vanity mirror lamp by moving it toward the direction of the arrow (A) shown in the figure.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;E>> ASSIST GRIP REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Remove the assist grip.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "Grab the position shown in the figure of the sheet metal clip with pliers, and remove the clip.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;F>> HEADLINING REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Peel off dual lock fasteners between headlining assembly and roof panel.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "To remove the clip, insert a vinyl cord into a clearance between the clip and the headlining, and pass it around the clip. Then, pull out the clip downwards while pulling the vinyl cord.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "Carry out the headlining assembly from the liftgate opening while deflecting the headlining.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "&lt;&lt;G>> PERSONAL LAMP REMOVAL", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", "Remove the personal lamp by moving it toward the direction of the arrow (A) shown in the figure.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5100105H0001400ENG.html", ">>A&lt;&lt; ASSIST GRIP REMOVAL INSTALLATION", "title");
