si[i++] = gsitm("N5100105H0001400ENG.html", "Attach the assist grip to the mounting location.", "ptxt");
si[i++] = gsitm("N5100105H0001400ENG.html", ">>B&lt;&lt; SUN VISOR INSTALLATION", "title");
