si[i++] = gsitm("N5100202Z0007J00ENG.html", "Be sure to remove the instrument panel center cover by following the procedure below, otherwise the instrument panel plug A may be damaged.", "ptxt");
si[i++] = gsitm("N5100202Z0007J00ENG.html", "Remove the clips shown in the figure. Starting from the clip on the front passenger\'s side, insert a flat-tipped screwdriver from the side or the lower side of the instrument panel center cover as shown in the figure and disengage the clips.", "ptxt");
