si[i++] = gsitm("N510030660000R00ENG.html", "Seat Heater", "title");
si[i++] = gsitm("N510030660000R00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510030660000R00ENG.html", "The seat heater consists of a seatback heater , seat cushion heater , heat sensor , CPU  and thermostat , and controls the heated seat system.", "ptxt");
si[i++] = gsitm("N510030660000R00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510030660000R00ENG.html", "Seat heater controls the temperature of the seat by activating the seat heater using the signals transmitted from the A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N510030660000R00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510030660000R00ENG.html", "Seat heater consists of a CPU that controls the temperature of the seat by activating the seat heater.", "ptxt");
si[i++] = gsitm("N510030660000R00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510030660000R00ENG.html", "Installed in the seat cushion trim and seatback trim underside. Refer to Component Parts Location for detailed installation location.", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N5100301A0002T00ENG.html", "Front seatback ventilator fan", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "Front seat cushion ventilator fan", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "A/C AMP.", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "Ventilated front seat switch", "ptxt");
si[i++] = gsitm("N5100301A0002T00ENG.html", "A/C switch assembly", "ptxt");
si[i++] = gsitm("N510030710000900ENG.html", "Ventilated seat", "title");
si[i++] = gsitm("N510030710000900ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510030710000900ENG.html", "The ventilated seat consists of a front seat cushion ventilator fan , front seatback ventilator fan , Blower duct (built-in seat cushion pad) , Blower duct (built-in seat back pad)  and ECU , and controls the ventilated seat system.", "ptxt");
si[i++] = gsitm("N510030710000900ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510030710000900ENG.html", "The ventilated seat uses a signal transmitted from the A/C automatic amplifier via LIN communication to activate the ventilator fan, which controls the air volume of the seat via a blower duct.", "ptxt");
si[i++] = gsitm("N510030710000900ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510030710000900ENG.html", "The ventilated seat consists of the CPU that activates the ventilator fan.", "ptxt");
si[i++] = gsitm("N510030710000900ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510030710000900ENG.html", "Installed in the seat cushion trim and seatback trim underside. Refer to Component Parts Location for detailed installation location.", "ptxt");
si[i++] = gsitm("N5100304T0002K00ENG.html", "System Description", "title");
si[i++] = gsitm("N5100304T0002K00ENG.html", "Power seat can be operated regardless of the ignition switch position, because power supply is always supplied to power seat switch.", "ptxt");
si[i++] = gsitm("N5100304T0002K00ENG.html", "SLIDING OPERATION", "title");
si[i++] = gsitm("N5100304T0002K00ENG.html", "While operating the sliding switch located in power seat switch, sliding motor operates and makes possible the seat front and back position adjustment.", "ptxt");
si[i++] = gsitm("N5100304T0002K00ENG.html", "RECLINING OPERATION", "title");
si[i++] = gsitm("N5100304T0002K00ENG.html", "While operating the reclining switch located in power seat switch, reclining motor operates and makes possible the seatback forward and backward position adjustment.", "ptxt");
si[i++] = gsitm("N5100304T0002K00ENG.html", "LIFTING OPERATION", "title");
si[i++] = gsitm("N5100304T0002K00ENG.html", "While operating the lifting switch located in power seat switch, lifting motor operates and makes possible the seat up and down position adjustment.", "ptxt");
si[i++] = gsitm("N5100304T0002K00ENG.html", "THIGH SUPPORT OPERATION", "title");
si[i++] = gsitm("N5100304T0002K00ENG.html", "While operating the thigh support switch located in power seat switch, thigh support motor operates and makes possible the seat cushion (front side) up and down position adjustment.", "ptxt");
si[i++] = gsitm("N5100304T0002L00ENG.html", "System Description", "title");
si[i++] = gsitm("N5100304T0002L00ENG.html", "Lumbar support can operate regardless of the ignition switch position, because power supply is always supplied to lumbar support switch.", "ptxt");
si[i++] = gsitm("N5100304T0002L00ENG.html", "While operating the lumbar support switch, pneumatic lumbar support unit operates which allows forward and backward operation of seatback suspension.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "System Description", "title");
si[i++] = gsitm("N5100304T0002M00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "A/C amp.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "A/C amp. receives the switch operation signals transmitted from the A/C switch assembly via LIN communication and transmits the switch operation signals to the seat heater via LIN communication.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Seat heater", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "A/C switch assembly (front seat heater switch)", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Front seat heater switch is integrated in the A/C switch assembly and is used to activate/deactivate the driver\'s seat and passenger seat heaters and set the temperature (Low, Mid, or High).", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "A/C switch assembly receives a switch indicator signal, it illuminates the indicator light on the front seat heater switch or rear seat heater switch.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Rear seat heater switch", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Rear seat heater switch is used to activate/deactivate the rear seat heaters and set the temperature (Low, Mid, or High).", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Heated seat system is activated by seat heater switch while engine is running.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "The seat heater temperature can be adjusted at 3 levels (Low, Mid, High) respective to the heating function by operating the seat heater switch.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "The operation status of the heated seat system can be checked by checking the indicators of the seat heater switch.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5100304T0002M00ENG.html", "When the front seat heater switch is operated, the A/C switch assembly recognizes switch operation.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "When the rear seat heater switch is operated, the A/C switch assembly receives a switch operation signal from rear seat heater switch.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "The A/C switch assembly transmits a switch operation signal to A/C amp. via LIN communication.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "When A/C amp. receives a switch operation signal, it operates the heated seat system.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "A/C amp. operates the heated seat system and simultaneously sends the switch indicator signal to the A/C switch assembly via LIN communication.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "When the A/C switch assembly receives a switch indicator signal, it illuminates the indicator light on the seat heater switch.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Heating Control", "title");
si[i++] = gsitm("N5100304T0002M00ENG.html", "The seat cushion heater is integrated with the heat sensor that detect the seat temperature. The heat sensor transmit the seat temperature as the heat sensor signal to CPU integrated with the seat cushion heater.", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "The CPU recognizes the seat temperature from heat sensor signal. It adjusts the seat temperature by stopping operation when the seat temperature reaches the operation stop temperature , and starting operation when the seat temperature reaches the operation start temperature .", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Preset temperature", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Temperature °C (°F)", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Temperature at operation stop", "ptxt");
si[i++] = gsitm("N5100304T0002M00ENG.html", "Temperature at operation start", "ptxt");
