si[i++] = gsitm("N510030250001200ENG.html", "Seat heater equips fail-safe function.", "ptxt");
si[i++] = gsitm("N510030250001200ENG.html", "When a malfunction occurs in the systems shown below, seat heater performs fail-safe control.", "ptxt");
