si[i++] = gsitm("N5100304T0002N00ENG.html", "A/C switch assembly (ventilated front seat switch)", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "Ventilated front seat switch is integrated in the A/C switch assembly and is used to activate/deactivate the driver\'s seat and passenger ventilator fan and set the air volume (Low, Mid, or High).", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "A/C switch assembly receives a switch indicator signal, it illuminates the indicator light on the ventilated front seat switch.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100304T0002N00ENG.html", "Ventilated seat system is activated by ventilated seat switch while engine is running.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "The seat air volume can be adjusted at 3 levels (Low, Mid, High) by operating the ventilated seat switch.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "The operation status of the ventilated seat system can be checked by checking the indicators of the ventilated seat switch.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5100304T0002N00ENG.html", "When the ventilated front seat switch is operated, the A/C switch assembly recognizes switch operation.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "The A/C switch assembly transmits a switch operation signal to A/C AMP. via LIN communication.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "When A/C AMP. receives a switch operation signal, it operates the ventilated seat system.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "A/C AMP. operates the ventilated seat system and simultaneously sends the switch indicator signal to the A/C switch assembly via LIN communication.", "ptxt");
si[i++] = gsitm("N5100304T0002N00ENG.html", "When the A/C switch assembly receives a switch indicator signal, it illuminates the indicator light on the ventilated seat switch.", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N510030250001300ENG.html", "Ventilated seat equips fail-safe function.", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "When a malfunction occurs in the systems shown below, ventilated seat performs fail-safe control.", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "Malfunction condition", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "Reset condition", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "Foreign objects get caught in the fan", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "The operation of the seat ventilation is restarted after a temporary stop. If the temporary stop is repeated several times in a row, the operation of the seat ventilation is interrupted.", "ptxt");
si[i++] = gsitm("N510030250001300ENG.html", "Ignition switch ON", "ptxt");
