si[i++] = gsitm("N510030700000L00ENG.html", ">>A&lt;&lt; FRONT SEAT ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000L00ENG.html", "Tilt the front seat assembly backward, and connect the harness connector under the seat.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Insert the seat pins to holes of the body securely.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Confirm that both the seat slides are locked, and then temporarily tighten the front side bolts so that no load is applied to the seat cushion.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Tighten the front inner side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Tightening torque: 40 ± 6 N·m", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Tighten the front outer side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Move the seat forward.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Confirm that both the seat slides are locked, and then temporarily tighten the rear side bolts so that no load is applied to the seat cushion.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Tighten the rear outer side bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000L00ENG.html", "Tighten the rear inner side bolt to the specified torque.", "ptxt");
