si[i++] = gsitm("N5100302W0001T00ENG.html", "Seat cushion heater harness connector (terminal No.4) - seatback heater harness connector (cushion heater side) (terminal No.2)", "ptxt");
si[i++] = gsitm("N5100302W0001T00ENG.html", "If a defect is found, replace the seat cushion pad.", "ptxt");
