si[i++] = gsitm("N5100301S0003H00ENG.html", "DISASSEMBLY AND ASSEMBLY", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Before disassembly and assembly the front seat assembly, refer to .", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Note how the part is installed for reference during assembly.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent accidental explosion, always place the front side air bag module with deploying direction facing upward.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent damage to the parts, never impact the front side air bag module.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Replace the front side air bag module if it is dropped or sustains an impact.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent accidental explosion, never insert any foreign objects (screwdriver, etc.) into the front side air bag module.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent accidental explosion, never disassemble the front side air bag module.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent accidental explosion, never expose the front side air bag module to temperature of more than 90°C (194°F).", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "To prevent damage to the parts, never allow oil, grease, detergent, or water to come in contact with the front side air bag module.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "When installing the front side air bag, check that the inner cloth (reinforcement cloth) is not caught in bolt hole.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Note the following for front side and center air bag module mounting nuts.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Always use new fixing nuts (prevents the nut from loosening).", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Never tighten nuts twice (prevents improper torque).", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Before perform separating operation, check the installed position of hog rings.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "When removing, always use a remover tool that is made of plastic to prevent damage to the parts.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "For hog ring that is removed or crimped unsuccessfully, fix it by using a new hog ring. (Never reuse hog ring.)", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Always install the hog rings in position.", "ptxt");
