si[i++] = gsitm("N5100301S0003H00ENG.html", "Remove the Headrest holders while pushing the on both sides inward.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "&lt;&lt;B>> RIVETS REMOVAL", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Using a drill, grind the rivet to the dotted line and break it.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "ASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", ">>A&lt;&lt; RIVETS INSTALLATION", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Use a rivet tool shown as in the illustration to connect the parts with rivets by the following procedures:", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Insert the rivet into a corresponding location.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Set the rivet tool at a portion A of rivet.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "While pushing the flange surface of the rivet onto parts to be fixed with the rivet tool, press the handle of the tool.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Thin part of portion A of the rivet will be cut off and the part is fixed in position.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", ">>B&lt;&lt; SEATBACK FRAME/FRONT SIDE AIR BAG MODULE / FRONT SEAT NUT INSTALLATION", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Replace the front seat nut and the seatback frame with new ones.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Do not reuse the seatback frame and the front seat nut because the fastening force may be reduced.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Temporarily tighten front seat nuts.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "First tighten the lower front seat nut to the specified torque, and then tighten the upper front seat nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", "Tightening torque: 5.5 ± 1.1 N·m", "ptxt");
si[i++] = gsitm("N5100301S0003H00ENG.html", ">>C&lt;&lt; SEATBACK SUSPENSION INSTALLATION &lt;VEHICLES WITH MASSAGE FUNCTION>", "title");
si[i++] = gsitm("N5100301S0003H00ENG.html", "When the lumbar unit on the front seat with massage function is replaced, be sure to relearn the driver/passenger seat control unit.", "ptxt");
