si[i++] = gsitm("N5100301S0003I00ENG.html", "&lt;&lt;A>> SEATBACK REMOTE RELEASE LEVER CABLE AND SEATBACK RELEASE CABLE", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the cap on the vehicle rear side of the seatback release cable joint part.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the weight piece.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Move the cap on the vehicle rear side forward to remove the cap on the vehicle front side as shown in the figure.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Pull the strap by the seat cushion to fold down the seat back. Then remove the joint piece.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the joint piece by passing the cable through the slit of the joint piece.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "&lt;&lt;B>> HEADREST HOLDER REMOVAL", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the clips shown by the arrows in the figure and remove the cup holder from the armrest assembly.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the second seat headrestraint guide.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "REASSEMBLY SERVICE POINTS", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", ">>A&lt;&lt; SEATBACK RELEASE LEVER FINISHER/SEATBACK PAD/SEATBACK TRIM/HOG RING INSTALLATION", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Install the seatback pad, the seatback trim and the hog ring. Then install the seatback release lever finisher.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", ">>B&lt;&lt; SEATBACK RELEASE LEVER INSTALLATION", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", "After the seatback trim is installed, install the seatback release lever knob to clip the seatback trim and the seatback release lever finisher.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", ">>C&lt;&lt; SEATBACK REMOTE RELEASE LEVER CABLE AND SEATBACK RELEASE CABLE CONNECTION", "title");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Lift the stopper and lock the joint piece. Before connection in step 2, in order to confirm that the joint piece is locked, push the joint piece by a finger to the direction of the arrow and check that it cannot be pushed in.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Push the cable into the joint piece as shown in the figure.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "If the stopper is accidentally pressed first and the joint piece got inside, pull out the joint piece according to the procedure below.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Remove the cap at the front of the vehicle.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Pull out the joint piece toward the front side of the vehicle.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "If the cable of the joint piece is pulled toward the seatback remote release lever side and cannot be pulled out, release the cable fixing part on the seatback remote release lever side, and press in the cable from the seatback remote release lever side as shown in the figure.", "ptxt");
si[i++] = gsitm("N5100301S0003I00ENG.html", "Push the stopper.", "ptxt");
