si[i++] = gsitm("N510030700000N00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N510030700000N00ENG.html", ">>A&lt;&lt; SEATBACK STRIKER INSTALLATION", "title");
si[i++] = gsitm("N510030700000N00ENG.html", "Check that the seatback turns smoothly and locks securely.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", ">>B&lt;&lt; SECOND SEAT FOLDING SHAFT ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000N00ENG.html", "Secure each body harness to the harness fixing bracket.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", ">>C&lt;&lt; SEATBACK ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000N00ENG.html", "Install the second seatback assembly as shown in the figure.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Hook the claws of the hinge bracket into the seat holes.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Tighten the bolts securely according to the order shown in the figure.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", ">>D&lt;&lt; SEATBACK REMOTE RELEASE LEVER CABLE AND SEATBACK RELEASE CABLE CONNECTION INSTALLATION", "title");
si[i++] = gsitm("N510030700000N00ENG.html", "Pass the seat-side cable through the vehicle outer side of the center belt anchor.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Do not let the seat-side cable and the body harness cross each other.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Install according to the procedure below.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Pass the seat-side cable through the underside of the pipe and connect it to the release lever-side cable. (Refer to , ).", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Slide the pin which prevents the falling off of the stopper.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Press in the stopper securely.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Insert the cable joint to the bracket.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", ">>E&lt;&lt; SEAT CUSHION ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000N00ENG.html", "Twist the seat belt buckle a half turn to the direction of the arrow.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Pass the belt through the slit of the cushion and put the seat belt buckle in the pocket.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Be careful not to get the wiring harness caught at this time.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Pass the rear end of the cushion pad between the hinge pipe and the seatback.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "Engage the seat cushion assembly into the rear seat hook securely. On completion, ensure that the assembly engages securely by pulling it up.", "ptxt");
si[i++] = gsitm("N510030700000N00ENG.html", "After installing the second seat cushion assembly, make sure that the pocket of the second seat cushion assembly is not crushed by the center seat belt buckle, and if it is crushed, pull it up.", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "INSPECTION", "title");
