si[i++] = gsitm("N5100302W0001V00ENG.html", "Disassemble the second seat (Refer to ).", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "Disconnect the seatback heater connector, and measure at the seatback heater side.", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "Measure the resistance between the terminals.", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "Check condition: At room temperature 23°C", "ptxt");
