si[i++] = gsitm("N5100302W0001V00ENG.html", "If a defect is found, replace the seatback pad.", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "SEAT CUSHION HEATER CHECK", "title");
si[i++] = gsitm("N5100302W0001V00ENG.html", "Disconnect the seat cushion heater connector and seatback heater connector, and measure at the seat cushion heater side.", "ptxt");
si[i++] = gsitm("N5100302W0001V00ENG.html", "Seat cushion heater connector (terminal No.4) - Seatback heater connector (cushion heater side) (terminal No.2)", "ptxt");
