si[i++] = gsitm("N5100301S0003J00ENG.html", "Slightly tilt the clip as shown in the figure and pull out the clip while taking care not to damage the seat cushion pad.", "ptxt");
si[i++] = gsitm("N5100301S0003J00ENG.html", "&lt;&lt;B>> SEAT CUSHION PAD REMOVAL", "title");
si[i++] = gsitm("N5100301S0003J00ENG.html", "When the clip is removed, be careful to avoid damage to it.", "ptxt");
si[i++] = gsitm("N5100301S0003J00ENG.html", "&lt;&lt;C>> SECOND SEAT LATCH COVER REMOVAL", "title");
si[i++] = gsitm("N5100301S0003J00ENG.html", "Remove the clips shown in the figure using special tool MB990784.", "ptxt");
si[i++] = gsitm("N5100301S0003J00ENG.html", "&lt;&lt;D>> HEADREST HOLDER REMOVAL", "title");
si[i++] = gsitm("N5100301S0003J00ENG.html", "Remove the headrestraint guides while pushing the claws on both sides inward.", "ptxt");
si[i++] = gsitm("N5100301S0003J00ENG.html", "&lt;&lt;E>> SEATBACK RELEASE LEVER FINISHER REMOVAL", "title");
si[i++] = gsitm("N5100301S0003J00ENG.html", "Insert a flat-tipped screwdriver into the position shown in the figure, and remove the seatback release lever finisher.", "ptxt");
