si[i++] = gsitm("N510030700000O00ENG.html", "&lt;&lt;A>> THIRD SEAT ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N510030700000O00ENG.html", "Before removing the bolts fixing the third seat, be sure to lift the rear side of the third seat. If you fail to do so, the seat may jump up when the bolts are removed and it may cause injury.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Pull the strap on the rear side of the seat to lift the rear side of the seat as shown in the figure.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Remove the mounting bolts on the front side of the seat.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N510030700000O00ENG.html", ">>A&lt;&lt; THIRD SEAT STRIKER/THIRD SEAT ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000O00ENG.html", "Install the striker in the procedure shown in the figure.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Tightening torque: 45 ± 7 N·m", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Insert the pin of the seat securely into the body hole shown as figure.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Temporarily tighten the mounting bolts on the front side, taking care not to apply load to the seat cushion.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Check that the seat is locked securely to the striker.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Raise the seat back.", "ptxt");
si[i++] = gsitm("N510030700000O00ENG.html", "Tighten the mounting bolts on the front side to the specified torque.", "ptxt");
