si[i++] = gsitm("N510030700000W01ENG.html", "&lt;&lt;A>> THIRD SEAT ASSEMBLY/STRIKER REMOVAL", "title");
si[i++] = gsitm("N510030700000W01ENG.html", "Remove the springs of the third seat assembly by the following procedures.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tip the third seat assembly backward, and pull out the slit of the left and right felts from the portion A shown in the illustration.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "While the third seat assembly is tipped backward, release the inner springs on the left and right side of the third seat assembly as shown in the illustration.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Return the third seat assembly to its original position and fold the seatback assembly forward, then release the outer springs on the left and right side of the third seat assembly as shown in the illustration.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Remove the third seat assembly.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N510030700000W01ENG.html", ">>A&lt;&lt; STRIKER/THIRD SEAT ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N510030700000W01ENG.html", "Tighten the striker mounting bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tightening torque: 21 ± 4 N·m", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Push portions B at the same time and securely lock the third seat assembly to the striker.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Surely insert the hinge bracket of the third seat into the stud bolt of the body and tighten the nut to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tightening torque: 30 ± 5 N·m", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tighten the front mounting bolt of the third seat hinge bracket to the specified torque.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tightening torque: 43 ± 8 N·m", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Installation the springs of the third seat assembly by the following procedures.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Fold the seatback assembly forward, and install the outer springs on the left and right side of the third seat assembly as shown in the illustration. Then, set the inner springs on the left and right side of the third seat assembly to the portion B shown in the illustration.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Tip the third seat assembly backward, and install the inner springs on the left side of the third seat assembly.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Hook the slit of the left and right side felts on the portion A as shown in the illustration.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "After installing the cargo floor box lid B and cargo floor cover, check the lock ability by the following steps. (Refer to )", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Check that the latch part of the third seat assembly is locked. If not, lock it.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Check that the latch part can be unlocked with the strap C. Do not relock the latch part after releasing the strap C.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Pull the strap D to raise the third seat assembly and lock it again after it is upright.", "ptxt");
si[i++] = gsitm("N510030700000W01ENG.html", "Check that the third seat assembly is securely locked.", "ptxt");
