si[i++] = gsitm("N5100405K0000N00ENG.html", "Driver Seat Control Unit", "title");
si[i++] = gsitm("N5100405K0000N00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Main units of automatic drive positioner system.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Driver seat control unit controls manual function, memory function, entry/exit assist function, log-in function (with navigation system), Keyless operation key inter lock function and massage function of automatic drive positioner system.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Driver seat control unit communicates with each control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Requests the operation of door mirror to BCM.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "The address of each part is recorded.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Operates each motor of seat to the registered position.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Operates the specific seat motor with the signal from power seat switch, lumbar support switch and massage switch.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Driver seat control unit communicates each control unit via CAN communication system and receives / transmits the required signals to control.", "ptxt");
si[i++] = gsitm("N5100405K0000N00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5100405K0000N00ENG.html", "Driver seat control unit is installed in back side of seat cushion. Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "PASSENGER SEAT CONTROL UNIT", "title");
si[i++] = gsitm("N510045120000K00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510045120000K00ENG.html", "Main units of automatic drive positioner system.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "Passenger seat control unit controls manual function, memory function and massage function of automatic drive positioner system.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510045120000K00ENG.html", "Passenger seat control unit communicates with each control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "The address of each part is recorded.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "Operates each motor of seat to the registered position.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "Operates the specific seat motor with the signal from power seat switch, lumbar support switch and massage switch.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510045120000K00ENG.html", "Passenger seat control unit communicates each control unit via CAN communication system and receives / transmits the required signals to control.", "ptxt");
si[i++] = gsitm("N510045120000K00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510045120000K00ENG.html", "Passenger seat control unit is installed in back side of seat cushion. Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Seat Memory Switch", "title");
si[i++] = gsitm("N5100405L0000O00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Set switch: It is used for registration and setting change of driving position.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Memory switch: The maximum 2 driving positions can be registered by memory switch 1 to 2.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Memory indicator: Memory indicator indicates the status of auto driving position system by turning ON or blinking.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Set switch: When set switch pressed, transmits set switch signal to seat control unit.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Memory switch: When memory switch 1 or 2 pressed, transmits memory switch 1 or 2 signal to seat control unit.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Memory indicator: Perform controls with the instructions of seat control unit.", "ptxt");
si[i++] = gsitm("N5100405L0000O00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5100405L0000O00ENG.html", "Seat memory switch is installed front door finisher. Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "LUMBAR SUPPORT SWITCH", "title");
si[i++] = gsitm("N510045300000F00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510045300000F00ENG.html", "The seatback support can be adjusted by operating the lumbar support switch.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "The lumbar support switch inputs the operation status of the switch to the seat control unit.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510045300000F00ENG.html", "Detects lumbar support switch operation.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510045300000F00ENG.html", "The lumbar support switch is composed of a combination of a switch and a resistor.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "When each switch is pressed, the voltage from the seat control unit changes according to the resistance value set for each switch, and the seat control unit reads which switch is operated.", "ptxt");
si[i++] = gsitm("N510045300000F00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510045300000F00ENG.html", "Lumbar support switch is installed to the front seat cushion finisher. Refer to .", "ptxt");
si[i++] = gsitm("N510045130000J00ENG.html", "MASSAGE SWITCH", "title");
si[i++] = gsitm("N510045130000J00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510045130000J00ENG.html", "The massage function can be turned ON/OFF by operating the massage switch.", "ptxt");
si[i++] = gsitm("N510045130000J00ENG.html", "The massage switch inputs the operation status of the switch to the seat control unit.", "ptxt");
si[i++] = gsitm("N510045130000J00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510045130000J00ENG.html", "Detects massage switch operation.", "ptxt");
si[i++] = gsitm("N510045130000J00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510045130000J00ENG.html", "Converts switch operations into ON/OFF signals.", "ptxt");
si[i++] = gsitm("N510045130000J00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510045130000J00ENG.html", "Massage switch is installed to the front seat cushion finisher. Refer to .", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "LUMBAR SUPPORT (FORWARD / BACKWARD) MOTOR", "title");
si[i++] = gsitm("N510045140000H00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510045140000H00ENG.html", "The lumbar support (forward / backward) motor is controlled by the seat control unit and adjusts the seatback support.", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "The lumbar support (forward / backward) motor inputs the position of the seatback support to the seat control unit by the built-in sensor.", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510045140000H00ENG.html", "The seatback support is adjusted by changing the direction of rotation of the motor.", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "The position of the motor is detected by the built-in sensor.", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510045140000H00ENG.html", "The rotation direction of the motor is changed according to the input drive signal, the winding amount of the wire is adjusted, and the seatback supports (zones 2 and 4) are adjusted.", "ptxt");
si[i++] = gsitm("N510045140000H00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510045140000H00ENG.html", "The lumbar support (forward / backward) motor is installed to the seatback frame. Refer to .", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "LUMBAR SUPPORT (UPWARD / DOWNWARD) MOTOR", "title");
si[i++] = gsitm("N510045150000H00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N510045150000H00ENG.html", "The lumbar support (upward / downward) motor is controlled by the seat control unit and adjusts the seatback support.", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "The lumbar support (upward / downward) motor inputs the position of the seatback support to the seat control unit by the built-in sensor.", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N510045150000H00ENG.html", "The seatback support is adjusted by changing the direction of rotation of the motor.", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "The position of the motor is detected by the built-in sensor.", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N510045150000H00ENG.html", "The rotation direction of the motor is changed according to the input drive signal, the winding amount of the wire is adjusted, and the seatback supports (zones 1 and 3) are adjusted.", "ptxt");
si[i++] = gsitm("N510045150000H00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N510045150000H00ENG.html", "The lumbar support (upward / downward) motor is installed to the seatback frame. Refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "System Description", "title");
si[i++] = gsitm("N5100404N0006N00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5100404N0006N00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Automatic drive positioner system is a system that adjusts the seat and door mirrors.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "By using the following functions, an optimum driving position can be achieved. If another driver is seated in the driver seat, the driving position can be easily changed to the preset driving position.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Manual function", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "The driving position (seat and door mirror position) can be adjusted by using the power seat switch, lumbar support switch or door mirror remote control switch.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on manual function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Memory function", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "The seat and door mirror move to the stored driving position by pressing seat memory switch (1 or 2).", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For models with navigation system, the seat position set with the seat memory switch cannot be operated interlocked with the Keyless operation key.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on memory function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Entry/exit assist function*", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Exit", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "On exit, the seat moves backward.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on exit assist function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Entry", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "On entry, the seat returns from exiting position to the previous driving position.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on entry assist function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Log-in function (with navigation system)*", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "The driving position can be registered and retrieved for each Keyless operation key.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on log-in function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Keyless operation key interlock function*", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "With navigation system", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "When Keyless operation key interlock function performs the following function, it causes the exit assist function to operate.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Unlock door: Keyless operation key", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Unlock door: Front door request switch (front door LH)", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Registered information of the driving position is retrieved from the memory registered to the driver seat control unit by the log-in function.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "For details on Keyless operation key interlock function, refer to .", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Without navigation system", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Perform memory operation, exiting operation and entry operation by Keyless operation key unlock operation or front door request switch (front door LH) unlock operation.", "ptxt");
si[i++] = gsitm("N5100404N0006N00ENG.html", "Massage function", "ptxt");
