si[i++] = gsitm("N5100404N0006O00ENG.html", "Automatic drive positioner system is a system that adjusts the seat and door mirrors.", "ptxt");
si[i++] = gsitm("N5100404N0006O00ENG.html", "By using the following functions, an optimum driving position can be achieved. If another driver is seated in the driver seat, the driving position can be easily changed to the preset driving position.", "ptxt");
