si[i++] = gsitm("N5100404N0006R00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100404N0006R00ENG.html", "The seat control unit can store the optimum driving positions (seat and door mirror position) for 2 people. If the front seat position is changed, one-touch (pressing desired memory switch) operation allows changing to the other driving position.", "ptxt");
si[i++] = gsitm("N5100404N0006R00ENG.html", "Further information for the memory storing procedure. Refer to .", "ptxt");
