si[i++] = gsitm("N5100404N0006S00ENG.html", "The memory switch signal is inputted to the seat control unit when memory switch 1 or 2 is operated.", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Motors", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "(Seat, door mirror)", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Seat control unit operates each motor of seat when it recognizes the memory switch pressed for 0.5 second or more and requests each motor operation to BCM via CAN communication. The BCM transmits mirror control signal to power window main switch and passenger door mirror control module via LIN communication and actuates each motor according to the operation of the door mirror remote control switch.", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Memory switch Indicator", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Seat control unit requests the flashing of memory indicator while either of the motors is operating. The seat control unit illuminates the memory indicator.", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Sensors", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Seat control unit judges the operating seat position with each seat sensor input. The positions of the door mirror is monitored with mirror sensor signal. Seat control unit stops the operation of each motor when each part reaches the recorded address.", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "4", "ptxt");
si[i++] = gsitm("N5100404N0006S00ENG.html", "Seat control unit requests the illumination of memory indicator after all motors stop. The seat control unit illuminates the memory indicator for 5 seconds.", "ptxt");
