si[i++] = gsitm("N5100404N0006W00ENG.html", "This function allows the driver side seat to return from the exiting position to the position before the exiting function is operated when the ignition switch is operated from OFF to ON when the driver enters the vehicle.", "ptxt");
si[i++] = gsitm("N5100404N0006W00ENG.html", "If the ignition switch is operated with any Keyless operation key other than that used before the exiting function is operated, the driver side seat will return to the driver position registered for that Keyless operation key.", "ptxt");
si[i++] = gsitm("N5100404N0006W00ENG.html", "This function is set to ON before delivery (initial setting).", "ptxt");
si[i++] = gsitm("N5100404N0006W00ENG.html", "Further information for the system setting procedure. Refer to .", "ptxt");
