si[i++] = gsitm("N5100404N0006X00ENG.html", "Log-in function is the function that registers the setting status of various systems and retrieves the status for each Keyless operation key as desired.", "ptxt");
si[i++] = gsitm("N5100404N0006X00ENG.html", "Registered information is automatically adjusted to the driving position (seat and door mirror position) registered by unlocking the driver side door with the Keyless operation key (Keyless operation key interlock function) or by operating the user selection function on the display.", "ptxt");
si[i++] = gsitm("N5100404N0006X00ENG.html", "When user selection is performed by display operation, the user information registered with another Keyless operation key can also be retrieved.", "ptxt");
si[i++] = gsitm("N5100404N0006X00ENG.html", "For details on Keyless operation key interlock function: Refer to  &lt;Vehicle with navigation system> or  &lt;Vehicle without navigation system>.", "ptxt");
si[i++] = gsitm("N5100404N0006X00ENG.html", "For the registration of the log-in function, the status is automatically registered as one of the following vehicle statuses when the ignition switch is turned to OFF.", "ptxt");
