si[i++] = gsitm("N5100404N0007Q00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "When ignition switch is OFF, and door unlock operation is performed using Keyless operation key or driver side door request switch, driver seat automatically adjusts to a driving position other than seat sliding. Seat sliding perform return operation and are set to standby status.", "ptxt");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "In standby status, when ignition switch is operated from OFF to ON, return operation sets seat sliding to a registered position.", "ptxt");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "When ignition switch signal turns ON during return operation, the operation is interrupted, ignition switch signal turns from ON to OFF, and operation restarts.", "ptxt");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "Operation Procedure", "title");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "Unlock driver door by Keyless operation key, front door request switch.", "ptxt");
si[i++] = gsitm("N5100404N0007Q00ENG.html", "Operation other than memory of seat sliding is performed. Seat sliding perform exit assist operation.", "ptxt");
