si[i++] = gsitm("N5100404N0007R00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5100404N0007R00ENG.html", "By associating Keyless operation key and automatic drive positioner system, the unlock operation of Keyless operation key or driver side door request switch performs memory function and entry/exit assist function.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Registration of Keyless operation key interlock function can register a different key ID to the driver seat control unit, one by one, for memory switch 1 and 2. A total of 2 key IDs can be registered.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "When ignition switch is OFF, and door unlock operation is performed using Keyless operation key or driver side door request switch, driver seat automatically adjusts to a driving position other than seat sliding. Seat sliding perform return operation and are set to standby status.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "In standby status, when ignition switch is operated from OFF to ON, return operation sets seat sliding to a registered position.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "When another key ID is newly registered to a key switch to which a key ID is already registered, the previously registered key ID is overwritten and becomes unusable.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "When ignition switch signal turns ON during return operation, the operation is interrupted, ignition switch signal turns from ON to OFF, and operation restarts.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Further information for the Keyless operation key interlock storing procedure. Refer to .", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Operation Procedure", "title");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Unlock driver door by Keyless operation key, front door request switch.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Operation other than memory function of seat sliding is performed. Seat sliding perform exit assist operation.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5100404N0007R00ENG.html", "Driver seat will return from the exiting position to entry position.", "ptxt");
