si[i++] = gsitm("N5100405Q0000N00ENG.html", "The seat control unit transmits a memory guidance display request signal (guidance display) to the combination meter for 5 seconds via CAN communication when the set switch is pressed.", "ptxt");
si[i++] = gsitm("N5100405Q0000N00ENG.html", "Combination meter displays the guidance (display pattern A) in the information display when it receives the memory guidance display request signal (guidance display) when the ignition switch is ON.", "ptxt");
si[i++] = gsitm("N5100405Q0000N00ENG.html", "When press memory switch-1 within 5 seconds after pressing set switch, seat control unit registered driving position to memory 1 and transmits memory guidance display request signal (memory 1 registration completion display) to the combination meter for 5 seconds via CAN communication.", "ptxt");
si[i++] = gsitm("N5100405Q0000N00ENG.html", "Combination meter displays the memory 1 registration completed (display pattern B) in the information display when it receives the memory guidance display request signal (memory 1 registration completion display) when the ignition switch is ON.", "ptxt");
si[i++] = gsitm("N5100405Q0000N00ENG.html", "When press memory switch-2 within 5 seconds after pressing set switch, seat control unit registered driving position to memory 2 and transmits memory guidance display request signal (memory 2 registration completion display) to the combination meter for 5 seconds via CAN communication.", "ptxt");
si[i++] = gsitm("N5100405Q0000N00ENG.html", "Combination meter displays the memory 2 registration completed (display pattern C) in the information display when it receives the memory guidance display request signal (memory 2 registration completion display) when the ignition switch is ON.", "ptxt");
