si[i++] = gsitm("N510040570000C00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N510040570000C00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
