si[i++] = gsitm("N510040590002K00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N510040590002K00ENG.html", "Memory Storage Procedure", "title");
si[i++] = gsitm("N510040590002K00ENG.html", "Two positions for the seat and outside mirror can be stored for memory operation by following procedure.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Memory registration can be performed with no restrictions of the shift position, vehicle speed, and ignition switch position.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "REGISTRATION METHOD", "title");
si[i++] = gsitm("N510040590002K00ENG.html", "Adjust driver seat and outside mirror position manually.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Push set switch.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Memory indicator for which seat position is already retained in memory is illuminated for 5 seconds.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Memory indicator for which seat position is not retained in memory is illuminated for 0.5 second.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Push the memory switch (1 or 2) for at least 1 second within 5 seconds after pushing the set switch.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "When registration is performed correctly, the memory indicator blinks for 5 seconds and a warning buzzer sounds.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "If memory is stored in the same memory switch, the previous memory will be deleted.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "Confirm the operation of each part with memory operation.", "ptxt");
si[i++] = gsitm("N510040590002K00ENG.html", "END", "ptxt");
si[i++] = gsitm("N5100401D0003T00ENG.html", "Description", "title");
si[i++] = gsitm("N5100401D0003T00ENG.html", "Always perform the Keyless operation key interlock function storage when the driver seat control unit is replaced. The Keyless operation key interlock function will not operate normally if no memory storage is performed. For details, refer to .", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N510040590000Z00ENG.html", "Keyless operation key Interlock Storage Procedure", "title");
si[i++] = gsitm("N510040590000Z00ENG.html", "Performing the following operation associates the registered driving position with Keyless operation key. When driver door unlock operation is performed by Keyless operation key or driver door request switch, display of the registered driving position and turnout operation can be performed.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "STEP 1", "title");
si[i++] = gsitm("N510040590000Z00ENG.html", "Check the following conditions.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "Ignition switch : OFF", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "Driving position : Registered", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "All door: Locked", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "STEP 2", "title");
si[i++] = gsitm("N510040590000Z00ENG.html", "Push set switch.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "Memory indicator for which driver seat position is already retained in memory is illuminated for 5 seconds.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "Push the Keyless operation key unlock button within 5 seconds after pushing memory switch (while the memory indicator is turned ON).", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "From the time registration is performed, the applicable memory indicator blinks for 5 seconds.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "STEP 3", "title");
si[i++] = gsitm("N510040590000Z00ENG.html", "Confirm the operation of each part with memory operation and Keyless operation key interlock operation.", "ptxt");
si[i++] = gsitm("N510040590000Z00ENG.html", "END", "ptxt");
si[i++] = gsitm("N5100401D0001Z00ENG.html", "Description", "title");
