si[i++] = gsitm("N5110103M0000U00ENG.html", "Hands Free Sensor", "title");
si[i++] = gsitm("N5110103M0000U00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5110103M0000U00ENG.html", "When the user performs a kick motion toward rear bumper while carrying Keyless operation key as shown in the figure, hands free sensor (upper side) detects shin motion of leg and hands free sensor (lower side) detects instep motion of foot. This varies the voltage waveform of hands free sensor. Hands free sensor control unit judges user operation by detecting the voltage change of hands free sensor.", "ptxt");
si[i++] = gsitm("N5110103M0000U00ENG.html", "Voltage generated in communication circuit between hands free sensor and hands free sensor control unit is extremely low and therefore cannot be measured.", "ptxt");
si[i++] = gsitm("N5110103M0000U00ENG.html", "It is necessary to perform hands free within space as shown in the figure for activating the hands free sensor completely. The detection area may differ depending on the conditions of the surroundings.", "ptxt");
si[i++] = gsitm("N5110103M0000U00ENG.html", "Keyless operation key must be carried for starting the operation of the power liftgate open/close function by hands free sensor operation (hands free function) with the liftgate stopped. Keyless operation key does not need to be carried when stopping the liftgate operation during power liftgate open/close operation (power open/close temporary stop function).", "ptxt");
si[i++] = gsitm("N5110103M0000U00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5110103M0000U00ENG.html", "The hands free sensor converts the approaching of feet to voltage and transmits it to the hands free sensor control unit.", "ptxt");
si[i++] = gsitm("N5110103M0000U00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5110103M0000U00ENG.html", "Hands free sensor (upper side)  and hands free sensor (lower side)  are installed in the rear bumper fascia.", "ptxt");
si[i++] = gsitm("N5110103N0000U00ENG.html", "Hands Free Sensor Control Unit", "title");
si[i++] = gsitm("N5110103N0000U00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5110103N0000U00ENG.html", "Only when hands free sensor (upper side) and hands free sensor (lower side) simultaneously detect that feet approach the sensors will the operation permission of the auto open/close function of the liftgate be judged.", "ptxt");
si[i++] = gsitm("N5110103N0000U00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5110103N0000U00ENG.html", "Hands free sensor control unit judges user operation by detecting the voltage waveform change of hands free sensor (upper side) and hands free sensor (lower side). The hands free sensor control unit then transmits the power liftgate operation request signal to BCM via serial communication.", "ptxt");
si[i++] = gsitm("N5110103N0000U00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5110103N0000U00ENG.html", "Hands free sensor control unit is installed in the rear bumper fascia. Refer to .", "ptxt");
