si[i++] = gsitm("N5110103R0000T00ENG.html", "The outside key antenna detection area is in the range of approximately 0.7 m (27.56 in) surrounding the door request switch (front door and rear door)  and liftgate request switch . However, this operating range depends on the ambient conditions.", "ptxt");
