si[i++] = gsitm("N5110103S0000T00ENG.html", "Encoder: Power liftgate control unit receives the pulse signals from encoders A and B that occurred due to synchronization with the liftgate operation. The power liftgate control unit calculates the liftgate position, operation direction, and operation speed according to the received pulse signals.", "ptxt");
