si[i++] = gsitm("N5110102T0007Q00ENG.html", "Transmit shift position signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM detects the vehicle status according to signals from each door switch.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM receives door lock/unlock switch signal from door lock/unlock switch, and then operate door lock actuator.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "TCU", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Transmit door lock/unlock signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Air bag diagnosis sensor unit", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Transmit vehicle collision information signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "DOOR LOCK FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Door Lock/Unlock Switch", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Interlocked with the locking operation of door lock/unlock switch, door lock actuator of all doors and fuel filler lid lock actuator are locked.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Interlocked with the unlocking operation of door lock/unlock switch, door lock actuator of all doors and fuel filler lid lock actuator are unlocked.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "INTERIOR ROOM LIGHT CONTROL FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Interior room light is controlled according to door lock /unlock state, refer to .", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "IMPACT DETECTION TYPE AUTO DOOR UNLOCK FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "When the air bag diagnosis sensor unit detects a strong impact on the vehicle body with the ignition switch ON, it transmits the vehicle collision information signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "When BCM detects an impact status signal from the air bag diagnosis sensor unit, it unlocks all doors.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "AUTOMATIC DOOR LOCK/UNLOCK FUNCTION (LOCK OPERATION)", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "The interlock door lock function is the function that locks all doors linked with the vehicle speed or shift position. It has 2 types as per the following items.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Vehicle Speed Sensing Auto Door Lock", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "All doors are locked when the vehicle speed reaches 15 km/h or more.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM outputs the lock signal to all door lock actuators when it detects all doors are closed and the vehicle speed received from the ABS actuator and electric unit (control unit) via CAN communication becomes 15 km/h or more.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Setting Change of Automatic Door Lock Function", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "The setting of the automatic door lock function can be changed by the following operations.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "The setting of the vehicle speed sensing auto door lock can be changed by operating the power window main switch as follows.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Close all the doors.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Turn the ignition switch to the \"ON\" position.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Within 20 seconds after turning the ignition switch to the \"ON\" position, press and hold the lock switch of the power window main switch for five seconds or more.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "When the setting of the vehicle speed sensing auto door lock is changed to ON, the hazard warning light flashes twice. When the setting is changed to OFF, the hazard warning light flashes once.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "AUTOMATIC DOOR LOCK/UNLOCK FUNCTION (UNLOCK OPERATION)", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "The automatic door lock/unlock function is the function that unlocks all doors linked with the key position or shift position. It has 2 types as per the following items.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "IGN OFF Interlock Door Unlock", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "All doors are unlocked when the ignition position is changed from ON to OFF.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM outputs the unlock signal to all door lock actuators when it detects that the ignition position is changed from ignition switch ON to OFF.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "P Range Interlock Door Unlock", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "All doors are unlocked when shifting the selector lever from any position other than the P to P position.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM outputs the unlock signal to all door lock actuators when it detects the shift position signal received from TCM via CAN communication is shifted from any position other than the P to P position.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Setting Change of Automatic Door Unlock Function", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "The unlock operation setting of the automatic door unlock function can be changed by combination meter setting.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "REAR SEAT ALERT WARNING", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "It is a function to prevent mislay of luggage in the rear seat when getting off, by setting the function with the combination meter in advance when getting on.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Operation condition", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "When all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Setting", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Condition", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Alert only", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Rear door: open → close", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Driver door: open → close", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Select \"Alert only\" of combination meter setting", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Vehicle: running → stop", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Shift position: P position", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Alert & horn", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Select \"Alert & horn\" of combination meter setting", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "Driver door: 8 seconds after open → close the horn operates", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "TELEMATICS LOCK/UNLOCK FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM outputs the lock signal to all door lock actuators when it detects the door lock signal received from TCU via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Q00ENG.html", "BCM outputs the unlock signal to driver/all door lock actuators (selective unlock function operation) when it detects the door unlock signal received from TCU via CAN communication.", "ptxt");
