si[i++] = gsitm("N5110102T0007R00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Transmits vehicle speed signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "BCM detects the vehicle status according to signals from each door switch.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "BCM transmits drive signal to door lock actuator when BCM receives door lock unlock request signal from Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Keyless operation key unit detects the vehicle status according to signals from each outside key antenna/inside key antenna", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Power liftgate control unit", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Keyless operation key", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Operates based on the results of electronic ID verification using two-way communication between the Keyless operation key and the vehicle (Keyless operation key unit)", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The Keyless operation key system is a system that makes it possible to lock and unlock the door locks (door lock/unlock function) by carrying the Keyless operation key, which operates based on the results of electronic ID verification using two-way communication between the Keyless operation key and the vehicle (Keyless operation key unit).", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The driver should always carry the Keyless operation key", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The settings for each function can be changed with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "If an Keyless operation key is lost, a new Keyless operation key can be registered. A maximum of 4 Keyless Operation Keys can be registered.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "It is possible to perform a diagnosis on the system and register an Keyless operation key with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Refer", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Door lock*", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Lock/unlock can be performed by pressing the door request switch.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Liftgate open", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The liftgate can be opened by carrying the Keyless operation key and pressing the liftgate opener switch.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Remote keyless entry", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Lock/unlock can be performed by pressing the remote controller button of the Keyless operation key.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Key reminder", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The Keyless operation key reminder buzzer sounds a warning if the door is locked with the key left inside the vehicle.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Warning (information display)", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "If an action that does not meet the operating condition of the Keyless operation key system is taken, the information display displays to inform the driver.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Warning Light/Indicator (Information Display)", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Warning (buzzer)", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "If an action that does not meet the operating condition of the Keyless operation key system is taken, the buzzer sounds to inform the driver.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Engine start", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "The engine can be turned on while carrying the Keyless operation key.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Interior room light control", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Interior room light is controlled according to door lock/unlock state.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Signature light", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Parking, license plate and tail lamps are controlled according to door lock/unlock state.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Automatic drive positioner", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "Setting of auto driving position can be automatically set, according to key ID of Keyless operation key, to the setting value that is registered in advance.", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "&lt;LHD>,  &lt;RHD>", "ptxt");
si[i++] = gsitm("N5110102T0007R00ENG.html", "*: With request switch models", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5110101K0002W00ENG.html", "Display contents of M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "B2042-4A: Electric shift authentication fail", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "Prohibit shifting the shift selector from P position", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "B2043-4A: Electric shift ID discord", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "B2044-4A: Electric shift ID registration fail", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "B2045-4A: Electric shift ID discord", "ptxt");
si[i++] = gsitm("N5110101K0002W00ENG.html", "B2047-87: Electric shift communication fail", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Door lock function controls operation function of the following items.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Door lock and unlock function (door request switch)", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Selective unlock function (door request switch)", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Reminder function (door request switch)", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Auto door lock function (door request switch)", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "DOOR LOCK AND UNLOCK FUNCTION (DOOR REQUEST SWITCH)", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When pressing the door request switch, it is possible to lock and unlock the door by carrying the Keyless operation key.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Operation Description", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When the Keyless operation key unit detects that each door request switch is pressed, it starts the outside key antenna and inside key antenna corresponding to the pressed door request switch and transmits the request signal to the Keyless operation key. And then, check that the Keyless operation key is near the door.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "If the Keyless operation key is within the outside key antenna detection area, it receives the request signal and transmits the key ID signal to the Keyless operation key unit via remote keyless entry receiver.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key unit receives the key ID signal and compares it with the registered key ID to the vehicle.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "If the verification result is OK, Keyless operation key unit transmits the door lock/unlock request signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "BCM transmits door lock/unlock signal to each door lock actuator and fuel filler lid lock actuator, activates each door lock actuator and fuel filler lid lock actuator when receiving door lock/unlock signal from keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Operation Condition", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "If the following conditions are satisfied, door lock and unlock operation is performed if the door request switch is operated.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Each door request switch operation", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Operation condition", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Lock", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key is outside the vehicle", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "P position warning is not activated", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Selective unlock function is not activated", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key is within outside key antenna detection area*", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "All doors closed", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Unlock", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key is within outside key antenna detection area *", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "*: Even with a registered Keyless operation key remaining inside the vehicle, door lock or unlock can be operated from outside of the vehicle with a spare Keyless operation key as long as key IDs are different.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "SELECTIVE UNLOCK FUNCTION (DOOR REQUEST SWITCH)", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Lock Operation", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When lock signal is sent from door request switch, all doors are locked.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Unlock Operation", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "&lt;Selective unlock function setting is OFF>", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When unlock signal is sent from door request switch, all doors are unlocked.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "The default setting of selective unlock function is OFF.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "&lt;Selective unlock function setting is ON>", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When unlock signal from front door request switch driver side &lt;LHD>, passenger side &lt;RHD> is transmitted, front door LH unlocks. When front door request switch driver side &lt;LHD>, passenger side &lt;RHD> is operated again within 2 seconds, all door unlock.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When unlock signal from front door request switch passenger side &lt;LHD>, driver side &lt;RHD> is transmitted, front door RH unlock. When front door request switch passenger side &lt;LHD>, driver side &lt;RHD> is operated again within 2 seconds, all doors unlocks.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When unlock signal from liftgate request switch is transmitted, liftgate unlock. When liftgate request switch is operated again within 2 seconds, all doors unlocks.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "How to Change Selective Unlock Function Operation Mode", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Selective unlock function operation mode can be changed pushing lock button and unlock button of the keyless operation key at the same time for four seconds.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Selective unlock function operation mode can be changed using combination meter setting.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "REMINDER FUNCTION (DOOR REQUEST SWITCH)", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "When doors are locked or unlocked by door request switch, BCM blinks hazard warning lamps as a reminder or Keyless operation key warning buzzer signal to Keyless operation key unit via CAN communication. Reminder function does not operate if ignition switch in ON position.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Except vehicles for Ukraine", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Vehicles for Ukraine", "ptxt");
