si[i++] = gsitm("N5110102T0007S00ENG.html", "Hazard warning light", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Once", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Twice", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key warning buzzer", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Once*", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "–", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "*: Work support mode [ANSWER BACK] setting is \"On\"", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "AUTO DOOR LOCK FUNCTION (DOOR REQUEST SWITCH)", "title");
si[i++] = gsitm("N5110102T0007S00ENG.html", "After door is unlocked by door request switch operation and if 30 seconds or more passes without performing the following operation, all doors are automatically locked. However, operation check function does not activate.", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Operating condition", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Door switch is ON (each door is open)", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Keyless operation key unit receives door lock signal", "ptxt");
si[i++] = gsitm("N5110102T0007S00ENG.html", "Push switch is pressed", "ptxt");
