si[i++] = gsitm("N5110102T0007S00ENG.html", "The outside key antenna detection area of door lock/unlock function is in the range of approximately 0.7 m (27.56 in) surrounding the door request switch (front door and rear door)  and liftgate request switch . However, this operating range depends on the ambient conditions.", "ptxt");
