si[i++] = gsitm("N5110102T0007T00ENG.html", "Power liftgate OPEN FUNCTION (WITHOUT Power liftgate SYSTEM MODELS)", "title");
si[i++] = gsitm("N5110102T0007T00ENG.html", "When the BCM detects that liftgate opener switch is pressed, then Keyless operation key unit transmits the request signal to the Keyless operation key. And then, check that the Keyless operation key is near the liftgate.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "If the Keyless operation key is within the outside key antenna detection area, it receives the request signal and transmits the key ID signal to the Keyless operation key unit via remote keyless entry receiver.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "Keyless operation key unit receives the key ID signal and compares it with the registered key ID to the vehicle.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "If the verification result is OK, BCM unlock and opens liftgate.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "Power liftgate OPEN FUNCTION (WITH Power liftgate SYSTEM MODELS)", "title");
si[i++] = gsitm("N5110102T0007T00ENG.html", "Keyless operation key unit receives the key ID signal and compares it with the registered key ID.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "If the verification result is OK, Keyless operation key unit transmits the liftgate open request signal to power liftgate control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "Power liftgate control unit transmits liftgate open request signal to liftgate lock assembly and liftgate is open.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "When the liftgate is open, power liftgate system performs waiting operation for next liftgate close operation.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "The operation of then liftgate open is the same as the power liftgate system, refer to .", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5110102T0007T00ENG.html", "If the following conditions are satisfied, the liftgate can be opened.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "Liftgate opener switch operation", "ptxt");
