si[i++] = gsitm("N5110102T0007T00ENG.html", "Keyless operation key is within outside key antenna (rear bumper) detection area*", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "*: Even with a registered Keyless operation key remaining inside the vehicle, liftgate can be opened from outside of the vehicle with a spare Keyless operation key as long as key IDs are different.", "ptxt");
si[i++] = gsitm("N5110102T0007T00ENG.html", "For details liftgate open operation other conditions. Refer to .", "ptxt");
