si[i++] = gsitm("N5110102T0007U00ENG.html", "The Keyless operation key has the same functions as the remote control entry function. Therefore, it can be used in the same manner as the remote controller by operating the door lock/unlock button.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Remote keyless entry function controls operation function of the following items.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Door lock and unlock function (Keyless operation key)", "ptxt");
