si[i++] = gsitm("N5110102T0007U00ENG.html", "DOOR LOCK AND UNLOCK FUNCTION (KEYLESS OPERATION KEY)", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Operation Description", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When door lock/unlock button of the Keyless operation key is pressed, lock signal or unlock signal is transmitted from Keyless operation key to Keyless operation key unit via remote keyless entry receiver.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Keyless operation key unit receives the signal and compares it with the registered key ID to the vehicle.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "If the verification result is OK, Keyless operation key unit transmits the door lock/unlock request signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "BCM transmits door lock/unlock signal to each door lock actuator and fuel filler lid lock actuator, activates each door lock actuator and fuel filler lid lock actuator.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Operation Condition", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "If the following condition is satisfied, door lock and unlock operation is performed if the Keyless operation key button is pressed.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Keyless operation key button operation", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Operation condition", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Lock", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "P position warning is not activated", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "SELECTIVE UNLOCK FUNCTION (KEYLESS OPERATION KEY)", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Lock Operation", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When lock signal is sent from Keyless operation key, all doors are locked.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Unlock Operation", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "&lt;Selective unlock function setting is OFF>", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When unlock signal is sent from door request switch, all doors are unlocked.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "The default setting of selective unlock function is OFF.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "&lt;Selective unlock function setting is ON>", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When unlock signal from Keyless operation key is transmitted, front door (driver side) is unlocked. When unlock signal is transmitted from Keyless operation key within 2 seconds again, all doors are unlocked.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "How to Change Selective Unlock Function Operation Mode", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Selective unlock function operation mode can be changed pushing lock button and unlock button of the keyless operation key at the same time for four seconds.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Selective unlock function operation mode can be changed using combination meter setting.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "REMINDER FUNCTION (KEYLESS OPERATION KEY)", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When doors are locked or unlocked by Keyless operation key button operation, BCM blinks hazard warning lamps as a reminder.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Keyless operation key Operation", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Unlock", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Hazard warning light blinks", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Once", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Twice", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When any door is open, reminder function does not operate according to door lock operation.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "AUTO DOOR LOCK FUNCTION (KEYLESS OPERATION KEY)", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "After door is unlocked by Keyless operation key button operation and if 30 seconds or more passes without performing the following operation, all doors are powerally locked. However, operation check function does not activate.", "ptxt");
