si[i++] = gsitm("N5110102T0007U00ENG.html", "Push switch is pressed", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "POWER LIFTGATE OPEN/CLOSE FUNCTION", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When liftgate open button is pressed, liftgate open powerally for detailed description.", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5110102T0007U00ENG.html", "REMOTE ENGINE START FUNCTION", "title");
si[i++] = gsitm("N5110102T0007U00ENG.html", "When remote engine start button is pressed, engine can be started.", "ptxt");
