si[i++] = gsitm("N5110102T0007V00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110102T0007V00ENG.html", "BASIC OPERATION", "title");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Key reminder is the function that prevents the key from being left in the vehicle.", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Key reminder has the following 2 functions.", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Key remainder function", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Operation condition", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Front door (driver side) closed*", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "When all doors other than front door (driver side) are locked, front door (driver side) locks within 0.3 seconds after front door (driver side) is closed", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "All doors unlock", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Door is open to closed", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "When all of the following conditions are satisfied", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Locked all doors with door lock/unlock switch", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "[Any door: open] → [all doors: closed]", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Registered Keyless operation key is inside the vehicle", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "Honk Keyless operation key warning buzzer", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "*:If the door closing impact shocks the door lock knob, or contacts against baggage with the door lock knob might activate the door locks accidentally but unlock operation is perform in these cases.", "ptxt");
si[i++] = gsitm("N5110102T0007V00ENG.html", "The above function operates when the Keyless operation key is inside the vehicle. However, there may be times when the Keyless operation key cannot be detected, and this function does not operate when the Keyless operation key is on the instrument panel, rear parcel shelf, or in the glove box. Also, this system sometimes does not operate if the Keyless operation key is in the door pocket for the open door.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110102T0007W00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Description", "title");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Keyless operation key unit incorporates a power consumption control function that reduces the power consumption according to the vehicle status.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Keyless operation key unit changes its status (control mode) with the sleep wake up signal received from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Normal mode (wake-up)", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "CAN communication is normally performed with other control units.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Individual unit control by Keyless operation key unit is normally performed.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Low power consumption mode (sleep)", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Low power consumption control is active.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "CAN transmission is stopped.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Sleep Mode Activation", "title");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Keyless operation key unit judges that the sleep-ready conditions are fulfilled when the ignition switch is OFF and none of the conditions below are present. Then it transmits a sleep-ready signal (ready) to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Outputting signals to actuators", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Output requests are being received from control units via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Keyless operation key unit stops CAN communication and enters the low power consumption mode when it receives a sleep wake up signal (sleep) from BCM and the sleep-ready conditions are fulfilled.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Wake-Up Operation", "title");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Keyless operation key unit changes from the low power consumption mode to the normal mode when it receives a sleep wake-up signal (wake up) from BCM or any of the following conditions is fulfilled. In addition, it transmits a sleep-ready signal (not-ready) to BCM via CAN communication to report the CAN communication start.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Push-button ignition switch status changes.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "Each door request switch status changes.", "ptxt");
si[i++] = gsitm("N5110102T0007W00ENG.html", "An output request is received from a control unit via CAN communication.", "ptxt");
