si[i++] = gsitm("N511010430000Q00ENG.html", "Synchronization is applied.", "ptxt");
si[i++] = gsitm("N511010430000Q00ENG.html", "Refer to Master Warning Light .", "ptxt");
si[i++] = gsitm("N511010430000Q00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N511010430000Q00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N511010430000Q00ENG.html", "BCM transmits door switch signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N511010430000Q00ENG.html", "When combination meter judges according to received door switch signal that a door is open or not fully closed, door open warning displays.", "ptxt");
si[i++] = gsitm("N511010430000Q00ENG.html", "WARNING/INDICATOR OPERATION CONDITION", "title");
