si[i++] = gsitm("N511010440000T00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N511010440000T00ENG.html", "Keyless operation key unit receives engine status signal from ECM via CAN communication and checks that the engine can be started.", "ptxt");
si[i++] = gsitm("N511010440000T00ENG.html", "When Keyless operation key unit detects that the engine can be started, meter display signal is transmitted by Keyless operation key unit to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N511010440000T00ENG.html", "When combination meter receives meter display signal, engine start information displays.", "ptxt");
