si[i++] = gsitm("N5110102T0007X00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Liftgate opener switch", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Liftgate opener actuator", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Transmit vehicle speed signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "When the BCM receives the open operation signal from the liftgate opener switch , it operates the liftgate opener actuator.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Power liftgate OPENER OPERATION", "title");
si[i++] = gsitm("N5110102T0007X00ENG.html", "When liftgate opener switch is pressed, BCM operates liftgate opener actuator.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Liftgate opener actuator is not for locking the liftgate. The function is only to open the liftgate.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5110102T0007X00ENG.html", "If the following conditions are satisfied, liftgate opener operation is performed.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Liftgate opener switch operation", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Operation condition", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Liftgate open", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "When liftgate opener switch is pressed while all doors are in unlock status.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Vehicle speed is less than 4 km/h (2 MPH)", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "When battery terminal is disconnected and reconnected during all doors unlock state, liftgate may not open.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "Regardless of door lock actuator state, BCM resets recognition of all doors unlock state approximately 30 seconds after battery terminal is disconnected and BCM recognizes that all doors are in lock state.", "ptxt");
si[i++] = gsitm("N5110102T0007X00ENG.html", "When battery terminal is reconnected and liftgate does not open, have BCM recognize that all doors are in unlock state.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The power liftgate system performs the automatic open/close operation of the liftgate by operating the power liftgate switch, power liftgate close switch, power liftgate lock and close switch, liftgate opener switch, hands free sensor, and Keyless operation key.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate system controls operation function of the following items.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free function (hands free sensor operation)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic open/close temporary stop function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Liftgate open position setting function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate open/close function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Warning function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Liftgate auto closure function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Anti-pinch function", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "HANDS FREE FUNCTION (HANDS FREE SENSOR OPERATION)", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The hands free function is a function that automatically opens/closes the liftgate when the user moves a foot toward rear bumper and then pulls it back quickly (performs a kick motion).", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands Free Sensor Operation", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When the user performs a kick motion toward rear bumper while carrying Keyless operation key as shown in the figure, hands free sensor (upper side) detects shin motion of leg and hands free sensor (lower side) detects instep motion of foot. This varies the voltage waveform of hands free sensor. Hands free sensor control unit judges user operation by detecting the voltage change of hands free sensor.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands Free Sensor Detection Area", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "It is necessary to perform a kick motion within space as shown in the figure for activating the hands free sensor completely. The detection area may differ depending on the conditions of the surroundings.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "For activating the hands free function, a kick motion must be detected by both hands free sensor (upper side) and hands free sensor (lower side).", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor may not operate in a place near a radio-wave generation source such as a coin-operated parking lot or radio wave tower.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor may not operate if shoes that block static electricity (safety shoes, etc.) are worn when operating hands free sensor.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor may not operate if there is any metal near rear bumper.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic open/close function may operate if hands free sensor detects an animal, rain, an object, etc. when Keyless operation key is near the rear bumper.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When automatic open function is activated by hands free function, BCM unlocks all doors and activates Keyless operation key warning buzzer.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Operation Condition", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When all of the following conditions are satisfied", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Vehicle speed: 0 km/h", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Shift position: P position", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate setting: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key: Within outside key antenna (rear bumper) detection area", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Operation Description (Fully Closed to Fully Open of Liftgate)", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When the user moves a foot toward rear bumper and pulls back quickly (performs a kick motion) while carrying Keyless operation key, voltage waveform change of hands free sensor (upper side) and hands free sensor (lower side) occurs.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor control unit judges user operation by detecting the voltage waveform change of hands free sensor (upper side) and hands free sensor (lower side). The hands free sensor control unit then transmits power liftgate operation request signal to BCM via serial communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When BCM receives an power liftgate operation request signal from hands free sensor control unit, the BCM transmits a key ID verification request signal to Keyless operation key unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When Keyless operation key unit receives a key ID verification request signal, Keyless operation key unit activates outside key antenna (rear bumper) and checks that Keyless operation key is near rear bumper.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When Keyless operation key is within the outside key antenna (rear bumper) detection area, Keyless operation key receives the request signal and transmits the key ID signal to Keyless operation key unit via remote keyless entry receiver.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key unit receives key ID signal and verifies the received key ID with the registered key ID.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When key IDs verification match, Keyless operation key unit transmits a key ID verification completed signal to power liftgate control unit via CAN communication. When selective unlock function is OFF, BCM unlocks all doors simultaneously. For details of selective unlock function, refer to .", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When power liftgate control unit receives a key ID verification completed signal from Keyless operation key unit, the power liftgate control unit operates liftgate auto closure function and opens liftgate.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate control unit operates the automatic open function after liftgate auto closure function stops, and opens liftgate to the full open position* automatically.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "*: Full open position can be changed with liftgate open position setting function.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Operation Description (Fully Open to Fully Closed of liftgate)", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor control unit judges user operation by detecting the voltage waveform of hands free sensor (upper side) and hands free sensor (lower side). The hands free sensor control unit then transmits an power liftgate operation request signal to BCM via serial communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When Keyless operation key unit receives key ID verification request signal, Keyless operation key unit activates outside key antenna (rear bumper) and checks that Keyless operation key is near rear bumper.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key unit receives a key ID signal and verifies it with the registered key ID.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When the key IDs match, Keyless operation key unit transmits the key ID verification completed signal to power liftgate control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When power liftgate control unit receives key ID verification completed signal from Keyless operation key unit, the power liftgate control unit operates automatic close function to close liftgate automatically until liftgate is in the ajar state (latch and striker are engaged).", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When power liftgate control unit detects liftgate ajar state, the unit operates liftgate auto closure function to close liftgate completely.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "AUTOMATIC OPEN/CLOSE TEMPORARY STOP FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic open/close temporary stop function temporarily stops the open/close operation by operating liftgate opener switch, power liftgate lock and close switch, power liftgate close switch, power liftgate switch, Keyless operation key or hands free sensor during automatic open/close operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Each Switch, Keyless operation key or Hands Free Sensor Operation", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic open/close operation stops when liftgate opener switch, power liftgate lock and close switch, power liftgate close switch, power liftgate switch, Keyless operation key or hands free sensor is operated during automatic open/close operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "If the liftgate opener switch, power liftgate lock and close switch, power liftgate close switch, power liftgate switch, Keyless operation key, or hands free sensor is operated during the operation of automatic open/close temporary stop function (liftgate operation is stopped), the liftgate direction of operation changes automatically. As a result, the liftgate operates in the direction opposite to the direction of operation before operation stop.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "POWER LIFTGATE OPEN POSITION SETTING FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Liftgate open position setting function is a function that enables users to set the full opening stop position of automatic open operation when liftgate may contact an obstacle if fully opened by the automatic open operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "It is not possible to set the position farther than the initial setting fully open position in the open direction.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The position of liftgate cannot be set to approximately 30% or less than full open position. (Opening angle cannot be set to approximately 28° or less.)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "If a vehicle is parked on a steep slope after setting the fully open position of liftgate to half open or less, the door may open to near the half open position instead of stopping at the set position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When more than one user uses the vehicle, the liftgate fully open position setting function may be changed. Be careful when operating automatic open operation for the first time.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Setting Procedure", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "By performing the following operations, stop position of the liftgate open position setting function can be set.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Set the shift position to P range.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Fully close the liftgate. (When liftgate is already fully closed, this operation is not necessary.)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "After turning OFF the power liftgate setting, release the latch by liftgate opener switch operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Manually move the liftgate to the desired stop position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "While maintaining the liftgate position, press and hold the power liftgate close switch for 3 seconds or more. When the setting is successfully completed, power liftgate warning buzzer sounds (pattern C).", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Reset Procedure", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "By performing the following operation, the setting of the liftgate open position setting function can be canceled.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Open the liftgate to the fully open position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Manually move the liftgate to the upper limit position in the opening direction.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Press and hold the power liftgate close switch for 3 seconds or more. When the setting is successfully completed, power liftgate warning buzzer sounds (pattern C).", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "POWER LIFTGATE OPEN/CLOSE FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "power liftgate open/close function operates auto open/close of liftgate according to operation of power liftgate switch, power liftgate close switch, liftgate opener switch, hands free sensor, and Keyless operation key.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When push the power liftgate lock and close switch while carrying the Keyless operation key, the liftgate will close, and when fully closed, all doors can be locked.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power supply (power liftgate control unit): Approx. 11 V or more", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key is with in outside key antenna (rear bumper) detection area. (when power liftgate lock and lock and close switch operated)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "All doors are in unlock status (when power liftgate switch operated)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic Open/close Operation When Each Switch is Operated", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The automatic open/close operation when each switch is operated differs according to the stop position or operating status of liftgate. Refer to the following.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When the liftgate position is in the range of  [between \"just before fully closed\" and the position approximately less than 150 mm (5.91 in) from \"just before fully closed\"], the liftgate does not operate even if any of switches are operated. But this is not malfunction.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "To operate the liftgate by switches, manually close the liftgate to \"Fully closed\" position or manually open the liftgate approximately more than 150 mm (5.91 in) from the position of \"Just before fully closed\". And then operate any of switches.", "ptxt");
