si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key must be carried for starting the automatic open/close function by hands free sensor operation (hands free function) with the liftgate stopped.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Full Closed to Fully Open Operation): Case 1", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Buzzer operate (A pattern) and, liftgate closure motor starts the open operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Open switch turns ON, and liftgate latch release operation completes.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Half latch switch turns ON, and then liftgate closure motor performs reverse operation and returns to the neutral position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When close switch turns OFF, liftgate closure motor reverse operation stops, and then completes returning to the neutral position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Full Closed to Fully Open Operation): Case 2", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Half latch switch turns ON, and liftgate latch release operation completes.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Open switch turns ON, and then liftgate closure motor performs reverse operation and returns to the neutral position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Fully Open to Fully Closed Operation)", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Buzzer operate (A pattern) and, spindle motor starts the close operation.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "CONTROL IF NOT WITHIN THE OPERATION CONDITIONS DURING THE OPERATION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "If the liftgate is not within the operation conditions during the operation, the power liftgate control unit performs the control as follows.", "ptxt");
