si[i++] = gsitm("N5110102T0007Y00ENG.html", "WARNING FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The warning function is as follows and gives the user warning information using power liftgate warning buzzer.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate warning buzzer", "title");
