si[i++] = gsitm("N5110102T0007Y00ENG.html", "POWER LIFTGATE AUTO CLOSURE FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Open Function", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When liftgate opener switch is pressed and power liftgate setting in the OFF position, BCM transmits the liftgate open request signal to power liftgate control unit via CAN communication, and power liftgate control unit opens liftgate lock assembly.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Open function): Case 1", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Open function): Case 2", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Closure Function", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When the liftgate is closed to the half-latch position, the motor drives to rotate the latch lever and pulls it in from half latched to fully latched and automatically closes the door. Then, the closure motor reverses to the neutral position.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Timing Chart (Closure Function)", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "ANTI-PINCH FUNCTION", "title");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When pinching of foreign material is detected during the operation of automatic open/close function, the liftgate is operated in the reverse direction.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "The detection methods are the following two types.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Overload detection (detection by encoder)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "When a drop in the operating speed is detected during the operation of the automatic open/close function, this is judged as pinching, and reverse operation operates.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "If an overload by pinching or contact with foreign material is detected, reverse operation operates again. At this time, when the second overload is detected, automatic operation stops.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Pinching detection (detection by liftgate touch sensor)", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "If the side part of the door pinches foreign material during the operation of automatic close function, the touch sensor detects this, and the door operates in the reverse direction. If a reverse operation is performed during driving, liftgate shifts to closing operation again. At this time, if the touch sensor detects foreign material in the closing direction for a second time, automatic operation stops.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Automatic operation is stopped when one of the following conditions is detected after the first overload or pinching is detected.", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate switch: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Keyless operation key liftgate open button: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate close switch: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Power liftgate lock and close switch: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Liftgate opener switch: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Hands free sensor: ON", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Overload detection or pinching detection: second time", "ptxt");
si[i++] = gsitm("N5110102T0007Y00ENG.html", "Detection method", "ptxt");
