si[i++] = gsitm("N5110104S0002U00ENG.html", "Voltage generated in communication circuit between hands free sensor and hands free sensor control unit is extremely low and therefore cannot be measured.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Record DTC and freeze frame data (print them out using M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Are any symptoms described or any DTC detected?", "question");
si[i++] = gsitm("N511010300001D00ENG.html", "Symptom is described, DTC is displayed", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Symptom is described, DTC is not displayed", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Symptom is not described, DTC is displayed", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Also study the normal operation and fail-safe related to the symptom.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again. At this time, always connect M.U.T.-III SE to the vehicle, and check diagnostic results in real time.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "If two or more DTCs are detected, refer to  (Keyless operation key unit), DTC Inspection Priority Chart (power liftgate control unit) or DTC Inspection Priority Chart (BCM), and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N511010300001D00ENG.html", "YES", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "NO", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "Refer to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Is the symptom described?", "question");
si[i++] = gsitm("N511010300001D00ENG.html", "Monitor input data from related sensors or check voltage of related module terminals using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Check for DTC. If DTC is displayed, erase it.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N511010300001D00ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is completely repaired.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N511010300001D00ENG.html", "YES-1", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "YES-2", "result");
si[i++] = gsitm("N511010300001D00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N511010300001D00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "Description", "title");
si[i++] = gsitm("N51101011000WF00ENG.html", "When replacing the Keyless operation key unit, always replace it with a new one. The functions controlled by the Keyless operation key unit does not operate properly in case of reuse of the Keyless operation key unit from another vehicle.", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "Perform the following operations when replacing Keyless operation key unit. For details, refer to .", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N51101011000WF00ENG.html", "After replacing Keyless operation key unit, the following must be performed. Or not doing so, Keyless operation key unit control function does not operate normally.", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "Writing vehicle specification", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "Initialization and reregistration of all keyless operation keys", "ptxt");
si[i++] = gsitm("N51101011000WF00ENG.html", "When replacing keyless operation key unit, Perform initialization and reregistration of all keyless operation keys.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511010320003Y00ENG.html", "REPLACE KEYLESS OPERATION KEY UNIT", "REPLACEINTELLIGENTKEYUNIT-0FBF3EEC");
si[i++] = gsitm("N511010320003Y00ENG.html", "Replace Keyless operation key unit. Refer to .", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "WRITING VEHICLE SPECIFICATION", "WRITINGVEHICLESPECIFICATION-0FBF3EF3");
si[i++] = gsitm("N511010320003Y00ENG.html", "M.U.T.-III SE Configuration", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "INITIALIZATION AND REREGISTRATION OF ALL KEYLESS OPERATION KEYS", "INITIALIZENATS-0FBF3EE2");
si[i++] = gsitm("N511010320003Y00ENG.html", "Perform initialization and reregistration of all keyless operation keys.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N511010320003Y00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"HANDS FREE MODULE\".", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N511010320003Y00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51101011000Q700ENG.html", "Description", "title");
si[i++] = gsitm("N51101011000Q700ENG.html", "When replacing power liftgate control unit necessary to perform initial setting to operate power liftgate system normally. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511010320003100ENG.html", "STEP 1", "title");
si[i++] = gsitm("N511010320003100ENG.html", "Select “Power liftgate” using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "Select \"RESET Power liftgate status\" of \"Special Function\" mode and erase power liftgate position information.", "ptxt");
