si[i++] = gsitm("N511010320003100ENG.html", "STEP 2", "title");
si[i++] = gsitm("N511010320003100ENG.html", "Fully close the liftgate manually.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "STEP 3", "title");
si[i++] = gsitm("N511010320003100ENG.html", "Operate liftgate opener switch and perform power liftgate open operation.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "STEP 4", "title");
si[i++] = gsitm("N511010320003100ENG.html", "The liftgate fully opens.", "ptxt");
