si[i++] = gsitm("N511010320003100ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"Power liftgate\".", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N511010320003100ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
