si[i++] = gsitm("N51101011000Q800ENG.html", "Description", "title");
si[i++] = gsitm("N51101011000Q800ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "The configuration no need to “save” configuration data from the Keyless operation key unit. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N51101011000Q800ENG.html", "Never perform “Configuration” except for new Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N511010320003200ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511010320003200ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N511010320003200ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N511010320003200ENG.html", "Perform writing vehicle specification to Keyless operation key unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N511010320003200ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N511010320003200ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N511010320003200ENG.html", "WORK END", "ptxt");
