si[i++] = gsitm("N51101011000R400ENG.html", "Description", "title");
si[i++] = gsitm("N51101011000R400ENG.html", "When the liftgate position is in the range of  [between \"just before fully closed\"  and the position approximately less than 150 mm from \"just before fully closed\" ], the liftgate does not operate even if any of switches are operated.", "ptxt");
si[i++] = gsitm("N51101011000R400ENG.html", "To operate the liftgate by switches, manually close the liftgate to \"Fully closed\"  position or manually open the liftgate approximately more than 150 mm from the position of \"Just before fully closed\". And then operate any of switches.", "ptxt");
si[i++] = gsitm("N511060340000Q00ENG.html", "ADJUSTMENT OF CLEARANCE AROUND HOOD", "title");
si[i++] = gsitm("N511060340000Q00ENG.html", "Loosen the hood hinge mounting nuts but do not remove them. Move the hood hinge back/forth and left/right to align the clearance between the hood and body.", "ptxt");
si[i++] = gsitm("N511060340000Q00ENG.html", "After the adjustment, tighten the hood hinge mounting nuts to specified torque.", "ptxt");
si[i++] = gsitm("N511060340000Q00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N511060340000Q00ENG.html", "9.5 ± 3.5 N·m", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "ADJUSTMENT OF HOOD LEVEL AND HOOD STRIKER ENGAGEMENT", "title");
si[i++] = gsitm("N511060350000N00ENG.html", "Remove the hood lock cover (Refer to ).", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "Loosen the hood lock mounting bolts but do not remove them. Move the hood lock up/down and left/right to align the hood level and adjust the hood striker engagement.", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "After the adjustment, tighten the hood lock mounting bolts specified torque.", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "Tightening torque:", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "9.0 ± 1.0 N·m &lt;Washer-assembled bolts> or11 ± 1 N·m &lt;Flange bolts>", "ptxt");
si[i++] = gsitm("N511060350000N00ENG.html", "Install the hood lock cover (Refer to .)", "ptxt");
si[i++] = gsitm("N511060360000O00ENG.html", "ADJUSTMENT OF HOOD HEIGHT", "title");
si[i++] = gsitm("N511060360000O00ENG.html", "Turn the damper 2 and 1/4 turns from the starting point to adjust the height. If the height of the hood is not even after adjusting the damper to the height shown, turn the damper again until the height is even.", "ptxt");
si[i++] = gsitm("N511060360000O00ENG.html", "If a rattling noise is heard due to the vibration of the hood when the vehicle is being driven, adjust the damper height until the damper is seated on the hood.", "ptxt");
