si[i++] = gsitm("N511220030000J00ENG.html", "Sliding hammer", "ptxt");
si[i++] = gsitm("N511220030000J00ENG.html", "MB990241", "ptxt");
si[i++] = gsitm("N511220030000J00ENG.html", "a: MB990243", "ptxt");
si[i++] = gsitm("N511220030000J00ENG.html", "Axle shaft puller", "ptxt");
si[i++] = gsitm("N511220030000J00ENG.html", "a: Body puller", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "DOOR FIT ADJUSTMENT", "title");
si[i++] = gsitm("N511220050000M00ENG.html", "When you adjust any of the doors, you should check the camera image on the multi-around monitor \"Bird-eye view.\" If necessary, calibrate the monitor &lt;vehicle with multi-around monitor>.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Do not apply 98 N·m or more to the door hinge adjusting wrench (Special tool: MB991163).", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "When the clearance between the door and the body is uneven:", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Apply protective tape to the fender around the hinge installation position and door edge.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Remove the centre pillar lower garnish &lt;Rear door> (Refer to Interior Trim ).", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Use the door hinge adjusting wrench (Special tool: MB991163) to loosen the body-side door hinge mounting bolts.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "As for the upper hinge of the rear door, loosen the body-side door hinge mounting nut using a general tool from inside the vehicle.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Move the door to adjust the clearance between the door and the body is even.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "When the door is not flush with the body surface:", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Loosen the door-side hinge mounting bolts.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Move the door to adjust so that the door is flush with the body surface.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "If adjustment is not possible, replace the door-side door hinge mounting bolt with the adjustment bolt (MU001031).", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "If the adjustment bolt has been already installed, reuse it.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Tighten the door-side door hinge mounting bolt to the specified torque.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Tightening torque: 27 ± 6 N·m", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "When the door is stiff to close and open:", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "To avoid inadvertent airbag deployment, always turn ignition switch to the \"OFF\" position and wait 3 minutes or more before adjust the striker.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Adjustment using the striker (toward the inside of the vehicle and vertical direction):", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Install a temporary bolt instead of the striker mounting bolt, and use the remover bar (Special tool: MB990939) and a hammer to tap the temporary bolt to the desired direction.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Adjustment by using the striker (toward the outside of the vehicle):", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Using the following tools, pull the striker toward the outside of the vehicle to adjust.", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Slide hammer (MB990211)", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Body puller (MB990243)", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Adjustment using shims: (forward and rearward)", "ptxt");
si[i++] = gsitm("N511220050000M00ENG.html", "Increase or decrease the number of shims so that the striker engages with the door latch properly.", "ptxt");
