si[i++] = gsitm("N5110108U000NJ00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "&lt;&lt;A>> DOOR OPENING OUTER WEATHERSTRIP REMOVAL", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Make the tool as shown in the figure, and remove the weatherstrip from the door panel.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", ">>A&lt;&lt; REAR DOOR SASH TAPE INSTALLATION", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Apply a new rear door sash tape according to the procedure below.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Apply a positioning tape at 10 mm above from the upper end of the door opening inner weatherstrip installation clip hole as shown in the figure.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Position the upper end of the rear door sash tape at the lower end of the applied positioning tape, and apply the rear door sash tape so that it is parallel to the sash.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "There is a triangular notch for identification on the rear door sash tape for the right side door.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", ">>B&lt;&lt; DOOR OPENING INNER WEATHERSTRIP INSTALLATION", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "A rubber string for factory production is installed to the new front side door opening inner weatherstrip. Therefore, peel off the rubber string to the root and remove it.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Align the mark on the door opening inner weatherstrip with the notch at the vehicle body side as shown.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", ">>C&lt;&lt; DOOR WINDOW GLASS RUNCHANNEL INSTALLATION", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Install only the roof part of the door window glass runchannel.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Install the front door sash cover front/front door sash cover rear or rear door sash cover front/rear door sash cover rear  (Refer to Door Sash Cover ).", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Insert the pillar part of the door window glass runchannel into the pillar garnish.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Install the other parts of the door window glass runchannel.", "ptxt");
si[i++] = gsitm("N5110108U000NJ00ENG.html", ">>D&lt;&lt; DOOR BELTLINE MOULDING INSTALLATION", "title");
si[i++] = gsitm("N5110108U000NJ00ENG.html", "Install the door beltline moulding so that the flange part of the door outer panel shown in the figure fits into the hole at the end cap part shown in the figure.", "ptxt");
si[i++] = gsitm("N511230010001000ENG.html", "SEALANT", "title");
