si[i++] = gsitm("N511230020001100ENG.html", "Bearing and oil seal installer set", "ptxt");
si[i++] = gsitm("N511230020001100ENG.html", "a: Remover bar", "ptxt");
si[i++] = gsitm("N511230020001100ENG.html", "Adjustment of liftgate striker", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "LIFTGATE ADJUSTMENT", "title");
si[i++] = gsitm("N511230040000U00ENG.html", "When you have adjusted the striker so that it is engaged with the latch properly and adjusted the liftgate height, you should check the camera image on the multi-around monitor \"Bird-eye view.\" If necessary, calibrate the monitor. &lt;Vehicles with multi-around monitor>", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "ADJUSTMENT OF ENGAGEMENT BETWEEN STRIKER AND LATCH", "title");
si[i++] = gsitm("N511230040000U00ENG.html", "Remove the luggage rear plate (Refer to Luggage Trim  &lt;Vehicles for 7 Persons>, &lt;Vehicles for 5 Persons>).", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Replace the striker mounting screws with temporary bolts, and use the remover bar (special tool: MB990939) and a hammer to tap the temporary bolt to the desired direction.", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Tighten the striker mounting screws.", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Tightening torque: 21 ± 4 N·m", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Install the luggage rear plate (Refer to Luggage Trim  &lt;Vehicles for 7 Persons>, &lt;Vehicles for 5 Persons>).", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "ADJUSTMENT OF CLEARANCE BETWEEN LIFTGATE AND BODY", "title");
si[i++] = gsitm("N511230040000U00ENG.html", "Loosen the liftgate hinge mounting bolts to adjust the clearance between the liftgate and body.", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Tighten the liftgate hinge mounting bolts.", "ptxt");
si[i++] = gsitm("N511230040000U00ENG.html", "Tightening torque: 24 ± 4 N·m", "ptxt");
si[i++] = gsitm("N511230050000R00ENG.html", "ADJUSTMENT OF LIFTGATE HEIGHT", "title");
si[i++] = gsitm("N511230050000R00ENG.html", "Rotate the damper by using the arrow mark on the damper as a guide to adjust the liftgate height. The damper height is altered by roughly 4.0 mm when it is rotated once.", "ptxt");
si[i++] = gsitm("N511230050000R00ENG.html", "If a rattling noise is heard due to the vibration of the liftgate when the vehicle is being driven, adjust the damper height until the damper is seated on the vehicle body. The damper should be seated on the vehicle body regardless of a rattling noise.", "ptxt");
