si[i++] = gsitm("N511220080000I00ENG.html", "DOOR OUTSIDE HANDLE PLAY CHECK", "title");
si[i++] = gsitm("N511220080000I00ENG.html", "Check that the door outside handle assembly play (stroke until the door latch unlocks) meets the standard value.", "ptxt");
si[i++] = gsitm("N511220080000I00ENG.html", "Standard value (B):", "ptxt");
si[i++] = gsitm("N511220080000I00ENG.html", "Front door: 0.1 - 5.0 mm [Target value: 2.0 mm]", "ptxt");
si[i++] = gsitm("N511220080000I00ENG.html", "Rear door: 0.1 - 5.0 mm [target value: 2.0 mm]", "ptxt");
si[i++] = gsitm("N511220080000I00ENG.html", "Check the door outside handle assembly and door lock assembly. Replace them if the play is out of the standard value.", "ptxt");
si[i++] = gsitm("N511220090000I00ENG.html", "DOOR INSIDE HANDLE CHECK", "title");
si[i++] = gsitm("N511220090000I00ENG.html", "DOOR INSIDE HANDLE KNOB PLAY CHECK", "title");
si[i++] = gsitm("N511220090000I00ENG.html", "Check that the door inside handle knob play (stroke until the door latch unlocks) meets the standard value.", "ptxt");
si[i++] = gsitm("N511220090000I00ENG.html", "Standard value (B): 13.8 - 30.0 mm [Target value: 21.7 mm]", "ptxt");
si[i++] = gsitm("N511220090000I00ENG.html", "Check the door inside handle knob and door lock assembly. Replace them if the play is out of the standard value.", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "DOOR LOCK INDICATOR ROD STROKE CHECK", "title");
si[i++] = gsitm("N511220100000J00ENG.html", "Measure the amount of protrusion from the door finisher at the lock position and the unlock position of the door lock indicator rod.", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "Check whether the difference between the amounts of protrusion (stroke) is within the standard value.", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "Front door: Approximately 12.3 mm", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "Rear door: Approximately 12.0 mm", "ptxt");
si[i++] = gsitm("N511220100000J00ENG.html", "If it is not within the standard value, check the door lock indicator rod, the door lock assembly and the door inside lock cable (rear only) and replace the defective parts.", "ptxt");
