si[i++] = gsitm("N5110200U0000T00ENG.html", "Starter cut relay", "ptxt");
si[i++] = gsitm("N5110200U0000T00ENG.html", "View with back side of rear bumper fascia assembly", "ptxt");
si[i++] = gsitm("N5110200U0000T00ENG.html", "View with front bumper fascia assembly removed", "ptxt");
si[i++] = gsitm("N511020380000L00ENG.html", "NATS Antenna Amp.", "title");
si[i++] = gsitm("N511020380000L00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N511020380000L00ENG.html", "If the ID is successfully verified, when push-button ignition switch is pressed and the engine can be started.", "ptxt");
si[i++] = gsitm("N511020380000L00ENG.html", "In that case, NATS ID verification can be performed when keyless operation key backside is contacted to push-button ignition switch while brake pedal is depressed. If verification result is OK, engine can be started.", "ptxt");
si[i++] = gsitm("N511020380000L00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N511020380000L00ENG.html", "NATS antenna amp. detects the ID registered in keyless operation key.", "ptxt");
si[i++] = gsitm("N511020380000L00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N511020380000L00ENG.html", "NATS antenna amp. transmits the ID received from the keyless operation key to the keyless operation key unit.", "ptxt");
si[i++] = gsitm("N511020380000L00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N511020380000L00ENG.html", "NATS antenna amp. is integrated in push-button ignition switch. Refer to .", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "Hood Switch", "title");
si[i++] = gsitm("N511020390000N00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N511020390000N00ENG.html", "Hood switch detects that hood is open, and then transmits hood switch signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "IPDM E/R transmits hood switch signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "If any door or hood is opened without using keyless operation key, vehicle security system switches to the ALARM phase. Refer to .", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N511020390000N00ENG.html", "Hood switch detects that hood is open/close condition.", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N511020390000N00ENG.html", "Hood switch is transmits hood switch signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N511020390000N00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N511020390000N00ENG.html", "Hood switch is integrated in hood lock assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Door switch", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Door switch detects door switch condition and then transmits door switch signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Inside key antenna", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Inside key antenna detects whether keyless operation key is inside the vehicle, and transmits the key ID signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Stop light switch", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Stop light switch detects that brake pedal is depressed, and then transmits stop light switch signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "ABS actuator and electric unit (control unit) transmits the vehicle speed signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "TCM receives the P/N position signal from transmission range switch, and then transmits the shift position signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "ECM controls the engine.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When ignition switch is turned ON, keyless operation key unit starts communication with ECM and performs the ID verification between keyless operation key unit and ECM.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "If the verification result is OK, the engine can start. If the verification result is NG, the engine cannot start.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Starter cut relay is controlled by BCM, and starter relay is controlled by IPDM E/R while communicating with BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When BCM receives a starter cut relay request signal from ECM, the starter cut relay is turned ON.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Push-button ignition switch", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Push switch", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Push-button ignition switch has push switch inside which detects that push-button ignition switch is pressed, and then transmits the push switch signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit changes the ignition switch position with the operation of push-button ignition switch.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit maintains the ignition switch position status while push-button ignition switch is not operated.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "NATS antenna amp.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "VEHICLE IMMOBILIZER SYSTEM: Refer to", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "KEYLESS OPERATION KEY SYSTEM: Refer to .", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The keyless operation key system is a system that makes it possible to lock and unlock the door locks (door lock/unlock function) by carrying the keyless operation key, which operates based on the results of electronic ID verification using two-way communication between the keyless operation key and the vehicle (keyless operation key unit).", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit controls KEYLESS OPERATION KEY SYSTEM (ENGINE START FUNCTION)", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit performs the ID verification between keyless operation key unit and keyless operation key when the keyless operation key is carried into the detection area of inside key antenna, and push-button ignition switch is pressed. If the ID verification result is OK, ignition switch operation is available.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Then, when the ignition switch is turned ON, keyless operation key unit performs ID verification between keyless operation key unit and ECM. If the ID verification result is OK, ECM can start engine.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "TCU", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "TCU transmits engine start request signal to BCM when engine start request is received from Infiniti Connection™ data center.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "BCM INPUT/OUTPUT SIGNAL CHART", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Input Signal Item", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Transmit unit", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Signal name", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "CAN communication", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine status signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Starter cut relay request signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Ignition ON signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Starter cut relay status signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Neutral position signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Vehicle speed signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Shift position signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine start request signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Each door switch", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Door switch signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Stop light switch signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Output Signal Item", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Reception unit", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "KEYLESS OPERATION KEY UNIT INPUT/OUTPUT SIGNAL CHART", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Key ID request signal", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The engine start function of keyless operation key system makes it possible to start and stop the engine without using the key, based on the electronic ID verification. The electronic ID verification is performed between keyless operation key unit and keyless operation key when the push-button ignition switch is pressed while the keyless operation key is within the detection area of inside key antenna.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The driver should carry the keyless operation key at all times.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key have ID (key ID). It can perform the door lock/unlock operation and the push-button ignition switch operation when the registered keyless operation key is carried.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "If the ID is successfully verified, when push-button ignition switch is pressed, engine can be started.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Up to 4 Keyless operation keys can be registered (Including the standard keyless operation key) upon request from the customer.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "For any functions other than engine start function of keyless operation key system. Refer to .", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "PRECAUTIONS FOR KEYLESS OPERATION KEY SYSTEM", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The transponder (the chip for NATS ID verification) is integrated into the keyless operation key. It is integrated into the mechanical key. Therefore, ID verification cannot be performed by mechanical key only.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "In that case, NATS ID verification can be performed when keyless operation key backside is contacted to push-button ignition switch while brake pedal is depressed. If verification result is OK, engine can be started.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "OPERATION WHEN KEYLESS OPERATION KEY IS CARRIED", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When the push-button ignition switch is pressed, the keyless operation key unit activates the inside key antenna and transmits the request signal to the keyless operation key.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The keyless operation key receives the request signal and transmits the NATS ID signal to the keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Keyless operation key unit receives the NATS ID signal verifies it with the registered ID.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When the ignition switch is turned to ON, keyless operation key unit performs ID verification with the ECM. When the result is OK, engine start is permitted.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When ECM detects that the start engine conditions* are satisfied, it transmits a starter cut relay request signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When starter cut relay is turned ON, IPDM E/R turns ON the starter relay and drives the starter motor.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When BCM receives an engine status signal from ECM, it turns the starter relay and starter cut relay OFF and stops cranking.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When the keyless operation key is carried outside of the vehicle (outside key antenna detection area) while the power supply is in the ON position, even if the engine start condition* is satisfied, the engine cannot be started.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "*: For the engine start condition, refer to \"IGNITION SWITCH POSITION CHANGE TABLE BY PUSH-BUTTON IGNITION SWITCH OPERATION\".", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "OPERATION RANGE", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine can be started when keyless operation key is inside the vehicle. However, sometimes engine may not start when keyless operation key is on instrument panel or in glove box.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "IGNITION SWITCH POSITION CHANGE TABLE BY PUSH-BUTTON IGNITION SWITCH OPERATION", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The ignition switch position can be changed by the following operations.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When an keyless operation key is within the detection area of inside key antenna or when keyless operation key backside is contacted to push-button ignition switch, it is equivalent to the operations below.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "When starting the engine, the BCM monitors under the engine start conditions.", "ptxt");
