si[i++] = gsitm("N5110202T0001U00ENG.html", "OFF → ON → OFF", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "OFF → START", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "ON → START", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "P or N position", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Depressed", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine is running → OFF", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "If the keyless operation key unit cannot detect that the keyless operation key is in the vehicle, ignition switch can be turned OFF by the press and hold the push-button ignition switch for 2 seconds or more.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Vehicle speed: 4 km/h (2.5 MPH) or more", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Emergency stop operation", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine stall return operation while driving", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "N position", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Press and hold the push-button ignition switch for 2 seconds or more.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Press the push-button ignition switch 3 times or more within 1.5 seconds.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "REMOTE ENGINE START FUNCTION", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Remote engine start function enables engine to be started from vehicle outside by operating remote engine start button of keyless operation key or cellular phone.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "In the same way as the keyless operation key, the engine can be started by operating a cellular phone using the telematics system function.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine Start Procedures", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The following operation enables the engine to be started.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Perform engine start operation using a cellular phone.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine does not start while the vehicle is in the following status.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "All doors are UNLOCK or any door is open.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Hood is open.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "A registered keyless operation key is in passenger room.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Shift position is other than P.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Vehicle security alarm is in operation.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Hazard light is in operation.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine Stop Procedures", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The following operation enables the engine to be stopped.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Press remote engine start button of keyless operation key.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Perform engine stop operation using a cellular phone.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Push-button ignition switch is operated.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Engine stops when the vehicle status changes to the following status.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "10 minutes are passed since engine start.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Shift position is shifted to a position other than P.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Vehicle security alarm starts to operate.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "While engine is in operation by keyless operation key, engine operation time can be extended for 10 minutes. To extend engine operation time, press LOCK button of keyless operation key, and then within 5 seconds, press and hold remote engine start button of keyless operation key for 2 seconds or more.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "Operation Area", "title");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The engine can be started when the vehicle is under the following conditions.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The remote engine start operating range is approximately 60 m (197 ft.) from the vehicle.", "ptxt");
si[i++] = gsitm("N5110202T0001U00ENG.html", "The vehicle is within the communication range of the Infiniti Connection™ data center.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Door switch", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Door switch detects door switch condition and then transmits door switch signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Stop light switch", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Stop light switch detects that brake pedal is depressed, and then transmits stop light switch signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "ABS actuator and electric unit (control unit) transmits the vehicle speed signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "TCM receives the P/N position signal from transmission range switch, and then transmits the shift position signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "ECM controls the engine.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When ignition switch is turned ON, keyless operation key unit starts communication with ECM and performs the ID verification between keyless operation key unit and ECM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "If the verification result is OK, the engine can start. If the verification result is NG, the engine cannot start.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Starter cut relay is controlled by BCM, and starter relay is controlled by IPDM E/R while communicating with BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When BCM receives a starter cut relay request signal from ECM, the starter cut relay is turned ON.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Push-button ignition switch", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Push switch", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Push-button ignition switch has push switch inside which detects that push-button ignition switch is pressed, and then transmits the push switch signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key unit changes the ignition switch position with the operation of push-button ignition switch.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key unit maintains the ignition switch position status while push-button ignition switch is not operated.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "NATS antenna amp.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Refer to", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "The keyless operation key system is a system that makes it possible to lock and unlock the door locks (door lock/ unlock function) by carrying the keyless operation key, which operates based on the results of electronic ID verification using two-way communication between the keyless operation key and the vehicle (keyless operation key unit).", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key unit controls VEHICLE IMMOBILIZER SYSTEM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Keyless operation key unit performs the ID verification between keyless operation key unit and keyless operation key when the keyless operation key is carried into the detection area of inside key antenna, and push-button ignition switch is pressed. If the ID verification result is OK, ignition switch operation is available.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Then, when the ignition switch is turned ON, keyless operation key unit performs ID verification between keyless operation key unit and ECM. If the ID verification result is OK, ECM can start engine.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "BCM INPUT/OUTPUT SIGNAL CHART", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Input Signal Item", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Transmit unit", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Signal name", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "CAN communication", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Engine status signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Starter cut relay request signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Ignition ON signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Starter cut relay status signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Neutral position signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Vehicle speed signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Shift position signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Each door switch", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Door switch signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Stop light switch signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Output Signal Item", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Reception unit", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "KEYLESS OPERATION KEY UNIT INPUT/OUTPUT SIGNAL CHART", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Key ID signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Inside key antenna", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Key ID request signal", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "The VEHICLE IMMOBILIZER SYSTEM prevents the engine from being started by keyless operation key whose ID is not registered to the vehicle (keyless operation key unit). It has higher protection against auto theft involving the duplication of mechanical keys.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "The ignition key integrated in the keyless operation key cannot start the engine. When the keyless operation key battery is discharged, the NATS ID verification is performed between the transponder integrated with keyless operation key and keyless operation key unit via NATS antenna amp. when the keyless operation key backside is contacted to push-button ignition switch while brake pedal is depressed. If the verification result is OK, the engine start operation can be performed by the push-button ignition switch operation.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "Up to 4 keyless operation keys can be registered (including the standard ignition key) upon request from the owner.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When replacing ECM, keyless operation key unit or keyless operation key, the specified procedure (Initialization and registration) using M.U.T.-III SE is required.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "PRECAUTIONS FOR KEY REGISTRATION", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "The ID registration is a procedure that erases the current NATS ID once, and then registers a new ID. Therefore before starting the registration operation, collect all registered keyless operation keys from the customer.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "ENGINE START OPERATION WHEN KEYLESS OPERATION KEY IS CONTACTED TO PUSH-BUTTON IGNITION SWITCH", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When brake pedal is depressed while selector lever is in the P position, keyless operation key unit activates NATS antenna amp. that is located behind push-button ignition switch.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When keyless operation key (transponder built-in) backside is contacted to push-button ignition switch, keyless operation key unit starts NATS ID verification between keyless operation key unit and keyless operation key (transponder built-in) via NATS antenna amp.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When the ignition switch is turned to ON, keyless operation key unit performs ID verification with the ECM. When the result is OK, engine start is permitted.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "BCM detects that the selector lever position and brake pedal operation condition.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When ECM detects that the start engine conditions* are satisfied, it transmits a starter cut relay request signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When starter cut relay is turned ON, IPDM E/R turns ON the starter relay and drives the starter motor.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When BCM receives an engine status signal from ECM, it turns the starter relay and starter cut relay OFF and stops cranking.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "*: For the engine start condition, refer to \"IGNITION SWITCH POSITION CHANGE TABLE BY PUSH-BUTTON IGNITION SWITCH OPERATION\" below.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "IGNITION SWITCH POSITION CHANGE TABLE BY PUSH-BUTTON IGNITION SWITCH OPERATION", "title");
si[i++] = gsitm("N5110202T0001V00ENG.html", "The ignition switch position can be changed by the following operations.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When an keyless operation key is within the detection area of inside key antenna or when keyless operation key backside is contacted to push-button ignition switch, it is equivalent to the operations below.", "ptxt");
si[i++] = gsitm("N5110202T0001V00ENG.html", "When starting the engine, the BCM monitors under the engine start conditions.", "ptxt");
