si[i++] = gsitm("N5110202T0001V00ENG.html", "If the keyless operation key unit cannot detect that the keyless operation key is in the vehicle, ignition switch can be turned OFF by the press and hold the push-button ignition switch for 2 seconds or more.", "ptxt");
