si[i++] = gsitm("N5110202T0001W00ENG.html", "Door switch detects door open/close condition and then transmits door switch signal to BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "IPDM E/R operates horns with horn request signal received from BCM.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "BCM controls VEHICLE SECURITY SYSTEM.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "BCM transmits horn request signal intermittently to IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When the security control system is activated, BCM blinks the turn-signal light.", "ptxt");
