si[i++] = gsitm("N5110202T0001W00ENG.html", "Push-button ignition switch has push switch inside which detects that push-button ignition switch is pressed, and then transmits the signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Keyless operation key unit changes the ignition switch position with the operation of push-button ignition switch.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Keyless operation key unit maintains the ignition switch position status while push-button ignition switch is not operated.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Keyless operation key", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "The keyless operation key system is a system that makes it possible to lock and unlock the door locks (door lock/unlock function) by carrying the keyless operation key, which operates based on the results of electronic ID verification using two-way communication between the keyless operation key and the vehicle (keyless operation key unit).", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Outside key antenna", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Outside key antenna detects whether keyless operation key is within the detection area or not, and then transmits signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Door request switch", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Door request switch transmits door lock/unlock request signal to keyless operation key unit.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hood switch", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Horn", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Theft warning alarm function activates horns intermittently when BCM detects that any door or hood is opened by unauthorized means, while the system is in the ARMED state.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Keyless operation key unit performs the ID verification between keyless operation key unit and keyless operation key when the keyless operation key is carried into the detection area of NATS antenna amp., and push-button ignition switch is pressed. If the ID verification result is OK, ignition switch operation is available.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hands free sensor control unit", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hands free sensor control unit judges user operation by detecting the hands free sensor.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hands free sensor", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hands free sensor detects when the user performs kick motion toward rear bumper.", "ptxt");
