si[i++] = gsitm("N5110202T0001W00ENG.html", "Each door request switch", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Door request switch signal", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hands free sensor signal", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Output Signal Item", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Reception unit", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Horn request signal", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Outside key antenna signal", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "THEFT WARNING ALARM", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "The theft warning alarm function activates horns and turn-signal lights intermittently when BCM detects that any door, hood or back door is opened by unauthorized means, while the system is in the ARMED state.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Operation Flow", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "No.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "System state", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Switching condition", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "DISARMED to PRE-ARMED", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When all conditions of A and one condition of B is satisfied.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "A", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "B", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Ignition switch: OFF", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "All doors: Closed", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "All doors are locked by:", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "LOCK button of keyless operation key", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "PRE-ARMED to ARMED", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When none of the following conditions are satisfied for 30 seconds.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "UNLOCK button of keyless operation key: ON", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Door request switch: ON", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Automatic back door open: Hands free sensor or automatic back door button of keyless operation key", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "ARMED to ALARM", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When one of the following condition is satisfied.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Any door: Closed to open", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "Hood: Closed to open", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "PRE-ARMED to DISARMED", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "ARMED to", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "DISARMED", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "ALARM to", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "RE-ALARM", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When one of the following condition is satisfied after the ALARM operation is finished. (Three times at maximum.)", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "To lock/unlock all doors by operating remote controller button of keyless operation key or door request switch, keyless operation key must be within the detection area of outside key antenna. For details, refer to .", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "DISARMED Phase", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "The vehicle security system is not set in the DISARMED phase. The vehicle security system stays in this phase while Any door other than back door is open, because it is assumed that the owner is inside or nearby the vehicle.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "When the vehicle security system is reset, each phase switches to the DISARMED phase directly.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "PRE-ARMED Phase", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "The PRE-ARMED phase is the transient state between the DISARMED phase and the ARMED phase. This phase is maintained for 30 seconds, so that the owner can reset the setting due to a mis-operation. This phase switches to the ARMED phase when vehicle conditions are not changed for 30 seconds.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "To reset the PRE-ARMED phase, refer to the switching condition of No. 4 in the table above.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "ARMED Phase", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "The vehicle security system is set, and BCM monitors all necessary inputs. If any door or hood is opened without using keyless operation key, vehicle security system switches to the ALARM phase.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "To reset the ARMED phase, refer to the switching condition of No. 5 in the table above.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "ALARM Phase", "title");
si[i++] = gsitm("N5110202T0001W00ENG.html", "BCM transmits \"horn request\" signal intermittently to IPDM E/R via CAN communication. In this phase, horns and turn-signal lights are activated intermittently for approximately 27 seconds to warn that the vehicle is accessed by unauthorized means. After 27 seconds, the vehicle security system returns to the ARMED phase. At this time, if BCM still detects unauthorized access to the vehicle, the system is switched to the ALARM phase again. This RE-ALARM operation is carried out a maximum of 3 times.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "To cancel the ALARM operation, refer to the switching condition of No. 6 in the table above.", "ptxt");
si[i++] = gsitm("N5110202T0001W00ENG.html", "If a battery terminal is disconnected during the ALARM phase, theft warning alarm stops. But when the battery terminal is reconnected, theft warning alarm is activated again.", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Remote Engine Start Information", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "DESIGN/PURPOSE", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Information display informs the driver that the engine can be started.", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Symbol", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Message", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Push brake and start switch to drive", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "SYNCHRONIZATION WITH MASTER WARNING LIGHT", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "No applicable", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "BCM transmits meter display signal to combination meter via CAN communication when remote engine run mode.", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "When combination meter receives meter display signal, combination meter display remote engine start information.", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "WARNING/INDICATOR OPERATION CONDITION", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "During remote engine run mode.", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "For details, refer to .", "ptxt");
si[i++] = gsitm("N5110203E0000J00ENG.html", "WARNING/INDICATOR CANCEL CONDITION", "title");
si[i++] = gsitm("N5110203E0000J00ENG.html", "Mode switch to normal engine run mode from remote engine run mode.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "M.U.T.-III SE Function (BCM - THEFT ALM)", "title");
si[i++] = gsitm("N5110203H0000C00ENG.html", "DATA MONITOR", "title");
si[i++] = gsitm("N5110203H0000C00ENG.html", "The following table includes information (items) inapplicable to this vehicle. For information (items) applicable to this vehicle, refer to M.U.T.-III SE display items.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Monitored item", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "DOOR SW-DR", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of front door switch LH.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Door switch AS", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of front door switch RH.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "DOOR SW-RR", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of rear door switch RH.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "DOOR SW-RL", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of rear door switch LH.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "CDL LOCK SW", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of lock signal from door lock/unlock switch.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "CDL UNLOCK SW", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "Indicates [On/Off] condition of unlock signal from door lock/unlock switch.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "IGN SW", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "This item is indicated, but not monitored.", "ptxt");
si[i++] = gsitm("N5110203H0000C00ENG.html", "START SW", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "List of ECU Reference", "title");
si[i++] = gsitm("N5110203J0000M00ENG.html", "ECU", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Values On The Diagnosis Tool", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Physical Values", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Fail-safe", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "DTC Inspection Priority Chart", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "DTC Index", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Reference Value", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5110203J0000M00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Record DTC and freeze frame data (Print them out using M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Are any symptoms described and any DTC detected?", "question");
si[i++] = gsitm("N511020300000C00ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Also study the normal operation and fail-safe related to the symptom.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again. At this time, always connect M.U.T.-III SE to the vehicle, and check self diagnostic results in real time.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "If two or more DTCs are detected, refer to DTC Inspection Priority Chart and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N511020300000C00ENG.html", "YES", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "NO", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Is the symptom described?", "question");
si[i++] = gsitm("N511020300000C00ENG.html", "Monitor input data from related sensors or check voltage of related module terminals using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Check DTC. If DTC is detected, erase it.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N511020300000C00ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is repaired securely.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N511020300000C00ENG.html", "YES-1", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "YES-2", "result");
si[i++] = gsitm("N511020300000C00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N511020300000C00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "Description", "title");
si[i++] = gsitm("N511020110005F00ENG.html", "Performing the following procedure can automatically activate recommunication of ECM and keyless operation key unit, but only when the ECM is replaced with a new one*. For details, refer to .", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "*: New one means a virgin ECM that has never been energized on-board.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "(In this step, initialization procedure using M.U.T.-III SE is not necessary)", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "When replacing the ECM, always replace it with a new one.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "The functions controlled by the ECM does not operate properly in case of reuse of the ECM from another vehicle.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "When the replaced ECM is not a brand new, the specified procedure (Initialization of keyless operation key unit and registration of keyless operation keys) using M.U.T.-III SE is necessary.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "If multiple keys are attached to the key holder, separate them before beginning work.", "ptxt");
si[i++] = gsitm("N511020110005F00ENG.html", "Distinguish keys with unregistered key IDs from those with registered IDs.", "ptxt");
si[i++] = gsitm("N511020320000L00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511020320000L00ENG.html", "PERFORM ECM RECOMMUNICATING FUNCTION", "title");
si[i++] = gsitm("N511020320000L00ENG.html", "Install ECM.", "ptxt");
si[i++] = gsitm("N511020320000L00ENG.html", "Contact backside of the registered keyless operation key* to push-button ignition switch while brake pedal is depressed, then turn ignition switch ON.", "ptxt");
