si[i++] = gsitm("N5110204N0000100ENG.html", "Security control system component parts", "title");
si[i++] = gsitm("N5110204N0000100ENG.html", "Front combination light assembly (refer to ).", "ptxt");
si[i++] = gsitm("N5110204N0000100ENG.html", "Door mirror assembly (refer to ).", "ptxt");
si[i++] = gsitm("N5110204N0000100ENG.html", "Rear combination light assembly (refer to ).", "ptxt");
si[i++] = gsitm("N5110204N0000100ENG.html", "Horn (refer to ).", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N511030350000I00ENG.html", "The Supplemental Restraint System such as “AIR BAG” and “SEAT BELT PRE-TENSIONER”, used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "Information necessary to service the system safely is included in the “SRS AIR BAG” and “SEAT BELT” of this Service Manual.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see “SRS AIR BAG”.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N511030350000I00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N511030350000I00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N511030360000C00ENG.html", "Precaution for Procedure without Cowl Top Cover", "title");
si[i++] = gsitm("N511030360000C00ENG.html", "When performing the procedure after removing cowl top cover, cover the lower end of windshield with urethane, etc to prevent damage to windshield.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N511030370000O00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N511030370000O00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N511030370000O00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Service", "title");
si[i++] = gsitm("N511030380000C00ENG.html", "Disconnect battery negative terminal in advance.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Disconnect air bag system line in advance.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Never tamper with or force air bag lid open, as this may adversely affect air bag performance.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Be careful not to scratch pad and other parts.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "When removing or disassembling any part, be careful not to damage or deform it. Protect parts, that may get in the way with a shop cloth.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "When removing parts with a screwdriver or other tool, cover the tool surface with vinyl tape to protect parts.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Keep removed parts protected with a shop cloth.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "If a clip is deformed or damaged, replace it.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "If an unreusable part is removed, replace it with a new one.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Tighten bolts and nuts firmly to the specified torque.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "After reassembly is complete, check that each part functions correctly.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Remove stains via the following procedure.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Water-soluble stains:", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Dip a soft cloth in warm water, and then squeeze it tightly. After wiping off the stain, wipe with a soft dry cloth.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Oil stain:", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Dissolve a synthetic detergent in warm water (density of 2 to 3%), dip the cloth, then wipe off the stain with the cloth. Next, dip the cloth in fresh water and squeeze it tightly. Then wipe off the detergent completely. Then wipe the area with a soft dry cloth.", "ptxt");
si[i++] = gsitm("N511030380000C00ENG.html", "Never use any organic solvent, such as thinner or benzine.", "ptxt");
