si[i++] = gsitm("N511210040000900ENG.html", "LUBRICANT", "title");
si[i++] = gsitm("N511210040000900ENG.html", "Item", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "Specified lubricant", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "Quantity", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "Degrease agent", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "Grease and dirt removal from parts surface", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "Mitsubishi Motors Genuine Parts Cleaner (MZ100387) or equivalent", "ptxt");
si[i++] = gsitm("N511210040000900ENG.html", "As required", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "GENERAL INFORMATION", "title");
si[i++] = gsitm("N511210060000900ENG.html", "The windshield glass, side window glass and liftgate window glass are attached by an urethane-base adhesive to the window frame. This adhesive provides improved glass holding and sealing, and also gives body openings a greater structural strength.", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "ITEMS", "title");
si[i++] = gsitm("N511210060000900ENG.html", "Name", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Remark", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Adhesive", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "3M™ AAD Part No.8609 Super Fast Urethane or equivalent", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Primer", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "3M™ AAD Part No.8608 Super Fast Urethane Primer or equivalent", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Spacers", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Available as service part", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Dam", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Anti-rust solvent (or Tectyl 506T.Valvoline Oil Company)", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "For rust prevention", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Degrease agent", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Mitsubishi Motors Genuine Parts Cleaner (MZ100387) or equivalent (For grease and dirt removal from bonded surface)", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Steel piano wire", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Dia. × length. 0.6mm × 1m (For cutting adhesive)", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Glass adhesive knife", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "For cutting adhesive", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "Adhesive gun", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "For pressing-out adhesive", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "HANDLING OF AUTO WINDOW SEALER", "title");
si[i++] = gsitm("N511210060000900ENG.html", "Keep the sealant in a cool place, not exposed to the direct rays of the sun. Do not place any heavy article on the sealant nor press it, otherwise it will become deformed. Avoid storing the sealant for more than 6 months, because it will lose its sealing effect.", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "BODY PINCH-WELD FLANGE SERVICING", "title");
si[i++] = gsitm("N511210060000900ENG.html", "Before servicing the body pinch-weld flange, remove old adhesive completely. If the flange requires painting, bake it after painting is completed.", "ptxt");
si[i++] = gsitm("N511210060000900ENG.html", "WINDOW GLASS INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Whenever you removal the windshield, calibrate its front camera unit (Refer to Camera Aiming Adjustment ) &lt;Vehicles with multi around monitor>.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Front Pillar Finisher Removal and Installation (Refer to Front Pillar Finisher/Rear Fender Sash Molding ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Front Deck Garnish Removal and Installation (Refer to Front Wiper ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Front Camera Unit Removal and Installation (Refer to Front Camera Unit ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Inside Mirror Assembly Removal and Installation (Refer to Inside Mirror ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Front Pillar Garnish Removal and Installation (Refer to Interior Trim ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Wiper Deicer Connector Disconnection and Connection.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Removal steps", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", ">>B&lt;&lt;", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Windshield glass", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Windshield spacer A", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Windshield spacer B", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Windshield glass stopper", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "&lt;&lt;A>> WINDSHIELD GLASS REMOVAL", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "In order to protect the body (paint surface), apply a cloth tape to the body area along the windshield glass opening.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "When separating adhesive using a piano wire.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use a knife to cut away the moulding.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use a sharp-point drill to make a hole in the windshield adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Pass the piano wire from the inside of the vehicle through the hole.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Do not damage the wiper deicer wire harness.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Do not let the piano wire touch the edge of the windshield glass.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Pull the piano wire alternately from the inside and outside along the windshield glass to cut away the adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "When cutting away adhesive using a windshield knife.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Using glass adhesive knife.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "If you lever the glass adhesive knife, the windshield glass may be damaged.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Holding the tip of the glass adhesive knife and the windshield glass edge at right angles, align the blade of the glass adhesive knife with the windshield glass surface and edge, and pull the blade parallel to the edge to cut away the adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Make mating marks on the windshield glass and body, and use the special tool glass holder (MB990480) to remove the windshield glass.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Be careful not to cut away more adhesive than is necessary.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Be careful also not to damage the paintwork on the body surface with the knife. If the paintwork is damaged, repair the damaged area with repair paint or anti-rust agent.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use a knife to cut away the remaining adhesive so that the thickness is within 2 mm around the entire circumference of the body flange.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Finish the flange surfaces so that they are smooth.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "If the windshield glass is reused, scrape away all traces of old adhesive, the glass stopper, and the windshield spacer.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", ">>A&lt;&lt; WINDSHIELD GLASS STOPPER/WINDSHIELD SPACER A/WINDSHIELD SPACER B INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Before the next operation, leave the decreased parts for 3 minutes or more to dry. Do not touch the coated surface.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use parts cleaner (MZ100387 or equivalent) to degrease the inside circumference of the windshield glass and the body flanges.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Position the windshield spacer A and spacer B, ensuring that there are no bends or looseness inside the windshield glass.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Secure the glass stoppers to the specified positions on the windshield glass.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", ">>B&lt;&lt; WINDSHIELD GLASS INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "To replace the windshield glass, temporarily set the windshield glass against the body, and place mating marks on the body and windshield glass.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "The primer strengthens the adhesive, so be sure to apply it. However, too thick application will weaken the adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Do not touch the coated surface.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Do not apply the primer on the remaining adhesive. The adhesive strength may be weakened.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Soak a sponge in the primer, and apply evenly to the windshield glass and the body in the specified places.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "After applying the primer, let it dry for 3 minutes or more.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Fill a sealant gun with adhesive. Then apply the adhesive evenly around the windshield glass within 30 minutes after the primer application.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Cut the tip of the sealant gun nozzle into a V-shape to simplify adhesive application.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "After applying the adhesive, align the mating marks on the windshield glass and the body, and then press the windshield glass gently to seat it.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use spatula or the like to remove any excessive adhesive. Then clean the surface with parts cleaner (MZ100387 or equivalent). Leave the vehicle stationary until the adhesive sets (Refer to Window Glass Installation ).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Move the vehicle carefully.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "When testing for water leakage, do not pinch the end of the hose to spray the water.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Wait 30 minutes or more, and then test for water leakage.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "INSPECTION EMBLEM REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Use your hands or a plastic spatula to remove the inspection emblem.", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Remove the remaining adhesive using diluted mild detergent for home use or inorganic solution (alcohol).", "ptxt");
si[i++] = gsitm("N5110303I0004L00ENG.html", "Attach the new inspection emblem to the specified position.", "ptxt");
si[i++] = gsitm("N5110301W0001500ENG.html", "Inspection", "title");
si[i++] = gsitm("N5110301W0001500ENG.html", "WATER LEAKAGE INSPECTION", "title");
si[i++] = gsitm("N5110301W0001500ENG.html", "Dry adhesive according to the specification of adhesive kit, do the leaking check when adhesive is stiffen.", "ptxt");
si[i++] = gsitm("N5110301W0001500ENG.html", "If leakage was found, start over from the beginning as windshield glass removal, install and leaking check.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "REMOVAL AND INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Luggage Side Upper Finisher Removal and Installation (Refer to Luggage Trim  &lt;Vehicles for 7 Persons>,  &lt;Vehicles for 5 Persons>).", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Rear Fender Sash Moulding Outer Removal and Installation (Refer to Front Pillar Finisher/Rear Fender Sash Moulding ).", "ptxt");
