si[i++] = gsitm("N5110303I0004E00ENG.html", "Side window glass", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "&lt;&lt;A>> SIDE WINDOW GLASS ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "In order to protect the body (paint surface), apply the protective tapes to body area around the installed side window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Stick the protective tapes to avoid the side window glass assembly from dropping.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Using glass adhesive knife.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Working inside the vehicle, insert the tip of a windshield knife into the sealed part of the side window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "If you lever the windshield knife, the side window glass assembly may be damaged.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Holding the tip of the glass adhesive knife and the body flange at right angles, align the blade of the windshield knife with the body flange, and pull the blade parallel to the body flange to separate the adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Use a piano wire to separate the clips.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Make mating marks on the side window glass assembly and body, and use special tool glass holder (MB990480) to remove the side window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Be careful not to cut away more adhesive than is necessary.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Be careful also not to damage the paintwork on the body surface with the knife. If the paintwork is damaged, repair the damaged area with touch-up paint or anti-rust agent.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Use a knife to cut away the remaining adhesive so that the thickness is within 2 mm around the entire circumference of the body flange.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Finish the flange surfaces so that they are smooth.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "If the side window glass assembly is reused, scrape away all traces of old adhesive from the side window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", ">>A&lt;&lt; SIDE WINDOW FASTENER INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "If the side window glass assembly is reused, follow the procedures below.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Engage the clip with the body.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Cut off the convex portion of the side window glass assembly clip installation position.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "If the side window glass assembly is installed without cutting off the convex portion of the side window glass assembly clip installation position, improper installation may result.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Before the next operation, leave the decreased parts for 3 minutes or more to dry. Do not touch the degreased parts.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Use parts cleaner (MZ100387 or equivalent) to degrease the inside circumference of the side window glass assembly and the body flanges.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Install the side window fastener to the specified positions on the body flange.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Install the side window fastener to the side window glass assembly at the positions which correspond to the fasteners on the body flange.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", ">>B&lt;&lt; SIDE WINDOW SPACER INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Install the spacer to the specified positions on the side window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", ">>C&lt;&lt; SIDE WINDOW GLASS ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Apply the primer and adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004E00ENG.html", "Install the side window glass assembly by the same procedures as for the windshield glass (Refer to ).", "ptxt");
si[i++] = gsitm("N5110301W0001400ENG.html", "Inspection", "title");
si[i++] = gsitm("N5110301W0001400ENG.html", "WATER LEAKAGE INSPECTION", "title");
si[i++] = gsitm("N5110301W0001400ENG.html", "Dry adhesive according to the specification of adhesive kit, do the leaking check when adhesive is stiffen.", "ptxt");
si[i++] = gsitm("N5110301W0001400ENG.html", "If leakage was found, start over from the beginning as side window glass removal, install and leaking check.", "ptxt");
