si[i++] = gsitm("N5110303I0004M00ENG.html", "&lt;&lt;A>> LIFTGATE WINDOW GLASS ASSEMBLY REMOVAL", "title");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Remove the liftgate window glass assembly by the same procedures as for the windshield glass (Refer to ).", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Use a piano wire to remove the liftgate window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N5110303I0004M00ENG.html", ">>A&lt;&lt; LIFTGATE LOWER DAM/LIFTGATE WINDOW GLASS STOPPER/LIFTGATE WINDOW FASTENER/LIFTGATE SPACER INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Use the parts cleaner (MZ100387 or equivalent) to degrease the inside circumference of the liftgate window glass assembly and liftgate flanges.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Peel off the protection sheet on the back of the liftgate lower dam and paste it to the specified position on the liftgate window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Install the liftgate glass stopper and liftgate window fastener to the specified position on the liftgate window glass assembly.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Install the fasteners to the specified positions on the liftgate flange.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", ">>B&lt;&lt; LIFTGATE WINDOW GLASS ASSEMBLY INSTALLATION", "title");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Apply the primer and adhesive.", "ptxt");
si[i++] = gsitm("N5110303I0004M00ENG.html", "Install the liftgate window glass assembly by the same procedure as for the windshield glass (refer to ).", "ptxt");
si[i++] = gsitm("N5110301W0001600ENG.html", "Inspection", "title");
si[i++] = gsitm("N5110301W0001600ENG.html", "WATER LEAKAGE INSPECTION", "title");
si[i++] = gsitm("N5110301W0001600ENG.html", "Dry adhesive according to the specification of adhesive kit, do the leaking check when adhesive is stiffen.", "ptxt");
si[i++] = gsitm("N5110301W0001600ENG.html", "If leakage was found, start over from the beginning as liftgate window glass removal, install and leaking check.", "ptxt");
