si[i++] = gsitm("N511220060000H00ENG.html", "DOOR WINDOW GLASS ADJUSTMENT", "title");
si[i++] = gsitm("N511220060000H00ENG.html", "Check that a door window glass operates smoothly and moves along the door window glass runchannel when the window glass is fully raised and lowered. If there is a problem, adjust the window glass by the following procedures:", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Remove a door finisher assembly (Refer to Door Finisher ).", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Remove the plug from the service hole.", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Remove the working hole rear cover (Refer to ).", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Remove the power window switch from the removed door trim assembly, and connect it to the door side connector.", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Set the glass holder mounting bolts to the service hole.", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Raise the window glass with the power window switch to check that the window glass to door clearance is even. If there is a problem, loosen the glass holder mounting bolts to adjust tilting up/down of the glass.", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Install the plug from the service hole.", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Install the working hole rear cover (Refer to ).", "ptxt");
si[i++] = gsitm("N511220060000H00ENG.html", "Install the door finisher assembly (Refer to Door Finisher ) .", "ptxt");
