si[i++] = gsitm("N511040380000K00ENG.html", "Power Window Main Switch", "title");
si[i++] = gsitm("N511040380000K00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N511040380000K00ENG.html", "Power window main switch controls all power window motors.", "ptxt");
si[i++] = gsitm("N511040380000K00ENG.html", "Power window lock switch inhibits power window operation rear power window.", "ptxt");
