si[i++] = gsitm("N5110402T0001000ENG.html", "BCM controls the power window relay and controls the ignition ON power source supplied to each power window switch.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Power window system is activated by power window switch when ignition switch turns ON or retained power is operating.", "ptxt");
