si[i++] = gsitm("N5110402T0001000ENG.html", "POWER WINDOW AUTO-OPERATION (FRONT DRIVER SIDE)", "title");
si[i++] = gsitm("N5110402T0001000ENG.html", "AUTO UP/DOWN operation can be performed when power window main switch turns to AUTO.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Power window main switch transmits AUTO UP/DOWN signal to front power window motor (driver side) and operating the front power window motor (driver side) turns to AUTO.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Front power window motor (driver side) reads the changes of operating condition and stops AUTO operation when door glass is at fully opened/closed position.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "RETAINED POWER FUNCTION", "title");
si[i++] = gsitm("N5110402T0001000ENG.html", "Retained power function is an additional power supply function that enables power window system to operate for 45 seconds after ignition switch turns OFF.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "RETAINED POWER FUNCTION CANCEL CONDITIONS", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Any of the following condition is satisfied.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Front door CLOSE → OPEN.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "When ignition switch turns ON again.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "When timer times out. (45 seconds)", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "LIN COMMUNICATION (FRONT DRIVER SIDE)", "title");
si[i++] = gsitm("N5110402T0001000ENG.html", "Front power window motor (driver side), power window main switch and BCM transmit and receive signal by LIN communication.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "POWER WINDOW LOCK", "title");
si[i++] = gsitm("N5110402T0001000ENG.html", "Ground circuit inside power window main switch shuts off when power window lock switch is ON. This inhibits rear power window switch operation.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "ANTI-PINCH SYSTEM (FRONT DRIVER SIDE)", "title");
si[i++] = gsitm("N5110402T0001000ENG.html", "Pinch foreign material in the door glass during AUTO-UP operation, and it is the anti-pinch function that lowers the door glass when detected.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "CPU continues detecting the movement of front power window motor (driver side) while front power window motor (driver side) is operating.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Front power window motor (driver side) controls to lower the door glass for approximately 150 mm (5.91 in) or more after it detects foreign material is trapped in the door glass.", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "OPERATION CONDITION", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "When door glass AUTO-UP operation is performed (anti-pinch function does not operate just before the door glass closes and is fully closed)", "ptxt");
si[i++] = gsitm("N5110402T0001000ENG.html", "Depending on environment and driving conditions, if a similar impact or load is applied to the door glass, it may lower.", "ptxt");
