si[i++] = gsitm("N511040320002300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511040320002300ENG.html", "STEP 1", "title");
si[i++] = gsitm("N511040320002300ENG.html", "Close the door.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Continue pulling the power window switch UP until glass stops at fully closed position then release the switch. *1", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Keep pulling the switch for 5 seconds or more. *2", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Continue pressing the power window switch DOWN until glass stops then release the switch.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Keep pressing the switch for 5 seconds or more. *2", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "After glass moves again, keep pressing the switch until glass reaches the fully open position.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Continue pulling the power window switch UP (MANUAL-UP operation) until glass stops at fully closed position.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "Check that AUTO-UP function operates normally.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "*1: If the power window stops before reaching the fully closed position: After the power window stops, release the switch then continue pulling the switch UP again and move the power window to the fully closed position.", "ptxt");
si[i++] = gsitm("N511040320002300ENG.html", "*2: After keep pulling or pressing 5 seconds or more, glass moves again.", "ptxt");
