si[i++] = gsitm("N5110503D0000Q00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5110503D0000Q00ENG.html", "When sunroof motor assembly receives signal from sunroof switch assembly, it opens/closes or tilts up/down the sunroof . And transmits sunroof switch assembly signal to sunshade motor assembly via communication line.", "ptxt");
