si[i++] = gsitm("N5110502T0000P00ENG.html", "The sunroof motor assembly receives the signal from the sunroof switch assembly to operate the sunroof, and transmits the signal from the sunroof switch assembly to the sunshade motor assembly via communication line.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "The sunshade motor assembly operates the sunshade with the operate signal received from the sunroof switch assembly or the communication line received from the sunroof motor assembly.", "ptxt");
