si[i++] = gsitm("N5110502T0000P00ENG.html", "Sunroof: OPEN (Fully-open)", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Sunroof: Fully-open", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Sunroof: CLOSE (Fully-close)", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "AUTO OPERATION", "title");
si[i++] = gsitm("N5110502T0000P00ENG.html", "The sunroof and sunshade operates automatically by operating the sunroof switch assembly.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "If initialization setting is not performed, the automatic function does not operate.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "During automatic operation, when the sunroof switch assembly is operated, automatic operation can be stopped.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "RETAINED POWER FUNCTION", "title");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Retained power operation is an additional power supply function that enables sunroof system to operate for 45 seconds after ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "RETAINED POWER FUNCTION CANCEL CONDITIONS", "title");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Any of the following conditions is satisfied.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Front door CLOSE (door switch OFF)→OPEN (door switch ON)", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "When ignition switch is ON again.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "When timer time passes. (45 seconds)", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "LIN COMMUNICATION", "title");
si[i++] = gsitm("N5110502T0000P00ENG.html", "Sunroof motor assembly, sunshade motor assembly and BCM transmit and receive signal by LIN communication.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "ANTI-PINCH FUNCTION", "title");
si[i++] = gsitm("N5110502T0000P00ENG.html", "The sunroof motor assembly monitors the sunroof condition using the signals from sunroof motor. When sunroof motor assembly detects an interruption during auto operation (close or tilt down operation), sunroof motor will tilt up or open [150 mm (5.91 in) or more] sunroof.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "The sunshade motor assembly monitors the sunshade condition using the signals from sunshade motor. When sunshade motor assembly detects an interruption during auto close operation, sunshade motor will open [150 mm (5.91 in) or more] sunshade.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "There are some small distances immediately before the closed position which cannot be detected.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "If initialization setting is not performed, the anti-pinch function does not operate.", "ptxt");
si[i++] = gsitm("N5110502T0000P00ENG.html", "When the distance between pinching position and fully-open position is less than 150 mm (5.91 in), sunroof or sunshade reverses to fully-open position.", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5110501J0000O00ENG.html", "FAIL-SAFE CONTROL BY SUNROOF MOTOR ASSEMBLY", "title");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Sunroof motor assembly switches sunroof operation to fail-safe control when malfunction is detected.", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Detected item", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Judgment condition", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Fail-safe operation", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Recovery condition", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Non-Initialized condition", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "When the motor integrated CPU detect door glass position non-initialized condition", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Auto OPEN/CLOSE Tilt UP/DOWN operation (Anti-pinch) is forbidden", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Initialization completed", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Thermal protection", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "When the motor integrated CPU detect temperature increases and exceeds threshold", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Sunroof operation is forbidden", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Approximately 20 seconds or more passed then operate.", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "(Temperature returns to normal)", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "FAIL-SAFE CONTROL BY SUNSHADE MOTOR ASSEMBLY", "title");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Sunshade motor assembly switches sunshade operation to fail-safe control when malfunction is detected.", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Auto OPEN/CLOSE operation (Anti-pinch) is forbidden", "ptxt");
si[i++] = gsitm("N5110501J0000O00ENG.html", "Sunshade operation is forbidden", "ptxt");
