si[i++] = gsitm("N511050300001700ENG.html", "Work Flow", "title");
si[i++] = gsitm("N511050300001700ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N511050300001700ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N511050300001700ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Record DTC and freeze frame data (Print them out using M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Are any symptoms described and any DTC detected?", "question");
si[i++] = gsitm("N511050300001700ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Also study the normal operation and fail-safe related to the symptom.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again. At this time, always connect M.U.T.-III SE to the vehicle, and check self diagnostic results in real time.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "If two or more DTCs are detected, refer to DTC INSPECTION PRIORITY CHART, and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N511050300001700ENG.html", "YES", "result");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "NO", "result");
si[i++] = gsitm("N511050300001700ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Is the symptom described?", "question");
si[i++] = gsitm("N511050300001700ENG.html", "Monitor input data from related sensors or check voltage of related module terminals using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N511050300001700ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Check DTC. If DTC is detected, erase it.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N511050300001700ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is repaired securely.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N511050300001700ENG.html", "YES-1", "result");
si[i++] = gsitm("N511050300001700ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "YES-2", "result");
si[i++] = gsitm("N511050300001700ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N511050300001700ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N511050110004L00ENG.html", "Description", "title");
si[i++] = gsitm("N511050110004L00ENG.html", "Initialization of system should be conducted after the following conditions. Refer to .", "ptxt");
si[i++] = gsitm("N511050110004L00ENG.html", "When the sunroof motor assembly or sunshade motor assembly is replaced.", "ptxt");
si[i++] = gsitm("N511050110004L00ENG.html", "When the sunroof or sunshade does not operate normally. (Incomplete initialization conditions)", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511050320001E00ENG.html", "PERFORM SYSTEM INITIALIZATION", "title");
si[i++] = gsitm("N511050320001E00ENG.html", "Close sunroof and sunshade.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Press and hold the sunroof switch CLOSE for approximately 10 seconds.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Sunroof and sunshade will move as following.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Sunroof tilt up, and the sunshade slightly close and stops.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Release the sunroof switch, and continue to press the sunroof switch CLOSE again soon.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Sunshade fully open → sunroof tilt down → sunroof fully open → sunroof fully closed → sunshade fully closed.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Release the sunroof switch after sunroof and sunshade stopped.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "GO TO 2", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "CHECK THE FUNCTION", "title");
si[i++] = gsitm("N511050320001E00ENG.html", "Check that sunroof and sunshade automatically operated normally.", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "Check anti-pinch function. Refer to .", "ptxt");
si[i++] = gsitm("N511050320001E00ENG.html", "END", "ptxt");
si[i++] = gsitm("N511050110004M00ENG.html", "Description", "title");
si[i++] = gsitm("N511050110004M00ENG.html", "Check anti-pinch function when the initialization of sunroof and sunshade system is performed. Refer to .", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N511050320001F00ENG.html", "CHECK ANTI-PINCH FUNCTION", "title");
si[i++] = gsitm("N511050320001F00ENG.html", "Fully open the sunroof.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Place a piece of wood near the fully closed position.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Close the sunroof completely with auto-slide closed.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Check that sunroof lowers for approximately 150 mm (5.91 in) without pinching a piece of wood and stops.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Fully open the sunshade.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Place a piece of wood near fully closed position.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Close the sunshade completely with auto-slide closed.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Check that sunshade lowers for approximately 150 mm (5.91 in) without pinching a piece of wood and stops.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "Never check with hands or another part of the body because they may be pinched. never get pinched.", "ptxt");
si[i++] = gsitm("N511050320001F00ENG.html", "When the distance between pinching position and fully-open position is less than 150 mm (5.91 in), sunroof or sunshade reverses to fully-open position.", "ptxt");
