si[i++] = gsitm("N511240010000E00ENG.html", "SUNROOF LEAKAGE CHECK", "title");
si[i++] = gsitm("N511240010000E00ENG.html", "Check the sunroof for leakage as follows:", "ptxt");
si[i++] = gsitm("N511240010000E00ENG.html", "Close the glass lid fully.", "ptxt");
si[i++] = gsitm("N511240010000E00ENG.html", "Using tap water, adjust the water pressure so that the height of water spouted out from the end of a hose is approximately 50 cm (19.7 inches) with the end of the hose facing up.", "ptxt");
si[i++] = gsitm("N511240010000E00ENG.html", "Apply tap water to the weatherstrip from approximately 30 cm (11.8 inches) above the roof surface for 5 minutes or longer.", "ptxt");
si[i++] = gsitm("N511240010000E00ENG.html", "While applying water, check the vehicle interior for any trace of leakage. If any leakage from around the glass lid is collected by the drip section, there is no problem.", "ptxt");
