si[i++] = gsitm("N5110504D000AC00ENG.html", "Install sunroof motor assembly and sunshade motor assembly in correct position without mistake.", "par2");
si[i++] = gsitm("N5110504D000AC00ENG.html", "Before installing the sunshade motor assembly, always place the link and wire of sunshade slider in the symmetrical and fully opened position.", "par3");
si[i++] = gsitm("N5110504D000AC00ENG.html", "Move the sunshade motor assembly laterally a little so that the gear is completely engaged into the wire on the sunroof unit assembly and mounting surface becomes parallel. Then secure the sunshade motor assembly with screws.", "ptxt");
