si[i++] = gsitm("N5110700U0000O00ENG.html", "Active grille shutter", "ptxt");
si[i++] = gsitm("N5110700U0000O00ENG.html", "For the engine related component parts, refer to &lt;PR25DD>, &lt;4B4>.", "ptxt");
si[i++] = gsitm("N5110703D0000C00ENG.html", "Active grille shutter", "title");
si[i++] = gsitm("N5110703D0000C00ENG.html", "Active grille shutter  is located at front bumper lower opening, and according to the signal from ECM it operates actuator to perform open/close movement of flap  to control the amount of air flow taken into engine compartment.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "System Description", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "While driving, the active grille shutter system closes shutter to reduce air flow to engine compartment for the purpose of reducing aerodynamic drag, and as a result, improves the vehicle\'s fuel efficiency.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "ECM controls active grille shutter system by detecting vehicle status through respective modules and sensors.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "Active grille shutter actuator is equipped with self-diagnosis function. When a malfunction is detected, a signal is transmitted to the ECM and the ECM records the active grille shutter malfunction.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "BASIC MOVEMENTS", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "S1: 30 km/h (19 MPH)", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "S2: Approx. 30 - 140 km/h (19 - 88 MPH)", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "*1: Shutter initial position learning", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "*2: Judgment of high vehicle speed", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "*3: Judgment of low vehicle speed", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "DESCRIPTION OF MOVEMENTS", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "Active grille shutter is fully open when the vehicle stops or the ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "ECM operates the shutter to close position in order to perform shutter\'s initial position learning whenever the ignition switch is turned OFF → ON and the engine is started. At the end of initial position learning ECM operates shutter to open position.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "While driving, after the initial position learning ends, ECM operates the active grille shutter to close position when the operational conditions of active grille shutter are met.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "While driving at high speed, ECM operates the shutter to open position when the vehicle reaches the specified speed in order to prevent the shutter from shutting up due to wind resistance.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "When the vehicle speed is reduced below the specified speed ECM operates active grille shutter to open position.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "When any one of the conditions for opening the active grille shutter is satisfied, ECM performs active grille shutter initial position learning even when the vehicle speed is less than 30 km/h.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "ECM may perform active grille shutter initial position learning according to other diagnosis conditions.", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "ACTIVE GRILLE SHUTTER OPERATIONAL CONDITIONS", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "ECM operates active grille shutter to close position when all of the following conditions are met.", "title");
si[i++] = gsitm("N5110702T0000C00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5110702T0000C00ENG.html", "Status", "ptxt");
