si[i++] = gsitm("N511280020000800ENG.html", "&lt;&lt;A>> FRONT BUMPER REINFORCEMENT LOWER REMOVAL", "title");
si[i++] = gsitm("N511280020000800ENG.html", "Remove all the front bumper reinforcement lower mounting bolts and nuts.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "Disengage the hook (View A) located on the mounting surface of the front bumper reinforcement lower on the vehicle left side, by the following procedures.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "Pull the vehicle right side of the front bumper reinforcement lower to the direction of the arrow (1) shown in the illustration and remove it from the front suspension member stud bolt.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "Lift the right side of the vehicle of the front bumper reinforcement lower by approximately 5° in the direction of arrow (2) shown in the figure.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "Be careful not to damage the peripheral parts when removing the front bumper reinforcement lower.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "Pull the front bumper reinforcement lower towards the vehicle front side and remove it.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "INSTALLATION SERVICE POINT", "title");
