si[i++] = gsitm("N511280020000800ENG.html", "Install the front bumper assembly in the order of the numbers shown in the figure.", "ptxt");
si[i++] = gsitm("N511280020000800ENG.html", "When installing the front bumper assembly to the front fender, align notch \"A\" on the front bumper assembly with rib \"A\" on the front bumper side bracket, and then install the front bumper assembly in the order of the numbers shown in the figure.", "ptxt");
