si[i++] = gsitm("N511280030000800ENG.html", "Use a drill [Φ 4.0 mm (0.16 inch) to make a hole in the rivet to break it, and remove the rivet.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "REASSEMBLY SERVICE POINT", "title");
si[i++] = gsitm("N511280030000800ENG.html", ">>A&lt;&lt; RIVETS INSTALLATION", "title");
si[i++] = gsitm("N511280030000800ENG.html", "Use a rivet tool shown as in the illustration to connect the parts with rivets by the following procedures:", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "Insert the rivet into a corresponding location (front bumper molding lower or license plate bracket, front bumper upper face).", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "Set the rivet tool at a portion A of rivet.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "While pushing the flange surface of the rivet onto parts to be fixed with the rivet tool, press the handle of the tool.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "Thin part of portion A of the rivet will be cut off and the part is fixed in position.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", ">>B&lt;&lt; FRONT BUMPER FACE PAD D/FRONT BUMPER FACE PAD C/FRONT BUMPER FACE PAD B/FRONT BUMPER FACE PAD A INSTALLATION &lt;VEHICLES WITH FRONT BUMPER FACE PAD>", "title");
si[i++] = gsitm("N511280030000800ENG.html", "Use Parts Cleaner (MZ100387 or equivalent) to clean the installation surfaces.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "Apply the 3M™ K-520 primer or equivalent to the installation surface.", "ptxt");
si[i++] = gsitm("N511280030000800ENG.html", "Install each front bumper face pad to the position shown in the illustration.", "ptxt");
