si[i++] = gsitm("N5110703I0000X00ENG.html", "Attach each mark to the position shown in the illustration.", "ptxt");
si[i++] = gsitm("N5110703I0000X00ENG.html", "Installation procedure", "ptxt");
si[i++] = gsitm("N5110703I0000X00ENG.html", "Use Mitsubishi Motors Genuine Parts Cleaner (MZ100387) or equivalent to clean the mark or decal installation surfaces on the body.", "ptxt");
si[i++] = gsitm("N5110703I0000X00ENG.html", "When attaching the mark or decal, the ambient temperature should be 20 - 38°C (68 - 100°F) and the air should be completely free of dust. If the ambient temperature is lower than 20°C (68°F), the mark, decal and the places on the vehicle body where the mark or decal are to be attached should be heated to 20 - 30°C (68 - 86°F).", "ptxt");
si[i++] = gsitm("N5110703I0000X00ENG.html", "Peel off the protection sheet on the back of the mark or decal to paste it on the installation position.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "Disconnect the 12V battery (–) terminal and wait for 60 seconds or more before starting work. Insulate the disconnected (–) terminal by wrapping a tape.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "The parts indicated by * indicates parts which should be temporarily tightened, and then fully tightened with the vehicle standing on the ground at curb weight.", "ptxt");
