si[i++] = gsitm("N511270010001J00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "&lt;&lt;A>> REAR FLOOR HOLE COVER/CLIP REMOVAL", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "Rotate the head of the clips from the locked state to the unlocked state and remove the rear floor hole cover.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "INSTALLATION SERVICE POINTS", "title");
si[i++] = gsitm("N511270010001J00ENG.html", ">>A&lt;&lt; CLIP/REAR FLOOR HOLE COVER INSTALLATION", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "Attach the unlocked clips to the floor, and place the rear floor hole cover over the clips. Then rotate the head of the clips from the unlocked state to the locked state and fix the rear floor hole cover.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", ">>B&lt;&lt; REAR WHEELHOUSE INNER PANEL BRACE INSTALLATION", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "The torque value differs depending on the strength class of the bolt. Therefore, refer to the tightening torque table to check which type of bolt is used, and tighten the bolt to the appropriate torque. (Refer to GENERAL INFORMATION – GENERAL INFORMATION – HOW TO USE THIS MANUAL – TIGHTENING TORQUE OF STANDARD BOLTS .)", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Strength class 8.8: 25 ± 3 N·m (18 ± 2 ft-lb)", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Strength class 10.9: 35 ± 5 N·m (26 ± 4 ft-lb)", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Temporarily hand tighten the bolt 1.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Press the rear wheelhouse inner panel brace toward the fastening surface of the bolt 2 and 3, clear the gap between the rear wheelhouse inner panel brace and the rear wheelhouse inner panel, and tighten the bolt 2 and 3.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Temporarily hand tighten the bolt 4 (9 places), and check whether the gap between the surface of the rear floor and the rear wheelhouse inner panel brace is cleared.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "If the gap between the surface of the rear floor and the rear wheelhouse inner panel brace is not cleared, repeat the step 2.", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", "Tighten the bolt 1 and the bolt 4 (9 places).", "ptxt");
si[i++] = gsitm("N511270010001J00ENG.html", ">>C&lt;&lt; HEADLIGHT SUPPORT UPPER PANEL INSTALLATION", "title");
si[i++] = gsitm("N511270010001J00ENG.html", "Tighten the headlight support upper panel bolts in the numerical order to 21 ± 3 N·m (16 ± 2 ft-lb).", "ptxt");
