si[i++] = gsitm("N511090AT0000300ENG.html", "SUPPLEMENTAL RESTRAINT SYSTEM (SRS)", "title");
si[i++] = gsitm("N511090AT0000300ENG.html", "Improper service or maintenance of any component of the SRS and any SRS-related component, can lead to personal injury or death to service personnel (from inadvertent firing of the air bag) or to the driver and passenger (from rendering the SRS inoperative).", "ptxt");
si[i++] = gsitm("N511090AT0000300ENG.html", "The SRS components and seat belt with pre-tensioner should not be subjected to heat, so remove the air bag diagnosis sensor unit, air bag modules, spiral cable, crush zone sensor, satellite sensor and seat belt with pre-tensioners before drying or baking the vehicle after painting.", "ptxt");
si[i++] = gsitm("N511090AT0000300ENG.html", "Service or maintenance of any SRS component and SRS-related component must be performed only at an authorized MITSUBISHI dealer.", "ptxt");
si[i++] = gsitm("N511090AT0000300ENG.html", "MITSUBISHI dealer personnel must thoroughly review workshop manual, and especially its SRS AIRBAG, before beginning any service or maintenance of any component of the SRS and any SRS-related component.", "ptxt");
