si[i++] = gsitm("N511090920000F00ENG.html", "BODY MAIN CROSS-SECTIONAL VIEWS", "title");
si[i++] = gsitm("N511090930000C00ENG.html", "SILENCER APPLICATION LOCATIONS", "title");
si[i++] = gsitm("N511090930000C00ENG.html", "A silencer (spray-type anti-vibration agent) have been adhered on the top part of the floor and the inside of the cowl top panel inner to improve anti-vibration performance and to shut out exhaust gas heat.", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "LOCATIONS USING URETHANE FOAM AND FOAM MATERIAL", "title");
si[i++] = gsitm("N511090940000C00ENG.html", "The sound dampening foam material may burn when heated. Always observe the following instructions:", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "Never use a gas burner to burn the areas where sound dampening foam material are used.", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "When cutting the parts which are provided with sound dampening foam material, ensure to use tools (air saw, etc.) that do not generate fire.", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "If there are residual sound dampening foam material remaining on the cut section (body side), remove the sound dampening foam material from periphery of the welding area before welding work.", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "The sound dampening foam material has been adopted to the upper and lower sections of the front pillar, roof side rail section, center pillar lower section, wheel house arch, and rear end inside to shield from external noise.", "ptxt");
si[i++] = gsitm("N511090940000C00ENG.html", "Urethane foam have been inserted into the center pillar lower section and quarter section to shield from external noise.", "ptxt");
si[i++] = gsitm("N511090950000I00ENG.html", "STIFFENER AND DAMP SHEET APPLICATION LOCATIONS", "title");
si[i++] = gsitm("N511090950000I00ENG.html", "A stiffener and a damping sheet are applied to enhance surface rigidity and sound insulation due to an anti-vibration effects.", "ptxt");
si[i++] = gsitm("N511090950000I00ENG.html", "The main contents of a stiffener are epoxy resin. It comes in a sheet form and contains a mixture of glass fiber and filler, and cures (stiffens) when heated.", "ptxt");
si[i++] = gsitm("N511090950000I00ENG.html", "No spare part of the stiffener for repair is available in the field. If the stiffener is damaged, replace it together with the panel.", "ptxt");
si[i++] = gsitm("N511090950000I00ENG.html", "&lt;EXCEPT VEHICLES FOR VIETNAM AND TAIWAN>", "title");
si[i++] = gsitm("N511090950000I00ENG.html", "&lt;VEHICLES FOR VIETNAM AND TAIWAN>", "title");
si[i++] = gsitm("N511090900000B00ENG.html", "GENERAL INFORMATION", "title");
si[i++] = gsitm("N511090900000B00ENG.html", "For the items not described, refer to \"FUNDAMENTALS\" and \"REPAIR INFORMATION\".", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "BODY DIMENSIONS AND MEASUREMENT METHODS", "title");
si[i++] = gsitm("N5110909E0000L00ENG.html", "Type B (actual-measurement dimensions) is the actual distance between the measurement points.Measure using a tracking gauge or a measuring tape, etc.", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "Make the lengths of the tracking gauge probes the same (A=A\').", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "Do not bend or twist the measuring tape.", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "Insert the tracking gauge probes securely into the measurement holes.", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "When the standard dimensions in the illustration are enclosed by rectangle, this indicates that the symmetrical left and right positions have the same dimensions.", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "When using a notch for dimension measurement, set the measuring point at the center of the notch.", "ptxt");
si[i++] = gsitm("N5110909E0000L00ENG.html", "The body center points are shown for the purpose of checking the position of the left and right symmetry location.", "ptxt");
