si[i++] = gsitm("N5110909P0000I00ENG.html", "ULTRA HIGH STRENGTH STEEL PLATE", "title");
si[i++] = gsitm("N5110909P0000I00ENG.html", "ADVANTAGES OF ULTRA HIGH STRENGTH STEEL PLATE", "title");
si[i++] = gsitm("N5110909P0000I00ENG.html", "The ultra high strength steel plate has the following advantages as compared with conventional high strength steel plate.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "It has tensile strength approximately 1.7 times higher than the conventional high strength steel sheet.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "It has a higher yielding point and yielding ratio (yielding point/tensile strength).", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "These advantages allow thinner and lighter plates and better fuel efficiency than the high strength steel plate.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "PRECAUTION UPON MAINTENANCE OF ULTRA HIGH STRENGTH STEEL PLATE", "title");
si[i++] = gsitm("N5110909P0000I00ENG.html", "Use a spot cutter for ultra high strength steel plate to ensure that the spot-welded area is cut off. The following tools are recommended.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "Drill bit, spot weld cutter (8) (Number: MB992621) &lt;Except 1500MPa-ultra-high-tensile steel panels>", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "Drill bit, spot weld cutter (8) (Number: MB993027) &lt;1500MPa-ultra-high-tensile steel panels>", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "The workability of cutting and drilling of the spot-welded area can be improved by applying lubricant (cutting oil) or the like to the tip of the drill bit.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "For the part in which the ultra high strength steel plate is used, do not repair it by cutting and bonding to avoid the reduction in strength by heat. Instead, replace the whole assembly including the part.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "Be careful with rough extending work, because the ultra high strength steel plate has higher tensile strength and a higher yielding point than high strength steel plate and general steel plate. Careless work will cause symptom such as over-pulling and springback. Do not extend it completely at a time. Do it gradually while removing the distortion by sheet metal processing with a hammer.", "ptxt");
si[i++] = gsitm("N5110909P0000I00ENG.html", "Plug welding of Φ 8 mm diameter plug for repair ensures the strength equivalent to spot welding for 2 steel sheets. For 3 sheets, weld 2 sheets from both sides instead of welding from one side to give sufficient welding strength.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "FRONT PILLAR", "title");
si[i++] = gsitm("N5110909S0000K00ENG.html", "When repairing the area using sound dampening foam material do not use firing tools since the sound dampening foam material may burn.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Before filling the foam material, seal the hole and flange with bolt and sheet-metal tape.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Wait 2 hours after filling the sound dampening foam material to remove the bolt and aluminium tape, then melt the sound dampening foam material with a soldering gun so a clip, etc. can thoroughly be inserted in the hole filled with sound dampening foam material.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Epoxyayresin adhesive", "title");
si[i++] = gsitm("N5110909S0000K00ENG.html", "&lt;With spot welding>", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Apply the adhesive to the inner side of the front pillar reinforcement lower inner part as shown.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "&lt;With MIG plug welding>", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Increase the number of the specified welding spots by 40% without applying any adhesive.", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Adhesive: Epoxyayresin adhesive", "ptxt");
si[i++] = gsitm("N5110909S0000K00ENG.html", "Brand: 3M™ AAD Part No.8115 or equivalent", "ptxt");
