si[i++] = gsitm("N511090A10000C00ENG.html", "When installing the new front door panel outer part, grind the bonding surface and remove the paint to improve adhesion. Then, degrease the front door panel outer.", "ptxt");
si[i++] = gsitm("N511090A10000C00ENG.html", "Install the front door panel outer and hem it. Then, wipe off the adhesive that squeezed out.", "ptxt");
