si[i++] = gsitm("N511090AD0000H00ENG.html", "A slash (/) in the material symbol indicates that two different materials make two-layer construction. A plus sign (+) indicates that the two different materials mix each other.", "ptxt");
si[i++] = gsitm("N511090AD0000H00ENG.html", "The indicated heat-resistant temperature for parts which are composed of two or more types of material is the value for the material with the lowest heat-resistant temperature.", "ptxt");
si[i++] = gsitm("N511090AD0000H00ENG.html", "The material symbols for synthetic-resin parts are embossed on the parts in hidden places.", "ptxt");
si[i++] = gsitm("N511090AD0000H00ENG.html", "Heat-resistant temperature means \"temperature which may cause thermal deformation during the service\".", "ptxt");
si[i++] = gsitm("N511090AD0000H00ENG.html", "When using an infrared light to dry the parts, protect the parts with heat-resistant covers, etc.", "ptxt");
