si[i++] = gsitm("N511090AF0000C00ENG.html", "Body color code is stamped on the vehicle information code plate, which is attached on the underside of the center pillar (Right side).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "BODY COLOR CHARTS", "title");
si[i++] = gsitm("N511090AG0001E00ENG.html", "Check the vehicle\'s body color code, and then use this body color chart to determine the refinishing paint supplier from which the color can be purchased.", "ptxt");
