si[i++] = gsitm("N511090AG0001E00ENG.html", "The coating film structure indicates top coating only (2S: 2 coat solid, 2M: 2 coat metallic, 3M: 3coat metallic, 2P: 2 coat pearl, 3P: 3 coat pearl, 3CM: 3 coat color clear metallic).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "For painting, inner panel colors should be similar to the outer panel colors.", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "2-tone color consists of 2 colors, a color before the slash (/) which indicates the body upper (roof, shark fin antenna cover and liftgate spoiler) color and a color after the slash (/) which indicates the body lower color.", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The door mirror outer cover is coated in black (AC11342) or body color.", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The roof rack is coated in silver (AC11169) or black (CMX18008).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "Front sonar sensor inner/outer holder and rear sonar sensor inner/outer holder are coated in black (AC11342). &lt;Color code X47 and U25X47>", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The front fog light bezel is coated in silver (CSU10025) or black (AC10705).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The front door sash cover front is coated in black (AC20157).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The front pillar finisher is coated in black (AC10705).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The rear fender sash molding outer is coated in black (CMX18010).", "ptxt");
si[i++] = gsitm("N511090AG0001E00ENG.html", "The front door sash cover rear, rear door sash cover front and rear door sash cover rear are coated in black (CMX18010).", "ptxt");
si[i++] = gsitm("N511090AI0000B00ENG.html", "2-TONE", "title");
si[i++] = gsitm("N511090AJ0000A00ENG.html", "FRONT END", "title");
si[i++] = gsitm("N511090AK0000A00ENG.html", "WHEELHOUSE", "title");
si[i++] = gsitm("N511090AK0000A00ENG.html", "Front", "title");
si[i++] = gsitm("N511090AK0000A00ENG.html", "Rear", "title");
si[i++] = gsitm("N511090BC0000800ENG.html", "RADIATOR GRILLE", "title");
si[i++] = gsitm("N511090AL0001100ENG.html", "FRONT BUMPER", "title");
si[i++] = gsitm("N511090AM0000Z00ENG.html", "REAR BUMPER", "title");
si[i++] = gsitm("N511090370000C00ENG.html", "Sheet Metal Work Tools", "title");
si[i++] = gsitm("N511090370000C00ENG.html", "This section explains various tools used in body repair work.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Hammers", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "A hammer is used to correct dents, projections or other deformations. Various shapes have been designed according to their purposes.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(1) TYPES AND FEATURES OF HAMMERS", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "(2) SELECTION AND MAINTENANCE OF HAMMERS", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "It is necessary to choose lighter or heavier hammers according to application or purpose.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Hammer weight should be selected according to the user\'s physical strength.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Hammer maintenance is important. In particular, the hammer face must always be kept clean. A distorted or damaged hammer face will lead to distorted panels.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Accordingly, hammers for sheet metal work must not be used to hit other objects such as a chisel. Do not mix sheet metal hammers with ordinary hammers.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Repairing the face of a sheet metal hammer is explained below.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(a) Clamp the hammer in a vise with the hammer face up.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "If the hammer face is deformed, use a hand file to smooth it.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(b) File the face in all directions. Do not file in only one direction.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(c) Chamfer the edge of the face to prevent it from nicking or distorting the sheet metal.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(d) After smoothing the hammer face, polish it with an oil stone or #400 - #800 abrasive paper wrapped around a wooden block. Polish the face in all directions.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(e) To check the finish, apply marking paint to the hammer face. Hit a piece of flat sheet metal on a flat surface.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "GOOD", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", ": The paint comes off the center to the face.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "NO GOOD", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", ": The paint comes off at a section other than the center or the face. Grind the surface again.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(3) HOLDING AND HITTING WITH THE HAMMER", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "(a) Holding the hammer", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "Hold the hammer handle tightly with the middle, third and little fingers so that it will not slip when it is swung.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Hold the sides of the hammer handle lightly with the thumb and index finger to prevent sideways movement.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "(b) Hammering", "title");
si[i++] = gsitm("N511090380000C00ENG.html", "For rough straightening work, strike strongly.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "For ordinary correcting work, swing the hammer using the wrist. In this case, the arm serves as a guide to determine the hammer direction.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "The hammer face should be flush with the panel surface when hitting. If the hammer edge strikes the surface, it will nick the panel.", "ptxt");
si[i++] = gsitm("N511090380000C00ENG.html", "Hammering should be approximately 100 hits a minute, and should be kept constant. An irregular hammering rhythm will lead to an uneven hammering force. Sheet metal will stretch when it is hammered. Irregular hammering also makes sheet metal correction more difficult.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Dollies", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Dollies are used in combination with a hammer. They are a 1 kg - 2 kg (2 lb - 4 lb) steel blocks, heavier than a hammer, with various curves and planes.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(1) USE OF DOLLIES", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "(a) Place the dolly on the underside of the deformed sheet metal.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Strike the deformed section of the sheet metal with the hammer to stretch it.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(b) Move the hammer and dolly as necessary, and direct the hammer blows so as to bend the sheet metal.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(c) If ordinary hammering is impossible due to limited space, substitute a dolly for the hammer, and strike the dented portion with the dolly.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(2) TYPES AND FEATURES OF DOLLIES", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "General purpose dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "This is also called a rail dolly. It has both wide and narrow curved faces.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Utility dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "This type of dolly features various curved surfaces and has wide applicability to automobile body repair work. It can be handled easily in narrow spaces.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Heel dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "One side is flat and the other side is curved slightly.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "This is suitable for correcting flat and slightly curved surfaces.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Toe dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "This dolly is formed by two flat surfaces and a connecting curved surface. It can be used in narrow places.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Round dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Both sides are curved. This dolly is used for repairing small dents.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Wedge dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "This dolly has a curved surface which changes gradually from sharp to gentle. Its sharp end can be inserted into narrow portions.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Shrinking dolly", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "The surface is like a file. This dolly is used in combination with a shrinking hammer.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(3) SELECTION AND MAINTENANCE OF DOLLIES", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Ideally, a dolly whose curved surface just fits the curvature of the panel should be used. However, this is often difficult. In most cases, a dolly whose curvature is slightly smaller than that of the panel should be selected.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Generally speaking, four types of dollies (general purpose, utility, heel and toe dollies) are sufficient for ordinary panel work. However a special dolly can be designed for unique shaping.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "The size and weight of the dolly must be easy to handle.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "The maintenance procedures and cautions described for the hammer also apply to the dolly.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "The entire surface of the dolly must be free from damage.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(4) HOW TO HOLD THE DOLLY", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Basic handling of the dolly.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(a) TOP:", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Place the dolly in the palm of your hand.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Holding it lightly, place the curved surface against the curved surface of the panel.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(b) CORNER:", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Hold the dolly lengthwise, and place the corner in the sharply bent portion of the panel.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(c) EDGE:", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "Hold the dolly so that the edge faces upward.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "Place this edge to the press line of the panel.", "ptxt");
si[i++] = gsitm("N511090390000C00ENG.html", "(d) CORRECTING THE PRESS LINE:", "title");
si[i++] = gsitm("N511090390000C00ENG.html", "To correct a concave press line in a narrow space on the back of the panel, use a dolly as shown in the figure and strike the press line with it.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "How to Use Hammer and Dolly", "title");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(1) HAMMER-ON-DOLLY", "title");
si[i++] = gsitm("N5110903A0000C00ENG.html", "This is also known as dinging on the dolly. The dolly is held directly under the area being struck with the hammer. Hammering smoothens the dented metal between the dolly and hammer. This method causes the sheet metal to stretch.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "Hammering on a dolly is most effective for repairing shallow dents.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(a) The hammer strikes the sheet metal, causing the dolly to bounce against the metal surface. Thus the damaged portion is worked out from both inside and outside.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(b) The sheet metal stretches between the hammer and dolly, and deformation is distributed around the strike area.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(c) Continuously move the dolly under the shifting deformation so that it can be struck properly.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(d) The sheet metal gradually stretches and returns to its original shape.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(2) HAMMER-OFF-DOLLY", "title");
si[i++] = gsitm("N5110903A0000C00ENG.html", "This is also known as dinging off the dolly.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "Place the dolly directly under a dent, and hammer against the edge of the dent. The hammer drives one area downward while the reaction of the dolly drives the adjacent area upward.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "An example of the hammer-off-dolly operation is given below.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(a) Place the dolly under the deepest dent, and hammer the highest portion of the top surface.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(b) The raised portion of the surface lowers as it is struck with the hammer.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(c) Hammer blows are transmitted to the dolly, creating a reaction force.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(d) This reaction force pushes the dent.", "ptxt");
si[i++] = gsitm("N5110903A0000C00ENG.html", "(e) Repeat steps (a) - (d) until the surface is smooth.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Spoons", "title");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Spoons are made of steel, and one or both ends are flat. Spoons are used as dollies in narrow spaces or as pry bars.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(1) TYPES AND FEATURES OF SPOONS", "title");
si[i++] = gsitm("N5110903B0000C00ENG.html", "General purpose spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "This spoon has a gently curved surface and sharply curved ends. It is widely used in automobile body repair work.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Long spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "This spoon has a long handle and thin, rigid faces. It is used primarily for prying.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Curved spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "The handle of this spoon is comparatively short. It has a wide curved blade. This spoon is used for smoothing.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Flat spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "This spoon has a short handle and a wide, flat blade. When the spoon is placed on the panel and hammered, the force disperses over a wide area.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "High crown spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "This spoon has a wide hooked blade. It is used for repairing narrow body panel spaces such as inside of outer sill panel.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Sickle-shaped spoon", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "This spoon has a wide, gently curved surface with a thin end. It can be inserted into very narrow gaps between panels.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(2) SELECTION AND MAINTENANCE OF SPOONS", "title");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Select spoons suitable for the particular panel shape and internal structure. Spoons can be made from leaf springs.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "Cut the leaf spring to the desired shape. Heat it with a gas torch and shape it into a spoon by bending or stretching with a hammer. Then grind and polish. (See Hammer Maintenance, refer to Hammers.)", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "The precautions described for the hammer and dolly also apply to spoons. Do not damage the surface which comes into direct contact with the panel during repair work.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(3) HOW TO USE SPOONS", "title");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(a) Insert the spoon into tight spaces such as inside of door, and use as a dolly.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(b) Place a spoon between two panels and pry out the concave portion.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(c) Hammer directly on the spoon to disperse the force of the hammer blows.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "(d) The figure to shows an example of incorrect spoon usage. There is no fulcrum point for the spoon.", "ptxt");
si[i++] = gsitm("N5110903B0000C00ENG.html", "If a spoon is used in this way, insufficient force is applied to the mating face, and the spoon cannot act as a dolly.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Scribing Chisels", "title");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Chisels are generally used to cut sheet metal.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "They are also used in body repair work. There are numerous types of chisels. This section, however, describes scribing chisels used exclusively for bending sheet metal or for shaping panel press lines.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "This type of chisel must have a smoothly rounded edge as shown in the figure. If the edge is sharp, the body panel will be nicked.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "HOW TO USE SCRIBING CHISELS", "title");
si[i++] = gsitm("N5110903C0000C00ENG.html", "(a) For bending sheet metal", "title");
si[i++] = gsitm("N5110903C0000C00ENG.html", "First scribe a line on the sheet metal.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Place thick paper or cardboard under the sheet metal.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Place the scribing chisel on the line and hammer it.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Place the sheet metal on a flat, angled surface scribed-side down, and bend the sheet metal with a wooden hammer.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Using a hammer and the scribing chisel, neatly bend the sheet metal squarely. Do not bend all at once.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "Bend the sheet metal gradually by gently hammering against the chisel head.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "(b) Shaping the press line", "title");
si[i++] = gsitm("N5110903C0000C00ENG.html", "If the dent in the press line is smaller than the width of the chisel, apply the chisel to the center of the dent. Hammer to flatten. Hammer gently so that the dent can be removed gradually.", "ptxt");
si[i++] = gsitm("N5110903C0000C00ENG.html", "If the dent is larger than the width of the chisel, do not strike the dent in the center. Apply the chisel at the edges of the dent.", "ptxt");
si[i++] = gsitm("N5110903D0000C00ENG.html", "Types and Uses of Tinman Shears", "title");
si[i++] = gsitm("N5110903D0000C00ENG.html", "(1) STRAIGHT BLADE SHEARS", "title");
si[i++] = gsitm("N5110903D0000C00ENG.html", "For cutting straight lines.", "ptxt");
si[i++] = gsitm("N5110903D0000C00ENG.html", "(2) CURVED BLADE SHEARS", "title");
si[i++] = gsitm("N5110903D0000C00ENG.html", "The blades are smoothly curved. Suitable for straight or curved cutting.", "ptxt");
si[i++] = gsitm("N5110903D0000C00ENG.html", "(3) SCOOPED BLADE SHEARS", "title");
si[i++] = gsitm("N5110903D0000C00ENG.html", "The entire blade is bent to one side. Suitable for cutting along a sharply curved line.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "Tools for Pulling", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "If it is impossible to gain access to the damaged area, dents can be pulled out and repaired.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(1) SLIDING HAMMER", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "The sliding hammer is used for repairing large, deep dents. Since it provides greater force than an ordinary hammer, it is used to repair dents in thick panels.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(a) When the panel is thick. A hook similar to the hand hook is attached to the end of the sliding hammer. Pulling holes are drilled in the panel. A limited force is allowed for pulling. The panel must be pulled carefully to avoid tearing.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(b) When the panel is thick. A tapping screw is attached to the end of the sliding hammer. It is then screwed into the panel. A greater pulling force is possible than with the hook.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(c) When the panel is thin. Instead of a hole, a metal pin or washer is welded to the panel. Great force can be used for pulling.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(d) When the dent is deep and narrow, pull it with a single blow.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(e) When the panel dent is shallow and wide, hold the end of the sliding handle. Repair the dent by gradually tapping the edge of the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(2) STUD WELDER (BODY REPAIR STATION)", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "A pin or washer is welded directly to the body panel dent without drilling. The panel dent area is then pulled outward with the sliding hammer. Because no drilling is required, panel strength is unaffected. Corrosion problems are also reduced.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "Because the stud welder welds pins directly, the paint must be removed from the dent surrounding area and the area where body ground is established.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "As shown in the figure, the ground can be established at the flange area or in the dent surrounding area using a magnet.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(3) WELDED PIN OR WASHER", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "A pin or washer is welded to the dent without drilling. It is then pulled to repair the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "Several pins or washers are welded to the dent. They are then pulled together or separately to repair the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(4) SPOT HAMMER WELDING", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "The sliding hammer tips are welded to the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "They are then pulled separately to repair the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "After the tips are pulled, they are twisted to separate them from the panel.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(5) VACUUM PULLER", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "The vacuum puller is suitable for pulling out large dents if the dented surface is comparatively smooth.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "(6) HAND HOOK", "title");
si[i++] = gsitm("N5110903E0000C00ENG.html", "Small holes are drilled in the dented portion, and a hand hook is inserted into the hole. The dented panel is pulled out with the hook. This method is used to repair small panel dents.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "When using a hand hook, fit the end snugly against the panel. Do not pry up or use too much force. Pull the hook lightly while tapping with a hammer at the edge of the dent.", "ptxt");
si[i++] = gsitm("N5110903E0000C00ENG.html", "The drilled hole must be refilled with body putty after completing the work.", "ptxt");
si[i++] = gsitm("N5110903G0000C00ENG.html", "Shrinking The Sheet Metal", "title");
si[i++] = gsitm("N5110903G0000C00ENG.html", "Plastic deformation may cause reduced panel thickness and the panel may stretch. Even when it is repaired using a hammer and dolly, the panel tends to bulge, losing its original shape.", "ptxt");
si[i++] = gsitm("N5110903G0000C00ENG.html", "In such cases, it must be shrunk to its original shape. This is called shrinking the sheet metal.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "Shrinking Methods", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(1) ELECTRIC WELDING MACHINE", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "The body panel is connected to the negative power supply terminal and the tip is connected to the positive terminal. Then, an electric current is supplied to heat the panel. The shrinking principle is the same as that of gas welding. This method features no hammering and greater workability than gas welding and is suitable for repairing local panel deformations.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(2) CARBON ROD", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "The panel is connected to the negative power supply terminal and a carbon rod is connected to the positive terminal. The panel is heated so that heat is conducted from the outside to the center of the dent. Wet rags are then applied to cool it quickly, thus shrinking the panel.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "This method is suitable for repairing wide, shallow panel deformations.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(3) GAS WELDING (OXY-ACETYLENE TORCH)", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(a) Heating and expansion", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "As the sheet metal is heated with a gas welding torch, it stretches.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "However, stretching is restricted in the unheated surrounding portion. As a result, the heated portion bulges.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(b) Sudden cooling", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "When the bulge is cooled suddenly, it shrinks.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "This shrinking is accelerated by tapping with a wooden hammer.", "ptxt");
si[i++] = gsitm("N5110903H0000C00ENG.html", "(4) HAMMER AND DOLLY", "title");
si[i++] = gsitm("N5110903H0000C00ENG.html", "A shrinking hammer and shrinking dolly are used by the hammer-on-dolly method. Many tiny dents are formed on the panel surface. This method is suitable for shrinking comparatively small areas of panel deformation.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "How to Heat Sheet Metal", "title");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Use a carburizing flame when shrinking sheet metal with a gas welding torch.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Hold the torch at a right angle to the center of the sheet metal.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Maintain a distance of 3 mm - 5 mm (0.12 in - 0.20 in) between the inner core and sheet metal.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Heat the sheet metal to approximately 800°C (1,472°F) (until the heated portion turns red). Increase the temperature if sheet metal stretching is insufficient.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Locate the stretched portion of the panel.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Press the surface being repaired in several places.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "The point where the largest elastic dent is formed is the center, where the stretch is the maximum. The highest portion of the panel being repaired can also be considered the most stretched portion.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "The area heated with a welding torch must be approximately 3 mm - 5 mm (0.12 in - 0.20 in) in diameter if the panel shape is complex, and approximately 6 mm - 15 mm (0.24 in - 0.59 in) in diameter if it is flat.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Small stretch", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Apply a dolly to the back of the heated panel. Tap the panel with a wooden hammer using the hammer-on-dolly method in the sequence shown in the figure.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "(A) and (B) → 1 - 8", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "(C) → 9", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Excessive stretch", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Shrink the panel, starting with the most stretched portion, and proceed toward the edge of the dent so that the dent surface is lower than the original surface.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Using a gas welding torch makes the panel concave.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "To correct this, strike the concave portion using the hammer-on-dolly method to stretch the panel bit by bit until the original surface is restored.", "ptxt");
si[i++] = gsitm("N5110903I0000C00ENG.html", "Apply wet cloths to the shrunken portion of the panel to cool it quickly.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "Determining Panel Damage", "title");
si[i++] = gsitm("N5110903K0000C00ENG.html", "This repair method should not be used on rails and reinforcements.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "Panel damage must be examined carefully to select the most suitable repair method.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "(A) In the figure is the plastic deformed area and the surrounding portions are elastic deformed areas.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "Correction of (A) will automatically remove the elastic deformation.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "Removing the cause of the dent can simplify the entire repair operation. Plastic deformation can be recognized by sharp bending, a nick, or cracked or peeled paint.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "SHEET METAL DEFORMATION ANALYSIS", "title");
si[i++] = gsitm("N5110903K0000C00ENG.html", "(a) When external force is applied, sheet metal deformation begins. Elastic deformation is generated around the point where the external force is applied.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "(b) As the external force increases, areas surrounding the dent yield to the pressure, and local cracking or small breaks in the paint occur. This indicates plastic deformation.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "(c) If the external force continues to increase, breaks around the dent enlarge, and the sheet metal at the center of the dent stretches.", "ptxt");
si[i++] = gsitm("N5110903K0000C00ENG.html", "(d) When the external force is removed, the “spring back” causes the plastic deformed portion of the dent to swell above the original surface.", "ptxt");
si[i++] = gsitm("N5110903L0000C00ENG.html", "Basic Types of Damage", "title");
si[i++] = gsitm("N5110903L0000C00ENG.html", "This repair method should not be used on rails and reinforcements.", "ptxt");
si[i++] = gsitm("N5110903L0000C00ENG.html", "Plastic deformation forms at the center of portion (A) of the dent. The surrounding area remains in elastic deformation.", "ptxt");
si[i++] = gsitm("N5110903L0000C00ENG.html", "Plastic deformation occurs at one or several portions around the dent. Other areas remain in elastic deformation.", "ptxt");
si[i++] = gsitm("N5110903L0000C00ENG.html", "Both plastic and elastic deformation are generated throughout the damaged panel.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Examination of Panel Damage", "title");
si[i++] = gsitm("N5110903M0000C00ENG.html", "This repair method should not be used on rails and reinforcements.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "It is difficult to find minor deformation or panel irregularity, particularly, at the final stage of repair. This section explains how to determine if a vehicle has minor panel deformation.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "(1) VISUAL CHECK", "title");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Check the affected portion of the panel by carefully examining the deformation in the light reflected on the surface.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "(2) TOUCH CHECK", "title");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Lightly place a hand on the surface of the panel and move it forward/backward and right/left to judge by touch with the palm of a hand. Slide and move a hand from an undamaged surface to a damaged part, all the way to the undamaged surface on the other side.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Wearing work gloves makes it easier to tell the difference.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "(3) CHECK WITH TOOLS", "title");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Use of chalk: Rub the panel surface with a piece of chalk held lengthwise.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Dents or concave areas in the panel will remain uncolored.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Use of hacksaw blade: Scrape the panel surface with the blade teeth.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Dents or concave areas will not be scratched.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Use of body file: Scrape a body file lightly on the panel.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "The body file should not be used for grinding.", "ptxt");
si[i++] = gsitm("N5110903M0000C00ENG.html", "Thickness and strength of the panel will be reduced.", "ptxt");
si[i++] = gsitm("N5110903N0000C00ENG.html", "Elastic VS. Plastic Deformation", "title");
si[i++] = gsitm("N5110903N0000C00ENG.html", "Elastic deformation: If pressed, the deformed portion will move or further deform.", "ptxt");
si[i++] = gsitm("N5110903N0000C00ENG.html", "Plastic deformation: If pressed, the deformed portion will remain unchanged, and other portions will move.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "Basic Repair Procedure", "title");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(1) WHEN PLASTIC DEFORMATION OCCURS AT THE CENTER OF THE DAMAGED PORTION", "title");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(a) Using a hammer or dolly, strike the lowest portion of the dent from behind until it becomes flat.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(b) Using the hammer-off-dolly method as shown in the figure, raise the concave portion and lower the convex portion.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "Then smooth the surface a little lower than the original. Using a wooden hammer and dolly, correct the irregularities in the panel.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(c) Existence of plastic deformation can be determined by the stretched panel. The original surface can be restored by shrinking that portion with a gas welding torch.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(d) Use a hammer and dolly by the hammer-on-dolly method. Stretch the panel while striking the outer area of the damaged portion. The entire panel surface should be formed somewhat higher than the original surface. Note that, in this case, the stretched portion of the panel must not be hit with the hammer.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "If the concave portion is shallow and if the working face of the wooden hammer matches it, the repair work can be completed quickly by directly shrinking the portion with a gas welding torch.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(2) WHEN PLASTIC DEFORMATION EXISTS AROUND THE DAMAGED PORTION", "title");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(a) Apply the dolly to the elastic deformation area behind the panel. Hit the plastic deformation area with a hammer so that the elastic deformation area is lower than the original surface.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(b) Repair the plastic deformed portion using the hammer-off-dolly method. If a shrinking hammer is available, the stretched portion can be easily shrunk.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(3) WHEN PLASTIC DEFORMATION EXISTS AT THE CENTER AND AROUND THE DAMAGED PORTION", "title");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(a) Using a hammer and dolly, flatten the lowest portion (A) where the plastic deformation exists, so that the flattened surface is not higher than the original surface.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(b) Flatten the highest points (B) where plastic deformation exists.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(c) Flatten portion (A) so that the panel surface is not higher than the original surface.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "Correct irregularities using a wooden hammer and dolly. If the panel has been stretched, repair by shrinking.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(4) CORRECTING PANEL DISTORTION", "title");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(a) Panel distortion occurs when panel damage is repaired. The panel is deformed within the range of elastic deformation. If pressed with a finger, the deformed area bends inward and outward. Panel irregularities occurring over a wide range other than the repaired portion may also indicate panel distortion.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(b) Cause of panel distortion", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "Expansion stress due to damage repair is confined inside the panel because the outer area is bent and work hardened. Thus, it does not allow the panel to expand. The stress is released in the form of panel distortion.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "(c) How to correct panel distortion", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "Panel distortion can be removed by shrinking the stretched portion or by stretching the side of the press line using the hammer-on-dolly method.", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "The front fender repair procedure is explained below:", "ptxt");
si[i++] = gsitm("N5110903O0000C00ENG.html", "When repairing the body panel, paint and anti-corrosive wax must be thoroughly removed from the damaged area by sanding.", "ptxt");
si[i++] = gsitm("N5110903Q0000C00ENG.html", "Paintless Dent Repair", "title");
si[i++] = gsitm("N5110903Q0000C00ENG.html", "Paintless dent repair is one type of panel repair technique. This technique is used to repair irregularities on painted outer panels without damaging the painted surface.", "ptxt");
si[i++] = gsitm("N5110903R0000C00ENG.html", "Confirmation of The Panel", "title");
si[i++] = gsitm("N5110903R0000C00ENG.html", "It is not possible to correct all convex/concave portions in paintless dent repair.", "ptxt");
si[i++] = gsitm("N5110903R0000C00ENG.html", "Whether or not the parts need to be removed/installed, and tools that can be inserted must be checked for each repair location.", "ptxt");
si[i++] = gsitm("N5110903R0000C00ENG.html", "When checking the convex/concave location, determine whether or not the paintless dent repair is possible. It is also important to determine the most suitable repair method.", "ptxt");
si[i++] = gsitm("N5110903R0000C00ENG.html", "Example of circular convex/concave", "ptxt");
si[i++] = gsitm("N5110903R0000C00ENG.html", "Example of oval convex/concave", "ptxt");
si[i++] = gsitm("N5110903S0000C00ENG.html", "Selection of Repair Tools", "title");
si[i++] = gsitm("N5110903S0000C00ENG.html", "Tools for paintless dent repair are hammers, spoons, dollies and punches. Some popular hand tools for paintless dent repair and application examples are described below.", "ptxt");
si[i++] = gsitm("N5110903S0000C00ENG.html", "Choose suitable tools to repair the panel.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Panel Repair Methods", "title");
si[i++] = gsitm("N5110903T0000C00ENG.html", "(1) CORRECTION OF CONCAVE PANEL WITH SPOONS", "title");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Convex panels can be repaired with a hammer and punch. Concave panels can be repaired with a spoon if the following conditions are satisfied:", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "The spoon must be able to be inserted behind the concave panel. A closed construction portion or mating panel cannot be repaired.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Use of lever action should be allowed.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "If the surrounding portion of panel can be used to support a spoon as a lever, the concave area can be repaired. Otherwise, corrective force cannot be transmitted to the desired portion.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "The concave portion should be visible from outside.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "This work is performed visually, and dents in concealed areas cannot be repaired.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "(2) KEY POINTS IN PAINTLESS DENT REPAIR WORK", "title");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Repairing a smoothly rounded concave section:", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Raise the concave portion little by little, beginning with the outside.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Repairing a concave section bent sharply at the center:", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "First, raise the concave portion 60% - 70%, beginning with the outside. Next, raise the sharply bent portion slightly higher than the surrounding panel surface.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Then flatten the high point by tapping with a hammer.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Do not attempt to correct panel deformation all at once.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "Use the step-by-step repair method, such as roughing → smoothing → finishing.", "ptxt");
si[i++] = gsitm("N5110903T0000C00ENG.html", "After repairing, visually check the repaired portion from all directions.", "ptxt");
si[i++] = gsitm("N5110903U0000C00ENG.html", "Polishing of Panel Surface and Anti-corrosive Treatment", "title");
si[i++] = gsitm("N5110903U0000C00ENG.html", "(1) POLISH-FINISHING OF CORRECTED SURFACE", "title");
si[i++] = gsitm("N5110903U0000C00ENG.html", "If the painted surface is scratched during repair, polish with compound to remove scratches.", "ptxt");
si[i++] = gsitm("N5110903U0000C00ENG.html", "(2) ANTI-CORROSIVE TREATMENT OF BACK OF PANEL", "title");
si[i++] = gsitm("N5110903U0000C00ENG.html", "The spoons may cause scratches. Apply anti-corrosive wax to the back of panel.", "ptxt");
si[i++] = gsitm("N5110903V0000C00ENG.html", "Examination of Panel", "title");
si[i++] = gsitm("N5110903V0000C00ENG.html", "Irregularities in the panel must be examined carefully to see whether or not they can be repaired, and also to determine the most suitable repair method.", "ptxt");
si[i++] = gsitm("N5110903V0000C00ENG.html", "Refer to Examination of Panel Damage.", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "Features of Welding", "title");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "No restrictions on the shape of joint", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "Reduction in weight compared to using of bolts or rivets", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "Great strength", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "Airtight and watertight", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "High working efficiency", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "Some welding processes require higher welding skills.", "ptxt");
si[i++] = gsitm("N5110903Y0000C00ENG.html", "The welded parts can be separated only by breaking the weld. (Except when brazing)", "ptxt");
si[i++] = gsitm("N5110903Z0000E00ENG.html", "Welding of Automobile Body", "title");
si[i++] = gsitm("N5110903Z0000E00ENG.html", "The automobile body is fabricated by welding 0.6 mm - 1.4 mm (0.024 in - 0.055 in) thick sheet steel. Spot welding is most suitable in terms of cost, quality and working efficiency. On the automobile production line, spot welding is widely used, except for some special areas which cannot use this procedure. Today, spot welding is mostly performed by robots.", "ptxt");
si[i++] = gsitm("N5110903Z0000E00ENG.html", "In addition to spot welding MAG brazing are also used.", "ptxt");
si[i++] = gsitm("N5110903Z0000E00ENG.html", "Soldering is not used in the automobile production line.", "ptxt");
si[i++] = gsitm("N5110903Z0000E00ENG.html", "Automobile assembly line welding processes are shown below.", "ptxt");
si[i++] = gsitm("N511090410000C00ENG.html", "Principles of Spot Welding", "title");
si[i++] = gsitm("N511090410000C00ENG.html", "Resistance spot welding is a kind of electric resistance welding. It is classified as pressure welding. Two or three sheets of metal are overlapped and pressed, and current is passed through the mating surfaces. As the current flows, the metals melt due to Joule heat at the mating surfaces and are joined by the pressure.", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Features of Spot Welding", "title");
si[i++] = gsitm("N511090420000C00ENG.html", "Short welding time and high efficiency compared to other welding processes", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Minimum thermal strain due to partial heating", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "No need to finish the welded surface", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Less rust formation compared to other welding processes due to application of conductive sealer", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Great welding skill is not needed. Uniform weld strength can be obtained regardless of worker\'s skill", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Heavy welding machine is required to produce high current", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Most suitable for welding thin sheet metals", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "The condition of the weld is difficult to check from the outside", "ptxt");
si[i++] = gsitm("N511090420000C00ENG.html", "Paint must be removed from the surfaces to be welded", "ptxt");
si[i++] = gsitm("N511090430000C00ENG.html", "Construction of Spot Welder", "title");
si[i++] = gsitm("N511090430000C00ENG.html", "The spot welding machine consists of a transformer unit which supplies the voltage and current required for welding, a timer unit which controls the current passing time, and a welding gun.", "ptxt");
si[i++] = gsitm("N511090430000C00ENG.html", "The separate transformer type includes a multi-functional type for welding of pins and washers.", "ptxt");
si[i++] = gsitm("N511090440000C00ENG.html", "Cooling Methods", "title");
si[i++] = gsitm("N511090440000C00ENG.html", "Air cooling: Forced air cooling with fan", "ptxt");
si[i++] = gsitm("N511090440000C00ENG.html", "Water cooling: Cooling by circulating the water", "ptxt");
si[i++] = gsitm("N511090450000C00ENG.html", "Spot Welding Gun", "title");
si[i++] = gsitm("N511090450000C00ENG.html", "(1) TYPES OF CLAMP", "title");
si[i++] = gsitm("N511090450000C00ENG.html", "(2) ATTACHMENT ARM", "title");
si[i++] = gsitm("N511090450000C00ENG.html", "In spot welding, 2 or 3 panels to be welded must be clamped directly at electrodes. Therefore, the disadvantage of spot welding is that there are some points at which welding cannot be performed.", "ptxt");
si[i++] = gsitm("N511090450000C00ENG.html", "In order to make up for this weakness, various types of attachment arms have been created.", "ptxt");
si[i++] = gsitm("N511090450000C00ENG.html", "(3) HANGING UNIT", "title");
si[i++] = gsitm("N511090450000C00ENG.html", "The weight of guns, arms and cables has been reduced to minimize the burdens on workers.", "ptxt");
si[i++] = gsitm("N511090450000C00ENG.html", "Depending on the unit type, the cable can simply be hung, or the gun can be hung with a cylinder.", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Multi-functional Type Spot Welder", "title");
si[i++] = gsitm("N511090460000D00ENG.html", "In addition to the ordinary spot welding function, sheet metal can be pulled with the sliding hammer.", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Major functions:", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Both sided spot welding", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "One sided spot welding (Pre tack welding)", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Spot hammer welding", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Nuts and bolts welding", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Carbon shrinking", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Contact shrinking", "ptxt");
si[i++] = gsitm("N511090460000D00ENG.html", "Washer and pin or stud welding", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "Process of Spot Welding", "title");
si[i++] = gsitm("N511090470000C00ENG.html", "It takes 3 processes, “pressurization”, “energization”, and “retention”, to complete the spot welding.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "(1) PRESSURIZATION", "title");
si[i++] = gsitm("N511090470000C00ENG.html", "The welding points of overlapped panels are pressurized with the tip (electrode) for close contact.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "With the panels contacting closely, the current can run intensively.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "(2) ENERGIZATION", "title");
si[i++] = gsitm("N511090470000C00ENG.html", "With the panels being pressurized, heavy current is applied.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "Joule heat is generated at panel mating areas, and the temperature rises sharply.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "The panel mating areas are melted and fused together by welding pressure.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "(3) RETENTION", "title");
si[i++] = gsitm("N511090470000C00ENG.html", "Even after the current is turned off, pressure is still applied until the welded point cools down.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "The nugget system becomes delicate by pressurization, resulting in better mechanical properties.", "ptxt");
si[i++] = gsitm("N511090470000C00ENG.html", "Therefore, the retention process must not be omitted.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "Condition of the Panel", "title");
si[i++] = gsitm("N511090480000C00ENG.html", "Before beginning, thoroughly check the panel and make any necessary corrections.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "(1) CLEARANCE BETWEEN WELDING SURFACES", "title");
si[i++] = gsitm("N511090480000C00ENG.html", "Gaps between the surfaces to be welded cause poor current flow. Even if welding could be done without removing such gaps, the welded area would be smaller, resulting in poor strength.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "Flatten the two surfaces to remove the gaps, and clamp them tightly before welding.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "(2) PANEL SURFACES TO BE WELDED", "title");
si[i++] = gsitm("N511090480000C00ENG.html", "Paint, rust, dust, or any other contamination on the panel surfaces to be welded cause insufficient current flow and poor results.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "Remove such foreign matter from the surfaces to be welded by sanding or wiping clean.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "(3) CORROSION PREVENTS PROPER WELDING OF PANEL SURFACES.", "title");
si[i++] = gsitm("N511090480000C00ENG.html", "Coat the surfaces to be welded with an anticorrosion agent that has high conductivity.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "It is important to evenly apply the agent to the panel including the end face.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "Perform the spot welding before the anticorrosion agent gets dry, as the agent has generally low conductivity.", "ptxt");
si[i++] = gsitm("N511090480000C00ENG.html", "Because the wet agent can move from the welding portion due to the welding pressure, that leads to the good quality of spot welding by high conductivity.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Precautions when Performing Spot Welding", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "(1) SELECTION OF SPOT WELDING MACHINE", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Use the direct welding method whenever possible.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(When direct welding cannot be applied, use MIG/MAG plug welding.)", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(2) APPLICATION OF ELECTRODE TIPS", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Apply electrodes at right angles to the panel. If they are not applied properly, the current density will be low, resulting in poor welding strength.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(3) NUMBER OF SPOT WELDING POINTS", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Generally, the capacity of repair shop spot welding machines is smaller than that of factory welding machines. Accordingly, the number of points of spot welding should be increased by 20% - 30%.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Spot weld indicated number in BRM.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(4) WELDING CORNERS", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Do not weld the curved corner. Welding this portion results in stress concentration, which leads to cracks.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Examples:", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Upper corner of front and center pillars", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Front upper portion of rear fender", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Corner portion of front and rear windows", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(5) MINIMUM WELDING PITCH", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "The minimum welding pitch varies with the thickness of panels to be welded. In general, observe the values in the following table.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "The excessively small pitch allows the current to flow through surrounding portions, resulting in poor welding strength.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Avoid welding over previously welded areas.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "As spot welded portion will become harder and thinner, the different portion should be welded as possible.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Old Spot Locations", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "New Spot Locations", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(6) MINIMUM LAP OF PANELS", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Observe the following values for the lap distance of panels. Too short of a lap distance results in reduced strength and also in a strained panel.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "Be sure to spot weld at the center of the overlapped portion.", "ptxt");
si[i++] = gsitm("N511090490000C00ENG.html", "(7) SPOTTING SEQUENCE", "title");
si[i++] = gsitm("N511090490000C00ENG.html", "Do not spot weld continuously in one direction only. This causes weak welding due to the shunt effect of the current. If the welding tips become red-hot, stop welding and cool the tips.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "Inspection of Welded Portion", "title");
si[i++] = gsitm("N5110904A0000C00ENG.html", "Spot welded portions can be checked by the destructive inspections explained below. They can be easily adopted when welding. Before and after welding, you should perform these destructive inspections to check the strength of the welded portions.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "The welding spots should be equally spaced and arranged at the center of the flange to be welded.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(1) CHECK BY USING TEST PIECE (Confirmation before operation)", "title");
si[i++] = gsitm("N5110904A0000C00ENG.html", "Clamp both test pieces together so that they will not slip or move during welding.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(a) Weld together test pieces with the same thickness as the panel to be welded.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "Break the weld by twisting, and examine the break.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(b) With this test, a hole should be made on one test piece by tearing at the welded portion. If no hole is formed, it indicates that the welding conditions are incorrect. Adjust the pressure, welding current, current passing time and other conditions, and repeat test until the best result is obtained.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(2) CHECK BY USING CHISEL AND HAMMER (Confirmation after welding)", "title");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(a) Insert a chisel tip between the welded panels, and tap the end until a clearance 3 mm - 4 mm (0.12 in - 0.16 in) [when the panel thickness is 0.8 mm - 1.0 mm (0.031 in - 0.039 in)] is formed between the panels. If the welded portions do not separate, it indicates that the welding has been done properly.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "This clearance varies with the location of the welded spots, length of the flange, panel thickness, welding pitch, and other factors. Note that the value shown above is only for reference.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(b) If the thickness of the panels is different, the clearance must be limited to 1.5 mm - 2.0 mm (0.059 in - 0.079 in). Further opening of the panels can become a destructive test.", "ptxt");
si[i++] = gsitm("N5110904A0000C00ENG.html", "(c) Be sure to repair the deformed portion of the panel after inspection.", "ptxt");
si[i++] = gsitm("N5110904C0000C00ENG.html", "Arc Welding", "title");
si[i++] = gsitm("N5110904C0000C00ENG.html", "Arc welding uses the heat of an electric arc to join two pieces of metal by fusing both the metal and the electrode. For auto repair, MIG (Metal Inert Gas) and MAG (Metal Active Gas) are the types of arc welding most often used.", "ptxt");
si[i++] = gsitm("N5110904D0000C00ENG.html", "Principles of MIG and MAG Arc Welding", "title");
si[i++] = gsitm("N5110904D0000C00ENG.html", "The welding electrode consists of a wire wound on a reel. This welding wire is fed by an electronically controlled motor.", "ptxt");
si[i++] = gsitm("N5110904D0000C00ENG.html", "The welding zone is shielded from the atmosphere by injecting a shielding gas. This prevents oxidation and nitriding so that greater weld strength and a good weld bead can be obtained. The shielding gas is argon, CO2, or a mixture of both.", "ptxt");
si[i++] = gsitm("N5110904D0000C00ENG.html", "MIG arc welding uses argon gas as a shield. If CO2 is used, the method is called MAG arc welding. Use of argon gas permits most metals, including aluminum, copper, stainless steel, titanium, to be welded.", "ptxt");
si[i++] = gsitm("N5110904D0000C00ENG.html", "The following figure shows the welding procedure.", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Features of MIG and MAG Welding", "title");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Less slag", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Less thermal strain", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Comparatively easy to master", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Greater weld strength than gas or spot welding", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Suitable for thin sheet metal", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Less influence of welding position to the strength of weld", "ptxt");
si[i++] = gsitm("N5110904E0000C00ENG.html", "Not suitable for windy locations", "ptxt");
si[i++] = gsitm("N5110904F0000C00ENG.html", "Structure of MIG and MAG Welding Machine", "title");
si[i++] = gsitm("N5110904F0000C00ENG.html", "The welding machine consists of a power supply unit composed of a transformer and rectifier which converts the source voltage to welding voltage and rectifies the current. A controller which controls the voltage, current and welding wire feed speed corresponding to the thickness of the welding panel. Welding wire which is wound around the wire spool, wire feed motor, welding torch, gas cylinder, and regulator.", "ptxt");
si[i++] = gsitm("N5110904G0000C00ENG.html", "Condition of Panel to be Welded", "title");
si[i++] = gsitm("N5110904G0000C00ENG.html", "Paint, rust, or oils on the surface of the panel cause blowholes and spatter when the panel is welded. Thoroughly remove any foreign matter with a belt sander or wire brush.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Inspection of Welded Portions", "title");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Refer to the inspection method for spot welding. Refer to Inspection of Welded Portion.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Sample defects and welding conditions of MIG, MAG welding.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Defect", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Check points", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Remarks", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is correct wire selected?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is gas sealed properly?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is weld joint surface clean?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is weld zone quickly cooled?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "A hole is made when gas is trapped in the weld metal.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is torch feed operated properly?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is voltage low?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is the area to be welded clean?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "This is an unfused condition between weld metals or between deposited metals.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is current too great?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is torch feed too fast?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is torch angle correct?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Undercut is a condition where the overmelted metal has made grooves or an indentation.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Metal\'s section is made thinner, and therefore the weld zone\'s strength is severely lowered.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is current too little?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is wire feed out of order?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is extrude extension too long?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is groove face too small?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "This is a condition where there is poor deposition made under the panel.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Is torch feed too slow?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Overlap is apt to occur in fillet weld rather than in butt weld.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Overlap causes stress concentration and results in premature corrosion.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Spatter is prone to occur in fillet weld.", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Are there any stains on welded surface (paint, oil, rust)?", "ptxt");
si[i++] = gsitm("N5110904H0000C00ENG.html", "Cracks usually occur on top surface only.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "Types of MIG and MAG Welding", "title");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(1) CONTINUOUS WELDING", "title");
si[i++] = gsitm("N5110904I0000C00ENG.html", "This welding process is suitable for sheet steel 2 mm (0.08 in) thick or over. If applied to thinner panels, it will cause melt-through.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(2) SPOT WELDING", "title");
si[i++] = gsitm("N5110904I0000C00ENG.html", "Replace the torch nozzle with a spot welding nozzle.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "Grind the surfaces to be welded and press tightly together.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(3) PLUG WELDING", "title");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(a) Make a hole 5 mm - 6 mm (0.20 in - 0.24 in) in diameter in the upper of the two panels to be welded. Keep the upper panel and lower panel tightly together.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(b) Apply the torch at a right angle to the panel and quickly fill the hole with the molten metal. Intermittent welding generates oxide film, causing blowholes. If this occurs, remove the oxide film with a wire brush or belt sander.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(c) Weld the upper and lower panels together tightly.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "(4) INTERMITTENT (STEP) WELDING", "title");
si[i++] = gsitm("N5110904I0000C00ENG.html", "This method is suitable for thin or rusted panels to prevent thermal deformation and melt-through. In body repair, it is used as butt welding on partial panel replacements.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "Before step welding, tack weld the panels to be welded to prevent strain and to align panel surfaces.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "To do this, point weld and then fill in the spaces with short welding beads.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "Long weld line will cause strain. Use the method as shown in the figure to reduce strain.", "ptxt");
si[i++] = gsitm("N5110904I0000C00ENG.html", "To fill the spaces between intermittently placed beads, grind the beads using a sander, then fill with molten metal. If this is done without grinding the surface of the beads, blowholes may result.", "ptxt");
si[i++] = gsitm("N5110904L0000C00ENG.html", "Precautions for Operation", "title");
si[i++] = gsitm("N5110904L0000C00ENG.html", "In body repair, great importance is attached to quality, efficiency and cost. Consideration for workers\' safety and health should, however, be deemed as the most important item. In reality, it is essential that measures be established to prevent accidents and to make the work environment safer and healthier.", "ptxt");
si[i++] = gsitm("N5110904M0000C00ENG.html", "Protectors", "title");
si[i++] = gsitm("N5110904M0000C00ENG.html", "While working, suitable work clothes, a work cap and safety shoes must be worn. To prevent burns, a long sleeve shirt and trousers must also be worn and must not be taken off under any circumstances.", "ptxt");
si[i++] = gsitm("N5110904M0000C00ENG.html", "Keep work clothes clean. Do not keep a lighter or other flammable materials in pockets.", "ptxt");
si[i++] = gsitm("N5110904M0000C00ENG.html", "During oxygen and acetylene gas welding, to protect eyes wear goggles according to the quantity of infrared rays.", "ptxt");
si[i++] = gsitm("N5110904M0000C00ENG.html", "During arc welding, to protect eyes wear a safety goggles with a shading plate according to the quantity of ultraviolet rays.", "ptxt");
si[i++] = gsitm("N5110904M0000C00ENG.html", "Gloves, apron, foot covers, earplugs and arm covers should be used to prevent burns.", "ptxt");
si[i++] = gsitm("N5110904N0000C00ENG.html", "Safety Stand", "title");
si[i++] = gsitm("N5110904N0000C00ENG.html", "After jacking up a vehicle body, be sure to support it with the safety stand. For the supporting positions, refer to “Lifting Points” in the Service Manual for each model.", "ptxt");
si[i++] = gsitm("N5110904O0000C00ENG.html", "Inflammables", "title");
si[i++] = gsitm("N5110904O0000C00ENG.html", "Before starting repair work, be sure to disconnect the negative terminal of the battery.", "ptxt");
si[i++] = gsitm("N5110904O0000C00ENG.html", "When welding parts near the fuel tank fuel filler, be sure to remove the fuel tank. Plug the filler port of the tank.", "ptxt");
si[i++] = gsitm("N5110904O0000C00ENG.html", "Plug the fuel pipe and brake pipes to avoid leakage when removing connectors from the pipes.", "ptxt");
si[i++] = gsitm("N5110904P0000C00ENG.html", "Working Environment", "title");
si[i++] = gsitm("N5110904P0000C00ENG.html", "Pay attention to ventilation and the health of workers.", "ptxt");
si[i++] = gsitm("N5110904P0000C00ENG.html", "Paint and sealant may generate poisonous gases when heated by fire. To prevent this, do not use a gas welder for cutting off damaged portions.", "ptxt");
si[i++] = gsitm("N5110904P0000C00ENG.html", "Use an air saw or an air chisel.", "ptxt");
si[i++] = gsitm("N5110904P0000C00ENG.html", "Use a belt sander or rotary wire brush for removing paint from the panel.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Handling of Welding Equipment", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(1) STORAGE OF GAS CYLINDERS", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "In a well ventilated area, post a “No Fire” sign.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Avoid the direct rays of the sun. Maintain temperature below 40°C (104°F).", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Inflammable gas cylinders and oxygen cylinders must not be stored in the same place.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Acetylene cylinders must be stored upright. Check that they cannot fall down.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(2) MOVEMENT AND TRANSPORTATION OF CYLINDERS", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Be sure to properly close the valve and securely install the cap.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not drag or roll the cylinder.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Use a cylinder transportation cart.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "When moving, tilt the cylinder slightly and roll it carefully on the bottom edge with one hand while supporting its cap with the other hand.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(3) USE OF CYLINDERS", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "The cylinder valve must be kept clean and free from oil.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "After opening the cylinder, leave the open-end wrench attached to the valve so it can be turned off quickly in an emergency.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "When the cylinder is replaced, open the valve of the new cylinder slightly and remove dust from around the valve seat.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "To check the cylinder for leakage, apply soapy water.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "The valve should be fully open for oxygen and open 1.5 turns or so for acetylene.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "To prevent the cylinder from falling down, ensure that it is properly secured.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "And never give a shock to the cylinder.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(4) HANDLING OF THE PRESSURE REGULATOR", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Always handle the pressure regulator with care and avoid impact.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Inspect the regulator periodically (at least once a year).", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "After use, purge the gas, and set the gauge to “0” (except the indoor type pressure regulator).", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(5) HANDLING OF WATER-SEALED SAFETY DEVICES", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "This device must be installed vertically. Check the water level every morning.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "In case of freezing, antifreeze solution can be added.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(6) HANDLING OF HOSES", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "All hoses must be checked before use for flaws or leaks.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Never use the pipe coupling made of copper or 70% copper alloy for the acetylene hose.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not use compressed oxygen to clean the gas hose.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not use any hose that has experienced backfire.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(7) HANDLING OF THE TORCH", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Keep the torch clean and free from oil.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "To replace the nozzle, use a special tool.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not use the torch as a hammer, etc.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not place it directly on the ground or on the floor.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Check suction of the torch at the end of the inflammable gas pipe coupling.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "(8) DANGER OF ARC WELDING ELECTRICAL SHOCK", "title");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Keep cables and connections in good shape.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Do not place machine in a wet place. Do not stand in a wet place when welding.", "ptxt");
si[i++] = gsitm("N5110904Q0000C00ENG.html", "Electrically ground welder. The vise clamp is not an electrical ground connection.", "ptxt");
si[i++] = gsitm("N5110904S0000C00ENG.html", "Use of Protectors", "title");
si[i++] = gsitm("N5110904S0000C00ENG.html", "Use of work clothes should be the same as for “PROTECTORS”. Refer to Protectors.", "ptxt");
si[i++] = gsitm("N5110904S0000C00ENG.html", "Wear a safety helmet and safety shoes.", "ptxt");
si[i++] = gsitm("N5110904S0000C00ENG.html", "When working under a vehicle or when using a grinder, wear goggles.", "ptxt");
si[i++] = gsitm("N5110904T0000C00ENG.html", "Precautions while Working", "title");
si[i++] = gsitm("N5110904T0000C00ENG.html", "To prevent danger in case the clamp slips or the panel breaks, be sure to apply a safety chain. Be careful not to stand near the area where the chain is stretched.", "ptxt");
si[i++] = gsitm("N5110904T0000C00ENG.html", "To prevent danger, any excessive slack in the safety chain must be taken up and properly wound.", "ptxt");
si[i++] = gsitm("N5110904T0000C00ENG.html", "Do not wear a working glove on the hand that is hammering.", "ptxt");
si[i++] = gsitm("N5110904T0000C00ENG.html", "Cracked glass must be removed or taped to prevent separation.", "ptxt");
si[i++] = gsitm("N5110904T0000C00ENG.html", "Any cut panels must be protected with cloth or tape.", "ptxt");
si[i++] = gsitm("N5110904U0000C00ENG.html", "Protection of Vehicle", "title");
si[i++] = gsitm("N5110904U0000C00ENG.html", "The seats and glass must be removed or covered with incombustible material, according to the type of work to be done, to prevent contamination and welding spatter.", "ptxt");
si[i++] = gsitm("N5110904U0000C00ENG.html", "When removing parts, utilize padding (cloth) or protective tape.", "ptxt");
si[i++] = gsitm("N5110904W0000C00ENG.html", "Danger from Dust", "title");
si[i++] = gsitm("N5110904W0000C00ENG.html", "If workers continue to inhale dust generated during paint film removal or body filler grinding work for long periods, they may suffer from respiratory insufficiency, which results in pneumoconiosis or asthma.", "ptxt");
si[i++] = gsitm("N5110904X0000C00ENG.html", "Precautions during Dust Generating Work", "title");
si[i++] = gsitm("N5110904X0000C00ENG.html", "Workers must use a sander equipped with a dust collecting function.", "ptxt");
si[i++] = gsitm("N5110904X0000C00ENG.html", "Workers must work in the facilities where a dust collector is installed on the floor or the wall.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Protector and Equipment", "title");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "(1) DUSTPROOF RESPIRATOR", "title");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "This is an important protector to prevent workers from inhaling dust.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "The cup type, gauze type, and other types of respirators are available.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "The respirators with the deodorizing function which utilizes activated carbons, or with the exhaust valve to release air can be selected.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "In order to maximize the respirator performance, be sure to cover your nose and mouth.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Do not use the respirator whose useful life has expired. This is because the function of the respirator has been deteriorated.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "(2) DUSTPROOF GOGGLES", "title");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Dustproof goggles prevent dust from entering workers\' eyes.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Goggles which can be worn on top of ordinary eyeglasses are also available.", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "(3) DUST COLLECTOR", "title");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Dustproof sander equipped with dust collecting bag", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Dustproof sander hose connected to the industrial cleaner", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Dust collector installed on the floor or the wall", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Dust collected through the filter", "ptxt");
si[i++] = gsitm("N5110904Y0000C00ENG.html", "Ambient air forcibly circulated", "ptxt");
si[i++] = gsitm("N5110904Z0000C00ENG.html", "Precautions during Air Blow", "title");
si[i++] = gsitm("N5110904Z0000C00ENG.html", "Workers must wear dustproof goggles and dustproof respirators, even during cleaning work after grinding.", "ptxt");
si[i++] = gsitm("N5110904Z0000C00ENG.html", "Adjust the pressure for air blow duster gun to prevent dust from being scattered all over the place.", "ptxt");
si[i++] = gsitm("N5110904Z0000C00ENG.html", "Be sure not to disturb other workers.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Paint Safety Precautions", "title");
si[i++] = gsitm("N511090510000C00ENG.html", "Observe the following precautions to maintain a safe painting work area.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Wear an approved respirator and eye protection when painting.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Wear approved gloves and appropriate clothing when painting. Avoid contact with skin.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Spray paint only in a well-ventilated area.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Cover spilled paint with sand or another absorbent material, or wipe it up at once.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "If paint gets in your mouth or on your skin, rinse and wash thoroughly with water. If paint gets in your eyes, flush with water and get prompt medical attention.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "After the painting work is finished, wash your face and gargle with water.", "ptxt");
si[i++] = gsitm("N511090510000C00ENG.html", "Paint is flammable. Store it in a safe place, and keep it away from sparks, flames, or cigarettes.", "ptxt");
si[i++] = gsitm("N511090540000C00ENG.html", "Fundamentals of Body Repair", "title");
si[i++] = gsitm("N511090540000C00ENG.html", "There are many kinds of damage caused by collisions.Therefore, the appropriate repair method for the damage should be selected. This section outlines repair methods of major damage and how to use the main tools.", "ptxt");
si[i++] = gsitm("N511090540000C00ENG.html", "BODY REPAIR FLOWCHART", "ptxt");
si[i++] = gsitm("N511090560000C00ENG.html", "Damage Diagnosis", "title");
si[i++] = gsitm("N511090560000C00ENG.html", "The damage must be diagnosed using the following criteria.", "ptxt");
si[i++] = gsitm("N511090560000C00ENG.html", "Location of damage", "ptxt");
si[i++] = gsitm("N511090560000C00ENG.html", "Range of affected area", "ptxt");
si[i++] = gsitm("N511090560000C00ENG.html", "Degree of damage", "ptxt");
si[i++] = gsitm("N511090560000C00ENG.html", "These three points relate directly to the quality, efficiency and cost of damage repair, and they must be determined correctly.", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "Determining Various Conditions of the Collision", "title");
si[i++] = gsitm("N511090570000C00ENG.html", "Size, shape, position, rigidity, etc. of the other vehicle involved in the collision", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "Speed of both vehicles at the time of collision", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "Collision angle and direction", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "Number of occupants and their positions at the time of collision", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "Size, shape, hardness, etc. of load in the vehicle", "ptxt");
si[i++] = gsitm("N511090570000C00ENG.html", "History of damaged portion, date of occurrence, and range of affected area", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "External Appearance", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "In body repair work, be careful not to overlook indirect damage. To avoid this, mechanical and structural analysis of the vehicle body is essential.", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "(1) OBSERVATION OF OVERALL VEHICLE", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "The extent of the impact damage", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Twisting, bending, and inclination of the whole vehicle", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Amount and location of damage: Check by examining the whole vehicle", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Examples", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Cracked or stressed paint", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Cracked or broken glass", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "(2) DETAILED OBSERVATION OF VEHICLE", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "Check for any gaps or dislocation at the welded seams of panels, or cracks in paint film, undercoating or sealing material.", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "(3) OBSERVATION OF FITTING", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "Examine the fit of various portions without lifting them.", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Estimate the damage in the pillar and hinge portions.", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Door alignment", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Alignment of hood and trunk lid", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "How doors, hood, and trunk lid open and close", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Smooth operation of windows", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "(4) CHECKING FOR MECHANICAL DAMAGE", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "Damage analysis also involves inspecting mechanical, steering and suspension parts for damage. When inspecting mechanical parts, look for signs of damage such as", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Bent or damaged parts", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Fluid leaks", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Binding or noise when turning the steering wheel", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "(5) DAMAGE BY INERTIA", "title");
si[i++] = gsitm("N511090580000C00ENG.html", "Check indirect damage such as a concave roof in frontend collisions, load damage and damage to the engine, which is insulated by rubber mounts.", "ptxt");
si[i++] = gsitm("N511090580000C00ENG.html", "Damaged or misaligned mounting points.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "Key Points in Choosing Repair Methods", "title");
si[i++] = gsitm("N511090590000C00ENG.html", "Do not reduce strength when repairing panels. Avoid excessive hammering which may lead to extending the panel.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "Also avoid prolonged heating.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "Do not increase the strength of impact absorbing portions unnecessarily. Do not patch these parts.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "Choose a method for properly aligning the body.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "For example, if changing the front side member of an FF car, it is recommended that the front suspension mounting member be left alone.", "ptxt");
si[i++] = gsitm("N511090590000C00ENG.html", "Examine carefully how past collision damage was repaired. This is necessary to properly decide the range to be repaired.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "Parts to be Replaced", "title");
si[i++] = gsitm("N5110905A0000C00ENG.html", "High-strength steel parts: The strength of these parts will be reduced if repaired by heating.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "Parts relating to body alignment and wheel alignment: Replacement of such parts would not provide proper alignment.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "When repair costs exceed replacement cost.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "Availability of service parts.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "When asked by customer.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "Repair of door side impact beam and bumper reinforcement is prohibited: Beams and reinforcements must be their original shape to perform as designed. Always replace door side impact beams and bumper reinforcements if damaged.", "ptxt");
si[i++] = gsitm("N5110905A0000C00ENG.html", "When performing repair work, it is necessary to consider quality, efficiency and cost, as well as safety and health. It is also important to gain the customer\'s confidence.", "ptxt");
si[i++] = gsitm("N5110905C0000C00ENG.html", "Checking Damage", "title");
si[i++] = gsitm("N5110905C0000C00ENG.html", "When completing body and frame repairs, the front body and underbody dimensions must be correct, because these dimensions directly affect wheel alignment and steering angles.", "ptxt");
si[i++] = gsitm("N5110905C0000C00ENG.html", "The degree of damage should be determined by using a steel tape, tram tracking gauge and centering gauge or other measuring device. The measuring points are shown in the Body Repair Manual for each model. Wheel alignments are shown in the Service Manual for each model.", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Centering Gauge", "title");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Suspend the body so that it is symmetrical to the frame member. Check for bending or twisting in the body.", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "(1) TYPES", "title");
si[i++] = gsitm("N5110905D0000C00ENG.html", "(2) DETERMINING STATE OF DEFORMATION", "title");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Normal state", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "The horizontal bar and center target are in their correct positions.", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Twist", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "The horizontal bar is tilted on both ends.", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Sag", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "One of the horizontal bars is lower in the vertical direction than the others.", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "Side-sway", "ptxt");
si[i++] = gsitm("N5110905D0000C00ENG.html", "The horizontal bars are correctly aligned, but the center target is displaced.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "Tracking Gauge and Steel Tape", "title");
si[i++] = gsitm("N5110905E0000C00ENG.html", "Measure the distance between two points. Before using the tracking gauge, check the measuring points with the steel tape.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "(1) TRACKING GAUGE", "title");
si[i++] = gsitm("N5110905E0000C00ENG.html", "Fit the tracking gauge correctly to the measuring point.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "The dimension is indicated between the hole center.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "If measurement is unavailable, use the method shown below.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "(2) STEEL TAPE", "title");
si[i++] = gsitm("N5110905E0000C00ENG.html", "Shape the end of the rule for ease of measurement.", "ptxt");
si[i++] = gsitm("N5110905E0000C00ENG.html", "If the measuring point hole diameter is different, use the following measuring method.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "Three-dimensional Measuring Equipment", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "The equipment has function of the measurement to display the vehicle measuring points in three dimensions: height, width and length.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "(1) UNIVERSAL JIG TYPE", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "This is one of the universal jig type body straightening equipment functions. The jig is assembled according to the instruction card specific to each vehicle model. The jig, which can move forward/backward, left/right, and up/down, is anchored to each location on the underbody. The three-dimensional coordinates for the anchored point are read from the scale at the sliding base and jig head positions.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "(2) UNIVERSAL MEASURING TYPE", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "The probe, which can move forward/backward, left/right, and up/down, is positioned on the frame. The three-dimensional coordinates at the measurement point and the distance between measurement holes can be measured by bringing the probe into contact with a locating hole on the body.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "It is set on the straightening equipment for use.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "(3) LASER TYPE", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "The three-dimensional coordinates are read using convergence and straight-line stability of a laser beam.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "A laser beam is used for measurement. Once set, repair work can be performed during measurement.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "(4) COMPUTER MEASURING TYPE", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "This is set on the straightening equipment. The probe which is mounted on flexible arm is positioned at each point of the vehicle body for measurement.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "The computer compares the vehicle model data and the actual measurement data to identify the damage range and determine acceptability.", "ptxt");
si[i++] = gsitm("N5110905F0000C00ENG.html", "(5) ULTRASOUND TYPE", "title");
si[i++] = gsitm("N5110905F0000C00ENG.html", "Ultrasound is transmitted from the probe, installed at the measurement point on the vehicle body, to the beam placed under the body in order to measure the three-dimensional coordinates at each measurement point.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Comparison of Pulling Methods", "title");
si[i++] = gsitm("N5110905H0000C00ENG.html", "(1) HYDRAULIC RAM TYPE", "title");
si[i++] = gsitm("N5110905H0000C00ENG.html", "In this method, the pressing force of a hydraulic ram is converted to a pulling force by a chain.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Pulling points on the body may be added easily, and there is more freedom to select the pulling direction.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The pulling direction changes during pulling.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Difficult to simultaneously pull several points on a vertical line.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "(2) TOWER TYPE I", "title");
si[i++] = gsitm("N5110905H0000C00ENG.html", "In this type, force is applied by the hydraulic ram pushing the post.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "A strong force is obtained because a large ram is used, creating much leverage.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The chain can be hooked to the post in many ways.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Leverage can be increased or decreased by changing the position of the hook.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The pulling direction is not restricted by the shape of the bench or a floor anchor.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Difficult to increase the number of pulling points on the body because the pulling tool itself is large.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "(3) TOWER TYPE II", "title");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The chain is wound up through the tower by an electric or hydraulic motor.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The direction of force does not change during pulling.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "The chain is easily set on the post because the pulling direction is constant.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Provides great flexibility in pulling direction.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Pulling points on the body are restricted by the number of posts.", "ptxt");
si[i++] = gsitm("N5110905H0000C00ENG.html", "Pulling force is relatively strong.", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "Clamps", "title");
si[i++] = gsitm("N5110905I0000C00ENG.html", "Generally speaking, when a body has to be straightened, the pulling device and the body must be attached to each other and the body itself must remain stationary. For this purpose, various clamps are used.", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "Common types of clamps and their characteristics are listed below:", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "DIRECTIONAL CHARACTERISTICS", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "When pulling the clamp, the line of pulling force must extend through the center of the clamp teeth. Otherwise, the clamp may come off or damage the body panel as the clamp rotates.", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "The figure shows how the direction of the chain\'s pulling force is at a downward angle from the center of the teeth. This generates a turning force on the entire clamp in the direction of the arrow. This force is amplified because of leverage, but only some of its teeth are engaged. Thus, the clamp tends to slip, which results in deformation of the body panel.", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "Clamp direction is important in creating the pulling force. Fundamentally, three directions are considered, ″X″, ″Y″ and ″Z″.", "ptxt");
si[i++] = gsitm("N5110905I0000C00ENG.html", "Directional (″X″, ″Y″ and ″Z″) characteristics are shown below for several kinds of clamps.", "ptxt");
si[i++] = gsitm("N5110905J0000C00ENG.html", "Hooks and Other Tools", "title");
si[i++] = gsitm("N5110905J0000C00ENG.html", "(1) HOOKS", "title");
si[i++] = gsitm("N5110905J0000C00ENG.html", "Unlike clamps which grab an object, hooks are curved tools that pull on the body. When a hook is used, it must be set so that the point where the body is pulled and the position of the hook\'s chain are lined up straight.", "ptxt");
si[i++] = gsitm("N5110905J0000C00ENG.html", "When a hook is used, a piece of wood, etc. should be inserted between the hook and body in order to prevent damage to the body.", "ptxt");
si[i++] = gsitm("N5110905J0000C00ENG.html", "(2) SPECIFIC-USE PULLING TOOL", "title");
si[i++] = gsitm("N5110905J0000C00ENG.html", "Specific-use pulling tools are special jigs which are used to repair a specific part of the vehicle.", "ptxt");
si[i++] = gsitm("N5110905J0000C00ENG.html", "An example of a specific-use pulling tools, a strut puller, is shown in the figure.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "High Intensity Cabin Structure", "title");
si[i++] = gsitm("N5110905K0000C00ENG.html", "In recent years, the body construction of vehicles is changing for the purpose of protecting passengers at the time of the collision.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "A greater use of high strength sheet steel reinforcements and the adoption of sheet steels of different thicknesses are good examples of securing survival space for passengers. Deformation caused when the vehicle body is damaged is controlled through modification of the body construction.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "The following points must be kept in mind when high intensity cabin structure bodies need to be repaired.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "No special skills are necessary in body straightening work.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "Body technicians must have a good understanding of the construction of the vehicle body to be repaired.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "Understanding the accurate damage range (performing accurate measuring work) is necessary.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "A greater force is required for straightening because of an increased use of high strength steel plate reinforcements.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "It is necessary to perform additional anchoring for the frame straightening equipment with which multiple jig anchoring is not possible in order to prevent secondary damage.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "Pulling force must be applied evenly to prevent welded points from breaking. (Simultaneous pulling in multiple directions, etc.)", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "The anchoring jig specific to each vehicle model is used for vehicles which cannot be anchored at the sill lower flange.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "(1) HIGH INTENSITY CABIN STRUCTURE", "title");
si[i++] = gsitm("N5110905K0000C00ENG.html", "When a front or rear end collision occurs, the crushable zone provided at the front and rear of the vehicle effectively absorbs impact energy and cushions the shock to the passengers. In addition, the safety zone securely maintains a survival space.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "Energy absorbing beads and high strength sheet steel reinforcements are used as front side members.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "Outrigger construction. (Distributes impact energy from front side members.)", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "(2) HIGH INTENSITY CABIN STRUCTURE (SIDE IMPACT)", "title");
si[i++] = gsitm("N5110905K0000C00ENG.html", "To improve the lateral strength of the occupant compartment, lateral strength such as crossmembers, steering member and reinforcements for roof side, center pillars and body sills are redesigned.", "ptxt");
si[i++] = gsitm("N5110905K0000C00ENG.html", "When a side collision occurs, the side door beams and doors minimize deformation of the body by absorbing impact energy subjected from the lateral direction, and by distributing energy over the reinforced body side.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Securing the Vehicle", "title");
si[i++] = gsitm("N5110905M0000N00ENG.html", "To prevent the movement of vehicle, use a suitable method that can resist the pulling force required for repair.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "(1) ANCHORING POINT", "title");
si[i++] = gsitm("N5110905M0000N00ENG.html", "For passenger vehicle", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Choose the foundation of a rigid pillar or a member for anchoring point.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Set the equipment so that the direction of claw clamp is opposite to the direction of pull.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "(2) ATTACHMENT OF CHAINS", "title");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Pulling to the front of vehicle", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "The vehicle will be secure if it is pulled in the range indicated by the arrows in the figure. The rear side is the opposite of this.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Pulling to the left or right side", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "Pull the vehicle within the range indicated by arrows.", "ptxt");
si[i++] = gsitm("N5110905M0000N00ENG.html", "(3) ANCHORING POINT FOR FRAME MODEL USING FRAME CLAMPING", "title");
si[i++] = gsitm("N5110905M0000N00ENG.html", "If the frame cannot be anchored to the straightening equipment with the basic anchoring method the frame can be directly anchored by using frame clamping system. The figure shows an example in which the spring shackle is anchored without the spring being removed.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "Securing and Pulling", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "In principle, the pulling force must be applied in the exact opposite direction of the impact force (input). The securing method must match this pulling direction.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(1) DOWNWARD PULL", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "Secure as close to the damaged portion as possible. If there is a separation between the pulling point and damaged point, the undamaged portion will also be pulled.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(2) UPWARD PULL", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "Set the supporting so that undamaged portions will not be affected by pulling.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(3) FIXING AND PULLING METHOD FOR SIDE BEND", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "To pull the front part of vehicle, secure the vehicle body to avoid movement by the moment of rotation caused by pulling.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(4) FIXING AND PULLING METHOD FOR DIAMOND", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "If only points (A) and (B) are secured, a moment of rotation may result. Establish another supporting point at portion (C).", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(5) SIMULTANEOUS PULLING IN MULTIPLE DIRECTIONS", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "This method can shorten repair time, and also prevent secondary damage.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(6) SIMULTANEOUS PUSH-PULL METHOD", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "This method may be used when stress is concentrated at the front side member. The front of the front side member is bent inward while the rear is bent outward.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "(7) ROOF DAMAGE", "title");
si[i++] = gsitm("N5110905N0000C00ENG.html", "Connect an extension tube to the ram.", "ptxt");
si[i++] = gsitm("N5110905N0000C00ENG.html", "Positioning it near the vehicle body will result in increased pulling length.", "ptxt");
si[i++] = gsitm("N5110905P0000C00ENG.html", "Repair Sequence", "title");
si[i++] = gsitm("N5110905P0000C00ENG.html", "In general, no single bend or twist is produced in a collision. Body deformation results from a combination of bending and twisting and other types of damage.", "ptxt");
si[i++] = gsitm("N5110905P0000C00ENG.html", "Repair should start where the damage is most deeply propagated.", "ptxt");
si[i++] = gsitm("N5110905P0000C00ENG.html", "If concentrating only on apparent damage while overlooking the propagation of impact to the whole body, it is impossible to obtain correct body alignment.", "ptxt");
si[i++] = gsitm("N5110905P0000C00ENG.html", "Repair work should basically be performed in this order of damage.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Key Points in Actual Repair Work", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Illustration shows a badly damaged side member for clarity. Badly damaged or kinked side rails must always be replaced.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(1) STRETCHING SHRUNK PORTIONS", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "The repair of a bent closed cross-sectional structure, such as a side member, is done by clamping the surface of the bent-in side and pulling. The pulling direction should be such that force is applied in the direction of an imaginary straight line extending through the original position of the part.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Sometimes a load of approximately 5,000 kg (11,025 lb) is applied during repair work. Accordingly, the clamp must be tightened securely. Be sure to use safety chain.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(2) GRADUAL PULL", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Pull step by step.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "The damaged portion may be work hardened.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Pulling all at once may cause cracking.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Reduce the hardness of the work-hardened portion.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Locally heat the panel to 400°C - 500°C (752°C - 932°F) to the extent that the panel is not colored. Do not heat above 700°C (1,292°F), or strength will be reduced. Do not raise to a temperature of more than 550°C (1,020°F) for HSS parts.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(3) CONSIDER SPRING-BACK", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "When pulling force is applied to a panel, spring-back is generated by the residual stress.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Proper amount of pull", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Pull 2 mm - 3 mm (0.08 in - 0.12 in) more than the required dimension. Adjust the amount of pull corresponding to the spring-back.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Use of hammer", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Residual stress caused by kinetic energy of the collision can be removed by hammering.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(4) DETERMINING PROPER AMOUNT OF PULL BY OBSERVING DOOR FIT", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "The proper amount of pull can be determined by observing the clearance at the door or trunk lid.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(5) PULLING UPPER PORTIONS FROM UNDERBODY CLAMP", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Note that if there is distance between the pulling point and the underbody clamp, as indicated by (A) in the figure, a moment of rotation is produced.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "This may cause secondary damage to the clamped portion.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Provide a supporting point under the side member to prevent generation of this moment of rotation.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(6) ADDITIONAL ANCHORING", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "Pulling work must be performed with care taken not to damage the anchoring points or undamaged area of the body. If area not targeted for repair is affected by the excessive pulling force or the direction of pulling, additional anchoring points need to be provided to protect undamaged areas. Side sills are strong enough against longitudinal force, however, they are easily damaged by downward or lateral force. For this reason, additional anchoring should be provided by supporting side members with the port power, or attaching a clamp and chain.", "ptxt");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "(7) PURPOSE OF BODY ALIGNMENT", "title");
si[i++] = gsitm("N5110905Q0000C00ENG.html", "This operation is necessary to obtain correct alignment of parts to be used again. Therefore, the damage caused by propagated impact is recovered by pulling out the first input point.", "ptxt");
si[i++] = gsitm("N5110905S0000C00ENG.html", "Replacement of Panel", "title");
si[i++] = gsitm("N5110905S0000C00ENG.html", "Panel replacement work includes replacement of the front fenders and hood which are installed by bolts, and replacement of rear fenders and the roof which are welded. This section explains panel replacement procedures after adjusting body alignment.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Door Hemming", "title");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(a) Sand the edge part of door outer panel using belt sander.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(b) Insert the tip of a sharp-edged tool, such as a chisel, into the clearance at door outer panel. Use a hammer to tap the tool inserted into the clearance from the side to separate the door inner panel and door outer panel.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(c) Remove the adhesive adhering to the door inner panel flange area surface.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(d) Adjust the position where the new door outer panel and door inner panel overlap. Once these are positioned correctly, fix them with clamps to prevent them from being displaced.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Apply new adhesive to both door outer panel and door inner panel.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "&lt;Adhesive>", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "3M™ Automix™ Panel Bond 8115 or equivalent", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(e) Hold the dolly on the corners of the flange at door outer panel. Tap the dolly with a hammer to bend the door outer panel flange area gradually.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(f) Bend with hammer until the angle of the whole circumference of the door outer panel flange area becomes approximately 45°.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(g) Check that the position of the door outer panel and door inner panel is not displaced while tapping it with a hammer to bend it until the angle of whole circumference of the door outer panel flange area becomes approximately 15°.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(h) Check that the position of the door outer panel and door inner panel is not displaced while taping it with a hammer to bend it until the angle of the whole circumference of the door outer panel flange area becomes approximately 0°.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(i) Use the hemming tool [SST: KV991-10000] to adjust the shape of the whole circumference of the door outer panel flange area.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "(j) Seal up the area around the hemmed end of the flange.", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Door inner panel", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Door outer panel", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Adhesive", "ptxt");
si[i++] = gsitm("N5110905T0000C00ENG.html", "Sealant", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Adjustment Fitting of Front Fender", "title");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Fitting adjustment means adjustment of clearance or gradient of the hood, door, front fender, etc. with respect to its adjacent part, and adjustment of gradient at the press line.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Adjustment of front fender is described as an example.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Adjust the fitting at the front fender mounting position. Tighten the front fender mounting bolts loosely, and adjust the fit by moving the front fender sideways or in the up-down direction while observing the clearance with the hood and door.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Adjust the front fender bend angle.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "If a proper fit cannot be obtained by step (1) above, change the bending angle of the front fender.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Explanation", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Condition", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "Correction method", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "When the clearance between the front fender and hood is too small: Apply a flat wood plate to the upper corner of front fender, and correct by hammering. Before hammering, securely tighten the front fender mounting bolts.", "ptxt");
si[i++] = gsitm("N5110905U0000C00ENG.html", "When the clearance between the front fender and hood is too large: Apply a scribing chisel to the bend at the base of the front fender. Tap with a hammer to adjust the clearance. Securely tighten the front fender mounting bolts before tapping. Apply the scribing chisel along the press line.", "ptxt");
si[i++] = gsitm("N5110905V0000C00ENG.html", "Adjustment Fitting of Door Assembly", "title");
si[i++] = gsitm("N5110905V0000C00ENG.html", "When there is excessive clearance on the upper part of door:", "ptxt");
si[i++] = gsitm("N5110905V0000C00ENG.html", "Apply a wood block between the outer sill and the lower side of door, and push the upper part of door.", "ptxt");
si[i++] = gsitm("N5110905V0000C00ENG.html", "When there is excessive clearance on the lower part of door.", "ptxt");
si[i++] = gsitm("N5110905X0000C00ENG.html", "Partial Replacement of Panel (Welded Panel)", "title");
si[i++] = gsitm("N5110905X0000C00ENG.html", "If damage occurs in a welded panel, it can be entirely replaced by a service panel or partial replacement can be done by cutting and replacing damaged portion with a service panel.", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Welded Panel Replacement Procedure", "title");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "When welding and dressing the parts, cover up holes of these parts with tape to prevent debris from entering.", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Assembly panel replacement or partial panel replacement", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Assembly panel replacement means replacement of a complete panel by cutting all the welded portions.", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Partial panel replacement is a method by which only the damaged portion of a panel is replaced. Partial panel replacement can be used when assembly panel replacement is too costly and time consuming, and when the damage is localized.", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Cutting positions for partial replacement", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "The illustration is just example, please see each BRM for details.", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Cutting panels for partial replacement is not allowed on some portions. If panels are cut in improper portions, body strength cannot be maintained. The allowable positions vary with body structure, panel strength or shape and differ from model to model. They are indicated in the Body Repair Manual of each model. In principle, the following portions may be cut:", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Portions without reinforcement or ducting", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Portions where no stress concentration occurs", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Portions with small finish area where finishing can be easily accomplished (where the connected portions can be covered by garnish or molding)", "ptxt");
si[i++] = gsitm("N5110905Y0000C00ENG.html", "Portions where work area or disassembling of parts is minimized", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Rough Cutting of Panel", "title");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Most body panels are joined by spot welding. It is difficult to cut them at the welded portion.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "To shorten work time, pull the damaged portion roughly, them cut near the panel joint in advance so that tools can be used properly to cut the spot welded portion. It is commonly used on panels having complicated structures.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Cutting body panel and service panels by leaving an overlap tolerance is also called rough cutting.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Use the cutting tools properly according to the portion to be cut, panel thickness, and panel structure.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Tools commonly used for this purpose and their features are described below:", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(1) ROUGH CUTTING USING AN AIR SAW", "title");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(a) Major application", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Members and pillars including side member, cross member, rear pillar, etc.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(b) Features", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Clear cut line. Suitable for cutting both thin and comparatively thick sheet metal.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(2) ROUGH CUTTING USING AN AIR CHISEL", "title");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Thin sheet metal including the rear fender and rear floor", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Faster cutting speed", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "High noise level", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Not applicable to thick sheet metal", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Irregular cut line", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Excessive sparking", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(3) ROUGH CUTTING WITH AN OXY-ACETYLENE CUTTING TORCH", "title");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Thick sheet metal including side member, cross member, hoodledge, etc.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "(4) ROUGH CUTTING WITH A PLASMA CUTTER", "title");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Floor, door, rear fender, roof, flat panels.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Only small will be affected by heat.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "This is suitable for cutting conductive materials.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Aluminum, stainless, and carbon steel can be cut.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Cut off damaged portion as shown in the figure.", "ptxt");
si[i++] = gsitm("N5110905Z0000C00ENG.html", "Be careful not to cut inner rear pillar reinforcement.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "Cutting Off Welded Portions", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "A vehicle body is constructed by using three different welding methods [spot welding, gas shielded arc (GSA) welding and brazing]. Cutting welded portion by these methods is described below.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "Spot welding is generally used on two or more overlapped panels. The tool or cut off method must be changed according to whether the panel to be removed is on the top, in the middle or on the bottom.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(1) CONFIRMING THE SPOT WELDED POSITION", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "Remove paint, undercoat, and sealer from the panel to confirm the spot welded positions.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(a) Using air sander or rotary wire brush:", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "When using this method, do not grind too much of the panel. Sand or brush the panel while confirming the spot welded portion.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(b) Using a chisel:", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "If the spot welded portion is indiscernible even after removing paint, insert the chisel blade between the panels and tap lightly with a hammer for confirmation.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(2) CUTTING OFF SPOT WELDED PORTION", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "(a) Using a spot cutter:", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "There are two types of spot cutters (a drill type and a hole saw type). When using the spot cutter, be careful not to cut the lower panel.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "If it is difficult to weld from behind the lower panel, the spot cutter may be used to cut the spot welded portions without drilling the bottom panel.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "The hole saw type spot cutter requires grinding of the spot weld after cutting. This requires additional work time.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(b) Using drill:", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "The drill may be used to cut welds from any portion welded by plug welding, by drilling out the plug welded portion.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(3) CUTTING SPOT WELDED PORTIONS WITH AN AIR SANDER", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "If the spot cutter cannot be used, use the air sander (or belt sander) to cut off the spot welded portion.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(4) REMOVING PANEL WITH A CHISEL", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "After cutting the spot welded portions, separate the panel using the chisel.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "By doing this, spot welded portions will separate from their mating surfaces. Thus, work can proceed while confirming the separation of spot-welded portions.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(5) CUTTING GSA WELDED PORTIONS", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "The GSA welding method is divided into two types (plug welding and seam welding). The plug weld portion can be cut off with a spot cutter or the like. To cut off the seam welded portion, grind the seam-weld bead with an air grinder to cut the welded portion. Be careful to grind from the replacement panel. Do not grind the reused panel excessively.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "GSA = Gas Shielded Arc welding", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(6) CUTTING OFF BRAZED PORTION OF PANEL", "title");
si[i++] = gsitm("N511090600000C00ENG.html", "Brazing is used to improve the external appearance of the joined portion (roof and fender) of the body outer panel as well as to improve sealing. Brazed portions can be generally disconnected by dissolving the braze with an oxy-acetylene torch.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "If arc brazing was used, cut off the welded portion with an air sander or the like. The melting temperature of arc brazed metal is higher than that of ordinary brazing, and the panel may be damaged by this high temperature. Ordinary brazing and arc brazing may be discriminated by observing the color of the brazed metal. Ordinary brazing looks like a brass, while arc brazing has a copper color.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(a) Cutting with an oxy-acetylene torch", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "Melt the filler metal with the oxy-acetylene torch.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "Remove the metal with a wire brush and separate the panel. While the filler metal is still hot, insert the tip of a screwdriver or the like between panels to prevent re-adhesion.", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "(b) Cutting with an air grinder", "ptxt");
si[i++] = gsitm("N511090600000C00ENG.html", "Cut off the brazed portion with the air grinder. Do not grind excessively the panel to be reused.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "Precautions for High Strength Steel (HSS) and Ultra High Strength Steel (UHSS)", "title");
si[i++] = gsitm("N511090610000C00ENG.html", "High strength steel (HSS) means the steel from 440 MPa - 979 MPa.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "Ultra high strength steel (UHSS) means the steel above 980 MPa.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "(a) The repair of reinforcements (such as side members) by heating is not recommended since it may weaken the component. When heating is unavoidable, do not heat HSS parts above 550°C (1,022°F). Verify heating temperature with a thermometer. (Crayon-type and other similar type thermometer are appropriate.)", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "When you heat the HSS or UHSS parts above 550°C (1,022°F), it must be replaced with new parts.", "par1");
si[i++] = gsitm("N511090610000C00ENG.html", "(b) When straightening body panels, use caution in pulling any HSS panel. Because HSS is very strong, pulling may cause deformation in adjacent portions of the body. In this case, increase the number of measuring points, and carefully pull the HSS panel.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "(c) When cutting HSS panels, avoid gas (torch) cutting if possible. Instead, use a saw to avoid weakening surrounding areas due to heat. If gas (torch) cutting is unavoidable, allow a minimum margin of 50 mm (1.97 in).", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "(d) When welding HSS panels, use spot welding whenever possible in order to minimize weakening surrounding areas due to heat.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "If spot welding is impossible, use GSA welding. Do not use gas (torch) welding because it is inferior in welding strength.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "(e) The spot weld on HSS panels is harder than that of an ordinary steel panel.", "ptxt");
si[i++] = gsitm("N511090610000C00ENG.html", "Therefore, when cutting spot welds on a HSS panel, use a low speed high torque drill (1,000 rpm - 1,200 rpm) to increase drill bit durability and facilitate the operation.", "ptxt");
si[i++] = gsitm("N511090620000C00ENG.html", "Prohibition for Ultra High Strength Steel (UHSS)", "title");
si[i++] = gsitm("N511090620000C00ENG.html", "Ultra high strength steel (UHSS) means the steel from 980 MPa or higher.", "ptxt");
si[i++] = gsitm("N511090620000C00ENG.html", "Never cut and joint the panel, plate and reinforcement made of ultra high strength steel (UHSS).", "ptxt");
si[i++] = gsitm("N511090620000C00ENG.html", "If such part is damaged, replace the part.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "Rear Fender Hemming Process", "title");
si[i++] = gsitm("N511090630000C00ENG.html", "When the rear fender and the outer wheel housing have been joined with adhesive, the panel replacement method described below is used.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "A wheel arch is to be installed and hemmed over left and right outer wheel house.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "In order to hem the wheel arch, it is necessary to repair any damaged or defaced parts around outer wheel house.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "Ensure that the area that is to be glued around outer wheelhouse is undamaged or defaced.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "Procedure of the hemming process", "title");
si[i++] = gsitm("N511090630000C00ENG.html", "(a) Peel off old bonding material on the surface of outer wheelhouse and clean thoroughly.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(b) Peel off a primer coat in the specified area where new adhesive is to be applied on rear fender. (the replacing part.)", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(c) Apply new adhesive to both specified areas of outer wheelhouse and rear fender.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "&lt;Adhesive>", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "3M™ Automix™ Panel Bond 8115 or equivalent", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(d) Attach rear fender to the body of the car, and weld the required part except the hemming part.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(e) Bend the welded part starting from the center of the wheel arch gradually with a hammer and a dolly. (Also hem the end of the flange.)", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(f) Hemming with a hammer is conducted to an approximate angle of 80°.", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(g) Starting from the center, hem the wheel arch gradually, using slight back and forth motion with a hemming tool [SST: KV991-10000].", "ptxt");
si[i++] = gsitm("N511090630000C00ENG.html", "(h) Seal up the area around the hemmed end of the flange.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "Welding Method for Stud Bolt and Nut", "title");
si[i++] = gsitm("N511090640000C00ENG.html", "When stud bolts and weld nuts are not welded on the part acquired for repair, and are supplied as separate parts, use the following method to perform welding.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "(1) FLANGE BOLT", "title");
si[i++] = gsitm("N511090640000C00ENG.html", "Remove paint, rust, or oils on the surface of the panel.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "Insert the bolt, temporarily tighten the matching nut of the bolt, and perform centering.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "Weld 3 points evenly by MIG weld. [approximately 3 mm (0.12 in)]", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "Apply an appropriate anti-corrosive treatment to the respective locations.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "The same welding method is also applied when welding on a panel surface without a through hole. Welding is performed with the bolt head surface and panel contact surface contacting.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "(2) WELD NUT", "title");
si[i++] = gsitm("N511090640000C00ENG.html", "Put the nut on the panel center of the hole, temporarily tighten the matching bolt of the nut, and perform centering.", "ptxt");
si[i++] = gsitm("N511090640000C00ENG.html", "Weld 3 or 4 points evenly by MIG weld. [approximately 3 mm (0.12 in)]", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Preparation for Service Panel Installation", "title");
si[i++] = gsitm("N511090650000C00ENG.html", "After removing the damaged panel, two operations are needed. Preparation for service panel installation and finishing of the panel mounting portion of the body.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(1) FINISHING BODY", "title");
si[i++] = gsitm("N511090650000C00ENG.html", "(a) Grind clean around the area where the spot-welded panel has been removed. Thoroughly remove rust and other contamination from the mating surface.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Also, remove paint from the portion to be welded.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Any brazing metal should be thoroughly removed, otherwise welding will be impaired.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(b) Irregularities on the panel mating surface prevent the panel from being welded correctly. Using a hammer and dolly, correct the shape of the mating surface.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(c) Apply conductive anti-corrosive treatment [spot sealer for spot welding or weld through primer (metallic solution) for GSA welding] in places that cannot be painted in the subsequent painting process.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(d) If it is impossible to apply sealer after welding the service panel, sealer should be applied before welding.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(2) PREPARATION FOR SERVICE PANEL INSTALLATION", "title");
si[i++] = gsitm("N511090650000C00ENG.html", "(a) The service panel is coated with primer. Remove the primer and apply spot sealer at the portions to be welded. Do not allow the spot sealer to be forced out of the mating surface of the panel.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(b) Drill the service panel for plug welding, if necessary.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Refer to the Body Repair Manual of applicable model for the number of holes to be drilled for plug welding. The number of holes must be the same as the number of original spot welds. The drill holes must be spaced equally. Drill hole diameter must be changed according to panel thickness to maintain welding strength.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Plug hole diameter and panel thickness", "title");
si[i++] = gsitm("N511090650000C00ENG.html", "Panel thickness", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Plug hole dia.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Below 1.0 mm (0.039 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Below 5 mm (0.20 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "1.0 mm - 2.4 mm", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(0.039 in - 0.094 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "6.5 mm - 10 mm", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(0.256 in - 0.394 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Over 2.4 mm (0.094 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Over 10 mm (0.39 in)", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "(3) UNDERSTANDING SERVICE PARTS", "title");
si[i++] = gsitm("N511090650000C00ENG.html", "This is important in judging when the panel should be replaced, or in determining conditions for efficient operation.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Service parts should be prepared with reference to the Parts Catalog for each model.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "The integral type outer body side panel consists of two types of service panels. These service panels need to be cut for use depending on the location and degree of the damage.", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Separate type outer body side panel", "ptxt");
si[i++] = gsitm("N511090650000C00ENG.html", "Integral type outer body side panel", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "Anti-corrosive Treatment", "title");
si[i++] = gsitm("N511090660000C00ENG.html", "Anti-corrosive treatment may be performed on three different occasions (before welding, before painting, and after painting). This section explains anti-corrosive treatment for the latter two occasions.", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "(1) ANTI-CORROSIVE TREATMENT BEFORE PAINTING", "title");
si[i++] = gsitm("N511090660000C00ENG.html", "Application of body sealer", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "Body sealer prevents water or mud from entering through the mating surface of the panel. It also prevents formation of corrosion. The sealer nozzle hole should be small. Use a finger or brush to shape the applied sealer. Refer to the Body Repair Manual for body sealer application points.", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "Application of undercoating", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "Apply undercoating to the underbody and inside of wheelhouse. Do not apply it to the exhaust pipe, suspension or driving portions.", "ptxt");
si[i++] = gsitm("N511090660000C00ENG.html", "(2) ANTI-CORROSIVE WAX AFTER PAINTING", "title");
si[i++] = gsitm("N511090660000C00ENG.html", "Apply anti-corrosive wax to the back of the panel where painting is difficult. Insert the nozzle of anti-corrosive wax into the holes in the inner panel. Apply until the anti-corrosive wax bleeds out from panel mating surface.", "ptxt");
si[i++] = gsitm("N511090680000C00ENG.html", "Use of Body Filler (Putty) and Grinding", "title");
si[i++] = gsitm("N511090680000C00ENG.html", "Panel irregularities may be corrected with a hammer and dolly. However, exact restoration of the original shape with these tools takes a long time. Body filler may be used to restore the original panel profile. For this purpose, the panel surface is finished slightly lower than the original surface.", "ptxt");
si[i++] = gsitm("N511090680000C00ENG.html", "Filler is applied to finish the shape and also to reduce the time needed for repair.", "ptxt");
si[i++] = gsitm("N511090680000C00ENG.html", "In body repair shops, the most commonly used materials are body filler, polyester putty, and detail putty.", "ptxt");
si[i++] = gsitm("N511090680000C00ENG.html", "This section mainly describes the body filler.", "ptxt");
si[i++] = gsitm("N511090680000C00ENG.html", "Polyester putty is described in the paint manual.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Types of Filler and Putty", "title");
si[i++] = gsitm("N511090690000C00ENG.html", "Type (Standard thickness limits)", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Characteristics", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Body Filler Putty", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "(For repairing of large dents or scratches)", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "[10 mm (0.39 in)]", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Surform type", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "This type of filler requires surforming (rough grinding). It will clog sandpaper if it is sanded only.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Can be thickly applied to panel.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "After drying, grindability is poor as it is harder than other types.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Light Type", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "This type of filler contains tiny hollow beads. It feels gritty when applied with a spatula.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Suitable for thick application to panel", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Superior grindability after application", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Forms blowholes easily", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Glass Fiber or Aluminum Powder Type", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Excellent thick application to panel", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Superior corrosion prevention and durability", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Suitable for repairing rusty holes in panel", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Intermediate Filler Putty [10 mm (0.39 in)]", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Good sanding characteristics.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "It is difficult for fine grain pores to form in it, so poly putty can be eliminated and surfacer can be applied directly over intermediate filler.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Polyester Putty", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "(For filling pores and sand scratches in body filler)", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Spatula Type", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "[3 mm (0.12 in)]", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Not very much thickness can be built up.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "It has fine grain and good flexibility.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Since no volatile content remains, there is no depletion after baking.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Sanding characteristics are good.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Spray Type", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "[1 mm (0.04 in)]", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Not very much thickness can be built-up.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Since a spray gun in used, it can be applied easily to any location.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Drying time is approximately two times as long as putty applied with a spatula.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Lacquer Putty [0.1 mm (0.004 in)]", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "(Detail putty)", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "It is soft and flexible.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "It cannot be used to built up low areas.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Standing characteristics are extremely good.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "The thicker the built-up, the longer the drying time.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Ultraviolet Curing Putty", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Since the drying time is short (approximately 20 seconds after UV irradiation), body work can be completed in a short period of time.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "This is often used for minor repairs.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Putty becomes very hard after hardening, therefore its grindability with sandpaper is not good.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "It is expensive.", "ptxt");
si[i++] = gsitm("N511090690000C00ENG.html", "Putty film thickness limits should be decided with putty manufacturer because limits vary from maker to maker.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Procedure for Applying Body Filler", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(1) REMOVAL OF PAINT", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Using an air sander, remove old paint from the panel surface for better filler adhesion. Form a featheredge on the panel surface approximately 20 mm (0.79 in) wider than the correction area in order to eliminate traces of body filler application.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(2) CHEMICAL CONVERSION COATING", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Body skin panels of Mitsubishi Motors vehicles use anti-corrosive steel. These panels should be coated with chemical conversion coating before applying common body filler.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "If body filler has been developed for anti-corrosive steel, chemical conversion coating will not be needed. (Please confirm this with the body filler supplier.)", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(3) SPATULA MOVEMENT", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Move the spatula lengthwise when applying to an oval shaped area. If applying to a round area, move the spatula in many directions as shown in the figure.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(4) APPLYING TECHNIQUE", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Apply body filler in several thin layers.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(a) Hold spatula well balanced and hold slightly standing position, then squeeze putty into scratches.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "a", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", ": 60°– 90°", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(b) Put a large amount of filler on the spatula.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Hold spatula slightly lean, then apply several times (do not put much in once) until covered above datum level.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "b", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", ": 30°– 45°", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(c) Use the spatula to smooth the applied filler.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Perform finishing work for smoothening the surface. The filler surface should be slightly higher than the panel surface.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "c", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", ": Less than 30°", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(5) PRECAUTION FOR APPLYING", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Be careful not to place body filler over the old lacquer type paint. If this is done, the paint will be softened by the thinner when painting. This causes the body filler to shrink and concave will result.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(6) APPLICATION OF BODY FILLER TO FLAT SURFACE", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(a) Apply filler so that the corrected surface is flush with the surrounding panel surface.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(b) Apply another layer of filler to overlap 1/3 - 2/3 of the previous application to eliminate the step.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(c) Repeat (b) until the filler is correctly applied to the desired portion.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(7) APPLICATION OF BODY FILLER TO CURVED SURFACE", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "Use of a flexible rubber spatula is recommended for application to curved surfaces.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(8) APPLICATION OF BODY FILLER TO PRESS LINE", "title");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(A) Apply tape along the press line. Then apply filler to only one side of the press line.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(B) Peel the tape from the half-dried filler.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(C) Apply tape along the filled and half-dried filler line.", "ptxt");
si[i++] = gsitm("N5110906A0000C00ENG.html", "(D) Apply filler to the other side of the press line.", "ptxt");
si[i++] = gsitm("N5110906B0000C00ENG.html", "Drying the Body Filler", "title");
si[i++] = gsitm("N5110906B0000C00ENG.html", "When the hardener is mixed with the base, the filler begins to harden. Heat is also generated, which accelerates hardening. For this reason, filler drying speed varies with the applied thickness.", "ptxt");
si[i++] = gsitm("N5110906B0000C00ENG.html", "If a thick coat of filler is applied, the generated heat remains inside, hence it hardens quickly.", "ptxt");
si[i++] = gsitm("N5110906B0000C00ENG.html", "Where the filler is not so thick, it hardens rather slowly because heat dissipates to the outside.", "ptxt");
si[i++] = gsitm("N5110906B0000C00ENG.html", "Approximately 10 - 20 minutes (at 20°C or 68°F) after application, the filler becomes hard enough to permit grinding with a surform. When the ambient temperature is low, use a panel heater or adjust the drying time. To check whether the filler is dry or not, press a thin portion with finger. If it is dry, then it is suitable for grinding.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Grinding the Filled Area", "title");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Grind the filler when it is half-dried. Half-dried filler means the condition where the surface, if ground lightly with a surform, will produce continuous linear chips. Grinding with the surform will be difficult after the filler hardens completely.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "(1) ROUGH GRINDING BY SURFORM", "title");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Smooth the filler surface by grinding with the surform or the like. Grind in many different directions. Better results may be obtained if the surform is inclined 30° - 40° with respect to the direction of movement. Be careful not to damage the surrounding panel surface.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "(2) ROUGH GRINDING BY AIR SANDER", "title");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Smooth the filler surface by grinding with the dual action sander or orbital sander. Grind in many different directions.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "This grinding method is faster than the method using a surform. However, if the worker is not accustomed to performing this type of grinding, an uneven surface may result from excessive grinding. #60 - #80 sandpaper is used.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "(3) SHAPING THE ENTIRE PANEL", "title");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Using an orbital sander or dual action sander, trim the shape of the filled panel. Leave the amount required for final finishing. #120 - #180 sandpaper is used.", "ptxt");
si[i++] = gsitm("N5110906C0000C00ENG.html", "(4) FINAL FINISH BY HAND FILE", "title");
si[i++] = gsitm("N5110906C0000C00ENG.html", "Using a hand file, orbital sander or dual action sander, smooth and form featheredge on the filler surface until it is flush with the surrounding panel. #240 - #320 sandpaper is used.", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", "Sandpaper Grits", "title");
si[i++] = gsitm("N5110906D0000C00ENG.html", "Select a sandpaper with a grit, appropriate to the putty used. Sanding marks that occur due to sanding are removed with further sanding.", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", "SWITCHING TO A SANDPAPER OF A DIFFERENT GRIT", "title");
si[i++] = gsitm("N5110906D0000C00ENG.html", "Sanding marks that occur during sanding are sanded with a sandpaper of the next finer grit. When doing this, do not sand using a sandpaper of a grit two grades or more finer than the previously applied sandpaper.", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", "NG", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", ": #80 ⇒ #180 ⇒ #320 ⇒ #400", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", "*: Note that, if sanding with a sandpaper of a grit two grades or more finer than the last one used, removing deep sanding marks that occur during sanding with a coarser sandpaper, as well as removing any remaining deep sanding marks may take longer.", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", "OK", "ptxt");
si[i++] = gsitm("N5110906D0000C00ENG.html", ": #120 ⇒ #180 ⇒ #240 ⇒ #320 ⇒ #400", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Grinding Power of Air Sander", "title");
si[i++] = gsitm("N5110906E0000C00ENG.html", "The diameter (shown in the figure) of a circle traced by a part of the dual action sander and the orbital sander is called an orbit diameter. The larger the area shown with diagonal lines, the greater the grinding power is.", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "When surface accuracy is required, a sander with a smaller orbit diameter should be selected. When grinding power is required, a sander with a larger orbit diameter should be selected.", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Work content", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Orbit diameter", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Sanding a body filler", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "7 mm - 10 mm (0.28 in - 0.39 in)", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Sanding a primer surfacer", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "4 mm - 5 mm (0.16 in - 0.20 in)", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "Roughing surface before topcoating", "ptxt");
si[i++] = gsitm("N5110906E0000C00ENG.html", "3 mm - 4.5 mm (0.118 in - 0.177 in)", "ptxt");
si[i++] = gsitm("N5110906G0000C00ENG.html", "Repair of Rust and Corrosion", "title");
si[i++] = gsitm("N5110906G0000C00ENG.html", "Rust on sheet metal is the result of the chemical reaction of steel to oxygen in the air, which is called oxidation. This rust, if left untreated, will increase and finally corrode and damage the sheet metal. If the vehicle is used for a long time under severe environmental conditions, rust or corrosion may form on body surfaces. When repairing rust and corrosion, it is necessary to keep rust from spreading from the repaired portion.", "ptxt");
si[i++] = gsitm("N5110906H0000C00ENG.html", "Removal of Rust Limited to the Skin Panel Surface", "title");
si[i++] = gsitm("N5110906H0000C00ENG.html", "Grind the rusted portion with an air sander or the like.", "ptxt");
si[i++] = gsitm("N5110906H0000C00ENG.html", "Rust may be more extensive than it appears from the outside. Therefore, it is necessary to grind the area around rusted portion. Repair the ground out portion using body filler.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "Repair of Corroded Panel", "title");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(1) FILLING WITH FIBERGLASS", "title");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(a) Grind off the corroded portion of the panel with an air sander. If corrosion is severe, cut off the affected portion with a chisel or tinman\'s shears. Remove the paint from the surrounding areas.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(b) Hollow the area surrounding the repair hole by tapping with a hammer and bending the panel.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(c) Cut a piece of fiberglass cloth. The cloth should be large enough to overlap the repair hole.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "Apply fiberglass putty to the cloth using a spatula until the mesh is filled. Prepare the fiberglass putty by mixing 100 parts of base with 2 to 3 parts of hardener.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(d) Apply a thin coat of fiberglass putty to the panel where the piece of fiberglass cloth is to be attached.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "Apply putty also to the edge and back of the repair hole.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(e) Apply the piece of fiberglass cloth to the surrounding portion and the back of the repair hole.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "This is necessary to prevent rust.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(f) Apply the piece of fiberglass cloth prepared in step (c) above to the repair hole. Press the periphery of the cloth to the panel for better adhesion. If the repair hole is large and the cloth sags in the center, support the cloth with tape applied behind the panel.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(g) Apply the fiberglass putty to the piece of fiberglass cloth. The fiberglass putty surface should be below the surrounding panel surface. If the area to be repaired is deep, use two or more piece of fiberglass cloth. In such a case, avoid thick application of fiberglass putty. Thick fiberglass putty will crack after drying.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(h) Dry the fiberglass putty, and grind the surface with an air sander. Then trim the entire panel using body filler.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "When force drying fiberglass putty, allow the putty to sit for approximately 20 minutes. Then heat at a temperature below 60°C (140°F). Rapid heating which causes the putty to change color must be avoided, as it will lead to cracked putty. Fiberglass putty forms blowholes easily. Body filler must be used to finish the surface of fiberglass putty.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(2) PATCHING", "title");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(a) Remove the corroded portion of the panel.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "Remove paint from the panel around the repair hole.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "Make a flange by bending the surrounding panel with pliers and hammer, then apply anti-corrosive treatment (Metallic solution).", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(b) Using tinman\'s shears, cut a patch large enough to overlap the repair hole. Apply the anti-corrosive treatment to the portion to be welded. Use of stainless steel is recommended to avoid rusting. If the repair hole is large, use a panel having the same thickness as the original panel to retain the original strength.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(c) Weld the patch to the repair hole. If stainless steel is used, use the MIG welding or spot welding method.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "When welding the patch by GSA welding, use the plug welding method.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(d) Apply the body filler to the repaired portion of the panel.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(e) Apply the anti-corrosive treatment to the back of the panel. If accessible from behind, apply a sealer to the panel-to-patch mating section.", "ptxt");
si[i++] = gsitm("N5110906I0000C00ENG.html", "(f) If inaccessible from behind, apply an anti-corrosive wax from an inner panel opening or the like. It is also important to apply the anti-corrosive treatment to other portions in addition to the repaired portion.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "High Strength Steel (HSS) and Ultra High Strength Steel (UHSS)", "title");
si[i++] = gsitm("N5110907G0000E00ENG.html", "High strength steel and ultra high strength steel are used for body panels in order to reduce vehicle weight.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Accordingly, precautions in repairing automotive bodies made of high strength steel are described below:", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Additional points to consider", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "The repair of reinforcements (such as side members) by heating is not recommended, because it may weaken the component. When heating is unavoidable, never heat HSS parts above 550°C (1,022°F).", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Verify heating temperature with a thermometer.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "(Crayon-type and other similar type thermometer are appropriate.)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "When you heat the HSS or UHSS parts above 550°C (1,022°F), it must be replaced with new parts.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "When straightening body panels, use caution in pulling any HSS panel. Because HSS is very strong, pulling may cause deformation in adjacent sections of the body. In this case, increase the number of measuring points, and carefully pull the HSS panel.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "When cutting HSS panels, avoid gas (torch) cutting if possible. Instead, use a saw to avoid weakening surrounding areas due to heat. If gas (torch) cutting is unavoidable, allow a minimum margin of 50 mm (1.97 in).", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "When welding HSS panels, use spot welding whenever possible in order to minimize weakening surrounding areas due to heat.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "If spot welding is impossible, use MIG. welding. Do not use gas (torch) for welding because it is inferior in welding strength.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Spot welding on HSS panels is harder than that of an ordinary steel panel.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Therefore, when cutting spot welds on a HSS panel, use a low speed high torque drill (1,000 to 1,200 rpm) to increase drill bit durability and facilitate the operation.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Precautions in spot welding HSS", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "This work should be performed under standard working conditions. Always note the following when spot welding HSS:", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "The electrode tip diameter must be sized properly according to the metal thickness.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "The panel surfaces must fit flush to each other, leaving no gaps.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Follow the specifications for the proper welding pitch.", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Thickness (T)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "Minimum pitch (L)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "0.6 (0.024)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "0.8 (0.031)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "1.0 (0.039)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "1.2 (0.047)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "1.6 (0.063)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "1.8 (0.071)", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "10 (0.39) or more", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "12 (0.47) or more", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "18 (0.71) or more", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "20 (0.79) or more", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "27 (1.06) or more", "ptxt");
si[i++] = gsitm("N5110907G0000E00ENG.html", "31 (1.22) or more", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "Description", "title");
si[i++] = gsitm("N511090120000Y00ENG.html", "To provide improved corrosion prevention, the following anti-corrosive measures have been implemented in Mitsubishi Motors production plants. When repairing or replacing body panels, it is necessary to use the same anti-corrosive measures.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "ANTI-CORROSIVE PRECOATED STEEL (GALVANNEALED STEEL)", "title");
si[i++] = gsitm("N511090120000Y00ENG.html", "To improve repairability and corrosion resistance, a new type of anti-corrosive precoated steel sheet is adopted replacing conventional zinc-coated steel sheet.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "Galvannealed steel is electroplated and heated to form Zinc-iron alloy, which provides excellent and long term corrosion resistance with cationic electrodeposition primer.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "Mitsubishi Motors genuine parts are fabricated from galvannealed steel. Therefore, it is recommended that Mitsubishi Motors genuine parts or an equivalent be used for panel replacement to maintain the anti-corrosive performance built into the vehicle at the factory.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "PHOSPHATE COATING TREATMENT AND CATIONIC ELECTRODEPOSITION PRIMER", "title");
si[i++] = gsitm("N511090120000Y00ENG.html", "A phosphate coating treatment and a cationic electrodeposition primer, which provide excellent corrosion protection, are applied to all body components.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "Confine paint removal during welding operation to an absolute minimum.", "ptxt");
si[i++] = gsitm("N511090120000Y00ENG.html", "Mitsubishi Motors genuine parts are also treated in the same manner. Therefore, it is recommended that Mitsubishi Motors genuine parts or an equivalent be used for panel replacement to maintain anti-corrosive performance built into the vehicle at the factory.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "Undercoating", "title");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "The underside of the floor and wheelhouse are undercoated to prevent rust, vibration, noise and stone chipping. Therefore, when such a panel is replaced or repaired, apply undercoating to that part. Use an undercoating which is rust resistant, soundproof, vibration-proof, shock-resistant, adhesive, and durable.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "PRECAUTIONS IN UNDERCOATING", "title");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "Never apply undercoating to any place unless specified (such as the areas above the muffler and three way catalyst that are subjected to heat).", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "Never undercoat the exhaust pipe or other parts that become hot.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "Never undercoat rotating parts.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "Apply bitumen wax after applying undercoating.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "After putting seal on the vehicle, put undercoating on it.", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", "UNDERCOATED AREAS", "title");
si[i++] = gsitm("N5110907Q0000C00ENG.html", ": Undercoated areas", "ptxt");
si[i++] = gsitm("N5110907Q0000C00ENG.html", ": Sealed portions", "ptxt");
si[i++] = gsitm("N5110907S0000E00ENG.html", "Body Sealing", "title");
si[i++] = gsitm("N5110907S0000E00ENG.html", "The following figure shows the areas that are sealed at the factory. Sealant that is applied to these areas should be smooth and free from cuts or gaps. Care should be taken not to apply an excess amount of sealant and not to allow other unaffected parts to come into contact with the sealant.", "ptxt");
si[i++] = gsitm("N5110907S0000E00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5110907S0000E00ENG.html", ": Sealed portions", "ptxt");
si[i++] = gsitm("N5110907D0000O00ENG.html", "Precautions for Body Repair", "title");
si[i++] = gsitm("N5110907D0000O00ENG.html", "The repair information in this section is intended for trained body repair technicians who have attained a high level of skill and experience (e.g. ASE Collision Repair Certification, I-CAR Professional Development Program [PDP] training, etc.) in repairing collision damaged vehicles using appropriate tools and equipment. Performing repairs without the proper training, tools or equipment could damage the vehicle or cause personal injury or death to you or others.", "ptxt");
si[i++] = gsitm("N5110907D0000O00ENG.html", "The information in this Body Repair Manual is a guideline for repairing collision damaged vehicles. However, this information cannot cover all possible ways that a vehicle can be damaged. As such, the body repair technician is responsible for making sure that the repair does not affect the structural integrity or safety of the vehicle. Improper repair of a damaged vehicle may result in a collision, property damage, personal injury or death.", "ptxt");
si[i++] = gsitm("N5110907D0000O00ENG.html", "Nissan recommends using only new genuine Nissan replacement body parts. Use of used, salvaged or aftermarket body parts is not recommended by Nissan. Non-genuine Nissan components may affect the vehicle\'s structural integrity and crash safety performance, which could result in serious personal injury or death in an accident.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Description", "title");
si[i++] = gsitm("N511090120000Z00ENG.html", "Technicians are encouraged to read the Body Repair Manual (Fundamentals) in order to ensure that the original functions and quality of the vehicle are maintained. The Body Repair Manual (Fundamentals) contains additional information, including cautions and warnings, that are not including in this manual. Technicians should refer to both manuals to ensure proper repair.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Please note that this information is prepared for worldwide usage, and as such, certain procedures might not apply in some regions or countries.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "The symbols used in this section for welding operations are shown below.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Symbol marks", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "″Number″", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "″Number″ after symbol mark is the total number of welds to apply.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Example 1: ″4″A = 4 MIG plug welds for 3-panel plug weld method.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Example 2: ″1″× 20 (0.79) = 1 MIG seam weld by length 20 mm (0.79 in).", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "2-panel spot weld", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "3-panel spot weld", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "MIG plug weld", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "For 3-panel plug weld method", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "MIG seam weld / Point weld", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Rivet", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Front pillar butt joint can be determined anywhere within shaded area as shown in the figure. The best location for the butt joint is at position A due to the construction of the vehicle.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Determine cutting position and record distance from the locating indent. Use this distance when cutting the service part. Cut outer front pillar over 60 mm (2.36 in) above the inner front pillar cut position.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Prepare a cutting jig to make outer pillar easier to cut. Also, this will permit the service part to be accurately cut at the joint position.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "An example of cutting operation using a cutting jig is as per the following.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Mark cutting lines.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "A: Cut position of outer pillar", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "B: Cut position of inner pillar", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Align cutting line with notch on jig. Clamp jig to pillar.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Cut outer pillar along groove of jig (at position A).", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Remove jig and cut remaining portions.", "ptxt");
si[i++] = gsitm("N511090120000Z00ENG.html", "Cut inner pillar at position B in same manner.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Welding of Ultra High Strength Steel", "title");
si[i++] = gsitm("N5110907X0000C00ENG.html", "SPOT WELDING", "title");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Spot welding is limited to ultra high strength steel (tensile strength: 980 MPa) according to the welding conditions listed below.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "If the below welding conditions cannot be met, then perform plug welding.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Never spot weld ultra high strength steel of tensile strength more than 980 MPa. For this type of ultra high strength steel, perform plug welding.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "The below welding condition is applicable only to this vehicle. Never apply this same welding condition to other vehicles.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Welding condition", "title");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Welder tip diameter", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "6 mm", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Welding pressure (Gun force)", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "3650 N", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Welding current", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "8010 A", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Weld time", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "0.2 sec (10 cyc: 50 Hz area, 12 cyc: 60 Hz area)", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Panel configuration", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Combination of a plate of tensile strength 980 MPa and that of tensile strength less than 980 MPa. (Up to 3 plates)", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "PLUG WELDING", "title");
si[i++] = gsitm("N5110907X0000C00ENG.html", "To weld ultra high strength steel of tensile strength 980 MPa or more, perform plug welding observing the welding hole diameter described in the manual.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "To perform plug welding, use fuel mixture (Ar 80% + CO2 20%) for shielding gas of welder.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Never use carbon dioxide gas (CO2 100%) as shielding gas of welder. Using CO2 100% gas results in inadequate weld strength.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "When welding hole diameter cannot be met, make multiple holes (smaller diameter) so that the sum of the hole areas equals the area of the original weld hole.", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", "EXAMPLE", "title");
si[i++] = gsitm("N5110907X0000C00ENG.html", "Body sealing", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", ": Drill φ6 mm (0.24 in) hole for the plug welding hole (ultra high strength steel).", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", ": N·m (kg-m, ft-lb)", "ptxt");
si[i++] = gsitm("N5110907X0000C00ENG.html", ": For spot welding of steel plate of tensile strength 980 MPa, observe the indicated welding conditions. Refer to ″Welding of Ultra High Strength Steel″.", "ptxt");
