si[i++] = gsitm("N511090120001000ENG.html", "All dimensions indicated in the figures are actual.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "When using a tracking gauge, adjust both pointers to equal length. Then check the pointers and gauge itself to make sure there is no free play.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "When a measuring tape is used, check to be sure there is no elongation, twisting or bending.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "Measurements should be taken at the center of the mounting holes.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "A star mark () following the value at the measuring point indicates that the measuring point on the other side is symmetrically the same value.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "The coordinates of the measurement points are the distances measured from the standard line of ″X″, ″Y″ and ″Z″.", "ptxt");
si[i++] = gsitm("N511090120001000ENG.html", "″Z″: Imaginary base line [200 mm (7.87 in) below datum line (″0Z″ at design plan)]", "ptxt");
