si[i++] = gsitm("N512010420000K00ENG.html", "Passenger Door Mirror Control Module", "title");
si[i++] = gsitm("N512010420000K00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512010420000K00ENG.html", "Passenger door mirror control module supplies mirror motor power supply in door mirror passenger side and operates door mirror passenger side.", "ptxt");
si[i++] = gsitm("N512010420000K00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512010420000K00ENG.html", "Passenger door mirror control module transmits the mirror motor power supply to door mirror passenger side.", "ptxt");
si[i++] = gsitm("N512010420000K00ENG.html", "Passenger door mirror control module receives the mirror position signal from door mirror passenger side.", "ptxt");
si[i++] = gsitm("N512010420000K00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512010420000K00ENG.html", "The mirror control signal is transmitted to passenger door mirror control module from BCM via LIN communication.", "ptxt");
si[i++] = gsitm("N512010420000K00ENG.html", "When the mirror control signal is detected, passenger door mirror control module activated mirror motor passenger side.", "ptxt");
