si[i++] = gsitm("N512010580000600ENG.html", "Inside Mirror", "title");
si[i++] = gsitm("N512010580000600ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512010580000600ENG.html", "Receives the camera image signal sent from the rear camera unit via LVDS communication, and displays the image on the LCD monitor.", "ptxt");
si[i++] = gsitm("N512010580000600ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512010580000600ENG.html", "Controls the brightness adjustment, image position adjustment, etc.", "ptxt");
si[i++] = gsitm("N512010580000600ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512010580000600ENG.html", "When the mode switching lever at the lower part of the inside mirror assembly is moved to the ON position, the mirror enters the monitor mode and the image sent from the rear camera unit is displayed on the LCD monitor incorporated into the inside mirror assembly. When the mode switching lever is moved to the OFF position, the inside mirror assembly enters the normal mirror mode.", "ptxt");
si[i++] = gsitm("N512010580000600ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N512010580000600ENG.html", "Is installed to the windshield glass. Refer to .", "ptxt");
si[i++] = gsitm("N512010530000800ENG.html", "Rear Camera Unit", "title");
si[i++] = gsitm("N512010530000800ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512010530000800ENG.html", "Transmits the camera image signal to the inside mirror assembly via LVDS communication.", "ptxt");
si[i++] = gsitm("N512010530000800ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512010530000800ENG.html", "Is supplied with power by the inside mirror assembly and shoots the image of the rear view of the vehicle.", "ptxt");
