si[i++] = gsitm("N512010440000O00ENG.html", "MANUAL OPERATION", "title");
si[i++] = gsitm("N512010440000O00ENG.html", "Description", "title");
si[i++] = gsitm("N512010440000O00ENG.html", "Power window main switch inputs mirror control signal and perform the driver side/passenger side control of door mirror motor supplying electric power when changeover switch is operated.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "Power window main switch inputs mirror control signal and supplies electric power to door mirror.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "Operation Conditions", "title");
si[i++] = gsitm("N512010440000O00ENG.html", "If the following conditions are not satisfied, operation is not performed.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "Changeover switch: Select either left or right", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "AUTOMATIC DRIVE POSITIONER LINKED OPERATION", "title");
si[i++] = gsitm("N512010440000O00ENG.html", "Door mirror control is included in automatic drive positioner system. Refer to automatic drive positioner system for more details. Refer to  &lt;LHD>,  &lt;RHD>.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "REVERSE INTERLOCK DOOR MIRROR FUNCTION", "title");
si[i++] = gsitm("N512010440000O00ENG.html", "Select either of the door mirror faces by changeover switch, and then set mirror face downward.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "When ignition switch is ON position and electric shift selector is in R position, TCM sends the R signal to BCM.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "The mirror control signal is transmitted to power window main switch and passenger door mirror control module from BCM via LIN communication.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "When the mirror control signal is detected, power window main switch and passenger door mirror control module activated mirror motor.", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "CVT shift selector: R position", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "Change over switch: Select either left or right", "ptxt");
si[i++] = gsitm("N512010440000O00ENG.html", "During the reverse interlock door mirror system, if all of the above conditions are not satisfied, mirror face returns to original angle.", "ptxt");
si[i++] = gsitm("N5120103H0001P00ENG.html", "System Description", "title");
si[i++] = gsitm("N5120103H0001P00ENG.html", "The sensor built inside the mirror detects the brightness of headlights of the vehicle behind and automatically changes the light transmission to decrease the brightness.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "System Description", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Inside mirror assembly", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Rear camera unit", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "The digital rear view mirror system has two modes: monitor mode, in which the digital image of the rear camera unit is displayed on the LCD monitor built into the inside mirror assembly, and mirror mode, in which the LCD monitor is switched off and used as a conventional mirror.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "The rear camera unit is mounted on the liftgate window glass assembly so the driver can see the rear view without being obstructed by the occupants and luggage in the vehicle.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "MONITOR MODE", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "When the switching lever of the inside mirror assembly is moved to the monitor mode position, the image of the rear camera unit is displayed on the LCD monitor built into the inside mirror assembly.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "The camera image signal communicates between the inside mirror assembly and the rear camera unit via LVDS communication.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "The LCD monitor display can adjust the brightness and image position.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Operating condition", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Operating condition (when all of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Engine switch: ON", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Inside mirror assembly switching lever: monitor mode", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "MIRROR MODE", "title");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "When the switching lever at the lower part of the inside mirror assembly is moved to the normal mirror mode position, the normal mirror view will be displayed.", "ptxt");
si[i++] = gsitm("N5120103H0001Q00ENG.html", "Inside mirror assembly switching lever: normal mirror mode", "ptxt");
si[i++] = gsitm("N5120101V0000C00ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N5120101V0000C00ENG.html", "If an abnormality occurs in the inside mirror assembly, the following fail-safe controls are performed.", "ptxt");
si[i++] = gsitm("N5120101V0000C00ENG.html", "If an abnormality is detected in the LCD monitor built into the inside mirror assembly, the LCD monitor stops working and shifts to the normal mirror mode. If the abnormality is resolved, the LCD monitor automatically returns to the monitor mode.", "ptxt");
si[i++] = gsitm("N5120101V0000C00ENG.html", "If an abnormality is detected in the rear camera unit, the error screen is displayed on the LCD monitor of the inside mirror assembly. If the abnormality is resolved, the error screen disappears and the screen automatically recovers.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "OBTAIN INFORMATION ABOUT SYMPTOM", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Interview the customer to obtain as much malfunction information (conditions and environment when the malfunction occurred) as possible when the customer brings the vehicle in.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "REPRODUCE THE MALFUNCTION INFORMATION", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Check the malfunction on the vehicle that the customer describes.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "Inspect the relation of the symptoms and the condition when the symptoms occur.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "IDENTIFY THE MALFUNCTIONING SYSTEM WITH “SYMPTOM DIAGNOSIS”", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Use “Symptom diagnosis” from the symptom inspection result in step 2. Then identify where to start the diagnosis based on possible causes and symptoms.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "IDENTIFY MALFUNCTIONING PARTS WITH “COMPONENT DIAGNOSIS”", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Perform the diagnosis with “Component diagnosis” of the applicable system.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PARTS", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Repair or replace the specified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5120103O0001700ENG.html", "Check that malfunctions are not reproduced when obtaining the malfunction information from the customer, referring to the symptom inspection result in step 2.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "Is the malfunctioning part repaired or replaced?", "question");
si[i++] = gsitm("N5120103O0001700ENG.html", "YES", "result");
si[i++] = gsitm("N5120103O0001700ENG.html", "Trouble diagnosis is completed.", "ptxt");
si[i++] = gsitm("N5120103O0001700ENG.html", "NO", "result");
si[i++] = gsitm("N5120103O0001700ENG.html", "Check Intermittent incident. Refer to Intermittent Incident.", "ptxt");
