si[i++] = gsitm("N512010330008Z00ENG.html", "Push in the inside mirror assembly until it hits the inside mirror base and stops as shown in the figure.", "ptxt");
si[i++] = gsitm("N512010330008Z00ENG.html", "Tighten the screw to the specified torque, and check that the inside mirror assembly is not loose.", "ptxt");
si[i++] = gsitm("N512010330008Z00ENG.html", "Tightening torque: 1.5 ± 0.4 N·m (13 ± 3 in-lb)", "ptxt");
