si[i++] = gsitm("N5122000C0000A00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N5122000C0000A00ENG.html", "REMOTE CONTROLLED DOOR MIRROR OPERATION CHECK", "title");
si[i++] = gsitm("N5122000C0000A00ENG.html", "Remove the door trim, and then connect the battery to the door mirror assembly connector to check that the door mirror operates.", "ptxt");
