si[i++] = gsitm("N5122000C0000A00ENG.html", "HEATED DOOR MIRROR CHECK", "title");
si[i++] = gsitm("N5122000C0000A00ENG.html", "When relocating the car between locations with extremely different temperatures (warm and cold), leave the car in the location for a while to adapt to the temperature prior to checking it.", "ptxt");
si[i++] = gsitm("N5122000C0000A00ENG.html", "Check that the resistance value between the door mirror assembly connector terminal No. 7 and 15 is at the standard value.", "ptxt");
si[i++] = gsitm("N5122000C0000A00ENG.html", "Standard value: 13.3 ± 1.3 ohms at 20°C", "ptxt");
si[i++] = gsitm("N5122000C0000A00ENG.html", "BLIND SPOT WARNING LIGHT CHECK", "title");
si[i++] = gsitm("N5122000C0000A00ENG.html", "Do not apply battery voltage to door mirror assembly connector No. 3 terminal as the blind spot warning light is broken.", "ptxt");
si[i++] = gsitm("N5122000C0000A00ENG.html", "Apply 5V to the door mirror assembly connector terminal No. 12, ground the terminal No. 15 and then check that the illumination lights up.", "ptxt");
