si[i++] = gsitm("N5120201F0000Y00ENG.html", "ALH-ECU", "ptxt");
si[i++] = gsitm("N5120201F0000Y00ENG.html", "Headlight (back)", "ptxt");
si[i++] = gsitm("N5120201F0000Y00ENG.html", "View with instrument garnish", "ptxt");
si[i++] = gsitm("N5120201F0000Y00ENG.html", "*1: Without light & rain sensor", "ptxt");
si[i++] = gsitm("N5120201F0000Y00ENG.html", "*2: With light & rain sensor", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "LED Headlight Control Module", "title");
si[i++] = gsitm("N5120205U0000F00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5120205U0000F00ENG.html", "When power is supplied from battery and receives control signal from the IPDM E/R, the LED headlight control module internally calculates the supplied power. The calculated power is distributed to multiple LEDs that consist of circuit boards and other components, illuminating the each lamps.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "When a malfunction is detected in the headlight (LO) circuit, the LED headlight control module outputs a headlight warning signal to the IPDM E/R (via LIN communication) to inform the driver of the malfunction.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5120205U0000F00ENG.html", "Turns the each lamps ON.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "Detects the headlight (LO) circuit malfunction condition.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120205U0000F00ENG.html", "IPDM E/R transmits the control signal and the request (via LIN communication) to LED headlight control module, and turns each lamps ON.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "LED headlight control module transmits the headlight warning signal to IPDM E/R (via LIN communication) according to the headlight (LO) circuit malfunction condition.", "ptxt");
si[i++] = gsitm("N5120205U0000F00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5120205U0000F00ENG.html", "LED headlight control module integrated to headlight. Refer to .", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "ALH-ECU", "title");
si[i++] = gsitm("N512020750000100ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N512020750000100ENG.html", "The ALH-ECU performs adaptive LED headlight (ALH) control based on each vehicle status signal.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "The ALH-ECU has a self-diagnosis function, and when the ALH system detects an abnormality or DTC, the combination meter displays an ALH warning.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N512020750000100ENG.html", "Controls the ALH system.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "Detects an error in the ALH system.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N512020750000100ENG.html", "ALH control", "title");
si[i++] = gsitm("N512020750000100ENG.html", "The ALH system has the following ALH control (partial high beam control).", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "When a vehicle ahead or an oncoming vehicle appears while driving with the headlight (HI) ON, the headlight (HI) is partially turned OFF. By setting the partial high beam state, the visibility of irradiation other than the vehicle ahead or the oncoming vehicle is improved.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "In order to prevent dazzling due to the light reflected on the traffic sign, the light emitted to the traffic sign is dimmed based on the traffic sign position information from the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "The modulated light control is performed when turning on and off the headlight during ALH control.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "The following controls are performed when ALH is activated.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "When switching from the headlight (LO) to the headlight (HI), each segment of LED is turned ON in order from the center of the vehicle.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "When switching from headlight (HI) to the headlight (LO), all segments of LED are dimmed and turned OFF.", "ptxt");
si[i++] = gsitm("N512020750000100ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N512020750000100ENG.html", "ALH-ECU is installed in the back of the glove box. Refer to .", "ptxt");
si[i++] = gsitm("N5120205R0000400ENG.html", "Headlight Aiming Motor", "title");
si[i++] = gsitm("N5120205R0000400ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5120205R0000400ENG.html", "The headlight aiming motor adjust the height of the optical axes by the headlight aiming switch setting position.", "ptxt");
si[i++] = gsitm("N5120205R0000400ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5120205R0000400ENG.html", "Adjust the height of the headlight optical axes.", "ptxt");
si[i++] = gsitm("N5120205R0000400ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120205R0000400ENG.html", "Adjust the height of the headlight optical axes by directed it setting according to the aiming motor drive signal input to the headlight aiming motor. When the reference position is 0, and the height of the headlight optical axes is adjust according to the headlight aiming switch setting position 1, 2 and 3.", "ptxt");
si[i++] = gsitm("N5120205R0000400ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5120205R0000400ENG.html", "Headlight aiming motor integrated to headlight. Refer to .", "ptxt");
si[i++] = gsitm("N512020760000100ENG.html", "REAR HEIGHT SENSOR", "title");
si[i++] = gsitm("N512020760000100ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512020760000100ENG.html", "The displacement of the vehicle height is detected by the sensor lever, and the detected value is transmitted to IPDM E/R as a rear height sensor signal.", "ptxt");
si[i++] = gsitm("N512020770000100ENG.html", "HEADLIGHT AIMING SWITCH", "title");
si[i++] = gsitm("N512020770000100ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512020770000100ENG.html", "Transmitted headlight aiming switch signal to the IPDM E/R and adjust the height of the optical axis of the headlight.", "ptxt");
si[i++] = gsitm("N512020770000100ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512020770000100ENG.html", "Adjust the height of the headlight optical axes.", "ptxt");
si[i++] = gsitm("N512020770000100ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512020770000100ENG.html", "Transmitted headlight aiming switch signal corresponding to each setting position to IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020770000100ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N512020770000100ENG.html", "Headlight aiming switch is installed in instrument panel lower finisher. Refer to .", "ptxt");
si[i++] = gsitm("N5120205W0000F00ENG.html", "Optical Sensor", "title");
si[i++] = gsitm("N5120205W0000F00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5120205W0000F00ENG.html", "Optical sensor converts the outside brightness (lux) to voltage and transmits the optical sensor signal to BCM.", "ptxt");
si[i++] = gsitm("N5120205W0000F00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5120205W0000F00ENG.html", "Detects the outside brightness.", "ptxt");
si[i++] = gsitm("N5120205W0000F00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120205W0000F00ENG.html", "The optical sensor outputs voltage signals to the BCM according to the brightness of the ambient light. This sensor increases the voltage output according to increases in the brightness of the ambient light.", "ptxt");
si[i++] = gsitm("N5120205W0000F00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5120205W0000F00ENG.html", "Optical sensor is installed in instrument garnish. Refer to .", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard Switch", "title");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Outputs the ON/OFF status of the hazard switch to the BCM, flashing the hazard warning light.", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Operates the hazard switch ON/OFF.", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Outputs the ON/OFF status of the push-return type hazard switch as a hazard switch signal.", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Operation", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Push-lock type", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Push-return type", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch ON operation", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch OFF operation", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch ON operation: At the time of hazard switch ON operation, the switch is pushed from the reference point  to the pushed position  , and the hazard switch turns ON. When the hazard switch is released from this position, the switch returns from the pushed position  to the hold position  , and the hazard switch position is held there.", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch OFF operation: At the time of the hazard switch OFF operation, the switch is pushed from the hold position  to the pushed position  . When the hazard switch is released from this position, the switch returns from the pushed position  to the reference point  , and the hazard switch turns OFF.", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch ON operation: At the time of the hazard switch ON operation, the switch is pushed from the reference point  to the pushed position  , and the hazard switch turns ON. When the hazard switch is released from this position, the switch returns from the pushed position  to the reference point  .", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch OFF operation: At the time of the hazard switch OFF operation, the switch is pushed from the reference point  to the pushed position  , and the hazard switch turns OFF. When the hazard switch is released from this position, the switch returns from the pushed position  to the reference point  .", "ptxt");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5120205Q0000F00ENG.html", "Hazard switch is installed in center ventilator finisher. Refer to .", "ptxt");
si[i++] = gsitm("N512020610000C00ENG.html", "Stop Light Switch", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "The BCM detects the ON/OFF status of the stop light switch and illuminates the stop light.", "ptxt");
si[i++] = gsitm("N512020610000C00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "Operates the stop light switch ON/OFF.", "ptxt");
si[i++] = gsitm("N512020610000C00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "When the brake pedal is released", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "When the brake pedal is released, the push rod  of the stop light switch  is pushed in.", "ptxt");
si[i++] = gsitm("N512020610000C00ENG.html", "When the brake pedal is depressed", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "When the brake pedal is depressed, the push rod  of the stop light switch  is released.", "ptxt");
si[i++] = gsitm("N512020610000C00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N512020610000C00ENG.html", "Stop light switch is installed in brake pedal. Refer to .", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "Light & Rain Sensor", "title");
si[i++] = gsitm("N5120206X0000900ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5120206X0000900ENG.html", "The light & rain sensor detects the outside ambient light level, forward light level and sensor conditions.", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "Based on ambient light level (day/night detection), forward light level (tunnel detection) and sensor conditions it judges ON/OFF condition for exterior lights.", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "And it transmits exterior light ON/OFF request to the BCM by the LIN communication line.", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "BCM controls each function depending on the signals. And it detects the LIN communication line error and the light & rain sensor malfunction.", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5120206X0000900ENG.html", "Detects the outside brightness.", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120206X0000900ENG.html", "Light & rain sensor  detects the outside vehicle of brightness, and request the auto light function to BCM (via serial link).", "ptxt");
si[i++] = gsitm("N5120206X0000900ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5120206X0000900ENG.html", "Light & rain sensor is installed in windshield glass. Refer to .", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "System Description", "title");
si[i++] = gsitm("N512020510004700ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N512020510004700ENG.html", "Component", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Function", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight (HI)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "(LED headlight)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED headlight control module supplies power supply voltage to headlight (HI), and turns the headlight (HI) ON.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Exterior light appearance: Refer to Exterior Light Appearance.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Bulb specifications: Refer to .", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight (LO)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED headlight control module supplies power supply voltage to headlight (LO), and turns the headlight (LO) ON.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED headlight control module", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Refer to LED Headlight Control Module.", "ReferToComponentDescriptionNGIEMD-0-62151362");
si[i++] = gsitm("N512020510004700ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Transmits the control signal and request (via LIN communication) to the LED headlight control module according with the request from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Detects the LIN communication error or headlight warning signal is input from the LED headlight control module (via LIN communication). And the IPDM E/R requests the combination meter (via CAN communication) to displays the headlight warning.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Detects each switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight (HI/LO) ON/OFF is judged from each signal, and then a request is transmitted to IPDM E/R (via CAN communication) to controls the LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "It also transmits a status to the combination meter (via CAN communication) to turns dipped beam indicator light and high beam indicator light ON/OFF.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Turns the dipped beam indicator light and high beam indicator light ON/OFF according to the status from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Displays the headlight warning according to the request from IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Combination switch", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting & turn signal switch", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Inputs the each switch condition signal to BCM.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight is controlled by combination switch reading function and headlight control function of BCM, and smart FET control function and LIN communication function of IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "HEADLIGHT (LO) OPERATION", "title");
si[i++] = gsitm("N512020510004700ENG.html", "BCM detects the combination switch condition with the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "BCM transmits the low beam request signal to IPDM E/R and low beam status signal to the combination meter via CAN communication according to the headlight (LO) ON condition.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight (LO) ON condition (When any of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch 1ST (Only when the illumination judgement by auto light function is ON. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch 2ND", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch AUTO (Only when the illumination judgement by auto light function is ON. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch PASS", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "IPDM E/R turns the integrated smart FET ON according to low beam request signal, and transmits the control signal to LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "IPDM E/R transmits the request to LED headlight control module (via LIN communication) according to low beam request signal.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED headlight control module turns the headlight (LO) ON according to the control signal and request (via LIN communication) from IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Combination meter turns the dipped beam indicator light according to the low beam status signal. (Full TFT meter models)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "HEADLIGHT (HI) OPERATION", "title");
si[i++] = gsitm("N512020510004700ENG.html", "BCM transmits the high beam request signal to IPDM E/R and high beam status signal to the combination meter via CAN communication according to the headlight (HI) ON condition.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight (HI) ON condition (When any of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch HI with the lighting switch 1ST or AUTO (Only when the illumination judgement by auto light function is ON. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Lighting switch HI with the lighting switch 2ND", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "High beam assist switch ON with the lighting switch 1ST or AUTO (Only when the illumination judgement by auto light function is ON and the illumination judgement by high beam assist system is ON. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "IPDM E/R turns the integrated smart FET ON according to high beam request signal, and transmits the control signal to LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "IPDM E/R transmits the request to LED headlight control module (via LIN communication) according to high beam request signal.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED headlight control module turns the headlight (HI) ON according to the control signal and request (via LIN communication) from IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Combination meter turns the high beam indicator light ON according to the high beam status signal.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "HEADLIGHT WARNING OPERATION", "title");
si[i++] = gsitm("N512020510004700ENG.html", "Headlight warning warns the driver that there is a malfunction in LED headlight system. Refer to Headlight Warning.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "LED HEADLIGHT", "title");
si[i++] = gsitm("N512020510004700ENG.html", "Semiconductor device (Light emitting diode: LED), which is illuminated when forward bias electric voltage is applied, is adopted as the source of light instead of halogen bulb or xenon bulb.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Comparing to halogen headlight or xenon headlight, LED headlight is electrically power saving, durable, and is illuminated in the similar color to the sunlight. Bright, natural, and eye-friendly visibility can be obtained.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Precautions for Trouble Diagnosis", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Representative malfunction examples are; “Light does not turn ON”, “Light blinks”, and “Brightness is inadequate.” Such malfunctions, however, occasionally by occur LED control module malfunction or light case malfunction. Specify the malfunctioning part with diagnosis procedure.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Never touch the harness, LED headlight control module, the inside and metal part of light when turning the headlight ON or operating the lighting switch, for preventing electrical shock.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Never work with wet hands, for preventing electrical shock.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Never perform LED headlight control module circuit diagnosis with a circuit tester or an equivalent.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Temporarily install the headlights on the vehicle. Always connect power supply to the connector (vehicle side) when checking ON/OFF status.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Disconnect the battery negative terminal before disconnecting the light socket connector or the harness connector.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Check for blown (open) of the fusible link(s), open around connector, short, disconnection if the symptom is caused by electric error.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Always check for deformation or hole of headlight housing and engagement of bulb cover. Otherwise, water may enter into headlight because of damage of headlight housing and contact to LED headlight control module connector. The normal operation may be inhibited when short circuit to power supply is detected.", "ptxt");
si[i++] = gsitm("N512020510004700ENG.html", "Turn the switch OFF once before turning ON, if the ON/OFF is inoperative.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5120202H0002A00ENG.html", "FAIL-SAFE CONTROL BY DTC", "title");
si[i++] = gsitm("N5120202H0002A00ENG.html", "IPDM E/R performs fail-safe control when any DTC are detected.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "DTC No.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "M.U.T.-III SE display", "ptxt");
