si[i++] = gsitm("N5120202H0002A00ENG.html", "[MISSING MESSAGE]", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Transmits the headlight warning signal (CAN communication) to the combination meter. (When the ignition switch turns ON, the headlight warning is displayed on the information display of the combination meter.)", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Transmits the request signal (via LIN communication) to the both side LED headlight control module, and turns ON the headlight (LO) and parking light.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "B20A4-87", "ptxt");
