si[i++] = gsitm("N5120202H0002A00ENG.html", "LED HEADLIGHT RH", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "[CMPNENT INTERNAL MLFNCTN]", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "B20E3-96", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "LED HEADLIGHT LH", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "CAN COMMUNICATION CONTROL", "title");
si[i++] = gsitm("N5120202H0002A00ENG.html", "When CAN communication with BCM is impossible, IPDM E/R performs fail-safe control. After CAN communication recovers normally, it also returns to normal control.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "If No CAN Communication Is Available With BCM", "title");
