si[i++] = gsitm("N5120202H0002A00ENG.html", "Fail-safe operation", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Headlight", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Turns ON the headlight (LO) when the ignition switch is turned ON.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Turns OFF the headlight (LO) when the ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5120202H0002A00ENG.html", "Headlight (HI): OFF", "ptxt");
