si[i++] = gsitm("N512020510004J00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Headlight", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Headlight (HI)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "(LED headlight)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "It is turned ON, OFF, or dimmed by the power supply from IPDM E/R and the lighting/extinguishing/modulated light signal from the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Exterior light appearance: Refer to Exterior Light Appearance.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Bulb specifications: Refer to .", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "LED headlight control module", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Refer to LED Headlight Control Module.", "ReferToComponentDescriptionNGIEMD-0-62151362");
si[i++] = gsitm("N512020510004J00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Supplies power to the ALH-ECU and LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH-ECU", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH control is performed based on information such as the front of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits ALH fault information to the combination meter.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits ALH fault information and ALH status to the BCM.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Front camera unit", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits lighting source information, road information, ambient illuminance, object information, traffic sign and camera fault information to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits the shift position signal and CVT fault information to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits yaw rate signal to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Power steering control module", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits steering angle information to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Combination meter", "ptxt");
