si[i++] = gsitm("N512020510004J00ENG.html", "Displays the ALH warning according to the request from ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Turns ON/OFF the adaptive LED headlight indicator light according to the request from BCM.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits the headlight (HI) illumination request to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits the headlight (HI) illumination signal to the combination meter and IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Combination switch", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Transmits the ALH ON/OFF signal to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004J00ENG.html", "The adaptive LED headlight (ALH) system is controlled by the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ADAPTIVE LED HEADLIGHT (ALH)", "title");
si[i++] = gsitm("N512020510004J00ENG.html", "The ALH-ECU controls headlight (HI) in the following cases:", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "When a vehicle ahead or an oncoming vehicle is recognized.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "When a traffic sign is recognized.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "When driving on a curve.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The ALH-ECU detects the vehicle information and surrounding conditions required for ALH control by the following signals.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH ON/OFF signal (received from combination switch", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Headlight (HI) illumination request signal (received from BCM via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Vehicle speed signal (received from combination meter via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Lighting source information, road information, ambient illuminance, object information, traffic sign and camera fault information (received from front camera unit via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Yaw rate signal [received from ABS actuator and electric unit (control unit) via CAN communication]", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Shift position signal and CVT fault information (received from TCM via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The ALH-ECU determines which segment of the headlight (HI) should be turned ON/OFF according to the vehicle condition and surrounding conditions, and transmits the lighting/extinguishing/modulated light signal to the LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The LED headlight control module controls the partial lighting/extinguishing or dimming of the headlight (HI) according to the lighting/extinguishing/modulated light signal.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The LED headlight control module transmits the ALH status to the ALH-ECU. The ALH-ECU determines the lighting status of each LED received from the ALH status.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "BCM transmits the adaptive LED headlight (ALH) indicator light signal to the combination meter when the ALH system operating conditions are satisfied. ALH system operating condition (when all of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH system operating condition (when all of the following conditions are satisfied)", "title");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH switch ON", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Lighting switch AUTO", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The combination meter turns ON the ALH indicator light according to the ALH indicator light signal.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ILLUMINATING JUDGEMENT OF THE HEADLIGHT (HI) BY THE LED HEADLIGHT CONTROL MODULE", "title");
si[i++] = gsitm("N512020510004J00ENG.html", "Headlight (HI) illumination requestThe ALH-ECU requests the LED headlight control module to turn ON the headlight (HI) when all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Detects the vehicle speed is approx. 40 km/h (25 MPH) or more.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Recognizes the ambient condition is dark.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Recognizes there is no oncoming vehicle, no vehicle ahead or no traffic sign in front of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Partial turn-OFF or dimming request for headlight (HI).", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Recognizes there is oncoming vehicle, vehicle ahead or traffic sign in front of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Dimming request for headlight (HI)", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "Detects the vehicle speed is approx. 30 km/h (19 MPH) or less.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "ALH WARNING", "title");
si[i++] = gsitm("N512020510004J00ENG.html", "The ALH-ECU transmits the ALH fail signal to the combination meter when it detects an abnormality in the ALH system.", "ptxt");
si[i++] = gsitm("N512020510004J00ENG.html", "The combination meter displays the ALH warning on the vehicle information display according to the ALH fail signal.", "ptxt");
