si[i++] = gsitm("N512020510004K00ENG.html", "BCM transmits low beam request signal to IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004K00ENG.html", "Headlight aiming control system is controlled by IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "IPDM E/R controls the headlight light axis height appropriately depending on the headlight aiming switch setting.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "IPDM E/R detects the vehicle condition necessary for the headlight aiming motor control with the following signals.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "Headlight aiming switch signal (inputted from Headlight aiming switch)", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "Low beam request signal (inputted from BCM via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "HEADLIGHT MANUAL AIMING OPERATION", "title");
si[i++] = gsitm("N512020510004K00ENG.html", "IPDM E/R receives the headlight aiming switch signal from headlamp aiming switch and detect the leveling position.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "IPDM E/R controls the height of the optical axis of the headlight depending on the leveling position.", "ptxt");
si[i++] = gsitm("N512020510004K00ENG.html", "IPDM E/R outputs aiming motor drive signal when operating conditions are satisfied.", "ptxt");
