si[i++] = gsitm("N512020510004L00ENG.html", "Rear Height sensor", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Judges whether the headlight (LO) is ON/OFF from each signal, and then a request is transmitted to IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Judges the vehicle status from each signal in order to control the headlight automatic leveling.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "ABS actuator and electric unit (control unit)", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Transmits the vehicle speed signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004L00ENG.html", "The headlight automatic leveling is controlled by the IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "HEADLIGHT AUTOMATIC AIMING OPERATION", "title");
si[i++] = gsitm("N512020510004L00ENG.html", "IPDM E/R controls the headlights to the appropriate height of the optical axes according to the change in the rear height of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "IPDM E/R outputs the leveling drive signal as a signal that corrects the headlight to the appropriate height of the optical axes when operating conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Operating condition (when all of the following conditions are satisfied)", "title");
si[i++] = gsitm("N512020510004L00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Headlight (LO) ON", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "IPDM E/R corrects the headlight optical axis by changing the leveling drive signal when the following vehicle conditions (compensating condition) are detected.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Compensating condition (when any of the following conditions are satisfied)", "title");
si[i++] = gsitm("N512020510004L00ENG.html", "Vehicle posture is stabilized after detecting the change in the vehicle posture when the headlight (LO) is turned ON and the vehicle is stationary.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Vehicle speed becomes constant when the headlight (LO) is turned ON and the vehicle is running.", "ptxt");
si[i++] = gsitm("N512020510004L00ENG.html", "Even if the headlight automatic leveling function is normal, there may be a difference between the corrected optical axis position and the reference position due to the changes in chassis component, aging deterioration of the suspension and so on.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "System Description &lt;Without light & rain sensor>", "title");
si[i++] = gsitm("N512020510004800ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N512020510004800ENG.html", "Component", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Function", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Optical sensor", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Controls the integrated smart FET, and supplies voltage to the load according with the request from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Transmits the control signal and request (via LIN communication) to the load according with the request from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Detects each switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Exterior light ON/OFF is judged from each signal, and then a request is transmitted to IPDM E/R (via CAN communication) to controls the each lamps.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "It also transmits a status to the combination meter (via CAN communication) to turns indicator light ON/OFF.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Combination meter", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Turns the indicator light ON/OFF according to the status from BCM via CAN communication.", "ptxt");
