si[i++] = gsitm("N512020510004800ENG.html", "Intelligent auto light system has the auto light function, wiper linked auto lighting function and delay timer function.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Auto light function automatically turns ON/OFF the exterior lamps*, depending on the outside brightness.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Wiper linked auto lighting function automatically turns ON/OFF the exterior lamps* when the lighting switch is in the AUTO position, according to a front wiper operation.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Delay timer function turns the exterior lamps* OFF depending on the vehicle condition with the auto light function when the ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "*: Headlight (LO/HI), front fog light, parking light, license plate light, side marker light and tail light.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Headlight (HI) depend on the combination switch condition.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Front fog light depend on the combination switch condition.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "AUTO LIGHT FUNCTION", "title");
si[i++] = gsitm("N512020510004800ENG.html", "BCM detects the combination switch condition with the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "BCM detects the vehicle condition that is required for auto light control with the following signals.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Parking brake status signal (received from combination meter via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Vehicle speed signal [received from ABS actuator and electric unit (control unit) via CAN communication]", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Shift position signal (received from TCM via CAN communication)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "BCM supplies voltage to the optical sensor when the ignition switch is turned ON.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Optical sensor converts outside brightness (lux) to voltage and transmits the optical sensor signal to BCM.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "When ignition switch is turned ON, BCM detects outside brightness from the optical sensor signal and judges ON/OFF condition of each exterior light, depending on the outside brightness condition.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "BCM transmits each request signal to IPDM E/R and each status signal to combination meter via CAN communication, according to ON/OFF condition by the auto light function.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Lighting conditions for lighting switch AUTO (When all of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Parking brake is released or vehicle speed is 4 km/h (2.5 MPH) or more", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Lighting judgment ON depending on the brightness outside of vehicle", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Lighting off conditions for lighting switch AUTO (When any of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Ignition switch OFF", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Vehicle speed is 3 km/h (1.8 MPH) or less and parking brake is operated*", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "*: Only before releasing the parking brake. After releasing the parking brake, it will not turn lights OFF if the parking brake is operate again.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Lighting judgment OFF depending on the brightness outside of vehicle", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Headlight lighting conditions when the lighting switch is 1ST (When all of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Vehicle speed is 4 km/h (2.5 MPH) or more, or parking brake is released and other than select lever P range", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Headlight lighting off conditions when the lighting switch is 1ST (When any of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Vehicle speed is 3 km/h (1.8 MPH) or less and parking brake is operated", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Vehicle speed is 3 km/h (1.8 MPH) or less and select lever is P range", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "WIPER LINKED AUTO LIGHTING FUNCTION", "title");
si[i++] = gsitm("N512020510004800ENG.html", "BCM turns each exterior light ON when the within 60 seconds detecting 4 operations of the front wiper while the lighting switch is in AUTO position.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "BCM turns OFF the headlights 3 seconds after the front wiper switch is turned OFF.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "DELAY TIMER FUNCTION", "title");
si[i++] = gsitm("N512020510004800ENG.html", "BCM turns the exterior lamps OFF depending on the vehicle condition with the auto light function when the ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Turns the exterior lamps OFF 30 seconds after the ignition switch is turned OFF.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "Delay timer function turns OFF, when the engine running or the lighting switch is other than AUTO.", "ptxt");
si[i++] = gsitm("N512020510004800ENG.html", "When any position other than the lighting switch AUTO is set, the auto light system function switches to the exterior light battery saver function.", "ptxt");
