si[i++] = gsitm("N512020510004A00ENG.html", "High beam assist system is a system that can reduce the driver\'s switch operation load. The system automatically switches the headlight to the low beam mode when a vehicle ahead or an oncoming vehicle appears, while driving the vehicle with the headlights in high beam mode at night.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "When the high beam assist system operation permission conditions are satisfied, the high beam assist indicator light in the combination meter turns ON and informs that the high beam assist is in operation.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "High beam assist system is controlled by each function of BCM, IPDM E/R and front camera unit.", "ptxt");
