si[i++] = gsitm("N512020510004A00ENG.html", "Front camera unit requests the headlight HI operation to BCM when all of following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Detects the vehicle speed is approx. 30 km/h (19 MPH) or more.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Recognizes the ambient condition is dark.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Recognizes there is no oncoming vehicle or no vehicle ahead in front of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Headlight LO Operation Request", "title");
