si[i++] = gsitm("N512020510004A00ENG.html", "Detects the vehicle speed is approx. 20 km/h (13 MPH) or less.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Recognizes the ambient condition is bright.", "ptxt");
si[i++] = gsitm("N512020510004A00ENG.html", "Recognizes there is oncoming vehicle or vehicle ahead in front of the vehicle.", "ptxt");
