si[i++] = gsitm("N512020510004B00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N512020510004B00ENG.html", "BCM detects the combination switch condition with the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "BCM transmits the high beam assist indicator signal to the combination meter via CAN communication when the high beam assist system operation permission conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "High beam assist system operation permission conditions (when all of following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Lighting switch AUTO (Only when the illuminating judgement by auto light function is ON. Refer to .)", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "High beam assist switch ON", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Combination meter turns the high beam assist indicator light ON according to the high beam assist indicator signal.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Front camera unit detects the vehicle status and ambient status that are required for high beam assist control with the following signals.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Vehicle speed signal [received from ABS actuator and electric unit (control unit) via CAN communication]", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Ambient light signal (detect from front camera unit)", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Image sensor signal (detect from front camera unit)", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Front camera unit judges the current recommended beam according to the vehicle status and ambient condition, and transmits the high beam assist request signal (headlight HI operation / headlight LO operation) to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "BCM switches the headlight LO operation / headlight HI operation according to high beam assist request signal while the high beam assist system operation permission conditions are satisfied. For headlight operation, refer to .", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "RECOMMENDED BEAM JUDGEMENT BY FRONT CAMERA UNIT", "title");
si[i++] = gsitm("N512020510004B00ENG.html", "Headlight HI Operation Request", "title");
si[i++] = gsitm("N512020510004B00ENG.html", "Front camera unit requests the headlight HI operation to BCM when all of following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Detects the vehicle speed is approx. 30 km/h (19 MPH) or more.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Recognizes the ambient condition is dark.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Recognizes there is no oncoming vehicle or no vehicle ahead in front of the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Headlight LO Operation Request", "title");
si[i++] = gsitm("N512020510004B00ENG.html", "Front camera unit requests the headlight LO operation to BCM when either of following conditions is satisfied.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Detects the vehicle speed is approx. 20 km/h (13 MPH) or less.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Recognizes the ambient condition is bright.", "ptxt");
si[i++] = gsitm("N512020510004B00ENG.html", "Recognizes there is oncoming vehicle or vehicle ahead in front of the vehicle.", "ptxt");
