si[i++] = gsitm("N512020510004C00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004C00ENG.html", "Daytime running light is controlled by daytime running light control function and combination switch reading function of BCM, and smart FET control function and LIN communication function of IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "DAYTIME RUNNING LIGHT OPERATION", "title");
si[i++] = gsitm("N512020510004C00ENG.html", "BCM detects the combination switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "BCM detects vehicle condition depending on the engine status signal and parking brake status signal (received from ECM and combination meter via CAN communication).", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "BCM transmits the daytime running light request signal to IPDM E/R via CAN communication according to the daytime running light ON condition.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Daytime running light ON condition", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Engine running, parking brake release and any following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Lighting switch OFF", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Lighting switch 1ST", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Lighting switch AUTO (Only when the illumination judgement by auto light function is OFF. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "IPDM E/R turns the integrated smart FET ON according to daytime running light request signal, and transmits the control signal to LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "IPDM E/R transmits the request to LED headlight control module (via LIN communication) according to daytime running light request signal.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "LED headlight control module turns the daytime running light ON according to the control signal and request (via LIN communication) from IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004C00ENG.html", "Daytime running light and parking light use a common light source. When the daytime running light is turned ON while parking light is ON, the parking light/daytime running light is brightening.", "ptxt");
si[i++] = gsitm("N5120202H0002D00ENG.html", "Fail-safe", "title");
si[i++] = gsitm("N5120202H0002D00ENG.html", "CAN COMMUNICATION CONTROL", "title");
si[i++] = gsitm("N5120202H0002D00ENG.html", "When CAN communication with BCM is impossible, IPDM E/R performs fail-safe control. After CAN communication recovers normally, it also returns to normal control.", "ptxt");
