si[i++] = gsitm("N512020510004D00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "Turn signal light and hazard warning light is controlled by combination switch reading function and the flasher control function of BCM.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "TURN SIGNAL LIGHT OPERATION", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM detects the combination switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM supplies voltage to the right (left) turn signal light circuit when the ignition switch is ON and the turn signal switch is in the right (left) position. BCM blinks the turn signal light.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "In the sequential turn specification, the LED is turned ON from the center of the vehicle to the outside.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "HAZARD WARNING LIGHT OPERATION", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM supplies voltage to both turn signal light circuits when the hazard switch is ON. BCM blinks the hazard warning light.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "TURN SIGNAL INDICATOR LIGHT AND TURN SIGNAL SOUND OPERATION", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM transmits the turn indicator signal to the combination meter via CAN communication while the turn signal light and the hazard warning light are operating.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "Combination meter outputs the turn signal sound to the meter speaker while blinking the turn signal indicator light according to the turn indicator signal.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "Meter speaker outputs the turn signal sound according to the signal from combination meter.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "3-TIME FLASHER FUNCTION", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "By a short touch of the turn signal lever, BCM blinks the turn signal lamps 3 times in the selected direction.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "Cancels the operation when short touch of the turn signal lever in the reverse direction during the 3-time flasher function operation.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "The flasher setting of 3-time flasher function can be changed using M.U.T.-III SE. Refer to M.U.T.-III SE Function (BCM - BCM).", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "HIGH FLASHER OPERATION", "title");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM detects the turn signal light circuit status from the current value.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "BCM increases the turn signal light blinking speed if the light or harness open is detected with the turn signal light operating.", "ptxt");
si[i++] = gsitm("N512020510004D00ENG.html", "The blinking speed is normal while operating the hazard warning light.", "ptxt");
