si[i++] = gsitm("N512020510004E00ENG.html", "IPDM E/R supplies power supply voltage to license plate light, and turns the license plate light ON.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Controls the integrated smart FET, and supplies voltage to the load according with the request from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Transmits the control signal and request (via LIN communication) to the LED headlight control module according with the request from BCM via CAN communication.", "ptxt");
