si[i++] = gsitm("N512020510004E00ENG.html", "Detects each switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Parking, license plate and tail light ON/OFF is judged from each signal, and then a request is transmitted to IPDM E/R (via CAN communication) to turn each smart FET ON/OFF and controls the LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "It also transmits a status to the combination meter (via CAN communication) to turns parking light indicator light ON/OFF.", "ptxt");
