si[i++] = gsitm("N512020510004E00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512020510004E00ENG.html", "Parking, license plate and tail lamps are controlled by combination switch reading function and parking, license plate, side marker and tail lamps control function of BCM, and smart FET control function and LIN communication function of IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "PARKING, LICENSE PLATE AND TAIL LAMPS OPERATION", "title");
si[i++] = gsitm("N512020510004E00ENG.html", "BCM detects the combination switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "BCM transmits the parking light request signal to IPDM E/R and parking light status signal to the combination meter via CAN communication according to the parking, license plate and tail lamps ON condition.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Parking, license plate and tail lamps ON condition (when any of the following conditions are satisfied)", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Lighting switch 1ST", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Lighting switch 2ND", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Lighting switch AUTO (Only when the illumination judgement by auto light function is ON. Refer to  &lt;Without light & rain sensor> or  &lt;With light & rain sensor>.)", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "IPDM E/R turns the integrated smart FET ON and turns the license plate and tail lamps ON according to the parking light request signal.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "IPDM E/R turns the integrated smart FET ON according to parking light request signal, and transmits the control signal to LED headlight control module.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "IPDM E/R transmits the request to LED headlight control module (via LIN communication) according to parking light request signal.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "LED headlight control module turns the parking light ON according to the control signal and request (via LIN communication) from IPDM E/R.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Combination meter turns the parking light indicator light ON according to the parking light status signal.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "When headlight is turned ON while parking, license plate and tail light are ON the parking light indicator light is turns OFF. (Full TFT meter models)", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "SIGNATURE LIGHT FUNCTION", "title");
si[i++] = gsitm("N512020510004E00ENG.html", "Description", "title");
si[i++] = gsitm("N512020510004E00ENG.html", "The signature light function is a function that turns ON the parking light, license plate light and tail light for a set period of time when the doors are locked or unlocked from outside the vehicle.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Operation Description", "title");
si[i++] = gsitm("N512020510004E00ENG.html", "BCM transmits the parking light request signal to IPDM E/R and parking light status signal to the combination meter via CAN communication according to the signature light function ON condition.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Signature light function ON condition (Operation when doors are unlocked)", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "When all of the following conditions are satisfied, the signature light function operates when door unlock operation is performed from outside the vehicle (Keyless operation key, door request switch, etc.).", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Ignition switch: OFF", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Door open/close status: All door close", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Door lock status: All door lock", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "When any of the following conditions is satisfied while the signature light function is operating, the signature light function stops.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Since signature light function ON, approx. 30 seconds are passed.", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "When door lock operation is performed with the Keyless operation key or door request switch, the system changes to operation when doors are locked", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "Signature light function ON condition (Operation when doors are locked)", "ptxt");
si[i++] = gsitm("N512020510004E00ENG.html", "When all of the following conditions are satisfied, the signature light function operates when door lock operation is performed from outside the vehicle (Keyless operation key or door request switch, etc.).", "ptxt");
