si[i++] = gsitm("N5120205G0000F00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GET INFORMATION FOR SYMPTOM", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Get detailed information from the customer about the symptom (the condition and the environment when the incident/malfunction occurs).", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Check operation condition of the function that is malfunctioning.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "CHECK DTC", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Check DTC.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Perform the following procedure if DTC is detected.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Record DTC and freeze frame data (Print them out using M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Erase DTC.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Study the relationship between the cause detected by DTC and the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Check related service bulletins for information.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Are any symptoms described and any DTC detected?", "question");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Symptom is described, DTC is detected", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Symptom is described, DTC is not detected", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Symptom is not described, DTC is detected", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "CONFIRM THE SYMPTOM", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Try to confirm the symptom described by the customer.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Also study the normal operation and fail-safe related to the symptom.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Verify relation between the symptom and the condition when the symptom is detected.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Perform DTC CONFIRMATION PROCEDURE for the detected DTC, and then check that DTC is detected again. At this time, always connect M.U.T.-III SE to the vehicle, and check self diagnostic results in real time.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "If two or more DTCs are detected, refer to DTC INSPECTION PRIORITY CHART, and determine trouble diagnosis order.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Freeze frame data is useful if the DTC is not detected.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Perform Component Function Check if DTC CONFIRMATION PROCEDURE is not included on Service Manual. This simplified check procedure is an effective alternative though DTC cannot be detected during this check.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "If the result of Component Function Check is NG, it is the same as the detection of DTC by DTC CONFIRMATION PROCEDURE.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N5120205G0000F00ENG.html", "YES", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "NO", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Check according to Intermittent Incident.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "DETECT MALFUNCTIONING SYSTEM BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Detect malfunctioning system according to SYMPTOM DIAGNOSIS based on the confirmed symptom in step 4, and determine the trouble diagnosis order based on possible causes and symptom.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Is the symptom described?", "question");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Monitor input data from related sensors or check voltage of related module terminals using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "DETECT MALFUNCTIONING PART BY DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Inspect according to Diagnosis Procedure of the system.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Is malfunctioning part detected?", "question");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "REPAIR OR REPLACE THE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Repair or replace the malfunctioning part.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Reconnect parts or connectors disconnected during Diagnosis Procedure again after repair and replacement.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Check DTC. If DTC is detected, erase it.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "FINAL CHECK", "title");
si[i++] = gsitm("N5120205G0000F00ENG.html", "When DTC is detected in step 2, perform DTC CONFIRMATION PROCEDURE again, and then check that the malfunction is repaired securely.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "When symptom is described by the customer, refer to confirmed symptom in step 3 or 4, and check that the symptom is not detected.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Is DTC detected and does symptom remain?", "question");
si[i++] = gsitm("N5120205G0000F00ENG.html", "YES-1", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "DTC is detected: GO TO 7.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "YES-2", "result");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Symptom remains: GO TO 4.", "ptxt");
si[i++] = gsitm("N5120205G0000F00ENG.html", "Before returning the vehicle to the customer, always erase DTC.", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5120205I0000O00ENG.html", "CHECK START", "title");
si[i++] = gsitm("N5120205I0000O00ENG.html", "In the cool LED status (wait for more than 10 minutes after turning headlight OFF), turn ON and turn OFF headlight for the several times. Check that headlight operates normally each time.", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "In the cool LED status, turn headlight ON, wait until headlight enters to the stable status (approximately 5 minutes after turning headlight ON), and then check that headlight operates normally without blinking or flickering.", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "In the warm LED status (turn headlight ON for more than 15 minutes and wait for 1 minute after turning OFF), turn ON and turn OFF headlight for the several times. Check that headlight operates normally each time.", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "Turn headlight ON for approximately 30 minutes, and then check that headlight operates normally without difference in brightness between LH and RH, blinking or flickering.", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N5120205I0000O00ENG.html", "YES", "result");
si[i++] = gsitm("N5120205I0000O00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5120205I0000O00ENG.html", "NO", "result");
si[i++] = gsitm("N5120205I0000O00ENG.html", "Refer to .", "ptxt");
