si[i++] = gsitm("N5120201P0002E00ENG.html", "LED brightness and color may slightly change until the temperature becomes stable. This is not malfunction.", "ptxt");
si[i++] = gsitm("N5120201P0002E00ENG.html", "Illumination time lag may occur between right and left. This is not malfunction.", "ptxt");
