si[i++] = gsitm("N5120201P0002E00ENG.html", "INTELLIGENT AUTO LIGHT SYSTEM", "title");
si[i++] = gsitm("N5120201P0002E00ENG.html", "The headlight may not be turned ON/OFF immediately after passing dark area or bright area (short tunnel, sky bridge, shadowed area etc.) while using the auto light system. This causes for the control difference. This is normal.", "ptxt");
si[i++] = gsitm("N5120201P0002E00ENG.html", "HIGH BEAM ASSIST SYSTEM", "title");
si[i++] = gsitm("N5120201P0002E00ENG.html", "When driving while using the high beam assist system, the headlight beam may not switch or the beam switching timing may vary according to the ambient environment (the condition of the vehicle ahead, the condition of the road, the position of the vehicle, etc.).This is due to control differences and is not a malfunction.", "ptxt");
