si[i++] = gsitm("N5120201V0009R00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5120201V0009R00ENG.html", "Select “FRONT FOG LIGHT REQ” in “Data List” mode of “IPDM E/R” using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5120201V0009R00ENG.html", "With operating the front fog light switch, check the monitor status.", "ptxt");
si[i++] = gsitm("N5120201V0009R00ENG.html", "Monitor item", "ptxt");
si[i++] = gsitm("N5120201V0009R00ENG.html", "Condition", "ptxt");
