si[i++] = gsitm("N5120204S0000A00ENG.html", "Service Specifications", "title");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Standard value", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Headlight aiming", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Low-beam", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Vertical direction", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "30 mm (0.57°) below horizontal (H)", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "±15 mm (±0.29°) from the horizontal cut-off line", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Horizontal direction", "ptxt");
