si[i++] = gsitm("N5120204S0000A00ENG.html", "± 26 mm (± 0.5°) from the vertical line (V)", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Headlight luminous intensity measurement cd", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "(When a screen is set 25 m ahead of the vehicle)", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "-", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "30,000 cd or more", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "PRECAUTIONS ON HOW TO USE THE HEADLIGHT ASSEMBLY", "title");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Be careful with the following items as resin lenses are used in the headlight assembly.", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Don\'t illuminate the headlight for three minutes or more when the headlight is covered with scratch protector.", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Don\'t tape the outer lens.", "ptxt");
si[i++] = gsitm("N5120204S0000A00ENG.html", "Don\'t scratch the outer lens surface with a sharp edged special tool.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Headlight Aiming", "title");
si[i++] = gsitm("N512020310000A00ENG.html", "&lt;USING A BEAM SETTING EQUIPMENT>", "title");
si[i++] = gsitm("N512020310000A00ENG.html", "The headlights should be aimed with the proper beam setting equipment, and in accordance with the equipment manufacture\'s instructions.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Alternately turn the adjusting screw to adjust the headlight aiming.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "&lt;USING A SCREEN> (LOW-BEAM)", "title");
si[i++] = gsitm("N512020310000A00ENG.html", "PRE-AIMING INSTRUCTION", "title");
si[i++] = gsitm("N512020310000A00ENG.html", "Inspect for badly rusted or faulty headlight assemblies.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "These conditions must be corrected before a satisfactory adjustment can be made.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Inspect tire inflation, and adjust if it is necessary.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "If the fuel tank is not filled up, put weight in the luggage compartment to make up for the fuel shortage so that the weight will become 90% of full-state weight or heavier. (0.8 kg per litter)", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "There should be no other load in the vehicle other than driver or substituted weight of approximately 75 kg placed in driver\'s position.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Turn the headlight levelling switch to the switch position \"0.\" &lt;Vehicles with headlight manual levelling system>", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Change the vehicle posture, and then operate the actuator of headlight levelling unit once. &lt;Vehicles with headlight automatic levelling system>", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Thoroughly clean the headlight lenses.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Check that the square shaped marking is on the lens surface.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Place the vehicle on a level floor, perpendicular to a flat screen 3 m away from the headlight center position of the low-beam.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Rock vehicle sideways to allow vehicle to assume its normal position.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "To correct for distortion of the suspension, rock the bumpers on the front/rear side of the vehicle up and down three times alternately.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Run the engine at a speed of 2,000 r/min to charge the battery.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Four lines of adhesive tape (or equivalent markings) are required on screen or wall:", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Position a vertical tape or mark so that it is aligned with the vehicle center line.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Measure the distance from the headlight center position to the floor. Transfer the measurement to the screen. Horizontal tape or mark on the screen is for reference of vertical adjustment.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Measure the distance from the center line of the vehicle to the center of each headlight. Transfer the measurement to the screen. Vertical tape or mark on the screen with reference to the center line of each headlight.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "HEADLAMP ADJUSTMENT", "title");
si[i++] = gsitm("N512020310000A00ENG.html", "Do not cover a headlight for more than three minutes to prevent the plastic headlight lens deformation.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "The low-beam headlight should project on the screen upper edge of the beam (cut-off).", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "When adjusting the horizontal direction side, insert the screwdriver from the service hole near the headlight assembly mounting bolts.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Be sure to adjust the aiming adjustment screw in the tightening direction.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "If not the case, turn the adjusting screws to achieve the specified low-beam cut-off location on the aiming screen.", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Standard value:", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Vertical direction; 30 mm (0.57°) below horizontal (H)", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Horizontal direction; Elbow point intersects the vertical line (V)", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Limit:", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Vertical direction; ±15 mm (±0.29°) from the horizontal cut-off line", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "Horizontal direction; ± 26 mm (± 0.5°) from the vertical line (V)", "ptxt");
si[i++] = gsitm("N512020310000A00ENG.html", "The illustration shows LH drive vehicles. For RH drive vehicles, it is symmetrical.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "Luminous Intensity Measurement", "title");
si[i++] = gsitm("N512020850000500ENG.html", "Using a photometer, and following its manufacture\'s instruction manual, measure the headlight intensity and check to be sure that the limit value is satisfied.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "Limit: 30,000 cd or more (When a screen is set 25 m ahead of the vehicle)", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "When measuring the intensity, maintain an engine speed of 2,000 r/min, with the battery in the charging condition.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "There may be special local regulations pertaining to headlight intensity, be sure to make any adjustments necessary to satisfy such regulations.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "Check that the headlight intensity of the high-beam satisfies the limit value.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "If an illuminometer is used to make the measurements, convert its values to photometer values by using the following formula.", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "I = Er2:", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "I=intensity (cd)", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "E=illumination (lux)", "ptxt");
si[i++] = gsitm("N512020850000500ENG.html", "r=distance (m) from headlights to illuminometer", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "service specifications", "title");
si[i++] = gsitm("N5120204S0000500ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Standard value", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Fog light aiming (cutoff line direction) [at 7.62 m]", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "The horizontal line 277.0 mm (2.08 degrees angle) below the horizontal line (H)", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "-", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Fog light aiming (vertical direction) [at 7.62 m]", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Area from 163.0 mm (1.22 degrees angle) above the cutoff line to 163.0 mm (1.22 degrees angle) below the cutoff line", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Fog light aiming (horizontal direction) [at 7.62 m]", "ptxt");
si[i++] = gsitm("N5120204S0000500ENG.html", "Vertical line (V) ± 599.7 mm (± 4.5 degrees angle).", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Front Fog Light Aiming", "title");
si[i++] = gsitm("N5120202L0000A00ENG.html", "PRE-AIMING INSTRUCTIONS", "title");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Inspect for rusted or faulty front fog light assemblies.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "These conditions must be corrected before a satisfactory adjustment can be made.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Inspect tire inflation, and adjust if necessary.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "If the fuel tank is not full, place a weight in the trunk of the vehicle to simulate weight of a full tank [3 kg per gallon].", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "There should be no other load in the vehicle other than driver or substituted weight of approximately 68 kg placed in driver\'s position.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Thoroughly clean the front fog light lenses.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Place the vehicle on a level floor, perpendicular to a flat screen 7.62 m away from the bulb center-marks on the fog light lens.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Rock the vehicle sideways to allow the vehicle to assume its normal position.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Bounce the front suspension through three (3) oscillations by applying the body weight to the hood or bumper.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Measure the center of the front fog lights as shown in the illustration.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Four lines of adhesive tape (or equivalent markings) are required on screen or wall:", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Position a vertical tape or mark so that it is aligned with the vehicle center line.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Measure the distance from the center of the front fog light lens to the floor. Transfer the measurement to the screen. Horizontal tape or mark on the screen is for reference of vertical adjustment.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Measure the distance from the center line of the vehicle to the center of each front fog light. Transfer the measurement to the screen. Vertical tape or mark on the screen is for reference to the center line of each front fog light.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "FOG LIGHT ADJUSTMENT", "title");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Check if the beam shining onto the screen is at the standard value.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Standard value:", "title");
si[i++] = gsitm("N5120202L0000A00ENG.html", "(Cutoff line direction): The horizontal line (H) 277.0 mm (2.08 degrees angle) below the horizontal line (H)", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Limit:", "title");
si[i++] = gsitm("N5120202L0000A00ENG.html", "(Vertical direction): Area from 163.0 mm (1.22 degrees angle) above the cutoff line to 163.0 mm (1.22 degrees angle) below the cutoff line", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "(Horizontal direction): Vertical line (V) ± 599.7 mm (± 4.5 degrees angle)", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "Be sure to adjust the aiming adjustment screw in the tightening direction.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "If it is not within the standard value range, adjust by turning the adjusting screw.", "ptxt");
si[i++] = gsitm("N5120202L0000A00ENG.html", "The horizontal direction is non-adjustable. If deviation of the light beam axis exceeds the standard value, check that the mounting location or some other points are not faulty.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "Configuration (ALH-ECU)", "title");
si[i++] = gsitm("N512020890000800ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N512020890000800ENG.html", "Complete the procedure of \"Configuration\" in order.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "If incorrect \"Configuration\", incidents might occur.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the ALH-ECU.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "For details the network connection and operation, refer to \"M.U.T.-III SE Operation Manual\".", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "The configuration no need to \"save\" configuration data from the ALH-ECU. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "WORK PROCEDURE", "title");
si[i++] = gsitm("N512020890000800ENG.html", "Perform writing vehicle specification to ALH-ECU. following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N512020890000800ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Initialization For IPDM E/R", "title");
si[i++] = gsitm("N512020870000700ENG.html", "After the operation below is completed, initialize the IPDM E/R (headlight automatic levelling system).", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "The IPDM E/R is replaced.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "The rear height sensor is replaced or removed/installed.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "The suspension related components are replaced or removed/installed.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "When adjusting the wheel alignment.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "INITIALIZATION PROCEDURE", "title");
si[i++] = gsitm("N512020870000700ENG.html", "If the \"SENSOR INITIALIZE\" is not completed, IPDM E/R has detected a change in the height sensor signal, and the \"SENSOR INITIALIZE\" has been stopped. In this case, turn off the ignition switch to prevent the vehicle height from changing, then turn on the ignition switch and perform the \"SENSOR INITIALIZE\" again.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Park the vehicle on a level surface.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Set the vehicle to the empty condition (0 occupants).", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Connect the M.U.T.-IIISE to the data link connector.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Turn the ignition switch to \"ON\" position.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Select the M.U.T.-IIISE screen menu as follows.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Select \"IPDM E/R\" displayed on the \"System selection\" screen.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Select \"Special function.\"", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Select \"Initialization\".", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Select \"SENSOR INITIALIZE\".", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "If \"Initialization completed\" is displayed, press the \"Finish\" button. If the initialization does not finish, perform the initialization again.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Check that the diagnostic trouble code is not set in the IPDM E/R. If the diagnostic trouble code is set, perform the initialization again.", "ptxt");
si[i++] = gsitm("N512020870000700ENG.html", "Perform the headlight aiming (Refer to Headlight Aiming ).", "ptxt");
si[i++] = gsitm("N5120208J0000100ENG.html", "Replace The Back-up Light Bulb", "title");
si[i++] = gsitm("N5120208J0000100ENG.html", "Remove the power liftgate inner finisher lid, refer to .", "ptxt");
si[i++] = gsitm("N5120208J0000100ENG.html", "Turn the socket to remove (Refer to ).", "ptxt");
si[i++] = gsitm("N5120208J0000100ENG.html", "Remove the bulb from the socket.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Pre-removal Operation", "title");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Front Bumper Assembly Removal (Refer to ).", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Post-installation Operation", "title");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Front Bumper Assembly Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight Aiming Adjustment (Refer to ).", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Removal Steps", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight inside bracket", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight assembly/Headlight outside bracket/Headlight upper bracket/Headlight lower bracket", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "3.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight outside bracket", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "4.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight upper bracket", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "5.", "ptxt");
si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight lower bracket", "ptxt");
