si[i++] = gsitm("N5120204K0009S00ENG.html", "Headlight assembly", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Disassembly and Reassembly", "title");
si[i++] = gsitm("N512020210000800ENG.html", "Disassembly steps", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "1.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Headlight lens", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "2.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Headlight sealant", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "3.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Headlight housing", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "DISASSEMBLY SERVICE POINT", "title");
si[i++] = gsitm("N512020210000800ENG.html", "&lt;&lt;A>> HEADLIGHT LENS, HEADLIGHT SEALANT, HEADLIGHT HOUSING REMOVAL", "title");
si[i++] = gsitm("N512020210000800ENG.html", "Wear clean rubber gloves during work.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "In order to prevent intrusion and adhesion of foreign materials to the headlight assembly, perform the work indoors if possible.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Be careful not to damage the claws and engaging part of the headlight housing and the headlight lens because airtightness in the headlight may not be secured or it may cause damage to the headlight.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "When using a dryer, do not heat one area of the headlight housing intensively or heat it at temperature of 110°C or higher to prevent deformation and erosion.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Do not allow Mitsubishi Genuine Parts Cleaner (MZ100387), grease or sebum to adhere to the lens side of the removed headlight housing and the inner side of the headlight lens.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Do not let dirt adhere to the plated surface because even wiping it with a soft cloth or a waste cloth may cause damage to it.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Be sure to clean them by dry wiping. Do not use solvent.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Remove the screws (seven locations).", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "When heating the headlight housing, be careful not to let the temperature exceed 110°C because it may be deformed.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Heat the surface of the headlight housing to 70 - 80°C using an infrared lamp, a dryer or the like.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Work carefully not to damage the headlight.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Disengage the claws (seven locations).", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "When removing the headlight lens, be careful not to touch the internal parts.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Remove the headlight lens from the headlight housing.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Remove the headlight sealant fitted in the groove of the headlight housing by pulling it.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "REASSEMBLY SERVICE POINT", "title");
si[i++] = gsitm("N512020210000800ENG.html", ">>A&lt;&lt; HEADLIGHT LENS, HEADLIGHT SEALANT, HEADLIGHT HOUSING INSTALLATION", "title");
si[i++] = gsitm("N512020210000800ENG.html", "Do not allow Mitsubishi Genuine Parts Cleaner (MZ100387), grease or sebum to adhere to the lens side of the headlight housing and the inner side of the headlight lens.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Do not use a dryer because if the engaging part of the headlight housing and the headlight lens is heated from the back, it may be deformed or melted and may cause damage to the headlight.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "When installing the headlight lens to the headlight housing, ensure that the wiring harness is not caught or strained.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Clean the headlight sealant application area thoroughly by using a waste cloth moistened with Mitsubishi Genuine Parts Cleaner (MZ100387).", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Cut a new headlight sealant at 45° angles with scissors.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Do not apply tension to the headlight sealant when placing it. If the headlight sealant is strongly pulled, it will be thin and airtightness cannot be secured, and it may also cause the sealant to float from the groove at the curved section.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "In order to secure airtightness, be sure to make the start point and the end point of the headlight sealant overlap by approximately 20 mm.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Apply the new headlight sealant into the groove of the headlight housing by hand, and make the start point and the end point of the headlight sealant overlap by approximately 20 mm.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Cut the end point of the headlight sealant at 45° angles with scissors.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Wrap release paper around the tip of a flat-tipped screwdriver as shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "By wrapping release paper, it will be easier to press the headlight sealant into the groove because the sealant does not stick to the screwdriver easily.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "The release paper comes with the new headlight sealant.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "After installing the headlight sealant, check that there is no floating, protrusion or gap between the start point and the end point. Check the sealant at the curved section carefully because the sealant tend to float from the groove.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Push the headlight sealant into the headlight housing groove thoroughly to the bottom as shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Install the headlight sealant to the groove of the headlight housing by pushing the center of the sealant with the flat-tipped screwdriver wrapped with release paper.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Set the headlight lens by lowering it straight down.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Lower the headlight lens straight down to install it to the headlight housing.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Remove the caps from the vent holes (two locations) shown in the figure. Then, set the hand vacuum pump to one of the vent holes and block the other vent hole with fingers.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "Apply positive pressure of 4 kPa to the headlight assembly by using the hand vacuum pump and check whether the pressure can be held for 10 seconds.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "If the pressure cannot be held for 10 seconds, replace the headlight sealant.", "ptxt");
si[i++] = gsitm("N512020210000800ENG.html", "If the pressure is maintained for 10 seconds, attach the removed two caps to the vent hole.", "ptxt");
si[i++] = gsitm("N5120204K0007U00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5120204K0007U00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N5120204K0007U00ENG.html", "Instrument lower panel assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5120204K0009T00ENG.html", "If the silicon pad of the light and rain sensor which has been removed is in the following condition, do not reuse the light and rain sensor.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "The silicon pad is deformed.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Dust is found on the surface of the silicon pad by visual check.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Removal Steps", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Front camera cover", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "&lt;&lt;A>>", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Light and rain sensor", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "REMOVAL SERVICE POINT", "title");
si[i++] = gsitm("N5120204K0009T00ENG.html", "&lt;&lt;A>> LIGHT AND RAIN SENSOR REMOVAL", "title");
si[i++] = gsitm("N5120204K0009T00ENG.html", "When the sensor is removed, wipe off the silicon pad remaining on the windshield surface.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Disengage light and rain sensor fixing lock spring portion A, and then peel off rain light sensor.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N5120204K0009T00ENG.html", ">>A&lt;&lt; LIGHT AND RAIN SENSOR INSTALLATION", "title");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Clean the sensor installation portion of the windshield.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "When installing, never allow silicon pad to touch the sensor bracket and other parts.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Never use a sensor that is dropped.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Perform check after replacement. Refer to Component Function Check.", "ptxt");
si[i++] = gsitm("N5120204K0009T00ENG.html", "Compress the lock spring portion A vertically to the glass surface and fully engage both ends of lock spring.", "ptxt");
si[i++] = gsitm("N5120204K0007W00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5120204K0007W00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N5120204K0007W00ENG.html", "AV control unit assembly Removal and Installation (Refer to ).", "ptxt");
