si[i++] = gsitm("N5120204K0009U00ENG.html", "Front Bumper Assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N512020210001100ENG.html", "Disassembly steps", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "&lt;&lt;A>>", "ptxt");
