si[i++] = gsitm("N512020210001100ENG.html", "1.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Front combination light lens", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "2.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Front combination light sealant", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "3.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Front combination light housing", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "DISASSEMBLY SERVICE POINT", "title");
si[i++] = gsitm("N512020210001100ENG.html", "&lt;&lt;A>> FRONT COMBINATION LIGHT LENS / FRONT COMBINATION LIGHT SEALANT / FRONT COMBINATION LIGHT HOUSING REMOVAL", "title");
si[i++] = gsitm("N512020210001100ENG.html", "Wear clean rubber gloves during work.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "In order to prevent intrusion and adhesion of foreign materials to the front combination light assembly, perform the work indoors if possible.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Be careful not to damage the claws and engaging part of the front combination light housing and the front combination light lens because airtightness in the front combination light may not be secured or it may cause damage to the front combination light.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When using a dryer, do not heat one area of the front combination light housing intensively or heat it at temperature of 120°C or higher to prevent deformation and erosion.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Do not allow Mitsubishi Motors Genuine Parts Cleaner (MZ100387), grease or sebum to adhere to the lens side of the removed front combination light housing and the inner side of the front combination light lens.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Do not let dirt adhere to the plated surface because even wiping it with a soft cloth or a waste cloth may cause damage to it.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Be sure to clean them by dry wiping. Do not use solvent.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Remove the screws (three locations).", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When heating the front combination light housing, be careful not to let the temperature exceed 120°C because it may be deformed.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Heat the surface of the front combination light housing to 70 - 80°C using an infrared light, a dryer or the like.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Disengage the claws (eleven locations).", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When removing the front combination light lens, be careful not to touch the internal parts.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "If the front combination light lens is hard to remove, heat it again before removal because forcible removal may damage the parts.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Hold the vehicle center side of the front combination light lens and remove the front combination light lens from the front combination light housing in the direction of the arrow.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When removing the front combination light sealant, be careful not to touch the internal parts.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Remove the front combination light sealant fitted in the groove of the front combination light housing by pulling it.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "REASSEMBLY SERVICE POINT", "title");
si[i++] = gsitm("N512020210001100ENG.html", ">>A&lt;&lt; FRONT COMBINATION LIGHT HOUSING / FRONT COMBINATION LIGHT SEALANT / FRONT COMBINATION LIGHT LENS INSTALLATION", "title");
si[i++] = gsitm("N512020210001100ENG.html", "Do not allow Mitsubishi Motors Genuine Parts Cleaner (MZ100387), grease or sebum to adhere to the lens side of the front combination light housing and the inner side of the front combination light lens.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Do not use a dryer when assembling it.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When installing the front combination light lens to the front combination light housing, ensure that the wiring harness is not caught or strained.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Clean the front combination light sealant application area thoroughly by using a waste cloth moistened with Mitsubishi Motors Genuine Parts Cleaner (MZ100387).", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Wrap release paper around the tip of a flat-tipped screwdriver as shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "By wrapping release paper, it will be easier to press the front combination light sealant into the groove because the sealant does not stick to the screwdriver easily.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "The release paper comes with the new front combination light sealant.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Cut a new front combination light sealant at 45° with scissors.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Install the new front combination light sealant counterclockwise starting at the lower side of the front combination light housing (range B), making sure that the sealant surface which is cut at 45° as shown in the figure is facing toward the outside of the front combination light housing groove.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Do not apply tension to the front combination light sealant when placing it. If the front combination light sealant is strongly pulled, it will be thin and airtightness cannot be secured, and it may also cause the sealant to float from the groove at the curved section.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When cutting the front combination light sealant at the end point, make sure that its length is not too long or too short.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When installing the front combination light sealant, make sure that the start point and the end point which are cut at 45° overlap to secure airtightness.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Install the front combination light sealant to the entire circumference of the front combination light housing groove. Then, cut the end point of the sealant at 45°. Make the start point and the end point of the sealant overlap by approximately 20 mm as shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "After installing the front combination light sealant, check that there is no floating, protrusion or gap between the start point and the end point. Check the sealant at the curved section carefully because the sealant tend to float from the groove.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Push the front combination light sealant into the front combination light housing groove thoroughly to the bottom as shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Install the front combination light sealant to the groove of the front combination light housing by pushing the center of the sealant with the flat-tipped screwdriver wrapped with release paper.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "When installing the front combination light lens, be careful not to touch the internal parts.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Lower the front combination light lens straight down to install it to the front combination light housing.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Install the screws (three locations).", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "There is a filter inside the vent cap, but do not lose it as it serves to prevent water from entering.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Remove the caps from the vent holes (two locations) shown in the figure.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Set the hand vacuum pump to one of the vent holes and block the other vent hole with fingers.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Because of the special shape of the vent hole, use a butyl sealant or similar material when using a hand vacuum pump to ensure a sealed condition.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "Apply positive pressure of 3 kPa to the front combination light assembly by using the hand vacuum pump and check whether the pressure can be held for 20 seconds.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "If the pressure cannot be held for 20 seconds, replace the front combination light sealant.", "ptxt");
si[i++] = gsitm("N512020210001100ENG.html", "If the pressure is maintained for 20 seconds, install the vent caps.", "ptxt");
