si[i++] = gsitm("N512030400004C00ENG.html", "Door switch", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Detects the door condition (open or close), and inputs the door switch signal to BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door lock and unlock switch", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Transmits the door lock and unlock switch signal to BCM from door lock and unlock switch operation.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Unlock sensor", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Detects the front door lock (driver side) condition, and inputs the unlock sensor signal to BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Keyless operation key", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Transmits the door lock/unlock signal to Keyless operation key unit from door lock/unlock button operation.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door request switch", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Detects the door lock/unlock operation from outside of the vehicle, and transmits the door request switch signal to Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Controls the interior room light relay, and turns the each interior room light ON/OFF.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Keyless operation key unit", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Transmits the door lock/unlock request signal to BCM (via CAN communication).", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Turns the push-button ignition switch illumination ON/OFF.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior room light relay", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior room light relay supplies power supply voltage to each interior room light according to the control signal from BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Map light", "ptxt");
