si[i++] = gsitm("N512030400004C00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "Following interior room lamps are controlled by interior room light timer control function of BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Map light*", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Personal light*", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Room light*", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Mood light is controlled by mood light control function of BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Luggage room light is controlled by luggage room light control function of BCM.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Push-button ignition switch illumination is controlled by push-button ignition switch illumination control function of Keyless operation key unit.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "*: Interior room light timer control operates when the switch position is DOOR.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "INTERIOR ROOM LIGHT TIMER CONTROL", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior Room Light Timer Basic Operation", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior room lamps turn ON and OFF (gradual brightening and dimming) by the interior room light timer.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Timer operating time is 20 seconds.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Brightening time is 2.8 second and dimming time is 1.5 seconds.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM judges the vehicle condition with the following items and activates the interior room light timer.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Ignition switch status", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door switch signal", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door lock and unlock switch signal", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Unlock sensor signal", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door lock/unlock signal", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door lock/unlock request signal", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior Room Light ON Operation", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM always turns the interior room light relay ON to turn on interior room light when any door opens (except liftgate).", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM activates interior room light timer in any of the following condition to turn interior room light ON for a period of time.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Status of all doors are OPEN –> CLOSE", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Ignition switch is turned engine running –> OFF", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door unlock signal is detected when all doors close with ignition switch OFF", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "The timer restarts if new condition is input during the timer operating time.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Interior Room Light OFF Operation", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM stops the timer in any of the following condition to turn the interior room light OFF.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "The timer operating time is expired", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Ignition switch is turned OFF –> engine running", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "Door lock signal is detected when all doors close with ignition switch OFF", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "MOOD LIGHT CONTROL", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the mood light ON when any door (except liftgate) opens or any door unlock (except liftgate).", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns dimming operation of the mood light when engine running.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the mood light OFF when door lock.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "LUGGAGE ROOM LIGHT CONTROL", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the luggage room light ON when liftgate is open (liftgate switch is ON).", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the luggage room light OFF when liftgate is close (liftgate switch is OFF).", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "PUSH-BUTTON IGNITION SWITCH ILLUMINATION CONTROL", "title");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the push-button ignition switch illumination ON when ignition switch is ON.", "ptxt");
si[i++] = gsitm("N512030400004C00ENG.html", "BCM turns the push-button ignition switch illumination OFF when ignition switch is OFF.", "ptxt");
