si[i++] = gsitm("N512030400004D00ENG.html", "Door lock and unlock switch", "ptxt");
si[i++] = gsitm("N512030400004D00ENG.html", "Transmits the door lock and unlock switch signal to BCM from door lock and unlock switch operation.", "ptxt");
