si[i++] = gsitm("N512040340000B00ENG.html", "When a power supply is supplied to the HI terminal of the front wiper motor, as for the front wiper motor, HI operates a front wiper.", "ptxt");
si[i++] = gsitm("N512040340000B00ENG.html", "When a power supply is supplied to the LO terminal of the front wiper motor, as for the front wiper motor, LO operates a front wiper.", "ptxt");
si[i++] = gsitm("N512040340000B00ENG.html", "When there is a front wiper motor at the stop position, two points of contact in the front wiper are connected, and the front wiper stop position signal is grounded.", "ptxt");
si[i++] = gsitm("N512040340000B00ENG.html", "When front wiper motor operates, two points of contact in the front wiper motor are not connected, and the front wiper stop position signal is not grounded.", "ptxt");
si[i++] = gsitm("N512040340000B00ENG.html", "IPDM E/R detects the front wiper stop position signal from the front wiper motor to find out the front wiper motor position (stop position/except stop position).", "ptxt");
