si[i++] = gsitm("N512040350000N00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512040350000N00ENG.html", "When a power supply is supplied to the ON terminal of the rear wiper motor, the rear wiper motor operates rear wiper.", "ptxt");
si[i++] = gsitm("N512040350000N00ENG.html", "When there is rear wiper motor at the stop position, two points of contact in the rear wiper motor are connected, and the rear wiper stop position signal is grounded.", "ptxt");
