si[i++] = gsitm("N5120403Z0000I00ENG.html", "Sprays the headlight washer fluid.", "ptxt");
si[i++] = gsitm("N5120403Z0000I00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5120403Z0000I00ENG.html", "A headlight washer mechanism that thrusts out and retracts nozzles, utilizing the water pressure produced by motors has been adopted as an option. This mechanism contributes to better appearances of vehicles when their washer nozzles are not in use.", "ptxt");
