si[i++] = gsitm("N512040440000A00ENG.html", "Detects water droplets on the windshield with infrared rays, and transmits the light & rain sensor signal to BCM via the LIN communication line.", "ptxt");
si[i++] = gsitm("N512040440000A00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N512040440000A00ENG.html", "Detects water droplets on the windshield with infrared rays.", "ptxt");
si[i++] = gsitm("N512040440000A00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N512040440000A00ENG.html", "Light & rain sensor judges a wiping speed for front wiper by rain condition and the vehicle conditions. And it transmits the wiping speed request signal to the BCM via the light & rain sensor LIN communication line.", "ptxt");
