si[i++] = gsitm("N5120402S0000S00ENG.html", "Relay control function", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER BASIC OPERATION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM detects the combination switch condition by the combination switch reading function.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal to IPDM E/R via CAN communication depending on each operating condition of the front wiper.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R turns ON/OFF the integrated front wiper relay and the front wiper HIGH relay according to the front wiper request signal. IPDM E/R provides the power supply to operate the front wiper HI/LO operation.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER LO OPERATION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (LOW) to IPDM E/R via CAN communication according to the front wiper LO operating condition.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper LO operating condition", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper switch LO or front wiper switch MIST (while pressing)", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R turns ON the integrated front wiper relay according to the front wiper request signal (LOW).", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER HI OPERATION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (HIGH) to IPDM E/R via CAN communication according to the front wiper HI operating condition.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper HI operating condition", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper switch HI", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R turns ON the integrated front wiper relay and the front wiper HIGH relay according to the front wiper request signal (HIGH).", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER INT OPERATION &lt;WITHOUT LIGHT & RAIN SENSOR>", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (LOW) to IPDM E/R via CAN communication depending on the front wiper INT operating condition and intermittent operation delay interval according to the wiper volume dial position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper INT operating condition", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper switch INT", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R turns ON the integrated front wiper relay so that the front wiper is operated only once according to the front wiper request signal (LOW) and front wiper request signal (RETURN).", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM detects stop position/except stop position of the front wiper motor according to the front wiper stop position signal received from IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (LOW) again after the intermittent operation delay interval.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "The front wiper INT operation setting of the linked or not linked with vehicle speed can be changed by combination meter setting.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper intermittent operation with vehicle speed", "ptxt");
