si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER AUTO OPERATION &lt;WITH LIGHT & RAIN SENSOR>", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Rain Detection", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Rain level and sensor conditions are detected by light & rain sensor.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the vehicle conditions (vehicle speed, front wiper condition, light & rain sensor sensitivity setting, etc.) to the light & rain sensor via the LIN communication line.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Light & rain sensor judges a wiping speed for front wiper by rain condition and the vehicle conditions. And it transmits the wiping speed request signal to the BCM via the light & rain sensor LIN communication line.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Auto Wiping Operation", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM receives the wiping speed request signal from the light & rain sensor via the LIN communication line.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM controls front wiper operation according to the wiping speed request signal. And it transmits the front wiper request signal (LOW or HIGH) to the IPDM E/R via CAN communication line.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper AUTO operating condition", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper switch AUTO", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When the front wiper switch is turned to AUTO position, front wiper operates once regardless of rainy conditions.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Light & rain Sensor Sensitivity Setting", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM determines light & rain sensor sensitivity according to wiper volume dial position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Sensitivity", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Low sensitivity", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Low-medium sensitivity", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Medium-high sensitivity", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "High sensitivity", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "The auto wiping operation setting of the linked or not linked with light & rain sensor can be changed by combination meter setting.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When the wiper volume dial position is turned up by 1 level under front wiper AUTO operating condition, front wiper operates once.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Splash mode operation", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper is operated at HI regardless of the wiper volume adjustment position, when water drops are instantaneously sprayed over the windshield glass due to water splash from oncoming vehicles or other causes. After that, AUTO operation is performed depending on the amount of water drops.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "SPLASH MODE OPERATION CONDITIONS", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Splash mode is not operated and auto wiping operation is performed, while the vehicle is stopped.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER AUTO STOP OPERATION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (RETURN) to IPDM E/R via CAN communication when the front wiper switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R detects the front wiper stop position signal from the front wiper motor to find out the front wiper motor position (stop position/except stop position).", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When IPDM E/R receives the front wiper request signal (RETURN) from BCM and the front wiper motor position is not in the stop position, IPDM E/R turns ON the front wiper relay until the front wiper motor returns to the stop position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When the front wiper motor returns to the stop position, IPDM E/R transmits front wiper status signal to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When BCM receives front wiper status signal from IPDM E/R, BCM transmits the front wiper request signal (STOP) to IPDM E/R via CAN communication.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER OPERATION LINKED WITH WASHER", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (LOW) to IPDM E/R via CAN communication according to the washer linked operating condition of the front wiper.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front wiper request signal (LOW) so that the front wiper operates approximately 2 times when the front washer switch OFF is detected.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Washer linked operating condition of front wiper", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front washer switch ON", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "BCM transmits the front washer pump request signal to IPDM E/R via CAN communication depending on operating condition.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "IPDM E/R turns ON /OFF the front washer relay according to the front washer pump request signal. IPDM E/R provides the power supply to operate the front and rear washer pump.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "WIPER LINKED AUTO LIGHTING FUNCTION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When lighting switch is in the AUTO position, front wiper operates, and then headlight ON. Refer to .", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "FRONT WIPER SERVICE POSITION OPERATION", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "When this operation is activated, front wiper operates at LO speed and stops in the service position so that front wiper arms can pulled up without contacting the hood.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Following 2 methods are the operation procedures.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Method A: With Ignition Switch ON", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Confirm the vehicle is stop.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Confirm front wiper is in stop position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Quickly (Within 0.5 second) move wiper switch lever to MIST position twice, wiper will move to service position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "To exit service position, operate front wiper switch.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Method B: With Ignition Switch OFF", "title");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Ignition switch OFF from any other position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Within 1 minute after turning ignition switch OFF, quickly (Within 0.5 second) move wiper switch lever to MIST position twice, wiper will move to service position.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "To exit service position, turn ignition switch ON and operate front wiper switch.", "ptxt");
si[i++] = gsitm("N5120402S0000S00ENG.html", "Front wiper arms can exit from service position without turning ignition switch ON if front wiper switch is operated within 1 minute after turning ignition switch OFF.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Fail-Safe", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "IPDM E/R", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "CAN COMMUNICATION CONTROL", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "When CAN communication with ECM and BCM is impossible, IPDM E/R performs fail-safe control. After CAN communication recovers normally, it also returns to normal control.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "If No CAN Communication Is Available With BCM", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "Control part", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Fail-safe operation", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Front wiper", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "The status just before activation of fail-safe control is maintained until the ignition switch is turned OFF while the front wiper is operating at LO or HI speed.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "The wiper is operated at LO speed until the ignition switch is turned OFF if the fail-safe control is activated while the front wiper is set in the INT mode and the front wiper motor is operating.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "FRONT WIPER CONTROL", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "IPDM E/R detects front wiper stop position by front wiper stop position signal.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "When front wiper stop position signal is in the condition listed below while the front wiper is operating, IPDM E/R activates the fail-safe.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Ignition switch", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Front wiper switch", "ptxt");
