si[i++] = gsitm("N512040380000K00ENG.html", "Fail-safe", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "OFF", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "The signal does not change from the battery voltage for 10 seconds.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Stops front wiper power supply for 20 seconds", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Except OFF", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "The signal does not change for 10 seconds.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "BCM &lt;WITH LIGHT & RAIN SENSOR>", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "Fail-safe Control By Light & Rain Sensor Malfunction", "title");
si[i++] = gsitm("N512040380000K00ENG.html", "BCM detects the light & rain sensor serial link error and the light & rain sensor malfunction.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "BCM controls the following fail-safe when light & rain sensor has a malfunction.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Front wiper switch AUTO and sensing rain drop: The condition just before the activation of fail-safe is maintained until the front wiper switch is turned OFF.", "ptxt");
si[i++] = gsitm("N512040380000K00ENG.html", "Front wiper switch AUTO and not sensing rain drop: The condition just before the activation of fail-safe (front wiper OFF) is maintained until the front wiper switch is turned OFF.", "ptxt");
