si[i++] = gsitm("N5120402S0000T00ENG.html", "BCM detects the rear wiper motor stop position.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "BCM supplies power to the rear wiper motor after an intermittent from the stop of the rear wiper motor.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "REAR WIPER AUTO STOP OPERATION", "title");
si[i++] = gsitm("N5120402S0000T00ENG.html", "BCM stops supplying power to the rear wiper motor when the rear wiper switch is turned OFF.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "BCM reads a rear wiper stop position signal from the rear wiper motor to detect a rear wiper motor position.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "When the rear wiper motor is at other than the stopping position, BCM continues to supply power to the rear wiper motor until it returns to the stop position.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "BCM stops supplying power to the rear wiper motor when the ignition switch is turned OFF.", "ptxt");
