si[i++] = gsitm("N5120402S0000T00ENG.html", "IPDM E/R turns ON/OFF the rear washer pump relay according to the rear washer pump request signal. IPDM E/R provides the power supply to operate the front and rear washer pump.", "ptxt");
si[i++] = gsitm("N5120402S0000T00ENG.html", "REAR WIPER OPERATION LINKED WITH REVERSE", "title");
