si[i++] = gsitm("N512040110000M00ENG.html", "Description", "title");
si[i++] = gsitm("N512040110000M00ENG.html", "FRONT WIPER MOTOR PROTECTION FUNCTION", "title");
si[i++] = gsitm("N512040110000M00ENG.html", "IPDM E/R may stop the front wiper to protect the front wiper motor if any obstruction (operation resistance) such as a large amount of snow is detected during the front wiper operation.", "ptxt");
si[i++] = gsitm("N512040110000M00ENG.html", "At that time turn OFF the front wiper and remove the foreign object. Then reactivate the front wiper. The wiper will operate normally.", "ptxt");
si[i++] = gsitm("N512040110000M00ENG.html", "REAR WIPER MOTOR PROTECTION FUNCTION", "title");
si[i++] = gsitm("N512040110000M00ENG.html", "BCM may stop rear wiper to protect the rear wiper motor when the rear wiper is stopped for 5 seconds or more due to a snowfall.", "ptxt");
si[i++] = gsitm("N512040110000M00ENG.html", "Rear wiper operates normally 1 minute after the obstacles are removed with rear wiper OFF.", "ptxt");
