si[i++] = gsitm("N5122301T0000200ENG.html", "FRONT WASHER FLUID EJECTION CHECK", "title");
si[i++] = gsitm("N5122301T0000200ENG.html", "Adjustment of the jet type washer nozzle injection position", "title");
si[i++] = gsitm("N5122301T0000200ENG.html", "If there is any foreign material clogged in the washer nozzle injection port, use a pin thinner than the washer nozzle diameter (0.7 mm) and remove the foreign materials.", "ptxt");
si[i++] = gsitm("N5122301T0000200ENG.html", "Check whether washer fluid is sprayed as shown.", "ptxt");
si[i++] = gsitm("N5122301T0000200ENG.html", "Be careful not to break a pin inside the washer nozzle when you adjust it.", "ptxt");
si[i++] = gsitm("N5122301T0000200ENG.html", "If the spray pattern shown is not satisfied, use a pin [thinner than 0.7 mm in diameter] to adjust the washer nozzle.", "ptxt");
si[i++] = gsitm("N5122301T0000200ENG.html", "The injection positions of the centre three of five injection ports of each nozzle cannot be adjusted.", "ptxt");
si[i++] = gsitm("N5122301N0000200ENG.html", "LIGHT AND RAIN SENSOR INSPECTION", "title");
si[i++] = gsitm("N5122301N0000200ENG.html", "Under clear weather (windshield glass is dry), turn the ignition switch to \"ON\" position and wiper switch to \"AUTO\" position. Check that the wiper works when applying water to the upper part of the windshield glass where the light and rain sensor is installed. If there is a malfunction, perform the troubleshooting.", "ptxt");
