si[i++] = gsitm("N5120501B0008I00ENG.html", "Replace A/C switch assembly (rear window defogger switch). Refer to .", "ptxt");
si[i++] = gsitm("N5120501B0008I00ENG.html", "Start engine.", "ptxt");
si[i++] = gsitm("N5120501B0008I00ENG.html", "Operate rear window defogger switch and check the operating condition.", "ptxt");
