si[i++] = gsitm("N5120501B0008I00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5120501B0008I00ENG.html", "REPLACE A/C AMP.", "title");
si[i++] = gsitm("N5120501B0008I00ENG.html", "Replace A/C amp. Refer to  (with auto A/C).", "ptxt");
si[i++] = gsitm("N5120501B0008I00ENG.html", "Replace BCM. Refer to .", "ptxt");
si[i++] = gsitm("N5120500S0004A00ENG.html", "Component Function Check", "title");
si[i++] = gsitm("N5120500S0004A00ENG.html", "CHECK REAR WINDOW DEFOGGER RELAY CONTROL FUNCTION", "title");
si[i++] = gsitm("N5120500S0004A00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5120500S0004A00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5120500S0004A00ENG.html", "Select “BCM” with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5120500S0004A00ENG.html", "Select “Rear defogger” in “Actuator Test” (in \"Special Function\") mode.", "ptxt");
si[i++] = gsitm("N5120500S0004A00ENG.html", "Touch “On”.", "ptxt");
