si[i++] = gsitm("N512050270000G00ENG.html", "Inspection and Repair", "title");
si[i++] = gsitm("N512050270000G00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N512050270000G00ENG.html", "When measuring voltage, wrap tin foil around the top of the negative probe. Then press the foil against the wire with your finger.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Attach probe circuit tester (in Volt range) to middle portion of each filament.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "If a filament is burned out, circuit tester registers 0 or battery voltage.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "To locate burned out point, move probe to left and right along filament. Test needle will swing abruptly when probe passes the point.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "REPAIR", "title");
si[i++] = gsitm("N512050270000G00ENG.html", "REPAIR EQUIPMENT", "title");
si[i++] = gsitm("N512050270000G00ENG.html", "Conductive silver composition (Dupont No. 4817 or equivalent)", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Ruler 30 cm (11.8 in) long", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Drawing pen", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Heat gun", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Alcohol", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Cloth", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "REPAIRING PROCEDURE", "title");
si[i++] = gsitm("N512050270000G00ENG.html", "Wipe broken heat wire and its surrounding area clean with a cloth dampened in alcohol.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Apply a small amount of conductive silver composition to tip of drawing pen.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Shake silver composition container before use.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Place ruler on glass along broken line. Deposit conductive silver composition on break with drawing pen. Slightly overlap existing heat wire on both sides [preferably 5 mm (0.20 in)] of the break.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "After repair has been completed, check repaired wire for continuity. This check should be conducted 10 minutes after silver composition is deposited.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Do not touch repaired area while test is being conducted.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "Apply a constant stream of hot air directly to the repaired area for approximately 20 minutes with a heat gun. A minimum distance of 3 cm (1.2 in) should be kept between repaired area and hot air outlet.", "ptxt");
si[i++] = gsitm("N512050270000G00ENG.html", "If a heat gun is not available, let the repaired area dry for 24 hours.", "ptxt");
si[i++] = gsitm("N5120504B0000100ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5120504B0000100ENG.html", "For the defogger switch removal and installation procedures, refer to .", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5120603B0000O00ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5120603B0000O00ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5120603B0000O00ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5120602N0000R00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5120602N0000R00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
