si[i++] = gsitm("N514010390000K00ENG.html", "CONSOLE POWER SOCKET", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "Functions Within The System", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "—", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Individual Functions Within The System", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "12 V power can be supplied.", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Specification", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "Rated voltage", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "DC 12 V", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Maximum electric capacity", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "120 W or less (Total)", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Maximum current", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "10 A or less (Total)", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Use the power socket while engine is running to avoid dead battery.", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "To prevent the fuse from blowing, use electrical devices with a rated voltage of DC 12 V, maximum power capacity of 120 W or less, and maximum current of 10 A or less, and do not use power strip.", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Be sure to fully insert plugs of electrical devices.", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "Individual Operation", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "Parts Location", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "The power socket is mounted on switch panel. Refer to .", "ptxt");
si[i++] = gsitm("N514010390000K00ENG.html", "REAR CARGO POWER SOCKET", "title");
si[i++] = gsitm("N514010390000K00ENG.html", "The power socket is mounted on luggage side lower. Refer to .", "ptxt");
