si[i++] = gsitm("N5140103F0000O00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5140103F0000O00ENG.html", "Supply DC 5V from the (USB) port.", "ptxt");
