si[i++] = gsitm("N5140103F0000O00ENG.html", "15 or less (Total)", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "Maximum current", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "(A)", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "3.0 or less (Total)", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "USB Type", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "Type C", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "Use the power socket while engine is running to avoid dead battery.", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "To prevent the fuse from blowing, use mobile devices with a rated voltage of 5 V, maximum power capacity of 15 W or less, and maximum current of 3.0 A or less, and do not use power strip.", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "Be sure to fully insert plugs of mobile devices.", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N5140103F0000O00ENG.html", "USB power socket converts input power (DC 12V) to DC 5 V internally to output.", "ptxt");
si[i++] = gsitm("N5140103F0000O00ENG.html", "PARTS LOCATION", "title");
si[i++] = gsitm("N5140103F0000O00ENG.html", "The USB charge port is mounted on console rear finisher. Refer to .", "ptxt");
