si[i++] = gsitm("N514010300000G00ENG.html", "INTERVIEW FOR MALFUNCTION", "title");
si[i++] = gsitm("N514010300000G00ENG.html", "It is also important to clarify the customer concerns before starting the inspection. Interview the customer about the concerns carefully and understand the symptoms fully.", "ptxt");
si[i++] = gsitm("N514010300000G00ENG.html", "The customers are not professionals. Never assume that \"maybe the customer means···\" or \"maybe the customer mentioned this symptom\".", "ptxt");
