si[i++] = gsitm("N514010450000G00ENG.html", "Using non-Qi-certified smart phones", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "Smartphones not supporting Qi format are unable to charge wirelessly.", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "Using Qi-certified smart phones.", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "When a Qi-certified smart phone starts charging, an orange indicator light flashes. (The indicator light turns off after flashing for 8 seconds.)", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "Confirm if any foreign matters are on the charging pad.", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "If the wireless charger and/or smart phone are/is overheated, leave them/it to cool off.", "ptxt");
si[i++] = gsitm("N514010450000G00ENG.html", "Perform self-diagnosis with M.U.T.-III SE. Perform detected DTC self-diagnosis. Refer to .", "ptxt");
