si[i++] = gsitm("N5140202T0004D00ENG.html", "System Description", "title");
si[i++] = gsitm("N5140202T0004D00ENG.html", "OUTLINE", "title");
si[i++] = gsitm("N5140202T0004D00ENG.html", "BCM (Body Control Module) controls the various electrical components. It inputs the information required to the control from CAN communication and the signal received from each switch and sensor.", "ptxt");
si[i++] = gsitm("N5140202T0004D00ENG.html", "BCM has combination switch reading function for reading the operation status of combination switches (light, turn signal, wiper and washer) in addition to a function for controlling the operation of various electrical components. It also has the signal transmission function as the passed point of signal and the power saving control function that reduces the power consumption with the ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5140202T0004D00ENG.html", "BCM is equipped with the diagnosis function that performs the diagnosis with M.U.T.-III SE and various settings.", "ptxt");
si[i++] = gsitm("N5140202T0004D00ENG.html", "BCM CONTROL FUNCTION LIST", "title");
