si[i++] = gsitm("N5140202T0004D00ENG.html", "MAC (MESSAGE AUTHENTICATION CODE)", "title");
si[i++] = gsitm("N5140202T0004D00ENG.html", "MAC (Message Authentication Code) is a function that prevents unauthorized communication from other than the ECU with MAC function by secure authentication communication. BCM can write a MAC key required for communication between the ECUs and perform MAC diagnosis.", "ptxt");
