si[i++] = gsitm("N5140202T0004E00ENG.html", "COMBINATION SWITCH READING FUNCTION", "title");
si[i++] = gsitm("N5140202T0004E00ENG.html", "Description", "title");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM reads the status of the combination switch at 10 ms intervals normally.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM operates as follows and judges the status of the combination switch.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "It operates the transistor on INPUT side in the following order: OUTPUT 6–> 5 –> 4 –> 3 –> 2 –> 1, and outputs voltage waveform.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "The voltage waveform of OUTPUT corresponding to the formed circuit is input into the interface on INPUT side if any (1 or more) switches are ON.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "It reads this change of the voltage as the status signal of the combination switch.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "Operation Example", "title");
si[i++] = gsitm("N5140202T0004E00ENG.html", "In the following operation example, the combination of the status signals of the combination switch is replaced as follows: INPUT 1 - 6 to “ - ” and OUTPUT 1 - 6 to “ - ”.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "Example 1: When a switch (Turn signal RH) is turned ON", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "The circuit between INPUT 3 () and OUTPUT 5 () is formed when the Turn signal RH is turned ON.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM detects the combination switch status signal “” when the signal of INPUT 3 is input to OUTPUT 5.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM judges that the Turn signal RH is ON when the signal “” is detected.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "Example 2: When some switches (Front fog switch, Turn signal RH) are turned ON", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "The circuits between INPUT 1 () and OUTPUT 5 () and between INPUT 3 () and OUTPUT 5 () are formed when the Front fog switch and Turn signal RH are turned ON.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM detects the combination switch status signal “” when the signals of INPUT 1 and INPUT 3 are input to OUTPUT 5.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM judges that the Front fog switch and Turn signal RH are ON when the signal “” is detected.", "ptxt");
si[i++] = gsitm("N5140202T0004E00ENG.html", "WIPER INTERMITTENT DIAL POSITION (WITH WIPER INTERMITTENT DIAL POSITION)", "title");
si[i++] = gsitm("N5140202T0004E00ENG.html", "BCM judges the wiper intermittent dial 1 - 5 by the status of INT volume 1, 2 and 3 switches.", "ptxt");
