si[i++] = gsitm("N514020120003M00ENG.html", "Description", "title");
si[i++] = gsitm("N514020120003M00ENG.html", "When replacing the BCM, always replace it with a new one. The functions controlled by the BCM does not operate properly in case of reuse of the BCM from another vehicle.", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "When before pairing of BCM and Keyless operation key unit, always writing the BCM configuration. Or not doing so, BCM control function does not operate normally.", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Perform the following operations when replacing BCM. For details, refer to .", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N514020120003M00ENG.html", "When after replacing BCM, the following items must be performed. Or not doing so, BCM control function does not operate normally.", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Writing vehicle specification", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Pairing of BCM and Keyless operation key unit", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Register of vehicle identification number", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Writing MAC key", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Tire pressure sensor ID registration (if equipped)", "ptxt");
si[i++] = gsitm("N514020120003M00ENG.html", "Factory Mode OFF", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "REPLACE BCM", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "Replace BCM. Refer to .", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "Perform configuration (BCM). Refer to .", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "PAIRING OF BCM AND KEYLESS OPERATION KEY UNIT", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "When before pairing of BCM and Keyless operation key unit, always writing the BCM configuration. Or not doing so, BCM control function does not operate normally.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Perform the pairing of BCM and Keyless operation key unit. Press UNLOCK button of Keyless operation key.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "REGISTER OF VEHICLE IDENTIFICATION NUMBER", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Select “VIN REGISTRATION” of BCM (BCM) work support item.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Refer to M.U.T.-III SE and follow the on-screen instructions.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 5", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "WRITING MAC KEY", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "When replacing BCM in relation with ECM replacement, replace ECM before writing MAC KEY. Refer to Description.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Perform MAC key writing. Refer to .", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "TIRE PRESSURE SENSOR ID REGISTRATION (IF EQUIPPED)", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "Perform the initialization and registration of tire pressure sensor ID. Refer to .", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N514020320003S00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"BCM\".", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N514020320003S00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "Description", "title");
si[i++] = gsitm("N514020120003N00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the BCM.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the BCM.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "The configuration no need to “save” configuration data from the BCM. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N514020120003N00ENG.html", "Never perform “Configuration” except for new BCM.", "ptxt");
si[i++] = gsitm("N514020320003T00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N514020320003T00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N514020320003T00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N514020320003T00ENG.html", "Perform writing vehicle specification to BCM following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N514020320003T00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N514020320003T00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N514020320003T00ENG.html", "WORK END", "ptxt");
