si[i++] = gsitm("N5140202R0000Z00ENG.html", "Symptom Table", "title");
si[i++] = gsitm("N5140202R0000Z00ENG.html", "Perform “Data List” of M.U.T.-III SE to check for any malfunctioning item.", "ptxt");
si[i++] = gsitm("N5140202R0000Z00ENG.html", "Check that the data monitor display switches in conjunction with the combination switch operation.", "ptxt");
si[i++] = gsitm("N5140202R0000Z00ENG.html", "If there is a switch whose display does not change, specify the applicable combination switch circuit (INPUT 1 - 6 and OUTPUT 1 - 5) using the combination switch circuit confirmation table for the circuit used for that switch.", "ptxt");
si[i++] = gsitm("N5140202R0000Z00ENG.html", "Since combination switch circuit is share with multiple switches, if the switches used other than the defective switch are normal, the combination switch circuit can be determined to be normal.", "ptxt");
si[i++] = gsitm("N5140202R0000Z00ENG.html", "Example: If the circuit used for the switch corresponds to INPUT 1 and OUTPUT 2 of the combination switch circuit, but the other switches that use the INPUT 1 circuit are normal, it is determined that the INPUT 1 circuit is normal and inspection OUTPUT 2 circuit. If other switches that use OUTPUT 2 circuit are normal, the combination switch circuit (INPUT 1 and OUTPUT 2) is determined to be normal, and it can be determined that the combination switch is defective.", "ptxt");
