si[i++] = gsitm("N514020120003P00ENG.html", "Description", "title");
si[i++] = gsitm("N514020120003P00ENG.html", "SHIPPING MODE", "title");
si[i++] = gsitm("N514020120003P00ENG.html", "Shipping mode inhibits battery power consumption during transportation or storage of the vehicle. Vehicle is set to shipping mode before being shipped from the factory.", "ptxt");
si[i++] = gsitm("N514020120003P00ENG.html", "When ignition switch is OFF, BCM operates shipping mode.", "ptxt");
si[i++] = gsitm("N514020120003P00ENG.html", "For shipping mode cancel operation, refer to .", "ptxt");
si[i++] = gsitm("N514020120003P00ENG.html", "Do not cancel shipping mode during storage of the vehicle. Always cancel shipping mode before delivery of the vehicle to customer.", "ptxt");
si[i++] = gsitm("N5140204R0001V00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5140204R0001V00ENG.html", "When replacing the BCM, always replace it with a new one. The functions controlled by the BCM does not operate properly in case of reuse of the BCM from another vehicle.", "ptxt");
si[i++] = gsitm("N5140204R0001V00ENG.html", "Be sure to perform the following items must be performed when replacing BCM.", "BeSureToPerformTheFollowingSystemsS-75A75CD2");
si[i++] = gsitm("N5140204R0001V00ENG.html", "Writing vehicle specification (Refer to .)", "ptxt");
