si[i++] = gsitm("N5140204R0001W00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N5140204R0001W00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Remove steering angle sensor. Refer to .", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Disconnect harness connector from combination switch.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Remove the combination switch  mounting screw .", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Pull out the combination switch  by moving it alternately on the right and left side.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Never deformation and damage the pawls.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", ": Pawl", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Never reuse combination switch. Always replace it with a new one when it is removed.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Visually check the pawls for deformation and damage during installation. Replace with new ones if necessary.", "ptxt");
si[i++] = gsitm("N5140204R0001W00ENG.html", "Insert the combination switch so that the protrusion  of the combination switch  and the cut-out  of the steering column  match together.", "ptxt");
si[i++] = gsitm("N5140204R0002400ENG.html", "Removal and Installation", "title");
