si[i++] = gsitm("N5140304R0000J00ENG.html", "Precautions for Trouble Diagnosis", "title");
si[i++] = gsitm("N5140304R0000J00ENG.html", "Never apply 7.0 V or more to the measurement terminal.", "ptxt");
si[i++] = gsitm("N5140304R0000J00ENG.html", "Use a tester with open terminal voltage of 7.0 V or less.", "ptxt");
si[i++] = gsitm("N5140304R0000J00ENG.html", "Turn the ignition switch OFF and disconnect the battery cable from the negative terminal when checking the harness.", "ptxt");
si[i++] = gsitm("N5140304S0000J00ENG.html", "Precautions for Harness Repair", "title");
si[i++] = gsitm("N5140304S0000J00ENG.html", "Solder the repaired area and wrap tape around the soldered area.", "ptxt");
si[i++] = gsitm("N5140304S0000J00ENG.html", "A fray of twisted lines must be within 110 mm (4.33 in).", "ptxt");
si[i++] = gsitm("N5140304S0000J00ENG.html", "Bypass connection is never allowed at the repaired area.", "ptxt");
si[i++] = gsitm("N5140304S0000J00ENG.html", "Bypass connection may cause CAN communication error. The spliced wire becomes separated and the characteristics of twisted line are lost.", "ptxt");
si[i++] = gsitm("N5140304S0000J00ENG.html", "Replace the applicable harness as an assembly if error is detected on the shield lines of CAN communication line.", "ptxt");
si[i++] = gsitm("N5140304B0000S00ENG.html", "System Description", "title");
si[i++] = gsitm("N5140304B0000S00ENG.html", "CAN communication is a multiplex communication system. This enables the system to transmit and receive large quantities of data at high speed by connecting control units with two communication lines (CAN-H and CAN-L).", "ptxt");
si[i++] = gsitm("N5140304B0000S00ENG.html", "Control units on the CAN network transmit signals using the CAN communication control circuit. They receive only necessary signals from other control units to operate various functions.", "ptxt");
si[i++] = gsitm("N5140304B0000S00ENG.html", "CAN communication lines adopt twisted-pair line style (two lines twisted) for noise immunity.", "ptxt");
si[i++] = gsitm("N5140304V0000J00ENG.html", "System Diagram", "title");
si[i++] = gsitm("N5140304V0000J00ENG.html", "Each control unit passes an electric current to the termination circuits when transmitting CAN communication signal. The termination circuits produce an electrical potential difference between CAN-H and CAN-L. CAN communication system transmits and receives CAN communication signals by the potential difference.", "ptxt");
si[i++] = gsitm("N5140304V0000J00ENG.html", "Component", "ptxt");
