si[i++] = gsitm("N5140304W0000J00ENG.html", "It converts digital signal into CAN communication signal, and CAN communication signal into digital signal.", "ptxt");
si[i++] = gsitm("N5140304W0000J00ENG.html", "Noise filter", "ptxt");
si[i++] = gsitm("N5140304W0000J00ENG.html", "It eliminates noise of CAN communication signal.", "ptxt");
si[i++] = gsitm("N5140304W0000J00ENG.html", "Termination circuit*", "ptxt");
