si[i++] = gsitm("N5140304W0000J00ENG.html", "*: These are the only control units wired with both ends of CAN communication system.", "ptxt");
si[i++] = gsitm("N5140301T0000A00ENG.html", "Description", "title");
si[i++] = gsitm("N5140301T0000A00ENG.html", "“Diag on CAN” is a diagnosis using CAN communication instead of previous DDL1 and DDL2 communication lines, between control units and diagnosis unit.", "ptxt");
