si[i++] = gsitm("N5140304Z0000A00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5140304Z0000A00ENG.html", "Example: Data link connector branch line open circuit", "title");
si[i++] = gsitm("N5140304Z0000A00ENG.html", "When data link connector branch line is open, transmission and reception of CAN communication signals are not affected. Therefore, no symptoms occur. However, be sure to repair malfunctioning circuit.", "ptxt");
si[i++] = gsitm("N5140304Z0000A00ENG.html", "The model (all units on CAN communication system are Diag on CAN) cannot perform CAN diagnosis with M.U.T.-III SE if the following error occurs. The error is judged by the symptom.", "ptxt");
