si[i++] = gsitm("N5140304Z0000A00ENG.html", "The headlamps (Lo) turn ON.", "ptxt");
si[i++] = gsitm("N5140304Z0000A00ENG.html", "The cooling fan continues to rotate.", "ptxt");
