si[i++] = gsitm("N514030510000F00ENG.html", "Self-Diagnosis", "title");
si[i++] = gsitm("N514030510000F00ENG.html", "If communication signals cannot be transmitted or received among units communicating via CAN communication line, CAN communication-related DTC is displayed on the M.U.T.-III SE \"Self-diagnosis\" screen.", "ptxt");
si[i++] = gsitm("N514030510000F00ENG.html", "The following table shows examples of CAN communication-related DTC. For other DTC, refer to the applicable sections.", "ptxt");
