si[i++] = gsitm("N5140304F0000I00ENG.html", "When: Date, Frequency", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Where: Road condition, Place", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "In what condition: Driving condition/environment", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Result: Symptom", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Notes for checking error symptoms:", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Check normal units as well as error symptoms.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Example: Circuit between ECM and the combination meter is judged normal if the customer indicates tachometer functions normally.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "When a CAN communication system error is present, multiple control units may malfunction or go into fail-safe mode.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Indication of the combination meter is important to detect the root cause because it is the most obvious to the customer, and it performs CAN communication with many units.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "INSPECTION OF VEHICLE CONDITION", "title");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Check whether the symptom is reproduced or not.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Do not turn the ignition switch OFF or disconnect the 12V battery cable while reproducing the error. The error may temporarily correct itself, making it difficult to determine the root cause.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CHECK OF CAN SYSTEM TYPE (HOW TO USE CAN SYSTEM TYPE SPECIFICATION CHART)", "title");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Determine CAN system type based on vehicle equipment.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "This chart is used if M.U.T.-III SE does not automatically recognize CAN system type.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "There are two styles for CAN system type specification charts. Depending on the number of available system types, either style A or style B may be used.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CAN System Type Specification Chart (Style A)", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CAN system type is easily checked with the vehicle equipment identification information shown in the chart.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CAN System Type Specification Chart (Style B)", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CREATE INTERVIEW SHEET", "title");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Fill out the symptom described by the customer, vehicle condition, and CAN system type on the interview sheet.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Interview Sheet (Example)", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "DETECT THE ROOT CAUSE", "title");
si[i++] = gsitm("N5140304F0000I00ENG.html", "CAN diagnosis function of M.U.T.-III SE detects a root cause. Refer to EXPLANATION ABOUT THE M.U.T.-IIISE CAN BUS DIAGNOSTICS.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "REPAIR OR REPLACE MALFUNCTIONING PART", "title");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Repair or replace malfunctioning parts identified by CAN diagnosis function of M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Vehicle CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "ITS CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Chassis CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Refer to Chassis Communication Circuit.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Drivetrain CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "IT CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Engine CAN communication circuit", "result");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Refer to Engine CAN Communication Circuit.", "ptxt");
si[i++] = gsitm("N5140304F0000I00ENG.html", "Diagnostic CAN communication circuit", "result");
si[i++] = gsitm("N5140308V0000J00ENG.html", "EXPLANATION ABOUT THE M.U.T.-IIISE CAN BUS DIAGNOSTICS", "title");
si[i++] = gsitm("N5140308V0000J00ENG.html", "The CAN bus is diagnosed by using \"Read all DTCs and FFD\" function on the M.U.T.-IIISE. \"Read all DTCs and FFD\" automatically reads the diagnosis code from all the ECUs selected in the system list, and displays the diagnostic results in the result field on the left side of the screen and the status of the diagnosis code on the right side of the screen as the respective results. In the CAN bus diagnostics using \"Read all DTCs and FFD\" of M.U.T.-IIISE, it is judged whether there is an abnormality in the CAN bus line based on the diagnostic results displayed in the result field on the left side of the screen.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Screen image of M.U.T.-IIISE (Read all DTCs and FFD)", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Result field (Left side of the screen)", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Action", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "\"OK\" or \"–\" is displayed for all the systems.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Perform normal failure phenomenon diagnosis.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "\"TC\" is displayed for one or more systems and \"NC\" is not displayed at all.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "After reading the diagnosis code, pinpoint the trouble spot according to the diagnosis code or perform normal failure phenomenon diagnosis.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "\"NC\" is displayed for one or more systems.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Write down all the systems for which \"NC\" is displayed, and proceed to CAN Bus Diagnostics Table.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "When \"NC\" is displayed, you can determine which communication bus malfunctions by checking the system diagram. (For the system diagram, refer to LAN SYSTEM – CAN – SYSTEM DESCRIPTION – SYSTEM – CAN COMMUNICATION SYSTEM – System Description .)", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "CAN BUS LINE DIAGNOSTIC FLOW", "title");
si[i++] = gsitm("N5140308V0000J00ENG.html", "CAN BUS DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Connect the M.U.T.-IIISE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Start the M.U.T.-IIISE system and turn the ignition switch to the \"ON\".", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "For details on how to use the M.U.T.-IIISE, refer to the \"M.U.T.-IIISE User’s Manual.\"", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "On the \"System Select\" screen, select \"8ch CAN GATEWAY\" in the system list and then press the check icon.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "If the function selection screen is displayed, go back to \"System Select\" screen. If the communication error window is displayed, CAN-C (Diag) bus line has a malfunction.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Press the \"ALL DTC\" icon on the \"System Selection\" screen.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "You cannot press the \"ALL DTC\" icon until all wearing options are selected.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Select \"Read all DTCs and FFD\" on the next screen.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "On the \"Read all DTCs and FFD\" screen, check whether the system installed in the vehicle is correctly selected in the check box on the left side of the screen (remove the check mark if necessary). If there is no problem in the selection, press the \"OK\" button.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "If a check mark is displayed on a system that is not installed, be careful that you may judge incorrectly at the step 7 or later and spend unnecessary time in diagnosis.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "Since the execution confirmation screen of \"Read all DTCs and FFD\" is displayed, press the \"OK\" button to execute it.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "After completing the diagnosis reading of the system selected in the step 6, judge whether there is an abnormality in the CAN bus line according to the contents displayed in the result field on the left side of the screen.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "The results can be printed with all diagnosis functions.", "ptxt");
si[i++] = gsitm("N5140308V0000J00ENG.html", "If \"NC\" is displayed as a result after reading all diagnosis, check whether the system is installed in the vehicle. Remove the check mark on the selection screen if necessary. Then, read all diagnosis again.", "ptxt");
si[i++] = gsitm("N514030580000M00ENG.html", "Caution", "title");
si[i++] = gsitm("N514030580000M00ENG.html", "This section describes information peculiar to a vehicle and inspection procedures.", "ptxt");
si[i++] = gsitm("N514030580000M00ENG.html", "For trouble diagnosis procedure, refer to .", "ptxt");
