si[i++] = gsitm("N514030590000R00ENG.html", "Unit name abbreviations in M.U.T.-III SE CAN diagnosis and in this section are as per the following list.", "ptxt");
si[i++] = gsitm("N514030590000R00ENG.html", "*: The abbreviations marked with * are the systems which are not displayed on the M.U.T.-III SE CAN diagnosis.", "ptxt");
