si[i++] = gsitm("N5140304B0002Y00ENG.html", "CAN Communication Signal Generation", "title");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Termination circuits (resistors) are connected across the CAN communication system. When transmitting a CAN communication signal, each control unit passes a current to the CAN-H line and the current returns to the CAN-L line.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The current flows separately into the termination circuits connected across the CAN communication system and the termination circuits drop voltage to generate a potential difference between the CAN-H line and the CAN-L line.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "A signal with no current passage is called \"Recessive\" and one with current passage is called \"Dominant\".", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The system produces digital signals for signal communications, by using the potential difference.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The Construction of CAN Communication Signal (Message)", "title");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "No.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Message name", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Description", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "1", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Start of frame (1 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Start of message.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "2", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Arbitration of field (11 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Priorities of message-sending are shown when there is a possibility that multiple messages are sent at the same time.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "3", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Control field (6 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Signal quantity in data field is shown.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "4", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Data field (0-64 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Actual signal is shown.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "5", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "CRC field (16 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The transmitting control unit calculates sending data in advance and writes the calculated value in a message.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The receiving control unit calculates received data and judges that the data reception is normal when the calculated value is the same as the value written in the sent data.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "6", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "ACK field (2 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The completion of normal reception is sent to the transmitting unit.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "7", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "End of frame (7 bit)", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "End of message.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "CAN Communication Line", "title");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The CAN communication line is a twisted pair wire consisting of strands of CAN-H  and CAN-L  and has noise immunity.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The CAN communication system has the characteristics of noise-resistant because this system produces digital signals by using the potential difference between the CAN-H line and the CAN-L line and has the twisted pair wire structure.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Since the CAN-H line and the CAN-L line are always adjacent to each other, the same degree of noise occurs, respectively, when a noise  occurs. Although the noise changes the voltage, the potential difference  between the CAN-H line and the CAN-L line is insensitive to noise. Therefore, noise-resistant signals can be obtained.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "CAN Signal Communications", "title");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Each control unit of the CAN communication system transmits signals through the CAN communication control circuit included in the control unit and receives only necessary signals from each control unit to perform various kinds of control.", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Example: Transmitted signals", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "Example: Received signals", "ptxt");
si[i++] = gsitm("N5140304B0002Y00ENG.html", "The above signal names and signal communications are provided for reference purposes. For CAN communications signals of this vehicle, refer to .", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "CAN Communication Control Circuit", "title");
si[i++] = gsitm("N5140304W0001700ENG.html", "CAN communication control circuit is incorporated into the control unit and transmits/receives CAN communication signals.", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "System description", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "CAN controller", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "It controls CAN communication signal transmission and reception, error detection, etc.", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "Transceiver IC", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "It converts digital signal into CAN communication signal, and CAN communication signal into digital signal.", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "Noise filter", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "It eliminates noise of CAN communication signal.", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "Termination circuit*", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "(Resistance of approx. 120 Ω)", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "Generates a potential difference between CAN-H and CAN-L.", "ptxt");
si[i++] = gsitm("N5140304W0001700ENG.html", "*: These are the only control units wired with both ends of CAN communication system.", "ptxt");
