si[i++] = gsitm("N5140304B0002500ENG.html", "System Description", "title");
si[i++] = gsitm("N5140304B0002500ENG.html", "8CH CAN GATEWAY", "title");
si[i++] = gsitm("N5140304B0002500ENG.html", "System Diagram", "title");
si[i++] = gsitm("N5140304B0002500ENG.html", "The 8CH CAN gateway system communicates between vehicle CAN communication circuits, ITS CAN communication circuits, chassis CAN communication circuits, IT CAN communication circuit, Drivetrain CAN communication circuit, and diagnostic CAN communication circuit.", "ptxt");
si[i++] = gsitm("N5140304B0002500ENG.html", "This system selects and transmits only necessary information.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "M.U.T.-III SE Function", "title");
si[i++] = gsitm("N5140308T0000B00ENG.html", "APPLICATION ITEM", "title");
si[i++] = gsitm("N5140308T0000B00ENG.html", "M.U.T.-III SE performs the following functions via CAN communication with 8CH CAN gateway.", "ptxt");
