si[i++] = gsitm("N5140308T0000B00ENG.html", "Refer to DTC Index.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "When \"Active DTC\" is displayed on \"Self-diagnosis\"", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "The system is presently malfunctioning.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "When \"Stored DTC\" is displayed on \"Self-diagnosis\"", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "System malfunction in the past is detected, but the system is presently normal.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Freeze Frame Data (FFD)", "title");
si[i++] = gsitm("N5140308T0000B00ENG.html", "When DTC is detected, a vehicle state shown below is recorded and displayed on M.U.T.-III SE.", "ptxt");
