si[i++] = gsitm("N5140308T0000B00ENG.html", "Display item", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "ODO/TRIP METER", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "(mile)", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Displays the total mileage when a DTC detected.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "CGW MODE CHANGE", "title");
si[i++] = gsitm("N5140308T0000B00ENG.html", "CGW is protected by security (this state is called \"Restricted Mode\") normally and some diagnostic functions of all systems cannot be completed when CGW is in this mode. In order to enable all the displayed functions, the CGW needs to be set to \"Open Mode\". If the CGW cannot be set to \"Open Mode\" because the internet connection is off-line, etc., the function which is restricted by \"Restricted Mode\" can be partially enabled by setting the CGW to \"Diag Test Mode\".", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Set to \"Open Mode\"", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Refer to “M.U.T.-III SE User\'s Manual”.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Set to \"Diag Test Mode\"", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Turn the ignition switch ON.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Depress accelerator pedal (5/8 or more) two times within 10 seconds.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "When any of the following conditions is satisfied, \"Diag Test Mode\" will be released.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Vehicle speed reaches 7.9 km/h or more.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Perform the following procedure.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Turn the ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5140308T0000B00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
