si[i++] = gsitm("N5140304N0000S00ENG.html", "When replacing 8CH CAN gateway, the following procedure must be performed.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "WORK PROCEDURE", "title");
si[i++] = gsitm("N5140304N0000S00ENG.html", "REPLACE 8CH CAN GATEWAY", "REPLACECANGATEWAY-57E3170B");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Replace 8CH CAN gateway. Refer to .", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "PERFORM 8CH CAN GATEWAY PROGRAMMING", "WRITINGVEHICLESPECIFICATION-57E31BBC");
si[i++] = gsitm("N5140304N0000S00ENG.html", "After the ECU update, the transfer of ECU update result is required.If the transfer of ECU update result fails, be sure to perform \"Data Upload\".For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Perform the 8CH CAN gateway programming. Refer to “M.U.T.-III SE User\'s Manual”.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "12V battery voltage: 10.5 V or more", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "CHASSIS NUMBER (CHASSIS NO.) WRITING", "WRITINGVEHICLESPECIFICATION-57E31BBC");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Select “8ch CAN GATEWAY” in the system selection screen.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Select “Special Function” and then select “Chassis No./VIN Registration”", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Write the chassis number by following the instructions on the screen.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "CHECK ALL ECU SELF-DIAGNOSIS RESULTS", "CHECKALLECUSELF-DIAGNOSISRESULTS-57E32006");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Erase all ECU self-diagnosis results using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Turn the ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Turn the ignition switch ON and wait for 2 seconds or more.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "Check that all ECU self-diagnosis results have no DTC (e.g. U1000 and U1001) of CAN communication.", "ptxt");
si[i++] = gsitm("N5140304N0000S00ENG.html", "GO TO 5.", "ptxt");
