si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET", "title");
si[i++] = gsitm("N514040390000I00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET turns the each lamps ON according to the request from BCM.", "ptxt");
si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET turns the A/C compressor (magnetic clutch) ON according to the request from ECM.", "ptxt");
si[i++] = gsitm("N514040390000I00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET supplies power supply voltage to the each lamps and A/C compressor (magnetic clutch).", "ptxt");
si[i++] = gsitm("N514040390000I00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET, that uses MOS field effect transistor, is adopted for each lamps and A/C compressor (magnetic clutch) control.", "ptxt");
si[i++] = gsitm("N514040390000I00ENG.html", "A MOS field effect transistor is a transistor in which the gate is composed of a metal-oxide-semiconductor (MOS). Field effect transistor is controlled by voltage, while ordinary transistor is controlled by current. Electrode of field effect transistor is called source, drain, or gate, while electrode of ordinary transistor is called emitter, collector, or base.", "ptxt");
si[i++] = gsitm("N514040390000I00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N514040390000I00ENG.html", "Smart FET integrated to IPDM E/R. Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N5140402T0003P00ENG.html", "System Description", "title");
si[i++] = gsitm("N5140402T0003P00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5140402T0003P00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5140402T0003P00ENG.html", "IPDM E/R activates the internal control circuit to perform the relay ON-OFF control according to the input signals from various sensors and the request signals received from control units via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003P00ENG.html", "To prevent to the parts, IPDM E/R integrated relays cannot be removed.", "ptxt");
