si[i++] = gsitm("N5140402T0003S00ENG.html", "Outline", "title");
si[i++] = gsitm("N5140402T0003S00ENG.html", "IPDM E/R incorporates a power consumption control function that reduces the power consumption according to the vehicle status.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "IPDM E/R changes its status (control mode) with the sleep wake up signal received from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Normal mode (wake-up)", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "CAN communication is normally performed with other control units.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Individual unit control by IPDM E/R is normally performed.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Low power consumption mode (sleep)", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Low power consumption control is active.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "CAN transmission is stopped.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Sleep Mode Activation", "title");
si[i++] = gsitm("N5140402T0003S00ENG.html", "IPDM E/R judges that the sleep-ready conditions are fulfilled when the ignition switch is OFF and none of the conditions below are present. Then it transmits a sleep-ready signal (ready) to BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Outputting signals to actuators", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Output requests are being received from control units via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "IPDM E/R stops CAN communication and enters the low power consumption mode when it receives a sleep wake up signal (sleep) from BCM and the sleep-ready conditions are fulfilled.", "ptxt");
si[i++] = gsitm("N5140402T0003S00ENG.html", "Wake-Up Operation", "title");
si[i++] = gsitm("N5140402T0003S00ENG.html", "IPDM E/R changes from the low power consumption mode to the normal mode when it receives a sleep wake up signal (wake up) from BCM or any of the following conditions is fulfilled. In addition, it transmits a sleep-ready signal (not-ready) to BCM via CAN communication to report the CAN communication start.", "ptxt");
