si[i++] = gsitm("N5140402T0003U00ENG.html", "Stop light switch detects that brake pedal is depressed, and then transmits ON/OFF signal to BCM.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Transmits shift position signal and cranking enable signal to BCM via CAN communication.", "ptxt");
