si[i++] = gsitm("N5140402T0003U00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "BCM controls the each relay, judged from each switch status.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "BCM transmits the ignition ON signal to IPDM E/R via CAN communication, judged from each switch status.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-1", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Controlled by BCM and turns ON/OFF the battery power supply to each parts.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Accessory relay", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-2", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-3", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "IPDM E/R controls the integrated ignition relay, and supplies voltage to the load according to the request from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5140402T0003U00ENG.html", "POWER DISTRIBUTION SYSTEM is the system that BCM controls with the operation of push-button ignition switch and performs the power distribution to each power circuit. This system is used instead of the mechanical power supply changing mechanism with the operation of the conventional key cylinder.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Allocation to the accessory power supply, refer to the auto ACC function. Refer to .", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Push-button ignition switch can be operated when Keyless operation key is in the following condition.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Keyless operation key is in the detection area of the inside key antenna.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Keyless operation key backside is contacted to push-button ignition switch.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Push-button ignition switch operation is input to Keyless operation key unit as a signal. Keyless operation key unit transmits push-button ignition switch status signal to BCM via CAN communication. BCM changes the ignition switch position according to the status and operates the following relays to supply power to each power circuit.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay (built-in IPDM E/R)", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-1 [installed in fuse block (J/B)]", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-2 [installed in fuse block (J/B)]", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-3 (installed in relay holder)", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition relay-3 turns ON only when the engine is running.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "[installed in fuse block (J/B)]", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "IGNITION BATTERY SAVER SYSTEM", "title");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition battery saver system is a system in which the BCM automatically shuts off the power supply (ignition switch position ON -> OFF) to protect the battery.", "WhenAllTheFollowingConditionsAreMet-2C11367D");
si[i++] = gsitm("N5140402T0003U00ENG.html", "BCM activates ignition battery saver system 10 minutes after ignition battery saver timer function operating conditions are met.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Operating Condition of Ignition Battery Saver Timer Function", "title");
si[i++] = gsitm("N5140402T0003U00ENG.html", "When all the following conditions are met for a 10 minutes, the battery saver system will cut off the power supply (ignition switch position ON -> OFF) to prevent battery discharge.", "WhenAllTheFollowingConditionsAreMet-2C1299EE");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition switch is in the ON position", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Engine stopped", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Cancel Condition of Ignition Battery Saver Timer Function", "title");
si[i++] = gsitm("N5140402T0003U00ENG.html", "If any of the following conditions are met the battery saver timer function is canceled.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition switch is not in the ON position", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Engine running", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "M.U.T.-III SE is connected", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "Ignition battery saver timer function will return 1 minute or more, after closing M.U.T.-III SE or removing VI from the vehicle.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "When ignition battery saver is disabling, the operation of push-button ignition switch less than 2 seconds is not accepted.", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "To resume ignition battery saver system, press and hold the push-button ignition switch continuously for 3 seconds or more with the brake pedal is not depressed. (Ignition switch turns ON -> OFF)", "ptxt");
si[i++] = gsitm("N5140402T0003U00ENG.html", "IGNITION SWITCH POSITION CHANGE TABLE BY PUSH-BUTTON IGNITION SWITCH OPERATION", "title");
