si[i++] = gsitm("N5140402T0003V00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "BCM operates the auto ACC function based on each signal state.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Accessory relay", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Controlled by BCM and turns ON/OFF the battery power supply to each parts.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Audio/Navigation", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Auto ACC status signal receives from BCM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "In conventional vehicles, power is supplied to the accessories of the vehicle after the ignition switch is turned to the ACC position.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "The AUTO ACC function is a function that bypasses the ignition switch ACC position and automatically distributes the accessory power supply to each switch and unit by door unlock operation, etc. using the Keyless operation key.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "OPERATION FLOW", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Ignition switch ON state", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "In this status the ignition switch is operated and turned ON.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Audio/Navigation use possible state", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "In this status the audio/navigation, and each switch and unit that is activated by the accessory power supply can be operated.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "When 10 minutes pass after conditions are satisfied while and audio/navigation are not operated, audio/navigation turn OFF.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Audio/Navigation preparation state", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "In this status audio/navigation are stopped, but the switches and units other than those for audio/navigation that can operate by using the accessory power supply are available until the accessory power supply turns OFF.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "When audio/navigation is operated within 1 minutes after conditions are satisfied, operation time is extended for 10 minutes. Audio/navigation can be operated for a maximum of 30 minutes after the status is satisfied.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Function OFF state", "title");
si[i++] = gsitm("N5140402T0003V00ENG.html", "In this status the AUTO ACC function stops and power to the accessories is not supplied.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "No.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Function status", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting condition", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Accessory power supply", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Function OFF state” to \"Ignition switch ON state\"", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Any of the following conditions is satisfied.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Turn the ignition switch ON from OFF.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate push-button ignition switch and start the engine.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "OFF –> ON", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation preparation state” to “Ignition switch ON state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "ON", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation use possible state” to “Ignition switch ON state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Function OFF state” to “Audio/Navigation preparation state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Each door is opened or closed.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Close all doors, and lock all doors with the Keyless operation key or door request switch.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate either the door request switch or the unlock button of the Keyless operation key to unlock the door.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate lighting switch and turn ON the tail light.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Software update of the AV control unit.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Map data update.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation preparation state” to “Audio/Navigation use possible state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate audio/navigation.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Ignition switch ON state” to “Audio/Navigation use possible state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Turn the ignition switch OFF from ON while driver door is close with vehicle speed is less than 3 km/h.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Ignition switch ON state” to “Audio/Navigation preparation state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Turn the ignition switch OFF from ON while driver door is open with vehicle speed is less than 3 km/h.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation use possible state” to “Audio/Navigation preparation state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Driver door is opened.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "10 minutes pass from “Audio/Navigation use possible state”.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation use possible state” to “Function OFF state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "ON –> OFF", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation preparation state” to “Function OFF state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "1 minutes or 10 minutes pass from “Audio/Navigation preparation state”.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Audio/Navigation use possible state” time extension (1 minute)", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate power window main switch and open/close the front power window LH.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Ignition switch ON state” (in status of emergency stop) to “Audio/Navigation use possible state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Vehicle speed is less than 3 km/h and except driver door is opened.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Ignition switch ON state” (in status of emergency stop) to “Audio/Navigation preparation state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Vehicle speed is less than 3 km/h and driver door is opened.", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Shifting from “Function OFF state” to “Audio/Navigation use possible state”", "ptxt");
si[i++] = gsitm("N5140402T0003V00ENG.html", "Operate telematics system.", "ptxt");
si[i++] = gsitm("N514030300000V00ENG.html", "List of ECU Reference", "title");
si[i++] = gsitm("N514030300000V00ENG.html", "ECU", "ptxt");
