si[i++] = gsitm("N51404017000JO00ENG.html", "Check that vehicle is under the condition shown in “Conditions of vehicle” before starting diagnosis, and check each symptom.", "ptxt");
si[i++] = gsitm("N51404017000JO00ENG.html", "The engine start function, door lock function, power distribution system, and NATS-IVIS/NVIS in the Keyless operation key system are closely related to each other regarding control. The vehicle security function can operate only when the door lock and power distribution system are operating normally.", "ptxt");
si[i++] = gsitm("N51404017000JO00ENG.html", "Conditions of Vehicle (Operating Conditions)", "title");
si[i++] = gsitm("N51404017000JO00ENG.html", "“ENGINE START BY I-KEY” in “Setting change” (in \"Special Function\") mode of \"HANDS FREE MODULE\" is \"On\" when setting on M.U.T.-III SE.", "ptxt");
