si[i++] = gsitm("N5140500V0000D00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5140500V0000D00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5140500V0000D00ENG.html", "Refer to", "ptxt");
si[i++] = gsitm("N5140500V0000D00ENG.html", "12V battery current sensor", "ptxt");
si[i++] = gsitm("N5140500V0000D00ENG.html", "Refer to 12V Battery Current Sensor.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "GENERATOR", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Generator provides DC voltage to operate vehicle\'s electrical system and to keep 12V battery charged.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Generator has control module (IC regulator).", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "The output voltage of generator is controlled by control module.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Control module transmits/receives signal via LIN communication.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Control module controls power generation voltage by target power generation voltage based on received target charge voltage signal.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "When there is no power generation command signal, generator performs the normal power generation according to characteristic of control module.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Control module in generator controls power generation voltage by generator voltage request signal at normal running, and generator has self-diagnosis function.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Power Generation Control", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "ECM calculates target power generation voltage according to 12V battery condition and sends calculated value as power generation command value signal to control module in generator. When generator receives its signal, control module controls power generation voltage by its signal.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Self-Diagnosis Function", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Generator transmits diagnosis result to ECM via LIN communication when detecting any malfunction. When it receives diagnosis result, ECM detects DTC and turns on charge warning light.", "ptxt");
si[i++] = gsitm("N5140503B0000D00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5140503B0000D00ENG.html", "Generator is installed to front side of engine. Refer to .", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V BATTERY CURRENT SENSOR", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V battery current sensor transmits battery current sensor signal via LIN communication to IPDM E/R.12V battery current sensor and 12V battery temperature sensor measure charging/discharging current of 12V battery and temperature around 12V battery, and sends its signal to IPDM E/R. IPDM E/R controls power generation by sending power generation command value signal based on following signals to generator.", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "As a result, engine load can be reduced.", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V Battery Current Sensor", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V battery current sensor measures charging/discharging current of 12V battery and sends its signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V Battery Temperature Sensor", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V battery temperature sensor is integrated in 12V battery current sensor. sensor measures temperature around 12V battery.", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V battery temperature sensor measures temperature around 12V battery using IC temperature sensor.", "ptxt");
si[i++] = gsitm("N5140503C0000E00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N5140503C0000E00ENG.html", "12V battery current sensor is installed to 12V battery negative cable. Refer to .", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "System Description", "title");
si[i++] = gsitm("N5140502T0000D00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Component", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Generator", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Refer to Generator.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "ECM transmits the received generator voltage request signal to generator via LIN communication.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Refer to  for detailed installation location.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "IPDM E/R sends the generator voltage request signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Refer to for detailed installation location.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "12V battery current sensor", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "(With 12V battery temperature sensor)", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Refer to 12V Battery Current Sensor.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5140502T0000D00ENG.html", "12V battery current sensor (With 12V battery temperature sensor) measures the charging/discharging current of the 12V battery and the temperature around the 12V battery via LIN communication to IPDM E/R.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "IPDM E/R judges 12V battery condition according to the charging/discharging current of the 12V battery and the temperature around the 12V battery.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "IPDM E/R calculates the target power generation voltage according to the 12V battery condition and sends the calculated value as generator voltage request signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "ECM transmits generator voltage request signal to generator via LIN communication.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Control module inside generator controls the power generation voltage based on the received generator voltage request signal.", "ptxt");
si[i++] = gsitm("N5140502T0000D00ENG.html", "Generator includes a self-diagnosis function and transmits the diagnosis result to ECM via LIN communication when detecting any malfunction.", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "Warning Lamps/Indicator Lamps", "title");
si[i++] = gsitm("N5140503F0000C00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "Design", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "Charge warning light", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "For layout, refer to .", "ptxt");
si[i++] = gsitm("N5140503F0000C00ENG.html", "For function, refer to 12V Battery Charge Warning Light(7 INCH INFORMATION DISPLAY) or 12V Battery Charge Warning Light(FULL TFT METER).", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "List of ECU Reference", "title");
si[i++] = gsitm("N514030300000W00ENG.html", "ECU", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "Reference", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "Values On The Diagnosis Tool", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "Physical Values", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "Fail-safe", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "Test Value and Test Limit", "ptxt");
si[i++] = gsitm("N514030300000W00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Work Flow", "title");
si[i++] = gsitm("N514050300000200ENG.html", "Generator Function Check", "title");
si[i++] = gsitm("N514050300000200ENG.html", "When the battery is dead, make sure to follow the battery failure judgment flow chart to prevent misjudgment of the cause of failure (Refer to Electrical & Power Control - Power Supply, Ground & Circuit Elements - Basic Inspection - Battery Inspection - ).", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Check the charge level with the battery test, and charge the battery up to the standard value if necessary. If necessary, the inspection may be performed using a new battery.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "This test is performed to determine whether the generator is functioning properly.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Disconnect the battery (-) terminal.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Set a clamp-type DC test ammeter to the generator \"B\" terminal output wire.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Disconnecting the generator output wire and connecting the ammeter may not thoroughly diagnose an generator output line resistance increase problem because of an insufficient connection between terminal \"B\" and the output wire.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Connect a digital-type voltmeter between the generator \"B\" terminal and the battery (+) terminal. [Connect the (+) lead of the voltmeter to the \"B\" terminal and connect the (-) lead of the voltmeter to the battery (+) cable].", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Connect the battery (-) terminal again (Refer to Electrical & Power Control - Power Supply, Ground & Circuit Elements - Removal and Installation - 12V Battery Current Sensor - ).", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Connect the M.U.T.-III SE to the data link connector (Refer to General Information – General – Basic Inspection – M.U.T.-III SE Checking System – ).", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Leave the hood open.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Select the data list item No. 80 \"Engine speed\" and No. 1 \"Coolant temperature sensor\" using the M.U.T.-III SE. Then check the engine speed and engine coolant temperature. (Refer to Engine - Engine Control System - PR25DD - System Description - Diagnosis System (ECM) – .)", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "With the engine running at 2,500 r/min, turn the headlights and other lights on and off to adjust the generator load so that the value displayed on the ammeter is slightly above 30 A.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Adjust the engine speed by gradually decreasing it until the value displayed on the ammeter is 30 A. Take a reading of the value displayed on the voltmeter at this time.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Limit: Maximum 0.3 V", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "When the generator output is high and the value displayed on the ammeter does not decrease until 30 A, set the value to 40 A. Read the value displayed on the voltmeter at this time. When the value range is 40 A, the limit is maximum 0.4 V.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "If the value displayed on the voltmeter is above the limit value, there is probably a malfunction in the generator output wire, so check the wiring between the generator \"B\" terminal and the battery (+) terminal (including fusible link).", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "If a terminal is not sufficiently tight or if the harness has become discolored due to overheating, repair and then test again.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "After the test, run the engine at idle.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Set the headlight to high beam, air conditioner air volume and windshield wiper, air conditioner switch, audio, fog light, defogger ON.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "After operating the above electrical loads, increase the engine speed to 2,500 r/min and maintain the engine speed at 2,500 r/min within 30 seconds.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Read the output current value indicated by the ammeter. (Maintain the engine speed at 2,500 r/min.)", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Limit: Minimum 30A", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Maintain the engine speed 2,500 r/min for at least 1 minute. Return the engine speed to idle operation and then turn off all electrical loads activated in Step 16 within 30 seconds.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Ensure that the engine speed is maintained for at least 1 minute, as it may not be correctly determined if the engine speed is maintained for less than 1 minute.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "In the following cases, replace the generator (Refer to Electrical & Power Control - Charging System - Removal and Installation - Generator - PR25DD – ).", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Current reading is below the limit", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Charging warning light in the combination mater illuminates.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Disconnect the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N514050300000200ENG.html", "Disconnect the ammeter and voltmeter.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Inspection Procedure", "title");
si[i++] = gsitm("N5140503K0000B00ENG.html", "CHECK 12V BATTERY TERMINALS CONNECTION", "title");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Check if 12V battery terminals are clean and tight.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Is the inspection result normal?", "question");
si[i++] = gsitm("N5140503K0000B00ENG.html", "YES", "result");
si[i++] = gsitm("N5140503K0000B00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "NO", "result");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Repair 12V battery terminals connection.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "CHECK \"B\" TERMINAL CONNECTION", "title");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Check if \"B\" terminal (generator ground harness) is clean and tight.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Repair \"B\" terminal connection.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "CHECK 12V BATTERY STATUS", "title");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Check 12V battery status. Refer to .", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Replace 12V battery. Refer to .", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "CHECK DRIVE BELT TENSION", "title");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Check drive belt tension. Refer to .", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5140503K0000B00ENG.html", "Repair as needed.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "DTC Description", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "DTC DETECTION LOGIC", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "DTC No.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "M.U.T.-III SE screen items", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "(Trouble diagnosis content)", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "DTC Detection Condition", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "B12A4–81", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Battery current sensor (invalid serial data received)", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Diagnosis condition", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "When ignition switch is ON.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Signal (terminal)", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "LIN (BAT CURRENT SEN)", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Threshold", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "12V battery current sensor and IPDM E/R cannot communicate with LIN communication signal.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Diagnosis delay time", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "2 seconds or more", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "POSSIBLE CAUSE", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "12V battery terminal is not connected", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Harness or connectors", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "12V battery current sensor (With 12V battery temperature sensor)", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "IPDM E/R", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "FAIL-SAFE", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Fix the power generation command value to 14.3 V.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "DTC CONFIRMATION PROCEDURE", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "PERFORM COMPONENT FUNCTION CHECK", "title");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Start engine and wait for 10 seconds or more.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Perform “Self Diagnostic Result” mode of “IPDM E/R” using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5140501D0001A00ENG.html", "Is the inspection result normal?", "question");
