si[i++] = gsitm("N5140503T0000G00ENG.html", "Remove generator mounting bolt (upper).", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Completely loosen generator mounting bolt (lower), and pull it out until bolt head is in contact with side member. And then, remove generator by pulling it forward.", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Generator can be removed together with bolts by pulling it forward and using generator bracket bolt hole cutout.", "ptxt");
