si[i++] = gsitm("N5140503T0000G00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Note the following items, and then install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Temporarily tighten generator bolts in order from the lower side to the upper side, and then tighten them in order from the upper side to the lower side.", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "For generator, the front side (pulley side) surface is the reference surface. Fit the reference surface to generator mounting part, and then tighten bolts.", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Be careful to tighten “B” terminal nut to the specified torque.", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "Install generator, and check tension of belt. Refer to .", "ptxt");
si[i++] = gsitm("N5140503T0000G00ENG.html", "For this model (with 12V battery current sensor models), energy management system that controls power generation voltage of generator has been adopted. Therefore, energy management system operation inspection should be performed after replacing generator, and then make sure that the system operates normally. Refer to .", "par1");
si[i++] = gsitm("N5140503T0000G00ENG.html", "12V Battery current sensor is installed to 12V battery cable at negative terminal.", "par2");
