si[i++] = gsitm("N5140503C0000G00ENG.html", "12V BATTERY CURRENT SENSOR", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "COMPONENT FUNCTION WITHIN SYSTEM", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V battery current sensor transmits battery current sensor signal via LIN communication to IPDM E/R.12V battery current sensor and 12V battery temperature sensor measure charging/discharging current of 12V battery and temperature around 12V battery, and sends its signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N5140503C0000G00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V Battery Current Sensor", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V battery current sensor measures charging/discharging current of 12V battery and sends its signal to IPDM E/R.", "ptxt");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V Battery Temperature Sensor", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V battery temperature sensor is integrated in 12V battery current sensor. sensor measures temperature around 12V battery.", "ptxt");
si[i++] = gsitm("N5140503C0000G00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N5140503C0000G00ENG.html", "12V battery temperature sensor measures temperature around 12V battery using IC temperature sensor.", "ptxt");
