si[i++] = gsitm("N5140502T0000F01ENG.html", "Belt drive starter generator", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "DC-DC converter", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "ECM", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "According to the status of the components related to the 48V system (belt driven starter generator, 48V battery, and DC-DC converter), the ECM instructs the belt driven starter generator to generate power.", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "SYSTEM DESCRIPTION", "title");
si[i++] = gsitm("N5140502T0000F01ENG.html", "12V battery current sensor (With 12V battery temperature sensor) measures the charging/discharging current of the 12V battery and the temperature around the 12V battery via LIN communication to IPDM E/R.", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "IPDM E/R judges 12V battery condition according to the charging/discharging current of the 12V battery and the temperature around the 12V battery.", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "IPDM E/R calculates the target power generation voltage according to the 12V battery condition and sends the calculated value as generator voltage request signal to ECM via CAN communication.", "ptxt");
si[i++] = gsitm("N5140502T0000F01ENG.html", "For 48V MILD HYBRID system control, refer to .", "ptxt");
