si[i++] = gsitm("N5140603E0000A00ENG.html", "12V Battery", "title");
si[i++] = gsitm("N5140603E0000A00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5140603E0000A00ENG.html", "—", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N5140603E0000A00ENG.html", "The 12 V battery is enhanced in recharging, discharging and its lifespan.", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "The 12 V battery supplies electrical power to the electrical equipment of the vehicles.", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "Specification", "title");
si[i++] = gsitm("N5140603E0000A00ENG.html", "Type", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "L3-EFB", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "20 hour rate capacity", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "[V – Ah]", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "12 – 70", "ptxt");
si[i++] = gsitm("N5140603E0000A00ENG.html", "Cold cranking current (For reference value)", "ptxt");
