si[i++] = gsitm("N5140603G0000A00ENG.html", "Standardized Relay", "title");
si[i++] = gsitm("N5140603G0000A00ENG.html", "NORMAL OPEN, NORMAL CLOSED AND MIXED TYPE RELAYS", "title");
si[i++] = gsitm("N5140603G0000A00ENG.html", "Relays can mainly be divided into three types: normal open, normal closed and mixed type relays.", "ptxt");
