si[i++] = gsitm("N5140604B0000200ENG.html", "Diagnosis Troubleshooting Flow", "title");
si[i++] = gsitm("N5140604B0000200ENG.html", "In case of the battery running out, inspections should be carried out according to the following flowchart to prevent misjudgement of the cause of the failure.", "ptxt");
