si[i++] = gsitm("N5140604B0000200ENG.html", "*11: Proceed to .", "ptxt");
si[i++] = gsitm("N514060700000A00ENG.html", "Fluid level check", "title");
si[i++] = gsitm("N514060700000A00ENG.html", "Check that the battery electrolyte level is above the LOWER LEVEL indications. If the battery electrolyte level is below the LOWER LEVEL, replace the battery.", "ptxt");
si[i++] = gsitm("N514060700000A00ENG.html", "If the battery is used with the electrolyte level below the LOWER LEVEL indicator, there is the danger that explosions may occur.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Dark Current Measurement", "title");
si[i++] = gsitm("N5140604C0000200ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Confirm that all electrical components (including electrical components installed by the customer) are inoperative.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "The work shall be performed while maintaining battery continuity, since the loss of power supply from the battery to the vehicle may cause each ECU to reset, making it impossible to detect a temporary increase in dark current, etc.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Doors must not be opened or closed during the operation. (Auto ACC will be activated, making it impossible to measure correctly.) Keep the door, which need to be opened to access to the interior of the vehicle, open during the work.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Set the tester by the following procedures and put it in the measurement state while maintaining battery continuity.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Place the probe (+ side) on the battery harness (- terminal) and fix it firmly with tape or other means so that it will not come off during operation. Secure the probe so that it does not touch the bolt or nut.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Place the probe (- side) on the battery (- terminal) and fix it firmly with tape or other means so that it will not come off during operation. Secure the probe so that it does not touch the bolt or nut.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Disconnect the battery harness (- terminal) from the battery current sensor.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Doors must not be opened or closed during the Step 4 to Step 6 below. (Auto ACC will be activated, making it impossible to measure correctly.)", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If any of the doors is opened and closed, leave the vehicle for at least 12 minutes after opening or closing the door before carrying out the following operations.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Confirm that current is flowing in the tester, and measure the dark current at least 12 minutes after the door has been opened and closed.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Standard value: less than 60 mA", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current is outside the standard value: Measure the dark current again at least 30 minutes after the door is opened or closed. If they still deviate from the standard values, go to step 5.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current is at the standard value: Dark current is normal. Go to step 7.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Check for the installation of non-genuine electrical components.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If non-genuine electrical equipment is installed, remove the non-genuine electrical equipment and measure the dark current again.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current is outside the standard value: If it has not been more than 30 minutes since the door was opened or closed, measure the dark current again after 30 minutes has elapsed. If it still exceeds the standard value, go to step 6.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current is at the standard value: Consult with the customer about measures such as removing non-genuine electrical components, etc., because these components are causing the increase in dark current.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If no non-genuine electrical components are installed: go to step 6.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Identify the system causing the abnormal dark current by the following procedure.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Check the electrical wiring diagram to determine the electrical components (ECU, parts) that are constantly energized when the ignition switch is in the \"LOCK\" (OFF) position.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Disconnect the determined electrical components one by one, starting with the fuse connected the farthest away from the battery, so that the connections can be disconnected in minimum units, and check the change in dark current.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Continue the inspection with the fuses removed, and identify the system causing the large drop in dark current.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Reinstall the fuse of the identified causative system and check whether the dark current changes when the harness of the causative system is shaken.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current changes: Check for a short in the harness of the causative system.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "If the dark current does not change: Check for any abnormality in the electrical components of the causative system, and if any abnormality is found, repair or replace it. If there is no abnormality, replace all the electrical components of the identified causative system.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Complete the dark current measurement with the battery continuity maintained by the following procedures.", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Connect the battery (- terminal). Refer to .", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Disconnect the probe (- side) from the battery (- terminal).", "ptxt");
si[i++] = gsitm("N5140604C0000200ENG.html", "Disconnect the probe (+ side) from the battery harness (- terminal).", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "How to Handle Battery", "title");
si[i++] = gsitm("N5140603W0000A00ENG.html", "If it becomes necessary to start the engine with a booster battery and jumper cables, use a 12-volt booster battery.", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "After connecting battery cables, ensure that they are tightly clamped to battery terminals for good contact.", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "METHODS OF PREVENTING OVER-DISCHARGE", "title");
si[i++] = gsitm("N5140603W0000A00ENG.html", "The following precautions must be taken to prevent over-discharging a battery.", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "The battery surface (particularly its top) should always be kept clean and dry.", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "The terminal connections should be clean and tight.", "ptxt");
si[i++] = gsitm("N5140603W0000A00ENG.html", "When the vehicle is not going to be used over a long period of time, disconnect the battery cable from the negative terminal. (If the vehicle has an extended storage fuse switch, turn it off.)", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "BATTERY DIAGNOSIS", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "To diagnose and confirm the condition of the battery, use the Multitasking battery and electrical diagnostic station (commercially-available tool):", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Refer to the applicable instruction manual for proper battery diagnosis procedures.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "BATTERY DIAGNOSIS WITHOUT Multitasking battery and electrical diagnostic station (commercially-available tool)", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "VISUAL INSPECTION", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "Check battery case for cracks or bends.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Check battery terminals for damage.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Are these inspection results normal?", "question");
si[i++] = gsitm("N514060300000M00ENG.html", "YES", "result");
si[i++] = gsitm("N514060300000M00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "NO", "result");
si[i++] = gsitm("N514060300000M00ENG.html", "Replace battery. Refer to .", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "CAPACITY TEST", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "Remove the battery cable.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Check battery voltage.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Is the voltage 12.35 V or more?", "question");
si[i++] = gsitm("N514060300000M00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "LOAD TEST", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "Check battery type and determine the specified current using the table.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Type", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Current (A)", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "L3–EFB", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "300", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Read load tester voltage when specified discharging current flows through battery for 15 seconds.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Follow tool manufacturers operating instructions when performing load test.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Is the voltage 10 V or more?", "question");
si[i++] = gsitm("N514060300000M00ENG.html", "Ready for use.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "CHARGE", "title");
si[i++] = gsitm("N514060300000M00ENG.html", "Charge battery, following the instructions below:", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Constant current charging may damage batteries. Therefore, charge battery by constant voltage charge mode with the maximum voltage set at 15 V.", "ptxt");
si[i++] = gsitm("N514060300000M00ENG.html", "Charge at least 6 hours or until the charge current becomes 4 amps or less.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "How To Check", "title");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "If fuse is blown, be sure to eliminate cause of malfunction before installing new fuse.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Use fuse of specified rating. Never use fuse of more than specified rating.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Do not partially install fuse; always insert it into fuse holder properly.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Remove fuse for “ELECTRICAL PARTS (BAT)” if vehicle is not used for a long period of time.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "EXTENDED STORAGE FUSE SWITCH (IF EQUIPPED)", "title");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "The following switch may be mounted on the fuse block (Junction Box) for transportation and storage.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Extended storage fuse switch", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Type A", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Type B", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Type C", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Remove the extended storage fuse switch if it causes the interference when checking fuses.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "How To Extended Storage Fuse Switch ON/OFF", "title");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Turn the ignition switch OFF when operating the extended storage fuse switch.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Under normal conditions, keep the extended storage fuse switch in ON state. Never operate the extended storage fuse switch except when necessary.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "To turn the extended storage fuse switch OFF, pull it up in  direction as shown in the figure.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "To turn the extended storage fuse switch ON, press it in  direction as shown in the figure.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "To turn the extended storage fuse switch OFF, hold  of the switch and pull up in  direction as shown in the figure.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "How To Remove Extended Storage Fuse Switch", "title");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Turn the ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Turn the extended storage fuse switch OFF.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Press pawl  and tilt to disengage the extended storage fuse switch. Press pawl  and tilt to remove the extended storage fuse switch.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Never use fuse for bus bar.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Extended storage fuse switch and bus bar are removed together. Remove bus bar from extended storage fuse switch, if necessary.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Install removed bus bar to fuse block.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Extended storage fuse switch is for transportation and storage. Reinstallation is not required after the removal.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Hold  and pull up the extended storage fuse switch hard in  direction.", "ptxt");
si[i++] = gsitm("N5140603Y0000J00ENG.html", "Extended storage fuse switch and bus bar may be removed together. Remove bus bar from extended storage fuse switch, if necessary.", "ptxt");
si[i++] = gsitm("N5140603Y0000K00ENG.html", "How To Check", "title");
si[i++] = gsitm("N5140603Y0000K00ENG.html", "A melted fusible link can be detected either by visual inspection or by feeling with finger tip. If its condition is questionable, use circuit tester or test light.", "ptxt");
si[i++] = gsitm("N5140603Y0000K00ENG.html", "Fusible link", "ptxt");
si[i++] = gsitm("N5140603Y0000K00ENG.html", "If fusible link should melt, it is possible that critical circuit (power supply or large current carrying circuit) is shorted. In such a case, carefully check and eliminate cause of malfunction.", "ptxt");
si[i++] = gsitm("N5140603Y0000K00ENG.html", "Never wrap outside of fusible link with vinyl tape. Important: Never let fusible link touch any other wiring harness, vinyl or rubber parts.", "ptxt");
