si[i++] = gsitm("N514060430002100ENG.html", "Apply lubricant before installing the battery cover hose to the battery cover (exhaust B) and before installing the battery grommet to the body or the battery cover hose.", "ptxt");
si[i++] = gsitm("N514060430002100ENG.html", "LUBRICANT: AQUA SOLVENT or equivalent", "ptxt");
si[i++] = gsitm("N514060430002100ENG.html", "Insert the battery cover hose into the battery grommet until the yellow marking of the battery cover hose comes to the position shown in the figure.", "ptxt");
si[i++] = gsitm("N514060430002100ENG.html", "Align the yellow marking of the battery cover hose with the emboss mark of the battery cover as shown in the figure. Then, secure the hose clip at the position shown in the figure.", "ptxt");
si[i++] = gsitm("N514060430002100ENG.html", "Never reuse the hose clip whose tab is broken off to prevent the rusting.", "ptxt");
