si[i++] = gsitm("N5160102T000HJ00ENG.html", "The ambient sensor input value that is displayed on “Data List” of M.U.T.-III SE is the value before the correction. It may not match the indicated temperature on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000HJ00ENG.html", "Depending on engine heat or heat on the road surfaces, an ambient temperature may be indicated higher than actual one.", "ptxt");
