si[i++] = gsitm("N5160102T000JQ00ENG.html", "Current fuel consumption on the information display is updated approximately every 0.1 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JQ00ENG.html", "Current fuel consumption on the information display shows 30 l/100km (0 mpg) when vehicle speed is 0 km/h (0 MPH).", "ptxt");
