si[i++] = gsitm("N5160102T000JQ00ENG.html", "Average fuel consumption on the information display is updated approximately every 30 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JQ00ENG.html", "Soon after a reset or when the ignition switch is turned ON, “−−−” is displayed until after a travel of 30 seconds and approximately 500 m (0.31 mile).", "ptxt");
