si[i++] = gsitm("N5160102T000HO00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160102T000HO00ENG.html", "The Head Up Display (HUD) displays information on the vehicle speed and driving assistance system on the windshield glass, and supports safe driving by suppressing the burden due to the movement of the driver\'s eyes.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "The Head Up Display unit receives necessary signals from each ECU via CAN communication and local communication.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Operation", "title");
si[i++] = gsitm("N5160102T000HO00ENG.html", "When the ignition switch is ON, pushing the main switch activates Head Up Display.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Head Up Display projects display on the windshield glass.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Image focus on 2.1 m (6.89 ft) from driver\'s eye point.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Windshield glass", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Eye point", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Virtual image display", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "C.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "2.1 m (6.89 ft)", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Structure", "title");
si[i++] = gsitm("N5160102T000HO00ENG.html", "The Head Up Display unit projects the image to the windshield glass by reflecting the image of the TFT liquid crystal display on the concave mirror. Also, by manipulating the angle of the concave mirror, the projection position on the windshield glass can be adjusted.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "Concave mirror", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "TFT liquid crystal display", "ptxt");
