si[i++] = gsitm("N5160102T000HO00ENG.html", "The Head Up Display (HUD) can display one or more of the following features.", "ptxt");
si[i++] = gsitm("N5160102T000HO00ENG.html", "The Head Up Display unit can cause an interrupt on the HUD display to indicate a warning, based on signals received from each unit.", "ptxt");
