si[i++] = gsitm("N516010320006000ENG.html", "Removal", "ptxt");
si[i++] = gsitm("N516010320006000ENG.html", "combination meter", "ptxt");
si[i++] = gsitm("N516010320006000ENG.html", "×", "ptxt");
si[i++] = gsitm("N516010320006000ENG.html", "–", "ptxt");
si[i++] = gsitm("N516010320006000ENG.html", "Configuration", "par5");
si[i++] = gsitm("N516010320006000ENG.html", "The combination meter do not operate normally unless the additional services are performed.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "INTERVIEW FOR MALFUNCTION", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "It is also important to clarify the customer concerns before starting the inspection. Interview the customer about the concerns carefully and understand the symptoms fully.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "The customers are not professionals. Never assume that “maybe the customer means···” or “maybe the customer mentioned this symptom”.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "SELF-DIAGNOSIS WITH M.U.T.-III SE", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Perform self-diagnosis of “E-HUD” using M.U.T.-III SE. Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Skip to step 4 of the diagnosis procedure if “E-HUD” is not displayed.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N516010300003S00ENG.html", "YES", "result");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "NO", "result");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "TROUBLE DIAGNOSIS FOR DTC", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "Check the DTC indicated in the “Self Diagnostic Result”.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "When DTC is detected, follow the instructions below:", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Record DTC", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Freeze Frame Data (FFD)", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Perform the relevant diagnosis referring to the DTC Index. Refer to .", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "If DTC “U1000‐01” is detected, first diagnose the CAN communication system.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "Perform the applicable diagnosis according to the diagnosis chart by symptom. Refer to Symptom Table.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "MALFUNCTIONING PART REPAIR", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "REPAIR CHECK (SELF-DIAGNOSIS WITH M.U.T.-III SE)", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "Erases self-diagnosis results.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Perform self-diagnosis of “E-HUD” again after repairing or replacing the specific items.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Check if any DTC is detected in self-diagnosis results of “E-HUD” .", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "REPAIR CHECK (OPERATION TEST)", "title");
si[i++] = gsitm("N516010300003S00ENG.html", "Perform operation test. Check that the malfunction symptom is solved or no other symptoms occur.", "ptxt");
si[i++] = gsitm("N516010300003S00ENG.html", "Is there a malfunction symptom?", "question");
si[i++] = gsitm("N516010300003S00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N516010320006100ENG.html", "Description", "title");
si[i++] = gsitm("N516010320006100ENG.html", "When replacing or removing the Head Up Display unit, distortion calibration of the display and adjustment of the display position are required.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "REPLACE HEAD UP DISPLAY UNIT", "title");
si[i++] = gsitm("N516010320006100ENG.html", "Replace Head Up Display unit. Refer to .", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "PERFORM CALIBRATION", "PERFORMCALIBRATION-48D13FC7");
si[i++] = gsitm("N516010320006100ENG.html", "Perform Head Up Display calibration. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "ADJUST DISPLAY SCREEN", "ADJUSTDISPLAY-48D147FE");
si[i++] = gsitm("N516010320006100ENG.html", "Adjust display screen position. Refer to .", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "OPERATION CHECK", "OPERATIONCHECK-48D14F0E");
si[i++] = gsitm("N516010320006100ENG.html", "Check the display of Head Up Display.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "Is the displayed normal?", "question");
si[i++] = gsitm("N516010320006100ENG.html", "YES", "result");
si[i++] = gsitm("N516010320006100ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "NO", "result");
si[i++] = gsitm("N516010320006100ENG.html", "Perform display adjustment again. GO TO 3.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N516010320006100ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"E-HUD\".", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N516010320006100ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Diagnosis Procedure", "title");
si[i++] = gsitm("N51601017004WV00ENG.html", "Description", "title");
si[i++] = gsitm("N51601017004WV00ENG.html", "Calibration must be performed after replacing or removing/installing the following parts..", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Head Up Display unit", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Windshield glass", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Steering member", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Place the vehicle on level ground.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Keep the space when calibration. (Vehicle front area)", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Wide: 2.0 m (6.56 ft)", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Height: 2.0 m (6.56 ft)", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Length: 2.0 m (6.56 ft)", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "TARGET PREPARATION", "title");
si[i++] = gsitm("N51601017004WV00ENG.html", "Prepare the distortion calibration jig according to the following procedure and the figure.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Prepare target sheet according to the figure.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Paste the created target sheet onto the board according to the figure.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "TARGET SETTING", "4A0150C3");
si[i++] = gsitm("N51601017004WV00ENG.html", "Mark points \"A\", \"B\", \"C\" and \"D\" at the center position of each wheels.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Draw line \"LH (RH)\"  passing through points \"A (C)\" and \"B (D)\" on the left (right) side of vehicle.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Approximately 4.0 m (13.12 ft) or more from the point \"B (D)\".", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Mark point \"E (F)\" on the line \"LH (RH)\" at the positions 1.53 m (5.02 in) from point \"A (C)\". And then draw line \"FW\" passing through the points \"E\" and \"F\".", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Place the target board on the line \"FW\" so that the center of the target comes to 560 mm (1.84 ft) from mark point \"E\".", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "DRIVER\'S SEAT POSITION ADJUSTMENT", "4A01590D");
si[i++] = gsitm("N51601017004WV00ENG.html", "Adjust the driver\'s seat to the position shown in the figure.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "RESET OPERATION", "4A015E4C");
si[i++] = gsitm("N51601017004WV00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Touch \"Reset\" on the Head Up Display setting screen of the combination meter and reset the setting. Refer to .", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "TARGET CENTER POSITION ADJUSTMENT", "4A016442");
si[i++] = gsitm("N51601017004WV00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Select \"Distortion calibration\" of \"Special Function\" on \"E-HUD\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Confirm from the between seatback and headrest whether the center position of the displayed guideline is coincident with the center position of the target sheet.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "If there is a gap between the target sheet and the guideline, move the target board so that the center of the target seat coincides with the center of the guideline.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "PERFORM DISTORTION CALIBRATION", "PERFORMDISTORTIONCALIBRATION-4A016B1D");
si[i++] = gsitm("N51601017004WV00ENG.html", "Check the distortion of the guideline from the between seatback and headrest.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "If the guideline display is distorted, touch \"+\" or \"-\" of the item corresponding to the distortion type to be corrected according to following table, and calibrate to match the target sheet.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Touch \"Save\" and save the setting when calibration is completed.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "Touch \"Reset\" to cancel the change.", "ptxt");
si[i++] = gsitm("N51601017004WV00ENG.html", "WORK END", "ptxt");
