si[i++] = gsitm("N51601011000DY00ENG.html", "Description", "title");
si[i++] = gsitm("N51601011000DY00ENG.html", "DISTANCE TO EMPTY", "title");
si[i++] = gsitm("N51601011000DY00ENG.html", "The calculated distance to empty may differ from the actual distance to empty if the refueling amount is approximately 4  (7/8 Imp gal) or less. This is because the refuel control (moves the fuel gauge needle quicker than normal judging that the driver is refueling the vehicle) is not performing.", "ptxt");
si[i++] = gsitm("N51601011000DY00ENG.html", "AMBIENT TEMPERATURE", "title");
si[i++] = gsitm("N51601011000DY00ENG.html", "The displayed ambient temperature on the information display may differ from the actual temperature because it is a corrected value calculated from the ambient sensor signal by the combination meter. Refer to   for details on the correction process.", "ptxt");
si[i++] = gsitm("N5160102P0001M00ENG.html", "Symptom Description", "title");
si[i++] = gsitm("N5160102P0001M00ENG.html", "The Head Up Display unit controls and protects the backlight and display when the LED temperature becomes high. Refer to .", "ptxt");
si[i++] = gsitm("N51604052000TY00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000TY00ENG.html", "When replacing the combination meter, always replace it with a new one. The functions controlled by the combination meter does not operate properly in case of reuse of the combination meter from another vehicle.", "ptxt");
si[i++] = gsitm("N51604052000TY00ENG.html", "Be sure to perform the configuration when replacing combination meter. Refer to .", "BeSureToPerformTheFollowingSystemsS-75A75CD2");
