si[i++] = gsitm("N516010410001200ENG.html", "Vehicle speed is 15 km/h (9.3 MPH) or more.", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "When blinking, it turn ON when all of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "Vehicle speed is less than 3 km/h (1.8 MPH).", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "Shift position is P or parking brake ON", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "SHUTOFF CONDITION", "title");
si[i++] = gsitm("N516010410001200ENG.html", "Combination meter turns seat belt warning light OFF when any of the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "Ignition switch is OFF.", "ptxt");
si[i++] = gsitm("N516010410001200ENG.html", "When all of the conditions listed below are satisfied while the ignition switch is ON", "ptxt");
