si[i++] = gsitm("N5160102T000JR00ENG.html", "WARNING CONFIRMATION", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter can cause an interrupt on the information display to indicate a warning, based on signals received from each unit and switch.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The indicated warning can be checked with “WARNING” during the satisfaction of an interrupt indication condition for each warning.", "ptxt");
