si[i++] = gsitm("N5160102T000JR00ENG.html", "Current Fuel Consumption", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates current fuel consumption based on the following signals, and the calculated value is displayed on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Current fuel consumption can be compared with average fuel consumption.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Current fuel consumption on the information display is updated approximately every 0.1 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Current fuel consumption on the information display shows 30 l/100km (0 mpg) when vehicle speed is 0 km/h (0 MPH).", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Average Fuel Consumption", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates average fuel consumption based on the following signals, and the calculated value is displayed on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Average fuel consumption on the information display is updated approximately every 30 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Soon after a reset or when the ignition switch is turned ON, “−−−” is displayed until after a travel of 30 seconds and approximately 500 m (0.31 mile).", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Current Vehicle Speed", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates current vehicle speed based on the following signals, and the calculated value is displayed on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Current vehicle speed on the information display is updated approximately every 0.3 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Average Vehicle Speed", "title");
