si[i++] = gsitm("N5160102T000JR00ENG.html", "Average vehicle speed on the information display is updated approximately every 30 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Soon after a reset, “−−−” is displayed until after 30 seconds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Travel Time", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter measures and displays travel time (ignition switch ON time).", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Travel Distance", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter measures and displays travel distance.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECO Pedal Guide", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The ECO pedal guide consists of Gauge 1  (displays accelerator pedal angle) and Gauge 2  (displays the guideline of ECO driving).", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "GAUGE1", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECM corrects the accelerator pedal angle to the maximum angle for ECO driving, according to vehicle speeds.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The maximum accelerator pedal angle increases/decreases as the vehicle speed increases/decrease.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The maximum accelerator angle corrected by ECM is the limitation of ECO driving. The ECO driving is possible only when the number of unlit segments  of the indicator bar is equal to or less than that of Gauge 2.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The less the number of unlit segments  of the indicator bar, the more the degree of ECO driving is. And the more the number of unlit segments, the less the degree of ECO driving is.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECM judges the number of lighting segments according to the accelerator pedal angle and vehicle speed and transmits a CAN communication signal to the combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter indicates the number of segments necessary for the ECO pedal guide, according to an ECO pedal guide signal.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter corrects the number of lighting segments according to a vehicle speed signal.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "GAUGE2", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter turns ON/OFF the Gauge 2 (guide line for ECO driving) according to a vehicle speed signal.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECO DRIVE INDICATOR", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter displays level of ECO drive in conjunction with ECO pedal guide.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECO pedal guide signal", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECO Drive Report", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The ECO drive report is a function which displays the last five data of average fuel consumption, present fuel economy (present value), and the best fuel economy (highest value) on the information display by calculating and recording average fuel consumption.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates the average fuel consumption according to the signal below, detects the status of ECO mode , and displays “ECO drive report” on the information display when the ignition switch is turned ON→OFF.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "ECO mode indicator signal", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "AMBIENT TEMPERATURE", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates ambient temperature based on the following signals, and the calculated value is displayed on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Ambient sensor signal", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Ambient sensor Combination meter", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The indicated temperature is corrected based on an ignition signal, ambient temperature detected by the ambient sensor, and vehicle speed signal. The indicated temperature is not raised under vehicle speed less than 20 km/h (12 MPH).", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The ambient sensor input value that is displayed on “Data List” of M.U.T.-III SE is the value before the correction. It may not match the indicated temperature on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "Depending on engine heat or heat on the road surfaces, an ambient temperature may be indicated higher than actual one.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "CLOCK", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter calculates time and displays it on the information display.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The settings screen of the information display allows the selection of time indication between 12-hour and 24-hour formats.", "ptxt");
si[i++] = gsitm("N5160102T000JR00ENG.html", "METER ILLUMINATION LEVEL", "title");
si[i++] = gsitm("N5160102T000JR00ENG.html", "The combination meter displays the illuminance level of the back light on the information display by turning the illumination control switch.", "ptxt");
