si[i++] = gsitm("N5160407Y0003Q00ENG.html", "METHOD OF STARTING", "title");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "How to Initiate Self-Diagnosis Mode", "title");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "Turn ignition switch OFF.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "While pressing the control switch , turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "Keep pressing the control switch for 1 seconds or more.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "Press the control switch at least 3 times. (Within 7 seconds after the ignition switch is turned ON.)", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "“Work instruction code” is indicated in the top portion of information display and self-diagnosis is started.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "When on-board diagnosis does not start, check the following items and replace combination meter if the check results are normal.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "Combination meter power supply and ground circuits. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "Steering switch signal circuits. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "The mode switches in the order shown below each time the control switch is pressed.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "If the control switch is not operated for 20 seconds or more, the self-diagnosis mode is automatically cancelled.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "The self-diagnosis mode is cancelled by turning the key switch OFF.", "ptxt");
si[i++] = gsitm("N5160407Y0003Q00ENG.html", "The self-diagnosis mode is cancelled by engine speed 170 rpm or more.", "ptxt");
