si[i++] = gsitm("N5161601S0002300ENG.html", "GO TO 1.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N516010320006200ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N516010320006200ENG.html", "When replacing the Combination meter, perform the procedures before and after replacement.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Before Replacement", "title");
si[i++] = gsitm("N516010320006200ENG.html", "Take note the odometer mileage of the combination meter. When replacing the combination meter, check that DTC’s are not detected at \"self-diagnostic result\" of ABS. When detecting DTC’s, perform \"self-diagnostic result\" of ABS.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "After Replacement", "title");
si[i++] = gsitm("N516010320006200ENG.html", "After replacing the combination meter, the following items must be performed.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Configuration", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Driving 1 km or more", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Factory Mode OFF", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "The odometer mileage of the combination meter is also stored and memorized in the ABS actuator and electric unit (control unit). When driving 1 km or more after replacement of the combination meter, the memorized mileage in the ABS actuator and electric unit (control unit) is written into the new combination meter.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "WORK PROCEDURE", "title");
si[i++] = gsitm("N516010320006200ENG.html", "COMBINATION METER CONFIGURATION", "title");
si[i++] = gsitm("N516010320006200ENG.html", "Perform the combination meter configuration with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "PERFORM SELF-DIAGNOSIS", "PERFORMSELF-DIAGNOSIS-AD50BBC1");
si[i++] = gsitm("N516010320006200ENG.html", "Perform the self-diagnosis of combination meter with M.U.T.-III SE. Check if any DTC is detected.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N516010320006200ENG.html", "YES", "result");
si[i++] = gsitm("N516010320006200ENG.html", "Perform the trouble diagnosis for the detected DTC. Refer to .", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "NO", "result");
si[i++] = gsitm("N516010320006200ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "DRIVING TEST", "DRIVINGTEST-AD4FBEF6");
si[i++] = gsitm("N516010320006200ENG.html", "Drive the vehicle at 30 km/h or more for 1 km or more with the vehicle raised.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Check that the odometer shows more than the mileage taken note before.", "question");
si[i++] = gsitm("N516010320006200ENG.html", "For AWD vehicles, the DTC indicating an abnormality in the G sensor may be set. For FWD vehicles, the brake indicator in the meter may illuminate and the DTC indicating an abnormality in the G sensor and an abnormality in the wheel speed sensor may be set. However, these are not malfunctions.If the DTC is set, erase it to complete the work.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N516010320006200ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"METER/M&A\".", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N516010320006200ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N516010120001U00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the combination meter.", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the combination meter.", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "The configuration no need to “save” configuration data from the combination meter. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N516010120001U00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N516010320006300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N516010320006300ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N516010320006300ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N516010320006300ENG.html", "Perform writing vehicle specification to combination meter following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N516010320006300ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N516010320006300ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N516010320006300ENG.html", "WORK END", "ptxt");
