si[i++] = gsitm("N51601011000E400ENG.html", "Description", "title");
si[i++] = gsitm("N51601011000E400ENG.html", "DISTANCE TO EMPTY", "title");
si[i++] = gsitm("N51601011000E400ENG.html", "The calculated distance to empty may differ from the actual distance to empty if the refueling amount is approximately 4  (7/8 Imp gal) or less. This is because the refuel control (moves the fuel gauge needle quicker than normal judging that the driver is refueling the vehicle) is not performing.", "ptxt");
si[i++] = gsitm("N51601011000E400ENG.html", "AMBIENT TEMPERATURE", "title");
si[i++] = gsitm("N51601011000E400ENG.html", "The displayed ambient temperature on the information display may differ from the actual temperature because it is a corrected value calculated from the ambient sensor signal by the combination meter. Refer to   for details on the correction process.", "ptxt");
si[i++] = gsitm("N51604052000U500ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000U500ENG.html", "When replacing the combination meter, always replace it with a new one. The functions controlled by the combination meter does not operate properly in case of reuse of the combination meter from another vehicle.", "ptxt");
si[i++] = gsitm("N51604052000U500ENG.html", "Be sure to perform the configuration when replacing combination meter. Refer to .", "BeSureToPerformTheFollowingSystemsS-75A75CD2");
si[i++] = gsitm("N51604052000U500ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N51604052000U500ENG.html", "Cluster lid assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Disassembly and Assembly", "title");
si[i++] = gsitm("N5161600C0000K00ENG.html", "DISASSEMBLY", "title");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Disengage the pawls of combination meter to allow the front cover  to become slightly released.", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Never damage the front cover.", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", ": Pawl", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Pull the front cover straight to remove it from the meter control unit.", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Never touch the inside of front cover, pointer, the display and the printed area of the dial during the work.", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Keep away from magnetic sources.", "ptxt");
si[i++] = gsitm("N5161600C0000K00ENG.html", "ASSEMBLY", "title");
si[i++] = gsitm("N5161600C0000K00ENG.html", "Install the front cover straight to the unified meter control unit and engage all the pawl.", "ptxt");
