si[i++] = gsitm("N516020470000P00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N516020470000P00ENG.html", "TCM judges the shift position by transmission range switch.", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "BCM transmits a door switch signal to the TCM.", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "The TCM judges the vehicle condition according to the shift position signal and the door switch signal. The TCM transmits a shift P range request display signal to the combination meter if the driver’s door is opened with the shift position not in P position.", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "WARNING OPERATING CONDITION", "title");
si[i++] = gsitm("N516020470000P00ENG.html", "When all of the following conditions are satisfied:", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "Shift position: P position", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "Front door (driver side): Close", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "WARNING CANCEL CONDITION", "title");
si[i++] = gsitm("N516020470000P00ENG.html", "When any of the following conditions are satisfied:", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "The shift position is changed to P position.", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "The driver’s door is closed.", "ptxt");
si[i++] = gsitm("N516020470000P00ENG.html", "TIMING CHART", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Take Away Warning (Buzzer)", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "PURPOSE", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Take away warning warns the driver that keyless operation key is removed from passenger room, according to the vehicle status.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "SYNCHRONIZATION WITH WARNING/INDICATOR (INFORMATION DISPLAY)", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Synchronization is applied.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Refer to Take Away Warning (Information Display).", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "SYSTEM DIAGRAM", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "SIGNAL PATH", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Door status changes from open to close", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Keyless operation key unit judges whether or not warning the driver is required, according to push switch signal from push-button ignition switch, door switch signal from each door switch, and inside key antenna signal from inside key antenna and NATS antenna amp.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "When keyless operation key unit judges that warning the driver is required, buzzer output signal and meter display signal are transmitted by keyless operation key unit to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Combination meter, when it receives buzzer output signal and meter display signal, operates meter speaker and information display. Keyless operation key unit simultaneously operates keyless operation key warning buzzer.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Door status is open", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Keyless operation key unit, when it judges that warning to the driver is required, transmits meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "When combination meter receives meter display signal, information display operates.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Push-button ignition switch is pressed", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "Combination meter, when it receives buzzer output signal and meter display signal, operates meter speaker and information display.", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "WARNING OPERATING CONDITION", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "When all of the following conditions are satisfied", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Ignition switch is other than OFF", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Door switch is switched from ON to OFF (Open door is closed)", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "A registered keyless operation key is not detected in passenger room", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Door switch is ON (Door is open)", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Ignition switch is in OFF", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Push-button ignition switch operation is performed", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "WARNING CANCEL CONDITION", "title");
si[i++] = gsitm("N516020480000N00ENG.html", "When any of the following conditions are satisfied", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "A registered keyless operation key is detected in passenger room", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "Since warning start, 15 seconds are passed while battery saver system is in operation", "ptxt");
si[i++] = gsitm("N516020480000N00ENG.html", "For battery saver system, refer to .", "ptxt");
