si[i++] = gsitm("N5160203M0000M00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "OVERALL SEQUENCE", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "OBTAIN INFORMATION ABOUT SYMPTOM", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Interview the customer to obtain as much information as possible about the conditions and environment under which the malfunction occurred.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "CHECK SYMPTOM", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Check the symptom based on the information obtained from the customer.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Check if any other malfunctions are present.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "CHECK M.U.T.-III SE SELF-DIAGNOSIS RESULTS", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Connect M.U.T.-III SE and perform self-diagnosis. Refer to  (Full TFT meter) or (7 inch information display).", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "When DTC is detected, follow the instructions below:", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Record DTC and Freeze Frame Data.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Are self-diagnosis results normal?", "question");
si[i++] = gsitm("N5160203M0000M00ENG.html", "YES", "result");
si[i++] = gsitm("N5160203M0000M00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "NO", "result");
si[i++] = gsitm("N5160203M0000M00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "NARROW DOWN MALFUNCTIONING PARTS BY SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Perform symptom diagnosis and narrow down the malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "REPAIR OR REPLACE MALFUNCTIONING PARTS", "title");
si[i++] = gsitm("N5160203M0000M00ENG.html", "Repair or replace malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "If DTC is displayed, erase DTC after repairing or replacing malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5160203M0000M00ENG.html", "FINAL CHECK", "title");
