si[i++] = gsitm("N516030370000N00ENG.html", "Sonar Control Unit", "title");
si[i++] = gsitm("N516030370000N00ENG.html", "COMPONENT FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N516030370000N00ENG.html", "Sonar control unit detects distance from an obstacles with signals transferred from sonar sensors.", "ptxt");
si[i++] = gsitm("N516030370000N00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N516030370000N00ENG.html", "Sonar control unit supplies power to each sonar sensor.", "ptxt");
si[i++] = gsitm("N516030370000N00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N516030370000N00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516030370000N00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N516030370000N00ENG.html", "Sonar control unit is located in the luggage room.", "ptxt");
si[i++] = gsitm("N516030380000O00ENG.html", "Sonar Sensor", "title");
si[i++] = gsitm("N516030380000O00ENG.html", "COMPONENT FUNCTION WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N516030380000O00ENG.html", "When a distance from an obstacle is detected, a signal is transmitted to the sonar control unit.", "ptxt");
si[i++] = gsitm("N516030380000O00ENG.html", "INDIVIDUAL COMPONENT FUNCTION", "title");
si[i++] = gsitm("N516030380000O00ENG.html", "Sonar sensor detects distance to obstacles by a period that supersonic emitted by the sensor reflects in an obstacle and returns to a sensor.", "ptxt");
si[i++] = gsitm("N516030380000O00ENG.html", "Sonar sensor transmits reflecting wave as received signal to sonar control unit.", "ptxt");
si[i++] = gsitm("N516030380000O00ENG.html", "COMPONENT OPERATION", "title");
si[i++] = gsitm("N516030380000O00ENG.html", "Sonar sensor takes power supply from sonar control unit, and detect distance to obstacles then outputs signal to sonar control unit.", "ptxt");
si[i++] = gsitm("N516030380000O00ENG.html", "COMPONENT PARTS LOCATION", "title");
si[i++] = gsitm("N516030380000O00ENG.html", "Sonar sensor is located on the front bumper and rear bumper. Refer to .", "ptxt");
