si[i++] = gsitm("N5160302T0001D00ENG.html", "Multi-around monitor control unit*", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "*: With multi-around monitor", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160302T0001D00ENG.html", "The sonar sensor installed to the front bumper and the rear bumper detects obstacles around the bumper.", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "The sonar control unit changes the tone alarm cycle and the warning of the sonar indicator (combination meter and multi-around monitor control unit), according to a distance from an obstacle detected by the sonar sensor.", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "The sonar control unit controls the tone alarm cycle according to a tone alarm output signal transmitted to the combination meter and the multi-around monitor control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "The sonar control unit controls the sonar indicator according to a sonar indicator display signal transmitted to the combination meter and the multi-around monitor control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5160302T0001D00ENG.html", "SONAR SYSTEM ACTIVATION CONDITION", "title");
