si[i++] = gsitm("N516030110002G00ENG.html", "The vehicle is on a rough surface, such as stone or gravel.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When used in poor weather conditions, such as heavy snow/rain or strong wind.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When subjected to an ultrasonic noise generated from exhaust muffler or brakes.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When left standing in the hot sun or in a cold climate.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When the surface of the sensor is frozen or covered with snow/dirt/moisture.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When a retrofitted xenon light, lighted license plate, or harness is close to the sensor body or sensor harness.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "When subjected to loop coil noises generated from a vehicle detector placed at an intersection or coin parking area.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "Object undetectable", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "Air-containing objects, such as cloth, cotton, glass wool, dust, and snow.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "Thin objects, such as rope, chain, and wire.", "ptxt");
si[i++] = gsitm("N516030110002G00ENG.html", "Smooth-faced objects placed in a slanting direction.", "ptxt");
