si[i++] = gsitm("N51604052000V000ENG.html", ">>A&lt;&lt; FRONT SONAR SENSOR, FRONT SONAR SENSOR INNER HOLDER, FRONT SONAR SENSOR OUTER HOLDER INSTALLATION", "title");
si[i++] = gsitm("N51604052000V000ENG.html", "ID mark of sonar sensor holder accord with ID mark of front bumper assembly.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Apply primer to cover inside the scratching line on sonar sensor holder applying surface (Even if it extends the scratching line).", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Before the next operation, leave the decreased parts for 3 minutes or more to dry. Do not touch the coated surface.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Use parts cleaner (MZ100387 or equivalent) to degrease the circumference inside the scratching line.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "The primer strengthens the adhesive, so be sure to apply it. However, too thick application will weaken the adhesive.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Soak a sponge in the primer, and apply evenly to the circumference inside the scratching line.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "After applying the primer, let it dry for 3 minutes or more.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Sensor connector accord with the position of the direction mark of the front bumper assembly side.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Install the sonar sensor holder to the front bumper assembly.", "ptxt");
si[i++] = gsitm("N51604052000V000ENG.html", "Install the front sonar sensor to the sonar sensor holder.", "ptxt");
