si[i++] = gsitm("N51604052000V100ENG.html", ">>A&lt;&lt; REAR SONAR SENSOR, REAR SONAR SENSOR INNER HOLDER, REAR SONAR SENSOR OUTER HOLDER INSTALLATION", "title");
si[i++] = gsitm("N51604052000V100ENG.html", "ID mark of sonar sensor holder accord with ID mark of rear bumper assembly.", "ptxt");
si[i++] = gsitm("N51604052000V100ENG.html", "Apply primer to cover inside the scratching line on sonar sensor holder applying surface (Even if it extends the scratching line).", "ptxt");
si[i++] = gsitm("N51604052000V100ENG.html", "Before the next operation, leave the decreased parts for 3 minutes or more to dry. Do not touch the coated surface.", "ptxt");
si[i++] = gsitm("N51604052000V100ENG.html", "Use parts cleaner (MZ100387 or equivalent) to degrease the circumference inside the scratching line.", "ptxt");
si[i++] = gsitm("N51604052000V100ENG.html", "The primer strengthens the adhesive, so be sure to apply it. However, too thick application will weaken the adhesive.", "ptxt");
