si[i++] = gsitm("N5160408B0000L00ENG.html", "Steering Switch", "title");
si[i++] = gsitm("N5160408B0000L00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N5160408B0000L00ENG.html", "By operating the switch disposed on the steering, the driver can operate the screen without releasing the hand from the handle.", "ptxt");
si[i++] = gsitm("N5160408B0000L00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N5160408B0000L00ENG.html", "The steering switches are connected to combination meter.", "ptxt");
si[i++] = gsitm("N5160408B0000L00ENG.html", "Combination meter transmits steering switch signals to AV control unit via AV communication.", "ptxt");
si[i++] = gsitm("N5160408B0000L00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N5160408B0000L00ENG.html", "The steering switch is constituted by a combination of a normally open switch and a resistor.", "ptxt");
si[i++] = gsitm("N5160408B0000L00ENG.html", "When each switch is pressed, the voltage from the combination meter is displaced according to the resistance value set for each switch, and the combination meter reads which switch is pressed.", "ptxt");
si[i++] = gsitm("N5160408B0000L00ENG.html", "Combination meter transmits a switch operating signal to the AV control unit.", "ptxt");
