si[i++] = gsitm("N5160408C0000L00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N5160408C0000L00ENG.html", "Secure reception performance of GPS information.", "ptxt");
si[i++] = gsitm("N5160408C0000L00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N5160408C0000L00ENG.html", "In order to specify the current position of the vehicle, GPS information is received from GPS satellites.", "ptxt");
si[i++] = gsitm("N5160408C0000L00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N5160408C0000L00ENG.html", "This antenna amplifies radio waves received from the GPS satellite and transmits the GPS signal to the AV control unit.", "ptxt");
si[i++] = gsitm("N5160408C0000L00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N5160408C0000L00ENG.html", "GPS antenna is installed in the instrument panel. Refer to .", "ptxt");
si[i++] = gsitm("N5160408C0000L00ENG.html", "An object on the instrument panel may cause the reception sensitivity to be decreased.", "ptxt");
