si[i++] = gsitm("N5160408D0000O00ENG.html", "Secure reception performance of radio waves.", "ptxt");
si[i++] = gsitm("N5160408D0000O00ENG.html", "Receives satellite radio waves and outputs it to AV control unit.", "ptxt");
