si[i++] = gsitm("N5160405X0002T00ENG.html", "Android AutoTM", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AUDIO SYSTEM", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Refer to Owner’s Manual for audio system operating instructions.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Audio system consists of the following functions.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Function", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Radio", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "USB connection", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Bluetooth® audio", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Speed Sensitive Volume", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Audio indicator", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Audio system is controlled by AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AM/FM radio", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Radio signal for AM/FM radio is received by the roof antenna.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Antenna amp. is connected to the roof antenna line, which receives the antenna amp. ON signal from the AV control unit, and transmits the antenna signal to the AV control unit after amplifying the AM or FM radio signal.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AV control unit transmits the sound signal to the each speaker when the antenna signal is received from the roof antenna.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "DAB Radio", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Radio signal for DAB radio is received by the roof antenna.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "CD audio like high-quality sound", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Improved radio reception due to digital radio wave", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "A DAB-DAB link function enables the driver to receive multiple radio stations which are broadcasting the same contents sequentially.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Text information such as song title or artist is displayed.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "USB Connection", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "USB port is located in the front auxiliary input jacks.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When iPod® or USB memory is connected to the USB port, the front auxiliary input jacks transmits the music data and text data in iPod® or USB memory device to the AV control unit via USB communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the text data from front auxiliary input jacks, it displays the text data (artist, album, and song title) on the display.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Bluetooth® Audio", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Bluetooth® module is integrated in the AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Music data, artist, album, and song title in a portable audio device can be played/displayed via Bluetooth® communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the music data from a portable audio device via Bluetooth® communication, it transmits the sound signal to each speaker.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the text data from a portable audio device via Bluetooth® communication, it displays the text data (artist, album, and song title) on the display.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AV control unit receives the vehicle speed signal from ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AV control unit determines the volume level according to the vehicle speed signal received from ABS actuator and electric unit (control unit), and transmits the sound signal to each speaker.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The control level can be selected by the customer.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Audio Indicator", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The status of the audio system is displayed on the information display in the combination meter.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The AV control unit transmits the meter display signal as the audio status to the combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When combination meter receives the meter display signal, the audio status is displayed on the information display in combination meter.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "NAVIGATION SYSTEM", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The navigation system can be operated by control panel of the AV control unit and display (touch panel) of the AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Guide sound during the operation of the navigation system is output from AV control unit to speakers.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "AV control unit calculates the vehicle location based on the signals from GYRO (angle speed sensor), vehicle sensor, and GPS satellite, as well as the map data. The vehicle location is displayed on the AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "POSITION DETECTION PRINCIPLE", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The navigation system periodically calculates the vehicle\'s current position according to the following three signals:", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Travel distance of the vehicle as determined by the vehicle speed sensor", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Turning angle of the vehicle as determined by the gyroscope (angular velocity sensor)", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Direction of vehicle travel as determined by the GPS antenna (GPS information)", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The current position of the vehicle is then identified by comparing the calculated vehicle position with map data, and indicated on the screen as a vehicle mark. More accurate data is judged and used by comparing vehicle position detection results found by the GPS with the result by map-matching.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The current vehicle position will be calculated by detecting the distance the vehicle moved from the previous calculation point and its direction.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Travel distance", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Travel distance calculations are based on the vehicle speed sensor input signal. Therefore, the calculation may become incorrect as the tires wear down. To prevent this, an automatic distance correction function has been adopted.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Travel direction", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Change in the travel direction of the vehicle is calculated by a gyroscope (angular velocity sensor) and a GPS antenna (GPS information). They have both advantages and disadvantages.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Type", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Advantage", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Disadvantage", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Gyroscope", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "(angular velocity sensor)", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Can detect the vehicle\'s turning angle quite accurately.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Direction errors may accumulate when vehicle is driven for long distances without stopping.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "(GPS information)", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Can detect the vehicle\'s travel direction (North/South/East/West).", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Correct direction cannot be detected when vehicle speed is low.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "More accurate traveling direction is detected because priorities are set for the signals from these two devices according to the situation.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "MAP-MATCHING", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Map-matching compares a current location detected by the method in the “Location Detection Principle” with a road map data.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The vehicle position may not be corrected under the following circumstances and after driving for a certain time when GPS information is difficult to receive. In this case, the vehicle mark on the display must be corrected manually:", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "In map-matching, alternative routes to reach the destination will be shown and prioritized, after the road on which the vehicle is currently driven has been judged and the vehicle mark has been repositioned.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Alternative routes will be shown in different order of priority, and the incorrect road can be avoided if there is an error in distance and/or direction.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Routes are of the same priority if two roads are running in parallel. Therefore, the vehicle mark may appear on either of them alternately, depending on maneuvering of the steering wheel and configuration of the road.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Map-matching does not function correctly when a road on which the vehicle is driving is new and not recorded in the map data, or when road pattern stored in the map data and the actual road pattern are different due to repair.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The map-matching function may find another road and position the vehicle mark on it when driving on a road not present in the map. Then, the vehicle mark may change to it when the correct road is detected.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Effective range for comparing the vehicle position and travel direction calculated by the distance and direction with the road data read from the map data is limited. Therefore, correction by map-matching is not possible when there is an excessive gap between current vehicle position and the position on the map.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "GPS (Global Positioning System)", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "GPS (Global Positioning System) is developed for and is controlled by the US Department of Defense. The system utilizes GPS satellites (NAVSTAR), transmitting out radio waves while flying on an orbit around the earth at an altitude of approximately 21,000 km (13,049 mile).", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The receiver calculates the travel position in three dimensions (latitude/longitude/altitude) according to the time lag of the radio waves that four or more GPS satellites transmit (three-dimensional positioning). The GPS receiver calculates the travel position in two dimensions (latitude/longitude) with the previous altitude data if the GPS receiver receives only three radio waves (two-dimensional positioning). GPS position correction is not performed while stopping the vehicle.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Accuracy of the GPS will deteriorate under the following conditions:", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "In two-dimensional positioning, GPS accuracy will deteriorate when altitude of the vehicle position changes.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The position of GPS satellite affects GPS detection precision. The position detection may not be precisely performed.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The position detection is not performed if GPS receiver does not receive radio waves from GPS satellites. (Inside a tunnel, parking in a building, under an elevated highway etc.) GPS receiver may not receive radio waves from GPS satellites if any object is placed on the GPS antenna.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The detection result has an error of approximately 10 m (32.81 ft) even with a high-precision three dimensional positioning.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "There may be cases when the accuracy is lowered and radio waves are stopped intentionally because the GPS satellite signal is controlled by the US trace control center.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "HANDS-FREE PHONE SYSTEM", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Refer to Owner’s Manual for hands-free phone system operating instructions.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Simply operating the steering switch without releasing hands from the steering wheel allows the driver to receive a phone call.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When a Bluetooth® communication compliant phone is registered to the AV control unit, hands-free phone communication can be performed.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "The content of the memory (telephone book) of the cellular phone can be recorded in the AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When Receiving a Call", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the voice of the other party from a cell phone via Bluetooth® communication, it transmits the TEL voice signal to each speaker.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When a Call Is Originated", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the microphone signal from microphone, it transmits the sound signal to a cell phone via Bluetooth® communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "Hands-Free Phone Indicator", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit recognizes an incoming call from a cell phone via Bluetooth® communication, it transmits the meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When combination meter receives the meter display signal, it displays the incoming call of cell phone on information display.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When an incoming call is received, the driver can operate the steering switch to answer the phone.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When steering switch is operated, the combination meter receives the steering switch signal, and then combination meter transmits the steering switch signal to the AV control unit via AV communication.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "When AV control unit receives the steering switch signal, it activates the hands-free phone.", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "MITSUBISHI CONNECT Services", "title");
si[i++] = gsitm("N5160405X0002T00ENG.html", "MITSUBISHI CONNECT services provides useful functions such as vehicle control app and data download", "ptxt");
si[i++] = gsitm("N5160405X0002T00ENG.html", "A Wi-Fi connection can be made by using an available Wi-Fi network near the vehicle or using the Wi-Fi hotspot function.", "ptxt");
