si[i++] = gsitm("N5160407Y0003200ENG.html", "On Board Diagnosis Function", "title");
si[i++] = gsitm("N5160407Y0003200ENG.html", "The AV control unit on board diagnosis performs the functions listed in the table below:", "ptxt");
si[i++] = gsitm("N5160407Y0003200ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160407Y0003200ENG.html", "The trouble diagnosis function has a self-diagnosis mode for conducting trouble diagnosis automatically and a confirmation/adjustment mode for operating manually.", "ptxt");
si[i++] = gsitm("N5160407Y0003200ENG.html", "The self-diagnosis mode performs diagnoses on the AV control unit connections between system components. Then it displays the diagnosis results on the display.", "ptxt");
si[i++] = gsitm("N5160407Y0003200ENG.html", "The confirmation/adjustment mode allows the technician to check, modify or adjust the vehicle signals and set values as well as to monitor the system error records and system communication status. The checking, modifying or adjusting generally requires human intervention and judgment (the system cannot make judgment automatically).", "ptxt");
si[i++] = gsitm("N5160407Y0003200ENG.html", "The AV control unit on board diagnosis performs the following functions listed in the table below:", "ptxt");
si[i++] = gsitm("N5160407Y0003200ENG.html", "Mode", "ptxt");
