si[i++] = gsitm("N5160407O0002500ENG.html", "Perform self-diagnosis of “MULTI AV” using M.U.T.-III SE. Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5160407O0002500ENG.html", "Skip to step 4 of the diagnosis procedure if “MULTI AV” is not displayed.", "ptxt");
