si[i++] = gsitm("N5160407O0002500ENG.html", "SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5160407O0002500ENG.html", "Perform the applicable diagnosis according to the diagnosis chart by symptom. Refer to .", "ptxt");
si[i++] = gsitm("N5160407O0002500ENG.html", "MALFUNCTIONING PART REPAIR", "title");
si[i++] = gsitm("N5160407O0002500ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160407O0002500ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5160407O0002500ENG.html", "REPAIR CHECK (SELF-DIAGNOSIS WITH M.U.T.-III SE)", "title");
