si[i++] = gsitm("N5160407Q0007000ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "REPLACE AV CONTROL UNIT", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Replace AV control unit. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "PERFORM PROGRAMMING", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Perform AV control unit programming according to the procedure of \"Programming\" in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "12V battery voltage: 12 – 13.5 V (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "CONFIGURATION (AV CONTROL UNIT)", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "M.U.T.-III SE Configuration", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "WRITE VIN DATA (AV CONTROL UNIT)", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "M.U.T.-III SE work support", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "Perform \"WRITE VIN (SAVED DATA)\" or \"WRITE VIN (MANUAL INPUT)\" to write VIN data.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "CHECK NETWORK INITIAL SETTINGS", "title");
si[i++] = gsitm("N5160407Q0007000ENG.html", "M.U.T.-III SE Special Function", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "1. Confirm 90 or more seconds passed after turning ignition switch ON, then select \"Network initial settings\" of \"IVC\".", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "2. Check the \"Radio wave condition\". If it is normal, go to the next step. If the condition is abnormal or cannot be detected, move the vehicle to a place where the radio wave environment is good. Then start from Step 1 again.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "3. Select \"Network initial settings\" of \"MULTI AV\".", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "4. Check the value of \"Network initial setting state\". If \"Completed\" is displayed, the setting is completed. If the value doesn\'t become \"Completed\" in 15 minutes, error may occur in the network setting.", "ptxt");
si[i++] = gsitm("N5160407Q0007000ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "When after replacing primary speaker amp, configuration must be performed. Or not doing so, speaker amp. control function does not operate normally", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "REPLACE PRIMARY SPEAKER AMP.", "title");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "Replace primary speaker amp. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "CONFIGURATION (PRIMARY SPEAKER AMP.)", "title");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "M.U.T.-III SE Configuration", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007D00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "Description", "title");
si[i++] = gsitm("N516040280008000ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the AV control unit.", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the AV control unit.", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "The configuration no need to “save” configuration data from the AV control unit. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N516040280008000ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "Perform writing vehicle specification to AV control unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N5160407Q0007E00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "Description", "title");
si[i++] = gsitm("N516040280008100ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the primary speaker amp.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the primary speaker amp.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE User\'s Manual”.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "The configuration no need to “save” configuration data from the primary speaker amp. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "Perform the procedures indicated in “Configuration”.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "Make sure to check that the chassis number matches. If a wrong number is written, the ECU may not operate normally.", "ptxt");
si[i++] = gsitm("N516040280008100ENG.html", "Perform “Configuration” only for new primary speaker amp. If it is performed for old primary speaker amp, the ECU may not operate normally.", "ptxt");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "Perform writing vehicle specification to primary speaker amp. following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE User\'s Manual.", "ptxt");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE User\'s Manual”.", "ptxt");
si[i++] = gsitm("N5160407Q0007F00ENG.html", "WORK END", "ptxt");
