si[i++] = gsitm("N516040280007R00ENG.html", "Phone’s performance or cellular connection. Disconnect and reconnect your phone.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Phone’s performance or cellular connection. Close all apps and restart them.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Phone’s performance or cellular connection. Cycle phone power off/on to restart.", "ptxt");
