si[i++] = gsitm("N516040280007R00ENG.html", "Cannot access Siri® Eyes Free using \"\" on the steering wheel.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check if a Bluetooth® connection is established between the iPhone and the system.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check if Siri® is enabled on the device. On your phone, go to Siri® setting.", "ptxt");
