si[i++] = gsitm("N516040280007R00ENG.html", "Audio source does not change automatically to iPod or Bluetooth® Audio mode.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "For best results, use the native music app. Performance of music control function while using Podcasts, Audiobook or other third party music apps may vary.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "For best results, play media already stored on your device. Streaming music or playback from cloud storage may degrade performance.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Switch the source manually by pushing \"AUDIO\".", "ptxt");
