si[i++] = gsitm("N516040280007R00ENG.html", "For best results, use the native music app. Performance of music control function while using Podcasts, Audiobook or other third party music apps may vary and is controlled by the device.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Cannot hear any music/audio being played back from a connected iPhone.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check that the audio source is set to Bluetooth® Audio or iPod mode. A USB connection is required for iPod mode.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Cannot hear map turn-by-turn direction guidance from a connected iPhone.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Cannot receive text message notifications on the vehicle audio system.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check if \"Show Notifications\" is enabled on your phone. On your phone, go to Bluetooth® settings. Find the device name, like \"MY CAR\". Touch the  icon on your phone. Turn on \"Show Notifications\".", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Cannot reply to text message notifications using Siri® Eyes Free.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "After receiving an incoming text message, follow the on-screen guidance. Press and hold \"\" on the steering wheel for Siri® Eyes Free. After Siri® Eyes Free starts, say \"Text Message\".", "ptxt");
