si[i++] = gsitm("N516040280007R00ENG.html", "This is because the quantity of the displayed information is reduced so that the screen does not become too cluttered. There is also a chance that names of the roads or locations may be displayed multiple times, and the names appearing on the screen may be different because of a processing procedure.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The location of the vehicle icon is misaligned from the actual position.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The vehicle was transported after the ignition switch was placed in the OFF position, for example, by a ferry or car transporter.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Drive the vehicle for a period of time on a road where GPS/GNSS signals can be received.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The position and direction of the vehicle icon may be incorrect depending on the driving environments and the levels of positioning accuracy of the navigation system.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "This is not a malfunction. Drive the vehicle for a period of time to automatically correct the position and direction of the vehicle icon.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Driving with tire chains or tires that have been replaced may result in an incorrect vehicle location display due to miscalculation by the speed sensor.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Drive the vehicle for a period of time (at approximately 19 MPH (30 km/h) for about 30 minutes) to automatically correct the vehicle icon position.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The map data has a mistake or is incomplete (the vehicle icon position is always misaligned in the same area).", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Updated road information will be included in the next version of the map data.", "ptxt");
