si[i++] = gsitm("N516040280007R00ENG.html", "Route information is not provided for certain types of roads.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The auto reroute calculation (or detour calculation) suggests the same route as the one previously suggested.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Route calculations took priority conditions into consideration, but the same route was calculated.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "A waypoint cannot be added.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Twenty waypoints are already set on the route, including ones that the vehicle has already passed.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "A maximum of 20 waypoints can be set on the route. To go to 21 or more waypoints, perform route calculations multiple times as necessary.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The suggested route is not displayed.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Roads near the destination cannot be calculated.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Reset the destination to a main or ordinary road, and recalculate the route.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The starting point and destination are too close.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Set a more distant destination.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The starting point and destination are too far away.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Divide the trip by selecting one or two intermediate destinations, and perform route calculations multiple times.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "There are time restricted roads (by the day of the week, by time) near the current vehicle location or destination.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Select [Do Not Use Restriction Info] in the [Time Restricted Roads] setting.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "A part of the route is not displayed.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The suggested route includes narrow streets.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The part of the route that the vehicle has already passed is deleted.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "A route is managed by sections between waypoints. If the vehicle passed the first waypoint, the section between the starting point and the waypoint is deleted (it may not be deleted depending on the area).", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "An indirect route is suggested.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "If there are restrictions (such as one-way streets) on roads close to the starting point or destination, the system may suggest an indirect route.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Adjust the location of the starting point or destination.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The system may suggest an indirect route because route calculation does not take into consideration some areas such as narrow streets.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The landmark information does not correspond to the actual information.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "This may be caused by insufficient or incorrect map data.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Updated information will be included in the next version of the map data.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The suggested route does not exactly connect to the starting point, waypoints or destination.", "ptxt");
