si[i++] = gsitm("N516040280007R00ENG.html", "Set the starting point, waypoints and destination on a main road, and perform route calculation.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "VOICE GUIDANCE", "title");
