si[i++] = gsitm("N516040280007R00ENG.html", "Follow all traffic rules and regulations.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "TRAFFIC INFORMATION", "title");
si[i++] = gsitm("N516040280007R00ENG.html", "Traffic information is not displayed.", "ptxt");
