si[i++] = gsitm("N516040280007R00ENG.html", "The subscription to SiriusXM TrafficTM is incomplete, or the subscription to SiriusXM TrafficTM has expired.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check the subscription status of SiriusXM TrafficTM.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The map scale is set at a level where the display of icons is impossible.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Check that the map scale is set at a level in which the display of icons is possible.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "With the automatic detour route turned on, no detour route is set to avoid congested areas.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "There is no faster route compared to the current route, based on the road network and the traffic information.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The automatic detour search is not intended for avoiding traffic jams. It searches for the fastest route taking conditions such as traffic jams into consideration. Follow the current route.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The route does not avoid a road section with traffic information stating that it is closed due to road construction.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The navigation system is designed not to avoid this event because the actual period of closure may differ from the declared roadwork period.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Observe the actual road conditions and follow the instructions on the road for a detour when necessary. If the road is closed, use the detour function and set the detour distance to avoid the road section that is closed.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "VOICE RECOGNITION", "title");
si[i++] = gsitm("N516040280007R00ENG.html", "The system does not operate or fails to interpret the command correctly.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The interior of the vehicle is too noisy.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Close the windows or have the other occupants be quiet.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The voice command is spoken in a low voice.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak the command in a louder voice.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The timing of speaking a command is too early.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak the command after confirming the following: a voice guidance is announced, a tone sounds, and an icon on the screen changes from gray to orange.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The command is spoken too slowly.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak in a natural voice without pausing between words.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The system prompts to repeat a command.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Pronunciation is unclear.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak clearly.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The command is spoken too late after the tone.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak the command within 5 seconds after confirming the following: a voice guidance is announced, a tone sounds, and an icon on the screen changes from gray to orange.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "An improper command is spoken.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak the command or a number that is displayed on the screen.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Speak a command that is shown in the command list.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The system does not correctly recognize a number spoken.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Too many numbers are spoken at once.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Place a pause between the appropriate digits for correct recognition by the system. When speaking a telephone number, place a pause between area codes, dial codes, etc.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "USB memory device cannot be operated with voice commands.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Depending on the device, iPhone or iPod may be recognized as a USB memory device.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "This is not malfunction", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The USB/iPod operation screen is grayed out.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The audio device is not connected.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Connect an audio device to the system.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "An error message is displayed when trying to select a track and operate USB/iPod.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The track information is being processed for registration by the system.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Song information will be loaded into the system when a new audio device is registered for the first time or when the song information in the pre-registered device has been changed. Please wait for the loading to complete which may take a few minutes to up to an hour.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "A number of songs exceeding the amount the device can contain are stored in the connected audio device.", "ptxt");
