si[i++] = gsitm("N516040280007R00ENG.html", "No song is stored in the audio device.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "Store songs in the connected audio device. Storing songs with information such as artist name, album name, song name, playlist, etc., will make voice recognition song search available.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "The system does not correctly recognize a Point of Interest (POI) name spoken.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "There are some rare cases where a POI search is unavailable by speaking the facility name but the location can be found on the map.", "ptxt");
si[i++] = gsitm("N516040280007R00ENG.html", "This is not a malfunction. Consider using an alternate search method, like street address.", "ptxt");
