si[i++] = gsitm("N516040BU0000I00ENG.html", "AV Control unit", "title");
si[i++] = gsitm("N516040BU0000I00ENG.html", "Component Function Within the System", "title");
si[i++] = gsitm("N516040BU0000I00ENG.html", "AV control unit is located in the center of the instrument panel assembly.", "ptxt");
si[i++] = gsitm("N516040BU0000I00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040BU0000I00ENG.html", "AV control unit integrates the following functions, and controls the rear view monitor system.", "ptxt");
si[i++] = gsitm("N516040BU0000I00ENG.html", "Unit equipped", "ptxt");
si[i++] = gsitm("N516040BU0000I00ENG.html", "Display", "ptxt");
