si[i++] = gsitm("N516040BU0000I00ENG.html", "Rear view camera is installed to the center of liftgate.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Rear View Camera", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "The rear view camera converts the vehicle rear image into analog signal, and outputs it to AV control unit.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "The rear view camera converts image information photographed through a lens into analog signal and outputs it.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Specification", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Image sensor optical size", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "1/4-inch", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Effective number of pixels", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Approx. 307,200 pixels (640 × 480)", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Angle of view", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Horizontal view angle: 145 ± 2.0°", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Vertical view angle: 120 ± 2.0°", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "A power supply is supplied from AV control unit in ignition switch ON position, and outputs the vehicle rear image signal to the AV control unit.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "When a image is not displayed, the camera outputs a image signal to regular AV control unit.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Rear view camera is installed to the center of liftgate.", "ptxt");
si[i++] = gsitm("N516040BV0000I00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "System Description", "title");
