si[i++] = gsitm("N5160405X0002U00ENG.html", "AV control unit", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "AV Control Unit", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Rear view camera", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "TCM", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Transmits the shift position signal to the AV control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Steering angle sensor", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Transmits the steering angle signal to the AV control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "AV control unit Input Signal (AV Communication)", "title");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Transmit unit", "ptxt");
si[i++] = gsitm("N5160405X0002U00ENG.html", "Signal name", "ptxt");
