si[i++] = gsitm("N5160407O0002600ENG.html", "INTERVIEW AND SYMPTOM CONFIRMATION", "title");
si[i++] = gsitm("N5160407O0002600ENG.html", "Check the malfunction symptoms by performing the following items.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Interview the customer to obtain the malfunction information (conditions and environment when the malfunction occurred).", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Check the symptom.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Is the occurred symptom malfunction?", "question");
si[i++] = gsitm("N5160407O0002600ENG.html", "YES", "result");
