si[i++] = gsitm("N5160407O0002600ENG.html", "DIAGNOSIS WITH M.U.T.-III SE", "title");
si[i++] = gsitm("N5160407O0002600ENG.html", "Connect M.U.T.-III SE and perform a self-diagnosis for “MULTI AV”. Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Skip to step 4 of the diagnosis procedure if “MULTI AV” is not displayed.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "When DTC is detected, follow the instructions below:", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Record DTC and Freeze Frame Data.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Is DTC displayed?", "question");
si[i++] = gsitm("N5160407O0002600ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "TROUBLE DIAGNOSIS FOR DTC", "title");
si[i++] = gsitm("N5160407O0002600ENG.html", "Check the DTC indicated in the “Self-Diagnosis Results”.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Perform the relevant diagnosis referring to the DTC Index. Refer to .", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "TROUBLE DIAGNOSIS FOR SYMPTOMS", "title");
si[i++] = gsitm("N5160407O0002600ENG.html", "Perform the relevant diagnosis referring to the diagnosis chart by symptom. Refer to .", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "ERROR PART REPAIR", "title");
si[i++] = gsitm("N5160407O0002600ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Perform a self-diagnosis for “MULTI AV” with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Erase the stored self-diagnosis results after repairing or replacing the relevant components if any DTC has been indicated in the “Self-Diagnosis Results”.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Check that the symptom does not occur.", "ptxt");
si[i++] = gsitm("N5160407O0002600ENG.html", "Does the symptom occur?", "question");
si[i++] = gsitm("N5160407O0002600ENG.html", "GO TO 1.", "ptxt");
si[i++] = gsitm("N5160402E002Z600ENG.html", "Diagnosis Procedure", "title");
