si[i++] = gsitm("N516040C00000I00ENG.html", "Multi-around Monitor Control Unit", "title");
si[i++] = gsitm("N516040C00000I00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N516040C00000I00ENG.html", "Multi-around monitor control unit control a multi-around monitor system.", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040C00000I00ENG.html", "Necessary signals are transmitted/received to/from control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "Supplies a power supply to each camera.", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "Camera image signals received from each camera are converted/synthesized in the multi-around monitor control unit and transmitted to the AV control unit by LVDS.", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "LVDS (Low Voltage Differential Signaling): LVDS is differential signaling system, meaning that it transmits information as the difference between the voltages on a pair of wire, the two wire voltages are compared at the receiver.", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N516040C00000I00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516040C00000I00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N516040C00000I00ENG.html", "Multi-around monitor control unit is located in the center console box.", "ptxt");
si[i++] = gsitm("N516040C10000J00ENG.html", "Front Camera", "title");
si[i++] = gsitm("N516040C10000J00ENG.html", "Component Function Within The System", "title");
