si[i++] = gsitm("N5160405X0002V00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "This system is equipped with wide-angle high-resolution cameras on the front and rear of the vehicle and on both right and left door mirrors. The images from front view, rear view, front-side view passenger side, and birds-eye view that shows the view from the top of the vehicle are displayed to monitor the vehicle surroundings.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit cuts out and expands the image received from each camera to create each view.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The sonar indicator is displayed on display (superimposed on the camera image) in combination with the sonar system to warm of the approach of an obstacle.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Camera image is displayed on the display when an obstacle is detected by sonar system.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "In front view and rear view, the vehicle width, distance lines and predictive course lines are superimposed and displayed. In front-side view, the vehicle distance guiding line and vehicle width guiding line are displayed.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The Birds-Eye view converts the images from 4 cameras into the overhead view and displays the status of the vehicle on display. The vehicle icon and sonar indicator that are displayed on the Birds-Eye view display are rendered by multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Moving Object Detection (MOD) is adopted that detects moving objects according to camera image and notifies the detection result to the driver.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front/rear wide view function is adopted. Visibility for the left and right that contains invisible area is improved.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "MULTI-AROUND MONITOR SCREEN", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor combines and displays the travel direction view and \"Birds-Eye view\", \"Front-Side view\" and then it displays the sonar indicator on the \"Birds-Eye view\", \"Front-Side view\", \"Front wide view\" and \"Rear wide view\".", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit renders the view icon, warning message on display.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Screen Constitution (Models with Invisible Area)", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Screen Constitution (Models without Invisible Area)", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The presence or absence of the invisible area depends on the sonar specifications.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor screen transition", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor is displayed on the display when \"CAMERA\" switch is pressed, when shifting position is reverse, or when an obstacle is detected by sonar system.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view, Front-side view, and front/rear wide view can be switched by \"CAMERA\" switch, while multi-around monitor is displayed.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "While shift position is other than reverse, multi-around monitor is cancelled when approximately 3 minutes are passed after \"CAMERA\" switch is pressed, or when vehicle speed is approximately 10 km/h (6 MPH) or more. The screen returns to the screen before displaying multi-around monitor.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Setting of Moving Object Detection (MOD) and sonar can be switched ON/OFF by combination meter.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "In Birds-Eye view, an enhanced boundary is displayed on the image indicating the invisible area and clearly indicating the boundary of the 4 cameras. The invisible area is displayed in yellow when Birds-Eye view is displayed after the ignition switch is turned ON. (Models with invisible area)", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "In D position, front sonar can detect an obstacle while camera image is not displayed on AV control unit. Screen is switched to camera image when an obstacle is detected.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When \"CAMERA\" switch is pressed, it receives camera switch signal from AV control unit via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When multi-around monitor control unit receives camera switch signal, multi-around monitor control unit reads the image signal from each camera.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When multi-around monitor control unit receives reverse signal, while shift position is R position, multi-around monitor control unit reads image signal from each camera by LVDS.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When multi-around monitor control unit reads image signal from each camera, it cuts out the required screen for each view, superimposes camera image, vehicle icon, guiding lines, predicted course line, \"MOD\" icon, and sonar indicator, and then outputs them to AV control unit by LVDS.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front View", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The front view image is from the front camera.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When the selector lever is in any position other than the reverse position, the front view is displayed by pressing the \"CAMERA\" switch. It improves the visibility of obstacles in front of the vehicle and helps driving by the images displayed from Birds-Eye view and Front-Side view. The front wide view function allows the display of an image with an approximately 180° horizontal angle.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Display the vehicle width guiding line and vehicle distance guiding line in front view and display the predictive course line according to the steering angle.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "If the steering angle is within approximately 90 degrees, the predictive course lines on the left/right side are displayed. If the steering angle is exceeding approximately 90 degrees, only the predictive course line on the outside (in the opposite side of steering direction) is displayed.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit receives the steering angle signal from ABS actuator and electric unit (control unit) via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit controls the direction of the predictive course line according to the steering sensor angle signal.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front view guiding lines", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Rear View", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The rear view image is from the rear camera.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "When the selector lever is in the reverse position, the rear view is displayed. Backing and parking are improved by the images from Birds-Eye view and Front-Side view. The rear wide view function allows the display of an image with an approximately 180° horizontal angle.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Display the vehicle width guiding line and vehicle distance guiding line in rear view and display the predictive course line according to the steering angle.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The predictive course line is not displayed at the steering neutral position.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit controls the direction and distance of predictive course line according to the steering angle sensor signal.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Rear view guiding lines", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front-side View", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The front-side view image is from the side camera RH.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "In front-side view, display the vehicle distance guiding line and vehicle width guiding line.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front-side view area and guiding line", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-eye View", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "The image from the 4 cameras is cut out and converted into the overhead view, and the surroundings of the vehicle is displayed in birds-eye view.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "In Birds-Eye view, the invisible area is displayed on the image to specify the boundary of the 4 cameras. (Models with invisible area)", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view display image", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view display area (Models with Invisible Area)", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view display area (Models without Invisible Area)", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Moving Object Detection (MOD)", "title");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Moving Object Detection (MOD) is a function that notifies the driver of the presence of moving objects in the area around the vehicle. MOD detects moving objects from camera image, illuminates frame of view in yellow whenever \"MOD\" icon is displayed in green, and sounds tone alarm.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "MOD detects moving objects while camera image is displayed on AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit performs the following process when moving objects are detected.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Superimposes yellow frame line on camera image signal and outputs them to AV control unit by LVDS.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Transmits MOD beep sound output request signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Combination meter that receives the MOD beep sound output request signal from multi-around monitor control unit, and outputs tone alarm drive signal to tone alarm.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Multi-around monitor control unit detects moving objects from camera image according to an image recognition method called optical flow.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "MOD does not detect a background as a moving object when the vehicle moves (when whole screen moves), but detects a moving object when an actual moving object is displayed on screen.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "MOD can be set to permanent OFF by the following operation.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Permanent OFF: Settings can be performed on the information display of the combination meter.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Color of \"MOD\" icon indicates whether or not MOD is operative. \"MOD\" icon is displayed as shown in the following table. when MOD is operative, \"MOD\" icon is displayed in green. when MOD is not operative, \"MOD\" icon is displayed in gray. MOD icon is not displayed when MOD is OFF by \"Settings\".", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "View", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Shift position", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "P or N position", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "D position", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "R position", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "\"MOD\" icon display", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view and front view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Birds-Eye view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Green", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Gray", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "–", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Side view and front view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Side view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "×", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Rear wide view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Front wide view", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "×: Icon is not displayed.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "–: View is not displayed in each shift position (D position and R position).", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "MOD illuminates frame of view in yellow and sounds tone alarm, when any of the conditions in the following table are satisfied.", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "Operation Condition", "ptxt");
si[i++] = gsitm("N5160405X0002V00ENG.html", "View where MOD is operative", "ptxt");
