si[i++] = gsitm("N516040280007S00ENG.html", "When replacing the multi-around monitor control unit, always replace it with a new one. Multi-around monitor system does not operate properly in case of reuse of the multi-around monitor control unit from another vehicle.", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "When before writing the multi-around monitor control unit configuration, always writing the MAC key.", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "Perform the following operations when replacing multi-around monitor control unit. For details, refer to .", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N516040280007S00ENG.html", "When after replacing multi-around monitor control unit, the following items must be performed. Or not doing so, multi-around monitor system does not operate normally.", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "Writing MAC key", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "Configuration", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "Camera calibration", "ptxt");
si[i++] = gsitm("N516040280007S00ENG.html", "Factory mode OFF", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Perform the following procedures after replacing the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "REPLACE MULTI-AROUND MONITOR CONTROL UNIT", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Replace multi-around monitor control unit. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "WRITING MAC KEY", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Perform MAC key writing. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "PERFORM CONFIGURATION", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "When before writing the multi-around monitor control unit configuration, always writing the MAC key.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "WRITING OF CALIBRATION DATA", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Write the calibration data stored in the camera using M.U.T.-III SE. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Perform the self-diagnosis of multi-around monitor control unit with M.U.T.-III SE (Multi Around Monitor).", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Check if any DTC is detected.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N5160407Q0007100ENG.html", "YES", "result");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Perform the trouble diagnosis for the detected DTC. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "NO", "result");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "OPERATION CHECK", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Confirm that the operation of the multi-around monitor and the camera image (reference line, expected route) are normal.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Change the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"Multi Around Monitor\".", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N5160407Q0007100ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N516040280007T00ENG.html", "Description", "title");
si[i++] = gsitm("N516040280007T00ENG.html", "When replacing multi-around monitor control unit, it is necessary to write MAC key to multi-around monitor control unit. Write MAC key to multi-around monitor control unit according to \"MAC Key writing\" procedure of \"M.U.T.-III SE Operation Manual\". Refer to .", "ptxt");
si[i++] = gsitm("N516040280007T00ENG.html", "During MAC key writing, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N516040280007T00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N516040280007T00ENG.html", "M.U.T.-III SE is connected to internet", "ptxt");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "PERFORM MAC KEY WRITING", "title");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "Select \"MAC Key writing\" on \"Special Function\" of \"Multi Around Monitor\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "Touch \"Write\".", "ptxt");
si[i++] = gsitm("N5160407Q0007G00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "Description", "title");
si[i++] = gsitm("N516040280007U00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "The configuration no need to “save” configuration data from the multi-around monitor control unit. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N516040280007U00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N5160407Q0007200ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007200ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5160407Q0007200ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007200ENG.html", "Perform writing vehicle specification to multi-around monitor control unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5160407Q0007200ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5160407Q0007200ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N5160407Q0007200ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "Diagnosis Procedure", "title");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "If only the multi-around monitor control unit is replaced, the calibration data stored in the camera can be written to the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "WORK PROCEDURE", "title");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "WRITE CALIBRATION DATA", "title");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "Select \"CALIBRATING CAMERA IMAGE\" of \"Special Function\" mode using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "After displaying the status, check that the status is displayed as \"Normal\".", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "Is the status of each camera displayed as \"Normal\"?", "question");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "YES", "result");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "NO", "result");
si[i++] = gsitm("N5160402E002ZP00ENG.html", "Calibrate the camera that is not displayed as \"normal\". Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Calibration must be performed after removing/replacing the cameras, removing parts (e.g. front grille, door mirror, and others) mounted on the cameras, or replacing the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "The use of M.U.T.-III SE is required to perform calibration or writing of calibration results to the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Align the white lines on the road near the vehicle at the boundary of each camera image by this camera calibration. The white lines far from the vehicle may not be aligned at the boundary of each camera image. The farther the line, the greater the difference is.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Following the flowchart shown in the figure, perform the calibration.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "When multi-around monitor control unit is replaced, Write the calibration data before performing this calibration. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "CHECK MULTI-AROUND MONITOR SCREEN", "title");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Check that there is no indication of \"Incomplete calibration\".", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "View in the incomplete calibration state is indicated by \"\" on the multi-around monitor.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Is the \"Incomplete calibration\" display visible?", "question");
si[i++] = gsitm("N5160407Q0007300ENG.html", "YES", "result");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "NO", "result");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "PERFORM SIMPLIFIED CONFIRMATION BY BIRDS-EYE VIEW SCREEN", "title");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Check the gap between each camera image on a birds-eye view screen.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Is the gap between each camera image exist?", "question");
si[i++] = gsitm("N5160407Q0007300ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "CONFIRMATION OF SPECIAL SERVICE TOOL", "CONFIRMATIONOFSPECIALSERVICETOOL-E7FE1743");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Do you use laser markers?", "question");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "PREPARATION OF TARGET LINE 1", "PREPARATIONOFTARGETLINE1-8094BDA6");
si[i++] = gsitm("N5160407Q0007300ENG.html", "If a target line is narrow, it is hard to confirm it with multi-around monitor screen. The width of the target line recommends an approximately 5.0 - 10.0 cm.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "It is easy to confirm a target line on an multi-around monitor screen when a target line is drawn with a color opposite to a working floor.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Example", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Floor is blue: target line is yellow", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Floor is green: target line is red", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Drawing target line 1", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Irradiate laser beam  to pass throw the center of vehicle (such as center of emblem) by using Laser marker (KV9912-0000)", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put the packing tape  on the front end of vehicle and mark the spot  on where laser beam irradiation line passes.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ":Laser beam irradiation line.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put packing tape  on the ground and draw line  along the laser beam irradiation line .", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Area around the front end of vehicle.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Slide Laser marker in 45 degree  away.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Irradiate laser beam  and adjust laser beam irradiation line to pass through the marked point  on the front end of the vehicle.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Draw line  along the laser beam irradiation line which passes through the packing tape put on grand and mark FM0 where the line  and  are crossed.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Apply the same procedure of front side to rear side and mark RM0.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Route the vinyl string under the vehicle, and then pull and fix it on the point approximately 1.0 m to the front and rear of the vehicle through the points FM0 and RM0 using packing tape.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "A", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Approx.1.0 m", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Mark the points FM and RM (mark) 75 cm away from each point, FM0 and RM0.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Approx. 75 cm", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Laser marker also emits red laser from the bottom. Align the red laser with point FM and adjust the laser beam to aim the center of vehicle.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Irradiate laser beam irradiation line  in 90 degree from Laser marker. Route the vinyl string  along the laser beam irradiation line and fix it on the point approximately 1.5 m away from the point FM using packing tape.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Approx. 1.5 m", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Rotate Laser marker to face the center line of the vehicle and rotate again in 90 degree . Route the vinyl string  along the laser beam irradiation line and fix it on the point approximately 1.5 m away from the point FM using packing tape.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Apply the same procedure of front side to rear side and fix the vinyl strings to the ground.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Mark the points FL, FR, RL, and RR (mark) to both right and left (vehicle width / 2 + 30 cm) from the points FM and RM.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Approx. 30 cm", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Draw the lines of the points FL – RL and FR – RR with vinyl string, and fix it with packing tape.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Irradiate laser beam  vertically from Laser marker to pass through the center of wheel.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put packing tape  on fender and mark point  on laser beam irradiation line.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put packing tape  on the ground and draw line  along laser beam irradiation line.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Adjust the laser beam  to pass through the marked point  on fender.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Draw line  along the laser beam irradiation line which passes through the packing tape put on grand and mark  (the center of the axle) where the line  and  are crossed.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Perform the same operation to rest of three wheels.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Route the vinyl string vertically through the lines of the points FL – RL and FR – RR using a triangle scale and fix it on the point approximately 60 cm away from center of axel  using packing tape. Drawing target line 1 is completed.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", ": Approx. 60 cm", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Indication of \"Incomplete calibration\"", "result");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "No indication of \"Incomplete calibration\"", "result");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "PERFORM \"CALIBRATING CAMERA IMAGE\"", "PERFORMCALIBRATINGCAMERAIMAGE-8094DBFF");
si[i++] = gsitm("N5160407Q0007300ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Select \"CALIBRATION\" in \"Special Function\" mode of \"Multi Around Monitor\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "In random order, perform the operation for all cameras for which un-match display  appears.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Front camera: \"CALIBRATING CAMERA IMAGE (FRONT CAMERA)\"", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Side camera RH: \"CALIBRATING CAMERA IMAGE (RIGHT CAMERA)\"", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Side camera LH: \"CALIBRATING CAMERA IMAGE (LEFT CAMERA)\"", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Rear camera: \"CALIBRATING CAMERA IMAGE (REAR CAMERA)\"", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Perform \"CALIBRATING CAMERA IMAGE (****)\" as per the following procedure.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Adjust the parameters in \"AXIS X\", \"AXIS Y\" and \"Pattern\" to place the calibration marker shown on the display on the target line on the ground.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Adjust the parameter in \"High\" so that size of the target line and calibration marker are matched.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "After Status become \"APPLIED\", the adjustment result is displayed on the display. If there are still gap between the target line and the calibration marker after the adjustment, adjust the parameters in \"AXIS X\", \"AXIS Y\", \"Pattern\" and \"High\", and touch \"Retry\" for additional adjustment.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Never perform other operations while \"PROCESSING\" is displayed in Status.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Touch \"OK\" when \"APPLIED\" is displayed in Status.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Touch \"OK\" button on the M.U.T.-III SE screen. Adjustment results are written to the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "PERFORM \"FINE TUNING OF BIRDS-EYE VIEW\" (1)", "PERFORMFINETUNINGOFBIRDS-EYEVIEW1-8094E364");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Select \"FINE TUNING OF BIRDS-EYE VIEW\" in \"Special Function\" mode of \"Multi Around Monitor\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Perform \"FINE TURNING OF BIRDS-EYE VIEW\" as per the following procedure.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Perform adjustment operation slowly because approximately 1 second is required for changing image on screen.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Touch \"Next camera\" to select a camera to be adjusted.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Never perform other operations while \"Switching camera\" is displayed in Selected Camera.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Touch \"OK\" on the M.U.T.-III SE screen. Adjustment results are written to the multi-around monitor control unit.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Is the gap between the each camera image normal?", "question");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "PREPARATION OF TARGET LINE 2", "PREPARATIONOFTARGETLINE2-8094F2D3");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Draw target line 2  at the position of the approximately 1.0 m outside from target line 1  which established by procedure 3.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "The white lines far from the vehicle may not be aligned at the boundary of each camera image. The farther the line, the greater the difference is. can adjust it in detail by drawing a target line 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "\"PERFORM \"FINE TUNING OF BIRDS-EYE VIEW\" (2)", "PERFORMFINETUNINGOFBIRDS-EYEVIEW2-8094FA38");
si[i++] = gsitm("N5160407Q0007300ENG.html", "This adjustment merges the boundary line of each camera image which was not able to adjust by \"FINE TUNING OF BIRDS-EYE VIEW\" (1).", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Confirm the gap of the boundary of target line 2 between the camera image and change the parameter in \"AXIS X\", \"AXIS Y\", \"Pattern\" and \"High\", and adjust the gap of the target line 2 boundary.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "After Status become \"APPLIED\", the adjustment result is displayed on the display. If there are still gap between target line 2 boundary after the adjustment, adjust the parameters in \"AXIS X\", \"AXIS Y\", \"Pattern\" and \"High\", and touch \"Retry\" for additional adjustment.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "If a target line is narrow, it is hard to confirm it with multi-around monitor screen. The width of the target line recommends an approximately 5.0 - 10.0 cm (1.97 - 3.94 in).", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "It is easy to confirm a target line on an multi-around monitor screen when draw a target line with a color opposite to a working floor.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Preparation of target line 1", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Hang a string with a weight as shown in the figure. Put the points FM0, RM0 (mark) on the ground at the center of the vehicle front end and rear end with white packing tape or a pen.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Thread", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Weight", "ptxt");
