si[i++] = gsitm("N5160407Q0007300ENG.html", "Point RM0 (mark)", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Packing tape (to fix the vinyl string)", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Vinyl string", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put the points FM and RM (mark) 75 cm from the points FM0 and RM0 individually.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Route the vinyl string through the points FM and RM using a triangle scale, and then fix it at approximately 1.5 m on both sides with packing tape.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Approx. 1.5 m", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put the points FL, FR, RL, and RR (mark) to both right and left (vehicle width / 2 + 30 cm) from the points FM and RM.", "ptxt");
si[i++] = gsitm("N5160407Q0007300ENG.html", "Put a mark on the center of each axle , draw vertical lines to the lines of the points FL – RL and FR – RR from the marks on the center of the axle using a triangle scale, and then fix the lines using packing tape.", "ptxt");
