si[i++] = gsitm("N516040280008200ENG.html", "Some menu items become unavailable while the vehicle is driven.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Park the vehicle in a safe location, and then operate the navigation system.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Locations stored in the Address Book and other memory functions may be lost if the vehicle\'s battery is disconnected or becomes discharged. If this occurs, service the vehicle\'s battery as necessary and re-enter the information in the Address Book.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "RELATED TO SONAR", "title");
si[i++] = gsitm("N516040280008200ENG.html", "Unstable object detection", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "The vehicle is on a rough surface, such as stone or gravel.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When used in poor weather conditions, such as heavy snow/rain or strong wind.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When subjected to an ultrasonic noise generated from exhaust muffler or brakes.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When left standing in the hot sun or in a cold climate.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When the surface of the sensor is frozen or covered with snow/dirt/moisture.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When a retrofitted xenon light, lighted license plate, or harness is close to the sensor body or sensor harness.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "When subjected to loop coil noises generated from a vehicle detector placed at an intersection or coin parking area.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Object undetectable", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Air-containing objects, such as cloth, cotton, glass wool, dust, and snow.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Thin objects, such as rope, chain, and wire.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Smooth-faced objects placed in a slanting direction.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "Fast-moving small animals.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "A corner of an angular object.", "ptxt");
si[i++] = gsitm("N516040280008200ENG.html", "If the sensor detection part is scratched, obstacles cannot be detected.", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000SV00ENG.html", "Perform \"Configuration\" to save or print current vehicle specification when before replacing multi-around monitor control unit. For details, refer to .", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "When you replace the multi-around monitor control unit, you should teach the multi-around monitor control unit for the multi-around monitor by writing a learned value. On completion, you should check the camera image on the multi-around monitor \"Bird\'s eye-view\". If necessary, calibrate the camera (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N51604052000SV00ENG.html", "Center console assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "Removal Steps", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", ">>A&lt;&lt;", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "1.", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "Ground bolt", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "2.", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "Multi-around monitor control unit", "ptxt");
si[i++] = gsitm("N51604052000SV00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N51604052000SV00ENG.html", ">>A&lt;&lt; MULTI-AROUND MONITOR CONTROL UNIT MOUNTING BOLT (GROUND BOLT) INSTALLATION", "title");
si[i++] = gsitm("N51604052000SV00ENG.html", "Check the head mark \"E\" and install the ground bolt.", "ptxt");
si[i++] = gsitm("N51604052000SW00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000SW00ENG.html", "When you remove/install or replace the camera, you should check the camera image on the multi-around monitor \"Bird\'s eye-view.\" If necessary, calibrate the camera (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SW00ENG.html", "To ensure the camera image is clearly visible, wipe the lens with a damped rag and then a dry rag to remove dust, rain drops or snow.", "ptxt");
si[i++] = gsitm("N51604052000SW00ENG.html", "Be careful not to damage the camera. Any damage may have an adverse effect on the screen image.", "ptxt");
si[i++] = gsitm("N51604052000SW00ENG.html", "Pre-removal and Post-installation Operation", "title");
si[i++] = gsitm("N51604052000SW00ENG.html", "Front Bumper Assembly Removal and Installation (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SX00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000SX00ENG.html", "When you remove/install or replace the camera, you should check the camera image on the multi-around monitor \"Bird\'s eye-view.\" If necessary, calibrate the camera (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SX00ENG.html", "To ensure the camera image is clearly visible, wipe the lens with a damped rag and then a dry rag to remove dust, rain drops or snow.", "ptxt");
si[i++] = gsitm("N51604052000SX00ENG.html", "Be careful not to damage the camera. Any damage may have an adverse effect on the screen image.", "ptxt");
si[i++] = gsitm("N51604052000SX00ENG.html", "For how to remove the Rear camera, refer to .", "ptxt");
si[i++] = gsitm("N51604052000SY00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N51604052000SY00ENG.html", "When you remove/install or replace the camera, you should check the camera image on the multi-around monitor \"Bird\'s eye-view.\" If necessary, calibrate the camera (Refer to ).", "ptxt");
si[i++] = gsitm("N51604052000SY00ENG.html", "To ensure the camera image is clearly visible, wipe the lens with a damped rag and then a dry rag to remove dust, rain drops or snow.", "ptxt");
si[i++] = gsitm("N51604052000SY00ENG.html", "Be careful not to damage the camera. Any damage may have an adverse effect on the screen image.", "ptxt");
si[i++] = gsitm("N51604052000SY00ENG.html", "For how to remove the side camera, refer to .", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "Precaution for Supplemental Restraint System (SRS) \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\"", "title");
si[i++] = gsitm("N5160407Z0002900ENG.html", "The Supplemental Restraint System such as \"AIR BAG\" and \"SEAT BELT PRE-TENSIONER\", used along with a front seat belt, helps to reduce the risk or severity of injury to the driver and front passenger for certain types of collision.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "Information necessary to service the system safely is included in the \"SRS AIR BAG\" and \"SEAT BELT\" of this Service Manual.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "Always observe the following items for preventing accidental activation.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "To avoid rendering the SRS inoperative, which could increase the risk of personal injury or death in the event of a collision that would result in air bag inflation, it is recommended that all maintenance and repair be performed by an authorized Mitsubishi Motors dealer.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "Improper repair, including incorrect removal and installation of the SRS, can lead to personal injury caused by unintentional activation of the system. For removal of Spiral Cable and Air Bag Module, see \"SRS AIR BAG\".", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "Never use electrical test equipment on any circuit related to the SRS unless instructed to in this Service Manual. SRS wiring harnesses can be identified by yellow harnesses or harness connectors.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "PRECAUTIONS WHEN USING POWER TOOLS (AIR OR ELECTRIC) AND HAMMERS", "title");
si[i++] = gsitm("N5160407Z0002900ENG.html", "When working near the Air Bag Diagnosis Sensor Unit or other Air Bag System sensors with the ignition/power switch ON or engine running, never use air or electric power tools or strike near the sensor(s) with a hammer. Heavy vibration could activate the sensor(s) and deploy the air bag(s), possibly causing serious injury.", "ptxt");
si[i++] = gsitm("N5160407Z0002900ENG.html", "When using air or electric power tools or hammers, always switch the ignition/power switch OFF, disconnect the 12V battery or batteries, and wait at least 3 minutes before performing any service.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N5160404P0002R00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing \"How to disconnect 12V battery terminal\" described below.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N5160404P0002R00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
