si[i++] = gsitm("N516040610001300ENG.html", "TCU", "title");
si[i++] = gsitm("N516040610001300ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N516040610001300ENG.html", "The TCU is a device that allows the vehicle to be connected with the Vehicle Owner giving them remote control access to their vehicle and information.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040610001300ENG.html", "A Network Access Device and an eSIM are built into the TCU that facilitates the connection with the network and allow for the data to be transferred.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "Component Operation", "title");
si[i++] = gsitm("N516040610001300ENG.html", "The TCU receives information request from the registered remote device (cellular handset) via SMS* using the signal provided by the telematics antenna.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "*: SMS stands for Short Message Service. It is also referred to as Text Messaging, Short Mail, etc. It is the service that performs text based message communication.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "TCU is connected to the AV control unit with the USB harness for sound signal input/output and data communication between them.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "VIN information necessary for the TCU to ensure that the connected services are activated and initialized as required.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "Sound signals received during an operator call are transmitted from TCU to each speaker via the AV control unit.", "ptxt");
si[i++] = gsitm("N516040610001300ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N516040610001300ENG.html", "Telematics Control Unit (TCU) is installed in the instrument panel. Refer to .", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Telematics Switch", "title");
si[i++] = gsitm("N516040840000P00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N516040840000P00ENG.html", "The telematics switch is connected to TCU and transmits an operation signal.", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Models without sunroof", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Models with sunroof", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040840000P00ENG.html", "Inputs the operating status of the switch to the TCU.", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Turns ON / Blinks / turns OFF the LED according to the signal from the TCU.", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N516040840000P00ENG.html", "The state of LED (ON/Blink/OFF) shows the status of SOS call.", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "LED ON", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", ":SOS Call available", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "LED Blink", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", ":SOS Call in communication", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "LED OFF", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", ":Out of service area or system error", "ptxt");
si[i++] = gsitm("N516040840000P00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N516040840000P00ENG.html", "The Telematics switch is located on the map light assembly. Refer to .", "ptxt");
si[i++] = gsitm("N5160407X0001600ENG.html", "Microphone", "title");
si[i++] = gsitm("N5160407X0001600ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N5160407X0001600ENG.html", "The microphone is used to talk to the operator.", "ptxt");
si[i++] = gsitm("N5160407X0001600ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N5160407X0001600ENG.html", "Microphone converts sound to electric signal.", "ptxt");
si[i++] = gsitm("N5160407X0001600ENG.html", "Component Operation", "title");
si[i++] = gsitm("N5160407X0001600ENG.html", "The power is supplied from the TCU to the microphone, transmitting sound signals to the TCU.", "ptxt");
si[i++] = gsitm("N5160407X0001600ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N5160407X0001600ENG.html", "The microphone is installed on the map light assembly. Refer to .", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "Telematics Antenna", "title");
si[i++] = gsitm("N516040830000O00ENG.html", "Component Function Within The System", "title");
si[i++] = gsitm("N516040830000O00ENG.html", "Ensure the transmission and reception performance of the information necessary for the telematics system.", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "Individual Component Function", "title");
si[i++] = gsitm("N516040830000O00ENG.html", "The telematics antenna consists of the TEL antenna and GPS antenna.", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "Component Operation", "title");
si[i++] = gsitm("N516040830000O00ENG.html", "Power is supplied from the TCU.", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "Amplify radio waves received from GPS satellites and transmit them to the TCU as GPS signals.", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "GPS signal is time information required for timer operation, and are used to obtain the vehicle position information.", "ptxt");
si[i++] = gsitm("N516040830000O00ENG.html", "Component Parts Location", "title");
si[i++] = gsitm("N516040830000O00ENG.html", "The telematics antenna is installed in the instrument panel. Refer to .", "ptxt");
