si[i++] = gsitm("N5160405X0002W00ENG.html", "AV control unit sends and receives signals to and from the TCU, and sends and receives information necessary for the Mitsubishi Connect service.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Airbag diagnosis sensor unit", "ptxt");
