si[i++] = gsitm("N5160405X0002W00ENG.html", "Parking brake status signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "BCM", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Front wiper request signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Sleep wake up signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Door lock status signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "TCU Output Signal (CAN Communication)", "title");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Sleep-ready signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Door lock/unlock signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Panic alarm request signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Engine start request signal", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "DESCRIPTION", "title");
si[i++] = gsitm("N5160405X0002W00ENG.html", "MITSUBISHI CONNECT Services provide various services to support dealing with emergencies of the subscribed vehicle and the driver. For example, in case of an illness or serious injury, you can seek support by pushing the in-vehicle telematics switch (SOS button) and connecting to the MITSUBISHI CONNECT Customer Support Line.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "The MITSUBISHI CONNECT Customer Support Line can specify the location of the vehicle via GPS, and the information will be sent to the police or other agencies as needed.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Telematics Communication Unit (TCU) equipped with a radio communication terminal communicates with the MITSUBISHI CONNECT Customer Support Line via radio waves for receiving MITSUBISHI CONNECT services.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "With the equipment of the radio communication terminal, TCU communicates with MITSUBISHI CONNECT Customer Support Line by Packet communication*1 and SMS*2 via TEL antenna.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "*1: Packet communication means a communication method that data is broken down into smaller chunks for communication. The split data is called a packet and improves the efficiency of the communication circuit.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "*2: SMS stands for Short Message Service, also known as text messaging or short mail, and provides text-based message communication services.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "While communicating with the operator, data (e.g. transmission of own vehicle location) is transmitted to the MITSUBISHI CONNECT Services Response Center by using DTMF tone signals and SMS via the radio communication module included in TCU.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Audio signals transmitted and received while communicating with the operator are input by microphone connected to TCU.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "Audio signals are output from TCU via the audio data circuit connected to the AV control unit.", "ptxt");
si[i++] = gsitm("N5160405X0002W00ENG.html", "COMMUNICATION SIGNAL", "title");
si[i++] = gsitm("N5160405X0002W00ENG.html", "TCU is connected to the AV control unit via USB communication, and it sends/receives reception data of TCU and operation signals of the AV control unit.", "ptxt");
