si[i++] = gsitm("N516040820000N00ENG.html", "Telematics", "title");
si[i++] = gsitm("N516040820000N00ENG.html", "Please note that the Automatic Collision Notification service and Emergency Call function cannot be used in the following conditions:", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "Emergency functions and services will not be available without a paid subscription to MITSUBISHI CONNECT Services.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The MITSUBISHI CONNECT Services network system is disabled.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The vehicle moves outside the service area where the TCU (Telematics Control Unit) is connected to the system.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The vehicle is outside the area where the cellular network service is receivable.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The vehicle is in a location with poor signal reception such as tunnels, underground parking garages, behind buildings or in mountainous areas.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The line is busy.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The TCU (Telematics Control Unit) or other systems of your vehicle are not working properly.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "It may not be possible to make an emergency call depending on the severity of a collision and/or emergency.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "Park the vehicle in a safe location and set the parking brake before operating the E-Call (SOS) button.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "Only use this service in case of an emergency. There may be a penalty for inappropriate use of the service.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "Radio waves could adversely affect electric medical equipment. Individuals who use a pacemaker should contact the device manufacturer regarding any possible effects before using the system.", "ptxt");
si[i++] = gsitm("N516040820000N00ENG.html", "The TCU (Telematics Control Unit) antenna is installed inside the upper central part of the instrument panel. An occupant should not get any closer to the antenna than specified by the pacemaker manufacturer. The radio waves from the TCU antenna may adversely affect the operation of the pacemaker while using the MITSUBISHI CONNECT Services.", "ptxt");
