si[i++] = gsitm("N5160407O0002A00ENG.html", "DETAILED FLOW", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "INTERVIEW AND SYMPTOM CONFIRMATION", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Check the malfunction symptoms by performing the following items.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Interview the customer to obtain the malfunction information (conditions and environment when the malfunction occurred).", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Check the symptom.", "ptxt");
