si[i++] = gsitm("N5160407O0002A00ENG.html", "DIAGNOSIS WITH M.U.T.-III SE", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Connect M.U.T.-III SE and perform a self-diagnosis for “IVC”. Refer to M.U.T.-III SE Function.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "When DTC is detected, follow the instructions below:", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Record DTC and Freeze Frame Data.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Are any DTCs displayed?", "question");
si[i++] = gsitm("N5160407O0002A00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "TROUBLE DIAGNOSIS FOR DTC", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Check the DTC indicated in the self-diagnosis results.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Perform the relevant diagnosis referring to the DTC Index. Refer to .", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "PERFORM SYMPTOM DIAGNOSIS", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Perform the relevant diagnosis referring to the diagnosis chart by symptom. Refer to Symptom Table.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "ERROR PART REPAIR", "title");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Perform a self-diagnosis for “IVC” with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Check that the symptom does not occur.", "ptxt");
si[i++] = gsitm("N5160407O0002A00ENG.html", "Does the symptom occur?", "question");
si[i++] = gsitm("N5160407O0002A00ENG.html", "GO TO 1.", "ptxt");
si[i++] = gsitm("N516040280008300ENG.html", "Description", "title");
si[i++] = gsitm("N516040280008300ENG.html", "When TCU is replaced, TCU activation operation and configuration are required. Refer to .", "ptxt");
si[i++] = gsitm("N516040280008300ENG.html", "Preparation before activation operation", "title");
si[i++] = gsitm("N516040280008300ENG.html", "Subscribe to telematics service.", "ptxt");
si[i++] = gsitm("N516040280008300ENG.html", "Preregister user ID and password (can be performed from owner homepage).", "ptxt");
si[i++] = gsitm("N516040280008300ENG.html", "Since VIN data is not included in the TCU after replacement, it is required to write VIN data with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "TCU REPLACEMENT", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Replace TCU. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "PERFORM TCU CONFIGURATION", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "WITH M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Perform configuration (TCU). Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "MANUAL WRITING OF VIN DATA TO TCU", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Turn ignition switch ON and wait at least 5 seconds.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Select “Chassis No./VIN Registration” of “Special Function” item using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Touch “OK” at “Chassis No./VIN Registration” screen to write the VIN data into new TCU.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "TCU ACTIVATION", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Perform TCU activation. Refer to .", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "CHECK NETWORK INITIAL SETTINGS", "title");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "M.U.T.-III SE Special Function", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "With MITSUBISHI CONNECT", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "1. Confirm 90 or more seconds passed after turning ignition switch ON, then select “Network initial settings” of “IVC”.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "2. Check the “Radio wave condition”. If it is normal, go to the next step.If the condition is abnormal or cannot be detected, move the vehicle to a place where the radio wave environment is good. Then start from Step 1 again.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "3. Select “Network initial settings” of “MULTI AV”.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "4. Check the value of “Network initial setting state”. If “Completed” is displayed, the setting is completed. If the value doesn’t become \"Completed\" in 15 minutes, error may occur in the network setting.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "Without MITSUBISHI CONNECT", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "3. Check the value of “Network initial setting state”. If “Completed” is displayed, the setting is completed. If the value doesn’t become \"Completed\" in 15 minutes, error may occur in the network setting.", "ptxt");
si[i++] = gsitm("N5160407Q0007H00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N516040280008400ENG.html", "Description", "title");
si[i++] = gsitm("N516040280008400ENG.html", "When the driver uses telematics system for the first time/re-subscription, TCU activation operation is required. Refer to .", "ptxt");
si[i++] = gsitm("N516040280008400ENG.html", "PREPARATION FOR ACTIVATION", "title");
si[i++] = gsitm("N516040280008400ENG.html", "Subscribe to telematics service.", "ptxt");
si[i++] = gsitm("N516040280008400ENG.html", "Pre-register user ID and password (can be performed from owner home page).", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "TCU ACTIVATION", "title");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "M.U.T.-III SE work support", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Turn ignition switch ON and wait at least 5 seconds or more.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Touch “IVC” on the M.U.T.-III SE screen.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "On the work support screen of M.U.T.-III SE, select “TCU ACTIVATE SETTING” and touch “Start.”", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Select “TCU ACTIVATE SETTING” of “Setting change” in “Special Function”.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "On the TCU ACTIVATE SETTING screen, touch “OK” to set to “ON”.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Exit from M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Turn ignition switch OFF and wait at least 10 seconds.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Wait (at least 10 seconds) until the power switch indicator turns OFF to shut down TCU.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "COMMUNICATION TEST", "title");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "If communicated with the MITSUBISHI CONNECT Customer Support Line with TCU turned ON before establishing the connections of the network line, TCU cannot perform communications. In this case, “The connection to the center failed.” is shown on the display, and the communication function of TCU is deactivated.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "To restore the communication function, turn OFF the TCU battery power and turn it ON again (after disconnecting battery negative terminal, reconnect it) to reset the shutdown condition of TCU communication function. The communication function recovers 20 seconds after turning ON the power again.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Perform TCU communication test by vehicle operation.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Turn ignition switch ON.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Wait 2 minutes or more until the TCU completes the initial communication.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Check the radio wave status with the telematics icon.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Telematics icon", "title");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Radio wave state (Service Area)", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Radio wave state (Out of Service Area)", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Does the radio wave status show Service Area?", "question");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "YES", "result");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "NO", "result");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "TCU activation error or vehicle is in an out of service area. Move vehicle to a service area.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "NO DISPLAY", "result");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Refer to Symptom Table.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "CHECK NETWORK INITIAL SETTINGS", "title");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "M.U.T.-III SE Special Function", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "1. Select “Network initial settings” of “IVC”.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "2. Check that “Completed” is displayed on the “Network initial setting state” field.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "When the received radio wave is weak, “Completed” is not displayed within 15 minutes and an error may occurs. If the error occurs, move the vehicle to a place where the radio wave environment is good. Then start from Step 1 again.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "Is the connection status normal?", "question");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "If not connected, repeat the cold start operation.", "ptxt");
si[i++] = gsitm("N5160407Q0005T00ENG.html", "GO TO 1.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "Description", "title");
si[i++] = gsitm("N516040280006W00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the TCU.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the TCU.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "The configuration no need to “save” configuration data from the TCU. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "Perform the procedures indicated in “Configuration”.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "Make sure to check that the chassis number matches. If a wrong number is written, the ECU may not operate normally.", "ptxt");
si[i++] = gsitm("N516040280006W00ENG.html", "Perform “Configuration” only for new TCU. If it is performed for old TCU, the ECU may not operate normally.", "ptxt");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "Perform writing vehicle specification to TCU following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N5160407Q0007I00ENG.html", "WORK END", "ptxt");
