si[i++] = gsitm("N517014450000F00ENG.html", "MI-PILOT Steering Switch", "title");
si[i++] = gsitm("N517014450000F00ENG.html", "FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N517014450000F00ENG.html", "MI-PILOT steering switch allows the ON/OFF of the Adaptive Cruise Control [ACC] and the settings of a vehicle speed and distance between vehicles.", "ptxt");
si[i++] = gsitm("N517014450000F00ENG.html", "MI-PILOT steering switch signal is transmitted to ECM. ECM transmits the signal to the ADAS control unit 2 via CAN communication.", "ptxt");
si[i++] = gsitm("N517014450000F00ENG.html", "INDIVIDUAL FUNCTIONS WITHIN THE SYSTEM", "title");
si[i++] = gsitm("N517014450000F00ENG.html", "MI-PILOT steering switch detects a switch operation by the driver.", "ptxt");
si[i++] = gsitm("N517014450000F00ENG.html", "INDIVIDUAL OPERATION", "title");
si[i++] = gsitm("N517014450000F00ENG.html", "The steering switch is composed of a combination of a normal open switch and a resistor.", "ptxt");
si[i++] = gsitm("N517014450000F00ENG.html", "When each switch is pressed, the ECM detects which switch is operated according to input voltage.", "ptxt");
