si[i++] = gsitm("N5170102T0004G00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The system measures the distance from the vehicle ahead using the front camera unit and distance sensor, and allows for driving while keeping a proper distance, with the vehicle speed set by the driver as the upper limit speed. At the same time, it detects the lane markers of the lane which the vehicle is driving in and supports steering to keep the vehicle close to the center of the lane.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "MI-PILOT is composed of 2 functions: Adaptive Cruise Control (ACC) and Lane Keep Assist (LKA) function.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "When the vehicle stops in response to the preceding vehicle stopping during the distance-keeping controls of the Adaptive Cruise Control [ACC] system, the engine may stop due to the control of the Auto Stop & Go [AS&G] system. &lt;4B4>", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Adaptive Cruise Control [ACC]", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The Adaptive Cruise Control [ACC] system maintains a selected distance from the vehicle ahead within set speeds.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The driver can select the set speeds.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The vehicle travels at a set speed when the road ahead is clear.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The ACC system can be set to one of two cruise control modes:", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Never set the cruise speed exceeding the posted speed limit.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Vehicle-to-vehicle Distance Control Mode Function", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "For maintaining a selected distance between own vehicle and the vehicle in front of own vehicle up to the preset speed. Refer to .", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Conventional (Fixed Speed) Cruise Control Mode Function", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "For cruising at a preset speed. Refer to .", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Lane Keep Assist (LKA) Function", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The system detects the lane markers and supports steering to keep the vehicle close to the center of the driving lane. Refer to .", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "EVENT DATA RECORDER (EDR)", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Recording and Collecting Vehicle Data", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "MI-PILOT system records and collects the following vehicle data.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Operating status of the accelerator pedal, brake pedal, steering wheel, and other controls", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Detection status of vehicles ahead, lane markers, and other items", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Vehicle speed and other vehicle information", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Information related to MI-PILOT operation", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "MI-PILOT trouble diagnosis information", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Front camera unit image information (when the SRS air bag or the forward emergency brake activates)", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Handling of Data", "title");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Nissan Motor and third parties contracted by Nissan Motor may acquire and use data recorded in the event recorder for the purpose of improving Nissan Motor vehicle collision safety performance.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "Nissan Motor and third parties contracted by Nissan Motor shall not disclose or provide the acquired data to any third party except in the following circumstances.", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "When the consent of the vehicle user is obtained", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "When based on a court order or other legally enforceable request", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "When the data is provided to a research institution or similar body after it is processed by statistical processing or other means so that it is not possible to identify the user or vehicle", "ptxt");
si[i++] = gsitm("N5170102T0004G00ENG.html", "The recorded data cannot be acquired or used at a Nissan dealer.", "ptxt");
si[i++] = gsitm("N5170103C0000N00ENG.html", "Fail-safe (ADAS Control Unit 2)", "title");
si[i++] = gsitm("N5170103C0000N00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5170103D0000U00ENG.html", "Fail-safe (Distance Sensor)", "title");
si[i++] = gsitm("N5170103D0000U00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5170103E0000N00ENG.html", "Fail-safe (Front Camera Unit)", "title");
si[i++] = gsitm("N5170103E0000N00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "System Description", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle-to-vehicle distance control mode is designed to maintain a selected distance from the vehicle in front of own vehicle and can reduce the speed to match a slower vehicle ahead.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The driver can select the distance from the vehicle ahead (Long/Middle/Short).", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If the status is the set wait condition and the vehicle speed is between approximately 30 and 144 km/h, when the SET- switch is pressed, the system records the vehicle speed and starts the control. If the vehicle speed is approximately 30 km/h or less and a vehicle ahead is detected when the SET switch is pressed, a vehicle speed of 30 km/h is set.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The system decelerates the vehicle as necessary and if the vehicle ahead comes to a stop, the vehicle decelerates to a standstill. However, the system can only apply up to 40% of the vehicle’s total braking power.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The system cancels and a warning chime sounds if the speed is below approximately 25 km/h and a vehicle is not detected ahead.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle-to-vehicle distance control mode operates as follows:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When there are no vehicles traveling ahead, the system maintains the speed set by the driver. The set vehicle speed range is between approximately 30 and 144 km/h.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When there is a vehicle traveling ahead, the system adjusts the speed to maintain the distance, selected by the driver, from the vehicle ahead. If the vehicle ahead comes to a stop, the vehicle decelerates to a standstill. Once own vehicle stops, the system keeps the vehicle stopped.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When own vehicle is stopped for less than 3 seconds and the vehicle ahead begins to move, own vehicle starts moving again automatically.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When own vehicle is at a standstill for more than 3 seconds and the vehicle ahead begins to accelerate, push up the RES+ switch or lightly depress the accelerator pedal. The system starts to follow the vehicle ahead.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the vehicle traveling ahead moves to a different traveling lane, the system accelerates and maintains vehicle speed up to the set speed.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "This system should only be used when traffic conditions allow vehicle speeds to remain fairly constant or when vehicle speeds change gradually.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If a vehicle moves into the traveling lane ahead or if a vehicle traveling ahead rapidly decelerates, the distance between vehicles may become closer because the system cannot decelerate the vehicle quickly enough. If this occurs, the system sounds a warning chime and blinks the system display to notify the driver to take necessary action.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle-to-vehicle distance control mode does not control vehicle speed or warn the driver when the driver approaches stationary and slow moving vehicles. The driver must pay attention to vehicle operation to maintain proper distance from vehicles ahead when approaching toll gates or traffic congestion.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle may not maintain the set speed on winding or hilly roads.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "To prevent the vehicle from moving, the driver must depress the brake pedal.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the accelerator pedal is depressed, the brake operation and the warning are not performed by the MI-PILOT system.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle-to-vehicle distance control mode has the following functions:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Cut-in detection", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If a vehicle moves into own traveling lane near own vehicle, the vehicle-to-vehicle distance control mode informs the driver by blinking the vehicle ahead detection indicator.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Approach warning", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If own vehicle comes closer to the vehicle ahead due to rapid deceleration of that vehicle or if another vehicle cuts in, the system warns the driver with the chime and MI-PILOT system display.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The warning chime does not sound in some cases when there is a short distance between vehicles. Some examples are:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the vehicles are traveling at the same speed and the distance between vehicles is not changing.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the vehicle ahead is traveling faster and the distance between vehicles is increasing.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When a vehicle cuts in near own vehicle.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The warning chime does not sound when:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Own vehicle approaches other vehicles that are parked or moving slowly.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The accelerator pedal is depressed, overriding the system.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Acceleration when passing &lt;Left-hand traffic>", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the vehicle-to-vehicle distance control mode system is engaged above 70 km/h and following a slower vehicle (below set speed), and the turn signal is activated to the right, the system automatically starts to accelerate the vehicle to help initiate passing on the right and begins to reduce the distance to vehicle directly ahead. Only the right side turn signal operates this feature.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "As the driver steers the vehicle and moves into the passing lane, if no vehicle is detected ahead the system continues to accelerate to the set speed. If another vehicle is detected ahead, then the vehicle accelerates up to the following speed of that vehicle.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If the vehicle is not steered into the right lane to pass, the acceleration stops after a short time and regains the set following distance.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Acceleration can be stopped at any point by depressing the brake pedal or the CANCEL switch on the steering wheel.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Acceleration when passing &lt;Right-hand traffic>", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the vehicle-to-vehicle distance control mode system is engaged above 70 km/h and following a slower vehicle (below set speed), and the turn signal is activated to the left, the system automatically starts to accelerate the vehicle to help initiate passing on the left and begins to reduce the distance to vehicle directly ahead. Only the left side turn signal operates this feature.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "If the vehicle is not steered into the left lane to pass, the acceleration stops after a short time and regains the set following distance.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Speed Limit Link (With Full TFT meter)", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When MI-PILOT is activated and a change in the speed limit is detected, a new speed limit indicator will be displayed and this can be applied to the vehicle’s set speed manually.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The Speed Limit Link operates:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the detected speed limit sign is 30 km/h and above.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The \"Speed Limit Link\" is enabled in the settings menu of the vehicle information display.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When MI-PILOT is OFF, pressing the MI-PILOT steering wheel switch for less than 1.5 seconds displays the MI-PILOT status, and the set wait condition is engaged.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "ADAS control unit 2 performs the control as per the following:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Constant speed", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The ADAS control unit compares the set vehicle speed with the current vehicle speed, transmits the command to ECM via CAN communication to reach the set vehicle speed, and controls the electric throttle control actuator.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Following", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The ADAS control unit 2 sends commands to the ECM and the ABS actuator and electric unit (control unit) and controls the vehicle speed for keeping the proper distance between vehicles according to the vehicle speed changes of the vehicle ahead.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Following → Stop", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The ADAS control unit 2 sends commands to the ABS actuator and electric unit (control unit) and stops the vehicle. After the vehicle stops, it is held at a stop.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Starting from stop → Following", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The ADAS control unit 2 judges that the RES+ switch is pressed by the MI-PILOT steering switch signal from the ECM or the accelerator pedal is depressed by the accelerator pedal position signal from ECM, transmits the command to ECM to resume following driving, and controls the electric throttle control actuator.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the ADAS control unit 2 judges that a vehicle moves into own traveling lane near own vehicle by the distance sensor signal from the distance sensor, it transmits the meter display signal to the combination meter to turn ON the vehicle ahead detection indicator.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the ADAS control unit 2 judges that own vehicle comes closer to the vehicle ahead due to rapid deceleration of that vehicle or another vehicle cuts in by the distance sensor signal from the distance sensor, it performs the following operations:", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Transmits the meter display signal to the combination meter to turn ON MI-PILOT system display.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Transmits the tone alarm output signal to the combination meter to sound the tone alarm.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the ADAS control unit 2 judges that the turn signal is activated to the right while the own vehicle is following a slower vehicle (below set speed) at 70 km/h or more, it transmits the command to the ECM to accelerate the vehicle.", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "MI-PILOT system: ON", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Vehicle speed: Between approximately 30 and 144 km/h", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Push the CANCEL switch", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Tap the brake pedal (except at a standstill)", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Push the MI-PILOT switch to turn the system OFF (The MI-PILOT status indicator turn OFF)", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Any door is open", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The driver’s seat belt is not fastened", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The vehicle ahead is not detected and own vehicle is traveling below the speed of 25 km/h", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "Own vehicle has been stopped by the MI-PILOT system for approximately 3 minutes or longer", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The shift lever is not in the D (Drive) position or manual shift mode", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The electronic parking brake is applied", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The ASC system is turned OFF", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The AEB applies harder braking", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "ASC (including the traction control system) operates", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "The SNOW mode, GRAVEL mode or MUD mode is selected (4WD models)", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "A wheel slips", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When distance measurement becomes impaired due to adhesion of dirt or obstruction to the distance sensor", "ptxt");
si[i++] = gsitm("N5170102T0004L00ENG.html", "When the radar signal is temporarily interrupted", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "System Description", "title");
si[i++] = gsitm("N5170102T0003700ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0003700ENG.html", "The conventional (fixed speed) cruise control mode allows driving at a speed between 30 and 144 km/h without keeping own foot on the accelerator pedal.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Unlike the vehicle-to-vehicle distance control mode of the distance from the vehicle ahead is not performed. The MI-PILOT system warning and brake control are not performed.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0003700ENG.html", "When the vehicle-to-vehicle distance control mode is OFF, pressing and holding the MI-PILOT switch for 1.5 seconds or more illuminates the speed control indicator and sets the control to the set wait condition.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "When switching to vehicle-to-vehicle distance control mode, first turn the system OFF, and then press the MI-PILOT switch for less than 1.5 seconds to set the vehicle-to-vehicle distance control mode to the set wait condition.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The system compares the current vehicle speed and the set vehicle speed, sends commands via CAN communication to the ECM, and controls the torque to bring the current speed closer to the set speed.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "When the system is in the set wait condition and the vehicle speed is between approximately 30 and 144 km/h, the vehicle speed at the time when the SET- switch is pressed is saved as the set vehicle speed, and control is started.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "ADAS control unit 2 performs the control as per the following:", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Constant speed", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Comparing the set vehicle speed with the current vehicle speed, transmits the command to ECM via CAN communication to reach the set vehicle speed, and controls electronic throttle control actuator.", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170102T0003700ENG.html", "Conventional (fixed speed) cruise control mode: ON", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Vehicle speed: Between approximately 30 and 144 km/h", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170102T0003700ENG.html", "Push the CANCEL switch", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Tap the brake pedal", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Push the MI-PILOT switch to turn the system OFF (The MI-PILOT status indicator turn OFF)", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Any door is open", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The driver’s seat belt is not fastened", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "Own vehicle is traveling below the speed of 25 km/h", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The shift lever is not in the D (Drive) position or manual shift mode", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The electronic parking brake is applied", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The ASC system is turned OFF", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The AEB applies braking", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "ASC (including the traction control system) operates", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "The SNOW mode, GRAVEL mode or MUD mode is selected (4WD models)", "ptxt");
si[i++] = gsitm("N5170102T0003700ENG.html", "A wheel slips", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "System Description", "title");
si[i++] = gsitm("N5170102T0004H00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0004H00ENG.html", "The front camera unit is used to control the steering so that the vehicle drives close to the center of the lane and to assist driver steering operations. [Lane Keep Assist (LKA) cannot be used with the vehicle speed less than approximately 60 km/h when there is no vehicle ahead.]", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When the steering wheel is operated by more than a certain amount, the steering wheel is operated by the Lane Keep Assist (LKA) function.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "During Lane Keep Assist[LKA] control, the ADAS control unit detects driver\'s steering operations based on the steering torque signal/ touch sensor signal received from the power steering control module via CAN communication.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "If the ADAS control unit 2 detects a condition that driver releases the steering wheel, a warning is indicated on the vehicle information display.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "If the driver does not operate the steering wheel after the warning has been displayed, an audible alert sounds and the warning blinks in the vehicle information display, followed by a quick brake application to request the driver to take control of the vehicle again.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "If the driver still does not respond, the MI-PILOT turns on the hazard light and slows the vehicle to a complete stop.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "The driver can cancel the deceleration at any time by steering, braking, accelerating, or operating the MI-PILOT switch.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Hands-off warning may be displayed in the following conditions.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When gripping the joint part of the steering wheel.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When operating the steering wheel with gloves.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When MI-PILOT is OFF, pressing the MI-PILOT steering switch for less than 1.5 seconds displays the MI-PILOT status, and the set wait condition is engaged.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "ADAS control unit 2 performs the control as per the following:", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Control active (straight road)", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "The front camera unit detects the lane markers and sends the lane marker detection signal via CAN/ETH communication to the ADAS control unit 2. Based on the lane marker detection signal, the ADAS control unit 2 supports steering by sending commands via CAN communication to the power steering control module for keeping the vehicle in the lane.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Control active (curved road)", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "The front camera unit detects the lane markers and sends the lane marker detection signal via CAN/ETH communication to the ADAS control unit 2. Based on the lane marker detection signal, the ADAS control unit 2 supports steering to match the curve by sending commands via CAN communication to the power steering control module for keeping the vehicle in the lane.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Control standby", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When the ADAS control unit 2 receives the turn signal indicator signal via CAN communication from BCM, it temporarily cancels the Lane Keep Assist (LKA) function.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Control reactivation", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "When the lane change is completed and the ADAS control unit 2 receives the lane marker detection signal via CAN/ETH communication from the front camera unit, it reactivates the Lane Keep Assist (LKA) function.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170102T0004H00ENG.html", "The Lane Keep Assist[LKA] function can be activated when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "MI-PILOT system: ON and ACC system is activated", "ptxt");
si[i++] = gsitm("N5170102T0004H00ENG.html", "Lane markers on both sides are clearly detected", "ptxt");
