si[i++] = gsitm("N5170103M0006P00ENG.html", "With a vehicle ahead/Without a vehicle ahead", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "State in which a change in speed limit is detected and the speed limit on the new speed limit sign can be incorporated into the vehicle\'s set speed (when manual mode is selected)", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Green frame", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the speed limit is greater than the set vehicle speed", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the speed limit is less than the set vehicle speed", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "APPROACH WARNING DISPLAY", "title");
si[i++] = gsitm("N5170103M0006P00ENG.html", "If own vehicle comes closer to a vehicle ahead due to rapid deceleration of that vehicle or if another vehicle cuts in, the system warns the driver with the chime and MI-PILOT system display. Decelerate by depressing the brake pedal to maintain a safe vehicle distance if:", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The chime sounds.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The vehicle ahead detection indicator blinks in yellow.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The warning chime may not sound in some cases when there is a short distance between vehicles. Some examples are:", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the vehicles are traveling at the same speed and the distance between vehicles is not changing.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the vehicle ahead is traveling faster and the distance between vehicles is increasing.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When a vehicle cuts in at near own vehicle.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The warning chime will not sound when own vehicle approaches vehicles that are parked or moving slowly.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The warning chime will not sound when the accelerator pedal is depressed, overriding the system.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The approach warning chime may sound and the system display may blink when the distance sensor detects some reflectors which are fitted on vehicles in other lanes or on the side of the road.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "This may cause the MI-PILOT system to decelerate or accelerate the vehicle.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The distance sensor may detect these objects when the vehicle is driven on winding roads, hilly roads or when entering or exiting a curve.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "The distance sensor may also detect reflectors on narrow roads or in road construction zones.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "In these cases, driver will have to manually control the proper distance ahead of own vehicle.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Also, the sensor sensitivity can be affected by vehicle operation (steering maneuver or driving position in the lane) or traffic or vehicle condition (for example, if a vehicle is being driven with some damage).", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When own vehicle comes closer to the vehicle ahead and it is judged that the distance between the vehicles is not sufficient", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Vehicle ahead detection indicator: Yellow (Blink)", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "WARNING LIGHT AND AUTOMATIC CANCELLATION DISPLAY", "title");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the ASC is turned OFF", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the SNOW mode, GRAVEL mode or MUD mode is selected (4WD models)", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "A chime sounds and the control is automatically canceled.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the condition is no longer present, turn the system OFF. Turn the ACC system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Currently Not Available", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the ASC or ABS (including the TCS) operates", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When a wheel slips", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the conditions listed above are no longer present, turn the system OFF. Turn the MI-PILOT system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Unavailable", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Slippery Road", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Parking brake is applied", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "After releasing the parking brake, turn the system OFF . Turn the MI-PILOT system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Not Available,", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Parking Brake On", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the driver’s seat belt is not fastened", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "After fastened the seat belt, turn the system OFF. Turn the MI-PILOT system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Seat Belt Not Fastened", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the distance sensor is dirty, making it impossible to detect a vehicle ahead", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Park the vehicle in a safe place, turn the engine OFF.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Check to see if the distance sensor area of the front grille is blocked.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "If the distance sensor area of the front grille is blocked, remove the blocking material.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Restart the engine and then perform the MI-PILOT system again.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Temporarily Disabled", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Front Radar Blocked", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "While the vehicle is stopped by the MI-PILOT, the driver’s door is opened but the electronic parking brake was not activated", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Please step on the brake immediately", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Press Brake pedal", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "When the system is malfunctioning", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Stop the vehicle in a safe place.", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "Turn the engine OFF, restart the engine and set the MI-PILOT system again", "ptxt");
si[i++] = gsitm("N5170103M0006P00ENG.html", "If it is not possible to set the MI-PILOT system or the indicator stays on, it may be a malfunction.", "ptxt");
