si[i++] = gsitm("N517010300003W00ENG.html", "Work Flow", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "After the front camera unit or distance sensor are replaced or a problem with MI-PILOT is corrected, perform a test of MI-PILOT operation and check that MI-PILOT operates correctly.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Always drive safely when performing the action test.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR MI-PILOT SWITCH", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Press the MI-PILOT switch (less than 1.5 seconds).", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Information display status", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "MI-PILOT status indicator", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", ":", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "ON (Gray)", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Speed control status indicator/warning", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Set vehicle speed indicator", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "“———”", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "““km/h”", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Set distance indicator", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Long mode", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the vehicle information display on the combination meter indicates the set standby mode.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Press the MI-PILOT switch and check that the MI-PILOT indicator turns off when MI-PILOT is set to OFF.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the MI-PILOT indicator is OFF after the engine is started again.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR DISTANCE SWITCH", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Press the DISTANCE switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the set distance indicator changes display in order of: (Long)→(Middle)→(Short).", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "When the MI-PILOT switch is turned ON, initial setting set to (Long).", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR RES+, SET-, AND CANCEL SWITCHES", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that RES+, SET-, CANCEL switches are operated smoothly.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that switches come up as hand is released from the switches.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "SET CHECKING (1)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Press the MI-PILOT switch (less than 1.5 seconds) and turn the MI-PILOT system ON.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Drive the vehicle at 30 km/h or more.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Push down the SET- switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the desired speed is set and MI-PILOT control starts when releasing SET- switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The set vehicle speed is indicated on the set vehicle speed indicator in the MI-PILOT system display on the information display.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR INCREASE OF CRUISING SPEED (1)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Set the MI-PILOT at desired speed.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the set speed increases by 1 km/h as RES+ switch is pushed up.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The maximum set speed of the MI-PILOT is 144 km/h.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Never set the cruise speed exceeding the posted speed limit.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR DECREASE OF CRUISING SPEED (1)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the set speed decreases by 1 km/h as SET- switch is pushed down.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The minimum set speed is approximately 30 km/h.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Cancel the control automatically when the system does not detect any vehicle ahead.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 7.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "SET CHECKING (2)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Stop the vehicle.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Drive the vehicle at less than approximately 30 km/h.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Push down the SET- switch when the system detects a vehicle ahead.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the MI-PILOT is performed so that the vehicle maintains a proper distance according to the vehicle speed [maximum: approximately 30 km/h when releasing SET- switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The MI-PILOT cannot be set when the vehicle speed is less than 30 km/h and when a vehicle ahead is not detected.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The set vehicle speed indicator in the MI-PILOT system display on the information display is set to 30 km/h.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 8.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR INCREASE OF CRUISING SPEED (2)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Set the MI-PILOT when the vehicle speed is less than approximately 30 km/h and when a vehicle ahead is detected.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 9.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR DECREASE OF CRUISING SPEED (2)", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Set the set vehicle speed to the desired vehicle speed according to “check for increase of cruising speed”.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "The minimum the set speed is approximately 30 km/h.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 10.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR CANCELLATION OF MI-PILOT", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the MI-PILOT is canceled when performing the following operations.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "When the brake pedal is depressed after MI-PILOT is set and the vehicle is driven.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "When the selector lever is in the “N” position after MI-PILOT is set and the vehicle is driven.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "When the MI-PILOT switch is turned OFF after MI-PILOT is set and the vehicle is driven.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "When the CANCEL switch is pressed after MI-PILOT is set and the vehicle is driven.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "GO TO 11.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "CHECK FOR RESTORING SPEED THAT IS SET BY MI-PILOT BEFORE CANCELLATION", "title");
si[i++] = gsitm("N517010300003W00ENG.html", "Check that the vehicle restores the previous speed kept before the system deactivation when performing the following operations.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Drive the vehicle when the MI-PILOT is set and depress the brake pedal to cancel the control. Check that the vehicle restores the previous vehicle speed kept before the system deactivation when pushing up the RES+ switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Drive the vehicle when the MI-PILOT is set and shift the selector lever to the “N” position to cancel the control. Check that the vehicle restores the previous vehicle speed kept before the system deactivation when shifting the selector lever to the “D” position and pushing up the RES+ switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "Drive the vehicle when the MI-PILOT is set and press the CANCEL switch to cancel the control. Check that the vehicle restores the previous vehicle speed kept before the system deactivation when pushing up the RES+ switch.", "ptxt");
si[i++] = gsitm("N517010300003W00ENG.html", "INSPECTION END", "ptxt");
