si[i++] = gsitm("N5170103M0004300ENG.html", "SET- switch", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Sets desired cruise speed or reduces speed incrementally", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Push and hold the switch to decrease the set speed by 5 km/h", "ptxt");
