si[i++] = gsitm("N5170103M0004300ENG.html", "SYSTEM DISPLAY", "title");
si[i++] = gsitm("N5170103M0004300ENG.html", "Speed control status indicator/warning", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "The vehicle speed control status is indicated by different colors and shapes", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Set vehicle speed indicator", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Indicates the set vehicle speed", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Indicates 30 km/h when setting less than 30 km/h", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Vehicle ahead detection indicator", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Indicates whether it detects a vehicle ahead", "ptxt");
si[i++] = gsitm("N5170103M0004300ENG.html", "Set distance indicator", "ptxt");
