si[i++] = gsitm("N5170103M0004400ENG.html", "When the SNOW mode, GRAVEL mode or MUD mode is selected (4WD models)", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "A chime sounds and the control is automatically canceled.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When the condition is no longer present, turn the system OFF. Turn the ACC system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Currently Not Available", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When the ASC or ABS (including the TCS) operates", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When a wheel slips", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When the conditions listed above are no longer present, turn the system OFF. Turn the ACC system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Unavailable", "ptxt");
