si[i++] = gsitm("N5170103M0004400ENG.html", "Parking brake is applied", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "After releasing the parking brake, turn the system OFF . Turn the ACC system back on to use the system.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Not Available,", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Parking Brake On", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When the distance sensor is dirty, making it impossible to detect a vehicle ahead", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Park the vehicle in a safe place, turn the engine OFF.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Check to see if the distance sensor area of the front grille is blocked.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "If the distance sensor area of the front grille is blocked, remove the blocking material.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Restart the engine and then perform the ACC system again.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Temporarily Disabled", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Front Radar Blocked", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "When the system is malfunctioning", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Stop the vehicle in a safe place.", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "Turn the engine OFF, restart the engine and set the ACC system again", "ptxt");
si[i++] = gsitm("N5170103M0004400ENG.html", "If it is not possible to set the ACC system or the indicator stays on, it may be a malfunction.", "ptxt");
