si[i++] = gsitm("N5170103M0004500ENG.html", "When the SNOW mode, GRAVEL mode or MUD mode is selected (4WD models)", "ptxt");
si[i++] = gsitm("N5170103M0004500ENG.html", "A chime sounds and the control is automatically canceled.", "ptxt");
