si[i++] = gsitm("N5170201G0005R00ENG.html", "With the detection of Network-DTC some systems do not perform the fail-safe operation.", "ptxt");
si[i++] = gsitm("N5170201G0005R00ENG.html", "A system controlling based on a signal received from the control unit performs fail-safe operation when the communication with the ADAS control unit 2 becomes inoperable.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "Always perform the additional service after replacing the ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "PERFORM PROGRAMMING", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Perform ADAS control unit 2 programming according to the procedure of “Programming” in M.U.T.-III SE User\'s Manual. Refer to M.U.T.-III SE User\'s Manual.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "12V battery voltage: 12 – 13.5 V (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "After the ECU update, the transfer of ECU update result is required. If the transfer of ECU update result fails, be sure to perform \"Data Upload\". For the detailed procedures, refer to \"M.U.T.-III SE User\'s Manual\".", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "ADAS CONTROL UNIT 2 CONFIGURATION", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "Perform the ADAS control unit 2 configuration. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "WRITING MAC KEY", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "Perform MAC key writing. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "With MI-PILOT Assist", "result");
si[i++] = gsitm("N51702032000GF00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Without MI-PILOT Assist", "result");
si[i++] = gsitm("N51702032000GF00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "STEERING TORQUE CALIBRATION", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "Perform the steering torque calibration. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N51702032000GF00ENG.html", "Change the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"ICC/ADAS 2\".", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N51702032000GF00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N517020320006600ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "The configuration no need to “save” configuration data from the ADAS control unit 2. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N517020320006600ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "Perform writing vehicle specification to ADAS control unit 2 following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N517020320006600ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5170203K0001900ENG.html", "Inspection Procedure", "title");
