si[i++] = gsitm("N51702032000FH00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000FH00ENG.html", "After replacing the ADAS control unit 2 and after replacing or removing the following steering components, the steering torque calibration is necessary to operate the system normally.", "ptxt");
