si[i++] = gsitm("N51702032000FH00ENG.html", "Follow the M.U.T.-III SE when performing Steering Torque Calibration. (Steering Torque Calibration cannot be performed without M.U.T.-III SE).", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Work Procedure (Preparation)", "title");
