si[i++] = gsitm("N51702032000FH00ENG.html", "PREPARATION BEFORE STEERING TORQUE CALIBRATION", "title");
si[i++] = gsitm("N51702032000FH00ENG.html", "Perform pre-inspection for diagnosis. Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Place the car on a level surface.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Adjust the tire pressure to the specified pressure value.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Maintain no-load in vehicle.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Check if the following conditions are satisfied.", "ptxt");
