si[i++] = gsitm("N51702032000FH00ENG.html", "Vehicle speed: 0 km/h", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "ADAS control unit 2 voltage: More than 10.5 V", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Release the parking brake.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Refer to Work Procedure (Steering Torque Calibration).", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Work Procedure (Steering Torque Calibration)", "title");
si[i++] = gsitm("N51702032000FH00ENG.html", "The steering wheel is operated automatically when \"Start\" is touched.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Do not touch the steering wheel.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "STEERING TORQUE CALIBRATION", "title");
si[i++] = gsitm("N51702032000FH00ENG.html", "M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Operate M.U.T.-III SE outside the vehicle, and close all the doors.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Select \"Special Function\", then \"Steering Torque Calibration\".", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Select \"OK\" to begin the Steering Torque Calibration.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Never touch steering wheel or shake the vehicle when the Steering Torque Calibration is conducted.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Confirm the displayed item.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "\"Completed\"： Select \"Home\"/\"Return one level\".", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "“Abnormally completed”: Perform the following services.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Displayed item possible cause service procedure:", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Possible Cause", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Action", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Steering wheel torque value is out range.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Check install condition of steering system (from torque sensor to steering wheel).", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "After repairing or replacing error-detected parts, perform calibration again.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Out of execution condition.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Ensure the following items are within the specified range:", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "ADAS control unit 2 power supply: more than 10.5 V", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Shift position: P range", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Touched the steering wheel during calibration: retry without touching the steering wheel.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Some parts are not normal: Perform “Read All DTCs” with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Touch \"Retry\" after satisfying the execution conditions.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Calibration for torque value is abnormally completed.", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Touch \"OK\" (Retry).", "ptxt");
si[i++] = gsitm("N51702032000FH00ENG.html", "Confirm that \"Completed\" is displayed and then select \"Home\"/\"Return one level\" to close the adjustment procedure.", "question");
si[i++] = gsitm("N51702032000FH00ENG.html", "Work End.", "ptxt");
si[i++] = gsitm("N517020320006800ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N517020320006800ENG.html", "When replacing ADAS control unit 2, it is necessary to write MAC key to ADAS control unit 2. Write MAC key to ADAS control unit 2 according to \"MAC Key writing\" procedure of \"M.U.T.-III SE Operation Manual\".", "ptxt");
