si[i++] = gsitm("N51702017006VZ00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Turn the engine switch OFF, close the driver\'s door, and wait for 3 minutes or more.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Turn the engine switch ON.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Perform \"ALL DTC\" with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Check if any DTCs of ethernet (DTC \"U19B5-87\", \"U2752-87\" &lt;Up to 2025 model year> and/or \"U2752-88\") are detected in \"Self Diagnostic Result\" of \"ICC/ADAS 2\", and check if any DTCs of ethernet (DTC \"C2599-13\" and/or \"U275F-88\") are detected in \"Self Diagnostic Result\" of \"LASER/RADAR\".", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Are DTC \"U19B5-87\", \"U2752-87\", \"U2752-88\", \"C2599-13\" and/or \"U275F-88\" detected?", "question");
