si[i++] = gsitm("N51702017006VZ00ENG.html", "NO", "result");
si[i++] = gsitm("N51702017006VZ00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "CHECK DISTANCE SENSOR CONNECTOR", "title");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Disconnect the ethernet harness connector terminals of the distance sensor once, and check the terminals for damage or looseness. Then, reconnect the terminals.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Are DTCs \"U19B5-87\", \"U2752-87\" &lt;Up to 2025 model year>, \"U2752-88\", \"C2599-13\" and/or \"U275F-88\" detected?", "question");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Repair or replace the malfunction part, securely lock the harness connector, and GO TO 3.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "CHECK ADAS CONTROL UNIT 2 CONNECTOR", "title");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Disconnect the ethernet harness connector terminals of ADAS control unit 2 once, and check the terminals for damage or looseness. Then, reconnect the terminals.", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Repair or replace the malfunction part, securely lock the harness connector, and GO TO 4.", "ptxt");
