si[i++] = gsitm("N51702017006VZ00ENG.html", "Perform DTC confirmation procedure again. Refer to DTC Description .", "ptxt");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Are DTCs \"U2752-88\" and/or \"U275F-88\" detected as the current malfunction?", "question");
si[i++] = gsitm("N51702017006VZ00ENG.html", "Replace the distance sensor (Refer to), and GO TO 5.", "ptxt");
