si[i++] = gsitm("N5170202T0009A00ENG.html", "The Predictive Forward Collision Warning(PFCW) system will function when the vehicle is driven at speeds of approximately 5 km/h (3 MPH) and above.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "The Predictive Forward Collision Warning(PFCW) system alerts the driver by the vehicle ahead detection indicator and chime when the distance between own vehicle and a vehicle in front of the vehicle ahead becomes closer.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009A00ENG.html", "The distance from the vehicle in front of the vehicle ahead and a relative speed are calculated by using the distance sensor and an distance sensor signal is transmitted to the ADAS control unit 2 via CAN communication. When judging the necessity of warning according to the received distance sensor signal, the ADAS control unit 2 transmits a meter display signal and a buzzer output signal to the combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009A00ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "PFCW system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "Vehicle speed: Approximately 5 km/h (3 MPH) and above.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "Vehicle in front of the vehicle ahead: Detected.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "ON/OFF of PFCW system is performed with the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T0009A00ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "When the distance sensor picks up interference from another radar source and making it impossible to detect a vehicle ahead.", "ptxt");
si[i++] = gsitm("N5170202T0009A00ENG.html", "When the distance sensor area of the front grill is dirty and the measurement of the distance between the vehicles becomes difficult.", "ptxt");
