si[i++] = gsitm("N5170202T0009200ENG.html", "Motor operation signal", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "Activates a motor operation signal to activate the steering vibration motor.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "Activates a motor operation signal to active the steering vibration motor", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009200ENG.html", "Lane Departure Warning (LDW) system provides a LDW function when the vehicle is driven at speeds of approximately 60 km/h (37 MPH) or more.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "When the vehicle approaches either the left or the right side of the traveling lane, a steering vibration activates and the LDW indicator (yellow) on the combination meter blinks to alert the driver.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "The warning does not occur during turn signal operation (Lane change side).", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "The warning function stops when the vehicle returns inside of the lane markers.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "The LDW system provides an early warning when the Driver Monitoring System (DMS) detects driver drowsiness or falling asleep.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "The LDW system is turned ON automatically when the Driver Monitoring System (DMS) detects driver drowsiness or falling asleep.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "EXAMPLE", "title");
si[i++] = gsitm("N5170202T0009200ENG.html", "When the vehicle approaches the right lane marker, the driver is alerted by the steering vibration and the blinking of LDW warning display (yellow).", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009200ENG.html", "The front camera unit monitors lane markers of the traveling lane.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "When judging from a lane marker detection signal that the vehicle is approaching the lane marker, the ADAS control unit 2 controls the following item to alert the driver.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "Activates the steering vibration motor by ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "ADAS control unit 2 transmits a meter display signal to combination meter via CAN communication and turns ON/OFF the LDW system display.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009200ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "LDW system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "Vehicle speed: approximately 60 km/h (37 MPH) or more", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "Turn indicator signal: After 2 seconds or more from turned OFF", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "LDW system ON/OFF can be set on the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "After the operating conditions of warning are satisfied, the warning continues until the vehicle speed reaches approximately 60km/h (37MPH)", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "The LDW system may not function properly, depending on the situation. Refer to .", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T0009200ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T0009200ENG.html", "When the front camera unit becomes high temperature [over approximately 40°C (104°F)].", "ptxt");
