si[i++] = gsitm("N5170202T000A400ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A400ENG.html", "Intelligent-Lane Intervention (LDP) system provides a lane departure warning and steering control assistance when the vehicle is driven at speeds of approximately 60 km/h (37 MPH)  or more.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the vehicle approaches either the left or the right side of the traveling lane, a steering vibration activates and the LDP warning display on the information display blinks to alert the driver. Then, the LDP system automatically applies the steering for a short period of time to help assist the driver to return the vehicle to the center of the traveling lane.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Warning and steering control are not performed during turn signal operation (lane change side).", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "The warning and assist functions stop when the vehicle returns to a position inside of the lane marker.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "EXAMPLE", "title");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the vehicle approaches the right lane marker, the driver is alerted by the steering vibration and the blinking of LDP indicator. Simultaneously, the steering is controlled to left to recover the vehicle from the lane departure.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the system is turned ON by dynamic driver assistance switch, ADAS control unit 2 transmits meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Front camera unit monitors lane markers of the traveling lane. It transmits the detected lane condition signal to ADAS control unit 2 via chassis CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When judging from a lane marker detection signal that the vehicle is approaching the lane marker, ADAS control unit 2 controls the following items.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Activates the steering vibration motor by ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Transmits a meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Calculates necessary steering angle to transmit a target steering angle signal to Power steering control module via CAN communication", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When receiving the target steering angle signal, Power steering control module controls the steering.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When receiving the signal from ADAS control unit 2, combination meter turns ON/OFF the LDP system display.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T000A400ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "LDP system: ON", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Vehicle speed: approximately 60 km/h (37 MPH) or more", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "Turn indicator signal: After 2 seconds or more from turned OFF", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "LDP system ON/OFF can be set on the information display.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "After the operating conditions are satisfied, the control continues until the vehicle speed reaches approximately 50 km/h (31 MPH).", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "The LDP system may not function properly, depending on the situation.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T000A400ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the ASC or ABS (Including the TCS) operates.", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the ASC is turned OFF", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the SNOW mode GRAVEL mode or MUD mode is selected (AWD models).", "ptxt");
si[i++] = gsitm("N5170202T000A400ENG.html", "When the front camera unit becomes high temperature [over approximately 40 °C (104 °F)].", "ptxt");
