si[i++] = gsitm("N5170202T000A500ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A500ENG.html", "The Blind Spot Warning (BSW) system can help alert the driver of other vehicles in adjacent lanes when changing lanes.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "The BSW system uses side radar installed near the rear bumper to detect vehicles in an adjacent lane.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "The side radar can detect vehicles on either side of vehicle within the detection zone shown as illustrated.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "This detection zone starts from the outside mirror of vehicle and extends approximately 10 ft (3.0 m) behind the rear bumper, and approximately 10 ft (3.0 m) sideways.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "The BSW system operates above approximately 10 km/h (6.2 MPH).", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "If the side radar detects vehicles in the detection zone, the BSW indicator illuminates.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "If the driver then activates the turn signal, a buzzer sounds twice and the BSW indicator blinks.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "A buzzer sounds if the side radar have already detected vehicles when the driver activates the turn signal. If a vehicle comes into the detection zone after the driver activates the turn signal, then only the BSW indicator blinks and no buzzer sounds.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A500ENG.html", "Side radar enables BSW system.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "The side radar turns on the BSW system when the turned ON by information display.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "Side radar detects a vehicle in the adjacent lane.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "Side radar starts the control as follows, based on a vehicle detection signal, turn signal and dimmer signal transmitted from BCM via CAN communication:", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "Transmits BSW indicator signal and BSW indicator dimmer signal to BSW indicator.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "Transmits a buzzer output signal to combination meter.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T000A500ENG.html", "Side radar performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "BSW system: ON", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "Vehicle speed: Approximately 10 km/h (6.2 MPH) or more", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "ON/OFF of BSW system is performed with the information display.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "After the operating conditions of warning are satisfied, the warning continues until the vehicle speed reaches approximately 29 km/h (18 MPH)", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "The BSW system may not function properly, depending on the situation. Refer to .", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T000A500ENG.html", "The side radar cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T000A500ENG.html", "When the area around the side radar is dirty.", "ptxt");
