si[i++] = gsitm("N5170202T000A600ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A600ENG.html", "The Rear Cross Traffic Alert (RCTA) system can help alert the driver of approaching vehicles when the driver is backing out of a parking space.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "The RCTA system uses side radars installed near the rear bumper to detect approaching vehicles.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "The RCTA system operates at speeds below 15 km/h (9.3 MPH) whenever the vehicle is in reverse.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "The side radar can detect vehicles on either side of vehicle within the detection zone shown as illustrated.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "The radar sensors detect the approaching vehicle from up to approximately 20 m (66 ft) away.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "If the radar detects a vehicle approaching from the side, the system gives visual and audible warning.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "If the side radar detects an approaching vehicle from the side, the RCTA system sounds a beep (single beep), the BSW indicator on the side of the approaching vehicle flashes.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T000A600ENG.html", "Side radar enables RCTA system.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "Side radar starts the control as follows, based on a reverse gear signal and vehicle detection signal.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "Side radar detects a vehicle approaching.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T000A600ENG.html", "Side radar performs the control when the following conditions are satisfied:", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "RCTA system: ON", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "Vehicle speed: Approximately 15 km/h (9.3 MPH) or less", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "Selector lever: “R” position", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T000A600ENG.html", "The side radar cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T000A600ENG.html", "When the area around the side radar is dirty.", "ptxt");
