si[i++] = gsitm("N5170202T0009E00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009E00ENG.html", "Displays the road conditions as identified by the front camera unit on the information display, and alerts the driver. Identifies the road sign information.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit detects road signs as described below and displays them on the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "Latest detected speed limit", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "Reduce speed limit caution (orange)", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "No speed limit information", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "No passing zone", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "Reduce speed limit caution (with no speed limit information) (orange)", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "EXAMPLE", "title");
si[i++] = gsitm("N5170202T0009E00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The TSR system is controlled by the front camera unit.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit turns on the TSR system when the turned ON by combination meter.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit detects the road sign.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit transmits the meter display signal to the combination meter, when detecting the road sign.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit adjusts the detection range of road signs according to a steering angle sensor signal received from the steering angle sensor.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009E00ENG.html", "Front camera unit performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "TSR system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "TSR system ON/OFF can be set on the combination meter", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The TSR system may not function properly, depending on the situation.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T0009E00ENG.html", "The front camera unit cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T0009E00ENG.html", "When the front camera unit becomes high temperature [over approximately 40 °C (104 °F)].", "ptxt");
