si[i++] = gsitm("N5170202T0009F00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009F00ENG.html", "Operates when the vehicle speed is 55 km/h (34 MPH) or higher.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "Detects the steering status and judges the attentiveness of the driver. The driver\'s attentiveness is shown on the vehicle information display in eight stages (level indicator).", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "When it is judged from the degree of minor swerving in the steering operation that the vehicle is drifting, the driver is prompted to exert caution by the drift warning, which displays on the combination meter.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "When the engine is stopped, the system is reset.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009F00ENG.html", "The DAA (Driver Attention Alert(DAA)) is controlled by the ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "ON/OFF of the DAA is performed by using the combination meter.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "The steering angle sensor detects the degree of swerving in the steering operation.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "When the ADAS control unit 2 judges that the steering operation is drifting it transmits the meter display signal to the combination meter.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009F00ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "DAA system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "Vehicle speed: Approximately 55 km/h (34 MPH) or more", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "DAA system ON/OFF can be set on the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "The DAA system may not function properly, depending on the situation.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T0009F00ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T0009F00ENG.html", "When the system malfunction occurs.", "ptxt");
