si[i++] = gsitm("N5170202T0009X00ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The Emergency Lane Assistance (ELA) system operates when the vehicle is driven at speeds of approximately 60 km/h(37 MPH) (front detection) or 50km/h(31MPH)(rear detection) or more.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The ELA system warns the driver when the vehicle approaches the road edge or solid white line with an indicator on the information display and steering vibration.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The system helps assist the driver to return the vehicle to the carriageway by applying the brakes to the left or right wheels individually (for a short period of time) in the following circumstances:", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the vehicle is approaching the edge of the road (for example, grass, gravel ,or a curb).", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the vehicle is approaching a solid line", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the system detects oncoming vehicles in adjacent lanes.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the system detects overtaking vehicles in adjacent lanes.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The ELA system operates only when the lane marker or road edge are clearly visible on the road.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The ELA system can be provide assistance when the vehicle is driven on motorway or dual carriageways.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The ELA system is turned ON automatically each time the engine is restarted.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The lane sensitivity (Strong / Normal / Mild) can be set on the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "EXAMPLE", "title");
si[i++] = gsitm("N5170202T0009X00ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the system is turned ON, ADAS control unit 2 transmits meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Front camera unit monitors lane markers of the traveling lane. It transmits the detected lane condition signal to ADAS control unit 2 via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Distance sensor monitors oncoming vehicles in adjacent lanes. It transmits the distance sensor signal to ADAS control unit 2 via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When judging that the vehicle is approaching the lane marker, the edge of the road, or oncoming vehicles ADAS control unit 2 controls the following items:", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Activates the steering vibration motor by ADAS control unit 2.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Transmits a meter display signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Calculates necessary yaw moment to transmit a target yaw moment signal to ABS actuator and electric unit (control unit) via CAN communication", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Side radar detects a vehicle in the adjacent lane. It transmits the vehicle detection signal to ADAS control unit 2 via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When judging that the vehicle is approaching the overtaking vehicles in adjacent lanes, ADAS control unit 2 controls the following items:", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "BSW indicator signal and BSW indicator dimmer signal transmission to side radar.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Transmits a buzzer output signal to combination meter via CAN communication.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Calculation of necessary yaw moment and transmission of the target yaw moment signal to ABS actuator and electric unit (control unit).", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When receiving the target yaw moment signal, ABS actuator and electric unit (control unit) controls brake pressure of four wheels, respectively.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When receiving the signal from ADAS control unit 2, combination meter turns ON/OFF the LDP system display.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When receiving the meter display signal, combination meter turns ON/OFF the ELA system display.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When receiving the buzzer output signal, combination meter sounds the buzzer.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When receiving the BSW indicator signal, side radar turns ON/OFF the BSW indicator.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009X00ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "ELA system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "Vehicle speed: Approximately 60 km/h(37 MPH) (front detection) or 50km/h (31MPH) (rear detection) or more", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "ELA system ON/OFF can be set on the information display.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When towing a trailer with trailer hitch harness of Genuine Mitsubishi Accessory attached, the ADAS control unit 2 disables the ELA system (Only situation that overtaking vehicles in adjacent lanes). (ON/OFF Settings menu in the multi-information display does not switched automatically.) &lt;From 23 Model year>", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "CANCEL CONDITION", "title");
si[i++] = gsitm("N5170202T0009X00ENG.html", "The ADAS control unit 2 cancels the operation when the system is under any conditions of the operation cancellation condition.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the system malfunction occurs.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the brake pedal is depressed.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the steering wheel is turned as far as necessary for the vehicle to change lanes.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the vehicle is accelerated during the ELA system operation.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the Adaptive Cruise Control System (ACC) approach warning occurs.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the hazard are operated.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When driving on a curve at high speed.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the ASC system is turned OFF.", "ptxt");
si[i++] = gsitm("N5170202T0009X00ENG.html", "When the turn signal operates (The ELA system is deactivated for approximately 2 seconds after the turn signal is operated. This does not apply if an overtaking vehicle is detected).", "ptxt");
