si[i++] = gsitm("N5170202T0009000ENG.html", "Warning function ON/OFF signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Receives driver monitoring system warning function ON/OFF.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Output Signal Item", "title");
si[i++] = gsitm("N5170202T0009000ENG.html", "Reception unit", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Looking aside warning signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Sends the signal and accelerates the FCM warning timing.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Drowsiness warning signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Sends the signal and accelerates the FCM and ELA warning timing.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Dozing off warning signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Driver monitor camera operating status signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "When the signal is sent and the driver monitor camera does not operate normally, it forbids the acceleration of the FCM and ELA warning timing.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Meter display signal", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Sends the signal, displays the warning on the vehicle information display and sounds the combination meter speaker.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "FUNCTION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009000ENG.html", "The driver monitoring system is a function that supports safe driving by recognising the driver\'s condition by means of a driver monitor camera.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "If the driver closes eyes for more than a certain period of time or turns face far away from the front while driving, and the system determines that the driver is looking aside, drowsy or dozing off, the driver is alerted by sound and display.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "OPERATION DESCRIPTION", "title");
si[i++] = gsitm("N5170202T0009000ENG.html", "The driver monitoring system is controlled by the ADAS control unit 2 and the driver monitor control unit.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "The driver\'s condition is monitored by the driver monitor camera from the moment the engine starts. It can be switched on and off using the combination meter.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "When the driver monitoring system\'s operating conditions are met, the driver monitor control unit sends a looking aside warning signal, drowsiness warning signal or dozing off warning signal to the ADAS control unit 2 when it judges that the driver is looking aside, drowsy or dozing off, for example by closing of driver\'s eyes or turning of driver\'s face far away from the front for a certain period of time.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "When the ADAS control unit 2 receives a signal from the driver monitor control unit, it sends a meter display signal to the combination meter, which displays a warning on the combination meter and sounds the combination meter speaker.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "If the driver monitor control unit determines that the driver is looking aside, the FCM warning timing is accelerated.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "If the driver monitor control unit determines that the driver is drowsy or dozing off, the FCM and ELA warning timing is accelerated.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "Once drowsiness is detected, the state is maintained for five minutes even if the driver immediately returns to wakefulness. During that period, the FCM and ELA will issue an early warning.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "OPERATION CONDITION", "title");
si[i++] = gsitm("N5170202T0009000ENG.html", "ADAS control unit 2 performs the control when the following conditions are satisfied.", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "DMS system: ON", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "When the shift position is other than \"R\" (reverse)", "ptxt");
si[i++] = gsitm("N5170202T0009000ENG.html", "While the vehicle is running (3km/h or more)", "ptxt");
si[i++] = gsitm("N5170203B0002700ENG.html", "Fail-safe (ADAS Control Unit 2)", "title");
si[i++] = gsitm("N5170203B0002700ENG.html", "Refer to Fail-Safe (ADAS Control Unit 2).", "ptxt");
si[i++] = gsitm("N5170207U0000T00ENG.html", "Fail-safe (Distance Sensor)", "title");
si[i++] = gsitm("N5170207U0000T00ENG.html", "If a malfunction occurs in the distance sensor, ADAS control unit 2 cancels control, sounds a beep, and turns ON the warning indicator on the information display.", "ptxt");
si[i++] = gsitm("N5170207V0001A00ENG.html", "Fail-safe (Front Camera Unit)", "title");
si[i++] = gsitm("N5170207V0001A00ENG.html", "FAIL-SAFE CONTROL BY DTC", "title");
si[i++] = gsitm("N5170207V0001A00ENG.html", "If a malfunction occurs in the front camera unit, ADAS control unit 2 cancels control, sounds a beep, and turns ON the warning indicator on the information display.", "ptxt");
si[i++] = gsitm("N5170207V0001A00ENG.html", "TEMPORARY DISABLED STATUS AT HIGH TEMPERATURE", "title");
si[i++] = gsitm("N5170207V0001A00ENG.html", "If the vehicle is parked in direct sunlight under high temperature conditions, the system may be deactivated automatically. At this time, ADAS control unit 2 turns ON the FCM warning light and indicates the warning message on the information display.", "ptxt");
si[i++] = gsitm("N5170207V0001A00ENG.html", "When the interior temperature is reduced, the system will resume operation automatically.", "ptxt");
si[i++] = gsitm("N5170207V0001A00ENG.html", "When vehicle front identification is difficult due to soiling of windshield glass and strong light shining from the front, operation may be canceled temporarily. At this time, ADAS control unit 2 turns ON the FCM warning light.", "ptxt");
si[i++] = gsitm("N5170207W0001X00ENG.html", "Fail-safe (Side Radar)", "title");
si[i++] = gsitm("N5170207W0001X00ENG.html", "FAIL-SAFE CONTROL BY DTC", "title");
si[i++] = gsitm("N5170207W0001X00ENG.html", "If a malfunction occurs in the side radar, ADAS control unit 2 cancels control, sounds a beep, and turns ON the warning indicator on the information display.", "ptxt");
si[i++] = gsitm("N5170207W0001X00ENG.html", "TEMPORARY DISABLED STATUS AT BLOCKAGE", "title");
si[i++] = gsitm("N5170207W0001X00ENG.html", "When the side radar is blocked, the operations of  BSW/ RCTA systems are temporarily cancelled. Then the warning message is displayed on information display. Also, under the following conditions, the operation may be temporarily cancelled.", "ptxt");
si[i++] = gsitm("N5170207W0001X00ENG.html", "The side radar may be blocked by temporary ambient conditions such as splashing water, mist or fog.", "ptxt");
si[i++] = gsitm("N5170207W0001X00ENG.html", "The blocked condition may also be caused by objects such as ice, frost or dirt obstructing the side radar.", "ptxt");
si[i++] = gsitm("N517020Q10000200ENG.html", "Fail-safe (DRIVER MONITOR CONTROL UNIT)", "title");
si[i++] = gsitm("N517020Q10000200ENG.html", "When there is malfunction in driver monitor control unit, the system is canceled.", "ptxt");
