si[i++] = gsitm("N5170207Z0007W00ENG.html", "After the operating conditions of warning are satisfied, the warning continues until the vehicle speed reaches approximately 60 km/h (37 MPH). Refer to p33 .", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Menu Displayed by Pressing Each Switch", "title");
