si[i++] = gsitm("N5170207Z0007P00ENG.html", "In the [Settings] menu, select the [Driver Assistance] key", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Select the [Driver Monitor] submenu", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Select the [Driver monitoring system] submenu", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "A tick mark next to [Driver monitoring system] indicates that the system is turned ON", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Press [OK] to turn the system warning OFF or ON", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "SYSTEM DISPLAY", "title");
