si[i++] = gsitm("N5170207Z0007P00ENG.html", "Driver monitor warning display (vehicle information display)", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Displayed when it is judged that the driver is not paying attention to the situation ahead.", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Driver Monitoring System (DMS) OFF indicator lamp", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS turns OFF, the DMS OFF indicator lamp will illuminate.", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "DISPLAY AND WARNING", "title");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "System Display", "title");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Condition", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Display on information display", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "Buzzer", "ptxt");
