si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS detects driver drowsiness", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS detects intense driver drowsiness", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS detects driver dozing", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS cannot detect the driver’s face", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS is temporarily inoperable", "ptxt");
si[i++] = gsitm("N5170207Z0007P00ENG.html", "When the DMS malfunctions", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "PRECAUTIONS FOR DISTANCE SENSOR", "title");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Always keep the distance sensor area of the front grill clean.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Do not strike or damage the areas around the distance sensor.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Do not cover or attach stickers or similar objects on the front grill near the distance sensor area. This could cause failure or malfunction.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Do not attach metallic objects near the distance sensor area (brush guard, etc.). This could cause failure or malfunction.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "PRECAUTIONS FOR PFCW", "title");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Failure to follow the warnings and instructions for proper use of the PFCW system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The PFCW system helps warn the driver before a collision but does not avoid a collision. It is the driver’s responsibility to stay alert, drive safely and be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Listed below are the system limitations for the PFCW system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The PFCW system cannot detect all vehicles under all conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The radar sensor does not detect the following objects:", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Pedestrians, animals or obstacles in the roadway", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Oncoming vehicles", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Crossing vehicles", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The PFCW system does not function when a vehicle ahead is a narrow vehicle, such as a motorcycle.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The radar sensor may not detect a vehicle ahead in the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Snow or heavy rain", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Dirt, ice, snow or other material covering the radar sensor", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Interference by other radar sources", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Snow or road spray from travelling vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Driving in a tunnel", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Towing a trailer", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "When the vehicle ahead is being towed.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "When the distance to the vehicle ahead is too close, the beam of the radar sensor is obstructed.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "When driving on a steep downhill slope or roads with sharp curves.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "The system is designed to automatically check the sensor’s functionality, within certain limitations. The system may not detect some forms of obstruction of the sensor area such as ice, snow, stickers, for example. In these cases, the system may not be able to warn the driver properly. Check, clean and clear the sensor area regularly.", "ptxt");
si[i++] = gsitm("N5170201Q0002H00ENG.html", "Excessive noise interferes with the warning chime sound, and the chime may not be heard.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "PRECAUTIONS FOR FRONT CAMERA UNIT", "title");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Always keep the windshield clean.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Do not attach a sticker (including transparent material) or install an accessory near the front camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Do not place reflective materials, such as white paper or a mirror, on the instrument panel. The reflection of sunlight may adversely affect the front camera unit’s capability of detecting the lane markers.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Do not strike or damage the areas around the front camera unit. Do not touch the camera lens or remove the screw located on the front camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Replace the windshield glass for operating the system normally, when there is a scratch on the area within the lines extended from notch of windshield upper portion.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Windshield upper position", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Black print part", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Line extended from notch", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "(front camera unit)", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "PRECAUTIONS FOR LDW", "title");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Failure to follow the warnings and instructions for proper use of the LDW system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "This system is only a warning device to inform the driver of a potential unintended lane departure. It does not steer the vehicle or prevent loss of control. It is the driver’s responsibility to stay alert, drive safely, keep the vehicle in the traveling lane, and be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Listed below are the system limitations for the LDW system. Failure to follow the warnings and instructions for proper use of the LDW system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "The system does not operate at speeds below approximately 60 km/h (37 MPH) or if it cannot detect lane markers.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "Do not use the LDW system under the following conditions as it may not function properly:", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "During bad weather (rain, fog, snow, etc.).", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When driving on slippery roads, such as on ice or snow.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When driving on winding or uneven roads.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When there is a lane closure due to road repairs.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When driving in a makeshift or temporary lane.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When driving on roads where the lane width is too narrow.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When driving without normal tire conditions (for example, tire wear, low tire pressure, installation of spare tire, tire chains, non-standard wheels).", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When the vehicle is equipped with non-original brake parts or suspension parts.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When towing a trailer or other vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "The system may not function properly under the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "On roads where there are multiple parallel lane markers; lane markers that are faded or not painted clearly; yellow painted lane markers; nonstandard lane markers; or lane markers covered with water, dirt, snow, etc.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "On roads where discontinued lane markers are still detectable.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "On roads where there are sharp curves.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "On roads where there are sharply contrasting objects, such as shadows, snow, water, wheel ruts, seams or lines remaining after road repairs. (The LDW system could detect these items as lane markers.)", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "On roads where the traveling lane merges or separates.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When the vehicle’s traveling direction does not align with the lane marker.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When traveling close to the vehicle ahead, which obstructs the lane camera unit detection range.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When rain, snow, dirt or object adheres to the windshield in front of the lane camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When the headlights are not bright due to dirt on the lens or if the aiming is not adjusted properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When strong light enters the lane camera unit. (For example, the light directly shines on the front of the vehicle at sunrise or sunset.)", "ptxt");
si[i++] = gsitm("N5170201Q0002I00ENG.html", "When a sudden change in brightness occurs. (For example, when the vehicle enters or exits a tunnel or under a bridge.)", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "PRECAUTIONS FOR FRONT CAMERA UNIT", "title");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Refer to Precautions for Lane Departure Warning.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "PRECAUTIONS FOR LDP", "title");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Failure to follow the warnings and instructions for proper use of the LDP system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "The LDP system does not steer the vehicle or prevent loss of control. It is the driver’s responsibility to stay alert, drive safely, keep the vehicle in the traveling lane, and be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "The LDP system is primarily intended for use on well-developed freeways or highways. It may not detect the lane markers in certain road, weather, or driving conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Listed below are the system limitations for the LDP system. Failure to follow the warnings and instructions for proper use of the LDP system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "The LDP system may activate if the driver changes lanes without first activating the turn signal or, for example, if a construction zone directs traffic to cross an existing lane marker. If this occurs the driver may need to apply corrective steering to complete the lane change.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Because the LDP may not activate under the road, weather, and lane marker conditions described in this section, it may not activate every time the vehicle begins to leave its lane and the driver needs to apply corrective steering.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "The LDP system does not operate at speeds below approximately 60 km/h (37 MPH) or if it cannot detect lane markers.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When the LDP system is operating, avoid excessive or sudden steering maneuvers. Otherwise, the driver could lose control of the vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "Do not use the LDP system under the following conditions as it may not function properly:", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "During bad weather (rain, fog, snow, etc.).", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When driving on slippery roads, such as on ice or snow.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When driving on winding or uneven roads.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When there is a lane closure due to road repairs.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When driving in a makeshift or temporary lane.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When driving on roads where the lane width is too narrow.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When driving without normal tire conditions (for example, tire wear, low tire pressure, installation of spare tire, tire chains, non-standard wheels).", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When the vehicle is equipped with non-original brake parts or suspension parts.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When towing a trailer or other vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "On roads where there are multiple parallel lane markers; lane markers that are faded or not painted clearly; yellow painted lane markers; nonstandard lane markers; or lane markers covered with water, dirt, snow, etc.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "On roads where discontinued lane markers are still detectable.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "On roads where there are sharp curves.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "On roads where there are sharply contrasting objects, such as shadows, snow, water, wheel ruts, seams or lines remaining after road repairs. (The LDP system could detect these items as lane markers.)", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "On roads where the traveling lane merges or separates.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When the vehicle’s traveling direction does not align with the lane marker.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When traveling close to the vehicle ahead, which obstructs the lane camera unit detection range.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When rain, snow or dirt adheres to the windshield in front of the lane camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When the headlights are not bright due to dirt on the lens or if the aiming is not adjusted properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When strong light enters the lane camera unit. (For example, the light directly shines on the front of the vehicle at sunrise or sunset.)", "ptxt");
si[i++] = gsitm("N5170201Q0002J00ENG.html", "When a sudden change in brightness occurs. (For example, when the vehicle enters or exits a tunnel or under a bridge.)", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "PRECAUTIONS FOR SIDE RADAR", "title");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Always keep the area near the side radars clean.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Do not attach stickers (including transparent material) or install an accessory near the side radars.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Do not strike or damage the area around the side radars.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "PRECAUTIONS FOR BSW", "title");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Failure to follow the warnings and instructions for proper use of the BSW system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The BSW system is not a replacement for proper driving procedure and is not designed to prevent contact with vehicles or objects. When changing lanes, always use the side and rear mirrors and turn and look in the direction the vehicle moves to ensure it is safe to change lanes. Never rely solely on the BSW system.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Listed below are the system limitations for the BSW system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The BSW system cannot detect all vehicles under all conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The radar sensors may not be able to detect and activate BSW when certain objects are present such as:", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Pedestrians, bicycles, animals.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Vehicles such as motorcycles, low height vehicles, or high ground clearance vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Oncoming vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Vehicles remaining in the detection zone when the driver accelerates from a stop.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "A vehicle merging into an adjacent lane at a speed approximately the same as the vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "A vehicle approaching rapidly from behind.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "A vehicle which own vehicle overtakes rapidly.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "A vehicle that passes through the detection zone quickly.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "When overtaking several vehicles in a row, the vehicles after the first vehicle may not be detected if they are traveling close together.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The radar sensor’s detection zone is designed based on a standard lane width. When driving in a wider lane, the radar sensors may not detect vehicles in an adjacent lane. When driving in a narrow lane, the radar sensors may detect vehicles driving two lanes away.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The radar sensors are designed to ignore most stationary objects, however objects such as guardrails, walls, foliage and parked vehicles may occasionally be detected. This is a normal operation condition.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "The following conditions may reduce the ability of the radar to detect other vehicles:", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Severe weather", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Road spray", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Ice/frost/dirt build-up on the vehicle", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Do not attach stickers (including transparent material), install accessories or apply additional paint near the radar sensors. These conditions may reduce the ability of the radar to detect other vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002K00ENG.html", "Excessive noise (for example, audio system volume, open vehicle window) interferes with the chime sound, and it may not be heard.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "PRECAUTIONS FOR SIDE RADAR", "title");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Refer to Precautions for Blind Spot Warning.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "PRECAUTIONS FOR ACTIVE BLIND SPOT ASSIST", "title");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Failure to follow the warnings and instructions for proper use of the ABSA system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The ABSA system is not a replacement for proper driving procedures and is not designed to prevent contact with vehicles or objects. When changing lanes, always use the side and rear mirrors and turn and look in the direction the vehicle moves to ensure it is safe to change lanes. Never rely solely on the ABSA system.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "There is a limitation to the detection capability of the radar. Not every moving object or vehicle is detected. Using the ABSA system under some road, ground, lane marker, traffic or weather conditions could lead to improper system operation. Always rely on own operation to avoid accidents.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Listed below are the system limitations for the ABSA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The ABSA system cannot detect all vehicles under all conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The radar sensors may not be able to detect and activate ABSA when certain objects are present such as:", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Pedestrians, bicycles, animals.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Vehicles such as motorcycles, low height vehicles, or high ground clearance vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Vehicles remaining in the detection zone when the driver accelerates from a stop.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Oncoming vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "A vehicle merging into an adjacent lane at a speed approximately the same as the vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "A vehicle approaching rapidly from behind.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "A vehicle which own vehicle overtakes rapidly.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "A vehicle that passes through the detection zone quickly.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The radar sensor’s detection zone is designed based on a standard lane width. When driving in a wider lane, the radar sensors may not detect vehicles in an adjacent lane. When driving in a narrow lane, the radar sensors may detect vehicles driving two lanes away.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The radar sensors are designed to ignore most stationary objects, however objects such as guardrails, walls, foliage and parked vehicles may occasionally be detected. This is a normal operation condition.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The following conditions may reduce the ability of the radar to detect other vehicles:", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Severe weather", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Road spray", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Ice/frost/dirt build-up on the vehicle", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Do not attach stickers (including transparent material), install accessories or apply additional paint near the radar sensors. These conditions may reduce the ability of the radar to detect other vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "The camera may not detect lane markers in the following situations and the ABSA system may not operate properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "On roads where there are multiple parallel lane markers; lane markers that are faded or not painted clearly; yellow painted lane markers; nonstandard lane markers; lane markers covered with water, dirt, snow, etc.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "On roads where discontinued lane markers are still detectable.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "On roads where there are sharp curves.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "On roads where there are sharply contrasting objects, such as shadows, snow, water, wheel ruts, seams or lines remaining after road repairs.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "On roads where the traveling lane merges or separates.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When the vehicle’s traveling direction does not align with the lane markers.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When traveling close to the vehicle ahead, which obstructs the lane camera unit detection range.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When rain, snow or dirt adheres to the windshield in front of a lane camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When the headlights are not bright due to dirt on the lens or if aiming is not adjusted properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When strong light enters a lane camera unit. (For example: light directly shines on the front of the vehicle at sunrise or sunset.)", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When a sudden change in brightness occurs. (For example: when the vehicle enters or exits a tunnel or under a bridge.)", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Do not use the ABSA system under the following conditions because the system may not function properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "During bad weather. (For example: rain, fog, snow, etc.)", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When driving on slippery roads, such as on ice or snow, etc.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When driving on winding or uneven roads.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When there is a lane closure due to road repairs.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When driving in a makeshift or temporary lane.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When driving on roads where the lane width is too narrow.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When driving with a tire that is not within normal tire conditions (for example, tire wear, low tire pressure, installation of spare tire, tire chains, nonstandard wheels).", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When the vehicle is equipped with non-original steering parts or suspension parts.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "When towing a trailer or other vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0002L00ENG.html", "Excessive noise (for example, audio system volume, open vehicle window) interferes with the chime sound, and it may not be heard.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "PRECAUTIONS FOR SIDE RADAR", "title");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Refer to Precautions for Blind Spot Warning.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "PRECAUTIONS FOR REAR CROSS TRAFFIC ALERT (RCTA)", "title");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Failure to follow the warnings and instructions for proper use of the RCTA system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "The RCTA system is not a replacement for proper driving procedures and is not designed to prevent contact with vehicles or objects. When backing out of a parking space, always use the side and rear mirrors and turn and look in the direction the vehicle moves. Never rely solely on the RCTA system.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Listed below are the system limitations for the RCTA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Always check surroundings and turn to check what is behind the vehicle before backing up. The radar sensors detect approaching (moving) vehicles. The radar sensors cannot detect every object such as:", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Pedestrians, bicycles, motorcycles, animals or child-operated toy vehicles", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "A vehicle that is passing at speeds greater than approximately 30 km/h (19 MPH)", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "A vehicle that is passing at speeds lower than approximately 8 km/h (5 MPH)", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "The radar sensors may not detect approaching vehicles in certain situations:", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "When a vehicle parked next to own vehicle obstructs the beam of the radar sensor.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "When the vehicle is parked in an angled parking space.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "When the vehicle is parked on inclined ground.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "When an approaching vehicle turns into own vehicle’s parking lot aisle.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "When the angle formed by own vehicle and approaching vehicle is small.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "The following conditions may reduce the ability of the radar to detect other vehicles:", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Severe weather", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Road spray", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Ice/frost/dirt build-up on the vehicle", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Do not attach stickers (including transparent material), install accessories or apply additional paint near the radar sensors. These conditions may reduce the ability of the radar to detect other vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0002M00ENG.html", "Excessive noise (e.g. audio system volume, open vehicle window) interferes with the chime sound, and it may not be heard.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "PRECAUTIONS FOR FRONT CAMERA UNIT", "title");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "Refer to Precautions for Lane Departure Warning.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "PRECAUTIONS FOR TSR", "title");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "The TSR system is only intended to be a support device to provide the driver with information. It is not a replacement for the driver’s attention to traffic conditions or responsibility to drive safely. It cannot prevent accidents due to carelessness. It is the driver’s responsibility to stay alert and drive safely at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "The TSR system is intended as an aid to careful driving. It is the driver’s responsibility to stay alert, drive safely, and observe all road regulations that currently apply, including looking out for road signs.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "The TSR system may not function properly under the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When the road sign is not clearly visible, for example, due to damage or weather conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When rain, snow or dirt adheres to the windshield in front of the multi-sensing front camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When the headlights are not bright due to dirt on the lens or if the aiming is not adjusted properly.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When strong light enters the camera unit. (For example, the light directly shines on the front of the vehicle at sunrise or sunset.)", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When a sudden change in brightness occurs. (For example, when the vehicle enters or exits a tunnel or under a bridge.)", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "In areas not covered by the navigation system.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "If there are deviations in relation to the navigation, for example due to changes in the road routing.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "When overtaking buses or trucks with speed stickers.", "ptxt");
si[i++] = gsitm("N5170201Q0002N00ENG.html", "The TSR system may display a traffic sign, though there is no traffic sign in front of the vehicle. It may display a different speed limit from that for a passenger vehicle. (The maximum speed limit sign may show a higher or lower number than the actual maximum speed, for example, when detecting a speed limit sign for truck, advisory sign, different speed limit sign between daytime and nighttime, or speed limit sign written in different unit near the border, etc.)", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "PRECAUTIONS FOR DAA", "title");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Failure to follow the warnings and instructions for proper use of the DAA system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "The DAA system is only a warning to inform the driver of a potential lack of driver attention or drowsiness. It does not steer the vehicle or prevent loss of control.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "The DAA system does not detect and provide an alert of the driver’s lack of attention or fatigue in every situation.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "It is the driver’s responsibility to:", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Stay alert.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Drive safely.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Keep the vehicle in the traveling lane.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Avoid driving when tired.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Avoid distractions (texting, etc).", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Listed below are the system limitations for the DAA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "The DAA system may not operate properly and may not provide an alert in the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Poor road conditions such as an uneven road surface or pot holes.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Strong side wind.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "If the driver has adopted a sporty driving style with higher cornering speeds or higher rates of acceleration.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Frequent lane changes or changes to vehicle speed.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "The DAA system does not provide an alert in the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Vehicle speeds lower than 60 km/h (37 MPH).", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Short lapses of attention.", "ptxt");
si[i++] = gsitm("N5170201Q0002O00ENG.html", "Instantaneous distractions such as dropping an object.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Handling Precaution", "title");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "PRECAUTIONS FOR FRONT CAMERA UNIT", "title");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "PRECAUTIONS FOR ELA", "title");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Failure to follow the warnings and instructions for proper use of the ELA system could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system will not steer the vehicle or prevent loss of control. It is the driver\'s responsibility to stay alert, drive safely, keep the vehicle in the travelling lane, and be in control of the vehicle at all times.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system is intended to work on all roads with well defined markings or road edges, but it may not detect the road edge or lane markers in certain road, weather or driving conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "There is a limitation to the detection capability of the radars and camera. Not every moving objector vehicle will be detected. Always rely on your own operation to avoid accidents.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Listed below are the system limitations for the ELA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system may activate if you cross a solid lane marker without first activating your turn signal or, for example, if a construction zone directs traffic to cross an existing lane marker. If this occurs you may need to apply corrective steering to complete your lane change.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Because the ELA may not activate under the road, weather and lane marker conditions described in this section, it may not activate every time your vehicle begins to leave the travelling lane and you will need to apply corrective steering.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system will not operate at speeds below the following speeds, or if it cannot detect lane markers.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "During bad weather (rain, fog, snow, etc.).", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving on slippery roads, such as on ice or snow.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving on winding or uneven roads.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When there is a lane closure due to road repairs.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving in a makeshift or temporary lane.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving on roads where the lane width is too narrow.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving without normal tire conditions (for example, tire wear, low tire pressure, installation of spare tire, tire chains, non-standard wheels).", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When the vehicle is equipped with non-original brake parts or suspension parts.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When towing a trailer or other vehicle.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "On roads where there are multiple parallel lane markers; lane markers that are faded or not painted clearly; yellow painted lane markers; nonstandard lane markers; or lane markers covered with water, dirt, snow, etc.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "On roads where discontinued lane markers are still detectable.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "On roads where there are sharp curves.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "On roads where there are sharply contrasting objects, such as shadows, snow, water, wheel ruts, seams or lines remaining after road repairs. (The ELA system could detect these items as lane markers.)", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "On roads where the traveling lane merges or separates.", "ptxt");
