si[i++] = gsitm("N5170201Q0004I00ENG.html", "When rain, snow or dirt adheres to the windshield in front of the lane camera unit.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When the headlights are not bright due to dirt on the lens or if the aiming is not adjusted properly.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When strong light enters the lane camera unit. (For example, the light directly shines on the front of the vehicle at sunrise or sunset.)", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When a sudden change in brightness occurs. (For example, when the vehicle enters or exits a tunnel or under a bridge.)", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Listed below are the system limitations for the overtaking detection feature of the ELA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system cannot detect all overtaking vehicles under all conditions.", "ptxt");
