si[i++] = gsitm("N5170201Q0004I00ENG.html", "Ice/frost/dirt build-up on the vehicle", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Do not attach stickers (including transparent material), install accessories or apply additional paint near the radar sensors. These conditions may reduce the ability of the radar to detect other vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Listed below are the system limitations for the Oncoming detection feature of the ELA system. Failure to operate the vehicle in accordance with these system limitations could result in serious injury or death.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system cannot detect all oncoming vehicles under all conditions.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The following are not detected as oncoming vehicles:", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Parked Vehicles or Low speed Vehicles.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "Oncoming Vehicles on same lane.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "The ELA system may not function properly or detect an oncoming vehicle in the following conditions:", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "In poor visibility conditions (such as rain, snow, fog, dust storms, sand storms, smoke and roads pray from other vehicles).", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "If dirt, ice, snow, fog or other material is covering the radar sensor area or camera area of the windscreen.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "If strong light (for example, sunlight or high beams) enters the front camera or a sudden change in brightness occurs (for example, entering a tunnel or driving in lightning).", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "In dark or dimly lit conditions, such as at night or in tunnels, including cases where your vehicle’s headlights are off or dim, or the tail lights of the vehicle ahead are off.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When the direction of the camera is misaligned.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When driving on a steep downhill slope, on roads with sharp curves, and/or bumpy or dirt roads.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "If there is interference from other radar sources.", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "When your vehicle’s position or movement is changed quickly or significantly (for example, lane change, turning vehicle, abrupt steering, sudden acceleration or deceleration).", "ptxt");
si[i++] = gsitm("N5170201Q0004I00ENG.html", "If the vehicle a head has a unique or unusual shape, extremely low or high clearance heights, or unusual cargo loading or is narrow (for example, a motorcycle).", "ptxt");
