si[i++] = gsitm("N517020300001F00ENG.html", "It is important to clarify the customer’s concerns before starting the inspection. Interview the customer about the concerns carefully and understand the symptoms fully.", "ptxt");
si[i++] = gsitm("N517020300001F00ENG.html", "The customers are not professionals. Never assume that “maybe the customer means...” or “maybe the customer mentioned this symptom”.", "ptxt");
