si[i++] = gsitm("N517020300001F00ENG.html", "REPAIR CHECK (ACTION TEST)", "title");
si[i++] = gsitm("N517020300001F00ENG.html", "Perform the following system action test. Check that the malfunction symptom is solved or no other symptoms occur.", "ptxt");
