si[i++] = gsitm("N517020300001F00ENG.html", "Inspection End.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000ES00ENG.html", "Always perform the distance sensor configuration after replacing the distance sensor.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Always perform the radar alignment after removing and installing or replacing the distance sensor.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "The system does not operate normally unless the distance sensor configuration and the radar alignment are performed. Always perform them.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Perform the FCM system action test to check that the FCM system operates normally.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "DISTANCE SENSOR CONFIGURATION", "title");
si[i++] = gsitm("N51702032000ES00ENG.html", "Perform the distance sensor configuration with M.U.T.-III SE. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "PERFORM RADAR ALIGNMENT", "title");
si[i++] = gsitm("N51702032000ES00ENG.html", "Perform the radar alignment. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "FCM SYSTEM ACTION TEST", "title");
si[i++] = gsitm("N51702032000ES00ENG.html", "Perform the following system action test.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "LDW: Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "LDP: Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "BSW: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Active Blind Spot Assist [ABSA]: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "TSR: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "RCTA: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "DAA: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Check that the each system operates normally.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N51702032000ES00ENG.html", "Change the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"LASER/RADAR\".", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N51702032000ES00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Always perform the radar alignment after removing and installing or replacing the distance sensor.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Description", "Description-5C80577F");
si[i++] = gsitm("N51702032000ET00ENG.html", "OUTLINE OF RADAR ALIGNMENT PROCEDURE", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "A 4-wheel vehicle alignment must be performed before proceeding with radar alignment procedure.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Radio waves could adversely affect electric medical equipment. Those who use a pacemaker should contact the electric medical equipment manufacturer for the possible influences before use.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The system does not operate normally unless the radar alignment is performed. Always perform it.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Set the target board (SST: KV99112700) to the correct position in front of the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Set the radar alignment mode (“MILLIWAVE RADAR ADJUST” on “Work support”) with M.U.T.-III SE, and then perform the adjustment according to the display. (Distance sensor automatically adjusts.)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "CAUTIONARY POINT FOR RADAR ALIGNMENT PROCEDURE", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "For radar alignment procedure, choose a level location with a few meter of working space in front and surrounding the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Vehicle must be stationary and unoccupied during the whole alignment procedure.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Any slight vibration during the alignment procedure can cause the test to fail. If this happens, you will have to restart the alignment process.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The ignition switch must be in the ON position.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The battery voltage must not fall below 12 volts during the whole alignment procedure. Failure to maintain adequate battery voltage will cause the test to fail. If this happens, you will have to restart the alignment process.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The target board must be set in front of the vehicle facing the sensor.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Adjust the radar alignment with M.U.T.-III SE. (The radar alignment procedure cannot be adjusted without M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Never enter the vehicle during radar alignment.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Never block the area between the radar and the target board at any time during the alignment process.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Accurate steering wheel setting is crucial. Once set, do not disturb the steering wheel for the remainder of the alignment procedure.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "For proper system operation and adjustment, all vehicle wheels must be of the same size.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Preparation", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "ADVANCE PREPARATION FOR RADAR ALIGNMENT", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Adjust all tire pressure to the specified value.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Empty the vehicle. (Remove any luggage from the passenger compartment, trunk room, etc.)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Shift the selector lever to “P” position, and release the parking brake.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Fully fill the fuel tank, and then check that the coolant and oils are filled up to correct level.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Clean the distance sensor area  of the front bumper grille.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "RADAR ALIGNMENT OPERATION AREA", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Position the vehicle in a place that is level and where  area can be secured.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "W", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", ": 3000 mm (118.11 in)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "L", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", ": 2000 mm (78.74 in)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "H", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "is a no object zone.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Go to Setting The Target Board.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Setting The Target Board", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Accurate adjustment of the radar alignment requires that the target board be accurately positioned.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "If the radar alignment is adjusted with the target board in the incorrect position, the FCM/PFCW systems do not function normally.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "TARGET BOARD HEIGHT ADJUSTMENT", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Set the target board up to adjustable maximum height.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "PREPARATION OF SETTING TARGET BOARD (1)", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "“A”–“E” (“C”–“F”)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", ": 2000 mm (78.7 in)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Mark points “A”, “B”, “C” and “D”at the center of the lateral surface of each wheels.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Hang a string with a cone from the fender so as to pass through the center of wheel, and then mark a point at the center of the lateral surface of the wheel.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Draw line “LH” passing through points “A” and “B” on the left side of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Approximately 2 m (6.56 ft) or more from the front end of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Mark point “E” on the line “LH” at the positions 2000 mm (78.7 in) from point “A”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Draw line “RH” passing through points “C” and “D” on the right side of vehicle in the same way as step 2.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Mark point “F” on the line “RH” at the positions 2000 mm (78.7 in) from point “C”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Draw line “FW” passing through the points “E” and “F” on the front side of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Mark point “X” at the center of point “E” and “F” on the line “FW”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Make sure that “E” to “X” is equal to “F” to “X”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "SETTING TARGET BOARD", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Place the center of target board on point “G” at line “E-F” and install the target board.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "For performing the radar alignment correctly, securely install (target board) to be parallel with the “E-F” line.", "ptxt");
