si[i++] = gsitm("N51702032000ET00ENG.html", "Go to Radar Alignment.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Radar Alignment", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "The radar alignment is performed automatically with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Perform all necessary work for radar alignment until the adjustment completes as shown in the procedure. If the procedure does not complete, the FCM/MI-PILOT Assist/PFCW systems are inoperable.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "PERFORM RADAR ALIGNMENT", "title");
si[i++] = gsitm("N51702032000ET00ENG.html", "Start the engine.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Connect M.U.T.-III SE and select “Work support” of “LASER/RADAR”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Select “MILLIWAVE RADAR ADJUST”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Confirm the following items;", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The target should be accurately placed.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The vehicle should be stopped.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Select “Start” after the conditions displayed on M.U.T.-III SE are satisfied.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Never select “Start” when the target is not accurately placed.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Select “Next” after the “Radar alignment conditions are ready.” screen is displayed.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "If the radar is in alignment at this time, “In progress” is displayed. It may take several 10s of seconds until the result is displayed.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Confirm the displayed item.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "“Completed.”: Go to 7.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Except “Completed.”: Perform the following services.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Displayed item", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Possible cause", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Service procedure", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Alignment result is over threshold.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "DTC is detected", "ptxt");
