si[i++] = gsitm("N51702032000ET00ENG.html", "Vehicle is moving", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Check the vehicle alignment condition and perform radar alignment again", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Horizontal value is over threshold.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Check the condition.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Perform the adjust again.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the target board is shifted horizontally", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Vertical value is over threshold.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the target board is shifted vertically", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Horizontal value and Vertical value are over threshold.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the target board is shifted horizontally and vertically", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "This display direction is looking from driver seat side.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "This is not an error message, so service procedures are not required.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Target is not detected. (Reflection radio waves is weak.)", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Reconfirm the placing condition, and then re-perform adjustment.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "A target is not-yet -placed", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the distance sensor is incorrect", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Target setting is offset in horizontal direction.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Reconfirm the placing condition. And then re-perform adjustment or re-install the radar.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the distance sensor is shifted horizontally", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Target setting is offset in vertical direction.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The position of the distance sensor is shifted vertically", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "EEPROM writing is error.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Re-perform adjustment or replace the ECU.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "The condition of the alignment is incorrect", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Distance sensor malfunction", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "If same massage displays again, replace the distance sensor", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Hardware is imperfect.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Replace the ECU.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Distance sensor hardware has trouble for alignment", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Replace the distance sensor", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Signal of vehicle side is imperfect or combination of ECU is incorrect.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Diagnose the other ECU.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Other ECU except distance sensor have trouble for alignment", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Check if any DTC is detected in “Self Diagnostic Result” of other ECU except distance sensor", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "If any DTC is not detected, replace the distance sensor", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Software is incorrect.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Distance sensor software is incorrect", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Confirm displayed value.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Monitor item", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Reference value", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Completed", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Vertical Angle", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Radar angle", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "“DownW” or “UpW”", "ptxt");
