si[i++] = gsitm("N51702032000ET00ENG.html", "Horizontal Angle", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "“LeftW” or “RightW”", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Less than 0 ± 4.00 deg", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Alignment status", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Alignment complete", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Within reference value: Go to 8.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Outside of reference value: Check the target board condition and perform radar alignment again.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Check the condition of the distance sensor installation.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Check the vehicle for damage.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Replace distance sensor if it is outside the reference value, even when distance sensor installation is installed normally and the vehicle is not damaged.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Select “End”.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "Once “MILLIWAVE RADAR ADJUST” is started with M.U.T.-III SE, always continue the work until the horizontal radar alignment is completed successfully. If the job is stopped midway, the radar alignment is not adjusted and the FCM/MI-PILOT Assist/PFCW systems cannot operate.", "ptxt");
si[i++] = gsitm("N51702032000ET00ENG.html", "RADAR ALIGNMENT END", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000F900ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the distance sensor.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the distance sensor.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "The configuration no need to “save” configuration data from the distance sensor. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N51702032000F900ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "Perform writing vehicle specification to distance sensor following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N51702032000F900ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000EU00ENG.html", "Always perform the front camera unit configuration after replacing the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Always perform the camera aiming after removing and installing or replacing the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "The system does not operate normally unless the front camera unit configuration and the camera aiming adjustment are performed. Always perform them.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "FRONT CAMERA UNIT CONFIGURATION", "title");
si[i++] = gsitm("N51702032000EU00ENG.html", "Perform the front camera unit configuration with M.U.T.-III SE. Refer to .", "ptxt");
