si[i++] = gsitm("N51702032000EU00ENG.html", "YES", "result");
si[i++] = gsitm("N51702032000EU00ENG.html", "Perform the trouble diagnosis for the detected DTC. Refer to DTC Index.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "NO", "result");
si[i++] = gsitm("N51702032000EU00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "ACTION TEST", "title");
si[i++] = gsitm("N51702032000EU00ENG.html", "Perform the following system action test.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "LDW: Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "LDP: Refer to Work Procedure.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Active Blind Spot Assist [ABSA]: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "TSR: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Check that the each system operates normally.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N51702032000EU00ENG.html", "Change the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"LANE CAMERA\".", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N51702032000EU00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Inspection Procedure", "title");
si[i++] = gsitm("N5170203K0002K00ENG.html", "CHECK CAMERA LENS AND WINDSHIELD", "title");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Are camera lens and windshield contaminated with foreign materials?", "question");
si[i++] = gsitm("N5170203K0002K00ENG.html", "YES (When the camera lens is contaminated with foreign materials.)", "result");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Replace front camera unit (Refer to .) and GO TO 2.", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "YES (When the windshield is contaminated with foreign materials.)", "result");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Clean windshield.", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "NO", "result");
