si[i++] = gsitm("N5170203K0002K00ENG.html", "CHECK FRONT CAMERA UNIT INSTALLATION CONDITION", "title");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Check front camera unit installation condition (installation position, properly tightened, a bent bracket).", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Is it properly installed?", "question");
si[i++] = gsitm("N5170203K0002K00ENG.html", "YES", "result");
si[i++] = gsitm("N5170203K0002K00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Install front camera unit properly, and perform camera aiming.", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "CHECK VEHICLE HEIGHT", "title");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Check vehicle height. Refer to .", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Is vehicle height appropriate?", "question");
si[i++] = gsitm("N5170203K0002K00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N5170203K0002K00ENG.html", "Repair vehicle to appropriate height.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Always adjust the camera aiming after removing and installing or replacing the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Always adjust the camera aiming after removing and installing or replacing the windshield glass.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Place the vehicle on level ground when the camera aiming adjustment is operated.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Be sure to place the target correctly according to work procedures because the system may not operate normally.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Follow the M.U.T.-III SE when performing the camera aiming. (Camera aiming adjustment cannot be operated without M.U.T.-III SE.)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Preparation", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform self-diagnosis of front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N51702032000DT00ENG.html", "YES", "result");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform diagnosis on the detected DTC and repair or replace the applicable item. Refer to DTC Index .", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "NO", "result");
si[i++] = gsitm("N51702032000DT00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "PREPARATION BEFORE CAMERA AIMING ADJUSTMENT", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform pre-inspection for diagnosis.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Adjust the tire pressure to the specified pressure value.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Maintain no-load in vehicle.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Check if coolant and engine oil are filled up to correct level and fuel tank is full.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Shift the selector lever to \"P\" position and release the parking brake.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Clean the windshield.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Completely clear off the instrument panel.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "If any fixed object is put on instrument panel, cover the upper of the instrument panel with black cloth to prevent an object from reflecting in the windshield.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "PREPARATION OF J-52266-2 ALIGNMENT TARGET", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Prepare the alignment target according to the following procedure and the figure.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Attach the J-52266-2 alignment target to a movable board.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Use the board that peripheral area of the target is monochrome such as a whiteboard.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Notice that the cross of the target is horizontal and vertical.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "White wall", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "String", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Cone", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Center between two targets", "ptxt");
