si[i++] = gsitm("N51702032000DT00ENG.html", ": 120 mm (4.72 in)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Height of a target lower end (Htl)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 1,180 mm (46.46 in)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Height of a target center (Ht)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 1,300 mm (51.18 in)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Height of a target upper end (Htu)", "ptxt");
