si[i++] = gsitm("N51702032000DT00ENG.html", ": 180 mm (7.09 in)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "W2", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Proceed to Target Setting.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Target Setting", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform this operation in a horizontal position where there is a clear view for 5 m (16.4 ft) forward and 3 m (9.84 ft) wide.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Place the target in a well-lighted location. (Poor lighting may make it hard to adjust.)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The target may not be detected when there is a light source within 1.5 m (4.92 ft) from either side and within 1 m (3.28 ft) upward/downward from the target.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Check the location of the sun. (Sunlight should not shine directly on the front of the vehicle.)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The target may not be detected when there is the same pattern of black and white as the target when the pattern is within 1 m (3.28 ft) from either side and upward/downward position from the target. (It is desirable that the vehicle is positioned on the opposite side of a single-color wall.)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "TARGET SETTING", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "A – E (C – F)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 3,000 mm (118.11 in)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Mark points \"A\", \"B\", \"C\" and \"D\" at the center of the lateral surface of each wheels.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Hang a string with a cone from the fender so as to pass through the center of wheel, and then mark a point at the center of the lateral surface of the wheel.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Draw line \"LH\" passing through points \"A\" and \"B\" on the left side of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Approximately 4 m (13.12 ft) or more from the front end of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Mark point \"E\" on the line \"LH\" at the positions 3,000 mm (118.11 in) from point \"A\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Draw line \"RH\" passing through points \"C\" and \"D\" on the right side of vehicle in the same way as step 2.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Mark point \"F\" on the line \"RH\" at the positions 3,000 mm (118.11 in) from point \"C\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Draw line \"FW\" passing through the points \"E\" and \"F\" on the front side of vehicle.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Mark point \"X\" at the center of point \"E\" and \"F\" on the line \"FW\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Make sure that \"E\" to \"X\" is equal to \"F\" to \"X\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Center the J-52266-2 alignment target at point \"X\" facing the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Dt", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Proceed to Camera Aiming Adjustment.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Camera Aiming Adjustment", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform the adjustment under unloaded vehicle condition.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "CHECK VEHICLE HEIGHT", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Measure the wheel arch height.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Hfl: Front left wheel arch height [mm]", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Hfr: Front right wheel arch height [mm]", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Dh(mm) = (Hfl+Hfr) ÷ 2 – 805 &lt;Vehicles with 18 inch tire>", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Dh(mm) = (Hfl+Hfr) ÷ 2 – 809 &lt;Vehicles with 20 inch tire>", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Be sure to measure wheel arch height correctly.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The value of Dh may become negative.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "CAMERA AIMING ADJUSTMENT", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Operate M.U.T.-III SE outside the vehicle, and close all the doors. (To retain vehicle attitude appropriately)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Select \"Special Function\" on \"LANE CAMERA\" with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Select \"AUTO AIM\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Confirm the following items;", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The target should be accurately placed.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The vehicle should be stopped.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Select \"OK\" to perform camera aiming.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Never select \"OK\" when the J-52266-2 alignment target is not accurately placed.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Wait 5 seconds or more after selecting \"OK\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Input the following parameters, and then select \"OK\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Dh", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": Calculated value in 1. CHECK VEHICLE HEIGHT", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "VP", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 0", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 3,000 mm", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Dbt", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 720 mm", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Htu", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 1,420 mm", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Htl", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 1,180 mm", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ts", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", ": 120 mm", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The M.U.T.-III SE only accepts the value which is input in 2 mm increments.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "When the value of Dh is an odd number, add or subtract 1 to make it even and input the value.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Example: When the value is -21 mm, input -20 mm or -22 mm (Whichever is input, it does not affect the aiming).", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Confirm the displayed item.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "\"Normally Completed\": Select \"OK\".", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "\"SUSPENSION\", \"Abnormally completed\": Perform the following services.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Displayed item", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Possible cause", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Service procedure", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "SUSPENSION", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Temporary malfunction in internal processing of the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Front camera unit malfunction.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Position the target appropriately again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Then perform the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Abnormally completed", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "0", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming completed (no error)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "–", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "1", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming status determination (SPI) protocol version mismatch", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Turn the ignition switch to the ON from OFF. Accurately set target and perform camera aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "If abnormally completed again after aiming, replace front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "2", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Header CRC abnormality in SPI message", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "3", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Object CRC abnormality in SPI message", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "4", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Abnormality in \"CLB Stat Run Mode\" due to \"Calibration static\"", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "5", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming not completed within 5 seconds", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "6", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Failure to activate aiming mode", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "7", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Internal error during aiming", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "8", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Bottom value threshold exceeded", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Correct the input values of the parameters and carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "9", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming completion value is outside a certain range.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Correct the input parameters and carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ensure that the target is correctly placed and the front camera unit is correctly installed, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "18", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Target not detected", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "The distance between the target and the camera input during the aiming differs more than 50 % of the actual distance.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ensure that the front camera unit is correctly installed, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ensure that the hood is not open, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ensure that there is no obstruction on the windshield in front of the front camera unit, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Brightly illuminate the targets, check that the targets are within the range of the front camera unit and that all targets are clearly visible, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Ensure that the distance from the vehicle to the target is correct, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "19", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming result exceeds tolerances in the roll direction.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Check that the input parameters are correct, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Check that there is no reflection of strong light on the target and that there is no object around the target that could be mistaken for the target, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "20", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming result exceeds the tolerances in the yaw/pitch direction.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "21", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Input parameters were not read correctly.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Correct the input parameters, then carry out the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "22", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "23", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Target size is outside the recognizable range. (Target size is too small compared to the recognizable size.)", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Position the target appropriately again. Then perform the aiming again.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "24", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming result exceeds the tolerances in the yaw direction.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "25", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Aiming result exceeds the tolerances in the pitch direction.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "26", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Too many targets", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "27", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Malfunction of internal processes", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Replace front camera unit if \"SUSPENSION\" are repeatedly indicated.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Confirm that \"Normally completed\" is displayed and then select \"Home\"/\"Return one level\" to close the adjustment procedure.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform self-diagnosis of \"LANE CAMERA\" with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "ACTION TEST", "title");
si[i++] = gsitm("N51702032000DT00ENG.html", "Perform the following system operation by action test.", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "LDW: Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "LDP: Refer to Work Procedure .", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "Active Blind Spot Assist [ABSA]: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "TSR: Refer to .", "ptxt");
si[i++] = gsitm("N51702032000DT00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000FA00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the front camera unit.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "The configuration no need to “save” configuration data from the front camera unit. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N51702032000FA00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "Perform writing vehicle specification to front camera unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N51702032000FA00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000EV00ENG.html", "Always perform the side radar configuration after replacing the side radar.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "SIDE RADAR CONFIGURATION", "title");
si[i++] = gsitm("N51702032000EV00ENG.html", "Perform the side radar configuration with M.U.T.-III SE. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "SIDE RADAR ALIGNMENT", "title");
si[i++] = gsitm("N51702032000EV00ENG.html", "Perform the side radar alignment with M.U.T.-III SE. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N51702032000EV00ENG.html", "Perform the self-diagnosis of side radar with M.U.T.-III SE. Check if any DTC is detected.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N51702032000EV00ENG.html", "YES", "result");
si[i++] = gsitm("N51702032000EV00ENG.html", "Perform the trouble diagnosis for the detected DTC.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Side radar LH: Refer to DTC Index", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Side radar RH: Refer to DTC Index", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "NO", "result");
si[i++] = gsitm("N51702032000EV00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N51702032000EV00ENG.html", "Change the ignition switch to ON.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of  “Side radar (Rear left)”/  “Side radar (Rear right)”.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N51702032000EV00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Always perform the driver monitor control unit configuration after replacing the driver monitor control unit.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "After the driver monitor control unit configuration is performed, it is necessary to perform \"Factory Mode OFF\" and \"Get ECU Information & Send it to MMC Server\".", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "DRIVER MONITOR CONTROL UNIT CONFIGURATION", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Perform the driver monitor control unit configuration with M.U.T.-III SE. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "M.U.T.-III SE SYSTEM DATA LIST", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Check the following DMC data list.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Item No. 1: Face recognition", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "OK: \"Detected (w/o normal area)\"", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Is the check result normal?", "question");
si[i++] = gsitm("N51702032000E300ENG.html", "YES", "result");
si[i++] = gsitm("N51702032000E300ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "NO", "result");
si[i++] = gsitm("N51702032000E300ENG.html", "Check the mounting condition of the driver monitor control unit (e.g. mounting position, specified torque, bracket bends, etc.).", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Perform the self-diagnosis of driver monitor control unit with M.U.T.-III SE. Check if any DTC is detected.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Is any DTC detected?", "question");
si[i++] = gsitm("N51702032000E300ENG.html", "Perform the trouble diagnosis for the detected DTC. Refer to .", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "PERFORM SELF-DIAGNOSIS OF DRIVING SUPPORT CONTROL UNIT", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Perform the self-diagnosis of driving support control unit with M.U.T.-III SE. Check if any DTC is detected.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "GET ECU INFORMATION & SEND IT TO MMC SERVER", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Be sure to complete the procedures above before performing \"Get ECU Information & Send it to MMC Server\".", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "If the transfer of ECU information fails, sure to perform \"Data Upload\"", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Select \"DMC\" from system select menu.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Enter \"Special function\" and select \"ECU information\".", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Press \"Get ECU Information & Send it to MMC Server\" at the bottom of M.U.T.-III SE display.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "GO TO 6.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N51702032000E300ENG.html", "Change the power supply mode of the electric motor switch to ON.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"DMC\".", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "Check the item No.1: Factory Mode and perform the follwing procedures by the set value.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N51702032000E300ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000E600ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the driver monitor control unit.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the driver monitor control unit.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE User\'s Manual”.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "The configuration no need to save configuration data from the driving support camera. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N51702032000E600ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "Perform writing vehicle specification to driver monitor control unit following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE User\'s Manual.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N51702032000E600ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000F300ENG.html", "Face recognition check shall be performed if the system detects that the driver is not looking forward, even though the driver is looking forward.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Preparation before carrying out face recognition check.", "title");
si[i++] = gsitm("N51702032000F300ENG.html", "Satisfy all the following conditions.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Set the vehicle speed to 0 km/h (in stop condition).", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Set the shift position to \"P\".", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Place your head on the headrest.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Adjust the seat so that the eyes are positioned at the centre of the assist grip.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Adjust the position so that the camera shows the entire face and the chin is not hidden by the steering pad.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Always have another person check the position of the eyes and chin from the passenger side.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "If the eye position differs from the designated position, it will not be recognised correctly.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "PERFORM FACE RECOGNITION CHECK", "title");
si[i++] = gsitm("N51702032000F300ENG.html", "Check the following driver monitor control unit data list item item", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Item No. 1: Face recognition", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Item No. 2: Right Eye recognition", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Item No. 3: Left Eye recognition", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not change the direction of the face for approximately 10 to 15 seconds until the result is displayed.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "The following precautions should be observed during the work.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not move the seat position and place the head on the headrest.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not wear sunglasses and masks.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not wear hats or scarves that cover the face.", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not scratch your face (do not cover your eyes, nose or mouth).", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not deliberately change facial expressions (e.g. squinting, smiling).", "ptxt");
si[i++] = gsitm("N51702032000F300ENG.html", "Do not turn your face to a direction you have not been instructed.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Always perform the side radar alignment after performing the following work.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "After removing and installing or replacing the side radar.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "After removing and installing, replacing or repainting the rear bumper.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Side radar alignment conditions are following;", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The vehicle speed is 50 km/h (31 MPH) or higher.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The objects which reflect the wave of radar is located 8 m or more away from the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The steering wheel is straight.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The side radar alignment process is reset (back to 0%) when key switch is OFF before completing.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The side radar alignment process stops when the vehicle speed is 0 km/h (vehicle parked) and restarts when the alignment conditions are satisfied.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Timeout occurs, if the side radar alignment conditions are not satisfied for 15 minutes after the side radar alignment is started.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The side radar irradiates radar and performs the alignment by receiving its reflected wave for certain fixed time.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Because of not receiving the reflected wave, the side radar alignment may stop making progress under the following environment.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When driving on a road with high snow banks on both sides.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When driving on a road that has no objects to reflect the radar waves, such as a coastline road.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When driving on the road that sits above the surrounding level surface, such as a road on top of a levee or on top of an earthen dam.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "SELECT WORK SUPPORT ITEM", "title");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Stop the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Select “Work support” of “Side radar (Rear left)” or  “Side radar (Rear right)”.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Whichever “Side radar (Rear left)” or  “Side radar (Rear right)” is selected, the installation information can be written to both side radar LH/RH.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Select “Side radar alignment”.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Is the screen to select the target side radar displayed?", "question");
si[i++] = gsitm("N51702032000CJ00ENG.html", "YES", "result");
si[i++] = gsitm("N51702032000CJ00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "NO", "result");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When error message is displayed: GO TO 4.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "START SIDE RADAR ALIGNMENT", "title");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Select “Start”.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Is “Ready to start the side radar alignment.” displayed?", "question");
si[i++] = gsitm("N51702032000CJ00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "NO-1", "result");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When “Abnormal side radar installation.” is displayed: GO TO 5.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "NO-2", "result");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When “Detecting DTC.” is displayed: GO TO 6.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "NO-3", "result");
si[i++] = gsitm("N51702032000CJ00ENG.html", "When “Stopped” is displayed: Perform side radar alignment again.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "PERFORM SIDE RADAR ALIGNMENT", "PERFORMSIDERADARINSTALLATIONLOCATIO-03E0975C");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Drive the vehicle.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Always drive safely.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Side radar alignment cannot be performed under the following conditions;", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Heavy rain or snow", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "The bumper around the radar is contaminated.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Confirm that “Side radars alignment are completed.” is displayed and select \"End\".", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "WORK END.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "CONFIRMATION OF UNDETECTED RADAR", "CHECKTHECONNECTORSOFSIDERADARLHRH-EECE7E8F");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Confirm undetected radar and repair the defective part.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Perform the side radar alignment again.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "CHECK THE CONNECTORS OF SIDE RADAR LH/RH", "043CEB56");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Confirm the description on M.U.T.-III SE, check the concerned radar installing condition (installed location, tightening torque, bend of bracket etc.) and repair the defective part.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "CHECK SELF-DIAGNOSIS RESULTS OF SIDE RADAR", "CHECKTHECONNECTOROFSIDERADARLH-EC07F11A");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Perform \"Read All DTCs\".", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Check if the DTC is detected on the self-diagnosis results of following.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "“Side radar (Rear left)”: Refer to DTC Index.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "“Side radar (Rear right)”: Refer to DTC Index.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Perform trouble diagnosis for the detected DTC, and repair or replace the identified malfunctioning parts.", "ptxt");
si[i++] = gsitm("N51702032000CJ00ENG.html", "Ignition switch OFF to ON, and perform the side radar alignment again.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000FB00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the side radar.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the side radar.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "The configuration no need to “save” configuration data from the side radar. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N51702032000FB00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "Perform writing vehicle specification to side radar following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N51702032000FB00ENG.html", "WORK END", "ptxt");
