si[i++] = gsitm("N51702017006W000ENG.html", "Diagnosis Procedure", "title");
si[i++] = gsitm("N51702017006W000ENG.html", "PERFORM ALL DTC READING", "title");
si[i++] = gsitm("N51702017006W000ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Turn the engine switch OFF, close the driver\'s door, and wait for 3 minutes or more.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Turn the engine switch ON.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Perform \"ALL DTC\" with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Check if any DTCs of ethernet (DTC \"U19B5-87\", \"U2752-87\" &lt;Up to 2025 model year> and/or \"U2752-88\") are detected in \"Self Diagnostic Result\" of \"ICC/ADAS 2\", and check if any DTCs of ethernet (DTC \"C2599-13\" and/or \"U275F-88\") are detected in \"Self Diagnostic Result\" of \"LASER/RADAR\".", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Are DTCs \"U19B5-87\", \"U2752-87\" &lt;Up to 2025 model year>, \"U2752-88\", \"C2599-13\" and/or \"U275F-88\" detected as the current malfunction?", "question");
si[i++] = gsitm("N51702017006W000ENG.html", "YES", "result");
si[i++] = gsitm("N51702017006W000ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "NO", "result");
si[i++] = gsitm("N51702017006W000ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "CHECK DISTANCE SENSOR CONNECTOR", "title");
si[i++] = gsitm("N51702017006W000ENG.html", "Disconnect the ethernet harness connector terminals of the distance sensor once, and check the terminals for damage or looseness. Then, reconnect the terminals.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Repair or replace the malfunction part, securely lock the harness connector, and GO TO 3.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "CHECK ADAS CONTROL UNIT 2 CONNECTOR", "title");
si[i++] = gsitm("N51702017006W000ENG.html", "Disconnect the ethernet harness connector terminals of ADAS control unit 2 once, and check the terminals for damage or looseness. Then, reconnect the terminals.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Repair or replace the malfunction part, securely lock the harness connector, and GO TO 4.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE-1", "title");
si[i++] = gsitm("N51702017006W000ENG.html", "Erase all self-diagnosis results with M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Perform DTC confirmation procedure again. Refer to DTC Description .", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "Are \"U2752-88\" and/or \"U275F-88\" detected as the current malfunction?", "question");
si[i++] = gsitm("N51702017006W000ENG.html", "Replace the distance sensor (Refer to ), and GO TO 5.", "ptxt");
si[i++] = gsitm("N51702017006W000ENG.html", "PERFORM DTC CONFIRMATION PROCEDURE-2", "title");
