si[i++] = gsitm("N5170201D007AU00ENG.html", "DTC “C1E91–97” may be detected under the following conditions except for possible cause. (Explain to the customer about the difference between the contamination detection function and the indication when the malfunction is detected and tell them “This is not malfunction”.)", "ptxt");
si[i++] = gsitm("N5170201D007AU00ENG.html", "The side radar may be blocked by temporary ambient conditions such as splashing water, mist or fog.", "ptxt");
si[i++] = gsitm("N5170201D007AU00ENG.html", "The blocked condition may also be caused by objects such as ice, frost or dirt obstructing the side radar.", "ptxt");
si[i++] = gsitm("N5170201D007AU00ENG.html", "Due to the nature of radar technology it is possible to get a blockage warning and not actually be blocked. This is rare and is known as a false blockage warning. A false blocked condition either self-clears or clears after an ignition cycle.", "ptxt");
si[i++] = gsitm("N5170201D007AU00ENG.html", "POSSIBLE CAUSE", "title");
