si[i++] = gsitm("N517020760005D00ENG.html", "To install the front camera unit, make sure the sealing foam on the front camera unit is not broken (not cracked and nicked). If yes, do not install the front camera unit.", "ptxt");
si[i++] = gsitm("N517020760005D00ENG.html", "Move in the arrow direction till the four front camera unit side hooks fixed part front camera unit bracket.", "ptxt");
si[i++] = gsitm("N517020760005D00ENG.html", "Move the front camera unit until it is held by the snaps of the front camera unit bracket and the front camera unit hooks comes in contact with the pinch shelf of the front camera unit bracket.", "ptxt");
si[i++] = gsitm("N517020760006A00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N517020760006A00ENG.html", "When the distance sensor is replaced, after turning the ignition switch ON or OFF, always carry out the calibration of radar at one time.", "ptxt");
si[i++] = gsitm("N517020760006A00ENG.html", "If distance sensor is being replaced or has been disconnected, perform \"ADDITIONAL SERVICE WHEN REPLACING DISTANCE SENSOR\". Refer to .", "par3");
si[i++] = gsitm("N517020760006A00ENG.html", "Do not touch distance sensor face.", "par4");
si[i++] = gsitm("N517020760006A00ENG.html", "Do not drop or shock distance sensor.", "par9");
si[i++] = gsitm("N517020760006A00ENG.html", "Make sure distance sensor harness is installed without any twists.", "par10");
