si[i++] = gsitm("N517020760005O00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N517020760005O00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N517020760005O00ENG.html", "Remove the glass mirror. Refer to .", "par1");
si[i++] = gsitm("N517020760005O00ENG.html", "Replace the glass mirror if you need to replace the BSW indicator.", "par2");
