si[i++] = gsitm("N5170202T0008H00ENG.html", "System Description", "title");
si[i++] = gsitm("N5170202T0008H00ENG.html", "This function senses driving based on the driver\'s steering and acceleration/braking patterns, and controls brake pressure at individual wheels to aid tracing at corners and help smooth vehicle response.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "Amount of brake control is changed based on drive mode selector switch.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "When the turn OFF the ASC function, AYC function is also turned OFF.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "When AYC function is not functioning properly, the master warning light illuminates, and Warning message will also appear on information display.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "Always drive carefully and attentively.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "AYC function is not always activated in any driving conditions.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "When the AYC function is activated, the driver may feel some vibration on the brake pedal, hear operating sound, or have feel of the deceleration. This is not a malfunction because it is caused by AYC function that is normally operated.", "ptxt");
si[i++] = gsitm("N5170202T0008H00ENG.html", "OPERATION CHARACTERISTICS", "title");
si[i++] = gsitm("N5170202T0008H00ENG.html", "This system enhances vehicle cornering performance and vehicle stability with management of vehicle turning power (yaw moment) by controlling the drive power difference of the left and right wheels and the braking force when the vehicle does not turn in response to steering input, such as when the steering wheel is turned quickly or when driving on slippery road.", "ptxt");
