si[i++] = gsitm("N5170202T0009300ENG.html", "System Description", "title");
si[i++] = gsitm("N5170202T0009300ENG.html", "Active ride control function senses upper body motion and controls four wheel brake pressure. This will enhance ride comfort in effort to restrain uncomfortable upper body movement when passing over undulated road surfaces.", "ptxt");
si[i++] = gsitm("N5170202T0009300ENG.html", "When the turn OFF the ASC function, active ride control function is also turned OFF.", "ptxt");
si[i++] = gsitm("N5170202T0009300ENG.html", "When active ride control function is not functioning properly, the master warning light illuminates, and Warning message will also appear on information display.", "ptxt");
si[i++] = gsitm("N5170202T0009300ENG.html", "Active ride control function is not always activated in any driving conditions.", "ptxt");
si[i++] = gsitm("N5170202T0009300ENG.html", "When the active ride control function is activated, the driver may feel some vibration on the brake pedal, hear operating sound, or have feel of the deceleration. This is not a malfunction because it is caused by active ride control function that is normally operated.", "ptxt");
si[i++] = gsitm("N5170202T0009300ENG.html", "BRAKING CONTROL", "title");
si[i++] = gsitm("N5170202T0009300ENG.html", "Brake control - Enhances ride comfort by restraining upper body movement with small amount of brake control when driving on bumpy roads.", "ptxt");
