si[i++] = gsitm("N517020DD0000L00ENG.html", "ACTIVE TEST", "title");
si[i++] = gsitm("N517020DD0000L00ENG.html", "The \"Actuator Test\" is used to determine and identify details of a malfunction, based on self-diagnosis test results and data obtained in the \"Data List\". In response to instructions from M.U.T.-III SE, instead of those from chassis control module on the vehicle, a drive signal is sent to the actuator to check its operation.", "ptxt");
si[i++] = gsitm("N517020DD0000L00ENG.html", "Never perform \"Actuator Test\" while driving the vehicle.", "ptxt");
si[i++] = gsitm("N517020DD0000L00ENG.html", "Always bleed air from brake system before \"Actuator Test\".", "ptxt");
si[i++] = gsitm("N517020DD0000L00ENG.html", "Never perform \"Actuator Test\" when system is malfunctioning.", "ptxt");
si[i++] = gsitm("N517020DD0000L00ENG.html", "During an \"Actuator Test\", sometimes a chassis control warning is displayed and the master warning light illuminates on the information display in the combination meter; however, this is not a malfunction.", "ptxt");
