si[i++] = gsitm("N517020300001E00ENG.html", "INTERVIEW FROM THE CUSTOMER", "title");
si[i++] = gsitm("N517020300001E00ENG.html", "Clarify customer complaints before inspection. First of all, perform an interview utilizing  and reproduce the symptom as well as fully understand it. Ask customer about his/her complaints carefully. Check symptoms by driving vehicle with customer, if necessary.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "Customers are not professional. Never guess easily like “maybe the customer means that...,” or “maybe the customer mentions this symptom”.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "CHECK SYMPTOM", "title");
si[i++] = gsitm("N517020300001E00ENG.html", "Reproduce the symptom that is indicated by the customer, based on the information from the customer obtained by the interview. Also check that the symptom is not caused by fail-safe mode. Refer to Fail-Safe.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "When the symptom is caused by normal operation, fully inspect each portion and obtain the understanding of customer that the symptom is not caused by a malfunction.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "PERFORM SELF-DIAGNOSIS", "title");
si[i++] = gsitm("N517020300001E00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "Perform self-diagnosis for “CHASSIS CONTROL”.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "Is DTC detected?", "question");
si[i++] = gsitm("N517020300001E00ENG.html", "YES", "result");
si[i++] = gsitm("N517020300001E00ENG.html", "Record or print self-diagnosis results and freeze frame data (FFD). GO TO 4.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "NO", "result");
si[i++] = gsitm("N517020300001E00ENG.html", "INSPECTION END", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "PERFORM DTC DIAGNOSIS PROCEDURE", "title");
si[i++] = gsitm("N517020300001E00ENG.html", "Perform DTC confirmation procedures for the error-detected system.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "If some DTCs are detected at the same time, determine the order for performing the diagnosis based on .", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "GO TO 5.", "ptxt");
si[i++] = gsitm("N517020300001E00ENG.html", "Check harness and connectors based on the information obtained by the interview.", "ptxt");
