si[i++] = gsitm("N517020190000P00ENG.html", "Diagnostic Work Sheet", "title");
si[i++] = gsitm("N517020190000P00ENG.html", "Description", "title");
si[i++] = gsitm("N517020190000P00ENG.html", "In general, customers have their own criteria for a symptom. Therefore, it is important to understand the symptom and status well enough by interviewing the customer about the symptom carefully. To systemize all the information for the diagnosis, prepare the interview sheet referring to the interview points.", "ptxt");
si[i++] = gsitm("N517020190000P00ENG.html", "In some cases, multiple conditions that appear simultaneously may cause a DTC to be detected.", "ptxt");
