si[i++] = gsitm("N517020110002S00ENG.html", "Description", "title");
si[i++] = gsitm("N517020110002S00ENG.html", "When replacing the chassis control module, the procedures of AFTER REPLACEMENT must be performed. For work procedure, refer to the following:", "ptxt");
si[i++] = gsitm("N517020110002S00ENG.html", "AFTER REPLACEMENT", "title");
si[i++] = gsitm("N517020110002S00ENG.html", "After replacing the chassis control module, the following items must be performed:", "ptxt");
si[i++] = gsitm("N517020110002S00ENG.html", "Chassis control module programming", "ptxt");
si[i++] = gsitm("N517020110002S00ENG.html", "Chassis control module configuration", "ptxt");
si[i++] = gsitm("N517020110002S00ENG.html", "Writing MAC key", "ptxt");
si[i++] = gsitm("N517020110002S00ENG.html", "Factory mode OFF", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Work Procedure [After Replacing Chassis Control Module]", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "WRITING MAC KEY", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Perform MAC key writing. Refer to .", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "PERFORM PROGRAMMING", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Perform chassis control module programming according to the procedure of “Programming” in M.U.T.-III SE Operation Manual. Refer to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "During programming, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Ignition switch: ON", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Electric load: OFF", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Brake pedal: Not depressed", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "12V battery voltage: 12 – 13.5 V (Check the value displayed on the M.U.T.-III SE screen.)", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "PERFORM CONFIGURATION", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Perform configuration. Refer to .", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "GO TO 4.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "PERFORM NECESSARY WORK", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Perform self-diagnosis for “CHASSIS CONTROL”.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Erase the memory of self-diagnosis results.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "GO TO 5.", "");
si[i++] = gsitm("N517020DH0000W00ENG.html", "PERFORM THE FACTORY MODE OFF", "title");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Select \"Factory Mode OFF\" in \"Special Function\" screen of \"CHASSIS CONTROL\".", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "Check the item No.1: Factory Mode and perform the following procedures by the set value.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "ON: Select \"OK\" and change the set value to \"OFF\".", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "OFF: No action required, work completed.", "ptxt");
si[i++] = gsitm("N517020DH0000W00ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "Description", "title");
si[i++] = gsitm("N517020110002U00ENG.html", "Vehicle specification needs to be written with M.U.T.-III SE because it is not written after replacing the chassis control module.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "The configuration requires network connection. M.U.T.-III SE connects to network and then it downloads the configuration data from the server. Then M.U.T.-III SE writes the vehicle specification to the chassis control module.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "Refer to .", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "The configuration no need to “save” configuration data from the chassis control module. The configuration data is always generated freshly at the server and then downloaded to the M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "Complete the procedure of “Configuration” in order.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "If incorrect “Configuration”, incidents might occur.", "ptxt");
si[i++] = gsitm("N517020110002U00ENG.html", "Never perform “Configuration” except for new chassis control module.", "ptxt");
si[i++] = gsitm("N51702032000F700ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000F700ENG.html", "WRITING VEHICLE SPECIFICATION", "title");
si[i++] = gsitm("N51702032000F700ENG.html", "With M.U.T.-III SE", "ptxt");
si[i++] = gsitm("N51702032000F700ENG.html", "Perform writing vehicle specification to chassis control module following \"Automatic Configuration\" procedure of \"Configuration\" according to M.U.T.-III SE Operation Manual.", "ptxt");
si[i++] = gsitm("N51702032000F700ENG.html", "Log in the network according to M.U.T.-III SE guidance.", "ptxt");
si[i++] = gsitm("N51702032000F700ENG.html", "For details the network connection and operation, refer to “M.U.T.-III SE Operation Manual”.", "ptxt");
si[i++] = gsitm("N51702032000F700ENG.html", "WORK END", "ptxt");
si[i++] = gsitm("N517020110002V00ENG.html", "Description", "title");
si[i++] = gsitm("N517020110002V00ENG.html", "When replacing chassis control module, it is necessary to write MAC key to chassis control module. Write MAC key to chassis control module according to \"MAC Key writing\" procedure of \"M.U.T.-III SE Operation Manual\". Refer to .", "ptxt");
si[i++] = gsitm("N517020110002V00ENG.html", "During MAC key writing, maintain the following conditions:", "ptxt");
si[i++] = gsitm("N517020110002V00ENG.html", "Ignition switch ON", "ptxt");
si[i++] = gsitm("N517020110002V00ENG.html", "M.U.T.-III SE is connected to internet", "ptxt");
si[i++] = gsitm("N51702032000F800ENG.html", "Work Procedure", "title");
si[i++] = gsitm("N51702032000F800ENG.html", "PERFORM MAC KEY WRITING", "title");
si[i++] = gsitm("N51702032000F800ENG.html", "Ignition switch ON.", "ptxt");
si[i++] = gsitm("N51702032000F800ENG.html", "Select \"MAC Key writing\" on \"Special Function\" of \"CHASSIS CONTROL\" using M.U.T.-III SE.", "ptxt");
si[i++] = gsitm("N51702032000F800ENG.html", "Touch \"OK\".", "ptxt");
si[i++] = gsitm("N51702032000F800ENG.html", "WORK END", "ptxt");
