si[i++] = gsitm("N517020760005M00ENG.html", "Removal and Installation", "title");
si[i++] = gsitm("N517020760005M00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N517020760005M00ENG.html", "When replacing chassis control module, configuration of chassis control module is required. Refer to .", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "Remove the glove box. Refer to  &lt;LHD> or  &lt;RHD>.", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "Remove the chassis control module harness connector  from chassis control module .", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "Remove the chassis control module  from bracket .", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "Never drop the chassis control module.", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N517020760005M00ENG.html", "Note the following, install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N517020760005M00ENG.html", "When replacing the chassis control module, be sure to perform the configuration of chassis control module. Refer to .", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Precautions for Removing Battery Terminal", "title");
si[i++] = gsitm("N517030350000E00ENG.html", "With the adoption of Auto ACC function, ACC power is automatically supplied by operating the Keyless operation key or remote keyless entry or by opening/closing the driver side door. In addition, ACC power is supplied even after the ignition switch is turned to the OFF position, i.e. ACC power is supplied for a certain fixed time.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "When disconnecting the 12V battery terminal, turn off the ACC power before disconnecting the 12V battery terminal, observing “How to disconnect 12V battery terminal” described below.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Some ECUs operate for a certain fixed time even after ignition switch is turned OFF and ignition power supply is stopped. If the battery terminal is disconnected before ECU stops, accidental DTC detection or ECU data damage may occur.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "For vehicles with the 2-batteries, be sure to connect the main battery and the sub battery before turning ON the ignition switch.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "If the ignition switch is turned ON with any one of the terminals of main battery and sub battery disconnected, then DTC may be detected.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "After installing the 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "The removal of 12V battery may cause a DTC detection error.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "HOW TO DISCONNECT 12V BATTERY TERMINAL", "title");
si[i++] = gsitm("N517030350000E00ENG.html", "Disconnect 12V battery terminal according to instruction described below.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Open the hood.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Turn ignition switch to the ON position.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Turn ignition switch to the OFF position with the driver side door opened.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Get out of the vehicle and close the driver side door.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Wait at least 3 minutes.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "While waiting, never operate the vehicle such as locking, opening, and closing doors. Violation of this caution results in the activation of ACC power supply according to the Auto ACC function.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "Remove 12V battery terminal.", "ptxt");
si[i++] = gsitm("N517030350000E00ENG.html", "After installing 12V battery, always check the DTC of all ECUs and erase DTC.", "ptxt");
si[i++] = gsitm("N517030360000C00ENG.html", "Precaution for Harness Repair", "title");
si[i++] = gsitm("N517030360000C00ENG.html", "Solder the repair part, and wrap it with tape. [Twisted wire fray must be 110 mm (4.33 in) or less.]", "ptxt");
si[i++] = gsitm("N517030360000C00ENG.html", "Never bypass the repair point with wire. (If it is bypassed, the turnout point cannot be separated and the twisted wire characteristics are lost.)", "ptxt");
