si[i++] = gsitm("N5170303B0000C00ENG.html", "The drive mode selector switches a vehicle mode with the flick of a switch (drive mode select switch) mounted on upper part of the center console and changes the control characteristics of the power train, combination meter, chassis function, driver assistant system, AWD function.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "When the ignition switch is ON from the OFF state, the drive mode select switch starts in NORMAL mode regardless of drive mode during ignition switch ON.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "The vehicle characteristics are controlled from the NORMAL mode to any mode listed below:", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "ECO", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "This mode supports ecological and economical driving by optimized power train characteristic.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "TARMAC", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "This mode offers the pleasure of driving with agile dynamics on dry paved road, such as responsive and powerful acceleration, responsive and linear steering feel, stability and traceability on cornering.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "GRAVEL", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "This mode is for driving on rough road surfaces such as flat unpaved roads or wet paved roads and improves straightablity on rough road and powerful launching acceleration. A part of ADAS function is limited.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "SNOW", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "This mode is for driving on slippery road surfaces, such as snow-covered roads and offers good initial steering response and high cornering stability on a slippery road. A part of ADAS function is limited.", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "MUD", "ptxt");
si[i++] = gsitm("N5170303B0000C00ENG.html", "This mode is for driving on slippery road where maximum traction is required, such as muddy roads and deep snow roads and improves traction performance. A part of ADAS function is limited.", "ptxt");
